// 题库关键点链：每道题解完必须作出的关键判断，据官方解析编译。
// 由 scripts/build-qbank-keysteps.mjs 生成，勿手改（改了下次重跑就没了）。
// 字段：title 这道坎叫什么 / judge 要作出什么判断 / why 依据 / do 动作 / expr 关系式 /
//       cues 学生口语说法（关键词定位通道的输入）/ concepts 物理概念名词。
export const QBANK_KEYSTEPS = {"1":[{"title":"判断能否发生光电效应","type":"前提判断","judge":"入射光子能量与金属逸出功的大小关系是否满足光电效应发生的条件","why":"光电效应的发生条件是入射光子能量不小于金属的逸出功，只有满足这一条件才有光电子逸出，不满足则无论光强多大都不发生","do":"把紫外线的光子能量分别与锡、铟的逸出功比较大小","expr":"h\\nu \\ge W_0","cues":["比逸出功大小","能量够不够","看能不能打出电子"],"concepts":["光电效应","逸出功","光子能量"]},{"title":"确定哪种金属能发生","type":"结论整理","judge":"比较结果中哪种金属的逸出功小于等于光子能量，从而只有它能发生光电效应","why":"两种金属逸出功不同，同一束紫外线的光子能量对一种金属够、对另一种不够，因此只有满足条件的那种金属有光电子逸出","do":"由两个比较结果得出只有铟满足条件、锡不满足，据此排除说两种都能或都不能的选项","expr":"","cues":["只有铟能","锡不行","一个能一个不能"],"concepts":["光电效应条件","逸出功"]}],"2":[{"title":"平行砖出射光平行","type":"前提判断","judge":"光穿过两面平行的树脂砖后，出射光线与入射光线是否平行","why":"两面平行的介质砖中，两个界面的折射互相抵消，出射光线方向与入射光线方向相同，只是发生侧移；不先确定这一点，就无法在四条线中筛出与入射光平行的候选","do":"找出与入射光线方向平行的出射光线，排除方向偏转的选项","expr":"","cues":["两面平行","出射光跟入射光平行","只侧移不偏转"],"concepts":["平行介质砖","折射定律"]},{"title":"判断侧移方向","type":"关系建立","judge":"出射光线相对入射光线延长线偏向哪一侧","why":"光从空气进入光密介质时折射角小于入射角，光线向法线偏折，在第二个界面又向远离法线方向偏折，最终出射光相对原方向发生侧移，侧移方向由两次偏折的几何关系决定","do":"画出P点法线，比较入射角与折射角大小，确定光在砖内的偏折方向，再推出出射光相对入射光延长线的位置","expr":"","cues":["向法线偏","折射角小于入射角","往哪边侧移"],"concepts":["光疏介质","光密介质","折射角"]},{"title":"按侧移方向定光线","type":"结论整理","judge":"四条出射光线中哪一条既与入射光平行又位于正确侧移一侧","why":"只有同时满足平行和侧移方向两个条件的光线才符合实际光路，只满足其中一个条件的光线是干扰项","do":"在平行于入射光的光线中，选出位于入射光延长线正确一侧的那一条","expr":"","cues":["先看平行","再看侧移","两条都满足"],"concepts":["光路作图","侧移"]}],"3":[{"title":"由波峰圆定波长","type":"图像读取","judge":"相邻两个实线圆（波峰）的间距对应一个波长还是半个波长","why":"相邻同相面（波峰到波峰）间距恰为一个波长，这是由波的空间周期性决定的","do":"在图上量出两实线圆的半径差，读出波长","expr":"\\lambda = r_2 - r_1","cues":["两圆间距就是波长","相邻波峰差一个波长"],"concepts":["波长","波峰","波的周期性"]},{"title":"波速由频率波长定","type":"关系建立","judge":"用 v=λf 还是用 v=λ/T 求波速，以及频率是否直接可用","why":"波速由介质决定，但可由 λ 与 f 的乘积求出，题给 f=2Hz 与图上 λ 即可定 v","do":"将读出的波长与 2Hz 相乘得波速","expr":"v=\\lambda f","cues":["先求波速","波长乘频率"],"concepts":["波速","频率","波长"]},{"title":"波源起振方向定初相","type":"前提判断","judge":"S 从平衡位置向上起振，决定各质点开始振动时的方向及波源振动方程","why":"介质中每个质点起振方向都与波源起振方向相同，这是波传播的因果性","do":"确定波传到某点时该点由平衡位置向上起振，据此写质点振动随时间的变化","expr":"y=A\\sin\\!\\left(2\\pi f t\\right)","cues":["起振方向都向上","从平衡位置向上"],"concepts":["起振方向","简谐振动","波的传播"]},{"title":"传播时间与相位对应","type":"关系建立","judge":"波传到某点所需时间与此时该点所处振动状态（平衡位置/波峰）的对应","why":"波传到该点的时刻即该点开始振动时刻，之后按 T 周期振动，相位由 Δt/T 决定","do":"用距离除以波速得传播时间，再与周期比较判断该时刻质点位置","expr":"t=\\frac{r}{v},\\quad T=\\frac{1}{f}","cues":["先算传到的时间","再看过了几个周期"],"concepts":["波的传播时间","周期","相位"]},{"title":"空间距离差转相位差","type":"几何关系","judge":"P、Q 到波源的距离差对应多少个波长，从而决定两点振动相位关系","why":"同波源发出的波，相位差由波程差与波长之比决定，Δr=nλ 同相、半波长奇数倍反相","do":"用坐标算 SP、SQ 长度，求波程差并与 λ 比较","expr":"\\Delta r=\\sqrt{4^2+3^2}-2=3\\ \\text{m},\\quad \\frac{\\Delta r}{\\lambda}","cues":["算两点到波源的距离","距离差除以波长"],"concepts":["波程差","相位差","干涉"]}],"4":[{"title":"分解两段运动","type":"模型选择","judge":"把小球从O到M、M到N的运动按水平与竖直两个方向独立分解，判断每段位移各是多少","why":"匀强电场力与重力都是恒力，合力恒定，故两个方向都是匀变速直线运动，可分别列位移方程","do":"以O为原点、水平向右为x、竖直向上为y，写出0~1s水平位移0、竖直位移3m，0~2s水平位移3m、竖直位移0","expr":"x_1=0,\\ y_1=3\\ \\text{m};\\ x_2=3\\ \\text{m},\\ y_2=0","cues":["分方向看","水平竖直分开","两段各一秒"],"concepts":["运动的分解","匀变速直线运动"]},{"title":"用位移定加速度","type":"关系建立","judge":"由两段位移数据反解出水平、竖直方向的加速度分量，而不是先求电场力","why":"位移只由初速度和加速度决定，两段位移给出四个方程，恰好解出两个方向的初速度和加速度","do":"对水平、竖直分别列0~1s和0~2s的位移公式，联立解出a_x、a_y","expr":"v_{0x}+\\tfrac12 a_x=0,\\ 2v_{0x}+2a_x=3;\\ v_{0y}+\\tfrac12 a_y=3,\\ 2v_{0y}+2a_y=0","cues":["先求加速度","位移反推","两段联立"],"concepts":["位移公式","加速度分解"]},{"title":"合力分解求场强","type":"关系建立","judge":"把合力分解为重力与电场力两部分，由ma_x、ma_y分别确定电场力的两个分量","why":"合力等于重力与电场力的矢量和，加速度分量对应合力分量，从而电场力分量可求","do":"写水平方向qE_x=ma_x，竖直方向qE_y-mg=ma_y，代入m、q、g解出E_x、E_y","expr":"qE_x=ma_x,\\ qE_y-mg=ma_y","cues":["合力等于重力加电场力","先求电场力分量","再除以电荷量"],"concepts":["牛顿第二定律","电场力","矢量分解"]},{"title":"合成场强大小","type":"数学处理","judge":"由两个正交分量合成总场强大小，判断是否需要保留方向信息","why":"电场强度是矢量，题目问大小需用勾股合成，方向由分量符号确定","do":"计算E=√(E_x²+E_y²)","expr":"E=\\sqrt{E_x^2+E_y^2}","cues":["勾股合成","分量平方和","矢量大小"],"concepts":["矢量合成","电场强度"]},{"title":"由场强方向判电势","type":"结论整理","judge":"由水平分量E_x的方向判断O、N两点电势高低，而不是凭竖直分量判断","why":"沿电场线方向电势降低，O、N在同一水平线上，电势差只由水平分量决定","do":"看E_x的正负确定水平方向电势升降，比较φ_O与φ_N","expr":"\\varphi_O-\\varphi_N=E_x\\cdot d_{ON}","cues":["看水平分量","沿场线电势降低","同一高度只看水平"],"concepts":["电势差","电场线方向"]}],"5":[{"title":"感应电流方向判定","type":"前提判断","judge":"线框进入磁场时，穿过回路的磁通量如何变化，感应电流沿哪个方向","why":"磁场垂直斜面向下，线框进入时回路面积增大、磁通量增大，由楞次定律（或右手定则）可定电流方向；方向判错则后续安培力方向、外力方向全反","do":"取线框进入磁场的阶段，判断磁通量增减，用楞次定律定感应电流绕行方向","expr":"","cues":["磁通量增大","用右手定则","看面积变化"],"concepts":["楞次定律","右手定则","磁通量"]},{"title":"安培力随有效长度变化","type":"关系建立","judge":"线框进入过程中切割磁感线的有效长度如何随位移变化，安培力大小和方向如何变","why":"梯形线框下底与上底不等，进入过程中处在磁场中的切割边长度由下底逐渐变为上底，安培力 F=BIL=B²L²v/R 随有效长度平方变化，这是判断外力方向变化的关键","do":"分别写出下底边刚进入和上底边即将进入两个时刻的有效切割长度，比较两时刻安培力大小","expr":"F_A=\\frac{B^2L^2v}{R}","cues":["有效长度在变","下底比上底长","安培力先大后小"],"concepts":["安培力","有效切割长度","法拉第电磁感应定律"]},{"title":"外力方向的分段判断","type":"临界条件","judge":"在进入过程的前段和后段，为维持给定运动，外力应沿斜面向上还是向下","why":"安培力沿斜面向上，其大小随有效长度变化；若安培力先大于重力沿斜面分量、后小于它，则外力需先向下后向上，做功正负随之改变","do":"对前后两段分别比较安培力与重力沿斜面分力的大小，定出外力方向","expr":"F_A \\gtrless mg\\sin\\theta","cues":["先看安培力多大","和重力分量比","方向会翻转"],"concepts":["受力平衡","安培力","重力分量"]},{"title":"梯形几何求高与位移","type":"几何关系","judge":"由下底、上底和腰长求出梯形的高，并确定线框沿斜面进入磁场的位移","why":"重力做功和安培力做功都要用到沿斜面方向的位移，位移由梯形几何尺寸决定，几何关系错则功和能量方程全错","do":"作梯形的高，用勾股关系由底边差和腰长求高，再取进入过程沿斜面的位移","expr":"h=\\sqrt{l^2-\\left(\\frac{a-b}{2}\\right)^2}","cues":["作高用勾股","底边差一半","位移沿斜面"],"concepts":["几何关系","位移","勾股定理"]},{"title":"恒定电流条件的运动学约束","type":"模型选择","judge":"若感应电流恒定，则速度与有效切割长度成什么关系，由此确定速度如何随位移变化","why":"I=BLv/R 恒定要求 Lv 为定值，而 L 随进入过程线性变化，故 v 必须随位移相应变化，这是把电流恒定转化为速度规律、进而求功的桥梁","do":"写出 Lv=常量的关系，结合 L 随位移的变化表示 v，再对全过程用动能定理","expr":"BLv=\\text{常量}\\Rightarrow v\\propto\\frac{1}{L}","cues":["电流恒定则电动势恒定","速度要配合长度变","用动能定理串起来"],"concepts":["电磁感应定律","恒定电流","动能定理"]}],"6":[{"title":"气泡偏向判断高低","type":"前提判断","judge":"气泡停在水平仪中心偏哪一侧，说明该侧台面偏高还是偏低","why":"水平仪内气泡受浮力作用会向液面较高的一端移动，即气泡偏向的一侧台面较高","do":"对照图丙中气泡偏离中心的方向，确定是M、N端偏高还是L端偏高","expr":"","cues":["气泡往高处跑","看气泡偏哪边","偏的一侧高"],"concepts":["水平仪","气泡浮力","连通液面"]},{"title":"三脚架调平的等效操作","type":"关系建立","judge":"在保持某一脚不动的前提下，应升高还是降低其余脚，才能让台面回到水平","why":"三点支撑的台面倾角由三脚高度差决定，只调一脚或同时调另外两脚都能消除同一高度差","do":"把气泡偏向判出的偏高侧与偏低侧，对应到L、M、N三脚，逐一检验各选项是否只改变高度差而不引入新倾斜","expr":"","cues":["保持一脚不动","调另外两脚","只动一个脚"],"concepts":["三点支撑","高度差","等效调节"]},{"title":"弹簧测力计读数规则","type":"实验操作","judge":"读数时取哪一条刻度线、估读到哪一位","why":"弹簧测力计需按最小分度值估读一位，视线要与指针正对","do":"确认所选量程的最小分度，读出指针所指刻度并保留到分度值的下一位","expr":"","cues":["看最小分度","估读一位","视线正对指针"],"concepts":["弹簧测力计","分度值","估读"]},{"title":"平行四边形作图求合力","type":"模型选择","judge":"用F1、F2为邻边作平行四边形，合力取哪条对角线","why":"力是矢量，共点两力的合成遵循平行四边形定则，合力为两分力所夹的对角线","do":"按同一标度作出F1、F2的图示，补全平行四边形，量出从共同作用点出发的对角线长度","expr":"","cues":["作平行四边形","取对角线","按标度画"],"concepts":["平行四边形定则","矢量合成","力的图示"]},{"title":"标度换算格数得合力","type":"数据处理","judge":"对角线占多少小格，每小格代表多少牛顿","why":"作图法求合力必须用统一标度把图上长度换算成力的大小，否则数值无意义","do":"数出对角线所跨小格数，乘以每格代表的力值，得到合力大小","expr":"F=n\\times 0.5\\,\\mathrm{N}","cues":["数格子","每格半牛","乘标度"],"concepts":["标度","作图法","合力大小"]}],"7":[{"title":"确定圆周轨迹的圆心","type":"几何关系","judge":"已知入射点S、出射点P和S点的速度方向，能否唯一确定电子做圆周运动的圆心位置","why":"电子只受洛伦兹力，做匀速圆周运动，圆心必在过S点且垂直于速度方向的直线上，同时到S、P两点距离相等","do":"过S作速度的垂线（竖直方向），再作SP的中垂线，两线交点即为轨迹圆心","expr":"","cues":["圆心在速度垂线上","找中垂线交点","先定圆心再算半径"],"concepts":["匀速圆周运动","圆心确定","几何作图"]},{"title":"由几何关系求轨迹半径","type":"几何关系","judge":"如何用已知的R和S点位置（距O点0.8R）表示出轨迹半径r","why":"磁场大小由半径决定，而半径只能通过圆面几何约束（S、P都在圆面上）求出","do":"在直角三角形中，用圆心到O的距离、OP=R、SO=0.8R等长度关系列勾股或相似关系解出r","expr":"","cues":["用勾股定理","半径和R的关系","画三角形找边"],"concepts":["几何关系","勾股定理","轨迹半径"]},{"title":"洛伦兹力提供向心力","type":"关系建立","judge":"选用哪个规律把半径r与磁感应强度B、速度v联系起来","why":"电子在匀强磁场中做匀速圆周运动，向心力完全由洛伦兹力提供（不计重力）","do":"列洛伦兹力等于向心力的方程，解出B","expr":"evB=\\frac{mv^2}{r}","cues":["洛伦兹力当向心力","用向心力公式","只有磁场力"],"concepts":["洛伦兹力","向心力","牛顿第二定律"]},{"title":"左手定则判磁场方向","type":"前提判断","judge":"电子带负电，由偏转方向反推磁场方向时，四指指向与电子运动方向的关系如何取","why":"左手定则中四指指向正电荷运动方向（或负电荷运动的反方向），电子带负电，方向判断易反","do":"由S到P的偏转方向确定洛伦兹力方向，再用左手定则（四指指电子运动反方向）推出磁场垂直纸面向里","expr":"","cues":["电子带负电要反着指","四指指速度反方向","先定受力方向"],"concepts":["左手定则","负电荷","洛伦兹力方向"]},{"title":"求轨迹圆心角","type":"几何关系","judge":"电子从S第一次到P转过的圆心角是多少，能否由圆心三角形直接读出","why":"时间由t=(θ/2π)T决定，θ必须由几何关系确定，不能想当然取半圆或整圆","do":"连接圆心与S、P，在等腰三角形中用已知边长求顶角θ","expr":"t=\\frac{\\theta}{2\\pi}T,\\quad T=\\frac{2\\pi m}{eB}","cues":["先求圆心角","用周期算时间","角度从三角形里找"],"concepts":["圆心角","周期","运动时间"]}],"8":[{"title":"碰撞对象与规律选择","type":"模型选择","judge":"P 与静止小球碰撞时，该用动量守恒加机械能守恒（弹性碰撞）联立，还是只用动量守恒","why":"题设明确所有碰撞为对心弹性碰撞，管道光滑无能量损失，故碰撞过程动量与动能同时守恒","do":"对 P 与 1 号球列动量守恒式和动能守恒式，联立解出两球碰后速度","expr":"m_P v_0 = m_P v_P + m v_1,\\ \\frac12 m_P v_0^2=\\frac12 m_P v_P^2+\\frac12 m v_1^2","cues":["弹性碰撞","动量加动能","两式联立"],"concepts":["弹性碰撞","动量守恒","机械能守恒"]},{"title":"碰后到下一平台用动能定理","type":"关系建立","judge":"球在两平台之间运动时，用什么规律把上一平台碰后速度与下一平台碰前速度联系起来","why":"管道光滑，只有重力做功，且两平台间有确定高度差，用动能定理（或机械能守恒）最直接","do":"对 1 号球从第 1 平台到第 2 平台列动能定理，求出它碰 2 号球前的速度","expr":"\\frac12 m v^2-\\frac12 m v_1^2 = mg\\,\\Delta h","cues":["重力做功","高度差","动能定理"],"concepts":["动能定理","重力势能"]},{"title":"质量相等时速度交换","type":"结论整理","judge":"1 号球与 2 号球质量相同，弹性碰撞后两球速度是什么关系","why":"等质量弹性对心碰撞的动量与动能守恒方程联立后，唯一解是两球交换速度","do":"把 m_1=m_2 代入弹性碰撞通解，验证碰后速度互换，从而把 1 号球的速度直接传给 2 号球","expr":"v_1'=v_2,\\ v_2'=v_1","cues":["质量相等","速度交换","直接传下去"],"concepts":["等质量弹性碰撞","速度交换"]},{"title":"多次碰撞的递推关系","type":"数学处理","judge":"P 与 1 号球第 n 次碰撞后的速度，能否由前一次碰撞后的速度按固定比例递推","why":"每次 P 从上一平台到下一平台获得相同高度差带来的速度增量，再与等质量球碰撞交换速度，过程结构完全重复","do":"设第 k 次碰撞后 P 的速度，写出它到下一平台的速度平方关系，再套用等质量碰撞的速度交换，得到相邻两次的递推式","expr":"v_{k+1}^2 = v_k^2 + 2g\\,\\Delta h","cues":["每次一样","找递推","速度平方加增量"],"concepts":["递推数列","等比数列","弹性碰撞"]},{"title":"等比数列求和取极限","type":"数学处理","judge":"递推式是速度平方的等差还是速度本身的等比，公比由什么决定","why":"递推式中速度平方每次加同一常数，开方后不构成简单等比，需对平方量构造等比或直接累加求和","do":"对速度平方的递推式累加，识别其构成等比数列，用求和公式并令碰撞次数趋于无穷取极限","expr":"v_n^2 = v_0^2 + n\\,2g\\Delta h","cues":["平方在递推","累加求和","取极限"],"concepts":["等比数列","极限","递推求和"]},{"title":"越过最高点的能量临界","type":"临界条件","judge":"N 足够大时，P 要能一直到达出口，对每个倒 V 形管道最高点的能量条件是什么","why":"管道光滑，球要越过最高点必须碰后动能足以克服到最高点的高度差，这是对任意 k 都成立的临界约束","do":"对任意第 k 个倒 V 形管道，写出 P 碰后速度对应的动能不小于爬升到最高点所需重力势能的不等式，再结合递推式化简","expr":"\\frac12 m v_k^2 \\ge mg\\,h_{\\max}","cues":["要过最高点","动能够不够","临界高度"],"concepts":["能量守恒","临界条件","重力势能"]}],"9":[{"title":"跃迁条件与光强无关","type":"前提判断","judge":"判断原子核能否发生跃迁取决于什么，是否与激光的光强（光子数目）有关","why":"能级跃迁的共振条件是单个光子能量恰好等于能级差，光强只改变光子数密度，不改变单个光子能量","do":"比较入射光子能量 hν 与能级差 ΔE 是否相等，据此排除以光强倍增或减半为理由的选项","expr":"h\\nu=\\Delta E","cues":["看单个光子能量","光强不影响","能量要匹配"],"concepts":["能级跃迁","光子能量","共振条件"]},{"title":"由能级差求光子频率","type":"关系建立","judge":"判断该激光的频率应由能级差与普朗克常量之比算出，而不是直接取题给数值","why":"光子能量公式 ε=hν 给出频率与能量的定量关系，是计算频率的唯一依据","do":"用 ν=ΔE/h 代入 1.3×10⁻¹⁸ J 与 6.6×10⁻³⁴ J·s 求频率，再与选项给出的频率数量级比较","expr":"\\nu=\\frac{\\Delta E}{h}","cues":["先算频率","能量除以普朗克常量","看数量级"],"concepts":["光子能量","普朗克常量"]},{"title":"由频率换算真空波长","type":"关系建立","judge":"判断波长需由光速与频率之比得到，并核对数量级","why":"真空中 c=λν，波长与频率成反比，是判断波长选项是否正确的依据","do":"用 λ=c/ν 代入求得波长，与选项中给出的波长值比较","expr":"\\lambda=\\frac{c}{\\nu}","cues":["用光速除频率","波长和频率反比","核对数量级"],"concepts":["光速","波长频率关系"]}],"10":[{"title":"判断电场力方向","type":"前提判断","judge":"晶片所受电场力是指向卡盘还是背离卡盘","why":"题设明确晶片被吸附、向卡盘运动，说明卡盘对晶片的电场力是引力，方向指向卡盘；若误判为斥力，后面功和电势能全反","do":"由“吸附”这一现象反推力的方向，确定电场力指向卡盘","expr":"","cues":["被吸过去","力指向卡盘","是引力"],"concepts":["电场力","静电吸附"]},{"title":"判断电场力做功正负","type":"关系建立","judge":"电场力方向与晶片位移方向是同向还是反向","why":"功的正负只由力与位移的夹角决定，晶片向卡盘运动，位移方向也指向卡盘，与电场力同向","do":"比较电场力方向与位移方向，得出夹角为零、做正功","expr":"W=qEd\\cos\\theta>0","cues":["同向","做正功","位移也朝卡盘"],"concepts":["力与位移夹角"]},{"title":"由做功定电势能变化","type":"关系建立","judge":"电场力做正功时电势能是增大还是减小","why":"电场力做功与电势能变化满足 W=-ΔEp，做正功则电势能减少，这是判断电势能增减的唯一依据","do":"用 W_电=-ΔEp 由正功推出电势能减少","expr":"W_{\\text{电}}=-\\Delta E_p","cues":["做正功电势能减","别和动能混","W等于负的增量"],"concepts":["电势能","电场力做功"]},{"title":"判断场强是否均匀","type":"模型选择","judge":"晶片与卡盘电极之间的电场能否当作匀强电场处理","why":"匀强电场要求场强处处相同，而双电极附近电场随位置变化，题设也未给出匀强条件，不能套用匀强电场模型","do":"依据电极结构判断场强随位置改变，排除“场强处处相同”的说法","expr":"","cues":["不是匀强场","场强各处不同","电极附近会变"],"concepts":["匀强电场","电场分布"]}],"11":[{"title":"读峰值与波形","type":"图像读取","judge":"从 U–t 图上读出电压的最大值，并判断波形是否恒为最大值","why":"有效值由波形决定，只有恒定直流才等于峰值；正弦式交变电流的有效值小于峰值，所以不能把 200 V 直接当有效值","do":"看纵轴最高点读出峰值，再看曲线是否随时间起伏","expr":"U_m=200\\ \\text{V}","cues":["峰值是200伏","曲线在上下波动","不是恒定值"],"concepts":["交变电流","峰值","有效值"]},{"title":"区分峰值与有效值","type":"前提判断","judge":"判断 200 V 是峰值还是有效值，从而确定有效值与 200 V 的大小关系","why":"题给的是 U–t 图像的最大值即峰值，正弦式交变电流的有效值小于峰值，故有效值必小于 200 V","do":"把峰值与有效值作比较，排除把 200 V 当作有效值的说法","expr":"U=\\dfrac{U_m}{\\sqrt{2}}<U_m","cues":["有效值比峰值小","不能拿峰值当有效值"],"concepts":["有效值","峰值"]},{"title":"读周期求频率","type":"关系建立","judge":"从图上读出电压完成一次周期性变化所用的时间，再由它求频率","why":"频率与周期互为倒数，周期必须从图像相邻同相位点（如相邻两个峰值）的水平间距读出","do":"量相邻两个峰值（或相邻两个过零点同向）之间的横轴间隔得周期，再取倒数","expr":"T=0.02\\ \\text{s},\\quad f=\\dfrac{1}{T}=50\\ \\text{Hz}","cues":["相邻峰值间隔","周期是0.02秒","频率取倒数"],"concepts":["周期","频率"]}],"12":[{"title":"确定安全到达的边界轨迹","type":"临界条件","judge":"要判断飞行器恰好安全到达着陆线的两种极限轨迹分别是什么","why":"速度过小会撞在坑边左侧壁，速度过大会越过着陆线右端，安全区域由两条擦边轨迹夹出","do":"画出从 P 点正上方出发、只受月面重力的抛物线，找出擦过坑边和擦过着陆线右端的两条极限轨迹","expr":"","cues":["擦着坑边","刚好越过","两条边界"],"concepts":["平抛运动","临界轨迹"]},{"title":"判断竖直位移取哪个深度","type":"几何关系","judge":"最小速度对应的竖直下落距离是 H 还是 H+h","why":"最小速度轨迹要刚好通过月面坑边再落到着陆线，竖直方向从关闭动力处一直落到着陆线，总深度为月面上空高度加深坑深度","do":"比较关闭动力点高度 H 与着陆线深度 h，把两段竖直距离相加","expr":"y_{\\min}=H+h","cues":["要加上坑深","从关闭动力处算起","落到着陆线"],"concepts":["竖直位移","自由落体"]},{"title":"判断水平位移取哪一段","type":"几何关系","judge":"最小速度的水平位移是 l 还是 l+d，最大速度的水平位移又是哪一段","why":"水平方向匀速，位移由起点到落点的水平距离决定，最小速度对应坑边，最大速度对着陆线右端","do":"从 P 点正上方量到坑边得 l，量到着陆线右端得 l+d","expr":"x_{\\min}=l,\\quad x_{\\max}=l+d","cues":["量到坑边","量到右端","水平距离看落点"],"concepts":["水平位移","匀速直线运动"]},{"title":"用竖直下落求飞行时间","type":"关系建立","judge":"竖直方向初速度为零，能否用自由落体公式由下落高度反求时间","why":"关闭动力后只受月球重力，竖直分运动为初速为零的匀加速直线运动","do":"对两种极限轨迹分别列竖直方向方程，解出各自的时间","expr":"H+h=\\tfrac12 g_\\text{月}t^2,\\quad H=\\tfrac12 g_\\text{月}t'^2","cues":["竖直初速为零","先求时间","自由落体"],"concepts":["自由落体运动","运动学公式"]},{"title":"由水平位移求速度范围","type":"数学处理","judge":"把两个时间分别代入水平匀速关系，得到的是速度的下限还是上限","why":"水平位移随速度增大而增大，时间越短对应的水平速度越大","do":"分别用 l/t 与 (l+d)/t' 算出两个边界速度，再写出安全速度所在的区间","expr":"v_{\\min}=\\frac{l}{t},\\quad v_{\\max}=\\frac{l+d}{t'}","cues":["小速度对应坑边","大速度对应右端","取中间区间"],"concepts":["平抛运动","速度范围"]}],"13":[{"title":"电子偏转方向判定","type":"前提判断","judge":"磁场垂直底面向外（向上）时，沿边缘射入的负电子应向哪一侧偏转","why":"洛伦兹力方向由左手定则结合负电荷反向判定，偏转方向决定电子打到哪个侧面、圆心在入射线的哪一侧","do":"由速度方向与磁场方向叉乘后取负，确定受力指向，画出三个电子各自的圆弧轨迹","expr":"\\vec F=-e\\,\\vec v\\times\\vec B","cues":["负电荷要反向","磁场向上","往哪边弯"],"concepts":["洛伦兹力","左手定则"]},{"title":"圆心角与时间关系","type":"几何关系","judge":"电子1打到相邻侧面时，其轨迹圆心角是否为90°","why":"入射速度垂直于左侧面，出射点在某侧面上，速度方向与边界的关系决定圆心角，进而决定运动时间占周期的比例","do":"画出电子1的圆弧，找出入射点与出射点处速度方向的夹角，确定圆心角","expr":"t=\\frac{\\theta}{2\\pi}T=\\frac{\\theta m}{eB}","cues":["先看圆心角","转了多少度","时间看角度"],"concepts":["圆周运动","周期","圆心角"]},{"title":"半径与速度动能关联","type":"关系建立","judge":"比较不同电子速度大小时，能否由轨迹半径直接比较","why":"洛伦兹力提供向心力得 r=mv/(eB)，同一磁场中半径与速度成正比，半径大小即速度大小","do":"由轨迹弯曲程度比较三个电子的半径，再由 r∝v 和 Ek∝v² 比较速度与动能","expr":"r=\\frac{mv}{eB},\\quad E_k=\\frac{e^2B^2r^2}{2m}","cues":["半径大速度大","看弯得厉害不","动能跟速度平方"],"concepts":["向心力","轨道半径","动能"]},{"title":"弦长几何求半径","type":"几何关系","judge":"电子2、3打到侧面时，如何用出射点到边缘的距离 x 与边长 a、b 构造半径方程","why":"圆心在入射点垂线上，出射点到入射线的垂距与沿边距离构成直角三角形，斜边为半径","do":"对电子2用 (r-b)²+x₂²=r²，对电子3用 (r-a)²+x₃²=r²，解出各自半径","expr":"(r_2-b)^2+x_2^2=r_2^2,\\quad (r_3-a)^2+x_3^2=r_3^2","cues":["找直角三角形","圆心在入射垂线上","用勾股定理"],"concepts":["几何关系","勾股定理","轨道半径"]},{"title":"动量由半径换算","type":"关系建立","judge":"求动量时是否用 p=eBr 而非先求速度再乘质量","why":"由 r=mv/(eB) 直接得 p=mv=eBr，避免多算一步速度，且半径已由几何关系求出","do":"把几何关系解出的 r₃ 代入 p=eBr 得动量表达式","expr":"p=eBr=\\frac{eB(x_3^2+a^2)}{2x_3}","cues":["动量直接用半径","不用再求速度","p等于eBr"],"concepts":["动量","轨道半径","洛伦兹力"]}],"14":[{"title":"刻度尺估读规则","type":"实验操作","judge":"读 s1 时要不要在毫米刻度后估读一位","why":"毫米刻度尺分度值为 1 mm，读数必须估读到分度值的下一位，否则有效数字位数不够","do":"对照图 1(b) 中 s1 两端所对刻度，按毫米位加一位估读记录","expr":"","cues":["估读到下一位","毫米刻度尺","读到零点几毫米"],"concepts":["刻度尺读数","估读","有效数字"]},{"title":"中间时刻速度替代","type":"关系建立","judge":"B 点瞬时速度能否用 A、C 间平均速度代替","why":"自由下落为匀变速直线运动，某段时间中间时刻的瞬时速度等于该段平均速度","do":"取 A 到 C 的位移 s1+s2、时间 2T，求平均速度作为 B 点速度","expr":"v_1=\\frac{s_1+s_2}{2T}","cues":["中间时刻速度","用平均速度代替","匀变速才成立"],"concepts":["匀变速直线运动","中间时刻瞬时速度","平均速度"]},{"title":"用逐差求加速度","type":"关系建立","judge":"求 C 点速度时，加速度该由哪段位移差给出","why":"相邻相等时间间隔的位移差恒定，s2−s1 对应一个 T 内的速度增量，是求 a 的唯一数据来源","do":"由 s2−s1=aT² 求 a，再代入 v2=v1+aT 消去 a","expr":"a=\\frac{s_2-s_1}{T^2},\\quad v_2=\\frac{3s_2-s_1}{2T}","cues":["逐差法","先求加速度"],"concepts":["逐差法","加速度","速度时间关系"]},{"title":"图像读数取点","type":"图像读取","judge":"Ip=158 a.u. 时在 F–Ip 图上对应哪个 F 值","why":"F 只能由已知的 F–Ip 曲线查得，读数偏差会直接传进压缩时间","do":"在横轴找到 158，竖直对应到曲线上，再水平读纵轴 F","expr":"","cues":["先找横坐标","对应到曲线上","再读纵轴"],"concepts":["图像读数","F–Ip 关系"]},{"title":"动量定理建模","type":"模型选择","judge":"压缩过程中动量变化该取初末速度的哪个组合","why":"小球接触薄膜前速度 v2、离开后速度近似为零，冲量只由薄膜平均冲击力提供，故动量变化为 mv2，公式中出现 2mv2/F","do":"对小球与薄膜作用过程列动量定理，取末动量为零，解出压缩时间","expr":"F t=m v_2,\\quad t=\\frac{m v_2}{F}","cues":["末速度取零","只算冲击力冲量","动量变化是m乘v2"],"concepts":["动量定理","冲量","平均冲击力"]},{"title":"有效数字与单位统一","type":"数据处理","judge":"代入时质量、时间、力是否统一到国际单位，结果保留几位","why":"m 以 g 给出、T 以 s 给出、F 以 N 给出，不换算会差三个数量级；题目要求保留 3 位有效数字","do":"把 30.0 g 换成 0.0300 kg，T 用 0.02 s，F 用 100 N 代入后按 3 位有效数字写出","expr":"t=\\frac{2m v_2}{F}","cues":["克换成千克","保留三位有效数字","单位要统一"],"concepts":["单位换算","有效数字"]}],"15":[{"title":"充气对象与总量守恒","type":"模型选择","judge":"把充入的 p0、V0 气体与 10 个气室内的气体取为同一团气体，判断充气前后质量（物质的量）不变","why":"单向阀充气是把外部气体全部送入气室，气道内气体忽略，故总量守恒；若只对单个气室列式会漏掉 10 倍因子","do":"写出充气前总状态 (p0,V0) 与充气后总状态 (p1,10V1)，对整团气体列等温方程","expr":"p_0V_0=p_1\\cdot 10\\pi r^2h","cues":["取整体","十个气室一起算","气体总量不变"],"concepts":["玻意耳定律","理想气体","质量守恒"]},{"title":"等温规律的适用判断","type":"前提判断","judge":"判断充气过程和挤压变形过程是否可视为等温过程","why":"题设明确充气及挤压变形过程中气体温度始终与室温相同，故两过程均满足玻意耳定律 pV=常量","do":"对第（1）（2）问分别确认 T 不变，选用 pV=常量而非理想气体状态方程全式","expr":"p_1V_1=p_2V_2","cues":["温度不变","用玻意耳定律","等温过程"],"concepts":["玻意耳定律","等温过程"]},{"title":"周长不变定跑道形尺寸","type":"几何关系","judge":"判断变形前后横截面周长相等，并据此求出跑道形直边长度","why":"题设给出横截面周长保持不变，这是唯一能联系原半径 r 与变形后直径 d 的几何约束","do":"令原圆周长 2πr 等于跑道形周长 πd+2L（L 为单根直边长），解出 L 后代入面积公式","expr":"2\\pi r=\\pi d+2L,\\quad L=\\frac{2\\pi r-\\pi d}{2}","cues":["周长不变","跑道形拆成圆加矩形","直边长度"],"concepts":["周长守恒","几何约束"]},{"title":"跑道形截面积与体积","type":"关系建立","judge":"把跑道形截面分解为整圆加矩形，判断变形后气室体积为截面积乘长度 h","why":"长度 h 不变，体积只由截面积决定；面积算错则第（2）（3）问全错","do":"用 S'=πd²/4+dL 求截面积，再乘 h 得 V2，并与 V1=πr²h 对比","expr":"S'=\\frac{\\pi d^2}{4}+d\\cdot\\frac{2\\pi r-\\pi d}{2}=\\frac{\\pi d(4r-d)}{4},\\quad V_2=S'h","cues":["拆成圆和矩形","面积乘长度","先算截面积"],"concepts":["截面积分解","体积计算"]},{"title":"等容升温的临界条件","type":"临界条件","judge":"判断第（3）问体积不变、压强随温度升高而增大，爆破临界对应 p=pc","why":"体积不变时由查理定律 p/T=常量，压强随 T 单调增大，故不爆破的最高温度对应压强恰好达到 pc","do":"以变形后状态 (p2,T0) 为初态，列等容方程，令末态压强为 pc 解出 Tc","expr":"\\frac{p_2}{T_0}=\\frac{p_c}{T_c}\\Rightarrow T_c=\\frac{p_cT_0}{p_2}","cues":["体积不变","压强到pc就爆","等容升温"],"concepts":["查理定律","等容过程","临界状态"]}],"16":[{"title":"确定小球平衡时的偏角","type":"几何关系","judge":"小球刚接触 N 板时，悬绳偏离竖直方向的角度是多少","why":"两绳等长、夹角为直角，且小球与横杆距离为 d，横杆在两板正中间，这些几何条件共同确定小球到达 N 板时的位置","do":"由两绳互相垂直且等长，得每根绳与竖直方向夹角为 45°；再结合小球到横杆的竖直距离 d 与板间距 d 的水平关系，求出小球在 N 板处悬绳与竖直方向的夹角","expr":"","cues":["两绳夹角直角","绳与竖直成多少度","画几何图"],"concepts":["几何关系","等长轻绳"]},{"title":"用平衡条件求恒定电压","type":"关系建立","judge":"小球缓慢移动过程中每个时刻都平衡，接触 N 板瞬间电场力与重力的比例由偏角决定","why":"缓慢移动意味着任一位置合力为零，电场力水平、重力竖直，二者合力必沿绳方向","do":"对接触 N 板瞬间的小球受力分析，列水平与竖直方向的平衡方程，消去绳拉力，得电场力与重力的比值，再由 E=U/d 求 U","expr":"\\tan\\theta=\\frac{qU}{mgd}","cues":["缓慢移动即平衡","电场力比重力","合力沿绳"],"concepts":["共点力平衡","匀强电场"]},{"title":"碰撞后电荷反转变向","type":"前提判断","judge":"小球与 N 板接触后电荷变为 -q，电场力方向反转，小球将沿哪段圆弧运动","why":"题设规定每次碰撞后电性反转、速度减为零，故小球从 N 板由静止出发，在反向电场力作用下向 M 板摆动","do":"明确碰撞后小球从 N 板处静止释放，沿以悬点为圆心的圆弧向 M 板运动，确定初末位置与高度变化","expr":"","cues":["电性反转","速度减为零","从静止出发"],"concepts":["电荷反转","圆弧运动"]},{"title":"用动能定理求碰 M 前速度","type":"关系建立","judge":"从 N 板到 M 板过程中，重力做功与电场力做功各为多少，如何求碰前速度","why":"绳拉力始终垂直于速度不做功，只有重力和电场力做功，可用动能定理","do":"写出 N 到 M 的竖直高度差与水平位移，分别算重力做功和电场力做功，求和得碰 M 前瞬间动能","expr":"W_G+W_E=\\frac12 mv^2","cues":["绳拉力不做功","重力电场力做功","用动能定理"],"concepts":["动能定理","功的计算"]},{"title":"碰 M 前瞬间的径向受力","type":"模型选择","judge":"碰 M 前瞬间小球做圆周运动，沿绳方向的合力提供向心力，需分解哪些力","why":"小球沿圆弧运动，在最低点附近径向加速度由向心力公式给出，重力、电场力、两绳拉力沿径向的分量共同决定","do":"在碰 M 前瞬间沿绳方向列牛顿第二定律，代入已求速度，解出单根绳拉力","expr":"2T\\cos\\theta-mg\\cos\\theta-qE\\sin\\theta=\\frac{mv^2}{R}","cues":["沿绳方向列向心力","两根绳各一半","分解重力和电场力"],"concepts":["向心力","牛顿第二定律"]},{"title":"往复运动条件与最大动能","type":"临界条件","judge":"电压变为 k 倍后，小球仍能沿圆弧往复运动需满足什么条件，最大动能出现在何处","why":"绳只能拉不能推，绳拉力须始终大于零；同时需判断合力做功正负的转折点，确定动能最大位置","do":"由绳拉力非负得 k 的上限；再比较不同 k 下合力方向与位移方向的夹角，判断最大动能是在到达极板时还是圆弧中点处取得，分段写出 Ek","expr":"T>0,\\quad E_k=\\frac12 mv^2","cues":["绳拉力不能为负","合力做正功最多处","分情况讨论"],"concepts":["临界条件","动能定理","受力分析"]}],"17":[{"title":"识别核反应方程","type":"前提判断","judge":"判断两个反应式各属于哪类核反应、反应前后哪些核素已知","why":"只有先确认反应物与生成物中已知核素的质量数和电荷数，才能用守恒律求未知核素","do":"写出两个反应式，标出每个已知核素的质量数A和电荷数Z","expr":"","cues":["先看反应物","标出质量数","认出已知核素"],"concepts":["核反应方程","质量数","电荷数"]},{"title":"质量数守恒定A","type":"关系建立","judge":"判断反应前后质量数总和是否相等，从而求X、Y的质量数","why":"核反应中质量数守恒是基本规律，未知核素的质量数只能由此确定","do":"对每个反应式列质量数守恒方程，用已知核素质量数反推X、Y的质量数","expr":"A_前=A_后","cues":["质量数守恒","前后相加相等","反推质量数"],"concepts":["质量数守恒"]},{"title":"电荷数守恒定Z","type":"关系建立","judge":"判断反应前后电荷数总和是否相等，从而求X、Y的电荷数","why":"核反应中电荷数守恒，未知核素的电荷数只能由此确定，且电荷数决定元素种类","do":"对每个反应式列电荷数守恒方程，用已知核素电荷数反推X、Y的电荷数","expr":"Z_前=Z_后","cues":["电荷数守恒","前后电荷相等","反推电荷数"],"concepts":["电荷数守恒"]},{"title":"由A、Z认核素","type":"结论整理","judge":"判断求得的(A,Z)对应哪种粒子：中子、电子还是其他","why":"质量数1电荷数0为中子，质量数0电荷数-1为电子，这是识别粒子的判据","do":"把求出的A、Z与常见粒子对照，确定X、Y的名称","expr":"","cues":["质量数一电荷零","电荷负一","对照粒子表"],"concepts":["中子","电子","粒子识别"]}],"18":[{"title":"由曲线峰位判温度高低","type":"图像读取","judge":"要判断哪条速率分布曲线对应更高的温度","why":"温度是分子平均动能的标志，温度越高，分子速率分布的峰值越向大速率方向移动，同时峰值降低、曲线变平缓","do":"比较状态Ⅰ与状态Ⅱ两条曲线的峰值位置和峰高，看哪条峰位更靠右、峰更矮更平","expr":"","cues":["看峰值位置","峰越靠右温度越高","曲线更平缓"],"concepts":["速率分布曲线","温度","统计规律"]},{"title":"内能只由温度决定","type":"前提判断","judge":"要判断一定质量理想气体的内能变化是否只取决于温度变化","why":"理想气体分子间无相互作用势能，内能只是分子热运动动能的总和，一定质量时仅由温度决定","do":"由Ⅰ到Ⅱ温度升高，直接判定内能增大，不必考虑体积或压强如何变化","expr":"","cues":["理想气体无势能","内能只看温度","温度升内能增"],"concepts":["理想气体内能","温度"]},{"title":"统计规律不等于每个分子","type":"前提判断","judge":"要判断温度升高能否推出每个分子的速率都增大","why":"速率分布是大量分子的统计规律，只说明各速率区间的分子数占比变化，单个分子的速率有增有减","do":"把“平均速率增大”与“每个分子速率增大”区分开，排除绝对化表述","expr":"","cues":["统计规律","不是每个分子","平均不是都"],"concepts":["统计规律","平均速率"]},{"title":"曲线下面积为分子数占比","type":"关系建立","judge":"要判断曲线下某速率区间的面积代表什么物理量","why":"纵轴是单位速率区间内分子数占总分子数的百分比，对速率区间积分即该区间分子数占总分子数的比例","do":"把两状态曲线在同一速率区间下的面积作比较，面积大者该区间分子占比大","expr":"","cues":["面积就是占比","看区间面积","纵轴是百分比"],"concepts":["速率分布函数","归一化"]},{"title":"峰位右移使小速率侧占比减小","type":"结论整理","judge":"要判断峰位右移后，小于某给定速率的分子占比如何变化","why":"曲线总面积恒为1，峰位右移且曲线变平，小速率一侧的面积被压缩，大速率一侧面积增大","do":"比较两曲线在给定速率左侧（或某区间）的面积大小，得出占比增减方向","expr":"","cues":["总面积不变","峰右移左边变小","占比此消彼长"],"concepts":["速率分布曲线","面积占比"]}],"19":[{"title":"匀速即力平衡","type":"前提判断","judge":"物体沿斜坡匀速上拉时，拉力是否等于重力沿坡分量与摩擦力之和","why":"匀速运动加速度为零，由牛顿第二定律沿斜面方向合力为零，才能把拉力写成重力分量加摩擦力","do":"沿斜面方向列力平衡方程，把拉力用 mg sinθ 与 μmg cosθ 表示","expr":"F=mg\\sin\\theta+\\mu mg\\cos\\theta","cues":["匀速就是受力平衡","加速度为零","拉力等于阻力之和"],"concepts":["牛顿第二定律","平衡状态","滑动摩擦力"]},{"title":"功率用Fv而非平均","type":"关系建立","judge":"恒定速度下拉力功率该用 P=Fv 还是用功除以时间","why":"速度恒定，瞬时功率与平均功率相同，P=Fv 可直接由拉力得到，无需另设位移或时间","do":"写出 P=Fv，把上一步的 F 代入，得到功率只含 m、θ、μ、v","expr":"P=Fv=(mg\\sin\\theta+\\mu mg\\cos\\theta)v","cues":["匀速功率就是力乘速度","不用算时间","P等于F乘v"],"concepts":["功率","瞬时功率"]},{"title":"增量取质量差","type":"数学处理","judge":"功率增加量是两功率之差，差值中哪些因子可以提出来","why":"前后速度 v、倾角 θ、摩擦因数 μ 均相同，只有被拉物体质量由 m 变为 M，功率差只与质量差成正比","do":"用穿戴后的功率减穿戴前的功率，提取公因子 (sinθ+μcosθ)v，剩下 (M−m)g","expr":"\\Delta P=(M-m)g(\\sin\\theta+\\mu\\cos\\theta)v","cues":["两式相减","速度一样可以提出来","只看质量差"],"concepts":["功率差","控制变量"]},{"title":"排除只算重力项","type":"结论整理","judge":"干扰项是否漏掉了摩擦力对应的功率，或把质量差写反","why":"斜坡上有摩擦，克服摩擦做功同样消耗功率，漏掉 μmg cosθ 项或把 M−m 写成 m−M 都会得到错误选项","do":"核对结果中同时含 sinθ 与 μcosθ 两项，且质量因子为 M−m 而非 m−M","expr":"\\Delta P=(M-m)gv(\\sin\\theta+\\mu\\cos\\theta)","cues":["不能漏掉摩擦","质量差不能反","两项都要有"],"concepts":["摩擦力做功","功率差"]}],"20":[{"title":"弹簧伸长量相同","type":"前提判断","judge":"三根弹簧的伸长量是否相等，能否只设一个未知量","why":"三球静止在同一水平面，正四面体三棱对称，三球位置等价，弹簧原长相同且形变对称","do":"由对称性判定三根弹簧伸长量相同，统一设为同一未知量","expr":"","cues":["三球等高","对称","设一个伸长量"],"concepts":["对称性","胡克定律"]},{"title":"杆与地面夹角","type":"几何关系","judge":"正四面体的棱与水平面夹角由什么几何关系确定","why":"正四面体棱长与高的关系固定，杆的一端在水平面上，需由正四面体几何求出棱与水平面的夹角","do":"用正四面体高与棱长的关系求棱与水平面夹角的正弦或余弦","expr":"\\sin\\theta=\\frac{h}{a}=\\sqrt{\\frac{2}{3}}","cues":["正四面体高","棱与地面夹角","几何关系"],"concepts":["正四面体几何","空间角"]},{"title":"沿杆方向平衡","type":"模型选择","judge":"对小球沿哪个方向列平衡方程，为什么选杆方向","why":"杆光滑只能提供垂直于杆的弹力，沿杆方向只有弹簧弹力的分量与重力分量，沿杆方向列式可避开杆的弹力","do":"对一个小球沿杆方向列平衡方程，把弹簧弹力沿杆分量与重力沿杆分量相等","expr":"2F\\cos\\alpha=mg\\sin\\theta","cues":["沿杆方向","避开杆的弹力","光滑杆"],"concepts":["受力分析","平衡条件","弹力方向"]},{"title":"弹力与杆的夹角","type":"几何关系","judge":"弹簧弹力方向与杆方向的夹角如何由正四面体几何确定","why":"弹簧沿两球连线方向，连线是正四面体的棱，需由棱与棱的空间夹角确定弹力与杆的夹角","do":"由正四面体相邻棱的夹角求弹力与杆的夹角余弦","expr":"\\cos\\alpha=\\frac{1}{2}","cues":["棱与棱夹角","弹力沿棱","空间角"],"concepts":["正四面体几何","空间角"]},{"title":"联立求伸长量","type":"数学处理","judge":"把几何角与平衡方程联立，解出伸长量表达式","why":"平衡方程中含弹力与伸长量的胡克关系，需代入几何角消去角度","do":"将胡克定律与平衡方程联立，消去角度解出伸长量","expr":"x=\\frac{mg\\sin\\theta}{2k\\cos\\alpha}","cues":["胡克定律","联立","消去角度"],"concepts":["胡克定律","平衡条件"]}],"21":[{"title":"碰后速度交换","type":"关系建立","judge":"质量相等的两物块发生弹性碰撞后，速度如何分配","why":"等质量弹性碰撞同时满足动量守恒与动能守恒，联立解得两物块交换速度，这是后续所有运动描述的起点","do":"对碰撞瞬间列动量守恒和动能守恒两式，消元求出碰后两物块速度","expr":"m v_0 = m v_M + m v_N,\\ \\frac12 m v_0^2=\\frac12 m v_M^2+\\frac12 m v_N^2 \\Rightarrow v_M=v_0,\\ v_N=0","cues":["交换速度","等质量弹性碰撞","碰后一个停"],"concepts":["弹性碰撞","动量守恒","动能守恒"]},{"title":"判断M碰后是否滑动","type":"前提判断","judge":"碰后M获得速度v，它所受重力沿斜面分量与最大静摩擦力的大小关系","why":"题设M恰好静止说明重力沿斜面分量恰等于最大静摩擦力，碰后M沿斜面向下运动时摩擦力方向反向，合力为零，故M做匀速运动而非减速","do":"比较碰后M沿斜面方向的合力：重力分量与滑动摩擦力等大反向，判断加速度是否为零","expr":"mg\\sin\\theta=\\mu mg\\cos\\theta \\Rightarrow a_M=0","cues":["恰好静止","匀速直线","摩擦力反向"],"concepts":["最大静摩擦力","滑动摩擦力","平衡条件"]},{"title":"N碰后加速度","type":"模型选择","judge":"N与斜面间无摩擦，碰后N从静止开始做什么运动","why":"N只受重力与支持力，沿斜面方向只有重力分量，做初速为零的匀加速直线运动","do":"对N沿斜面方向列牛顿第二定律求加速度","expr":"a_N=g\\sin\\theta","cues":["无摩擦","匀加速","从静止开始"],"concepts":["牛顿第二定律","匀变速直线运动"]},{"title":"两次碰撞间位移相等","type":"关系建立","judge":"从一次碰后到下一次碰前，M与N的位移满足什么关系","why":"两物块在同一直线上运动，再次相遇时从同一位置出发，位移必然相等，这是求碰撞时间间隔的关键","do":"分别写出M匀速、N匀加速的位移表达式，令二者相等解出时间间隔","expr":"v\\,t=\\frac12 a_N t^2 \\Rightarrow t=\\frac{2v}{g\\sin\\theta}","cues":["位移相等","再次相遇","同一起点"],"concepts":["追及相遇","位移关系"]},{"title":"逐次碰撞的速度递推","type":"数学处理","judge":"每次碰撞前N的速度如何变化，碰撞后速度如何交换","why":"每次碰前M速度恒为v、N速度逐次增大，碰后交换速度，使M速度逐次增大、N速度归零，形成规律性递推","do":"由第k次碰前N的速度求碰后M、N速度，再代入位移相等条件求下一次碰撞时刻","expr":"v_N^{(k)}=k\\,g\\sin\\theta\\cdot t,\\quad t_k=\\frac{2k v}{g\\sin\\theta}","cues":["速度越来越大","每次交换","时间间隔成倍"],"concepts":["弹性碰撞","递推规律","匀变速运动"]},{"title":"图像分段与斜率对应","type":"图像读取","judge":"v-t图中各段斜率与速度跳变应如何对应M、N的运动","why":"M匀速对应水平线、N匀加速对应斜线，碰撞瞬间速度交换表现为图线竖直跳变，据此排除斜率或跳变不符的选项","do":"按时间段核对图线斜率（M为零、N为g sinθ）及碰撞时刻的速度值是否与递推结果一致","expr":"","cues":["水平线","斜线","竖直跳变"],"concepts":["v-t图像","斜率表示加速度"]}],"22":[{"title":"区域Ⅰ电动势与充电极性","type":"前提判断","judge":"区域Ⅰ中变化磁场产生的感应电动势大小，以及充电完毕后电容器极板的带电正负","why":"磁场垂直纸面向里且均匀增大，由法拉第定律得电动势为 ΔB/Δt·L²，再由楞次定律判断感应电流为顺时针方向，从而确定上极板带正电；若极性判反，后续放电方向与动量定理符号全错","do":"用法拉第电磁感应定律算电动势，用楞次定律定感应电流方向，再沿回路确定电容器极板极性","expr":"$E=\\dfrac{\\Delta B}{\\Delta t}L^{2}=kL^{2}$","cues":["磁场在增大","顺时针方向","上极板带正电"],"concepts":["法拉第电磁感应定律","楞次定律","电容器充电"]},{"title":"放电回路的最终稳定条件","type":"临界条件","judge":"开关切换后回路达到最终稳定时，回路电流和导体棒速度应满足什么条件","why":"稳定时回路中不再有电流，导体棒不受安培力而做匀速运动，此时电容器两端电压与导体棒切割磁感线产生的动生电动势相等；不抓住这一条件就无法建立速度与电荷量的联系","do":"令稳定时回路电流为零，写出导体棒动生电动势与电容器电压相等的方程","expr":"$BLv=\\dfrac{q}{C}$","cues":["最终电流为零","匀速运动","电压相等"],"concepts":["动生电动势","电容电压","稳定状态"]},{"title":"用动量定理联系速度与电荷量","type":"关系建立","judge":"导体棒从静止到稳定的过程中，安培力的冲量如何与流过它的电荷量挂钩","why":"安培力 F=BIL 对时间积分得 BIL·Δt=BLq，等于导体棒动量的增量；这是把未知速度 v 与未知电荷量 q 联系起来的唯一桥梁，跳过它就无法求解","do":"对导体棒写动量定理，把电流对时间的积分替换为流过的电荷量","expr":"$BLq=mv$","cues":["安培力的冲量","动量定理","电荷量乘磁感应强度"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"电荷守恒分配初末电荷","type":"关系建立","judge":"放电前后两电容器与导体棒所带电荷量之间满足什么守恒关系","why":"断开开关后电荷只能在两电容器与导体棒回路间重新分配，初态总电荷等于末态各电容器电荷量之和；不列此式就少一个方程，无法同时解出末态电荷与速度","do":"写出初态充电电荷量等于末态两电容器电荷量之和的守恒式，并与稳定条件、动量定理联立","expr":"$q_{0}=q_{1}+q_{2}$","cues":["电荷守恒","重新分配","初态等于末态"],"concepts":["电荷守恒","电容器","回路"]}],"23":[{"title":"静摩擦与滑动摩擦的区分","type":"前提判断","judge":"t<2.6s 内拉力随时间增大而物块未动，应判断物块处于静止还是匀速运动","why":"物块由静止被缓慢拉动，拉力先增大到超过最大静摩擦力才起动，拉力未达最大静摩擦前物块保持静止","do":"对照图乙看 0~2.6s 拉力是否随时间单调增大且物块位移为零，确认此段为静止（静摩擦平衡拉力）","expr":"","cues":["拉力在变大","还没拉动","静摩擦平衡"],"concepts":["静摩擦力","最大静摩擦力","二力平衡"]},{"title":"匀速段才可测滑动摩擦","type":"模型选择","judge":"应选哪一时间段的数据来代表滑动摩擦力","why":"只有匀速直线运动时拉力才与滑动摩擦力等大反向，加速或静止阶段拉力都不等于滑动摩擦力","do":"在图乙中找拉力随时间稳定不变的水平段，比较 2.8~6.0s 与 4.0~6.0s 哪段拉力已恒定","expr":"T=f=μmg（匀速时）","cues":["取拉力不变那段","匀速才相等","前面还在加速"],"concepts":["滑动摩擦力","匀速直线运动","平衡条件"]},{"title":"由稳定拉力读摩擦力","type":"图像读取","judge":"从图乙稳定段读出拉力数值作为滑动摩擦力大小","why":"匀速段拉力恒定，其数值即滑动摩擦力，是代入 μ=f/(mg) 的唯一数据来源","do":"读图乙 4.0~6.0s 水平段的纵坐标值，作为 f 代入","expr":"f=T","cues":["读水平段","看纵坐标","拉力恒定值"],"concepts":["滑动摩擦力","图像读数"]},{"title":"正压力等于物重","type":"关系建立","judge":"水平放置时物块对橡胶板的压力是否等于 mg","why":"橡胶板水平固定，竖直方向无加速度，支持力与重力平衡，故正压力 N=mg","do":"写出 N=mg，再与 f=μN 联立求 μ","expr":"μ=\\frac{f}{mg}","cues":["压力等于重力","竖直平衡","水平板"],"concepts":["正压力","滑动摩擦定律","重力"]},{"title":"倾斜时拉力与重力的分力同向","type":"误差分析","judge":"桌面右端偏高时，拉力与重力沿板面分力是相加还是相减，测得 μ 偏大还是偏小","why":"物块从右端被向左拉，沿板面向下运动，重力沿板面的分力与拉力同向，二者共同克服摩擦力，故 T+mgsinθ=μmgcosθ","do":"对倾斜情况列平衡方程，解出 μ 表达式并与水平时的 f/(mg) 比较大小","expr":"μ=\\frac{T+mg\\sin\\theta}{mg\\cos\\theta}>\\frac{T}{mg}","cues":["往下坡拉","重力帮了忙","分母也变了"],"concepts":["力的分解","滑动摩擦力","系统误差"]}],"24":[{"title":"速度选择器平衡条件","type":"前提判断","judge":"粒子在速度选择器中做直线运动时，电场力与洛伦兹力是否等大反向","why":"速度选择器只让特定速率的粒子沿直线通过，电场力 qE 与洛伦兹力 qvB0 必须平衡","do":"对粒子在速度选择器中受力分析，令电场力等于洛伦兹力","expr":"qE=qvB_0","cues":["电场力和洛伦兹力平衡","直线通过","速度不变"],"concepts":["速度选择器","洛伦兹力","电场力"]},{"title":"区域I轨迹半径的几何确定","type":"几何关系","judge":"粒子从(-h,h)水平进入、从O点沿y轴负方向离开，圆弧轨迹的圆心和半径如何由几何条件定出","why":"粒子在区域I做匀速圆周运动，入射速度沿x轴正向、出射速度沿y轴负向，速度方向改变90°，圆心必在入射点正下方与出射点正右方的交点","do":"画出轨迹，由入射点(-h,h)和出射点O的速度方向作垂线定圆心，读出半径","expr":"R_1=h","cues":["速度转90度","圆心在入射点下方","半径等于h"],"concepts":["匀速圆周运动","几何关系","半径"]},{"title":"区域II、III半径与周期换算","type":"关系建立","judge":"粒子在区域II（5B）和区域III（12B）中的轨迹半径与半周期，如何由同一速率v和各自磁感应强度算出","why":"洛伦兹力提供向心力，半径 r=mv/(qB)，周期 T=2πm/(qB)，磁感应强度不同则半径、周期不同","do":"分别代入 B=5B 和 B=12B，写出 r2、r3 与半周期 T2/2、T3/2","expr":"r_2=\\frac{mv}{5qB},\\ r_3=\\frac{mv}{12qB}","cues":["半径和B成反比","周期和B成反比","分别算两区域"],"concepts":["向心力","回旋半径","回旋周期"]},{"title":"分段累加运动时间","type":"数学处理","judge":"从O到P粒子依次经过区域II、III、II的哪些半圆，总时间是否为各段半周期之和","why":"粒子在每段磁场中做半圆运动，进入下一区域时速度方向反转，需按轨迹顺序逐段累加","do":"沿轨迹数出各段半圆，把对应的半周期相加","expr":"t=\\frac{T_2}{2}+\\frac{T_3}{2}+\\frac{T_2}{2}","cues":["一段一段加","半圆时间","按轨迹顺序"],"concepts":["半周期","分段运动","轨迹分析"]},{"title":"速度向上点的坐标递推","type":"关系建立","judge":"粒子每完成一次“区域II下半圆+区域III上半圆”，速度再次沿y轴正方向时x坐标的净变化量是多少","why":"两次半圆运动使x坐标分别变化 2r2 与 -2r3，净位移决定后续相遇点的位置序列","do":"写出单次循环的x净变化，并给出第n个速度向上点的坐标与时刻通式","expr":"\\Delta x=2r_2-2r_3=\\frac{7mv}{30qB}","cues":["一个循环的净位移","速度再次向上","找通项"],"concepts":["位移叠加","周期性","通项"]},{"title":"相遇条件的整数解匹配","type":"临界条件","judge":"a、b在x轴相遇且速度都沿y轴正方向，要求两者的位置序列与时刻序列同时相等，如何确定正整数n、k","why":"相遇必须同时满足坐标相同和时间相同，两式相除消去M后得到关于n、k的整数方程，取最小正整数解","do":"联立 xa(n)=xb(k) 与 ta(n)=tb(k)，消去M，求最小正整数解","expr":"x_a(n)=x_b(k),\\ t_a(n)=t_b(k)","cues":["位置和时刻都要相等","消去质量","取最小正整数"],"concepts":["相遇条件","整数解","联立方程"]}],"25":[{"title":"识别图像为v-t图","type":"图像读取","judge":"要判断图中纵轴表示速度、横轴表示时间，斜率对应加速度","why":"只有v-t图像的斜率才等于加速度，若误认作x-t图像则斜率变成速度","do":"确认纵轴标注为速度v、横轴标注为时间t，明确斜率含义","expr":"","cues":["看纵轴是速度","斜率就是加速度"],"concepts":["v-t图像","加速度"]},{"title":"确定第2s内的时间区间","type":"前提判断","judge":"要判断“第2s内”对应的时间范围是1s到2s，而不是0到2s或2s到3s","why":"加速度需用该段起止时刻的速度差除以对应时间间隔，区间取错则时间差和速度差都错","do":"在横轴上定位t=1s和t=2s两个端点，读出对应的两个速度值","expr":"","cues":["第2秒内是一秒到两秒","不是前两秒"],"concepts":["时间间隔","时刻"]},{"title":"由斜率求加速度大小","type":"关系建立","judge":"要判断加速度等于该段图线的斜率，即速度变化量除以时间间隔，并取绝对值表示大小","why":"加速度定义式a=Δv/Δt，v-t图线斜率即加速度，题目问大小故取绝对值","do":"用两端点速度差除以1s的时间间隔，算出结果并取正","expr":"a=\\left|\\dfrac{\\Delta v}{\\Delta t}\\right|","cues":["速度差除以时间","斜率取绝对值"],"concepts":["加速度定义式","斜率"]}],"26":[{"title":"轨道半径与恒星半径关系","type":"几何关系","judge":"行星轨道半径 r 与恒星半径 R 之间是什么关系","why":"题设给出轨道半径是恒星半径的 n 倍，密度要用恒星自身半径算体积，必须把 r 换成 nR","do":"写出 r = nR，把万有引力方程中的 r 统一用 nR 表示","expr":"r=nR","cues":["半径是n倍","r等于nR"],"concepts":["轨道半径","球体半径"]},{"title":"万有引力提供向心力","type":"模型选择","judge":"行星做匀速圆周运动的向心力由什么力提供","why":"行星只受恒星引力，不考虑其他星体，故引力全部充当向心力","do":"对行星列牛顿第二定律方程，左边写引力，右边写含周期 T 的向心力","expr":"G\\frac{Mm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["引力当向心力","只有万有引力"],"concepts":["万有引力定律","向心力","牛顿第二定律"]},{"title":"由周期反求恒星质量","type":"关系建立","judge":"怎样从周期和轨道半径解出恒星质量 M","why":"方程中行星质量 m 可约去，只剩未知量 M，可直接解出","do":"约去 m，把 r = nR 代入，整理出 M 的表达式","expr":"M=\\frac{4\\pi^{2}r^{3}}{GT^{2}}=\\frac{4\\pi^{2}n^{3}R^{3}}{GT^{2}}","cues":["约掉小m","先求恒星质量"],"concepts":["中心天体质量"]},{"title":"密度用恒星自身体积","type":"前提判断","judge":"算密度时体积该用轨道半径还是恒星半径","why":"平均密度是恒星自身质量与其自身体积之比，体积必须用恒星半径 R，不能用轨道半径 r","do":"写出球体体积 V = 4πR³/3，再写 ρ = M/V","expr":"V=\\frac{4}{3}\\pi R^{3},\\quad \\rho=\\frac{M}{V}","cues":["用恒星自己的半径","不能用轨道半径算体积"],"concepts":["密度","球体体积"]},{"title":"消去半径得密度表达式","type":"数学处理","judge":"代入后 R 能否完全消去，密度是否只由 n、T、G 决定","why":"M 含 R³、V 含 R³，两者相除 R 消掉，说明密度与恒星半径无关，这是本题能求密度的关键","do":"把 M 与 V 代入 ρ = M/V，约去 R³，整理成只含 n、T、G 的式子","expr":"\\rho=\\frac{3\\pi n^{3}}{GT^{2}}","cues":["R会约掉","只剩n和T"],"concepts":["密度公式","代数化简"]}],"27":[{"title":"识别两种接法的电路结构","type":"模型选择","judge":"要判断两种接法下分别有几个电池接入回路、是串联还是单独接入","why":"题干说两个电池组完全相同，接法不同会改变接入回路的电池个数，从而改变总电动势和总内阻，这是列方程的前提","do":"对照电路图，分别画出 a、b 接 d、e 和 a、c 接 d、e 两种情形下的等效回路，数清接入的电池个数","expr":"","cues":["先看接了几个电池","两个电池串联","只有一个电池"],"concepts":["闭合电路欧姆定律","串联电源"]},{"title":"串联电池组的总电动势与总内阻","type":"关系建立","judge":"要判断两个相同电池串联时总电动势和总内阻分别是单个的几倍","why":"串联时电动势相加、内阻相加，若误认为总电动势不变或内阻不变，方程就列错","do":"写出串联组合的总电动势和总内阻与单个电池 E、r 的关系","expr":"E_{总}=2E,\\quad r_{总}=2r","cues":["电动势翻倍","内阻也翻倍","两个加起来"],"concepts":["电源串联","电动势","内阻"]},{"title":"把电流表内阻当零处理","type":"近似条件","judge":"要判断理想电流表的内阻是否计入回路总电阻","why":"题目明确电流表为理想电表，其内阻为零，回路总电阻只含外电阻 R 和电池内阻，漏掉或多加都会使方程不匹配","do":"在两种接法的回路总电阻中都只写 R 与相应电池内阻之和","expr":"R_{总}=R+r\\ \\text{或}\\ R+2r","cues":["理想电表","电流表不分压","内阻为零"],"concepts":["理想电流表","回路总电阻"]},{"title":"按两种接法列闭合电路方程","type":"关系建立","judge":"要判断每种接法下电流、电动势、总电阻三者的对应关系，并据此列出两个独立方程","why":"两个未知量 E、r 需要两个独立条件，题给的两个电流示数正好对应两种接法","do":"对单电池接法写 I1=E/(R+r)，对双电池串联接法写 I2=2E/(R+2r)","expr":"I_1=\\frac{E}{R+r},\\quad I_2=\\frac{2E}{R+2r}","cues":["列两个方程","一个电池一个式子","两个未知数两个条件"],"concepts":["闭合电路欧姆定律","独立方程"]},{"title":"联立求解并取舍结果","type":"数学处理","judge":"要判断联立两式后解出的 E、r 是否为正、是否符合电池的物理意义","why":"代数上可能解出负内阻或与题设不符的根，需按 E>0、r>0 筛选","do":"由两式消去 E 或 r，解出 E 与 r，检验符号后与选项比对","expr":"\\frac{I_1}{I_2}=\\frac{R+2r}{2(R+r)}","cues":["消元求解","内阻不能为负","代回检验"],"concepts":["方程联立","物理意义检验"]}],"28":[{"title":"内外气体温度始终相同","type":"前提判断","judge":"升温过程中内外两部分气体是否始终处于同一温度","why":"系统导热良好且温度缓慢升高，内外气体有充分时间交换热量，达到热平衡","do":"把心形气球内、小气球内两部分气体看作温度同步变化的两个系统，用同一 T 列状态方程","expr":"T_1=T_2=T","cues":["导热良好","缓慢升温","温度一样"],"concepts":["热平衡","理想气体状态方程"]},{"title":"压强差由膜弹性决定","type":"模型选择","judge":"小气球内外压强差由什么决定，升温时这个压强差是否改变","why":"题目说明忽略温度对气球材料性质的影响，弹性膜的附加压强只由形变（即小气球体积）决定，与温度无关","do":"把 p1−p2 与膜在同一体积下提供的附加压强对应起来，判断升温时若体积不变，压强差是否还能维持平衡","expr":"p_1-p_2=\\Delta p_{\\text{膜}}(V_1)","cues":["膜弹力","附加压强","材料性质不变"],"concepts":["弹性膜","附加压强","力学平衡"]},{"title":"等容假设下比较压强增量","type":"关系建立","judge":"若两部分气体都保持体积不变，升温后哪一部分压强增加得更多","why":"两部分气体温度相同、体积不变时，由 p∝T 得 Δp∝p，初始压强大的那部分压强增量也大","do":"先假设 V1、V2 不变，写出 Δp1 与 Δp2 的表达式，用初始 p1>p2 比较两者大小","expr":"\\Delta p=\\frac{p}{T}\\Delta T,\\quad \\Delta p_1>\\Delta p_2","cues":["先假设体积不变","等容变化","压强增量"],"concepts":["查理定律","等容变化"]},{"title":"判断小气球体积变化方向","type":"临界条件","judge":"升温后小气球是膨胀还是收缩","why":"等容假设下气体压强差会超过膜在同一体积下能提供的附加压强，平衡被打破，小气球必须向外膨胀使膜附加压强增大以重新平衡","do":"比较等容假设下的 p1−p2 与膜能提供的附加压强，判断 V1 应增大还是减小","expr":"p_1-p_2>\\Delta p_{\\text{膜}}(V_1)\\Rightarrow V_1\\uparrow","cues":["平衡被打破","向外膨胀","体积变大"],"concepts":["力学平衡","弹性膜"]},{"title":"外部气体压强变化判断","type":"结论整理","judge":"升温后外部气体压强是增大还是减小","why":"外部气体温度升高且体积 V2=V−V1 因 V1 增大而减小，两个因素都使 p2 增大","do":"对外部气体用理想气体状态方程，分析 T 升高与 V2 减小对 p2 的共同影响","expr":"p_2=\\frac{n_2RT}{V-V_1}","cues":["温度升体积减","两个因素同向","压强一定增大"],"concepts":["理想气体状态方程","等压与等容"]}],"29":[{"title":"无弹力即洛伦兹力竖直分量平衡重力","type":"临界条件","judge":"小球与管道无弹力时，竖直方向由什么力平衡重力","why":"无弹力意味着管道对球没有支持力，竖直方向只剩重力与洛伦兹力的竖直分量，二者必须等大反向","do":"把洛伦兹力按竖直和水平分解，竖直分量与重力列平衡式","expr":"qvB\\cos\\theta=mg","cues":["洛伦兹力分解","洛伦兹力","力的分解","平衡条件"],"concepts":["洛伦兹力","力的分解","平衡条件"]},{"title":"水平分量充当向心力","type":"关系建立","judge":"小球做匀速圆周运动的向心力由哪个力提供","why":"无弹力时水平方向只有洛伦兹力的水平分量，它必须指向圆心提供向心力","do":"写出水平分量等于向心力的方程，与竖直平衡式联立","expr":"qvB\\sin\\theta=\\frac{mv^2}{R}","cues":["水平分量指向圆心","向心力由洛伦兹力给"],"concepts":["向心力","洛伦兹力","圆周运动"]},{"title":"由左手定则定绕行方向","type":"前提判断","judge":"正电荷在给定磁场方向下洛伦兹力水平分量指向哪侧，从而确定俯视的绕行方向","why":"正电荷受力方向由左手定则决定，向心力方向决定圆心方位，进而决定顺时针还是逆时针","do":"取管道上一点，分解磁场，用左手定则判断洛伦兹力水平指向，再判断绕行方向","expr":"","cues":["左手定则判方向","正电荷受力同向"],"concepts":["左手定则","洛伦兹力方向"]},{"title":"联立求速率与磁感应强度","type":"数学处理","judge":"由竖直平衡式和水平向心力式能否解出速率和磁感应强度，并据此求周期","why":"两式含v和B两个未知量，联立可解，周期由圆周运动关系得出","do":"两式相除消去B求v，回代求B，再用周期公式计算","expr":"T=\\frac{2\\pi R}{v}","cues":["两式联立消元","先求速率再求周期"],"concepts":["联立方程","周期"]},{"title":"洛伦兹力冲量用动量定理求","type":"模型选择","judge":"半个周期内洛伦兹力的冲量该用动量定理还是直接积分","why":"洛伦兹力方向不断变化，不能直接用F乘时间，但其冲量等于动量变化量，可用动量定理","do":"找出半个周期初末速度矢量，求动量变化量的大小和方向，即为洛伦兹力冲量","expr":"I=\\Delta p=m\\Delta v","cues":["用动量定理求冲量","动量定理","冲量","矢量差"],"concepts":["动量定理","冲量","矢量差"]},{"title":"速率加倍后重新分解求弹力","type":"临界条件","judge":"速率变为2倍后竖直方向不再平衡，需由合力方向判断弹力方向再求大小","why":"速率变化使洛伦兹力各分量改变，竖直方向出现净力，管道必须提供弹力，方向由净力方向决定","do":"对2v重新写竖直、水平方程，比较洛伦兹力竖直分量与重力大小定弹力方向，再合成求大小","expr":"N=\\sqrt{(qv'B\\sin\\theta-\\frac{mv'^2}{R})^2+(qv'B\\cos\\theta-mg)^2}","cues":["先判弹力方向再合成","牛顿第二定律","弹力","力的合成"],"concepts":["牛顿第二定律","弹力","力的合成"]}],"30":[{"title":"从速度图像读周期","type":"图像读取","judge":"v-t 图像中相邻两个同向速度峰值（或相邻两次速度为零且变化趋势相同）之间的时间间隔才是一个完整周期","why":"单摆速度按正弦规律变化，一个周期内速度两次过零、两次达到同向最大，只有相隔一个完整循环的两点时间差才是 T","do":"在拟合曲线上找相邻两个速度最大值（或相邻两个同趋势过零点），读出横坐标之差","expr":"T=t_2-t_1","cues":["看相邻峰值","别取半个波形","过零点间隔是半周期"],"concepts":["简谐运动周期","v-t 图像"]},{"title":"摆长量到球心","type":"实验操作","judge":"摆长应为悬点到摆球球心的距离，刻度尺读数应取球心对应的位置而非球的最低点或最高点","why":"单摆模型把摆球视为质点，等效摆长是悬点到质心的距离，取球的下沿会系统性偏大","do":"比较图中 a、b、c 三个位置，选出与球心等高的那一处读数","expr":"l=L_{悬点\\to 球心}","cues":["量到球心","不是量到球底","球心才是质点"],"concepts":["单摆摆长","质点模型"]},{"title":"由周期公式反解 g","type":"关系建立","judge":"需把单摆周期公式变形，把待求的 g 用测得的 T 和 l 表示","why":"实验原理就是单摆小角度周期公式，g 只能通过该式反解得到","do":"对周期公式两边平方后解出 g","expr":"T=2\\pi\\sqrt{\\frac{l}{g}}\\ \\Rightarrow\\ g=\\frac{4\\pi^2 l}{T^2}","cues":["先平方再解","原理公式变形","g在根号里"],"concepts":["单摆周期公式","重力加速度"]},{"title":"由结果偏小反推零线位置","type":"误差分析","judge":"g 的测量值偏小，在 T 测量准确的前提下只能是摆长测量值偏小，据此判断零刻度线相对悬点的位置","why":"g 与 l 成正比、与 T² 成反比，T 由视频拟合较准，误差主要来自 l 的系统偏差","do":"由 g∝l 判断 l 偏小，再想零刻度线在悬点下方时读数会偏小","expr":"g\\propto l,\\quad g_{测}<g_{真}\\Rightarrow l_{测}<l_{真}","cues":["g偏小说明摆长量小了","零线在下面读数偏小","T是软件拟合的较准"],"concepts":["系统误差","比例关系"]}],"31":[{"title":"确定折射界面与法线","type":"几何关系","judge":"要判断光线在哪个界面发生折射、法线取哪条线，从而确定入射角与折射角的量法","why":"折射定律中的入射角、折射角都是相对法线定义的，界面选错或法线取错，角度全部错位","do":"在矩形截面上标出空气—介质分界面，过入射点作该界面的垂线作为法线，标出光线1的入射角与折射角","expr":"","cues":["先找界面","法线垂直界面","角从法线量"],"concepts":["法线","入射角","折射角"]},{"title":"贴面入射取入射角九十度","type":"近似条件","judge":"要判断“几乎贴着介质表面入射”对应入射角的极限取值","why":"贴着表面意味着光线与界面夹角趋于零，与法线的夹角就趋于90°，这是题目给“几乎”二字的用意","do":"把光线1的入射角取为90°，代入折射定律","expr":"i_1=90^\\circ","cues":["贴着表面","入射角取九十度","极限情况"],"concepts":["极限入射","折射定律"]},{"title":"由拍摄角定折射角","type":"关系建立","judge":"要判断摄像头拍摄角与光线1在介质中折射角之间的几何对应关系","why":"题目说拍摄角度扩大为给定值，光线1恰好射入摄像头，说明折射角由摄像头位置和拍摄角边界共同决定，需用矩形截面的几何关系换算","do":"画出光线1从入射点到摄像头的路径，利用矩形边与法线的平行关系，把拍摄角换算成折射角","expr":"r_1=\\frac{\\pi}{2}-\\frac{\\theta}{2}\\ \\text{（由几何关系确定）}","cues":["画路径图","用矩形几何","拍摄角换折射角"],"concepts":["几何关系","光路图"]},{"title":"全反射临界角判据","type":"临界条件","judge":"要判断光线2在介质内发生全反射时，入射到侧面的角必须不小于临界角","why":"只有入射角达到临界角才发生全反射，这是“发生一次全反射”的定量条件，缺它无法把反射路径与折射率联系起来","do":"写出临界角与折射率的关系，并把它与光线2在介质内射向侧面的几何角对应起来","expr":"\\sin C=\\frac{1}{n}","cues":["全反射要过临界角","临界角看折射率","侧面入射角"],"concepts":["全反射","临界角","折射率"]},{"title":"两次折射加反射联立","type":"数学处理","judge":"要判断光线2的路径包含空气→介质折射、介质内全反射、再射向摄像头三段，需把各段角度用同一几何参数串起来","why":"入射角、介质内折射角、侧面入射角、反射后射向摄像头的角彼此由矩形几何约束关联，单独一段方程解不出入射角","do":"设入射角为i，用折射定律得折射角r，由几何关系写出侧面入射角，令其满足全反射条件，再结合射向摄像头的角度关系联立求解","expr":"\\sin i=n\\sin r,\\quad \\sin(\\text{侧面入射角})\\ge\\frac{1}{n}","cues":["三段路径","角度互相牵连","联立消元"],"concepts":["折射定律","全反射","几何约束"]}],"32":[{"title":"脱离条件的临界判断","type":"临界条件","judge":"小球脱离轻杆的瞬间，杆对球的弹力为零这一条件对应什么力学方程","why":"杆是轻杆，只能沿杆方向提供拉力或推力；弹力为零时，沿杆方向的合力只剩重力的分量，提供向心力","do":"在脱离位置对小球沿杆方向列牛顿第二定律，令杆的弹力为零，解出脱离角与脱离速度","expr":"mg\\cos\\beta=\\dfrac{mv_1^2}{L}","cues":["弹力为零","沿杆方向","向心力"],"concepts":["向心力","牛顿第二定律","临界条件"]},{"title":"脱离前后分段守恒","type":"模型选择","judge":"从静止到脱离、从脱离到落地，各用哪段机械能守恒，脱离点速度是否作为两段的衔接量","why":"杆转动过程中只有重力做功，机械能守恒；脱离后小球只受重力，仍机械能守恒，但脱离点速度是两段的公共量","do":"第一段从最高点到脱离点列机械能守恒求脱离速度，第二段从脱离点到地面再列机械能守恒求落地速度","expr":"mgL(1-\\cos\\beta)=\\tfrac12 mv_1^2,\\quad \\tfrac12 mv_1^2+mgL\\cos\\beta=\\tfrac12 mv^2","cues":["分段守恒","脱离点速度","衔接量"],"concepts":["机械能守恒","轻杆模型"]},{"title":"落地速度的分解","type":"关系建立","judge":"落地速度与水平面夹角的正切应由哪两个分速度之比决定，竖直分速度如何由脱离点竖直分速度加自由落体得到","why":"脱离后水平分速度不变，竖直方向做匀加速运动，故可用速度位移关系单独求竖直分速度","do":"写出脱离点水平、竖直分速度，再用竖直方向速度位移关系求落地竖直分速度，最后取两者之比","expr":"\\tan\\alpha=\\dfrac{v_y}{v_x},\\quad v_y^2=v_{1y}^2+2gL\\cos\\beta","cues":["分速度","竖直方向","速度位移关系"],"concepts":["运动分解","匀变速直线运动"]},{"title":"分裂过程的动量守恒","type":"模型选择","judge":"极短时间内弹射分裂，能否忽略重力和地面冲量而用动量守恒处理","why":"分裂时间极短，外力冲量可忽略，两部分组成的系统动量守恒；同时能量由装置提供，机械能不守恒","do":"沿分裂前速度方向和垂直方向分解，写出动量守恒的两个分量方程，注意两部分速度与分裂前速度方向各成θ角","expr":"mv=m_1v_1'+m_2v_2',\\quad 0=m_1v_{1\\perp}'+m_2v_{2\\perp}'","cues":["极短时间","动量守恒","沿原方向分解"],"concepts":["动量守恒","速度分解"]},{"title":"能量与质量比的函数关系","type":"关系建立","judge":"弹射释放的能量等于分裂前后动能差，需把两部分速度用动量守恒消去后写成k的函数","why":"装置释放的能量转化为两部分动能增量，动量守恒给出速度关系，从而E只由k和分裂前速度决定","do":"由动量守恒解出两部分速度，代入动能差表达式，整理成E关于k的函数","expr":"E=\\tfrac12 m_1v_1'^2+\\tfrac12 m_2v_2'^2-\\tfrac12 mv^2","cues":["动能差","消去速度","写成k的函数"],"concepts":["能量守恒","动量守恒"]},{"title":"E最小与同时落地的联立","type":"数学处理","judge":"E取最小时k满足什么条件，以及两部分第一次落地时刻相同意味着什么","why":"E(k)为二次型函数，其最小值由均值不等式或配方确定；落地时刻相同要求两部分竖直分速度大小相等（因高度相同）","do":"对E(k)求极值定出k，再由竖直分速度相等条件结合动量守恒求出两部分水平分速度，用水平位移差求间距","expr":"E_{\\min}\\Rightarrow k=1,\\quad v_{1y}'=v_{2y}'","cues":["求极值","同时落地","竖直分速度相等"],"concepts":["函数极值","平抛运动","运动独立性"]}],"33":[{"title":"位移只看首末位置","type":"前提判断","judge":"两种运输方式的位移是否由同一对初末位置决定","why":"位移是从初位置指向末位置的有向线段，只由初、末位置决定，与路径无关；题设两种方式都从P到Q","do":"比较两种方式的初位置和末位置是否分别为P和Q","expr":"","cues":["只看起点终点","不管走哪条路"],"concepts":["位移","矢量"]},{"title":"路程与路径相关","type":"模型选择","judge":"路程是否由实际运动轨迹长度决定，两种方式轨迹是否相同","why":"路程是轨迹长度，是标量，不同路径对应不同路程；无人机空中直线飞行与货车盘山公路轨迹不同","do":"比较两种方式的实际运动轨迹是否重合","expr":"","cues":["走的路不一样","空中和山路不同"],"concepts":["路程","轨迹"]},{"title":"时间由路程和速率共同定","type":"关系建立","judge":"运动时间能否仅由位移或仅由某一方速率确定","why":"时间由实际路程与运行速率共同决定，题中两者路程与速率均无确定关系","do":"分析时间与路程、速率的依赖关系，判断是否一定相等","expr":"t=\\frac{s}{v}","cues":["路程速度都没定","快慢不知道"],"concepts":["运动时间","速率"]},{"title":"平均速度依赖时间","type":"关系建立","judge":"位移相同能否推出平均速度相同","why":"平均速度是位移与时间的比值，位移相同但时间不一定相同，比值不一定相同","do":"写出平均速度定义式，比较两方式的时间是否相等","expr":"\\bar{v}=\\frac{\\Delta x}{\\Delta t}","cues":["还要看时间","位移除以时间"],"concepts":["平均速度","位移"]}],"34":[{"title":"判断磁通量是否变化","type":"前提判断","judge":"要判断每种情形下穿过回路的磁通量是否随时间变化","why":"产生感应电流的前提是磁通量变化，磁通量不变则无感应电动势，更无交变电流","do":"对每个图分别看回路面积在垂直于磁场方向上的投影是否改变，或回路与磁场的相对位置是否改变","expr":"\\Phi=BS\\cos\\theta","cues":["看磁通量变不变","面积投影有没有变","线圈平面和磁场夹角"],"concepts":["磁通量","法拉第电磁感应定律"]},{"title":"区分平动与转动","type":"模型选择","judge":"要判断回路是绕轴转动还是整体平动，转动时回路平面与磁场的夹角是否周期性变化","why":"绕垂直于磁场的轴匀速转动时夹角θ随时间周期性变化，磁通量按正弦规律变化；平动时夹角不变","do":"对乙、丁两图分别确认运动方式：乙绕轴转动、丁整体平动，比较两者磁通量随时间的变化规律","expr":"\\Phi=BS\\cos\\omega t","cues":["绕轴转还是平移","转动才有夹角变化","平动磁通量不变"],"concepts":["交变电流的产生","正弦式交流电"]},{"title":"判断电动势是否交变","type":"关系建立","judge":"要判断感应电动势的大小和方向是否随时间周期性变化，从而确定电流是否交变","why":"交变电流要求电动势的大小和方向都随时间周期性变化，仅有恒定电动势只能得到恒定电流","do":"由磁通量变化率求电动势，看乙中电动势是否按正弦规律变化，再看丙中切割磁感线的电动势是否恒定","expr":"e=-\\frac{d\\Phi}{dt},\\quad e=Blv","cues":["电动势方向变不变","是不是正弦变化","切割速度恒定"],"concepts":["感应电动势","交变电流"]},{"title":"排除无电流情形","type":"临界条件","judge":"要判断丁图中回路平动时磁通量是否始终不变、感应电流是否为零","why":"回路整体在匀强磁场中平动，穿过回路的磁通量保持不变，感应电动势为零，谈不上交变电流","do":"比较丁图初末位置回路在垂直磁场方向的投影面积，确认磁通量不变","expr":"\\Delta\\Phi=0\\Rightarrow e=0","cues":["磁通量一直没变","没有感应电流","平动不切割净磁通"],"concepts":["磁通量不变","感应电流条件"]}],"35":[{"title":"万有引力充当向心力","type":"模型选择","judge":"卫星做匀速圆周运动的向心力由什么力提供","why":"卫星只受地球万有引力，且做匀速圆周运动，故引力全部用来提供向心力，这是推出所有参量关系的前提","do":"对卫星列万有引力等于向心力的方程，分别写出含角速度和含线速度的形式","expr":"G\\frac{Mm}{r^2}=m\\omega^2 r=m\\frac{v^2}{r}","cues":["引力提供向心力","只受万有引力"],"concepts":["万有引力定律","向心力","匀速圆周运动"]},{"title":"消去卫星质量求参量","type":"关系建立","judge":"如何把方程化为只含中心天体质量和轨道半径的表达式","why":"卫星质量 m 在等式两边可约去，说明角速度、线速度只由中心天体质量和轨道半径决定，与卫星自身性质无关","do":"约去 m，分别解出角速度和线速度关于轨道半径的表达式","expr":"\\omega=\\sqrt{\\frac{GM}{r^3}},\\quad v=\\sqrt{\\frac{GM}{r}}","cues":["约掉卫星质量","只跟半径有关"],"concepts":["中心天体质量","轨道半径"]},{"title":"判断随半径的变化趋势","type":"结论整理","judge":"轨道半径越大时，角速度和线速度各自如何变化","why":"由表达式可见角速度与半径的二分之三次方成反比、线速度与半径的平方根成反比，两者都随半径增大而减小","do":"比较两卫星的轨道半径大小，按反比关系判断角速度、线速度的大小顺序","expr":"r\\uparrow\\Rightarrow\\omega\\downarrow,\\ v\\downarrow","cues":["半径大反而慢","高轨低速"],"concepts":["反比关系","半径大小比较"]},{"title":"区分与半径无关的量","type":"前提判断","judge":"哪些物理量由中心天体唯一决定、与卫星轨道半径无关","why":"GM 是中心天体的固有量，由它单独决定的量不随轨道半径改变，这正是干扰项设置的关键","do":"检查各选项所比较的量是否只含 GM，若只含 GM 则两卫星相同","expr":"GM=\\text{常量}","cues":["跟地球有关","与半径无关"],"concepts":["中心天体固有量","不变量"]}],"36":[{"title":"加速段与漂移段分界","type":"模型选择","judge":"把整个运动分成匀加速段（AB间）和匀速段（BC间）两段来处理，还是当成单一过程","why":"AB间有电场加速、BC间无场，两段运动性质不同，必须分段列式才能把总时间t与板间距、电压联系起来","do":"以B板小孔为分界，AB段用初速为零的匀加速，BC段用匀速直线","expr":"","cues":["分两段","先加速后匀速","B板是分界"],"concepts":["匀加速直线运动","匀速直线运动","电场加速"]},{"title":"用电压表示加速度","type":"关系建立","judge":"AB间场强该用E=U/d表示，且d是AB间距而非AC间距","why":"开关S闭合时极板间电压U保持不变，场强随板间距变化，这是后面判断各选项变化的出发点","do":"写出E=U/d_AB，再由qE=ma得加速度，进而得B板处速度与加速段时间","expr":"a=\\frac{qU}{md_1},\\quad v=\\sqrt{\\frac{2qU}{m}}","cues":["电压不变","场强看板距","加速度由U和d定"],"concepts":["匀强电场","牛顿第二定律","电压与场强关系"]},{"title":"末速只由U决定","type":"前提判断","judge":"漂移段速度是否与AB间距无关，只由加速电压U决定","why":"由动能定理qU=mv²/2，末速只含U，与板间距无关；这是判断漂移时间随BC长度变化的依据","do":"对加速段用动能定理求v，确认v中不含d_AB","expr":"qU=\\frac{1}{2}mv^2","cues":["速度只看电压","和板距无关","动能定理"],"concepts":["动能定理","加速电压"]},{"title":"总时间随板距的增减","type":"关系建立","judge":"B板移动时，加速段时间与漂移段时间各自如何随d_AB、d_BC变化，总时间如何变","why":"总时间t=t_1+t_2，两项随板位置反向变化，必须分别写出再合成才能判断增减","do":"写出t_1=√(2md_1²/(qU))与t_2=d_2√(m/(2qU))，按B板移动方向分析两项","expr":"t=\\sqrt{\\frac{2md_1^2}{qU}}+d_2\\sqrt{\\frac{m}{2qU}}","cues":["两段时间相加","一项变长一项变短","看谁主导"],"concepts":["运动学公式","时间叠加"]},{"title":"断开后场强不变","type":"临界条件","judge":"S断开后移动B板，AB间场强是否改变","why":"断开后极板电荷量不变，由E=Q/(εS)知场强与板距无关，故加速度不变，这与闭合时结论相反","do":"比较S闭合（U不变）与S断开（Q不变、E不变）两种情形下移动B板对a的影响","expr":"E=\\frac{Q}{\\varepsilon S}","cues":["断开电荷量不变","场强不变","加速度不变"],"concepts":["电容器电荷量","匀强电场"]},{"title":"总时间极值的数学判断","type":"数学处理","judge":"d_1增大时t=d_1√(2m/(qU))+d_2√(m/(2qU))（d_1+d_2固定）是单调减还是有极小值","why":"两项一增一减，需用和固定下的函数性质判断，不能凭直觉说一定变长或变短","do":"令d_2=L-d_1代入，对d_1分析该函数在d_1<L范围内的单调性","expr":"t=\\sqrt{\\frac{2m}{qU}}\\,d_1+\\sqrt{\\frac{m}{2qU}}\\,(L-d_1)","cues":["一增一减","看斜率","和固定求极值"],"concepts":["函数单调性","极值判断"]}],"37":[{"title":"释放瞬间弹簧无形变","type":"前提判断","judge":"释放瞬间弹簧是否已有弹力，能否先按原长处理","why":"初始托住时弹簧处于原长，释放瞬间形变量尚未改变，弹力为零，这是求瞬时加速度的前提","do":"取释放瞬间为状态，令弹簧弹力为零，只保留重力和绳拉力","expr":"F_{弹}=0","cues":["弹簧还没形变","瞬间弹力为零","先按原长算"],"concepts":["弹簧弹力","瞬时状态"]},{"title":"绳两侧加速度关联","type":"关系建立","judge":"由同一根不可伸长轻绳判断两侧物块加速度大小是否相等","why":"轻绳不可伸长且绕过定滑轮，绳上各点速率相同，两侧物块沿绳方向加速度大小相等","do":"对绳两端物块分别列牛顿第二定律，用同一加速度大小 a 联立","expr":"a_1=a_2=a","cues":["同一根绳","加速度一样大","绳长不变"],"concepts":["不可伸长轻绳","加速度关联"]},{"title":"瞬时加速度的求法","type":"模型选择","judge":"求释放瞬间加速度时选谁作研究对象、列几个方程","why":"绳拉力是内力，取绳两端物块整体可消去拉力直接求加速度；求拉力时再隔离单个物块","do":"先对两物块整体列方程求 a，再隔离其一求绳拉力 T","expr":"(m_1-m_2)g=(m_1+m_2)a","cues":["取整体","先求加速度","再隔离求拉力"],"concepts":["整体法","隔离法","牛顿第二定律"]},{"title":"系统动量守恒的判定","type":"前提判断","judge":"释放后系统所受合外力是否为零，能否用动量守恒","why":"两物块重力大小相等、方向相反，绳拉力为内力，系统合外力为零，故动量守恒","do":"比较两侧重力大小，确认合外力为零后写动量守恒式","expr":"m_1v_1=m_2v_2","cues":["合外力为零","动量守恒","两边重力抵消"],"concepts":["动量守恒","合外力"]},{"title":"速度最大在平衡位置","type":"临界条件","judge":"物块速度最大出现在合力为零处还是最低点","why":"加速度为零时速度取极值，此时弹簧弹力与两侧重力差平衡，不是弹簧形变最大处","do":"令合力为零求平衡时的弹簧形变量，再代回能量方程求最大速度","expr":"kx=mg","cues":["合力为零时最快","平衡位置","不是最低点"],"concepts":["平衡位置","临界条件","简谐运动"]},{"title":"能量守恒求最大位移","type":"关系建立","judge":"下降最大距离时用哪种能量关系，弹性势能如何计入","why":"只有重力和弹簧弹力做功，机械能守恒，最低点动能为零，重力势能减少量等于弹性势能增加量","do":"设最大下降距离，写出重力势能减少与弹簧弹性势能相等的方程求解","expr":"mgx=\\frac12kx^2","cues":["机械能守恒","最低点速度为零","重力势能转弹性势能"],"concepts":["机械能守恒","弹性势能"]}],"38":[{"title":"打点计时器操作顺序","type":"实验操作","judge":"应先接通电源还是先释放纸带","why":"打点计时器需通电后振针稳定振动才能打出清晰、连续的点，先拉纸带会漏点或点迹不稳","do":"比较两种操作顺序对纸带点迹完整性的影响，确定先通电后放纸带","expr":"","cues":["先通电","打点稳定再放","先放纸带会漏点"],"concepts":["打点计时器","实验操作规范"]},{"title":"纸带点距的读数","type":"数据处理","judge":"P点左右相邻点的刻度值如何读取并求间距","why":"瞬时速度由相邻两点间位移除以时间得到，必须准确读取相邻点位置","do":"从刻度尺上读出P点左、右相邻点的坐标，用坐标差求两点间距离","expr":"$\\Delta x=x_{\\text{右}}-x_{\\text{左}}$","cues":["读相邻点坐标","用坐标差求距离","别读成P点坐标"],"concepts":["刻度尺读数","位移"]},{"title":"打点周期的确定","type":"前提判断","judge":"相邻两计数点间的时间间隔是打点周期还是其若干倍","why":"电源频率决定打点周期，若中间有计数点间隔需乘以间隔数","do":"由频率求打点周期，确认P点左右相邻点是否为相邻打点","expr":"$T=\\frac{1}{f}$","cues":["先算周期","看是不是相邻点","频率取五十"],"concepts":["打点周期","交流电频率"]},{"title":"瞬时速度的等效替代","type":"模型选择","judge":"用哪段平均速度代表P点的瞬时速度","why":"匀变速直线运动中某段时间的平均速度等于中间时刻的瞬时速度","do":"取P点左右相邻两点间的平均速度作为P点瞬时速度","expr":"$v_P=\\frac{\\Delta x}{2T}$","cues":["用平均速度代替","取左右两点","中间时刻速度"],"concepts":["平均速度","瞬时速度","匀变速直线运动"]},{"title":"平均加速度的求法","type":"关系建立","judge":"用哪两点速度与哪段时间求平均加速度","why":"加速度定义式要求速度变化量与对应时间间隔一致","do":"取P、Q两点瞬时速度之差除以两点间的时间间隔","expr":"$a=\\frac{v_Q-v_P}{\\Delta t}$","cues":["速度差除以时间","对应同一段时间","用定义式"],"concepts":["加速度定义","速度变化量"]}],"39":[{"title":"分段选加速度规律","type":"模型选择","judge":"AB 段与 BC 段粗糙程度不同，应分别对两段各用一次牛顿第二定律求加速度，而不是全程用一个加速度","why":"两段动摩擦因数不同，合力不同，加速度必然不同；机械能损失和后续追及都依赖各自的加速度","do":"对 AB 段沿斜面方向列牛二方程，对 BC 段水平方向列牛二方程，分别解出 a1 与 a2","expr":"mg\\sin\\theta-\\mu_1 mg\\cos\\theta=ma_1,\\quad \\mu_2 mg=ma_2","cues":["分段列方程","两段摩擦不同","先求加速度"],"concepts":["牛顿第二定律","滑动摩擦力","匀变速直线运动"]},{"title":"由运动学反求动摩擦因数","type":"关系建立","judge":"AB 段已知位移、初速为零和末速（或时间），要判断用哪组运动学公式把加速度解出来，再回代牛二方程求 μ1","why":"μ1 不能直接测，只能通过加速度这一桥梁由运动学量与动力学方程联立得到","do":"用速度位移关系或位移时间关系求出 a1，再代入 AB 段牛二方程解出 μ1","expr":"v_B^2=2a_1 L,\\quad \\mu_1=\\tan\\theta-\\frac{a_1}{g\\cos\\theta}","cues":["先求加速度","用位移和速度","回代求摩擦因数"],"concepts":["运动学公式","加速度","动摩擦因数"]},{"title":"机械能损失用摩擦功算","type":"关系建立","judge":"机械能损失应等于该段克服摩擦力做的功（或末机械能减初机械能），不能只算动能变化","why":"下滑过程中重力势能减少同时动能增加，只有摩擦力做负功才造成机械能损失，功能关系给出损失量","do":"写出 AB 段摩擦力做功的绝对值，即损失机械能；也可用初末机械能之差核对","expr":"\\Delta E=\\mu_1 mg\\cos\\theta\\cdot L","cues":["损失等于摩擦做功","用功能关系","别只算动能"],"concepts":["功能关系","机械能","摩擦力做功"]},{"title":"动量变化量取矢量大小","type":"结论整理","judge":"动量是矢量，求“动量变化量的大小”要判断是末动量减初动量的矢量差大小，方向沿斜面，不能把动量大小直接相减后当标量随意处理","why":"初末动量同向沿斜面向下，矢量差大小等于 mv_B-0，但必须明确方向与大小分开表述","do":"先由运动学求出 v_B，再算 Δp=m v_B，注明方向沿 AB 向下","expr":"\\Delta p=m v_B-0","cues":["动量是矢量","同向直接相减","要写方向"],"concepts":["动量","动量定理","矢量性"]},{"title":"判断甲是否已停下","type":"临界条件","judge":"求乙到达 B 点时甲乙距离，必须先判断这段时间内甲在 BC 段是否已经减速到零并停下，否则位移公式用错","why":"甲在 BC 段做匀减速，若在乙到达前已停止，位移应取停止距离而非继续代入减速公式","do":"算出甲在 BC 段的减速度与从 v_B 减速到零所需时间，与乙从 A 滑到 B 所用时间比较","expr":"t_{\\text{停}}=\\frac{v_B}{a_2},\\quad t_\\text{乙}=\\frac{v_B'}{a_1}","cues":["先看停没停","比较两个时间","别盲目代公式"],"concepts":["匀减速运动","临界状态","追及问题"]},{"title":"同起点追及定距离","type":"几何关系","judge":"乙从 A 点出发、甲已到 B 点，两者位置差要用“甲在 BC 段走过的距离”与“乙在 AB 段走过的距离”在滑道上的位置关系来定，不能直接把两段位移相减","why":"AB 与 BC 是折线滑道，甲乙分别处于不同段上，距离需按各段长度与已滑距离换算到同一路径坐标","do":"分别算出乙到达 B 点时甲在 BC 段的位置和乙的位置，用路径坐标差求两者间距","expr":"s_\\text{距}=L_\\text{BC位置}-s_\\text{乙}","cues":["换算到同一路径","看各自在哪段","路径坐标相减"],"concepts":["追及相遇","位移关系","参考位置"]}],"40":[{"title":"电场中类斜抛分解","type":"模型选择","judge":"粒子在板间电场中受恒力、初速度斜向，应判断为类斜抛运动并沿垂直板方向与平行板方向分解","why":"电场力沿y方向恒定，初速度有x、y两个分量，只有分解成两个独立的一维运动才能用运动学方程联系O点位置","do":"取x方向匀速、y方向匀变速，分别写出从发射点到O点的位移方程","expr":"x=L=v_0\\cos\\alpha\\,t,\\quad y=\\tfrac12 a t^2-v_0\\sin\\alpha\\,t","cues":["类斜抛","分两个方向","先分解"],"concepts":["类斜抛运动","运动的分解","匀强电场"]},{"title":"入射磁场速度方向换算","type":"关系建立","judge":"要判断进入磁场的速度方向角与电场中初速度方向角不是同一个角，需由速度分量重新合成","why":"电场力只改变y方向速度，x分量不变，进入磁场时的速度偏转角由末速度分量决定，直接沿用初速度角会算错","do":"先求O点处v_x、v_y，再求进入磁场速度与x轴夹角的正弦","expr":"v_x=v_0\\cos\\alpha,\\quad v_y=v_0\\sin\\alpha-a t,\\quad \\sin\\theta=\\frac{|v_y|}{\\sqrt{v_x^2+v_y^2}}","cues":["速度方向变了","要合成速度","不能直接用初角"],"concepts":["速度合成","速度偏转角"]},{"title":"磁场半径与区域半径相等","type":"几何关系","judge":"需判断粒子圆周运动半径与半圆磁场区域半径同为L这一巧合带来的出射方向规律","why":"轨迹半径等于磁场区域半径时，从边界一点射入的粒子必从边界另一点射出，且出射速度方向与入射点位置有确定的几何对应，这是求射出点和后续碰撞点的前提","do":"作入射点、圆心、出射点与磁场区域圆心的几何图，利用两圆半径相等确定出射速度方向与出射点纵坐标","expr":"r=\\frac{mv}{qB}=L","cues":["半径相等","画两个圆","出射方向水平"],"concepts":["洛伦兹力","匀速圆周运动","几何对称"]},{"title":"弹性碰撞后对称返回","type":"关系建立","judge":"要判断与Q板弹性碰撞后速度反向、轨迹关于碰撞点对称，从而再次进入磁场的位置可由对称性推出","why":"弹性碰撞且电荷量不变，速度大小不变方向反向，磁场中圆周运动轨迹与碰前关于Q板对称，才能由第一次出射点推第二次打到P板的位置","do":"先定第一次出射点纵坐标，再按碰后反向入射作对称轨迹，求再次打到P板的y坐标","expr":"y'=2y_Q-y_{\\text{出}}","cues":["弹性碰撞反向","轨迹对称","用对称性推"],"concepts":["弹性碰撞","对称性","圆周运动"]},{"title":"到达O点的电压门槛","type":"临界条件","judge":"要判断粒子能否到达小孔O取决于电压大小，存在一个使y方向位移恰好为零的临界电压","why":"粒子要进入磁场必须穿过O点，而y方向位移由电场加速与初速度分量共同决定，电压过小时y方向偏移过大无法回到轴线","do":"令到达x=L处时y方向位移为零，解出临界电压，与题给电压比较","expr":"U_0=\\frac{2m v_0^2\\sin^2\\alpha}{q}","cues":["能不能到O点","找临界电压","y位移为零"],"concepts":["临界条件","匀变速直线运动"]},{"title":"不打板与撞击点数目分界","type":"临界条件","judge":"要判断不同电压下有几个发射角能进入磁场、轨迹是否与上极板相切或彼此重合，从而区分无撞击点、1个、2个撞击点","why":"电压改变使可进入磁场的发射角数目和轨迹与极板的相切情况改变，撞击点数目由进入磁场的不同轨迹条数决定，必须逐段找临界电压","do":"对每个候选发射角检验轨迹是否与上极板相切，比较相切临界电压与到达O点临界电压的大小，划分电压区间","expr":"y_{\\max}=\\frac{v_0^2\\sin^2\\alpha}{2a}\\le \\frac{d}{2}","cues":["刚好擦上板","看有几条轨迹","分段讨论电压"],"concepts":["相切临界","轨迹数目","分类讨论"]}],"41":[{"title":"区分路程与位移","type":"前提判断","judge":"题给的两个长度分别对应路程还是位移大小","why":"路程是轨迹长度（标量），位移大小是初末位置的有向线段长度（矢量），二者由不同定义给出，不能混用","do":"把总里程对应到轨迹长度，把起点到终点的直线距离对应到初末位置连线长度","expr":"","cues":["里程是路程","直线距离是位移","轨迹长度","有向线段"],"concepts":["路程","位移"]},{"title":"速度计读数的含义","type":"前提判断","judge":"汽车速度计显示的是瞬时速度还是平均速度","why":"速度计反映某一时刻的速度大小，平均速度需用总位移与总时间之比求得，二者不是同一物理量","do":"明确速度计读数对应某一时刻，与全程平均速度区分开","expr":"","cues":["速度计是瞬时","不是平均速度","某一时刻"],"concepts":["瞬时速度","平均速度"]},{"title":"判断能否视为质点","type":"模型选择","judge":"研究运动轨迹时汽车的大小形状能否忽略","why":"当物体自身线度远小于运动范围时，其大小形状对轨迹描述无影响，可抽象为质点","do":"比较汽车尺寸与数千公里路径的尺度，判断大小形状是否可忽略","expr":"","cues":["取质点","车长可忽略","看轨迹不看转动"],"concepts":["质点","理想化模型"]}],"42":[{"title":"读图取两点坐标","type":"图像读取","judge":"伏安特性曲线上状态 a、b 两点对应的电压和电流各是多少","why":"电阻和功率都要由 U、I 算出，坐标读错后面全错；小灯泡 U-I 图线是曲线，必须逐点读而不能用斜率当电阻","do":"在图上找到状态 a、b 两点，分别向横轴、纵轴作垂线读出 U 和 I","expr":"","cues":["先读电压","再读电流","别用斜率"],"concepts":["伏安特性曲线","坐标读取"]},{"title":"区分电阻与斜率","type":"前提判断","judge":"某点的电阻该用该点 U 与 I 的比值，还是用该点切线斜率","why":"小灯泡灯丝电阻随温度变化，图线是曲线，只有 U/I 才是该状态的电阻，切线斜率没有电阻的量纲意义","do":"对每个状态分别算 U 除以 I，得到该状态的电阻","expr":"R=\\frac{U}{I}","cues":["用比值不用斜率","曲线斜率不是电阻","逐点算电阻"],"concepts":["欧姆定律","非线性元件"]},{"title":"求电阻变化量","type":"关系建立","judge":"电阻变化量是两状态电阻之差，取绝对值还是带符号","why":"题目问的是变化量大小，用两状态电阻作差后取绝对值即可","do":"用状态 b 的电阻减去状态 a 的电阻，取绝对值","expr":"\\Delta R=|R_b-R_a|","cues":["两电阻相减","取绝对值","变化量是正的"],"concepts":["电阻","变化量"]},{"title":"求功率变化量","type":"关系建立","judge":"电功率该用 P=UI 逐状态算，还是用 ΔU·ΔI 直接算","why":"功率是状态量，P=UI 对每个状态成立，但功率之差一般不等于电压变化量与电流变化量之积，必须分别算出两状态功率再作差","do":"分别算 P_a=U_aI_a 和 P_b=U_bI_b，再作差取绝对值","expr":"\\Delta P=|U_bI_b-U_aI_a|","cues":["先算两个功率","不能电压差乘电流差","再作差"],"concepts":["电功率","状态量"]}],"43":[{"title":"确定磁场与运动平面","type":"模型选择","judge":"小球在竖直平面内摆动时，磁场方向与速度方向是什么空间关系，洛伦兹力落在哪个平面内","why":"磁场竖直向下，速度沿水平方向的分量始终与磁场垂直，因此洛伦兹力始终水平、垂直于速度，只改变小球在水平面内投影轨迹的弯曲方向，不改变摆动的高度规律","do":"把速度分解为水平分量和竖直分量，判断只有水平分量与磁场作用产生水平方向的洛伦兹力","expr":"","cues":["磁场竖直向下","速度在水平面内","力只改变水平方向"],"concepts":["洛伦兹力","速度分解","左手定则"]},{"title":"判断初始偏转方向","type":"关系建立","judge":"小球从静止释放后最初一段运动，洛伦兹力指向俯视图的哪一侧","why":"初始速度方向由释放点指向平衡位置，正电荷用左手定则（四指指速度、磁感线穿掌心）可定出洛伦兹力方向，这决定轨迹一开始向哪边弯","do":"取释放瞬间的速度方向，用左手定则定出洛伦兹力方向，再对应到俯视图中的偏转侧","expr":"","cues":["正电荷用左手","四指指速度","看初始那一段"],"concepts":["左手定则","洛伦兹力方向"]},{"title":"判断返回段偏转方向","type":"关系建立","judge":"小球到达最高点返回时速度反向，洛伦兹力是否随之反向，轨迹向哪一侧弯","why":"洛伦兹力方向由速度方向决定，速度反向则洛伦兹力反向，但力始终指向轨迹凹侧，所以两段弧的弯曲方向在俯视图中相反","do":"取返回段速度方向重新用左手定则定洛伦兹力，比较两段轨迹的凹侧","expr":"","cues":["速度反向了","力也跟着反向","两段弯的方向相反"],"concepts":["洛伦兹力方向","轨迹凹侧"]},{"title":"排除对称与直线轨迹","type":"结论整理","judge":"轨迹在俯视图中是否关于初始连线对称、是否可能是一条直线或始终向同一侧弯","why":"洛伦兹力方向随速度反向而反向，轨迹不可能始终向同一侧弯曲，也不会是直线；若误认为力方向不变就会选到单向弯曲或对称的图形","do":"把各选项图形与两段弯曲方向相反的结论对照，剔除单向弯曲、直线和对称的图形","expr":"","cues":["不会一直朝一边弯","不是直线","两段弯向相反"],"concepts":["轨迹弯曲方向","对称性"]}],"44":[{"title":"读图取拉力做功","type":"图像读取","judge":"F-x 图线与 x 轴所围面积表示拉力做的功，需判断各段面积如何取（正负、梯形还是矩形）","why":"功的定义 W=∫F dx，F-x 图线下面积即功，这是求各段功的唯一途径","do":"在 F-x 图上分别读出 OA、AB、BC 三段图线下的面积，得到 W1、W2、W3","expr":"W=\\int F\\,dx","cues":["看面积","图线下方面积","分段求功"],"concepts":["功的定义","F-x 图像"]},{"title":"分段用动能定理","type":"关系建立","judge":"每段是否把拉力功、摩擦力功与动能变化三者联立，而不是只靠牛顿定律逐段积分","why":"力随位置变化，加速度不恒定，用动能定理可绕开变加速过程的运动学细节","do":"对 OA、AB、BC 各段列 W_i - μmg·Δx_i = ΔEk，解出各点速度","expr":"W_i-\\mu mg\\Delta x_i=\\tfrac12 mv_i^2-\\tfrac12 mv_{i-1}^2","cues":["用动能定理","别用运动学公式","力是变的"],"concepts":["动能定理","摩擦力做功"]},{"title":"瞬时功率取力与速度","type":"关系建立","judge":"某点瞬时功率要用该点拉力与速度的点积，而不是平均功率或合力功率","why":"P=Fv cosθ 中 F 必须是该位置的拉力，v 是该位置瞬时速度","do":"读出 A、B 两点的拉力值，配上刚求出的 v_A、v_B，算 P_A、P_B 并比较","expr":"P=Fv\\cos\\theta","cues":["瞬时功率","力乘速度","用该点拉力"],"concepts":["瞬时功率"]},{"title":"平均功率比时间","type":"关系建立","judge":"平均功率要用该段功除以该段所用时间，不能直接用平均速度乘平均力","why":"P̄=W/t，各段功不同、时间也不同，必须分别求时间再比","do":"由各段位移和速度变化估算或比较各段时间 t1、t2、t3，再用 W_i/t_i 比较","expr":"\\bar P=\\frac{W}{t}","cues":["功除以时间","先比时间","分段算"],"concepts":["平均功率"]},{"title":"判加速度增减定时间","type":"临界条件","judge":"判断每段是加速还是减速、加速度是增大还是减小，从而比较各段所用时间的长短","why":"F 与 μmg 的大小关系决定加速/减速，F 随 x 增大决定加速度单调变化，进而决定平均速度与时间","do":"比较各段 F 与 μmg：OA 段 F<μmg 减速、AB 段 F>μmg 加速，结合加速度变化比较 t1、t2、t3","expr":"a=\\frac{F-\\mu mg}{m}","cues":["先看加速减速","比加速度","时间谁长"],"concepts":["牛顿第二定律","变加速运动"]}],"45":[{"title":"识别图像类型与坐标","type":"图像读取","judge":"要判断这是 p-V 图还是 V-T 图，横纵坐标各代表什么","why":"不同图像的斜率、面积含义完全不同，p-V 图的面积才是功，V-T 图过原点的直线才是等压","do":"看坐标轴标注，确认纵轴压强、横轴体积，再读各段图线形状","expr":"","cues":["先看坐标轴","是压强体积图","面积代表功"],"concepts":["p-V 图像","状态参量"]},{"title":"等压段用体积判温度","type":"关系建立","judge":"要判断等压过程中体积变化方向对应温度升高还是降低","why":"理想气体状态方程 pV=nRT，p 不变时 V 与 T 成正比","do":"对等压段比较初末体积，体积大的一侧温度高、内能大","expr":"\\frac{V}{T}=\\text{常量}\\ (p\\text{不变})","cues":["等压看体积","体积大温度高","内能跟着温度走"],"concepts":["理想气体状态方程","等压变化","内能"]},{"title":"非等压段用 pV 乘积比温度","type":"关系建立","judge":"要判断两状态温度高低时，能否直接由 pV 乘积大小比较","why":"由 pV=nRT，温度正比于 pV 乘积，与路径无关，只需比较两状态坐标乘积","do":"读出 b、c 两状态的 p 与 V，分别算 pV 乘积再比较","expr":"T\\propto pV","cues":["算压强乘体积","乘积大温度高","不用管中间过程"],"concepts":["理想气体状态方程","状态量"]},{"title":"面积求功并区分正负","type":"几何关系","judge":"要判断 p-V 图线下面积表示功，且膨胀取正、压缩取负","why":"功 W=∫p dV，图线下方面积即功的大小，体积增大时气体对外做正功","do":"分别算出两段图线下方面积，比较大小并判断正负","expr":"W=\\int p\\,dV","cues":["面积就是功","膨胀做正功","两段面积比一比"],"concepts":["功的图示","p-V 图面积"]},{"title":"等压膨胀用热一律判吸热","type":"关系建立","judge":"要判断等压膨胀时吸收的热量与对外做功的大小关系","why":"热力学第一定律 Q=ΔU+W，等压膨胀时温度升高使 ΔU>0，故 Q>W","do":"先由体积增大定 ΔU 符号，再用 Q=ΔU+W 比较 Q 与 W","expr":"Q=\\Delta U+W","cues":["温度升内能增","吸热大于做功","用热一律"],"concepts":["热力学第一定律","等压过程"]}],"46":[{"title":"分段切割判电动势","type":"模型选择","judge":"线框在不同位置时，是哪一条边在切割磁感线、切割边处在哪个磁场区","why":"只有处在磁场中且与边界平行的边才切割磁感线产生电动势，进入Ⅰ区、跨两区、出Ⅱ区时有效切割边和所在磁场都不同","do":"按线框位置分三段：进入Ⅰ区、从Ⅰ区到Ⅱ区、离开Ⅱ区，分别确定切割边及其所在磁场","expr":"E=BLv","cues":["看哪条边在切","分三段看","左右边都在切"],"concepts":["动生电动势","切割磁感线","有效长度"]},{"title":"两区反向磁场叠加","type":"关系建立","judge":"线框跨在Ⅰ、Ⅱ两区之间时，左右两边产生的电动势是相加还是相减","why":"两区磁感应强度方向相反，左右两边运动方向相同，由右手定则判出的电动势方向相同，回路总电动势为两边电动势之和","do":"对跨区情形分别用右手定则判左右边电动势方向，再沿回路求代数和","expr":"E=B_1Lv+B_2Lv","cues":["方向相反要相加","右手定则判方向","两边都切割"],"concepts":["右手定则","串联电动势","磁通量变化率"]},{"title":"电势差取路段判断","type":"关系建立","judge":"求两点间电势差时，是取整段回路电动势还是只取两点间那段导体的电动势","why":"电势差等于从一点到另一点沿导体路径的电动势与电流压降的代数和，不能把整个回路的电动势直接当作两点间电势差","do":"沿两点间那段导体写 U=E_段-IR_段，比较该段电动势与整框电动势的占比","expr":"U_{ab}=E_{ab}-IR_{ab}","cues":["不能拿总电动势","看两点间那段","要减内阻压降"],"concepts":["电势差","闭合电路欧姆定律","路端电压"]},{"title":"安培力冲量求速度","type":"数学处理","judge":"求线框经过一段磁场后的速度变化，用牛顿第二定律逐时刻积分还是用安培力冲量","why":"安培力随速度变化，加速度不恒定，但安培力冲量可写成 ΣBILΔt=qBL，与位移挂钩，适合用动量定理整体求速度变化","do":"对每段穿越过程写动量定理，把安培力冲量化为电量与磁场的乘积，逐段累加求速度变化量","expr":"mΔv=-ΣBILΔt=-qBL","cues":["加速度在变","用动量定理","冲量换成电量"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"弹性碰撞定往返次数","type":"临界条件","judge":"线框与挡板弹性碰撞后速度反向大小不变，据此判断线框还能完整穿越磁场几次、最终停在何处","why":"每次完整穿过两区速度减少固定量，弹性碰撞只改变速度方向不改变大小，需用总速度变化量与初速度比较确定穿越次数和停止位置","do":"算出单次完整穿越的速度减少量，用初速度除以该量得穿越次数，再由次数奇偶判断停止时线框所处区域","expr":"n=\\frac{v_0}{\\Delta v}","cues":["碰撞只反向","每次减一样多","看奇偶定位置"],"concepts":["弹性碰撞","速度变化量","能量损耗"]}],"47":[{"title":"标记点用途的区分","type":"前提判断","judge":"判断所标记的各点分别用来确定哪条光线，哪些点可以任意选、哪些点必须由实际光路确定","why":"折射率由入射光线与折射光线的方向决定，只有真实光路上的点才能定出光线方向；玻璃砖内部的光路无法直接标记","do":"把入射光线上的点与出射光线上的点分开，确认出射点必须取光从玻璃砖射出的实际位置，入射光线上的点可任取","expr":"","cues":["入射光线上任取","出射点不能乱标","玻璃砖里标不了"],"concepts":["光的折射","光路确定"]},{"title":"用垂线构造正弦","type":"几何关系","judge":"判断如何把入射角和折射角的正弦转化为可直接测量的线段长度之比","why":"正弦等于对边比斜边，作垂线后两角的正弦都化为同一半径圆弧上的线段与半径之比，避免量角","do":"过入射点作界面的垂线，把入射光线、折射光线与垂线的交点投影到以入射点为圆心的圆弧上，写出两角正弦的线段表达式","expr":"$\\sin i=\\frac{d_1}{R},\\ \\sin r=\\frac{d_2}{R}$","cues":["作垂线","用圆弧半径","量线段代替量角"],"concepts":["折射定律","正弦的几何表示"]},{"title":"圆弧半径可任取","type":"近似条件","judge":"判断作圆弧时半径长度是否需要与玻璃砖厚度或入射角满足特定关系","why":"折射率表达式中半径在分子分母同时出现而约去，半径只影响作图方便，不影响结果","do":"确认半径取任意值都能使两正弦之比不变，据此排除对半径取值有限制的说法","expr":"$n=\\frac{\\sin i}{\\sin r}=\\frac{d_1}{d_2}$","cues":["半径随便取","半径会约掉","只影响画图"],"concepts":["折射率","比值不变"]},{"title":"测距仪按真空光速计时","type":"模型选择","judge":"判断测距仪示数反映的是光在介质中的实际传播时间还是按真空中光速折算的时间","why":"测距仪内部固定用真空光速乘以往返时间的一半来换算距离，并不知道光在玻璃或水中速度变慢","do":"写出示数与往返时间的关系，明确式中速度取真空光速而非介质中的光速","expr":"$s=\\frac{c\\,t}{2}$","cues":["仪器默认真空光速","往返算一半","不管介质里变慢"],"concepts":["光速","测距原理"]},{"title":"示数比与折射率挂钩","type":"关系建立","judge":"判断两个位置示数之比为何能反映折射率，需要把实际厚度、介质中光速与示数三者联系起来","why":"同一厚度下光在介质中的传播时间比真空中长，示数被放大，放大倍数由折射率决定","do":"设实际厚度，用介质中光速写出往返时间，再代入示数公式，把示数比化为折射率与几何因子的组合","expr":"$n=\\frac{c}{v},\\ s=\\frac{c}{2}\\cdot\\frac{2h}{v}=\\frac{c}{v}h$","cues":["示数被放大","放大倍数看折射率","先设实际厚度"],"concepts":["折射率与光速","光速与介质"]}],"48":[{"title":"小球下摆用机械能守恒","type":"模型选择","judge":"小球从静止摆到最低点的过程中，绳张力不做功，是否可用机械能守恒求最低点速度","why":"只有重力做功、绳张力始终垂直于速度，机械能守恒成立；这是求碰前速度的唯一途径","do":"对小球从释放位置到最低点列机械能守恒，解出碰前速度","expr":"m_C g L(1-\\cos\\theta)=\\tfrac12 m_C v_0^2","cues":["绳拉力不做功","只有重力做功","用机械能守恒"],"concepts":["机械能守恒","重力势能"]},{"title":"弹性碰撞双守恒","type":"关系建立","judge":"小球与木板碰撞时间极短且为弹性碰撞，应同时用动量守恒和动能守恒，而不是只用一个","why":"碰撞极短说明水平方向外力冲量可忽略，动量守恒；题明说弹性碰撞，动能守恒，两式才能解出碰后两个速度","do":"以小球和木板为系统列动量守恒式，再列碰撞前后动能相等式，联立解出木板速度","expr":"m_C v_0=m_C v_C'+m_A v_A',\\quad \\tfrac12 m_C v_0^2=\\tfrac12 m_C v_C'^2+\\tfrac12 m_A v_A'^2","cues":["弹性碰撞动能不变","两个方程解两个速度","碰后小球可能反弹"],"concepts":["动量守恒","弹性碰撞","动能守恒"]},{"title":"碰后系统动量守恒","type":"前提判断","judge":"碰后木板、弹簧、物块组成的系统在水平方向是否动量守恒（地面光滑、无水平外力）","why":"水平面光滑，弹簧力是系统内力，故碰后到弹簧压缩量第一次为给定值时系统水平动量守恒，这是求物块速度的关键","do":"以木板和物块为系统，取碰后瞬间到弹簧压缩量第一次为给定值的状态，列水平方向动量守恒","expr":"m_A v_A'=m_A v_A''+m_B v_B","cues":["地面光滑","弹簧力是内力","取木板和物块整体"],"concepts":["动量守恒","内力与外力"]},{"title":"正方向与速度符号","type":"数学处理","judge":"物块速度方向向左，与木板碰后速度方向相反，代入动量式时须带负号","why":"动量是矢量，方向相反必须用正负号区分，否则动量守恒式写错导致速度解错","do":"规定向左为正（或统一规定某方向为正），把木板、物块的速度按方向代入带符号运算","expr":"m_A v_A'=m_A v_A''-m_B v_B","cues":["向左为正","物块速度取负","方向相反要带符号"],"concepts":["动量矢量性","正方向规定"]},{"title":"弹性势能不变消去","type":"临界条件","judge":"弹簧压缩量第一次为给定值时，与初始伸长量对应的形变量大小相同，弹性势能是否相等","why":"弹簧弹性势能只由形变量大小决定，压缩量与初始伸长量大小相同则势能相同，能量方程中该项可抵消，否则多一个未知量","do":"比较压缩量与初始伸长量的大小，判定两状态弹性势能相等，在能量守恒式中消去弹性势能项","expr":"E_p(\\Delta x_1)=E_p(\\Delta x_2)\\Rightarrow \\Delta E_p=0","cues":["形变量大小相同","弹性势能只看形变量","势能项抵消"],"concepts":["弹性势能","形变量"]},{"title":"摩擦生热用相对路程","type":"关系建立","judge":"能量守恒中摩擦生热应用摩擦力乘以物块与木板的相对位移，而不是各自对地位移","why":"滑动摩擦力做功转化为内能等于摩擦力乘相对路程，用对地位移会算错内能，这是求动摩擦因数的核心","do":"由两状态速度求系统动能减少量，等于摩擦生热，再除以摩擦力与相对位移表示式解出动摩擦因数","expr":"\\tfrac12 m_A v_A'^2-\\tfrac12 m_A v_A''^2-\\tfrac12 m_B v_B^2=\\mu m_B g\\,s_{\\text{相对}}","cues":["摩擦生热看相对位移","不是各自位移","动能减少等于内能"],"concepts":["功能关系","摩擦生热","相对位移"]}],"49":[{"title":"识别光路转折的成因","type":"模型选择","judge":"筷子水下部分发出的光到达眼睛前，在哪个界面上发生了传播方向的改变","why":"光从水中斜射入空气时，两种介质的光速不同，传播方向必然偏折，这是折射而非反射或直线传播","do":"画出从筷子水下点到眼睛的光路，标出水面处的入射点与法线，确认光线在水面处折向空气一侧","expr":"","cues":["光从水里出来","在水面拐弯","不是镜面反射"],"concepts":["光的折射","介质界面","光路"]},{"title":"区分折射与反射","type":"前提判断","judge":"看到筷子侧移，是光被水面反射回来造成的，还是光穿过水面折射造成的","why":"反射光只反映水面以上物体的像，而筷子水下部分的光必须穿过水面才能进入眼睛，故只能是折射","do":"比较反射定律与折射现象的成像来源，排除平面镜成像式的解释","expr":"","cues":["不是倒影","光穿过了水面","反射看不到水下部分"],"concepts":["光的反射","光的折射"]},{"title":"虚像位置偏移的判断","type":"关系建立","judge":"人眼沿折射光线的反向延长线看，所看到的像的位置相对筷子实际位置偏向哪一侧","why":"人眼习惯认为光沿直线传播，会把进入眼睛的折射光线反向延长，交点即为看到的虚像，该点比实际点更靠近水面且侧移","do":"把进入眼睛的折射光线反向延长到水中，与实际发光点比较位置，得出像偏高、偏侧","expr":"","cues":["眼睛认为光是直的","反向延长线","像比实际高"],"concepts":["虚像","反向延长线","视深"]}],"50":[{"title":"由振动方向定波向","type":"前提判断","judge":"已知某质点沿 y 轴正方向运动，要判断波的传播方向","why":"质点振动方向与波传播方向由波形图的斜率联系，用上下坡法或同侧法才能唯一确定传播方向","do":"在波形图上找到该质点所在位置，看该处波形的斜率，由质点速度方向反推波沿 x 轴哪一侧传播","expr":"","cues":["上下坡法","看波形斜率","质点向上走"],"concepts":["波的传播方向","质点振动方向","波形图"]},{"title":"第一次回平衡位置对应半周期","type":"关系建立","judge":"质点从平衡位置出发第一次回到平衡位置，这段过程对应周期的几分之几","why":"简谐运动从平衡位置出发需先到最大位移再返回，经历的是半个周期，而不是四分之一周期","do":"画出该质点的振动过程：平衡位置→波峰→平衡位置，数出对应的时间与周期的关系","expr":"t=\\frac{T}{2}","cues":["先到波峰再回来","半个周期","不是四分之一"],"concepts":["简谐运动周期","全振动"]},{"title":"读波长与振幅","type":"图像读取","judge":"从波形图横轴和纵轴分别读出波长和振幅","why":"波速公式和路程计算都要用到波长、振幅，必须直接从图上读取而不是凭周期推算","do":"量出相邻同相点间的横轴距离得波长，量出波峰到平衡位置的纵轴距离得振幅","expr":"","cues":["看相邻波峰","横轴一格多少","纵轴最大值"],"concepts":["波长","振幅","波形图"]},{"title":"波速由波长周期求","type":"关系建立","judge":"判断波速该用波长除以周期，而不是用质点路程除以时间","why":"波速是波形整体平移的速度，由介质和波长、周期决定，与质点振动速度无关","do":"用读出的波长和求得的周期代入波速公式计算","expr":"v=\\frac{\\lambda}{T}","cues":["波速不等于质点速度","波长除周期","别用路程除时间"],"concepts":["波速","波长","周期"]},{"title":"一个周期路程为四倍振幅","type":"结论整理","judge":"判断一段时间内质点路程是否等于四倍振幅，需先确认时间是否为整周期","why":"只有经历一个完整周期，质点路程才严格等于 4A；非整周期不能直接套用","do":"把给定时间与周期比较，确认是否为整周期后再决定能否用 4A","expr":"s=4A\\ (t=T)","cues":["整周期才用四倍振幅","先比时间和周期","不能乱套公式"],"concepts":["路程","振幅","周期"]},{"title":"加速度指向平衡位置","type":"临界条件","judge":"判断某时刻质点的加速度方向，需先确定该时刻质点相对平衡位置的位移方向","why":"简谐运动回复力与位移反向，加速度总指向平衡位置，与速度方向无关","do":"先由振动过程确定该时刻质点位于哪个最大位移处，再由位移方向反推加速度方向","expr":"a=-\\omega^{2}x","cues":["加速度指向平衡位置","看位移方向","与速度方向无关"],"concepts":["简谐运动加速度","回复力","位移"]}],"51":[{"title":"找速度最大位置","type":"临界条件","judge":"速度最大处对应合力为零（重力与弹力平衡），需判断该平衡点相对绳原长的位置","why":"加速度为零时速度取极值，弹力等于重力是加速转减速的分界","do":"设平衡点，令弹力等于重力，求出伸长量，与绳恰好伸直的位置比较","expr":"k\\Delta x = mg","cues":["合力为零处","重力等于弹力","先加速后减速"],"concepts":["牛顿第二定律","平衡位置","加速度与速度"]},{"title":"用简谐对称定最低点","type":"关系建立","judge":"把绳伸直后的运动看作简谐运动，判断最低点相对平衡点的位置","why":"弹性绳伸长后合力与位移成正比，满足简谐运动对称性，最低点与释放点关于平衡点对称","do":"以平衡点为对称中心，比较从绳伸直处释放与从更高处释放的最低点位置","expr":"","cues":["简谐运动对称性","最低点在平衡点下方","释放点有初速"],"concepts":["简谐运动","对称性","振幅"]},{"title":"比较两点加速度","type":"关系建立","judge":"判断绳刚伸直点与最低点的加速度大小关系","why":"两点加速度都由牛顿第二定律给出，需先确定最低点的伸长量再算弹力","do":"分别写出两点的合力，用牛顿第二定律求加速度并比较","expr":"a=\\frac{k\\Delta x - mg}{m}","cues":["刚伸直只受重力","最低点弹力最大","比加速度大小"],"concepts":["牛顿第二定律","弹性力","加速度"]},{"title":"判断超失重分段","type":"模型选择","judge":"判断下落过程中加速度方向如何变化，从而确定先失重还是先超重","why":"加速度向下为失重、向上为超重，加速度方向在平衡点处改变","do":"比较平衡点前后加速度方向，划分加速与减速阶段","expr":"","cues":["加速度向下失重","过平衡点后超重","先失重后超重"],"concepts":["失重","超重","加速度方向"]},{"title":"系统机械能守恒","type":"前提判断","judge":"判断人、地球、弹性绳组成的系统机械能是否守恒，并据此分析重力势能与弹性势能之和","why":"只有重力和弹力做功，系统机械能守恒，动能变化决定两势能之和的变化","do":"写出机械能守恒式，由动能先增后减推出两势能之和先减后增","expr":"E_k+E_p+E_{弹}=常量","cues":["只有重力和弹力做功","系统机械能守恒","动能先增后减"],"concepts":["机械能守恒","重力势能","弹性势能"]}],"52":[{"title":"光滑时能否停住","type":"前提判断","judge":"判断光滑曲面上小球能否最终静止在谷底","why":"机械能守恒，动能与势能相互转化，小球不会自发停在势能极小值处，而信息重现要求最终停在极小值点","do":"比较光滑情形下的运动与题设“直至停在某个山谷底部”的要求","expr":"","cues":["光滑会来回滚","停不下来","要有阻力"],"concepts":["机械能守恒","能量耗散"]},{"title":"沿势能减小方向演化","type":"模型选择","judge":"判断小球运动类比的是有阻力、沿势能持续减小的演化过程，而非无耗散的往复运动","why":"题设明确“始终沿着重力势能减小的方向运动，直至停在某个山谷底部”，对应神经网络状态向函数值降低方向演化","do":"把“势能单调减小直至停止”作为类比模型，排除光滑无阻尼模型","expr":"","cues":["取有阻力模型","势能一直降","类比演化过程"],"concepts":["势能","阻尼","类比法"]},{"title":"吸引域划分初态","type":"临界条件","judge":"判断两个微小差别的初始位置是否可能落入不同山谷的势力范围","why":"谷底有各自的吸引域，初始位置只要分属不同吸引域，微小差别也会导致不同终态","do":"比较两个初始位置相对分界（山脊）的位置，判断是否属于同一吸引域","expr":"","cues":["看落在哪个谷","分界在山脊","微小差别也可能分开"],"concepts":["吸引域","极小值","初态敏感性"]},{"title":"势能相等不等于同谷","type":"关系建立","judge":"判断函数值（势能）相等是否意味着最终到达同一极小值","why":"势能相等只约束初始高度，不约束初始位置所在的吸引域，等势位置可分属不同山谷","do":"比较两个等势初始点所在吸引域是否相同","expr":"","cues":["等高不代表同谷","看位置不看高度","势能相等不够"],"concepts":["等势面","吸引域","极小值"]},{"title":"谷底与记忆一一对应","type":"结论整理","judge":"判断谷底消失后原记忆是否还能重现","why":"每个极小值对应一个存储信息，极小值不存在则对应状态无法被重现","do":"检查该谷底对应的极小值是否仍存在","expr":"","cues":["谷底就是记忆","没了就重现不了","一一对应"],"concepts":["极小值","联想记忆"]}],"53":[{"title":"桶砂质量远小于小车","type":"近似条件","judge":"要判断桶和砂的总质量 m 与小车的质量 M 之间必须满足什么数量关系，才能把桶砂重力当作小车所受合力","why":"对整体有 a=mg/(M+m)，绳中拉力 T=Mmg/(M+m)=mg/(1+m/M)，只有 m≪M 时 T 才近似等于 mg","do":"对小车和桶砂整体列牛顿第二定律求加速度，再隔离小车写出实际拉力表达式，令 m/M 趋于零取近似","expr":"T=\\frac{Mmg}{M+m}=\\frac{mg}{1+m/M}\\approx mg\\ (m\\ll M)","cues":["取整体","隔离小车","远小于"],"concepts":["整体法","隔离法","牛顿第二定律"]},{"title":"平衡阻力后合力判断","type":"前提判断","judge":"要判断平衡阻力之后小车沿板方向所受的合力是否只剩绳的拉力","why":"只有重力沿斜面的分力与摩擦力已相互抵消，绳的拉力才等于小车所受合力，否则拉力不等于合力，近似链条断裂","do":"检查实验步骤中是否已垫高木板补偿摩擦，确认合力来源唯一","expr":"","cues":["先平衡阻力","合力就是拉力"],"concepts":["平衡摩擦力","合力"]},{"title":"打点计时器先通电","type":"实验操作","judge":"要判断使用打点计时器时，是先接通电源还是先释放小车","why":"打点稳定需要时间，先放小车会丢掉起始的密集点，纸带利用不充分甚至无法取点","do":"比较各选项的操作顺序，确认先接通电源待打点稳定再释放","expr":"","cues":["先通电","打点稳定再放"],"concepts":["打点计时器","实验操作规范"]},{"title":"等温变化不能快拉","type":"前提判断","judge":"要判断探究气体等温变化时快速拉动柱塞是否满足温度不变的前提","why":"等温变化的前提是气体温度始终等于环境温度，快速压缩或膨胀来不及与外界交换热量，温度会变","do":"分析快速拉动时气体状态变化的时间尺度与热交换的关系，判断是否偏离等温条件","expr":"pV=C\\ (T\\ \\text{不变})","cues":["要等温","快拉会变温"],"concepts":["等温变化","玻意耳定律"]},{"title":"大头针间距取大","type":"误差分析","judge":"要判断测玻璃折射率时两枚大头针的间距应取大还是取小","why":"间距越大，确定入射光线和出射光线方向时由针位偏差引起的角度误差越小","do":"比较间距大小对光线方向确定精度的影响，判断应适当增大间距","expr":"","cues":["间距大些","方向更准"],"concepts":["折射率测量","角度误差"]}],"54":[{"title":"判断感应电流方向","type":"前提判断","judge":"导体棒向右切割竖直向下的磁感线时，棒中感应电流沿哪个方向","why":"动生电动势方向由右手定则（或楞次定律）决定，方向错了后续安培力方向、加速度方向全错","do":"伸右手，让磁感线穿入掌心，拇指指向棒的运动方向，四指所指即棒中电流方向","expr":"","cues":["右手定则","磁感线穿掌心","拇指指运动方向"],"concepts":["右手定则","动生电动势","楞次定律"]},{"title":"选切割长度与电动势","type":"模型选择","judge":"导体棒切割磁感线的有效长度取导轨间距还是棒长，电动势用哪个公式","why":"只有处在导轨间、构成闭合回路的那段棒才产生有效电动势，导轨宽即有效切割长度","do":"确认棒与导轨垂直、接触点在导轨上，取导轨宽度为有效长度，写动生电动势公式","expr":"E=BLv_0","cues":["有效长度是导轨宽","棒与导轨垂直","用动生电动势公式"],"concepts":["动生电动势","有效切割长度","闭合回路"]},{"title":"选研究对象求安培力","type":"模型选择","judge":"求加速度时以导体棒为对象、用安培力公式还是把回路整体当对象","why":"棒是唯一有质量的运动部件，加速度由棒所受合力决定，安培力作用在棒上","do":"对棒单独受力分析，写安培力大小并确定其方向与运动方向相反","expr":"F=BIL=B^2L^2v_0/R","cues":["只研究导体棒","安培力阻碍运动","合力只有安培力"],"concepts":["安培力","牛顿第二定律","受力分析"]},{"title":"判断是否需变力分析","type":"模型选择","judge":"速度减小过程中安培力随速度变化，求热量能否用牛顿定律逐段积分，还是改用能量观点","why":"安培力随速度减小而减小，是变力，无法用匀变速公式；但只有安培力做功，机械能全部转化为电阻热量","do":"放弃运动学公式，对全过程用能量守恒，把初动能全部记为电阻产生的热量","expr":"Q=\\frac12 mv_0^2","cues":["安培力是变力","不能用匀变速公式","用能量守恒"],"concepts":["变力做功","能量守恒","焦耳热"]},{"title":"确认热量全部归于电阻","type":"近似条件","judge":"题目不计棒和导轨电阻时，产生的总热量是否全部算在电阻上","why":"焦耳热按回路各电阻分配，棒与导轨电阻为零，故总热量全部由电阻承担","do":"核对题设“不计导体棒和导轨的电阻”，把总焦耳热直接等同于电阻发热","expr":"Q_R=Q=\\frac12 mv_0^2","cues":["棒和导轨无电阻","热量全给电阻","总热量等于初动能"],"concepts":["焦耳定律","电阻分配","能量转化"]}],"55":[{"title":"最低点速度的求法","type":"模型选择","judge":"从释放到最低点该用机械能守恒还是牛顿第二定律直接求速度","why":"绳的拉力是变力且不做功，只有重力做功，机械能守恒成立；牛顿第二定律在最低点只能联系速度与拉力，不能单独给出速度","do":"取最低点为零势能面，写出释放点与最低点的机械能相等方程，解出最低点速度","expr":"mgL(1-\\cos\\theta)=\\frac{1}{2}mv^2","cues":["只有重力做功","用机械能守恒","拉力不做功"],"concepts":["机械能守恒","变力不做功"]},{"title":"最低点拉力用向心力","type":"关系建立","judge":"最低点绳的拉力与重力如何合成提供向心力","why":"最低点速度水平、加速度竖直指向悬点，合外力沿绳方向，牛顿第二定律的向心形式适用","do":"沿绳方向列牛顿第二定律，把已求出的速度代入解拉力","expr":"T-mg=m\\frac{v^2}{L}","cues":["指向圆心","合力提供向心力","沿绳方向"],"concepts":["向心力","牛顿第二定律"]},{"title":"小角度简谐近似","type":"近似条件","judge":"夹角较小时单摆周期公式是否可用","why":"只有摆角很小时回复力才近似与位移成正比，运动才近似为简谐运动，周期才与振幅无关","do":"确认小角度条件成立，直接引用单摆周期公式，不重新推导","expr":"T_0=2\\pi\\sqrt{\\frac{L}{g}}","cues":["摆角很小","近似简谐","周期与振幅无关"],"concepts":["单摆","简谐运动"]},{"title":"一周期拉力冲量用动量定理","type":"模型选择","judge":"求变力拉力在一整周期内的冲量，是逐点积分还是对整周期用动量定理","why":"拉力大小方向都随时间变化，无法直接积分；但一个周期后小球回到原状态，动量变化为零，可把重力冲量与拉力冲量一起考虑","do":"对一个完整周期列动量定理，注意重力冲量不为零，由动量变化为零解出拉力冲量大小","expr":"I_T-mgT_0=0","cues":["一个周期动量不变","重力冲量不能漏","用动量定理"],"concepts":["动量定理","冲量","周期性"]},{"title":"圆锥摆的向心力来源","type":"关系建立","judge":"水平面内匀速圆周运动时，向心力由拉力与重力的哪个分量提供","why":"小球在水平面内做匀速圆周运动，竖直方向无加速度，合力水平指向圆心，只能由绳拉力的水平分量提供","do":"竖直方向列平衡方程，水平方向列向心力方程，圆周半径用绳长与夹角表示","expr":"T\\cos\\theta=mg,\\quad T\\sin\\theta=m\\frac{4\\pi^2}{T^2}L\\sin\\theta","cues":["竖直方向平衡","合力水平","半径是水平投影"],"concepts":["圆锥摆","向心力","受力分解"]},{"title":"两周期大小比较","type":"结论整理","judge":"圆锥摆周期与单摆周期谁大，取决于哪个三角函数的单调性","why":"两周期表达式只差一个与夹角有关的因子，夹角在零到九十度之间时该因子的单调性决定大小关系","do":"把两周期表达式相除，利用夹角范围判断比值大于还是小于一","expr":"\\frac{T_{\\text{锥}}}{T_0}=\\frac{1}{\\sqrt{\\cos\\theta}}>1","cues":["两式相除","余弦小于一","圆锥摆周期更长"],"concepts":["周期比较","三角函数单调性"]}],"56":[{"title":"加速过程选动能定理","type":"模型选择","judge":"离子在加速电场中由静止到进入磁场，应选什么规律联系电压与速度","why":"电场力做功等于动能增量，题设离子由静止加速，初动能为零","do":"对母离子（及子离子）写加速过程的功能关系，把电压与出射速度联系起来","expr":"qU=\\frac{1}{2}mv^{2}","cues":["用动能定理","从静止加速","电压变速度"],"concepts":["动能定理","加速电场"]},{"title":"磁场中洛伦兹力提供向心力","type":"关系建立","judge":"离子垂直进入匀强磁场后做匀速圆周运动，向心力由谁提供","why":"磁场只改变速度方向，洛伦兹力始终垂直速度、指向圆心","do":"对母离子写向心力方程，把半径、速度、比荷、磁感应强度联系起来","expr":"qvB=m\\frac{v^{2}}{R}","cues":["洛伦兹力当向心力","垂直进入","半径由比荷定"],"concepts":["洛伦兹力","匀速圆周运动"]},{"title":"联立消去速度求电压","type":"数学处理","judge":"待求的是加速电压，速度是中间量，应消去哪个量","why":"两个方程中速度未知且不可测，需用半径和比荷表示电压","do":"由向心力方程解出速度代入动能定理式，整理成电压关于半径、比荷、磁场的表达式","expr":"U=\\frac{qB^{2}R^{2}}{2m}","cues":["消掉速度","用半径表示电压","比荷代进去"],"concepts":["联立方程","比荷"]},{"title":"判断半径是否随比荷变","type":"前提判断","judge":"仅加匀强磁场时，不同比荷子离子的轨道半径是否相同","why":"半径表达式中比荷出现在根号内，比荷不同则半径不同，而题目要求所有子离子走同一固定半径","do":"写出子离子在磁场中的半径表达式，指出它依赖比荷，与固定半径要求矛盾","expr":"r=\\frac{1}{B}\\sqrt{\\frac{2mU_{2}}{q}}","cues":["半径跟比荷有关","做不到同一半径","磁场不行"],"concepts":["轨道半径","比荷"]},{"title":"电场力充当向心力","type":"模型选择","judge":"仅加电场时，要让离子做固定半径的匀速圆周运动，电场力应满足什么条件","why":"匀速圆周运动需要大小恒定、方向始终指向圆心的合力，电场力必须独自提供向心力","do":"设半径 r0 处场强为 E，对任意子离子写电场力等于向心力的方程","expr":"qE=m\\frac{v'^{2}}{r_{0}}","cues":["电场力提供向心力","方向指向圆心","辐向电场"],"concepts":["向心力","电场力"]},{"title":"验证场强与比荷无关","type":"结论整理","judge":"解出的场强表达式中比荷是否被消去，从而同一电场能否适用于所有子离子","why":"只有场强与比荷无关，同一辐向电场才能让不同比荷离子都在同一半径上做圆周运动","do":"把加速得到的动能关系代入向心力方程，消去比荷，得到只由电压和半径决定的场强","expr":"E=\\frac{2U_{2}}{r_{0}}","cues":["比荷约掉了","场强只由电压定","同一电场都适用"],"concepts":["辐向电场","比荷无关性"]}],"57":[{"title":"碰撞前后动能关系","type":"前提判断","judge":"动能损失64%是相对落地前动能而言，还是相对其他量而言","why":"题设明确损失的是与地面碰撞前的动能，损失比例以落地瞬间动能为基准","do":"写出反弹瞬间动能与落地前动能的比例关系","expr":"E_k'=(1-64\\%)E_k=0.36E_k","cues":["损失的是落地前的动能","剩百分之三十六"],"concepts":["动能","百分比损失"]},{"title":"分段用机械能守恒","type":"模型选择","judge":"下落段和上升段各自是否只有重力做功、可分别用机械能守恒","why":"忽略空气阻力，碰撞以外的运动过程只有重力做功，机械能守恒","do":"对下落段和上升段分别列高度与动能的对应关系","expr":"E_k=mgh,\\quad E_k'=mgh'","cues":["下落上升分开看","只有重力做功"],"concepts":["机械能守恒","重力势能"]},{"title":"高度比等于动能比","type":"关系建立","judge":"上升最大高度与反弹瞬间动能之间的比例关系","why":"同一皮球质量不变，机械能守恒给出动能与高度成正比","do":"把两段守恒式相除，消去质量和重力加速度","expr":"\\frac{h'}{h}=\\frac{E_k'}{E_k}=0.36","cues":["高度跟动能成正比","质量约掉"],"concepts":["正比关系","机械能守恒"]}],"58":[{"title":"衰变释放能量判质量","type":"前提判断","judge":"要判断自由中子衰变是放能过程还是吸能过程，从而确定反应前后质量的大小关系","why":"自由中子衰变能自发进行，说明反应后总静质量小于反应前，存在质量亏损","do":"比较衰变前中子质量与衰变后质子、电子、反中微子质量之和","expr":"m_n > m_p + m_e + m_{\\bar\\nu}","cues":["自发衰变","放能","有质量亏损"],"concepts":["质量亏损","质能关系"]},{"title":"反中微子质量取零","type":"近似条件","judge":"要判断反中微子质量能否忽略，从而把它从质量比较中剔除","why":"题干明确给出反中微子质量近似为零，故质量亏损全部体现在中子和质子、电子之间","do":"在质量不等式中令反中微子质量为零，得到中子质量与质子加电子质量的大小关系","expr":"m_{\\bar\\nu}\\approx 0 \\Rightarrow m_n > m_p + m_e","cues":["质量近似为零","忽略反中微子","只看质子和电子"],"concepts":["质量亏损","近似处理"]},{"title":"电荷守恒定反中微子电荷","type":"关系建立","judge":"要判断反中微子的电荷量由什么规律确定，而不是凭直觉猜测","why":"衰变过程必须同时满足电荷数守恒，方程左右两侧总电荷数相等","do":"写出方程两侧电荷数：左侧中子电荷为零，右侧为质子电荷加电子电荷加反中微子电荷，令其相等","expr":"0 = (+1) + (-1) + q_{\\bar\\nu}","cues":["电荷数守恒","左右电荷相等","列电荷方程"],"concepts":["电荷守恒","衰变方程"]}],"59":[{"title":"内能由温度决定","type":"前提判断","judge":"判断理想气体内能是否只由温度决定，从而把比较内能转化为比较温度","why":"理想气体分子间无相互作用势能，内能只是温度的函数，温度相同则内能相同","do":"明确本题只需比较四个状态的温度，不必计算内能数值","expr":"U=U(T)","cues":["内能看温度","理想气体无势能"],"concepts":["理想气体内能","温度"]},{"title":"状态方程联系参量","type":"关系建立","judge":"判断用哪个方程把 p、V 与 T 联系起来，从而由图上坐标算出各状态温度","why":"理想气体状态方程 pV=nRT 给出 pV 乘积与温度成正比，是读图求温度的唯一桥梁","do":"对 a、b、c、d 各状态分别写出 pV 乘积，比较其大小","expr":"pV=nRT","cues":["用状态方程","算pV乘积"],"concepts":["理想气体状态方程"]},{"title":"读图取各状态坐标","type":"图像读取","judge":"判断图中横纵坐标各代表什么量，并读出 a、b、c、d 四点的坐标值","why":"p-V 图上点的坐标直接给出压强与体积，读错坐标或误把图当 V-T 图会使 pV 乘积全错","do":"从坐标轴标度和实线折点读出四个状态的 p、V 数值","expr":"","cues":["先看坐标轴","读四个点坐标"],"concepts":["p-V 图像","状态参量"]},{"title":"比较 pV 乘积定温度","type":"数学处理","judge":"判断哪两个状态的 pV 乘积相等，即温度相等","why":"pV 乘积相同则温度相同，内能相同；乘积不同则温度不同","do":"把四个状态的 pV 值两两比较，找出相等的一对","expr":"p_aV_a=p_dV_d","cues":["比pV大小","找乘积相等"],"concepts":["pV 乘积","温度比较"]}],"60":[{"title":"起振方向判定","type":"前提判断","judge":"波源在 t=0 时刻由平衡位置向哪个方向起振","why":"介质中每个质点的起振方向都与波源起振方向相同，这是判断波前质点振动方向的唯一依据","do":"读振动图像 t=0 时刻的斜率（位移变化趋势），确定起振方向沿 y 轴正方向","expr":"","cues":["看起振方向","t=0往哪走","所有质点起振同向"],"concepts":["起振方向","振动图像"]},{"title":"波前位置与相位","type":"关系建立","judge":"给定时刻波已传播多远、波前处质点处于什么振动状态","why":"波沿 x 轴正向匀速传播，传播距离由 Δt 与周期、波长的比例决定，波前质点刚开始振动","do":"由时刻与周期的关系算出传播距离（几个波长），确定波前坐标及该处质点位移与振动方向","expr":"Δx=vΔt=(λ/T)Δt","cues":["传了几个波长","波前在哪","波前刚开始振动"],"concepts":["波速","波长","波的传播"]},{"title":"波形与振动图对应","type":"几何关系","judge":"如何由波源一个周期的振动图像反推空间波形（哪个位置对应波峰、波谷）","why":"波是振动状态在空间的平移，波源振动图像的时间轴按 v 折算成空间轴，先振动的状态传得更远","do":"把振动图像按时间先后映射到沿传播方向由远到近的各点，标出波峰、波谷的空间位置","expr":"y(x,t)=y(0,t-x/v)","cues":["时间换成空间","先振动的在远处","图像平移"],"concepts":["波形图","振动与波动关系"]},{"title":"起伏顺序与幅值比较","type":"结论整理","judge":"波形是先向上还是先向下起伏，以及上、下起伏的极值大小关系","why":"波源振动图像中正、负方向的最大位移不同，波形上对应波峰与波谷的幅值也不等，需按图像读数比较","do":"沿 x 正向依次读出各段起伏方向，并比较波峰与波谷的位移绝对值","expr":"","cues":["先下后上","最高点比最低点高","看幅值大小"],"concepts":["振幅","波形图"]}],"61":[{"title":"出舱后运动状态","type":"模型选择","judge":"出舱后航天员是否仍随空间站一起绕地球做圆周运动","why":"题干明确说明可认为航天员出舱后与空间站一同绕地球做圆周运动，因此不能把出舱后的航天员当作脱离引力、静止或做其他运动的物体","do":"把出舱航天员与空间站视为同一轨道上做匀速圆周运动的物体","expr":"","cues":["跟着空间站转","同一轨道","匀速圆周"],"concepts":["匀速圆周运动","万有引力"]},{"title":"向心力来源","type":"关系建立","judge":"航天员做圆周运动的向心力由什么力提供","why":"航天员只受地球万有引力，没有其他接触力，故万有引力全部充当向心力","do":"对航天员列万有引力等于向心力的方程","expr":"G\\frac{Mm}{r^2}=m\\frac{v^2}{r}","cues":["万有引力提供","只有引力","引力当向心力"],"concepts":["万有引力","向心力"]},{"title":"加速度与重力加速度","type":"前提判断","judge":"航天员的加速度是否等于该处的重力加速度","why":"由牛顿第二定律，万有引力产生的加速度就是当地重力加速度，二者是同一个量","do":"比较万有引力加速度与重力加速度的表达式","expr":"a=\\frac{GM}{r^2}=g'","cues":["加速度就是重力加速度","同一个东西","由引力决定"],"concepts":["重力加速度","牛顿第二定律"]},{"title":"完全失重判据","type":"临界条件","judge":"航天员对舱内支持物是否有压力，从而判断是否处于完全失重","why":"完全失重的本质是重力全部用于提供向心力，视重为零，与在舱内还是舱外无关","do":"检查航天员与舱壁或座椅之间是否存在支持力，若没有则视重为零","expr":"N=0","cues":["视重为零","没有压力","完全失重"],"concepts":["完全失重","视重"]}],"62":[{"title":"进入电场瞬间速度方向","type":"前提判断","judge":"小球刚进入两板间时速度沿什么方向","why":"小球进入电场前只受重力、由静止下落，速度方向竖直向下；进入瞬间水平分速度为零，这是判断轨迹在边界处切线方向的依据","do":"取进入点为轨迹起点，确认该点速度竖直向下，轨迹在边界处切线竖直","expr":"","cues":["先自由下落","竖直进入","水平初速为零"],"concepts":["自由落体","速度方向","轨迹切线"]},{"title":"电场内受力是否恒定","type":"模型选择","judge":"进入电场后小球受的是恒力还是变力，能否用匀变速分解处理","why":"忽略边缘效应时板间为匀强电场，电场力大小方向恒定，与重力合成后仍为恒力，才能把运动分解为两个方向的匀变速直线运动","do":"把重力与电场力合成，确认合外力恒定，从而按分方向匀变速处理","expr":"","cues":["匀强电场","电场力恒定","合外力不变"],"concepts":["匀强电场","电场力","运动的合成与分解"]},{"title":"竖直与水平分运动性质","type":"关系建立","judge":"竖直方向和水平方向各自是匀速还是加速，水平速度如何从零变化","why":"竖直方向有向下的初速度和重力加速度，竖直分速度不断增大；水平方向初速为零、受恒定电场力，做初速为零的匀加速运动，水平分速度从零逐渐增大","do":"分别写出竖直、水平方向的速度表达式，比较两方向速度随时间的变化趋势","expr":"$v_y=v_0+gt,\\quad v_x=\\frac{qE}{m}t$","cues":["竖直越来越快","水平从零开始","两个方向都加速"],"concepts":["匀变速直线运动","分速度","加速度"]},{"title":"轨迹弯曲方向与切线","type":"几何关系","judge":"轨迹向哪一侧弯曲，边界处切线是否竖直","why":"合外力（电场力）水平，曲线凹向合力一侧即电场力方向；进入点水平分速度为零，切线必须竖直向下，轨迹在边界处光滑不折转","do":"看轨迹在进入点是否竖直切入，再看曲线向电场力一侧弯曲","expr":"","cues":["切线竖直","向电场力方向弯","不能折角"],"concepts":["曲线运动条件","轨迹切线","凹向合力"]},{"title":"电场力方向不确定","type":"结论整理","judge":"电场力水平向左还是向右能否确定","why":"题目未给出两板电性及小球电性，电场力方向有两种可能，因此向左右两侧偏转的轨迹都可能正确，只认一种偏向的图被排除","do":"对每种候选图检查其偏转方向是否对应某一种可能的电场力方向","expr":"","cues":["电性未知","左右都可能","不能只认一边"],"concepts":["电场力方向","电性"]}],"63":[{"title":"两球同时释放的机制","type":"模型选择","judge":"判断球A自由下落与球B平抛是否由同一次击打同时触发，从而保证两球运动时间从同一时刻起算","why":"实验要比较竖直方向运动，必须让两球同时开始运动，否则落地时间差不能归因于竖直分运动差异","do":"观察弹性金属片P被击打时，A失去支撑自由下落、B被P弹出，确认二者由同一动作同时启动","expr":"","cues":["同时释放","同一时刻开始","击打瞬间"],"concepts":["平抛运动","自由落体运动","同时性"]},{"title":"击打力度与初速度","type":"关系建立","judge":"判断击打力度改变时，金属片弹性形变储存的弹性势能如何转化为球B的动能，从而判断水平初速度的变化","why":"弹性金属片的形变程度由击打力度决定，弹性势能越大，转化为B的动能越多","do":"比较不同击打力度下金属片的形变量，由能量转化关系推出B的抛出速度变化","expr":"E_p=\\frac{1}{2}mv_0^2","cues":["形变越大","弹性势能转化","速度变大"],"concepts":["弹性势能","动能","能量转化"]},{"title":"控制变量比较竖直运动","type":"前提判断","judge":"判断改变击打力度或改变装置高度时，哪些量在变、哪些量保持不变，从而确认两球始终满足竖直方向运动可比的条件","why":"探究竖直分运动规律需排除水平初速度与下落高度的干扰，只比较竖直方向运动本身","do":"分别只改变击打力度、只改变装置高度，观察两球是否仍同时落地","expr":"h=\\frac{1}{2}gt^2","cues":["只改一个量","高度相同","同时落地"],"concepts":["控制变量法","平抛运动","自由落体"]},{"title":"由同时落地得结论","type":"结论整理","judge":"判断多次不同初速度、不同高度下两球均同时落地，能否说明平抛竖直分运动与自由落体运动一致","why":"若竖直分运动与自由落体不同，落地时间应随初速度或高度出现差异；始终同时落地说明竖直方向运动规律相同","do":"汇总各组实验结果，比较两球落地时间是否始终相等，归纳竖直分运动规律","expr":"","cues":["始终同时落地","竖直方向相同","规律一致"],"concepts":["平抛运动","自由落体运动","运动的独立性"]},{"title":"斜抛方向影响落地时间","type":"临界条件","judge":"判断球B抛出方向偏离水平时，竖直分初速度的方向如何改变总运动时间，从而解释A比B早落地的现象","why":"竖直方向总位移固定，竖直分初速度向上会延长运动时间，向下会缩短运动时间","do":"分别分析斜向上、斜向下抛出时竖直分初速度对下落时间的影响，与自由落体的A比较","expr":"h=v_{y0}t+\\frac{1}{2}gt^2","cues":["斜向上先上升","斜向下更快","时间变长变短"],"concepts":["运动的分解","竖直分运动","运动时间"]}],"64":[{"title":"平抛分方向处理","type":"模型选择","judge":"石块离手后做什么运动，能否把运动拆成水平匀速和竖直自由落体两个独立分运动","why":"只受重力、初速度水平，是平抛运动；两个分运动互不影响，才能分别用匀速和自由落体公式","do":"把运动分解为水平方向和竖直方向，分别列方程","expr":"","cues":["平抛","分方向看","水平匀速竖直自由落体"],"concepts":["平抛运动","运动的分解"]},{"title":"竖直方向定高度","type":"关系建立","judge":"求抛出点高度该用哪个分运动的哪个量，竖直位移与下落时间的关系是什么","why":"高度只由竖直分运动决定，竖直初速度为零，位移与时间满足自由落体位移公式","do":"用竖直方向位移公式，代入下落时间求高度","expr":"h=\\frac{1}{2}gt^{2}","cues":["高度看竖直","竖直初速为零","用下落时间"],"concepts":["自由落体","位移公式"]},{"title":"水平位移独立求","type":"关系建立","judge":"水平位移由哪个量决定，是否受竖直下落影响","why":"水平方向不受力做匀速直线运动，水平位移只与初速度和飞行时间有关","do":"用水平匀速公式，代入初速度和下落时间求水平位移","expr":"x=v_{0}t","cues":["水平匀速","水平位移","用初速度乘时间"],"concepts":["匀速直线运动","水平分运动"]},{"title":"两点距离用勾股","type":"几何关系","judge":"落水点与抛出点的距离是水平位移还是斜边，该用哪个几何关系合成","why":"抛出点与落水点的连线是水平位移和竖直位移构成的直角三角形的斜边","do":"对水平位移和竖直高度用勾股定理求斜边","expr":"s=\\sqrt{x^{2}+h^{2}}","cues":["斜边","勾股定理","不是水平位移"],"concepts":["位移合成","勾股定理"]},{"title":"声速对应斜边路程","type":"前提判断","judge":"声音传播的路程是竖直高度还是两点间直线距离，对应哪段时间","why":"声音从落水点沿直线传回抛出点，路程是两点间距离；题给的是落水后到听到声音的时间","do":"用两点间距离除以声音传播时间求声速","expr":"v_{声}=\\frac{s}{t'}","cues":["声音走直线","用斜边距离","不是高度"],"concepts":["声速","路程与时间"]}],"65":[{"title":"识别动量定义","type":"前提判断","judge":"要判断题目所求的“动量大小之差”该用哪个物理量公式来算","why":"动量是矢量，其大小由质量与速率的乘积决定，与速度方向无关，因此不能把速度差或质量差直接当作动量差","do":"写出动量大小的表达式，确认它等于质量乘速率","expr":"p=mv","cues":["动量就是质量乘速度","先写动量公式"],"concepts":["动量","质量","速率"]},{"title":"统一速度取值","type":"前提判断","judge":"要判断两款机器人各自的速率是否相同、能否用同一个速度值代入","why":"题设说明两者以同一速度同方向运动，速率相同，所以动量差异只来自质量差异，速度不必分别代入","do":"确认两机器人速率相同，取同一个 v 代入两动量表达式","expr":"v_1=v_2=v","cues":["速度一样","同方向同速度"],"concepts":["速率","同向运动"]},{"title":"作动量差取正","type":"关系建立","judge":"要判断动量之差应取哪个减哪个、结果取正还是取负","why":"题目问的是“动量大小之差”，是两动量大小的差值，应取绝对值，避免因减数顺序不同而得到负值","do":"用较大动量减去较小动量，或对差值取绝对值","expr":"\\Delta p=|m_1v-m_2v|=|m_1-m_2|v","cues":["大减小","取绝对值"],"concepts":["动量差","绝对值"]},{"title":"质量单位换算","type":"数学处理","judge":"要判断题给质量单位与速度单位是否属于同一单位制、能否直接相乘","why":"动量单位为千克米每秒，质量须用千克、速度须用米每秒，若质量以克或吨给出必须先换算，否则数量级出错","do":"把各机器人质量统一换算为千克，速度统一为米每秒后再代入","expr":"1\\,\\text{t}=10^3\\,\\text{kg}","cues":["先换单位","质量化成千克"],"concepts":["单位制","单位换算"]}],"66":[{"title":"判定波的类型","type":"前提判断","judge":"管内机械波的振动方向与传播方向是平行还是垂直","why":"活塞沿管长方向往复振动，介质质点的振动方向与波的传播方向共线，这是纵波的定义特征；若误判为横波，后续波长、频率关系全错","do":"比较活塞振动方向与波沿管传播方向是否在同一直线上","expr":"","cues":["振动方向沿管","振动与传播同向","是纵波"],"concepts":["纵波","横波","振动方向"]},{"title":"振幅由活塞行程定","type":"关系建立","judge":"波的振幅等于活塞振动离开平衡位置的最大距离，还是等于 a、b 间距离","why":"简谐运动中振幅是偏离平衡位置的最大位移，活塞在 a、b 间往返，平衡位置在中间，故振幅是 a、b 间距的一半","do":"取 a、b 间距的一半作为振幅","expr":"A=\\frac{x_{ab}}{2}","cues":["振幅是最大位移","取间距一半","不是整个间距"],"concepts":["简谐运动","振幅","平衡位置"]},{"title":"波长由波速和周期定","type":"关系建立","judge":"用波速和驱动周期求波长，还是把 a、b 间距当成波长","why":"稳定机械波的波长由波源周期和介质波速共同决定，λ=vT；a、b 间距只是波源行程，与波长无直接关系","do":"由驱动周期 T 和声速 v 算出波长 λ=vT","expr":"\\lambda=vT","cues":["波长等于波速乘周期","别拿间距当波长","先求周期"],"concepts":["波长","波速","周期"]},{"title":"每秒完整波个数","type":"结论整理","judge":"每秒经过某位置的完整波个数等于频率还是周期","why":"波传播时每个周期通过一个完整波形，故单位时间通过的完整波个数就是频率 f=1/T","do":"用 f=1/T 求每秒通过位置 c 的完整波个数","expr":"f=\\frac{1}{T}","cues":["每秒个数就是频率","频率是周期倒数","数完整波形"],"concepts":["频率","周期","波的传播"]}],"67":[{"title":"微粒平衡定场强方向","type":"前提判断","judge":"由微粒静止判断电场力与重力等大反向，进而确定板间电场方向","why":"微粒只受重力和电场力而静止，二力必等大反向，电场力竖直向上","do":"对微粒列平衡方程，由电荷正负定出极板间场强方向","expr":"qE=mg","cues":["电场力向上","重力等于电场力","先定方向"],"concepts":["二力平衡","电场力","匀强电场"]},{"title":"断开时电荷不转移","type":"模型选择","judge":"开关断开后，带电电容器是否仍保持原带电量、原场强","why":"开关断开使该电容器与外界无电荷交换，极板电荷量不变，孤立电容器电荷守恒","do":"比较断开前后极板电荷量与板间场强是否变化","expr":"Q=\\text{const},\\quad E=\\frac{U}{d}=\\frac{Q}{Cd}","cues":["断开电荷不变","电量保持","场强不变"],"concepts":["电荷守恒","电容器的孤立","场强与电荷量"]},{"title":"闭合后两电容并联","type":"模型选择","judge":"开关闭合后，ab与cd两电容器是串联还是并联，总电荷如何重新分配","why":"长导线把两电容器的极板对应相连，构成并联，总电荷在两电容器间重新分配","do":"画出闭合后的等效电路，确认并联关系并写出电荷分配关系","expr":"Q_{\\text{总}}=Q_{ab}+Q_{cd},\\quad U_{ab}=U_{cd}","cues":["相当于并联","电荷重新分","两端电压相同"],"concepts":["电容器并联","电荷分配","等势"]},{"title":"并联后场强变小","type":"关系建立","judge":"并联后ab板间电压（场强）比原来增大还是减小，从而判断电场力与重力的大小关系","why":"并联使总电容增大，在总电荷不变时共同电压低于原ab单独电压，故ab板间场强减小","do":"比较并联后的共同电压与原电压，得出场强变化，再比较电场力与重力","expr":"U'=\\frac{Q_{\\text{总}}}{C_{ab}+C_{cd}}<U_{ab},\\quad E'<E","cues":["电压变小","场强减小","电场力小于重力"],"concepts":["电容并联","电压与电荷量","电场力"]},{"title":"由合力方向定运动","type":"结论整理","judge":"场强减小后微粒所受合力方向，确定其运动方向","why":"电场力减小后小于重力，合力竖直向下，微粒由静止开始向下加速","do":"比较电场力与重力大小，判断合力方向与运动方向","expr":"mg-qE'>0","cues":["合力向下","向下加速","电场力不够"],"concepts":["牛顿第二定律","合力与运动方向"]}],"68":[{"title":"选传送带为参考系","type":"模型选择","judge":"以地面还是以传送带为参考系分析两物块的运动","why":"物块初始与传送带相对静止，摩擦力只由相对速度决定，取传送带系后初速度为零、摩擦力方向随相对速度反向，运动图像最简","do":"把甲、乙的初速度都记为相对传送带为零，之后所有速度、路程都指相对传送带的量","expr":"v_{\\text{相对}}=v_{\\text{物}}-v_{\\text{带}}","cues":["取传送带系","相对静止起步","摩擦力看相对速度"],"concepts":["参考系","相对运动","滑动摩擦力"]},{"title":"撤力后乙的加速度","type":"关系建立","judge":"撤去外力后乙相对传送带向哪边滑、摩擦力方向如何，从而定出加速度大小","why":"撤力瞬间乙相对传送带仍有向右速度，滑动摩擦力向左，大小由 μ₂mg 决定，与传送带速度无关","do":"对乙单独受力分析，只算水平方向的滑动摩擦力，写出牛顿第二定律求加速度","expr":"a_2=\\mu_2 g","cues":["只看摩擦力","加速度由动摩擦因数定","方向与相对速度相反"],"concepts":["牛顿第二定律","滑动摩擦力"]},{"title":"绳绷直时刻的速度","type":"关系建立","judge":"绳绷直时乙相对传送带的速度是否已减为零，即绷直发生在乙相对滑动停止之前还是之后","why":"题设给出撤力后再经 t₂ 绳才绷直，说明这段时间内乙仍在相对传送带滑动，速度按匀减速规律变化，据此可定出 t₁、t₂ 的关系","do":"用匀减速公式写出绷直瞬间乙的相对速度，并令其大于零（或恰为零）作为判断依据","expr":"v_2=a_1t_1-a_2t_2>0","cues":["绷直时还在滑","速度没减到零","先算剩余速度"],"concepts":["匀变速直线运动","速度公式"]},{"title":"绷直瞬间的动量守恒","type":"临界条件","judge":"绳绷直瞬间甲、乙组成的系统在沿绳方向动量是否守恒、能否用共同速度处理","why":"绷直过程极短，绳的冲力远大于摩擦力冲量，沿绳方向系统动量守恒，绷直后两者相对传送带速度相同","do":"对甲、乙沿绳方向列动量守恒，求出绷直后的共同相对速度","expr":"m v_2=(m+m)v_{\\text{共}}","cues":["绷直瞬间动量守恒","内力远大于摩擦","取共同速度"],"concepts":["动量守恒","完全非弹性碰撞","绳的冲力"]},{"title":"绷直后是否碰撞","type":"结论整理","judge":"绷直后甲、乙各自相对传送带滑行的路程谁大，判断甲能否追上乙","why":"绷直后两者速度相同但加速度不同（μ₁g 与 μ₂g 不同），滑行路程不同，需分别算出停止前走过的相对路程再比较","do":"分别用 v²/(2a) 算出甲、乙从绷直到相对静止的路程，与绷直前乙已走过的路程相加后比较位置","expr":"s=\\frac{v_{\\text{共}}^2}{2\\mu g}","cues":["比相对路程","看谁滑得远","加速度不同路程不同"],"concepts":["匀减速路程","相对位移","追及判断"]}],"69":[{"title":"手点位置角几何","type":"几何关系","judge":"要判断球心到单侧手作用点的连线与竖直轴的夹角如何由小圆半径和半球半径确定","why":"压力沿球面法线指向球心，手点在小圆上，其到球心的距离等于半球半径，故夹角由小圆半径与半球半径之比的正弦决定","do":"画出球心、手点、竖直轴构成的直角三角形，用半径比写出夹角的正弦","expr":"\\sin\\theta=\\frac{r}{R}","cues":["画直角三角形","半径比定角"],"concepts":["球面法线","几何关系"]},{"title":"整体受力分解","type":"模型选择","judge":"要判断把演员整体作为研究对象，把两手的支持力与摩擦力沿竖直和水平方向分解来列平衡方程","why":"演员静止倒立，受重力、两个支持力和两个摩擦力，水平分量互相抵消，竖直分量与重力平衡，用整体法可避开手间内力","do":"对整体列水平平衡和竖直平衡两式，把每个力按夹角分解","expr":"2N\\sin\\theta=2f\\cos\\theta,\\quad 2N\\cos\\theta+2f\\sin\\theta=mg","cues":["取整体","水平抵消","竖直配重力"],"concepts":["受力平衡","整体法","正交分解"]},{"title":"静摩擦上限约束","type":"临界条件","judge":"要判断静摩擦力不能超过最大静摩擦力，从而给出压力与重力的可行范围","why":"题目说明最大静摩擦力等于滑动摩擦力，平衡时所需静摩擦必须满足不超过该上限，这是判断各选项能否成立的前提","do":"把平衡式解出的摩擦与压力代入不等式，化为对压力或角度的限制","expr":"f\\le \\mu N","cues":["摩擦有上限","不能超过最大静摩擦"],"concepts":["最大静摩擦力","临界条件"]},{"title":"压力随角变化趋势","type":"关系建立","judge":"要判断在保持平衡时压力随夹角增大是增大还是减小，以及上升与压力大小是否有关","why":"由平衡式消去摩擦可得压力与重力的函数关系，压力只由角度决定，能否上升取决于摩擦是否足够而非压力大小","do":"由竖直与水平平衡消去摩擦，写出压力关于角度的表达式并分析单调性","expr":"N=\\frac{mg}{2(\\cos\\theta+\\mu\\sin\\theta)}","cues":["消去摩擦","看单调性","上升与压力无关"],"concepts":["平衡方程","函数关系"]},{"title":"辅助角求极值","type":"数学处理","judge":"要判断压力表达式的分母何时取最大，从而求出压力的最小值","why":"压力最小对应分母最大，分母是正弦与余弦的线性组合，需用辅助角公式化为单一正弦函数求极值","do":"把分母合并为一个正弦函数，令其等于一，解出最小压力","expr":"\\cos\\theta+\\mu\\sin\\theta=\\sqrt{1+\\mu^2}\\sin(\\theta+\\varphi)","cues":["合并成正弦","分母最大压力最小"],"concepts":["辅助角公式","极值"]}],"70":[{"title":"缓慢拉动的目的","type":"实验操作","judge":"拉动活塞时选缓慢还是快速，依据是什么","why":"等温变化要求气体温度始终等于环境温度，快速拉动会使气体来不及与外界换热而温度改变","do":"比较缓慢与快速拉动时气体状态变化的时间尺度与热交换条件，选定操作方式","expr":"","cues":["缓慢拉","温度不变","快速会变温"],"concepts":["等温变化","热交换"]},{"title":"先测摩擦力再密封","type":"前提判断","judge":"为什么要在未密封时先测活塞与筒壁的摩擦力","why":"密封后活塞两侧都有气体压力，拉力中混入气压差，无法单独得到摩擦力；未密封时活塞两端均为大气压，拉力只平衡摩擦力","do":"在未封口状态下匀速拉活塞，由电子秤示数等于摩擦力大小，作为后续受力分析的已知量","expr":"","cues":["先测摩擦","两端都是大气压","匀速才平衡"],"concepts":["平衡条件","摩擦力"]},{"title":"活塞受力平衡求压强","type":"关系建立","judge":"如何由拉力、摩擦力、大气压和横截面积表示筒内气体压强","why":"缓慢拉动时活塞近似处于平衡状态，水平方向受大气压力、气体压力、拉力和摩擦力，需按方向正确列平衡方程","do":"以活塞为研究对象，沿水平方向列平衡方程，解出筒内压强","expr":"p_0 S = pS + F + f","cues":["取活塞为对象","四个力平衡","注意摩擦方向"],"concepts":["平衡条件","压强","受力分析"]},{"title":"化曲为直选坐标","type":"图像读取","judge":"画 p-V 图还是 p-1/V 图才能由直线判断规律","why":"等温下 p 与 V 成反比，p-V 图是双曲线不便判断，改画 p 与 1/V 的关系若为过原点直线即可确认反比","do":"把体积取倒数作为横坐标，检查图像是否为过原点的直线","expr":"p = C·\\frac{1}{V}","cues":["取倒数","看是不是直线","过原点"],"concepts":["反比关系","线性化","玻意耳定律"]},{"title":"体积增量取值","type":"数据处理","judge":"每次体积增加量取多少才兼顾数据点数量与压强变化幅度","why":"增量过大则点少、规律不明显，过小则压强变化小、相对误差大，需与注射器刻度分度值匹配","do":"按针筒最小刻度选定等间隔体积增量，逐次记录对应拉力示数","expr":"","cues":["按刻度取","等间隔","点要够多"],"concepts":["多次测量","刻度分度值"]}],"71":[{"title":"分段拆解运动过程","type":"模型选择","judge":"要判断返航全程由哪几段运动组成、每段的初末速度与位移各是什么","why":"题目把水平飞行和竖直下降分开描述，各段遵循不同的运动规律，不先分段就无法为每段选公式","do":"把全程分为水平匀速段、水平匀减速段、竖直下降段，逐段标出已知量和待求量","expr":"","cues":["先分段","水平两段竖直一段","各段分开算"],"concepts":["运动过程分析","匀速直线运动","匀变速直线运动"]},{"title":"匀减速段位移的确定","type":"几何关系","judge":"要判断水平匀减速段的位移是120 m与50 m之差，而不是120 m或50 m","why":"无人机先飞到距降落点水平50 m处，再沿原方向减速到降落点正上方，减速段起点到终点的水平距离由两段水平距离相减得到","do":"用总水平距离减去已匀速飞过的水平距离，得到减速段位移","expr":"$x_2=120\\ \\text{m}-50\\ \\text{m}=70\\ \\text{m}$","cues":["相减得减速段","不是直接用120","50到0这段"],"concepts":["位移","几何关系"]},{"title":"减速段末速度为零","type":"临界条件","judge":"要判断匀减速段末速度为零（恰好停在降落点正上方），从而用速度位移关系求加速度","why":"题设说减速至降落点正上方后转为竖直下降，水平方向不再前进，说明水平末速度为零，这是选用$0-v_0^2=2ax$的前提","do":"以初速度10 m/s、末速度0、位移70 m代入速度位移公式解出加速度大小","expr":"$0-v_0^2=-2ax_2$","cues":["末速度为零","停在正上方","用速度位移公式"],"concepts":["匀变速直线运动","速度位移关系","临界条件"]},{"title":"位移只看首末位置","type":"概念辨析","judge":"要判断全程位移是起点到降落点的直线距离，与中间路径无关","why":"位移是矢量，只由初位置和末位置决定；题目给的水平距离120 m和竖直距离90 m正好构成直角三角形的两直角边","do":"用勾股定理求起点到降落点的直线距离作为位移大小","expr":"$s=\\sqrt{120^2+90^2}\\ \\text{m}$","cues":["位移看首末","勾股定理","不管中间怎么走"],"concepts":["位移","矢量","勾股定理"]},{"title":"平均速度用总位移除总时间","type":"关系建立","judge":"要判断平均速度必须用全程总位移除以全程总时间，而不是各段速度的平均","why":"平均速度定义式为$\\bar v=s/t$，全程时间需把匀速段、减速段、竖直下降段三段的时间都加起来","do":"分别求匀速段时间、减速段时间，加上竖直下降的33 s得总时间，再用总位移除以总时间","expr":"$\\bar v=\\dfrac{s}{t_1+t_2+33}$","cues":["总位移除总时间","三段都算上","不能取速度平均"],"concepts":["平均速度","总时间","位移"]}],"72":[{"title":"磁场方向判定","type":"前提判断","judge":"Ⅱ区磁场应取垂直纸面向内还是向外，才能让甲每次过（d，0）时速度沿x轴正方向","why":"洛伦兹力方向由左手定则决定，磁场方向选反则偏转方向相反，轨迹无法闭合回（d，0）","do":"分别假设Ⅱ区磁场向外、向内画出甲在Ⅱ区的偏转方向，检验能否回到（d，0）且速度沿x轴正向","expr":"","cues":["先试磁场方向","偏转方向反了","回不到原点"],"concepts":["左手定则","洛伦兹力方向","圆周运动"]},{"title":"周期性轨迹几何","type":"几何关系","judge":"甲在Ⅰ、Ⅱ两区圆弧的圆心位置与衔接点，如何拼成闭合周期轨迹","why":"两区磁感应强度大小相同，半径相同，轨迹由两段等半径圆弧组成，周期与总路程由几何拼接决定","do":"由（d，0）出发沿x轴正向进入Ⅰ区，定出圆心，求圆弧转过的圆心角与各段弧长，拼出完整周期路径","expr":"r=\\frac{mv}{qB}","cues":["两段圆弧拼起来","找圆心","算圆心角"],"concepts":["圆周运动","几何对称","轨迹拼接"]},{"title":"弹性正碰列式","type":"关系建立","judge":"碰撞中动量与动能同时守恒，且碰后甲速度方向反向、乙沿x轴正向","why":"弹性正碰无电荷交换、质量分别为m和km，必须联立动量守恒与动能守恒才能定出碰后两速度","do":"以碰前甲速度v0为正方向，列动量守恒与动能守恒，解出v1、v2并判断v1的符号","expr":"mv_0=mv_1+kmv_2,\\ \\frac12mv_0^2=\\frac12mv_1^2+\\frac12kmv_2^2","cues":["弹性正碰","动量加动能","碰后甲反向"],"concepts":["动量守恒","动能守恒","弹性碰撞"]},{"title":"再次正碰位置","type":"临界条件","judge":"甲与乙再次正碰只能发生在x轴上的哪一点，且碰前甲仅进Ⅱ区一次","why":"乙碰后沿x轴匀速，甲要与其相遇必须在同一时刻到达同一点；由轨迹对称性知相遇点在（3d，0），且限制甲只进Ⅱ区一次","do":"画出碰后甲反向绕行、经细管加速再进入Ⅱ区的路径，确认与乙在（3d，0）相遇且只穿越Ⅱ区一次","expr":"","cues":["只能在x轴相遇","相遇点是3d","只进一次Ⅱ区"],"concepts":["匀速直线运动","周期性轨迹","相遇条件"]},{"title":"加速器横坐标","type":"几何关系","judge":"细管加速器应放在何处，使甲碰后能竖直进入管内并被加速到所需速度","why":"甲碰后反向做半径r1的圆周运动，须沿y轴方向进入平行于y轴的细管，管的位置由该圆弧的几何位置确定","do":"由碰后甲的速度求半径r1，结合圆心位置定出甲竖直进入细管处的横坐标","expr":"r_1=\\frac{m|v_1|}{qB}","cues":["竖直进管","半径由碰后速度定","横坐标看圆心"],"concepts":["圆周运动半径","几何约束"]},{"title":"等时性与k范围","type":"数学处理","judge":"甲在管内匀加速的时间与乙匀速到（3d，0）的时间相等，由此解出k需满足的条件","why":"再次正碰要求两者同时到达同一点，甲在管内速度由|v1|匀加速到v甲2，时间由运动学求出，与乙的匀速时间联立","do":"对甲列|v1|+at=v甲2求加速时间t，对乙列匀速时间，令两时间相等并化简，结合k>1得k的范围","expr":"|v_1|+at=v_{\\text{甲}2},\\ t=\\frac{3d-d}{v_2}","cues":["时间相等","等时性","k大于1"],"concepts":["匀变速直线运动","匀速直线运动","等时性"]}],"73":[{"title":"识别原子符号的标注含义","type":"前提判断","judge":"符号左上角和左下角的数字分别代表什么物理量","why":"核素符号的书写约定：左上角为质量数，左下角为质子数（核电荷数），这是比较两种核素各项参数的前提","do":"读出铀和钚符号左上角的数值与左下角的数值，分别对应质量数和质子数","expr":"","cues":["左上角是质量数","左下角是质子数","先看角标"],"concepts":["核素符号","质量数","质子数"]},{"title":"区分元素种类与质子数","type":"关系建立","judge":"铀和钚是否为同种元素，由什么量决定","why":"元素种类由质子数（核电荷数）决定，质子数不同即为不同元素，因此两者质子数必然不相等","do":"比较两种核素左下角的质子数，判断是否相同","expr":"","cues":["不同元素","看核电荷数","质子数不一样"],"concepts":["元素","核电荷数"]},{"title":"由质量数与质子数求中子数","type":"关系建立","judge":"质量数相同、质子数不同时，中子数是否相同","why":"中子数等于质量数减质子数，质量数相同而质子数不同，差值必然不同","do":"对两种核素分别用质量数减去质子数，比较所得中子数","expr":"N=A-Z","cues":["差值不同","中子数也不等"],"concepts":["中子数","质量数"]},{"title":"判断原子质量是否相等","type":"结论整理","judge":"质子数、中子数各自不同时，原子总质量能否相等","why":"原子质量由核内质子、中子的质量与核外电子质量共同决定，核子总数相同但质子与中子的比例不同，单个质子与中子的质量并不严格相等，故总质量不相等","do":"比较两核素的核子构成（质子数、中子数各是多少），判断总质量是否一致","expr":"","cues":["质子中子质量不同","核子总数一样","总质量不相等"],"concepts":["原子质量","核子"]}],"74":[{"title":"质点判据","type":"前提判断","judge":"判断能否把船看成质点，依据是什么","why":"质点是没有大小形状的点，只有当物体的大小和形状对所研究的问题影响可忽略时才能这样简化","do":"先明确判据：看船的大小形状是否影响所研究的运动，而不是看船本身大小或运动快慢","expr":"","cues":["看大小形状影响","不是看船大小","能否忽略"],"concepts":["质点","理想化模型"]},{"title":"区分运动性质","type":"模型选择","judge":"所研究的问题关注的是船的整体位置变化，还是船的姿态、各部位位置","why":"若只关心整体轨迹和快慢，船的大小形状不影响结论；若涉及转动、通过狭窄处、避让，就必须考虑形状尺寸","do":"把各情境归为两类：整体平动求速率，还是涉及姿态或局部位置","expr":"","cues":["看整体还是局部","转船头算姿态","过闸口看长度"],"concepts":["平动","转动","参考系"]},{"title":"尺度比较","type":"关系建立","judge":"船的长度与所研究运动的空间尺度相比是否可以忽略","why":"质点化的实质是物体线度远小于问题涉及的距离，运河全程远大于船长，故可忽略","do":"比较船长与运河航程的数量级，判断船长对平均速率计算有无影响","expr":"L_{\\text{船}} \\ll s_{\\text{航程}}","cues":["船长远小于航程","尺度差很多","可忽略"],"concepts":["尺度","平均速率"]}],"75":[{"title":"确定合力的变化","type":"关系建立","judge":"起跳方向和作用时间不变时，平均合力是否随平均作用力同比例增大","why":"人受重力与地面反作用力，起跳方向固定意味着两力沿起跳方向的夹角固定，合力沿起跳方向的分量随地面平均作用力增大而增大","do":"把地面平均作用力沿起跳方向分解，减去重力沿该方向的分量，写出平均合力表达式","expr":"F_{合}=F_{地}-mg\\sin\\theta","cues":["先看合力","方向不变夹角不变","重力分量固定"],"concepts":["力的合成与分解","牛顿第三定律"]},{"title":"用动量定理求末速度","type":"模型选择","judge":"判断该用动量定理还是牛顿第二定律加运动学来求起跳完成时的速度","why":"已知平均作用力和作用时间，直接求冲量得动量变化最简，初速度为零","do":"对起跳过程列动量定理，把平均合力与作用时间的乘积等于末动量","expr":"F_{合}t=mv","cues":["用动量定理","冲量等于动量变化","初速为零"],"concepts":["动量定理","冲量"]},{"title":"区分冲量与支持力","type":"前提判断","judge":"判断地面给人的冲量变化与地面平均支持力变化是否由同一关系决定","why":"冲量是力对时间的积累，支持力大小还要叠加竖直方向的重力分量，二者变化规律不能混为一谈","do":"分别写出冲量表达式与支持力表达式，比较它们随平均作用力增大的变化","expr":"I=F_{地}t,\\quad N=F_{地}\\sin\\alpha+mg","cues":["冲量看时间积累","支持力要加重力","别把两者混了"],"concepts":["冲量","支持力","受力分析"]},{"title":"判断起跳方向与水平夹角","type":"几何关系","judge":"判断起跳方向不变时，地面平均作用力方向与竖直方向的夹角是否固定","why":"起跳方向固定即合力方向固定，地面反作用力方向随之固定，其竖直分量与水平分量按同一角度分配","do":"设起跳方向与水平面夹角，把地面平均作用力分解为竖直和水平分量","expr":"N=F_{地}\\sin\\alpha+mg","cues":["方向不变角度不变","分解到竖直","夹角固定"],"concepts":["运动的合成与分解","角度关系"]}],"76":[{"title":"转动切割电动势","type":"模型选择","judge":"判断金属棒OP绕一端转动切割磁感线时，感应电动势该用哪个公式、用哪段长度","why":"棒上各点线速度随半径线性增大，只有用转动切割公式才能得到正确电动势，不能当成平动切割","do":"写出OP转动产生的感应电动势，与角速度成正比","expr":"E=\\frac{1}{2}B\\omega L^{2}","cues":["转动切割","用二分之一","看角速度"],"concepts":["动生电动势","转动切割"]},{"title":"二极管单向导电","type":"前提判断","judge":"判断两个发光二极管在各自支路中允许电流通过的方向，以及自感电流能否反向流过它们","why":"二极管具有单向导电性，电流反向时该支路被切断，这决定了自感电流只能沿原方向经某一支路流通","do":"标出两支路中二极管的导通方向，比较自感电动势方向与原电流方向是否一致","expr":"","cues":["单向导电","反向不通","只走一边"],"concepts":["二极管单向导电性","自感电动势"]},{"title":"自感阻碍电流变化","type":"关系建立","judge":"判断角速度变化（含变为零）时，电感L是否产生自感电动势、其方向如何","why":"通过电感的电流变化时会产生自感电动势阻碍变化，电流减小时自感电动势与原电流同向，维持电流","do":"分析角速度随时间变化引起电流增减，确定自感电动势的方向与作用","expr":"\\varepsilon_{L}=-L\\frac{\\Delta i}{\\Delta t}","cues":["阻碍变化","电流减小","同向维持"],"concepts":["自感现象","自感电动势"]},{"title":"分阶段求消耗电能","type":"数学处理","judge":"判断求0到某时刻整个电路消耗的电能时，需按角速度随时间的分段规律分别积分再相加","why":"角速度随时间先变化后为零，电动势和电流不是恒定值，不能用一个时刻的功率乘总时间","do":"按图乙分段写出角速度表达式，求各段功率对时间的积分后求和","expr":"W=\\int\\frac{E^{2}}{R_{总}}\\,dt","cues":["分段算","功率在变","不能直接乘"],"concepts":["焦耳定律","交流电有效值"]},{"title":"亮度与熄灭先后","type":"结论整理","judge":"判断两支路中二极管亮度由通过它的电流决定，以及断电后哪支路先失去自感电流","why":"亮度取决于实际电流大小；自感电流只能沿二极管导通方向流动，被反向截止的支路立即熄灭","do":"比较两支路电流大小关系，再结合自感电流方向判断熄灭先后","expr":"","cues":["看电流大小","谁先灭","自感供电"],"concepts":["电功率","自感电流","二极管"]}],"77":[{"title":"椭圆半长轴","type":"几何关系","judge":"椭圆变轨轨道的半长轴该由两圆轨道半径如何组合得出","why":"椭圆轨道近地点在低轨道1上、远地点在高轨道2上，长轴两端就是两圆半径之和，半长轴是长轴的一半；把半长轴误当成某一圆半径或两半径之差，后续开普勒第三定律全错","do":"画出两圆与椭圆的位置关系，写出长轴两端到地心的距离，取平均得半长轴","expr":"a=\\frac{r_1+r_2}{2}","cues":["取两半径平均","长轴是两半径之和","别直接用低轨半径"],"concepts":["椭圆半长轴","几何关系"]},{"title":"开普勒第三定律定周期","type":"关系建立","judge":"椭圆轨道周期与圆轨道周期之间该用哪个量建立联系","why":"开普勒第三定律对同一中心天体成立，比值只与中心天体质量有关，与卫星质量无关；必须用半长轴而非圆半径代入，否则周期比算错","do":"对椭圆轨道和圆轨道分别写周期平方比半长轴三次方，联立求椭圆周期","expr":"\\frac{T^2}{a^3}=\\frac{T_2^2}{r_2^3}=\\frac{4\\pi^2}{GM}","cues":["用半长轴","比值只跟中心天体有关","跟卫星质量无关"],"concepts":["开普勒第三定律","中心天体"]},{"title":"半椭圆飞行时间","type":"前提判断","judge":"变轨卫星从P到K所用时间对应椭圆周期的多少","why":"P、K是椭圆长轴两端，从一端到另一端恰好走过半个椭圆，时间应为周期的一半；若误取整个周期或四分之一周期，时间关系就错","do":"确认P、K为近远地点，取椭圆周期的一半作为飞行时间","expr":"t=\\frac{T}{2}","cues":["走半个椭圆","取周期一半","P到K是半圈"],"concepts":["椭圆轨道","周期"]},{"title":"高轨卫星转角","type":"关系建立","judge":"高轨卫星在相同时间内转过的角度如何由角速度与时间求出","why":"高轨卫星做匀速圆周运动，转角等于角速度乘时间；角速度需由万有引力提供向心力或由周期求出，角度关系决定两卫星能否同时到达K","do":"先求高轨圆轨道角速度，再乘变轨卫星的半周期得转角","expr":"\\theta=\\omega_2 t=\\frac{2\\pi}{T_2}\\cdot\\frac{T}{2}","cues":["先求角速度","转角等于角速度乘时间","用高轨周期"],"concepts":["角速度","匀速圆周运动"]},{"title":"相距最近的角度条件","type":"临界条件","judge":"两卫星第一次相距最近时，相对转过的角度应满足什么条件","why":"相距最近指两卫星与地心连线重合，即相对转角等于初始位置的角度差（或其整数倍加该差）；不先确定初始角度差就无法列相对运动方程","do":"由几何关系求出初始时两卫星位置矢量夹角，令相对转角等于该角度差，解出时间","expr":"(\\omega_1-\\omega_2)t=\\Delta\\theta_0","cues":["连线重合才最近","先找初始角度差","用相对角速度"],"concepts":["相对运动","角度差","临界条件"]}],"78":[{"title":"单闭合时电压表读电动势","type":"前提判断","judge":"只闭合 S1 时，电压表测的是不是电源电动势","why":"理想电压表内阻无穷大，所在支路无电流，电源内阻与定值电阻上均无电压降，路端电压等于电动势","do":"把只闭合 S1 的电路看成开路状态，确认电压表直接跨接在电源两端","expr":"E=U_1","cues":["电压表当断路","内阻不分压","路端电压就是电动势"],"concepts":["理想电压表","电动势","路端电压"]},{"title":"电压表量程与分度值","type":"图像读取","judge":"图乙中电压表选的是哪一量程、每小格代表多少伏","why":"读数精度由所选量程的分度值决定，量程判断错则读数整体错位","do":"看图乙接线柱与刻度盘，确认量程后数出指针所在小格数","expr":"","cues":["先看量程","一小格多少伏","指针偏转格数"],"concepts":["电压表量程","分度值","读数"]},{"title":"估读到分度值下一位","type":"数据处理","judge":"读数应保留到哪一位、是否要估读","why":"电压表为刻度式仪表，需读到分度值的下一位，否则有效数字不符要求","do":"按分度值确定末位，写出带估读位的读数","expr":"U_2=1.20\\ \\text{V}","cues":["要估读一位","末位是零也得写","别只读到分度值"],"concepts":["估读","有效数字"]},{"title":"双闭合时外电路结构","type":"模型选择","judge":"S1、S2 都闭合后，定值电阻与电压表是串联还是并联、电压表测谁两端电压","why":"电压表与定值电阻并联后再与电源串联成回路，电压表读数即为并联部分（定值电阻）两端电压，而非电动势","do":"画出双闭合时的等效电路，标出电压表并联在定值电阻两端","expr":"U_2=I R_0","cues":["电压表并在外电阻上","测的是定值电阻电压","不再是电动势"],"concepts":["并联","闭合电路欧姆定律","等效电路"]},{"title":"用两次读数联立求内阻","type":"关系建立","judge":"如何把两次电压读数与 E、r、R0 联系起来","why":"单闭合给出 E，双闭合时由闭合电路欧姆定律 E=U+Ir 且 I=U/R0，可解出唯一未知量 r","do":"对双闭合状态列闭合电路欧姆定律，用 U2/R0 表示电流后解出 r","expr":"E=U_2+\\frac{U_2}{R_0}r","cues":["先求电流","再列闭合电路欧姆定律","两个状态联立"],"concepts":["闭合电路欧姆定律","内阻","电流"]},{"title":"结果保留两位有效数字","type":"结论整理","judge":"内阻结果应保留几位、如何取舍","why":"题目明确要求保留两位有效数字，多留或少留都算不规范","do":"算出 r 后按两位有效数字修约写出","expr":"","cues":["两位有效数字","从第一个非零数字数","别多写一位"],"concepts":["有效数字","修约"]}],"79":[{"title":"选钩爪石块为整体","type":"模型选择","judge":"求绳对钩爪的拉力时，应把钩爪和石块取作一个整体还是分别隔离","why":"绳的拉力作用在钩爪上，而石块通过钩爪间的摩擦与钩爪关联；取整体可让钩爪与石块间的内力（摩擦力、正压力）成对抵消，只出现外部的重力与绳拉力","do":"把钩爪与石块合并为一个系统，画它所受的外力：两段轻绳的拉力与总重力","expr":"","cues":["取整体","别拆开","内力抵消"],"concepts":["整体法","受力分析"]},{"title":"由对称定绳拉力方向","type":"几何关系","judge":"两段轻绳对钩爪的拉力沿什么方向、与竖直方向成多大角度","why":"图中钩爪与绳构成正方形，绳沿正方形边、钩爪沿对角线，故绳与竖直方向成45°；又因结构左右对称，两绳拉力大小相等","do":"由正方形的边角关系定出绳与竖直方向夹角为45°，并判断两绳拉力等大","expr":"","cues":["正方形对角线","两边对称","四十五度"],"concepts":["对称性","几何关系"]},{"title":"竖直方向平衡列式","type":"关系建立","judge":"静止时用合力为零还是用某一方向的分力平衡来求绳拉力","why":"系统静止，所受两绳拉力与重力共面，竖直方向合力为零；每段绳拉力在竖直方向的分量之和等于总重力","do":"对整体在竖直方向列平衡方程，把两绳拉力的竖直分量相加等于总重力，解出单根绳的拉力","expr":"2T\\cos45^\\circ=(M+m)g","cues":["竖直方向平衡","分解拉力","两段绳"],"concepts":["共点力平衡","力的分解"]},{"title":"绳受拉力用牛顿第三定律","type":"结论整理","judge":"题目问的是绳受到钩爪的拉力，还是钩爪受到绳的拉力","why":"平衡方程解出的是绳对钩爪的拉力，而待求量是钩爪对绳的拉力，二者是作用力与反作用力","do":"把求得的绳对钩爪拉力按牛顿第三定律反向，说明其大小相等、方向沿绳向下","expr":"","cues":["作用力反作用力","方向反过来","沿绳向下"],"concepts":["牛顿第三定律"]},{"title":"由运动学求加速度","type":"关系建立","judge":"用哪组运动学量求石块下放的加速度","why":"题设给出初速度为零、时间0.2秒、位移0.1米且为匀加速，位移公式可直接定出加速度","do":"由初速为零的匀加速位移公式代入时间和位移，解出加速度","expr":"h=\\frac12at^2","cues":["初速为零","位移公式","先求加速度"],"concepts":["匀变速直线运动","加速度"]},{"title":"隔离石块定摩擦方向","type":"临界条件","judge":"石块加速度向下且小于g时，钩爪对石块的摩擦力沿哪个方向、与重力谁大","why":"由运动学算出的加速度远小于g，石块所受合力向下但小于重力，说明必有一个向上的力抵消部分重力，即摩擦力竖直向上","do":"隔离石块，比较加速度与g的大小，判定摩擦力向上，再沿竖直方向列牛顿第二定律方程求其大小","expr":"mg-f=ma","cues":["加速度小于g","摩擦力向上","隔离石块"],"concepts":["牛顿第二定律","隔离法","滑动摩擦力"]}],"80":[{"title":"安培力方向与大小","type":"关系建立","judge":"判断金属棒所在处磁场的有效方向与有效长度，从而定出安培力方向","why":"安培力方向由左手定则决定，大小 F=BIL 中的 L 是垂直于 B 的有效长度；磁场竖直向下、棒水平，二者垂直","do":"先确认棒所在位置属于左段匀强区还是右段三角区，再用左手定则定方向、用 F=BIL 算大小","expr":"F=BIL","cues":["左手定则","看有效长度","磁场竖直向下"],"concepts":["安培力","左手定则","有效长度"]},{"title":"最大速度的受力条件","type":"临界条件","judge":"判断速度最大时加速度为零，即安培力与摩擦力平衡","why":"棒在安培力驱动下加速，速度增大使所在处磁场减弱、安培力减小，当安培力降到与滑动摩擦力相等时不再加速","do":"令安培力等于滑动摩擦力，解出最大速度对应的位置或速度","expr":"B(x)IL=μmg","cues":["加速度为零","安培力等于摩擦力","速度最大时平衡"],"concepts":["牛顿第二定律","滑动摩擦力","平衡条件"]},{"title":"三角磁场的几何关联","type":"几何关系","judge":"判断棒到达最大速度处时在三角形磁场中的位置与磁感应强度的对应关系","why":"右段磁场呈等腰三角形分布，B 随进入深度线性变化，必须由几何相似把位移与当地 B 联系起来","do":"按三角形高和底边宽度写出 B 随位移变化的线性关系，代入平衡条件求位移","expr":"B(x)=B_0(1-x/h)","cues":["相似三角形","磁场线性减弱","先找几何关系"],"concepts":["等腰三角形","相似关系","磁感应强度分布"]},{"title":"变力做功的动能定理","type":"模型选择","judge":"判断全程用动能定理处理，且安培力是变力需按 B-x 图线下面积求功","why":"安培力随位置变化，不能直接用恒力功公式；摩擦力为恒力可直接算，初末动能已知","do":"对解除锁定到最大速度的过程列动能定理，安培力功由 B-x 线性关系积分或面积求出","expr":"W_A-μmgx=\\frac12mv_m^2","cues":["动能定理","变力做功看面积","摩擦力做负功"],"concepts":["动能定理","变力做功","功的面积表示"]},{"title":"恰好到达顶点的临界","type":"临界条件","judge":"判断棒恰好到达顶点 O 时速度为零，据此建立安培力做功与电流的关系","why":"恰好到达意味着到达顶点时动能刚好耗尽，是求最大电流的临界状态","do":"对全程列动能定理，末动能为零，把安培力功写成含 I 的表达式","expr":"W_A(I)-μmgL=0","cues":["恰好到达","末速度为零","临界状态"],"concepts":["动能定理","临界条件","安培力做功"]},{"title":"起动的静摩擦临界","type":"临界条件","judge":"判断棒能开始运动的条件是初始安培力大于最大静摩擦力","why":"最大静摩擦力等于滑动摩擦力，安培力必须超过它棒才会起动，这给出电流下限","do":"令初始位置安培力等于最大静摩擦力，解出最小电流","expr":"B_0IL=\\mu mg","cues":["能运动起来","超过最大静摩擦","求电流下限"],"concepts":["最大静摩擦力","起动条件","安培力"]}],"81":[{"title":"洛伦兹力方向判定","type":"前提判断","judge":"电子（负电荷）所受洛伦兹力指向哪一侧，从而确定轨迹向哪边弯曲","why":"洛伦兹力方向由左手定则给出，但电子带负电，四指应指向电子运动的反方向（或判出正电荷受力后反向），方向判反则轨迹弯曲方向全错","do":"按电子入射方向取反作为等效电流方向，用左手定则判出受力方向，再对照图中轨迹的弯曲侧","expr":"\\vec F=q\\vec v\\times\\vec B,\\ q=-e","cues":["四指指速度反方向","负电荷要反向","看受力朝哪边"],"concepts":["左手定则","洛伦兹力","负电荷"]},{"title":"轨迹形状判断","type":"模型选择","judge":"电子在匀强磁场中垂直入射时轨迹是圆弧还是抛物线或其他曲线","why":"速度与磁场垂直，洛伦兹力大小不变且始终垂直于速度，只改变方向不改变速率，故为匀速圆周运动，轨迹是圆（弧）的一部分","do":"确认 v⊥B 且只受洛伦兹力，判定轨迹为圆弧而非直线或抛物线","expr":"qvB=\\frac{mv^2}{r}","cues":["力始终垂直速度","速率不变","是圆弧不是抛物线"],"concepts":["匀速圆周运动","向心力"]},{"title":"圆心与弯曲侧对应","type":"几何关系","judge":"圆心应位于电子入射点处洛伦兹力所指的一侧，轨迹向受力方向弯曲","why":"圆周运动的圆心在向心力（洛伦兹力）方向上，圆心位置决定弧线弯向哪边，圆心定错则选到反向弯曲的图","do":"从入射点沿受力方向作垂线找圆心，比较各图中弧的凹向是否与该侧一致","expr":"","cues":["圆心在受力方向","弧往受力那边弯","找圆心定弯曲"],"concepts":["圆心","向心力方向","曲率"]}],"82":[{"title":"分解平抛两方向","type":"模型选择","judge":"判断排球做什么运动、水平与竖直各按什么规律处理","why":"不计空气阻力且初速度水平，排球只受重力，是平抛运动，必须分解为水平匀速和竖直自由落体两个独立分运动","do":"把运动分解为水平方向和竖直方向，分别写出两方向的运动方程","expr":"x=v_0 t,\\quad h=\\tfrac12 g t^2","cues":["平抛运动","水平匀速","竖直自由落体"],"concepts":["平抛运动","运动的分解"]},{"title":"飞行时间由高度定","type":"前提判断","judge":"判断三次飞行的竖直下落高度是否相同，从而判断飞行时间是否相等","why":"竖直方向 h=½gt²，时间只由下落高度决定，与水平初速度无关；三次从同一高度落到同一水平面，高度相同","do":"比较三次的竖直位移，确认 h 相同，得出 t 相同","expr":"t=\\sqrt{\\frac{2h}{g}}","cues":["同一高度","时间一样","与初速度无关"],"concepts":["自由落体","等时性"]},{"title":"水平位移读图比较","type":"图像读取","judge":"从图中判断三个落点的水平位移大小顺序","why":"初速度关系要靠 x=v₀t 反推，必须先由落点位置读出水平位移的大小关系","do":"比较三个落点到击球点正下方的水平距离，排出 x 的大小顺序","expr":"x_1<x_2<x_3","cues":["看水平距离","落点越远位移越大","比水平位移"],"concepts":["水平位移","匀速直线运动"]},{"title":"等时反推初速度","type":"关系建立","judge":"在时间相等的前提下，判断水平位移与初速度成正比，由位移顺序得初速度顺序","why":"x=v₀t 中 t 相同，x 与 v₀ 成正比，位移大的初速度大；干扰项错在把时间当成随初速度变化","do":"用 x=v₀t 把位移大小关系直接翻译成初速度大小关系","expr":"v_0=\\frac{x}{t},\\quad v_{01}<v_{02}<v_{03}","cues":["时间相同","位移大速度大","成正比"],"concepts":["匀速直线运动","控制变量"]}],"83":[{"title":"识别条纹成因","type":"模型选择","judge":"要判断条纹是薄膜前后表面反射光叠加形成的干涉条纹，还是色散或衍射条纹","why":"只有认定为薄膜干涉，才能用膜厚与波长的关系去分析条纹分布；若误判为棱镜色散或单缝衍射，后续推理全部失效","do":"确认光在肥皂膜前后两表面反射后相遇叠加，属于等厚干涉","expr":"","cues":["薄膜干涉","前后表面反射","不是色散"],"concepts":["薄膜干涉","反射光叠加"]},{"title":"判断膜厚分布","type":"前提判断","judge":"要判断重力使液体下流后，肥皂膜是上薄下厚还是上厚下薄","why":"膜厚随高度的变化方向决定条纹疏密的变化方向，方向判反则结论相反","do":"由液体在重力作用下向下流动，判断膜厚随高度增加而增大","expr":"","cues":["上薄下厚","液体往下流","重力作用"],"concepts":["重力","膜厚分布"]},{"title":"厚度变化率随高度","type":"关系建立","judge":"要判断越往下膜厚随高度增长得越快还是越慢，即厚度变化率是否随高度增大","why":"条纹间距由厚度变化率决定，仅知道上薄下厚不够，还必须知道变化率如何随高度改变，否则无法比较条纹疏密","do":"比较不同高度处单位竖直距离内的厚度增量，判断越靠下增量越大","expr":"","cues":["越往下越陡","变化率变大","厚度增长加快"],"concepts":["厚度变化率","液膜形状"]},{"title":"厚度差与条纹对应","type":"关系建立","judge":"要判断相邻亮纹（或暗纹）对应的膜厚差是否为定值","why":"干涉加强条件给出相邻同相条纹的厚度差恒为半个波长，这是把厚度变化率与条纹间距联系起来的桥梁","do":"写出相邻亮纹的厚度差关系，确认其为与位置无关的常量","expr":"\\Delta d=\\frac{\\lambda}{2}","cues":["厚度差固定","半个波长","相邻条纹"],"concepts":["干涉条件","半波长厚度差"]},{"title":"间距与变化率反比","type":"数学处理","judge":"要判断厚度变化率越大时，相邻条纹的竖直间距越大还是越小","why":"厚度差固定而厚度变化率不同，间距等于厚度差除以变化率，变化率越大间距越小","do":"用定值厚度差除以局部厚度变化率，比较上下各处的条纹间距","expr":"\\Delta h=\\frac{\\Delta d}{\\left|\\mathrm{d}d/\\mathrm{d}h\\right|}","cues":["变化率大间距小","越往下越密","间距反比"],"concepts":["条纹间距","厚度变化率"]},{"title":"条纹疏密与半径","type":"结论整理","judge":"要判断条纹在圆环半径方向上是由内向外变密还是变疏","why":"肥皂泡为球面，竖直高度与环纹半径一一对应，需把竖直方向的疏密结论换算成半径方向的分布","do":"将越靠下条纹越密的结论对应到半径增大的方向，得出条纹半径增大时变密","expr":"","cues":["半径增大变密","由内向外","环纹疏密"],"concepts":["球面几何","条纹分布"]}],"84":[{"title":"冲量等于动量变化","type":"关系建立","judge":"求顶点处冲量大小，应判断为合外力的冲量等于动量的矢量变化量，而不是等于动量大小本身","why":"小球在顶点只受圆壁弹力（冲量），由动量定理 I=Δp，冲量大小等于动量变化量的大小；若误把冲量当成动量大小，比值恒为 1，就失去意义","do":"写出动量定理矢量式，明确待求比值是 |Δp|/|p|","expr":"\\vec{I}=\\Delta\\vec{p}","cues":["冲量等于动量变化","用动量定理","不是动量本身"],"concepts":["动量定理","冲量","动量变化量"]},{"title":"弹性碰撞速率不变","type":"前提判断","judge":"判断小球与圆内壁弹性碰撞前后速率是否改变","why":"弹性碰撞且壁面不动，动能不变，故碰前碰后速率相等，只有速度方向改变，动量变化完全来自方向偏转","do":"确认各顶点前后速率均为 v，动量大小均为 mv","expr":"|\\vec{p}_1|=|\\vec{p}_2|=mv","cues":["弹性碰撞速率不变","只变方向","速度大小一样"],"concepts":["弹性碰撞","动能守恒","速率"]},{"title":"速度方向转角","type":"几何关系","judge":"判断小球在顶点处碰前与碰后速度方向之间的夹角","why":"轨迹是圆内接正四边形，每次碰撞后沿下一条弦运动，速度方向偏转角由正四边形的内角（或弦与切线的夹角）决定，取错角就算错 Δp","do":"由内接正四边形顶角 90° 及反射对称，求出速度方向改变角","expr":"\\theta=90^\\circ","cues":["看内接四边形内角","反射对称","转角是九十度"],"concepts":["圆内接正四边形","反射定律","速度偏转角"]},{"title":"动量变化量大小","type":"数学处理","judge":"由等大矢量夹角求动量变化量的大小","why":"碰前碰后动量大小相等、方向夹角为 θ，Δp 是两矢量的差，须用矢量三角形或余弦定理，不能直接相减","do":"用 |Δp|=2mv sin(θ/2) 计算","expr":"|\\Delta\\vec{p}|=2mv\\sin\\frac{\\theta}{2}","cues":["矢量三角形","等大矢量作差","用半角公式"],"concepts":["矢量合成","余弦定理","动量变化量"]},{"title":"比值与选项比对","type":"结论整理","judge":"把求得的无量纲比值与各选项的数值形式比对，判断哪个选项在数值上吻合","why":"题目只给几何图形未给具体数值，选项以含根号的常数形式给出，需把 2sin(θ/2) 化简成最简根式再对照","do":"代入 θ=90° 得比值，化简后与选项比较","expr":"\\frac{|\\Delta\\vec{p}|}{|\\vec{p}|}=2\\sin\\frac{\\theta}{2}=\\sqrt{2}","cues":["化简成根号","和选项对数值","只有一项吻合"],"concepts":["最简根式","比值"]}],"85":[{"title":"读电容标识","type":"图像读取","judge":"从电容器外壳标识上读出电容值与单位，判断是微法还是皮法量级","why":"电容器的标称值直接印在外壳上，单位换算关系决定最终数值","do":"读图2外壳上的数字与单位符号，按 1 μF = 10⁻⁶ F 换算","expr":"C = \\text{标识值} \\times 10^{-6}\\ \\mathrm{F}","cues":["看外壳数字","单位是微法","换算成法拉"],"concepts":["电容","单位换算"]},{"title":"公共端接法","type":"模型选择","judge":"判断单刀双掷开关哪个接线柱是公共端（动触点），导线 a 应接公共端还是定触点","why":"只有把电源-电阻-电流表支路接到公共端，开关掷向两侧才能分别构成充电回路和放电回路","do":"对照图1电路与图3实物，找出开关的动触点接线柱，把 a 端接到该柱","expr":"","cues":["找公共端","动触点","一边充电一边放电"],"concepts":["单刀双掷开关","电路连接"]},{"title":"先录像后合闸","type":"实验操作","judge":"判断录像开始与开关掷向 b 的先后顺序，以及何时停止录像","why":"充电开始瞬间电流最大、变化最快，晚开录像会丢掉起始段数据，无法完整记录 I-t 全过程","do":"先打开手机录像，再把开关掷向 b 开始充电，待电流表示数趋于 0 后停止录像","expr":"","cues":["先录再合闸","开头最快不能丢","电流为零再停"],"concepts":["实验步骤","数据采集"]},{"title":"放电电流走向","type":"关系建立","judge":"判断 t₁ 时刻后是放电过程，电流随电荷量、电压减小而如何变化","why":"电容器放电时极板电荷量减少、极板电压降低，回路由 I=U/R 决定电流，故电流逐渐减小且减小变慢，趋于零","do":"由 q=CU、U=IR 得 I 随 q 减小而减小，画出 t₁ 后单调下降并趋近横轴的曲线","expr":"I=\\frac{U}{R}=\\frac{q}{CR}","cues":["放电电流变小","越来越慢","最后趋于零"],"concepts":["电容放电","欧姆定律"]},{"title":"铝框电磁阻尼","type":"结论整理","judge":"判断铝框在磁场中转动是否产生感应电流、该电流受安培力是否阻碍转动","why":"铝框是导体，随指针在磁场中转动切割磁感线产生感应电流，安培力方向阻碍相对运动，形成电磁阻尼使指针快速稳定","do":"用楞次定律判定感应电流方向与安培力方向，说明阻尼作用，从而同意小明的观点","expr":"","cues":["铝框切割磁感线","产生感应电流","安培力阻碍转动","电磁阻尼"],"concepts":["电磁感应","楞次定律","电磁阻尼"]}],"86":[{"title":"判断过程为等温","type":"前提判断","judge":"两状态温度相同是否意味着整个过程温度不变、可当作等温过程处理","why":"题设给出初末温度相同，理想气体内能只由温度决定，等温是使用内能不变和玻意耳定律的前提","do":"比较初末两状态的温度，确认温度相同，把过程定性为等温压缩","expr":"T_1=T_2","cues":["温度相同","等温过程","内能不变"],"concepts":["等温过程","理想气体内能"]},{"title":"内能变化为零","type":"关系建立","judge":"等温过程中气体内能变化量取零还是取其他值","why":"理想气体忽略分子势能，内能仅是温度的函数，温度不变则内能不变","do":"写出内能变化为零，为热力学第一定律中消去内能项做准备","expr":"\\Delta U=0","cues":["理想气体内能只看温度","内能增量为零"],"concepts":["理想气体内能","温度"]},{"title":"第一定律符号约定","type":"关系建立","judge":"外界对气体做功与气体吸放热在热力学第一定律中取什么正负号","why":"热力学第一定律的符号约定决定功和热的正负，符号取反会得到相反的热量结论","do":"统一取吸热为正、内能增加为正、气体对外做功为正，把外界对气体做功写成负值代入","expr":"Q=\\Delta U+W_{\\text{对外}}=-W_{\\text{外界}}","cues":["外界做功取负","吸热为正","放热写负号"],"concepts":["热力学第一定律","符号约定"]},{"title":"由功求放出热量","type":"关系建立","judge":"放出的热量与外界做功在数值上是什么关系","why":"内能不变时，外界对气体做的功全部以热量形式放出，二者数值相等","do":"将内能变化为零代入第一定律，解出热量并说明负号表示放热","expr":"Q_{\\text{放}}=-Q=W_{\\text{外界}}","cues":["功全变成热","放热量等于外界做功"],"concepts":["热力学第一定律","等温过程"]},{"title":"选用玻意耳定律","type":"模型选择","judge":"求另一状态压强该用玻意耳定律还是理想气体状态方程","why":"一定质量理想气体在温度不变时压强与体积成反比，正是玻意耳定律的适用条件","do":"对初末两状态列压强与体积的反比关系","expr":"p_1V_1=p_2V_2","cues":["等温用玻意耳","压强体积反比"],"concepts":["玻意耳定律","等温变化"]},{"title":"体积比代入求压强","type":"数学处理","judge":"用初态压强乘体积之比还是乘体积反比来求末态压强","why":"由玻意耳定律解出p_2=p_1V_1/V_2，体积缩小则压强增大，可检验结果方向","do":"把已知的初态压强和两状态体积代入体积比式，算出末态压强","expr":"p_2=\\frac{p_1V_1}{V_2}","cues":["体积变小压强变大","乘体积之比"],"concepts":["玻意耳定律","体积比"]}],"87":[{"title":"向心加速度的半径取值","type":"模型选择","judge":"求最高点向心加速度时，圆周运动的半径该取桥面圆弧半径还是别的量","why":"汽车沿拱形桥面做圆周运动，轨迹半径就是桥面圆弧半径，向心加速度由轨迹曲率决定","do":"确认轨迹为半径 R 的圆弧，把 R 直接代入向心加速度公式","expr":"a=\\frac{v^{2}}{R}","cues":["半径就是桥的半径","用速度平方除以半径"],"concepts":["圆周运动","向心加速度"]},{"title":"最高点受力分解方向","type":"关系建立","judge":"最高点处把合力分解到水平（切向）和竖直（法向）两个方向，各方向分别对应什么效果","why":"汽车在最高点速度沿水平切向，向心加速度竖直向下指向圆心，故法向合力提供向心力，切向合力改变速率","do":"沿水平切向和竖直法向建坐标，把牵引力、阻力归入切向，把重力、支持力归入法向","expr":"","cues":["速度是水平的","向心加速度朝下","分水平和竖直看"],"concepts":["受力分析","正交分解","向心力"]},{"title":"合力用矢量合成而非代数相加","type":"数学处理","judge":"总合力是切向合力与法向合力的矢量和，不能把两者直接相加或只取其中一个","why":"切向合力与法向合力互相垂直，合力大小须按勾股定理合成","do":"先分别求出水平方向合力和竖直方向合力，再用勾股定理求总合力","expr":"F=\\sqrt{F_{x}^{2}+F_{y}^{2}}","cues":["两个方向垂直","用勾股定理合成","不能直接相加"],"concepts":["合力","矢量合成"]},{"title":"竖直方向用牛顿第二定律","type":"关系建立","judge":"竖直方向合力等于重力与支持力之差，且等于质量乘向心加速度，而不是等于零","why":"汽车在最高点有竖直向下的向心加速度，竖直方向并非平衡状态","do":"对竖直方向列牛顿第二定律方程，用重力减去支持力等于 ma","expr":"mg-N=ma","cues":["竖直方向不平衡","重力减支持力","等于质量乘加速度"],"concepts":["牛顿第二定律","向心力"]},{"title":"牵引力与阻力的合力","type":"关系建立","judge":"水平切向合力是牵引力与阻力之差，方向沿牵引力方向","why":"牵引力与阻力都沿切线且方向相反，切向合力决定速率变化","do":"把牵引力减去阻力得到水平方向合力","expr":"F_{x}=F_{\\text{牵}}-f","cues":["牵引力减阻力","水平方向合力"],"concepts":["切向合力","阻力"]}],"88":[{"title":"弹性正碰定A初速","type":"模型选择","judge":"B与A的碰撞该用哪组守恒方程、碰后A的速度取哪个解","why":"题设明确为弹性正碰，动量与动能同时守恒，且碰后A沿细杆方向获得速度","do":"对B、A列动量守恒与动能守恒，联立解出碰后A的速度，舍去不合物理意义的解","expr":"Mv_0=Mv_B+mv_A,\\ \\frac12Mv_0^2=\\frac12Mv_B^2+\\frac12mv_A^2","cues":["弹性正碰","动量动能都守恒","取碰后A的速度"],"concepts":["弹性碰撞","动量守恒","动能守恒"]},{"title":"碰后系统选整体","type":"模型选择","judge":"求弹簧最大势能时把哪些球取作一个系统","why":"A与两球通过弹簧相互作用，水平方向无外力，只有取三者整体动量才守恒；弹簧最大势能对应三者共速","do":"把A与两小球取为系统，列水平方向动量守恒，再列初末动能与弹性势能的能量关系","expr":"mv_A=(m+2m')v_{\\text{共}},\\ \\frac12mv_A^2=\\frac12(m+2m')v_{\\text{共}}^2+2E_p","cues":["取整体","三者共速时势能最大","两根弹簧各一份"],"concepts":["整体法","动量守恒","弹性势能"]},{"title":"共速判最大势能","type":"临界条件","judge":"弹簧形变量最大（弹性势能最大）出现在什么运动状态","why":"弹簧伸长过程中A减速、两球加速，相对速度为零时形变量不再增大，此刻势能取极大","do":"令A与两小球速度相等，作为能量方程的末态","expr":"v_A=v_1=v_2=v_{\\text{共}}","cues":["相对速度为零","共速时形变最大","速度相等那一刻"],"concepts":["临界状态","相对速度","最大弹性势能"]},{"title":"恢复原长用简谐周期","type":"关系建立","judge":"弹簧再次恢复原长所经历的时间由什么决定","why":"碰后A与两球在弹簧作用下做相对简谐运动，弹簧从原长到再次原长对应一个完整周期","do":"写出相对运动周期，取弹簧再次恢复原长的时间等于一个周期","expr":"T=2\\pi\\sqrt{\\frac{\\mu}{k}},\\ \\mu=\\frac{m\\cdot2m'}{m+2m'}","cues":["相对简谐运动","一个周期","折合质量"],"concepts":["简谐运动","周期","折合质量"]},{"title":"B追上A的位移条件","type":"几何关系","judge":"弹簧恢复原长时B恰能与A再次碰撞，需要满足什么位移关系","why":"B碰后匀速、A在弹簧力作用下做变速运动，能否再碰取决于同一时间内两者沿杆方向的位移是否相等","do":"分别写出B的匀速位移与A的位移（用动量守恒对时间求和得到平均速度关系），令两者相等","expr":"v_B T=\\bar v_A T,\\ \\bar v_A=\\frac{m v_A+2m'\\bar v}{m+2m'}","cues":["同时间位移相等","B匀速追A","用平均速度"],"concepts":["匀速运动","平均速度","追及条件"]},{"title":"质量比取值取舍","type":"数学处理","judge":"解出的质量比中哪个符合“恰能碰撞”的物理情形","why":"恰能碰撞对应追及方程有唯一合理正根，需检验根的正负与大小关系","do":"联立位移条件与速度关系解出m/M，舍去非正或与题设矛盾的值","expr":"\\frac{m}{M}=\\text{由 }v_B T=\\bar v_A T\\text{ 解出的正根}","cues":["取正根","检验能否追上","恰能碰撞"],"concepts":["方程求解","结果检验"]}],"89":[{"title":"区分位移与路程","type":"前提判断","judge":"要判断题目问的是位移大小还是路程（运动轨迹总长）","why":"位移是矢量，只看初末位置的有向线段；路程是标量，累加实际路径长度，两者对往复运动结果完全不同","do":"读题干关键词“位移大小”，确认不需求路径长度，排除按每次举高高度累加的思路","expr":"","cues":["看位移不是路程","别算路径长","位移只看首尾"],"concepts":["位移","路程","矢量与标量"]},{"title":"确定初末位置关系","type":"关系建立","judge":"要判断重复10次后哑铃的末位置与初始位置是否重合","why":"每次都是从原位置举高再回到原位置，一个完整循环后位置复原，重复任意次末位置仍与初位置重合","do":"把10次往复看成一个整体过程，只比较整个过程起点和终点位置","expr":"","cues":["首尾重合","回到原位置","起点终点一样"],"concepts":["初位置","末位置","位置变化"]},{"title":"由初末位置求位移","type":"结论整理","judge":"要判断初末位置重合时位移大小为多少","why":"位移大小等于初位置到末位置的有向线段长度，初末重合则有向线段长度为零，与举高高度和次数无关","do":"用初末位置重合直接得出位移大小为零，据此排除把高度乘次数的干扰项","expr":"","cues":["重合就是零","有向线段长度为零","跟高度无关"],"concepts":["位移的大小","有向线段"]}],"90":[{"title":"导热管温度跟随外界","type":"前提判断","judge":"封闭气体温度是否随外界温度同步下降","why":"U形管导热良好，气体与外界无隔热，热平衡后气体温度等于外界温度","do":"由外界温度下降直接判定封闭气体温度降低","expr":"T\\downarrow","cues":["导热良好","温度跟着降","和外界一样"],"concepts":["热平衡","导热"]},{"title":"右升则左降定体积","type":"几何关系","judge":"右侧液面上升时左侧气柱长度如何变化","why":"水银总体积不变，U形管粗细均匀，右臂液面上升的高度等于左臂液面下降的高度，左臂气柱变长","do":"比较左右两臂液面高度变化，得出左管气柱长度增大","expr":"\\Delta h_{\\text{右}}=\\Delta h_{\\text{左}},\\quad V\\uparrow","cues":["水银总量不变","右边升左边降","气柱变长"],"concepts":["体积守恒","U形管液面关系"]},{"title":"由状态方程定压强","type":"关系建立","judge":"温度降低、体积增大时封闭气体压强如何变化","why":"理想气体状态方程把压强、体积、温度三者联系起来，单独看T或V都不能定压强","do":"对封闭气体列状态方程，比较初末状态的pV/T，判断压强变化","expr":"\\dfrac{pV}{T}=C","cues":["用状态方程","看压强怎么变","三个量一起看"],"concepts":["理想气体状态方程"]},{"title":"内能与平均动能看温度","type":"结论整理","judge":"内能和分子平均动能由哪个量决定","why":"理想气体无分子势能，内能和分子平均动能都只由温度决定","do":"由温度降低直接判定内能减小、平均动能减小","expr":"U=U(T),\\ \\bar{E}_k\\propto T","cues":["理想气体无势能","只看温度","温度降都变小"],"concepts":["理想气体内能","分子平均动能"]},{"title":"分子数密度看体积","type":"关系建立","judge":"分子数密度由分子总数和体积如何决定","why":"气体质量一定则分子总数不变，数密度等于总数除以体积","do":"由体积增大、分子总数不变判定数密度减小","expr":"n=\\dfrac{N}{V}","cues":["分子总数不变","体积变大","数密度变小"],"concepts":["分子数密度"]}],"91":[{"title":"识别双缝的来源","type":"模型选择","judge":"判断这套装置里起双缝作用的是哪两个透光区域","why":"金属丝本身不透光，它只是把狭缝中央挡住，真正让光通过并发生干涉的是金属丝两侧剩下的两条窄缝，所以这是双缝干涉而非单缝衍射","do":"把金属丝看成挡光障碍，把狭缝被金属丝遮住后剩下的左右两条空隙看成两个相干光源","expr":"","cues":["金属丝两侧透光","不是单缝衍射","两条缝在两边"],"concepts":["双缝干涉","相干光源"]},{"title":"确定双缝间距的几何关系","type":"几何关系","judge":"判断双缝间距 d 与狭缝总宽 W、金属丝直径 D 之间的几何关系","why":"两透光缝的中心分别位于金属丝两侧空隙的中央，缝心间距等于总宽减去金属丝直径，而不是等于直径本身","do":"画出狭缝截面，用总宽 W 减去金属丝直径 D 得到两缝中心距","expr":"d=W-D","cues":["缝间距等于总宽减直径","不是直接用直径","两缝中心量起"],"concepts":["双缝间距","几何关系"]},{"title":"判断膨胀对缝间距的影响","type":"前提判断","judge":"判断金属丝受热均匀膨胀后直径 D 变大时，双缝间距 d 是变大还是变小","why":"狭缝总宽 W 由挡板固定不变，D 增大则 W−D 减小，缝间距随之变小，这一步方向判断反了整题就错","do":"对 d=W−D 作变化分析，D 增大则 d 减小","expr":"D↑ ⇒ d=W-D↓","cues":["直径变大缝间距变小","总宽不变","缝被挤窄了"],"concepts":["热膨胀","双缝间距变化"]},{"title":"用条纹间距公式定方向","type":"关系建立","judge":"判断条纹间距 Δx 随缝间距 d 减小而如何变化","why":"双缝干涉条纹间距与缝间距成反比，d 减小则 Δx 增大，这是判断选项正误的唯一依据","do":"写出条纹间距公式，把 d 减小代入看 Δx 的变化趋势","expr":"Δx=\\frac{L}{d}\\lambda","cues":["间距和缝距成反比","缝距变小条纹变宽","用条纹间距公式"],"concepts":["双缝干涉条纹间距","反比关系"]}],"92":[{"title":"圆轨道速度由引力提供","type":"关系建立","judge":"变轨前碎片做匀速圆周运动，其速度大小该由哪个力决定","why":"圆轨道上只有万有引力提供向心力，不能用能量守恒或冲量求初速度","do":"对变轨前的圆轨道列万有引力等于向心力的方程，解出速度平方","expr":"G\\frac{Mm}{r^2}=m\\frac{v_0^2}{r}\\Rightarrow v_0^2=\\frac{GM}{r}","cues":["万有引力当向心力","先求原速度"],"concepts":["万有引力定律","向心力"]},{"title":"冲量只改变径向速度","type":"模型选择","judge":"冲量方向与原速度垂直且沿径向，它使哪个速度分量发生变化","why":"冲量沿径向，只改变径向分速度，切向速度保持原值不变","do":"把速度分解为切向和径向，判断冲量只作用于径向分量","expr":"","cues":["冲量沿径向","切向速度不变"],"concepts":["动量定理","速度分解"]},{"title":"径向速度由动量定理求","type":"关系建立","judge":"冲量给碎片新增的径向速度大小如何确定","why":"瞬时冲量等于动量变化量，初径向速度为零，故冲量直接等于新增径向动量","do":"对冲量作用过程列动量定理，求出新增径向速度","expr":"I=mv_r\\Rightarrow v_r=\\frac{I}{m}","cues":["冲量等于动量变化","径向从零开始"],"concepts":["动量定理","冲量"]},{"title":"两垂直分量勾股合成","type":"几何关系","judge":"作用后瞬间的合速度与切向、径向两个分量是什么几何关系","why":"切向与径向互相垂直，合速度平方等于两分量平方和，不能直接代数相加","do":"用勾股定理把切向速度平方与径向速度平方相加得合速度平方","expr":"v^2=v_0^2+v_r^2=\\frac{GM}{r}+\\frac{I^2}{m^2}","cues":["两个方向垂直","用勾股定理合成"],"concepts":["速度合成","矢量合成"]},{"title":"动能用合速度平方表示","type":"结论整理","judge":"求的是冲量作用后瞬间的动能，该用哪个速度代入动能式","why":"动能由作用后瞬间的合速度决定，且要用合速度平方而非速度大小相加","do":"把合速度平方代入动能公式整理成选项形式","expr":"E_k=\\frac12 mv^2=\\frac{GMm}{2r}+\\frac{I^2}{2m}","cues":["用合速度算动能","别把速度直接相加"],"concepts":["动能","合速度"]}],"93":[{"title":"安培力随位置线性变化","type":"关系建立","judge":"要判断导体棒所受安培力大小随坐标 x 如何变化、方向指向哪里","why":"恒流源保证电流 I 恒定，B 随 x 线性变化，故 F=BIL 也随 x 线性变化；由左手定则，两侧磁场方向相反但安培力都指向交界点 O","do":"写出 F=BIL，代入 B=k|x|，得到 F 与 |x| 成正比，并确定方向始终指向 O","expr":"F=BIL=kIL|x|","cues":["电流恒定","安培力指向原点","B随位置变"],"concepts":["安培力","左手定则","恒流源"]},{"title":"等效弹簧模型","type":"模型选择","judge":"要判断这个变力作用下导体棒做什么运动，能否类比为简谐运动","why":"合力大小与到 O 点位移成正比、方向指向 O，正是回复力形式，可类比弹簧振子；不识别这一点就只能用微积分硬算","do":"把 F=kIL|x| 与 F=kx 对比，确认回复力系数，写出运动方程","expr":"F=-kIL\\,x","cues":["像弹簧振子","回复力","指向平衡位置"],"concepts":["简谐运动","回复力"]},{"title":"动能定理求速度","type":"关系建立","judge":"要判断从 x=0 到速度为零处，安培力做功如何计算","why":"安培力是变力，不能用 W=Fs，必须用 F-x 图线下面积或对 kIL|x| 积分求功","do":"对 F-x 图线下三角形面积积分，列动能定理方程求末速度或最大位移","expr":"-\\int_0^{x_m}kIL|x|\\,dx=0-\\tfrac12mv_0^2","cues":["变力做功","看图像面积","用动能定理"],"concepts":["动能定理","变力做功"]},{"title":"周期与初速度无关","type":"前提判断","judge":"要判断初速度改变后，第一次速度为零所需时间是否改变","why":"简谐运动的周期只由回复力系数和质量决定，与振幅（初速度）无关；只要仍做简谐运动，四分之一周期时间就不变","do":"写出圆频率 ω=√(kIL/m)，比较 T/4 与 v0 是否有关","expr":"T=2\\pi\\sqrt{\\frac{m}{kIL}}","cues":["周期与振幅无关","四分之一周期","时间不变"],"concepts":["简谐运动周期","圆频率"]},{"title":"判断能否往复运动","type":"临界条件","judge":"要判断初速度变为 2v0 后导体棒能否到达右侧磁场边界并离开","why":"若到达 x=2L 处速度仍大于零，棒将离开磁场不再受回复力，就不会以 O 为中心往复运动","do":"用动能定理算出棒到 x=2L 处的速度，判断其正负","expr":"\\tfrac12mv^2=\\tfrac12m(2v_0)^2-\\int_0^{2L}kIL|x|\\,dx","cues":["能否到达边界","速度是否为零","会不会离开磁场"],"concepts":["动能定理","临界条件"]}],"94":[{"title":"测力计读数规则","type":"实验操作","judge":"读数时要不要估读到分度值的下一位，还是只读到分度值所在位","why":"弹簧测力计刻度分度值为0.2N，指针恰好落在整刻度线上，按读数规范应读到与分度值相同的位数","do":"先由刻度确定分度值0.2N，再看指针位置对应的刻度数，按同位数写出读数","expr":"","cues":["看分度值","读到小数点后一位","指针正好在刻度上"],"concepts":["分度值","估读","弹簧测力计读数"]},{"title":"示数差异的归因","type":"误差分析","judge":"两测力计示数明显不同，是仪器本身（量程、弹簧材质）造成的，还是使用前未校准造成的","why":"牛顿第三定律保证相互作用力大小相等，正常工作的测力计示数应相同，差异只能来自仪器未调零等使用问题","do":"排除量程和弹簧材质对示数准确性的影响，锁定未调零这一操作缺陷","expr":"","cues":["作用力反作用力等大","量程不影响示数","没调零"],"concepts":["牛顿第三定律","仪器调零","系统误差"]}],"95":[{"title":"读图定波长","type":"图像读取","judge":"从波形图上相邻波峰（或波谷）的水平间距读出波长","why":"简谐横波的空间周期性：相邻波峰间距等于一个波长","do":"在图上找两个相邻波峰（或波谷），量出它们的横坐标之差","expr":"\\lambda = x_{\\text{峰2}}-x_{\\text{峰1}}","cues":["看相邻波峰","量峰到峰","一个波长"],"concepts":["波长","波形图"]},{"title":"波峰位置通式","type":"关系建立","judge":"把已知波峰的位置与波长、波传播方向联立，写出波峰坐标的通式","why":"波沿 x 轴正方向传播，波峰位置随传播不断右移，需用通式表示所有可能的波峰位置","do":"设波峰坐标为 x，写出 x 与波长、传播距离的关系，并引入整数参数","expr":"x = x_0 + n\\lambda\\ (n=0,1,2,\\dots)","cues":["波峰右移","加整数个波长","通式表示"],"concepts":["波的传播","空间周期性"]},{"title":"整数取值筛选","type":"数学处理","judge":"由通式解出整数参数，并判断哪些整数使波峰落在题目给定范围内","why":"题目限定了波峰坐标的取值范围，只有满足该范围的整数解才有效","do":"把通式代入范围不等式，解出整数 n 的取值，再逐个回代求波峰坐标","expr":"x_{\\min}\\le x_0+n\\lambda\\le x_{\\max}","cues":["解整数","落在范围内","逐个回代"],"concepts":["不等式","整数解"]},{"title":"路程判周期数","type":"关系建立","judge":"由质点在一段时间内通过的路程与振幅的比值，判断这段时间等于多少个周期","why":"简谐运动中质点在一个周期内通过的路程为 4 倍振幅，路程与振幅之比决定经历的周期数","do":"用路程除以振幅得到 4 的倍数关系，反推出时间与周期的比值","expr":"s = 4A\\cdot\\dfrac{t}{T}","cues":["一个周期走四倍振幅","路程比振幅","算几个周期"],"concepts":["简谐运动","振幅","周期"]},{"title":"波速公式联立","type":"关系建立","judge":"用波长和周期表示波速，把第(1)问的波长与第(2)问的周期联立求解","why":"波速由介质决定，满足 v=λ/T，是连接两问的桥梁","do":"将已求出的波长和周期代入波速公式，算出波速","expr":"v=\\dfrac{\\lambda}{T}","cues":["波长除周期","波速公式","两问联立"],"concepts":["波速","波长","周期"]}],"96":[{"title":"磁场中轨迹半径的几何确定","type":"几何关系","judge":"要判断粒子在梯形磁场中做圆周运动的圆心位置与半径，能否由入射垂直CD、出射平行CD且过CG中点O这两个条件唯一确定","why":"粒子垂直CD进入磁场、平行CD从O点射出，速度方向改变60°（CG与HG夹角60°），轨迹圆心必在过入射点垂直CD的直线上，也在过O点垂直出射方向的直线上，两线交点即圆心","do":"画出轨迹图，由入射点与O点的位置关系及速度方向偏转角，用几何关系求出半径R与CG边长的关系","expr":"R=\\frac{CG/2}{\\sin 60^\\circ}","cues":["画轨迹找圆心","速度偏转角等于圆心角","半径由几何定"],"concepts":["洛伦兹力","圆周运动","几何关系"]},{"title":"洛伦兹力提供向心力求比荷","type":"关系建立","judge":"要判断磁场中圆周运动的动力学方程用哪个，从而把半径R与速度v、比荷k联系起来","why":"磁场中只受洛伦兹力，洛伦兹力提供向心力，这是求比荷的唯一途径","do":"列向心力方程，把R代入，得到v与k、B、R的关系式","expr":"qvB=m\\frac{v^2}{R},\\quad k=\\frac{q}{m}=\\frac{v}{BR}","cues":["洛伦兹力当向心力","洛伦兹力","向心力","比荷"],"concepts":["洛伦兹力","向心力","比荷"]},{"title":"无场区与电场中运动的时间分解","type":"模型选择","judge":"要判断总时间t由哪几段组成，哪几段与α无关、哪一段随α变化，从而把图2的t-α关系对应到具体运动过程","why":"粒子经历加速电场、无场区、偏转电场三段，只有偏转电场中的运动时间随α（即PQ与MN的取向）变化，其余为常量t0","do":"分别写出无场区匀速直线时间、偏转电场中沿电场方向（法向）的匀变速运动时间，把总时间写成t=t0+t电(α)","expr":"t=t_0+\\frac{v_\\perp+\\sqrt{v_\\perp^2+2a d}}{a}","cues":["总时间分三段","只有电场那段随角度变","法向初速度反向"],"concepts":["匀速直线运动","匀变速直线运动","运动的分解"]},{"title":"偏转电场中法向初速度反向的判断","type":"前提判断","judge":"要判断粒子进入偏转电场时法向（垂直PQ方向）初速度与电场方向是相同还是相反，从而确定法向是做加速还是先减速再反向的运动","why":"粒子从O平行CD射出后经无场区进入PQ，速度方向与PQ成一定角度，电场垂直于PQ，需由几何判断法向分量指向电场反方向","do":"把进入电场时的速度分解为平行PQ和垂直PQ两个分量，确认法向分量与E反向，写出法向位移方程","expr":"v_\\perp=v\\sin\\theta,\\quad d=v_\\perp t-\\frac{1}{2}\\frac{qE}{m}t^2","cues":["法向先减速再返回","电场力与法向速度反向","垂直分量决定时间"],"concepts":["运动的分解","匀变速运动","电场力"]},{"title":"由图2极值条件定电压与比荷","type":"临界条件","judge":"要判断图2中t最小时对应什么物理条件（哪一项取极值），并据此建立第二个方程与磁场方程联立","why":"t(α)表达式中含与α有关的项，其最小值对应图2给出的最小时间，这是从图像读取定量信息的唯一入口","do":"对t(α)表达式用均值不等式或求导找极小值条件，读出图2中t的最小值及对应α，与向心力方程联立解出U和k","expr":"t_{\\min}=t_0+2\\sqrt{\\frac{2d}{a}},\\quad a=\\frac{qE}{m}","cues":["图2最低点对应极值","均值不等式求最小","联立两个方程"],"concepts":["极值条件","图像读取","联立方程"]},{"title":"用平均作用力求质量","type":"模型选择","judge":"要判断第三个可测物理量应选接收器受到的平均作用力（或等效的力/压强），并用动量定理把宏观可测量与单粒子动量变化率联系起来","why":"质量不能由运动学量单独确定，需借助与粒子数n和动量变化率相关的力学量，动量定理给出F与单个粒子动量变化及n的关系","do":"对Δt内打到接收器的nΔt个粒子用动量定理，写出F与单粒子质量、速度的关系，再结合(2)中已得的比荷消去速度求m","expr":"F=n\\,m\\,v_{\\text{法}},\\quad m=\\frac{F}{n\\,v_{\\text{法}}}","cues":["测接收器受力","动量定理连起来","用n把宏观和微观接上"],"concepts":["动量定理","平均作用力","粒子数"]}],"97":[{"title":"振幅与摆角的关系","type":"关系建立","judge":"拉开相同的小角度时，振幅（摆球离平衡位置的最大弧长或位移）是否随重力加速度改变","why":"振幅由初始释放条件决定，A≈lθ，摆长和释放角都没变，所以振幅不变；干扰项错在把振幅当成随g变化","do":"写出振幅与摆长、偏角的关系，比较地球与月球两种情况下的摆长和偏角","expr":"A=l\\theta","cues":["角度相同","摆长没变","振幅不变"],"concepts":["单摆","振幅","偏角"]},{"title":"周期随重力加速度变化","type":"前提判断","judge":"移到月球后重力加速度变小，周期是变大还是变小","why":"单摆周期公式 T=2π√(l/g)，l 不变而 g 减小，T 必然增大","do":"用周期公式比较地球与月球的 g，判断周期变化方向","expr":"T=2\\pi\\sqrt{\\frac{l}{g}}","cues":["月球重力小","周期变大","摆长不变"],"concepts":["单摆周期","重力加速度"]},{"title":"振动图像的坐标与起点","type":"图像读取","judge":"图像横轴表示时间、纵轴表示位移时，周期变大对应图像上什么变化，t=0 释放处的位移如何","why":"振动图像是 x-t 图，周期对应相邻两次同向过平衡位置的时间间隔，周期变大即波形在横轴上被拉宽；从最大位移处释放则 t=0 时位移为振幅","do":"看各选项图像的周期长短和 t=0 时的位移值，选出周期变长且起点在最大位移处的图","expr":"x=A\\cos\\left(\\frac{2\\pi}{T}t\\right)","cues":["看横轴时间","波形变宽","起点在最高点"],"concepts":["振动图像","周期","位移"]}],"98":[{"title":"确定入射光方向与法线","type":"几何关系","judge":"光垂直底边入射时，在底边（半圆直径）处是否发生折射，以及进入棱镜后沿什么方向传播","why":"光垂直于两种介质的分界面入射时入射角为零，不发生偏折，沿原方向直线传播；这是后续所有几何角度的起点","do":"画出过入射点垂直于底边的法线，确认入射光线与法线重合，进入棱镜后仍垂直于底边前进","expr":"","cues":["垂直入射不偏折","沿原方向走","法线就是底边垂线"],"concepts":["折射定律","法线","垂直入射"]},{"title":"判断出射点处的法线","type":"几何关系","judge":"出射点位于半圆弧上，该点的法线应取圆弧半径方向还是底边垂线方向","why":"光从棱镜射向空气的界面是圆弧面，界面法线是过该点的半径，不是底边的垂线；取错法线则入射角全错","do":"连接圆心与出射点，该连线即为出射界面的法线，量出光线与该半径的夹角作为入射角","expr":"","cues":["圆弧面法线沿半径","连圆心","别用底边垂线"],"concepts":["界面法线","圆弧面","半径方向"]},{"title":"用平行条件定偏向角","type":"关系建立","judge":"出射光线与入射光线平行这一条件，对应光在棱镜内两次偏折的总效果是什么","why":"入射光线方向已知（垂直底边），出射光线与之平行，说明两次折射的偏向相互抵消，可把出射角与内部几何角联系起来","do":"把入射光线方向平移到出射点作参考，由平行关系得出出射光线与法线的夹角（即出射角）等于内部光线与法线夹角所对应的几何角","expr":"","cues":["出射平行入射","偏向抵消","平移光线找角"],"concepts":["光路可逆","偏向角","平行条件"]},{"title":"由距离条件求几何角","type":"几何关系","judge":"入射点、出射点到三角形底边距离相等这一条件，能确定出射点在半圆上的位置及对应的圆心角/入射角","why":"两点等高说明它们在同一平行于底边的直线上，结合半圆半径可解出出射点半径与底边的夹角，从而得到界面入射角","do":"以底边为 x 轴建坐标，写出入射点与出射点纵坐标相等的方程，联立半圆方程解出出射点位置，再求半径与光线的夹角","expr":"","cues":["等高","同一水平线","联立半圆方程"],"concepts":["几何作图","半圆方程","等高条件"]},{"title":"折射定律求折射率","type":"关系建立","judge":"用哪一对角（空气中的角与棱镜中的角）代入折射定律，且正弦之比的方向不能颠倒","why":"折射率定义为空气中角的正弦与介质中角的正弦之比，取错角或颠倒比值会得到倒数或错误结果","do":"把上一步求得的出射角（空气中）与内部光线相对半径法线的角（介质中）代入 n=sin i/sin r 计算","expr":"$n=\\dfrac{\\sin i}{\\sin r}$","cues":["空气角比介质角","别取倒数","先定哪边是空气"],"concepts":["折射定律","折射率"]}],"99":[{"title":"环颗粒的向心力来源","type":"模型选择","judge":"判断土星环上颗粒做圆周运动的向心力由什么提供、中心天体取谁","why":"颗粒绕土星运动，万有引力提供向心力，中心天体是土星而不是土星环本身；若误把环当中心天体或引入其他力，方程就列错","do":"对环上中间颗粒列万有引力等于向心力的方程","expr":"G\\frac{Mm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["万有引力提供向心力","中心天体是土星","颗粒质量约掉"],"concepts":["万有引力定律","匀速圆周运动","向心力"]},{"title":"用密度替换土星质量","type":"关系建立","judge":"判断如何把未知的土星质量 M 用已知密度 ρ 和土星半径 R 表示","why":"题目只给密度和引力常量，M 未知，必须借球体体积公式把 M 换成 ρ 与 R，否则方程里多一个未知量解不出","do":"写出球体质量表达式并代入向心力方程","expr":"M=\\frac{4}{3}\\pi R^{3}\\rho","cues":["质量换成密度乘体积","球体体积公式","消去土星质量"],"concepts":["密度","球体体积"]},{"title":"从照片读轨道半径比","type":"图像读取","judge":"判断照片中土星环中间颗粒的轨道半径 r 与土星半径 R 的比值","why":"照片只提供几何比例信息，周期表达式中只剩 r/R 这个比值待定，读不出这个比例就无法得到数值结果","do":"在照片上量出土星半径与环中间颗粒到土星中心距离的比例","expr":"\\frac{r}{R}\\approx\\text{（由照片量出）}","cues":["量照片上的比例","环半径比土星半径","用图片估比值"],"concepts":["几何比例","轨道半径"]},{"title":"化简出周期只含密度与比值","type":"数学处理","judge":"判断联立后周期 T 是否只由 ρ、G 和 r/R 决定，与土星质量、颗粒质量无关","why":"只有把 T 化成这种形式，才能把已知密度和照片读出的比值直接代入；若保留 M 或 m 就无法算出数值","do":"将 M 的表达式代入向心力方程，解出 T 并整理成含 ρ、G、r/R 的形式","expr":"T=\\sqrt{\\frac{3\\pi}{G\\rho}\\left(\\frac{r}{R}\\right)^{3}}","cues":["周期与颗粒质量无关","只剩密度和半径比","开根号整理"],"concepts":["周期公式","万有引力提供向心力"]},{"title":"代入数据估算数量级","type":"数据处理","judge":"判断代入密度、引力常量和照片比值后得到的周期数量级，并与各选项比对","why":"选项之间是数量级差别，估算时若单位或开方处理出错就会选错档；干扰项正是错在比值取错或漏开立方","do":"把 ρ、G 与读出的 r/R 代入化简式，算出 T 的数值再对照选项","expr":"T=\\sqrt{\\frac{3\\pi}{G\\rho}\\left(\\frac{r}{R}\\right)^{3}}","cues":["代入数值","看数量级","和选项对档"],"concepts":["估算","数量级"]}],"100":[{"title":"分解初速度到两个方向","type":"模型选择","judge":"把水平初速度分解为垂直于网面和平行于网面两个分量，还是把整段运动当作单一平面内的平抛处理","why":"轨迹平面与网面成夹角，只有把初速度投影到垂直网面方向，才能直接得到球到网面的距离；不分解就找不到位移与速度的对应关系","do":"沿垂直网面方向取 v⊥=v0cosθ，沿平行网面方向取 v∥=v0sinθ，两方向独立处理","expr":"v_\\perp=v_0\\cos\\theta,\\quad v_\\parallel=v_0\\sin\\theta","cues":["先分解速度","垂直网面方向","平行网面方向"],"concepts":["运动的分解","平抛运动"]},{"title":"竖直方向定飞行时间","type":"关系建立","judge":"用竖直自由落体从击球点到擦网点的高度差求时间，而不是用水平位移求时间","why":"擦网点相对击球点的高度差已知，竖直方向初速度为零，是唯一能独立确定时间的方程","do":"对竖直方向列 h=½gt²，解出 t","expr":"h=\\tfrac12 g t^2","cues":["竖直方向自由落体","用高度差求时间","先求时间"],"concepts":["自由落体","运动学方程"]},{"title":"切线方向定竖直速度","type":"几何关系","judge":"把投影轨迹在擦网点的切线与网面上沿的夹角，对应到竖直分速度与平行网面分速度之比","why":"投影轨迹的切线斜率等于该点速度在投影平面内的两个分量之比，夹角给出这个比值，从而把已知角转化为速度关系","do":"写出 tanα=v_y/v∥，其中 v_y=gt，v∥=v0sinθ，联立求角或求时间","expr":"\\tan\\alpha=\\frac{v_y}{v_\\parallel}=\\frac{gt}{v_0\\sin\\theta}","cues":["切线斜率","竖直比平行","投影平面内看速度"],"concepts":["速度方向","斜率与夹角"]},{"title":"垂直网面方向求距离","type":"关系建立","judge":"击球点到网面的距离只由垂直网面方向的匀速运动决定，与平行网面分量无关","why":"垂直网面方向不受力、速度恒定，位移就是所求距离；平行分量只影响球沿网面的位置，不影响该距离","do":"用 d=v⊥t=v0cosθ·t 求距离，t 由前两步联立得出","expr":"d=v_0\\cos\\theta\\cdot t","cues":["垂直方向匀速","距离只看垂直分量","平行分量不影响距离"],"concepts":["匀速直线运动","分运动的独立性"]}],"101":[{"title":"选M为参考系","type":"模型选择","judge":"是否把问题转化为N相对M的运动，用间距变化代替两飞行器的绝对位移","why":"M匀速且速度不变，以M为参考系后N的相对运动只由N的加速度决定，间距数据直接就是相对位移，不必引入M的速度这个未知量","do":"令间距s(t)为N相对M的位置坐标，把表中间距逐差得到每2s的相对位移","expr":"s(t)=x_N(t)-x_M(t)","cues":["取M作参考","看间距变化","不用管M速度"],"concepts":["参考系","相对运动"]},{"title":"由逐差判定两段匀变速","type":"前提判断","judge":"相邻相等时间内相对位移的差值是否恒定，从而判断哪段时间是匀加速、哪段时间是匀减速","why":"匀变速直线运动在连续相等时间间隔内的位移差为常量aT²，只有差值恒定才能用匀变速公式，否则不能套用","do":"算出各2s内的相对位移，再求相邻两段位移之差，看0~8s与10~20s内差值是否各自恒定","expr":"Δs=s_{n+1}-s_n=aT^2","cues":["看位移差","差值一样就是匀变速","分两段看"],"concepts":["匀变速直线运动","逐差法"]},{"title":"定位加速转减速的时刻","type":"临界条件","judge":"速度最大（加速度由正变负）发生在哪两个时刻之间，不能默认在整2s的计时点上","why":"间距先增后减，间距最大处相对速度为零，而表格只给出偶数秒的数据，转折点在8s与10s之间，取整点会算错加速度和最大速度","do":"比较8s与10s的间距，判断间距最大值所在区间，据此确定加速段与减速段各自的时间跨度","expr":"v_{rel}=0 \\Leftrightarrow s \\text{ 取极大}","cues":["最大值在中间","不能取整秒","先增后减的拐点"],"concepts":["临界状态","相对速度"]},{"title":"分段列加速度方程","type":"关系建立","judge":"用哪段数据、以哪个时间起点列匀变速方程求两段加速度","why":"加速段与减速段加速度不同，必须分段用位移差公式或速度公式，混用会把两段当成一个匀变速过程","do":"对加速段用Δs=aT²求a₁，对减速段同法求a₂，再由转折时刻衔接两段","expr":"a_1=\\frac{\\Delta s_1}{T^2},\\quad a_2=\\frac{\\Delta s_2}{T^2}","cues":["分段求加速度","用位移差公式","两段加速度不同"],"concepts":["加速度","匀变速运动规律"]},{"title":"求相对速度最大值","type":"数学处理","judge":"如何由加速度和转折时刻算出相对速度的峰值，并判断它对应哪个时刻","why":"相对速度从初值按a₁增大到零加速度点再按a₂减小，峰值只由加速段时间与a₁决定，需用速度公式衔接","do":"由某已知时刻的相对速度加上a₁乘时间得到峰值，并核对峰值时刻是否落在8~10s内","expr":"v_{max}=v_0+a_1 t","cues":["速度加到最大","用速度公式","峰值在拐点"],"concepts":["速度公式","相对速度"]},{"title":"用间距差求瞬时间距","type":"关系建立","judge":"非计时点（如7s末）的间距要用相邻已知间距加该段相对位移求得，不能直接读表","why":"表格只给偶数秒数据，7s末介于6s与8s之间，需用该段匀变速的相对位移公式外推","do":"取6s时的间距，加上6~7s内的相对位移（用该段初速与加速度算）得到7s末间距","expr":"s(7)=s(6)+v_{rel}(6)\\cdot 1+\\tfrac12 a\\cdot 1^2","cues":["表里没有7秒","用6秒推","加一小段位移"],"concepts":["匀变速位移公式","相对位移"]}],"102":[{"title":"游标卡尺读数规则","type":"实验操作","judge":"判断游标卡尺是几分度、主尺读数取到哪条刻线、游标第几条刻线与主尺对齐","why":"游标卡尺读数=主尺整毫米数+对齐格数×精度，精度由游标总格数决定，读错格数或精度直接使宽度值错","do":"先数游标总格数确定精度，再读主尺游标零刻线左侧的整毫米数，最后找游标上与主尺刻线对齐的那一条，按精度换算后相加","expr":"d=\\text{主尺读数}+n\\times\\text{精度}","cues":["数游标格数","看哪条对齐","精度是零点零几"],"concepts":["游标卡尺","精度","读数"]},{"title":"平均速度代瞬时速度","type":"近似条件","judge":"判断能否用遮光时间内的平均速度代表滑块经过光电门时的瞬时速度","why":"遮光条宽度很小、挡光时间极短，这段时间内速度变化可忽略，平均速度才近似等于瞬时速度；不取这个近似就无法由计时器读数得到速度","do":"用遮光条宽度除以遮光时间求平均速度，并确认遮光条越窄该近似越好","expr":"v=\\frac{d}{\\Delta t}","cues":["时间很短","用平均速度代替","遮光条要窄"],"concepts":["瞬时速度","平均速度","极限思想"]},{"title":"选速度位移关系求加速度","type":"关系建立","judge":"判断用哪组已知量（两光电门速度、间距）来求加速度，而不是用时间或力","why":"两光电门间距和两端速度已知，匀变速直线运动中速度平方差与位移成正比，无需知道下滑时间","do":"对滑块从光电门1到光电门2的过程列速度位移公式，解出加速度","expr":"v_2^2-v_1^2=2aL\\ \\Rightarrow\\ a=\\frac{v_2^2-v_1^2}{2L}","cues":["用速度平方差","不用时间","两门间距"],"concepts":["匀变速直线运动","速度位移关系"]},{"title":"垫高求倾角正弦","type":"几何关系","judge":"判断导轨倾角的正弦该用垫高与支脚间距（斜面长度）之比，而不是垫高与水平投影之比","why":"气垫导轨两支脚间距是斜面的长度，垫高是斜面高度，由直角三角形定义 sinθ=高度/斜面长","do":"画出导轨与水平面的直角三角形，用垫高除以支脚间距表示 sinθ","expr":"\\sin\\theta=\\frac{h}{s}","cues":["间距是斜面长","垫高是高度","别用水平距离"],"concepts":["斜面","几何关系","正弦"]},{"title":"沿斜面列牛顿第二定律","type":"模型选择","judge":"判断理论加速度由重力沿斜面的分力提供（气垫导轨近似无摩擦），据此写出理论表达式","why":"气垫导轨使滑块与导轨间摩擦可忽略，沿斜面方向只有重力分量 mg sinθ，由牛顿第二定律得 a=g sinθ","do":"对滑块沿斜面方向受力分析，把 sinθ=h/s 代入得理论加速度","expr":"ma=mg\\sin\\theta\\ \\Rightarrow\\ a=g\\frac{h}{s}","cues":["气垫无摩擦","只有重力分量","理论值"],"concepts":["牛顿第二定律","重力分量","气垫导轨"]},{"title":"比较实测与理论值","type":"结论整理","judge":"判断验证成功与否要看测得的加速度与理论加速度在误差范围内是否相等，而非看某一个速度或时间","why":"实验目的是验证牛顿第二定律，定律给出 a 与倾角的定量关系，只有两个加速度相符才算验证","do":"把(3)中由速度位移关系算出的 a 与 g h/s 比较，看在误差允许范围内是否相等","expr":"\\frac{v_2^2-v_1^2}{2L}\\approx g\\frac{h}{s}","cues":["比两个加速度","误差范围内相等","验证成功"],"concepts":["实验验证","误差允许范围"]}],"103":[{"title":"确定氮气为研究对象","type":"模型选择","judge":"把气腔内的氮气（而非油或皮囊）选作研究对象，并确认其质量在泵油过程中不变","why":"玻意耳定律只适用于一定质量的理想气体；油体积变化只是改变了氮气所占体积，氮气本身没有漏出","do":"明确封闭气体为气腔内的氮气，写出初态（p1、V1）与末态（p2、V2）两组状态参量","expr":"","cues":["取氮气为对象","气体质量不变","别把油算进去"],"concepts":["理想气体","封闭气体","质量一定"]},{"title":"判定泵油为等温过程","type":"前提判断","judge":"判断泵油过程中氮气温度保持不变，从而可用玻意耳定律而非状态方程","why":"题设明确泵油过程为等温过程，且温度不变时 pV=常量，质量不变时无需引入温度","do":"确认 T 不变、m 不变，选用 p1V1=p2V2 建立初末态联系","expr":"p_1V_1=p_2V_2","cues":["等温变化","温度不变","用玻意耳定律"],"concepts":["玻意耳定律","等温变化"]},{"title":"体积差对应泵出油量","type":"关系建立","judge":"判断泵出油的体积等于氮气体积的减少量，而不是氮气末体积本身","why":"油腔与气腔通过皮囊分隔，油泵出使皮囊膨胀、气腔体积增大，油体积变化与气腔体积变化相等","do":"由等温方程解出末态气腔体积 V2，再求泵出油体积 ΔV=V2−V1","expr":"\\Delta V=V_2-V_1=\\frac{p_1V_1}{p_2}-V_1","cues":["体积差就是油量","用末体积减初体积"],"concepts":["体积变化","等温膨胀"]},{"title":"补气后总量守恒的处理","type":"模型选择","judge":"判断补气后气腔内气体是“原有气体+补充气体”的混合整体，需对总质量用状态方程，而不是只对原有气体用","why":"补气改变了气体质量，玻意耳定律不再适用于总气体，必须用含质量（或物质的量）的理想气体状态方程","do":"对补气后总气体列 pV=nRT，求出总物质的量，再减去原有氮气物质的量得到补充量","expr":"p_2V_1=n_{\\text{总}}RT_2","cues":["补气后质量变了","不能再用玻意耳","对总气体列状态方程"],"concepts":["理想气体状态方程","物质的量"]},{"title":"同温同压质量比转体积比","type":"关系建立","judge":"判断补充质量与原有质量之比可转化为同温同压下气体体积之比，避免直接算摩尔数","why":"同温同压下理想气体摩尔体积相同，质量比等于物质的量比，也等于同温同压下的体积比","do":"把原有氮气换算到补气后的温度与压强下求其体积，与气腔体积作比得质量比","expr":"\\frac{\\Delta m}{m_0}=\\frac{V_1-V_0'}{V_0'}","cues":["同温同压比体积","质量比等于体积比","把原有气体换算过去"],"concepts":["阿伏加德罗定律","摩尔体积"]}],"104":[{"title":"球壳碰天花板后反向","type":"前提判断","judge":"球壳与天花板弹性碰撞后，速度是否等大反向、小球速度是否不变","why":"天花板质量极大且碰撞弹性、时间极短，球壳速度反向大小不变；小球未参与该碰撞，速度连续","do":"先算抛出到碰天花板时两者共同速度，再令球壳速度反号、小球速度保持原值，作为后续追及问题的初态","expr":"v^2=v_0^2-2g(H-h),\\quad v_{\\text{壳}}'=-v,\\ v_{\\text{球}}'=v","cues":["碰天花板只反弹壳","小球速度不变","弹性碰等速反弹"],"concepts":["弹性碰撞","竖直上抛","速度连续性"]},{"title":"用相对位移定小球直径","type":"几何关系","judge":"碰后到第一次球壳-小球碰撞，两者位移之和对应哪段几何长度","why":"球壳下端与小球顶端初始相距 D-d，球壳向下、小球向上相向运动，路程之和恰等于这段间隙","do":"分别写出球壳向下和小球向上的位移，令两者之和等于 D 减 d，解出 d","expr":"\\tfrac12 g t^2+v t+v t-\\tfrac12 g t^2=D-d","cues":["相向走完间隙","位移和等于间隙","间隙是直径差"],"concepts":["相对位移","运动学公式","几何约束"]},{"title":"弹性碰撞用相对速度结论","type":"关系建立","judge":"两球弹性碰撞后，是否需要解动量与能量方程组，还是可直接用相对速度反向","why":"一维弹性碰撞中质心系速度反向，碰前后相对速度大小不变、方向相反，可绕过质量比未知的困难","do":"对第一次碰撞，用碰前两速度求相对速度，碰后相对速度取等大反向，直接得速度差","expr":"u_{\\text{rel}}'=-u_{\\text{rel}},\\quad |\\Delta v'|=|\\Delta v|","cues":["相对速度反向","不用解质量","恢复系数为一"],"concepts":["弹性碰撞","相对速度","恢复系数"]},{"title":"两次碰撞间相对运动为匀速","type":"模型选择","judge":"碰后两者都只受重力，相对加速度是否为零、相对速度是否恒定","why":"球壳与小球加速度均为 g 向下，相对加速度为零，相对速度保持不变，故时间间隔由相对位移除以相对速率得到","do":"取碰后相对速度大小，令其乘时间间隔等于下一次相遇所需的相对位移（同向追及为 D-d）","expr":"\\Delta t=\\frac{D-d}{|u_{\\text{rel}}|}","cues":["相对加速度为零","相对速度不变","间距除以相对速度"],"concepts":["相对运动","匀变速直线运动","追及相遇"]},{"title":"逐次碰撞递推球壳速度","type":"数学处理","judge":"每次碰撞后球壳速度改变量大小是否恒定、方向如何随快慢关系翻转","why":"弹性碰撞使相对速度反向，球壳速度改变量由质量比决定且大小固定；碰前谁快决定壳被减速还是加速，两次碰撞间重力再给壳加速 gΔt","do":"从第一次碰前速度出发，交替做“加减固定改变量”和“加重力增量”，列出第 8 次碰前速度表达式并与已知 6 m/s 对照","expr":"v_{n+1}=v_n\\pm\\Delta v+g\\Delta t","cues":["每次改变量一样","快慢决定加减","中间加重力增量"],"concepts":["弹性碰撞","递推关系","速度改变量"]},{"title":"分段累加定位触地时刻","type":"临界条件","judge":"球壳何时首次触地，需逐段判断每次碰撞后运动方向与位移，累加到质心高度降为零","why":"球壳速度方向多次翻转，不能整体用一段匀变速；触地临界是球壳最低点（质心高度）到达地面","do":"用每段初速度和 0.1 s 时间算位移，带符号逐段累加球壳位置，找到跨过触地高度的那一段，再对该段用速度位移公式求落地速度","expr":"s_n=v_n\\Delta t+\\tfrac12 g\\Delta t^2,\\quad v^2=v_n^2+2g s","cues":["逐段累加位置","质心到地为零","最后一段用速度位移"],"concepts":["分段运动","临界条件","速度位移公式"]}],"105":[{"title":"判断速度方向是否变化","type":"前提判断","judge":"机器人沿弯道奔跑时，速度方向是否发生改变","why":"速度是矢量，方向改变即速度改变，由加速度定义可知速度变化必有加速度","do":"分析转弯过程中速度矢量的方向是否随轨迹切线方向改变","expr":"\\vec{a}=\\frac{\\Delta\\vec{v}}{\\Delta t}\\neq 0","cues":["转弯方向变了","速度是矢量","有加速度"],"concepts":["速度的矢量性","加速度"]},{"title":"判断能否视为质点","type":"模型选择","judge":"研究奔跑姿态时能否忽略机器人的大小和形状","why":"质点模型要求物体的大小形状对所研究问题无影响，研究姿态必须关注肢体动作","do":"比较研究目的（姿态细节）与忽略形状后的信息损失","expr":"","cues":["看姿态不能忽略形状","质点要形状可忽略","动作细节重要"],"concepts":["质点","理想化模型"]},{"title":"区分路程与位移","type":"关系建立","judge":"21.0975 km 是轨迹长度还是初末位置的有向距离","why":"马拉松路线为曲线，轨迹长度是路程，只有直线单向运动时路程才等于位移大小","do":"判断比赛路线是否为曲线，比较路程与位移大小的关系","expr":"s_{\\text{路程}}\\geq|\\Delta\\vec{r}|","cues":["路线是弯的","轨迹长度是路程","位移看首末位置"],"concepts":["路程","位移"]},{"title":"区分平均速率与平均速度","type":"关系建立","judge":"路程与时间的比值对应平均速率还是平均速度大小","why":"平均速度是位移与时间的比值，平均速率是路程与时间的比值，曲线运动中二者不等","do":"写出两个定义式并比较分母相同的两个比值","expr":"\\bar{v}=\\frac{\\Delta\\vec{r}}{\\Delta t},\\quad \\text{平均速率}=\\frac{s}{\\Delta t}","cues":["路程比时间","位移比时间","两个不一样"],"concepts":["平均速度","平均速率"]},{"title":"判断参考系选择的影响","type":"模型选择","judge":"以冲刺机器人为参考系时裁判员是否静止","why":"参考系不同，物体的相对位置变化情况不同，运动描述具有相对性","do":"分析机器人与裁判员之间是否有相对位置变化","expr":"","cues":["选机器人作参考系","裁判相对机器人在动","运动是相对的"],"concepts":["参考系","运动的相对性"]}],"106":[{"title":"副线圈电压取值","type":"前提判断","judge":"副线圈输出电压应取单个灯泡的额定电压还是121个灯泡电压之和","why":"121个灯泡并联，各支路两端电压相同，都等于副线圈端电压，并联不叠加电压","do":"由并联电路电压特点确定副线圈电压等于单个灯泡额定电压","expr":"U_2=4\\ \\text{V}","cues":["并联电压相等","不能乘121","先看连接方式"],"concepts":["并联电路","电压特点"]},{"title":"副线圈总电流","type":"关系建立","judge":"副线圈总电流是单个灯泡电流还是121个灯泡电流之和","why":"并联电路干路电流等于各支路电流之和，副线圈供给整条灯带","do":"把121个灯泡的额定电流相加得副线圈总电流","expr":"I_2=121\\times0.1\\ \\text{A}=12.1\\ \\text{A}","cues":["干路电流相加","并联分流","总电流是总和"],"concepts":["并联电路","电流特点"]},{"title":"理想变压器三关系","type":"模型选择","judge":"用电压比等于匝数比、电流比等于匝数反比、输入功率等于输出功率这三条关系求解","why":"理想变压器无能量损失、无漏磁，原副线圈的电压、电流、功率由这三条规律联系","do":"由电压比求匝数比，由电流反比求原线圈电流，由功率相等求输入功率","expr":"\\frac{U_1}{U_2}=\\frac{n_1}{n_2},\\ \\frac{I_1}{I_2}=\\frac{n_2}{n_1},\\ P_1=P_2","cues":["理想变压器","电压比看匝数","功率相等"],"concepts":["理想变压器","匝数比","功率守恒"]},{"title":"原线圈电流与功率","type":"关系建立","judge":"原线圈电流应由电流反比关系还是由功率关系求出，两者是否一致","why":"理想变压器输入功率等于输出功率，且电流与匝数成反比，两条路径应给出同一结果","do":"先用功率相等求输入功率，再用电流反比或功率除以原电压求原线圈电流","expr":"P_1=U_2I_2=48.4\\ \\text{W},\\ I_1=\\frac{P_1}{U_1}","cues":["先算功率","电流反比","功率除以电压"],"concepts":["输入功率","原线圈电流"]}],"107":[{"title":"测力计读数等于月面重力","type":"前提判断","judge":"测力计测得的示数是否等于钩码在月球表面所受的万有引力","why":"钩码在月面静止时只受万有引力和测力计拉力，二者平衡，故示数即月面重力，也等于月球对钩码的万有引力","do":"把测力计示数当作钩码与月球间的万有引力大小，写出万有引力等于示数的等式","expr":"F=G\\dfrac{Mm}{R^{2}}","cues":["示数就是重力","月面重力等于引力"],"concepts":["万有引力","重力","二力平衡"]},{"title":"由表面重力反求月球质量","type":"关系建立","judge":"用月面重力、钩码质量、月球半径和引力常量能否唯一确定月球质量","why":"万有引力定律给出表面重力与中心天体质量的关系，钩码质量、半径、引力常量均已知，月球质量是唯一未知量","do":"将万有引力等式变形，把月球质量解出来，得到只含已知量的表达式","expr":"M=\\dfrac{FR^{2}}{Gm}","cues":["反解中心天体质量","用表面重力求"],"concepts":["万有引力定律","中心天体质量"]},{"title":"第一宇宙速度用近月环绕","type":"模型选择","judge":"月球的第一宇宙速度对应哪一类环绕模型","why":"第一宇宙速度是贴近星球表面做圆周运动的卫星的环绕速度，轨道半径取月球半径，由万有引力提供向心力","do":"对近月卫星列万有引力等于向心力的方程，解出环绕速度并与选项给出的数值比较","expr":"G\\dfrac{Mm'}{R^{2}}=m'\\dfrac{v^{2}}{R}\\Rightarrow v=\\sqrt{\\dfrac{GM}{R}}","cues":["近月卫星","轨道半径取月半径"],"concepts":["第一宇宙速度","向心力"]},{"title":"劲度系数与星球无关","type":"前提判断","judge":"弹簧的劲度系数是否随所处星球的重力环境改变","why":"劲度系数由弹簧自身的材料、匝数、粗细决定，是弹簧的固有属性，与重力加速度无关","do":"比较地球与月球上同一弹簧的劲度系数，判断其是否相同","expr":"","cues":["弹簧本身决定","和重力无关"],"concepts":["劲度系数","弹簧固有属性"]},{"title":"光速不随参考系叠加","type":"前提判断","judge":"月球运动时测得的光速是否需要用月球速度做矢量叠加","why":"狭义相对论的光速不变原理指出，真空中光速在任何惯性系中都是同一常量，与光源和观察者的运动无关","do":"判断选项中对光速做速度叠加的说法是否成立","expr":"","cues":["光速不变","不能叠加"],"concepts":["光速不变原理","狭义相对论"]}],"108":[{"title":"判断安培力方向","type":"前提判断","judge":"通电导体棒在竖直磁场中所受安培力沿哪个方向，是水平指向平衡位置还是背离","why":"安培力方向由左手定则结合电流方向与磁场方向决定，它决定回复力来源，判错则振动方向与平衡位置全错","do":"由电源正负极定出棒中电流方向，再用左手定则（磁场竖直向上）定出安培力水平方向","expr":"","cues":["左手定则","磁场竖直向上","看电流方向"],"concepts":["安培力","左手定则"]},{"title":"确认平衡位置","type":"关系建立","judge":"棒静止处是重力切向分量与安培力切向分量相平衡的位置，而非圆环最低点","why":"棒受重力和安培力两个力，平衡条件是两力沿圆弧切向分量等大反向，故平衡位置偏离最低点","do":"沿切向分解重力与安培力，令切向合力为零，确定平衡位置对应的角度","expr":"mg\\sin\\theta_0 = F_A\\cos\\theta_0","cues":["切向分量平衡","不是最低点","重力与安培力"],"concepts":["力的分解","平衡条件"]},{"title":"小角度线性化","type":"近似条件","judge":"偏离平衡位置小角度时，回复力是否与角位移成正比，从而判定为简谐运动","why":"只有把切向合力在平衡位置附近作一阶展开，才能得到 F=-kx 形式的回复力，否则无法判断振动图样","do":"设偏离平衡位置小角 φ，将两力的切向分量在平衡位置附近展开，保留 φ 的一次项","expr":"F_{回}\\approx -k\\varphi","cues":["小角度近似","回复力正比位移","简谐运动"],"concepts":["简谐运动","回复力"]},{"title":"识别反电动势","type":"模型选择","judge":"棒运动切割竖直磁场产生的动生电动势是削弱还是增强电源电流","why":"动生电动势方向由右手定则判定，与电源电动势反向，使电流随速度变化，这是阻尼的根源","do":"用右手定则判断棒切割竖直磁场产生的电动势方向，与电源电动势比较","expr":"\\varepsilon' = BLv","cues":["切割磁感线","右手定则","反电动势"],"concepts":["动生电动势","右手定则"]},{"title":"判断阻尼衰减","type":"结论整理","judge":"振动过程中振幅是保持不变还是逐渐减小，最终趋于哪个位置","why":"反电动势使电流随速度改变，安培力中与速度相关的部分始终阻碍运动，做负功耗散机械能","do":"比较安培力方向与速度方向，判断其做功正负，得出振幅随时间衰减、平衡位置不变的结论","expr":"","cues":["振幅衰减","电磁阻尼","趋于原平衡位置"],"concepts":["电磁阻尼","能量耗散"]}],"109":[{"title":"区分充电功率与发热功率","type":"前提判断","judge":"题给的 20 度/分钟是充电输出功率，10 kW 才是电路发热功率，两者不能混用","why":"充电装置向外输出的电能与电路自身发热是两笔不同的能量，水冷只带走发热这部分","do":"把每分钟 20 度电换算成输出功率，与 10 kW 发热功率分开列出","expr":"P_out=\\frac{20\\ \\text{kW}\\cdot\\text{h}}{1/60\\ \\text{h}}","cues":["20度是输出","发热才用水冷","两个功率别混"],"concepts":["电功率","能量转化"]},{"title":"发热功率全被水吸收","type":"模型选择","judge":"能否把电路发热功率全部视为水吸收的热功率（忽略其它散热）","why":"题干明确忽略其它散热，热交换稳定后水吸热等于电路发热","do":"令单位时间内水吸收的热量等于发热功率","expr":"P_热=\\frac{Q}{t}=cm\\Delta T/t","cues":["忽略其它散热","发热全给水","热平衡"],"concepts":["热平衡","比热容"]},{"title":"单位时间流量与体积流量换算","type":"关系建立","judge":"要求的是每分钟流出水的体积，需由质量流量经密度换算成体积流量","why":"吸热公式给出的是单位时间质量，而选项给的是体积，必须用密度搭桥","do":"先由 P=cmΔT/t 求质量流量，再除以密度得体积流量，最后乘 60 s 得每分钟体积","expr":"q_m=\\frac{P}{c\\Delta T},\\quad q_V=\\frac{q_m}{\\rho},\\quad V=60q_V","cues":["先求质量流量","再除密度","乘60秒"],"concepts":["质量流量","密度","体积流量"]},{"title":"温差取25减15","type":"数学处理","judge":"水温从 15℃ 升到 25℃，温升取 10℃ 而不是 25℃","why":"吸热公式中的 ΔT 是进出口水温差","do":"用 ΔT=25℃−15℃=10℃ 代入","expr":"\\Delta T=10\\ \\text{K}","cues":["温差是10度","不是25度","进出口之差"],"concepts":["温度变化","吸热公式"]}],"110":[{"title":"偏转位移与动能关系","type":"关系建立","judge":"电子在偏转电场中水平位移由什么量决定，能否化成只含初动能的表达式","why":"电子以斜入射进入匀强电场，竖直方向匀减速到零再返回，总时间由竖直分速度和加速度决定，水平方向匀速，只有把时间代回才能把落点距离与入射动能挂钩","do":"分解初速度，竖直方向用位移为零求总时间，水平方向写匀速位移，再代入初动能化简","expr":"L=\\frac{2E_k\\sin\\theta\\cos\\theta}{qE}","cues":["分解速度","竖直位移为零","水平匀速"],"concepts":["运动的分解","匀变速直线运动","动能"]},{"title":"最远斑点对应无损失","type":"前提判断","judge":"最远斑点对应哪一种碰撞后的电子","why":"由位移与动能成正比可知，落点越远初动能越大，动能最大的电子就是未发生非弹性碰撞、能量无损失的电子","do":"把最远距离代入位移—动能关系，反解最大动能，再与加速电压给的动能比较","expr":"E_{k\\max}=eU","cues":["最远动能最大","没损失能量","和加速电压比"],"concepts":["弹性碰撞","动能守恒","电场加速"]},{"title":"激发能级差判断","type":"临界条件","judge":"电子剩余能量能否把氢原子激发到某一能级，最高能到哪一能级","why":"非弹性碰撞中电子损失的能量必须恰好等于两能级差，且不能超过电子自身动能，否则该激发不可能发生","do":"算出各能级与基态的能级差，与电子最大动能逐一比较，找出可达到的最高激发态","expr":"\\Delta E=E_n-E_1\\le E_{k\\max}","cues":["能级差","够不够激发","最高到哪级"],"concepts":["玻尔能级","能级差","激发"]},{"title":"可见光条数判断","type":"结论整理","judge":"激发后氢原子向下跃迁能发出几种可见光","why":"只有跃迁能量落在可见光能量范围内的谱线才计入，不能把所有跃迁都算作可见光","do":"列出从最高激发态向下各可能的跃迁，筛出能量在可见光范围内的条数","expr":"h\\nu=E_m-E_n","cues":["巴耳末系","可见光范围","跃迁条数"],"concepts":["能级跃迁","光子能量","可见光"]},{"title":"斑点数目与间距","type":"数学处理","judge":"有几种剩余动能就对应几个斑点，相邻斑点的最大间距取哪两个","why":"每个允许的能量损失对应一个确定的剩余动能，从而对应一个确定落点；间距最大者出现在相邻落点差最大的那一对","do":"对每种允许的能量损失算出剩余动能和对应水平位移，比较相邻位移差取最大","expr":"L_i=\\frac{2E_{ki}\\sin\\theta\\cos\\theta}{qE}","cues":["几种剩余动能","几个斑点","相邻差最大"],"concepts":["分立能级","位移与动能成正比","间距比较"]}],"111":[{"title":"光路顺序定单双缝","type":"模型选择","judge":"判断光沿传播方向依次经过哪些元件，从而确定1位置是单缝还是双缝","why":"双缝干涉要求光先经单缝成为线光源，再经双缝分成相干光，顺序颠倒则无法形成干涉","do":"沿光传播方向从光源出发依次列出透镜、1位置、双缝、遮光筒、测量头，比较1位置与双缝的先后","expr":"","cues":["先单缝后双缝","1在双缝前面","看光走的方向"],"concepts":["双缝干涉","相干光源","光路顺序"]},{"title":"拨杆调缝平行","type":"实验操作","judge":"判断视场整体暗、条纹不清时应调拨杆还是调其他部件，以及光应会聚到单缝还是双缝","why":"拨杆的作用是左右调节单缝与双缝的取向使两缝平行，只有缝平行且光会聚在单缝上，才有足够光强形成清晰干涉条纹","do":"比较拨杆、手轮、光源各自的功能，确定拨杆调缝的平行取向，光源或透镜前后移动使光会聚到单缝位置","expr":"","cues":["拨杆管缝的取向","光要聚到单缝","手轮是测间距的"],"concepts":["单缝与双缝平行","会聚","干涉条纹清晰度"]},{"title":"单侧暗调拨杆","type":"临界条件","judge":"判断图样一侧清晰一侧暗的成因是缝未完全平行还是亮度不足，从而选择调拨杆而非光源或手轮","why":"单侧明暗不均说明单缝与双缝取向有夹角，属缝的平行度问题，只有拨杆能改变缝的取向；光源只改整体亮度，手轮只移动分划板","do":"对比三种调节对象的作用范围，把单侧暗归因于缝不平行，选拨杆微调","expr":"","cues":["一边亮一边暗是缝歪了","光源只管整体亮暗","手轮不动缝"],"concepts":["缝的平行度","视场明暗分布"]},{"title":"刻线不平行转测量头","type":"实验操作","judge":"判断分划板中心刻线与条纹不平行时应旋转测量头整体还是只转目镜或分划板","why":"分划板固定在测量头内，刻线取向由测量头整体方位决定，只有旋转测量头才能让刻线与条纹平行，否则读数基准线斜交条纹导致间距测量错误","do":"明确刻线与分划板的固连关系，选择旋转整个测量头使刻线对准条纹方向","expr":"","cues":["刻线跟着测量头转","转整个测量头","不能只转目镜"],"concepts":["分划板","测量头","刻线与条纹平行"]},{"title":"波长公式中距离对应","type":"关系建立","judge":"判断波长公式中的长度对应哪两个部件之间的距离","why":"公式中的长度是双缝到光屏（观察屏）的距离，即相干光出射面到接收条纹面的距离，取错段落则波长算错","do":"在装置图上定位双缝与光屏（遮光筒末端观察屏）的位置，取二者间距代入公式","expr":"\\Delta x=\\frac{L}{d}\\lambda","cues":["取双缝到屏的距离","不是缝到缝","看②到③"],"concepts":["双缝间距","双缝到屏距离","条纹间距公式"]}],"112":[{"title":"磁场方向判定","type":"几何关系","judge":"沿z轴正方向看，长直导线电流产生的磁感线绕行方向是顺时针还是逆时针","why":"长直载流导线的磁场由右手螺旋定则决定，磁感线是以导线为轴的同心圆，方向与电流方向成右手螺旋关系","do":"用右手握住导线，拇指指向电流的+z方向，四指弯曲方向即为磁感线绕行方向，再投影到垂直于z轴的平面上画出同心圆","expr":"","cues":["右手螺旋定则","同心圆","顺时针"],"concepts":["安培定则","长直导线磁场"]},{"title":"有效受力边的选取","type":"模型选择","judge":"正方形线圈四条边中哪两条边受力、哪两条边安培力相互抵消","why":"沿z方向的两条边电流方向相反且处在同一磁场中，安培力等大反向抵消；沿径向的两条边分别处于普通磁场和磁性材料增强磁场中，受力不能抵消","do":"把每匝线圈分解为两条沿z的边和两条沿径向的边，逐边用左手定则判断受力方向，确认只有径向边贡献净安培力","expr":"","cues":["沿z的边抵消","径向边受力","只看两条边"],"concepts":["安培力","左手定则","对称性"]},{"title":"增强磁场与力差","type":"关系建立","judge":"处于磁性材料中的那条边磁感应强度取B还是取增强后的值，净安培力是两边受力之差还是之和","why":"题设给出有磁性材料处磁感应强度增强至给定倍数，两条径向边所在磁场不同，方向相反的电流使两边安培力方向相反，故净力为差值","do":"分别写出两条径向边所受安培力，一条用B、一条用增强后的磁感应强度，按方向相反作差得到单匝净安培力","expr":"F_单匝 = I·L·(kB - B)","cues":["一边强一边弱","取差值","增强倍数"],"concepts":["安培力","磁介质增强","叠加"]},{"title":"总安培力与方向","type":"结论整理","judge":"n匝线圈总安培力是单匝的n倍，方向由左手定则结合恒流源电流方向确定","why":"n匝串联，每匝电流相同、受力同向，总力为单匝受力的n倍；方向由左手定则对有效受力边判定","do":"将单匝净安培力乘以匝数n，用左手定则判断方向沿z轴正方向还是负方向，再代入数值求大小","expr":"F = n·I·L·(k-1)B","cues":["串联同向叠加","乘匝数","左手定则定方向"],"concepts":["安培力","串联线圈","左手定则"]},{"title":"热功率的电阻计算","type":"关系建立","judge":"n匝串联的总电阻是每匝电阻的n倍，热功率用总电阻还是单匝电阻计算","why":"n匝线圈串联，电流处处相同，总电阻为各匝电阻之和，焦耳热功率按总电阻与总电流计算","do":"先求总电阻R总=nR，再用P=I²R总求热功率并代入数值","expr":"P = I²·nR","cues":["串联电阻相加","用总电阻","电流相同"],"concepts":["焦耳定律","串联电阻","电功率"]},{"title":"乙方案并联等效","type":"模型选择","judge":"乙方案中每匝线圈被内外圆筒短接后，各边是串联还是并联，总安培力与总热功率如何等效","why":"两金属圆筒不计电阻，把每匝线圈的四个顶点分别短接，相当于2n条电阻为R的边并联接在恒流源两端，每条边电流为总电流的1/(2n)，但只有径向边产生净安培力","do":"按并联分流写出每条边电流，用与甲相同的单匝净力表达式求乙的总安培力，令其等于甲的总安培力反解恒流源电流；再用并联电阻求乙的热功率并与甲比较","expr":"F_乙 = 2n·(I'/2n)·L·(k-1)B = I'·L·(k-1)B","cues":["短接即并联","每条边分流","力相同反求电流"],"concepts":["并联分流","安培力","等效电路"]}],"113":[{"title":"识别核反应方程形式","type":"模型选择","judge":"要判断这是核反应方程配平问题，而非衰变或裂变能量计算","why":"题干给出'由核反应……生成'的方程，未知量在反应物一侧，属于用守恒定律确定粒子种类的题型","do":"写出反应方程，标出反应物与生成物两侧的质量数和电荷数","expr":"","cues":["配平方程","看两边数字","守恒定律"],"concepts":["核反应方程","质量数","电荷数"]},{"title":"质量数守恒定未知量","type":"关系建立","judge":"要判断反应前后质量数总和相等，据此求未知粒子的质量数","why":"核反应中质量数守恒是配平方程的基本规律，反应物一侧质量数之和必须等于生成物一侧","do":"把反应物各粒子质量数相加，令其等于生成物质量数，解出未知质量数","expr":"a+1=90","cues":["上标相加","质量数守恒","先算大数"],"concepts":["质量数守恒"]},{"title":"电荷数守恒定未知量","type":"关系建立","judge":"要判断反应前后电荷数（原子序数）总和相等，据此求未知粒子的电荷数","why":"核反应中电荷数守恒，反应物一侧电荷数之和必须等于生成物一侧","do":"把反应物各粒子电荷数相加，令其等于生成物电荷数，解出未知电荷数","expr":"39+b=39","cues":["下标相加","电荷数守恒","看原子序数"],"concepts":["电荷数守恒"]},{"title":"由质量数电荷数认粒子","type":"结论整理","judge":"要根据求出的质量数与电荷数组合判断未知粒子是中子还是其他粒子","why":"质量数为1、电荷数为0的粒子是中子，这是识别粒子的判据；若误把电荷数当质量数就会错认成电子或质子","do":"将解出的质量数与电荷数对照常见粒子（质子、中子、电子、α粒子）的特征值","expr":"","cues":["质量数一电荷零","是中子","不是电子"],"concepts":["中子","粒子识别"]}],"114":[{"title":"确定末态温度变化","type":"关系建立","judge":"要判断初末两态温度之比，需用理想气体状态方程把 T 与 p、V 联系起来","why":"一定质量理想气体满足 pV/T 为常量，温度不能直接由单一参量判断，必须由 p、V 的联合变化算出","do":"写出初末两态的 pV/T 相等，代入 V₂=V₁/2、p₂=3p₁，解出 T₂/T₁","expr":"\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}\\Rightarrow \\frac{T_2}{T_1}=\\frac{p_2V_2}{p_1V_1}","cues":["用状态方程","pV比T","先算温度比"],"concepts":["理想气体状态方程","温度"]},{"title":"温度与平均动能对应","type":"前提判断","judge":"要判断分子平均动能如何变，需确认温度是不是分子平均动能的唯一宏观标志","why":"理想气体分子平均动能只由温度决定，温度升高则平均动能增大，与压强、体积无直接关系","do":"比较 T₂ 与 T₁ 的大小，由温度高低直接判定平均动能增减","expr":"\\bar{E}_k\\propto T","cues":["温度看平均动能","温度高动能大"],"concepts":["分子平均动能","温度的微观意义"]},{"title":"区分统计规律与单个分子","type":"前提判断","judge":"要判断“每个分子速率都变大”是否成立，需分清平均动能是统计量还是单个分子的量","why":"温度对应的平均动能是大量分子的统计平均结果，只说明速率分布整体向高速区偏移，个别分子速率可增可减","do":"把“平均动能增大”与“每个分子速率增大”区分开，否定对单个分子的断言","expr":"","cues":["平均不代表每个","统计规律","个别分子不一定"],"concepts":["统计规律","速率分布"]},{"title":"压强微观决定因素","type":"关系建立","judge":"要判断单位时间单位面积碰撞分子数如何变，需明确压强由碰撞频率与单次碰撞冲量共同决定","why":"气体压强等于单位时间内单位面积上分子碰撞总冲量，温度升高使单次碰撞冲量增大，若压强还增至 3 倍，则碰撞频率必然增大","do":"把压强分解为碰撞频率与平均碰撞冲量两个因素，在冲量增大、压强增大的条件下反推碰撞频率的变化","expr":"p\\propto n\\bar{v}\\cdot\\Delta p","cues":["压强看碰撞","碰撞次数和冲量","两个因素一起看"],"concepts":["气体压强的微观解释","碰撞频率"]}],"115":[{"title":"弹簧形变状态判断","type":"前提判断","judge":"弹簧当前长度与自然长度谁大，即弹簧处于伸长还是压缩","why":"弹力方向由形变状态决定，压缩时弹力沿弹簧指向外端、伸长时指向固定端，方向反了平衡方程就全错","do":"先用几何关系算出平衡时弹簧的实际长度，再与原长比较","expr":"l=\\sqrt{R^2+R^2-2R^2\\cos\\theta}","cues":["先算弹簧长度","比一比原长","是压缩还是伸长"],"concepts":["胡克定律","几何关系"]},{"title":"确定弹力方向","type":"模型选择","judge":"弹力沿弹簧方向指向哪一侧（推小球还是拉小球）","why":"受力分析中弹力方向决定它与重力、支持力的夹角，进而决定各分量正负","do":"由压缩状态判定弹力沿弹簧由固定端指向小球，画出受力图","expr":"","cues":["弹力沿弹簧","往外推","画受力图"],"concepts":["弹力方向","受力分析"]},{"title":"几何角与力角对应","type":"几何关系","judge":"弹簧与水平方向夹角、半径与水平方向夹角、弹力与竖直方向夹角之间的换算","why":"圆环半径与弹簧构成等腰三角形，弹力方向沿弹簧，只有把几何角正确搬到受力图上才能写出分量式","do":"利用等腰三角形底角关系，把弹簧与水平方向夹角换算成弹力与竖直（或水平）方向的夹角","expr":"\\alpha=\\theta","cues":["等腰三角形","底角相等","角度搬过去"],"concepts":["等腰三角形","角度关系"]},{"title":"径向与切向分解","type":"关系建立","judge":"沿哪个方向列平衡方程最省未知数（沿半径方向还是水平竖直方向）","why":"小球受重力、弹力、圆环支持力三个力，支持力沿半径，沿半径方向分解可让支持力只出现在一个方程里，避免解它","do":"沿半径方向和切线方向分解重力与弹力，列两个平衡方程","expr":"k\\Delta l\\cos\\alpha=mg\\sin\\theta,\\quad N=k\\Delta l\\sin\\alpha+mg\\cos\\theta","cues":["沿半径分解","避开支持力","切向也平衡"],"concepts":["共点力平衡","正交分解"]},{"title":"形变量与劲度系数联立","type":"数学处理","judge":"用形变量 Δl 与几何长度差表示弹力，并与平衡方程联立求 k","why":"胡克定律中的弹力是 k 乘形变量，形变量必须由几何长度减去原长得到，不能直接用弹簧长度","do":"写出 Δl 的几何表达式，代入切向平衡方程解出 k","expr":"k=\\frac{mg\\sin\\theta}{\\Delta l\\cos\\alpha}","cues":["形变量是长度差","代入胡克定律","解出劲度系数"],"concepts":["胡克定律","共点力平衡"]}],"116":[{"title":"安培力冲量用磁通量变化","type":"关系建立","judge":"求导体棒速度变化时，是逐段积分安培力，还是把安培力冲量整体写成与磁通量变化相关的形式","why":"安培力 F=BIL 随速度变化，直接积分困难；但 q=ΔΦ/R，安培力冲量 ∫BILdt=BqL=ΔΦ·L/R，可绕开速度随时间的具体变化","do":"对导体棒写动量定理，把安培力冲量用通过回路的总电荷量表示，再把电荷量与磁通量变化挂钩","expr":"-∫BIL\\,dt = -\\frac{L}{R}\\Delta\\Phi = 0-mv_0","cues":["安培力冲量","电荷量代换","磁通量变化"],"concepts":["安培力冲量","磁通量","动量定理"]},{"title":"分两阶段算磁通量变化","type":"前提判断","judge":"磁场只在刚过某边界后极短时间内增大，磁通量变化要分成棒运动切割磁感线部分和磁场突变部分两段来算","why":"磁通量变化有两个来源：导体棒扫过面积使磁通量变化，以及区域内磁感应强度在极短时间内由 B 增到 2B 使磁通量突变；两者都要计入总电荷量","do":"分别写出棒从出发到静止扫过面积引起的磁通量变化，以及磁场突变区域面积乘以磁感应强度增量","expr":"\\Delta\\Phi = B L x + (2B-B)S","cues":["两段磁通量","磁场突变","扫过面积"],"concepts":["磁通量变化","切割磁感线","磁场突变"]},{"title":"突变瞬间棒几乎不动","type":"近似条件","judge":"磁场在极短时间内增大时，导体棒的位置和速度是否可视为不变","why":"题设磁场增大过程极短，安培力冲量有限，棒在该瞬间的位移和速度变化可忽略，故突变只贡献磁通量变化而不额外贡献位移","do":"把突变阶段的位移取为零，只把磁感应强度增量代入磁通量变化","expr":"\\Delta x_{\\text{突变}}\\approx 0","cues":["极短时间","位置不变","速度不变"],"concepts":["瞬时近似","冲量"]},{"title":"正方形区域面积取值","type":"几何关系","judge":"磁场突变所涉及区域的面积应取正方形边长对应的面积，而不是整段导轨扫过的面积","why":"只有标注的正方形区域内磁感应强度发生突变，其余区域磁场不变，故突变磁通量只与该正方形面积有关","do":"由导轨间距确定正方形边长，写出突变区域面积 S 与 L 的关系","expr":"S=L^2","cues":["正方形区域","边长就是间距","只算这块"],"concepts":["几何面积","磁场区域"]},{"title":"总位移由总磁通量反解","type":"数学处理","judge":"把两段磁通量合并后，由动量定理方程解出总位移 x，而不是分段求速度再相加","why":"安培力冲量只与总磁通量变化有关，与路径无关，故可一次性由初动量求出总位移","do":"将 ΔΦ 表达式代入动量定理，解出 x 并整理成选项形式","expr":"\\frac{B L}{R}(BLx+BL^2)=mv_0","cues":["一次解出","总磁通量","不用分段"],"concepts":["动量定理","磁通量","位移求解"]}],"117":[{"title":"建立落点坐标约束","type":"几何关系","judge":"落点必须同时满足平抛轨迹方程和圆弧边界方程，要判断用哪个几何量作自变量把两者联立","why":"物资做平抛运动，落点又在以O为圆心R为半径的圆弧上，两个条件缺一不可，只用一个条件无法确定落点","do":"设落点相对O的竖直高度h和水平位移x，写出平抛的x、h与初速度分量的关系，再写出圆弧的几何关系，消去x得到h与抛射角的关系","expr":"x=v_0\\cos\\theta\\, t,\\quad h=v_0\\sin\\theta\\, t+\\tfrac12 g t^2,\\quad x^2+(R-h)^2=R^2","cues":["落点在圆弧上","平抛加圆方程","消去水平位移"],"concepts":["平抛运动","圆的几何约束"]},{"title":"用机械能守恒定落点速率","type":"关系建立","judge":"要判断落点速率由什么量决定，是逐点算速度分量还是直接用能量关系","why":"只有重力做功，机械能守恒，落点速率只与下落高度有关，不必分解速度再合成","do":"从抛出点到落点列机械能守恒，把落点速率平方写成初动能项加重力势能减少项","expr":"\\tfrac12 m v^2=\\tfrac12 m v_0^2+m g h","cues":["只有重力做功","用能量不用分量","速率只看高度"],"concepts":["机械能守恒","重力势能"]},{"title":"把速率最小化为高度最小","type":"数学处理","judge":"要判断使落点速率最小的条件等价于使哪个几何量取极值","why":"初速度大小固定，由机械能守恒知速率随下落高度单调增大，故速率最小等价于h最小","do":"由能量式看出v随h单调增，把问题转化为求h的最小值，再对h的表达式配方或求极值","expr":"v^2=v_0^2+2gh\\ \\Rightarrow\\ v_{\\min}\\Leftrightarrow h_{\\min}","cues":["速率随高度增大","转化成求高度最小","配方找极值"],"concepts":["单调性","极值条件"]},{"title":"确定极值对应的抛射方向","type":"临界条件","judge":"要判断h取最小时对应的抛射角（或初速度方向）以及落点位置","why":"h的表达式是抛射角的函数，极值出现在特定角度，这个角度决定落点坐标，进而决定各选项的数值","do":"对h关于抛射角的表达式求极值，得到取极小时的抛射角，再回代求h和水平位移，确定落点相对O的位置","expr":"h=h(\\theta),\\quad \\frac{dh}{d\\theta}=0\\ \\Rightarrow\\ \\theta_{\\min},\\ h_{\\min},\\ x_{\\min}","cues":["对角度求极值","极值角定落点","回代算坐标"],"concepts":["极值条件","平抛运动"]},{"title":"区分速率最小与时间最短","type":"前提判断","judge":"要判断题目问的是落点速率最小还是运动时间最短（或水平位移最小），不能混为一谈","why":"速率最小由能量决定对应h最小，而时间最短对应竖直下落最快，两者极值条件不同，混淆会选错项","do":"明确目标函数是v而非t或x，检查极值条件是否针对v，排除按时间或水平位移求极值的做法","expr":"","cues":["问的是速率不是时间","别按时间求","目标函数是速度"],"concepts":["极值目标函数","机械能守恒"]}],"118":[{"title":"螺旋测微器读数","type":"实验操作","judge":"读数时主尺整毫米数与可动刻度对齐格数如何组合，是否要估读","why":"螺旋测微器精度为0.01 mm，可动刻度需估读到下一位，固定刻度半毫米线是否露出决定是否加0.5 mm","do":"先读固定刻度（含半毫米线），再读可动刻度与主尺对齐的格数并估读一位，两者相加","expr":"d=L+0.01n\\ \\text{mm}","cues":["看半毫米线露没露","可动刻度要估读一位","主尺加转筒读数"],"concepts":["螺旋测微器","估读","长度测量"]},{"title":"确定测量电阻的原理","type":"模型选择","judge":"铅笔芯接入电路的是P到某端的一段，其电阻应由哪两个电表示数之比得到","why":"铅笔芯与电阻箱串联，电压表测铅笔芯接入段两端电压U，电流表测通过它的电流I，由欧姆定律得该段电阻","do":"明确电压表并联在铅笔芯接入段两端、电流表串联在干路，写出该段电阻表达式","expr":"R_x=\\frac{U}{I}","cues":["电压表测哪一段","电流表测干路","用欧姆定律求电阻"],"concepts":["欧姆定律","伏安法测电阻","串联电路"]},{"title":"电阻定律与长度对应","type":"关系建立","judge":"电阻定律中的L应取接入电路的有效长度，横截面积用直径表示","why":"电阻率由R=ρL/S定义，S=πd²/4，其中L必须是电流流过的铅笔芯长度而非全长","do":"将R=U/I与R=ρL/S联立，把S用d表示，解出ρ","expr":"\\rho=\\frac{US}{IL}=\\frac{\\pi d^2 U}{4IL}","cues":["长度取接入段","面积用直径算","联立两式消电阻"],"concepts":["电阻定律","电阻率","横截面积"]},{"title":"图像化曲为直求斜率","type":"图像读取","judge":"由表达式判断应作什么关系图像，斜率对应哪个物理量组合","why":"ρ表达式中U/I与L成正比，作U/I–L图应为过原点直线，斜率k=4ρI/(πd²)，从而由斜率反求ρ","do":"写出纵轴U/I与横轴L的关系式，指出斜率含义，从图(c)取两点求斜率","expr":"\\frac{U}{I}=\\frac{4\\rho}{\\pi d^2}L,\\quad k=\\frac{4\\rho}{\\pi d^2}","cues":["先看坐标轴是什么","斜率对应哪个量","取两点算斜率"],"concepts":["图像法","线性关系","斜率"]},{"title":"内阻变化的影响判断","type":"误差分析","judge":"电池内阻增大是否改变电压表与电流表示数所反映的铅笔芯段U、I关系","why":"电压表直接测铅笔芯段电压、电流表直接测其电流，U/I始终等于该段真实电阻，与电源内阻无关","do":"分析内阻增大只改变总电流和路端电压，不改变U与I的比值，判断ρ是否受影响","expr":"\\frac{U}{I}=R_x\\ \\text{不变}","cues":["电压电流还是真实值","内阻只影响总电流","比值不变"],"concepts":["电源内阻","系统误差","伏安法"]}],"119":[{"title":"由振动方向定波向","type":"前提判断","judge":"已知某质点的振动方向，要判断波沿 x 轴正方向还是负方向传播","why":"波的传播方向与质点振动方向由同一侧法（上下坡法）相互制约，方向判错则后续所有时间计算全错","do":"在波形图上标出该质点此刻的振动方向，用同侧法判断波传播方向","expr":"","cues":["同侧法","看上下坡","振动方向定波向"],"concepts":["波的传播方向","质点振动方向","同侧法"]},{"title":"读图取波长","type":"图像读取","judge":"要从波形图横轴上读出相邻同相点之间的距离作为波长","why":"波长是波形图直接给出的空间周期，是联系波速与周期的桥梁","do":"在图上找两个相邻波峰（或相邻平衡位置且振动同相的点），读出其横坐标差","expr":"","cues":["看相邻波峰","读横轴间距","一个完整波形"],"concepts":["波长","波形图"]},{"title":"波速波长定周期","type":"关系建立","judge":"要判断用哪个关系式把波速、波长、周期三者联系起来","why":"波速由介质决定，满足 v=λ/T，已知 v 和 λ 即可唯一确定 T","do":"将读出的波长与给定波速代入波速公式解出周期","expr":"v=\\frac{\\lambda}{T}\\Rightarrow T=\\frac{\\lambda}{v}","cues":["用波速公式","波长比波速","先求周期"],"concepts":["波速","周期","波长"]},{"title":"波形平移找首次平衡","type":"模型选择","judge":"要判断用“波形平移”还是“质点振动计时”来求质点到达平衡位置的时间","why":"波传播的是振动形式和能量，某处质点的振动状态由前方波形平移传来，平移距离对应时间","do":"找出离该质点最近的、处于平衡位置且振动状态相同的波形点，量出它与该质点的水平距离","expr":"","cues":["波形平移","看哪个平衡位置传过来","找最近同相点"],"concepts":["波形平移","振动形式传播"]},{"title":"区分第一次与第二次","type":"临界条件","judge":"要判断“第二次到达平衡位置”对应波形平移的距离是几个半波长","why":"质点每经过半个周期就过一次平衡位置，第一次与第二次之间恰隔半个周期，漏掉这一层就会少算或多算","do":"先算第一次到达平衡位置的时间，再加半个周期得到第二次的时间","expr":"t_2=t_1+\\frac{T}{2}","cues":["隔半个周期","第二次再加半周期","过平衡位置两次"],"concepts":["平衡位置","半周期","周期性"]}],"120":[{"title":"下滑过程选规律","type":"模型选择","judge":"甲从释放到第一次到达 A 点，用动能定理还是牛顿第二定律加运动学","why":"轨道光滑、只有重力做功，且不涉及时间，动能定理一步到位；用牛顿定律需先求加速度再求位移，多绕一步","do":"对甲从释放点到 A 点列动能定理，初动能为零，重力做功取下降高度","expr":"m_1 g h = \\frac{1}{2} m_1 v_0^2","cues":["光滑轨道","只有重力做功","用动能定理"],"concepts":["动能定理","机械能守恒"]},{"title":"弹性正碰定碰后速度","type":"关系建立","judge":"第一次碰撞后甲、乙各自的速度方向和大小，用动量守恒加机械能守恒联立还是只用一个","why":"题设明确为弹性正碰，动量守恒和动能守恒同时成立，两个方程才能解出两个未知速度；只列动量守恒无法确定碰后状态","do":"取向右为正，列动量守恒式和机械能守恒式，联立解出碰后甲、乙速度","expr":"m_1 v_0 = m_1 v_1 + m_2 v_2,\\ \\frac{1}{2}m_1 v_0^2=\\frac{1}{2}m_1 v_1^2+\\frac{1}{2}m_2 v_2^2","cues":["弹性正碰","两个方程","取向右为正"],"concepts":["动量守恒","弹性碰撞"]},{"title":"冲量用动量定理求","type":"模型选择","judge":"求乙所受合外力的冲量，是逐段求各力冲量再合成，还是直接用动量定理","why":"碰撞过程中重力、支持力、甲对乙的弹力都在变，逐力求冲量不可行；合外力冲量等于动量变化，只需碰前碰后速度","do":"对乙写动量定理，合外力冲量等于乙碰后动量减碰前动量，碰前乙静止","expr":"I = m_2 v_2 - 0","cues":["合外力冲量","动量变化","碰前静止"],"concepts":["动量定理","冲量"]},{"title":"碰后运动方向分情况","type":"临界条件","judge":"碰后甲、乙谁向左谁向右、谁先滑上斜面，取决于质量比 k 与 1、3 的大小关系","why":"碰后甲速度正负由 k 与 1 的大小决定，乙与甲速度大小比较由 k 与 3 的大小决定，不同区间追及对象和追及地点完全不同","do":"由碰后速度表达式比较 v_1 与零、|v_1| 与 v_2 的大小，把 k 分成 0<k≤1、1<k<3、k>3 三段","expr":"v_1=\\frac{1-k}{1+k}v_0,\\ v_2=\\frac{2}{1+k}v_0","cues":["先看速度正负","谁先上斜面","按质量比分类"],"concepts":["弹性碰撞","临界条件","分类讨论"]},{"title":"斜面往返的对称性","type":"几何关系","judge":"滑上斜面的物块返回水平轨道时速度大小和方向如何确定","why":"斜面光滑，上滑和下滑加速度大小相同，往返路程对称，返回连接点时速率不变、方向反向，这是追及时间计算的依据","do":"对滑上斜面的物块用机械能守恒判断返回连接点速率不变，方向改为沿水平轨道反向","expr":"v_{\\text{返}} = -v_{\\text{上}}","cues":["光滑斜面","往返对称","速率不变"],"concepts":["机械能守恒","对称性"]},{"title":"追及须在斜面端点前","type":"临界条件","judge":"第二次碰撞发生的位置必须在水平轨道上，即追及时刻要早于被追物块到达另一侧连接点的时刻","why":"题目限定第二次碰撞在水平轨道上且碰前只有一个物块滑上斜面，若追及发生在斜面上或物块已越过连接点，则情形不符","do":"对每种 k 区间写出追及时间 t 与位移关系，再令该时间小于先出发物块到达连接点所需时间，化简成关于 k 的不等式","expr":"t < \\frac{L}{v_{\\text{先}}}\\quad(\\text{各区间分别列})","cues":["在水平轨道上碰","赶在到端点前","时间要小于"],"concepts":["追及相遇","临界条件","分类讨论"]}],"121":[{"title":"衰变方程守恒律","type":"前提判断","judge":"判断该核反应方程应满足哪两条守恒律，并据此确定未知核的质量数与电荷数","why":"核反应中质量数守恒和电荷数守恒是确定生成核身份的唯一依据，题给方程中铊核与铅核的符号信息需由此补全","do":"对题给方程两侧分别列质量数之和相等、电荷数之和相等的两个等式，解出未知核的A与Z","expr":"A_{Tl}=A_{Pb}+0,\\quad Z_{Tl}=Z_{Pb}-1","cues":["质量数守恒","电荷数守恒","先定A和Z"],"concepts":["质量数守恒","电荷数守恒","β衰变"]},{"title":"束缚态衰变的实质","type":"模型选择","judge":"判断该过程放出的电子来自核内中子转变还是核外电子，从而确定方程中电子符号的写法","why":"束缚态β衰变是核内一个中子转变为质子并放出电子，电子被原子束缚，核的电荷数增加1而质量数不变","do":"确认方程右侧电子为核内放出，核对Z加1、A不变，与守恒式对照","expr":"n\\to p+e^-+\\bar{\\nu}_e","cues":["核内中子变质子","电子来自核内","Z加一A不变"],"concepts":["β衰变","中子转变","束缚态"]},{"title":"同量异位素判断","type":"关系建立","judge":"判断铊核与铅核是否质量数相同、质子数不同","why":"由守恒式得出两者A相同而Z相差1，属于同量异位素，不是同位素","do":"比较两核的A与Z，指出A相同、Z不同","expr":"A_{Tl}=A_{Pb},\\quad Z_{Tl}=Z_{Pb}-1","cues":["质量数一样","质子数差一","不是同位素"],"concepts":["同位素","同量异位素","核素符号"]},{"title":"中子数计算","type":"数学处理","judge":"判断某核的中子数应由质量数减质子数得到，并算出具体数值","why":"核素符号中A为核子总数、Z为质子数，中子数N=A−Z，这是判断选项数值正误的直接依据","do":"对目标核用N=A−Z计算中子数，与选项给出的数值比较","expr":"N=A-Z","cues":["中子数等于A减Z","用质量数减质子数","算核内中子个数"],"concepts":["中子数","核子数","质子数"]}],"122":[{"title":"重力与万有引力的关系","type":"关系建立","judge":"考虑自转时，地表物体的重力是万有引力的全部分还是其中一个分力","why":"物体随地球自转需要向心力，该向心力只能由万有引力提供，故万有引力须分解为重力与自转向心力两部分","do":"对地表物体作受力分析，写出万有引力、重力、向心力的矢量关系，明确重力是万有引力扣除向心力后的剩余分力","expr":"\\vec{F}_{万}=\\vec{G}+\\vec{F}_{向}","cues":["重力是分力","要扣向心力","万有引力分两份"],"concepts":["万有引力","向心力","重力"]},{"title":"自转半径随纬度变化","type":"几何关系","judge":"物体随地球自转的圆周轨道半径在不同纬度处是否相同","why":"物体绕地轴转动，轨道平面垂直于地轴，轨道半径是物体到地轴的距离而非到地心的距离","do":"画出地轴与物体位置，取物体到地轴的垂直距离为自转半径，比较赤道、两极及中间纬度的该距离","expr":"r=R\\cos\\theta","cues":["绕地轴转","半径不是地心距","两极半径为零"],"concepts":["自转半径","纬度","地轴"]},{"title":"向心力随纬度递减","type":"关系建立","judge":"自转向心力大小随纬度如何变化，从而重力如何变化","why":"角速度相同，向心力与自转半径成正比，半径越小所需向心力越小，万有引力中留给重力的部分就越多","do":"由向心力公式比较各纬度的向心力大小，再用万有引力减去向心力得到重力，判断重力随纬度升高而增大","expr":"F_{向}=m\\omega^{2}R\\cos\\theta,\\quad G=F_{万}-F_{向}","cues":["角速度相同","半径小向心力小","两极重力最大"],"concepts":["向心力","角速度","重力加速度"]},{"title":"重力方向是否指地心","type":"前提判断","judge":"除赤道和两极外，重力的方向是否沿地心连线指向地心","why":"重力是万有引力与向心力的矢量差，向心力指向地轴而非地心，二者合成后重力方向一般偏离地心连线","do":"在中间纬度处作万有引力与向心力的矢量三角形，观察合力方向与地心连线是否重合","expr":"","cues":["重力竖直向下","不指向地心","只有赤道两极指向地心"],"concepts":["重力方向","矢量合成","向心力"]},{"title":"高度对重力加速度的影响","type":"关系建立","judge":"同一地点上空，重力加速度随高度增大还是减小","why":"高度增大使物体到地心距离增大，万有引力按距离平方反比减小，故重力加速度随高度减小","do":"写出高度 h 处的万有引力表达式，与地表比较，判断 g 随 h 的变化趋势","expr":"g'=\\frac{GM}{(R+h)^{2}}","cues":["越高越小","距离变远","平方反比"],"concepts":["万有引力定律","重力加速度","高度"]}],"123":[{"title":"同价离子电荷量相同","type":"前提判断","judge":"碳12和碳13两种同价阳离子所带电荷量是否相同","why":"题目说'同价'，即两种离子电荷量相同，只是质量数不同（质量比12:13），这是后面所有比值的前提","do":"确定两种离子的电荷量q相同、质量m之比为12:13","expr":"q_1=q_2,\\quad m_1:m_2=12:13","cues":["同价就是电荷量一样","质量比按质量数算"],"concepts":["电荷量","质量数","同位素"]},{"title":"加速后速度与动量","type":"关系建立","judge":"用动能定理把加速电压与出射速度、动量联系起来，判断速度、动量随质量如何变化","why":"离子在电场中被加速，只有电场力做功，初速度为零，动能定理给出qU=mv²/2","do":"对电场加速段列动能定理，解出v和p=mv，再比较两种离子","expr":"qU=\\frac12 mv^2,\\quad v=\\sqrt{\\frac{2qU}{m}},\\quad p=\\sqrt{2mqU}","cues":["先看加速电场","动能定理列一下","动量带根号质量"],"concepts":["动能定理","动量","加速电压"]},{"title":"磁场中半径由动量定","type":"模型选择","judge":"离子垂直进入匀强磁场后做匀速圆周运动，轨道半径由哪个量决定","why":"洛伦兹力提供向心力，且洛伦兹力不做功，速率不变，半径r=mv/(qB)","do":"对磁场偏转段列向心力方程，解出半径表达式，再代入速度关系","expr":"qvB=\\frac{mv^2}{r},\\quad r=\\frac{mv}{qB}=\\frac{1}{B}\\sqrt{\\frac{2mU}{q}}","cues":["磁场里转圈","洛伦兹力当向心力","半径跟质量开方"],"concepts":["洛伦兹力","匀速圆周运动","轨道半径"]},{"title":"动能只由加速电压定","type":"结论整理","judge":"到达接收器时的动能是否与质量有关，能否用动能定理直接比较","why":"洛伦兹力不做功，磁场中动能不变，到达接收器的动能就等于离开电场时的动能qU，与质量无关","do":"比较两种离子到达接收器的动能，判断动能之比是否为1:1","expr":"E_k=qU","cues":["磁场不改动能","动能只看加速电压","两种离子动能一样"],"concepts":["动能定理","洛伦兹力不做功"]}],"124":[{"title":"用做功差定等势点","type":"关系建立","judge":"要判断由两次静电力做功之差能否推出某两点电势相等","why":"静电力做功只由始末位置电势差决定，与路径无关；同一电荷从同一点出发到两个不同点做功相等，说明这两个终点电势相同","do":"把从 O 到某点的做功拆成两段已知做功之和，与另一次已知做功比较，看差值是否为零","expr":"W_{O\\to P}=q(\\varphi_O-\\varphi_P)","cues":["做功相等就等势","拆成两段算","电势差为零"],"concepts":["电势差","静电力做功与路径无关"]},{"title":"等势线垂直于电场","type":"模型选择","judge":"要判断哪条连线是等势线，从而确定电场方向垂直于哪条弦","why":"匀强电场中电场线与等势面垂直，等势线必与电场方向垂直","do":"把电势相等的两点连成等势线，作其垂线即为电场方向所在直线","expr":"","cues":["等势线垂直电场","作垂线定方向","沿弦找等势"],"concepts":["等势面","匀强电场"]},{"title":"由高低定电场指向","type":"前提判断","judge":"要判断电场方向是沿垂线指向高电势一侧还是低电势一侧","why":"电场线由高电势指向低电势，正电荷从高电势移到低电势时静电力做正功","do":"比较已知做功的正负，确定哪点电势高，再让电场箭头从高电势指向低电势","expr":"U_{AB}=\\varphi_A-\\varphi_B=\\frac{W_{AB}}{q}","cues":["正功电势降低","从高电势指向低电势","看功的正负"],"concepts":["电势高低","电场线方向"]},{"title":"几何求夹角与有效距离","type":"几何关系","judge":"要判断电场方向与某条半径（或弦）的夹角，以及沿电场方向两点间的距离","why":"U=Ed 中的 d 是沿电场方向的距离，必须由圆的半径、弦长和夹角换算，不能直接取两点间距","do":"在圆内用半径与弦构成的三角形求夹角，再取两点连线在电场方向上的投影作为 d","expr":"U=Ed,\\quad d=L\\cos\\theta","cues":["d是沿场强距离","投影到电场方向","用半径和弦求角"],"concepts":["几何投影"]},{"title":"由电势差反求场强","type":"数学处理","judge":"要判断用哪两点间的电势差和对应的沿场距离来求 E，避免用错 d","why":"E=U/d 要求 U 与 d 严格对应同一对点，且 d 为沿电场方向的投影距离","do":"选一对电势差已知且沿场距离易求的点，代入 E=U/d 求大小","expr":"E=\\frac{U}{d}","cues":["U和d要配套","选好算的那对点","别用斜距离"],"concepts":["电场强度","电势差"]}],"125":[{"title":"额定功率下的变加速模型","type":"模型选择","judge":"速度增大时牵引力如何变化、加速度如何变化","why":"发动机始终在额定功率下工作，P=Fv 中 P 恒定，v 增大则 F 减小；再由 F-f=ma 得加速度随速度增大而减小","do":"写出 P=Fv 与 F-f=ma，联立消去 F，得到 a 随 v 变化的函数关系","expr":"P=Fv,\\quad F-f=ma\\ \\Rightarrow\\ a=\\frac{P}{mv}-\\frac{f}{m}","cues":["功率不变","速度越大牵引力越小","加速度越来越小"],"concepts":["额定功率","牛顿第二定律","变加速运动"]},{"title":"加速度为零即速度最大","type":"临界条件","judge":"速度增大到什么时候不再增大、此后做什么运动","why":"加速度 a 随 v 增大而减小，当 a=0 时牵引力等于阻力，速度达到最大值，之后维持匀速","do":"令 a=0，即 F=f，代入 P=Fv 求出最大速度","expr":"a=0\\Rightarrow F=f,\\quad v_m=\\frac{P}{f}","cues":["加速度减到零","牵引力等于阻力","之后匀速"],"concepts":["临界状态","最大速度","匀速直线运动"]},{"title":"牵引力趋于阻力","type":"结论整理","judge":"牵引力最终趋于哪个值、速度是单调增大还是先增后不变","why":"由 F=P/v，v 趋于 v_m=P/f，故 F 趋于 f；速度在 a>0 阶段一直增大，a=0 后保持不变","do":"对 F=P/v 取 v→v_m 的极限，并说明速度变化趋势","expr":"v\\to v_m=\\frac{P}{f}\\ \\Rightarrow\\ F\\to f","cues":["牵引力趋于阻力","速度先增大后不变","不会一直加速"],"concepts":["极限分析","牵引力","速度变化趋势"]},{"title":"平均速度与位移比较","type":"关系建立","judge":"经过一段时间后速度是否达到 v_m，位移与 v_m t 的大小关系","why":"速度从 v 增到 v_m 的过程中加速度不断减小，v-t 图线是上凸的，相同时间内位移大于匀加速情形，故速度达不到 v_m","do":"画 v-t 图比较曲线下面积与矩形面积，判断 t 时刻速度与 v_m 的关系","expr":"v<v_m\\ (t\\ \\text{有限}),\\quad x>\\frac{v+v_m}{2}t","cues":["加速度在减小","图线是上凸的","速度达不到最大"],"concepts":["v-t 图像","位移","平均速度"]}],"126":[{"title":"读图取周期与峰值","type":"图像读取","judge":"从图2的波形上读出交流电的周期和电压峰值，而不是直接拿某一时刻的瞬时值当有效值","why":"交流电表的示数和功率计算都要用有效值，而有效值必须由峰值和波形（正弦）换算，周期决定频率","do":"在图上量出相邻两个同相点的时间间隔得周期，读出电压最大值，再按正弦交流电的有效值与峰值关系换算","expr":"T=\\text{由图读出},\\quad U=\\frac{U_m}{\\sqrt2}","cues":["先读周期","峰值除以根号二","表测的是有效值"],"concepts":["交流电有效值","周期与频率","正弦交流电"]},{"title":"变压器电压按匝数比","type":"关系建立","judge":"判断副线圈电压应由原线圈电压乘匝数比得到，且原线圈电压就是电源有效值（理想变压器无内阻损耗）","why":"理想变压器电压比等于匝数比，原线圈直接接电源，故原电压等于电源输出电压有效值","do":"用匝数比把电源有效值折算成副线圈电压，该值即电压表示数","expr":"\\frac{U_1}{U_2}=\\frac{n_1}{n_2}","cues":["电压比等于匝数比","电压表读副线圈电压"],"concepts":["理想变压器","匝数比","电压关系"]},{"title":"副线圈电路结构判断","type":"模型选择","judge":"判断闭合两开关后副线圈侧电阻是串联还是并联，从而确定总电阻和电流分配关系","why":"副线圈电流由总电阻决定，而各电阻电流分配取决于串并联结构，结构判断错则电流表读数全错","do":"画出副线圈回路，确认两电阻的连接方式，写出副线圈总电阻及总电流与各支路电流的关系","expr":"I_2=\\frac{U_2}{R_{\\text{总}}}","cues":["先看怎么连","两个电阻并联","总电阻是多少"],"concepts":["串并联电路","欧姆定律","总电阻"]},{"title":"电流按匝数比反比折算","type":"关系建立","judge":"判断原、副线圈电流之比等于匝数反比，且原线圈电流由副线圈总电流折算而来","why":"理想变压器输入功率等于输出功率，故电流与匝数成反比，这是求原线圈电流表读数的唯一依据","do":"先由副线圈电压和总电阻求副线圈总电流，再用匝数反比求原线圈电流","expr":"\\frac{I_1}{I_2}=\\frac{n_2}{n_1}","cues":["电流比是匝数反比","先求副线圈总电流","功率相等推电流"],"concepts":["理想变压器","电流关系","功率相等"]},{"title":"功率归属与总功率","type":"结论整理","judge":"判断某电阻消耗的功率用其自身电流和电阻算，电源输出功率等于副线圈各电阻功率之和（理想变压器无损耗）","why":"理想变压器不耗能，输入功率等于输出功率，故电源输出功率等于副线圈所有电阻消耗功率之和","do":"分别算出各电阻功率并求和得电源输出功率，再与某电阻功率作比","expr":"P=UI=I^2R,\\quad P_{\\text{出}}=P_{R_1}+P_{R_2}","cues":["功率用电流平方乘电阻","变压器不耗能"],"concepts":["电功率","理想变压器功率关系","能量守恒"]}],"127":[{"title":"确定条纹间距公式","type":"模型选择","judge":"判断双缝干涉中条纹间距由哪个公式决定，以及各符号分别对应什么物理量","why":"双缝干涉的条纹间距由干涉条件与几何近似共同决定，只有选对公式才能把已知波长和间距联系起来","do":"写出条纹间距与波长、双缝到屏距离、双缝间距的关系式，并明确各符号含义","expr":"\\Delta x=\\frac{L}{d}\\lambda","cues":["用条纹间距公式","间距和波长成正比","看双缝到屏的距离"],"concepts":["双缝干涉","条纹间距","波长"]},{"title":"同装置比例求波长","type":"关系建立","judge":"判断两次测量中哪些量保持不变，能否用比例关系直接求待测波长","why":"同一双缝装置中双缝间距和挡板到屏的距离不变，条纹间距与波长成正比","do":"把两次测量的条纹间距与波长写成比例式，消去共同的装置参数","expr":"\\frac{\\lambda'}{\\lambda}=\\frac{\\Delta x'}{\\Delta x}","cues":["装置没换","间距比等于波长比","不用求具体距离"],"concepts":["正比关系","双缝干涉"]},{"title":"由波长换算频率","type":"关系建立","judge":"判断频率该由波速与波长的关系求出，还是能由条纹间距直接得出","why":"光速为真空中常数，频率由波速与波长共同决定，条纹间距只给出波长信息","do":"先用比例式求出待测波长，再用波速等于波长乘频率求频率","expr":"\\nu=\\frac{c}{\\lambda'}","cues":["先求波长再求频率","光速是常数","频率不能只看间距"],"concepts":["波速","波长","频率"]},{"title":"平移挡板改变哪个量","type":"几何关系","judge":"判断挡板平移时双缝间距和挡板到屏距离中哪一个发生变化","why":"条纹间距只由双缝间距和双缝到屏的距离决定，平移方向决定这两个几何量是否改变","do":"沿水平方向平移时看双缝到屏的距离是否变化，沿竖直方向平移时看双缝间距和屏距是否变化","expr":"\\Delta x=\\frac{L}{d}\\lambda","cues":["右移屏距变小","上移两个量都不变","看双缝到屏的距离"],"concepts":["几何关系","条纹间距","双缝间距"]},{"title":"条纹间距变化判断","type":"结论整理","judge":"判断几何量变化后条纹间距如何变化，以及竖直平移时条纹间距是否改变","why":"条纹间距与屏距成正比、与双缝间距成反比，几何量不变则条纹间距不变","do":"把平移后的几何量代入条纹间距公式，比较变化前后的间距","expr":"\\Delta x\\propto\\frac{L}{d}","cues":["屏距变小间距变小","上移间距不变","间距只跟两个量有关"],"concepts":["条纹间距","正比反比关系"]}],"128":[{"title":"压强差驱动力的来源","type":"模型选择","judge":"判断驱动力由哪两个面的压强差提供、作用在哪个面积上","why":"液态合金沿管路流动，只有左右两侧存在压强差，压力差推动整段流体前进","do":"取整段液态合金为受力对象，用两侧压强差乘以横截面积得到驱动力","expr":"F=(p_1-p_2)bh","cues":["取整段流体","看两侧压强差","乘横截面积"],"concepts":["压强差","压力","横截面积"]},{"title":"驱动力功率的对应速度","type":"关系建立","judge":"判断驱动力功率用哪个速度、与哪个力配对","why":"功率等于力与沿力方向速度的乘积，驱动力沿流动方向，应配流速","do":"用驱动力乘以流速写出功率表达式","expr":"P=Fv=(p_1-p_2)bhv","cues":["力乘流速","沿流动方向","别用别的速度"],"concepts":["功率","流速"]},{"title":"稳定流动的力平衡","type":"前提判断","judge":"判断稳定流动时驱动力与黏滞阻力、安培力的合力关系","why":"目标速率稳定意味着加速度为零，合外力为零","do":"对整段液态合金列平衡方程，把三种力写成等式","expr":"(p_1-p_2)bh=f+kv+BIL","cues":["稳定就是合力为零","三力平衡","先列平衡式"],"concepts":["平衡条件","黏滞阻力","安培力"]},{"title":"感应电动势与电阻的几何取值","type":"几何关系","judge":"判断切割磁感线的有效长度和电流通路的截面积分别取哪个尺寸","why":"磁场垂直于前后面，流动方向与磁场垂直，导电板上下短路决定电流沿高度方向","do":"用高度作切割长度写电动势，用长度乘高度作导体横截面写电阻","expr":"E=Bhv,\\quad R=\\rho\\frac{L}{Lh}","cues":["高度是切割长度","电流沿高度","电阻看长短截面"],"concepts":["动生电动势","电阻定律","有效长度"]},{"title":"安培力与流速联立消元","type":"数学处理","judge":"判断把安培力用流速表示后如何与平衡方程联立解出流速","why":"安培力中含电流，电流又由电动势和电阻决定，最终都归结为流速","do":"由欧姆定律求电流，写出安培力，代入平衡方程解出流速","expr":"I=\\frac{Bhv}{R},\\quad F_A=\\frac{B^2h^2v}{R}","cues":["安培力换成流速","先求电流","联立解流速"],"concepts":["欧姆定律","安培力","联立方程"]},{"title":"吸热正负的临界条件","type":"临界条件","judge":"判断液态合金从器件吸热要求产热与吸热的净效果满足什么不等式","why":"克服黏滞阻力和安培力做功全部转化为流体内能，只有产热小于总吸热才表现为从器件吸热","do":"写出单位时间产热与总吸热量，令产热小于总吸热，整理成温差与流速的关系","expr":"(p_1-p_2)bhv<c\\rho Lbh\\Delta T","cues":["产热要小于吸热","净吸热为正","列不等式"],"concepts":["焦耳热","比热容","能量守恒"]}],"129":[{"title":"识别匀减速模型","type":"模型选择","judge":"判断列车在隧道内的运动属于哪种运动模型，能否用匀变速直线运动公式处理","why":"题干明确说明列车在隧道中做匀减速直线运动，只有确认是匀变速，才能使用平均速度公式和位移公式","do":"从题干提取'匀减速直线运动'这一条件，确认加速度恒定、速度均匀减小","expr":"","cues":["匀减速","加速度不变","是匀变速"],"concepts":["匀变速直线运动","匀减速"]},{"title":"选平均速度求位移","type":"关系建立","judge":"判断用哪条路径求位移最省事：是用平均速度乘时间，还是先求加速度再代入位移公式","why":"已知初速度、末速度和时间，用平均速度公式可直接得位移，避免多求一个加速度未知量","do":"写出匀变速运动的平均速度等于初末速度的算术平均，再用位移等于平均速度乘时间","expr":"\\bar v=\\frac{v_0+v}{2},\\quad x=\\bar v t","cues":["取平均速度","初末速度平均","不用求加速度"],"concepts":["平均速度","位移公式"]},{"title":"统一单位与代入","type":"数学处理","judge":"判断各已知量的单位是否统一，代入时是否需要换算","why":"速度与时间的单位必须匹配，否则位移数值会差出数量级","do":"把速度统一为米每秒、时间统一为秒，再代入平均速度与位移式","expr":"x=\\frac{v_0+v}{2}\\,t","cues":["先换单位","化成米每秒","时间用秒"],"concepts":["单位换算","位移计算"]}],"130":[{"title":"碰前速度由下落高度定","type":"关系建立","judge":"A 从释放到碰前，速度该由哪段高度差决定","why":"细线不可伸长、忽略空气阻力，只有重力做功，用动能定理；下落高度是悬点到球心的距离乘以（1−cosθ），不是弧长","do":"写出 A 释放点与最低点的高度差，对 A 用动能定理求碰前速度","expr":"mgL_A(1-\\cos\\theta)=\\frac12 m v_0^2","cues":["用动能定理","看高度差","不是弧长"],"concepts":["动能定理","重力做功"]},{"title":"等质量弹性正碰交换速度","type":"模型选择","judge":"两球质量相等且发生弹性正碰时，碰后速度如何分配","why":"动量守恒与机械能守恒联立，等质量弹性正碰的唯一解是两球交换速度，A 停下、B 获得 A 碰前速度","do":"联立动量守恒和机械能守恒，代入两球质量相等，得出碰后 B 的速度等于 A 碰前速度","expr":"v_B'=v_0,\\quad v_A'=0","cues":["等质量交换速度","弹性正碰","A停下B走"],"concepts":["弹性碰撞","动量守恒","机械能守恒"]},{"title":"B 碰后上升高度换算","type":"关系建立","judge":"B 碰后做圆周运动，球心上升的最大高度与碰后速度的关系","why":"碰后绳长不变，B 绕悬点做圆周运动，只有重力做功，动能全部转化为重力势能，上升高度对应竖直方向的高度差","do":"对 B 从碰后到最高点用动能定理，把碰后速度代入求 h","expr":"mgh=\\frac12 m v_B'^2","cues":["碰后做圆周运动","动能变动能势","求竖直高度"],"concepts":["动能定理","圆周运动"]},{"title":"两球半径相同消去半径","type":"几何关系","judge":"两球半径相同、接触无挤压时，两球球心到各自悬点的距离与绳长的关系","why":"球心到悬点距离等于绳长加半径，两球半径相同，比较两球球心高度时半径项相互抵消，只需比较绳长","do":"把球心距离写成绳长加半径，在高度差中消去相同的半径","expr":"L_A=l_A+r,\\quad L_B=l_B+r","cues":["半径相同可抵消","球心距离含半径","只比绳长"],"concepts":["几何关系","球心与悬点"]}],"131":[{"title":"分清两段输电回路","type":"模型选择","judge":"要判断 R₁ 与 R₂ 各自接在哪一级变压器的副线圈回路上，不能把两个电阻当成同一回路里的串联电阻","why":"理想变压器只传递功率、不改变各级回路的独立性，升压后每一级副线圈回路有各自的电流，两电阻不在同一回路中","do":"画出两级升压结构：第一台变压器副线圈回路含 R₁，第二台变压器副线圈回路含 R₂，分别标出各自回路的电流","expr":"","cues":["分两段看","各算各的电流","不能串起来"],"concepts":["理想变压器","输电回路","功率传递"]},{"title":"由输出功率定首级电流","type":"关系建立","judge":"要判断第一级回路电流应由发电站输出功率和第一台变压器副线圈电压求出，而不是用发电站输出电压","why":"变压器原副线圈电压不同，副线圈回路电流由副线圈电压与该回路功率决定，P=UI 中的 U 必须取该回路两端电压","do":"用输出功率除以第一台变压器副线圈电压，得到 R₁ 所在回路电流","expr":"I_1=\\frac{P}{U_2}","cues":["用副线圈电压","别用原线圈电压","功率除以电压"],"concepts":["电功率公式","理想变压器电压比"]},{"title":"理想变压器功率不变","type":"前提判断","judge":"要判断第二级回路的输入功率仍等于发电站输出功率，不能因经过一次升压而折减","why":"理想变压器无能量损耗，副线圈输出功率等于原线圈输入功率，功率沿变压器逐级等量传递","do":"把第一台变压器副线圈输出功率等同于发电站输出功率，再传给第二台变压器作为输入功率","expr":"P_2=P_1=P","cues":["理想变压器不损耗","功率一路传下去","功率不变"],"concepts":["理想变压器","功率守恒"]},{"title":"由第二级电压定电流","type":"关系建立","judge":"要判断 R₂ 所在回路电流须用第二台变压器副线圈电压去除同一功率，而不是沿用第一级电流","why":"第二级副线圈电压更高，同一功率下回路电流更小，两回路电流不相等","do":"用输出功率除以第二台变压器副线圈电压，得到 R₂ 所在回路电流","expr":"I_2=\\frac{P}{U_3}","cues":["电压更高电流更小","重新算电流","用第二级电压"],"concepts":["电功率公式","理想变压器电压比"]},{"title":"两段损失功率相加","type":"结论整理","judge":"要判断总损失是两回路各自焦耳热功率之和，不能只算其中一段或用总电流乘总电阻","why":"两电阻分处不同回路，各自发热互不影响，总损失功率为各回路 I²R 之和","do":"分别算出两回路的 I²R 再相加","expr":"P_损=I_1^2R_1+I_2^2R_2","cues":["两段分别算","平方乘电阻","再相加"],"concepts":["焦耳定律","输电损耗"]}],"132":[{"title":"判断两力的方向","type":"前提判断","judge":"负电荷逆时针做圆周运动时，洛伦兹力和电场力分别指向圆心还是背离圆心","why":"由左手定则，负电荷逆时针运动、磁场垂直纸面向里，洛伦兹力背离圆心；只有电场力指向圆心，才能与洛伦兹力合成向心力","do":"用左手定则定洛伦兹力方向，再由匀速圆周运动需要指向圆心的合力，反推电场力方向","expr":"","cues":["左手定则","负电荷反向","洛伦兹力向外","电场力指向圆心"],"concepts":["洛伦兹力","左手定则","向心力"]},{"title":"列向心力方程","type":"关系建立","judge":"把洛伦兹力与电场力之差作为向心力，还是把两者之和作为向心力","why":"两力方向相反，合力大小为二者之差，且该合力提供向心力","do":"对两种磁感应强度分别写合力等于质量乘速度平方比半径的方程","expr":"qE_1-qvB_1=\\frac{mv^2}{r_1},\\quad qE_2-qvB_2=\\frac{mv^2}{r_2}","cues":["两力反向相减","合力提供向心力","速率不变"],"concepts":["向心力","牛顿第二定律","电场力"]},{"title":"用场强表达式代换","type":"关系建立","judge":"把电场强度用该处到 O 点的距离表示，并判断该距离就是粒子轨道半径","why":"题设场强大小与到 O 点距离成反比，粒子做以 O 为圆心的圆周运动，所在处到 O 的距离即半径","do":"将两处的场强分别写成常量比半径，代入向心力方程","expr":"E=\\frac{k}{r}","cues":["场强随距离变","距离就是半径","代入消去场强"],"concepts":["点电荷电场","反比关系"]},{"title":"联立求半径关系","type":"数学处理","judge":"消去质量、电荷量和速率，得到两种情况下半径与磁感应强度的关系","why":"速率相同、粒子相同，联立两方程可消去共同量，只剩半径与磁感应强度的关系","do":"将两方程相减或相比，消去含速度的项，解出半径随磁感应强度变化的表达式","expr":"","cues":["两式联立","消去速度","比较半径大小"],"concepts":["方程联立","匀速圆周运动"]},{"title":"判断电势能高低","type":"结论整理","judge":"负电荷在电势较低处电势能较大，需先判断哪处电势低","why":"沿电场线方向电势降低，电场线沿径向向外，故半径小处电势低；负电荷电势能等于电荷量与电势乘积，电势越低电势能越大","do":"由半径大小定电势高低，再由负电荷性质定电势能大小","expr":"E_p=q\\varphi,\\quad q<0","cues":["沿电场线电势降低","负电荷电势能反着来","半径小电势低"],"concepts":["电势","电势能","电场线"]}],"133":[{"title":"有效长度随位置变化","type":"几何关系","judge":"导体棒在两导轨间滑行时，接入回路的有效长度随位移如何变化","why":"两导轨延长线交于角平分线上的点，导轨成夹角，棒始终垂直于角平分线，故有效长度与到交点的距离成正比","do":"由交点位置和已知长度定出比例系数，写出有效长度随位移（或到交点距离）的线性表达式","expr":"l=kx","cues":["看几何","长度在变","和距离成正比"],"concepts":["有效长度","几何相似"]},{"title":"匀速段电流恒定","type":"关系建立","judge":"匀速运动阶段感应电动势、回路电阻都随有效长度变化时，感应电流是否变化","why":"电动势与有效长度成正比，电阻也与有效长度成正比（单位长度电阻给定），比值与长度无关","do":"写出电动势和电阻表达式后相除，看长度是否约去","expr":"I=Blv/(λl)=Bv/λ","cues":["长度约掉","电流不变","电阻也变"],"concepts":["法拉第电磁感应定律","电阻定律"]},{"title":"撤力后变减速的动力学","type":"模型选择","judge":"撤去拉力后棒只受安培力，速度与有效长度同时变化，能否直接用匀变速公式","why":"安培力随速度和有效长度变化，加速度不是恒量，只能用动量定理或能量关系处理","do":"对减速段列动量定理，把安培力冲量写成对位移的积分（求和）","expr":"-ΣBIlΔt=mv-mv₀","cues":["不能匀变速","用动量定理","安培力在变"],"concepts":["动量定理","安培力"]},{"title":"冲量转化为面积","type":"数学处理","judge":"安培力冲量中的求和项能否化为与位移成正比的量的累加，从而用图像面积求","why":"安培力冲量中含速度乘时间，即位移元，求和变成对位移的线性函数求和","do":"把冲量写成系数乘位移的求和，作该量与位移的关系图，用梯形面积计算","expr":"Σl·Δx=(k/2)(x₂²-x₁²)","cues":["画图求面积","化成位移求和","梯形面积"],"concepts":["微元求和","图像面积"]},{"title":"安培力做功与焦耳热","type":"关系建立","judge":"减速段产生的焦耳热是否等于安培力做功的大小，能否用功的面积法求","why":"导轨电阻不计，只有棒有电阻，克服安培力做的功全部转化为焦耳热","do":"对减速段把安培力做功写成对位移的求和，作力与位移图求面积，再由功能关系得热量","expr":"Q=W_安=ΣBIl·Δx","cues":["克服安培力做功","功转成热","求面积"],"concepts":["功能关系","焦耳热"]},{"title":"电荷量用平均电流","type":"关系建立","judge":"求通过棒的电荷量时，能否用平均电动势和平均电流，而不是瞬时值","why":"电荷量由电流对时间的积累决定，磁通量变化与回路总电阻之比给出电荷量","do":"写出平均电动势，结合回路电阻（随长度变化）分析电荷量表达式","expr":"q=ΔΦ/R_总","cues":["用平均值","电荷量看磁通量","别用瞬时电流"],"concepts":["电荷量","平均感应电动势"]}],"134":[{"title":"摆长取线长加半径","type":"关系建立","judge":"单摆公式中的摆长 L 是悬点到球心的距离，还是仅指摆线长度","why":"单摆周期公式中的摆长是悬点到摆球球心的距离，卷尺只能量到线长和球直径","do":"把测得的摆线长度与球半径相加，得到摆长 L","expr":"L=l+\\frac{d}{2}","cues":["摆长加半径","线长不是摆长","球心到悬点"],"concepts":["单摆摆长","悬点","球心"]},{"title":"小偏角近似条件","type":"近似条件","judge":"释放摆球时的偏角应满足什么条件，单摆才近似做简谐运动","why":"只有偏角很小时 sinθ≈θ，周期才与振幅无关，公式 T=2π√(L/g) 才成立","do":"把摆球拉至偏角小于 5° 的位置由静止释放","expr":"\\theta<5^\\circ","cues":["偏角要小","小于五度","近似简谐"],"concepts":["简谐运动","小角度近似"]},{"title":"多次全振动测周期","type":"实验操作","judge":"测周期时是测一次全振动还是测多次全振动再求平均","why":"手机秒表手动计时反应时间误差固定，测多次全振动可把该误差摊薄","do":"测 20 次全振动的总时间 t，用 t/20 求周期","expr":"T=\\frac{t}{20}","cues":["测二十次","总时间除以次数","减小计时误差"],"concepts":["周期测量","误差均摊"]},{"title":"表中周期取平均","type":"数据处理","judge":"表中同一摆长下三次计时得到的周期该取哪一个值","why":"同一条件多次测量取平均值可减小偶然误差，表中已给出三次周期","do":"把该摆长对应的三次周期相加除以 3，保留三位有效数字","expr":"T=\\frac{T_1+T_2+T_3}{3}","cues":["三次取平均","保留三位","取中间值"],"concepts":["平均值","有效数字"]},{"title":"由周期式反解 g","type":"关系建立","judge":"重力加速度表达式应由周期公式中的摆长 L 反解，还是用线长直接代入","why":"周期公式 T=2π√(L/g) 中的 L 是摆长（含球半径），反解才能得到 g 的正确表达式","do":"对 T=2π√(L/g) 平方后解出 g，其中 L=l+d/2","expr":"g=\\frac{4\\pi^2 L}{T^2}=\\frac{4\\pi^2\\left(l+\\frac{d}{2}\\right)}{T^2}","cues":["平方后解出","用摆长不用线长","四派方乘摆长"],"concepts":["单摆周期公式","重力加速度"]},{"title":"阻力误差看质量体积","type":"误差分析","judge":"为减小空气阻力影响，摆球应选质量大还是小、体积大还是小","why":"空气阻力与体积（迎风面积）有关，而重力与质量有关；质量大、体积小可使阻力相对重力可忽略","do":"比较阻力与重力的相对大小，选择质量大、体积小的摆球","expr":"","cues":["质量大体积小","阻力相对小","密度要大"],"concepts":["空气阻力","误差分析"]}],"135":[{"title":"读图取波长振幅","type":"图像读取","judge":"从波形图上判断相邻同相点间距为一个波长、波峰到平衡位置的距离为振幅","why":"波长和振幅是波的两个基本参量，只能由波形图的几何特征直接读出，与传播方向、时刻无关","do":"在实线（或虚线）上找两个相邻波峰（或相邻平衡位置且振动同相的点），量其横坐标差；再量波峰到x轴的距离","expr":"","cues":["看相邻波峰","量峰到横轴"],"concepts":["波长","振幅","波形图"]},{"title":"由传播方向定平移方向","type":"前提判断","judge":"波沿x轴负方向传播时，波形整体向x轴负方向平移，虚线是实线向负方向平移的结果","why":"波的传播方向决定波形平移方向，平移方向反了会把时间关系写成补一个周期，导致周期解错","do":"比较实线与虚线同一相位点（如波峰）的横坐标，确认虚线相对实线是向左移动的","expr":"","cues":["向左平移","沿负方向传"],"concepts":["波的传播方向","波形平移"]},{"title":"平移量与周期的多解关系","type":"关系建立","judge":"实线到虚线的时间间隔对应波形平移的距离，该距离等于 nλ 加一个不足 λ 的余量，需写出含整数 n 的通式","why":"波形具有空间周期性，平移整数个波长后图形重合，因此时间间隔与周期之间是含整数 n 的多值关系，不能只取最小平移","do":"找出虚线相对实线的最小左移距离，写成 Δx 与 λ 的关系，再由 v=λ/T 换算成 Δt 与 T 的关系","expr":"Δt=nT+\\frac{\\Delta x}{\\lambda}T","cues":["可能多走几个波长","加整数个周期"],"concepts":["空间周期性","波的平移","周期"]},{"title":"用周期条件定n取值","type":"临界条件","judge":"由周期大于给定时间间隔这一不等式，判断整数 n 只能取哪个值","why":"题目给出的周期下限是排除多解的唯一依据，不列不等式就无法把通式收成唯一解","do":"把通式代入 T>Δt 的不等式，解出 n 的取值范围，取满足条件的非负整数","expr":"T=\\frac{\\Delta t}{n+\\frac{\\Delta x}{\\lambda}}>\\Delta t\\Rightarrow n<\\ldots","cues":["周期比时间间隔大","只能取零"],"concepts":["周期","多解取舍","不等式"]},{"title":"由周期波长求波速","type":"关系建立","judge":"波速由介质决定，数值上等于波长与周期之比，须用已定出的唯一周期代入","why":"v=λ/T 是波速、波长、周期的基本关系，周期取错则波速必错","do":"把读出的波长和定出的周期代入波速公式计算","expr":"v=\\frac{\\lambda}{T}","cues":["波长除以周期","用定下的周期"],"concepts":["波速","波长","周期"]},{"title":"半周期对应波形反相","type":"结论整理","judge":"经过半个周期，各质点振动状态反向，波形图关于x轴上下翻转，而不是左右平移","why":"简谐波经 T/2 后每个质点位移变为相反数，图像是沿y轴翻转；与沿x轴平移半个波长在图形上等效，但作图依据是振动状态反相","do":"把实线在0~2.0 m内关于x轴作对称图形，得到该时刻的波形","expr":"y(x,t+\\frac{T}{2})=-y(x,t)","cues":["上下翻过来","关于横轴对称"],"concepts":["简谐波","振动状态反相","波形图"]}],"136":[{"title":"冲量方向与速度反向","type":"前提判断","judge":"合力的冲量方向应取沿轨道向上还是沿运动方向","why":"冲量等于动量变化量，初动量为零、末动量沿轨道向下，故冲量方向沿轨道向上","do":"规定沿轨道向下为正，用末动量减初动量确定冲量方向，再换算成与水平方向的夹角","expr":"\\vec I=\\Delta\\vec p=m\\vec v-0","cues":["冲量看动量变化","方向沿轨道向上","与速度反向"],"concepts":["动量定理","冲量","动量变化量"]},{"title":"释放后动力按剩余质量算","type":"模型选择","judge":"释放一枚弹后，水平动力是按载弹总质量还是按剩余质量代入关系式","why":"题给动力与质量满足的函数关系，动力随无人机当前质量变化，释放后质量减少动力也随之改变","do":"用释放后剩余质量代入动力关系式，再对剩余整体列水平方向牛顿第二定律求加速度","expr":"F'=f(m_{\\text{剩}}),\\quad F'-f_{\\text{阻}}=m_{\\text{剩}}a","cues":["质量变了动力也变","按剩余质量算","先求加速度"],"concepts":["牛顿第二定律","变质量系统","动力与质量关系"]},{"title":"两弹平抛初速不同","type":"关系建立","judge":"两弹离开无人机时的水平初速度是否相同，落地点距离由什么决定","why":"两弹先后释放，后释放的弹在无人机匀加速飞行中获得更大水平速度，平抛水平射程由各自初速和同一高度决定","do":"先由匀加速运动求时间间隔内无人机速度增量与位移，得到第二枚弹的释放初速，再分别写两弹平抛的水平射程并作差","expr":"v_2=v_1+a\\Delta t,\\quad x_i=v_i\\sqrt{\\frac{2H}{g}}","cues":["后释放的速度大","平抛高度相同","射程差就是间距"],"concepts":["平抛运动","匀加速直线运动","运动学公式"]},{"title":"无人机速度不变定甲落点","type":"模型选择","judge":"第三问中无人机速度始终不变，甲释放后是否还随无人机加速","why":"题设明确无人机速度始终不变，甲相对无人机无初速释放即具有与无人机相同的水平速度，做平抛运动","do":"用平抛规律求甲落地时间与水平位移，确定甲落地瞬间乙相对甲的水平与竖直位置关系","expr":"t_1=\\sqrt{\\frac{2H}{g}},\\quad x_甲=v_0t_1","cues":["速度始终不变","甲做平抛","乙在甲正上方"],"concepts":["平抛运动","运动的独立性","相对位置"]},{"title":"距离函数对称轴是否在区间","type":"临界条件","judge":"两弹距离平方的二次函数最小值点是否落在乙飞行时间的有效区间内","why":"二次函数在对称轴处取最小值，但对称轴位置随发射速度取值变化，只有落在有效时间区间内才能取到","do":"写出距离平方关于乙飞行时间的二次函数，求对称轴，与有效区间比较，分情况讨论最小值","expr":"d^2=(v_0t)^2+(H-\\tfrac12gt^2)^2","cues":["配方找对称轴","看对称轴在不在区间","分情况讨论"],"concepts":["二次函数极值","临界条件","相对运动"]}],"137":[{"title":"识别单位符号含义","type":"前提判断","judge":"判断 THz 中 Hz 代表什么物理量的单位","why":"Hz 是国际单位制中频率的单位，1 Hz 表示每秒振动一次，这是单位换算的出发点","do":"把 THz 拆成 T 与 Hz 两部分，先确认 Hz 对应频率","expr":"1\\ \\mathrm{Hz}=1\\ \\mathrm{s^{-1}}","cues":["赫兹是频率单位","先看后面的赫兹"],"concepts":["频率","单位制"]},{"title":"识别词头 T 的含义","type":"前提判断","judge":"判断词头 T（太）表示多大的倍数","why":"SI 词头 T 表示 10¹²，只改变数量级，不改变所对应的物理量种类","do":"写出 T 的倍数并说明它只是倍数词头","expr":"1\\ \\mathrm{THz}=10^{12}\\ \\mathrm{Hz}","cues":["太是十的十二次方","词头只管倍数"],"concepts":["SI 词头","数量级"]},{"title":"由单位反推物理量","type":"关系建立","judge":"判断带倍数词头的 Hz 整体对应哪一类物理量","why":"词头不改变单位所量度的物理量，故 THz 与 Hz 同属频率单位，与长度、能量、时间无关","do":"把 THz 与各选项物理量的单位逐一对照，确认只有频率的单位是 Hz 的倍数","expr":"[\\mathrm{THz}]=[\\mathrm{Hz}]=\\mathrm{s^{-1}}","cues":["词头不改变物理量","还是频率"],"concepts":["频率","单位与物理量的对应"]}],"138":[{"title":"电场线疏密定场强","type":"图像读取","judge":"由图判断 A、B 两点所在处电场线的疏密程度，从而比较两点场强大小","why":"电场线的疏密表示场强的强弱，密处场强大、疏处场强小，这是电场线的基本性质","do":"观察图中 A、B 附近电场线的疏密，比较两处场强大小","expr":"","cues":["看疏密","线密场强大","A处线稀"],"concepts":["电场线","电场强度"]},{"title":"沿电场线方向判电势","type":"关系建立","judge":"判断 A、B 两点电势的高低，并进一步判断电子移动时电势能的变化","why":"顺着电场线方向电势逐渐降低；电子带负电，电势能变化与电势变化相反","do":"沿电场线走向确定 A、B 电势高低，再用负电荷电势能关系判断电子从 A 到 B 电势能增减","expr":"E_p=q\\varphi,\\ q=-e","cues":["顺着线电势降","电子带负电","电势能反着变"],"concepts":["电势","电势能","电场线方向"]},{"title":"导体静电平衡等势","type":"前提判断","judge":"判断同一块金属极板上不同位置（上表面 C 与下表面 D）的电势是否相等","why":"金属导体达到静电平衡后是等势体，表面是等势面，整块极板电势处处相等","do":"确认 C、D 同属一块处于静电平衡的金属极板，直接得出两点电势相等","expr":"","cues":["金属是等势体","同一极板电势相同","静电平衡"],"concepts":["静电平衡","等势体"]},{"title":"曲线电场线不即轨迹","type":"模型选择","judge":"判断只在静电力作用下由静止释放的电子能否沿弯曲电场线 ab 运动","why":"电子所受静电力沿电场线切线方向，而做曲线运动需要力指向轨迹凹侧，弯曲电场线的切线方向与轨迹弯曲要求不匹配","do":"比较 E 点电场线切线方向与电子若沿 ab 运动所需的向心方向，判断二者是否一致","expr":"","cues":["力沿切线","曲线要指向凹侧","不会沿电场线走"],"concepts":["曲线运动条件","静电力方向"]}],"139":[{"title":"三力平衡汇交判断","type":"前提判断","judge":"灯受重力与两根绳的拉力共三个力，三力平衡时作用线是否必须交于一点","why":"三力平衡的合力为零，若三力不共点则会对灯产生净力矩，灯不能静止","do":"画出灯的重力作用线（竖直过灯的重心）与左右两绳拉力作用线，检查三者是否交于同一点","expr":"","cues":["三力共点","看作用线交点","灯受三个力"],"concepts":["三力平衡","共点力","力矩平衡"]},{"title":"选灯为受力对象","type":"模型选择","judge":"以灯为研究对象还是以结点或整体为研究对象","why":"题目只要求两绳拉力与重力G的关系，灯受三力且重力已知，隔离灯可直接建立闭合矢量三角形","do":"隔离艺术灯，画重力G竖直向下、左绳拉力沿绳指向左上、右绳拉力沿绳指向右上","expr":"","cues":["隔离灯","取灯为对象","画三力"],"concepts":["隔离法","受力分析"]},{"title":"矢量三角形求拉力比","type":"关系建立","judge":"两绳拉力与重力构成的封闭三角形中，各边对应哪个角","why":"三力平衡时三力首尾相接构成闭合三角形，由正弦定理可把拉力比化为对角正弦之比","do":"把G、T左、T右平移成闭合三角形，找出各力所对的角（由绳与水平夹角45°、60°推出），用正弦定理比较两拉力大小","expr":"\\frac{T_1}{\\sin\\alpha}=\\frac{T_2}{\\sin\\beta}=\\frac{G}{\\sin\\gamma}","cues":["矢量三角形","正弦定理","看对角"],"concepts":["矢量三角形","正弦定理","力的合成"]},{"title":"撤绳后能否平衡","type":"临界条件","judge":"撤去AB绳改接C与B（或C与D）后，灯在原位置能否仍保持三力共点平衡","why":"灯位置不变则重力作用线不变，新绳方向改变后三力作用线一般不再交于一点，合力矩不为零","do":"保持灯位置不变，画出新连接方式下两绳的方向，检查三力作用线是否仍汇交于一点","expr":"","cues":["位置不变","还能共点吗","力矩不为零"],"concepts":["共点力平衡","力矩"]}],"140":[{"title":"双股绕法的有效匝数","type":"模型选择","judge":"并成双股后再绕两圈，穿过线圈A的磁通量应按几匝计算","why":"双股并绕时两股线在同一处、绕向相同，磁通量相互叠加，等效匝数不是简单相加的4匝，而是每股各绕2圈、两股并联，有效匝数需按单股路径判断","do":"画出双股并绕的走向，比较两股的绕向与所围面积，确定磁通量是叠加还是抵消，得出有效匝数","expr":"","cues":["双股并绕","绕向相同","有效匝数"],"concepts":["磁通量","匝数","并联"]},{"title":"区分自感与互感","type":"模型选择","judge":"求线圈A的电动势时，应算螺线管的自感电动势还是A的互感（感应）电动势","why":"A是独立闭合回路，其电动势来自螺线管磁场变化穿过A的磁通量变化，属于互感/感应电动势，与螺线管自身的自感电动势不是一回事","do":"明确研究对象是线圈A，写出ε=N_A·ΔΦ/Δt，其中Φ=B·S为螺线管横截面内的磁通","expr":"\\varepsilon=N_A\\dfrac{\\Delta\\Phi}{\\Delta t}","cues":["算A的电动势","不是自感","穿过A的磁通"],"concepts":["互感","法拉第电磁感应定律","磁通量"]},{"title":"由I-t图读变化率","type":"图像读取","judge":"各时间段内电流是恒定还是线性变化，变化率取哪一段斜率","why":"感应电动势只由磁通量变化率决定，电流恒定时ΔΦ=0无电动势，只有线性变化段才有恒定电动势","do":"读图2各段的斜率ΔI/Δt，找出电流恒定段与线性下降段，分别求B的变化率","expr":"\\dfrac{\\Delta B}{\\Delta t}=a\\dfrac{\\Delta I}{\\Delta t}","cues":["看斜率","恒定段无电动势","线性下降"],"concepts":["变化率","图像斜率","磁感应强度"]},{"title":"电荷量用磁通量变化算","type":"关系建立","judge":"求通过A的电荷量时，是否可用q=ΔΦ_total/R而无需知道时间细节","why":"电荷量只取决于总磁通量变化量与电阻，与变化快慢无关；电流恒定段ΔΦ=0，故该段电荷量为零","do":"对每个时间段求穿过A的总磁通量变化量，除以R得电荷量，再按段求和","expr":"q=\\dfrac{\\Delta\\Phi_{\\text{总}}}{R}","cues":["电荷量看磁通量变化","与快慢无关","恒定段为零"],"concepts":["电荷量","磁通量变化量","欧姆定律"]},{"title":"焦耳热只在变化段产生","type":"临界条件","judge":"哪些时间段有感应电流、才产生焦耳热","why":"电流恒定时无感应电动势、无电流，焦耳热为零；只有电流变化的两段才有电动势和发热","do":"分别对两个变化段用Q=ε²t/R求热量，再相加，恒定段不计","expr":"Q=\\dfrac{\\varepsilon^2}{R}t","cues":["只有变化段发热","恒定段不发热","分段求热"],"concepts":["焦耳定律","感应电动势","分段求和"]}],"141":[{"title":"光子能量下限","type":"前提判断","judge":"γ光子能量与一对正负电子静止能量（2m_ec²）的大小关系","why":"光子转化为正负电子对时，能量至少等于这对粒子的静止能量；本题光子还要额外打出电子，故光子能量必大于2m_ec²","do":"写出产生电子对所需的最小能量2m_ec²，与光子能量比较","expr":"E_γ>2m_ec^2","cues":["至少一对电子","还要打出电子"],"concepts":["质能方程","能量守恒"]},{"title":"由半径定动量","type":"关系建立","judge":"三条径迹的曲率半径与对应电子动量成正比","why":"电子在匀强磁场中做圆周运动，洛伦兹力提供向心力，得p=eBR，故半径直接反映动量大小","do":"对径迹1、2、3分别写eBv=m_ev²/R，化为p=eBR","expr":"p=eBR","cues":["半径看动量","洛伦兹力提供向心力"],"concepts":["洛伦兹力","圆周运动","动量"]},{"title":"光子动量守恒","type":"关系建立","judge":"把光子动量与三个电子动量按矢量关系联系起来","why":"氢原子和质子视为静止，初态只有光子动量，末态为三个电子动量之和，动量守恒","do":"写出光子动量等于三条径迹对应动量矢量和，结合共切于O点的方向关系求大小","expr":"\\vec p_\\gamma=\\vec p_1+\\vec p_2+\\vec p_3","cues":["初态只有光子","三电子动量相加"],"concepts":["动量守恒","矢量合成"]},{"title":"阻力致速度衰减","type":"模型选择","judge":"阻力正比于速率时，速率随时间线性减小，从而把路程与初速度、时间联系起来","why":"阻力f=kv，由牛顿第二定律m_edv/dt=-kv得v=v_0-k t/m_e，速度减为零的时刻t=m_ev_0/k，与半径给出的初速度挂钩","do":"对沿径迹运动的电子列动量定理并求和，得总路程s与v_0、k的关系","expr":"m_e\\frac{dv}{dt}=-kv,\\quad s=\\frac{m_ev_0}{k}","cues":["阻力正比速率","速度线性减小"],"concepts":["变力冲量","动量定理","微元求和"]},{"title":"位移与路程区分","type":"几何关系","judge":"M、P、Q是速度减为零的位置，O到它们的距离是位移而非路程","why":"径迹是圆弧，电子沿弧运动到停止，位移是弦长（O到停止点的直线距离），路程是弧长，两者不能混用","do":"由半径和停止时转过的圆心角求弦长OP、OQ，再比较比值","expr":"OP=2R_2\\sin\\frac{\\theta_2}{2}","cues":["位移是弦长","路程是弧长"],"concepts":["圆周运动","位移与路程"]}],"142":[{"title":"按探究目的选装置","type":"前提判断","judge":"要探究水平方向分运动的特点，需要把平抛运动与哪种运动对比，从而判断甲、乙哪个装置能提供这种对比","why":"平抛的水平分运动是匀速直线运动，只有让平抛小球与同时运动的匀速直线运动小球在水平方向位置始终对应，才能验证水平分运动规律","do":"看两装置中是否有一个同时做匀速直线运动的参照小球（或参照物），选出能同时呈现平抛与匀速直线运动的装置","expr":"","cues":["看有没有对比小球","要同时运动","甲只有一个球"],"concepts":["运动的合成与分解","平抛运动","对比实验"]},{"title":"背板必须竖直","type":"实验操作","judge":"判断背板放置方向对记录轨迹的影响，确定背板应竖直还是可以倾斜","why":"小球在白纸上留下的印迹是它在竖直平面内运动的投影，背板倾斜会使印迹对应的水平、竖直坐标被压缩，轨迹失真","do":"检查背板是否与水平面垂直，把背板调成竖直","expr":"","cues":["背板要竖直","歪了轨迹就变形","印迹要反映真实位置"],"concepts":["平抛运动轨迹","实验装置调节"]},{"title":"斜槽末端调水平","type":"临界条件","judge":"判断斜槽末端切线是否水平，决定小球离开斜槽时初速度的方向","why":"只有末端切线水平，小球离开时速度才沿水平方向，才是平抛运动；否则是斜抛，水平分运动不再是匀速","do":"调节斜槽使末端切线水平，可用小球在末端附近能静止或水平飞出检验","expr":"","cues":["末端要水平","不然就是斜抛","初速度必须水平"],"concepts":["平抛运动条件","初速度方向"]},{"title":"坐标原点取球心","type":"几何关系","judge":"判断坐标原点应取斜槽末端球心位置还是末端在背板上的投影点","why":"小球离开斜槽时球心所在位置才是平抛的抛出点，轨迹描述的是球心运动，取投影点会使竖直位移整体偏移一个球半径","do":"把坐标原点定在小球位于斜槽末端时球心在白纸上的投影处","expr":"","cues":["原点取球心","不是槽口投影","差一个半径"],"concepts":["平抛起点","球心轨迹"]},{"title":"每次同高度释放","type":"实验操作","judge":"判断多次释放小球时是否必须从同一位置由静止释放，以及是否要求等间距下降","why":"只有每次初速度相同，各次印迹才属于同一条平抛轨迹，才能连成一条曲线；等间距下降与初速度无关，不是必要条件","do":"每次让小球从斜槽上同一位置由静止释放，重复多次取点","expr":"","cues":["同一位置释放","初速度要一样","不用等间距"],"concepts":["控制变量","平抛初速度"]},{"title":"选靠近轨迹的点算速度","type":"数据处理","judge":"在若干印迹点中判断哪一点更贴近实际轨迹、更适合用来求水平速度","why":"偏离轨迹的点含有较大测量误差，用它算出的时间和速度不可靠；应取落在平滑曲线上的点","do":"比较各点与拟合曲线的偏离程度，选最贴合曲线的点，用竖直位移求时间再求水平速度","expr":"t=\\sqrt{\\frac{2y}{g}},\\quad v_0=\\frac{x}{t}","cues":["选贴近曲线的点","偏的点误差大","先由竖直位移求时间"],"concepts":["平抛运动规律","实验误差"]}],"143":[{"title":"判断液体是否浸润","type":"图像读取","judge":"由细管内液面上升且呈凹液面，判断液体对管壁是浸润还是不浸润","why":"浸润液体在毛细管中液面呈凹形并沿管壁上升，不浸润液体呈凸形并下降，液面形状与升降方向是判断依据","do":"观察图中细管内液面相对管外液面的高低及弯月面凹凸方向","expr":"","cues":["液面是凹的","管内液面比外面高","看弯月面形状"],"concepts":["浸润","毛细现象","表面张力"]},{"title":"管径变小对液面高度的影响","type":"关系建立","judge":"细管仅内径变小时，毛细上升高度是升高、不变还是降低","why":"毛细上升高度与管内径成反比，内径越小毛细现象越显著，液柱升得越高","do":"比较原细管与新细管的内径大小，按毛细高度随内径减小而增大的规律判断升降","expr":"h=\\frac{2\\gamma\\cos\\theta}{\\rho g r}","cues":["内径越小升得越高","毛细现象更明显","管越细液面越高"],"concepts":["毛细现象","内径","表面张力"]},{"title":"选活塞与液体为对象求压强","type":"模型选择","judge":"求封闭气体压强时，取活塞连同其上方液体整体为受力对象，还是只取活塞","why":"活塞与液体一起静止，整体受力平衡可一次性消去活塞与液体之间的作用力，避免多引入未知数","do":"对活塞加液体整体列竖直方向平衡方程，得初态气体压强","expr":"p_A S=p_0 S+(m_1+m_2)g","cues":["取整体","把液体和活塞一起看","别管内力"],"concepts":["受力平衡","整体法","封闭气体压强"]},{"title":"吸走液体后压强重算","type":"前提判断","judge":"液体全部吸走后，活塞上方只剩大气，末态气体压强由什么决定","why":"液体质量消失，活塞上方压力只剩大气压力，气体压强须重新由活塞平衡确定，不能沿用初态压强","do":"对单独活塞列平衡方程，得末态压强","expr":"p_B S=p_0 S+m_1 g","cues":["液体没了","只剩活塞","压强变小了"],"concepts":["受力平衡","封闭气体压强"]},{"title":"等温过程用玻意耳定律","type":"模型选择","judge":"从A到B气体温度是否变化，能否用玻意耳定律联系两态体积与压强","why":"瓶导热良好且环境温度不变、过程缓慢，气体始终与外界热平衡，温度不变，pV乘积守恒","do":"写出 p_A V_A=p_B V_B，代入两态压强求末态体积","expr":"p_A V_A=p_B V_B","cues":["温度不变","缓慢吸走","导热良好"],"concepts":["玻意耳定律","等温过程","理想气体"]},{"title":"热力学第一定律定做功","type":"关系建立","judge":"用吸收的热量与内能变化反推气体对外做功时，等温过程中内能变化取多少","why":"理想气体温度不变则内能不变，第一定律中ΔU=0，吸收的热量全部用于对外做功","do":"对A到B列热力学第一定律，令ΔU=0，由已知吸热量求对外做功","expr":"Q=\\Delta U+W,\\quad \\Delta U=0\\Rightarrow W=Q","cues":["温度不变内能不变","热量全用来做功","理想气体内能只看温度"],"concepts":["热力学第一定律","内能","等温过程"]}],"144":[{"title":"小弧高差近似","type":"近似条件","judge":"h<<r 时能否把圆弧上的运动按小角近似处理，用弧长或水平位移代替几何量","why":"只有小角近似下回复力才与位移成正比，才能判定为简谐运动并写出周期","do":"对偏离最低点的位置取角度 θ，用 sinθ≈θ、弧长≈水平位移，把重力沿切向分量写成与 x 成正比","expr":"F=-\\frac{mg}{r}x","cues":["小角近似","摆角很小","近似成直线"],"concepts":["简谐运动","小角近似","回复力"]},{"title":"分解b的两个方向运动","type":"模型选择","judge":"b 在圆弧面上应分解为沿槽轴线方向的匀速直线运动和垂直轴线方向的简谐运动，两方向独立","why":"槽面光滑且两方向受力互不影响，垂直方向受回复力做简谐运动，平行方向不受力做匀速运动","do":"把初速度 vb 沿 MN 方向和垂直 MN 方向分解，分别写出两方向的运动方程","expr":"v_{b\\parallel}=v_b\\cos45^\\circ,\\quad v_{b\\perp}=v_b\\sin45^\\circ","cues":["速度分解","两个方向分开看","沿槽匀速"],"concepts":["运动的独立性","简谐运动","速度分解"]},{"title":"最高点相遇定时","type":"关系建立","judge":"b 第一次到达最高点的条件是其垂直方向速度减为零，且此时高度与 a 的释放高度相同，据此确定 b 的初速度与时间","why":"题目说两物块同时到达同一最高点，垂直方向做简谐运动的物体第一次到最高点用时为四分之一周期","do":"令垂直方向速度为零，写出到达最高点的时间 t1 与高度关系，再与 a 从 A 滑到最高点的时间相等联立","expr":"t_1=\\frac{T}{4}=\\frac{\\pi}{2}\\sqrt{\\frac{r}{g}},\\quad h=\\frac{v_{b\\perp}^2}{2g}","cues":["四分之一周期","同时到达","高度相同"],"concepts":["简谐运动周期","运动学关系","同时性"]},{"title":"弹性碰撞定碰后速度","type":"关系建立","judge":"碰撞只发生在垂直槽轴线方向，沿槽方向速度不变；用动量守恒和机械能守恒求碰后两物块速度","why":"两物块在最高点相碰，接触面法向沿垂直轴线方向，弹性碰撞满足动量与动能同时守恒","do":"对垂直方向列动量守恒和机械能守恒方程，联立解出碰后 a、b 的速度","expr":"m v_{b\\perp}=m v_{b\\perp}'+m_a v_a,\\quad \\frac12 m v_{b\\perp}^2=\\frac12 m v_{b\\perp}'^2+\\frac12 m_a v_a^2","cues":["弹性碰撞","动量守恒","动能守恒"],"concepts":["弹性碰撞","动量守恒","机械能守恒"]},{"title":"滑离边界的临界轨迹","type":"临界条件","judge":"a 碰后沿槽方向匀速、垂直方向做简谐运动，要从 NQ 之间滑离，需判断其横向位移与槽宽 d、纵向位置 L 的组合落在哪个临界情形","why":"a 在槽内做周期性横向往复运动，能否从 NQ 边滑出取决于到达边界时横向坐标是否在 0 到 d 之间","do":"写出 a 的横向坐标随时间的变化，结合纵向匀速位移 L=v_a t，按不同周期数分类讨论滑出条件","expr":"y(t)=A\\sin\\omega t,\\quad L=v_a t","cues":["周期性","分情况讨论","边界条件"],"concepts":["简谐运动","临界条件","运动的合成"]},{"title":"多解周期取整","type":"数学处理","judge":"滑离时间 t 需按 a 完成整数个或半整数个横向周期的时刻分类，得到 L 的多值区间","why":"a 的横向运动具有周期性，每个周期内都有机会从 NQ 边滑出，故 L 不是单值而是随整数 n 变化的一系列区间","do":"把 t 写成 nT 加特定相位的形式，代入 L=v_a t，整理出含整数 n 的 L 范围","expr":"L=v_a(nT+\\Delta t)","cues":["整数个周期","多解","含n的区间"],"concepts":["周期性","多解讨论","运动合成"]}],"145":[{"title":"最高点的加速度方向","type":"前提判断","judge":"质点在拱形赛道最高点时，加速度是否为零、方向指向哪里","why":"做曲线运动的质点速度沿切线，加速度有指向轨迹凹侧（圆心）的法向分量，故最高点加速度竖直向下、不为零","do":"画出最高点速度的切线方向，确定曲率中心在正下方，判断向心加速度竖直向下","expr":"a_n=\\dfrac{v^2}{R}\\neq 0","cues":["速度沿切线","加速度指向圆心","最高点速度不为零"],"concepts":["曲线运动","向心加速度","曲率中心"]},{"title":"向心力随速度变化","type":"关系建立","judge":"质量与半径不变时，向心力大小由速度如何决定","why":"向心力由牛顿第二定律给出，与速度平方成正比，速度越大所需向心力越大","do":"写出向心力表达式，固定 m、R，比较不同速度对应的向心力大小","expr":"F_n=m\\dfrac{v^2}{R}","cues":["速度越大向心力越大","与速度平方成正比","半径不变"],"concepts":["向心力","牛顿第二定律"]},{"title":"最高点受力与向心力方程","type":"模型选择","judge":"把骑手和车视为整体，在最高点受哪几个力、合力指向哪","why":"整体只受重力与支持力两个竖直方向的力，合力必须指向圆心提供向心力，故取竖直向下为正列方程","do":"对整体受力分析，列重力与支持力的合力等于向心力的方程","expr":"mg-N=m\\dfrac{v^2}{R}","cues":["取整体","只受重力和支持力","合力指向圆心"],"concepts":["整体法","向心力","受力分析"]},{"title":"支持力与重力的大小比较","type":"结论整理","judge":"由方程判断支持力 N 与重力 mg 谁大谁小","why":"方程中 mg 减去 N 等于正的向心力项，说明 N 必小于 mg，即处于失重状态","do":"由 mg-N=mv²/R 移项得 N=mg-mv²/R，与 mg 比较","expr":"N=mg-m\\dfrac{v^2}{R}<mg","cues":["支持力小于重力","处于失重","合力向下"],"concepts":["失重","支持力","向心力"]}],"146":[{"title":"识别理想变压器模型","type":"模型选择","judge":"是否可忽略变压器损耗，用理想变压器规律处理","why":"题设明确说明视为理想变压器，只有这样才能用电压比等于匝数比、输入功率等于输出功率","do":"确认无漏磁、无铜损铁损，直接套用理想变压器三条基本关系","expr":"","cues":["理想变压器","无能量损失","直接用匝数比"],"concepts":["理想变压器","能量守恒"]},{"title":"有效值对应关系","type":"前提判断","judge":"电压比、功率计算中该用有效值还是最大值","why":"变压器电压比和功率公式中的电压电流均指有效值，题给220 V和15400 V本身就是有效值","do":"直接用220 V与15400 V作比求匝数比，不再乘根号二","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2}","cues":["题给就是有效值","不用再换算","直接作比"],"concepts":["有效值","匝数比"]},{"title":"功率相等求原线圈电流","type":"关系建立","judge":"求原线圈电流时用功率守恒还是用匝数比反推电流","why":"理想变压器输入功率等于输出功率，先由副线圈电压电流得输出功率，再除以原线圈电压得原线圈电流","do":"先算P=U2I2，再由I1=P/U1求原线圈电流","expr":"U_1I_1=U_2I_2","cues":["输入等于输出","先算功率","再除原电压"],"concepts":["理想变压器功率关系","电功率"]},{"title":"最大值与有效值换算","type":"数学处理","judge":"判断原线圈电压最大值时是否需乘根号二","why":"家用正弦交流电的有效值与最大值满足峰值等于有效值的根号二倍，题干给的是有效值","do":"对220 V乘根号二得峰值，与选项中给出的数值比较","expr":"U_m=\\sqrt{2}U","cues":["正弦交流电","乘根号二","峰值比有效值大"],"concepts":["交流电最大值","有效值"]}],"147":[{"title":"入射角与界面角换算","type":"几何关系","judge":"入射角应取光线与MK面法线的夹角，而不是与MK面的夹角","why":"入射角定义是入射光线与法线的夹角，题给45°是与界面的夹角，二者互余","do":"在P点作MK面的法线，用90°减去光线与MK面的45°得到入射角","expr":"i=90^\\circ-45^\\circ=45^\\circ","cues":["与界面成角","要转成法线角","互余"],"concepts":["入射角","法线"]},{"title":"由出射方向反推折射角","type":"关系建立","judge":"棱镜内折射光线垂直射到MN面，说明折射光线与MN面法线平行，需据此确定折射光线相对MK面的方向","why":"光线垂直入射到镜面MN，其方向沿MN面的法线，而MN与MK的夹角决定了折射光线与MK面法线的夹角","do":"由MN⊥折射光线及MK与MN的几何夹角，算出折射光线与MK面法线的夹角即折射角","expr":"r=90^\\circ-\\angle K","cues":["垂直射到镜面","折射光线沿法线","看三角形内角"],"concepts":["折射角","几何关系"]},{"title":"折射率与临界角关联","type":"前提判断","judge":"判断从NK面射出时是否发生全反射，须先由折射定律求出棱镜折射率，再与临界角条件比较","why":"光从光密介质射向空气，只有入射角小于临界角才能射出，临界角由折射率决定","do":"用折射定律算出n，再由全反射条件求临界角，与NK面上的入射角比较","expr":"n=\\frac{\\sin i}{\\sin r},\\quad \\sin C=\\frac{1}{n}","cues":["先求折射率","再看临界角","光密到光疏"],"concepts":["折射定律","全反射","临界角"]}],"148":[{"title":"半径与速率成正比","type":"关系建立","judge":"要判断轨道半径由什么决定、与速率成什么关系","why":"洛伦兹力提供向心力 qvB=mv²/r，比荷相同、B 相同，故 r 只由 v 决定且 r∝v","do":"写出半径公式，把 r 与 v 的线性关系作为后续几何比较的依据","expr":"r=\\frac{mv}{qB}\\propto v","cues":["半径跟速度成正比","比荷相同","先写半径公式"],"concepts":["洛伦兹力","圆周运动半径","比荷"]},{"title":"判断偏转方向定圆心","type":"前提判断","judge":"要判断两种磁场方向下正粒子的洛伦兹力朝上还是朝下，从而确定圆心在 K 点的哪一侧","why":"正电荷受洛伦兹力方向由左手定则决定，磁场反向、速度反向都会改变力的方向，圆心位置随之改变","do":"对向外磁场向右发射、向里磁场向左发射两种情况分别用左手定则定受力方向，画出圆心在 K 正下方","expr":"","cues":["左手定则","圆心在正下方","受力朝下"],"concepts":["左手定则","洛伦兹力方向","圆心位置"]},{"title":"大半径对应远交点","type":"几何关系","judge":"要判断同一发射方式下速率大的粒子打在哪个交点、速率小的打在哪个交点","why":"两圆都以 K 正下方为圆心且过 K 点，半径越大与竖直挡板线的交点离 K 越远，故大 r 对应远点","do":"以 K 为顶点作两个同心圆弧，比较它们与挡板所在直线的交点位置，把 v₁、v₂ 与 M、H、N 对应起来","expr":"","cues":["大圆打远点","两圆三交点","小半径打H"],"concepts":["圆弧轨迹","几何交点"]},{"title":"用弦长差建立方程","type":"关系建立","judge":"要判断已知的 MH、HN 长度分别对应哪两个半径之差或之和","why":"同一直线上交点间距等于两圆与该直线交点坐标之差，而交点坐标由半径的几何投影给出","do":"把 MH、HN 用 r₁、r₂ 及 K 到挡板的水平距离表示，联立两式消去公共距离","expr":"MH=r_2-r_1,\\quad HN=r_2+r_1\\ (\\text{按几何投影确定})","cues":["弦长差就是半径差","两式联立消距离","先表示再消元"],"concepts":["几何投影","弦长"]},{"title":"比值与长度比挂钩","type":"数学处理","judge":"要判断待求的速率比等于哪个半径比，并化为已知长度比","why":"r∝v，故 v₁/v₂=r₁/r₂，而 r₁、r₂ 可由 MH、HN 的组合表示","do":"由联立结果解出 r₁/r₂，再换成 MH、HN 的表达式与题给比值比较","expr":"\\frac{v_1}{v_2}=\\frac{r_1}{r_2}=f(MH,HN)","cues":["速率比就是半径比","代长度比","化简成题给形式"],"concepts":["半径比","速率比"]}],"149":[{"title":"识别类平抛运动模型","type":"模型选择","judge":"判断粒子在匀强电场中做何种运动，能否分解为两个方向的独立运动","why":"初速度沿x轴、电场力沿y轴正方向，初速度与恒力垂直，符合类平抛条件","do":"把运动分解为x方向匀速直线运动和y方向初速为零的匀加速直线运动","expr":"x=v_0t,\\quad y=\\tfrac12 at^2,\\quad a=qE/m=kE","cues":["类平抛","分解两方向","x方向匀速"],"concepts":["类平抛运动","运动的分解","牛顿第二定律"]},{"title":"用动能定理建立速率与y的关系","type":"关系建立","judge":"判断等速率曲线由什么量决定，应把末速率写成初速率与y坐标的关系","why":"电场力做功只与y方向位移有关，动能定理把末速率与y直接联系，是曲线方程的来源","do":"对粒子从O到某点用动能定理，消去初速率得到v'与y的对应关系","expr":"qEy=\\tfrac12 mv'^2-\\tfrac12 mv_0^2\\ \\Rightarrow\\ v'^2=v_0^2+2kEy","cues":["用动能定理","速率只跟y有关","消去初速度"],"concepts":["动能定理","电场力做功","比荷"]},{"title":"由曲线过y轴点定出场强","type":"前提判断","judge":"判断曲线a与y轴交点处粒子的初速度取值，从而反解出场强E","why":"曲线与y轴相交意味着x=0，即初速度为零的粒子轨迹上的点，该点速率完全由电场加速决定","do":"在交点处取v_0=0，把该点速率代入速率关系解出E","expr":"v^2=2kEy_0\\ \\Rightarrow\\ E=\\frac{v^2}{2ky_0}","cues":["交y轴说明初速为零","先定场强","用交点定E"],"concepts":["电场强度","动能定理","边界条件"]},{"title":"联立曲线与直线求交点坐标","type":"关系建立","judge":"判断M、N是曲线方程与直线方程的交点，需联立两方程求坐标","why":"M在曲线a上又在给定直线上，必须同时满足两个方程才能定位其位置","do":"写出曲线a的方程与直线方程联立，解出M的坐标，同理对曲线b求N","expr":"v'^2=v_0^2+2kEy,\\quad \\text{直线方程联立}","cues":["联立两方程","交点同时满足","先定位再算电势差"],"concepts":["曲线方程","交点坐标","联立方程"]},{"title":"沿场强方向求电势差","type":"关系建立","judge":"判断M、N两点电势差只由两点沿y方向的坐标差决定","why":"匀强电场沿y方向，电势差U=Ed中d是沿场强方向的投影距离，与x坐标无关","do":"取M、N的y坐标之差，乘以场强得电势差","expr":"U_{MN}=E\\,(y_M-y_N)","cues":["只看y方向距离","x坐标不影响","U等于E乘d"],"concepts":["匀强电场电势差","沿场强方向距离"]},{"title":"用极值条件求曲线最右端","type":"临界条件","judge":"判断曲线a最右端对应x取最大值的条件，需对x关于初速率的表达式求极值","why":"同一曲线上不同初速率粒子到达不同x，最右端是x随初速率变化的极大值点","do":"由x=v_0t与y约束消去t，把x写成v_0的函数，求导或配方取最大值","expr":"x=v_0\\sqrt{\\frac{2y}{kE}}\\ \\Rightarrow\\ x_{\\max}","cues":["最右端是极大值","x随初速变化","求导或配方"],"concepts":["极值条件","类平抛位移关系"]}],"150":[{"title":"按精度选测量仪器","type":"实验操作","judge":"测量活塞杆伸出长度该选毫米刻度尺还是螺旋测微器","why":"仪器选择由待测长度所需精度决定，题目明确要求最小分度值为1 mm，螺旋测微器精度远高于需求且量程小，不适合测几十毫米的伸出长度","do":"比较两种量具的最小分度值与题目要求的1 mm，选出分度值恰好匹配且量程够用的那一种","expr":"","cues":["看分度值","量程够不够","精度别浪费"],"concepts":["测量精度","仪器选择"]},{"title":"等效劲度系数的含义","type":"模型选择","judge":"把气弹簧等效为弹簧时，劲度系数对应F-x图的什么几何量","why":"已消除大气压、摩擦和质量影响后，F就是气体对活塞的回复力，与弹簧弹力地位相同，故等效劲度系数等于F随x变化的斜率","do":"明确k等于F-x图线的斜率，而不是某点的F值或图线面积","expr":"k=\\left|\\dfrac{\\Delta F}{\\Delta x}\\right|","cues":["斜率就是劲度系数","不是看某点高度","等效成弹簧"],"concepts":["胡克定律","等效替代"]},{"title":"在直线上取点求斜率","type":"图像读取","judge":"从F-x图哪一段取点、取哪两个点算斜率","why":"图线为直线时斜率处处相同，但必须取图线上相距较远、读数方便的两点以减小相对误差，不能取曲线段或凭单点估算","do":"在直线段上选两个坐标易读的点，读出对应的F与x，作差后相除","expr":"k=\\dfrac{F_2-F_1}{x_2-x_1}","cues":["取直线上两点","两点隔远些","读格点"],"concepts":["图像斜率","有效数字"]},{"title":"面积对应气体做功","type":"关系建立","judge":"F-x图线与x轴围成的面积代表什么物理量","why":"功的定义为力对位移的累积，F-x图线下面积即∫F dx，正是气体对外做的功","do":"确认所求量为x从40.0 mm到70.0 mm区间图线下的面积，而非某点力值乘总长度","expr":"W=\\int F\\,\\mathrm{d}x","cues":["面积就是功","力乘位移的积累","看区间面积"],"concepts":["功的定义","F-x图像面积"]},{"title":"线性段用平均力求功","type":"近似条件","judge":"该区间内F随x近似线性变化，能否用平均力代替变力求功","why":"图线在该段近似为直线，平均力等于首末力值的算术平均，变力做功可等效为恒力做功，避免逐点积分","do":"取区间两端对应的F值求平均，再乘以位移Δx，注意把毫米换算成米","expr":"W=\\dfrac{F_1+F_2}{2}\\,\\Delta x","cues":["近似直线","取首末平均","毫米换米"],"concepts":["平均力","变力做功","线性近似"]}],"151":[{"title":"匀速时水平方向平衡","type":"前提判断","judge":"刨身匀速直线运动时，能否由水平方向合力为零直接得出摩擦力等于推力的水平分量","why":"匀速直线运动是平衡状态，水平方向只有推力的水平分量和滑动摩擦力两个力","do":"把推力沿水平、竖直分解，令水平分力与滑动摩擦力大小相等","expr":"f=F\\cos\\theta","cues":["匀速就平衡","水平分力等于摩擦力","只看水平方向"],"concepts":["平衡条件","力的分解"]},{"title":"竖直方向支持力含推力分量","type":"关系建立","judge":"求支持力时，是否要把斜向下推力的竖直分量计入竖直方向平衡","why":"推力斜向下，其竖直分量与重力同向压紧接触面，支持力不等于重力","do":"对竖直方向列平衡方程，把推力的竖直分量与重力相加后等于支持力","expr":"N=mg+F\\sin\\theta","cues":["支持力不等于重力","推力往下压","竖直方向也要平衡"],"concepts":["支持力","正交分解","平衡条件"]},{"title":"摩擦力与支持力联立求质量","type":"关系建立","judge":"能否用滑动摩擦力公式把第（1）问的摩擦力与含未知质量的支持力联系起来","why":"滑动摩擦力由动摩擦因数和支持力决定，而支持力又含质量，构成关于质量的方程","do":"将第（1）问的摩擦力与第（2）问的支持力同时代入滑动摩擦力公式，解出质量","expr":"F\\cos\\theta=\\mu(mg+F\\sin\\theta)","cues":["用滑动摩擦力公式","两个式子联立","先表示支持力"],"concepts":["滑动摩擦力","动摩擦因数","联立方程"]},{"title":"冲量用动量定理求","type":"模型选择","judge":"求合力冲量时，是直接求各力冲量的矢量和，还是用动量定理转化为动量变化","why":"合力冲量等于动量变化量，匀加速直线运动末速度可由运动学公式得到，避免逐个求力再合成","do":"由初速度为零和运动学公式求末速度，再用动量定理求合力冲量","expr":"I=\\Delta p=Mv,\\quad v=\\sqrt{2aL}","cues":["用动量定理","冲量等于动量变化","先求末速度"],"concepts":["动量定理","冲量","匀加速直线运动"]},{"title":"初动量与方向判断","type":"结论整理","judge":"初动量是否为零、冲量方向是否与加速度方向一致","why":"由静止开始，初动量为零；合力方向沿运动方向，冲量方向也沿运动方向","do":"确认初速度为零，取运动方向为正，写出冲量大小表达式","expr":"I=M\\sqrt{2aL}","cues":["从静止开始","初动量为零","方向沿运动方向"],"concepts":["动量","冲量的矢量性"]}],"152":[{"title":"从图像读出外力表达式","type":"图像读取","judge":"图乙中 F 随动能 Ek 变化的图线是分段直线，需判断各段的斜率、截距及转折点对应的动能值","why":"外力 F 是后续所有动力学方程和稳定条件的输入，题目只给图像不给解析式，必须先把图线翻译成 F(Ek) 的分段函数","do":"读图乙，取横轴为动能、纵轴为外力，分别写出低动能段与高动能段的直线方程，并记下两段交点（转折点）的坐标","expr":"F=k_1 E_k + b_1\\ (E_k\\le E_0),\\quad F=k_2 E_k + b_2\\ (E_k>E_0)","cues":["先读图","分段直线","看截距","找转折点"],"concepts":["图像斜率","分段函数","动能"]},{"title":"安培力写成速度的函数","type":"关系建立","judge":"需判断安培力随速度如何变化，即把 F安 用 v（或 Ek）表示，而不是当成常量","why":"稳定条件是外力与安培力平衡，而安培力由感应电动势、欧姆定律、安培力公式链式依赖于 v，不建立这个函数关系就无法列稳定方程","do":"由 E=BLv、I=E/(R+r)、F安=BIL 依次代入，消去 I 和 E，得到 F安 关于 v 的表达式，再借 Ek=mv²/2 换成 Ek 的函数","expr":"F_{安}=\\frac{B^2L^2v}{R},\\qquad F_{安}\\propto\\sqrt{E_k}","cues":["先写感应电动势","安培力随速度变","换成动能"],"concepts":["法拉第电磁感应定律","安培力","闭合电路欧姆定律"]},{"title":"稳定条件联立求速度","type":"关系建立","judge":"判断“稳定速度”对应外力与安培力大小相等，从而把图像给出的 F(Ek) 与 F安(Ek) 联立成关于速度的方程","why":"稳定时加速度为零，合力为零，这是稳定速度的定义；只有把两个都表成 Ek 的函数才能解出稳定速度","do":"令 F(Ek)=F安(Ek)，对图像各段分别列方程，解出候选稳定速度，再逐一检验是否落在该段对应的动能区间内","expr":"F(E_k)=\\frac{B^2L^2}{R}\\sqrt{\\frac{2E_k}{m}}","cues":["稳定时合力为零","外力等于安培力","解完要检验区间"],"concepts":["平衡条件","稳定速度","分段讨论"]},{"title":"用初态比较筛除增根","type":"临界条件","judge":"判断解出的多个稳定速度中，哪些是初态能真正到达的：比较初速度处外力与安培力的大小，确定棒是加速还是减速","why":"稳定方程只是必要条件，若初态安培力大于外力则棒减速，只能趋向较小的稳定速度，较大的根是数学增根","do":"把初速度代入 F 与 F安 比较大小，判断加速度方向，据此保留与运动趋势一致的稳定速度","expr":"F(v_0)\\gtrless F_{安}(v_0)\\ \\Rightarrow\\ a\\gtrless 0","cues":["先看初态","比较外力和安培力","加速还是减速","舍去大根"],"concepts":["牛顿第二定律","运动趋势","增根检验"]},{"title":"合外力做功按初末动能算","type":"模型选择","judge":"判断求合外力做功不必对变力沿路径积分，直接用动能定理取末动能减初动能","why":"外力随动能变化、安培力随速度变化，都是变力，直接积分困难；但合外力做功恒等于动能变化，这是动能定理给出的捷径","do":"对每个初速度区间，确定末态稳定速度，写出 W合=Ek末−Ek初，并按初速度大小分段给出结果","expr":"W_{合}=\\frac12mv_s^2-\\frac12mv_0^2","cues":["用动能定理","不用积分","末动能减初动能","分区间写"],"concepts":["动能定理","合外力做功","变力做功"]},{"title":"两稳定速度的临界条件","type":"临界条件","judge":"判断“存在两个稳定速度”要求稳定方程有两个正根且都落在图像对应段的定义域内，据此定出电阻的临界值","why":"稳定方程是含 v 的二次方程，两根为正只是代数条件，还必须满足分段函数的适用区间，边界恰好取等时两根才同时成立","do":"写出含 R 的稳定方程，用判别式和韦达定理判断两根为正，再令较大根恰等于分段转折点对应的速度，解出临界 R 并回代求另一根","expr":"\\Delta>0,\\ v_1+v_2>0,\\ v_1v_2>0,\\ v_{\\max}=v_{\\text{转折}}","cues":["两根都为正","根要落在区间内","取端点恰好","回代求另一根"],"concepts":["一元二次方程根的分布","临界条件","分段定义域"]}],"153":[{"title":"识别瓦时的构成","type":"前提判断","judge":"W·h 是由功率单位 W 与时间单位 h 相乘得到的复合单位，还是某个基本量的单独单位","why":"题干给出的单位由两个符号并列相乘构成，必须先看清它是功率与时间的乘积，而不是功率本身或时间本身","do":"把 W·h 拆成 W 和 h 两个因子，确认中间是乘号关系","expr":"","cues":["瓦时是功率乘时间","W是瓦h是小时","两个单位相乘"],"concepts":["功率","时间","复合单位"]},{"title":"用功率定义式换算","type":"关系建立","judge":"功率乘时间对应的是哪个物理量","why":"功率的定义式 P=W/t 变形后 W=Pt，说明功率与时间的乘积就是功（能量）","do":"写出 P=W/t 并变形为 W=Pt，把 W·h 对应到功的单位","expr":"P=\\frac{W}{t}\\Rightarrow W=Pt","cues":["功率乘时间等于功","用功率定义式变形","瓦时是能量单位"],"concepts":["电功","功率定义式","能量"]},{"title":"排除电流与电荷量干扰","type":"结论整理","judge":"W·h 是否可能对应电流、电荷量或电功率本身","why":"电荷量单位由 q=It 给出为 A·s（即 C），电流单位是 A，功率单位是 W，都与 W·h 的量纲不符","do":"把 W·h 与 A、C、W 的量纲逐一比较，确认只有功（能量）与之相符","expr":"q=It,\\ \\mathrm{C}=\\mathrm{A}\\cdot\\mathrm{s}","cues":["安时才是电荷量","瓦是功率不是能量","单位对不上"],"concepts":["电荷量","电流","量纲比较"]}],"154":[{"title":"明确质点判据","type":"前提判断","judge":"判断物体能否被看作质点，依据的是所研究的问题中物体的大小和形状是否影响结果，而不是物体本身的大小","why":"质点是一种理想化模型，只有当物体的形状和大小对所研究的问题没有影响或影响可以忽略时，才能把物体看作质点","do":"先确定每个选项所研究的具体问题，再看该问题中是否需要关注机器人的姿态、动作或各部分差异","expr":"","cues":["看研究什么问题","大小形状能否忽略","不是看物体大小"],"concepts":["质点","理想化模型"]},{"title":"区分位置与姿态动作","type":"模型选择","judge":"判断所研究的问题是“确定机器人整体在空间中的位置”，还是“关注机器人自身的姿态、动作或部件运动”","why":"定位整体位置时，机器人各点的运动可视为相同，形状无关；而监测转弯姿态、机械臂动作时，各点运动不同，形状和大小不可忽略","do":"把各选项归为“定位位置”或“观察姿态动作”两类，只有前者满足质点条件","expr":"","cues":["定位位置可以","看姿态不行","机械臂动作不能忽略"],"concepts":["质点","参考系","运动状态"]}],"155":[{"title":"双臂合力与重力关系","type":"前提判断","judge":"双臂对杠铃的两个作用力的合力，是否必须与杠铃重力等大反向","why":"杠铃稳定时处于平衡状态，双臂作用力的合力与重力是一对平衡力，其大小只由重力决定，与两臂夹角无关","do":"对稳定状态的杠铃受力分析，把两臂作用力合成一个合力，与重力比较","expr":"F_{合}=G=mg","cues":["稳定就是平衡","合力等于重力","跟夹角无关"],"concepts":["平衡条件","力的合成"]},{"title":"单臂力大于半重力","type":"关系建立","judge":"手臂与竖直方向有夹角时，单只手臂对杠铃的作用力与杠铃重力一半的大小关系","why":"两臂对称支撑时，两分力的竖直分量之和等于重力，夹角使每臂需提供大于一半重力的力","do":"设手臂与竖直方向夹角为 θ，沿竖直方向列平衡方程，比较 F 与 G/2","expr":"2F\\cos\\theta=G,\\ \\cos\\theta<1\\Rightarrow F>\\frac{G}{2}","cues":["两臂有夹角","竖直分量加起来","比一半大"],"concepts":["力的分解","平衡条件"]},{"title":"压力与支持力是相互作用","type":"模型选择","judge":"杠铃对手臂的压力与手臂对杠铃的支持力属于哪一对力","why":"两力分别作用在手臂和杠铃两个不同物体上，大小相等方向相反，符合作用力与反作用力的特征，不是平衡力","do":"明确两力的施力物体和受力物体，判断是否作用在同一物体上","expr":"","cues":["看施力物体","作用在两个物体上","相互作用力"],"concepts":["牛顿第三定律","作用力与反作用力"]},{"title":"加速上举判超重","type":"临界条件","judge":"加速举起杠铃时，人和杠铃系统的加速度方向及对地面的压力与总重力的大小关系","why":"加速度向上时系统处于超重状态，地面对人的支持力大于系统总重力","do":"取人和杠铃为整体，由加速度方向向上列牛顿第二定律方程，比较支持力与总重力","expr":"N-(M+m)g=(M+m)a>0\\Rightarrow N>(M+m)g","cues":["取整体","加速度向上","超重"],"concepts":["超重与失重","牛顿第二定律","整体法"]}],"156":[{"title":"由电场线判电势高低","type":"前提判断","judge":"电场线的指向与电势升降的对应关系，以及图中电场线由哪种电荷发出、指向哪种电荷","why":"电场线总是从高等势面指向低等势面，所以沿电场线方向电势降低；图中电场线由正电荷指向负电荷，据此才能比较各点所在等势面的电势","do":"沿图中电场线的箭头方向判断电势降低的方向，比较 a、b 两点所在等势面的电势高低","expr":"","cues":["顺着电场线电势降低","电场线从正电荷出发","看箭头方向"],"concepts":["电场线","电势","等势面"]},{"title":"场强看疏密与方向","type":"图像读取","judge":"比较两点场强大小时看电场线的疏密，比较场强是否相同时还要看切线方向是否一致","why":"电场强度是矢量，大小由电场线疏密反映，方向沿电场线切线；只有大小和方向都相同才能说场强相同","do":"观察 a、c 两点处电场线的疏密和切线方向，判断场强大小与方向是否都相同","expr":"","cues":["看疏密比大小","方向看切线","矢量要方向相同"],"concepts":["电场强度","电场线疏密","矢量"]},{"title":"非匀强场中比较电势差","type":"关系建立","judge":"d、e、f 之间场强是否均匀，能否直接用 U=Ed 比较两段电势差","why":"U=Ed 只适用于匀强电场；图中 d→e→f 电场线越来越疏、场强逐渐减小，需用平均场强或积分思想比较两段电势差","do":"比较 de 段与 ef 段的平均场强，由 U=Ē·d 判断两段电势差的大小关系，再判断 fd 间电势差与 2 倍 ed 间电势差的关系","expr":"U_{ed}=\\bar{E}_{de}\\,d,\\quad U_{fe}=\\bar{E}_{ef}\\,d,\\quad \\bar{E}_{de}>\\bar{E}_{ef}","cues":["场强在变小","不能直接用U=Ed","用平均场强比"],"concepts":["电势差","非匀强电场","平均电场强度"]},{"title":"等势面上电势差相同","type":"关系建立","judge":"a 点与 f 点是否在同一等势面上，从而 a、b 与 f、b 之间的电势差是否相等","why":"同一等势面上各点电势相等，电势差只由始末位置的电势决定，与路径无关；再结合 W=qU 判断电场力做功","do":"确认 a、f 位于同一条等势线，写出 U_ab=U_fb，再由 W=qU 比较电子从 a 到 b 与从 f 到 b 的电场力做功","expr":"U_{ab}=U_{fb},\\quad W=qU","cues":["电势差只看始末","做功只与电势差有关"],"concepts":["等势面","电势差","电场力做功"]}],"157":[{"title":"判断是否已达稳定速度","type":"前提判断","judge":"颗粒从静止开始下落，20 m 的行程中是否大部分时间已处于匀速（收尾）状态，从而可用稳定速度代替全程平均速度","why":"阻力与速率成正比，速度从零增大到收尾速度需要一段加速过程；只有加速段极短、行程绝大部分在匀速段完成时，才能用收尾速度算时间，否则会明显偏小","do":"比较加速到收尾速度所需时间与总下落时间，或估算加速段位移占总高度 20 m 的比例，判断加速段可否忽略","expr":"","cues":["先看加速段","能不能忽略起步","速度很快就稳定"],"concepts":["收尾速度","加速度减小的加速运动"]},{"title":"由合力为零求收尾速度","type":"临界条件","judge":"稳定竖直降落时加速度为零，重力与阻力大小相等，据此求收尾速度","why":"速度增大使阻力增大、加速度减小，当加速度减到零时速度不再变化，即达到最大稳定速度，此时合力为零","do":"令重力等于阻力，代入质量和阻力系数解出收尾速度","expr":"mg=kv_m","cues":["合力为零","重力等于阻力","加速度为零"],"concepts":["平衡条件","阻力与速率成正比"]},{"title":"用匀速段求下落时间","type":"关系建立","judge":"把全程近似为以收尾速度匀速下落，用高度除以收尾速度求时间","why":"加速段极短可忽略，颗粒几乎全程以收尾速度匀速下落，故时间由高度与收尾速度之比给出","do":"用高度 20 m 除以收尾速度，再把秒换算成小时与选项比对","expr":"t=\\frac{h}{v_m}","cues":["匀速下落","高度除以速度","换算成小时"],"concepts":["匀速直线运动","单位换算"]}],"158":[{"title":"彗星轨道非圆","type":"模型选择","judge":"彗星绕太阳的轨道能否当作圆轨道处理","why":"图中彗星轨道为椭圆，太阳位于一个焦点，彗星到太阳距离和速率都随位置变化，不能用匀速圆周运动的公式直接套","do":"对照图中椭圆轨道与地球圆轨道，确认彗星做椭圆运动、地球做近似圆周运动","expr":"","cues":["椭圆轨道","不是圆周","太阳在焦点"],"concepts":["椭圆轨道","开普勒第一定律"]},{"title":"面积定律定时间","type":"关系建立","judge":"扫过面积大小能否直接比较两段过程所用时间","why":"开普勒第二定律指出对同一行星，太阳与行星连线在相等时间内扫过相等面积，故面积与时间成正比","do":"由 S1>S2 推出 a 到 b 的时间大于 c 到 d 的时间","expr":"\\frac{S_1}{t_1}=\\frac{S_2}{t_2}","cues":["面积定时间","等时间等面积","面积大时间长"],"concepts":["开普勒第二定律","面积速度"]},{"title":"近日点速度比较","type":"关系建立","judge":"彗星在近日点的速度与地球公转速度谁大","why":"近日点处彗星到太阳距离约为地球轨道半径的 0.6 倍，由 GMm/r²=mv²/r 得 v=√(GM/r)，r 越小 v 越大","do":"比较近日点距离 r1 与地球轨道半径 r2，由 v∝1/√r 判断速度大小","expr":"v=\\sqrt{\\frac{GM}{r}}","cues":["距离小速度快","比半径","用圆轨道公式估"],"concepts":["万有引力提供向心力","线速度"]},{"title":"远离太阳速度减小","type":"前提判断","judge":"从 b 到 c 彗星远离太阳时速度如何变化","why":"引力指向太阳，与速度方向夹角为钝角，引力做负功，动能减小","do":"判断 b 到 c 过程中引力与速度夹角，由做功正负判断速率增减","expr":"W_{\\text{引}}<0\\Rightarrow E_k\\downarrow","cues":["远离变慢","引力做负功","夹角是钝角"],"concepts":["功与动能变化","引力做功"]},{"title":"加速度比看距离","type":"关系建立","judge":"彗星近日点加速度与地球加速度之比由什么决定","why":"由 GMm/r²=ma 得 a=GM/r²，加速度只与中心天体质量和距离有关，与速度大小无关","do":"写出 a1/a2=(r2/r1)²，代入 r1=0.6r2 得比值","expr":"\\frac{a_1}{a_2}=\\left(\\frac{r_2}{r_1}\\right)^2","cues":["加速度看距离","与速度无关","平方反比"],"concepts":["牛顿第二定律","万有引力定律"]}],"159":[{"title":"变压器电压比关系","type":"关系建立","judge":"理想变压器原副线圈电压之比是否等于匝数之比，还是等于匝数反比","why":"理想变压器无漏磁、无损耗时，每匝磁通量变化率相同，故电压比等于匝数比","do":"写出原副线圈电压与匝数的比例式，与选项给出的比例式对照","expr":"$\\frac{U_1}{U_2}=\\frac{n_1}{n_2}$","cues":["电压比等于匝数比","别取反了"],"concepts":["理想变压器","匝数比","互感"]},{"title":"转动中电动势的变化","type":"模型选择","judge":"线框从图示位置转到与磁感线垂直的过程中，是靠近还是远离中性面，电动势应增大还是减小","why":"线圈平面与磁感线垂直时磁通量最大、磁通量变化率为零，电动势为零；偏离中性面越远电动势越大","do":"判断图示位置与中性面的夹角变化趋势，由此判断电动势的变化趋势","expr":"$e=E_m\\sin\\theta$","cues":["看是否靠近中性面","中性面","磁通量变化率","交变电流"],"concepts":["中性面","磁通量变化率","交变电流"]},{"title":"由电场方向定极板电性","type":"前提判断","judge":"电容器内电场竖直向上时，是上极板带正电还是下极板带正电","why":"电场线由正电荷指向负电荷，场强方向由正极板指向负极板","do":"由场强方向反推上下极板的电荷正负","expr":"","cues":["电场线从正极板出发","下板带正电"],"concepts":["匀强电场","电场线方向","极板电性"]},{"title":"由磁场方向定电流方向","type":"几何关系","judge":"已知线圈中磁场方向，用安培定则判断线圈中电流的绕行方向","why":"通电螺线管内部磁场方向与电流绕向满足右手螺旋关系","do":"用右手握住线圈，让四指沿电流方向，判断拇指（内部磁场）指向是否与题图一致","expr":"","cues":["右手螺旋定则","四指顺着电流"],"concepts":["安培定则","螺线管磁场","电流方向"]},{"title":"充放电与能量增减","type":"结论整理","judge":"电流流向正极板时电容器是在充电还是放电，电场能随之增大还是减小","why":"正电荷流向正极板使极板电荷量增加，即充电，电场能随电荷量增大而增大","do":"比较电流方向与极板电性，判断电荷量增减，再判断电场能变化","expr":"$E_C=\\frac{Q^2}{2C}$","cues":["电荷变多电场能变大","充放电与能量增减","电容器充电","电场能","电荷量"],"concepts":["电容器充电","电场能","电荷量"]},{"title":"振荡频率与电容关系","type":"关系建立","judge":"电容 C 增大时，LC 振荡电路的固有频率是增大还是减小","why":"LC 振荡周期由电感和电容决定，频率与电容的平方根成反比","do":"写出频率与 L、C 的关系式，判断 C 增大时频率的变化方向","expr":"$f=\\frac{1}{2\\pi\\sqrt{LC}}$","cues":["电容大频率小","频率和电容反着变"],"concepts":["LC 振荡电路","固有频率","调谐"]}],"160":[{"title":"碰后瞬间速度","type":"模型选择","judge":"A、B 碰撞是弹性还是完全非弹性，碰后是否与 C 的速度混在一起算","why":"题设明确 A、B 碰后粘在一起不再分开，是完全非弹性碰撞，只对 A、B 用动量守恒，C 不参与碰撞瞬间的动量交换","do":"取向右为正，对 A、B 列碰前碰后动量守恒，求出碰后共同速度","expr":"m v_A - m v_B = 2m v_1","cues":["粘在一起","只算A和B","C不参与碰撞"],"concepts":["完全非弹性碰撞","动量守恒"]},{"title":"碰后 C 的初速度","type":"前提判断","judge":"碰后瞬间 C 相对地面的速度方向是否改变","why":"C 未参与碰撞，速度仍为碰前的 2 m/s 向左，而 AB 碰后向右运动，二者反向，摩擦力方向由此确定","do":"比较碰后 AB 共同速度方向与 C 的速度方向，确定 C 相对 AB 的滑动方向","expr":"v_C = -2\\,\\mathrm{m/s}","cues":["C速度没变","还是向左","和AB反向"],"concepts":["惯性","相对运动"]},{"title":"三者共速的终态","type":"关系建立","judge":"AB 整体与 C 最终能否达到共同速度，共速值为多少","why":"地面光滑，AB 与 C 组成的系统水平方向合外力为零，动量守恒；摩擦力使二者趋于共速","do":"对 AB 整体和 C 列动量守恒，求共速速度","expr":"2m v_1 - m v_C = 3m v","cues":["整体动量守恒","最后一起动","共速"],"concepts":["动量守恒","系统"]},{"title":"相对滑动的时间","type":"关系建立","judge":"C 相对 AB 滑动持续多久，能否直接用 C 的加速度求时间","why":"C 只受恒定滑动摩擦力，加速度为 μg，方向与 C 初速反向，由速度从 2 m/s 减到共速值可求时间","do":"对 C 用牛顿第二定律求加速度，再由速度变化求时间","expr":"t=\\frac{v_C-v}{\\mu g}","cues":["C只受摩擦力","加速度是5","速度减到零"],"concepts":["牛顿第二定律","滑动摩擦力"]},{"title":"相对位移与板长比较","type":"临界条件","judge":"C 相对 AB 滑动的距离是否超过板长，C 会不会从板上掉下","why":"摩擦生热等于摩擦力乘相对路程，求出的相对位移必须与板长 0.75 m 比较才能判断 C 是否始终在板上","do":"用能量守恒求相对位移，再与板长比较","expr":"\\mu m g x_{\\text{相对}}=\\tfrac12(2m)v_1^2+\\tfrac12 m v_C^2-\\tfrac12(3m)v^2","cues":["先算相对位移","和板长比","会不会掉下来"],"concepts":["功能关系","相对位移"]}],"161":[{"title":"亮点对应哪条光路","type":"模型选择","judge":"屏上出现亮点时，光是从溶液经隔板折射后射出，还是从空气经隔板折射后射出","why":"容器一半是溶液一半是空气，只有光路穿过溶液并斜射到隔板-空气界面且入射角小于临界角时才能射出到屏上，否则在隔板-空气界面全反射、屏上无亮点","do":"画出容器旋转到不同位置时的光路，判断亮点出现时光线依次经过溶液、隔板、空气","expr":"","cues":["光从溶液一侧射入","隔板与空气界面","先看全反射"],"concepts":["全反射","折射定律","光路分析"]},{"title":"无亮点即全反射","type":"临界条件","judge":"屏上无亮点时，隔板射向空气的入射角与临界角的大小关系","why":"光从光密介质（隔板 n）射向光疏介质（空气 1），入射角大于等于临界角时发生全反射，光无法到达屏","do":"写出隔板-空气界面的临界角条件，把临界角与隔板折射率联系起来","expr":"$\\sin C=\\frac{1}{n}$","cues":["无亮点就是全反射","临界角","隔板到空气"],"concepts":["全反射","临界角"]},{"title":"溶液-隔板界面折射","type":"关系建立","judge":"光从溶液进入隔板时，溶液中的入射角与隔板中的折射角满足什么关系","why":"溶液与隔板折射率不同，界面处必须用折射定律联系两侧角度，才能把待测折射率与临界角挂钩","do":"对溶液-隔板界面列折射定律，把隔板中的角取为临界角 C","expr":"$\\frac{\\sin\\theta}{\\sin C}=\\frac{n}{n_x}$","cues":["溶液到隔板","折射定律","两边角度对应"],"concepts":["折射定律","折射率"]},{"title":"转角与时间的关系","type":"几何关系","judge":"从亮点出现到亮点消失，容器转过的角度与光路对称位置的关系","why":"容器匀速转动，亮点出现和消失对应两条对称的临界光路，两临界方向之间的夹角是容器转角的一半关系","do":"由角速度和时间求总转角，再取一半作为临界入射角 θ","expr":"$2\\theta=\\omega\\Delta t$","cues":["转过的角度","对称的两条光线","一半是入射角"],"concepts":["圆周运动","角速度","对称性"]},{"title":"消去中间量求折射率","type":"数学处理","judge":"如何把临界角 C 从两个方程中消去，只留可测量 ω、Δt 和已知 n","why":"C 不是题目给出的量，必须联立两式消去，才能得到只含 ω、Δt 的待测折射率表达式","do":"将临界角正弦代入溶液-隔板折射方程，解出 n_x","expr":"$n_x=\\frac{1}{\\sin\\frac{\\omega\\Delta t}{2}}$","cues":["消掉临界角","联立两式","只剩时间和角速度"],"concepts":["联立方程","折射率"]}],"162":[{"title":"读截止电压定频率","type":"图像读取","judge":"由图(b)中三条曲线与横轴交点读出各自截止电压的大小顺序","why":"截止电压由光电效应方程 Uc·e = hν − W 决定，对同一阴极 W 相同，故 Uc 越大入射光频率越高","do":"找出 P、Q、R 曲线与电压轴负半轴的交点，比较三者截止电压绝对值","expr":"eU_c = h\\nu - W","cues":["看横轴交点","截止电压越大频率越高","Q的截止电压最大"],"concepts":["光电效应","截止电压","逸出功"]},{"title":"频率定波长与衍射","type":"关系建立","judge":"由频率大小关系推出波长大小，再判断单缝衍射中央亮纹宽窄","why":"c=λν 给出波长与频率反比；波长越长衍射越明显、中央亮纹越宽","do":"比较 Q、R 的频率得波长关系，再据此判断中央亮纹宽度","expr":"c=\\lambda\\nu","cues":["频率大波长短","波长长衍射明显","中央亮纹宽窄"],"concepts":["波长频率关系","单缝衍射"]},{"title":"最大初动能定德布罗意波长","type":"关系建立","judge":"由截止电压比较最大初动能，再比较光电子最小德布罗意波长","why":"最大初动能 Ekm=eUc，德布罗意波长 λ=h/p 且 p=√(2mEkm)，动能越大波长越短","do":"比较 P、Q 的截止电压得 Ekm 大小，代入 λ=h/√(2mEkm) 比较","expr":"\\lambda=\\frac{h}{\\sqrt{2mE_{km}}}","cues":["动能大波长小","截止电压定初动能"],"concepts":["最大初动能","德布罗意波长"]},{"title":"跃迁能级高低判断","type":"前提判断","judge":"向第一激发态跃迁时，光子能量越大对应跃迁的始能级越高","why":"跃迁光子能量 hν=Em−E2，终态相同则能量越大始能级越高","do":"由三束光频率大小定能量大小，判断哪束对应能级最高","expr":"h\\nu=E_m-E_2","cues":["向第一激发态跃迁","能量大能级高","终态相同比始态"],"concepts":["能级跃迁","光子能量"]},{"title":"光电流大小定电子数","type":"关系建立","judge":"同一电压下光电流相等说明单位时间到达阳极的光电子数相等","why":"光电流由单位时间到达阳极的光电子数目决定，与光电子初动能无关","do":"在图(b)中取 M 点，比较 P、Q 曲线在该电压下的电流值","expr":"I=ne","cues":["电流相等电子数相等","光强决定电子数","与初动能无关"],"concepts":["光电流","饱和电流"]}],"163":[{"title":"两侧介质波速不同","type":"前提判断","judge":"波从波源传到某点的时间是否等于该点到波源的距离除以该侧介质中的波速","why":"以 x=6 m 为界两侧是不同均匀介质，同一列波在两侧波速不同，不能用一个波速算全程","do":"用 x=4 m 处 0.1 s 开始振动求左侧波速，用 x=6 m 处 0.1 s 开始振动求右侧波速","expr":"v_1=\\frac{4}{0.1}=40\\,\\mathrm{m/s},\\quad v_2=\\frac{6}{0.1}=60\\,\\mathrm{m/s}","cues":["两侧波速不一样","先算两个波速","用传播时间求速度"],"concepts":["波速","介质","波的传播"]},{"title":"读振动图得周期","type":"图像读取","judge":"从图(b)的振动图像读出周期和波源的起振方向","why":"周期决定波长，起振方向决定各点振动方向，两者都是后续判断加强减弱的依据","do":"读图(b)一个完整循环对应的时间得周期，读 t=0 后第一个位移方向得起振方向","expr":"T=0.02\\,\\mathrm{s}","cues":["看周期","起振向上","一个循环多长"],"concepts":["周期","振动图像","起振方向"]},{"title":"相遇时间用相对速度","type":"关系建立","judge":"两列波相向传播时，相遇时间是否由两波速之和与总距离决定","why":"两列波同时从两端出发相向传播，接近速度为 v1+v2，总距离为 12 m","do":"列两波传播距离之和等于 12 m 的方程，解出相遇时刻","expr":"(v_1+v_2)t'=12","cues":["相向传播","速度相加","总距离十二米"],"concepts":["波的叠加","相对速度"]},{"title":"跨介质传播分段计时","type":"模型选择","judge":"波从一侧波源传到另一侧某点时，是否要按介质分界分段计算时间","why":"波在 x=6 m 处换介质后波速改变，全程不能只用一种波速，必须分段求时间","do":"把传播路程分成界面前、界面后两段，分别除以对应波速再相加","expr":"t=\\frac{6}{v_1}+\\frac{x-6}{v_2}","cues":["要分段算","过界变速","先左后右"],"concepts":["波速","介质分界","传播时间"]},{"title":"用相位差判加强减弱","type":"临界条件","judge":"某点是振动加强还是减弱，要看两列波到达该点时的相位差（或已振动时间差与周期的关系）","why":"两波源振动情况相同，某点加强减弱由两列波传到该点的相位差决定，相位差为 2π 整数倍加强、π 奇数倍减弱","do":"分别求两列波到达该点的时刻，作差得时间差，再与周期比较取余","expr":"\\Delta t=nT\\ (\\text{加强}),\\quad \\Delta t=\\left(n+\\tfrac12\\right)T\\ (\\text{减弱})","cues":["算时间差","看差几个周期","同相加强反相减弱"],"concepts":["相位差","波的干涉","振动加强减弱"]},{"title":"同侧区间加强点计数","type":"数学处理","judge":"在 0<x<6 m 内找加强点，是看该点到两波源（含界面处等效源）的路程差是否为波长整数倍，并数出区间内解的个数","why":"两波源振动同相，加强条件为路程差等于波长整数倍；区间端点与波长共同限制 n 的取值范围","do":"写出路程差表达式，令其等于 nλ1，解出 x 关于 n 的表达式，再由 0<x<6 确定 n 的整数个数","expr":"x-(6-x)=n\\lambda_1,\\quad \\lambda_1=v_1T=0.8\\,\\mathrm{m}","cues":["路程差整数倍","数n的个数","端点算不算"],"concepts":["路程差","干涉加强条件","波长"]}],"164":[{"title":"感生电场分布规律","type":"前提判断","judge":"判断感生电场是否只由磁通量变化率决定、其大小是否随半径变化","why":"法拉第电磁感应定律给出 ∮E·dl=−dΦ/dt，同心圆电场线使 E·2πρ 等于所围磁通变化率，故 E 与 ρ 成反比（ρ>r 时）","do":"对以 O 为圆心、半径 ρ 的圆取环路积分，写出 E 与 dΦ/dt 的关系","expr":"E·2πρ=\\left|\\frac{dΦ}{dt}\\right|","cues":["电场线是同心圆","半径越大电场越弱","只看磁通变化率"],"concepts":["感生电场","法拉第电磁感应定律","磁通量"]},{"title":"区分磁通与有效面积","type":"模型选择","judge":"判断各圆环所围的磁场有效面积是 πr² 还是各自圆面积","why":"磁场只存在于半径 r 的圆形区域内，环 I 半径 2r、环 II 半径 0.5r 且与磁场边界相切，只有落在磁场内的部分才贡献磁通","do":"分别确定环 I、环 II 所围磁场区域的有效面积，环 II 完全在磁场外则磁通恒为零","expr":"Φ_I=B·πr^2,\\quad Φ_{II}=0","cues":["磁场只在圆内","环II在磁场外","有效面积取小的那个"],"concepts":["磁通量","有效面积"]},{"title":"分段求电动势再算有效值","type":"数学处理","judge":"判断环 I 中电流随时间分段变化、需按电流的热效应求有效值","why":"B–t 图斜率在 0~t₀、2t₀~3t₀ 与 t₀~2t₀ 不同，感应电动势大小不同，交流有效值须由焦耳热等效定义","do":"按三段斜率分别求电动势与电流，再用 I²R·3t₀ 等于各段热量之和求有效值","expr":"I^2R·3t_0=I_1^2R·2t_0+I_2^2R·t_0","cues":["斜率不同电流不同","有效值看发热","分三段算"],"concepts":["交流有效值","焦耳热等效"]},{"title":"直导线电动势的对称补全","type":"模型选择","judge":"判断无限长直导线 CD 的感生电动势能否直接算，需借助对称回路","why":"直导线不闭合，单独无法用磁通变化率求电动势，需补一条对称的无限长直导线构成闭合回路，再由对称性平分总电动势","do":"在另一侧补一条对称直导线构成回路，求回路总电动势后取一半","expr":"E_{CD}=\\frac12\\left|\\frac{dΦ_{回路}}{dt}\\right|","cues":["直导线不闭合","补一条对称导线","总电动势取一半"],"concepts":["对称性","感生电动势","闭合回路"]},{"title":"环 II 无磁通故无电流","type":"临界条件","judge":"判断环 II 整体处于磁场外时环内是否有感应电流","why":"环 II 与磁场边界相切，所围区域全在磁场外，磁通量恒为零，不产生感应电动势","do":"比较环 II 位置与磁场边界，确认磁通为零，得电流为零","expr":"Φ_{II}=0\\Rightarrow I_{II}=0","cues":["相切在磁场外","磁通一直为零","没有感应电流"],"concepts":["磁通量","感应电流产生条件"]},{"title":"PQ 段电动势按角度分配","type":"几何关系","judge":"判断环 II 上 P、Q 两点间那段导线的电动势如何由同心圆电场沿弧长积分得到","why":"感生电场沿以 O 为圆心的圆周，PQ 所在圆弧对应的圆心角 φ=30°，该段电动势等于同半径整圆电动势按角度比例分配","do":"先求过 P、Q 的圆轨道整圆电动势，再乘 30°/360°","expr":"E'=\\frac{30^\\circ}{360^\\circ}E=\\frac{1}{12}E","cues":["按圆心角分","整圆电动势乘比例","PQ在同一圆弧上"],"concepts":["感生电动势","弧长积分","圆心角"]}],"165":[{"title":"计数点时间间隔","type":"前提判断","judge":"每5个连续打出的点取一个计数点，相邻计数点间的时间间隔取多少","why":"电源频率50 Hz，打点周期0.02 s，计数点间隔是打点周期的5倍","do":"由频率算打点周期，再乘5得计数点间隔T","expr":"T=5\\times\\frac{1}{f}=0.1\\,\\mathrm{s}","cues":["每5个点取一个","频率五十赫兹","间隔是零点一秒"],"concepts":["打点计时器","计数点","周期与频率"]},{"title":"瞬时速度用平均速度替代","type":"模型选择","judge":"求打下计数点3时的瞬时速度，应取哪一段位移和哪段时间","why":"匀变速直线运动中某段时间内的平均速度等于中间时刻的瞬时速度，计数点3正是2到4的中间时刻","do":"取计数点2到4的位移除以对应时间2T，而不是取3到4或2到3","expr":"v_3=\\frac{x_{24}}{2T}","cues":["用前后两点求中间时刻","取二到四段","别只用相邻一段"],"concepts":["匀变速直线运动","中间时刻瞬时速度","平均速度"]},{"title":"平衡摩擦力与质量无关","type":"前提判断","judge":"改变小车总质量后是否需要重新补偿阻力","why":"平衡摩擦力条件是重力沿板分量等于摩擦力，质量在等式两边约去，与小车质量无关","do":"写出平衡摩擦力的等式，看质量能否消去，据此判断A项","expr":"mg\\sin\\theta=\\mu mg\\cos\\theta","cues":["质量约掉了","不用重新平衡","与小车质量无关"],"concepts":["平衡摩擦力","重力分量","滑动摩擦力"]},{"title":"计时器电源类型","type":"前提判断","judge":"实验所用打点计时器应接什么电压、什么类型的电源","why":"电磁打点计时器接低压交流，电火花计时器接220 V交流，二者都不能接直流","do":"辨认装置图中计时器类型，对照其额定电压与电源性质判断B项","expr":"","cues":["看是电火花还是电磁","交流不是直流","二百二十伏"],"concepts":["打点计时器","交流电源","额定电压"]},{"title":"细线平行与操作顺序","type":"实验操作","judge":"牵引细线是否要与长木板平行，以及接通电源与释放小车的先后顺序","why":"细线不平行会使拉力产生垂直板的分力、改变正压力；先通电后放小车才能打全点迹","do":"对照装置调节滑轮高度使细线平行板面，并确认先接通电源再释放小车","expr":"","cues":["细线要平行木板","先通电后放小车","小车靠近计时器"],"concepts":["实验操作规范","纸带利用率","拉力方向"]},{"title":"遮光条宽度读数","type":"图像读取","judge":"游标卡尺的主尺读数与游标对齐格数各是多少","why":"游标卡尺读数等于主尺整毫米数加游标对齐格数乘精度，本卡尺精度为0.05 mm","do":"读主尺10 mm，游标零刻线对齐第0条，故游标读数为零","expr":"d=10\\,\\mathrm{mm}+0.05\\,\\mathrm{mm}\\times 0=10.00\\,\\mathrm{mm}","cues":["主尺读十毫米","游标对齐第零格","精度是零点零五"],"concepts":["游标卡尺","精度","读数规则"]},{"title":"光电门测速与加速度公式","type":"关系建立","judge":"遮光条通过光电门的平均速度能否当作滑块经过光电门的瞬时速度，并用哪条运动学公式求加速度","why":"遮光时间极短，平均速度近似等于瞬时速度；两光电门间为匀加速，已知初末速度和位移可求加速度","do":"先由d与遮光时间求两个瞬时速度，再代入速度位移关系式解出a","expr":"v_1=\\frac{d}{\\Delta t_1},\\ v_2=\\frac{d}{\\Delta t_2},\\ v_2^2-v_1^2=2ax","cues":["遮光时间很短","用速度位移公式","两个光电门速度"],"concepts":["光电门测速","匀变速直线运动","速度位移关系"]}],"166":[{"title":"电流方向与指针偏转对应","type":"前提判断","judge":"要判断指针左偏时感应电流是从哪个接线柱流入电流表的","why":"题干给出了电流流入方向与指针偏转方向的对应规则，这是把指针偏转反推为电流方向的唯一依据","do":"读题干规则，把图中指针左偏对应到电流从“-”接线柱流入","expr":"","cues":["左偏对应负接线柱","先定电流方向","看指针往哪偏"],"concepts":["灵敏电流计","电流方向"]},{"title":"由电流方向定线圈内磁场","type":"关系建立","judge":"要判断螺线管中感应电流的绕行方向所对应的内部磁场方向（即感应电流的磁场朝上还是朝下）","why":"安培定则把线圈中电流方向与感应电流产生的磁场方向联系起来，这是应用楞次定律的前提","do":"由电流从“-”流入确定线圈中电流绕向，用右手螺旋定则判断感应磁场方向","expr":"","cues":["右手螺旋定则","看线圈绕向","感应磁场朝哪"],"concepts":["安培定则","感应电流的磁场"]},{"title":"楞次定律判磁铁运动","type":"关系建立","judge":"要判断感应磁场与原磁场的方向关系，从而确定原磁通是增大还是减小，进而确定磁铁是插入还是拔出","why":"楞次定律指出感应电流的磁场总要阻碍引起感应电流的磁通量的变化","do":"","expr":"","cues":["增反减同","磁通量在增还是减","阻碍变化"],"concepts":["楞次定律","磁通量变化"]},{"title":"偏角大小看电动势与量程","type":"模型选择","judge":"要判断指针偏转角度由什么决定：是感应电动势（磁通量变化率）还是电流计量程","why":"偏角大小既随通过电流计的电流增大而增大，也随电流计量程减小而增大，两个因素要分开考虑","do":"把各选项归为“改变磁通量变化率”或“改变电流计量程”两类，再判断是否一定使偏角增大","expr":"","cues":["偏角看电流大小","量程越小越灵敏","变化越快电动势越大"],"concepts":["感应电动势","电流计量程","磁通量变化率"]},{"title":"相对运动等效性判断","type":"临界条件","judge":"要判断磁铁静止而线圈移动时，磁通量变化率是否一定比原来大","why":"磁铁与线圈的相对运动才决定磁通量变化，仅改变谁动不能保证变化率增大","do":"比较线圈上移与磁铁上拔两种情形下相对速度与磁通量变化率的大小关系","expr":"","cues":["相对运动才关键","谁动都一样吗","不一定变大"],"concepts":["相对运动","磁通量变化率"]},{"title":"外部闭合线圈是否影响","type":"结论整理","judge":"要判断套在外面的未接入电路的闭合线圈是否改变原线圈中的电流","why":"原电路中的感应电流只由穿过原线圈的磁通量变化决定，外部独立线圈不接入原电路，不改变原回路电流","do":"分析外部线圈与原电路有无电连接，判断原回路电流是否变化","expr":"","cues":["没接进电路","不影响原电流","各是各的回路"],"concepts":["闭合回路","电磁感应"]}],"167":[{"title":"分压接法选小阻值","type":"模型选择","judge":"滑动变阻器采用分压接法时，要判断选阻值小的 A 还是阻值大的 B 才能让 cd 间电压基本不变","why":"分压电路中，只有滑动变阻器总阻值远小于负载电阻时，滑片移动对并联部分电压的影响才小，U0 才近似恒定；热敏电阻为几百欧，B 的 100 Ω 与负载可比，调温时电压会明显漂移","do":"比较滑动变阻器最大阻值与负载（热敏电阻几百欧）的大小关系，选远小于负载的那个","expr":"","cues":["分压接法","选小阻值","电压才稳"],"concepts":["分压电路","滑动变阻器"]},{"title":"换接后电压的对应关系","type":"关系建立","judge":"S2 从 a 切到 b 后，要判断电压表两次读数分别对应哪段电压，以及 cd 间总电压是否仍为 U0","why":"滑片 P 不动则 cd 间总电压不变，接 a 时电压表测热敏电阻电压，接 b 时测电阻箱电压，两者之和恒为 U0，这是列式的前提","do":"画出两种接法下的等效电路，标出电压表所测元件与 cd 间总电压","expr":"U_a+U_b=U_0","cues":["滑片不动","总电压不变","测的是谁"],"concepts":["串联分压","等效电路"]},{"title":"串联电流相等求阻值","type":"关系建立","judge":"要判断用哪个量把两次测量联系起来——同一支路中电流相等","why":"Rt 与 R1 串联，接 b 时电压表读数 U1 与 R1 之比就是该支路电流，接 a 时同一电流流过 Rt，故 Rt=(U0−U1)/(U1/R1)","do":"先由 U1、R1 求支路电流，再用 U0 减去 U1 得 Rt 上电压，两者相除得 Rt","expr":"R_t=\\frac{U_0-U_1}{U_1/R_1}","cues":["电流相同","先求电流","总电压减掉"],"concepts":["欧姆定律","串联电路"]},{"title":"有效数字与单位处理","type":"数学处理","judge":"计算结果要判断保留几位有效数字、单位是否统一","why":"题设要求保留三位有效数字，电压用 V、电阻用 Ω，直接代入即可，但不能随意截断中间结果","do":"代入 2.50、1.40、200.0 计算后按三位有效数字取舍","expr":"R_t=\\frac{1.10\\times200.0}{1.40}\\ \\Omega","cues":["三位有效数字","别提前约","单位统一"],"concepts":["有效数字"]},{"title":"滑片不动下的替代方案","type":"结论整理","judge":"要判断在 P 不动、cd 电压未知但恒定的条件下，能否只用电压表读数和电阻箱示值求出 Rt","why":"P 不动使 cd 间电压 U 恒定但未知，需通过两次接法消去 U，或保持接 b 改变 R1 多次测量，用比例关系消去恒定电压","do":"设计先接 a 读 U、再接 b 读 U′ 与 R1 的步骤，写出含 U 的串联方程并消去 U 解出 Rt","expr":"\\frac{U}{R_1+R_t}=\\frac{U'}{R_1}\\Rightarrow R_t=\\left(\\frac{U}{U'}-1\\right)R_1","cues":["电压恒定但未知","两次读数消去","保持接b改变电阻箱"],"concepts":["等效替代","串联分压"]}],"168":[{"title":"判断压强来源","type":"模型选择","judge":"瓶内气体压强由大气压和吸管内水柱高度差共同决定，要判断用哪个液面高度差、加还是减","why":"吸管内液面高于瓶内液面 h，管内液体在瓶内气压和大气压之间平衡，故瓶内气压大于大气压","do":"对管内高出瓶内液面的水柱列静力平衡，写出瓶内气压表达式","expr":"p_1=p_0+\\rho gh","cues":["液面高差定压强","管内比瓶内高","要加不是减"],"concepts":["压强平衡","液体静压强"]},{"title":"判断状态1到2的规律","type":"关系建立","judge":"瓶塞缓慢上升过程中瓶内气体压强是否变化，从而判断该过程是等压还是等温变化","why":"h 保持不变说明水柱高度差不变，瓶内气压恒为 p_0+ρgh；瓶塞无摩擦缓慢上升，气体压强不变","do":"确认 p 不变后对状态1、2列等压过程方程，求 V_2","expr":"\\frac{V_1}{T_1}=\\frac{V_2}{T_2}","cues":["高度差不变","压强不变","用盖吕萨克"],"concepts":["等压变化","盖—吕萨克定律"]},{"title":"判断状态3的压强","type":"前提判断","judge":"吸走部分水后管内与瓶内液面等高，瓶内气体压强等于什么","why":"液面等高时水柱不产生附加压强，气体只与大气相通平衡","do":"由液面等高条件确定 p_3=p_0，再对状态2到3列等温方程求 V_3","expr":"p_3=p_0,\\quad p_2V_2=p_3V_3","cues":["液面等高","压强等于大气压","温度没变"],"concepts":["等温变化","玻意耳定律"]},{"title":"判断各段做功的求法","type":"关系建立","judge":"状态1到2和状态2到3两段气体对外做功分别怎么算，能否直接用 pΔV","why":"状态1到2压强恒为 p_1，可用 W=pΔV；状态2到3做功已由题给 1.02 J，不必再算","do":"对等压段用 p_1(V_2−V_1) 求 W_1，与题给 W_2 相加得总做功","expr":"W_1=p_1(V_2-V_1),\\quad W=W_1+W_2","cues":["等压段才能用","压强乘体积差","第二段题给"],"concepts":["功的计算","等压过程"]},{"title":"热力学第一定律符号","type":"关系建立","judge":"吸热、对外做功在 ΔU=Q−W 中各自取什么符号","why":"热力学第一定律约定吸热 Q 为正、气体对外做功 W 为正，内能改变等于吸热减对外做功","do":"把 Q=4.56 J 与总对外做功代入 ΔU=Q−W 求内能改变","expr":"\\Delta U=Q-(W_1+W_2)","cues":["吸热取正","对外做功取正","用总功"],"concepts":["热力学第一定律","内能"]},{"title":"微观量的温度判据","type":"结论整理","judge":"状态2到3温度不变时，分子平均速率和单位时间撞击单位面积的分子数如何变化","why":"平均速率只由温度决定；温度不变则速率不变，而压强减小意味着单位时间单位面积碰撞次数减少","do":"先由等温判断平均速率不变，再由压强减小判断碰撞数密度通量减小","expr":"","cues":["温度决定速率","等温就不变","压强小撞得少"],"concepts":["分子平均动能","压强微观解释"]}],"169":[{"title":"碰撞前后分段选规律","type":"模型选择","judge":"滑块1下滑段与碰撞段应分别用哪种规律处理","why":"AB段光滑无摩擦，只有重力做功，机械能守恒；碰撞瞬间时间极短、水平方向无外力，动量守恒但机械能不守恒（完全非弹性）","do":"对滑块1下滑用动能定理求碰前速度，再对1、2碰撞用动量守恒求碰后共同速度","expr":"mgh=\\frac{1}{2}mv_0^2,\\quad mv_0=2mv_C","cues":["下滑用动能定理","碰撞用动量守恒","碰后速度减半"],"concepts":["动能定理","动量守恒","完全非弹性碰撞"]},{"title":"恰过最高点的临界条件","type":"临界条件","judge":"滑块3恰好通过竖直圆轨道最高点D时，向心力由什么提供、速度满足什么条件","why":"轨道为光滑圆轨道，最高点处轨道对滑块的压力恰为零，仅重力提供向心力，这是'恰好通过'的临界含义","do":"在D点对滑块3列牛顿第二定律，取支持力为零，求出v_D","expr":"2mg=2m\\frac{v_D^2}{R}","cues":["最高点只受重力","支持力为零","恰好通过就是临界"],"concepts":["向心力","临界条件","牛顿第二定律"]},{"title":"D到C'的机械能守恒","type":"关系建立","judge":"从D点回到C'点（同一高度）速度大小如何确定，能否直接用能量守恒","why":"螺旋轨道光滑，只有重力做功，D与C'等高，重力势能不变，动能不变","do":"对滑块3从D到C'列机械能守恒，求出v_C'，再逆推到碰后速度与h","expr":"\\frac{1}{2}\\cdot2mv_C'^2=2mg\\cdot2R+\\frac{1}{2}\\cdot2mv_D^2","cues":["光滑轨道机械能守恒","等高速度大小相等","逆推回高度"],"concepts":["机械能守恒","螺旋轨道"]},{"title":"EF段摩擦力与能量损耗","type":"关系建立","judge":"滑块3从C'到F过程中，重力和摩擦力各做多少功，正负如何取","why":"EF段粗糙且倾角37°，下滑时重力做正功、摩擦力做负功，需用动能定理统一处理","do":"沿EF方向分解重力，写摩擦力μ·2mgcos37°，对C'到F列动能定理求v_F","expr":"-2mgL\\sin37^\\circ-\\mu\\cdot2mg\\cos37^\\circ L=\\frac{1}{2}\\cdot2mv_F^2-\\frac{1}{2}\\cdot2mv_C'^2","cues":["沿斜面分解重力","摩擦力做负功","用动能定理"],"concepts":["动能定理","滑动摩擦力"]},{"title":"平抛落点与反弹规则","type":"模型选择","judge":"滑块3离开F后做何种运动，落在GH段反弹后水平、竖直分速度如何变化，落点是否在H右侧","why":"离开F后只受重力，做斜抛运动；题设规定落在GH段反弹时水平分速度不变、竖直分速度减半，落在H右侧立即停止","do":"分别讨论直接落入I点（一次斜抛）与经GH反弹一次后落入I点两种情形，按水平位移与竖直时间关系列式","expr":"L_{FG}+L_{GH}+L_{HI}=v_F\\cos37^\\circ t,\\quad t_1=\\frac{2v_F\\sin37^\\circ}{g}","cues":["离开F做斜抛","反弹竖直速度减半","分直接落和反弹落"],"concepts":["斜抛运动","运动的分解","反弹规则"]},{"title":"两种落点情形分别求h","type":"结论整理","judge":"直接落入与反弹一次落入对应不同的飞行时间，需分别联立求h，并检验落点是否满足题设区间","why":"两种情形的竖直分速度与总时间关系不同，对应不同的v_F，从而对应不同的h；还需确认反弹点确在GH段内","do":"对两种情形分别由水平位移求v_F，再经EF段动能定理和碰撞、下滑关系逆推h，并核对落点位置","expr":"t_2=\\frac{2v_F'\\sin37^\\circ}{g}+\\frac{v_F'\\sin37^\\circ}{g}","cues":["两种情形分开算","逆推回高度","检验落点位置"],"concepts":["斜抛运动","动能定理","动量守恒"]}],"170":[{"title":"有效长度随位置变化","type":"几何关系","judge":"线框在磁场中的有效切割长度是整条对角线还是随中心位置 x 变化的量","why":"线框是正方形且对角线沿 Ox 轴，磁场边界竖直，只有位于边界左侧（磁场内）的那部分对角线在磁场中，有效长度等于磁场内对角线长度","do":"画出中心在 x 时的线框，找出对角线被磁场边界 CD 截下的长度，写出 l 与 x 的关系","expr":"l=2(L-x)","cues":["取磁场内那段","对角线被边界截断","不是整条对角线"],"concepts":["有效长度","安培力"]},{"title":"恒流源电流方向判断","type":"前提判断","judge":"线框各边中电流方向如何，安培力是否同向叠加、合力方向是否沿 Ox 轴","why":"恒流源保证电流大小和方向不变，安培力方向由左手定则决定；线框关于 Ox 轴对称，垂直于 Ox 的分力互相抵消，只剩沿 Ox 方向的合力","do":"对磁场内的两条边分别用左手定则定安培力方向，判断垂直分量是否抵消、沿轴分量是否同向","expr":"F_{\\text{安}}=BIl","cues":["两边受力同向","垂直分量抵消","合力沿x轴"],"concepts":["左手定则","安培力","对称性"]},{"title":"变力做功用平均力","type":"模型选择","judge":"安培力随 x 线性变化，求功时能否用初末安培力的平均值乘位移","why":"F 与 x 成一次函数关系，力—位移图像是直线，直线下的面积等于平均力乘位移，不能直接用某一位置的力乘全程","do":"写出 F(x)，取 x=0 与 x=L/2 两端的力值求平均，再乘位移 L/2","expr":"W=\\frac{F_1+F_2}{2}\\cdot\\frac{L}{2}","cues":["力随位置线性变","取平均力","看力位移图像面积"],"concepts":["变力做功","平均力","动能定理"]},{"title":"冲量用动量定理","type":"关系建立","judge":"求安培力的冲量是直接对变力积分，还是借合力做功先求速度再用动量定理","why":"安培力是变力，冲量难直接积分；但水平面光滑、只有安培力做功，可由动能定理得末速度，再由动量定理得冲量","do":"先用 W=½mv² 求 x=L/2 处的速度，再用 I_冲=mv 求冲量","expr":"I_{\\text{冲}}=mv=\\sqrt{2mW}","cues":["先求速度","动量定理","光滑面只有安培力"],"concepts":["动量定理","动能定理","冲量"]},{"title":"恒流源电压含反电动势","type":"关系建立","judge":"恒流源提供的电压是否只等于 IR，还是要加上线框切割磁感线产生的动生电动势项","why":"线框在磁场中运动切割磁感线，产生动生电动势，恒流源要维持电流 I 必须克服这一反电动势，能量守恒给出 UI=安培力功率+I²R","do":"写出能量守恒式，用安培力的功率 Fv 代替动生电动势项，解出 U","expr":"UI=Fv+I^2R","cues":["要克服反电动势","能量守恒","不只是电阻压降"],"concepts":["动生电动势","能量守恒","恒流源"]},{"title":"类比简谐运动求时间","type":"模型选择","judge":"回复力 F=2BI(L-x) 与偏离平衡位置的位移成正比，运动是否为简谐运动、两次时间是否相同","why":"F 与 (L-x) 成正比且指向平衡位置 x=L，符合简谐运动回复力特征，周期只由 m 和等效劲度系数决定，与振幅无关","do":"令 x'=L-x 作位移，写出 F=kx' 定出 k=2BI，用周期公式比较两次从最大位移到平衡位置的时间","expr":"T=2\\pi\\sqrt{\\frac{m}{2BI}}","cues":["回复力与位移成正比","类比弹簧振子","周期与振幅无关"],"concepts":["简谐运动","回复力","周期"]}],"171":[{"title":"核反应方程配平","type":"前提判断","judge":"中子轰击氮-14 生成碳-14 时，剩余的那个核子应写成质子还是中子，以及 β 衰变方程中电子与反中微子如何取舍","why":"核反应必须满足质量数守恒和电荷数守恒，β 衰变是原子核内一个中子转变为质子并放出一个电子","do":"对第一个方程用质量数 1+14=14+A、电荷数 0+7=6+Z 定出 A=1、Z=1；对第二个方程用 14=14+0、6=7+(-1) 检验并写出电子","expr":"{}^{1}_{0}\\mathrm{n}+{}^{14}_{7}\\mathrm{N}\\to{}^{14}_{6}\\mathrm{C}+{}^{1}_{1}\\mathrm{H},\\quad {}^{14}_{6}\\mathrm{C}\\to{}^{14}_{7}\\mathrm{N}+{}^{0}_{-1}\\mathrm{e}","cues":["质量数守恒","电荷数守恒","β衰变放电子"],"concepts":["核反应方程","质量数守恒","β 衰变"]},{"title":"比荷定电压高低","type":"关系建立","judge":"由 U 与比荷的关系判断三种同位素中哪一种对应图(b)中较高的那段平台电压","why":"离子在电场中加速、在磁场中做圆周运动，轨道半径固定为 R，联立得 U 正比于 m/q，即比荷越小所需电压越大","do":"由 qU=mv²/2 与 qvB=mv²/R 消去 v，得到 U 的表达式，再比较 12、13、14 三种 C³⁺ 的 m/q","expr":"U=\\frac{qB^{2}R^{2}}{2m}","cues":["比荷越小电压越大","半径固定","先消去速度"],"concepts":["动能定理","洛伦兹力提供向心力","比荷"]},{"title":"读图取平台电压","type":"图像读取","judge":"图(b)中 12C 与 13C 百分比同时达到 100% 的那段电压区间对应哪一个 U 值","why":"只有电压使两种离子的轨道半径都恰等于管道半径 R 时，它们才能全部通过并被接收器计数","do":"在图(b)上找两条曲线都升到 100% 的平台段，读出该平台对应的电压值作为 12C 的 U","expr":"","cues":["看100%平台","两条曲线重合段","读横坐标"],"concepts":["图像读取","共振通过条件"]},{"title":"类斜抛的对称性","type":"模型选择","judge":"14C 离子在两极板间是匀速直线还是类斜抛，以及出射点相对入射点的高度关系","why":"离子以 45° 斜射入匀强电场，水平方向不受力做匀速运动，竖直方向受电场力做匀变速运动；两孔等高且只允许 45° 入射，说明竖直方向先减速到零再返回，运动具有对称性","do":"把速度分解为水平 v/√2 与竖直 v/√2，水平方向用 L=v_x t 求时间，竖直方向用 v_y=a·t/2 表示回到原高度","expr":"v_x=v_y=\\frac{\\sqrt{2}}{2}v,\\quad L=v_xt,\\quad v_y=a\\frac{t}{2}","cues":["分解速度","水平匀速","竖直先减速再返回","两孔等高"],"concepts":["运动的分解","类斜抛运动","匀强电场"]},{"title":"消去速度求板间电压","type":"数学处理","judge":"如何把上一问得到的 v 与板间加速度 a=qU₁/(md) 联立，消去 v 和 t 只留 U₁","why":"v 已由磁体-Ⅱ 的 B、R 和 14C 的比荷确定，板间电压只通过加速度影响竖直运动，必须消去中间量才能解出 U₁","do":"由 v=qBR/m 代入 v_y=a t/2 与 L=v_x t，整理出 U₁ 只含 B、R、d、L 和 m/q","expr":"U_1=\\frac{qB^{2}R^{2}d}{mL}","cues":["先求速度","消去时间","只留电压"],"concepts":["联立消元","匀变速直线运动"]},{"title":"比值定衰变年数","type":"数学处理","judge":"古木与活木中 14C/12C 的比值之比说明 14C 只剩原来的几分之几，以及如何由半衰期换算成时间","why":"12C 不衰变，比值下降完全由 14C 的指数衰变造成；活木比值是初始值，古木比值是剩余值","do":"先算比值 4×10⁻¹³/1.2×10⁻¹²=1/3，再由 (1/2)ⁿ=1/3 求半衰期个数 n=ln3/ln2，最后乘 5700 年","expr":"\\left(\\frac{1}{2}\\right)^{n}=\\frac{1}{3},\\quad n=\\frac{\\ln 3}{\\ln 2},\\quad t=5700n","cues":["比值相除","剩下三分之一","几个半衰期","取对数"],"concepts":["半衰期","指数衰变","比值法"]}],"172":[{"title":"由公式反解单位","type":"关系建立","judge":"要判断 h 的单位该由哪个等式变形得到","why":"物理量单位由定义式决定，E=hν 中 E 与 ν 的单位已知，h 的单位只能由 h=E/ν 导出，不能凭记忆直接猜","do":"把 E=hν 变形为 h=E/ν，用 E 的单位除以 ν 的单位","expr":"h=\\frac{E}{\\nu}","cues":["先变形公式","用定义式推单位"],"concepts":["物理量的单位","定义式"]},{"title":"频率单位的换算","type":"前提判断","judge":"要判断频率 ν 的单位赫兹用基本单位表示是什么","why":"Hz 是导出单位，只有化成 s⁻¹ 才能与焦耳相除得到 h 的单位形式","do":"把 Hz 写成 s⁻¹ 再参与运算","expr":"1\\,\\mathrm{Hz}=1\\,\\mathrm{s}^{-1}","cues":["赫兹就是每秒","化成秒的倒数"],"concepts":["导出单位","赫兹"]},{"title":"单位相除得 J·s","type":"数学处理","judge":"要判断 J 除以 s⁻¹ 后单位落在分子还是分母","why":"除以 s⁻¹ 等于乘以 s，秒应出现在分子上，若误当成除以 s 就会得到 J/s","do":"做 J/(s⁻¹) 的运算，把 s 提到分子","expr":"\\frac{\\mathrm{J}}{\\mathrm{s}^{-1}}=\\mathrm{J}\\cdot\\mathrm{s}","cues":["除以倒数变乘法","秒跑到上面"],"concepts":["单位运算","量纲"]}],"173":[{"title":"能否视为质点","type":"模型选择","judge":"研究返回舱运行轨迹时，能否忽略其大小和形状而视为质点","why":"物体能否视为质点取决于其尺寸对所研究问题的影响是否可忽略；轨迹长度远大于返回舱尺寸，形状不影响轨迹分析","do":"比较返回舱尺寸与轨迹长度，判断形状结构是否影响轨迹描述","expr":"","cues":["看轨迹","尺寸可忽略","形状不影响"],"concepts":["质点","理想化模型"]},{"title":"引力随高度变化","type":"关系建立","judge":"返回舱靠近地面过程中，地球对它的万有引力是增大还是减小","why":"万有引力与到地心距离的平方成反比，距离减小则引力增大","do":"写出引力表达式，看距离减小时引力的变化趋势","expr":"F=\\frac{GMm}{r^{2}}","cues":["离地越近","距离变小","引力变大"],"concepts":["万有引力定律"]},{"title":"超重失重判据","type":"临界条件","judge":"反推发动机点火减速时，宇航员处于超重还是失重","why":"加速度方向向上时支持力大于重力为超重，加速度向下才是失重；减速下降意味着加速度向上","do":"先定加速度方向，再比较支持力与重力的大小","expr":"N-mg=ma","cues":["先看加速度","减速下降","支持力更大"],"concepts":["超重与失重","牛顿第二定律"]},{"title":"平均速度与平均速率","type":"前提判断","judge":"轨迹长度与时间的比值是平均速度还是平均速率","why":"平均速度是位移与时间之比，平均速率是路程与时间之比，轨迹长度是路程","do":"区分位移与路程，对应到平均速度与平均速率的定义","expr":"\\bar v=\\frac{\\Delta x}{\\Delta t},\\quad \\text{平均速率}=\\frac{s}{t}","cues":["位移不是路程","轨迹长是路程","两个概念不同"],"concepts":["位移与路程","平均速度","平均速率"]}],"174":[{"title":"落点高度决定飞行时间","type":"模型选择","judge":"钢球离开桌面后竖直方向做什么运动、下落高度取桌面到木板的竖直距离 h","why":"平抛运动竖直分运动为自由落体，飞行时间只由竖直下落高度决定，与水平初速度无关","do":"对竖直方向列自由落体位移公式，解出飞行时间 t","expr":"h=\\frac{1}{2}gt^{2}\\Rightarrow t=\\sqrt{\\frac{2h}{g}}","cues":["竖直方向自由落体","时间只看高度","h是桌面到木板"],"concepts":["平抛运动","自由落体","运动的分解"]},{"title":"水平方向匀速求初速","type":"关系建立","judge":"水平方向做匀速直线运动，用水平位移 x 与飞行时间 t 的比值表示平抛初速度","why":"平抛运动水平方向不受力，做匀速直线运动，x=v0t","do":"把已求出的 t 代入水平位移关系，把 v0 用 x、h、g 表示","expr":"x=v_{0}t\\Rightarrow v_{0}=\\frac{x}{t}=x\\sqrt{\\frac{g}{2h}}","cues":["水平方向匀速","把时间代进去"],"concepts":["平抛运动","匀速直线运动","初速度"]},{"title":"速度方向由两分速度比决定","type":"关系建立","judge":"撞击木板时速度方向与水平方向的夹角由竖直分速度与水平分速度之比决定，需判断 h 变化时该比值如何变","why":"速度方向由合速度与水平方向夹角的正切决定，tanθ=vy/v0，vy 随 h 增大而增大","do":"写出 tanθ 的表达式，分析 h 增大时 vy 与 v0 各自的变化趋势，比较得出夹角变化","expr":"\\tan\\theta=\\frac{v_{y}}{v_{0}}=\\frac{\\sqrt{2gh}}{v_{0}}","cues":["看竖直和水平速度之比","高度越大竖直速度越大","夹角跟着变"],"concepts":["速度的合成与分解","平抛运动","正切"]},{"title":"水平射程随高度的变化","type":"数学处理","judge":"在初速度由同一释放位置决定（v0 不变）的前提下，判断 h 减小时水平射程 x 如何变化","why":"钢球从斜面同一位置静止滚下，平抛初速度相同，x=v0√(2h/g) 中只有 h 可变","do":"把 x 写成 h 的函数，由 h 减小推出 x 减小","expr":"x=v_{0}\\sqrt{\\frac{2h}{g}}","cues":["初速不变","射程随高度减小","同一位置滚下"],"concepts":["平抛运动","控制变量","水平射程"]}],"175":[{"title":"衍射图样的物理含义","type":"前提判断","judge":"电子穿过铝箔后出现明暗相间的衍射图样，说明电子具有什么性质","why":"衍射是波特有的现象，只有波动性才能产生衍射图样，这是判断本题方向的出发点","do":"把'电子衍射图样'与'波动性'对应起来，排除把衍射图样当作粒子轨迹的说法","expr":"","cues":["衍射说明是波","电子也有波动性","这是粒子轨迹吗"],"concepts":["物质波","波动性","电子衍射"]},{"title":"亮纹的统计解释","type":"模型选择","judge":"亮纹处代表电子出现的概率大，还是代表电子运动的轨迹","why":"电子是微观粒子，其空间分布服从概率波规律，亮纹只是电子到达概率大的区域，单个电子的径迹无法用亮纹描述","do":"用概率波观点解释亮纹与暗纹，明确亮纹不等于轨迹","expr":"","cues":["亮纹是概率大","不是轨迹","概率波"],"concepts":["概率波","统计规律"]},{"title":"波长与加速电压的关系","type":"关系建立","judge":"电子速度（或加速电压）变化时，物质波波长如何变化","why":"德布罗意关系 λ=h/p 把波长与动量联系起来，速度越大动量越大波长越短","do":"写出 λ=h/(mv)，比较速度增大时波长的增减","expr":"$\\lambda=\\frac{h}{p}=\\frac{h}{mv}$","cues":["速度大波长小","用德布罗意关系","波长反比于动量"],"concepts":["德布罗意波长","动量"]},{"title":"波长与衍射显著程度","type":"关系建立","judge":"波长变短时衍射现象更明显还是更不明显，中心亮斑半径如何变化","why":"波长越短衍射越不明显，条纹和中心亮斑越窄，这是波动衍射的普遍规律","do":"由波长变化推断衍射显著程度，再推断中心亮斑半径的变化方向","expr":"","cues":["波长短衍射不明显","亮斑变小","条纹变窄"],"concepts":["衍射","波长"]}],"176":[{"title":"周期公式的依赖关系","type":"关系建立","judge":"要判断振荡周期由哪些电路参量决定、随它们怎样变化","why":"LC 振荡周期由自感系数和电容共同决定，只有先明确周期随 L、C 增大而增大，才能把各选项的操作翻译成周期的变化","do":"写出周期公式，明确 T 与 L、C 都是正相关（单调递增）","expr":"T=2\\pi\\sqrt{LC}","cues":["周期看电感和电容","根号里是乘积","L或C变大周期变大"],"concepts":["LC 振荡电路","电磁振荡周期"]},{"title":"自感系数的变化判断","type":"前提判断","judge":"要判断插入铁芯、增加匝数这类操作使自感系数变大还是变小","why":"自感系数由线圈本身结构决定，插入铁芯或增加匝数都会增强线圈的磁通量变化效果，使 L 增大","do":"比较操作前后线圈的自感系数，判断 L 是增大还是减小","expr":"","cues":["插铁芯电感变大","匝数多电感大","L只由线圈决定"],"concepts":["自感系数","线圈"]},{"title":"电容的变化判断","type":"前提判断","judge":"要判断插入电介质、改变极板间距使电容变大还是变小","why":"平行板电容器的电容由介电常数、正对面积和极板间距决定，插入电介质使介电常数增大，间距增大使电容减小","do":"按电容公式比较操作前后介电常数与极板间距的变化方向，得出电容变化","expr":"C=\\frac{\\varepsilon_r S}{4\\pi kd}","cues":["插介质电容变大","间距大电容小","看介电常数和间距"],"concepts":["平行板电容器","电容"]},{"title":"合成周期变化方向","type":"结论整理","judge":"要把各操作引起的 L、C 变化合起来，判断周期是增大还是减小","why":"题目要求减小周期，只有使 L 或 C 减小（且另一个不变）的操作才符合要求","do":"对每个操作先定 L、C 的变化方向，再代入周期公式判断 T 的增减，挑出使 T 减小的那一个","expr":"T\\propto\\sqrt{LC}","cues":["要周期小就得LC小","间距增大电容变小","插铁芯反而周期变大"],"concepts":["周期与自感电容的关系"]}],"177":[{"title":"判断是否简谐运动","type":"模型选择","judge":"橡皮绳弹力与摩擦力共同作用下，回复力是否满足 F=-kx 的形式","why":"简谐运动要求回复力大小与位移成正比且方向总指向平衡位置；摩擦力是大小恒定的力，不随位移线性变化，会破坏这一比例关系","do":"写出物块在任意位置所受合力沿中垂线方向的表达式，检查其中是否含恒定项","expr":"F_合 = 2F_弹 sinθ - μmg","cues":["看回复力","摩擦力是恒力","不成正比"],"concepts":["简谐运动","回复力","滑动摩擦力"]},{"title":"确定平衡位置不在C点","type":"前提判断","judge":"物块速度最大（合力为零）的位置是否就是C点","why":"C点是橡皮绳原长位置，弹力为零，但此处仍有摩擦力，合力不为零，故C点不是平衡位置，物块不会在C点两侧对称往复","do":"比较C点处弹力合力与摩擦力的大小，判断合力是否为零","expr":"","cues":["C点弹力为零","还有摩擦力","平衡位置偏移"],"concepts":["平衡位置","合力为零"]},{"title":"求两绳夹角的合力","type":"几何关系","judge":"当∠AOB=90°时，两根橡皮绳弹力的合力如何由单根弹力求","why":"两绳等长、对称分布，两弹力大小相等、夹角为90°，合力沿角平分线（中垂线）方向，大小等于单根弹力的√2倍","do":"用平行四边形定则合成两等大且互相垂直的弹力","expr":"F_弹合 = √(F²+F²) = √2 F","cues":["两力垂直","等大合成","沿中垂线"],"concepts":["力的合成","平行四边形定则"]},{"title":"合力方向与摩擦力方向","type":"关系建立","judge":"弹力合力与摩擦力是相加还是相减，方向如何","why":"物块向C运动时弹力合力指向C，摩擦力阻碍相对运动、方向背离C，二者反向，故合力大小为弹力合力减去摩擦力","do":"沿中垂线方向规定正方向，写出合力的代数和","expr":"F_合 = √2 F - μmg","cues":["方向相反","弹力向前","摩擦向后"],"concepts":["合力","摩擦力方向"]},{"title":"用动能定理求弹力做功","type":"关系建立","judge":"从O到C过程中，弹力做的功能否由动能定理间接求出","why":"摩擦力大小恒为μmg、路程为L，摩擦生热可直接算出；初动能为零、末动能由末速度给出，故弹力做功等于动能增量加摩擦生热","do":"对O到C过程列动能定理，把摩擦力的功移到等号右边","expr":"W - μmgL = ½mv₀²","cues":["用动能定理","摩擦力做负功","初速为零"],"concepts":["动能定理","摩擦力做功"]}],"178":[{"title":"电池容量换算成电能","type":"关系建立","judge":"能否把电池的安时容量换算成以度（千瓦时）为单位的电能，用来和灯的耗电量比较","why":"容量 Q 与电压 U 的乘积才是电能，单位是 W·h，必须换算成 kW·h 才能与灯的耗电同单位比较","do":"用 E=UQ 算出电池总电能，再除以 1000 换成度","expr":"E=UQ=48\\times200=9600\\,\\mathrm{W\\cdot h}=9.6\\,\\mathrm{kW\\cdot h}","cues":["安时乘电压","换算成度","先算总电能"],"concepts":["电功","电池容量","单位换算"]},{"title":"一周耗电按每天十小时","type":"前提判断","judge":"连续一周阴雨时，灯每天照明时间仍取 10 h，而不是 24 h 全亮","why":"题设给出平均每天照明 10 h，这是灯的日耗电时间，不能按全天通电计算","do":"用 W=P·t 算一周耗电，t 取 7×10 h","expr":"W=Pt=0.06\\times70=4.2\\,\\mathrm{kW\\cdot h}","cues":["每天亮十小时","一周七天","不能按全天算"],"concepts":["电功","额定功率"]},{"title":"比较电能定能否供电","type":"临界条件","judge":"判断电池储存的电能是否大于一周所需电能，从而确定能否连续工作","why":"电池充满后无补充能源，只有储存电能不小于一周耗电才能保证正常照明","do":"比较 9.6 kW·h 与 4.2 kW·h 的大小","expr":"E=9.6\\,\\mathrm{kW\\cdot h}>W=4.2\\,\\mathrm{kW\\cdot h}","cues":["比大小","够不够用","看谁大"],"concepts":["能量守恒","电能比较"]},{"title":"风能功率与风速三次方","type":"模型选择","judge":"判断风力发电机输出功率与风速是三次方关系还是一次方关系","why":"风的动能正比于 v²，单位时间通过扇叶截面的空气质量又正比于 v，两者相乘得功率正比于 v³","do":"取 Δt 内通过截面空气柱，用动能除以时间导出功率表达式","expr":"P=\\frac{\\tfrac12\\rho\\pi r^{2}v^{3}\\Delta t}{\\Delta t}=\\tfrac12\\rho\\pi r^{2}v^{3}","cues":["取空气柱","动能除以时间","三次方"],"concepts":["风能","功率","流体模型"]},{"title":"光电转换有效率损失","type":"前提判断","judge":"判断太阳能板接收的辐射能是否全部转化为电能","why":"单晶硅太阳能板存在转换效率（约 15%~20%），辐射能不能全部变成电能","do":"指出接收辐射能与输出电能之间需乘转换效率","expr":"","cues":["有转换效率","不能全转化","有损耗"],"concepts":["太阳能电池","转换效率"]},{"title":"节煤减排的换算链","type":"数学处理","judge":"判断六年总耗电换算成节煤量与减排量时，该用除法还是乘法，以及数量级","why":"每 2.8 度电对应 1 kg 煤、对应 2.6 kg 二氧化碳，需先由电量求煤量再乘排放系数","do":"算六年总电量，除以 2.8 得煤量，再乘 2.6 得减排量，核对数量级","expr":"M=\\frac{1314}{2.8}\\times2.6\\approx1.2\\times10^{3}\\,\\mathrm{kg}","cues":["先求总电量","除以二点八","数量级不对"],"concepts":["电能","比例换算","数量级"]}],"179":[{"title":"库仑力做功正负","type":"关系建立","judge":"α粒子沿轨迹1靠近再远离金核的过程中，库仑斥力与速度方向的夹角如何变化，从而判断库仑力做正功还是负功","why":"库仑力沿两核连线向外，轨迹1先靠近后远离，靠近段力与速度成钝角做负功、远离段成锐角做正功，不能笼统说一直做负功","do":"在轨迹1上取靠近段和远离段各一点，比较库仑斥力方向与该点速度方向的夹角","expr":"","cues":["先靠近后远离","斥力向外","夹角看钝锐"],"concepts":["库仑力","功的正负","曲线运动速度方向"]},{"title":"最近点动能不为零","type":"临界条件","judge":"α粒子沿轨迹2到达离金核最近的点P时，速度（动能）是否为零","why":"α粒子做曲线运动，速度方向沿轨迹切线，最近点处速度方向与连线垂直而非速度为零；只有正碰（速度沿连线）才可能瞬时静止","do":"画出P点处轨迹的切线方向，判断该点速度是否为零，并比较该点与无穷远处的动能、电势能大小","expr":"","cues":["曲线运动速度不为零","切线方向","最近处电势能最大"],"concepts":["曲线运动","动能","电势能"]},{"title":"等势面判电势能","type":"前提判断","judge":"以金核为圆心的虚线圆周是否为等势面，圆周上各点电势是否相等","why":"点电荷电场中等势面是以电荷为球心的球面，圆周上各点到金核距离相同，电势相同，同一α粒子在各点的电势能相等","do":"比较虚线圆上三点到金核的距离，由点电荷电势分布判断三点电势及α粒子电势能关系","expr":"","cues":["到核距离相同","等势面是球面","电势能相等"],"concepts":["点电荷电势","等势面","电势能"]},{"title":"库仑力量级估算","type":"数学处理","judge":"把α粒子电荷取2e、金核电荷取79e、距离取10⁻¹⁴ m代入库仑定律后，结果的数量级是多少","why":"库仑定律F=kqQ/r²中α粒子带2个元电荷、金核带79个元电荷，距离为10⁻¹⁴ m时平方后放大到10²⁸量级，需正确估算数量级","do":"代入q=2e、Q=79e、r=10⁻¹⁴ m计算F，再取数量级与选项比较","expr":"F=k\\dfrac{(2e)(79e)}{r^{2}}","cues":["α粒子带两个元电荷","金核带七十九个","数量级看十的幂"],"concepts":["库仑定律","元电荷","数量级估算"]}],"180":[{"title":"撞击过程按匀减速建模","type":"模型选择","judge":"鸡蛋触地后到静止这段，能否当作匀减速直线运动处理","why":"题给上下沿接触地面的时间差即撞击时间，隐含把鸡蛋视为整体、在恒定阻力下匀减速到零，才能用平均速度求时间","do":"认定触地过程为匀减速至静止，用平均速度等于初末速度平均值求时间","expr":"\\bar v=\\frac{v}{2},\\quad \\Delta t=\\frac{s}{\\bar v}=\\frac{2s}{v}","cues":["匀减速到零","用平均速度","撞击时间"],"concepts":["匀变速直线运动","平均速度"]},{"title":"撞击时间用位移与速度表示","type":"关系建立","judge":"撞击时间该由哪个已知量（5 cm 位移）和待求速度 v 共同决定，而不是直接取某个固定值","why":"题设明确用上下沿距离作为撞击过程的位移，时间必须由 s 与 v 联立得出，否则动量定理中多出一个未知量","do":"把 s=0.05 m 代入 Δt=2s/v，将时间写成 v 的函数","expr":"\\Delta t=\\frac{2\\times0.05}{v}=\\frac{0.1}{v}","cues":["位移是五厘米","时间含速度","两个未知量"],"concepts":["位移","速度"]},{"title":"动量定理含重力冲量","type":"前提判断","judge":"撞击过程中重力冲量 mgΔt 是否可以忽略，还是必须与冲击力一起计入","why":"冲击力 500 N 与 mg≈0.5 N 相比虽小，但解析中保留 (F−mg) 才是严格式；若直接令 FΔt=mv 会引入系统偏差，且这是动量定理的完整形式","do":"对撞击过程取竖直向上为正，列合外力的冲量等于动量变化","expr":"(F-mg)\\Delta t=0-(-mv)","cues":["合外力冲量","要减重力","取向上为正"],"concepts":["动量定理","冲量"]},{"title":"联立求落地速度","type":"数学处理","judge":"把时间表达式代入动量定理后，方程中只剩 v 一个未知量，可直接解出 v","why":"F、m、g、s 均已知，Δt 已用 v 表示，代入后成为关于 v 的一元方程","do":"将 Δt=0.1/v 代入 (F−mg)Δt=mv，解出 v","expr":"(500-0.5)\\cdot\\frac{0.1}{v}=0.05v\\Rightarrow v\\approx\\sqrt{1000}\\ \\mathrm{m/s}","cues":["只剩一个未知数","代入消时间","解出速度"],"concepts":["动量定理","一元方程"]},{"title":"自由落体求高度再折楼层","type":"关系建立","judge":"落地速度与下落高度由自由落体规律联系，且楼层数需用每层约 3 m 折算","why":"鸡蛋从静止坠落，只受重力，v²=2gh 给出高度；题目问楼层，必须再除以层高并取整","do":"由 v²=2gh 求 h，再用 h 除以 3 m 得楼层数","expr":"h=\\frac{v^{2}}{2g}\\approx51\\ \\mathrm{m},\\quad n=\\frac{51}{3}=17","cues":["自由落体","除以层高","约十七层"],"concepts":["自由落体运动","估算"]}],"181":[{"title":"由波形图数波腹定波长","type":"图像读取","judge":"要从图乙判断金属丝上形成几个波腹，从而确定弦长与波长的关系","why":"两端固定、中点为波腹的驻波，相邻波腹间距为半个波长，波腹数决定弦长等于几个半波长","do":"数图乙中金属丝上的波腹个数，用弦长除以半波长个数求波长","expr":"L = n\\cdot\\frac{\\lambda}{2}","cues":["数波腹","三个鼓包","两端固定"],"concepts":["驻波","波长","波腹"]},{"title":"区分振动速度与波速","type":"前提判断","judge":"要判断题目所求的“振动最大速度”是质点振动的速度，不是波沿金属丝传播的波速","why":"波速由波长和频率决定，而切割磁感线产生电动势的是质点上下振动的速度，两者物理意义不同","do":"把波速与质点振动最大速度分开计算，电动势公式中代入的是质点振动速度","expr":"v_{\\text{波}}=\\lambda f,\\quad v_m=2\\pi fA","cues":["两个速度别混","波速不是振动速度","切割用振动速度"],"concepts":["波速","简谐振动速度","频率"]},{"title":"切割长度取磁场区宽度","type":"模型选择","judge":"要判断切割磁感线的有效长度是磁场作用区宽度，而不是整根金属丝长度","why":"只有处于匀强磁场中的那一段导体才切割磁感线产生电动势，磁场外部分不贡献","do":"取磁场范围宽度作为有效切割长度，与质点最大速度相乘求最大电动势","expr":"E_{\\max}=B\\,l_{\\text{有效}}\\,v_m,\\quad l_{\\text{有效}}=1.00\\,\\mathrm{cm}","cues":["只用磁场里那段","有效长度","别拿一米算"],"concepts":["动生电动势","有效切割长度","匀强磁场"]},{"title":"正弦交流取有效值","type":"关系建立","judge":"要判断振动产生的电动势是正弦式交变电，功率计算须用有效值而非最大值","why":"质点做简谐振动，速度按正弦规律变化，感应电动势也是正弦式，有效值等于最大值除以根号二","do":"先由最大电动势求有效值，再代入功率公式","expr":"E=\\frac{E_{\\max}}{\\sqrt{2}}","cues":["正弦交流","用有效值","除以根号二"],"concepts":["正弦交流电","有效值","最大值"]},{"title":"最大输出功率匹配条件","type":"临界条件","judge":"要判断外电阻取何值时电源输出功率最大，即内外电阻相等","why":"闭合电路欧姆定律下，外电阻等于内阻时输出功率取极大值","do":"令外电阻等于金属丝电阻，用有效电动势和内阻算最大输出功率","expr":"P_{\\max}=\\frac{E^{2}}{4r},\\quad R=r","cues":["内外电阻相等","匹配","输出最大"],"concepts":["闭合电路欧姆定律","输出功率","内阻"]},{"title":"纵波端点必为节点","type":"结论整理","judge":"要判断改为纵波后两端固定时端点与中点的振动状态","why":"两端固定约束使端点位移恒为零，是纵波驻波的节点，中点则为波腹","do":"由端点位移为零推出端点必为节点，据此否定中点振幅为零的说法","expr":"","cues":["端点不能动","端点是节点","中点振幅最大"],"concepts":["纵波","驻波节点","边界条件"]}],"182":[{"title":"热量传递方向判据","type":"前提判断","judge":"热量能否自发地从低温物体传到高温物体","why":"热力学第二定律指明热传导具有方向性，自发过程不可逆；只有借助外界做功才能实现逆向传热","do":"对照选项表述，看是否声称'自发'由低温传向高温","expr":"","cues":["自发传热","低温到高温","需要外界做功"],"concepts":["热力学第二定律","热传导方向性"]},{"title":"时间延缓与寿命关系","type":"关系建立","judge":"粒子高速运动时其固有时间进程与静止观察者测得寿命的关系","why":"相对论时间延缓效应表明运动的时钟变慢，粒子自身时间进程变慢，实验室测得的寿命应比静止时更长","do":"比较粒子静止寿命与高速运动时的观测寿命，判断'速度越大寿命越短'的说法是否成立","expr":"$\\Delta t=\\dfrac{\\Delta \\tau}{\\sqrt{1-v^2/c^2}}$","cues":["运动的钟变慢","寿命变长","速度大寿命短"],"concepts":["时间延缓","相对论效应","固有时间"]},{"title":"变压器副线圈电动势来源","type":"模型选择","judge":"副线圈中的感应电动势是由变化的磁场直接产生，还是由原线圈电流直接传递","why":"变压器依据电磁感应，原线圈的变化电流产生变化磁场，穿过副线圈引起磁通量变化，在副线圈中激发感生电场驱动自由电荷","do":"确认副线圈电动势的物理机制是磁通量变化引起的感生电场，而非电流直接传导","expr":"$\\mathcal{E}=-\\dfrac{d\\Phi}{dt}$","cues":["电磁感应","磁通量变化","感生电场"],"concepts":["电磁感应","感生电场","变压器原理"]},{"title":"传感器工作量的识别","type":"模型选择","judge":"电阻应变片是把形变（非电学量）转换为电阻变化，还是把电阻变化转换为其他量","why":"传感器的作用是把非电学量转换为电学量，电阻式传感器以电阻为敏感量，通过测电阻反推温度、形变等非电学量","do":"判断应变片受力形变时电阻改变、再由电阻变化确定外力这一因果链是否成立","expr":"","cues":["电阻变化","测非电学量","应变片"],"concepts":["传感器","电阻应变效应"]}],"183":[{"title":"比较两光光子能量","type":"前提判断","judge":"要判断从 n=4 和 n=6 分别跃迁到 n=2 时，哪一次放出的光子能量更大","why":"能级差越大，放出光子能量越大；n=6 与 n=2 的能级差大于 n=4 与 n=2 的能级差，故 Q 光能量大、频率高","do":"写出两次跃迁的能量差，比较 E6−E2 与 E4−E2 的大小，定出 P、Q 的频率高低","expr":"h\\nu = E_n - E_2","cues":["能级差大的光能量大","先比频率高低"],"concepts":["能级跃迁","光子能量"]},{"title":"频率定折射率与波长","type":"关系建立","judge":"要判断由频率高低能否推出折射率大小和波长长短","why":"同种介质中频率越高的光折射率越大、波长越短，这是把能级信息接到后面四个光学装置的唯一桥梁","do":"由 Q 光频率高得出 n_Q>n_P、λ_Q<λ_P，作为后面各项的共同前提","expr":"n_Q>n_P,\\ \\lambda_Q<\\lambda_P","cues":["频率高折射率大","频率高波长短"],"concepts":["折射率","波长与频率"]},{"title":"棱镜偏折与谱线位置","type":"几何关系","judge":"要判断经三棱镜后哪条谱线对应 P 光","why":"折射率越大偏折越明显，Q 光折射率大，偏折大，落在离顶角更远的位置","do":"比较两光通过棱镜后的偏折程度，把偏折小的谱线对应到 P 光","expr":"","cues":["折射率大偏得多","偏得少的是P"],"concepts":["棱镜色散","偏折角"]},{"title":"全反射临界角比较","type":"临界条件","judge":"要判断玻璃棒能导出哪种光，取决于临界角大小","why":"临界角由 sinC=1/n 决定，折射率小的 P 光临界角大，更不容易全反射；能导出临界角大的光，就一定能导出临界角小的光","do":"比较 P、Q 的临界角，判断哪种光更容易在侧面发生全反射而漏出","expr":"\\sin C=\\frac{1}{n}","cues":["临界角大的易导出","折射率小临界角大"],"concepts":["全反射","临界角"]},{"title":"干涉条纹间距比较","type":"关系建立","judge":"要判断换成 Q 光后条纹间距变大还是变小","why":"双缝干涉条纹间距与波长成正比，Q 光波长短，条纹间距应变小","do":"用 Δx 与 λ 的正比关系比较两光的条纹间距","expr":"\\Delta x=\\frac{L}{d}\\lambda","cues":["波长长的条纹宽","Q光条纹更密"],"concepts":["双缝干涉","条纹间距"]},{"title":"光电效应图线对应","type":"图像读取","judge":"要判断丁图中哪条图线对应 P 光、哪条对应 Q 光","why":"截止电压（横轴截距）由入射光频率决定，频率高的 Q 光截止电压更大，图线应更靠右","do":"比较两图线在横轴上的截距大小，把截距大的对应到 Q 光","expr":"eU_c = h\\nu - W_0","cues":["频率高截止电压大","看横轴截距"],"concepts":["光电效应","截止电压"]}],"184":[{"title":"椭圆轨道焦点定位","type":"模型选择","judge":"要判断物体做椭圆运动时，月球球心 O 处于椭圆轨道的什么特殊位置","why":"月球质量集中在球心，引力始终指向 O，只有 O 为椭圆焦点时，轨道才满足开普勒定律和椭圆几何性质","do":"把月球球心 O 取为椭圆的一个焦点，另一个焦点记为 O'，再用椭圆定义把发射点到 M 的路径长度与半长轴联系起来","expr":"O'M+OM=2a","cues":["球心是焦点","取O为焦点","椭圆定义"],"concepts":["椭圆轨道","开普勒定律","中心天体"]},{"title":"最短周期对应最小半长轴","type":"关系建立","judge":"要判断“周期最短”这个条件应转化为椭圆哪个几何量的最小化","why":"由开普勒第三定律，绕同一中心天体的轨道周期只由半长轴 a 决定，a 越小周期越短","do":"写出开普勒第三定律，把周期最短等价为半长轴 a 最小，再在 O、O'、M 构成的几何关系中找 a 的极小值","expr":"\\frac{a^{3}}{T^{2}}=C","cues":["周期看半长轴","a最小周期最短","开普勒第三定律"],"concepts":["开普勒第三定律","半长轴"]},{"title":"垂直时半长轴取极小","type":"几何关系","judge":"要判断 O' 在满足 O'M+OM=2a 的约束下取何位置时 a 最小","why":"OM=R 固定，a 随 O'M 变化，O'M 是 O' 到定点 M 的距离，其最小值对应 O' 落在过 M 的垂线上","do":"作 OO' 与 MO' 垂直的几何图，此时 O'M=Rcosφ，代入椭圆定义求 a，并由此读出焦距 2c=OO'=Rsinφ","expr":"2a=R\\cos\\varphi+R,\\quad 2c=R\\sin\\varphi","cues":["作垂线","O'M最短","画几何图"],"concepts":["椭圆几何性质","极值条件"]},{"title":"由 a 反推发射高度","type":"几何关系","judge":"要判断发射点（北极正上方）到月面的高度 h 与 a、c、R 的几何关系","why":"发射点在长轴端点一侧，到球心距离为 a+c，减去月球半径 R 才是离月面高度","do":"用 h=a+c-R 计算，并代入 φ=60° 得到的 a、c 值检验","expr":"h=a+c-R","cues":["长轴端点","减去半径","a加c"],"concepts":["椭圆半长轴","焦距","高度"]},{"title":"用表面重力换算周期","type":"关系建立","judge":"要判断如何把椭圆周期与已知的表面重力加速度 g月 联系起来","why":"题目只给 g月 和 R，需借助贴月面圆轨道作为桥梁：重力提供向心力给出 T0，再用开普勒第三定律把 T0 换成椭圆周期","do":"先由 mg月=m(4π²/T0²)R 求 T0，再由 R³/T0²=a³/T² 求 T","expr":"mg_{\\text{月}}=m\\frac{4\\pi^{2}}{T_{0}^{2}}R,\\quad \\frac{R^{3}}{T_{0}^{2}}=\\frac{a^{3}}{T^{2}}","cues":["贴月面圆轨道","重力当向心力","桥接周期"],"concepts":["万有引力提供向心力","开普勒第三定律"]},{"title":"能量守恒比较速度","type":"关系建立","judge":"要判断比较发射速度 v 与 M 点速度 vM 时应使用哪条守恒关系及引力势能表达式","why":"椭圆轨道上只有引力做功，机械能守恒，但势能零点须取无穷远，势能为 -GMm/r，不能漏掉负号","do":"对发射点和 M 点列机械能守恒，用 g月R²=GM 消去 GM，解出 vM 与 v 的关系","expr":"-\\frac{GMm}{R+h}+\\frac{1}{2}mv^{2}=-\\frac{GMm}{R}+\\frac{1}{2}mv_{M}^{2}","cues":["机械能守恒","势能取负","消去GM"],"concepts":["机械能守恒","引力势能"]}],"185":[{"title":"选电流表接法","type":"模型选择","judge":"测干电池电动势和内阻时，电流表应相对电源外接还是内接（即选甲还是乙）","why":"电压表分流与电流表分压都会带来系统误差，需比较哪种接法对 r 的测量影响更小；干电池内阻很小，电流表内阻与之可比","do":"比较甲、乙两图中电流表所测电流是否为干路电流、电压表所测是否为路端电压，判断哪种接法使 r 的测量误差更小","expr":"","cues":["看电流表位置","内阻小怕分流","选甲"],"concepts":["伏安法测电源","系统误差","电流表内接外接"]},{"title":"图像纵轴起点取舍","type":"图像读取","judge":"作 U-I 图时纵轴是否从零开始，还是从接近 1.10 V 处截取","why":"数据 U 只在 1.15~1.35 V 间变化，若纵轴从零起，点挤成一小团，斜率与截距都读不准","do":"在方格纸上以 I 为横轴、U 为纵轴，纵轴取 1.10 V 附近为起点、每格 0.05 V 左右，横轴每格 0.05 A，描点连线并延长到 I=0","expr":"","cues":["纵轴不从零","点太挤","延长到纵轴"],"concepts":["U-I 图像","标度选择","描点作图"]},{"title":"由截距斜率求 E 和 r","type":"关系建立","judge":"U-I 图线的纵轴截距和斜率分别对应电源的哪个参量","why":"闭合电路欧姆定律 U=E-Ir 表明 U 与 I 是线性关系，截距为 E，斜率绝对值为 r","do":"读出图线在 I=0 处的纵截距得 E，取图线上相距较远的两点求 ΔU/ΔI 的绝对值得 r","expr":"U=E-Ir,\\quad r=\\left|\\frac{\\Delta U}{\\Delta I}\\right|","cues":["截距是电动势","斜率是内阻","取两点算斜率"],"concepts":["闭合电路欧姆定律","截距与斜率"]},{"title":"力传感器图读周期","type":"图像读取","judge":"力-时间图上相邻两个拉力峰值之间的时间间隔对应周期的多少","why":"摆球经最低点时绳拉力最大，一次全振动内两次经过最低点，故相邻峰值间隔为半个周期","do":"从图 2 读出首末峰值时刻，数出其间包含的峰值间隔个数，用总时间除以间隔数再乘 2 得周期","expr":"\\Delta t=N\\cdot\\frac{T}{2}\\Rightarrow T=\\frac{2\\Delta t}{N}","cues":["峰值间隔是半周期","数间隔个数","最低点拉力最大"],"concepts":["单摆周期","力传感器","峰值间隔"]},{"title":"光电门计时的周期换算","type":"关系建立","judge":"从第 1 次遮光到第 n 次遮光，摆球经过平衡位置多少次、对应多少个半周期","why":"每次遮光对应摆球经过平衡位置一次，相邻两次遮光间隔为半个周期","do":"数出第 1 次到第 n 次遮光之间的间隔数为 n-1，每个间隔为 T/2，列式解 T","expr":"(n-1)\\frac{T}{2}=t\\Rightarrow T=\\frac{2t}{n-1}","cues":["遮光一次过平衡位置","间隔是半周期","n减1个间隔"],"concepts":["光电门","平衡位置","半周期"]},{"title":"化曲为直求 g 与 h","type":"数学处理","judge":"把含未知摆长（含球心偏移 h）的周期公式变形为 l-T² 的线性关系，再由斜率截距反解 g 和 h","why":"球变形后摆长不等于摆线长，直接代入 T=2π√(l/g) 会引入系统误差，需把 h 作为截距参量一并拟合","do":"由 T=2π√((l+h)/g) 解出 l 关于 T² 的表达式，对照图线斜率 k 与截距 b 建立方程，反解 g 和 h","expr":"l=\\frac{4\\pi^{2}}{g}T^{2}-h,\\quad k=\\frac{4\\pi^{2}}{g},\\quad h=kb","cues":["摆长要加球心偏移","化成直线","斜率求g截距求h"],"concepts":["单摆周期公式","化曲为直","斜率与截距"]},{"title":"圆弧槽偏离实际值归因","type":"误差分析","judge":"圆弧槽实验中测得的 g 明显偏小，主因是摆长取值偏差还是空气阻力、槽面摩擦等次要因素","why":"小钢球有大小，质心轨迹半径与槽半径不同，代入的“摆长”与实际质心轨迹半径不符，属系统误差且量级最大","do":"比较槽半径与球质心轨迹半径，判断所用摆长偏大还是偏小，从而解释 g 偏小的方向","expr":"","cues":["球不能当质点","摆长取错","质心轨迹半径"],"concepts":["系统误差","质心","等效摆长"]}],"186":[{"title":"确定初态压强","type":"前提判断","judge":"状态1刚扣上时罐内压强取大气压还是别的值","why":"扣上瞬间罐口与外界尚未形成压强差，罐内气体与大气连通，压强等于外界大气压","do":"把状态1的压强直接取为大气压强，作为等容过程的起点","expr":"p_1=p_0","cues":["刚扣上还没吸住","罐口和外面通着","初态就是大气压"],"concepts":["大气压强","封闭气体初态"]},{"title":"判定等容过程","type":"模型选择","judge":"从状态1到状态2气体体积变不变，该用哪个气体定律","why":"皮肤不变形、罐口紧贴皮肤，罐内气体体积被罐的容积固定，质量也不变","do":"确认V不变，排除等压、等温定律，选等容变化规律","expr":"V_1=V_2","cues":["皮肤不变形","罐子容积固定","体积没变"],"concepts":["等容变化","查理定律"]},{"title":"温度换算为热力学温度","type":"数学处理","judge":"代入气体定律前温度用摄氏度还是开尔文","why":"气体实验定律中的T必须是热力学温度，摄氏温度不能直接成比例","do":"把两个摄氏温度分别加273换成开尔文再代入","expr":"T_1=350\\,\\mathrm{K},\\ T_2=300\\,\\mathrm{K}","cues":["先加273","换成开尔文","不能用摄氏度比"],"concepts":["热力学温度","温度换算"]},{"title":"判断体积功为零","type":"关系建立","judge":"放热过程中外界对气体做不做功","why":"体积不变则气体不做体积功，热力学第一定律中W=0，内能变化只由热量决定","do":"在热力学第一定律中令W=0，把放热取负值代入","expr":"\\Delta U=W+Q,\\ W=0,\\ Q=-7.35\\,\\mathrm{J}","cues":["体积不变不做功","W等于零","放热取负号"],"concepts":["热力学第一定律","体积功","内能"]},{"title":"吸力源于压强差","type":"模型选择","judge":"皮肤受到的吸力是罐内气体压力还是内外压强差产生的合力","why":"皮肤外侧受大气压、内侧受罐内较低气压，两者反向，净效果由压强差决定","do":"先求内外压强差，再乘以罐口面积得吸力","expr":"F=(p_0-p_2)S","cues":["内外压强差","不是罐内气压本身","两边压力相减"],"concepts":["压强差","压力"]}],"187":[{"title":"斜面上求B点速度","type":"模型选择","judge":"斜面上物块受哪些力做功、能否用动能定理一步求B点速度","why":"斜面光滑，只有重力做功，支持力不做功，可用动能定理；若误把摩擦力或传送带影响算进来就错","do":"对P到B过程列动能定理，重力沿斜面分力乘位移等于动能增量","expr":"mgL\\sin 30^{\\circ}=\\frac{1}{2}mv_B^{2}","cues":["斜面光滑","只有重力做功","用动能定理"],"concepts":["动能定理","重力做功"]},{"title":"判断传送带上加速还是减速","type":"前提判断","judge":"物块滑上传送带时速度与传送带速度谁大，从而判断摩擦力方向与运动性质","why":"摩擦力方向由相对运动方向决定，v_B=4 m/s 小于 v_0=5 m/s，物块相对传送带向后滑，摩擦力向前使其加速","do":"比较 v_B 与 v_0 的大小，确定摩擦力方向为运动方向，判断物块做匀加速直到共速","expr":"v_B<v_0\\Rightarrow f=\\mu mg\\ \\text{向前}","cues":["先比速度","物块比带慢","摩擦力向前"],"concepts":["相对运动","滑动摩擦力方向"]},{"title":"摩擦力做功的算法选择","type":"关系建立","judge":"求摩擦力做功是用摩擦力乘对地位移，还是用动能定理间接求","why":"摩擦力是恒力，但物块对地位移需另求；直接用动能定理可避开位移计算，只需初末动能","do":"对B到共速过程列动能定理，摩擦力做功等于动能增量","expr":"W_f=\\frac{1}{2}mv_0^{2}-\\frac{1}{2}mv_B^{2}","cues":["用动能定理","不用算位移","末速是带速"],"concepts":["动能定理","摩擦力做功"]},{"title":"滑痕长度用相对位移","type":"关系建立","judge":"滑痕长度对应物块与传送带的相对位移，而不是物块对地位移","why":"滑痕是物块在带上划过的痕迹，等于两者对地位移之差；误用物块位移会得到错误长度","do":"先由加速度和时间求共速时刻，再算传送带位移与物块位移之差","expr":"\\Delta x=v_0t-\\frac{v_0+v_B}{2}t","cues":["算相对位移","带比物块多走","先求共速时间"],"concepts":["相对位移","匀变速直线运动"]},{"title":"圆弧轨道水平动量守恒","type":"模型选择","judge":"物块与可动圆弧轨道组成的系统在水平方向是否动量守恒","why":"水平面光滑，系统水平方向不受外力，水平动量守恒；竖直方向受重力与地面支持力不守恒","do":"对物块进入圆弧到最高点过程，列水平方向动量守恒式","expr":"mv_0=mv_1+Mv_2","cues":["水平面光滑","取物块和槽整体","只看水平方向"],"concepts":["动量守恒","系统内力"]},{"title":"最高点临界与速度取舍","type":"临界条件","judge":"物块即将离开最高点时轨道对它的压力方向及两解中哪组符合实际","why":"即将离开时物块仍在轨道内侧，轨道对物块的压力向下指向圆心；能量与动量联立得两组解，需用物块相对轨道的速度方向及不穿越轨道筛除不合理解","do":"联立动量守恒与能量方程解出两组(v_1,v_2)，判断物块相对轨道速度应使物块在轨道内侧运动，舍去不合理解，再用向心力求压力","expr":"F+mg=m\\frac{(v_2-v_1)^{2}}{R}","cues":["压力指向圆心","两组解要筛","相对速度是差"],"concepts":["向心力","临界条件","相对速度"]}],"188":[{"title":"接通瞬间无感应电动势","type":"前提判断","judge":"接通 S 的瞬间动子速度为零，是否要计入动子切割磁感线产生的反电动势","why":"动子从静止开始，v=0 时 E=Blv=0，回路中只有电源电压 U 驱动电流","do":"写出接通瞬间回路电流 I₁=U/R₁，再算安培力 F=BI₁l","expr":"I_1=\\frac{U}{R_1},\\quad F=\\frac{BUl}{R_1}","cues":["刚接通速度为零","没有反电动势","只有电源电压"],"concepts":["法拉第电磁感应定律","欧姆定律","安培力"]},{"title":"匀速时安培力与阻力平衡","type":"临界条件","judge":"动子达到最大速度时加速度为零，安培力与速度成正比的阻力大小相等","why":"题设说运动 x_m 时可视为已匀速，匀速即合力为零，这是求 v_m 的唯一方程来源","do":"令 BI₂l=kv_m，其中 I₂=(U−Blv_m)/R₁，解出 v_m","expr":"B\\frac{U-Blv_m}{R_1}l=kv_m","cues":["匀速时合力为零","安培力等于阻力","阻力跟速度成正比"],"concepts":["牛顿第二定律","安培力","收尾速度"]},{"title":"电源总能量含三部分","type":"关系建立","judge":"电源输出的总能量是否只等于动能，还是还要加上阻力做功与回路焦耳热","why":"能量守恒要求电源输出能量分配到动能增量、克服阻力做功和电阻发热三处，漏掉任一项都会算错","do":"用 W=ΔE_k+W_f+Q 列式，其中 Q 用匀速段电流 I₂ 与时间 t=x_m/v_m 计算","expr":"W=\\tfrac12 Mv_m^2+k v_m x_m+I_2^2R_1\\frac{x_m}{v_m}","cues":["能量守恒","还有焦耳热","阻力也耗能"],"concepts":["能量守恒","焦耳热"]},{"title":"楞次定律定超导电流方向","type":"关系建立","judge":"超导线圈产生的磁场方向与第二级回路感应电流的磁场方向之间如何相互制约","why":"磁通量增加时感应电流的磁场要阻碍增加，再由右手螺旋定则反推超导线圈中的电流方向","do":"先由楞次定律定出第二级回路感应电流的磁场方向，再用右手螺旋定则判断超导线圈电流的俯视方向","expr":"","cues":["阻碍磁通量增加","右手螺旋定则","俯视看顺逆时针"],"concepts":["楞次定律","右手螺旋定则","磁通量"]},{"title":"磁场消失时安培力冲量","type":"模型选择","judge":"第二级加速阶段对飞机用动量定理还是用能量关系，安培力冲量如何由磁通量变化表示","why":"磁场快速消失时间极短，安培力是变力，只能用冲量 ∫BI'l dt，而 I'Δt=ΔΦ/R₂ 把冲量化成磁通量","do":"对飞机列动量定理 BI'l·Δt=mv−mv_m，代入 I'Δt=Φ/R₂ 求 v","expr":"BI'l\\Delta t=mv-mv_m,\\quad I'\\Delta t=\\frac{\\Phi}{R_2}","cues":["磁场消失时间极短","安培力是变力","用冲量不用功"],"concepts":["动量定理","安培力","磁通量变化"]},{"title":"飞机与动子动量守恒","type":"模型选择","judge":"解锁飞机瞬间，飞机与剩余动子装备组成的系统在水平方向是否动量守恒","why":"解锁与磁场消失都在极短时间内完成，水平方向外力冲量可忽略，系统总动量守恒","do":"列 (M−m)v'+mv=Mv_m，与飞机的动量定理联立消去 v'","expr":"(M-m)v'+mv=Mv_m","cues":["解锁瞬间","水平方向不受外力","系统动量守恒"],"concepts":["动量守恒定律","内力作用"]}],"189":[{"title":"核反应方程配平","type":"前提判断","judge":"反应产物中除已知的 ²⁸Al 外，另一种粒子是什么，需由质量数和电荷数守恒确定","why":"核反应遵循质量数守恒和电荷数守恒，入射 ²H+²⁷Al 总质量数 29、电荷数 14，产物 ²⁸Al 质量数 28、电荷数 13，差额恰为一个质子","do":"对反应前后分别列质量数与电荷数守恒式，解出未知产物的 A 和 Z","expr":"2+27=28+A,\\quad 1+13=13+Z","cues":["先配质量数","看电荷数守恒","少一个质子"],"concepts":["核反应方程","质量数守恒","电荷数守恒"]},{"title":"由能谱读两种动能","type":"图像读取","judge":"图 2 能谱中两个峰对应的质子动能各是多少，哪一个是基态反应产物","why":"两种质子来自激发态与基态两条反应通道，能谱峰位直接给出动能值，是后续求半径比和能量差的唯一数据来源","do":"读图 2 横轴，取两个峰对应的动能值 3 MeV 与 9 MeV","expr":"E_{k1}=3\\,\\mathrm{MeV},\\quad E_{k2}=9\\,\\mathrm{MeV}","cues":["读两个峰","3和9","看横坐标"],"concepts":["能谱","动能"]},{"title":"磁场中半径与速度关系","type":"关系建立","judge":"质子在圆形磁场中做圆周运动的半径由什么决定，与动能如何换算","why":"洛伦兹力提供向心力，r=mv/(eB)，同一质子 m、e、B 相同，故 r∝v∝√E_k","do":"对两种质子分别写 r=mv/(eB)，用 E_k=mv²/2 把半径比化为动能比的平方根","expr":"r=\\frac{mv}{eB},\\quad r\\propto\\sqrt{E_k}\\Rightarrow r_1:r_2=1:\\sqrt{3}","cues":["洛伦兹力提供向心力","半径比看速度","动能开根号"],"concepts":["洛伦兹力","圆周运动半径","动能"]},{"title":"几何定出射点与半径","type":"几何关系","judge":"质子从水平直径射入、从磁场边界射出后打在 A、D，需判断哪条轨迹对应 A、哪条对应 D，以及 D 点轨迹半径与 R 的关系","why":"探测板与磁场相切于 A、D 在圆心正上方，D 点出射要求轨迹圆心与 O 的几何关系给出 r₂=R；A 点由切线方向与半径垂直给出 tanθ=r₁/R","do":"画两条轨迹，利用出射速度沿探测板方向（与半径垂直）列几何关系，得 r₂=R 与 r₁/R=tanθ","expr":"r_2=R,\\quad \\tan\\theta=\\frac{r_1}{R}","cues":["小半径打A","大半径打D","相切处速度沿板"],"concepts":["几何关系","轨迹圆","切线方向"]},{"title":"间距由两落点合成","type":"数学处理","judge":"A、D 间距应等于 D 到切点 A 的板上距离，需把 θ 与 R 组合成 L","why":"A 为切点、D 在 O 正上方，板上距离 L=R·tanθ，θ 由半径比 1:√3 确定为 30°","do":"由 r₁:r₂=1:√3 及 r₂=R 得 tanθ=1/√3，取 θ=30°，再算 L=Rtan30°","expr":"L=R\\tan30^\\circ=\\frac{\\sqrt{3}}{3}R","cues":["先求角度","再用正切","30度"],"concepts":["几何关系","正切"]},{"title":"功率用电流与单核能量","type":"模型选择","judge":"输出功率应把束流理解为单位时间通过的核数乘单个核动能，而不是用电压电流公式","why":"氘核流 I 对应每秒 n=I/e 个核，每个核带动能 E_k，功率即能量流率","do":"写 n=It/e，P=nE_k/t=IE_k/e，注意把 MeV 换成 eV 后与 e 约去","expr":"P=\\frac{I E_k}{e}=2.74\\times10^{3}\\,\\mathrm{W}","cues":["每秒多少个核","电流除以元电荷","能量乘个数"],"concepts":["电流微观表达式","功率","能量"]},{"title":"能量守恒求衰变能","type":"关系建立","judge":"激发态 ²⁸Al 的激发能等于两条质子通道的动能差，需把它与 β 衰变的静质量能差相加","why":"同一激发态核比基态多出激发能，该能量由两质子动能之差体现；β 衰变释放能还需加上母核与子核加电子的静质量差","do":"用 2.74 MeV 入射动能与 3 MeV 质子动能之差得激发能，再加 Δmc²（母核质量等于子核质量时只剩电子质量项）","expr":"\\Delta E=(2.74-3)+0.51=0.25\\,\\mathrm{MeV}","cues":["激发能是动能差","再加电子质量能","母核子核质量相等"],"concepts":["能量守恒","激发能","质能方程"]}],"190":[{"title":"确定衰变类型","type":"前提判断","judge":"由反应前后质量数不变、电荷数增加 1，判断这是哪种衰变","why":"质量数不变而电荷数改变，只能是 β 衰变；α 衰变会使质量数减少 4，γ 衰变不改变质量数和电荷数","do":"比较反应前后质量数 14 与 14、电荷数 6 与 7 的变化","expr":"A: 14\\to14,\\quad Z: 6\\to7","cues":["质量数没变","电荷数多了一个","不是阿尔法衰变"],"concepts":["β衰变","质量数守恒","电荷数守恒"]},{"title":"用守恒定出粒子","type":"关系建立","judge":"用质量数守恒和电荷数守恒分别列式，求出 X 的质量数和电荷数","why":"核反应方程必须同时满足质量数守恒与电荷数守恒，两个方程才能唯一确定未知粒子的 A 和 Z","do":"设 X 的质量数为 A、电荷数为 Z，对质量数和电荷数各列一个方程并求解","expr":"14=14+A,\\quad 6=7+Z\\Rightarrow A=0,\\ Z=-1","cues":["列两个守恒式","质量数相减","电荷数相减"],"concepts":["核反应方程","质量数守恒","电荷数守恒"]},{"title":"识别粒子本质","type":"结论整理","judge":"由 A=0、Z=-1 判断 X 是电子，并判断它的来源","why":"质量数为 0、电荷数为 -1 的粒子是电子；β 衰变中的电子来自核内中子转变为质子，并非核外电子","do":"把求得的 A、Z 与电子（以及正电子）的符号特征对照，确认 X 为电子并说明其产生机制","expr":"^{0}_{-1}\\mathrm{e}","cues":["是电子","中子变成质子","核内产生的"],"concepts":["电子","β衰变","中子转化为质子"]}],"191":[{"title":"估算高中生质量","type":"前提判断","judge":"需要判断把高中生的质量取为多少千克才合理","why":"题目只给速度不给质量，必须用生活常识补出人质量的数量级，取 50 kg 才能得到与选项同量级的结果","do":"按常识取 m≈50 kg，作为后续计算的输入","expr":"m\\approx 50\\,\\mathrm{kg}","cues":["取五十千克","人的质量约一百斤"],"concepts":["质量估算","数量级"]},{"title":"速度单位换算","type":"数学处理","judge":"判断 144 km/h 要换算成国际单位制才能代入动能式","why":"动能定理中 v 必须以 m/s 为单位，否则结果差 3.6 的平方倍，量级全错","do":"把 144 km/h 除以 3.6 换成 40 m/s","expr":"v=144\\,\\mathrm{km/h}=40\\,\\mathrm{m/s}","cues":["先换成米每秒","除以三点六"],"concepts":["单位换算"]},{"title":"选人作研究对象","type":"模型选择","judge":"判断该对人用动能定理还是对列车用牛顿定律","why":"题目问的是列车对人所做的功，直接对人列动能定理可绕开座椅支持力、摩擦力等内力细节","do":"以高中生为研究对象，只追踪其动能变化","expr":"W=\\Delta E_k","cues":["对人用动能定理","别去算列车牵引力"],"concepts":["动能定理","研究对象选取"]},{"title":"认定功等于动能增量","type":"关系建立","judge":"判断列车对人所做的功是否就等于人动能的增加量","why":"人由静止随车加速，水平方向上只有列车（通过座椅）对人做功，竖直方向重力与支持力不做功，故合功即所求功","do":"写出 W=½mv²−0，把初动能取为零","expr":"W=\\frac{1}{2}mv^{2}-0","cues":["初速为零","合功等于动能增量"],"concepts":["动能定理"]},{"title":"结果取数量级","type":"近似条件","judge":"判断算出的是精确值还是只需保留一位有效数字的数量级","why":"题干问“最接近”，质量本身是估的，结果只能给量级，不能当精确值去挑差很小的选项","do":"代入 50 kg 与 40 m/s 算得约 4×10⁴ J，按数量级匹配选项","expr":"W\\approx\\frac{1}{2}\\times 50\\times 40^{2}\\approx 4\\times10^{4}\\,\\mathrm{J}","cues":["只要数量级","四万焦左右"],"concepts":["数量级估算","有效数字"]}],"192":[{"title":"两鸟食竖直位移比较","type":"几何关系","judge":"要判断从抛出点 O 到 M、N 两点的竖直下落高度哪个更小","why":"平抛竖直方向为自由落体，下落高度直接由图中的几何位置决定，是后续比较时间的前提","do":"在图上比较 O 到 M 与 O 到 N 的竖直距离","expr":"h_M < h_N","cues":["看竖直高度","M点更高","下落得少"],"concepts":["平抛运动","自由落体"]},{"title":"由高度定飞行时间","type":"关系建立","judge":"要判断竖直高度与飞行时间的对应关系，从而比较两鸟食的飞行时间","why":"平抛竖直分运动满足 h=gt²/2，高度唯一决定时间，与水平初速度无关","do":"由 h=gt²/2 比较 t_M 与 t_N","expr":"h=\\frac{1}{2}gt^{2}\\Rightarrow t_M<t_N","cues":["高度定时间","竖直方向算时间","时间只由高度决定"],"concepts":["平抛运动","运动的分解"]},{"title":"同时接到推抛出先后","type":"前提判断","judge":"要判断两鸟食同时被接到时，飞行时间长的那个是先抛出还是后抛出","why":"同时到达意味着抛出时刻不同，飞行时间越长，必须越早抛出","do":"由 t_M<t_N 且同时接到，比较两鸟食的抛出先后","expr":"t_N>t_M\\Rightarrow N 点鸟食先抛出","cues":["同时接到","先抛后抛","时间长的先抛"],"concepts":["平抛运动","时间关系"]},{"title":"同高度比水平位移","type":"几何关系","judge":"要判断在相同竖直高度处，M 轨迹与 N 轨迹的水平位移哪个更大","why":"初速度只能通过水平位移与时间共同体现，需在同一高度（同一时间）下比较水平位移","do":"过 M 作水平面，与 N 轨迹相交，比较该高度处两轨迹的水平位移","expr":"x_M>x_N（同一高度处）","cues":["作水平面","同一高度比水平","看谁飞得远"],"concepts":["平抛运动","水平位移"]},{"title":"由位移时间定初速度","type":"关系建立","judge":"要判断水平位移与飞行时间共同决定初速度时，M、N 两鸟食初速度的大小关系","why":"平抛水平方向为匀速直线运动，x=v₀t，同一高度处时间相同，水平位移大者初速度大","do":"用 x=v₀t 在同一高度（同 t）下比较 v₀","expr":"x=v_0t\\Rightarrow v_{0M}>v_{0N}","cues":["水平方向匀速","位移大速度大","同时间比位移"],"concepts":["平抛运动","匀速直线运动"]}],"193":[{"title":"等势线疏密定场强","type":"图像读取","judge":"要判断等势线的疏密程度与电场强度大小的对应关系，并比较 a、b、c、d 四点的疏密","why":"等势线越密处电场强度越大，这是由 E=U/d 决定的；只看电势高低无法判断场强大小","do":"观察图中四点附近等势线的间距，找出等势线最密集的点","expr":"E\\approx\\frac{U}{d}","cues":["看疏密","越密场强越大","比间距"],"concepts":["等势线","电场强度"]},{"title":"电势差与路径无关","type":"关系建立","judge":"要判断电场力做功只由初末位置的电势差决定，与移动路径无关","why":"静电场是保守场，电场力做功等于电荷量与电势差的乘积的负值","do":"用 W=qU 直接由两点电势求功，不必关心电子沿什么路径移动","expr":"W_{AB}=qU_{AB}=q(\\varphi_A-\\varphi_B)","cues":["只看首末位置","与路径无关","用两点电势差"],"concepts":["电势差","电场力做功","保守场"]},{"title":"电子电荷取负号","type":"前提判断","judge":"要判断电子带负电，代入 W=qU 时 q 取负值，从而确定电场力做正功还是负功","why":"电子电荷量为 -e，符号直接决定功的正负，漏掉负号会把做功方向判反","do":"把 q=-e 代入 W=qU，先算 U 的正负再定 W 的正负","expr":"W=-e\\,(\\varphi_{\\text{初}}-\\varphi_{\\text{末}})","cues":["电子带负电","别漏负号","先看电势差正负"],"concepts":["元电荷","电场力做功"]},{"title":"电场力做功与电势能","type":"关系建立","judge":"要判断电场力做正功时电势能减小、做负功时电势能增大","why":"电场力做功等于电势能减少量，二者符号相反，混淆会把增减说反","do":"由算出的 W 的正负推出电势能变化量的正负","expr":"\\Delta E_p=-W","cues":["做正功电势能减小","功和能反号","看功的正负"],"concepts":["电势能","电场力做功"]}],"194":[{"title":"选定中心天体与定律","type":"模型选择","judge":"判断该用哪条规律把周期和轨道半径联系起来","why":"小行星与八大行星都绕太阳运行，中心天体相同，才能用开普勒第三定律的同一个比值","do":"确认环绕中心都是太阳，写出开普勒第三定律的比值式","expr":"\\frac{r^3}{T^2}=k","cues":["绕同一个太阳","用开普勒第三定律"],"concepts":["开普勒第三定律","中心天体"]},{"title":"统一单位取地球为基准","type":"前提判断","judge":"判断公式中的 k 和 T 用什么单位、以谁为参照","why":"题给地球轨道半径为 1 AU、周期 1 年，取地球为基准可使 k 的数值直接为 1，避免换算成年与 AU 之外的量","do":"把地球的 r=1 AU、T=1 年代入比值式，确定 k 的数值","expr":"k=\\frac{(1\\,\\mathrm{AU})^3}{(1\\,\\mathrm{年})^2}=1","cues":["以地球为参照","取1年1AU"],"concepts":["单位制","参照基准"]},{"title":"由周期反求轨道半径","type":"关系建立","judge":"判断已知周期时如何反解出半径，而不是直接比较周期","why":"开普勒第三定律联系的是 r³ 与 T²，必须开立方才能得到半径，不能把周期比直接当半径比","do":"把 T=5.8 年代入比值式，解出 r³ 再开立方","expr":"r=\\sqrt[3]{T^2}=\\sqrt[3]{5.8^2}\\approx 3.2\\,\\mathrm{AU}","cues":["先算周期的平方","再开三次方"],"concepts":["开普勒第三定律","立方根"]},{"title":"与表中半径比较定区间","type":"结论整理","judge":"判断算出的半径落在表中哪两个相邻行星的轨道半径之间","why":"表中给出各行星半径，只有把 3.2 AU 与相邻两行数值比较，才能确定小行星位于哪两颗行星轨道之间","do":"将 3.2 AU 与火星 1.5 AU、木星 5.2 AU 比较，确认介于二者之间","expr":"1.5\\,\\mathrm{AU}<3.2\\,\\mathrm{AU}<5.2\\,\\mathrm{AU}","cues":["比火星大","比木星小"],"concepts":["轨道半径比较","区间判断"]}],"195":[{"title":"位移与MN段位置无关","type":"关系建立","judge":"总位移是否依赖滑块初始位置与MN段的相对距离","why":"全程只有MN段和其余段两段摩擦做功，初末动能相同，能量守恒中MN段长度固定，故总位移只由v0和两个摩擦因数决定","do":"对两次运动分别写全程动能定理，比较两式中除总位移外各项是否相同","expr":"\\frac12 mv_0^2=\\mu_1 mg x_{MN}+\\mu_2 mg(x-x_{MN})","cues":["用能量守恒","全程列式","MN段长度一样"],"concepts":["动能定理","摩擦力做功"]},{"title":"分段加速度大小比较","type":"前提判断","judge":"滑块在MN段和其余段上加速度哪个大","why":"滑动摩擦力提供合外力，a=μg，加速度大小由该段动摩擦因数决定","do":"由牛顿第二定律写出每段的加速度，比较μ1与μ2","expr":"a=\\mu g","cues":["先看加速度","摩擦因数大的加速度大","分两段看"],"concepts":["牛顿第二定律","滑动摩擦力"]},{"title":"到M点速度的比较","type":"关系建立","judge":"第二次从更靠近M的位置出发，到达M点时速度比第一次大还是小","why":"在MN段之前的其余段上加速度相同、初速相同，滑行距离越短末速越大","do":"对M点之前的运动用速度位移公式，比较两次在μ2段上走过的距离","expr":"v_0^2-v_M^2=2\\mu_2 g s","cues":["离M近的先到","距离短速度大","用速度位移公式"],"concepts":["匀变速直线运动","速度位移关系"]},{"title":"用v-t图面积定时间","type":"图像读取","judge":"两次总位移相同（v-t图线下面积相等）时，哪次用时更短","why":"总位移相等即图线与横轴围成的面积相等，而两次的初速、末速和分段加速度结构不同，需比较图线形状","do":"画出两次的v-t图：第二次在μ2段速度较高、在μ1段停留的图线位置更高，在面积相同条件下比较横轴跨度","expr":"x=\\int v\\,dt","cues":["画速度时间图","面积一样比宽度","第二次速度整体偏高"],"concepts":["v-t图像面积","匀变速运动"]}],"196":[{"title":"读图定波长","type":"图像读取","judge":"从实线或虚线波形上读出相邻同相点间距，确定波长","why":"简谐横波在均匀介质中波长由波形图直接给出，是求周期和波速的前提","do":"在实线（或虚线）上找相邻波峰到波峰（或平衡位置同向过零点）的水平距离","expr":"\\lambda = 4\\,\\mathrm{m}","cues":["看相邻波峰","量一个完整波形"],"concepts":["波长","波形图"]},{"title":"用两时刻波形定周期","type":"关系建立","judge":"判断实线与虚线之间是半个周期的平移还是整数个周期加半周期","why":"同一列波两时刻波形反相，说明时间间隔等于半周期的奇数倍，取最小正周期","do":"比较实线与虚线同一位置的振动方向，确认波形反相后令时间差等于半周期","expr":"\\frac{T}{2}=2.5-1.5\\,\\mathrm{s}\\Rightarrow T=2\\,\\mathrm{s},\\ v=\\frac{\\lambda}{T}=2\\,\\mathrm{m/s}","cues":["波形反了","差半个周期"],"concepts":["周期","波速"]},{"title":"由波前位置反推波源","type":"模型选择","judge":"把波源到 P 的距离设为未知量，用左侧波前已传到 P 外 2 m 这一几何条件反推波源位置","why":"波源位置未知，但波前到 P 的距离等于波源到 P 的距离加上波已传播的距离，这是唯一能定出波源位置的约束","do":"对左侧实线波形读出波前在 P 外侧 2 m 处，列出波源到 P 距离与传播时间的关系","expr":"\\frac{x_0+2}{v}=1.5\\,\\mathrm{s}\\Rightarrow x_0=1\\,\\mathrm{m}","cues":["波前到P多远","设波源到P为x"],"concepts":["波前","波传播距离"]},{"title":"由波前振动方向定起振方向","type":"前提判断","judge":"由波前处质点的振动方向判断波源起振方向","why":"介质中每个质点起振方向都与波源起振方向相同，波前处质点的运动方向就是起振方向","do":"在实线波形波前处用同侧法（或上下坡法）判断该质点速度方向","expr":"","cues":["看波前那一点","同侧法"],"concepts":["起振方向"]},{"title":"算两质点已振动时间","type":"关系建立","judge":"分别算出波传到 P、Q 的时刻，再求 5.5 s 时各自已振动的时间是周期的多少","why":"质点某时刻的位移和运动方向只取决于它已振动的时间与周期的比值，与波源距离无关","do":"用 x0、x1 除以波速得传到时刻，再用 5.5 s 减去传到时刻","expr":"t_0'=5.5-0.5=2.5T,\\quad t_1'=5.5-1.5=2T","cues":["先算传到时刻","看振动了几个周期"],"concepts":["波的传播时间","振动时间"]},{"title":"按起振方向定相位","type":"临界条件","judge":"由起振方向向下，结合已振动时间为整数或半整数周期，判断两质点此刻的位置与速度方向","why":"已振动整数个周期回到平衡位置且速度与起振方向相同，半整数周期回到平衡位置但速度与起振方向相反","do":"对 P 取 2.5T、对 Q 取 2T，分别按起振向下推出此刻速度方向，再比较位移","expr":"","cues":["整数周期同起振","半周期反向"],"concepts":["简谐振动周期性","相位"]}],"197":[{"title":"理想变压器电压比规律","type":"前提判断","judge":"是否可用匝数比等于电压比来求原、副线圈匝数比","why":"变压器视为理想变压器，无漏磁、无铜损铁损，每匝电压相同，故任意两线圈的电压比等于匝数比","do":"对原线圈与每个副线圈分别写出电压比等于匝数比，算出两个匝数比","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2},\\quad \\frac{n_1}{n_3}=\\frac{U_1}{U_3}","cues":["理想变压器","匝数比等于电压比","每匝电压相同"],"concepts":["理想变压器","匝数比","电压比"]},{"title":"多副线圈功率守恒","type":"关系建立","judge":"输入功率应等于各副线圈输出功率之和，而不是等于某一个副线圈的功率","why":"理想变压器无能量损耗，由能量守恒，输入功率等于全部副线圈输出功率之和","do":"把两副线圈的输出功率相加，得到输入功率","expr":"P_1=P_2+P_3","cues":["能量守恒","输入等于输出总和","两个副线圈都要算"],"concepts":["能量守恒","输入功率","输出功率"]},{"title":"区分有效值与最大值","type":"前提判断","judge":"题给的 220 V 是有效值还是最大值，求最大值时是否需乘根号二","why":"交流电表的示值、铭牌电压均指有效值，最大值与有效值满足根号二倍关系","do":"把 220 V 当作有效值，乘根号二得最大值，再与选项所给数值比较","expr":"U_m=\\sqrt{2}\\,U","cues":["220是有效值","最大值要乘根号二","示数都是有效值"],"concepts":["有效值","最大值","正弦交流电"]}],"198":[{"title":"气体做等容变化","type":"模型选择","judge":"b 管体积相对 a 泡可忽略时，a 内气体在温度变化中体积是否保持不变","why":"题设明确 b 管体积与 a 泡相比可忽略，液面升降引起的气体体积变化可忽略，故只能按等容过程处理","do":"确认气体体积不变，选定查理定律作为温度—压强关系","expr":"p/T = C","cues":["体积不变","忽略细管","等容变化"],"concepts":["等容变化","查理定律","理想气体"]},{"title":"压强与液柱的平衡","type":"关系建立","judge":"a 内气体压强与 b 管内外液面高度差之间满足什么定量关系","why":"b 管液面与槽面存在高度差，液柱静压强参与平衡，气体压强不等于大气压","do":"对 b 管液面列压强平衡式，把气体压强表示为大气压与液柱压强之差","expr":"p_a + \\rho g h = p_0","cues":["液柱压强","高度差","压强平衡"],"concepts":["压强平衡","液体静压强"]},{"title":"温度升高液面下降","type":"关系建立","judge":"温度升高时气体压强如何变、液柱高度差随之如何变，从而液面往哪个方向移动","why":"等容下压强随温度升高而增大，而气体压强与液柱高度差之和恒等于大气压，故高度差必须减小","do":"由查理定律判断压强增大，再由压强平衡式判断 h 减小，得出管内液面下降","expr":"T\\uparrow \\Rightarrow p_a\\uparrow \\Rightarrow h\\downarrow","cues":["温度高压强大","液面下降","高度差变小"],"concepts":["查理定律","压强平衡"]},{"title":"刻度方向与温度对应","type":"结论整理","judge":"b 管刻度从上到下对应温度升高还是降低","why":"温度越高管内液面越低，故低温刻度在上、高温刻度在下，刻度方向不能弄反","do":"把液面高度与温度一一对应，确定刻度上端为低温、下端为高温","expr":"","cues":["上冷下热","刻度反着标","液面越低越热"],"concepts":["温度刻度","等容测温"]},{"title":"水蒸发致测量值偏大","type":"误差分析","judge":"槽中水少量蒸发后，同一环境温度下管内液面位置如何偏移，读数偏大还是偏小","why":"水蒸发使槽面下降，而同一温度下气体压强不变、高度差 h 不变，管内液面随槽面同步下降，落在更低（更高温度）的刻度处","do":"固定温度对应同一 h，比较槽面下降前后管内液面所对刻度，判断读数偏向高温","expr":"h\\ \\text{不变},\\ \\text{槽面下降}\\Rightarrow\\text{管内液面下降}","cues":["槽面下降","液面跟着降","读数偏大"],"concepts":["系统误差","高度差不变"]}],"199":[{"title":"用过程Ⅰ定PO距离","type":"关系建立","judge":"过程Ⅰ中滑块从P到O做匀减速运动，能否用动能定理把PO距离L与v0、θ、μ联系起来","why":"过程Ⅰ只有重力沿斜面分量和滑动摩擦力做负功，且μ=tanθ使两力大小相等，这是全题唯一能确定L的信息来源","do":"对过程Ⅰ从P到O列动能定理，把L用v0、g、θ表示","expr":"-mg\\sin\\theta\\cdot L-\\mu mg\\cos\\theta\\cdot L=0-\\tfrac12 mv_0^2","cues":["先求PO距离","用动能定理","两力大小相等"],"concepts":["动能定理","滑动摩擦力","斜面倾角"]},{"title":"μ=tanθ的等效含义","type":"前提判断","judge":"μ=tanθ意味着重力沿斜面分量与滑动摩擦力大小相等，这对上滑、下滑、静止各意味着什么","why":"μ=tanθ使mgsinθ=μmgcosθ，上滑时两力同向、合力为2mgsinθ，下滑时两力反向、合力为零，是判断平衡位置和能否静止的关键","do":"比较mgsinθ与μmgcosθ的大小，写出上滑合力和下滑合力","expr":"mg\\sin\\theta=\\mu mg\\cos\\theta","cues":["摩擦力和重力分量相等","上滑合力翻倍","下滑合力为零"],"concepts":["最大静摩擦力","平衡条件","等效重力"]},{"title":"速度最大处的平衡位置","type":"临界条件","judge":"过程Ⅱ中速度最大时加速度为零，此时弹簧弹力应等于哪些力之和","why":"速度最大对应加速度为零，此时弹簧仍被压缩、弹力沿斜面向上，需平衡重力分量与摩擦力（上滑时摩擦力向下）","do":"在M点列沿斜面方向的力平衡方程，求出MO距离L1","expr":"kL_1=mg\\sin\\theta+\\mu mg\\cos\\theta","cues":["速度最大加速度为零","弹力等于下滑力加摩擦","先找平衡点"],"concepts":["牛顿第二定律","弹簧弹力","平衡位置"]},{"title":"PM距离的几何拼接","type":"几何关系","judge":"M在O点下方，PM应等于PO减去MO还是加上MO","why":"M是速度最大点，位于O点下方（弹簧已压缩），故PM=PO-MO，符号搞反会得到错误表达式","do":"用L和L1表示PM距离L2，再代入前两步结果","expr":"L_2=L-L_1","cues":["M在O下方","用PO减MO","画图定位置"],"concepts":["几何关系","位移叠加"]},{"title":"过程Ⅱ的机械能损失","type":"关系建立","judge":"从P到O单向运动过程中，损失的机械能是否只等于克服摩擦力做的功","why":"弹簧在P、O两处形变量相同（P处为原长拉伸L，O处为原长），弹性势能变化为零，机械能损失仅由摩擦生热决定","do":"写出ΔE=μmgcosθ·L，再用过程Ⅰ的动能定理结果代换","expr":"\\Delta E=\\mu mg\\cos\\theta\\cdot L=\\tfrac14 mv_0^2","cues":["只看摩擦生热","两端弹簧形变一样","弹性势能没变"],"concepts":["功能关系","摩擦生热","弹性势能"]},{"title":"最大位移用能量守恒","type":"关系建立","judge":"求过程Ⅱ最大上滑位移时，初末状态弹性势能是否相同，能否直接用能量守恒","why":"最高点速度为零但弹簧形变量为x-L，与初态形变量L不同，必须同时计入重力势能、摩擦热和末态弹性势能","do":"从P到最高点列能量守恒，解出x","expr":"\\tfrac12 kL^2=mg\\sin\\theta\\cdot x+\\mu mg\\cos\\theta\\cdot x+\\tfrac12 k(x-L)^2","cues":["最高点速度为零","弹簧还压着","能量守恒列全"],"concepts":["能量守恒","弹性势能","摩擦生热"]}],"200":[{"title":"测摩擦力的原理","type":"模型选择","judge":"要判断测力计示数 F 是否等于木板对滑块的滑动摩擦力","why":"滑块静止、木板被电机匀速拉动，滑块受绳拉力与摩擦力平衡，二力大小相等","do":"对滑块（含砝码）受力分析，确认水平方向只有绳拉力和滑动摩擦力，且滑块始终静止","expr":"F=f=\\mu F_N","cues":["滑块不动","二力平衡","读数就是摩擦力"],"concepts":["二力平衡","滑动摩擦力"]},{"title":"正压力取谁的重力","type":"关系建立","judge":"要判断接触面间的正压力由滑块和砝码的总重力提供，而不是木板重力或绳拉力","why":"滑块在竖直方向无加速度，支持力与总重力平衡，与木板如何运动无关","do":"写出正压力表达式，用总质量 M 乘 g，把表格中 M 换算成千克","expr":"F_N=Mg","cues":["用总质量","别忘了砝码","竖直方向平衡"],"concepts":["正压力","重力"]},{"title":"a 处按定义式算","type":"数据处理","judge":"要判断 a 是用该行的 F 与该行 M 对应的正压力直接相除得到，不能拿别的行数据或平均值代","why":"动摩擦因数由该次接触状态下的 f 与 F_N 之比定义，每行数据独立成立","do":"取 M=300 g 一行，把 M 换算为 0.300 kg，算 Mg 后与 1.35 N 相除，保留 3 位有效数字","expr":"\\mu=\\frac{1.35}{0.300\\times9.80}","cues":["用本行数据","先算正压力","保留三位"],"concepts":["动摩擦因数","有效数字"]},{"title":"由数据列看规律","type":"结论整理","judge":"要判断比较的是各行的 f 与 F_N 是否同比例变化、以及各行 μ 是否近似相等，而不是比较 F 与 M 的差值","why":"表格已给出每行 μ，若 μ 基本不变则 f 与 F_N 成正比、μ 与压力无关","do":"横向比较四行 μ 值是否在误差范围内相同，再回看 F 随 M 增大的比例","expr":"\\mu=\\frac{f}{F_N}=\\text{常量}","cues":["看μ变不变","F随M变大","成正比"],"concepts":["正比关系","控制变量"]},{"title":"细线不平行的影响","type":"误差分析","judge":"要判断挂钩高于滑轮时绳拉力出现竖直分力，使真实正压力大于 Mg，而计算时仍用 Mg","why":"竖直方向平衡变为 F_N+T sinθ=Mg，实际正压力减小还是增大取决于绳拉力的竖直分量方向，此处拉力斜向上拉滑块，竖直分量向上，故真实正压力小于 Mg，而计算时代入的偏大","do":"对滑块列竖直方向平衡式，比较真实正压力与 Mg 的大小，再代入 μ=F/Mg 判断测量值偏大还是偏小","expr":"F_N=Mg-T\\sin\\theta<Mg,\\quad \\mu_{\\text{测}}=\\frac{F}{Mg}<\\frac{F}{F_N}=\\mu_{\\text{实}}","cues":["绳子斜了","有竖直分力","正压力算大了"],"concepts":["力的分解","系统误差"]}],"201":[{"title":"读图求温度系数","type":"图像读取","judge":"由图(a)读出 0 ℃ 和 100 ℃ 对应的铂电阻阻值，判断阻值随温度的变化率","why":"题目说明 R_t 随 t 线性变化，故斜率即为每升高 1 ℃ 的阻值增量，是后续由阻值反推温度的依据","do":"读出图线两端点纵坐标，用 ΔR/Δt 求斜率","expr":"k=\\frac{R_{100}-R_0}{100}","cues":["读两端点","求斜率","线性变化"],"concepts":["线性关系","图像斜率","电阻温度特性"]},{"title":"选电流表接法","type":"模型选择","judge":"判断甲、乙两图中哪种接法能消除电表内阻带来的系统误差","why":"A₁ 内阻已知（4.5 kΩ）而 A₂ 内阻未知，只有把 A₁ 与待测电阻并联、用 A₁ 读数算电压、用两表读数之差算电流，才能准确求出 R_t","do":"比较甲、乙中 A₁ 是串联还是并联在 R_t 两端，判断哪个电路能同时得到 R_t 的电压和电流","expr":"R_t=\\frac{I_1R_{A1}}{I_2-I_1}","cues":["内阻已知的表测电压","两表示数之差","并联取电压"],"concepts":["伏安法测电阻","电表内阻","系统误差"]},{"title":"保护电阻按电流上限选","type":"临界条件","judge":"判断保护电阻应使电路电流不超过铂电阻允许的最大工作电流 0.3 mA","why":"铂电阻工作电流须在 0.1~0.3 mA 之间，电流过大将损坏或使测量偏离；电源电动势 5 V 固定，最小总电阻由最大允许电流决定","do":"用最大电流 0.3 mA 和电源电动势求电路最小总电阻，再与 R₁、R₂ 的阻值比较取舍","expr":"R_{\\min}=\\frac{E}{I_{\\max}}=\\frac{5}{0.3\\times10^{-3}}\\approx17\\,\\mathrm{k}\\Omega","cues":["电流不能超上限","算最小总电阻","选大阻值"],"concepts":["闭合电路欧姆定律","工作电流范围","保护电阻"]},{"title":"电流表读数与量程","type":"实验操作","judge":"判断图(c)中 A₁ 应读到哪一位、分度值是多少","why":"A₁ 量程 100 μA，读数需按表盘分度值估读，读数精度直接决定温度计算结果的有效数字","do":"确认 A₁ 表盘分度值，按指针位置读出并保留到估读位","expr":"","cues":["看分度值","估读一位","量程一百微安"],"concepts":["电流表读数","估读","有效数字"]},{"title":"由阻值反推温度","type":"关系建立","judge":"判断如何把测得的 R_t 与温度 t 对应起来","why":"图(a)给出 R_t 与 t 的线性关系，需先写出 R_t=R₀+kt 的表达式，再把测量算出的阻值代入解温度","do":"用第(1)问的斜率写出 R_t 与 t 的关系式，代入由两表示数算出的 R_t 求 t","expr":"R_t=R_0+kt,\\quad t=\\frac{R_t-R_0}{k}","cues":["先写关系式","再代阻值","反解温度"],"concepts":["线性关系","函数反解","电阻测温"]}],"202":[{"title":"全反射临界角","type":"临界条件","judge":"判断未滴油时盖玻片上表面能透光的最边缘光线对应的入射角是否恰为临界角","why":"光从盖玻片（n=1.5）射向空气（n=1）是由光密到光疏，入射角超过临界角即全反射，透光区边界由临界角决定","do":"用临界角公式求 sinC，作为透光圆边缘光线的入射角","expr":"\\sin C=\\frac{1}{n}=\\frac{2}{3}","cues":["由光密到光疏","临界角","刚好全反射"],"concepts":["全反射","临界角","折射率"]},{"title":"临界角对应半径","type":"几何关系","judge":"判断点光源 O 到上表面透光圆边缘的光线与法线夹角如何用厚度 d 和半径 r 表示","why":"O 在盖玻片底部中心，光线沿直线到达上表面，入射角就是该光线与竖直法线的夹角，由直角三角形联系 r 与 d","do":"在 O 到边缘点的直角三角形中写出正弦关系，解出 r","expr":"\\sin C=\\frac{r}{\\sqrt{r^{2}+d^{2}}}","cues":["画直角三角形","厚度是竖直边","半径是水平边"],"concepts":["几何关系","光路图"]},{"title":"透光面积换算","type":"数学处理","judge":"判断透光区是圆面并统一单位后保留两位有效数字","why":"临界角以内全部透光，边界为圆，面积由半径平方乘 π 得到；d 用 mm 需换成 m","do":"由 r 求 S=πr²，把 mm 换算成 m 后取两位有效数字","expr":"S=\\pi r^{2}","cues":["透光是个圆","毫米换米","保留两位"],"concepts":["圆面积","有效数字","单位换算"]},{"title":"最短时间取垂直路径","type":"模型选择","judge":"判断光从 O 到物镜传播时间最短对应哪条路径","why":"各段路程一定时，光在介质中速度小于真空速度，应让光在低速介质中走的路程最短，即沿垂直于界面的直线传播","do":"取沿竖直方向（垂直盖玻片上表面）的光线计算时间","expr":"","cues":["走直线最短","垂直入射","少走慢介质"],"concepts":["光速与介质","直线传播"]},{"title":"分段求时间","type":"关系建立","judge":"判断滴油前后光经过的两段介质分别是什么、各段速度取 c 还是 c/n","why":"未滴油时盖玻片内为玻璃（v=c/n）、间隙为空气（v=c）；滴油后间隙也被油填充（v=c/n），两段速度不同需分段相加","do":"分别写出 t₁ 与 t₂ 的分段表达式，再作差","expr":"t_1=\\frac{nd+h}{c},\\quad t_2=\\frac{n(d+h)}{c}","cues":["分两段算","油和玻璃折射率一样","空气段用光速"],"concepts":["光在介质中的速度","分段求和"]},{"title":"作差消去厚度","type":"数学处理","judge":"判断作差后哪些项相消、只剩与 h 有关的项","why":"两式中 nd/c 相同，相减后 d 项抵消，差值只由间隙段介质改变引起","do":"t₂−t₁ 化简后代入 n、h、c 求值并保留两位有效数字","expr":"t_2-t_1=\\frac{(n-1)h}{c}","cues":["厚度项抵消","只剩间隙","代数据"],"concepts":["代数化简","有效数字"]}],"203":[{"title":"速度选择器受力平衡","type":"模型选择","judge":"粒子在速度选择器中做匀速直线运动，需判断电场力与洛伦兹力等大反向","why":"速度选择器只让特定速率的粒子无偏转通过，合力为零是唯一能确定速率的条件","do":"对粒子在极板间列电场力与洛伦兹力平衡方程，并用 E=U/d 代入","expr":"qv_0B_0=q\\frac{U}{d}","cues":["电场力和洛伦兹力抵消","合力为零","匀速直线通过"],"concepts":["速度选择器","电场力","洛伦兹力"]},{"title":"由入射几何定半径","type":"几何关系","judge":"粒子从 ON 中点垂直 ON 射入屏蔽区，需判断它在 x≥0 区域内的圆心位置和轨迹半径","why":"垂直边界射入意味着圆心在入射点所在边界线上，结合粒子从 y 轴垂直射入的入射方向才能定出半径","do":"画出粒子在 x≥0 区域的圆弧轨迹，利用垂直 ON 射入与垂直 y 轴射入两个方向条件，找出圆心并读出半径","expr":"r_1=L","cues":["垂直边界射入","圆心在ON上","半径就是半个边长"],"concepts":["匀速圆周运动","几何关系","圆心定位"]},{"title":"B2 小于 B1 判半径变大","type":"前提判断","judge":"由 0<B2<B1 判断粒子在屏蔽区内轨迹半径 r2 与 L 的大小关系，进而判断粒子能否穿出屏蔽区","why":"同一速率下半径与磁感应强度成反比，B2 更小则半径更大，这决定了粒子在屏蔽区内的运动形态和出射位置","do":"写出 r2 与 B2 的反比关系，与 r1=L 比较，得出 r2>L，再讨论 B2→0 的极限情形确定出射方向","expr":"r_2=\\frac{mv_0}{qB_2}>\\frac{mv_0}{qB_1}=L","cues":["磁场弱半径大","半径比L大","会穿出屏蔽区"],"concepts":["洛伦兹力提供向心力","半径与磁感应强度反比"]},{"title":"出屏蔽区后重入 B1 定落点","type":"临界条件","judge":"粒子离开屏蔽区进入 x≥0 的 B1 区域后，需判断其偏转方向及打在 y 轴上的位置，并取 B2 的极限求范围端点","why":"y 轴上能检测到的范围由 B2 可取值的两个极端决定，B2→0 时粒子直线穿出屏蔽区，是范围的一个端点","do":"取 B2=0 的极限，画出粒子在屏蔽区内直线运动、出区后在 B1 中偏转的轨迹，用左手定则判偏转方向，再由半径 L 求与 y 轴交点","expr":"r_3=r_1=L,\\quad y_{\\max}=3L","cues":["取B2等于零","出区后向左偏","半径还是L"],"concepts":["左手定则","匀速圆周运动","极限法"]},{"title":"Q 点落点反推 r2","type":"几何关系","judge":"粒子经屏蔽区偏转后恰好过 Q 点，需判断圆心位置并建立 r2 与正方形边长的几何方程","why":"Q 是正方形顶点，粒子轨迹圆弧过 Q 且与入射点、入射方向相切，只有用弦长与半径的直角三角形关系才能解出 r2","do":"以入射点为切点作半径垂线定圆心，连接圆心与 Q，用勾股定理列方程解 r2","expr":"r_2^2=(2L)^2+(r_2-L)^2","cues":["过Q点作圆","圆心在入射点垂线上","勾股定理列方程"],"concepts":["几何关系","勾股定理","圆周轨迹"]},{"title":"由 r2 反求 B2 与效率","type":"关系建立","judge":"把几何得到的 r2 与 B2 的动力学表达式、以及 B1 的表达式联立，代入效率定义求 η","why":"效率定义中同时含 B1 与 B2，必须先用同一速率把两者都表示成已知量，才能约去公共因子得到纯数值","do":"由 r2 求 B2，与 B1 表达式作比，代入 η 定义化简","expr":"\\eta=\\frac{B_1-B_2}{B_1}\\times100\\%","cues":["先求B2再求比值","公共因子约掉","代入效率定义"],"concepts":["洛伦兹力提供向心力","磁屏蔽效率","联立消元"]}],"204":[{"title":"木块与箱相对静止的临界","type":"临界条件","judge":"木块与箱子恰好相对静止时，靠什么力提供水平加速度、这个力取到什么极限值","why":"木块水平方向只受箱壁的弹力，竖直方向受重力和摩擦力；相对静止要求静摩擦力不超过最大静摩擦力，而最大静摩擦力等于 μ 倍正压力","do":"对木块分别列水平方向牛顿第二定律和竖直方向平衡，令摩擦力取最大值 μF_N，与整体加速度联立","expr":"F_N=ma,\\quad \\mu F_N=mg","cues":["恰好不滑","摩擦力取最大","竖直方向平衡"],"concepts":["最大静摩擦力","牛顿第二定律","整体法"]},{"title":"分离条件由安培力与F比较","type":"前提判断","judge":"箱子右侧壁进入磁场瞬间木块与箱子分离，说明此时水平方向的加速度关系发生了什么变化","why":"分离的物理本质是箱子加速度被安培力减小到小于木块能获得的最大加速度，即箱子所受合外力被安培力抵消到 F_安 ≥ F 的程度","do":"写出进入磁场瞬间的安培力表达式，与第（1）问求得的 F 比较，取临界 F_安=F 求最小速度","expr":"F_{\\text{安}}=\\frac{B^2d^2v}{R}\\ge F","cues":["安培力把箱子拽住","加速度变小才分离","临界取等号"],"concepts":["安培力","分离条件","临界状态"]},{"title":"用运动学把速度换成距离","type":"关系建立","judge":"进入磁场前的速度 v 与初始距离 s 之间用哪个运动学关系联系","why":"箱子在恒力下由静止做匀加速直线运动，加速度由第（1）问给出，速度与位移满足 v²=2as","do":"由 F=(M+m)a 求 a，代入 v²=2as，把第（2）问的速度临界值翻译成距离临界值","expr":"v^2=2as,\\quad a=\\frac{F}{M+m}=\\frac{g}{\\mu}","cues":["匀加速从静止","速度平方关系","把速度换成距离"],"concepts":["匀变速直线运动","加速度"]},{"title":"分离后木块做平抛的时间","type":"模型选择","judge":"木块与箱子分离后，竖直方向做什么运动、水平方向还要不要考虑箱壁的力","why":"分离后木块在竖直方向只受重力，做自由落体；水平方向不再受箱壁弹力，与箱子无水平相互作用，故下落时间只由 h 决定","do":"对木块竖直方向列自由落体方程求 t₂，并明确这段时间内木块水平速度保持不变","expr":"h=\\frac{1}{2}gt_2^2","cues":["分离后只受重力","竖直自由落体","水平不再受力"],"concepts":["自由落体","平抛运动","运动的独立性"]},{"title":"安培力冲量只与位移有关","type":"数学处理","judge":"对系统用动量定理时，安培力的冲量能否直接写成与速度无关的表达式","why":"安培力 F_安=B²d²v/R 正比于速度，对时间积分时 vΔt 就是位移，箱子完全进入磁场过程中切割磁感线的有效位移恰为 L，故冲量只由 L 决定","do":"把安培力对时间求和写成 (B²d²/R)ΣvΔt=(B²d²/R)L，再与恒力 F 的冲量一起代入动量定理","expr":"\\int F_{\\text{安}}\\,dt=\\frac{B^2d^2L}{R}","cues":["安培力正比速度","速度乘时间就是位移","冲量只跟L有关"],"concepts":["动量定理","安培力冲量","电磁感应"]},{"title":"最终速度是否为零的分情况","type":"结论整理","judge":"撤去 F 后系统是否还有速度，取决于恒力冲量与安培力冲量谁大","why":"动量定理给出的是代数和，若安培力冲量大于恒力冲量，按公式算出的速度为负，而实际物体不能反向穿过磁场边界，只能停下，故速度取零","do":"比较 F(t₁+t₂) 与 B²d²L/R 的大小，分两种情况写出最终速度","expr":"v=\\frac{F(t_1+t_2)}{M+m}-\\frac{B^2d^2L}{(M+m)R}","cues":["算出来是负的","不能倒着走","要分两种情况"],"concepts":["动量定理","速度的物理意义","分类讨论"]}],"205":[{"title":"统一单位","type":"前提判断","judge":"初速度与位移是否统一到国际单位制后再代入","why":"速度位移公式中 v₀ 与 x 必须同属一个单位制，km/h 与 km 混用会得到错误量级","do":"把 120 m/s 保留，把 14.4 km 换算成 14400 m","expr":"x=14.4\\,\\mathrm{km}=1.44\\times10^{4}\\,\\mathrm{m}","cues":["先换算单位","位移换成米"],"concepts":["单位制","速度","位移"]},{"title":"选速度位移公式","type":"模型选择","judge":"已知 v₀、v、x 而不知时间，应选不含 t 的运动学公式","why":"匀减速到停止，末速度为零，题目未给时间，用速度位移关系可一步求出加速度","do":"写出 0−v₀²=−2ax，把末速度取零代入","expr":"0-v_0^{2}=-2ax","cues":["不含时间","用速度位移公式"],"concepts":["匀变速直线运动","速度位移关系"]},{"title":"加速度方向与大小","type":"关系建立","judge":"公式中 a 的正负号与题目所求的“加速度大小”如何对应","why":"减速运动中加速度方向与速度相反，公式里 a 取负值，题目问的是大小需取绝对值","do":"由方程解出 a 的数值，再取绝对值作为加速度大小","expr":"a=\\frac{v_0^{2}}{2x}","cues":["减速取负","问的是大小"],"concepts":["加速度","矢量与标量"]}],"206":[{"title":"识别椭圆轨道非匀速","type":"模型选择","judge":"要判断卫星在椭圆轨道上是匀速运动还是变速运动","why":"椭圆轨道上卫星到月球的距离不断变化，万有引力大小和方向都在变，不能当作匀速圆周运动处理","do":"确认轨道为椭圆、月球位于焦点，卫星与月球距离 r 随位置改变","expr":"","cues":["椭圆轨道","不是圆周","距离在变"],"concepts":["椭圆轨道","万有引力"]},{"title":"引力随距离变化","type":"关系建立","judge":"要判断引力大小随卫星到月球距离如何变化","why":"由万有引力定律，引力与距离平方成反比，距离越小引力越大","do":"写出引力表达式，比较近月点与远月点的 r 大小","expr":"F=G\\frac{Mm}{r^{2}}","cues":["离得近引力大","平方反比","看距离"],"concepts":["万有引力定律"]},{"title":"近月点速度最大","type":"关系建立","judge":"要判断速度大小随位置如何变化，即近月点与远月点速度谁大","why":"由开普勒第二定律，卫星与月球的连线在相等时间内扫过相等面积，故距离近时速度大","do":"用面积定律比较近月点与远月点的速度，或由引力做功判断动能变化","expr":"v_{\\text{近}}>v_{\\text{远}}","cues":["开普勒第二定律","近的快远的慢","扫过面积相等"],"concepts":["开普勒第二定律","面积速度"]}],"207":[{"title":"确定研究对象与过程","type":"模型选择","judge":"把运动员（含杆）看作一个整体，还是分别分析杆的弹性势能与人的动能？","why":"题目问的是助跑动能理论上能转化成的最大重力势能，杆的弹性形变在理想极限下可把能量全部还给运动员，故只需对运动员整体用能量守恒，不必追踪杆的形变细节","do":"选定运动员为研究对象，取起跳瞬间到最高点这一段过程","expr":"","cues":["把人当整体","不用管杆的形变","只看起跳和最高点"],"concepts":["机械能守恒","质点模型"]},{"title":"判断最大高度的临界条件","type":"临界条件","judge":"重心提升到最大高度时，运动员的速度应取什么值？","why":"若最高点仍有速度，则动能未全部转化为重力势能，高度还能继续增大；只有速度减为零时动能才全部转化为势能，高度取极大值","do":"令最高点速度为零，作为求最大高度的临界条件","expr":"v_{\\text{top}}=0","cues":["最高点速度为零","动能全变势能","到顶就停下"],"concepts":["临界状态","动能与势能转化"]},{"title":"建立能量守恒方程","type":"关系建立","judge":"助跑动能与重心升高所增加的重力势能之间是什么关系？","why":"忽略空气阻力和杆的耗散，只有重力做功，机械能守恒，动能的减少量等于重力势能的增加量","do":"以起跳点（或地面）为势能零点，写出动能等于重力势能增量的等式","expr":"\\frac{1}{2}mv^{2}=mgh","cues":["动能等于势能","机械能守恒","二分之一方等于gh"],"concepts":["机械能守恒定律","动能","重力势能"]},{"title":"质量约去后求解高度","type":"数学处理","judge":"方程中运动员质量 m 能否直接约去，结果是否与质量无关？","why":"等式两边都含 m，说明理论上最大提升高度只由初速度和重力加速度决定，与运动员体重无关","do":"两边约去 m，代入 v=10、g=10 解出 h","expr":"h=\\frac{v^{2}}{2g}","cues":["质量约掉","跟体重无关","只代速度和重力加速度"],"concepts":["匀变速运动规律","自由落体等效"]}],"208":[{"title":"电场力方向与大小","type":"前提判断","judge":"带正电的点电荷在匀强电场中受到的电场力方向与大小是否恒定","why":"匀强电场中场强处处相同，正电荷受力方向沿电场线方向，F=qE 为恒力","do":"由电场线方向定出电场力方向，确认 F=qE 大小方向都不变","expr":"\\vec F=q\\vec E","cues":["正电荷受力沿场强","恒力"],"concepts":["匀强电场","电场力"]},{"title":"加速度是否恒定","type":"模型选择","judge":"电荷仅受电场力时，运动能否按匀变速（类平抛）模型处理","why":"合力恒定则加速度恒定，与初速度方向无关，可套用匀变速直线或类平抛模型","do":"由牛顿第二定律求 a=qE/m，判断加速度大小方向均不变","expr":"\\vec a=\\frac{q\\vec E}{m}","cues":["合力恒定","加速度不变"],"concepts":["牛顿第二定律","匀变速运动"]},{"title":"初速度与力共线与否","type":"临界条件","judge":"初速度方向与电场力方向是共线还是垂直，决定轨迹是直线还是曲线","why":"力与速度共线时做直线运动，不共线时速度方向不断改变，轨迹弯曲","do":"比较初速度方向与电场力方向，分共线（同向/反向）与垂直两种情形讨论","expr":"","cues":["先看初速度方向","共线走直线","垂直走曲线"],"concepts":["直线运动条件","曲线运动条件"]},{"title":"电势升降看位移方向","type":"关系建立","judge":"电势升高还是降低，取决于电荷沿电场线方向的位移正负，而非加速度方向","why":"沿电场线方向电势降低，电势变化由实际位移方向决定，减速反向阶段位移与电场力反向","do":"由速度方向（即位移方向）与电场线方向的关系判断电势升降，注意反向运动阶段","expr":"U_{AB}=E\\,d_{AB}\\cos\\theta","cues":["看往哪边走","反向时电势升高","不能只看受力"],"concepts":["电势","电势差与场强关系"]}],"209":[{"title":"定圆心与半径","type":"几何关系","judge":"电子从 a 点垂直 ab 边射入，圆心应落在哪条线上","why":"洛伦兹力始终垂直于速度，圆心必在过入射点且垂直于 v0 的直线上，即 ab 边所在直线上","do":"过 a 作速度垂线，把圆心定在 ab 边所在直线上，再按出射点位置确定半径","expr":"","cues":["圆心在ab边上","速度垂线找圆心","过a点作垂线"],"concepts":["洛伦兹力","圆周运动圆心"]},{"title":"出射点定轨迹弧","type":"几何关系","judge":"从 ab 中点、b 点、c 点射出时，各自对应的圆弧圆心角是多少","why":"电子做匀速圆周运动，轨迹弧对应的圆心角决定运动时间，出射点位置不同则圆心角不同","do":"分别画出三种出射情形下的圆弧，比较各圆弧所对圆心角","expr":"","cues":["看圆心角","画三段圆弧","比弧所对角度"],"concepts":["圆心角","轨迹圆弧"]},{"title":"时间正比于弧长","type":"关系建立","judge":"运动时间由弧长还是由弦长或半径决定","why":"速率 v0 不变，圆周运动时间 t=s/v0，只取决于轨迹弧长，与半径大小无直接关系","do":"写出 t=s/v0，把比较时间转化为比较三段弧长","expr":"t=\\frac{s}{v_0}","cues":["时间看弧长","速率不变","比弧长就行"],"concepts":["匀速圆周运动","弧长与时间"]},{"title":"弧长与圆心角对应","type":"数学处理","judge":"三段弧长与正方形边长的比例关系如何","why":"弧长 s=Rθ，而各情形的半径 R 与圆心角 θ 需由正方形几何关系配套确定，不能只看半径","do":"由几何关系求出各情形的 R 与 θ，代入 s=Rθ 比较三段弧长","expr":"s=R\\theta","cues":["半径乘圆心角","先求半径再求角","配套算弧长"],"concepts":["弧长公式","几何比例"]},{"title":"排除半径大即时间长的误判","type":"前提判断","judge":"能否由半径越大直接推出运动时间越长","why":"半径变大时圆心角同时改变，时间只由弧长决定，半径与时间无单调关系，这正是干扰项的错因","do":"对三种情形分别算弧长，而不是只比较半径或弦长","expr":"","cues":["半径大不一定久","不能只看半径","要算弧长"],"concepts":["弧长决定时间","半径与圆心角"]}],"210":[{"title":"选对状态方程形式","type":"模型选择","judge":"用 pV=CT 的哪种变形来对应 V-T 图上的斜率","why":"V-T 图上纵轴是 V、横轴是 T，只有把方程解成 V=(C/p)T 才能让斜率与 p 挂钩","do":"把 pV=CT 变形为 V 关于 T 的一次式，确认斜率含义","expr":"V=\\frac{C}{p}T","cues":["先变形","写成V等于","斜率是什么"],"concepts":["理想气体状态方程","V-T 图像"]},{"title":"斜率对应压强的倒数","type":"关系建立","judge":"V-T 图上原点连线的斜率与压强是正比还是反比","why":"斜率等于 C/p，C 为定值，故斜率越大压强越小，这是比较三点压强的唯一依据","do":"写出斜率 k=C/p，得出 k 与 p 成反比","expr":"k=\\frac{V}{T}=\\frac{C}{p}","cues":["斜率越大压强越小","反比关系","看连线斜率"],"concepts":["斜率","压强"]},{"title":"比较三点连线斜率","type":"图像读取","judge":"a、b、c 三点与原点连线的斜率谁大谁小","why":"图上点的位置决定连线斜率，斜率大小直接决定压强大小关系","do":"在图上分别作 Oa、Ob、Oc 三条连线，比较其倾斜程度","expr":"k_c<k_b=k_a","cues":["连原点","看谁陡","a和b一样陡"],"concepts":["图像斜率","原点连线"]},{"title":"斜率转成压强大小","type":"结论整理","judge":"由斜率大小反推 p_a、p_b、p_c 的大小关系","why":"斜率与压强成反比，斜率相等则压强相等，斜率最小则压强最大","do":"把斜率比较结果按反比关系翻译成压强关系","expr":"p_c>p_b=p_a","cues":["反比翻过来","c压强最大","ab一样大"],"concepts":["压强比较","反比关系"]}],"211":[{"title":"识别波峰波谷对应","type":"模型选择","judge":"判断“蹲至最低点”和“恰好站直”分别对应波的什么位置","why":"题设把下蹲—起立类比为简谐波，最低点即波谷、站直即波峰，不建立这个对应就无法把人的姿态转成波形位置","do":"把第一位同学记为波谷，把站直的同学记为波峰","expr":"","cues":["蹲最低是波谷","站直是波峰","姿态对应波形"],"concepts":["简谐波","波峰与波谷"]},{"title":"波峰波谷间距条件","type":"关系建立","judge":"判断波谷到波峰的距离与波长的关系","why":"相邻波谷与波峰相距半个波长，但题目未限定是相邻的，故应为半波长的奇数倍","do":"写出波谷到波峰距离的通式，取奇数倍半波长","expr":"$d=(2k+1)\\dfrac{\\lambda}{2},\\ k=0,1,2,\\cdots$","cues":["相隔半个波长","奇数倍半波长","不一定相邻"],"concepts":["波长","半波长的奇数倍"]},{"title":"代入波长取可能值","type":"数学处理","judge":"把波长代入通式，判断哪些距离值可能出现","why":"只有满足半波长奇数倍的距离才同时对应波谷与波峰，偶数倍半波长对应的是同相点","do":"用 4 m 代入，逐个检验选项距离是否为半波长的奇数倍","expr":"$d=(2k+1)\\times 2\\,\\mathrm{m}=2,6,10,\\cdots\\mathrm{m}$","cues":["代波长算","看是不是奇数倍","偶数倍不行"],"concepts":["波长","同相点与反相点"]}],"212":[{"title":"切割磁感线的有效长度","type":"几何关系","judge":"圆环转动时，真正切割磁感线的有效长度是哪一段弦，它随转角如何变化","why":"只有位于磁场边界内、两端在虚线上的那段弦才切割磁感线，其余部分要么在磁场外要么不切割；有效长度决定感应电动势大小","do":"画出某时刻圆环与虚线（磁场边界）的交点，取两交点间的弦长为有效长度，用圆心到虚线的距离和半径表示","expr":"l=2r\\cos(90^\\circ-\\omega t)","cues":["取弦长","看两交点","有效长度","不是直径"],"concepts":["有效切割长度","几何关系"]},{"title":"转动切割电动势公式","type":"模型选择","judge":"圆环绕 P 点转动产生电动势，应选用哪类切割模型和公式","why":"圆环整体绕轴转动，各点速度不同，不能直接用 E=Blv；需用转动切割的等效公式，且有效长度对应的是弦而非半径","do":"对有效弦用转动切割公式求瞬时电动势，再代入有效长度表达式","expr":"e=\\frac12 B\\omega l^{2}","cues":["转动切割","用二分之一","不能直接Blv"],"concepts":["动生电动势","转动切割"]},{"title":"电动势随时间的函数","type":"数学处理","judge":"把有效长度代入后，电动势随时间按什么规律变化、极值和零点出现在哪些转角","why":"判断电流大小变化、周期和为零的时刻，必须先把 e 化成单一角频率的三角函数","do":"将 l 的表达式代入并利用倍角公式化简，找出 e 的最大值与零值对应的转角","expr":"e=B\\omega r^{2}[1-\\cos(2\\omega t)]","cues":["化成余弦","看极值","找零点","周期减半"],"concepts":["三角函数化简","瞬时电动势"]},{"title":"电流方向的判定","type":"前提判断","judge":"进磁场和出磁场两个阶段，穿过圆环的磁通量是增还是减，感应电流绕 O 是逆时针还是顺时针","why":"由楞次定律，感应电流的磁场要阻碍原磁通量的变化，进、出磁场时磁通量变化方向相反，电流方向也相反","do":"分别对进入和离开磁场阶段判断磁通量增减，再用楞次定律定出绕 O 的环绕方向","expr":"","cues":["进增出减","楞次定律","方向相反","绕O看"],"concepts":["楞次定律","磁通量变化"]},{"title":"电流周期与转动周期","type":"结论整理","judge":"电流变化的周期是否等于圆环转动一圈的时间，还是为其一半","why":"e 中含 cos(2ωt)，角频率是转动角频率的两倍，但一圈内电流方向要翻转两次，需按完整变化循环判断周期","do":"在一个转动周期内标出电流增大、减小、反向的各段，看电流状态重复一次所需时间","expr":"T_{电}=T_{转}=\\frac{2\\pi}{\\omega}","cues":["转一圈看几次","方向翻两次","周期相同","不是一半"],"concepts":["周期性","交变电流"]}],"213":[{"title":"坐标纸读数与刻度","type":"图像读取","judge":"图(a)中相邻圆点的竖直间距对应坐标纸上多少厘米，需先确定坐标纸的最小分度与估读位","why":"橡皮筋底端位置由坐标纸读出，长度差只能由同一把尺上两位置的读数相减得到，分度值决定有效数字位数","do":"读出 200 g 与 300 g 两圆点在坐标纸上的纵坐标，相减得间距，按最小分度估读到下一位","expr":"\\Delta y = y_{300}-y_{200}","cues":["看小格","估读一位","两位置相减"],"concepts":["刻度尺读数","有效数字"]},{"title":"判断正比于哪个量","type":"前提判断","judge":"长度增加量是与钩码质量本身成正比，还是与质量的增加量成正比","why":"橡皮筋原长未知，图(a)给出的是底端位置（含原长），只有把各点纵坐标差与质量差对比才能判断比例关系","do":"比较相邻质量间隔（均为 50 g）对应的位置间隔是否相等，若相等则说明长度增加量与质量增加量成正比","expr":"\\Delta x \\propto \\Delta m","cues":["看间隔是否均匀","原长不知道","用差值比"],"concepts":["胡克定律","正比关系"]},{"title":"用差值消去原长","type":"关系建立","judge":"求劲度系数时，能否直接用某一点的伸长量代入胡克定律","why":"橡皮筋原长 L0 未知，单点方程 mg=kx 中含两个未知量，必须用两组数据相减消去 L0","do":"对 200 g 与 300 g 两组列胡克定律方程并相减，用质量差和长度差求 k","expr":"(m_2-m_1)g = k(x_2-x_1)","cues":["原长未知","两式相减","用差值求"],"concepts":["胡克定律","劲度系数"]},{"title":"单位换算与有效数字","type":"数学处理","judge":"长度差用 cm 还是 m、质量用 g 还是 kg，结果保留几位","why":"劲度系数单位为 N/m，须用国际单位；题目要求保留 2 位有效数字","do":"把 cm 换成 m、g 换成 kg 后代入，计算结果按 2 位有效数字取舍","expr":"k=\\frac{\\Delta m\\, g}{\\Delta x}","cues":["换成国际单位","保留两位","厘米换米"],"concepts":["单位制","有效数字"]},{"title":"测力计读数","type":"实验操作","judge":"图(b)中测力计的分度值与指针位置对应多少牛","why":"F 的大小直接由测力计示数给出，读错分度值会使后续角度和质量的判断全部偏移","do":"确认测力计最小分度，读出指针所指刻度并估读一位","expr":"F=\\text{示数}","cues":["看分度值","指针位置","估读一位"],"concepts":["弹簧测力计读数"]},{"title":"三力平衡求质量","type":"关系建立","judge":"橡皮筋下端受钩码拉力、水平力 F 和橡皮筋弹力三力平衡时，用哪个几何量联系 F 与 mg","why":"橡皮筋弹力沿橡皮筋方向，竖直分量平衡钩码重力，水平分量平衡 F，故由橡皮筋与竖直方向的夹角正切联系两力","do":"在图(b)中量出橡皮筋方向与竖直方向的水平、竖直格数，求正切，再由 tanθ=F/(mg) 反求 m 并对照选项","expr":"\\tan\\theta=\\frac{F}{mg}","cues":["三力平衡","看夹角","数格子求正切"],"concepts":["共点力平衡","力的分解"]}],"214":[{"title":"内接法误差归属","type":"前提判断","judge":"电流表内接时，电压表测的是元件电压还是元件与电流表的总电压","why":"电压表并联在电流表与元件的串联支路两端，读数包含电流表分压","do":"画出内接电路，标出电压表两接线端所跨的元件范围","expr":"U_{测}=U_{x}+U_{A}>U_{x}","cues":["电压表跨了电流表","电流表也分压"],"concepts":["内接法","串联分压","电压表测量范围"]},{"title":"外接法误差归属","type":"前提判断","judge":"电流表外接时，电流表读数是否等于流过元件的电流","why":"电压表与元件并联，电流表测的是电压表与元件的总电流","do":"画出外接电路，标出电流表所在支路包含哪些并联分支","expr":"I_{测}=I_{x}+I_{V}>I_{x}","cues":["电压表也吃电流","电流表测总电流"],"concepts":["外接法","并联分流","电流表测量范围"]},{"title":"测量值偏大偏小判定","type":"关系建立","judge":"用 U/I 算出的电阻相对真实值是偏大还是偏小","why":"R=U/I 中若分子偏大或分母偏大，比值随之偏离真实电阻","do":"分别把内接的 U 偏大、外接的 I 偏大代入 R=U/I 比较","expr":"内接：\\frac{U_{x}+U_{A}}{I_{x}}>R_{x}；外接：\\frac{U_{x}}{I_{x}+I_{V}}<R_{x}","cues":["分子大了","分母大了","比值跟着变"],"concepts":["伏安法测电阻","测量值与真实值"]},{"title":"曲线斜率与电阻关系","type":"图像读取","judge":"伏安特性曲线上某点与原点连线的斜率倒数代表什么，随电流增大如何变化","why":"R=U/I 即该点与原点连线的斜率倒数，曲线弯曲说明电阻随电流变化","do":"在图(a)上取电流逐渐增大的几个点，比较各点与原点连线的斜率","expr":"R=\\frac{U}{I}=\\frac{1}{k_{OP}}","cues":["看连线斜率","斜率倒数就是电阻","曲线不是直线"],"concepts":["伏安特性曲线","非线性电阻","斜率与电阻"]},{"title":"双表测电阻的电路结构","type":"模型选择","judge":"已知内阻的 A1 应并联在 Rx 两端作电压表用，还是与 Rx 串联","why":"只有 A1 内阻已知，把它与 Rx 并联才能用 I1r1 直接给出 Rx 两端电压，无需另加电压表","do":"把 A1 与 Rx 并联，再与 A2、R0 串联接成回路，补全图(b)连线","expr":"U_{x}=I_{1}r_{1}","cues":["已知内阻的表当电压表","并联取电压","A2测总电流"],"concepts":["已知内阻电流表","并联分流","等效电压表"]},{"title":"分流关系求 Rx","type":"关系建立","judge":"流过 Rx 的电流是 I2 还是 I2 与 I1 之差","why":"A2 测干路总电流，A1 支路分走 I1，剩余电流才流过 Rx","do":"对并联部分写电压相等方程，解出 Rx","expr":"I_{1}r_{1}=(I_{2}-I_{1})R_{x}\\Rightarrow R_{x}=\\frac{I_{1}r_{1}}{I_{2}-I_{1}}","cues":["总电流减分支电流","并联电压相等","差值才是Rx的电流"],"concepts":["并联电路电流关系","欧姆定律"]}],"215":[{"title":"识别不变量选公式","type":"前提判断","judge":"两问中各自被固定不变的是电荷量还是电压","why":"电容定义式 C=Q/U 中 Q、U、C 三者联动，只有先确定哪个量不变，才能判断另外两个量如何随 d 变化","do":"读题干条件，第（1）问锁定 Q 不变，第（2）问锁定 U 不变，分别作为推导出发点","expr":"C=\\frac{Q}{U}","cues":["电荷量不变","电压不变","先看谁固定"],"concepts":["电容定义式","不变量"]},{"title":"电容随间距反比变化","type":"关系建立","judge":"间距变为 η 倍时电容变为原来的几分之几","why":"平行板电容器电容与板间距成反比，d 增大则 C 减小，比例关系为倒数关系而非正比","do":"写出按压前后电容之比，把 d₂=ηd₁ 代入 C=αS/d 得 C₂/C₁","expr":"\\frac{C_2}{C_1}=\\frac{d_1}{d_2}=\\frac{1}{\\eta}","cues":["电容和间距成反比","间距变η倍","电容变倒数倍"],"concepts":["平行板电容器电容","反比关系"]},{"title":"电压随电容反比推倍数","type":"关系建立","judge":"Q 不变时电压与电容成反比，U 的倍数等于 d 的倍数","why":"由 U=Q/C 且 Q 恒定，U 与 C 成反比，而 C 与 d 成反比，故 U 与 d 成正比","do":"将 C₂/C₁ 代入 U₂/U₁=C₁/C₂，化简得 U₂/U₁=η","expr":"\\frac{U_2}{U_1}=\\frac{C_1}{C_2}=\\eta","cues":["电压跟电容反着来","电荷不变","两次反比抵消"],"concepts":["电压与电容关系","比例推导"]},{"title":"场强用电压比间距","type":"模型选择","judge":"匀强电场中 E 应由 U/d 求，而不是由 Q 或 C 单独决定","why":"平行板间为匀强电场，场强等于极板电压与板间距之比，这是联系 U、d、E 的基本关系","do":"写出 E₁=U/d₁、E₂=U/d₂，在 U 不变条件下作比","expr":"E=\\frac{U}{d}","cues":["匀强电场","场强等于电压除间距","用电压和间距算"],"concepts":["匀强电场","电场强度与电势差关系"]},{"title":"U 不变时场强反比于 d","type":"关系建立","judge":"电压恒定时场强与间距成反比，倍数取 η 的倒数","why":"E=U/d 中 U 固定，E 只随 d 反比变化，d 变为 η 倍则 E 变为 1/η 倍","do":"将 d₂=ηd₁ 代入 E₂/E₁=d₁/d₂，得 E₂/E₁=1/η","expr":"\\frac{E_2}{E_1}=\\frac{d_1}{d_2}=\\frac{1}{\\eta}","cues":["电压不变","场强跟间距反比","取倒数"],"concepts":["电场强度","反比关系"]}],"216":[{"title":"圆弧段重力做功的判断","type":"前提判断","judge":"小球沿圆弧从 A 滑到最低点（离开圆弧进入 Q 上表面）的过程中，重力做功只由哪一段高度差决定","why":"重力做功只与初末位置的高度差有关，与路径无关；圆弧轨道光滑，支持力不做功，所以只需看竖直下降的高度","do":"找出小球进入圆弧时的位置与离开圆弧时的位置，比较两者的高度差","expr":"W_G=mgR","cues":["只看高度差","支持力不做功","路径无关"],"concepts":["重力做功","高度差","光滑轨道"]},{"title":"弹簧压缩过程的能量方程","type":"关系建立","judge":"小球从刚接触弹簧到速度降为初速三分之一的过程中，用哪两个状态的机械能守恒来求初速度","why":"轨道与 Q 上表面光滑、只有弹簧弹力做功，小球（含弹簧）系统机械能守恒；题给该时刻弹性势能为 2mgR，可把初动能与末动能、弹性势能联系起来","do":"取刚接触弹簧时为初态、速度为 v0/3 时为末态，列初动能等于末动能加弹性势能","expr":"\\frac12 mv_0^2=2mgR+\\frac12 m\\left(\\frac{v_0}{3}\\right)^2","cues":["初态取刚接触","末态速度是三分之一","弹性势能已知"],"concepts":["机械能守恒","弹性势能","动能"]},{"title":"自由落体段与圆弧段衔接","type":"关系建立","judge":"B 到 A 的自由下落与 A 到刚接触弹簧的圆弧下滑，能否合并成一次机械能守恒来求下落高度","why":"全程只有重力做功（圆弧支持力不做功），小球从 B 静止释放到刚接触弹簧时速度为 v0，可直接用总高度差列式","do":"以 B 点为初态、刚接触弹簧为末态，列重力势能减少等于动能增加，解出 B、A 高度差 h","expr":"mg(h+R)=\\frac12 mv_0^2","cues":["全程机械能守恒","从B静止释放","高度差含R"],"concepts":["机械能守恒","自由落体","重力势能"]},{"title":"断开后动量守恒的对象选择","type":"模型选择","judge":"P 与 Q 断开后，研究小球与 Q 组成的系统在水平方向上的动量与机械能是否守恒","why":"断开后 Q 在光滑水平面上滑动，小球与弹簧、Q 之间只有内力，水平方向不受外力，动量守恒；且只有弹簧弹力做功，机械能守恒","do":"取小球加 Q（含弹簧）为系统，以断开瞬间为初态列动量守恒，配合机械能守恒联立","expr":"m\\cdot\\frac{v_0}{3}=(m+M)v_{\\text{共}}","cues":["取小球和Q整体","水平方向无外力","动量守恒"],"concepts":["动量守恒","系统内力","光滑水平面"]},{"title":"最大弹性势能的临界条件","type":"临界条件","judge":"弹簧弹性势能最大时，小球与 Q 的速度满足什么关系","why":"弹性势能最大意味着弹簧形变最大，此时两者相对速度为零，即达到共同速度","do":"令小球与 Q 共速，把该共速动能与初动能之差全部归入弹性势能，列式求 Q 的质量","expr":"\\frac12 mv_0^2=2.2mgR+\\frac12(m+M)v_{\\text{共}}^2","cues":["共速时势能最大","相对速度为零","形变最大"],"concepts":["临界条件","共速","弹性势能"]},{"title":"Q 最终动能最大的条件","type":"临界条件","judge":"断开后 Q 的最终动能取最大时，小球最终速度应处于什么状态","why":"系统机械能一定，Q 的动能要最大就要让小球分走的动能最小；小球速度不能反向（否则弹簧仍被压缩、能量未全部释放），故最小动能为零，即弹簧刚好恢复原长","do":"令小球末速度为零、弹簧恢复原长，用动量守恒与机械能守恒联立求 Q 的质量","expr":"m\\cdot\\frac{v_0}{3}=M'v_m,\\quad \\frac12 mv_0^2=\\frac12 M'v_m^2","cues":["小球速度刚好为零","弹簧恢复原长","能量全给Q"],"concepts":["机械能守恒","动量守恒","极值条件"]}],"217":[{"title":"判断是否绝热","type":"前提判断","judge":"猛推过程中气体与外界是否有热交换，能否取 Q=0","why":"猛推时间极短，气体来不及与外界交换热量，这是用热力学第一定律的前提；若认为有放热，内能变化方向就无法确定","do":"比较推压时间与热传递所需时间，判定过程为绝热过程","expr":"Q=0","cues":["猛推来不及散热","时间太短","当作绝热"],"concepts":["绝热过程","热力学第一定律"]},{"title":"判断做功正负","type":"关系建立","judge":"气体体积减小，是外界对气体做功还是气体对外做功","why":"做功正负由体积变化决定，压缩时外界对气体做正功，这是内能增大的直接原因","do":"由推杆压缩判断体积减小，写出外界对气体做功 W>0","expr":"W>0（外界对气体做功）","cues":["体积变小","外界对气体做功","压缩气体"],"concepts":["体积功","做功改变内能"]},{"title":"判断内能与温度","type":"关系建立","judge":"由 Q=0 和 W>0 判断内能如何变化，进而判断温度如何变化","why":"热力学第一定律 ΔU=Q+W，绝热压缩时 W>0 使内能增大；理想气体内能只由温度决定，内能增大即温度升高","do":"用 ΔU=Q+W 得 ΔU>0，再由内能与温度的关系得 T 升高","expr":"ΔU=Q+W>0，T 升高","cues":["内能增大","温度升高","绝热压缩升温"],"concepts":["热力学第一定律","理想气体内能","温度"]},{"title":"判断压强变化","type":"关系建立","judge":"体积减小同时温度升高，压强是增大还是减小","why":"由理想气体状态方程 pV/T=C，V 减小使 p 趋于增大，T 升高使 p 也趋于增大，两者同向，故 p 必增大","do":"对 pV/T=C 分析 V 减小、T 增大两个因素对 p 的影响","expr":"pV/T=C，V↓且T↑ ⇒ p↑","cues":["体积小温度高","两个因素同向","压强一定增大"],"concepts":["理想气体状态方程","压强"]},{"title":"判断分子平均动能","type":"结论整理","judge":"温度升高对应分子平均动能如何变化","why":"温度是分子平均动能的标志，温度升高则分子平均动能增大，这是微观解释的核心结论","do":"由 T 升高直接得出分子平均动能增大","expr":"T↑ ⇒ 分子平均动能↑","cues":["温度是平均动能的标志","温度升高动能增大"],"concepts":["分子平均动能","温度的微观意义"]}],"218":[{"title":"区分衍射与干涉","type":"前提判断","judge":"判断现象是光绕过障碍物/狭缝边缘传播，还是两束相干光叠加","why":"衍射的本质是光偏离直线传播绕到障碍物后方，干涉的本质是相干光叠加形成明暗条纹，二者成因不同","do":"对每个现象追问：条纹是绕过边缘产生的，还是两束光叠加产生的","expr":"","cues":["绕过边缘","两束光叠加","看条纹成因"],"concepts":["光的衍射","光的干涉"]},{"title":"识别色散与折射","type":"模型选择","judge":"判断彩虹类现象是不同色光折射率不同引起的色散，还是衍射","why":"雨后彩虹是阳光在雨滴中经折射、反射后各色光偏折角不同而分开，属色散而非衍射","do":"看现象中是否有水滴或棱镜使各色光因折射率不同而分开","expr":"","cues":["雨滴折射","各色光偏折不同","这是色散"],"concepts":["色散","折射"]},{"title":"识别薄膜干涉","type":"模型选择","judge":"判断肥皂膜、油膜上的彩色条纹是薄膜前后表面反射光干涉还是衍射","why":"薄膜干涉由膜前后表面反射的两束相干光叠加形成，厚度变化决定条纹，与绕过边缘无关","do":"看彩色条纹是否出现在薄膜上、是否随膜厚变化","expr":"","cues":["薄膜前后表面","反射光叠加","膜上彩色"],"concepts":["薄膜干涉"]},{"title":"识别全反射发光","type":"模型选择","judge":"判断水中气泡明亮是光的全反射还是衍射","why":"光由水射向气泡（空气）时可能发生全反射，使更多光线折回水中进入人眼，与衍射无关","do":"看现象是否涉及光从光密介质射向光疏介质、超过临界角","expr":"","cues":["光密到光疏","超过临界角","气泡发亮"],"concepts":["全反射","临界角"]}],"219":[{"title":"感应电流的产生条件","type":"前提判断","judge":"判断金属圆环中能否产生感应电流，依据的是磁通量是否变化，而不是环是否在磁场中或是否运动","why":"法拉第电磁感应定律：只有穿过闭合回路的磁通量发生变化，回路中才产生感应电流；环在磁场中静止或平动但磁通量不变时无感应电流","do":"对每个图示先问：穿过圆环的磁通量 Φ 是否改变，再决定有无感应电流","expr":"\\Phi=BS\\cos\\theta,\\quad \\Delta\\Phi\\neq 0 \\Rightarrow I\\neq 0","cues":["看磁通量变不变","不是看动不动","环在磁场里也没用"],"concepts":["磁通量","电磁感应现象","感应电流产生条件"]},{"title":"匀强磁场中平动的磁通量","type":"模型选择","judge":"圆环在匀强磁场中整体平移时，穿过环的磁通量是否改变","why":"匀强磁场 B 处处相同，环面积 S 与环面法线相对 B 的夹角都不变，故 Φ=BScosθ 保持不变","do":"比较平移前后 B、S、θ 三个量，确认三者均不变，得出 ΔΦ=0","expr":"\\Phi=BS\\cos\\theta=\\text{常量}","cues":["匀强磁场里平移","面积没变","磁通量不变"],"concepts":["匀强磁场","磁通量"]},{"title":"转动与平移的区分","type":"关系建立","judge":"圆环绕轴转动时，环面与磁场的夹角 θ 是否随时间改变，从而磁通量是否变化","why":"转动改变环面法线与 B 的夹角，cosθ 变化使 Φ 随时间变化，产生感应电流；这与平动不改变 θ 形成对照","do":"对绕轴转动的图，判断环面法线与 B 的夹角是否在变，写出 Φ 随 θ 变化的趋势","expr":"\\Phi=BS\\cos\\theta(t),\\quad \\theta\\ \\text{变化}\\Rightarrow \\Delta\\Phi\\neq 0","cues":["转动改变夹角","夹角在变","磁通量在变"],"concepts":["磁通量","转动切割"]},{"title":"非匀强磁场的空间变化","type":"模型选择","judge":"在长直电流旁或条形磁铁旁平移时，环所在处的磁感应强度是否随位置改变","why":"恒定电流的磁场随距离减弱，条形磁铁两极附近磁场最强且空间不均匀，环平移时各点 B 不同，导致 Φ 变化","do":"判断环移动路径上 B 的大小是否变化，比较平移前后穿过环的磁通量","expr":"B=B(r)\\ \\text{随位置变化}\\Rightarrow \\Delta\\Phi\\neq 0","cues":["离导线越远越弱","磁铁旁边不均匀","磁场在变"],"concepts":["非匀强磁场","磁通量"]}],"220":[{"title":"从表达式读角速度","type":"图像读取","judge":"由电动势表达式中的系数 100π 判断出角速度 ω，再换算频率","why":"正弦交流电的瞬时表达式为 e=E_m sin(ωt)，ω 与频率满足 ω=2πf，这是判断频率类选项的唯一依据","do":"把 e=10sin(100πt) 与标准形式对比，取 ω=100π，算出 f=ω/2π","expr":"$\\omega=100\\pi,\\ f=\\frac{\\omega}{2\\pi}$","cues":["看系数","角速度是100π"],"concepts":["正弦交流电表达式","角速度","频率"]},{"title":"图示位置磁通量判断","type":"模型选择","judge":"判断图示时刻线圈平面与磁感线的相对取向，从而确定磁通量大小和磁通量变化率","why":"感应电动势由磁通量的变化率决定，而磁通量变化率最大处恰是磁通量为零（线圈平面与磁场平行）处，两者不能混为一谈","do":"观察图中线圈平面与磁感线是否平行，比较该位置的磁通量与变化率","expr":"","cues":["线圈平面和磁场平行","磁通量为零","变化率最大"],"concepts":["磁通量","磁通量变化率","法拉第电磁感应定律"]},{"title":"感应电流方向判定","type":"关系建立","judge":"用右手定则判断图示位置 AB 边中感应电流的方向","why":"线圈在磁场中切割磁感线，导体中感应电流方向由右手定则确定，方向判错则后续安培力方向全错","do":"取 AB 边的运动方向与磁场方向，用右手定则确定电流由 B 流向 A","expr":"","cues":["右手定则","四指指电流方向","电流从B到A"],"concepts":["右手定则","感应电流方向"]},{"title":"安培力方向判定","type":"关系建立","judge":"在已知电流方向的前提下，用左手定则判断 AB 边所受安培力的方向","why":"安培力方向由电流方向和磁场方向共同决定，须用左手定则，且电流方向必须取自上一判断的结果","do":"取 AB 边电流方向与磁场方向，用左手定则判断安培力指向","expr":"","cues":["左手定则","磁感线穿掌心","安培力向上"],"concepts":["左手定则","安培力"]},{"title":"峰值与转速关系","type":"关系建立","judge":"判断仅转速加倍时电动势峰值如何变化","why":"峰值 E_m=NBSω 中 ω 与转速成正比，N、B、S 不变时峰值随转速同比例变化","do":"写出 E_m=NBSω，把 ω 加倍后比较峰值与原峰值","expr":"$E_m=NBS\\omega\\propto n$","cues":["峰值跟转速成正比","转速加倍峰值加倍","和线圈匝数面积有关"],"concepts":["电动势峰值","转速","角速度"]}],"221":[{"title":"判定横波还是纵波","type":"前提判断","judge":"质点振动方向与波传播方向是垂直还是平行","why":"横波定义为振动方向与传播方向垂直，纵波为平行；图中质点沿竖直方向振动而波沿水平方向传播","do":"比较质点 S 的振动方向与波沿绳传播的方向，看两者是否垂直","expr":"","cues":["看振动方向和传播方向","垂直就是横波","绳波是横波"],"concepts":["横波","纵波","振动方向"]},{"title":"由波形定传播方向","type":"图像读取","judge":"波是向左还是向右传播，从而确定 P 点此刻的运动方向","why":"波形图只给出位移分布，必须结合传播方向才能用同侧法或上下坡法判断质点速度方向","do":"读图中波峰位置与 P 点所在斜面，结合波向确定 P 点下一时刻的位移变化","expr":"","cues":["先定传播方向","看P在哪一侧","用同侧法"],"concepts":["波的传播方向","波形图","同侧法"]},{"title":"起振方向全体相同","type":"关系建立","judge":"P 点此刻的振动方向能否代表波源 S 的起振方向","why":"介质中每个质点都由波源带动起振，各质点起振方向都与波源最初起振方向一致","do":"由 P 点此刻的振动方向反推 S 的起振方向","expr":"","cues":["起振方向都一样","由P推波源","看最开始振动"],"concepts":["起振方向","波源","波的传播"]},{"title":"步调由距离与波长定","type":"关系建立","judge":"S、P 两质点平衡位置间距是半波长的奇数倍还是偶数倍","why":"相距半波长奇数倍的两质点振动步调相反，偶数倍则相同","do":"从图上数出 S 到 P 之间包含的波长数，判断是半波长的几倍","expr":"","cues":["数几个波长","差半个波长就反相","看间距是半波长几倍"],"concepts":["波长","振动步调","反相"]},{"title":"质点不随波迁移","type":"结论整理","judge":"质点是否会沿波的传播方向移动","why":"机械波传播的是振动形式和能量，介质质点只在平衡位置附近振动，不随波迁移","do":"区分质点的振动位移与波的传播位移，排除质点随波移动的说法","expr":"","cues":["质点不跟着波跑","只上下振动","波传的是振动形式"],"concepts":["机械波","质点振动","能量传播"]}],"222":[{"title":"隔离A定摩擦力","type":"模型选择","judge":"A 与 B 之间是否存在静摩擦力，方向如何","why":"A 只受重力、B 的支持力和可能的摩擦力；重力沿斜面向下的分量必须由某个力平衡，否则 A 不能静止，所以 B 对 A 的静摩擦力必沿斜面向上","do":"对 A 单独受力分析，沿斜面方向列平衡式，判断 B 对 A 的摩擦力方向","expr":"m_A g\\sin\\theta = f_{BA}","cues":["先隔离A","重力有下滑分力","A要静止"],"concepts":["隔离法","静摩擦力","平衡条件"]},{"title":"由反作用定B受摩擦","type":"关系建立","judge":"A 对 B 的摩擦力方向是沿斜面向上还是向下","why":"牛顿第三定律：B 对 A 的摩擦力沿斜面向上，则 A 对 B 的摩擦力必沿斜面向下，不能凭直觉认为 A 压在 B 上就只给压力","do":"取 B 对 A 摩擦力的反方向，确定 A 对 B 的摩擦力方向","expr":"f_{AB}=-f_{BA}","cues":["作用力反作用力","方向反过来","A给B的摩擦"],"concepts":["牛顿第三定律","作用力与反作用力"]},{"title":"B自身平衡定斜面摩擦","type":"临界条件","judge":"斜面对 B 的摩擦力是否存在、方向如何","why":"B 受重力下滑分力、A 的压力分力、A 给的沿斜面向下摩擦力，再加拉力 F，这些沿斜面方向的合力是否为零决定斜面摩擦力；不能默认 F 恰好抵消一切","do":"对 B 沿斜面方向列平衡方程，看除斜面摩擦力外各分力之和的方向，判断斜面摩擦力方向","expr":"F + f_{斜面} = m_B g\\sin\\theta + f_{AB} + N_A\\text{的分量}","cues":["B也静止","沿斜面合力为零","看还差哪个力"],"concepts":["平衡条件","受力分析","静摩擦力"]},{"title":"按性质逐个数力","type":"结论整理","judge":"B 一共受几个力，是否把压力与支持力、摩擦力重复或漏计","why":"数力要按性质力分类：重力、拉力、斜面支持力、斜面摩擦力、A 的压力、A 的摩擦力，共六类；把 A 的压力与 B 对 A 的支持力混为一谈会数错","do":"按重力、弹力、摩擦力、已知外力逐类清点 B 受到的力，核对每个力的施力物体","expr":"","cues":["按性质数","别把压力漏了","摩擦有两个"],"concepts":["受力分析","力的分类","弹力与摩擦力"]}],"223":[{"title":"变轨方向判断","type":"模型选择","judge":"在 A 点从圆轨道 1 进入椭圆轨道 2，是加速还是减速","why":"圆轨道上万有引力恰好提供向心力；进入椭圆轨道后 A 成为近月点，需要的向心力大于圆轨道时的值，故必须点火加速，机械能增加","do":"比较同一半径 r_A 处圆轨道所需向心力与万有引力的大小，判断速度应增大","expr":"G\\frac{Mm}{r_A^2} < m\\frac{v_2^2}{r_A} \\Rightarrow v_2 > v_1","cues":["近月点要加速","变轨看供需","向心力不够就加速"],"concepts":["离心运动","向心力","机械能"]},{"title":"远离时引力做功","type":"关系建立","judge":"从 A 到 B 远离月球的过程中，万有引力做正功还是负功，动能如何变化","why":"引力指向月球中心，位移方向背离月球，力与位移夹角大于 90°，做负功，由动能定理动能减小","do":"判断力与速度方向夹角，用动能定理写功与动能变化的关系","expr":"W = -G\\frac{Mm}{r_A}+G\\frac{Mm}{r_B} < 0 \\Rightarrow E_k \\text{减小}","cues":["远离做负功","引力向后拽","速度越来越小"],"concepts":["功的正负","动能定理","万有引力"]},{"title":"加速度看距离","type":"关系建立","judge":"轨道 2 上从 A 到 B 加速度如何变化，能否用速度变化代替加速度判断","why":"合力只有万有引力，a=GM/r²，只由该点距离 r 决定；r 增大则 a 减小，与速度大小无直接关系","do":"写出牛顿第二定律的加速度表达式，比较 A、B 两点的 r","expr":"a = \\frac{GM}{r^2}","cues":["加速度只看距离","别拿速度当加速度","越远引力越小"],"concepts":["牛顿第二定律","万有引力定律"]},{"title":"机械能比较","type":"结论整理","judge":"同一探测器在两条轨道上的机械能谁大","why":"机械能包含动能与引力势能，变轨时发动机做功改变机械能；加速后机械能增大，故轨道 2 上机械能更大","do":"比较变轨前后除引力外其他力做功情况，判断机械能增减","expr":"E_2 = E_1 + W_{\\text{发动机}} > E_1","cues":["加速机械能变大","点火做功了","不能只看动能"],"concepts":["机械能","功能原理"]},{"title":"求质量缺半径","type":"前提判断","judge":"仅知引力常量 G 和轨道 1 的周期 T，能否求出月球质量","why":"由万有引力提供向心力得 M=4π²r³/(GT²)，式中 r 为轨道半径，未知则 M 不可求，只给 T 不够","do":"写出含 M、r、T 的方程，检查未知量个数","expr":"M = \\frac{4\\pi^2 r^3}{G T^2}","cues":["还差轨道半径","只有周期不够","半径没给"],"concepts":["万有引力提供向心力","天体质量估算"]}],"224":[{"title":"等高线疏密判坡度","type":"图像读取","judge":"要判断等高线密集程度与坡面陡缓的对应关系","why":"等高线越密集表示相同水平距离内高度变化越大，坡面越陡，坡角越大","do":"比较 MA 与 MB 沿线等高线的疏密，得出哪条滑道更陡","expr":"","cues":["线密坡陡","看等高线间距","右边更密"],"concepts":["等高线","坡度","坡角"]},{"title":"坡度决定下滑加速度","type":"关系建立","judge":"要判断无摩擦下滑时加速度由什么量决定","why":"沿光滑斜面下滑只受重力和支持力，沿斜面方向合力为重力分量，由牛顿第二定律得加速度只与坡角有关","do":"对小球沿滑道方向列牛顿第二定律，写出加速度与坡角的关系","expr":"a=g\\sin\\theta","cues":["取沿斜面方向","重力分量提供加速度","跟坡角有关"],"concepts":["牛顿第二定律","重力分量","光滑斜面"]},{"title":"同高度下落速度相同","type":"前提判断","judge":"要判断小球滑到 A、B 时速度大小是否只由下落高度决定","why":"不计阻力时只有重力做功，机械能守恒，末动能只取决于下落的高度差，与路径和坡度无关","do":"对 MA、MB 两条路径分别用机械能守恒，比较 A、B 两点的高度","expr":"mgh=\\tfrac12 mv^2","cues":["同一等高线","高度一样","机械能守恒"],"concepts":["机械能守恒","高度差","路径无关"]},{"title":"类比等势线疏密","type":"模型选择","judge":"要判断等高线模型与等势线模型之间哪些量可以类比","why":"等高线描述高度分布，等势线描述电势分布，两者都是标量场的等值线，线越密场变化越快","do":"把等高线疏密对应到等势线疏密，把高度降落对应到电势降落","expr":"","cues":["等高线像等势线","线密变化快","类比着看"],"concepts":["等势线","标量场","类比法"]}],"225":[{"title":"开关闭合瞬间的元件等效","type":"模型选择","judge":"闭合瞬间要判断电容和线圈各自相当于什么电路元件","why":"电容电压不能突变、线圈电流不能突变，故瞬间电容相当于短路（通路）、线圈相当于断路","do":"把 C 看成导线、把 L 看成断开，画出瞬间的等效电路","expr":"","cues":["电容当导线","线圈先断路","瞬间看突变"],"concepts":["自感现象","电容电压不能突变","等效电路"]},{"title":"稳定后元件等效","type":"模型选择","judge":"稳定后要判断电容和线圈各自相当于什么","why":"直流稳态下电容充电完毕无电流相当于断路，理想线圈电阻为零相当于短路","do":"把 C 看成断开、把 L 看成导线，重画稳态等效电路","expr":"","cues":["电容充满就断开","线圈稳定当导线","稳态看直流"],"concepts":["直流稳态","理想电感","等效电路"]},{"title":"判断各灯亮暗变化","type":"关系建立","judge":"要判断哪些灯瞬间亮、哪些灯逐渐变亮或亮后熄灭","why":"灯是否发光取决于通过它的电流，而电流受 L 的逐渐导通和 C 的充电过程控制","do":"比较瞬间与稳态两种等效电路下各支路电流的有无与变化趋势","expr":"","cues":["先看谁有电流","再看电流怎么变","亮一下还是常亮"],"concepts":["自感","充电过程","支路电流"]},{"title":"稳态串并联结构","type":"关系建立","judge":"要判断稳态时 A1、A3 与电容之间的串并联关系","why":"C 断路后该支路无电流，L 短路把两端并成一点，需重新识别回路结构","do":"沿稳态等效电路追踪电流路径，确定 A1 与 A3 是否串联、C 与谁并联","expr":"","cues":["电容支路没电流","线圈两端等电势","看谁跟谁串"],"concepts":["串联","并联","等效电路"]},{"title":"分压求电容电压","type":"关系建立","judge":"要判断电容两端电压等于哪部分电压、其值为多少","why":"C 与 A3 并联故电压相同；忽略线圈与电源内阻时 A1、A3 串联均分电动势","do":"用串联分压求 A3 电压，即得电容电压，再由 Q=CU 求电荷量","expr":"U_C=U_{A3}=\\frac{E}{2},\\quad Q=CU_C","cues":["电容跟灯并联","两灯平分电压","电压一半"],"concepts":["串联分压","并联等压","电容电荷量"]}],"226":[{"title":"电磁阻尼的判定","type":"模型选择","judge":"磁铁在线圈上方振动时，线圈中是否产生感应电流并对磁铁施加阻碍其相对运动的力","why":"磁铁振动使穿过闭合线圈的磁通量变化，由法拉第电磁感应定律和楞次定律，线圈中产生感应电流，该电流的磁场阻碍磁铁与线圈的相对运动，即电磁阻尼","do":"比较有、无线圈两种情形下磁铁所受阻力来源，判断振动停止的快慢","expr":"","cues":["有感应电流","阻碍相对运动","更快停下"],"concepts":["电磁感应","楞次定律","电磁阻尼"]},{"title":"线圈收缩趋势的判断","type":"关系建立","judge":"磁铁靠近线圈、磁通量增大时，线圈为阻碍磁通量增大应扩张还是收缩","why":"楞次定律的推广形式：感应电流的效果总要阻碍引起它的磁通量的变化，磁铁靠近时磁通量增大，线圈应通过面积缩小来阻碍增大","do":"由磁铁靠近时磁通量增大，判断线圈面积的变化趋势","expr":"","cues":["阻碍磁通量增大","面积要减小","有收缩趋势"],"concepts":["楞次定律","磁通量"]},{"title":"最近点感应电流为零","type":"临界条件","judge":"磁铁运动到离线圈最近处时，磁铁与线圈的相对速度是否为零，感应电动势是否为零","why":"感应电动势由磁通量的变化率决定，最近点处相对速度为零，磁通量变化率为零，故感应电动势、感应电流、安培力均为零","do":"分析最近点处磁铁速度与磁通量变化率的关系，判断此刻安培力是否为零","expr":"","cues":["最近点速度为零","变化率为零","安培力为零"],"concepts":["法拉第电磁感应定律","磁通量变化率"]},{"title":"终态平衡位置相同","type":"前提判断","judge":"有、无线圈两种情形下，磁铁最终静止时弹簧的伸长量是否相同","why":"最终静止时磁铁只受重力和弹簧弹力（线圈对静止磁铁无作用力），由平衡条件 kx=mg 得伸长量相同，与有无阻尼无关","do":"对最终静止的磁铁列竖直方向平衡方程，比较两种情形的伸长量","expr":"kx=mg","cues":["静止时只受重力和弹力","伸长量相同","与阻尼无关"],"concepts":["共点力平衡","胡克定律"]},{"title":"损失机械能比较","type":"结论整理","judge":"两种情形下系统损失的机械能是否相同","why":"初态相同（原长释放、动能为零），终态弹簧伸长量相同、磁铁位置相同，故初末势能差相同，损失的机械能等于重力势能减少量与弹性势能增加量之差，两种情形相等","do":"比较两种情形的初末机械能，用重力势能减少量减去弹性势能增加量求损失","expr":"ΔE=mgx-½kx²","cues":["初末位置相同","势能差相同","损失机械能相同"],"concepts":["机械能","能量守恒"]}],"227":[{"title":"由阻力方向反推速度方向","type":"前提判断","judge":"由图读出各时间段阻力 f 的正负，判断实验舱的速度方向是向上还是向下","why":"空气阻力方向总与速度方向相反，题设规定向上为正，所以 f 的正负直接对应速度方向的反号","do":"把 f-t 图按 t1、t2、t3、t4、t5 分段，看每段 f 在横轴上方还是下方","expr":"","cues":["阻力反向就是速度","看正负定方向","f向上速度向下"],"concepts":["空气阻力","速度方向","正方向规定"]},{"title":"由阻力大小变化判断速率变化","type":"关系建立","judge":"由同一段内 f 的大小增大或减小，判断速率在增大还是减小","why":"题设明确 f 随速率增大而增大，f 的大小变化与速率变化同向对应","do":"比较 t1~t2 与 t2~t3 内 f 的绝对值变化，得出速率先增后减","expr":"","cues":["阻力大速度大","f变小速度变小","先加速后减速"],"concepts":["阻力与速率关系","速率变化"]},{"title":"分段还原运动过程","type":"模型选择","judge":"把整段运动划分为电磁弹射加速、竖直上抛上升、自由下落、电磁制动四个阶段","why":"f 的方向在 t3 处翻转，说明速度反向，t3 是上升与下落的转折点；t1 前 f 为零对应静止起步","do":"以 t3 为速度反向点、以 f 由零开始增大处为弹射起点，把图线分段对应到各运动阶段","expr":"","cues":["t3是最高点","先弹射再上抛","分四段看"],"concepts":["竖直上抛","运动分段","最高点速度为零"]},{"title":"上升减速段的加速度判断","type":"关系建立","judge":"在 t2~t3 段速度向上、阻力向下且减小时，判断加速度大小如何变化","why":"上升阶段重力与阻力同向向下，合力为 mg+f，由牛顿第二定律 a=g+f/m，f 减小则 a 减小","do":"对 t2~t3 段列牛顿第二定律，把 a 写成 g 与 f/m 之和，随 f 减小判断 a 减小","expr":"$a=g+\\dfrac{f}{m}$","cues":["重力阻力同向","合力等于重力加阻力","阻力减小加速度减小"],"concepts":["牛顿第二定律","合力","加速度"]},{"title":"下降段的超失重判断","type":"结论整理","judge":"在 t3~t5 段速度向下时，判断加速度先向下后向上，对应先失重后超重","why":"向下运动时阻力向上，合力为 mg-f，f 先增后减使合力先减后增，加速度先向下减小后向上增大","do":"对下降段比较 mg 与 f 的大小，确定合力方向变化，再对应超重失重","expr":"$ma=mg-f$","cues":["下降先加速后减速","加速度先下后上","先失重后超重"],"concepts":["超重与失重","合力方向","加速度方向"]}],"228":[{"title":"判断电势高低","type":"前提判断","judge":"正负离子在磁场中受洛伦兹力偏转后，M、N 哪端电势更高","why":"管内液体中的正负离子随液体沿轴线运动，速度方向相同而电荷相反，用左手定则判断洛伦兹力方向时正负离子偏向相反，偏出的一侧积累同号电荷，决定 M、N 的电势高低","do":"取液体流动方向为速度方向，对正离子用左手定则定洛伦兹力指向，再对负离子反向判断，比较两端积累的电荷符号","expr":"","cues":["正离子往下偏","负离子往上偏","看左手定则"],"concepts":["洛伦兹力","左手定则","电荷积累"]},{"title":"稳定时力平衡","type":"关系建立","judge":"稳定状态下电场力与洛伦兹力是否平衡，以及电场强度如何用 U0 和管径表示","why":"液体稳定流动时离子不再继续偏转，径向合力为零，故 qE=qvB；而 M、N 是直径两端，间距为 2r，故 E=U0/(2r)","do":"对径向受力列平衡方程，并用直径 2r 而不是半径 r 表示场强","expr":"\\frac{U_0}{2r}q=Bqv","cues":["电场力和洛伦兹力平衡","间距是直径","别用半径"],"concepts":["电场力","洛伦兹力","平衡条件"]},{"title":"流量与速度关系","type":"关系建立","judge":"流量 Q 与流速 v、管道半径 r 的关系如何写","why":"流量定义为单位时间流过横截面的体积，横截面是圆，面积为 πr²，故 Q=Sv","do":"写出横截面积 S=πr²，再与速度相乘得流量","expr":"Q=\\pi r^{2}v","cues":["流量等于面积乘速度","截面是圆","面积用半径平方"],"concepts":["流量","横截面积"]},{"title":"消去速度得 U0 表达式","type":"数学处理","judge":"把力平衡式与流量式联立，消去 v，得到 U0 与 Q、r、B 的关系","why":"题目要判断 U0 与 Q、r 的比例关系，必须把中间量 v 消掉，只留题给的可测量","do":"由流量式解出 v=Q/(πr²)，代入平衡式解出 U0","expr":"U_0=\\frac{2BQ}{\\pi r}","cues":["消掉速度","把v代进去","只剩流量和半径"],"concepts":["联立方程","正比关系"]},{"title":"磁场不垂直时的等效","type":"临界条件","judge":"直径 MN 与磁场不垂直时，公式中的 B 应取哪个分量，测得流量偏大还是偏小","why":"只有垂直于速度又垂直于 MN 的磁场分量才产生沿 MN 方向的洛伦兹力，实际有效分量小于 B；若仍代入全 B，由 U0∝BQ 反推 Q 会偏小","do":"把 B 分解，取垂直于速度且垂直于 MN 的分量代入 U0 表达式，比较代入值与有效值","expr":"U_0\\propto B_{\\perp}Q","cues":["取垂直分量","有效磁场变小","测得的流量偏小"],"concepts":["磁场分解","有效分量"]}],"229":[{"title":"反粒子电荷结构等价","type":"前提判断","judge":"反氢原子中正电子绕反质子运动，其电磁相互作用结构与氢原子是否完全相同","why":"库仑力只依赖电荷的量和符号组合，正电子与反质子电荷等量异种，与电子—质子体系完全对应","do":"比较反氢原子与氢原子的两体电荷组合，确认能级结构不因粒子反性而改变","expr":"E_n=-\\dfrac{13.6\\,\\mathrm{eV}}{n^2}","cues":["电荷结构一样","能级不变","质量相等"],"concepts":["库仑力","能级结构","反粒子"]},{"title":"衰变方程守恒校验","type":"关系建立","judge":"中子转化为质子加正电子的过程是否同时满足电荷数与核子数守恒","why":"任何粒子反应都必须遵守电荷守恒，反应前后总电荷必须相等","do":"写出反应式，核对两侧电荷数与质量数","expr":"{}^{1}_{0}\\mathrm{n}\\to{}^{1}_{1}\\mathrm{p}+{}^{0}_{1}\\mathrm{e}","cues":["电荷数对不上","左边中性右边带正电","守恒没满足"],"concepts":["电荷守恒","β衰变"]},{"title":"单光子动量守恒","type":"临界条件","judge":"一对静止正负电子湮灭时能否只产生一个光子","why":"湮灭前总动量为零，单个光子动量不为零，无法同时满足动量守恒与能量守恒","do":"在质心系中比较湮灭前后总动量，判断光子数下限","expr":"\\vec p_{\\text{前}}=0,\\quad \\vec p_\\gamma\\neq 0","cues":["至少两个光子","一个光子动量不为零","质心系看动量"],"concepts":["动量守恒","光子","湮灭"]},{"title":"反氘核聚变能方向","type":"结论整理","judge":"反氘核聚变与普通氘核聚变一样是放能还是吸能","why":"反物质体系与正物质体系遵循相同的核力与结合能规律，比结合能变化方向相同","do":"对比反应前后核子比结合能，判断能量是释放还是吸收","expr":"\\Delta E=\\Delta m c^2","cues":["聚变放能","和普通核一样","结合能变大"],"concepts":["核聚变","结合能","质能方程"]}],"230":[{"title":"声线类比光线折射","type":"模型选择","judge":"要判断能否把声波在温度分层空气中的弯曲传播当作光线在变折射率介质中的折射来处理","why":"题干明确说声波传播规律与光波类似、用声线描述路径，只有建立声线与光线的类比，才能用折射定律分析声线弯曲","do":"把每条声线看成光线，把不同温度的空气层看成不同折射率的介质层，声线向法线偏折对应折射率变大","expr":"","cues":["类比光线","当成折射","声线就是光线"],"concepts":["折射定律","声线","折射率"]},{"title":"由偏折方向定折射率","type":"关系建立","judge":"要判断声线向地面传播时是靠近法线还是远离法线，从而确定近地面折射率是变大还是变小","why":"由图可看出声线向地面弯曲时与法线夹角减小，折射定律要求从光疏介质进入光密介质时折射角小于入射角","do":"在声线与两种温度层的分界面处画法线，比较入射角和折射角的大小，得出近地面折射率更大","expr":"n=\\frac{\\sin\\theta_1}{\\sin\\theta_2}","cues":["看偏折方向","靠近法线","折射率变大"],"concepts":["折射定律","法线","折射率"]},{"title":"折射率反推声速与温度","type":"关系建立","judge":"要判断近地面折射率大对应声速大还是小，进而判断温度高低","why":"类比光在介质中速度与折射率成反比，且题设温度越高声速越大，两个关系联立才能定出温度分布","do":"由折射率大推出声速小，再由声速小推出温度低，得到近地面温度低于高处","expr":"v=\\frac{c}{n},\\quad v\\propto T","cues":["折射率大速度小","速度小温度低","地面更冷"],"concepts":["波速与折射率","声速与温度"]},{"title":"频率不变推波长变化","type":"前提判断","judge":"要判断声波从高处传到低处时频率是否改变，才能由声速变化推出波长变化","why":"频率由声源决定，跨介质传播时频率不变，而波速随温度改变，故波长必随之改变","do":"认定频率不变，用波速与波长、频率的关系比较 M、N 两处的波长","expr":"v=\\lambda f","cues":["频率不变","波速变小","波长变短"],"concepts":["频率","波长","波速"]},{"title":"声线路径可逆性","type":"结论整理","judge":"要判断把声源移到 N 点后声波能否沿原声线反向回到 S 点","why":"光路可逆是折射定律的必然推论，声线类比光线后同样满足路径可逆","do":"将传播方向反转，检查各层界面上的入射角与折射角互换后仍满足折射定律","expr":"","cues":["光路可逆","反过来走","沿原路返回"],"concepts":["光路可逆","折射定律"]}],"231":[{"title":"单摆计时位置","type":"实验操作","judge":"测单摆周期时应在摆球经过最低点还是最高点开始计时","why":"摆球在最低点速度最大，经过该位置的时间最短，计时起止判断误差最小；最高点速度为零，计时起止难以判定","do":"比较摆球在最高点与最低点的速度大小，确定计时起点选在平衡位置","expr":"","cues":["最低点速度最大","最高点不好掐表","平衡位置计时"],"concepts":["单摆周期","计时误差"]},{"title":"变压器测电压挡位","type":"前提判断","judge":"测变压器原副线圈电压应选多用电表的直流电压挡还是交流电压挡","why":"变压器只对交变电流起作用，原副线圈电压均为交变电压，必须用交流电压挡测量","do":"根据变压器工作原理判断线圈两端电压的性质，选择对应挡位","expr":"","cues":["变压器通交流","电压是交变的","不能用直流挡"],"concepts":["电磁感应","交变电压","多用电表"]},{"title":"欧姆调零的先后","type":"实验操作","judge":"用多用电表测电阻前是否必须先短接表笔进行欧姆调零","why":"欧姆挡内部电池电动势和内阻会变化，换挡后指针零点漂移，不调零则读数系统偏差","do":"确认测电阻前选倍率后短接红黑表笔、调欧姆调零旋钮使指针指欧姆零点的操作顺序","expr":"","cues":["先选倍率再调零","表笔短接","指针指到零欧姆"],"concepts":["欧姆挡","欧姆调零"]},{"title":"单缝双缝的排列","type":"模型选择","judge":"图(a)中A、B两位置哪个装单缝、哪个装双缝","why":"双缝干涉要求光先经单缝成为线光源，再经双缝分成两束相干光，故单缝在前、双缝在后","do":"沿光路从光源出发判断先后顺序，确定A为单缝、B为双缝","expr":"","cues":["单缝在前","双缝在后","先滤成线光源"],"concepts":["双缝干涉","相干光源"]},{"title":"螺旋测微器读数","type":"数据处理","judge":"主尺读数与可动刻度读数如何组合，可动刻度是否需估读","why":"螺旋测微器精度为0.01 mm，需估读到0.001 mm，固定刻度读出整毫米及半毫米，可动刻度对齐格数乘0.01 mm","do":"读固定刻度整毫米数，再看可动刻度与基准线对齐的格数（含估读半格），相加","expr":"$d=3\\,\\mathrm{mm}+18.5\\times0.01\\,\\mathrm{mm}$","cues":["主尺加可动","要估读一位","半毫米刻度看露没露"],"concepts":["螺旋测微器","估读"]},{"title":"断路位置的电路推断","type":"关系建立","judge":"由各接线柱间表头是否偏转，反推哪条支路断开","why":"欧姆挡提供电源，只有表头所在回路闭合指针才偏转；A、B间不偏转而经C的两路都偏转，说明断开处在A、B之间的公共支路上","do":"分别画出接A、B与接A、C、B、C时的电流通路，找出使A、B间断路而其余通路完好的元件","expr":"","cues":["看回路通不通","AB之间断了","经C能绕通"],"concepts":["闭合电路","断路检测","欧姆挡"]}],"232":[{"title":"操作顺序的因果","type":"实验操作","judge":"先调滑轮、先通电还是先放小车，哪个动作必须排在前面","why":"细线不平行木板会使拉力方向偏离运动方向；打点计时器需先稳定打点再让纸带运动，否则起始段点迹缺失或混乱","do":"按'调装置→启动计时器→释放研究对象'的因果链排序三个步骤","expr":"","cues":["先调滑轮","先接通电源","最后放小车"],"concepts":["打点计时器使用规范","细线平行木板"]},{"title":"由点距判断连接端","type":"前提判断","judge":"纸带哪一端与小车相连，即点距由小变大的方向对应运动起点","why":"小车从静止开始做匀加速运动，速度逐渐增大，相同时间间隔内的位移逐渐增大","do":"比较纸带两端相邻计数点的间距大小，间距小的一端为起始端，与小车相连","expr":"","cues":["点距越来越大","速度越来越大","间距小的是起点"],"concepts":["匀变速直线运动","位移随时间增大"]},{"title":"中间时刻速度替代","type":"关系建立","judge":"求B点瞬时速度时，能否用A到C的平均速度代替","why":"匀变速直线运动中，某段时间内的平均速度等于该段时间中间时刻的瞬时速度，B恰为A、C的中间时刻","do":"写出A到C的位移与总时间2T之比，作为B点的瞬时速度","expr":"$v_B=\\frac{x_{AC}}{2T}$","cues":["用平均速度代替","B是中间时刻","位移除以总时间"],"concepts":["中间时刻瞬时速度","平均速度"]},{"title":"逐差法求加速度","type":"数据处理","judge":"用哪两段位移差和几个T²来算加速度，避免逐段相减造成误差","why":"匀变速直线运动中连续相等时间间隔的位移差为常量aT²，用相隔两段作差可减小偶然误差","do":"取CE段与AC段位移之差，除以对应时间间隔平方的4倍","expr":"$a=\\frac{x_{CE}-x_{AC}}{4T^{2}}$","cues":["逐差法","隔段作差","除以四倍时间平方"],"concepts":["逐差法","匀变速直线运动规律"]},{"title":"纸带速度对应圆盘线速度","type":"模型选择","judge":"纸带通过计时器的速度与圆盘边缘M点的线速度是什么关系","why":"纸带一端固定在圆盘边缘，纸带被拉出的速率等于M点做圆周运动的线速度","do":"把求得的B点速度直接作为M点在该时刻的线速度，再代入向心加速度公式","expr":"$a_n=\\frac{v_B^{2}}{R}$","cues":["纸带速度就是线速度","M点做圆周运动","用向心加速度公式"],"concepts":["线速度","向心加速度"]}],"233":[{"title":"最高点速度为零","type":"前提判断","judge":"竖直上抛到最高点时速度是否为零，能否用速度公式反推初速度","why":"最高点是速度方向由向上变为向下的转折点，竖直方向速度必为零，这是求初速度的唯一依据","do":"对上升阶段列速度公式，令末速度为零，解出初速度","expr":"0=v_{0}-gt","cues":["最高点速度为零","上升时间就是t"],"concepts":["竖直上抛运动","速度公式"]},{"title":"爆炸瞬间动量守恒","type":"模型选择","judge":"炸裂瞬间应选哪个守恒定律，内力远大于外力时动量是否守恒","why":"爆炸时间极短，重力的冲量可忽略，系统所受合外力冲量近似为零，动量守恒成立；爆炸过程机械能不守恒，不能用能量守恒","do":"取爆炸前整体为初态、A 与 B 为末态，列动量守恒方程","expr":"p_{初}=p_{A}+p_{B}","cues":["爆炸时间极短","内力远大于重力","不能用能量守恒"],"concepts":["动量守恒定律","爆炸模型"]},{"title":"动量守恒分方向","type":"关系建立","judge":"动量守恒应沿哪个方向列式，爆炸前总动量在该方向上是多少","why":"爆炸前物体在最高点竖直速度为零，总动量为零；炸裂后 A 沿水平飞出，故只需沿水平方向列动量守恒","do":"沿水平方向列式，把 A 的动量与 B 的动量相加等于零，解出 B 的速度","expr":"0=2mv+mv_{B}","cues":["只沿水平方向","爆炸前总动量为零"],"concepts":["动量矢量性","分方向守恒"]},{"title":"速度正负号含义","type":"数学处理","judge":"解出的 B 速度为负值代表什么，题目问的“大小”该取什么","why":"动量守恒是矢量式，负号表示 B 的运动方向与 A 相反，而速度大小只取绝对值","do":"由方程解出带符号的 v_B，取绝对值作为速度大小","expr":"v_{B}=-2v,\\quad |v_{B}|=2v","cues":["负号表示反向","问的是大小"],"concepts":["矢量方向","速率"]},{"title":"下落时间对称","type":"前提判断","judge":"炸裂后两部分的下落时间是否等于上升时间 t","why":"炸裂不改变竖直方向初速度（仍为零），下落高度与上升高度相同，竖直方向为自由落体，由对称性下落时间等于上升时间","do":"比较上升高度与下落高度，确认下落时间取 t，再算水平位移","expr":"h=\\tfrac12gt^{2}","cues":["竖直方向初速为零","上升下落对称"],"concepts":["竖直上抛对称性","自由落体"]},{"title":"反向水平位移相加","type":"几何关系","judge":"A、B 落地点间距是两水平位移之差还是之和","why":"A、B 从同一点沿相反方向水平抛出，落地点分居抛出点正下方两侧，间距等于两段水平位移大小之和","do":"分别求两部分的水平位移大小，再相加得落地点间距","expr":"d=|x_{A}|+|x_{B}|=vt+2vt","cues":["两边分开落","距离要相加"],"concepts":["平抛运动","位移合成"]}],"234":[{"title":"垂直入射判圆周","type":"前提判断","judge":"速度方向与磁场垂直时，粒子是否做匀速圆周运动、洛伦兹力是否始终不做功","why":"洛伦兹力始终垂直于速度，只改变方向不改变速率，故为匀速率圆周运动；若速度与磁场平行则不受洛伦兹力","do":"由速度与磁场夹角判断粒子1做圆周运动、粒子2做匀速直线运动","expr":"","cues":["垂直才转圈","平行不受力","力不做功"],"concepts":["洛伦兹力","匀速圆周运动"]},{"title":"向心力定半径周期","type":"关系建立","judge":"用哪个力充当向心力，以及半径与周期如何由同一组量表示","why":"匀强磁场中洛伦兹力提供向心力，结合圆周运动周期定义才能把T与m、q、B联系起来","do":"列洛伦兹力等于向心力的方程，解出R，再代入周期定义式消去v","expr":"q_{0}vB=m\\dfrac{v^{2}}{R},\\quad T=\\dfrac{2\\pi R}{v}=\\dfrac{2\\pi m}{q_{0}B}","cues":["洛伦兹力当向心力","先求半径再求周期","消掉速度"],"concepts":["向心力","回旋周期"]},{"title":"同时间联系两粒子","type":"关系建立","judge":"两个粒子用什么共同的量把各自的速度表达出来","why":"题设给出相同时间t，粒子1转过的圆心角θ与粒子2走过的距离d分别是各自在这段时间内的运动记录","do":"对粒子1用角速度写线速度，对粒子2用匀速直线运动写速度，再取比值消去t","expr":"v_{1}=\\dfrac{\\theta R}{t},\\quad v_{2}=\\dfrac{d}{t},\\quad \\dfrac{v_{1}}{v_{2}}=\\dfrac{\\theta R}{d}","cues":["用同一个时间","角速度乘半径","比值消掉时间"],"concepts":["角速度","线速度"]},{"title":"质量相等桥接动量","type":"关系建立","judge":"求粒子2动量时，如何借助粒子1的圆周运动信息得到共同的质量m","why":"两粒子质量相等，粒子1的半径关系给出m与v1的约束，粒子2动量需用同一个m","do":"由粒子1的向心力方程解出m，再乘粒子2的速度得p2，最后代入速度比消去v1、v2","expr":"m=\\dfrac{qBR}{v_{1}},\\quad p_{2}=mv_{2}=qBR\\dfrac{v_{2}}{v_{1}}=\\dfrac{qBd}{\\theta}","cues":["质量相等是关键","用粒子1求质量","动量等于质量乘速度"],"concepts":["动量","质量相等"]}],"235":[{"title":"牵引力做功的规律选择","type":"模型选择","judge":"求变力（牵引力）做功，是直接用功的定义式还是用动能定理","why":"牵引力大小未知且可能变化，无法用 W=Fs 直接求；而阻力、位移、初末速度都已知，动能定理把功与速度变化直接联系起来","do":"对飞机从静止到速度 v 的过程列动能定理，把牵引力做功、阻力做功、动能变化三项写全","expr":"W-fx=\\frac{1}{2}mv^{2}","cues":["用动能定理","牵引力大小不知道","别用功的定义式"],"concepts":["动能定理","变力做功"]},{"title":"阻力做功的符号","type":"关系建立","judge":"阻力做的功在动能定理中取正还是取负","why":"阻力方向与位移方向相反，做负功，动能定理中合力功等于各力功的代数和","do":"把阻力做功写成 -fx，与牵引力做功 W 相加作为合功","expr":"W_{\\text{合}}=W-fx","cues":["阻力做负功","方向相反","代数和"],"concepts":["负功","合力功"]},{"title":"放弃起飞的临界速度","type":"临界条件","judge":"在距起点 d 处决定放弃时，飞机应恰好处于什么速度状态","why":"超过该位置就不能放弃，说明该位置是能否安全停下的分界，临界情形是飞机加速到该处后立即以最大减速加速度减速，到跑道末端速度恰好为零","do":"设该处速度为 v_m，把加速段和减速段用同一速度 v_m 衔接，减速段位移取 L-d","expr":"v_m^{2}=2a_1 d,\\quad v_m^{2}=2a_2(L-d)","cues":["末端速度刚好为零","临界位置","加速到这就减速"],"concepts":["临界状态","匀变速直线运动"]},{"title":"两段位移的衔接","type":"几何关系","judge":"加速段位移与减速段位移如何用跑道总长 L 联系","why":"飞机从起点到跑道末端全程都在跑道上，加速段长 d、减速段长 L-d，两段之和等于跑道长","do":"写出加速位移 d 与减速位移 L-d 之和为 L，并与速度位移关系联立消去 v_m","expr":"d+(L-d)=L","cues":["两段加起来是跑道长","减速距离是L减d"],"concepts":["位移关系","分段运动"]},{"title":"气流模型的建立","type":"模型选择","judge":"把机翼对气流的力看成什么模型来求，气流质量如何取","why":"升力来源于气流方向改变带来的动量变化，需用动量定理，且只有撞到机翼面积 S 上的气流才参与动量改变","do":"取一段时间 Δt 内掠过机翼面积 S 的气柱为研究对象，质量用密度乘体积表示，体积为 S 乘气流速度乘 Δt","expr":"\\Delta m=\\rho S u\\,\\Delta t","cues":["取气柱为对象","用动量定理","质量用密度乘体积"],"concepts":["动量定理","流体模型"]},{"title":"动量变化与速度成正比","type":"近似条件","judge":"气流速度变化量 Δv 与来流速率 u 成什么关系","why":"气流掠过机翼后方向改变但速率量级不变，偏转角基本不随 u 变化，故速度变化量的大小与 u 成正比","do":"由动量定理写出 FΔt=Δm·Δv，代入 Δm 后得 F∝u·Δv，再由 Δv∝u 得 F 与 u 的幂次关系","expr":"F\\Delta t=\\Delta m\\,\\Delta v,\\quad \\Delta v\\propto u","cues":["偏转角不变","速度变化跟来流同比例","方向变了大小差不多"],"concepts":["动量变化","正比关系"]}],"236":[{"title":"负电荷做功正负","type":"前提判断","judge":"负电荷从低电势的 B 极移向高电势的 A 极，静电力做正功还是负功，功该用 Q 乘电势差还是乘电势差的相反数","why":"静电力做功 W=qU_AB，负电荷 q=-Q，且 A 极接正极、B 极接负极，U_AB=U>0","do":"写出 W=(-Q)(φ_B-φ_A)，代入 φ_A-φ_B=U 定出符号","expr":"W=(-Q)(\\varphi_B-\\varphi_A)=QU","cues":["负电荷往高电势走","电场力做正功","别丢负号"],"concepts":["电势差","电场力做功","电势能"]},{"title":"向心力来源与动能","type":"关系建立","judge":"圆周运动的向心力由谁提供，以及由 qE=mv²/r 与 E=k·2λ/r 联立后动能是否与半径无关","why":"粒子只受径向电场力，电场力充当向心力；E∝1/r 使 r 在方程两边约去","do":"列 qE=mv²/r，代入 E 的表达式，解出 mv² 再求 Ek","expr":"qk\\frac{2\\lambda}{r}=m\\frac{v^{2}}{r}\\Rightarrow E_k=\\frac12 mv^{2}=qk\\lambda","cues":["电场力当向心力","半径约掉了","动能是常数"],"concepts":["向心力","电场力","动能"]},{"title":"电势能零点与积分","type":"模型选择","judge":"电势能零点取在哪里，以及如何由 E∝1/r 积分得到半径 r 处的电势能","why":"只有先定零势能点（取无穷远为 0）才能写出 Ep(r)；E 随 r 变化不能直接用 Er 乘距离","do":"取无穷远电势能为零，对 E=k·2λ/r 从无穷远积到 r，用 W=-ΔEp 得 Ep","expr":"E_p(r)=2qk\\lambda\\ln r","cues":["零点取无穷远","电场不是匀强","要积分不能直接乘"],"concepts":["电势能","电势零点","非匀强电场做功"]},{"title":"总能量随半径的单调性","type":"数学处理","judge":"总能量 E=Ek+Ep 中 Ek 为常数、Ep 随 ln r 增大，故 E 随 r 单调增，需比较的是 ln r 的增量而非 r 的增量","why":"Ek=qkλ 与 r 无关，Ep=2qkλln r 随 r 递增，总能量差完全由对数项决定","do":"写出 E(r)=qkλ+2qkλln r，把两个能量差化为 2qkλ 乘 ln r 的差","expr":"E_3-E_2=2qk\\lambda\\ln\\frac{r_3}{r_2},\\quad E_2-E_1=2qk\\lambda\\ln\\frac{r_2}{r_1}","cues":["动能不变","电势能随半径变大","比对数"],"concepts":["总能量","对数函数","能量差"]},{"title":"凹函数比较等距增量","type":"数学处理","judge":"r 等间距时，ln r 的增量是递减还是递增，从而判断两个能量差的大小","why":"ln x 的二阶导数为 -1/x²<0，是上凸（凹）函数，等距自变量增量对应的函数增量随 x 增大而减小","do":"由 r₃-r₂=r₂-r₁ 得 r₂/r₁>r₃/r₂，比较两个对数比，或用凹函数性质 ln r₂>(ln r₁+ln r₃)/2","expr":"\\ln\\frac{r_3}{r_2}<\\ln\\frac{r_2}{r_1}\\Rightarrow E_3-E_2<E_2-E_1","cues":["等间距但比值变小","对数增长越来越慢","上凸函数"],"concepts":["凹函数性质","对数函数","增量比较"]},{"title":"外电场电离的能量判据","type":"临界条件","judge":"外电场电离基态氢原子时，是让电子获得的能量等于电离能，还是等于基态能量的绝对值，以及电子在电场中移动的有效距离取多少","why":"电离即把电子从基态轨道移到无穷远，所需能量等于基态能量的绝对值 |E₀|；外电场对电子的做功近似为 eEa（沿轨道尺度 a 的位移）","do":"令 eEa=|E₀|（或由 ke²/a²=mv²/a 得 Ek=ke²/2a、Ep=-ke²/a，相加得电离能 ke²/2a），解出 E 并代入数据","expr":"eEa=|E_0|=\\frac{ke^{2}}{2a}\\Rightarrow E=\\frac{ke}{2a^{2}}","cues":["电场做功按轨道尺度算","先算电离能再除以ea"],"concepts":["电离能","玻尔模型","电场力做功"]}],"237":[{"title":"平均速度用位移算","type":"前提判断","judge":"求平均速度时，分子该用位移还是路程","why":"平均速度定义为位移与时间的比值，不是路程与时间的比值；本题返回舱一直下降，位移大小等于下降的高度差","do":"确认返回舱单向下降，位移大小等于高度差，用位移除以时间","expr":"\\bar v=\\frac{\\Delta h}{t}","cues":["用位移不用路程","一直下降"],"concepts":["平均速度","位移"]},{"title":"高度差取两高度之差","type":"关系建立","judge":"位移大小该由哪两个高度相减得到","why":"题给的是两个时刻的高度，位移是末位置减初位置，必须用 3090 m 与 2010 m 作差，不能把某个高度直接当位移","do":"用初末高度作差求下降的位移大小","expr":"\\Delta h=3090-2010=1080\\ \\mathrm{m}","cues":["两高度相减","别拿单个高度"],"concepts":["位移","高度差"]},{"title":"时间取对应过程","type":"前提判断","judge":"时间该取 130 s 还是别的量","why":"130 s 正是从 3090 m 降到 2010 m 所经历的时间，位移与时间必须对应同一段过程","do":"把 1080 m 的位移与 130 s 配对代入","expr":"t=130\\ \\mathrm{s}","cues":["时间和位移要配套","就用130秒"],"concepts":["过程对应","时间"]},{"title":"估算结果量级","type":"数学处理","judge":"1080 除以 130 的结果落在哪个数量级","why":"选项之间差一个数量级，只要判断出结果约为 8 而非 80 或 0.8，就能排除把高度差或时间用错的干扰项","do":"做除法并保留一位有效数字，与各选项比对","expr":"\\bar v=\\frac{1080}{130}\\approx 8.3\\ \\mathrm{m/s}","cues":["大概八点几","先看数量级"],"concepts":["平均速度","数量级估算"]}],"238":[{"title":"识别衍射明显条件","type":"前提判断","judge":"判断衍射现象是否明显取决于什么物理量","why":"波通过尺寸与其波长相近或更小的障碍物/狭缝时衍射才明显，即要比较波长与缝宽的大小关系，而不是比较粒子速度或质量本身","do":"明确判据：缝宽 d 与粒子德布罗意波长 λ 相近或 λ 更大时衍射最明显","expr":"\\lambda \\gtrsim d","cues":["波长和缝宽比","看波长够不够大","尺寸相近才明显"],"concepts":["衍射","波长","缝宽"]},{"title":"粒子波动性用德布罗意波长","type":"模型选择","judge":"判断把粒子束当作波处理时该用哪个波长量","why":"粒子束的波动性由德布罗意关系 λ=h/p 给出，动量越大波长越短，波动性越弱","do":"对每种粒子写出 λ=h/p=h/(mv)，把粒子质量、速度代入比较","expr":"\\lambda=\\frac{h}{p}=\\frac{h}{mv}","cues":["用德布罗意波长","算波长比大小","动量越大波长越短"],"concepts":["德布罗意波","动量","普朗克常量"]},{"title":"同速下质量决定波长","type":"关系建立","judge":"判断在速度相同的前提下，粒子质量与波长的大小关系","why":"λ=h/(mv) 中 h、v 相同，λ 与 m 成反比，质量越小波长越长，越容易满足 λ 与缝宽相近","do":"比较各选项粒子的质量，找出质量最小者对应最长波长","expr":"\\lambda \\propto \\frac{1}{m}\\ (v\\text{ 相同})","cues":["质量越小波长越长","电子最轻","比质量就行"],"concepts":["德布罗意波","质量","反比关系"]},{"title":"估算波长与缝宽量级","type":"数学处理","judge":"判断电子波长与 3.5×10⁻¹⁰ m 缝宽是否同数量级","why":"只有把 λ 的数值量级与缝宽 d 比较，才能确认哪个粒子的 λ/d 最接近或超过 1","do":"用 λ=h/(mv) 估算电子等粒子的波长数量级，与 d=3.5×10⁻¹⁰ m 比较","expr":"\\frac{\\lambda}{d}\\sim 1","cues":["估一下数量级","和缝宽比一比","看谁最接近"],"concepts":["数量级估算","德布罗意波长","缝宽"]}],"239":[{"title":"库仑力随距离变化","type":"关系建立","judge":"比较各点到 O 的距离，判断库仑力大小随距离如何变化","why":"库仑力大小与到点电荷距离的平方成反比，距离越大受力越小","do":"分别找出 b、e 到 O 的距离，比较两者大小后判断受力大小","expr":"F=\\frac{kQq}{r^{2}}","cues":["距离越大受力越小","看离圆心多远"],"concepts":["库仑定律","点电荷"]},{"title":"电势能随距离变化","type":"关系建立","judge":"判断沿管道各段到 O 的距离如何变化，从而判断电势能如何变化","why":"点电荷电势与距离成反比，电势能等于电荷量乘电势，同号电荷距离越远电势能越小","do":"分段看 c→d、d→e 到 O 的距离是否变化，再判断电势能增减","expr":"\\varphi=\\frac{kQ}{r},\\quad E_p=q\\varphi","cues":["先看距离变不变","同号电荷越远势能越小"],"concepts":["电势","电势能"]},{"title":"能量守恒联系动能","type":"模型选择","judge":"判断管道光滑、只有库仑力做功时机械能（动能加电势能）是否守恒","why":"管道光滑无摩擦，库仑力是保守力，只有保守力做功则动能与电势能之和不变","do":"对任意两点列动能加电势能相等的式子，由电势能大小反推动能大小","expr":"E_k+E_p=\\text{常量}","cues":["光滑没有摩擦","动能加势能不变"],"concepts":["能量守恒","保守力做功"]},{"title":"速度大小由动能反推","type":"结论整理","judge":"由动能大小关系判断对应点速度大小关系","why":"质量不变时动能越大速度越大，动能与速度平方成正比","do":"比较 a 与 b、d 与 f 的电势能，得动能关系后再比较速度","expr":"E_k=\\frac{1}{2}mv^{2}","cues":["动能大速度就大","势能小的地方快"],"concepts":["动能","速度"]}],"240":[{"title":"活塞受力平衡定压强","type":"前提判断","judge":"活塞自由稳定时，封闭气体压强是否等于外界大气压","why":"活塞质量不计摩擦，只有大气压力和气体压力平衡，故气体压强始终等于外界大气压，与体积、温度无关","do":"对活塞列力平衡，比较内外压力","expr":"pS=p_0S \\Rightarrow p=p_0","cues":["活塞受力平衡","压强等于大气压","压强不变"],"concepts":["力平衡","封闭气体压强"]},{"title":"分清两段过程的条件","type":"模型选择","judge":"a→b 与 b→a 两段各自哪个量被约束不变","why":"a→b 气缸浸入恒温冷水，气体与外界换热且活塞自由，是等压过程；b→a 保持气缸不动、外力提活塞，是等温过程","do":"分别标出两段过程的温度、压强、体积变化趋势","expr":"a\\to b:\\ p\\ \\text{不变};\\quad b\\to a:\\ T\\ \\text{不变}","cues":["先分两段","冷水恒温","外力提活塞"],"concepts":["等压过程","等温过程","理想气体状态方程"]},{"title":"判断内能随温度变化","type":"关系建立","judge":"两段过程中气体内能如何变化","why":"一定质量理想气体内能只由温度决定，a→b 温度降低内能减小，b→a 温度不变内能不变","do":"比较初末温度，判断内能增减","expr":"\\Delta U\\propto \\Delta T","cues":["内能看温度","温度降内能减","温度不变内能不变"],"concepts":["理想气体内能","温度"]},{"title":"等温压缩压强关系","type":"关系建立","judge":"b→a 体积增大时压强如何变化","why":"温度不变时玻意耳定律给出 pV 为常量，体积增大压强必减小","do":"对 b→a 段用玻意耳定律比较 a、b 两处压强","expr":"p_aV_a=p_bV_b,\\ V_a>V_b\\Rightarrow p_a<p_b","cues":["等温用玻意耳","体积大压强小","回到a压强变小"],"concepts":["玻意耳定律","等温变化"]}],"241":[{"title":"摆长定周期顺序","type":"前提判断","judge":"由摆长从左到右递增，判断四个单摆周期的大小顺序","why":"单摆周期 T=2π√(L/g) 只由摆长决定，摆长越长周期越大","do":"比较甲、乙、丙、丁的摆长，写出周期由小到大的排列","expr":"T=2\\pi\\sqrt{L/g}","cues":["摆长越长越慢","周期看摆长"],"concepts":["单摆周期","摆长"]},{"title":"同侧异侧定相位","type":"关系建立","judge":"把“同侧最高点”和“另一侧最高点”翻译成各球所用时间与自身周期的倍数关系","why":"从同一释放侧出发，回到同侧最高点经历整数个周期，到另一侧最高点经历半周期的奇数倍","do":"对甲、乙、丙、丁分别写出 2T甲、3T乙/2、T丙、T丁/2 并令其相等","expr":"2T_{\\text{甲}}=\\frac{3T_{\\text{乙}}}{2}=T_{\\text{丙}}=\\frac{T_{\\text{丁}}}{2}","cues":["同侧是整周期","另一侧是半周期","先数半周期"],"concepts":["简谐运动周期性","相位"]},{"title":"周期比转摆长比","type":"数学处理","judge":"由周期之比换算摆长之比时，判断应取周期的平方比而非一次比","why":"T∝√L，故 L∝T²，周期比要平方才得摆长比","do":"先由连等式求出各周期与 T甲 的比值，再平方得到摆长比","expr":"L_{\\text{丙}}:L_{\\text{丁}}=T_{\\text{丙}}^2:T_{\\text{丁}}^2","cues":["周期比要平方","别直接当摆长比"],"concepts":["单摆周期公式","比例运算"]},{"title":"特定时刻定状态","type":"临界条件","judge":"判断甲第一次回到释放位置时丙所处的位置，以及丁第一次回平衡位置时乙所处的位置","why":"由已得的周期比例确定该时刻各球走过的周期份额，份额为整数周期或半周期时在最高点，为四分之一周期奇数倍时在平衡位置","do":"用 T丙=2T甲 判断丙在另一侧最高点；用 T丁=3T乙 判断乙在平衡位置","expr":"t=T_{\\text{甲}}=\\frac{T_{\\text{丙}}}{2},\\quad t=\\frac{T_{\\text{丁}}}{4}=\\frac{3T_{\\text{乙}}}{4}","cues":["看走了几个周期","最高点速度为零","平衡位置速度最大"],"concepts":["简谐运动位移","加速度与速度"]}],"242":[{"title":"信号强弱对应距离","type":"模型选择","judge":"信号强度随时间变化反映的是卫星与观测站之间距离的远近变化，而不是卫星本身的亮度或功率变化","why":"卫星持续发射信号，接收强度只由卫星到观测站的距离决定，距离最近时信号最强、最远时最弱","do":"把图像中信号强度的极大值对应卫星与观测站相距最近（卫星在观测站正上方），极小值对应相距最远（卫星在地球另一侧）","expr":"","cues":["强度看距离","最近最强","最远最弱"],"concepts":["信号强度","距离变化"]},{"title":"两次最强的时间间隔","type":"图像读取","judge":"图像中相邻两次信号最强（或相邻两次最弱）之间的时间间隔对应什么运动学量","why":"卫星与观测站都在转动，信号最强要求两者相对位置回到同一状态，间隔由两者的相对角速度决定","do":"读出图像中相邻两个信号强度峰值之间的时间间隔，把它与地球自转周期 T 比较","expr":"","cues":["读峰值间隔","看相邻最强","和T比"],"concepts":["周期","图像读取"]},{"title":"相对角速度定周期","type":"关系建立","judge":"卫星与观测站同向转动时，信号强弱变化的周期由两者角速度之差决定，而不是卫星周期本身","why":"同向转动时相对角速度等于两者角速度之差，相对位置每转一圈（相对转过 2π）信号强弱重复一次","do":"用相对角速度乘峰值间隔等于 2π 列方程，把峰值间隔用 T 表示后解出卫星周期 T'","expr":"(2π/T' - 2π/T)·Δt = 2π","cues":["同向要相减","相对转一圈","角速度差"],"concepts":["相对角速度","角速度差"]},{"title":"引力提供向心力","type":"关系建立","judge":"卫星做匀速圆周运动的向心力完全由万有引力提供，中心天体质量用地球质量 M","why":"卫星只受地球引力，轨道为圆轨道，万有引力充当向心力","do":"对卫星列万有引力等于向心力的方程，把上一步得到的 T' 代入解出轨道半径 r","expr":"G Mm/r² = m(4π²/T'²)r","cues":["引力当向心力","用地球质量","代卫星周期"],"concepts":["万有引力","向心力","圆周运动"]}],"243":[{"title":"判断物块相对小车的运动方向","type":"前提判断","judge":"物块相对小车是向上滑还是向下滑，即摩擦力方向朝哪","why":"物块随小车沿斜面向上加速，需要判断最大静摩擦能否提供足够加速度；μmgcos30°=0.75mg 大于 mgsin30°=0.5mg，物块相对小车有下滑趋势，摩擦力沿斜面向上","do":"比较 μmgcos30° 与 mgsin30° 的大小，确定物块所受摩擦力方向","expr":"\\mu mg\\cos30^\\circ > mg\\sin30^\\circ","cues":["摩擦力向上","物块跟不上小车","先比摩擦力和重力分量"],"concepts":["静摩擦","最大静摩擦力","相对运动趋势"]},{"title":"求物块加速度与位移","type":"关系建立","judge":"物块做匀加速直线运动，能否用牛顿第二定律加运动学公式求其位移","why":"物块受恒定的重力分量和滑动摩擦力，加速度恒定，且初速度为零、末速度为 v0","do":"对物块列牛顿第二定律求 a，再用 v0²=2ax1 求物块位移","expr":"\\mu mg\\cos30^\\circ-mg\\sin30^\\circ=ma,\\quad v_0^2=2ax_1","cues":["物块匀加速","先求加速度","用速度位移公式"],"concepts":["牛顿第二定律","匀变速直线运动"]},{"title":"区分小车与物块的位移","type":"关系建立","judge":"小车位移与物块位移是否相同，求小车位移该用哪个方程","why":"两者速度相同时加速度不同、位移不同，物块位移不能直接当作小车位移；小车位移须由小车的动能定理单独求","do":"对小车用动能定理，注意摩擦力方向与位移方向相反，且拉力做功为 Pt","expr":"Pt-(\\mu mg\\cos30^\\circ+mg\\sin30^\\circ)x=\\tfrac12 mv_0^2","cues":["位移不一样","小车单独列动能定理","拉力做功是功率乘时间"],"concepts":["动能定理","变力做功","功率"]},{"title":"用速度关系消去时间","type":"数学处理","judge":"时间 t 未知，能否用物块的速度关系 t=v0/a 把它消掉","why":"物块加速度已知且初速为零，速度达到 v0 所用时间即为全过程时间，可把 t 用 v0 和 a 表示","do":"由 t=v0/a 代入小车动能定理方程，解出小车位移 x","expr":"t=\\frac{v_0}{a}=\\frac{4v_0}{g}","cues":["时间用速度比加速度","消掉t","两段运动时间相同"],"concepts":["匀变速运动时间关系","方程消元"]},{"title":"机械能增量含势能与动能","type":"结论整理","judge":"求机械能增量时是否同时计入动能增量和重力势能增量","why":"机械能包括动能与重力势能，斜面上升过程两者都变，只算动能会漏项","do":"分别对物块和小车写 ΔE=½mv0²+mgx sin30°，代入各自位移比较","expr":"\\Delta E=\\tfrac12 mv_0^2+mgx\\sin30^\\circ","cues":["别漏重力势能","机械能是动能加势能","高度用位移乘正弦"],"concepts":["机械能","重力势能","动能"]}],"244":[{"title":"识别各符号的量纲","type":"前提判断","judge":"a、b、c、d 分别对应长度、质量、时间、动量的量纲，能否写出各自的量纲式","why":"题目用字母代替物理量，必须先还原成基本量纲才能比较；动量不是基本量，要由质量和速度导出","do":"写出 a=L、b=M、c=T，并由 p=mv 推出 d=MLT⁻¹","expr":"[a]=\\mathrm{L},\\ [b]=\\mathrm{M},\\ [c]=\\mathrm{T},\\ [d]=\\mathrm{MLT^{-1}}","cues":["先还原量纲","动量是质量乘速度","长度质量时间"],"concepts":["量纲","基本单位","动量"]},{"title":"确定能量的量纲目标","type":"关系建立","judge":"要判断某式是否为能量，需先明确能量对应的量纲组合是什么","why":"能量与功同量纲，可由动能或功的定义得到，作为比较的基准","do":"由 E=½mv² 或 W=Fs 写出能量的量纲式","expr":"[E]=\\mathrm{ML^{2}T^{-2}}","cues":["能量和功同量纲","用动能公式找","力乘位移"],"concepts":["能量","量纲"]},{"title":"代入化简各表达式量纲","type":"数学处理","judge":"把 a、b、c、d 的量纲代入每个待选式，化简后与能量量纲比较","why":"只有量纲完全一致才可能是能量，量纲不同则一定不是","do":"逐式代入并合并 L、M、T 的指数，与 ML²T⁻² 对照","expr":"\\frac{a^{2}b}{c^{2}}=\\mathrm{ML^{2}T^{-2}},\\ \\frac{ab^{2}}{c^{2}}=\\mathrm{M^{2}LT^{-2}},\\ \\frac{d^{2}}{b}=\\mathrm{ML^{2}T^{-2}},\\ \\frac{b^{2}}{d}=\\mathrm{ML^{-1}T}","cues":["逐个代进去","合并指数","和能量比一比"],"concepts":["量纲运算","单位制"]},{"title":"区分力与能量量纲","type":"结论整理","judge":"化简结果中哪些与能量量纲相同，哪些只是力或其它量的量纲","why":"MLT⁻² 是力的量纲，含 M² 或含 L⁻¹T 的组合都不是能量，不能因形式相似误判","do":"把每个结果与 ML²T⁻² 和 MLT⁻² 分别对照，排除量纲不符者","expr":"[F]=\\mathrm{MLT^{-2}}\\neq\\mathrm{ML^{2}T^{-2}}","cues":["这个是力的单位","多了一个质量","量纲不对就排除"],"concepts":["量纲检验","力的单位"]}],"245":[{"title":"全反射临界角判据","type":"前提判断","judge":"光线在玻璃内表面能否发生全反射，取决于入射角与临界角 C 的大小关系","why":"全反射条件：光从光密介质射向光疏介质且入射角大于等于临界角，临界角由 sinC=1/n 决定；n 越小 C 越大，越难全反射","do":"由 sinC=1/n 算出各折射率对应的临界角，与光线在玻璃内表面的实际入射角比较","expr":"\\sin C=\\frac{1}{n}","cues":["先算临界角","折射率小临界角大","入射角要大于临界角"],"concepts":["全反射","临界角","折射率"]},{"title":"入射角与θ的几何关系","type":"几何关系","judge":"光垂直上表面入射后，第一次射到玻璃内表面的入射角与玻璃上下表面的夹角 θ 是什么关系","why":"光垂直入射不改变方向，射到倾斜内表面时入射角由表面法线与光线的夹角决定，需用几何关系把 θ 与实际入射角挂钩","do":"画出法线，由平行表面与垂直入射条件，得出第一次全反射入射角等于 θ，并据此判断 θ<45° 时能否满足全反射","expr":"i_1=\\theta","cues":["垂直入射不偏折","入射角就是那个角","画法线看夹角"],"concepts":["几何光学","入射角","法线"]},{"title":"多次反射的角度传递","type":"关系建立","judge":"第一次全反射的入射光线与反射光线的夹角，与后续各次全反射的入射角之间是什么数量关系","why":"相邻反射面平行，反射光线与表面的夹角在两次反射间保持不变，故第一次的入射光线与反射光线夹角等于第二次的入射角","do":"由反射定律和两反射面平行的几何关系，把第一次的入射光线与反射光线夹角与第二次入射角联系起来，再与临界角比较","expr":"\\alpha=2i_1=2\\theta","cues":["反射角等于入射角","两面平行角度不变","夹角是入射角两倍"],"concepts":["反射定律","平行表面","角度传递"]},{"title":"出射光线的平移方向","type":"模型选择","judge":"入射光线整体平移时，三次全反射后的出射光线朝哪个方向移动、是否仍与入射光平行","why":"每次全反射都使光线相对表面按反射定律偏转，入射点平移会逐次传递到各反射点，需追踪光路整体平移方向","do":"把入射光线向左平移，依次画出三次反射光线的平移方向，判断出射光线的移动方向","expr":"","cues":["逐次画反射光","平移会累积","出射光跟着移"],"concepts":["光路作图","全反射","平移"]}],"246":[{"title":"两区半径反比关系","type":"关系建立","judge":"同一粒子在两区中速率相同，轨迹半径与磁感应强度成反比，需判断 r₁:r₂ 由 B 的比值直接取倒数得到","why":"洛伦兹力提供向心力 qvB=mv²/r，得 r=mv/(qB)，v、m、q 不变时 r∝1/B，故 r₁:r₂=B₂:B₁=1:4","do":"写出 r=mv/(qB)，用 B₁:B₂=4:1 求两区半径比","expr":"r=\\frac{mv}{qB},\\quad \\frac{r_1}{r_2}=\\frac{B_2}{B_1}=\\frac14","cues":["速度一样半径只由B定","先求半径比"],"concepts":["洛伦兹力","圆周运动半径"]},{"title":"轨迹圆心不在 O","type":"几何关系","judge":"需判断粒子在 Ⅰ 区做圆周运动的圆心是否落在正方形中心 O 上","why":"粒子沿某边中垂线方向入射，圆心应在入射点速度的垂线上，而该垂线并不通过 O，故圆心不在 O","do":"过入射点作速度垂线找 Ⅰ 区轨迹圆心，与 O 点位置比较","expr":"","cues":["圆心在速度垂线上","垂线不过中心","圆心不在O"],"concepts":["圆心定位","速度垂线"]},{"title":"两圆相切的几何构型","type":"几何关系","judge":"需判断粒子在 Ⅱ 区圆弧与 Ⅰ 区圆弧在边界处如何衔接，从而建立两半径与圆心角的关系","why":"粒子在两区边界处速度连续，两段圆弧在边界点相切，圆心与切点共线，由内外边界同心可构造直角三角形","do":"画出两段圆弧及各自圆心，连接圆心与切点，用直角三角形边长 r₁、r₂ 表示 Ⅱ 区圆心角 α","expr":"\\cos\\alpha=\\frac{r_2}{r_1+r_2}=\\frac45","cues":["两段圆弧在边界相切","圆心和切点共线","用直角三角形找角度"],"concepts":["相切","几何关系","圆心角"]},{"title":"由余弦值定圆心角","type":"数学处理","judge":"需由 cosα=4/5 结合题给 sin37°=0.6 判断 α 的取值","why":"cosα=0.8 对应 α=37°，题目给出 sin37°=0.6 正是提示用此特殊角","do":"由 cosα=4/5 反查特殊角得 α=37°","expr":"\\cos\\alpha=\\frac45\\Rightarrow\\alpha=37^\\circ","cues":["用题目给的三十七度","特殊角直接读出"],"concepts":["特殊角三角函数"]},{"title":"两区圆心角分配","type":"临界条件","judge":"需判断粒子在 Ⅰ 区偏转角与 Ⅱ 区偏转角各为多少，才能拼出从 a 进、从 a 出的闭合轨迹","why":"粒子从同一点 a 进出，总偏转须使轨迹闭合，由几何构型 Ⅰ 区偏转角为 360°−2(90°−α)，Ⅱ 区为 2α","do":"由几何图确定 Ⅰ 区圆心角 360°−2(90°−37°)=254°，Ⅱ 区圆心角 2×37°=74°","expr":"\\theta_1=360^\\circ-2(90^\\circ-\\alpha),\\quad \\theta_2=2\\alpha","cues":["从同一点进出要闭合","两段偏转角加起来看","先定每段转过的角度"],"concepts":["轨迹闭合","圆心角"]},{"title":"时间比与弧长比","type":"结论整理","judge":"需判断比较时间与轨迹长度时，两区周期不同、半径不同，不能直接用圆心角比代替","why":"周期 T=2πm/(qB) 随 B 变，弧长 l=rθ 随 r 变，须分别代入 θ/360°·T 与 θ/360°·2πr 再求比","do":"分别写 t=θT/360°、l=θ·2πr/360°，代入 θ₁、θ₂ 与 r₁、r₂ 求两比值","expr":"\\frac{t_1}{t_2}=\\frac{\\theta_1 B_2}{\\theta_2 B_1},\\quad \\frac{l_1}{l_2}=\\frac{\\theta_1 r_1}{\\theta_2 r_2}","cues":["周期跟B有关不能省","弧长要用半径乘角度","时间和弧长比不一样"],"concepts":["周期","弧长","比值"]}],"247":[{"title":"刻度尺估读位数","type":"实验操作","judge":"读数时要不要在分度值后多估读一位","why":"刻度尺分度值为 0.1 cm，测量读数须估读到分度值的下一位，否则有效数字不足","do":"先确认分度值 0.1 cm，再对系绳点所在刻度估读一位小数","expr":"","cues":["看分度值","估读一位","读到毫米后一位"],"concepts":["刻度尺读数","估读","有效数字"]},{"title":"原长与伸长量区分","type":"前提判断","judge":"图像纵坐标的 x 是弹簧总长还是伸长量","why":"胡克定律中的 x 必须是形变量，若误用总长则截距含义改变、劲度系数算错","do":"明确 x = 当前长度 − 原长，把第(1)问读出的原长作为基准","expr":"$x=L-L_0$","cues":["伸长量不是总长","减去原长","形变量"],"concepts":["形变量","胡克定律","原长"]},{"title":"受力平衡建方程","type":"关系建立","judge":"弹簧弹力由哪些力平衡，桶重是否计入","why":"弹簧稳定时弹力等于桶与水的总重力，漏掉空桶重力会使截距无法解释","do":"对桶和水整体列平衡式，弹力等于桶重加水重","expr":"$kx=mg+\\rho Vg$","cues":["取桶和水整体","别忘了空桶","弹力等于总重"],"concepts":["共点力平衡","胡克定律","重力"]},{"title":"化线性读斜率截距","type":"数学处理","judge":"把平衡式整理成 x 关于 V 的一次函数，斜率截距各对应什么","why":"图像是 x–V 直线，只有化成标准一次函数形式才能把斜率和截距与 k、m 对应","do":"将平衡式改写为 x 关于 V 的表达式，对照斜率与截距","expr":"$x=\\frac{\\rho g}{k}V+\\frac{mg}{k}$","cues":["化成一次函数","斜率对应密度乘g比k","截距对应桶重比k"],"concepts":["一次函数","斜率","截距"]},{"title":"单位与有效数字","type":"数据处理","judge":"体积用 mL 还是 m³，结果保留几位","why":"斜率单位是 m⁻²，体积须换算成 m³ 才能与密度、g 配套；题目要求保留 2 位有效数字","do":"把 50 mL 换算为 5.0×10⁻⁵ m³，代入后按 2 位有效数字取舍","expr":"$1\\,\\mathrm{mL}=10^{-6}\\,\\mathrm{m^3}$","cues":["毫升换立方米","保留两位","单位要配套"],"concepts":["单位换算","有效数字"]}],"248":[{"title":"有效长度取夹间距离","type":"前提判断","judge":"计算电阻率时，公式里的 l 应取两金属夹之间的样品长度还是整根样品的长度","why":"电阻定律 R=ρl/S 中的 l 是实际接入电路、有电流通过的那段导体长度，金属夹之外的部分不参与导电","do":"用两夹位置坐标相减得到接入长度，而不是用米尺总长或样品总长","expr":"l=70.00\\,\\mathrm{cm}-20.00\\,\\mathrm{cm}=50.00\\,\\mathrm{cm}","cues":["取两夹之间","不是整根","夹子外不算"],"concepts":["电阻定律","有效长度"]},{"title":"直径平均值与单位换算","type":"数据处理","judge":"三个直径读数取算术平均后，代入公式前要不要换算成国际单位","why":"电阻率公式中长度、面积均用国际单位制，直径以 mm 给出，直接代入会使结果差 10⁶ 量级","do":"先求三次读数的平均值，再把 mm 换算为 m 后代入面积公式","expr":"d=\\frac{0.499+0.498+0.503}{3}\\,\\mathrm{mm}=0.500\\,\\mathrm{mm}=5.00\\times10^{-4}\\,\\mathrm{m}","cues":["先平均","毫米换米","别忘了换算"],"concepts":["平均值","单位制","横截面积"]},{"title":"限流接法接线柱选择","type":"实验操作","judge":"限流电路中电流表正接线柱应接滑动变阻器的哪个接线柱，才能保证滑片移动时电阻连续可调","why":"限流接法要求滑动变阻器只用“一上一下”两个接线柱串入电路，接错则变阻器被短路或不起调节作用","do":"对照图(a)判断哪一个是下端接线柱，把电流表正极经它接入，形成串联回路","expr":"","cues":["一上一下","串联进去","接下面那个"],"concepts":["限流接法","滑动变阻器"]},{"title":"闭合前滑片置最大阻值","type":"实验操作","judge":"闭合开关前滑片应放在使接入电阻最大的一端，以保护电流表","why":"接通瞬间若电阻过小，电流可能超过电流表量程而损坏仪表","do":"判断滑片移到哪一端时变阻器接入回路的电阻丝最长，即置于该端","expr":"","cues":["保护电表","阻值最大","先放最左"],"concepts":["安全操作","限流保护"]},{"title":"等电流替代测电阻","type":"关系建立","judge":"两次电流相同说明什么，电阻箱示数与合金丝电阻是什么关系","why":"电源电动势和内阻不变，两次电流相等意味着两次外电路总电阻相等，故电阻箱阻值等于合金丝阻值","do":"读出电阻箱面板示数，直接作为待测丝电阻代入电阻定律","expr":"R_x=R_{\\text{箱}}","cues":["电流相同电阻相同","替代法","电阻箱读数就是它"],"concepts":["等效替代","闭合电路欧姆定律"]},{"title":"误差来源与改进方向","type":"误差分析","judge":"各项改进措施是通过减小哪个量的测量误差来减小电阻率误差的","why":"由 ρ=πRd²/(4l) 知误差来自 R、d、l 的测量，电源内阻和电流表内阻在等电流替代中已被抵消","do":"逐项分析该措施影响 R、d、l 中的哪一个，排除与替代法原理无关的选项","expr":"\\rho=\\frac{\\pi R d^{2}}{4l}","cues":["看公式找误差","内阻被抵消","电阻箱更精细"],"concepts":["误差传递","等效替代法"]}],"249":[{"title":"碰撞后电荷变号","type":"前提判断","judge":"碰后微粒电性与极板相同、电量绝对值不变，需判断碰后所受电场力方向是否反向","why":"下极板接地且微粒带正电，碰后带负电，电场方向不变而受力反向，运动由加速变为减速","do":"比较碰前碰后电场力方向，确定碰后加速度方向与速度方向相反","expr":"","cues":["碰后带负电","受力反向了","先减速上升"],"concepts":["电场力方向","电荷守恒"]},{"title":"分段取加速度大小","type":"模型选择","judge":"判断每段运动是匀加速还是匀减速，加速度大小是否相同","why":"不计重力，合力只有电场力，大小恒为 qE，故各段加速度大小均为 qE/m，仅方向不同","do":"对每段用牛顿第二定律写出加速度大小 a=qE/m，方向随电荷正负改变","expr":"a=\\frac{qE}{m}","cues":["只有电场力","加速度大小不变","方向要分段看"],"concepts":["牛顿第二定律","匀变速直线运动"]},{"title":"首段位移取半板距","type":"几何关系","judge":"微粒从中央 O 点释放，第一次到下极板的位移是 d 还是 d/2","why":"O 位于两极板正中央，到下极板距离为 d/2","do":"在运动学公式中代入位移 d/2，而非 d","expr":"\\frac{d}{2}=\\frac{1}{2}at^{2}","cues":["从中央出发","只走半个板距","别用整个d"],"concepts":["位移","板间距"]},{"title":"碰后机械能不变定速率","type":"临界条件","judge":"碰撞前后瞬间机械能不变意味着碰后速率与碰前速率相等","why":"机械能只含动能（不计重力势能变化），机械能不变即速率不变，只改变方向与电荷","do":"把碰前速率作为下一段初速率，方向取向上","expr":"v_{1}=at=\\sqrt{\\frac{qEd}{m}}","cues":["速率不变","只改方向","拿碰前速度当初速"],"concepts":["机械能","动能"]},{"title":"逐段用速度位移关系","type":"关系建立","judge":"碰后向上运动跨越整个板距 d 到上极板，再返回 O 点走 d/2，需分段用速度位移公式","why":"每段加速度大小相同但方向不同，用 v²-v₀²=2as 可避开各段时间，直接串联速率","do":"对下极板到上极板取 s=d，对上极板到 O 点取 s=d/2，逐段求末速率","expr":"v_{2}^{2}-v_{1}^{2}=2ad,\\quad v_{3}^{2}-v_{2}^{2}=2a\\frac{d}{2}","cues":["分段列式子","用速度位移公式","省去求时间"],"concepts":["速度位移关系","匀变速直线运动"]},{"title":"动量取速率乘质量","type":"结论整理","judge":"求动量大小只需末速率大小，不必管方向","why":"动量大小 p=mv，题目只问大小","do":"把最后一段求得的速率乘以 m 得动量大小","expr":"p=mv_{3}","cues":["只求大小","速率乘质量","方向不用管"],"concepts":["动量"]}],"250":[{"title":"切割长度取导轨间距","type":"模型选择","judge":"判断金属杆切割磁感线的有效长度是导轨间距 l 还是杆长或绳长","why":"只有垂直于磁场且同时垂直于速度方向的那段导体才产生电动势，杆在导轨间的部分才是有效切割长度","do":"把杆在磁场中的有效长度取为两导轨间距 l，写出动生电动势表达式","expr":"E=Blv","cues":["取导轨间距","杆长不是切割长度","只看两轨之间"],"concepts":["动生电动势","有效切割长度"]},{"title":"回路电阻随位置变化","type":"关系建立","judge":"判断回路总电阻由哪几段串联组成、是否随杆的位置改变","why":"导轨单位长度电阻为 r，杆移动后接入回路的导轨长度随 d 增大，定值电阻 2sr 不变，故总电阻是 d 的函数","do":"把两段接入导轨的电阻 2dr 与定值电阻 2sr 串联相加，得总电阻后代入功率公式","expr":"R=2dr+2sr=2r(d+s)","cues":["两段导轨都算","电阻随d变","定值电阻不变"],"concepts":["串联电阻","电阻定律"]},{"title":"热功率用电动势平方比电阻","type":"关系建立","judge":"判断回路热功率应由总电动势与总电阻决定，而不是只算外电阻或只算某段","why":"杆电阻不计，电动势全部降在总电阻上，焦耳热功率等于电动势平方除以总电阻","do":"用 P=E²/R 代入 E 与 R 的表达式化简","expr":"P=\\frac{B^{2}l^{2}v^{2}}{2r(d+s)}","cues":["用总电阻","电动势平方除电阻","杆无内阻"],"concepts":["电功率","闭合电路欧姆定律"]},{"title":"绳拉力方向随位置改变","type":"几何关系","judge":"判断绳与水平方向的夹角随杆位置如何变化，以及临界时杆在何处","why":"滑轮在 N、Q 中点正上方 h 处，杆向右运动时绳的水平投影变短，夹角增大，水平分力减小","do":"设杆距 MP 为 x，写出绳水平投影 s−x 与竖直高度 h 的几何关系，得 tanθ=h/(s−x)","expr":"\\tan\\theta=\\frac{h}{s-x}","cues":["绳角在变","水平投影是s减x","滑轮在正上方"],"concepts":["几何约束","绳的方向"]},{"title":"匀速的临界是拉力水平分力","type":"临界条件","judge":"判断杆能保持匀速的最大路程对应什么临界状态——是安培力等于拉力的水平分力，还是别的","why":"杆匀速则水平方向合力为零，安培力随 x 增大而增大，绳水平分力随 x 增大而减小，两者相等时到达极限，再往前无法维持匀速","do":"对杆列水平与竖直两个平衡方程，消去拉力 T，得安培力与重力的关系","expr":"F_{\\text{安}}=T\\cos\\theta,\\quad mg=T\\sin\\theta","cues":["水平竖直都平衡","消去拉力","安培力等于水平分力"],"concepts":["共点力平衡","安培力"]},{"title":"安培力随位置增大","type":"关系建立","judge":"判断安培力中电流随 x 如何变化，从而确定安培力是随 x 增大还是减小","why":"总电阻随 x 增大，电流减小，但安培力还要乘上随位置变化的几何因子，需联立后才能判断临界方程可解","do":"写出 I=Blv/[2r(x+s)] 与 F安=BIl，与平衡条件和几何关系联立消去 θ、T、I","expr":"I=\\frac{Blv}{2r(x+s)},\\quad F_{\\text{安}}=BIl","cues":["电流随x减小","安培力含电流","联立消元"],"concepts":["安培力","闭合电路欧姆定律","联立方程"]}],"251":[{"title":"甲在ab段的受力方向","type":"模型选择","judge":"甲沿直挡板ab运动时，沿斜面方向受什么力、加速度由哪个分量决定","why":"挡板光滑无摩擦，甲只受重力和挡板支持力，沿运动方向只有重力沿斜面的分量","do":"沿斜面方向对甲列牛顿第二定律，取沿斜面向下为正","expr":"m_{1}g\\sin\\theta = m_{1}a_{1}","cues":["沿斜面分解重力","只有重力分量","挡板光滑"],"concepts":["牛顿第二定律","重力分量"]},{"title":"恰到c点的临界条件","type":"临界条件","judge":"甲恰能到达c点意味着c点处挡板对甲的压力处于什么状态","why":"甲在c点做圆周运动，恰能到达说明c点所需向心力恰好由重力沿斜面分量提供，支持力为零","do":"在c点沿半径方向列向心力方程，令支持力为零","expr":"m_{1}g\\sin\\theta = m_{1}\\frac{v_{1}^{2}}{R}","cues":["恰能到达就是压力为零","c点速度最小"],"concepts":["向心力","临界条件"]},{"title":"弹性碰撞后乙的速度","type":"关系建立","judge":"完全弹性碰撞中，用动量守恒和能量守恒消去甲碰后速度，得到乙的速度与质量比的关系","why":"两球完全弹性碰撞，动量守恒且动能守恒，乙碰前锁定静止","do":"联立动量守恒与动能守恒，消去甲碰后速度v1'，解出v2","expr":"v_{2}=\\frac{2m_{1}v_{1}}{m_{1}+m_{2}}","cues":["动量动能都守恒","消去甲碰后速度","乙碰前静止"],"concepts":["完全弹性碰撞","动量守恒","动能守恒"]},{"title":"乙到e点的两条路径","type":"模型选择","judge":"碰后乙沿挡板运动到e点，是贴着半圆挡板做圆周运动，还是脱离挡板做类平抛运动","why":"乙在b点速度方向沿切线，若速度足够大则沿圆弧运动，若不足则脱离挡板沿斜面方向做类平抛","do":"分两种情况：贴挡板圆周运动需b点向心力条件；脱离后做类平抛，沿斜面方向位移8R、垂直方向位移R","expr":"v_{2}\\geq\\sqrt{gR\\sin\\theta}\\quad\\text{或}\\quad 8R=\\frac{1}{2}g\\sin\\theta\\,t^{2},\\ R=v_{2}t","cues":["可能贴挡板转过去","也可能飞出去","分两种情况讨论"],"concepts":["圆周运动","类平抛运动","临界速度"]},{"title":"越过de但不撞圆弧","type":"临界条件","judge":"乙做类平抛时，要穿过线段de而不先撞到圆弧cd，速度应满足什么上下限","why":"速度太小落点不到de，速度太大轨迹会先与圆弧cd相交，两个边界分别对应到达e点和擦过c点","do":"用沿斜面位移8R定时间，要求垂直方向位移大于R（过de）且小于R（不撞圆弧），联立得速度区间","expr":"\\frac{1}{4}\\sqrt{gR\\sin\\theta}<v_{2}<\\sqrt{\\frac{1}{2}gR\\sin\\theta}","cues":["太快会撞圆弧","太慢到不了de","两个边界夹住"],"concepts":["类平抛运动","轨迹边界","临界条件"]},{"title":"甲从a到c的动能定理","type":"关系建立","judge":"把碰前甲在c点的速度与初动能联系起来时，重力沿斜面做负功的位移取多少","why":"甲从a沿直线到b再沿半圆到c，沿斜面方向上升的总高度对应8R的斜面位移","do":"对甲从a到c列动能定理，重力做功取-m1g·8R·sinθ","expr":"-m_{1}g\\cdot 8R\\sin\\theta=\\frac{1}{2}m_{1}v_{1}^{2}-E_{k0}","cues":["上升总高度是8R","重力做负功","用动能定理连初末"],"concepts":["动能定理","重力做功"]}],"252":[{"title":"建立引力提供向心力的模型","type":"模型选择","judge":"卫星做匀速圆周运动的向心力由什么力提供，能否用同一个引力方程统一描述各物理量","why":"卫星只受地球万有引力，且做匀速圆周运动，故万有引力全部充当向心力，这是推出所有参量随半径变化关系的前提","do":"对卫星写万有引力等于向心力的等式，把向心力分别写成含线速度、角速度、周期、向心加速度的四种形式","expr":"\\frac{GMm}{r^{2}}=m\\frac{v^{2}}{r}=m\\omega^{2}r=m\\frac{4\\pi^{2}}{T^{2}}r=ma","cues":["万有引力当向心力","只有引力","列一个通式"],"concepts":["万有引力定律","向心力","匀速圆周运动"]},{"title":"导出各参量随半径的单调关系","type":"关系建立","judge":"线速度、角速度、周期、向心加速度各自随轨道半径增大是增大还是减小","why":"由同一引力方程解出各参量关于 r 的表达式，才能把 r_A>r_B 转化为各物理量的大小比较","do":"从引力方程分别解出 v、ω、T、a 的表达式，观察各自与 r 的幂次关系","expr":"v=\\sqrt{\\frac{GM}{r}},\\ \\omega=\\sqrt{\\frac{GM}{r^{3}}},\\ T=\\sqrt{\\frac{4\\pi^{2}r^{3}}{GM}},\\ a=\\frac{GM}{r^{2}}","cues":["半径越大速度越小","周期随半径变大","加速度随半径变小"],"concepts":["线速度","角速度","周期","向心加速度"]},{"title":"用半径大小比较各量","type":"结论整理","judge":"把 r_A>r_B 代入各单调关系后，A 的线速度、角速度、周期、加速度相对 B 是偏大还是偏小","why":"题目只给出半径大小关系，必须逐一代入才能确定哪个选项描述的关系成立","do":"将 r_A>r_B 分别代入 v、ω、T、a 的表达式，比较 A、B 两卫星的对应量","expr":"r_{A}>r_{B}\\Rightarrow v_{A}<v_{B},\\ \\omega_{A}<\\omega_{B},\\ T_{A}>T_{B},\\ a_{A}<a_{B}","cues":["半径大的速度小","半径大的周期长","半径大的加速度小"],"concepts":["控制变量比较","反比关系"]}],"253":[{"title":"α衰变核变化","type":"前提判断","judge":"α衰变时母核的质量数和电荷数各减少多少","why":"α粒子就是氦核，放出它等于母核减去2个质子和2个中子","do":"写出α衰变方程，比较母核与新生核的质量数、电荷数","expr":"{}^{A}_{Z}\\mathrm{X}\\to{}^{A-4}_{Z-2}\\mathrm{Y}+{}^{4}_{2}\\mathrm{He}","cues":["放氦核","质量数减四","电荷数减二"],"concepts":["α衰变","质量数守恒","电荷数守恒"]},{"title":"衰变中的质量亏损","type":"关系建立","judge":"衰变前后总质量是增加还是减少","why":"衰变自发释放能量，由质能方程必然对应质量亏损","do":"把释放的能量与质量变化用质能方程联系起来，判断总质量的变化方向","expr":"\\Delta E=\\Delta m c^{2},\\ \\Delta m>0","cues":["释放能量","质量亏损","总质量变小"],"concepts":["质能方程","质量亏损","衰变放能"]},{"title":"半衰期的决定因素","type":"前提判断","judge":"半衰期由核内部结构决定还是由外部温度压强决定","why":"半衰期是大量原子核衰变的统计规律，只取决于核自身","do":"比较温度变化对半衰期有无影响，排除外界条件干扰","expr":"","cues":["与温度无关","由核内部决定","外界改不了"],"concepts":["半衰期","统计规律"]},{"title":"β衰变电子来源","type":"模型选择","judge":"β衰变放出的电子是核内原有电子还是中子转变产生","why":"核内只有质子和中子，β衰变是中子转化为质子并放出一个电子","do":"写出β衰变方程，看电子由哪个核子转变而来","expr":"{}^{1}_{0}\\mathrm{n}\\to{}^{1}_{1}\\mathrm{p}+{}^{0}_{-1}\\mathrm{e}","cues":["中子变质子","电子是新产生的","核内没有电子"],"concepts":["β衰变","中子转变"]}],"254":[{"title":"识别匀速圆周运动","type":"模型选择","judge":"座椅做的是匀速圆周运动还是变速/平衡状态","why":"题设明确悬臂绕竖直轴匀速转动、座椅在水平面内做圆周运动，速率不变但速度方向时刻改变","do":"把座椅的运动归为匀速圆周运动模型，确认速率恒定、方向沿切线不断变化","expr":"","cues":["匀速圆周","速率不变","方向在变"],"concepts":["匀速圆周运动","线速度"]},{"title":"区分速度与速率","type":"前提判断","judge":"一周内速度（矢量）是否变化、动量是否变化","why":"动量是矢量，大小不变但方向改变，动量就改变；不能只看速率不变就认为动量不变","do":"比较初末速度方向，判断动量矢量是否变化","expr":"$\\vec p=m\\vec v$","cues":["动量是矢量","方向变了","不能只看大小"],"concepts":["动量","矢量性"]},{"title":"动能定理判合力做功","type":"关系建立","judge":"一周内合外力做功是否为零","why":"动能定理指出合外力做功等于动能变化，速率不变则动能不变，故合力做功为零","do":"比较一周初末的动能，用动能定理反推合力做功","expr":"$W_{\\text{合}}=\\Delta E_k=0$","cues":["动能不变","合力做功为零","用动能定理"],"concepts":["动能定理","动能"]},{"title":"区分冲量与做功","type":"前提判断","judge":"重力冲量是否为零，能否用做功为零类推冲量为零","why":"冲量是力对时间的积累，重力始终存在且时间不为零，冲量不为零；做功为零不等于冲量为零","do":"用重力乘一周时间判断重力冲量，注意冲量与功是不同积累量","expr":"$I_G=mgt\\neq 0$","cues":["冲量是力乘时间","重力一直有","功和冲量不同"],"concepts":["冲量"]},{"title":"判断是否受力平衡","type":"结论整理","judge":"匀速圆周运动是否处于受力平衡状态","why":"匀速圆周运动有指向圆心的向心加速度，合外力不为零，不是平衡态","do":"指出存在向心加速度，否定合力为零的平衡判断","expr":"$a_n=\\dfrac{v^2}{r}\\neq 0$","cues":["有向心加速度","合力不为零","不是平衡态"],"concepts":["向心加速度","受力平衡"]}],"255":[{"title":"判断两状态温度关系","type":"关系建立","judge":"A、C 两状态的温度是否相等，能否由 p-V 图上两点连线过原点或 pV 乘积相等来判定","why":"理想气体状态方程 pV/T=C，温度相同等价于 pV 乘积相同；图上 A、C 在同一过原点的直线上，说明 pV 相同","do":"在 p-V 图中比较 A、C 两点对应的 pV 乘积（或看两点是否在同一条过原点的直线上）","expr":"\\frac{p_A V_A}{T_A}=\\frac{p_C V_C}{T_C}","cues":["看乘积","过原点直线","温度一样"],"concepts":["理想气体状态方程","等温线"]},{"title":"判断内能变化","type":"前提判断","judge":"从 A 到 C 内能是否变化，取决于初末温度是否相同而非路径","why":"一定质量理想气体的内能只由温度决定，与经历的过程无关","do":"由 A、C 温度相同直接得出内能相同，排除与路径有关的干扰","expr":"\\Delta U_{AC}=0","cues":["内能只看温度","与路径无关"],"concepts":["理想气体内能","温度"]},{"title":"比较做功大小","type":"几何关系","judge":"不同路径下外界对气体做功的大小，要由 p-V 图线下面积比较，而不是只看初末状态","why":"功 W=∫p dV，p-V 图线与 V 轴围成的面积表示做功多少，路径不同面积不同","do":"比较 AC 直线与折线 ABC、ADC 下方所围面积的大小关系","expr":"W=\\int p\\,dV","cues":["看面积","线下面积","路径不同"],"concepts":["p-V 图面积","气体做功"]},{"title":"判断吸放热","type":"关系建立","judge":"由做功和 ΔU 反推各过程吸放热的多少与方向","why":"热力学第一定律 ΔU=W+Q，ΔU 相同而 W 不同，则 Q 不同","do":"在 ΔU 相同的前提下，用 W 的大小关系比较 Q 的大小与正负","expr":"\\Delta U=W+Q","cues":["用第一定律","先定内能","再比功"],"concepts":["热力学第一定律","吸热放热"]},{"title":"比较 B、D 温度","type":"关系建立","judge":"B、D 两状态温度高低，需由各自 pV 乘积比较而非位置高低","why":"温度由 pV 乘积决定，B 点 pV 乘积大于 D 点，故 B 温度更高","do":"分别读出 B、D 的 p 与 V 并比较乘积","expr":"T\\propto pV","cues":["比乘积","不看位置"],"concepts":["理想气体状态方程","温度"]},{"title":"平均动能与温度","type":"结论整理","judge":"分子平均动能大小只由温度决定，温度高则平均动能大","why":"温度是分子平均动能的标志，与体积、压强无直接对应","do":"由 B、D 温度高低直接判断平均动能大小","expr":"\\bar{E}_k\\propto T","cues":["温度是标志","平均动能看温度"],"concepts":["分子平均动能","温度"]}],"256":[{"title":"从图中读出条纹间距","type":"图像读取","judge":"要判断的是：横轴相邻两个光照强度极大值（或极小值）之间的间距，哪一束光的更大","why":"双缝干涉条纹间距是相邻亮（暗）纹中心的距离，图上表现为相邻峰值（谷值）的水平间隔，只有先读出这个间隔才能进入条纹间距公式","do":"在上下两图中各取相邻两个峰值，比较它们的水平间隔大小","expr":"","cues":["看相邻峰的距离","峰和峰之间","a的条纹更密"],"concepts":["双缝干涉","条纹间距","光照强度分布"]},{"title":"条纹间距反推波长","type":"关系建立","judge":"要判断的是：同一装置下条纹间距与波长成正比，从而由间距大小比较 a、b 的波长","why":"双缝干涉条纹间距公式 Δx=Lλ/d 中 L、d 对同一装置相同，间距只由波长决定","do":"用 Δx=Lλ/d 把间距大小关系翻译成波长大小关系","expr":"$\\Delta x=\\frac{L}{d}\\lambda$","cues":["同一装置","间距小波长短","套条纹间距公式"],"concepts":["条纹间距公式","波长"]},{"title":"波长联系光子能量与动量","type":"关系建立","judge":"要判断的是：波长越短，光子能量和光子动量越大，据此比较 a、b 的光子能量与动量","why":"光子能量 ε=hc/λ 与动量 p=h/λ 都随波长减小而增大，这是判断能量、动量类选项的唯一依据","do":"把上一步得到的波长大小关系代入 ε=hc/λ 和 p=h/λ，比较两光的光子能量与动量","expr":"$\\varepsilon=\\frac{hc}{\\lambda},\\quad p=\\frac{h}{\\lambda}$","cues":["波长短能量大","动量看波长","能量和动量都反比"],"concepts":["光子能量","光子动量"]},{"title":"单缝衍射中央条纹宽度","type":"结论整理","judge":"要判断的是：同一单缝衍射装置中，波长与中央亮条纹宽度的对应关系，从而比较 a、b 的中央亮纹宽窄","why":"单缝衍射中央亮条纹宽度随波长增大而变宽，这是与双缝干涉不同的另一条规律，不能与条纹间距公式混用","do":"由波长大小关系推出通过同一单缝时中央亮条纹的宽窄关系","expr":"","cues":["衍射看波长","波长长中央宽","换成单缝装置"],"concepts":["单缝衍射","中央亮条纹"]}],"257":[{"title":"副线圈电压由谁决定","type":"前提判断","judge":"滑动变阻器阻值变化时，副线圈两端电压是否随之改变","why":"理想变压器输出电压只由输入电压有效值和匝数比决定，与负载电阻无关；输入电压有效值不变，故副线圈电压不变","do":"写出电压比关系，确认 U2 与负载无关，把 U2 当作已知不变量","expr":"\\frac{U_1}{U_2}=\\frac{n_1}{n_2},\\quad U_2=\\frac{n_2}{n_1}U_1","cues":["电压由匝数比定","负载不影响输出电压","先定住副线圈电压"],"concepts":["理想变压器","电压比"]},{"title":"滑片右移阻值怎么变","type":"模型选择","judge":"滑动变阻器滑片向右移动时，接入电路的电阻是变大还是变小","why":"副线圈回路为串联电路，接入电阻直接决定总电阻，进而决定电流方向","do":"看图判断滑片右移时接入线圈长度变短，电阻减小，总电阻减小","expr":"R_{\\text{总}}=R_0+R_{\\text{滑}},\\quad R_{\\text{滑}}\\downarrow","cues":["向右电阻变小","接入部分变短","总电阻减小"],"concepts":["滑动变阻器","串联电路"]},{"title":"副线圈电流与定值电阻电压","type":"关系建立","judge":"总电阻减小后，副线圈电流和定值电阻两端电压各如何变化","why":"U2 不变而总电阻减小，由欧姆定律电流增大；定值电阻阻值不变，其两端电压随电流增大而增大","do":"用欧姆定律求 I2，再用 U_R0=I2R0 判断电压表读数变化","expr":"I_2=\\frac{U_2}{R_0+R_{\\text{滑}}},\\quad U_{R_0}=I_2R_0","cues":["电流变大","定值电阻分压变大","电压表读数变大"],"concepts":["欧姆定律","串联分压"]},{"title":"原线圈电流随副线圈变","type":"关系建立","judge":"副线圈电流增大时，原线圈电流表读数如何变化","why":"理想变压器电流比由匝数比决定，原、副线圈电流同比例变化","do":"由电流比关系，用 I2 增大推出 I1 增大","expr":"\\frac{I_1}{I_2}=\\frac{n_2}{n_1}","cues":["电流比看匝数","原线圈电流变大"],"concepts":["理想变压器","电流比"]},{"title":"功率由副线圈负载决定","type":"关系建立","judge":"副线圈回路功率如何变化，输入功率是否随之变化","why":"理想变压器输入功率等于输出功率，输出功率由副线圈电压和负载决定","do":"用 P=U2I2 判断输出功率增大，再由功率相等得输入功率增大","expr":"P_2=U_2I_2=\\frac{U_2^2}{R_{\\text{总}}},\\quad P_1=P_2","cues":["功率看负载","输出功率变大","输入功率跟着变大"],"concepts":["理想变压器","功率相等"]}],"258":[{"title":"由波形定波长","type":"图像读取","judge":"如何从图中 P、Q 的位置关系读出波长","why":"P 在 x=3 m、Q 在 x=7 m，图中 P、Q 之间恰为一个完整波形（同相点），故两点间距等于一个波长","do":"读出 P、Q 的横坐标差，令其等于波长","expr":"\\lambda = 7-3 = 4\\,\\mathrm{m}","cues":["看两点间距","同相点差一个波长","图上量一段"],"concepts":["波长","波形图"]},{"title":"由 Q 起振定波源方向","type":"前提判断","judge":"波源开始振动的方向与 Q 刚开始振动时的方向是否一致","why":"介质中每个质点的起振方向都重复波源的起振方向，故由 Q 此刻的运动方向即可反推波源起振方向","do":"用同侧法（波形平移法）判断 Q 点此刻的速度方向，再把它等同于波源起振方向","expr":"","cues":["起振方向都一样","看Q点往哪走","同侧法判方向"],"concepts":["起振方向","波的传播","同侧法"]},{"title":"由 Q 到波谷定周期","type":"关系建立","judge":"Q 从刚开始振动到第一次到波谷经历的是几分之几个周期","why":"Q 起振方向确定后，从平衡位置到第一个波谷所走的时间是固定的周期分数，题给 1 s 即对应这一分数","do":"先定 Q 起振方向，再数从平衡位置到第一个波谷需经过的时间份额，与 1 s 对应求 T","expr":"t=\\frac{T}{4}\\Rightarrow T=4\\,\\mathrm{s}","cues":["四分之一周期","起振到波谷","先定方向再数"],"concepts":["周期","简谐振动"]},{"title":"波速与传播时间","type":"关系建立","judge":"波传到 x=9 m 处所需时间如何由波速求出","why":"波速由介质决定，v=λ/T，波前以该速度匀速推进，故传播距离除以波速即传播时间","do":"用波长和周期求波速，再用 (9-7) m 除以波速得传到该点的时间","expr":"v=\\frac{\\lambda}{T}=2\\,\\mathrm{m/s},\\quad t'=\\frac{9-7}{v}=1\\,\\mathrm{s}","cues":["先求波速","距离除以速度","波前匀速走"],"concepts":["波速","波长与周期关系"]},{"title":"叠加起振延迟求首达波峰","type":"临界条件","judge":"x=9 m 处质点第一次到波峰的总时间是否等于传播时间加起振后到波峰的时间","why":"质点先静止，待波传到后才开始按起振方向振动，第一次到波峰须从起振时刻算起再走相应周期分数，两段时间必须相加","do":"用起振方向确定从起振到第一个波峰所需周期份额，再加上波传到该点的时间","expr":"t=t'+\\frac{3T}{4}=1+3=4\\,\\mathrm{s}","cues":["先等波传到","再算起振到波峰","两段时间相加"],"concepts":["起振延迟","波峰","简谐振动"]}],"259":[{"title":"由受力方向定场源位置","type":"几何关系","judge":"两条受力方向所在直线的交点是否就是场源点电荷的位置","why":"点电荷对试探电荷的静电力沿两者连线，故a、b两处受力方向的反向延长线必过场源电荷","do":"把a、b两点的力箭头沿直线反向延长，找交点O，确定场源在O点","expr":"","cues":["反向延长找交点","力沿连线","场源在交点"],"concepts":["点电荷电场","库仑力方向"]},{"title":"判断两电荷电性异同","type":"前提判断","judge":"试探电荷受力是指向场源还是背离场源，从而判断两者同号还是异号","why":"同种电荷相斥、异种电荷相吸，受力方向相对场源指向决定电性关系","do":"看a、b两处力箭头是背离O还是指向O，若均背离则同号","expr":"","cues":["看力背离还是指向","同斥异吸","两力都向外"],"concepts":["电荷相互作用","同种电荷相斥"]},{"title":"电性未知则电势高低不定","type":"结论整理","judge":"场源电荷的正负能否由题给信息唯一确定","why":"只能确定两电荷同号，场源可正可负，电场线方向不定，故a、b电势高低无法比较","do":"检查是否已知场源电性；未知则a、b电势高低不能判定","expr":"","cues":["电性没法确定","电势高低不定","场源可正可负"],"concepts":["电势","电场线方向"]},{"title":"由距离比较场强大小","type":"关系建立","judge":"a、b两点到O点的距离谁大谁小","why":"点电荷场强按平方反比衰减，距离越近场强越大","do":"比较Oa与Ob的长度，近者场强大","expr":"$E=\\frac{kQ}{r^{2}}$","cues":["离得近场强大","平方反比","比距离"],"concepts":["点电荷场强","场强大小"]},{"title":"由力与速度夹角判做功","type":"临界条件","judge":"电场力方向与运动方向的夹角是先钝角后锐角，还是始终不变","why":"力与速度夹角为钝角时做负功、为锐角时做正功，决定电势能先增后减","do":"沿轨迹看力箭头与速度切向的夹角变化，判断功的正负转换","expr":"$W=F s\\cos\\theta$","cues":["先钝角后锐角","先做负功","电势能先增后减"],"concepts":["功的正负","电势能变化"]}],"260":[{"title":"确定竖直方向的依据","type":"实验操作","judge":"取下白纸前，用什么实物基准在白纸上标出竖直方向","why":"平抛运动的竖直分运动是自由落体，坐标系的竖直轴必须与重力方向平行，否则轨迹无法按平抛规律处理","do":"回忆装置中可悬挂重锤的部件，判断应依据铅垂线（重垂线）在白纸上标竖直方向","expr":"","cues":["用铅垂线","重垂线定竖直","看挡板边"],"concepts":["平抛运动","竖直方向","铅垂线"]},{"title":"区分两图线的运动性质","type":"图像读取","judge":"甲、乙两条位移—时间图线分别对应水平还是竖直方向","why":"平抛的水平分运动是匀速直线运动，位移随时间成正比；竖直分运动是初速为零的匀加速运动，位移随时间非线性增大","do":"比较两图线形状：过原点的直线对应匀速，曲线对应匀加速，直线那条即水平位移图线","expr":"x=v_0t,\\quad y=\\tfrac12gt^2","cues":["直线是水平","曲线是竖直","匀速对应直线"],"concepts":["运动的合成与分解","匀速直线运动","自由落体"]},{"title":"从图线斜率求初速度","type":"数据处理","judge":"用水平位移图线上哪一段数据、以什么量求初速度","why":"水平方向 x=v₀t，图线斜率即初速度，需从直线上取可读的坐标点而非曲线段","do":"在甲图线上取一组对应坐标（如 t=0.15 s 时 x=0.30 m），用 x/t 求斜率","expr":"v_0=\\frac{x}{t}","cues":["取直线上的点","算斜率","用横纵坐标相除"],"concepts":["斜率","初速度","匀速直线运动"]}],"261":[{"title":"电表量程按估算选","type":"前提判断","judge":"电压表、电流表各选哪个量程，才能既覆盖又不超量程且读数尽量准","why":"电源电动势 3 V 决定电压表上限；待测约 5 Ω 决定电流最大值约 0.6 A，量程过大则指针偏转太小、相对误差大","do":"用电动势估电压上限，用 E/Rx 估电流上限，再与各量程比较，选略大于估算值的量程","expr":"I_{max}=\\frac{E}{R_x}=\\frac{3}{5}\\,\\mathrm{A}=0.6\\,\\mathrm{A}","cues":["先估最大电流","量程别选太大","指针要过半"],"concepts":["量程选择","电表读数误差"]},{"title":"断线位置由电压示数定位","type":"关系建立","judge":"用电压挡测 a 与 b、a 与 c 间电压，示数为零或不为零分别说明断点在哪一段","why":"电压表有示数说明从电源正极经表笔到该接线柱的路径是通的，示数为零说明该路径中存在断点；断点必在两次测量结果不同的那段导线上","do":"把 a—b 段与 a—c 段的通断结果对比，找出使 a 到 c 通、a 到 b 不通的那条导线","expr":"","cues":["有示数说明通","零示数说明断","比较两段路径"],"concepts":["电路故障分析","电压表测断路"]},{"title":"判断电流表内外接法","type":"模型选择","judge":"由图(c)判断电压表是并在 Rx 两端还是并在 Rx 与电流表串联支路两端，即电流表内接还是外接","why":"只有先确定接法，才能写出 U 与 I 的正确关系；接法不同，电压表分流带来的误差项不同","do":"看图(c)中电压表两接线柱接在哪两点，确认电压表与 Rx 并联、电流表在干路","expr":"","cues":["看电压表接哪两点","电流表在外侧","是外接法"],"concepts":["伏安法","电流表外接"]},{"title":"把电压表分流写进方程","type":"关系建立","judge":"电流表读数 I 是否等于流过 Rx 的电流，还是等于 Rx 与电压表电流之和","why":"电压表内阻并非无穷大，外接时电压表分流，I 比真实通过 Rx 的电流大，忽略就会把 Rx 算小","do":"对并联部分列电流分配式，把 I 拆成通过 Rx 的 U/Rx 与通过电压表的 U/RV 两部分","expr":"I=\\frac{U}{R_x}+\\frac{U}{R_V}","cues":["电压表会分流","电流表读数偏大","别忽略内阻"],"concepts":["并联分流","电压表内阻"]},{"title":"由斜率反解 Rx","type":"数学处理","judge":"U-I 图线的斜率对应的是 Rx 与 RV 的并联值还是 Rx 本身","why":"由 I 的表达式变形得 U 与 I 成正比，比例系数是并联电阻，不是 Rx，直接取 k=Rx 会错","do":"把电流方程整理成 U=kI 形式，令斜率等于并联电阻，再解出 Rx","expr":"k=\\frac{R_VR_x}{R_V+R_x}\\Rightarrow R_x=\\frac{kR_V}{R_V-k}","cues":["斜率是并联值","先变形再对应","解出待测电阻"],"concepts":["U-I 图像斜率","并联电阻"]}],"262":[{"title":"光滑段选机械能守恒","type":"模型选择","judge":"A 到 B（乃至到 C）这段该用机械能守恒还是动能定理，能否忽略摩擦","why":"题设明确 A 点至 C 点光滑，只有重力做功，轨道支持力始终垂直于速度不做功，机械能守恒成立","do":"对小车从 A 到 B 列机械能守恒，求出 B 点速度","expr":"mgR=\\frac{1}{2}mv_0^{2}","cues":["光滑段用机械能守恒","支持力不做功","从静止释放"],"concepts":["机械能守恒","圆周运动"]},{"title":"B 点向心力方程","type":"关系建立","judge":"B 点小车做圆周运动，合力指向圆心，支持力与重力的合力提供向心力","why":"在圆轨道最低点，支持力向上、重力向下，二者之差才是向心力，不能把支持力直接当向心力","do":"沿半径方向列牛顿第二定律，用已求出的 v0 解出支持力","expr":"F_N-mg=m\\frac{v_0^{2}}{R}","cues":["最低点合力向上","支持力减重力","向心力指向圆心"],"concepts":["向心力","牛顿第二定律"]},{"title":"碰撞瞬间动量守恒","type":"前提判断","judge":"碰撞时间极短、桌面光滑，碰撞过程水平方向合外力可忽略，能否用动量守恒","why":"碰撞极短时摩擦冲量可忽略，水平方向动量守恒；碰撞后粘在一起是完全非弹性碰撞，机械能不守恒","do":"对小车与物块组成的系统沿水平方向列动量守恒，求碰后共同速度","expr":"mv_0=(M+m)v","cues":["碰撞极短取动量守恒","粘在一起用共同速度","别用能量守恒"],"concepts":["动量守恒","完全非弹性碰撞"]},{"title":"碰后整体减速求摩擦","type":"模型选择","judge":"碰后组合体在桌面上只受摩擦力做匀减速，该用动能定理还是牛顿定律加运动学","why":"已知位移和初末速度、不涉及时间，用动能定理最直接；也可用牛顿第二定律结合运动学，但需先求加速度","do":"对组合体从 C 到 D 列动能定理，摩擦力做负功等于动能变化","expr":"-\\mu(M+m)gx=0-\\frac{1}{2}(M+m)v^{2}","cues":["用动能定理","摩擦力做负功","末速度为零"],"concepts":["动能定理","滑动摩擦力"]}],"263":[{"title":"判断粒子电性","type":"前提判断","judge":"粒子所受电场力方向与电场方向是否相同，从而确定电荷正负","why":"电场竖直向上，粒子从O点向上偏转进入上方磁场，说明电场力竖直向上，与场强同向","do":"比较电场力方向与题给电场方向，同向则带正电","expr":"","cues":["向上偏转","电场力向上","与场同向"],"concepts":["电场力方向","电荷正负"]},{"title":"电场中分解两方向运动","type":"模型选择","judge":"把电场中的运动看成水平匀速与竖直匀加速的合成，还是整体用动能定理","why":"电场力只在竖直方向，水平方向不受力，两方向运动独立，且已知水平位移L和末速度方向","do":"水平方向列匀速位移式，竖直方向列初速为零的匀加速速度式","expr":"L=vt\\sin\\theta,\\quad v\\cos\\theta=at","cues":["水平匀速","竖直匀加速","分方向列式"],"concepts":["运动的合成与分解","匀变速直线运动"]},{"title":"用末速度方向定时间","type":"关系建立","judge":"如何把入射速度大小v与方向角θ同电场中的时间t、加速度a联系起来","why":"P点速度的竖直分量由竖直匀加速获得，水平分量等于初速度，θ是速度与竖直方向夹角","do":"由速度分解得水平分量v sinθ、竖直分量v cosθ，分别对应水平位移式和竖直速度式","expr":"v_x=v\\sin\\theta,\\quad v_y=v\\cos\\theta","cues":["速度分解","与竖直夹角","分量对应"],"concepts":["速度分解","匀加速运动"]},{"title":"磁场中定圆心与半径","type":"几何关系","judge":"粒子在磁场中做圆周运动，如何由P、Q两点位置和入射方向确定半径","why":"洛伦兹力提供向心力，轨迹为圆弧，P、Q是圆弧上的两点且PQ竖直、长度L，入射速度与竖直方向夹角θ决定弦与切线的关系","do":"作入射速度垂线找圆心，利用弦PQ与切线夹角θ得弦长与半径的关系","expr":"L=2r\\sin\\theta","cues":["找圆心","弦与切线夹角","半径几何关系"],"concepts":["洛伦兹力","圆周运动几何关系"]},{"title":"联立消元求E和B","type":"数学处理","judge":"先由电场中三式消去t和a求E，再由磁场中两式消去r求B","why":"E只出现在电场段方程，B只出现在磁场段方程，两段通过P点速度v和角θ衔接，可分别独立求解","do":"电场段联立L=v t sinθ、qE=ma、v cosθ=at消去t、a；磁场段联立L=2r sinθ、qvB=mv²/r消去r","expr":"E=\\frac{mv^{2}\\sin\\theta\\cos\\theta}{qL},\\quad B=\\frac{2mv\\sin\\theta}{qL}","cues":["分段联立","消去时间","消去半径"],"concepts":["牛顿第二定律","向心力公式"]}],"264":[{"title":"判断外缘电极极性","type":"前提判断","judge":"由磁场方向与转动方向，判断盘内自由电荷受洛伦兹力沿半径指向内缘还是外缘","why":"圆盘切割磁感线时，正电荷所受洛伦兹力方向决定哪一端积累正电荷，即电源正极","do":"用右手定则：四指指向导体运动方向，让磁感线穿入手心，拇指指向即正电荷受力方向，由此定出外缘极性","expr":"","cues":["右手定则","看电荷受力","磁场穿手心"],"concepts":["洛伦兹力","右手定则","电源正极"]},{"title":"用平均速度求感应电动势","type":"关系建立","judge":"判断盘上各点线速度随半径线性变化，需用切割区域的平均速度（或对速度积分）求电动势","why":"转动切割时速度沿半径变化，不能取某一端速度，须取该径向区间的平均速度或积分","do":"取圆心角 θ 区域为研究对象，速度从内缘到外缘线性增大，用两端速度的平均值乘有效切割长度求电动势","expr":"E=B\\cdot 2l\\cdot\\frac{1}{2}(3l+l)\\omega","cues":["速度随半径变","取平均速度","不能只用外缘"],"concepts":["动生电动势","转动切割","平均速度"]},{"title":"按圆心角分配电流","type":"关系建立","judge":"判断盘内电流沿半径流动且各径向路径并联，总电流按圆心角比例分配到 θ 区域","why":"题设说明相同圆心角区域内电流相同，各径向支路并联分流，电流与所占圆心角成正比","do":"先由闭合电路欧姆定律求总电流，再按 θ/2π 的比例求出该扇形区域的电流","expr":"I'=\\frac{\\theta}{2\\pi}\\cdot\\frac{E}{R}","cues":["并联分流","按角度分","先求总电流"],"concepts":["并联电路","分流","闭合电路欧姆定律"]},{"title":"安培力用区域电流与有效长度","type":"模型选择","judge":"判断安培力公式中的电流应取该 θ 区域的电流而非总电流，长度取径向有效长度","why":"安培力只作用于所考察的那段载流导体，θ 很小时可视为长为 2l 的直导体棒","do":"把 θ 区域视为径向直棒，用该区域电流 I' 与径向长度 2l 代入安培力公式","expr":"F=BI'\\cdot 2l","cues":["取区域电流","视为直棒","长度取径向"],"concepts":["安培力","电流元","微元模型"]},{"title":"微元法求盘电阻","type":"数学处理","judge":"判断电阻率随半径变化，须沿半径把盘分成厚度为 dr 的微元串联积分，再按圆心角并联折算总电阻","why":"ρ=kr 随 r 变化，不能直接用均匀电阻公式，须对径向微元电阻积分；各扇形支路并联","do":"写出半径 r 处、径向长 dr、横截面积 θrd 的微元电阻，沿 r 从内半径积到 3l，再乘 θ/2π 得盘电阻","expr":"R_{\\text{盘}}=\\frac{\\theta}{2\\pi}\\int_x^{3l}k\\frac{dr}{\\theta d}=\\frac{k(3l-x)}{2\\pi d}","cues":["电阻率随半径变","沿半径积分","再按角度并联"],"concepts":["电阻定律","微元积分","并联电阻"]},{"title":"写功率并求极值","type":"临界条件","judge":"判断发热功率等于电动势平方除以盘电阻，并把内半径 x 作为变量求极大值","why":"外电阻忽略时盘自身为唯一耗能元件，功率由电动势与盘电阻共同决定，二者都随 x 变化，须求导找极值","do":"将 E'(x) 与 R盘(x) 代入 P=E'²/R盘，对 x 求导令其为零，解出使功率最大的内半径","expr":"P=\\frac{\\pi dB^{2}\\omega^{2}(3l-x)(3l+x)^{2}}{2k},\\ \\frac{dP}{dx}=0","cues":["外阻为零","功率随内半径变","求导找极大"],"concepts":["电功率","函数极值","闭合电路"]}],"265":[{"title":"识别核反应的两类变化","type":"模型选择","judge":"要判断俘获中子和β衰变各自改变质量数还是电荷数","why":"中子不带电、质量数为1，β衰变放出电子，核电荷数加1而质量数不变，这是两类过程的本质区别","do":"分别写出俘获中子和β衰变对质量数A、电荷数Z的影响","expr":"","cues":["中子只加质量数","β衰变只加电荷数"],"concepts":["质量数","电荷数","β衰变"]},{"title":"用守恒定x和y","type":"关系建立","judge":"要判断从钍到铀质量数差1、电荷数差2分别由哪种过程提供","why":"核反应前后质量数和电荷数守恒，总变化量必须等于各过程贡献之和","do":"对质量数列方程，对电荷数列方程，联立求x、y","expr":"232+x=233,\\quad 90+0=92-y","cues":["质量数差1","电荷数差2","列两个方程"],"concepts":["质量数守恒","电荷数守恒"]}],"266":[{"title":"判断波的类型","type":"模型选择","judge":"弹簧上疏密相间的波中，质点振动方向与波的传播方向是平行还是垂直","why":"纵波与横波的区别在于质点振动方向与传播方向是否平行，疏密相间正是质点沿传播方向往复振动形成的","do":"比较推拉方向（沿弹簧轴线）与波沿弹簧传播的方向，判断二者平行","expr":"","cues":["沿轴线推拉","疏密相间"],"concepts":["纵波","横波","质点振动方向"]},{"title":"区分波速与质点速度","type":"前提判断","judge":"标记物往复运动的速度与波在弹簧中传播的速度是不是同一个量","why":"波速由介质决定，质点速度是质点在平衡位置附近振动的速度，两者物理意义不同，不能混为一谈","do":"分别指出波速由介质决定、质点速度随振动相位变化，确认二者不等价","expr":"","cues":["波速由介质决定","质点只是来回振动","两个速度不一样"],"concepts":["波速","质点振动速度","介质"]},{"title":"波速由介质决定","type":"前提判断","judge":"改变推拉周期时，波在弹簧中的传播速度是否改变","why":"同一种介质中机械波的传播速度由介质性质决定，与波源振动周期无关","do":"固定介质（同一根弹簧），认定波速不变，只让周期变化","expr":"v=\\text{常量}","cues":["同一根弹簧","波速不变","只变周期"],"concepts":["波速","介质","周期"]},{"title":"周期与波长的关系","type":"关系建立","judge":"推拉周期变小时，波长如何变化","why":"由波速、波长、周期的关系，波速不变时波长与周期成正比","do":"用波长公式，在波速不变的前提下比较周期变小对应的波长变化","expr":"\\lambda=vT","cues":["周期越小","波长越短","波速不变"],"concepts":["波长","周期","波速"]},{"title":"波传递能量的判断","type":"结论整理","judge":"标记物由静止开始振动说明波传递了什么","why":"标记物原本静止，靠弹簧波获得振动能量，说明机械波在传播过程中传递能量","do":"把标记物从静止到振动的过程与能量获得对应起来","expr":"","cues":["由静止开始振动","获得了能量","波传递能量"],"concepts":["机械波","能量传递"]}],"267":[{"title":"气体温度是否变化","type":"前提判断","judge":"气球上升过程中球内气体温度是否随深度改变","why":"气球导热良好且过程缓慢，气体与恒温容器中的水始终充分热交换，温度被水体锁定","do":"比较球内气体与容器水温，确认二者始终相等","expr":"T=\\text{const}","cues":["导热良好","缓慢上升","水温不变"],"concepts":["热平衡","理想气体","等温过程"]},{"title":"体积随压强变化方向","type":"关系建立","judge":"上升时外界水压减小，球内气体体积是变大还是变小","why":"等温下理想气体压强与体积成反比，深度减小则压强减小，体积必增大","do":"由 pV=常量，比较上升前后压强，得出体积变化方向","expr":"pV=\\text{const},\\quad p\\downarrow\\Rightarrow V\\uparrow","cues":["越往上压强越小","气泡会胀大","等温膨胀"],"concepts":["玻意耳定律","压强"]},{"title":"内能与平均动能判断","type":"结论整理","judge":"温度不变时内能和分子平均动能是否改变","why":"理想气体无分子势能，内能只由温度决定，温度不变则内能不变、平均动能不变","do":"由温度不变直接判定内能与平均动能均不变","expr":"\\Delta U=0","cues":["温度不变内能不变","平均动能看温度","理想气体无势能"],"concepts":["内能","分子平均动能","理想气体"]},{"title":"做功与吸放热判断","type":"关系建立","judge":"体积增大时气体对外做功的正负，以及由第一定律确定吸热还是放热","why":"体积膨胀对外做正功而内能不变，热力学第一定律要求必须从外界吸热且吸热量等于对外做的功","do":"先判 W<0（对外做功），再由 ΔU=W+Q 且 ΔU=0 得 Q=−W>0","expr":"\\Delta U=W+Q=0\\Rightarrow Q=-W>0","cues":["膨胀对外做功","内能不变就得吸热","吸热等于做功"],"concepts":["热力学第一定律","等温膨胀"]}],"268":[{"title":"减速段位移与加速段相等","type":"前提判断","judge":"匀减速段初速度等于匀速速度、末速度为 0、加速度大小同为 a，其位移是否与匀加速段相同","why":"两段加速度大小相同、速度变化量大小相同（0→v 与 v→0），由 v²=2ax 知位移大小必相等，这是把总路程拆成三段的前提","do":"比较加速段与减速段的速度变化，判定两段位移均为 x","expr":"x=\\frac{v^2}{2a}","cues":["两段对称","速度变化一样","减速段也是x"],"concepts":["匀变速直线运动","速度位移公式","对称性"]},{"title":"匀速段位移由总长扣除","type":"关系建立","judge":"总位移 8x 减去加速段和减速段位移后，剩余部分是否就是匀速段位移","why":"三段运动首尾相接、方向相同，总位移等于各段位移之和，题设给出总距离 8x","do":"用 8x 减去两段各 x，得到匀速段位移 6x","expr":"8x-x-x=vt","cues":["总长减两段","剩下的是匀速","三段相加"],"concepts":["位移的合成","分段运动"]},{"title":"加速段平均速度求时间","type":"关系建立","judge":"匀加速段位移能否用平均速度乘时间表示，从而把 t' 与 v 联系起来","why":"初速为 0 的匀加速运动平均速度为 v/2，位移 x 已知，可避开加速度直接联系 v 与 t'","do":"对加速段写 x=(v/2)t'，与匀速段 6x=vt 联立消去 v","expr":"x=\\frac{v}{2}t'","cues":["用平均速度","初速为零","消掉速度"],"concepts":["平均速度","匀变速直线运动"]},{"title":"由位移比得时间比","type":"数学处理","judge":"联立两式后 t' 与 t 的比值是否只由位移比 1:6 决定","why":"两式中 v 相同，位移比等于时间与半时间的比，与 a、v 的具体值无关","do":"将 x=(v/2)t' 与 6x=vt 相除，解出 t'=t/3","expr":"t'=\\frac{t}{3}","cues":["消去速度","比出时间","三分之一"],"concepts":["比例关系","方程联立"]},{"title":"用加速段求 a 与 x 关系","type":"关系建立","judge":"把 t' 代回加速段位移公式时，应选含 a 与 t' 的 x=½at'² 而非含 v 的式子","why":"题目要求的是 x 与 a、t 的关系，只有代入 t'=t/3 才能把 a、t、x 三者联系起来","do":"将 t'=t/3 代入 x=½at'²，化简得 x 与 at² 的关系","expr":"x=\\frac{1}{2}a\\left(\\frac{t}{3}\\right)^2","cues":["代回加速段","换成a和t","消掉速度"],"concepts":["匀变速位移公式","代入消元"]}],"269":[{"title":"甲对木箱摩擦方向","type":"前提判断","judge":"甲相对木箱向哪边滑动，从而判断甲对木箱的摩擦力方向","why":"摩擦力方向由相对运动方向决定，甲向右运动而木箱静止，甲对木箱的摩擦力应向右，不是向左","do":"比较甲与木箱的运动方向，确定甲相对木箱向右滑动，再反推甲对木箱的摩擦力方向","expr":"","cues":["甲向右动","木箱不动","看相对运动"],"concepts":["相对运动","滑动摩擦力方向"]},{"title":"地面支持力是否变化","type":"模型选择","judge":"判断乙加速下落时，地面对木箱的支持力是否因乙的失重而改变","why":"乙有竖直向下的加速度，处于失重状态，把甲、乙、木箱取整体在竖直方向列牛顿第二定律，支持力随乙的加速度减小","do":"对甲、乙、木箱整体在竖直方向列方程，比较有无乙加速时的支持力","expr":"$F_N=M_{\\text{总}}g-ma$","cues":["取整体","乙在失重","竖直方向看加速度"],"concepts":["整体法","失重","牛顿第二定律"]},{"title":"绳中张力不等于乙重力","type":"关系建立","judge":"判断绳的张力是否等于乙的重力，即能否直接用 mg 作为拉甲的力","why":"乙加速下落，处于失重状态，绳的张力小于乙的重力，必须对乙单独列方程求张力","do":"对乙列牛顿第二定律，写出重力与张力的差等于质量乘加速度","expr":"$mg-T=ma$","cues":["乙在加速","张力小于重力","不能直接用重力"],"concepts":["牛顿第二定律","失重","绳的张力"]},{"title":"甲受绳拉力与摩擦力","type":"关系建立","judge":"甲在水平方向受绳的拉力和木箱给的滑动摩擦力，判断两者方向相反并列出合力","why":"甲向右加速，绳的拉力向右、滑动摩擦力向左，合力等于质量乘加速度，摩擦力大小由动摩擦因数与正压力决定","do":"对甲在水平方向列牛顿第二定律，摩擦力取动摩擦因数乘甲的重力","expr":"$T-\\mu mg=ma$","cues":["甲受两个力","摩擦力向左","拉力减摩擦力"],"concepts":["牛顿第二定律","滑动摩擦力","受力分析"]},{"title":"联立求加速度与张力","type":"数学处理","judge":"把甲、乙两式联立，消去张力求出共同的加速度，再回代求张力","why":"甲、乙由不可伸长的轻绳相连，加速度大小相同，两式含两个未知量可解","do":"将两式相加消去张力求加速度，再代入任一式求张力","expr":"$a=\\frac{mg-\\mu mg}{2m}=2.5\\,\\mathrm{m/s^2},\\ T=7.5\\,\\mathrm{N}$","cues":["加速度相同","两式相加","消去张力"],"concepts":["连接体","加速度关联","方程组求解"]}],"270":[{"title":"定圆心半径","type":"前提判断","judge":"由速度大小和磁场确定粒子圆周运动的半径与速度方向的关系","why":"洛伦兹力提供向心力，半径 R=mv/(qB)，代入 v=qBd/m 得 R=d，这是后续所有几何关系的基准长度","do":"写出 qvB=mv²/R，代入题给速度求 R","expr":"R=\\frac{mv}{qB}=d","cues":["先算半径","半径等于d","洛伦兹力提供向心力"],"concepts":["洛伦兹力","圆周运动半径"]},{"title":"入射方向与轨迹","type":"模型选择","judge":"粒子从 O 点向 x 轴上方各方向射入，轨迹圆都过 O 点且半径相同，需判断圆心随入射方向如何分布","why":"速度方向决定圆心位置（圆心在入射点垂直于速度的方向上，距 O 为 R），不同方向对应不同圆心，才能扫出打在板上的范围","do":"以 O 为起点、半径 d 画不同入射方向对应的轨迹圆，找出与板相交的极端轨迹","expr":"","cues":["圆心在速度垂线上","转一圈看轨迹","画轨迹圆"],"concepts":["圆周运动圆心","轨迹分析"]},{"title":"上表面两端点","type":"几何关系","judge":"判断上表面接收粒子区域的最近点和最远点分别由哪条轨迹给出","why":"沿 x 轴正方向射出时轨迹与上表面相切于最近点；恰过 N 点（板下沿）的轨迹对应上表面最远接收点，需用几何关系求两点的 x 坐标","do":"对最近轨迹用半径 d 求切点横坐标；对过 N 点的轨迹用勾股关系求最远点横坐标，再作差","expr":"s_{\\text{上}}=\\sqrt{3}d-d","cues":["相切时最近","过N点最远","作差求长度"],"concepts":["几何关系","相切条件"]},{"title":"下表面范围","type":"几何关系","judge":"判断下表面接收粒子区域的边界由哪两条轨迹决定","why":"粒子可恰好打到下表面 N 点，而沿 y 轴正方向射出时下表面接收点离 y 轴最远，需比较这两条轨迹确定下表面接收区间的长度","do":"找出打到下表面 N 点的轨迹与沿 y 轴射出轨迹在下表面的落点，求区间长度","expr":"s_{\\text{下}}=d","cues":["下表面也能接","沿y轴射出最远","区间长度是d"],"concepts":["几何关系","边界轨迹"]},{"title":"最短时间圆心角","type":"临界条件","judge":"判断哪条轨迹对应粒子在磁场中转过的最小圆心角","why":"周期 T=2πm/(qB) 与速度无关，时间只由圆心角决定，恰好打到下表面 N 点的轨迹圆心角最小","do":"对过 N 点的轨迹求圆心角，用 t=(θ/2π)T 计算最短时间","expr":"t_{\\text{min}}=\\frac{60^\\circ}{360^\\circ}\\cdot\\frac{2\\pi m}{qB}=\\frac{\\pi m}{3qB}","cues":["时间看圆心角","周期与速度无关","过N点转角最小"],"concepts":["周期","圆心角与时间"]}],"271":[{"title":"峰值转有效值","type":"前提判断","judge":"电流表示数对应的是交流电的有效值还是峰值","why":"交流电表读数为有效值，而输入电压以峰值形式给出，必须先用峰值除以根号二换算","do":"由输入电压表达式读出峰值，算出有效值作为原线圈电压","expr":"U_1=\\frac{U_m}{\\sqrt{2}}","cues":["电表读有效值","峰值除以根号二","先换算有效值"],"concepts":["交流电有效值","峰值"]},{"title":"滑动触头取部分匝数","type":"模型选择","judge":"副线圈接入电路的匝数是总匝数还是触头位置对应的那部分","why":"滑动触头把副线圈分成两段，只有接入电路的那段才参与变压，触头在正中间即取总匝数的一半","do":"把副线圈有效匝数写成总匝数的一半，再代入变压比求副线圈电压","expr":"U_2=\\frac{0.5n_2}{n_1}U_1","cues":["触头位置决定匝数","取一半匝数","接入电路那段"],"concepts":["理想变压器变压比","有效匝数"]},{"title":"副线圈电流由负载决定","type":"关系建立","judge":"副线圈电流该用输出电压除以负载电阻，还是由原线圈电流按匝数比反推","why":"理想变压器副线圈相当于电压为 U2 的电源，电流由外接电阻决定，原线圈电流随之被动变化","do":"写出副线圈电流与输出电压、电阻箱阻值的关系，作为判断各操作是否使示数变为 2.0 A 的依据","expr":"I_2=\\frac{U_2}{R}","cues":["电流看负载","电压除以电阻","副线圈定电流"],"concepts":["欧姆定律","理想变压器"]},{"title":"频率不影响有效值","type":"近似条件","judge":"改变交流电频率时，电压有效值和变压器输出电压是否改变","why":"理想变压器只按匝数比变换电压，与频率无关；频率变化只改变周期，不改变有效值","do":"比较改变频率前后输入电压有效值是否相同，从而判断副线圈电流是否变化","expr":"","cues":["频率只管周期","有效值没变","变压器与频率无关"],"concepts":["交流电频率","有效值"]}],"272":[{"title":"椭圆轨道半长轴","type":"几何关系","judge":"椭圆轨道的半长轴该用高度还是到月心的距离来算","why":"开普勒第三定律中的 a 是轨道半长轴，即卫星到中心天体中心的距离尺度，而题给的 a、b 是距月球表面的高度，必须各加半径 R","do":"把近月点、远月点到月心的距离相加再除以 2，得到半长轴","expr":"L=\\frac{(a+R)+(b+R)}{2}=\\frac{a+b}{2}+R","cues":["高度要加半径","半长轴不是高度","到月心算"],"concepts":["半长轴","开普勒第三定律"]},{"title":"两轨道周期相同","type":"前提判断","judge":"能否把椭圆轨道和圆轨道用同一个周期 T 代入开普勒第三定律","why":"题设明确两卫星运行周期都为 T，绕同一中心天体（月球）运动，故 k 值相同，周期相同则半长轴必相等","do":"对椭圆轨道和圆轨道分别写出半长轴三次方与周期平方之比，令其相等","expr":"\\frac{L^{3}}{T^{2}}=\\frac{r^{3}}{T^{2}}","cues":["周期一样","同一中心天体","k相同"],"concepts":["开普勒第三定律","中心天体"]},{"title":"圆轨道半径求解","type":"关系建立","judge":"由半长轴相等能否直接得出圆轨道半径 r","why":"周期相同使两轨道半长轴相等，圆轨道的半长轴就是其半径，故 r 等于椭圆半长轴","do":"令 r=L，把上一步的半长轴表达式代入","expr":"r=\\frac{a+b}{2}+R","cues":["半径等于半长轴","直接相等","代进去"],"concepts":["圆轨道半径","半长轴"]},{"title":"引力提供向心力","type":"模型选择","judge":"求月球质量该用哪条动力学方程","why":"只考虑月球引力，圆轨道上卫星做匀速圆周运动，万有引力全部提供向心力，这是求中心天体质量的唯一途径","do":"对圆轨道卫星列万有引力等于向心力的方程，向心加速度用周期表示","expr":"\\frac{GMm}{r^{2}}=m\\left(\\frac{2\\pi}{T}\\right)^{2}r","cues":["万有引力当向心力","用周期表示","求中心天体质量"],"concepts":["万有引力定律","向心力","中心天体质量"]},{"title":"质量表达式化简","type":"数学处理","judge":"由向心力方程解出 M 时 r 和 T 各在什么位置","why":"方程中 r 在分母一次、向心加速度中 r 在分子一次，整理后 M 与 r 的三次方成正比、与 T 的平方成反比，指数写错就会误判选项","do":"把方程两边约去 m，解出 M 并检查 r、T 的幂次","expr":"M=\\frac{4\\pi^{2}r^{3}}{GT^{2}}","cues":["三次方","平方在分母","约掉质量"],"concepts":["周期公式","幂次整理"]}],"273":[{"title":"两球受力方向与电场力方向","type":"前提判断","judge":"甲、乙带正电，电场水平向右，判断电场力沿水平向右还是沿斜面方向，以及库仑斥力沿两球连线方向","why":"正电荷受电场力方向与 E 同向（水平向右），库仑力沿连线互相排斥；只有先定下这两个方向，才能把力沿斜面与垂直斜面分解","do":"画出两球受力图，标出重力、支持力、库仑斥力、电场力的方向","expr":"","cues":["电场力水平向右","库仑力沿连线","先画受力图"],"concepts":["电场力方向","库仑定律","受力分析"]},{"title":"沿垂直斜面方向定支持力","type":"关系建立","judge":"垂直斜面方向无加速度，判断支持力是否只由重力垂直分量决定，与库仑力和电场力无关","why":"库仑力沿两球连线、电场力水平，它们在垂直斜面方向的分量是否为零需要判断；题设两球在同一高度、轨道对称，连线沿水平，故库仑力无垂直斜面分量，电场力也需分解","do":"对甲、乙分别写垂直斜面方向的平衡方程，得到 N1cosθ=mg、N2cosθ=2mg","expr":"$F_{N1}\\cos\\theta=mg,\\quad F_{N2}\\cos\\theta=2mg$","cues":["垂直斜面平衡","支持力只由重力定","先求支持力"],"concepts":["正交分解","平衡条件"]},{"title":"沿斜面方向联立消去支持力","type":"关系建立","judge":"沿斜面方向两球各自平衡，判断库仑力 F 与电场力 Eq 的大小关系，需联立两球方程消去 N 和 θ","why":"甲、乙沿斜面方向的平衡方程各含未知的 N 与 θ，单独一球无法求解，必须两球联立才能定出 F 与 Eq 的比例","do":"对甲写 F=N1sinθ+Eq，对乙写 N2sinθ=F+2Eq，代入 N1、N2 后联立","expr":"$F=F_{N1}\\sin\\theta+Eq,\\quad F_{N2}\\sin\\theta=F+2Eq$","cues":["两球联立","消去支持力","沿斜面平衡"],"concepts":["整体与隔离","平衡方程"]},{"title":"区分合力与库仑力求比值","type":"结论整理","judge":"F1、F2 是甲、乙所受静电力的合力（库仑力与电场力的矢量和），判断其大小是 F−Eq 与 F+2Eq 还是别的组合","why":"题目问的是静电力合力而非库仑力，甲受库仑力与电场力反向、乙受两者同向，方向判断错则比值颠倒","do":"分别写出 F1=|F−Eq|、F2=F+2Eq，代入 F=4Eq 求比值","expr":"$\\frac{F_1}{F_2}=\\frac{4Eq-Eq}{4Eq+2Eq}=\\frac12$","cues":["合力不是库仑力","方向相反要相减","先定方向再算大小"],"concepts":["力的合成","静电力合力"]},{"title":"用库仑定律反求场强","type":"关系建立","judge":"两球间距 L 即为库仑定律中的距离，判断 F=kq·2q/L² 并由此解出 E","why":"库仑力大小由库仑定律给出，与前面平衡得到的 F=4Eq 联立才能把 E 用 k、q、L 表示","do":"写 F=2kq²/L²，与 F=4Eq 联立解 E","expr":"$F=\\frac{2kq^2}{L^2}=4Eq\\Rightarrow E=\\frac{kq}{2L^2}$","cues":["库仑定律代L","联立求场强","间距就是L"],"concepts":["库仑定律","电场强度"]},{"title":"互换后判断能否再平衡","type":"临界条件","judge":"甲、乙互换位置后，判断是否存在满足两球同时平衡的 θ 与 F，即方程组是否有正解","why":"互换后电荷量与质量重新搭配，沿斜面方程变为 F+4Eq=0 型，需判断该式在物理量均为正时是否可能成立","do":"重写互换后的两球沿斜面平衡方程并联立，检查是否出现要求 F 为负或为零的矛盾","expr":"$F+4Eq=0$","cues":["互换后重列方程","看有没有解","出现负值不合理"],"concepts":["平衡条件","方程有解性"]}],"274":[{"title":"平衡阻力的判据","type":"实验操作","judge":"平衡阻力时应选小车不受牵引、但拖着纸带做匀速运动这一状态，还是静止或受牵引时匀速","why":"阻力只在小车运动时（含纸带限位孔摩擦）才实际起作用，平衡的目的是让重力沿轨道分力恰好抵消全部运动阻力，使合力为零","do":"比较三个选项对应的受力状态，确认只有无牵引且已挂好纸带、轻推后能匀速下滑，才说明阻力被完全平衡","expr":"","cues":["不受牵引","拖着纸带","匀速才平衡","静止不算"],"concepts":["平衡摩擦力","匀速直线运动","受力平衡"]},{"title":"由加速度方向定超失重","type":"图像读取","judge":"t=4s 时加速度沿正方向还是负方向，据此判断超重还是失重","why":"竖直向上为正，加速度向上为超重、向下为失重，取决于 a 的符号而非速度方向","do":"在图(c)中读 t=4s 对应的 a 值正负，再对照超重失重的定义","expr":"","cues":["看加速度方向","向上为正","向下就失重","别管速度"],"concepts":["超重与失重","加速度方向"]},{"title":"建 a 与 F_N 的关系式","type":"关系建立","judge":"把牛顿第二定律写成 a 关于 F_N 的函数，确定斜率和截距各由什么决定","why":"图像拟合的是 a-F_N 直线，必须先把方程化成 a=kF_N+b 的形式才能读出斜率、截距的物理含义","do":"对物体列竖直方向牛顿第二定律，解出 a 的表达式","expr":"$F_N-mg=ma\\ \\Rightarrow\\ a=\\frac{1}{m}F_N-g$","cues":["先列牛二","化成a等于","看斜率和截距"],"concepts":["牛顿第二定律","一次函数"]},{"title":"斜率截距的物理含义","type":"数学处理","judge":"斜率对应 1/m、纵截距对应 -g，判断质量变化时哪个变哪个不变","why":"截距只由重力加速度决定，与物体质量无关；斜率与质量成反比","do":"把图线 a 的斜率与 1/m、截距与 -g 对应起来，再分析 m 加倍后的变化","expr":"$k=\\frac{1}{m},\\quad b=-g$","cues":["斜率是质量的倒数","截距是重力加速度","质量翻倍斜率减半"],"concepts":["斜率","截距","反比关系"]},{"title":"选质量加倍后的图线","type":"结论整理","judge":"m 增大一倍后，新图线应与原图线交于同一点还是平行、截距是否相同","why":"斜率变为原来一半而截距不变，两条直线只在 F_N=0 处纵截距相同，随 F_N 增大差距变大","do":"在图(d)中找截距相同、斜率更小的那条线","expr":"$a=\\frac{1}{2m}F_N-g$","cues":["截距不变","斜率变小","找更平的那条"],"concepts":["图像平移与旋转","斜率变化"]}],"275":[{"title":"欧姆调零的本质","type":"前提判断","judge":"欧姆表调零时是把表笔短接（外电阻为零）还是断开，指针应指到电流满偏对应的哪一端刻度","why":"欧姆表刻度是电流满偏对应电阻零、电流为零对应电阻无穷，调零就是让外接电阻为零时表头恰好满偏","do":"判断红黑表笔短接，并确定满偏电流对应表盘上的 0 刻度（欧姆挡的零欧姆线）","expr":"","cues":["短接表笔","满偏就是零欧","断开是无穷"],"concepts":["欧姆调零","满偏电流","闭合电路欧姆定律"]},{"title":"挡位与中值电阻","type":"关系建立","judge":"换挡改变的是什么，中值电阻与挡位倍率的关系，从而判断 150 欧该用哪一挡","why":"欧姆表内阻等于中值电阻，倍率越大内阻越大；测量值应落在中值附近读数才准","do":"由中值刻度 15 与倍率确定各挡内阻，比较 150 欧与中值电阻的大小选挡","expr":"R_中=n\\times 15\\ \\Omega","cues":["中值附近最准","换挡改内阻","看倍率"],"concepts":["中值电阻","倍率","欧姆表内阻"]},{"title":"表盘读数乘倍率","type":"图像读取","judge":"虚线位置读出的刻度数字要乘当前挡位倍率才是电阻值","why":"欧姆表刻度标的是倍率前的数值，实际电阻等于读数乘倍率","do":"读虚线所指刻度数值，再乘以所选挡位的倍率","expr":"R=读数\\times 倍率","cues":["读数要乘倍率","看虚线位置","别忘乘十"],"concepts":["欧姆表读数","倍率"]},{"title":"断开S2后电路重构","type":"模型选择","judge":"闭合 S1、断开 S2 后，表内哪些电阻仍串在回路中，总内阻由哪些部分组成","why":"S2 断开使并联支路退出，回路只剩电池、表头、滑动变阻器（已调零）与电阻箱串联","do":"画出断开 S2 后的串联回路，写出总电阻为 r+Rg+R+R箱 的形式","expr":"E=I(r+R_g+R+R_{箱})","cues":["断开后只剩串联","滑动变阻器已调零","把内阻合并"],"concepts":["闭合电路欧姆定律","串联电路","等效内阻"]},{"title":"两次满偏半偏联立","type":"数学处理","judge":"用两组电流与电阻箱阻值建立两个方程，消去未知内阻求电动势","why":"同一电源电动势不变，两次测量给出两个闭合电路方程，未知量为 E 和内阻之和","do":"把 10 mA 配 228 欧、20 mA 配 88 欧分别代入，联立消去内阻求 E","expr":"E=I_1(R_1+R_内),\\ E=I_2(R_2+R_内)","cues":["两个方程两个未知","先消内阻","半偏对应中值"],"concepts":["闭合电路欧姆定律","联立方程","等效内阻"]}],"276":[{"title":"由P点坐标定入射角","type":"几何关系","judge":"P 到 x 轴的距离与半径之比对应的是入射角还是折射角的正弦","why":"入射光线平行于 x 轴，法线沿半径 OP，入射角是入射光线与法线的夹角，需用直角三角形中距离与半径的关系求","do":"在过 P 的半径与 x 轴构成的直角三角形中，用 P 到 x 轴的距离比半径求出入射角的正弦","expr":"\\sin\\alpha=\\frac{\\frac{\\sqrt{2}}{2}R}{R}","cues":["距离比半径","入射角看半径","平行x轴"],"concepts":["入射角","法线","几何关系"]},{"title":"由PQ弦长定折射角","type":"几何关系","judge":"P、Q 间距离在圆内对应哪段弦、与折射角构成什么三角形关系","why":"光在玻璃内沿 PQ 直线传播，PQ 是圆内弦，弦长与半径之比决定圆心角，进而与折射角关联","do":"把 PQ 与两条半径 OP、OQ 组成等腰三角形，用弦长比半径求出顶角，再换算成折射角","expr":"\\cos\\gamma=\\frac{\\frac{\\sqrt{3}}{2}R}{R}","cues":["弦长比半径","等腰三角形","折射角在内部"],"concepts":["弦长","圆心角","折射角"]},{"title":"折射定律求折射率","type":"关系建立","judge":"用空气到玻璃的折射定律时，角的正弦该取入射角还是折射角作分子","why":"光由空气（n≈1）射入玻璃，折射定律为空气侧正弦比玻璃侧正弦等于 1/n","do":"把已求出的入射角与折射角代入折射定律解出 n","expr":"n=\\frac{\\sin\\alpha}{\\sin\\gamma}","cues":["空气进玻璃","大角在空气","正弦之比"],"concepts":["折射定律","折射率"]},{"title":"全反射临界角条件","type":"临界条件","judge":"在 O 点发生全反射要求入射角满足什么不等式，临界角由谁决定","why":"光从玻璃射向空气才可能全反射，临界角满足正弦等于折射率倒数，入射角须不小于临界角","do":"由已求折射率算出临界角，写出 O 点入射角与临界角的比较关系","expr":"\\sin C=\\frac{1}{n}","cues":["玻璃到空气","临界角","大于等于"],"concepts":["全反射","临界角"]},{"title":"指向O点才可全反射","type":"前提判断","judge":"射到 O 点的光线，其入射角由入射方向还是由入射点位置决定","why":"O 点处法线沿半径方向，光线必须沿半径射向 O，入射角才等于光线与法线的夹角，否则光线不经过 O 点谈不到在 O 点全反射","do":"确定入射光线须沿半径指向 O，把入射角表示为入射光线与 x 轴夹角（或其余角）","expr":"","cues":["必须指向圆心","沿半径射入","法线是半径"],"concepts":["法线","入射角","全反射条件"]},{"title":"夹角范围及对称补全","type":"结论整理","judge":"入射光线与 x 轴夹角取哪个区间时入射角不小于临界角，另一侧是否由对称性补出","why":"入射角与光线和 x 轴夹角互为余角关系，临界角给出夹角上限；半圆关于 y 轴对称，左侧存在对应区间","do":"由入射角不小于临界角反解出与 x 轴夹角的区间，再利用对称性写出另一侧区间","expr":"","cues":["余角关系","左右对称","开区间端点"],"concepts":["对称性","角度范围"]}],"277":[{"title":"绳绕钉后的圆心与半径","type":"几何关系","judge":"绳子绕过 N、M 后，小球做圆周运动的圆心在哪、半径多大","why":"绳被两钉折成折线，只有判断出哪一段绳在约束小球、绕哪个钉转，才能写出向心力半径","do":"画出小球在 M 正下方与 M 相距 L 时的绳形，找出此时绳的哪一段绷直、绕哪个钉，量出该段长度","expr":"r=L","cues":["绕M转","半径是L","绳被两钉折住"],"concepts":["圆周运动","绳的约束","几何关系"]},{"title":"拉断点速度用机械能守恒","type":"模型选择","judge":"从最低点到拉断点，绳拉力是否做功、能否用机械能守恒","why":"绳拉力始终垂直于速度，只有重力做功，机械能守恒成立；若误把拉力做功列入就会多出未知量","do":"以最低点为初态、拉断点为末态列机械能守恒式，注意下降/上升的高度差","expr":"\\frac12 mv_0^2=mg\\cdot 2L+\\frac12 mv^2","cues":["只有重力做功","用机械能守恒","绳拉力不做功"],"concepts":["机械能守恒","功与能"]},{"title":"向心力方程定拉力","type":"关系建立","judge":"拉断瞬间沿半径方向的合力由哪些力提供，向心力指向哪里","why":"圆周运动径向方程必须用牛顿第二定律，且圆心在拉断点正上方，重力与拉力同向","do":"沿径向列牛顿第二定律，把重力与绳拉力都算进向心力","expr":"T-mg=m\\frac{v^2}{L}","cues":["径向列牛二","重力也指向圆心","向心力是合力"],"concepts":["牛顿第二定律","向心力"]},{"title":"平抛的竖直高度取 2L","type":"前提判断","judge":"平抛的抛出点离地多高，竖直位移是 L 还是 2L","why":"小球初始与地面接触无压力，说明最低点离地为零，拉断点在最低点上方 2L 处","do":"由初始“接触地面但无压力”定出最低点高度，再数到拉断点的竖直距离","expr":"h=2L","cues":["初始贴地","高度是2L","从地面算起"],"concepts":["平抛运动","竖直位移"]},{"title":"绳不松弛的临界在 N 正上方","type":"临界条件","judge":"要使绳全程不松弛，最危险的临界位置是哪里，临界条件是什么","why":"绳只能拉不能推，最容易松弛的是绕 N 转的最高点，该处绳拉力刚为零时重力单独提供向心力","do":"取绕 N 转的最高点为临界点，令绳拉力为零列向心力方程，再与最低点到该点的能量方程联立","expr":"mg=m\\frac{v'^2}{2L}","cues":["最高点最危险","拉力刚为零","绕N转的顶"],"concepts":["临界条件","向心力","绳的约束"]},{"title":"临界点上升高度 5L","type":"几何关系","judge":"从最低点到 N 正上方临界点，小球升高了多少","why":"能量方程中的高度差必须由几何关系准确给出，数错高度整个初速度就错","do":"由钉间距 L 与绳长 3L 定出 N 的位置，再算最低点到 N 正上方最高点的竖直距离","expr":"\\Delta h=5L","cues":["升高5L","N在上方","数高度差"],"concepts":["几何关系","动能定理"]}],"278":[{"title":"回路总电阻的判定","type":"前提判断","judge":"导体棒进入磁场形成回路时，回路中除定值电阻 R 外是否还有别的电阻，总电阻取多少","why":"导体棒自身电阻为 R、导轨电阻不计，棒与 R 串联构成闭合回路，欧姆定律中的分母必须是总电阻","do":"画出棒—导轨—R 的闭合回路，确认串联电阻只有棒电阻 R 与定值电阻 R","expr":"R_{\\text{总}}=2R","cues":["只有棒和电阻","导轨没电阻","两个电阻串联"],"concepts":["闭合电路欧姆定律","串联电阻"]},{"title":"安培力功率的求法","type":"关系建立","judge":"求安培力的功率时，用 P=Fv 还是用 P=I²R，两者是否等价、用哪个更直接","why":"安培力方向与棒速度反向，安培力做负功的功率大小等于 F安·v，也等于回路总电功率，但题目问的是安培力这一力的功率","do":"先由 E=BLv0、I=E/2R 求电流，再由 F安=BIL 求安培力，最后乘 v0","expr":"P=BIL\\cdot v_0=\\frac{B^2L^2v_0^2}{2R}","cues":["先求电流","再求安培力","乘速度"],"concepts":["安培力","感应电动势","功率"]},{"title":"变力过程用动量定理","type":"模型选择","judge":"棒在磁场中受随速度变化的安培力做减速运动，能否用牛顿定律直接求位移或时间，该选什么规律求电荷量","why":"安培力 F=B²L²v/2R 随 v 变化，加速度不恒定，无法用匀变速公式；但安培力冲量与电荷量通过 q=It 直接挂钩，动量定理可绕开速度细节","do":"对第 2 根棒从进入到停止列动量定理，把 ∫I dt 整体记为 q","expr":"-B\\bar{I}L\\Delta t=0-mv_0,\\quad q=\\bar{I}\\Delta t","cues":["力随速度变","不能用匀变速","冲量里有电量"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"各棒过程相互独立","type":"前提判断","judge":"前一根棒被锁定后是否仍参与后续回路、是否影响后一根棒的运动与产热","why":"棒停止后被锁定，但仍静止在磁场中与导轨接触，后续棒进入时回路结构改变；需判断每根棒从进入到停止这一段的初末速度都相同，故每段总产热相同","do":"比较每根棒进入时的初速度 v0 与锁定时的末速度 0，确认每段动能损失均为 mv0²/2","expr":"Q_{\\text{每根}}=\\frac{1}{2}mv_0^2","cues":["每根都从v0到0","动能损失一样","锁定后不动"],"concepts":["能量守恒","动能定理"]},{"title":"逐次回路电阻的递推","type":"关系建立","judge":"第 k 根棒减速过程中，回路里同时有几个电阻、总电阻是几倍的 R，从而定出 R 上分得热量的比例","why":"已锁定的前 k-1 根棒仍并联在导轨上（电阻均为 R），与第 k 根棒及定值电阻构成并串联组合，总电阻随 k 变化，R 上分热比例随之改变","do":"对第 k 根棒所在回路求等效电阻，用串联分热（热量按电阻正比分配）写出 R 上热量占总热量的比例","expr":"Q_{Rk}=\\frac{R}{R_{\\text{总},k}}\\cdot\\frac{1}{2}mv_0^2","cues":["前面棒还并在导轨上","总电阻在变","热量按电阻分"],"concepts":["并联等效电阻","焦耳热分配","串并联电路"]},{"title":"数列裂项求和","type":"数学处理","judge":"各段 R 上热量构成什么形式的数列，能否裂项相消求和","why":"每段比例为 1/[k(k+1)] 型，直接逐项相加无法化简，需拆成 1/k−1/(k+1) 才能望远镜求和","do":"写出第 k 项表达式，裂项后从 k=1 累加到 n，中间项相消","expr":"\\sum_{k=1}^{n}\\frac{1}{k(k+1)}=1-\\frac{1}{n+1}=\\frac{n}{n+1}","cues":["分母是相邻整数积","拆成两项差","中间全消掉"],"concepts":["裂项相消","数列求和"]}],"279":[{"title":"最大初动能与遏止电压挂钩","type":"关系建立","judge":"要判断光电子最大初动能能否直接用遏止电压的大小来比较","why":"遏止电压是使光电子恰好不能到达阳极的反向电压，由动能定理 eUc 等于最大初动能，所以 Ek 的大小顺序与 Uc 完全一致","do":"写出 Ek 与 Uc 的定量关系，把比较 Ek 转化为比较图中各金属对应的遏止电压","expr":"E_{k}=eU_{C}","cues":["看遏止电压","动能定理","电压越大动能越大"],"concepts":["遏止电压","最大初动能","动能定理"]},{"title":"从图中读出电压高低","type":"图像读取","judge":"要判断图中三条曲线与横轴交点（遏止电压）谁大谁小","why":"遏止电压对应光电流恰好为零时的反向电压，即图线与横轴负向交点的位置，交点越靠左电压越大","do":"比较三条图线与横轴交点的位置，按从左到右排出 Uc 的大小顺序","expr":"U_{C2}>U_{C3}>U_{C1}","cues":["看横轴交点","交点越左越大","光电流为零处"],"concepts":["遏止电压","光电流图像"]},{"title":"排除频率强度相同的干扰","type":"前提判断","judge":"要判断入射光频率相同这一条件是否影响 Ek 的比较","why":"由爱因斯坦光电效应方程，最大初动能由入射光频率和金属逸出功共同决定；频率相同则差异只来自各金属逸出功不同，不影响 Ek 与 Uc 的对应关系","do":"确认频率相同只说明各金属逸出功不同，不改变 Ek=eUc 的换算，也不因强度相同而改变遏止电压","expr":"E_{k}=h\\nu-W_{0}","cues":["频率相同","逸出功不同","强度不影响电压"],"concepts":["光电效应方程","逸出功","入射光频率"]}],"280":[{"title":"读图定平衡位置","type":"图像读取","judge":"从 F-r 图像上判断哪一点分子间作用力为零，即平衡位置 r0","why":"分子间作用力为零的位置就是引力和斥力相平衡的位置，题设规定该处分子势能为零，是整条推理的起点","do":"在图上找 F=0 的横坐标，确认它对应 r0","expr":"F(r_0)=0","cues":["找力为零的点","横轴交点","平衡位置"],"concepts":["分子间作用力","平衡位置"]},{"title":"由力方向定做功正负","type":"关系建立","judge":"判断 r>r0 与 r<r0 两侧分子间作用力分别表现为引力还是斥力，以及分子靠近或远离时该力做正功还是负功","why":"分子势能的变化由分子间作用力做功的正负决定，力做负功则势能增大，做正功则势能减小","do":"在图上分别取 r>r0 和 r<r0 两段，读出 F 的正负（方向），再结合位移方向判断做功正负","expr":"W=-\\Delta E_p","cues":["看力的方向","引力做负功","斥力做负功"],"concepts":["分子势能","功与势能变化"]},{"title":"以零点为基准定势能符号","type":"前提判断","judge":"以 r0 处势能为零为基准，判断 r 偏离 r0 时势能是正还是负","why":"题设规定 r=r0 时 Ep=0，而两侧偏离时分子间作用力都做负功，势能都从零增大，故偏离处势能必为正","do":"从 r0 出发分别向 r 增大和 r 减小两个方向推势能变化趋势，比较与零点的关系","expr":"E_p(r_0)=0,\\quad E_p(r)>0\\ (r\\neq r_0)","cues":["两侧都变大","零点在最低处","势能都是正的"],"concepts":["分子势能","势能零点"]},{"title":"定势能曲线形状","type":"结论整理","judge":"判断 Ep-r 图像在 r0 处取最小值且两侧单调上升，而不是在 r0 处取最大值或穿过零点变号","why":"由两侧偏离均使势能增大可知 r0 是势能极小点，曲线呈谷形，最小值恰为零","do":"把 r0 处为零、两侧上升的谷形曲线与各选项图像比对","expr":"E_p^{\\min}=E_p(r_0)=0","cues":["谷形曲线","最低点为零","两侧往上走"],"concepts":["分子势能曲线","极小值"]}],"281":[{"title":"判断条纹间距由什么决定","type":"关系建立","judge":"条纹间距是否只由双缝间距、屏距和波长决定，与偏振片是否插入、如何转动无关","why":"双缝干涉条纹间距公式 Δx=Lλ/d 中不含偏振片参数，P1、P2 只改变透过的光强和偏振方向，不改变波长和几何量","do":"写出 Δx=Lλ/d，逐一核对 P2 转动时 L、d、λ 是否变化","expr":"\\Delta x=\\frac{L}{d}\\lambda","cues":["间距只看波长","偏振片不改间距","Ldλ都没变"],"concepts":["双缝干涉","条纹间距公式"]},{"title":"判断两偏振片透振方向夹角","type":"前提判断","judge":"P2 绕轴转 90° 过程中，P1 与 P2 透振方向的夹角从 0° 连续增大到 90°","why":"初始时两片透振方向平行，P1 不动、P2 绕 OO' 轴转动，夹角随之单调增大","do":"以 P1 透振方向为基准，写出 P2 转过角 θ 后两片透振方向的夹角 θ","expr":"\\theta:0\\to 90^{\\circ}","cues":["从平行转到垂直","夹角越来越大","先平行后垂直"],"concepts":["偏振片","透振方向"]},{"title":"判断透过光强如何变化","type":"关系建立","judge":"经两片偏振片后的光强随夹角增大而减小，转到 90° 时透射光强为零","why":"马吕斯定律 I=I0cos²θ，θ 从 0° 增到 90° 时 cos²θ 单调减小到 0","do":"对 P2 用马吕斯定律，比较 θ=0°、中间角、90° 三个位置的透射光强","expr":"I=I_0\\cos^{2}\\theta","cues":["光强按余弦平方变","转到垂直就没光了","亮度逐渐变暗"],"concepts":["马吕斯定律","光强"]},{"title":"区分亮度与间距两个结论","type":"结论整理","judge":"转动过程中变的是条纹亮度，不变的是条纹间距，不能把两者混为一谈","why":"光强只影响干涉条纹的明暗程度，条纹位置和间距由光程差和波长决定，两者相互独立","do":"把间距结论与亮度结论分开表述，排除“间距变大/变小”“亮度不变”等干扰说法","expr":"","cues":["间距不变亮度变","变暗但条纹不动","别把亮度当间距"],"concepts":["干涉条纹亮度","条纹间距"]}],"282":[{"title":"曝光径迹当弧长","type":"几何关系","judge":"照片上留下的径迹长度能否直接当作小球在曝光时间内走过的弧长","why":"径迹是发光小球在底片上连续曝光形成的轨迹，其长度对应小球实际走过的弧长，题给的“半径的五分之一”就是这段弧长","do":"用半径乘以五分之一算出径迹长度，作为曝光时间内的位移大小","expr":"\\Delta l=\\frac{1}{5}r","cues":["径迹就是弧长","五分之一半径","量出轨迹长度"],"concepts":["弧长","轨迹"]},{"title":"短曝光近似匀速","type":"近似条件","judge":"曝光时间极短、径迹只占圆周一小段时，能否把这段运动当作匀速直线运动处理","why":"曝光时间只有五十分之一秒，小球在最低点附近速度变化极小，可用平均速度代替最低点的瞬时速度","do":"用径迹长度除以曝光时间求速度，并认定它就是最低点速度","expr":"v=\\frac{\\Delta l}{\\Delta t}","cues":["时间很短","近似匀速","平均速度代替瞬时速度"],"concepts":["瞬时速度","平均速度"]},{"title":"最低点向心方向","type":"模型选择","judge":"在最低点沿半径方向指向圆心的合力由哪些力构成","why":"最低点细线拉力竖直向上、重力竖直向下，二者合力提供向心力，方向指向圆心","do":"沿竖直方向列牛顿第二定律方程，拉力减重力等于向心力","expr":"T-mg=m\\frac{v^{2}}{r}","cues":["指向圆心","拉力减重力","向心力方程"],"concepts":["向心力","牛顿第二定律","圆周运动"]},{"title":"向心加速度用线速度","type":"关系建立","judge":"向心加速度该用线速度与半径表示，还是误用角速度或其他量","why":"已知的是线速度和半径，向心加速度的标准形式为速度平方除以半径","do":"把刚求出的速度与半径代入向心加速度表达式再解拉力","expr":"a=\\frac{v^{2}}{r}","cues":["速度平方除以半径","用线速度","先算向心加速度"],"concepts":["向心加速度","线速度"]}],"283":[{"title":"匀速时牵引力等于阻力","type":"前提判断","judge":"小车匀速运动时，电动机的牵引力与阻力是否大小相等","why":"匀速直线运动合力为零，牵引力必须与阻力平衡，否则无法由阻力求出牵引力","do":"对小车沿运动方向列平衡方程，把阻力表达式代入","expr":"F=f=kv","cues":["匀速就是受力平衡","牵引力等于阻力"],"concepts":["平衡条件","阻力"]},{"title":"机械功率用牵引力乘速度","type":"关系建立","judge":"求电动机输出的机械功率时，应使用牵引力与速度的乘积，而不是某个力单独平方","why":"机械功率定义为力与沿力方向速度的乘积，牵引力做功的功率才是电动机输出的机械功率","do":"用牵引力乘以速度，并代入阻力表达式化简","expr":"P_机=Fv=kv^{2}","cues":["功率等于力乘速度","先求牵引力再乘速度"],"concepts":["机械功率","牵引力"]},{"title":"效率是输出比输入","type":"关系建立","judge":"电动机效率 50% 时，电功率与机械功率谁是分子谁是分母","why":"效率定义为有用输出与总输入的比值，电动机的有用输出是机械功率，输入是电功率","do":"由效率定义反解电功率，把机械功率除以效率","expr":"P_电=P_机/0.5=2kv^{2}","cues":["效率是输出除以输入","电功率比机械功率大"],"concepts":["电动机效率","电功率"]},{"title":"光电效率对应光能输入","type":"关系建立","judge":"光伏电池的光电转换效率中，电功率与获得的太阳能功率谁是输出谁是输入","why":"光电转换效率是输出的电功率与输入的太阳能功率之比，题目所求正是单位时间获得的太阳能即输入功率","do":"由光电效率定义把电功率除以效率，得到光能功率","expr":"P_光=P_电/η=2kv^{2}/η","cues":["太阳能是输入","电功率除以效率"],"concepts":["光电转换效率","太阳能功率"]}],"284":[{"title":"分离瞬间动量守恒","type":"模型选择","judge":"弹射过程极短、内力远大于引力，能否对两舱系统用动量守恒","why":"弹射是短时内力作用，行星引力冲量可忽略，系统动量守恒；若误用机械能守恒或分开后各自用动量定理就做不下去","do":"对分离前后两舱系统沿速度方向列动量守恒方程","expr":"6mv=5mv_1+mv_2","cues":["弹射时间极短","内力远大于引力","取两舱系统"],"concepts":["动量守恒","内力","短时作用"]},{"title":"由圆轨道求原速度","type":"前提判断","judge":"分离前组合体做圆周运动，其线速度由万有引力提供向心力决定，与质量无关","why":"万有引力充当向心力，组合体质量在方程两边约去，速度只由中心天体质量和轨道半径决定","do":"对分离前组合体列万有引力等于向心力的方程，解出原速度","expr":"G\\frac{M\\cdot6m}{r^2}=6m\\frac{v^2}{r}\\Rightarrow v=\\sqrt{\\frac{GM}{r}}","cues":["万有引力提供向心力","质量约掉","先求原速度"],"concepts":["万有引力定律","向心力","圆周运动"]},{"title":"速度方向与正负号","type":"关系建立","judge":"返回舱被向前弹射，其速度方向与原速度同向，动量方程中取同号相加","why":"题设“沿运动方向向前弹射”，返回舱相对行星速度方向与原速度同向，若误判为反向则动量方程符号出错","do":"确定 v、v_2 同向取正，v_1 待定，按同向列式","expr":"6mv=5mv_1+m\\cdot2\\sqrt{\\frac{GM}{r}}","cues":["向前弹射","同向取正","方向别弄反"],"concepts":["速度方向","一维动量守恒"]},{"title":"质量比代入","type":"数学处理","judge":"质量比 5:1 是轨道舱与返回舱之比，总质量是 6m 而非 5m 或 m","why":"动量守恒中总质量必须用两舱质量之和，误把总质量当成 5m 或把返回舱质量当成 6m 会算错系数","do":"设返回舱质量 m、轨道舱 5m，总质量 6m，代入动量方程解 v_1","expr":"v_1=\\frac{6v-2v}{5}=\\frac{4}{5}\\sqrt{\\frac{GM}{r}}","cues":["总质量是六份","返回舱一份","轨道舱五份"],"concepts":["质量比","总质量"]}],"285":[{"title":"棒切割的有效长度","type":"模型选择","judge":"导体棒在区域Ⅰ、Ⅱ中切割磁感线的有效长度分别是多少","why":"动生电动势 E=Blv 中的 l 是棒垂直于速度和磁场方向的有效长度，区域Ⅱ宽仅 0.5L，棒只有 0.5L 处于磁场中","do":"分别对区域Ⅰ（正方形边长 L）和区域Ⅱ（宽 0.5L）确定有效切割长度","expr":"E_1=BLv,\\quad E_2=0.5BLv","cues":["取有效长度","区域二只有半根","棒长不等于切割长"],"concepts":["动生电动势","有效切割长度"]},{"title":"两区域磁场方向相反","type":"前提判断","judge":"两区域磁场反向是否影响电动势大小的计算","why":"电动势有效值只由 E 的大小和持续时间决定，方向反转不改变 E² 对时间的平均","do":"确认求有效值时只需用 E 的平方，不必区分正负方向","expr":"","cues":["方向相反不影响大小","只看绝对值","平方后没正负"],"concepts":["交变电流有效值","磁场方向"]},{"title":"确定运动周期","type":"关系建立","judge":"导体棒相邻两次进入同一位置的时间间隔（周期）由什么决定","why":"棒每隔 2L 固定一根，传送带速度 v，故同一位置相邻棒到达的时间间隔为 2L/v","do":"用棒间距除以带速求周期 T","expr":"T=\\frac{2L}{v}","cues":["看棒间距","周期不是走一个区域","间距两倍棒长"],"concepts":["周期","匀速运动"]},{"title":"各段持续时间","type":"几何关系","judge":"棒通过区域Ⅰ、Ⅱ各用多长时间，一个周期内剩余时间电动势是否为零","why":"区域Ⅰ沿运动方向长 L、区域Ⅱ沿运动方向长 L，故各历时 L/v；周期 2L/v 中剩余时间棒不在磁场中，E=0","do":"用区域沿运动方向的长度除以 v 求 t1、t2，并与 T 比较","expr":"t_1=t_2=\\frac{L}{v},\\quad T=\\frac{2L}{v}","cues":["走一个区域用多久","剩下时间没电动势","两段各占一半"],"concepts":["运动学关系","分段电动势"]},{"title":"有效值按平方平均","type":"数学处理","judge":"非恒定（分段恒定）电动势的有效值该用哪种平均","why":"有效值定义是电流热效应等效，须对 E² 按时间加权平均再开方，不能对 E 直接取算术平均","do":"列 E1²t1+E2²t2=E有²T，代入 t1、t2、T 求解","expr":"\\frac{E_1^2}{R}t_1+\\frac{E_2^2}{R}t_2=\\frac{E_{\\text{有}}^2}{R}T","cues":["平方再平均","不能直接取平均","按发热等效"],"concepts":["有效值定义","焦耳热等效"]}],"286":[{"title":"建立坡面内二维坐标","type":"几何关系","judge":"要判断沿坡面下滑方向与挡板法向在坡面内如何分解，即 MN 与 QN、PN 的夹角关系","why":"题设给出 ∠MNQ=θ 且 QN⊥PN，只有把坡面内两个正交方向（沿 QN 与沿 PN）定出来，才能把重力的坡面分量和挡板弹力方向统一到同一坐标系","do":"在坡面内以 QN 方向（坡底指向）和 PN 方向（垂直 QN）为两轴，标出 MN 与 QN 的夹角 θ，写出沿 MN 方向与垂直 MN 方向的单位矢量","expr":"","cues":["坡面内建坐标","MN和QN夹角是θ","沿坡面和垂直坡面分"],"concepts":["几何分解","正交分解"]},{"title":"重力沿坡面的分量","type":"关系建立","judge":"要判断重力在坡面内的分量沿 MN 方向的分量是 mg sinθ·cosθ，而不是 mg sinθ","why":"重力沿坡面的分量为 mg sinθ，但它沿 QN 方向而非沿 MN 方向，MN 与 QN 成 θ 角，故需再乘 cosθ 才是沿 MN 的驱动力","do":"把 mg sinθ 沿 MN 与垂直 MN 分解，取沿 MN 向下的分量","expr":"F_{\\parallel}=mg\\sin\\theta\\cos\\theta","cues":["重力沿坡面再投影","要乘一个余弦","不是直接mgsinθ"],"concepts":["重力分解","斜面模型"]},{"title":"坡面正压力与挡板正压力","type":"前提判断","judge":"要判断坡面给的支持力由重力垂直坡面的分量决定，挡板给的支持力由重力在坡面内垂直 MN 的分量决定，两者互不叠加","why":"坡面与挡板是两个互相垂直的硬面，各自只承受垂直于自身表面的压力分量；把两者混成一个正压力就会漏掉一份摩擦力","do":"分别写出垂直坡面方向的力平衡和坡面内垂直 MN 方向的力平衡，得到两个正压力","expr":"N_1=mg\\cos\\theta,\\quad N_2=mg\\sin\\theta\\sin\\theta","cues":["两个面各有一个正压力","别把两个支持力合并"],"concepts":["正压力","力平衡","垂直面约束"]},{"title":"两处摩擦力求和","type":"模型选择","judge":"要判断沿 MN 滑行时坡面摩擦力和挡板摩擦力同时存在且方向都沿 MN 向上，需相加","why":"材料同时与坡面和挡板接触并相对滑动，两个接触面都产生滑动摩擦力，且都阻碍沿 MN 的运动，缺一项加速度就偏大","do":"对两个正压力分别乘 μ 得到两个摩擦力，再与重力沿 MN 分量合成求合力","expr":"f_1=\\mu mg\\cos\\theta,\\quad f_2=\\mu mg\\sin^2\\theta","cues":["两个面都有摩擦","摩擦力要加起来","挡板也摩擦"],"concepts":["滑动摩擦力","受力分析"]},{"title":"沿 MN 列牛顿第二定律","type":"关系建立","judge":"要判断合力只取沿 MN 方向的分量，把驱动力减去两个摩擦力后等于 ma","why":"加速度沿 MN 方向，垂直 MN 方向合力为零，只有沿 MN 方向的方程能解出 a","do":"沿 MN 方向列方程，把重力分量与两个摩擦力代入，解出 a","expr":"mg\\sin\\theta\\cos\\theta-\\mu mg\\cos\\theta-\\mu mg\\sin^2\\theta=ma","cues":["沿MN列方程","驱动力减两个摩擦","垂直方向合力为零"],"concepts":["牛顿第二定律","匀加速直线运动"]}],"287":[{"title":"由波形图读甲波长","type":"图像读取","judge":"从 t=0 的波形图上读出甲波一个完整波形的长度","why":"波长是波形图上相邻同相点的距离，甲波沿 x 轴负向传播，波形图直接给出其空间周期","do":"在图上找甲波相邻两个波峰（或相邻两个同相零点）的横坐标差","expr":"\\lambda_{\\text{甲}}=4\\,\\mathrm{m}","cues":["看相邻波峰","数一个完整波形","图上直接量"],"concepts":["波长","波形图"]},{"title":"波速波长定周期","type":"关系建立","judge":"用波速、波长与周期的关系把读出的波长换成周期","why":"波速由介质决定，v=λ/T 是波传播的基本运动学关系","do":"对甲、乙分别代入 v=1 m/s 求周期","expr":"T=\\frac{\\lambda}{v}","cues":["先求周期","波速定周期","用波长除波速"],"concepts":["波速","周期","波长"]},{"title":"由位移反推乙波长","type":"几何关系","judge":"利用 N 点位移 1 cm（振幅 2 cm）确定 N 到平衡位置质点的水平距离，再结合图上 2 m 到 6 m 的区间约束解出乙波波长","why":"简谐波上质点位移 y=A sin(2πx/λ)，位移为振幅一半对应特定相位，且乙波在给定区间内的波形长度必须与半波长整数关系吻合","do":"设 N 左侧平衡位置质点与 N 的距离为 x，由 1=2sin(πx/(λ乙/2)) 及 6−2−2x=λ乙/2 联立求解","expr":"1=2\\sin\\frac{2\\pi x}{\\lambda_{\\text{乙}}},\\quad 6-2-2x=\\frac{\\lambda_{\\text{乙}}}{2}","cues":["位移是振幅一半","找平衡位置点","用区间长度约束"],"concepts":["简谐波方程","相位","波长"]},{"title":"同侧法判质点振动方向","type":"模型选择","judge":"由波的传播方向与质点位置判断质点此刻的速度方向","why":"质点振动方向与波传播方向满足同侧法（上下坡法），不能只看位移正负","do":"对 M 看甲波向左传播、对 N 看乙波向右传播，分别定出 t=0 时的运动方向","expr":"","cues":["同侧法","看波往哪传","上坡下坡"],"concepts":["同侧法","振动方向","波的传播方向"]},{"title":"按周期整数倍推演状态","type":"数学处理","judge":"把 6 s 换算成各波周期的倍数，判断质点经过该时间后的位置与速度方向","why":"经过整数个周期质点回到原状态，经过半整数个周期位移反向、速度反向","do":"分别用 6 s 除以 T甲、T乙，看是整数倍还是半整数倍，再叠加初态方向","expr":"t=nT\\ \\text{或}\\ t=\\left(n+\\tfrac12\\right)T","cues":["看几个周期","整数倍回原状态","半周期反向"],"concepts":["周期性","简谐运动"]}],"288":[{"title":"释放后运动性质","type":"模型选择","judge":"物品脱离无人机后做什么运动","why":"物品相对无人机无初速度释放，初速度就是无人机在该点的速度，方向水平，只受重力","do":"把物品的运动判定为平抛，竖直方向自由落体、水平方向匀速","expr":"H=\\frac{1}{2}gt^{2},\\quad x=vt","cues":["平抛","初速度水平","竖直自由落体"],"concepts":["平抛运动","运动的分解"]},{"title":"落点范围的几何约束","type":"几何关系","judge":"水平射程最大能取到多少才不飞出圆形目标区","why":"物品落点与 O 点的水平距离由抛出点在地面的投影到落点的位移决定，抛出点投影在半径 R2 的圆上，落点须在半径 R1 的圆内，最远沿径向向外","do":"用勾股关系把最大水平射程与两圆半径联系起来","expr":"x_{\\max}=\\sqrt{R_{1}^{2}-R_{2}^{2}}","cues":["沿半径向外最远","两圆半径勾股","投影在圆上"],"concepts":["位移合成","几何约束"]},{"title":"线速度与角速度换算","type":"关系建立","judge":"无人机圆周运动的角速度与物品水平初速度如何对应","why":"物品初速度等于无人机线速度，而线速度由角速度和轨道半径 R2 决定","do":"由最大射程求最大线速度，再除以 R2 得最大角速度","expr":"v_{\\max}=\\frac{x_{\\max}}{t},\\quad \\omega_{\\max}=\\frac{v_{\\max}}{R_{2}}","cues":["先求速度再求角速度","圆周运动","线速度与角速度"],"concepts":["圆周运动","线速度与角速度"]},{"title":"落地时间与到B时间比较","type":"临界条件","judge":"物品落地前无人机是否已从 A 转到 B","why":"判断 B 点释放的物品与 A 点释放的物品是否同时在空中，需比较无人机转过 90° 所用时间与物品下落时间","do":"用圆心角除以角速度求 A 到 B 的时间，与下落时间 t 比较大小","expr":"t'=\\frac{\\pi/2}{\\omega_{\\max}},\\quad t=\\sqrt{\\frac{2H}{g}}","cues":["转过四分之一圆","比时间长短","谁先落地"],"concepts":["圆周运动周期","时间比较"]}],"289":[{"title":"碗内平衡的受力模型","type":"模型选择","judge":"小球在光滑碗内静止时受哪几个力、支持力沿什么方向","why":"碗面光滑无摩擦，支持力必沿半径指向球心 O，三力（重力、支持力、库仑斥力）共点平衡","do":"对甲、乙分别画三力受力图，确认支持力沿 OA、OB 方向","expr":"","cues":["三力平衡","支持力沿半径","没有摩擦力"],"concepts":["共点力平衡","弹力方向","库仑力"]},{"title":"由弦长定圆心角","type":"几何关系","judge":"由 AB=√3R 判断弦 AB 对应的圆心角及三角形 OAB 的形状","why":"弦长与半径之比决定圆心角，是后续确定各力方向角的前提","do":"用 2R sin(θ/2)=√3R 求 ∠AOB，再得 ∠OAB=∠OBA","expr":"2R\\sin\\frac{\\angle AOB}{2}=\\sqrt{3}R","cues":["弦长比半径","先求圆心角","等腰三角形"],"concepts":["圆的几何关系","弦长公式"]},{"title":"力的方向角与正弦定理","type":"关系建立","judge":"库仑力沿 AB 连线，需确定它与重力、支持力之间的夹角","why":"库仑力沿 AB 方向，而支持力沿半径，只有把三个力的夹角都定出来才能用正弦定理建立质量与库仑力的关系","do":"找出 AB 与 OC 的交点 G，算出 ∠OGA、∠OGB，对甲、乙分别列正弦定理式","expr":"\\frac{m g}{\\sin 30^{\\circ}}=\\frac{F_{电}}{\\sin\\angle OGA}","cues":["库仑力沿连线","找夹角","用正弦定理"],"concepts":["正弦定理","力的合成与分解","库仑定律"]},{"title":"比较两球质量","type":"结论整理","judge":"由两球所受库仑力大小相等（作用力与反作用力），比较两式中角度正弦的大小","why":"库仑力是一对相互作用力，大小相同，故质量之比由对应角的正弦之比决定","do":"比较 sin45° 与 sin75° 的大小，得出 m甲 与 m乙 的大小关系","expr":"\\frac{m_{甲}}{m_{乙}}=\\frac{\\sin\\angle OGB}{\\sin\\angle OGA}","cues":["库仑力等大","比正弦值","谁重谁轻"],"concepts":["牛顿第三定律","共点力平衡"]},{"title":"叠加法判场强与电势","type":"模型选择","judge":"把 A、B 两电荷的电场拆成等量异种电荷场与 A 点剩余电荷场的叠加","why":"两电荷量不等，直接叠加不便比较；拆成对称部分（等量异种）加剩余部分，可利用对称性判断 E、F 及 C、D 间的场强与电势","do":"先看等量异种部分在 E、F 的场强等大反向/同向，再叠加 A 点 3q 电荷在 E、F 产生的不同场强；沿 C→D 判断电场力做功正负","expr":"E=E_{等量异种}+E_{3q}","cues":["拆成等量异种","再叠加剩余电荷","看电场力做功"],"concepts":["电场叠加","点电荷场强","电势能"]},{"title":"沿 OD 判电势极值","type":"临界条件","judge":"OD 与 AB 交点是否为距两电荷最近处，从而判断电势沿 OD 的变化趋势","why":"电势是标量，两正电荷产生的电势在离电荷最近处最大，故沿 O→D 电势先升后降","do":"找 OD 与 AB 的交点，比较该点与 O、D 到两电荷的距离","expr":"\\varphi=\\frac{k\\cdot2q}{r_1}+\\frac{kq}{r_2}","cues":["电势是标量","离电荷越近越高","先升后降"],"concepts":["电势叠加","点电荷电势"]}],"290":[{"title":"由抛物线定类平抛","type":"模型选择","judge":"区域Ⅰ中轨迹为以 y 轴对称的抛物线，能否判定粒子做类平抛（匀变速曲线）运动","why":"抛物线轨迹是恒力作用下初速度与力垂直的运动的特征，说明电场力沿 y 方向、初速度沿 x 方向","do":"把区域Ⅰ运动分解为 x 方向匀速、y 方向初速为零的匀加速，写出两个分运动方程","expr":"x=v_0t,\\quad y=\\tfrac12 at^2","cues":["类平抛","分解成两个方向","初速度沿x轴"],"concepts":["类平抛运动","运动的分解","匀强电场"]},{"title":"由轨迹弯曲定电场方向","type":"前提判断","judge":"由轨迹向 y 轴正方向弯曲判断电场力方向，进而确定电场方向","why":"正电荷受力方向即电场方向，轨迹凹侧指向合力方向","do":"观察抛物线开口/弯曲方向，确定加速度沿 y 轴正向，再由正电荷定电场方向","expr":"qE=ma","cues":["看轨迹往哪弯","正电荷受力同电场","力指向凹侧"],"concepts":["电场力方向","曲线运动条件"]},{"title":"正弦图像判圆周运动","type":"图像读取","judge":"区域Ⅱ中 y-t 图像为正弦曲线一部分，能否判定粒子做匀速圆周运动","why":"匀速圆周运动中某方向投影随时间按正弦规律变化，且速率不变","do":"由正弦图像的振幅和周期读出圆周运动的半径与周期信息，与几何边界条件对照","expr":"y=A\\sin\\omega t","cues":["正弦就是圆周投影","匀速圆周运动","看振幅和周期"],"concepts":["匀速圆周运动","简谐投影","洛伦兹力"]},{"title":"速度合成求入射速度","type":"关系建立","judge":"进入磁场时的合速度需由类平抛两分速度合成，而非只用初速度","why":"洛伦兹力用合速度，半径和磁感应强度都依赖合速度大小与方向","do":"用 v_y=at 与 v_0 合成求 v 及与竖直方向夹角，再代入 qvB=mv²/R","expr":"v=\\sqrt{v_0^2+(at)^2},\\quad \\sin\\theta=\\frac{v_0}{v}","cues":["合速度不是初速度","先求竖直分速度","速度方向要算夹角"],"concepts":["速度合成","洛伦兹力提供向心力"]},{"title":"几何定圆心与半径","type":"几何关系","judge":"由入射点、入射速度方向和出射边界条件确定圆周圆心位置与半径","why":"圆心在过入射点且垂直速度方向的直线上，半径由边界 x=3L 处的几何约束确定","do":"画轨迹图，用入射角与边界位置列几何关系求 R 和圆心坐标","expr":"R\\sin\\theta \\text{ 与 } 3L \\text{ 的几何约束}","cues":["圆心在速度垂线上","画图找几何关系","用边界位置定半径"],"concepts":["圆周运动几何关系","圆心定位"]}],"291":[{"title":"遮光片宽度取舍","type":"前提判断","judge":"用平均速度代替瞬时速度时，遮光片宽度 d 取大还是取小误差更小","why":"遮光片通过光电门的平均速度只在 d→0 时才趋近瞬时速度，d 越小平均速度越接近瞬时速度","do":"比较 5.00 cm 与 1.00 cm 两种宽度下平均速度与瞬时速度的偏差，选宽度小的","expr":"v\\approx\\frac{d}{\\Delta t}\\ \\ (d\\to 0)","cues":["宽度越小越准","平均速度代替瞬时速度","选小的那个"],"concepts":["瞬时速度","平均速度","极限思想"]},{"title":"加速度用速度差除以时间","type":"关系建立","judge":"已知两个光电门处的速度和经过两门的时间，用哪个式子求加速度","why":"加速度定义为速度变化量与所用时间之比，题给 v1、v2、t 恰好构成匀变速过程的初末速度与时间","do":"把 v1、v2 与 t 代入加速度定义式求 a，并按 2 位有效数字取舍","expr":"a=\\frac{v_2-v_1}{t}","cues":["速度变化除以时间","两个速度一个时间","直接套定义式"],"concepts":["加速度定义","匀变速直线运动"]},{"title":"图像不过原点判平衡不足","type":"图像读取","judge":"a-F 图线在 F 轴上有正截距说明摩擦力平衡过度还是不足","why":"有外力 F 时加速度仍为零，说明重力沿斜面的分力还不足以抵消摩擦力，即平衡摩擦力不足","do":"读图线横截距的位置，判断需要增大还是减小轨道倾角来补足重力分量","expr":"mg\\sin\\theta - f = Ma","cues":["有拉力还没加速度","横截距说明什么","摩擦力没平衡够"],"concepts":["平衡摩擦力","牛顿第二定律","图像截距"]},{"title":"斜率单位由关系式定","type":"结论整理","judge":"a-F 图线斜率的单位该由哪个物理关系推出","why":"由 F=ma 得 a=F/m，斜率 Δa/ΔF 对应 1/m，其单位由加速度单位除以力的单位决定","do":"写出 a 与 F 的比例关系，取 Δa/ΔF 的量纲化简","expr":"k=\\frac{\\Delta a}{\\Delta F}=\\frac{1}{m}\\Rightarrow \\mathrm{(m/s^2)/N=kg^{-1}}","cues":["斜率是质量的倒数","看纵横坐标单位","量纲化简一下"],"concepts":["牛顿第二定律","斜率物理意义","单位制"]}],"292":[{"title":"电流表量程与分度读取","type":"实验操作","judge":"读 A₁ 示数时，要先判断所用接线柱对应量程，再由量程确定分度值，最后按分度值估读","why":"电流表读数由量程决定分度值，量程选错或分度值算错，读数就会成倍偏差，后续功率全部错","do":"看题干给出的量程 250 mA，数表盘上该量程对应的总格数，算出每格代表多少 mA，再读指针所在格数","expr":"分度值=\\frac{量程}{总格数}","cues":["先看量程","数总格数","估读到分度值"],"concepts":["电流表读数","分度值","估读"]},{"title":"电源输出功率用总电流","type":"关系建立","judge":"求学生电源输出功率时，要判断用哪个电流——是干路总电流还是支路电流","why":"学生电源输出功率等于输出电压乘以其输出的总电流，低压电路中 A₁ 串在干路上，测的正是总电流","do":"确认 A₁ 在电路中的位置为干路，用电源输出电压 12 V 乘 A₁ 读数求输出功率","expr":"P=UI_{A_1}","cues":["A₁在干路","用总电流","电压乘电流"],"concepts":["电功率","干路电流","电源输出功率"]},{"title":"电阻箱阻值保持不变","type":"前提判断","judge":"比较高低压两种情况时，要判断电阻箱的阻值是否相同，能否用低压时算出的 R 直接代入高压情形","why":"题设明确保持电阻箱阻值不变，所以低压步骤中由 V₁ 与 A₁ 算出的 R 就是高压时电阻箱的阻值","do":"先用低压数据算 R，再把同一 R 用于高压时由 A₂ 求电阻箱功率","expr":"R=\\frac{U_1}{I_1},\\quad P_3=I_2^2R","cues":["阻值不变","先算电阻","同一电阻"],"concepts":["欧姆定律","电阻箱","功率"]},{"title":"区分电阻箱功率与总功率","type":"模型选择","judge":"第（2）问比较的是电阻箱消耗的功率，不是电源输出功率，要判断该用哪一段电路的电压电流","why":"电阻箱是负载，其功率只能用自身两端电压和通过它的电流计算；高压时它两端电压不再是 6 V，不能套用 V₂ 示数","do":"低压用 V₁ 与 A₁ 算电阻箱功率，高压用已求得的 R 与 A₂ 算电阻箱功率，再求比值","expr":"P_2=U_1I_1,\\quad P_3=I_2^2R","cues":["算电阻箱的","别用总功率","用自身电流"],"concepts":["负载功率","部分电路","功率分配"]},{"title":"高压时总电流取 A₃","type":"关系建立","judge":"求高压输电时电源输出功率，要判断哪个电流表测的是电源干路电流","why":"高压电路中电源经 T₁ 原线圈供电，A₃ 串在电源输出干路上，其示数才是电源输出的总电流，A₂ 只是负载支路电流","do":"用电源输出电压 12 V 乘 A₃ 示数求高压时输出功率，再与低压输出功率作差","expr":"P_4=UI_{A_3},\\quad \\Delta P=P_1-P_4","cues":["A₃在干路","用A₃算总功率","A₂是支路"],"concepts":["干路电流","变压器","功率差"]}],"293":[{"title":"入射点法线方向","type":"几何关系","judge":"B 点入射时，法线是过 B 的下表面半径 OB，还是别的方向","why":"下表面圆弧以 O 为圆心，圆弧上任意点的法线都沿该点与圆心的连线，入射角必须相对 OB 量取","do":"连接 OB，把入射光线（平行 OO'）与 OB 的夹角定为入射角","expr":"","cues":["法线过圆心","连O和B","入射角对OB量"],"concepts":["法线","圆的几何性质","入射角"]},{"title":"上表面垂直出射","type":"前提判断","judge":"光到达上表面时是否沿半径方向入射，从而不发生偏折","why":"上表面圆弧以 O' 为圆心，题设说射出后恰好经过 O'，说明介质内光线沿上表面半径方向，入射角为零，出射方向不变","do":"由出射光线过 O' 反推介质内光线沿 O' 的半径方向，确定上表面入射角为零","expr":"","cues":["射出后过O'","沿半径射出","上表面不偏折"],"concepts":["垂直入射","光的折射","圆心"]},{"title":"三角形定折射角","type":"关系建立","judge":"介质内光线与法线 OB 的夹角（折射角）由哪个三角形决定","why":"OB=OO'=R，O、O' 与 B 构成等腰三角形，折射角是这条光线与 OB 的夹角，需用三角形内角关系求出","do":"在三角形 OBO' 中用 OB=OO'=R 及入射角，求光线与 OB 的夹角","expr":"","cues":["等腰三角形","OB等于OO'","用内角求折射角"],"concepts":["等腰三角形","折射角","几何关系"]},{"title":"折射率定律求 n","type":"关系建立","judge":"用哪两个角代入折射定律，角是否对应同一种介质分界面","why":"折射定律要求入射角在空气、折射角在介质，且都相对法线；本题入射在下表面、出射在上表面，需用下表面那组角","do":"把下表面入射角与介质内折射角代入折射定律求 n","expr":"n=\\frac{\\sin\\theta_1}{\\sin\\theta_2}","cues":["用下表面那组角","入射角在空气","折射角在介质"],"concepts":["折射定律","折射率"]},{"title":"判断是否全反射","type":"临界条件","judge":"光到达上表面 D 点时是折射出去还是发生全反射","why":"光从介质射向空气，若上表面入射角的正弦大于临界角正弦 1/n，就会全反射，后续路径完全不同","do":"求上表面入射角的正弦，与 1/n 比较大小","expr":"\\sin\\theta \\gtrless \\sin C=\\frac{1}{n}","cues":["先算临界角","和1/n比","看会不会全反射"],"concepts":["全反射","临界角"]},{"title":"光路总路程","type":"几何关系","judge":"全反射后光线在介质中走的是哪几段，总路程如何由 R 表示","why":"全反射后光线按反射定律折回，路径由圆弧半径和界面位置决定，必须逐段用几何关系累加，不能只算一段","do":"按反射定律画出后续光路，用 R 表示各段长度并求和","expr":"L=2(GE+AF)","cues":["按反射定律折回","分段加起来","用R表示各段"],"concepts":["反射定律","几何关系","光程"]}],"294":[{"title":"活塞启动的临界压强","type":"临界条件","judge":"活塞刚开始缓慢上升时，摩擦力方向朝下，气体压强该取哪个值","why":"活塞静止时静摩擦力可在零到最大值间调节，只有气体压强增大到恰好克服大气压加最大静摩擦力时活塞才启动，此时摩擦力达最大值且方向向下","do":"对刚开始上升的活塞受力分析，取竖直向上为正，列平衡方程求启动压强","expr":"p_1S=p_0S+f_0,\\quad p_1=\\frac{22}{21}p_0","cues":["摩擦力朝下","恰好要动","取最大静摩擦"],"concepts":["受力平衡","最大静摩擦力","临界状态"]},{"title":"升温段为等压膨胀","type":"模型选择","judge":"T1到T2活塞上升过程中气体压强是否保持不变","why":"活塞一旦滑动，滑动摩擦力大小恒定、方向不变，活塞所受合外力为零，气体压强由大气压与恒定摩擦力共同决定，故为等压过程","do":"确认活塞滑动后摩擦力恒为f0且方向向下，压强恒为p1，用盖-吕萨克定律联系两状态","expr":"\\frac{h_1S}{T_1}=\\frac{h_2S}{T_2}","cues":["滑动摩擦不变","压强不变","等压膨胀"],"concepts":["等压过程","盖-吕萨克定律"]},{"title":"降温段先等容后等压","type":"模型选择","judge":"T2到T3活塞不动、T3到T4活塞下降，两段各是什么过程","why":"降温初期静摩擦力随压强减小而调整，活塞不动为等容；压强降到恰好等于大气压减最大静摩擦力时活塞才下降，之后摩擦力方向向上且恒定，为等压压缩","do":"把全过程分成等压膨胀、等容降压、等压压缩三段，分别判断各段体积是否变化","expr":"p_3S+f_0=p_0S,\\quad p_3=\\frac{20}{21}p_0","cues":["先不动","等容降温","摩擦力朝上"],"concepts":["等容过程","等压过程","静摩擦调节"]},{"title":"各段功的正负与大小","type":"关系建立","judge":"每段气体对外做功还是外界对气体做功，符号如何取","why":"热力学第一定律中W取外界对气体做功，气体膨胀时W为负、压缩时W为正，且等压段功等于压强乘体积变化","do":"对等压膨胀段和等压压缩段分别用pΔV计算功并带符号，等容段功为零，再代数求和","expr":"W_1=-p_1(h_2-h_1)S,\\ W_2=0,\\ W_3=p_3(h_2-h_4)S","cues":["膨胀做负功","压缩做正功","等容不做功"],"concepts":["体积功","热力学第一定律","符号规定"]},{"title":"首末温度相同定内能","type":"结论整理","judge":"全程内能变化是否为零，能否用ΔU=0把净热量与总功挂钩","why":"理想气体内能只由温度决定，T1=T4说明初末内能相等，故净吸热等于气体对外做的总功","do":"比较T1与T4确认内能不变，再由ΔU=W+Q反解Q","expr":"\\Delta U=0,\\quad Q=-W","cues":["温度相同","内能不变","净热量等于做功"],"concepts":["理想气体内能","热力学第一定律"]}],"295":[{"title":"水平方向动量守恒的适用","type":"前提判断","judge":"小球沿弯曲轨道下滑过程中，系统水平方向是否动量守恒、竖直方向是否守恒","why":"轨道光滑、方形物体置于光滑水平面，系统水平方向不受外力；竖直方向受地面支持力与重力不平衡，故只有水平方向动量守恒","do":"对小球与方形物体组成的系统，只沿水平方向列动量守恒，竖直方向不列","expr":"mv_{1}=Mv_{2}","cues":["水平方向才守恒","竖直方向别用","地面光滑"],"concepts":["动量守恒","系统受力分析"]},{"title":"下滑过程能量守恒","type":"关系建立","judge":"小球从释放到 P 点，机械能是否守恒、重力势能减少量转化为哪些动能","why":"轨道光滑、无摩擦无空气阻力，只有重力做功，系统机械能守恒；小球竖直下落高度 h 全部转化为小球与方块的动能","do":"以小球下落高度 h 为重力势能减少量，等于小球与方形物体动能之和，与水平动量守恒式联立","expr":"mgh=\\frac{1}{2}mv_{1}^{2}+\\frac{1}{2}Mv_{2}^{2}","cues":["机械能守恒","高度差就是h","两个动能都算上"],"concepts":["机械能守恒","动能"]},{"title":"碰撞只保留水平动量","type":"模型选择","judge":"小球落到 a 上粘连时，是竖直方向速度消失、只沿水平方向动量守恒，还是总动量守恒","why":"a 在光滑水平面上，竖直方向受地面支持力冲量抵消小球竖直动量，水平方向无外力，故只水平方向动量守恒","do":"只取小球与 a 的水平速度列动量守恒，竖直分速度直接舍去","expr":"mv_{1}=(m+m_{a})v_{3}","cues":["竖直速度没了","只算水平","粘在一起"],"concepts":["完全非弹性碰撞","动量守恒"]},{"title":"锁定解除的临界条件","type":"临界条件","judge":"b 何时解除锁定——由弹簧拉力达到 15 N 确定形变量，还是由速度为零等其它条件确定","why":"题设明确给出解除锁定条件是弹簧拉力达到 F=15 N，由胡克定律反推此时形变量，这是后续能量计算的起点","do":"用 F=kx 求解除锁定时的形变量 x1，再对 a（含小球）与弹簧系统用机械能守恒求此时速度 v4","expr":"F=kx_{1},\\ \\frac{1}{2}(m+m_{a})v_{3}^{2}=\\frac{1}{2}(m+m_{a})v_{4}^{2}+\\frac{1}{2}kx_{1}^{2}","cues":["拉力到15牛才解锁","先求形变量","用胡克定律"],"concepts":["胡克定律","机械能守恒","临界条件"]},{"title":"共速时势能最大","type":"临界条件","judge":"弹簧弹性势能最大对应三者速度满足什么关系","why":"解除锁定后三者系统水平方向动量守恒，当三者速度相等时相对速度为零、弹簧形变量最大，弹性势能最大","do":"对小球、a、b 组成系统列动量守恒求共速 vb，再用能量守恒求最大弹性势能","expr":"(m+m_{a})v_{4}=(m+m_{a}+m_{b})v_{b}","cues":["共速时形变最大","三者速度相同","动量守恒求共速"],"concepts":["动量守恒","共速","弹性势能"]},{"title":"势能最大值含初态存量","type":"关系建立","judge":"最大弹性势能是从解除锁定时刻的机械能算起，还是从弹簧原长算起","why":"解除锁定时弹簧已有形变量 x1、已储存弹性势能，最大势能应等于解除时刻总机械能减去共速时总动能","do":"用解除时刻的动能加弹簧势能减去共速时系统动能，得到 Epm","expr":"E_{pm}=\\frac{1}{2}(m+m_{a})v_{4}^{2}+\\frac{1}{2}kx_{1}^{2}-\\frac{1}{2}(m+m_{a}+m_{b})v_{b}^{2}","cues":["别漏掉原来的势能","从解锁时刻算","初态有弹性势能"],"concepts":["能量守恒","弹性势能"]}],"296":[{"title":"斜面切割的有效速度","type":"几何关系","judge":"磁场竖直向上而轨道倾斜，切割磁感线的有效速度分量应取哪一个","why":"动生电动势只由速度垂直于 B 且垂直于棒的分量决定，v 沿斜面，B 竖直，二者夹角为 α","do":"把速度 v 分解到水平方向，取水平分量作为有效切割速度","expr":"E=BLv\\cos\\alpha","cues":["速度沿斜面","取水平分量","磁场是竖直的"],"concepts":["动生电动势","有效切割速度"]},{"title":"安培力沿斜面的分量","type":"关系建立","judge":"安培力水平向左，它在斜面方向的分量如何与重力沿斜面分量平衡","why":"线框匀速，沿斜面合力为零；安培力水平，需投影到斜面方向","do":"写出安培力 F=BIL，再乘 cosα 投影到斜面，与 mg sinα 平衡","expr":"BIL\\cos\\alpha=mg\\sin\\alpha","cues":["安培力水平","投影到斜面","匀速合力为零"],"concepts":["安培力","力的分解","平衡条件"]},{"title":"进入前只有重力做功","type":"模型选择","judge":"从释放到 pq 边刚进入磁场这段用什么规律求 s","why":"进入前无磁场、无安培力，只有重力做功，轨道光滑无摩擦","do":"对释放到进入的过程列动能定理，初速为零","expr":"mgs\\sin\\alpha=\\frac{1}{2}mv^{2}","cues":["进入前没有安培力","只有重力做功","初速为零"],"concepts":["动能定理","重力做功"]},{"title":"区分感生与动生电动势","type":"模型选择","judge":"区域 Ⅱ 中磁感应强度随 t 和 x 都变，电动势该由哪部分变化产生","why":"B 显含时间 t 且随位置 x 变，线框运动使所处 B 变化，两者都要计入磁通量变化率","do":"对 Φ=BL² 求全导数，分别取对 t 的偏导和随运动 dx/dt 的变化","expr":"E'=(k_{1}+k_{2}v)L^{2}","cues":["磁场随时间和位置都变","求磁通量变化率","两项都要算"],"concepts":["法拉第电磁感应定律","感生电动势","动生电动势"]},{"title":"两边安培力相减取净力","type":"关系建立","judge":"ef、pq 两边所在处 B 不同，安培力方向相反，应取合力还是单边力","why":"线框两边电流方向相反、所处磁场大小不同，沿斜面的安培力需相减","do":"分别写出两边安培力，作差后代入 k1 关系化简","expr":"F_{\\text{安}}=[k_{1}t+k_{2}(s+L)]I'L-(k_{1}t+k_{2}s)I'L","cues":["两边磁场不一样","安培力方向相反","取合力"],"concepts":["安培力","叠加原理"]},{"title":"平衡态对应速度为零","type":"临界条件","judge":"化简后安培力恒比 mg sinα 多出一项，平衡时速度应满足什么","why":"净安培力等于重力沿斜面分量时加速度为零，代入 k1 后多出正比于 v 的项","do":"令 F安=mg sinα，解出平衡时的 v","expr":"F_{\\text{安}}=mg\\sin\\alpha+\\frac{k_{2}^{2}L^{4}v}{R}=mg\\sin\\alpha","cues":["平衡时加速度为零","多出一项含速度","速度只能为零"],"concepts":["平衡条件","安培力"]},{"title":"动量定理积分求位移","type":"数学处理","judge":"安培力含速度、随时间变，如何由速度变化求移动距离","why":"力对时间的累积中，vΔt 累积即为位移 d，可直接消去过程细节","do":"对整个过程列动量定理，把 ∫v dt 换成 d，末速取零","expr":"-\\frac{k_{2}^{2}L^{4}}{R}\\int v\\,dt=0-mv_{0},\\quad \\int v\\,dt=d","cues":["力随速度变","对时间累积","速度乘时间就是位移"],"concepts":["动量定理","微元累积"]}],"297":[{"title":"固有频率由谁决定","type":"前提判断","judge":"要判断系统的固有频率是否随驱动力频率改变","why":"固有频率是系统自身的属性，只由系统的质量、劲度等自身结构参数决定，与外部驱动无关","do":"把固有频率与驱动频率区分开，确认改变驱动力频率不会改变固有频率","expr":"","cues":["固有频率看系统本身","跟驱动力无关"],"concepts":["固有频率","受迫振动"]},{"title":"共振发生的条件","type":"临界条件","judge":"要判断共振在什么频率关系下才发生","why":"受迫振动的振幅在驱动力频率等于固有频率时达到最大，这一条件才是共振的判据","do":"比较驱动力频率与固有频率，只有两者相等时才判定为共振","expr":"f_{驱}=f_{固}","cues":["频率相等才共振","振幅最大时共振"],"concepts":["共振","受迫振动"]},{"title":"多普勒频移的方向","type":"关系建立","judge":"要判断观察者与波源相互靠近或远离时，接收频率相对波源频率是变大还是变小","why":"多普勒效应中，单位时间内接收到的波数随两者相对运动而改变，靠近时接收频率升高，远离时降低","do":"由相对运动方向判断接收频率与波源频率的大小关系","expr":"","cues":["靠近变高","远离变低"],"concepts":["多普勒效应","接收频率"]},{"title":"多普勒效应的应用","type":"结论整理","judge":"要判断能否由多普勒频移反推波源与观察者的相对速度","why":"频移量随相对速度单调变化，测出频率变化即可确定相对速度，这是测速雷达等的原理","do":"把频移与相对速度对应起来，确认可用于测量车辆速度","expr":"","cues":["频移能算速度","雷达测速"],"concepts":["多普勒效应","相对速度"]}],"298":[{"title":"升压变比由电压比定","type":"关系建立","judge":"升压变压器的匝数比该用哪两个电压相比、谁比谁","why":"理想变压器电压比等于匝数比，且升压时副线圈电压高、匝数多，比值必须小于 1","do":"用原线圈电压 400 V 与副线圈电压 10 kV 作比，得到 n1:n2","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2}=\\frac{400}{10000}=\\frac{1}{25}","cues":["电压比就是匝数比","升压是副线圈多","别把比倒过来"],"concepts":["理想变压器","匝数比"]},{"title":"输电线电流用副线圈算","type":"模型选择","judge":"算输电线上的电流时，应取升压后副线圈的电流还是原线圈电流","why":"输电线接在升压变压器副线圈回路中，线损由流过输电线的电流决定，而该电流由输送功率和输电电压决定","do":"用输出功率除以升压后的输电电压求副线圈电流，再乘等效电阻得电压损失","expr":"I_2=\\frac{P}{U_2}=\\frac{10^6}{10^4}\\,\\mathrm{A}=100\\,\\mathrm{A},\\quad \\Delta U=I_2R=500\\,\\mathrm{V}","cues":["输电线在副线圈那边","先求输电电流","用高压侧电压除功率"],"concepts":["输电电流","电压损失","电功率"]},{"title":"原线圈电流按功率相等求","type":"前提判断","judge":"理想变压器是否改变功率，原线圈电流该由哪个功率和哪个电压求","why":"理想变压器无能量损耗，原副线圈功率相等，原线圈电流由输送功率和原线圈电压共同决定","do":"用同一功率除以原线圈电压 400 V 得原线圈电流","expr":"I_1=\\frac{P}{U_1}=\\frac{10^6}{400}\\,\\mathrm{A}=2500\\,\\mathrm{A}","cues":["变压器不耗功率","原线圈电压低电流大","功率前后一样"],"concepts":["理想变压器","功率相等"]},{"title":"频率不被变压器改变","type":"结论整理","judge":"变压器能否改变交变电流的频率","why":"变压器只按电磁感应改变电压和电流，不改变交变电流的周期和频率","do":"比较原、副线圈电流频率，判定二者相同","expr":"","cues":["频率不变","变压器只变电压","周期也不变"],"concepts":["交变电流频率","变压器原理"]}],"299":[{"title":"判断乙是否发生光电效应","type":"前提判断","judge":"由只有甲发射光电子，判断该频率的光与乙金属截止频率的大小关系","why":"发生光电效应的条件是入射光频率不低于金属截止频率，乙不发射说明该光频率低于乙的截止频率","do":"比较入射光频率与乙的截止频率，确定乙不发生光电效应的原因","expr":"\\nu < \\nu_{c乙}","cues":["乙没光电子","频率不够","低于截止频率"],"concepts":["光电效应","截止频率"]},{"title":"逸出功与截止频率关系","type":"关系建立","judge":"由甲的逸出功小于乙，判断两者截止频率的大小顺序","why":"逸出功越大，截止频率越高，由 W0=hνc 得","do":"由 W甲<W乙 推出甲的截止频率低于乙的截止频率","expr":"W_0 = h\\nu_c,\\quad W_甲<W_乙 \\Rightarrow \\nu_{c甲}<\\nu_{c乙}","cues":["逸出功小截止频率低","甲更容易发生","乙更难"],"concepts":["逸出功","截止频率"]},{"title":"用光电效应方程建立联系","type":"关系建立","judge":"把最大初动能、入射光频率、逸出功三者用光电效应方程联系起来","why":"光电效应方程给出最大初动能与入射光频率和逸出功的定量关系，是判断改变频率后动能如何变化的依据","do":"写出 E_k=hν-W0，明确频率变化时动能随之变化的方向","expr":"E_k = h\\nu - W_0","cues":["光电效应方程","最大初动能"],"concepts":["光电效应方程","最大初动能"]},{"title":"频率减小后能否发生","type":"临界条件","judge":"换用频率更小的光时，判断甲是否仍能发生光电效应、乙是否仍不能","why":"原光频率已低于乙的截止频率，频率再减小更低于乙的截止频率；而甲能否发生取决于新频率是否仍高于甲的截止频率","do":"比较新频率与甲、乙的截止频率，确定只有甲可能发生光电效应","expr":"\\nu' < \\nu < \\nu_{c乙},\\quad \\nu' \\text{ 与 } \\nu_{c甲} \\text{ 比较}","cues":["频率再小更不行","甲可能还能","乙肯定不行"],"concepts":["截止频率","临界条件"]},{"title":"频率变化对最大初动能的影响","type":"结论整理","judge":"判断频率减小（或不变）时甲的最大初动能相对 E_k 如何变化","why":"由 E_k=hν-W0，同一金属逸出功不变，最大初动能随入射光频率单调增大","do":"比较新旧频率下甲的最大初动能，得出频率减小时动能小于 E_k、频率不变时动能不变","expr":"E_k' = h\\nu' - W_甲 < h\\nu - W_甲 = E_k","cues":["频率越小动能越小","频率不变动能不变","动能跟着频率走"],"concepts":["光电效应方程","最大初动能"]}],"300":[{"title":"垂直入射不偏折","type":"前提判断","judge":"光垂直射入棱镜第一个面时是否发生折射偏折","why":"光从空气垂直射入玻璃表面，入射角为零，由折射定律折射角也为零，光线沿原方向进入棱镜","do":"确定光在第一个面上的入射角为 0，画出进入棱镜后仍沿原方向传播的光线","expr":"","cues":["垂直入射不偏折","沿原方向走","第一面不折射"],"concepts":["折射定律","入射角"]},{"title":"棱镜内光线与第二面夹角","type":"几何关系","judge":"棱镜内光线射到第二个面时的入射角与顶角 α 的关系","why":"棱镜顶角是两折射面的夹角，光线垂直第一面进入后与第一面法线平行，由三角形内角和可把第二面的入射角用顶角 α 表示","do":"在棱镜截面内作第二面的法线，利用顶角 α 与法线的几何关系求出第二面上的入射角","expr":"$i_2=\\alpha$","cues":["入射角等于顶角","画法线","看三角形内角"],"concepts":["几何光路","法线","顶角"]},{"title":"偏转角与出射角关系","type":"关系建立","judge":"偏转角 β 与第二面出射角 r 之间满足什么关系","why":"光线只在第二面发生偏折，偏转角就是出射光线相对原入射方向的夹角，由几何关系它等于出射角与入射角之差","do":"延长原入射方向，比较出射光线与原方向的夹角，写出 β 与出射角的几何关系","expr":"$r=\\alpha+\\beta$","cues":["偏转角是折出来的角","出射角减入射角","延长原光线"],"concepts":["偏转角","出射角"]},{"title":"第二面折射定律求 n","type":"模型选择","judge":"在第二个面上用哪一侧的折射定律形式（玻璃到空气）","why":"光从玻璃射入空气，折射定律中玻璃一侧对应角的正弦乘 n 等于空气一侧对应角的正弦","do":"对第二面列折射定律，把入射角 α 和出射角 α+β 代入并解出 n","expr":"$n\\sin\\alpha=\\sin(\\alpha+\\beta)$","cues":["玻璃到空气","n乘入射角","解出折射率"],"concepts":["折射定律","折射率"]}],"301":[{"title":"椭圆轨道半长轴","type":"几何关系","judge":"小行星轨道是椭圆，需判断用近日距与远日距的平均值作为半长轴","why":"开普勒第三定律中的 a 是椭圆轨道半长轴，等于近日距与远日距之和的一半","do":"把地球轨道半径记为 R，取近日距 5R 与远日距 7R 求平均","expr":"a=\\frac{5R+7R}{2}=6R","cues":["取平均","半长轴","两头加起来除二"],"concepts":["椭圆轨道","半长轴"]},{"title":"周期比较用开普勒第三定律","type":"关系建立","judge":"比较小行星与地球的公转周期，需判断用同一中心天体下 a³/T² 为常量","why":"两者都绕太阳运行，中心天体相同，开普勒第三定律才可直接对比","do":"把小行星的 6R 与地球的 R 分别代入 a³/T² 相等的关系","expr":"\\frac{(6R)^3}{T^2}=\\frac{R^3}{T_{\\text{地}}^2}","cues":["绕同一个太阳","开普勒第三定律","周期比"],"concepts":["开普勒第三定律","公转周期"]},{"title":"近日点加速度由距离决定","type":"模型选择","judge":"判断加速度大小只取决于该点到太阳的距离，与速度大小无关","why":"万有引力提供加速度，a=GM/r²，同一中心天体 GM 相同，只由 r 决定","do":"用近日距 5R 与地球轨道半径 R 代入 a=GM/r² 求比值","expr":"a=\\frac{GM}{r^2},\\quad \\frac{a_{\\text{行}}}{a_{\\text{地}}}=\\frac{R^2}{(5R)^2}=\\frac{1}{25}","cues":["只看距离","引力除以质量","跟速度无关"],"concepts":["牛顿第二定律","万有引力定律"]},{"title":"近日点速度最大","type":"前提判断","judge":"从远日点到近日点过程中，需判断距离减小对应速度增大还是减小","why":"开普勒第二定律（面积定律）要求近日点速度最大、远日点速度最小，引力做正功使速率增大","do":"比较近日点与远日点的速率，确认靠近太阳时速率增大","expr":"","cues":["近日点最快","越近越快","面积相同"],"concepts":["开普勒第二定律","速率变化"]}],"302":[{"title":"负离子顺时针的磁场方向","type":"前提判断","judge":"由负离子沿顺时针圆弧偏转，判断各圆弧处偏转磁场的方向","why":"洛伦兹力指向圆心提供向心力，负电荷受力方向与左手定则（或右手四指指向速度反方向）对应，方向判反则整题错","do":"取任一段圆弧，画出速度方向与指向圆心的洛伦兹力，用左手定则反推磁感应强度方向","expr":"","cues":["先定圆心","看受力指向","负电荷要反向"],"concepts":["洛伦兹力","左手定则","向心力"]},{"title":"加速电场方向与电势高低","type":"关系建立","judge":"判断直通道内电场方向及 P、Q 两端电势高低，使负离子每次经过都被加速","why":"负电荷受力方向与电场方向相反，只有电场方向与运动方向相反时离子才被加速，这决定电势差的正负","do":"由离子在 PQ 中的运动方向确定电场力方向，再反推电场方向与两端电势高低","expr":"","cues":["负电荷受力反向","顺着运动才加速","看电势降落"],"concepts":["电场力","电势差","动能定理"]},{"title":"洛伦兹力不做功","type":"模型选择","judge":"判断每圈动能增量只来自 PQ 段的电场加速，圆弧段磁场不改变速率","why":"洛伦兹力始终垂直于速度，不做功，故动能增量只由加速电压累加，这是求任意圈后速度的前提","do":"对从 P 到第 k 次出加速场的全过程用动能定理，只计 k 次 qU 的功","expr":"kqU=\\frac12 mv^{2}-\\frac12 mv_0^{2}","cues":["磁场不改速度大小","只算电场做功","一圈加一次"],"concepts":["动能定理","洛伦兹力不做功"]},{"title":"半径公式联系速度与磁场","type":"关系建立","judge":"判断半径 R 固定时，速率增大必须同步调大磁感应强度 B","why":"由 qvB=mv²/R 得 B=mv/(qR)，v 随加速次数增大，B 必须随之增大，这是判断 B 随 k 变化关系的依据","do":"写出半径公式解出 B 的表达式，再把上一步的 v(k) 代入","expr":"qvB=m\\frac{v^{2}}{R}\\Rightarrow B=\\frac{mv}{qR}","cues":["半径不变","速度变大磁场变大","先求速度再求磁场"],"concepts":["洛伦兹力提供向心力","圆周运动半径"]}],"303":[{"title":"确定向心力来源","type":"模型选择","judge":"小球做水平面内匀速圆周运动时，向心力由重力与支持力的合力提供，还是由支持力的某个分量提供","why":"小球受重力 mg 与坑壁支持力 N 两个力，合力必须水平指向圆心；若误把支持力或重力单独当作向心力，方程就列错","do":"对小球受力分析，画出竖直方向与水平方向，把两力的合力分解到指向圆心方向","expr":"F_{\\text{向}}=mg\\tan\\theta","cues":["取合力指向圆心","重力不提供向心力","只看水平分量"],"concepts":["向心力","受力分析","合力"]},{"title":"切面角与半径的几何对应","type":"几何关系","judge":"题给的切面与水平面夹角 θ 对应的是合力方向与竖直方向的夹角，还是与水平方向的夹角","why":"光滑内壁支持力垂直于切面，由几何关系可得合力方向与竖直方向夹角等于 θ，从而 tanθ 出现在向心力表达式中；角度取错则 tan 与 cot 互换","do":"由支持力垂直切面推出合力方向，确认合力与竖直方向夹角为 θ，写出 F向 与 mg 的比值关系","expr":"\\tan\\theta=\\frac{F_{\\text{向}}}{mg}","cues":["角在竖直方向","支持力垂直切面","别用余切"],"concepts":["几何关系","切面","支持力方向"]},{"title":"向心力与角速度关联","type":"关系建立","judge":"用 F向=mω²R 还是 F向=mv²/R 把合力与圆周运动参量联系起来","why":"题目先求角速度，用含 ω 的向心力公式可直接解出 ω；选错公式会多绕一步或引入未知 v","do":"将合力表达式与 mω²R 联立，解出 ω","expr":"mg\\tan\\theta=m\\omega^{2}R","cues":["先求角速度","用含角速度的式子","半径已知"],"concepts":["向心力公式","角速度","匀速圆周运动"]},{"title":"线速度与向心加速度换算","type":"关系建立","judge":"由已得 ω 和 R 求 v、a 时，用 v=ωR 与 a=ω²R 还是另立方程","why":"ω 已确定，v 与 a 都是 ω、R 的派生量，直接代换即可；若重新受力分析会重复劳动且易错","do":"用 v=ωR 求线速度，用 a=ω²R 求向心加速度，与选项数值比对","expr":"v=\\omega R,\\quad a=\\omega^{2}R","cues":["直接代换","派生量","和选项比大小"],"concepts":["线速度","向心加速度"]},{"title":"支持力由竖直平衡求","type":"关系建立","judge":"支持力 N 应由竖直方向合力为零求出，还是由水平向心力方向求出","why":"小球在竖直方向无加速度，N 的竖直分量与 mg 平衡，故 N=mg/cosθ；若把 N 当成向心力会得到错误值","do":"沿竖直方向列平衡方程，解出 N 并与选项比对","expr":"N\\cos\\theta=mg","cues":["竖直方向平衡","支持力竖直分量","别把支持力当向心力"],"concepts":["平衡条件","支持力","力的分解"]}],"304":[{"title":"两次测量对应两种状态","type":"前提判断","judge":"要判断步骤①和步骤②中线圈分别处于通电平衡状态还是断开切割状态","why":"步骤①通电流 I 且框架平衡，安培力参与受力；步骤②线圈断开、磁场运动，只产生感应电动势而无电流，两种状态不能混用同一个电流","do":"把题干两个步骤分开，明确 I 是通电平衡时的电流，E 是断开时因磁场运动产生的电动势","expr":"","cues":["分两步看","断开没电流","通电才平衡"],"concepts":["安培力","电磁感应","平衡状态"]},{"title":"平衡方程取框架整体","type":"模型选择","judge":"要判断步骤①中把托盘、物块、线圈作为整体受力，安培力方向向上与重力平衡","why":"框架整体静止，竖直方向只受总重力和磁场对通电线圈边的安培力，取整体可避开内部作用力","do":"对框架加物块整体列竖直方向平衡方程，安培力用 BIL 表示","expr":"(M+m)g=BIL","cues":["取整体","安培力向上","总重力"],"concepts":["整体法","安培力","力的平衡"]},{"title":"电动势来自相对切割","type":"关系建立","judge":"要判断步骤②中磁场向下运动等效于线圈边相对磁场向上切割，感应电动势由 B、L、v 决定","why":"线圈不动而磁场匀速运动，相对速度大小为 v，切割磁感线的有效长度是处于磁场中的那一边 L","do":"写出磁场运动时单边切割产生的感应电动势表达式，与步骤①的安培力式共用同一个 B 和 L","expr":"E=BLv","cues":["相对运动","切割磁感线","同一个B和L"],"concepts":["动生电动势","切割磁感线"]},{"title":"消去 B 和 L 求质量","type":"数学处理","judge":"要判断 B 和 L 未知，必须由两式相除消去，才能用 E、I、v、g 表示 m","why":"题目只给 E、I、v、g、M，B 与 L 是中间量，只有联立两式消元才能得到可测量的质量表达式","do":"由平衡式解出 BL，代入电动势式，整理出 m 的表达式","expr":"m=EI/(vg)-M","cues":["消掉B和L","两式联立","只剩已知量"],"concepts":["联立方程","消元"]},{"title":"E 比 I 不是电阻","type":"结论整理","judge":"要判断 E/I 是否具有电阻的量纲和物理意义","why":"E 是断开时的感应电动势，I 是另一状态下人为通入的电流，两者不满足欧姆定律的同一回路关系，比值无电阻含义","do":"比较 E 与 I 的物理来源，确认它们不属于同一闭合电路的同时状态","expr":"","cues":["不是同一状态","不能比成电阻","欧姆定律不适用"],"concepts":["电阻","欧姆定律","感应电动势"]}],"305":[{"title":"匀速隐含合力为零","type":"前提判断","judge":"能否由水平匀速直线运动断定三力合力为零，从而空气作用力与重力、拉力的合力等大反向","why":"匀速直线运动是平衡状态，牛顿第二定律给出合外力为零；这是后面所有矢量关系的前提","do":"对无人机受力分析，写出重力、拉力、空气作用力的矢量和为零","expr":"\\vec{F}_{\\text{空}}+m\\vec{g}+\\vec{F}=0","cues":["匀速就是合力为零","三力平衡","空气力去平衡另外两个"],"concepts":["平衡条件","牛顿第二定律","受力分析"]},{"title":"空气力随拉力变化","type":"关系建立","judge":"判断空气作用力的大小和方向是否随 F 减小而改变，还是保持不变","why":"重力恒定、拉力方向不变而大小线性减小，二者合力的大小和方向都变，故平衡它的空气力也必随之改变","do":"作重力与拉力的矢量合成图，观察合力随 F 缩短时的变化，再取反向得空气力","expr":"\\vec{F}_{\\text{空}}=-(m\\vec{g}+\\vec{F})","cues":["重力不变拉力变小","合力方向在转","空气力也得跟着转"],"concepts":["矢量合成","平行四边形定则","动态平衡"]},{"title":"余弦定理求空气力大小","type":"几何关系","judge":"重力与拉力夹角取多少，用哪条边角关系求空气力大小","why":"拉力与水平面成 30° 角，重力竖直向下，两矢量夹角为 120°，已知两边及夹角求第三边只能用余弦定理","do":"在重力、拉力、空气力构成的三角形中对 120° 角列余弦定理，再代入 F=F0-kT","expr":"F_{\\text{空}}=\\sqrt{(mg)^{2}+F^{2}-2mgF\\cos120^\\circ}=\\sqrt{(mg)^2+F^2+mgF}","cues":["夹角是120度","两边夹一角","用余弦定理"],"concepts":["余弦定理","矢量三角形"]},{"title":"变力冲量用面积","type":"数学处理","judge":"拉力随时间线性变化时，冲量能否直接用 F·t，还是要用 F-t 图线面积","why":"冲量定义是力对时间的积分，力不是常量时不能乘端点值，线性变化时积分等于梯形面积","do":"画 F-t 图线，取 0 到 T 的梯形面积作为拉力冲量","expr":"I_F=\\frac{F_0+(F_0-kT)}{2}T=\\left(F_0-\\tfrac12 kT\\right)T","cues":["力在变不能直接乘","看图像面积","梯形面积"],"concepts":["冲量","F-t 图像面积","积分思想"]},{"title":"合力冲量先分解再合成","type":"模型选择","judge":"求重力与拉力合力的冲量时，是直接对合力积分，还是先分方向求分冲量再矢量合成","why":"合力方向随 F 变化，不能当作恒力处理；但重力、拉力各自方向固定，分方向积分后合成才成立","do":"把重力和拉力分解到水平、竖直方向，分别对时间积分得 Ix、Iy，再求模","expr":"I=\\sqrt{I_x^2+I_y^2},\\quad I_x=\\tfrac{\\sqrt3}{2}\\left(F_0T-\\tfrac12 kT^2\\right)","cues":["合力方向在变","先分方向算","再勾股合成"],"concepts":["冲量的矢量性","正交分解","变力冲量"]}],"306":[{"title":"螺旋测微器读数规则","type":"实验操作","judge":"读数时主尺整毫米数之外，可动刻度要估读到哪一位、是否乘 0.01 mm","why":"螺旋测微器精度为 0.01 mm，需估读到千分之一毫米，固定刻度半毫米线是否露出决定主尺读数","do":"先读固定刻度（含半毫米线），再读可动刻度对齐格数并估读一位，相加","expr":"d=d_{\\text{主}}+n\\times0.01\\,\\mathrm{mm}","cues":["看半毫米线","估读一位","乘零点零一"],"concepts":["螺旋测微器","估读","精度"]},{"title":"平衡摩擦的判据","type":"前提判断","judge":"用什么现象说明小车在轨道甲上已做匀速运动、阻力被平衡","why":"平衡摩擦力后小车在轨道甲上合力为零，做匀速直线运动，经过两光电门速度相同","do":"比较小车通过光电门 A、B 的遮光时间是否相等","expr":"t_A=t_B","cues":["看时间相等","匀速就平衡了","两门速度一样"],"concepts":["平衡摩擦力","匀速直线运动","光电门测速"]},{"title":"弹性碰撞的速度互换","type":"关系建立","judge":"质量相等的两车发生弹性碰撞后，碰后速度与碰前速度是什么关系","why":"等质量弹性碰撞满足动量守恒与动能守恒，联立得两车速度交换","do":"把碰后小车1的速度等同于碰前小车2的速度，转化为遮光时间比较","expr":"m_1=m_2,\\ v_1'=v_2,\\ v_2'=v_1","cues":["等质量交换速度","碰后速度互换","时间应该相等"],"concepts":["弹性碰撞","动量守恒","动能守恒"]},{"title":"遮光条测速换算","type":"关系建立","judge":"用遮光条宽度除以遮光时间得到的是哪一时刻的速度","why":"遮光条很窄，通过光电门的平均速度可近似为该位置的瞬时速度","do":"分别用 d 除以各次遮光时间求碰前、碰后各车速度","expr":"v=\\frac{d}{\\Delta t}","cues":["宽度除以时间","平均当瞬时","先算速度"],"concepts":["瞬时速度","平均速度近似","光电门"]},{"title":"动能比中质量约去","type":"数学处理","judge":"求总动能比值时两车质量如何处理","why":"两车相同且吸能材料质量不计，动能式中质量 m 相同可整体约去","do":"写出碰前、碰后动能表达式，约去 m 后只留速度平方比","expr":"\\frac{E_k'}{E_k}=\\frac{v_1^2+v_2^2}{v_0^2}","cues":["质量约掉","只比速度平方","材料质量不计"],"concepts":["动能","比值化简","有效数字"]}],"307":[{"title":"最大电流的估算","type":"前提判断","judge":"求最大电流时，应判断哪些电阻计入回路、哪些可忽略","why":"电源内阻与电流表内阻均不计，回路最小电阻只由定值电阻与电磁铁线圈电阻串联构成，滑片置阻值最小处时电流最大","do":"把 R0 与线圈电阻串联，取滑动变阻器阻值为零，用电动势除以总电阻","expr":"I_{\\max}=\\frac{E}{R_0+R_{\\text{线}}}=\\frac{15}{10+16}\\approx 0.58\\,\\mathrm{A}","cues":["内阻不计","滑到零","串联总电阻"],"concepts":["闭合电路欧姆定律","串联电路"]},{"title":"量程由最大电流定","type":"前提判断","judge":"根据算出的最大电流判断该选哪个电流表量程","why":"最大电流 0.58 A 略小于 0.6 A，选 3 A 挡指针偏转不足满偏的五分之一，读数相对误差大","do":"比较最大电流与两个量程，选使指针偏转尽量大又不超程的挡位","expr":"0.58\\,\\mathrm{A}<0.6\\,\\mathrm{A}\\ll 3\\,\\mathrm{A}","cues":["选小量程","偏转大些","不超量程"],"concepts":["电流表量程选择","测量误差"]},{"title":"滑片置 b 端的用意","type":"实验操作","judge":"判断滑片置于 b 端时滑动变阻器接入阻值是最大还是最小，从而判断电流是最小还是最大","why":"限流接法中滑片在使接入阻值最大的一端时回路电流最小，可避免闭合开关瞬间电流过大损坏器材","do":"看电路图确认 b 端对应变阻器全部接入，说明闭合前电流处于最小状态","expr":"R_{\\mathrm{P}}=R_{\\max}\\Rightarrow I\\ \\text{最小}","cues":["限流接法","阻值最大","电流最小"],"concepts":["限流电路","电路安全"]},{"title":"实物连线对应原理图","type":"实验操作","judge":"判断 R0、滑动变阻器与电流表在实物图中应串在哪条支路、按什么顺序首尾相接","why":"原理图为串联限流电路，实物连线必须与之一一对应，否则变阻器起不到限流作用或电表接法错误","do":"从电源一端出发依次串接开关、滑动变阻器、电流表、线圈与 R0，回到电源另一端，核对每个接线柱","expr":"","cues":["顺着电流走","首尾相接","对照原理图"],"concepts":["串联电路","实物连线"]},{"title":"电流表读数估读","type":"数据处理","judge":"判断 0.6 A 挡下每小格代表多少、指针位置应读到哪一位","why":"0.6 A 挡分度值为 0.02 A，需估读到分度值的下一位，读数偏差会直接进入 B-I 图斜率","do":"确认所选量程的分度值，按指针所在格数读取并保留到 0.01 A 位","expr":"","cues":["先看分度值","估读一位","零点零二"],"concepts":["电表读数","估读"]},{"title":"B-I 图线取斜率","type":"图像读取","judge":"判断斜率应取图线上相距较远的两点坐标差之比，而不是取单个数据点或图线端点外的外推值","why":"B 与 I 成正比，斜率为 B/I，取相距远的两点可减小读数误差；纵轴单位是 mT，横轴是 A","do":"在直线上选两个便于读数的点，读出对应 B、I 值，作差后相除","expr":"k=\\frac{B_2-B_1}{I_2-I_1}","cues":["取直线上的点","两点相距远些","纵轴是毫特"],"concepts":["图像斜率","正比关系"]}],"308":[{"title":"液面升降的体积守恒","type":"关系建立","judge":"判断金属液从气室流入铸型室的体积与气室液面下降所腾出体积之间的关系","why":"金属液不可压缩且升液管体积不计，流入铸型室的液体体积必等于气室液面下降排出的体积","do":"用铸型室充满时的容积 S1h1 等于气室液面下降体积 S2h2 列等式","expr":"S_{1}h_{1}=S_{2}h_{2}","cues":["液体体积不变","上下体积相等","升液管体积不计"],"concepts":["体积守恒","不可压缩液体"]},{"title":"液柱高度差的起止面","type":"几何关系","judge":"判断求气室压强时液柱的竖直高度差应从哪个液面算到哪个液面","why":"气室压强需平衡大气压加上两自由液面之间的液柱压强，液柱高度差随液面升降而改变","do":"把铸型室液面到气室液面的高度差写成 h1+H+h2（充满时）或 H+h3+h4（未充满时）","expr":"\\Delta h=h_{1}+H+h_{2}","cues":["从气室液面算起","加上下降的那段","两液面高度差"],"concepts":["连通器","液体静压强"]},{"title":"气室压强由液柱平衡","type":"模型选择","judge":"判断气室内气体压强与上方气压、液柱压强之间的平衡关系","why":"液面静止时，同一段液柱两端压强差等于 ρg 乘液柱高度差","do":"对气室液面写压强平衡式，气室压强等于上方气压加液柱压强","expr":"p=p_{\\text{上}}+\\rho g\\Delta h","cues":["液柱压强","压强平衡","静止液面"],"concepts":["液体静压强","压强平衡"]},{"title":"密封后上方气体等温","type":"模型选择","judge":"判断关闭排气孔后铸型室内被封气体经历的是等温压缩过程","why":"题设明确注气过程中铸型室内温度不变，被封闭的空气质量不变","do":"对铸型室内气体用玻意耳定律，初态 p0、体积 S1h1，末态体积 S1(h1-h3)","expr":"p_{0}S_{1}h_{1}=p'S_{1}(h_{1}-h_{3})","cues":["温度不变","用玻意耳定律","封闭气体"],"concepts":["玻意耳定律","理想气体"]},{"title":"上方气压不再等于大气压","type":"前提判断","judge":"判断第二问中铸型室液面上方气压是否仍取大气压 p0","why":"排气孔关闭后上方气体被压缩，压强随体积减小而升高，不再是 p0","do":"先用等温压缩求出 p'，再把它作为液柱上端压强代入压强平衡式","expr":"p_{2}=p'+\\rho g(H+h_{3}+h_{4})","cues":["上方压强变了","不能再用大气压","先求上方压强"],"concepts":["封闭气体压强","玻意耳定律"]},{"title":"第二问液面下降量重算","type":"关系建立","judge":"判断第二问中气室液面下降高度应由哪部分液体体积决定","why":"只有进入铸型室的那部分液体（高度 h3）才使气室液面下降，不能用 h1","do":"用 S1h3 等于 S2h4 求 h4，再代入液柱高度差","expr":"S_{1}h_{3}=S_{2}h_{4}","cues":["按实际液高算","不是充满","重新算下降量"],"concepts":["体积守恒","连通器"]}],"309":[{"title":"木塞与齿轮的速度关联","type":"关系建立","judge":"木塞向上运动的速度与齿轮边缘线速度是否相等，以及用哪个半径换算角速度","why":"齿轮啮合传动、拔塞钻与木塞固定，木塞的平动速度等于齿轮节圆的线速度，这是把平动量与转动量连接的唯一桥梁","do":"写出木塞末速度与齿轮线速度相等，再用线速度与角速度关系换算","expr":"v=\\omega r,\\ v^{2}=2ah","cues":["速度相等","齿轮边缘线速度","用半径换算"],"concepts":["线速度与角速度","匀加速直线运动"]},{"title":"摩擦力做功取面积","type":"数学处理","judge":"f 随 x 线性减小到零，摩擦力做的功是否等于 f-x 图线下的面积并取负号","why":"f 是变力，不能直接用 f·h；题给提示面积表示功，且摩擦力方向与位移方向相反，功为负","do":"画出 f-x 图线，取三角形面积，加上负号表示摩擦力做负功","expr":"W_{f}=-\\frac{1}{2}f_{0}h","cues":["变力不能直接乘","图线下面积","摩擦力做负功"],"concepts":["变力做功","f-x 图像面积"]},{"title":"全过程的功与能对象","type":"模型选择","judge":"对木塞从静止到离开瓶口用动能定理，并把哪些力做的功计入方程","why":"全过程涉及变力摩擦、恒定的重力、气压差力和拔塞钻作用力，动能定理可避开中间过程的细节，只需初末动能","do":"对木塞列动能定理，左侧写拔塞钻做功、摩擦力做功、重力做功、气压差力做功，右侧写动能变化","expr":"W+W_{f}-mgh-\\Delta pSh=\\frac{1}{2}mv^{2}","cues":["取木塞为对象","用动能定理","气压差也要做功"],"concepts":["动能定理","气压差力做功"]},{"title":"气压差力方向判断","type":"前提判断","judge":"瓶外气压大于瓶内气压时，气压差对木塞的合力方向是向上还是向下，做正功还是负功","why":"题设给出瓶外气压减瓶内气压为 Δp，木塞底面积 S，气压差力大小为 ΔpS，方向由外压大指向瓶内，即向下阻碍拔出","do":"确定气压差力方向向下，故在动能定理中取负功，在牛顿第二定律中与重力、摩擦力同向","expr":"F_{压}=\\Delta pS","cues":["外压大于内压","气压差力向下","阻碍拔出"],"concepts":["压强差产生的压力","功的正负"]},{"title":"瞬时功率的力与速度","type":"关系建立","judge":"求瞬时功率时用哪个力、哪个速度，以及 F 是否随时间变化","why":"功率 P=Fv 中的 F 是拔塞钻对木塞的作用力，它需由牛顿第二定律随 f 和 v 变化求出，不能当作恒力","do":"由牛顿第二定律解出 F 的表达式，代入 f 随 x 的表达式和 x 与 t 的关系，再乘 v=at","expr":"F=ma+mg+\\Delta pS+f_{0}(1-\\frac{x}{h}),\\ x=\\frac{1}{2}at^{2},\\ P=Fv","cues":["F不是恒力","先求F再乘速度","f随位移变"],"concepts":["牛顿第二定律","瞬时功率"]},{"title":"摩擦力随时间的代换","type":"数学处理","judge":"把 f 中的位移 x 用匀加速运动的 x-t 关系替换，才能得到 P 随 t 的表达式","why":"题目要求 P 随时间 t 变化的表达式，而 f 是位移的函数，必须通过 x=at²/2 消去 x","do":"将 x=at²/2 代入 f 的表达式，再与 v=at 相乘展开","expr":"f=f_{0}(1-\\frac{at^{2}}{2h}),\\ P=(ma+mg+\\Delta pS+f_{0}-\\frac{f_{0}at^{2}}{2h})at","cues":["消去位移","换成时间","展开乘进去"],"concepts":["匀加速运动学关系","函数代换"]}],"310":[{"title":"分解两方向运动","type":"模型选择","judge":"颗粒在板间受重力和水平电场力，两力互相垂直，能否把运动拆成竖直和水平两个独立分运动分别处理","why":"重力竖直向下、匀强电场水平，两方向受力互不影响，加速度各自独立，符合运动的独立性","do":"竖直方向按自由落体、水平方向按初速为零的匀加速直线运动分别列式","expr":"h=\\frac12 gt^2,\\quad l=\\frac12 at^2","cues":["拆成两个方向","竖直自由落体","水平匀加速"],"concepts":["运动的独立性","匀变速直线运动"]},{"title":"电场力方向定电荷正负","type":"前提判断","judge":"颗粒向右下方运动且水平位移向右，电场力必须指向哪一侧，从而确定电荷正负与电场方向的关系","why":"水平方向从静止开始向右加速，合外力水平分量必向右，电场力方向由电荷正负与场强方向共同决定","do":"由水平加速度向右推出电场力向右，再结合两板电压极性确定电荷符号","expr":"qE=ma,\\quad E=\\frac Ud","cues":["电场力向右","先定正负","看水平加速度方向"],"concepts":["电场力","电荷正负"]},{"title":"碰后合力垂直于速度","type":"关系建立","judge":"碰后瞬间合力与速度垂直这一条件，如何转化为重力与电场力的比值关系","why":"合力是重力与电场力的矢量和，合力垂直于速度意味着合力方向与速度方向夹 90°，可由速度分量比得到合力分量比","do":"写出碰后速度的竖直与水平分量，令合力方向与速度方向垂直，列正切关系式","expr":"\\tan\\theta=\\frac{v_{y2}}{v_{x1}}=\\frac{QE}{mg}","cues":["合力垂直速度","用速度分量比","合力方向看正切"],"concepts":["合力","速度分解","垂直条件"]},{"title":"碰后竖直分速度取 k 倍","type":"前提判断","judge":"碰后竖直分速度大小变为碰前的 k 倍且方向反弹向上，水平分速度保持不变","why":"题设明确碰撞只改变竖直分量大小并反向、水平分量不变，这是求碰后速度和后续运动的唯一依据","do":"用碰前竖直速度乘 k 得碰后竖直速度，水平速度沿用碰前值","expr":"v_{y2}=k\\sqrt{2gh},\\quad v_{x1}=\\sqrt{\\frac{2gl^2}{h}}","cues":["竖直变k倍","水平速度不变","反弹向上"],"concepts":["速度分解","碰撞条件"]},{"title":"判断第二次碰哪块板","type":"临界条件","judge":"碰后颗粒是再次落到下绝缘板，还是先撞到右侧金属板，需比较水平位移与剩余板宽","why":"k<1 时竖直反弹高度不足以上升到上板，但水平方向持续加速，可能先到达右板，两种情形电场力做功不同","do":"先按落回下板算飞行时间和水平位移，再与 d-l 比较，分情况讨论","expr":"t'=\\frac{2kv_{y1}}{g},\\quad l'=v_{x1}t'+\\frac12 a't'^2","cues":["先算落回下板","再比剩余宽度","分两种情况"],"concepts":["临界条件","分情况讨论","匀变速运动"]},{"title":"分段累加电场力做功","type":"结论整理","judge":"电场力做功要按碰撞前后两段分别计算再相加，且每段用该段电荷量与水平位移","why":"碰撞改变了电荷量，电场力大小在碰撞前后不同，功不能用一个电荷量统一计算","do":"第一段用 q 乘水平位移 l，第二段用 Q 乘该段水平位移，两段相加","expr":"W=\\frac{qUl}{d}+\\frac{QUs}{d}","cues":["分段算功","电荷量变了","按水平位移算"],"concepts":["电场力做功","功的累加"]}],"311":[{"title":"发生光电效应的条件","type":"前提判断","judge":"判断能否逸出光电子取决于入射光子能量与金属逸出功的大小关系，而不是光强或照射时间","why":"光电效应方程 hν = W₀ + Eₖ 中，只有 hν > W₀ 时 Eₖ 才为正，电子才能逸出；光强只影响光电子数目","do":"写出光电效应的发生条件，明确比较对象是光子能量与逸出功","expr":"h\\nu > W_0","cues":["看能量够不够","跟逸出功比","光强没用"],"concepts":["光电效应","逸出功","光子能量"]},{"title":"统一能量单位后比较","type":"数学处理","judge":"判断四种金属的逸出功与 2.20 eV 光子能量能否直接比较","why":"逸出功与光子能量均以 eV 给出，单位一致，可直接数值比较，无需换算成焦耳","do":"把 2.20 eV 分别与 2.13、2.25、2.29、3.20 eV 逐一比较大小","expr":"2.20\\ \\mathrm{eV}\\ \\gtrless\\ W_0","cues":["单位都是电子伏","直接比数值","不用换焦耳"],"concepts":["电子伏","能量单位"]},{"title":"锁定满足条件的金属","type":"结论整理","judge":"判断哪些金属的逸出功小于 2.20 eV","why":"只有逸出功小于入射光子能量的金属才能发生光电效应，其余金属无论光多强都不行","do":"在四种金属中筛出逸出功小于 2.20 eV 的那一种，其余三种因 W₀ 大于光子能量而被排除","expr":"W_0 < 2.20\\ \\mathrm{eV}","cues":["找最小的逸出功","只有铷小于它","其余都超了"],"concepts":["逸出功","光电效应"]}],"312":[{"title":"区分峰值与有效值","type":"前提判断","judge":"给出的 11√2 V 是最大值还是有效值，能否直接与 220 V 相比","why":"理想变压器匝数比等于电压有效值之比，而 220 V 已明确为有效值，副线圈给的却是最大值，两者不同一标准不能直接相除","do":"识别副线圈电压为最大值，需先换算成有效值再与原线圈电压比较","expr":"U_2=\\frac{U_{2m}}{\\sqrt{2}}","cues":["先换成有效值","最大值不能直接用","正弦电要除以根号二"],"concepts":["有效值","最大值","正弦交流电"]},{"title":"选用匝数比公式","type":"关系建立","judge":"用电压比还是用电流比、功率比来求匝数比","why":"理想变压器原副线圈每匝电压相同，故匝数比等于电压有效值之比，这是唯一直接可用的关系","do":"写出原副线圈电压有效值之比等于匝数之比的方程","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2}","cues":["电压比等于匝数比","用有效值之比","别用电流比"],"concepts":["理想变压器","匝数比"]},{"title":"约简比值","type":"数学处理","judge":"220 与 11 的比值应化成最简整数比还是保留小数","why":"选项以整数比形式给出，需约分成最简整数比才能与选项对应","do":"把两电压有效值相除并约成最简整数比","expr":"\\frac{220}{11}=\\frac{20}{1}","cues":["约成最简比","整数比","别写成小数"],"concepts":["比值化简"]}],"313":[{"title":"脉搏次数换算时间","type":"数据处理","judge":"用脉搏跳动次数和脉搏频率求出这段减速过程经历的时间","why":"题中只给了脉搏跳动次数，时间必须由脉搏频率间接得到，这是本题唯一的计时信息来源","do":"把每分钟 60 次换成每秒 1 次，再用 70 次除以频率得总时间","expr":"$t=\\frac{70}{60/60}\\,\\mathrm{s}=70\\,\\mathrm{s}$","cues":["脉搏当计时器","一分钟六十次","七十次就是七十秒"],"concepts":["频率与周期","时间换算"]},{"title":"速度单位换算","type":"前提判断","judge":"把初速度由 km/h 换算成国际单位 m/s 才能与秒、米配套","why":"位移公式中的速度必须用 m/s，直接拿 36 代入会差 3.6 倍","do":"用 1 m/s = 3.6 km/h 换算初速度","expr":"$v_0=36\\,\\mathrm{km/h}=10\\,\\mathrm{m/s}$","cues":["先换成米每秒","除以三点六","单位要统一"],"concepts":["单位换算"]},{"title":"匀减速平均速度求位移","type":"模型选择","judge":"末速度为零的匀减速过程，能否用平均速度乘时间直接求位移","why":"匀变速直线运动平均速度等于初末速度的算术平均，末速为零时平均速度就是初速度的一半，无需先求加速度","do":"取初速度与末速度的平均值，乘以总时间得位移","expr":"$x=\\frac{v_0+0}{2}t=\\frac{10}{2}\\times70\\,\\mathrm{m}$","cues":["用平均速度","末速是零","不用求加速度"],"concepts":["匀变速直线运动","平均速度"]}],"314":[{"title":"金属外壳屏蔽内部","type":"模型选择","judge":"金属外壳（罩）内部的 b 点场强是否为零","why":"带电玻璃棒接触金属球后，整个验电器（球、杆、箔、外壳）成为等势体，达到静电平衡；处于静电平衡的导体内部场强处处为零，外壳把外电场屏蔽，故 b 点场强为零","do":"把 b 点定位在金属外壳内部，用静电平衡导体内部场强为零的结论直接判定","expr":"E_b=0","cues":["外壳内部没电场","静电屏蔽","导体内部场强为零"],"concepts":["静电平衡","静电屏蔽","等势体"]},{"title":"金属杆内部场强为零","type":"前提判断","judge":"金属杆内部的 c 点场强是否为零","why":"金属杆是导体的一部分，静电平衡时导体内部（包括杆内）没有净电荷定向移动，场强为零；c 点位于杆内部而非表面","do":"确认 c 点在金属杆内部，套用导体内部场强为零","expr":"E_c=0","cues":["杆里面没电场","导体内部为零","c在杆内"],"concepts":["静电平衡","导体内部场强"]},{"title":"尖端电荷分布更密","type":"关系建立","judge":"金属球表面与金属箔下端，哪处电荷面密度更大","why":"静电平衡导体的电荷分布与表面曲率有关，曲率越大（尖端、边缘）电荷越密集；金属箔下端比金属球更尖锐，面密度更大","do":"比较金属球与金属箔下端的曲率，判断电荷面密度大小关系","expr":"\\sigma_{\\text{箔下端}}>\\sigma_{\\text{球}}","cues":["尖端电荷密","箔片下端尖","球比较圆"],"concepts":["电荷分布","尖端放电","面电荷密度"]},{"title":"由电荷密度比场强","type":"关系建立","judge":"a 点与 d 点场强大小如何比较","why":"导体表面附近的场强由该处面电荷密度决定（E 与 σ 成正比），面密度越大处场强越强；d 点靠近电荷更密集的箔片下端，a 点靠近电荷较疏的金属球","do":"把 a、d 两点分别对应到金属球表面和箔片下端，用面密度大小推出场强大小","expr":"E_d>E_a","cues":["d靠近箔片下端","a在球附近","越密场强越大"],"concepts":["表面场强与面电荷密度","电场强度"]}],"315":[{"title":"定临界角上限","type":"前提判断","judge":"由折射率大于根号2，能否确定全反射临界角小于45度","why":"全反射临界角由 sinC=1/n 决定，n 越大临界角越小，n>根号2 给出 C<45度，这是后面比较入射角的基准","do":"写出 sinC=1/n，代入 n>根号2，得到 sinC<根号2/2，从而 C<45度","expr":"\\sin C=\\frac{1}{n}<\\frac{1}{\\sqrt{2}},\\ C<45^\\circ","cues":["先算临界角","折射率越大临界角越小","临界角不到四十五度"],"concepts":["全反射","临界角","折射率"]},{"title":"判断光线1入射角","type":"几何关系","judge":"光线1射到圆弧中点B时，入射角（与法线夹角）是多少，是否超过临界角","why":"圆弧面上法线沿半径方向，入射角是光线与半径的夹角，必须由等腰三角形的顶角关系算出，不能凭感觉估","do":"连圆心与A、B，利用OA=OB及圆心角45度，用三角形内角和求光线与半径OB的夹角","expr":"\\alpha=\\frac{180^\\circ-45^\\circ}{2}=67.5^\\circ","cues":["法线沿半径","连圆心","等腰三角形算角"],"concepts":["法线","入射角","等腰三角形"]},{"title":"光线1全反射判定","type":"临界条件","judge":"光线1的入射角67.5度与临界角C（小于45度）比较，是否发生全反射","why":"入射角大于临界角时发生全反射，67.5度必然大于任何小于45度的C，结论确定","do":"比较 67.5度 与 C<45度，得入射角大于临界角","expr":"\\alpha=67.5^\\circ>C","cues":["比临界角大","肯定全反射","角度差很多"],"concepts":["全反射条件","临界角"]},{"title":"光线2入射角下界","type":"关系建立","judge":"光线2射到C点偏上处，其入射角与45度的大小关系如何确定","why":"C点处半径与界面成45度，射向C点上方的光线偏离法线更多，入射角必大于45度，这是不需要精确算角的单调性判断","do":"以C点法线为参照，比较光线2方向与法线的夹角同45度的大小","expr":"\\beta>45^\\circ","cues":["比C点更偏","入射角更大","超过四十五度"],"concepts":["入射角","法线","全反射"]},{"title":"光线2全反射判定","type":"临界条件","judge":"光线2的入射角大于45度而临界角小于45度，是否发生全反射","why":"由传递关系 beta>45度>C，入射角大于临界角，全反射成立，无需知道beta的具体值","do":"串联 beta>45度 与 C<45度，得 beta>C","expr":"\\beta>45^\\circ>C","cues":["两个都大于四十五度","传递比较","一样全反射"],"concepts":["全反射条件","临界角"]}],"316":[{"title":"识别两段导体的连接方式","type":"模型选择","judge":"要判断 a 与 b 是串联还是并联，从而确定它们的电流关系还是电压关系","why":"图中两段导体分处两条支路、两端接在同一对节点上，属于并联，故电压相等而非电流相等；若误判为串联就会用电流相等去推，结论全错","do":"沿导线从电源正极出发追踪节点，确认 a、b 各自两端接在同一对节点上","expr":"U_a=U_b","cues":["看节点","两端接一起","是并联"],"concepts":["并联电路","等压关系"]},{"title":"看清 b 支路的实际长度","type":"图像读取","judge":"要判断 b 支路中参与导电的导体总长是 l2 还是 2l2","why":"图中 b 支路由两段相同导体串联而成，电阻应按 2l2 计算；漏掉这个 2 倍因子会得到错误比例","do":"数清 b 支路中同规格导体的段数，确定总长度","expr":"R_b=2\\rho\\frac{l_2}{S_2}","cues":["两段串起来","长度翻倍","看仔细"],"concepts":["电阻定律","串联电阻"]},{"title":"用电阻定律写电阻比","type":"关系建立","judge":"要判断电阻由材料、长度、横截面积共同决定，需分别写出 Ra 与 Rb 的表达式","why":"材质相同即电阻率相同，这是把几何量 l、S 与电阻联系起来的前提，也是后续把电压比转成电流比的桥梁","do":"对 a、b 分别写 R=ρl/S，并注意 b 的长度取 2l2","expr":"R_a=\\rho\\frac{l_1}{S_1},\\quad R_b=2\\rho\\frac{l_2}{S_2}","cues":["电阻定律","同种材料同电阻率","长度除面积"],"concepts":["电阻定律","电阻率"]},{"title":"由等压得电流比","type":"关系建立","judge":"要判断并联等压下电流与电阻成反比，从而把电压关系换成电流关系","why":"并联支路电压相同，由 I=U/R 可知电流与电阻成反比，这是把电阻比转化为电流比的唯一依据","do":"对两支路写 I=U/R 后相除，消去公共电压 U","expr":"\\frac{I_a}{I_b}=\\frac{R_b}{R_a}","cues":["电压相同","电流反比电阻","消去电压"],"concepts":["欧姆定律","并联分流"]},{"title":"用微观表达式联系漂移速率","type":"关系建立","judge":"要判断电流由 n、q、v、S 四个量共同决定，不能只看电流大小就比速率","why":"I=nqvS 中横截面积 S 不同，同种材料 n、q 相同，故速率比必须连同 S 一起比较，忽略 S 会得出错误比例","do":"对 a、b 分别写 I=nqvS，取 n、q 相同后作比，把电流比与面积比合并","expr":"I=nqvS\\Rightarrow \\frac{v_a}{v_b}=\\frac{I_a}{I_b}\\cdot\\frac{S_2}{S_1}","cues":["微观表达式","同种材料数密度相同","面积也要算"],"concepts":["电流的微观表达式","自由电子定向移动速率"]},{"title":"联立消元得速率比","type":"数学处理","judge":"要判断哪些量（ρ、S1、S2、U）在联立中会约掉，只留下 l1、l2 与常数因子 2","why":"题目只给长度和面积符号而未给数值，只有把 ρ、S、U 全部消去，结果才可能只含 l1、l2，这也是判断选项形式的依据","do":"把电阻比代入电流比再代入速率比，逐项约去 ρ、S1、S2、U","expr":"\\frac{v_a}{v_b}=\\frac{2l_2}{l_1}","cues":["全部约掉","只剩长度","别丢系数2"],"concepts":["比例运算","等效替换"]}],"317":[{"title":"等效总电阻","type":"模型选择","judge":"两个 2R 定值电阻并联后再与棒电阻 R 串联，总电阻是多少","why":"导轨无电阻，两端电阻并联构成外电路，棒为电源内阻，必须先把电路结构化简才能算电流和电荷量","do":"画出等效电路，先求两 2R 并联值，再串上 R","expr":"R_{\\text{总}}=\\frac{2R\\cdot 2R}{2R+2R}+R=2R","cues":["两个电阻并联","外电路先合并","再串上棒电阻"],"concepts":["等效电路","并联电阻","串联电阻"]},{"title":"用平均电流求电荷","type":"关系建立","judge":"求安培力冲量时能否用平均电流乘时间，电荷量由磁通量变化除以总电阻得到","why":"安培力 F=BIl 随时间变化，冲量需对时间积分，而 ∫I dt 恰为通过棒的电荷量，电荷量只由 ΔΦ 与 R总 决定","do":"写出冲量表达式，把 q 用 ΔΦ/R总 替换，ΔΦ 取 B l 乘扫过距离","expr":"I_{\\text{安}}=Blq,\\quad q=\\frac{Bl(a+b)}{R_{\\text{总}}}","cues":["安培力冲量","电荷量看磁通量","扫过长度是a加b"],"concepts":["安培力冲量","电荷量","磁通量变化"]},{"title":"弹簧总冲量取两倍","type":"前提判断","judge":"动量定理中弹簧冲量是单个弹簧的还是两个弹簧的合力冲量","why":"两根完全相同的弹簧并联连在棒中间，形变相同、弹力同向，合冲量是单根的两倍，漏掉倍数会算错单根冲量","do":"对棒列动量定理，弹力项写成 2I弹，再解出单根弹簧冲量","expr":"2I_{\\text{弹}}-I_{\\text{安}}+mg\\sin\\theta\\cdot t=0","cues":["两根弹簧","弹力要乘二","求的是单根冲量"],"concepts":["动量定理","弹簧弹力","冲量"]},{"title":"始末弹性势能差","type":"关系建立","judge":"初末位置弹簧形变量分别是 a 和 b，弹性势能变化该用哪个形变量","why":"中间位置为原长，向上移 a 时形变为 a，最远处在下方距中间 b，形变为 b，两弹簧势能都要计两份","do":"写出初末总弹性势能，作差得弹簧释放的势能","expr":"\\Delta E_{p}=2\\cdot\\frac12ka^{2}-2\\cdot\\frac12kb^{2}=k(a^{2}-b^{2})","cues":["原长在中间","形变是a和b","两根弹簧算两份"],"concepts":["弹性势能","形变量","能量守恒"]},{"title":"热量按电阻分配","type":"关系建立","judge":"回路总热量求出后，单个定值电阻分到多少","why":"棒与两并联电阻串联，电流关系决定功率分配，两定值电阻相同各分得总热量的四分之一","do":"先由能量守恒求总热量 Q，再按电阻比例分配给定值电阻","expr":"Q=mg\\sin\\theta(a+b)+k(a^{2}-b^{2}),\\quad Q_{1}=\\frac{Q}{4}","cues":["总热量按电阻分","定值电阻占四分之一","棒上也有热量"],"concepts":["焦耳热","能量守恒","功率分配"]},{"title":"平均功率对应总热量","type":"结论整理","judge":"平均输出功率用哪部分能量除以时间","why":"金属棒输出的机械能全部转化为回路总热量，平均功率应为总热量除以时间，而不是单个电阻的热量","do":"用总热量 Q 除以 t 得平均输出功率，与选项比对","expr":"\\bar{P}=\\frac{Q}{t}=\\frac{mg\\sin\\theta(a+b)+k(a^{2}-b^{2})}{t}","cues":["输出功率看总热量","不是单个电阻的热量","除以总时间"],"concepts":["平均功率","能量转化"]}],"318":[{"title":"油膜视为单分子层","type":"模型选择","judge":"是否把水面上的油膜当作单分子层、分子紧密排列来处理","why":"只有认定油膜是单分子层且分子紧密排列，油膜厚度才等于分子直径，才能用体积除以面积求分子大小","do":"明确实验的建模前提：油膜为单层、分子紧密排列、厚度即分子直径","expr":"d=\\frac{V}{S}","cues":["单分子层","紧密排列","厚度就是直径"],"concepts":["单分子油膜","分子模型"]},{"title":"分子简化为球形","type":"近似条件","judge":"是否把形状复杂的分子简化为球体，并用球的直径代表油膜厚度","why":"分子真实形状复杂，无法直接给出一个尺寸，只有取球形模型才能把厚度与分子直径对应起来","do":"说明球形简化是计算分子直径的必要近似","expr":"","cues":["看成小球","简化成球形","直径代表厚度"],"concepts":["球形模型","分子直径"]},{"title":"稳定油膜仍有热运动","type":"前提判断","judge":"油膜宏观上稳定不动，是否意味着分子停止热运动","why":"分子热运动是永不停息的，与宏观是否静止无关，宏观稳定只是分子平均效果的表现","do":"区分宏观静止与微观热运动，判断稳定油膜中分子仍在做无规则运动","expr":"","cues":["宏观静止","分子还在动","热运动不停"],"concepts":["分子热运动","宏观与微观"]},{"title":"不足半格舍去","type":"数据处理","judge":"数格子求油膜面积时，对边界不完整格子按什么规则取舍","why":"面积估算采用数格法，边界格子按大于半格计一格、小于半格舍去的规则处理，才能较准确估算不规则油膜面积","do":"对边界格子逐个比较是否超过半格，超过的计入、不足的舍去，再累加得面积","expr":"S=N\\times S_0","cues":["数格子","大于半格算一格","不足半格舍去"],"concepts":["数格法","面积估算"]},{"title":"酒精助油酸展开","type":"关系建立","judge":"配制油酸酒精溶液时酒精起什么作用，加与不加有何差别","why":"酒精易溶于水且能溶解油酸，随酒精挥发和水面扩散带动油酸铺展，使油酸形成尽量薄的单分子层","do":"把酒精的作用定位为帮助油酸展开、便于形成单分子膜，而非参与测量体积的主体","expr":"","cues":["酒精帮忙展开","溶解油酸","挥发后只剩油酸"],"concepts":["油酸酒精溶液","单分子膜展开"]}],"319":[{"title":"减速即合力不为零","type":"前提判断","judge":"能否由'减速滑行'直接判定选手与楠竹所受合力是否为零","why":"速度大小在改变就是有加速度，由牛顿第二定律 F=ma 知合力必不为零；匀速才谈合力为零","do":"抓住'减速'二字，确认加速度方向与速度反向，从而整体合力不为零","expr":"\\vec{F}_{合}=m\\vec{a}\\neq 0","cues":["减速就有加速度","合力不为零","匀速才合力为零"],"concepts":["牛顿第二定律","加速度","合力"]},{"title":"相对静止判重心共线","type":"关系建立","judge":"选手与楠竹保持相对静止（不翻倒、不相对滑动）时，两者的重心在水平方向上应满足什么位置关系","why":"两者无相对运动且只受重力、支持力与摩擦力，若重心错开会产生使二者相对转动的力矩，无法维持相对静止","do":"把选手和楠竹分别看作有重心的物体，比较两重心在水平方向上的投影位置","expr":"","cues":["相对静止不翻转","重心要对齐","不能一前一后"],"concepts":["重心","相对静止","力矩平衡"]},{"title":"整体法看外力作用线","type":"模型选择","judge":"分析整体受力时应把选手和楠竹取作一个整体，还是分别隔离分析","why":"题目只问整体重心与合力作用线的关系，取整体可避开两者之间的内力（支持力、摩擦力），只保留水对楠竹的外力","do":"把选手与楠竹合并为一个整体，画出水对楠竹的阻力等外力，找其合力作用线","expr":"","cues":["取整体","避开内力","只看水的作用力"],"concepts":["整体法","内力与外力","合力作用线"]},{"title":"合力作用线过重心","type":"关系建立","judge":"整体所受合外力（水平阻力）的作用线与整体重心在竖直方向上是否必须共面","why":"整体做减速平动，合外力若不过重心会产生使整体翻转的力矩，与'稳定滑行不翻转'矛盾，故合力作用线必过重心所在竖直线","do":"将水对楠竹的合力作用线与整体重心竖直线比较，判断是否在同一竖直面上","expr":"","cues":["合力过重心","不产生翻转","作用线对齐重心"],"concepts":["合力作用线","重心","力矩"]}],"320":[{"title":"加速场求速度","type":"关系建立","judge":"能否用加速电场把粒子进入选择器的速度与质量、U 联系起来","why":"初速几乎为零，电场力做功等于动能增量，这是后续所有速度、半径的起点","do":"对 M、N 分别写加速过程动能定理，得到 v0 与 m 的关系","expr":"qU=\\frac12 m v_0^2","cues":["初速为零","电场做功","先求速度"],"concepts":["动能定理","加速电场"]},{"title":"选择器直线通过条件","type":"前提判断","judge":"M 沿轴线直线穿过时，电场力与洛伦兹力必须平衡","why":"速度选择器只让满足 v=E/B1 的粒子无偏转通过，这是求 M 质量和速度的唯一依据","do":"对 M 写 qv0B1=qE，与加速式联立消去 v0","expr":"qv_0B_1=qE","cues":["电场力等于洛伦兹力","直线通过","速度选择器"],"concepts":["洛伦兹力","电场力平衡"]},{"title":"由偏转方向定速度大小","type":"结论整理","judge":"N 向下偏转说明洛伦兹力大于电场力，从而判断 N 的速度比 M 大还是小","why":"选择器中电场竖直向上、磁场向外，正电荷向下偏转意味着 qvB1>qE","do":"比较 N 的 v0N 与 M 的 v0M，判断 B 项的速度大小关系","expr":"qv_{0N}B_1>qE\\Rightarrow v_{0N}>v_{0M}","cues":["向下偏","洛伦兹力大","速度更大"],"concepts":["洛伦兹力方向","左手定则"]},{"title":"偏转磁场几何关系","type":"几何关系","judge":"M、N 打在同一点时，两圆轨迹的弦长与开口宽度 2d 构成什么几何约束","why":"N 从开口下边缘斜射入，M 沿轴线射入，两者落点相同，必须用弦长关系把 r1、r2、θ 联系起来","do":"画两段圆弧，找公共落点，列弦长差与 d 的关系","expr":"2r_1-2r_2\\cos\\theta=d","cues":["画轨迹","弦长关系","落点相同"],"concepts":["圆周运动","几何弦长"]},{"title":"选择器中电场力做功","type":"关系建立","judge":"N 在选择器中向下偏转 d，电场力做正功还是负功，动能如何变化","why":"N 从轴线下偏 d 出射，电场竖直向上，位移向下，电场力做负功，这是联系 v0N 与 vN 的桥梁","do":"对 N 写选择器中的动能定理，再与加速、偏转半径式联立求 mN","expr":"-qEd=\\frac12 m_N v_N^2-\\frac12 m_N v_{0N}^2","cues":["电场力做负功","下落d","动能减少"],"concepts":["动能定理","电场力做功"]},{"title":"直线通过所需场比","type":"临界条件","judge":"要让 N 也沿轴线直线通过，调节后的 E' 与 B' 之比应等于什么","why":"速度选择器的通过速度由 E/B 决定，N 要直线通过必须使 E'/B'=v0N","do":"把已求出的 v0N 代入 E'/B'=v0N，检验 C 项给出的比值是否一致","expr":"\\frac{E'}{B'}=v_{0N}","cues":["比值等于速度","调节场","直线通过"],"concepts":["速度选择器","场比与速度"]}],"321":[{"title":"调零时表笔短接","type":"实验操作","judge":"欧姆表调零时 A、B 两端应处于什么状态","why":"欧姆表测电阻前必须让表笔短接，使指针指到满偏，以此标定内阻对应的零欧姆刻度","do":"判断调零操作是把 A、B 直接短接还是接入标准电阻","expr":"","cues":["短接表笔","两表笔碰一起","接标准电阻"],"concepts":["欧姆表调零","短接"]},{"title":"满偏电流定零刻度","type":"前提判断","judge":"调零完成时电流表应指到哪个电流值","why":"欧姆表的零欧刻度对应表头满偏，调零就是把指针调到满偏电流处","do":"比较调零目标电流与电流表满偏电流 Ig","expr":"I=I_g=100\\,\\mu\\mathrm{A}","cues":["调到满偏","指到最大","看满刻度"],"concepts":["满偏电流","欧姆表刻度"]},{"title":"调零电阻用闭合电路求","type":"关系建立","judge":"调零时滑动变阻器阻值由哪条电路方程决定","why":"调零时外电阻为零，回路只有电源、表头、R0 和滑动变阻器串联，由闭合电路欧姆定律确定总电阻","do":"用 Ig=E/(Rg+R0+R) 反解滑动变阻器阻值","expr":"R=\\frac{E}{I_g}-R_g-R_0","cues":["串联回路","闭合电路欧姆定律"],"concepts":["闭合电路欧姆定律","串联电路"]},{"title":"中值内阻的确定","type":"模型选择","judge":"测电阻时把欧姆表内部等效成什么","why":"调零后欧姆表内阻固定，接入 Rx 后电流由 E 与 (R内+Rx) 决定，内阻即调零时的总电阻","do":"写出 R内=E/Ig，并确认它与调零时总电阻相等","expr":"R_{\\text{内}}=\\frac{E}{I_g}","cues":["等效内阻","内阻不变","总内阻"],"concepts":["欧姆表内阻","等效电路"]},{"title":"由电流反求待测电阻","type":"关系建立","judge":"已知接入 Rx 后的电流，如何求 Rx","why":"接入 Rx 后回路总电阻为 R内+Rx，电流 I=E/(R内+Rx)，解出 Rx 即可","do":"用 I=E/(R内+Rx) 解出 Rx=E/I−E/Ig 并换算单位","expr":"R_x=\\frac{E}{I}-\\frac{E}{I_g}","cues":["总电阻减内阻","电动势除电流","单位换千欧"],"concepts":["闭合电路欧姆定律","欧姆表测电阻"]}],"322":[{"title":"确定实验方法","type":"前提判断","judge":"研究 a 与 F 的关系时，应保持哪个物理量不变、改变哪个量","why":"牛顿第二定律涉及 a、F、M 三个量，要单独研究 a 与 F 的关系，必须固定 M","do":"对照实验目的，指出保持小车（含传感器）质量不变、只改变拉力，属于哪种实验方法","expr":"","cues":["只变拉力","质量不变","控制变量"],"concepts":["控制变量法","牛顿第二定律"]},{"title":"细绳与轨道平行","type":"实验操作","judge":"细绳拉力方向是否与小车运动方向共线，从而决定定滑轮高度如何调","why":"只有拉力沿轨道方向，拉力才等于小车所受合外力沿运动方向的分量，否则出现垂直分力、增大摩擦与误差","do":"调节定滑轮高度，使连接小车的细绳与轨道平面平行","expr":"","cues":["绳子要平行","调滑轮高度","拉力沿轨道"],"concepts":["力的分解","合外力"]},{"title":"从图像判断是否需平衡摩擦","type":"图像读取","judge":"a-F 图线是否过原点，即 F 为零时 a 是否为零","why":"若存在摩擦，拉力需先克服摩擦力才产生加速度，图线在 F 轴上有截距，说明必须补偿阻力","do":"看图(b)中图线与横轴的交点是否在原点，若不过原点则判定需要平衡阻力","expr":"","cues":["看横轴截距","图线不过原点","有拉力才动"],"concepts":["a-F 图像","摩擦力","截距"]},{"title":"平衡阻力的正确操作","type":"实验操作","judge":"平衡阻力时是否应撤去细绳和重物，只让小车在倾斜轨道上匀速下滑","why":"平衡阻力的依据是重力沿斜面的分力与摩擦力等大反向，若仍挂重物则拉力参与，无法单独平衡摩擦","do":"撤去细绳、力传感器和重物，垫高轨道一端，轻推小车使其能匀速下滑","expr":"","cues":["撤掉重物","垫高木板","轻推匀速"],"concepts":["平衡摩擦力","匀速运动"]},{"title":"由时间比求加速度比","type":"关系建立","judge":"两车均从静止做匀加速直线运动，相同位移下加速度与时间成什么关系","why":"初速度为零的匀加速直线运动满足 x=½at²，位移相同时 a 与 t² 成反比","do":"对 M、N 两车分别写 x=½at²，消去相同的 x，代入 t_M:t_N=n:1 求加速度之比","expr":"$x=\\frac{1}{2}at^{2}\\Rightarrow a=\\frac{2x}{t^{2}}\\Rightarrow \\frac{a_M}{a_N}=\\frac{t_N^{2}}{t_M^{2}}$","cues":["初速为零","位移相同","时间平方反比"],"concepts":["匀变速直线运动","位移公式"]}],"323":[{"title":"读图取波长","type":"图像读取","judge":"从波形图上判断相邻同相点（如两个相邻波峰）的水平间距，读出两列波各自的波长","why":"波长定义为相邻同相点的距离，图上横轴单位是米，必须按坐标刻度读出而非凭波形疏密估计","do":"在图(a)上量相邻两波峰（或两波谷）的横坐标差得 λ₁，在图(b)上同样操作得 λ₂","expr":"λ₁=0.5\\,\\mathrm{m},\\ \\lambda₂=1\\,\\mathrm{m}","cues":["看相邻波峰间距","横轴一格是多少","两图波长不一样"],"concepts":["波长","波形图"]},{"title":"同频率才可叠加","type":"前提判断","judge":"判断两列波能否用同一时刻的波形直接相加，即两波是否同频率、同方向传播、振动方向相同","why":"波的叠加原理要求两列波在同一质点引起同方向振动，且题给同一时刻波形图，只有相干条件满足才能把位移代数相加","do":"由声速相同、波长成二倍关系确认频率成二倍关系，两波均沿 x 正方向传播，故同一时刻波形可直接叠加","expr":"f_1=2f_2,\\ v_1=v_2=v","cues":["同方向传播","频率成两倍","同一时刻波形"],"concepts":["波的叠加原理","频率"]},{"title":"由相位定各波位移","type":"关系建立","judge":"判断 x=0 与 x=0.375 m 处各列波在该时刻处于什么相位（波峰、平衡位置还是中间值）","why":"简谐波上各点位移由该点到波源（或原点）的相位差决定，必须把距离换算成波长的倍数才能定出相位","do":"x=0 处两波均为波峰；x=0.375 m 对第一列波为 3λ₁/4，对第二列波为 3λ₂/8，分别代入余弦式求位移","expr":"y=A\\cos\\left(\\frac{2\\pi x}{\\lambda}\\right)","cues":["波峰处位移最大","四分之三波长对应零"],"concepts":["相位","简谐波方程"]},{"title":"叠加求合位移","type":"数学处理","judge":"判断两列波在该点的位移是相加还是相减，即各自的正负号如何取","why":"叠加是位移的矢量和，两波振动方向相同，故按代数和相加，符号由各自相位决定","do":"x=0 处两波峰相加；x=0.375 m 处第一列波位移为零、第二列波为负值，二者代数相加","expr":"y=y_1+y_2","cues":["代数和","一个为零一个为负","同向振动直接加"],"concepts":["波的叠加","位移合成"]},{"title":"拍周期取差频","type":"关系建立","judge":"判断叠加后呈现的周期性变化由什么决定——是各波自身周期还是两波频率之差","why":"两列频率不同的简谐波叠加形成拍，合振动振幅按差频周期性变化，其周期由频率差决定而非单个波的周期","do":"由 λ 和 v 求各波周期，确认 T₂=2T₁，再用差频求拍的周期","expr":"T=\\frac{1}{|f_1-f_2|}=\\frac{1}{340}\\,\\mathrm{s}","cues":["不是单个波的周期","频率差决定","两倍关系取差频"],"concepts":["差频","周期"]}],"324":[{"title":"椭圆上到焦点距离","type":"几何关系","judge":"椭圆上任一点到两焦点距离之和为 2a，且源电荷只在一个焦点上，需判断 B 点到源电荷的距离","why":"椭圆定义给出 r1+r2=2a，B 在半短轴顶点时两焦点距离相等，故各为 a","do":"用椭圆定义写出 B 点到左焦点距离，并推广到 A 点距离","expr":"r_B=a,\\quad r_A=a-c","cues":["用椭圆定义","到两焦点之和","B点对称"],"concepts":["椭圆定义","焦点","半长轴"]},{"title":"电势随距离代入","type":"关系建立","judge":"把各点电势写成该点到源电荷距离的函数，而不是用椭圆中心或半短轴长度","why":"电势公式 φ=kQ/r 中的 r 是场源到该点的距离，源电荷在左焦点而非椭圆中心","do":"分别将 r_B、r_A 代入 φ=kQ/r 得 φ_B、φ_A","expr":"\\varphi_B=\\frac{kQ}{a},\\quad \\varphi_A=\\frac{kQ}{a-c}","cues":["源电荷在焦点","r是到场源距离","别用中心距离"],"concepts":["点电荷电势","电势叠加"]},{"title":"电场力做功正负","type":"前提判断","judge":"判断电场力做功与电势能变化、电势差之间的符号关系，明确 W=qU 中 q 取负值","why":"电场力做功等于电势能减少量，W_AB=q(φ_A-φ_B)，粒子带 -q，符号不能丢","do":"写出 W_AB=-q(φ_A-φ_B)，代入两电势并化简","expr":"W_{AB}=-q(\\varphi_A-\\varphi_B)=-kQq\\left(\\frac{1}{a-c}-\\frac{1}{a}\\right)","cues":["电荷是负的","做功等于电势能减少","先定正负"],"concepts":["电场力做功","电势能","电势差"]},{"title":"从图像斜率截距读信息","type":"图像读取","judge":"判断 v²-1/r 图线为直线意味着什么函数关系，并读出斜率与截距的物理含义","why":"若机械能守恒则 v² 与 1/r 成线性关系，斜率对应 2kQq/m，截距对应 2C/m","do":"设 ½mv²+(-q)kQ/r=C，整理成 v² 关于 1/r 的一次式，与图线比对","expr":"v^2=\\frac{2kQq}{m}\\cdot\\frac{1}{r}+\\frac{2C}{m}","cues":["看斜率","看截距","化成一次函数"],"concepts":["机械能守恒","图像斜率","动能与电势能"]},{"title":"用图线截点定常数","type":"数据处理","judge":"选取图线与横轴交点 (1/2a, 0) 作为定值 C 的代入点，判断该点对应 v=0、r=2a","why":"图线过该点说明在 r=2a 处动能为零，此时总能量等于电势能，可直接定出 C","do":"把 1/r=1/(2a)、v²=0 代入线性关系解出 C","expr":"C=-\\frac{kQq}{2a}","cues":["取横轴交点","那点动能为零","代截距"],"concepts":["总能量","电势能","图线交点"]},{"title":"守恒性由线性关系反推","type":"结论整理","judge":"判断图线是直线是否足以证明动能与电势能之和守恒，而非仅凭图像形状猜测","why":"只有假设 ½mv²+qφ=C 才能推出 v² 与 1/r 的线性关系，图线确为直线即验证假设成立","do":"由假设推出线性式，与题给直线图对照，确认斜率截距为常数，再给出守恒结论及总能量值","expr":"\\frac{1}{2}mv^2+(-q)\\frac{kQ}{r}=C","cues":["先假设再验证","直线说明守恒","总能量是常数"],"concepts":["能量守恒","反证法","保守力场"]}],"325":[{"title":"脉冲面积对应冲量","type":"图像读取","judge":"图(b)中脉冲与横轴所围面积代表什么物理量","why":"冲量式传感器输出的是力随时间变化的图像，力对时间的积分就是散货撞击时对传感器的冲量","do":"把脉冲面积 I 认定为单次撞击的冲量大小，而不是峰值力或作用时间","expr":"I=\\int F\\,dt","cues":["面积就是冲量","力乘时间","不是峰值"],"concepts":["冲量","动量定理","F-t图像"]},{"title":"撞击后水平动量归零","type":"前提判断","judge":"撞击前后散货水平方向动量变化由哪个速度决定","why":"题设撞击后水平速度变为 0、竖直速度不变，故水平方向动量变化量大小为 mv0，竖直方向不产生水平冲量","do":"只对水平方向列动量定理，把初动量 mv0 与冲量 I 对应起来","expr":"I=mv_0","cues":["只看水平方向","竖直速度不变","末速度为零"],"concepts":["动量定理","分方向动量","冲量"]},{"title":"计数间隔定单件周期","type":"关系建立","judge":"相邻两件散货落到水平传送带上的时间间隔是多少","why":"相同时间间隔 Δt 放置，第 10 个放置时第 1 个恰好抛出，说明每件在倾斜带上经历的时间为 9Δt，稳定后输出周期也是 Δt","do":"用第 1 个与第 10 个之间的时间差除以间隔数，得到单件在倾斜带上的总时间 9Δt","expr":"t_1+t_2=9\\Delta t","cues":["第10个对应第1个","间隔数是9","周期就是Δt"],"concepts":["时间间隔","周期性","相对运动"]},{"title":"加速段与匀速段分界","type":"临界条件","judge":"散货在倾斜带上何时结束加速、进入与带共速的匀速段","why":"题设到达顶端前已与传送带共速，说明先匀加速后匀速，共速时刻是两段运动的分界","do":"由摩擦力和重力沿斜面分量求加速度，再由 v0 求加速时间与加速位移，剩余时间按匀速处理","expr":"a=\\mu g\\cos30^\\circ-g\\sin30^\\circ=\\tfrac14 g,\\quad t_1=\\frac{v_0}{a}","cues":["先加速后匀速","共速是分界","到顶前已共速"],"concepts":["牛顿第二定律","匀变速运动","共速"]},{"title":"相对位移生热","type":"关系建立","judge":"传送带额外做功中摩擦生热用哪段相对位移计算","why":"只有加速阶段散货与传送带速度不同，才有相对滑动和摩擦生热，匀速段无相对位移","do":"用带速乘加速时间减去散货加速位移得到相对位移，再乘摩擦力得热量","expr":"\\Delta x=v_0t_1-x_1,\\quad Q=\\mu mg\\cos30^\\circ\\,\\Delta x","cues":["只有加速段有相对滑动","带走的比货走的多","匀速段不生热"],"concepts":["相对位移","摩擦生热","功能关系"]},{"title":"平均功率取单件周期","type":"模型选择","judge":"求倾斜传送带平均输出功率时对哪段时间、哪些能量求和","why":"稳定运行后每 Δt 输出一件，传送带在一个周期内需提供散货动能增量、重力势能增量及摩擦热","do":"对一个 Δt 内的单件散货列能量方程，再除以 Δt 得平均功率","expr":"W=\\tfrac12mv_0^2+mgL\\sin30^\\circ+Q,\\quad \\bar P=\\frac{W}{\\Delta t}","cues":["按一个周期算","动能加重力势能加生热","再除以间隔"],"concepts":["功能关系","平均功率","能量守恒"]}],"326":[{"title":"识别匀减速模型","type":"模型选择","judge":"判断该过程是否为加速度恒定的匀变速直线运动","why":"题干明确说“做匀减速直线运动”，只有加速度恒定才能用 v=v₀+at 一次求解","do":"确认速度随时间均匀减小，选定匀变速直线运动的速度公式作为主方程","expr":"v=v_0+at","cues":["匀减速","加速度不变","用速度公式"],"concepts":["匀变速直线运动","加速度"]},{"title":"规定正方向定符号","type":"前提判断","judge":"判断初速度、末速度、加速度在所选正方向下的正负号","why":"速度由 12 m/s 减至 0，加速度方向与初速度相反，若取初速度方向为正，则 a 必为负值","do":"取初速度方向为正，令 v₀=12 m/s、v=0，代入后解出的 a 带负号","expr":"0=12+a\\times2","cues":["取初速方向为正","加速度取负","减速所以带负号"],"concepts":["正方向规定","矢量符号"]},{"title":"区分加速度与大小","type":"结论整理","judge":"判断题目问的是加速度矢量还是加速度大小","why":"题干问“加速度大小为”，负号只表示方向，大小应取绝对值","do":"对解出的 a 取绝对值，与选项中的正值比较","expr":"|a|=6\\ \\mathrm{m/s^2}","cues":["问的是大小","负号去掉","取绝对值"],"concepts":["加速度大小","矢量与标量"]}],"327":[{"title":"识别理想变压器模型","type":"模型选择","judge":"判断能否用理想变压器的电压比等于匝数比来处理本题","why":"可拆变压器在探究实验中忽略漏磁与损耗，题设只给输入、输出电压和副线圈匝数，只有用理想变压器规律才能把电压与匝数联系起来","do":"确认这是理想变压器，写出电压比与匝数比相等的关系式","expr":"\\frac{U_1}{U_2}=\\frac{n_1}{n_2}","cues":["理想变压器","电压比等于匝数比","忽略漏磁"],"concepts":["理想变压器","匝数比","电压比"]},{"title":"接线柱对应匝数","type":"前提判断","judge":"判断右侧选“0”和“4”时副线圈的匝数是多少，以及左侧选“0”和某接线柱时原线圈匝数如何表示","why":"可拆变压器每个接线柱标号代表从“0”端数起的匝数，选两个接线柱之间的匝数差才是接入匝数，不明确这一点就无法把电压比换算成接线柱编号","do":"读出右侧“0”到“4”对应副线圈匝数，并把左侧待求匝数记为对应接线柱编号","expr":"n_2=4","cues":["标号就是匝数","从零数起","接线柱间匝数"],"concepts":["原线圈","副线圈","接线柱"]},{"title":"由电压比求原匝数","type":"关系建立","judge":"判断输入电压小于输出电压时原线圈匝数应少于副线圈匝数，并据此算出原线圈匝数","why":"电压比等于匝数比，输入 2 V 小于输出 4 V，原线圈匝数必为副线圈的一半，这是判断接线柱选择的核心依据","do":"把输入、输出电压和副线圈匝数代入电压比式，解出原线圈匝数","expr":"\\frac{2}{4}=\\frac{n_1}{4}\\Rightarrow n_1=2","cues":["降压还是升压","电压小的匝数少","一半匝数"],"concepts":["电压比","匝数比","升压变压器"]},{"title":"匝数对应接线柱编号","type":"结论整理","judge":"判断原线圈匝数为 2 时应选哪两个接线柱","why":"原线圈匝数等于两接线柱标号之差，只有选“0”和“2”才得到 2 匝，选其他组合匝数不符","do":"在左侧接线柱中找出标号差为 2 的一对","expr":"n_1=2-0=2","cues":["选零和二","标号差为二","对应接线柱"],"concepts":["接线柱选择","匝数差"]}],"328":[{"title":"磁感线疏密表示强弱","type":"前提判断","judge":"要判断磁感线的疏密程度与磁感应强度大小的对应关系","why":"磁感线是为形象描述磁场而引入的，规定磁感线越密处磁感应强度越大，越疏处越小","do":"明确用磁感线的疏密来比较各点磁感应强度大小，而不是看磁感线方向或箭头数","expr":"","cues":["看疏密","越密越强","不看方向"],"concepts":["磁感线","磁感应强度"]},{"title":"比较三点疏密","type":"图像读取","judge":"要判断 a、b、c 三点各自所在区域磁感线的疏密次序","why":"只有先读出图中各点附近磁感线的密集程度，才能按疏密规律排出磁感应强度大小","do":"观察图中 a、b、c 三点附近磁感线的间距，间距越小越密，据此排出三点的疏密顺序","expr":"","cues":["看间距","b处最密","c处最疏"],"concepts":["磁感线疏密","磁场分布"]},{"title":"由疏密定大小关系","type":"关系建立","judge":"要把读出的疏密次序转化为三点磁感应强度的大小关系","why":"疏密与磁感应强度大小一一对应，疏密次序直接决定 B 的大小次序","do":"按疏密从大到小写出三点磁感应强度的大小排序，与选项给出的不等式比较","expr":"","cues":["排大小","密处B大","对应选项"],"concepts":["磁感应强度大小","磁感线"]}],"329":[{"title":"区分两个转动参考","type":"模型选择","judge":"要判断杯上 A 点的运动应分解为哪两个转动，以及这两个转动分别绕哪个轴","why":"题设给出底盘绕 O 转动、转杯绕 O' 转动且 O' 固定在底盘上，A 点同时参与绕 O' 的自转和随 O' 绕 O 的公转，不能把 A 当成单一圆周运动","do":"把 A 的运动写成绕 O' 的圆周运动与 O' 绕 O 的圆周运动的合成，明确两个转动的圆心和半径","expr":"\\vec v_A=\\vec v_{A/O'}+\\vec v_{O'}","cues":["两个转动","绕O和绕O撇","合成运动"],"concepts":["运动的合成","圆周运动","参考系"]},{"title":"判定 A 的轨迹非圆","type":"结论整理","judge":"要判断 A 点相对地面的轨迹是否为圆、运动是否为匀速圆周运动","why":"两个不同圆心、不同半径的匀速圆周运动叠加后，合运动轨迹一般不是圆，只有单一圆周运动才满足匀速圆周运动的条件","do":"由两个分运动圆心不同、半径不同，判断合轨迹不是圆，从而排除“A 做匀速圆周运动”的说法","expr":"","cues":["轨迹不是圆","两个圆心不同","不是单一圆周"],"concepts":["匀速圆周运动","运动合成"]},{"title":"O' 的运动性质","type":"前提判断","judge":"要判断 O' 点相对地面做什么运动","why":"O' 固定在底盘上，随底盘绕 O 做匀速转动，到 O 的距离不变，故 O' 做匀速圆周运动","do":"由 O' 固定在底盘上、底盘绕 O 匀速转动，得出 O' 绕 O 做匀速圆周运动","expr":"v_{O'}=\\omega_{\\text{底}}r_{OO'}","cues":["O撇固定在底盘","绕O转","匀速圆周"],"concepts":["匀速圆周运动","角速度"]},{"title":"共线时的速度方向","type":"几何关系","judge":"要判断 A 与 O、O' 共线时，A 相对 O' 的速度方向与 O' 的速度方向是相同还是相反","why":"A 在 OO' 延长线上，A 绕 O' 转动的线速度垂直于 OO'，其指向由转杯的顺时针转动决定，需与 O' 绕 O 转动的速度方向比较","do":"画出该时刻 OO' 连线，标出 O' 绕 O 的速度方向，再由转杯顺时针转动定出 A 相对 O' 的速度方向，比较两者是否同向","expr":"\\vec v_A=\\vec v_{O'}+\\vec v_{A/O'}","cues":["共线时刻","速度方向相同","顺时针判断"],"concepts":["线速度方向","几何关系"]},{"title":"比较速度大小","type":"关系建立","judge":"要判断共线时刻 A 的速度与 O' 的速度谁大","why":"两速度同向时合速度大小等于两者之和，必大于 O' 的速度；若反向则需相减，结论会不同，故方向判断是大小比较的前提","do":"把同向的两分速度大小相加，与单独 O' 的速度比较","expr":"v_A=v_{O'}+v_{A/O'}>v_{O'}","cues":["同向相加","A更快","合速度更大"],"concepts":["速度合成","线速度"]}],"330":[{"title":"过程快慢定绝热","type":"近似条件","judge":"瓶塞跳出、气体迅速膨胀的过程能否当作来不及与外界交换热量","why":"过程时间极短，瓶内气体与外界的热交换量可忽略，必须按绝热过程处理，否则无法由热力学第一定律判断内能变化","do":"比较膨胀过程的时间与热交换所需时间，判断 Q 是否可忽略","expr":"Q\\approx 0","cues":["来不及吸热","过程太快","按绝热算"],"concepts":["绝热过程","热力学第一定律"]},{"title":"判断对外做功","type":"关系建立","judge":"瓶内气体体积膨胀时是气体对外做功还是外界对气体做功","why":"瓶塞跳出、气体体积增大，气体对外界做正功，这是内能变化的直接原因","do":"由体积增大判断 W 的符号，气体对外做功取 W<0（对气体而言）","expr":"W<0","cues":["体积变大","气体对外做功","推瓶塞出去"],"concepts":["做功","体积变化"]},{"title":"内能温度变化","type":"结论整理","judge":"由绝热且对外做功，判断气体内能和温度如何变化","why":"热力学第一定律 ΔU=W+Q，Q≈0 而气体对外做功，故内能减小，理想气体内能只由温度决定，温度随之降低","do":"把 Q≈0 与 W<0 代入第一定律，得 ΔU<0，再联系温度","expr":"\\Delta U=W+Q<0","cues":["内能减小","温度降低","白雾是液化"],"concepts":["热力学第一定律","内能","温度"]},{"title":"压强变化判断","type":"关系建立","judge":"温度降低、体积增大时压强如何变化","why":"由理想气体状态方程 pV/T=C，V 增大、T 减小，两者都使 p 减小，故压强一定减小","do":"对初末状态列 pV/T 相等，比较 V 与 T 的变化方向","expr":"\\frac{pV}{T}=C","cues":["体积大温度低","压强变小","用气态方程"],"concepts":["理想气体状态方程","压强"]}],"331":[{"title":"判断亮环的成因","type":"模型选择","judge":"亮环是光在膜内多次反射/折射形成的干涉或色散现象，还是光在膜与空气界面发生全反射后沿膜传播形成的？","why":"题中只有一束激光、一个亮环，且未给出膜厚与波长关系；若按薄膜干涉解释，亮环位置应由膜厚与波长决定，与'一束激光射入后出现亮环'的几何特征不符，故应取全反射模型。","do":"比较两种机制：薄膜干涉需要厚度渐变且出现明暗条纹；全反射只需入射角超过临界角，光被限制在膜内沿弯曲膜面传播并形成亮环。","expr":"","cues":["是干涉吧","膜很薄会干涉","光被关在膜里","全反射"],"concepts":["全反射","薄膜干涉","临界角"]},{"title":"确定全反射发生在哪个界面","type":"前提判断","judge":"全反射发生在肥皂膜与内部空气的界面，还是膜与外部空气的界面？","why":"光从光密介质（肥皂膜，折射率大于空气）射向光疏介质（空气）时才可能全反射；膜两侧都是空气，但光必须先由外部空气进入膜内，再在膜的内表面（膜—内部空气）处满足入射角大于临界角。","do":"画出光由空气→膜→内部空气的路径，标出光在膜内表面处的入射角，判断该角能否超过临界角。","expr":"","cues":["从膜射向空气","光密到光疏","内表面反射","膜比空气折射率大"],"concepts":["光密介质","光疏介质","全反射条件"]},{"title":"由全反射解释亮环形状","type":"关系建立","judge":"全反射后光沿膜传播，能否说明亮环是光在弯曲膜内'绕行'并被散射/出射形成的闭合亮环？","why":"全反射把光约束在膜内，膜是球壳状弯曲的，光沿膜走一圈即可在膜内形成环形亮迹；这解释了'亮环'而非'亮点'的几何形态。","do":"把膜看作弯曲的光导层，说明全反射光沿膜面传播并绕泡一周，从各处出射或散射形成环状亮区。","expr":"","cues":["膜是弯的","光绕着泡走","一圈都亮","像光纤一样"],"concepts":["全反射","光导","几何形态"]},{"title":"排除波长与环长的关联","type":"结论整理","judge":"亮环的周长（大小）是否由激光波长决定？","why":"全反射只由折射率和入射角决定，与波长无关；不同波长激光频率相同、波长不同，但亮环位置不由波长决定，故'波长与亮环周长有关'的说法错误。","do":"指出亮环由全反射路径决定，与波长无直接关系，据此排除把环长与波长挂钩的选项。","expr":"","cues":["跟波长无关","频率才不变","环长不看波长","全反射不看颜色"],"concepts":["波长","频率","全反射"]}],"332":[{"title":"速率分布图的峰位与温度","type":"图像读取","judge":"要判断速率分布曲线峰值位置和高速分子占比随温度如何变化","why":"温度是分子平均动能的标志，温度升高使速率分布曲线整体右移、高速分子占比增大","do":"比较甲、乙两条曲线的峰值横坐标位置和右侧尾部的高低","expr":"","cues":["看峰值位置","曲线右移","高速分子变多"],"concepts":["速率分布曲线","温度","分子平均动能"]},{"title":"由分布图反推温度高低","type":"关系建立","judge":"要判断乙状态温度比甲状态高还是低","why":"乙曲线高速分子占比更大，说明分子平均速率更大，对应温度更高","do":"比较两状态下高速段分子所占比例，得出温度高低关系","expr":"","cues":["乙温度更高","高速分子多","平均动能大"],"concepts":["温度","分子平均动能","速率分布"]},{"title":"体积不变推分子数密度","type":"前提判断","judge":"要判断体积相同时分子数密度和分子平均间距是否相同","why":"一定质量理想气体分子总数不变，体积相同则数密度相同，与温度无关","do":"由体积相同直接得出分子数密度相同、平均间距相同","expr":"n=\\frac{N}{V}","cues":["体积相同","数密度一样","间距不变"],"concepts":["分子数密度","分子平均间距"]},{"title":"温度升高对压强的影响机制","type":"关系建立","judge":"要判断温度升高时单位时间内撞击器壁的分子数和每次碰撞的冲量如何变化","why":"体积不变时温度升高，分子数密度不变但平均速率增大，单位时间碰撞次数增多且每次碰撞冲量变大，故压强增大","do":"从碰撞次数和单次冲量两个角度分析压强变化","expr":"p=\\frac{1}{3}nm\\overline{v^2}","cues":["碰撞次数变多","冲量变大","压强变大"],"concepts":["气体压强","碰撞","分子平均速率"]}],"333":[{"title":"电源连接电压不变","type":"前提判断","judge":"移动极板时电容器是接在电源上还是已断开，从而判断极板间电压 U 变不变","why":"题设说平行金属板与电源连接，移动极板过程中电源持续供电，极板电压被电源钳制不变；若误判为断开（电荷量不变），后面 E 的变化方向就全错","do":"读题干确认“与电源连接”，锁定 U 为不变量，排除用 Q 不变去推 E 的路线","expr":"U=\\text{const}","cues":["接电源","电压不变","别用电荷量不变"],"concepts":["电容器","电压","电源"]},{"title":"场强随板距反比","type":"关系建立","judge":"板距变为 2 倍后，匀强电场的场强按什么规律变化","why":"电压不变时由 E=U/d 得 E 与 d 成反比，板距加倍则场强减半；这是把“距离变化”翻译成“场强变化”的唯一桥梁","do":"写出 E=U/d，比较 d 变为 2d 前后的 E","expr":"E=\\frac{U}{d},\\quad E'=\\frac{E}{2}","cues":["场强减半","距离翻倍","用电压除以板距"],"concepts":["匀强电场","电场强度","电势差"]},{"title":"做功只沿场强方向","type":"几何关系","judge":"a 到 b 的位移中，哪一段沿电场方向、哪一段垂直于电场方向","why":"电场力做功 W=qE·d∥，只由沿场强方向的位移分量决定，垂直分量不做功；若把 a、b 间总距离当成沿场方向位移，就会算错倍数","do":"把 a→b 位移分解，取沿板间方向（垂直极板）的分量作为有效位移，确认该分量不随板距改变","expr":"W=qE\\,d_{\\parallel}","cues":["只看沿场方向","垂直方向不做功","位移分量"],"concepts":["电场力做功","位移分解"]},{"title":"有效位移不变","type":"临界条件","judge":"板距增大后，a、b 两点沿场强方向的位移分量是否改变","why":"a、b 是板上固定位置的点，其沿极板法向的间距由几何布置决定，不随极板整体外移而变；只有认定 d∥ 不变，功的变化才完全由 E 减半决定","do":"对比移动前后 a、b 沿场方向间距，确认 d∥'=d∥","expr":"d_{\\parallel}'=d_{\\parallel}","cues":["两点没动","沿场间距不变","只有场强变了"],"concepts":["位移","匀强电场"]},{"title":"功与场强同比例","type":"结论整理","judge":"新功 W' 与原来 W 的比值由哪个量决定","why":"d∥ 不变、q 不变，W=qEd∥ 与 E 成正比，E 减半则 W 减半；干扰项错在把 E 当成不变（误以为 U 变或 d 不影响 E）或把 E 当成加倍","do":"用 W'=qE'd∥ 与 W=qEd∥ 相除，得 W'/W=E'/E","expr":"\\frac{W'}{W}=\\frac{E'}{E}=\\frac{1}{2}","cues":["功跟着场强走","减半","和原来比一半"],"concepts":["电场力做功","比例关系"]}],"334":[{"title":"判断释放瞬间是否滑动","type":"前提判断","judge":"释放瞬间弹簧弹力最大，物块与木箱之间是否已经发生相对滑动","why":"题设明确说释放后物块在木箱上有滑动，且滑动摩擦力有限，弹力超过最大静摩擦力时必然相对滑动","do":"比较释放瞬间弹簧弹力与物块和木箱间的最大静摩擦力","expr":"F_{\\text{弹}}>f_{\\max}","cues":["释放瞬间就滑动","弹力最大","静摩擦不够"],"concepts":["最大静摩擦力","相对滑动"]},{"title":"判断共速前摩擦方向","type":"关系建立","judge":"物块与木箱第一次共速之前，物块相对木箱向哪边运动、所受摩擦力朝哪边","why":"木箱受弹簧向右加速，物块靠摩擦力被带动，加速度小于木箱，故物块相对木箱向左滑，摩擦力方向与相对运动方向相反","do":"比较木箱与物块的加速度，确定相对运动方向，再由滑动摩擦力方向与相对运动反向定出物块受力方向","expr":"a_M=\\frac{F-f}{M}>a_m=\\frac{f}{m}","cues":["木箱跑得快","物块相对向左","摩擦力向右"],"concepts":["相对运动","滑动摩擦力方向","牛顿第二定律"]},{"title":"判断摩擦力是否恒定","type":"模型选择","judge":"共速前物块与木箱间的摩擦力是恒定的滑动摩擦力还是随弹力变化的力","why":"只要两者有相对滑动，摩擦力就是滑动摩擦力，大小由动摩擦因数和正压力决定，与弹簧弹力无关","do":"确认共速前始终存在相对滑动，写出滑动摩擦力表达式，判断其是否随弹力变化","expr":"f=\\mu mg","cues":["滑动摩擦不变","只跟正压力有关","共速前一直滑"],"concepts":["滑动摩擦力","动摩擦因数"]},{"title":"判断何时开始共同运动","type":"临界条件","judge":"弹簧弹力减小到什么程度时物块与木箱不再相对滑动、开始一起做简谐运动","why":"当所需共同加速度对应的摩擦力不超过最大静摩擦力时，两者才能保持相对静止","do":"对整体和物块分别列牛顿第二定律，令摩擦力等于最大静摩擦力，解出临界弹力","expr":"F=(M+m)\\frac{f_{\\max}}{m}","cues":["弹力减小到某值","静摩擦够用","之后一起振动"],"concepts":["临界条件","整体法","简谐运动"]},{"title":"判断运动是否会停止","type":"结论整理","judge":"物块最终是否会停下来，还是持续做周期性运动","why":"系统只有弹簧弹力和摩擦力做功，但进入共同振动后无相对滑动、无机械能损失，振动不会停止","do":"分析共速后系统是否还有相对滑动与能量耗散，判断运动能否持续","expr":"","cues":["不会停下","一直振动","没有相对滑动就不耗能"],"concepts":["机械能","简谐运动","能量耗散"]}],"335":[{"title":"装置安装顺序","type":"实验操作","judge":"安装斜槽各步骤的先后顺序，哪一步必须在哪一步之前完成","why":"斜槽必须先固定到底座、再调竖直面内、再调末端水平，最后才能按水平末端的位置装光电门；顺序颠倒则前面调好的状态会被后面操作破坏","do":"按'固定底座→调竖直面→调末端水平→装光电门'排出顺序，与三个选项比对","expr":"","cues":["先固定底座","末端水平最后调","光电门最后装"],"concepts":["实验操作规范","光电门"]},{"title":"卡尺测直径的夹持方式","type":"实验操作","judge":"用游标卡尺测球径时，应让量爪卡住球的哪个部位、以什么姿态夹持","why":"只有量爪与球面垂直接触、卡在球的最大宽度处，读数才是直径；斜夹或未夹住球会得到偏小或错误的读数","do":"比较甲、乙两图量爪与球面的接触位置，选出量爪卡在球最大宽度处的那一幅","expr":"","cues":["卡在最大宽度","量爪要垂直接触","乙图没夹住球"],"concepts":["游标卡尺","测量误差"]},{"title":"重力势能按比例补算","type":"数据处理","judge":"表格最后一格的重力势能减少量该用哪条规律、与表中哪一列数据对应","why":"ΔEp=mgh 与 h 成正比，可直接由已知列按高度倍数外推，避免重复代入出错","do":"用 h=8.00×10⁻² m 与 h=4.00×10⁻² m 的倍数关系，把 7.84×10⁻³ J 乘 2","expr":"$\\Delta E_p = mgh$","cues":["正比于高度","是四厘米那格的两倍","直接乘二"],"concepts":["重力势能","正比关系"]},{"title":"往返过程的功能关系","type":"关系建立","judge":"从 A 释放到最高点 B，摩擦力做的功与 mgH 之间是什么关系","why":"A、B 两点速度均为零，全程动能变化为零，重力做功 mgH 全部被摩擦力做负功消耗","do":"对 A→B 全程用动能定理，初末动能都取零，解出摩擦力做功大小","expr":"$mgH - W_{\\text{理}} = 0$","cues":["首末都静止","动能变化为零","重力功全被摩擦吃掉"],"concepts":["动能定理","摩擦力做功"]},{"title":"判断近似是否成立","type":"前提判断","judge":"ΔE 与 Wf 相差明显，是否真由'W测/2 近似不合理'造成","why":"若只是近似不当，两者应同阶同趋势地接近；而表中 ΔE 约为 Wf 的 2.5～3 倍且随 h 增大差距拉大，说明还有未被计入的能量去向（球的转动动能），不是折半近似的问题","do":"逐行比较 ΔE 与 Wf 的比值及随 h 的变化趋势，判断差异是否能用'取一半'解释","expr":"","cues":["比值约三倍","差距随高度变大","还有转动动能"],"concepts":["误差分析","转动动能","机械能损失"]}],"336":[{"title":"选光电效应方程","type":"模型选择","judge":"判断该用哪个规律把入射光频率、逸出功和光电子动能联系起来","why":"光电效应中电子吸收单个光子能量，能量守恒给出 hν = W₀ + E_k，这是唯一能沟通已知量 W₀、h、ν 与待求量的关系","do":"写出光电效应方程，明确各项分别对应光子能量、逸出功和最大初动能","expr":"h\\nu = W_0 + E_{k}","cues":["用光电效应方程","一个光子对一个电子","能量守恒"],"concepts":["光电效应","光子能量","逸出功"]},{"title":"截止频率的临界条件","type":"临界条件","judge":"判断截止频率对应光电子恰好不能逸出、最大初动能为零这一临界状态","why":"截止频率的定义就是使光电子最大初动能恰为零的入射光频率，只有取 E_k = 0 才能把 ν₀ 从方程中解出","do":"在光电效应方程中令 E_k = 0，把对应的 ν 记为 ν₀ 并解出","expr":"0 = h\\nu_0 - W_0 \\Rightarrow \\nu_0 = \\frac{W_0}{h}","cues":["刚好逸不出","初动能为零","临界频率"],"concepts":["截止频率","临界条件"]},{"title":"最大初动能对应最大动能电子","type":"前提判断","judge":"判断第二问求的是光电子最大初动能，而非某个电子的任意动能","why":"光电效应方程直接给出的是从金属表面逸出、无能量损失的那部分电子的最大初动能，题目问的正是这个量","do":"确认所求为 E_km，直接用方程右端 hν − W₀ 表示，不再另设未知量","expr":"E_{km} = h\\nu - W_0","cues":["求的是最大值","表面电子损失最小","直接用方程"],"concepts":["最大初动能","光电效应方程"]},{"title":"发生光电效应的频率条件","type":"前提判断","judge":"判断入射光频率 ν 与截止频率 ν₀ 的大小关系是否满足发生光电效应的条件","why":"只有 ν > ν₀（即 hν > W₀）时才有光电子逸出，E_km 才为正；这是题目所说“能使金属发生光电效应”的含义","do":"比较 ν 与 W₀/h，确认 hν − W₀ > 0，保证结果物理上合理","expr":"\\nu > \\nu_0 = \\frac{W_0}{h}","cues":["频率要够大","超过截止频率","动能不能为负"],"concepts":["极限频率","逸出条件"]}],"337":[{"title":"两粒子抛射方向判定","type":"图像读取","judge":"要判断 a、b 两粒子的初速度方向分别是斜向上还是斜向下（即两粒子是否沿同一竖直线的两侧对称抛出）","why":"题给两粒子速度方向与水平方向夹角均为 θ，但图中 a 斜向上、b 斜向下，只有确认这一点才能确定竖直分速度的正负与后续位移的叠加方式","do":"读图确认 a 的竖直分速度向上、b 的竖直分速度向下，写出两者竖直分速度大小均为 v₀sinθ、水平分速度均为 v₀cosθ","expr":"v_{ay}=+v_0\\sin\\theta,\\quad v_{by}=-v_0\\sin\\theta,\\quad v_{ax}=v_{bx}=v_0\\cos\\theta","cues":["一个上一个下","看图定方向","斜上抛和斜下抛"],"concepts":["运动的分解","斜抛运动"]},{"title":"忽略重力只受电场力","type":"前提判断","judge":"要判断粒子在竖直方向所受合力是否只有电场力 qE，从而加速度是否恒为 qE/m 且方向竖直向下","why":"题目明确不计重力及粒子间相互作用，若误把重力计入或漏掉电场力方向，加速度大小和方向都会错","do":"对单个粒子受力分析，确认竖直方向仅受竖直向下的电场力，由牛顿第二定律得加速度","expr":"qE=ma\\Rightarrow a=\\frac{qE}{m}","cues":["不计重力","只受电场力","加速度向下"],"concepts":["牛顿第二定律","匀强电场"]},{"title":"最高点的临界条件","type":"临界条件","judge":"要判断 a 到达最高点时其竖直分速度恰好减为零，而不是位移为零或速度为零","why":"最高点是竖直方向速度反向的临界点，只有取 v_y=0 才能把时间 t 与初速度、加速度联系起来","do":"对 a 的竖直分运动用速度公式，令末速度为零，解出上升时间","expr":"v_0\\sin\\theta=at\\Rightarrow t=\\frac{mv_0\\sin\\theta}{qE}","cues":["最高点竖直速度为零","速度减到零","用速度公式"],"concepts":["匀变速直线运动","临界条件"]},{"title":"水平方向同竖直线判断","type":"关系建立","judge":"要判断两粒子水平分速度相同，因而始终处于同一竖直线上，距离只由竖直方向位移差决定","why":"两粒子水平初速度均为 v₀cosθ 且水平方向不受力，水平位移时刻相等，故 a、b 间距就是竖直方向的位置差","do":"比较两粒子水平分速度，确认水平位移相同，把求距离的问题化为求竖直方向位移之差","expr":"x_a^{水平}=x_b^{水平}=v_0\\cos\\theta\\cdot t","cues":["水平速度一样","一直在同一竖直线","只算竖直距离"],"concepts":["运动的独立性","匀速直线运动"]},{"title":"竖直位移差的计算","type":"数学处理","judge":"要判断 a 到最高点时 b 已从 O 点向下运动了同样长的时间 t，需把 a 的上升位移与 b 的下降位移相加","why":"a 在 O 点上方、b 在 O 点下方，两者分处 O 点两侧，间距等于各自到 O 点竖直距离之和而非之差","do":"分别写出 a 的竖直位移（匀减速到零）与 b 的竖直位移（初速向下、加速度向下），取两者大小之和","expr":"H=\\frac{(v_0\\sin\\theta)^2}{2a}+\\left(v_0\\sin\\theta\\,t+\\frac12 at^2\\right)","cues":["一个在上一个在下","位移要相加","别相减"],"concepts":["匀变速直线运动","位移公式"]},{"title":"换参考系简化求距离","type":"模型选择","judge":"要判断能否以 a 为参考系，把 b 相对 a 的运动看成竖直方向的匀速直线运动","why":"两粒子加速度相同（同为 qE/m 向下），相对加速度为零，相对速度恒为 2v₀sinθ，用相对运动可避开分别求位移再叠加","do":"取 a 为参考系，求 b 相对 a 的初速度，用匀速运动公式乘时间 t 得间距","expr":"H=2v_0\\sin\\theta\\cdot t=\\frac{2mv_0^2\\sin^2\\theta}{qE}","cues":["取a为参考系","相对加速度为零","相对匀速"],"concepts":["相对运动","参考系"]}],"338":[{"title":"等质量弹性碰撞速度互换","type":"模型选择","judge":"质量相等的两球发生弹性正碰时，能否直接判定二者速度互换而不必解方程组","why":"动量守恒与动能守恒联立后，等质量弹性碰撞的解唯一为交换速度，这是可整体调用的结论","do":"比较玻璃球与钢球质量是否相等，相等则把入射球速度直接传给被碰球","expr":"m_1=m_2 \\Rightarrow v_1'=v_2,\\ v_2'=v_1","cues":["质量相等","速度互换","不用解方程"],"concepts":["弹性碰撞","速度交换","动量守恒"]},{"title":"碰撞后速度方向定正负","type":"关系建立","judge":"碰后玻璃球速度的正负号表示什么，题目要的是速度还是速率","why":"一维弹性碰撞公式给出的是带符号的代数量，负号只表示反向，而第（2）问求的是速度大小","do":"用一维弹性碰撞公式算出带符号的碰后速度，再取绝对值作为速度大小","expr":"v_1=\\frac{m-3m}{m+3m}v_0=-\\frac{v_0}{2},\\quad |v_1|=\\frac{v_0}{2}","cues":["负号是反向","取绝对值","大小不看符号"],"concepts":["一维弹性碰撞","速度方向","速率"]},{"title":"钢球间碰撞只传不反弹","type":"模型选择","judge":"被撞钢球再与同列下一个等质量钢球碰撞时，玻璃球是否参与、能量是否继续留在钢球列中","why":"同列钢球质量相同，弹性碰撞只把速度依次传递，最后只有最右端钢球以该速度飞出，中间球静止","do":"把同列钢球看成一串等质量弹性碰撞链，判断速度被完整传到列端，玻璃球不再受影响","expr":"v_{\\text{端}}=v_{\\text{首碰后}}","cues":["同列等质量","速度传下去","中间球停下"],"concepts":["弹性碰撞链","速度传递"]},{"title":"每次往返速度减半的递推","type":"关系建立","judge":"玻璃球每与一个 3m 钢球碰撞一次，其速率按什么比例衰减，往返一次算几次碰撞","why":"与 3m 球弹性碰撞的速度系数恒为 (m-3m)/(m+3m)，与入射速率无关，故可逐次相乘","do":"写出单次碰撞的速率比例因子，数清左右往返各算一次碰撞，累计 2n 次","expr":"v_{k}=\\left|\\frac{m-3m}{m+3m}\\right|v_{k-1}=\\frac{1}{2}v_{k-1}","cues":["每次减半","左右各碰一次","比例固定"],"concepts":["弹性碰撞","等比递推","速率衰减"]},{"title":"碰撞次数与指数对应","type":"数学处理","judge":"2n 次碰撞后速率因子是 1/2 的多少次方，动能中又该如何平方","why":"速率每碰一次乘 1/2，动能正比于速率平方，指数要翻倍，容易少算或错算指数","do":"先写速率 v=(1/2)^{2n}v_0，再平方代入动能公式化简指数","expr":"E_k=\\frac{1}{2}m\\left[\\left(\\frac{1}{2}\\right)^{2n}v_0\\right]^2=\\left(\\frac{1}{2}\\right)^{4n+1}mv_0^2","cues":["指数要平方","动能看速率平方","别漏二分之一"],"concepts":["动能","指数运算","等比数列"]}],"339":[{"title":"切割速度的确定","type":"关系建立","judge":"ab 边切割磁感线的速度该用哪个半径和哪个角速度来算","why":"ab 边位于外转子上，随外转子绕轴做圆周运动，线速度由外转子半径与角速度决定","do":"写出 ab 边做圆周运动的线速度，再代入动生电动势公式","expr":"v=\\omega_{0}r_{1},\\quad E_{1}=BLv","cues":["用外转子半径","切割速度的确定","动生电动势","线速度"],"concepts":["动生电动势","线速度"]},{"title":"两直边电动势叠加","type":"模型选择","judge":"线圈 abcd 的总电动势是只算 ab 边，还是要把 ab、cd 两边一起算并判断方向","why":"ab、cd 都在磁场中切割磁感线，两边运动方向相反、所在处磁场方向也相反，需判断两边电动势是相加还是相消","do":"比较 ab、cd 两边产生的电动势方向，确认沿线圈回路同向叠加","expr":"E_{2}=2BL\\omega_{0}r_{1}","cues":["两边都切割","方向相反要叠加","总电动势翻倍"],"concepts":["法拉第电磁感应定律","电动势方向"]},{"title":"热量用有效电流算","type":"关系建立","judge":"求一周焦耳热时用哪段电流、哪段时间，是否要考虑电流方向变化","why":"电流方向变化不改变焦耳热，热量只由电流大小和通电时间决定，一周时间由外转子角速度给出","do":"用总电动势除以回路电阻得电流，再乘以外转子转动一周的时间求热量","expr":"I=\\frac{2BL\\omega_{0}r_{1}}{R},\\quad T_{0}=\\frac{2\\pi}{\\omega_{0}},\\quad Q=I^{2}RT_{0}","cues":["方向变不影响发热","用一周时间","电流大小不变"],"concepts":["焦耳定律","周期"]},{"title":"相对速度决定电动势","type":"前提判断","judge":"内转子也转动后，感应电动势由外转子的绝对速度还是内外转子的相对速度决定","why":"磁场由内转子磁体产生并随内转子一起转动，线圈切割磁感线的有效速度是线圈相对磁场的速度","do":"写出线圈相对磁场的速度差，用相对速度代替原线速度重写电动势","expr":"E'=2BL\\Delta v=IR","cues":["磁场跟着内转子转","用相对速度","不能再用外转子速度"],"concepts":["相对速度","动生电动势"]},{"title":"电流换向的临界位置","type":"临界条件","judge":"线圈中电流方向在转子转到什么位置时改变，换向间隔对应多少圆心角","why":"磁场沿径向且由四个磁体分区，线圈经过磁极分界处时穿过它的磁场方向反转，电流随之反向","do":"找出相邻两次磁场反向之间线圈转过的角度，结合相对速度求时间间隔","expr":"t=\\frac{\\frac{1}{4}\\cdot2\\pi r_{1}}{\\Delta v}","cues":["过磁极分界换向","四分之一圈换一次","用相对速度算时间"],"concepts":["磁极分界","电流换向"]},{"title":"电流周期与换向间隔","type":"结论整理","judge":"电流的周期是相邻两次同向之间的时间，还是相邻两次换向之间的时间","why":"电流周期定义为完成一次完整变化（同向到同向）所需时间，等于两次换向间隔的两倍","do":"把换向间隔乘以二得到电流周期","expr":"T=2t=\\frac{2\\pi BLr_{1}}{IR}","cues":["周期是两次换向的两倍","同向到同向","别把间隔当周期"],"concepts":["周期","交变电流"]}],"340":[{"title":"识别充电过程","type":"前提判断","judge":"要判断超级电容器储存能量时处于充电还是放电状态","why":"储存能量意味着电源向电容器输入电能，极板电荷量应增加，这是后续判断 Q、U 变化方向的前提","do":"由“储存能量”这一题设条件，确定电容器处于充电过程","expr":"","cues":["储存就是充电","电荷量在增加","能量变多"],"concepts":["充电过程","电荷量"]},{"title":"电容由结构决定","type":"前提判断","judge":"要判断充电过程中电容 C 是否随 Q、U 改变","why":"电容由极板结构、介质等自身因素决定，题目未提及结构变化，故 C 视为定值，这是 Q 与 U 成正比的条件","do":"确认题目没有给出电容变化的信息，把 C 当作常量处理","expr":"C=\\dfrac{Q}{U}=\\text{常量}","cues":["电容不变","结构没变","C是定值"],"concepts":["电容","决定式"]},{"title":"建立 Q 与 U 的正比关系","type":"关系建立","judge":"要判断 Q 增大时 U 如何变化","why":"由 Q=CU 且 C 不变，Q 与 U 成正比，Q 增大必然对应 U 增大","do":"用 Q=CU 把 Q 的增大趋势传递到 U 上，得出两者同向增大","expr":"Q=CU\\Rightarrow U=\\dfrac{Q}{C}","cues":["成正比","一起增大","电压跟着涨"],"concepts":["电容定义式","正比关系"]}],"341":[{"title":"判定Ⅱ轨道机械能守恒","type":"前提判断","judge":"飞船在椭圆轨道Ⅱ上从P到Q的过程中，除万有引力外是否还有其他力做功","why":"题设明确不计阻力，飞船只受万有引力，而万有引力属于保守力，因此机械能守恒；若误认为有阻力或发动机做功，就会得出机械能变化的错误结论","do":"对飞船在Ⅱ轨道上的受力分析，确认只有中心天体的万有引力，无发动机推力、无空气阻力","expr":"","cues":["只有万有引力","不计阻力","机械能不变"],"concepts":["机械能守恒","万有引力","保守力"]},{"title":"判断引力做功正负","type":"关系建立","judge":"从近地点P向远地点Q运动时，万有引力方向与速度方向夹角是锐角还是钝角，引力做正功还是负功","why":"P为近地点、Q为远地点，飞船从P到Q离中心天体越来越远，引力指向中心而位移有远离中心的分量，故引力做负功，这是判断动能如何变化的关键","do":"比较P、Q到中心天体的距离，判断飞船径向运动方向，再结合引力方向确定功的正负","expr":"","cues":["离地球越来越远","引力指向地心","引力做负功"],"concepts":["功的正负","万有引力","径向运动"]},{"title":"由做功推速率变化","type":"结论整理","judge":"引力做负功时动能（速率）应增大还是减小","why":"由动能定理，合外力做负功则动能减小；机械能守恒时引力做负功必然对应动能减少、势能增加，故速率减小","do":"对P到Q过程用动能定理或机械能守恒，比较P、Q两点的速率大小","expr":"W_引=ΔE_k<0 ⇒ v_Q<v_P","cues":["动能减小","速率变小","远地点慢"],"concepts":["动能定理","动能","速率"]}],"342":[{"title":"识别图像为线性关系","type":"图像读取","judge":"要判断 U-n 图像是过原点的直线，从而 U 与 n 成正比","why":"理想变压器电压比等于匝数比，U=(U1/n1)n，U 与 n 成正比，图像才是一条过原点的直线","do":"观察图像是否为过原点的直线，确认正比关系成立","expr":"U=\\frac{U_1}{n_1}n","cues":["过原点直线","正比关系","电压跟匝数成正比"],"concepts":["理想变压器","电压比等于匝数比"]},{"title":"取图线上一点读数","type":"图像读取","judge":"要在图线上选一个坐标好读的点（如 U=3 V 对应 n=70），而不是随便估读","why":"图线是实验数据拟合出的直线，取格点交点读数误差最小，才能得到接近整数的原线圈匝数","do":"在直线上找与网格线交点重合的点，读出对应的 U 和 n","expr":"","cues":["找格点交点","读3伏对应70匝","别在中间瞎估"],"concepts":["图像读数","坐标点"]},{"title":"用匝数比公式反解","type":"关系建立","judge":"要判断用 n1/n=U1/U 直接反解 n1，而不是用电流或功率关系","why":"原线圈电压 9 V 已知、副线圈电压 U 与匝数 n 已知，只有匝数比公式把这三个量与未知的 n1 联系起来","do":"把读出的 (U,n) 与 U1=9 V 代入匝数比公式解出 n1","expr":"n_1=\\frac{U_1}{U}n","cues":["用匝数比","电压比等于匝数比","不用电流关系"],"concepts":["匝数比","理想变压器"]},{"title":"区分原副线圈电压","type":"前提判断","judge":"要判断 9 V 是加在原线圈上的 U1，图中 U 是副线圈电压，两者不能混用","why":"题设明确 9 V 输入原线圈，图像纵轴是副线圈两端电压，若把 9 V 当成 U 代入会得到错误匝数","do":"确认公式中 U1=9 V、U 取图像读数，各归其位","expr":"\\frac{n_1}{n}=\\frac{U_1}{U},\\quad U_1=9\\,\\mathrm{V}","cues":["9伏是原线圈的","图上是副线圈电压","别把两个电压搞反"],"concepts":["原线圈","副线圈","输入电压"]}],"343":[{"title":"竖直方向定时间","type":"模型选择","judge":"小球竖直方向做什么运动、下落高度取多少","why":"平抛竖直分运动为自由落体，下落高度是抛出点与接球点的高度差 H−h，与水平运动无关","do":"对竖直方向列自由落体方程，求出球在空中飞行的时间 t","expr":"H-h=\\frac{1}{2}gt^{2}","cues":["竖直自由落体","高度差是H减h","先求时间"],"concepts":["平抛运动","自由落体","运动的独立性"]},{"title":"水平方向追及关系","type":"关系建立","judge":"水平方向上球与小孩的位移如何凑成初始距离 l","why":"球向右、小孩向左相向运动，两者水平位移之和才等于初始水平距离 l，而不是某一方的位移等于 l","do":"把球的水平位移 v1t 与小孩的位移 v2t 相加，令其等于 l","expr":"l=v_{1}t+v_{2}t","cues":["相向运动","位移相加","不是相减"],"concepts":["匀速直线运动","追及相遇","位移关系"]},{"title":"联立消元求初速","type":"数学处理","judge":"用哪个量作桥梁把两个方程合成只含 v1 的式子","why":"t 是竖直方向与水平方向共有的物理量，先由竖直方程解出 t 再代入水平方程","do":"由竖直方程得 t，代入水平关系解出 v1","expr":"v_{1}=\\frac{l}{t}-v_{2}=l\\sqrt{\\frac{g}{2(H-h)}}-v_{2}","cues":["消去时间","先解t再代入","减去小孩速度"],"concepts":["方程联立","平抛运动"]}],"344":[{"title":"确定CS线圈磁场方向","type":"前提判断","judge":"CS 线圈中电流方向与它产生的磁场方向（沿中心柱轴向）的对应关系","why":"等离子体电流由 CS 线圈磁场变化感应而生，磁场方向判错则后续感应电场方向全反；需用右手螺旋定则把图(b)的电流方向映射为轴向磁场方向","do":"由图(b)读出初始阶段电流的正负与增减，用右手螺旋定则判断线圈内部磁场的 N/S 极分布","expr":"","cues":["右手螺旋定则","看电流正负","磁场沿轴向"],"concepts":["安培定则","磁场方向"]},{"title":"判断磁通量增减","type":"关系建立","judge":"穿过等离子体环所围截面的磁通量是增大还是减小","why":"楞次定律的结论取决于磁通量的变化趋势而非磁场本身方向，图(b)中电流先减小后反向增大，两阶段磁通量都在同方向变化","do":"比较图(b)中相邻时刻电流大小，判断穿过环面的磁通量增减趋势","expr":"","cues":["电流在减小","磁通量在变","分两个阶段"],"concepts":["磁通量","楞次定律"]},{"title":"用楞次定律定感应电场","type":"关系建立","judge":"感应电场（俯视）的环绕方向","why":"感应电场方向由楞次定律决定：要阻碍原磁通量的变化，磁场方向与增减趋势任一判错都会使结果反向","do":"由原磁场方向和磁通量增减，按“增反减同”定出感应磁场方向，再用右手螺旋定则得感应电场环绕方向","expr":"","cues":["增反减同","阻碍变化","顺时针还是逆时针"],"concepts":["楞次定律","感应电场"]},{"title":"电子离子受力与电流方向","type":"模型选择","judge":"等离子体中电子和离子的受力方向如何合成宏观电流方向","why":"等离子体含正负两种电荷，感应电场对二者的作用力方向相反，但形成的等效电流方向由正电荷受力方向（即电场方向）决定，不能只看电子","do":"由感应电场方向确定正离子受力方向，即得等离子体电流的环绕方向","expr":"","cues":["正负电荷都动","看正电荷","电流方向跟电场"],"concepts":["洛伦兹力","电流方向"]},{"title":"两阶段结论一致性","type":"结论整理","judge":"电流减小阶段与反向增大阶段得到的电流方向是否相同","why":"图(b)中电流先正向减小、后反向增大，两种变化对磁通量的效果等效，若只算第一阶段会漏掉验证","do":"对反向增大阶段重复磁通量变化与楞次定律判断，与第一阶段结果比对","expr":"","cues":["两段等效","再算一遍","方向一样吗"],"concepts":["楞次定律","等效变化"]}],"345":[{"title":"确定研究对象与初态","type":"模型选择","judge":"把桶内原有空气和压入的空气合为研究对象，判断初态总体积与压强","why":"两部分气体最终混合在同一容器内，只有取整体才能用一个玻意耳定律方程联系初末态","do":"写出初态：桶内空气体积为桶身容积、压强为大气压，压入空气体积为待求量、压强也为大气压","expr":"p_0 SH+p_0 V_{0c}=pSH","cues":["取整体","把压入的气也算进去","初态两部分"],"concepts":["玻意耳定律","研究对象选取"]},{"title":"末态体积取桶身容积","type":"前提判断","judge":"判断末态气体占据的体积是桶身容积还是桶身加颈部容积","why":"题设忽略颈部体积，气体只充满桶身部分，颈部不计入气体体积","do":"末态体积取 SH，不把颈部高度 l 计入体积","expr":"V末=SH","cues":["颈部不算体积","忽略颈部","只算桶身"],"concepts":["气体体积","理想气体状态方程"]},{"title":"恰能出水的压强条件","type":"临界条件","judge":"判断桶内压强至少要多大水才能被压到颈部顶端出口","why":"出水口在颈部顶端，水需被压到高出桶身液面 H 再加颈部 l 的高度，静水压强差由气体压强提供","do":"列出临界压强等于大气压加上高为 H+l 的水柱压强","expr":"p=p_0+\\rho g(H+l)","cues":["要压到瓶口","高度是桶高加颈高","恰能出水取等号"],"concepts":["液体静压强","临界条件"]},{"title":"液面最低的含义","type":"前提判断","judge":"判断液面最低时桶内水最少、气体空间最大，对应最难出水的设计工况","why":"气体空间越大，同样压入空气后压强升高越少，液面最低是最不利情形，临界值须按此设计","do":"取桶内水面在桶底、气体占满整个桶身容积作为设计工况","expr":"","cues":["液面最低最难压","水最少气最多","按最不利情况设计"],"concepts":["临界工况","气体体积"]},{"title":"联立消去中间压强","type":"数学处理","judge":"判断中间量 p 不必求出，直接由两式消去得到 V0c","why":"p 只是过渡量，题目只问 V0c，消去 p 可避免多算一个未知数","do":"把压强表达式代入玻意耳方程，解出 V0c 并整理成因式形式","expr":"V_{0c}=\\frac{\\rho gS}{p_0}H(H+l)","cues":["消去压强","直接解体积","整理成乘积"],"concepts":["方程联立","代数整理"]}],"346":[{"title":"轮轨接触半径随横移变化","type":"几何关系","judge":"横移后内外轮与铁轨接触处的半径如何随偏移量变化","why":"轮子是锥台形，横向偏移使接触点沿锥面移动，接触半径改变；这是打滑与否的根源","do":"把锥台半顶角与横移量联系，写出外轮半径增大、内轮半径减小的表达式","expr":"2r_1=D+2\\Delta x\\tan\\frac{\\theta}{2},\\quad 2r_2=D-2\\Delta x\\tan\\frac{\\theta}{2}","cues":["锥面接触","半径变大变小","横移改变半径"],"concepts":["锥台几何","接触半径"]},{"title":"小角近似化简","type":"近似条件","judge":"能否用半顶角近似代替正切值","why":"题设给出 θ 很小，tanθ≈sinθ≈θ，必须把半角的正切化为 θ/2 才能得到选项形式","do":"对 tan(θ/2) 作小角近似，把半径差写成含 θΔx 的形式","expr":"\\tan\\frac{\\theta}{2}\\approx\\frac{\\theta}{2}\\Rightarrow r_1-r_2\\approx\\theta\\Delta x","cues":["θ很小","半角近似","化到θ"],"concepts":["小角近似"]},{"title":"纯滚动决定路程比","type":"关系建立","judge":"两轮固定同转时，各自前进路程与接触半径成什么比例","why":"两轮固连角速度相同且不打滑，轮缘走过的弧长正比于接触半径","do":"由同一转角下弧长等于半径乘转角，写出内外轮路程之比等于半径之比","expr":"\\frac{s_1}{s_2}=\\frac{r_1}{r_2}","cues":["同轴同转角","不打滑","弧长比"],"concepts":["纯滚动","角速度相同"]},{"title":"路程比对应轨道半径比","type":"几何关系","judge":"内外轮走过的路程之比对应弯道上哪两个半径之比","why":"过弯时内外轮分别沿半径 R+L/2 与 R−L/2 的圆弧运动，弧长比即半径比","do":"由俯视图写出内外轨迹半径，取比值与路程比相等","expr":"\\frac{s_1}{s_2}=\\frac{R+\\frac{L}{2}}{R-\\frac{L}{2}}","cues":["内外轨迹半径","俯视图","加半轨距减半轨距"],"concepts":["圆周运动","轨迹半径"]},{"title":"联立求最小半径","type":"数学处理","judge":"把半径比与轨迹半径比联立后解出 R，并判断 R 与 Δx 的单调关系","why":"不打滑条件给出等式，横向偏移取最大值 Δx 时对应最小过弯半径","do":"令两比值相等，解出 R 关于 L、D、θ、Δx 的表达式","expr":"\\frac{D+\\theta\\Delta x}{D-\\theta\\Delta x}=\\frac{R+\\frac{L}{2}}{R-\\frac{L}{2}}\\Rightarrow R=\\frac{LD}{2\\theta\\Delta x}","cues":["两比相等","解出R","偏移取最大"],"concepts":["联立方程","临界偏移"]}],"347":[{"title":"电子受洛伦兹力方向","type":"前提判断","judge":"棒向右运动时，棒内自由电子随棒一起向右运动，所受洛伦兹力沿棒还是垂直于棒","why":"电子速度方向与磁场垂直，用左手定则（电子带负电，四指指运动反方向）判断洛伦兹力方向，这是判断电子是否沿棒运动的前提","do":"取电子为对象，速度向右、磁场向里，用左手定则定出洛伦兹力方向，看它是否沿棒方向","expr":"\\vec F=q\\vec v\\times\\vec B","cues":["电子带负电","四指指反方向","力垂直棒"],"concepts":["洛伦兹力","左手定则"]},{"title":"判断两端电势高低","type":"关系建立","judge":"棒切割磁感线时，哪一端电势高","why":"棒在磁场中向右运动切割磁感线，相当于电源，由右手定则（或洛伦兹力驱动正电荷的方向）确定正电荷聚集端为高电势端","do":"用右手定则：磁感线穿掌心、拇指指运动方向，四指指向高电势端，比较 P、Q 两端","expr":"","cues":["右手定则","切割磁感线","哪端是正极"],"concepts":["动生电动势","右手定则"]},{"title":"电动势与场强的关系","type":"关系建立","judge":"棒两端电势差与棒内匀强电场、棒长的定量关系","why":"棒内电子最终沿棒方向受力平衡，电场力与洛伦兹力沿棒分量平衡，故 U=BLv，再由 E=U/L 得 E=Bv","do":"写出 U=BLv，除以棒长 L 得 E=Bv，据此判断 v 增大时 E 如何变化","expr":"U=BLv,\\quad E=\\frac{U}{L}=Bv","cues":["电势差等于电动势","场强等于电压除长度","场强跟速度成正比"],"concepts":["动生电动势","匀强电场"]},{"title":"加速时场强变化","type":"结论整理","judge":"棒加速运动时，棒内电场强度是否变化、如何变化","why":"由 E=Bv 知 E 随 v 变化，加速则 v 增大，E 必增大，不能把 U 当作恒定值","do":"比较加速前后 v 的大小，由 E=Bv 判断 E 增大","expr":"E=Bv","cues":["速度在变大","场强跟着变大","不能当恒定"],"concepts":["动生电动势","电场强度"]},{"title":"匀速时电子是否定向移动","type":"临界条件","judge":"棒匀速运动时，电子是否持续沿棒定向移动形成电流","why":"稳定后电子沿棒方向所受洛伦兹力分量与电场力平衡，电子相对棒不再定向移动，两端电势差恒定","do":"对电子沿棒方向列力平衡，判断其相对棒的定向速度是否为零","expr":"eE=evB","cues":["最终相对静止","力平衡了","不再有电流"],"concepts":["洛伦兹力","力平衡"]}],"348":[{"title":"判断线框相对传送带的运动方向","type":"前提判断","judge":"线框进入磁场时，安培力与重力分力、摩擦力的合力方向如何，线框相对传送带向上还是向下滑动","why":"安培力大于 2mg sinθ，而 μ=tanθ 使最大静摩擦力恰等于 mg sinθ，安培力超过重力分力与最大静摩擦力之和，线框必相对传送带向上滑动，摩擦力方向沿传送带向下","do":"比较安培力 BLI 与 mg sinθ+μmg cosθ 的大小，确定滑动摩擦力方向","expr":"BIL>2mg\\sin\\theta=mg\\sin\\theta+\\mu mg\\cos\\theta","cues":["安培力比下滑力大","摩擦力朝下","相对传送带向上滑"],"concepts":["安培力","最大静摩擦力","相对运动"]},{"title":"分段判断加速度与速度极值","type":"模型选择","judge":"线框穿过磁场的全过程应分成哪几段，每段受哪些力、加速度方向如何，速度在哪一时刻取极小值","why":"只有 ef 边在磁场中时有安培力做负功使线框减速；两边都在磁场中时磁通量不变无安培力，线框在重力分力与向下摩擦力共同作用下匀加速；ef 边出磁场后同理加速，故 gh 边刚进入磁场时速度最小","do":"按 ef 进入、gh 进入、ef 离开、gh 离开四个时刻分段，写出无安培力段的牛顿第二定律","expr":"mg\\sin\\theta+\\mu mg\\cos\\theta=ma","cues":["先减速后加速","速度最小在中间"],"concepts":["分段受力分析","牛顿第二定律","磁通量不变"]},{"title":"用速度位移关系求最小速度","type":"关系建立","judge":"从最小速度加速到 v0 所经过的位移是 d−l 还是别的量","why":"gh 边刚进入磁场时速度最小，此后到 ef 边刚离开磁场，线框整体沿传送带移动的距离为 d−l，且该段加速度恒为 2g sinθ","do":"对加速段列速度位移公式，解出最小速度","expr":"v_0^2-v_{\\min}^2=2a(d-l),\\ a=2g\\sin\\theta","cues":["位移是d减l","加速度是2gsinθ","从最小速度到v0"],"concepts":["匀变速直线运动","速度位移公式"]},{"title":"用动量定理求安培力冲量","type":"关系建立","judge":"有安培力的减速段中，安培力的冲量能否用 ΣBILΔt 与电量关联，从而绕开变力积分","why":"安培力随速度变化，不能直接用匀变速公式，但 ΣBILΔt=B L q，而 q=ΔΦ/R=Bl²/R，可把变力冲量化为磁通量变化","do":"对 ef 进入至 gh 进入这一段列动量定理，把安培力冲量写成 B²l³/R","expr":"\\sum BIL\\Delta t=\\frac{B^2l^3}{R}","cues":["安培力是变力","用冲量不用功"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"用能量守恒求焦耳热","type":"关系建立","judge":"减速段产生的焦耳热能否由动能定理中重力与摩擦力做功之和反推，且四段过程焦耳热是否对称相等","why":"安培力做功全部转化为焦耳热，减速段与 ef 离开后的减速段磁通量变化相同、速度变化相同，故两段焦耳热相等，总热量为单段的二倍","do":"对减速段列动能定理求 W安，取负号得 Q，再乘 2","expr":"Q=-W_{\\text{安}}=2mgd\\sin\\theta,\\ Q_{\\text{总}}=4mgd\\sin\\theta","cues":["安培力做功等于发热","两段减速对称","热量要乘二"],"concepts":["动能定理","焦耳热","功能关系"]},{"title":"用平均速度求传送带位移","type":"数学处理","judge":"ef 边从进入到离开的总时间能否拆成减速段与加速段分别求，传送带位移是否等于 v0 乘总时间","why":"传送带匀速，其位移只由总时间决定；减速段时间由动量定理给出，加速段时间由速度变化除以加速度给出，两段相加即总时间","do":"分别求 t1 与 t2 后相加，再乘 v0","expr":"s=v_0(t_1+t_2)=\\frac{B^2l^3v_0}{2mgR\\sin\\theta}","cues":["传送带匀速","时间分两段算","位移等于速度乘时间"],"concepts":["匀速运动","运动学时间"]}],"349":[{"title":"判断哪个光电门位置不当","type":"前提判断","judge":"两个光电门中哪一个离释放点太近、导致测速误差偏大","why":"遮光片通过光电门的时间越短、速度越小，用平均速度代替瞬时速度的相对误差越大；靠近释放点的光电门处滑块速度小","do":"比较两光电门到释放点的距离，找出速度较小、遮光时间较长的那一个，并说明应向远离释放点方向移动","expr":"","cues":["离释放点太近","速度太小误差大","往右挪一点"],"concepts":["瞬时速度近似","平均速度","实验误差"]},{"title":"用遮光时间求瞬时速度","type":"关系建立","judge":"把遮光片宽度除以遮光时间当作滑块经过光电门的瞬时速度","why":"遮光片宽度足够窄时，通过光电门的平均速度可近似为该位置的瞬时速度","do":"从表格中取 L=65.00 cm 对应的 Δt₂，用 d 除以 Δt₂ 并统一为国际单位","expr":"v_2=\\frac{d}{\\Delta t_2}","cues":["宽度除以时间","遮光片很窄","换成米和秒"],"concepts":["瞬时速度","极限思想"]},{"title":"由倾角换算下降高度","type":"几何关系","judge":"两光电门间沿导轨的距离 L 与竖直下降高度 H_L 的正弦关系","why":"导轨倾斜角 θ 已知，沿斜面距离与竖直高度构成直角三角形","do":"用 L 乘以 sinθ，注意 L 用 cm 时结果也是 cm","expr":"H_L=L\\sin\\theta","cues":["沿斜面距离乘正弦","高度是竖直的","别用余弦"],"concepts":["斜面几何关系","高度差"]},{"title":"把守恒检验化为线性关系","type":"模型选择","judge":"应检验 Δv² 与 H_L 是否成正比（斜率是否为 2g），而不是直接比较动能和势能的具体数值","why":"由机械能守恒有 ½v₂²−½v₁²=gH_L，即 Δv²=2gH_L，是过原点的直线关系","do":"写出 Δv²=2gH_L，明确图线应为过原点直线、斜率等于 2g","expr":"\\Delta v^{2}=2gH_L","cues":["化曲为直","看斜率是不是二倍g","过原点的直线"],"concepts":["机械能守恒","线性化","图像法"]},{"title":"读图求斜率并与 2g 比较","type":"图像读取","judge":"从图(b)取两点算斜率，判断其是否在误差范围内等于 2g","why":"只有斜率等于 2g 才说明动能增量等于重力势能减少量，机械能守恒","do":"在直线上取相距较远的两点读坐标，算 k=Δ(Δv²)/ΔH_L，与 2×9.80 m/s² 比较","expr":"k=\\frac{\\Delta(\\Delta v^{2})}{\\Delta H_L}\\approx 2g","cues":["取两点算斜率","斜率约十九点六","和十九点六比"],"concepts":["图像斜率","重力加速度","误差范围内成立"]}],"350":[{"title":"分压关系式推导","type":"关系建立","judge":"电压表测的是热敏电阻两端电压还是匹配电阻两端电压，据此确定分压对象","why":"电压表并联在 R_T 两端，串联电路中电压按电阻正比分配，须用闭合电路欧姆定律先求电流再乘 R_T","do":"写出回路电流 I=E/(R_T+R_0)，再取 U_out=I·R_T","expr":"U_{\\text{out}}=\\frac{R_T}{R_T+R_0}E","cues":["电压表接在热敏电阻上","先求电流再乘电阻","串联分压"],"concepts":["闭合电路欧姆定律","串联分压"]},{"title":"灵敏度看曲线陡缓","type":"图像读取","judge":"比较不同 R_0 对应图线时，应看同一 R_1 区间内 U_out 的变化幅度（曲线陡峭程度），而不是看 U_out 的绝对大小","why":"传感器灵敏度指单位电阻变化引起的输出变化，即图线斜率大小，斜率大则响应更灵敏","do":"在图(b)中取热敏电阻实际阻值范围（10 kΩ 到 0.5 kΩ）对应的横轴区间，比较各图线在该区间的电压变化量","expr":"","cues":["看曲线陡不陡","比电压变化范围","不看电压高低"],"concepts":["灵敏度","伏安特性曲线","斜率"]},{"title":"匹配阻值取中间值","type":"前提判断","judge":"R_0 应取与热敏电阻工作区间阻值相当的量级，使分压在 R_T 大范围变化时都有明显响应","why":"R_0 过大或过小都会使 U_out 在某一端趋于饱和，只有与 R_T 变化区间匹配时输出变化才最宽","do":"对照热敏电阻 10 kΩ→0.5 kΩ 的变化范围，判断哪条图线对应的 R_0 落在该量级","expr":"","cues":["取中间量级","别太大也别太小","和热敏电阻差不多"],"concepts":["匹配电阻","分压电路"]},{"title":"绝对误差取绝对值比较","type":"数据处理","judge":"比较误差大小时应对 ΔT 取绝对值，不能只看代数值的正负","why":"绝对误差是测量值与标准值之差的绝对值，负号只表示偏小，不表示误差小","do":"对表中每个 ΔT 取绝对值后排序，找出最大与最小对应的 T","expr":"|\\Delta T|=|T-T_b|","cues":["负的也要算大小","取绝对值比","别被负号骗了"],"concepts":["绝对误差","误差"]},{"title":"误差来源指向拟合与匹配","type":"误差分析","judge":"在排除元器件精度与稳定性后，误差应归因于标定环节：拟合函数形式与实际关系的偏差、匹配电阻选取不当","why":"传感器先用二次多项式拟合 T-U_out 关系，拟合式本身是近似，且 R_0 决定曲线线性程度，二者都会引入系统误差","do":"回顾第(3)问的二次拟合与第(2)问的 R_0 选择，指出拟合不精确和匹配电阻不合适","expr":"","cues":["拟合不够准","匹配电阻没选好","标定曲线有偏差"],"concepts":["系统误差","数据拟合","传感器标定"]}],"351":[{"title":"入射角折射角换算","type":"几何关系","judge":"题目给的是光线与水面（界面）的夹角，要判断入射角和折射角是它与法线的夹角，需用余角换算","why":"折射定律中的角一律是光线与界面法线的夹角，而水面法线竖直，题给 45°、60° 都是与水面（水平面）的夹角","do":"对第一问，把与水面成 45° 的入射光线换成入射角 i=90°−45°，把水下与水面成 60° 的折射光线换成折射角 r=90°−60°","expr":"i=90^\\circ-45^\\circ,\\quad r=90^\\circ-60^\\circ","cues":["与水面夹角","换成与法线夹角","取余角"],"concepts":["入射角","折射角","法线"]},{"title":"判断光从空气射入水","type":"前提判断","judge":"要判断第一问中光是由空气进入水还是由水进入空气，从而确定折射定律中 n 放在哪一侧","why":"球壳上方是空气、下方是水，激光自上而下斜射，先在空气侧入射、再进入水中折射，故 n=sin i/sin r","do":"确认入射介质为空气、折射介质为水，写出 n=sin i/sin r 并代入 i、r","expr":"n=\\frac{\\sin i}{\\sin r}","cues":["从空气进水","n在分母","先空气后水"],"concepts":["折射定律","折射率"]},{"title":"全反射发生在哪一界面","type":"临界条件","judge":"要判断第二问中光线从水射向球壳时，全反射发生在水与球壳内空气的界面上，而不是水与外界空气的水面","why":"光线在水下射向球壳，穿过球壳壁后进入球壳内的空气，是从光密介质（水）射向光疏介质（空气），才可能发生全反射","do":"锁定全反射界面为球壳内壁的水—空气界面，取临界条件 sin C=1/n","expr":"\\sin C=\\frac{1}{n}","cues":["水到空气","光密到光疏","球壳内壁"],"concepts":["全反射","临界角","光密介质"]},{"title":"临界角与水面夹角互余","type":"关系建立","judge":"要判断所求的“光线与水面的夹角”与临界角 C 是互余关系，而不是相等或互补","why":"临界角 C 是光线与界面法线的夹角，而水面法线竖直，故光线与水平水面的夹角 θ=90°−C","do":"由 sin C=1/n 求出 C，再用 θ=90°−C 得到所求夹角","expr":"\\theta=90^\\circ-C","cues":["与法线夹角","再取余角","水面是水平的"],"concepts":["临界角","几何关系"]}],"352":[{"title":"摩擦力是否恒定","type":"前提判断","judge":"弹力绳拉力沿杆的分量随伸长量变化，但垂直于杆的分量是否恒定，从而判断滑动摩擦力是否为定值","why":"弹力绳方向随小球位置改变，若垂直杆分量不恒定，摩擦力就是变力，无法用 f=μF_N 直接求定值；需借助 Q 到斜杆的垂距与伸长量的几何关系","do":"设伸长量 l、绳与斜杆夹角 α，写出垂直杆方向压力 F_N=F sinα−mg cosθ，再用 Q 到斜杆的垂距 h₁=l sinα 与 h₁=h cosθ 消去 l 和 α","expr":"$F_N=kl\\sin\\alpha-mg\\cos\\theta,\\quad l\\sin\\alpha=h\\cos\\theta$","cues":["压力随位置变吗","绳方向在变","垂直分量恒定","先找几何关系"],"concepts":["受力分析","胡克定律","滑动摩擦力"]},{"title":"下滑全程用动能定理","type":"模型选择","judge":"求 A 到达 O 点的速度时，是逐段用牛顿定律还是对整段用动能定理","why":"摩擦力虽为定值但绳拉力是变力，且题目给了弹性势能表达式，说明能量路径是设计好的；用动能定理可避开变力做功的积分","do":"对从释放点到 O 点的整段列动能定理，把摩擦力做功、重力做功、弹性势能变化一并计入","expr":"$-f\\cdot 2h+mgh+\\left[\\tfrac12 k(\\sqrt3 h)^2-\\tfrac12 kh^2\\right]=\\tfrac12 mv_A^2$","cues":["用动能定理","变力不做功积分","整段列式","弹性势能代进去"],"concepts":["动能定理","弹性势能"]},{"title":"弹性碰撞定碰后速度","type":"关系建立","judge":"A、B 在 O 点发生弹性碰撞，碰后两者速度各为多少、方向如何","why":"碰撞前后动量守恒且动能守恒，两式联立才能定出两个未知速度；A 碰后反向是后续上滑简谐运动与 B 减速计时不同步的根源","do":"以碰前 A 的速度方向为正，列动量守恒与动能守恒两式，解出 v_A′ 与 v_B′ 并判断正负号含义","expr":"$mv_A=mv_A'+3mv_B',\\quad \\tfrac12 mv_A^2=\\tfrac12 mv_A'^2+\\tfrac12\\cdot3mv_B'^2$","cues":["弹性碰撞两式","碰后反向","质量三倍","速度交换吗"],"concepts":["弹性碰撞","动量守恒","能量守恒"]},{"title":"简谐运动周期定时刻","type":"关系建立","judge":"A 碰后上滑做简谐运动，第一次速度为零对应相位是多少、对应多长时间","why":"题目直接给出 x=A₀sin(√(k/m)t)，说明上滑是简谐运动；速度为零即位移最大，对应相位 π/2，由此得 t_A","do":"由速度为零对应位移最大，令相位等于 π/2，解出 t_A","expr":"$\\sqrt{\\tfrac{k}{m}}\\,t_A=\\tfrac{\\pi}{2}\\Rightarrow t_A=\\tfrac{\\pi}{2}\\sqrt{\\tfrac{m}{k}}$","cues":["速度为零在最大位移","相位取二分之派","四分之一周期","简谐运动"],"concepts":["简谐运动","相位","周期"]},{"title":"比较两球停止先后","type":"临界条件","judge":"在 A 第一次速度为零的时刻，B 是否已经停下，从而决定用哪段运动学公式","why":"B 在水平杆上只受摩擦力做匀减速，若在 t_A 之前已停止，位移公式要换成先算停止距离；只有确认 t_B>t_A 才能直接用减速位移公式","do":"先算 B 的减速度 μg 与停止时间 t_B，与 t_A 比较大小，再决定位移表达式","expr":"$t_B=\\dfrac{v_B'}{\\mu g}=\\dfrac{1}{\\mu}\\sqrt{\\dfrac{2m}{k}},\\quad t_B>t_A$","cues":["B停没停","先比时间","匀减速到零","μ是三分之根三"],"concepts":["匀变速直线运动","临界条件","摩擦力"]},{"title":"位移公式代入化简","type":"数学处理","judge":"确认 B 仍在运动后，用初速度、加速度和时间写出 B 相对 O 的位移并化简为含 π 的表达式","why":"B 从 O 点出发做匀减速，位移为 v_B′t_A−½μg t_A²，代入 t_A 与 μ 的具体值才能得到题目要求的距离形式","do":"把 v_B′、t_A、μ=√3/3 代入位移式，整理成含 π 与 mg/k 的式子","expr":"$s=v_B't_A-\\tfrac12\\mu g t_A^2$","cues":["代入化简","保留π","提出mg/k","别漏平方项"],"concepts":["匀变速位移公式","代入化简"]}],"353":[{"title":"光子能量与逸出功比较","type":"前提判断","judge":"要判断哪种阴极材料能对所有波长（200~900 nm）都发生光电效应，即比较最短波长光子的能量与各材料逸出功的大小","why":"光电效应发生的条件是入射光子能量不小于逸出功，而波长范围中能量最小的是最长波长 900 nm 对应的光子，只要它也能打出光电子，整个波段就都能打出","do":"用 ε=hc/λ 分别算出 200 nm 和 900 nm 光子的能量，与三种材料的逸出功逐一比较，取逸出功小于最小光子能量的材料","expr":"$\\varepsilon=\\frac{hc}{\\lambda}$","cues":["算最短波长能量","看最长波长够不够","比逸出功大小"],"concepts":["光电效应","逸出功","光子能量"]},{"title":"分段建立运动模型","type":"模型选择","judge":"要判断电子在加速区、无场区、偏转区、偏转后无场区各做什么运动，以及水平方向速度是否始终不变","why":"加速区只有轴向电场做匀加速；无场区不受力做匀速直线；偏转区水平匀速、竖直匀加速；出偏转板后竖直匀速，水平速度全程不变","do":"把全程拆成四段，分别写出各段的位移—时间关系和速度关系，用同一水平速度 v1 串起各段时间","expr":"$v_1^2=2\\frac{eU_1}{md_1}d_1,\\quad L_1=v_1t_2,\\quad L_2=v_1t_3,\\quad L_3=v_1t_4$","cues":["先求加速后速度","水平速度不变","分四段算时间"],"concepts":["匀加速直线运动","类平抛运动","匀速直线运动"]},{"title":"偏转位移与出射偏角叠加","type":"关系建立","judge":"要判断屏上总偏移由偏转板内的竖直位移和出板后按出射竖直速度匀速漂移的位移两部分叠加而成","why":"出偏转板后竖直方向不再受力，以出板时的 vy 做匀速直线运动，两段竖直位移必须相加，不能只算板内位移","do":"分别写出板内位移 y1 与板后位移 y2=vy·t4，相加得屏上坐标，并消去中间量化为 U、L2、L3、U1、d2 的表达式","expr":"$y=\\frac12a_2t_3^2+v_yt_4=\\frac{UL_2(L_2+2L_3)}{4U_1d_2}$","cues":["两段位移要相加","出板后按速度漂","别漏板后那段"],"concepts":["类平抛运动","速度分解","位移叠加"]},{"title":"变电压下用平均加速度求末速度","type":"数学处理","judge":"要判断偏转电压随时间线性变化时，竖直加速度也线性变化，末速度可由加速度对时间的积分（a-t 图面积）求得，而非用匀加速公式","why":"a=e(U0+kt)/(md2) 随 t 线性增大，不能直接套 v=at，需对进入时刻到出板时刻的加速度积分，等效取初末加速度平均值","do":"确定电子进入偏转板的时刻，写出该时刻电压，对 a-t 线性关系在 t3 内积分（或取平均加速度），得到出板时 vy","expr":"$v_y=\\bar a\\,t_3=\\frac{e}{md_2}\\left[U_0+k(t_1+t_2+\\Delta t)+\\frac{kt_3}{2}\\right]t_3$","cues":["加速度在变","用平均加速度","画加速度时间图"],"concepts":["变加速运动","加速度积分","平均加速度"]},{"title":"首末电子时刻差对应脉冲宽度","type":"临界条件","judge":"要判断脉冲宽度对应的是最先与最后进入偏转板的电子之间的时间差，即激光持续时间 Δt，且两者出板后漂移时间相同","why":"电子脉冲持续时间与激光相同，最先进入的是脉冲前沿电子，最后进入的比它晚 Δt；因水平速度相同，两者从出板到屏的飞行时间 t4 相同，速度差直接转化为屏上间距","do":"写出前沿电子进入时刻 t1+t2 与后沿电子进入时刻 t1+t2+Δt 对应的 vy1、vy2，作差乘 t4 得屏上宽度","expr":"$\\Delta y=(v_{y2}-v_{y1})t_4=\\frac{kL_2L_3}{2U_1d_2}\\Delta t$","cues":["首末电子差一个脉宽","漂移时间相同","速度差乘时间"],"concepts":["脉冲持续时间","速度差","空间展宽"]},{"title":"小 L2 近似忽略板内位移差","type":"近似条件","judge":"要判断 L2≪L3 时可忽略不同时刻电子在偏转板内竖直位移的差别，只保留出板竖直速度差造成的屏上展宽","why":"板内位移差正比于 L2²，而板后漂移差正比于 L2L3，在 L2≪L3 时前者为高阶小量，可略去，这正是题目给出该条件的用意","do":"比较 y1 差与 y2 差的数量级，只保留含 L2L3 的项，得到 Δy 的简化式","expr":"$\\Delta y\\approx(v_{y2}-v_{y1})t_4,\\quad L_2\\ll L_3$","cues":["L2很小可略","只算速度差","板内位移差忽略"],"concepts":["近似条件","小量忽略","空间展宽"]}],"354":[{"title":"电场线方向与电势","type":"前提判断","judge":"沿电场线方向电势是降低还是升高","why":"静电场中电场线由高电势指向低电势，这是判断各点电势高低的唯一依据","do":"回忆电场线方向与电势降落方向的对应关系，确定比较电势时只需看各点沿电场线的先后位置","expr":"","cues":["顺着电场线电势降低","电场线指向低电势"],"concepts":["电场线","电势"]},{"title":"确定电场线指向","type":"图像读取","judge":"图中电场线的箭头（或疏密变化）指向哪一端，即哪端是尖端、哪端是远处","why":"尖端放电时电场线由带电线端向外发散，箭头背离尖端，只有先定出箭头方向才能定出电势降落方向","do":"读图中电场线的箭头方向，确认电场线从尖端附近指向外侧","expr":"","cues":["看箭头","箭头背离尖端","尖端是起点"],"concepts":["尖端放电","电场线方向"]},{"title":"沿同一条线排序","type":"关系建立","judge":"a、b、c、d 四点是否在同一条电场线上，以及它们沿电场线方向的先后次序","why":"只有沿同一条电场线（或同一路径）才能直接用“沿电场线电势降低”比较电势，否则需借助等势面","do":"把四点定位到图中那条电场线上，按电场线箭头方向排出从上游到下游的顺序","expr":"","cues":["在同一条线上","按箭头排顺序","上游电势高"],"concepts":["电场线","电势高低比较"]},{"title":"取最上游点","type":"结论整理","judge":"排序中最靠电场线起点（上游）的那个点电势最高","why":"沿电场线电势单调降低，故越靠上游电势越高，最上游点即为四点中电势最高者","do":"在排好的顺序中取最靠尖端一侧的点作为答案","expr":"","cues":["最靠尖端的高","越往外越低"],"concepts":["电势","电场线"]}],"355":[{"title":"判断气体做功方向","type":"模型选择","judge":"气体体积变大时，是气体对外做功还是外界对气体做功","why":"做功正负由体积变化决定：体积膨胀时气体对外界做功，体积被压缩时外界对气体做功","do":"比较初末体积，确定体积增大，再据此判断做功方向","expr":"W<0（气体对外做功）","cues":["体积变大","对外做功","膨胀"],"concepts":["气体做功","体积变化"]},{"title":"判断热传递方向","type":"前提判断","judge":"温度升高是气体吸热还是放热","why":"太阳曝晒使皮球温度高于环境，热量由外界传给气体，气体吸热","do":"比较气体温度与外界温度，确定热流方向","expr":"Q>0","cues":["暴晒","吸热","温度升高"],"concepts":["热传递","吸热"]},{"title":"区分平均与单个分子","type":"结论整理","judge":"温度升高能否推出每个分子速率都增大","why":"温度只决定分子平均动能，分子速率服从统计分布，个别分子速率可能减小","do":"把'平均动能增大'与'每个分子速率增大'区分开","expr":"","cues":["平均动能","不是每个","统计规律"],"concepts":["分子平均动能","统计规律"]},{"title":"判断分子数密度变化","type":"关系建立","judge":"未漏气且体积变大时，分子数密度如何变化","why":"分子总数不变而体积增大，单位体积内分子数减少","do":"用分子总数除以体积，比较体积变化前后的数密度","expr":"n=N/V，V增大则n减小","cues":["未漏气","总数不变","数密度减小"],"concepts":["分子数密度","物质的量"]}],"356":[{"title":"识别游标卡尺分度","type":"前提判断","judge":"要判断图中游标尺是多少分度，从而确定每分度代表多少毫米","why":"游标卡尺的精度由游标尺分度数决定，50 分度对应精度 0.02 mm，分度数看错则精度和末位有效数字全错","do":"数游标尺上的总格数（或看标注的 0.02），确定精度","expr":"\\text{精度}=\\frac{1\\ \\text{mm}}{n}","cues":["数游标格数","看是不是五十分度","精度是零点零二"],"concepts":["游标卡尺","分度值"]},{"title":"读主尺整毫米数","type":"图像读取","judge":"要判断游标尺零刻线落在主尺哪两条刻度线之间，取哪一条作为主尺读数","why":"游标卡尺读数以游标零刻线为准，主尺读数是零刻线左侧最近的整毫米刻度，取错刻度会整体偏差 1 mm","do":"找游标零刻线位置，读其左侧主尺整毫米刻度值","expr":"L_{\\text{主}}=17\\ \\text{mm}","cues":["看游标零线","取左边那条","主尺十七毫米"],"concepts":["主尺读数","零刻线"]},{"title":"找对齐的游标刻线","type":"图像读取","judge":"要判断游标尺上第几条刻度线与主尺某条刻度线对齐","why":"游标尺读数等于对齐刻线的格序数乘精度，对齐线找错则小数部分错","do":"沿游标尺逐条比对，找出与主尺刻线重合的那一条，记下格序数","expr":"k=10","cues":["找对齐那条","第十条对齐","看哪条重合"],"concepts":["对齐刻线","游标读数"]},{"title":"小数部分与有效位","type":"数学处理","judge":"要判断游标读数保留几位小数、末位零是否必须写出","why":"50 分度卡尺精度 0.02 mm，读数应保留到百分位，末位零是有效数字不能省略，否则与仪器精度不符","do":"用格序数乘精度得小数部分，再与主尺读数相加，按百分位写全","expr":"L=17\\ \\text{mm}+10\\times0.02\\ \\text{mm}=17.20\\ \\text{mm}","cues":["保留两位小数","末位零要写","加起来是十七点二零"],"concepts":["有效数字","读数规则"]}],"357":[{"title":"绳两段方向","type":"几何关系","judge":"判断小球在最低点时，绳的两段分别沿什么方向、与竖直方向夹角多大","why":"细绳一端固定在左边沿、另一端过右边沿，两段绳都从最低点连到半圆边沿，由半圆的几何性质，这两段与竖直方向各成 45°","do":"画出最低点到左右边沿的两条弦，利用半圆内接角关系定出两段绳与竖直方向的夹角","expr":"\\theta=45^\\circ","cues":["两段绳对称","沿切线方向","连到边沿"],"concepts":["半圆几何","绳的方向"]},{"title":"绳张力处处相等","type":"前提判断","judge":"判断同一根不可伸长的细绳上各处张力是否相等，两段绳对球的拉力大小是否相同","why":"绳不可伸长、穿孔处光滑，绳中张力处处相等，故两段绳对球的拉力大小都等于 F","do":"把两段绳对球的拉力都记为 F，作为受力分析的输入","expr":"T_1=T_2=F","cues":["同一根绳","光滑孔","张力一样"],"concepts":["绳的张力","光滑接触"]},{"title":"三力平衡建方程","type":"关系建立","judge":"判断小球受哪几个力，并沿竖直方向把两段绳拉力的分量与重力平衡","why":"小球始终在最低点，处于平衡状态，竖直方向合力为零；两段绳拉力竖直分量之和等于重力","do":"对小球受力分析，写出竖直方向的平衡方程","expr":"2F\\cos45^\\circ=G","cues":["三力平衡","取竖直方向","分解拉力"],"concepts":["共点力平衡","力的分解"]},{"title":"最大拉力的临界","type":"临界条件","judge":"判断 F 增大到最大时凹槽对小球的支持力处于什么状态","why":"F 增大使绳的竖直分量增大，凹槽对球的支持力随之减小；支持力减到零即为 F 最大的临界，再大球就会离开最低点","do":"令支持力 N=0，把此时代入竖直平衡方程求 F 的极值","expr":"N=0\\Rightarrow 2F_m\\cos45^\\circ=G","cues":["支持力为零","刚要离开","取临界"],"concepts":["临界状态","支持力"]}],"358":[{"title":"轨迹弧长对应曝光时间","type":"前提判断","judge":"照片上那段圆弧是彩灯在曝光时间内扫过的轨迹，还是彩灯本身静止的形状","why":"只有把圆弧认定为曝光时间内转过的角度，才能把圆心角与曝光时间对应起来","do":"读图确认圆弧是运动轨迹，把圆弧圆心角与曝光时间配对","expr":"","cues":["圆弧是轨迹","曝光时间内转过的","不是灯的形状"],"concepts":["匀速圆周运动","曝光时间"]},{"title":"角度单位换算","type":"数学处理","judge":"圆心角用度还是弧度代入角速度公式","why":"角速度定义式要求角度用弧度，直接用 30 代入会差一个换算因子","do":"把 30 度换成弧度再除以曝光时间","expr":"$\\theta=30^\\circ=\\frac{\\pi}{6}\\ \\mathrm{rad}$","cues":["先换成弧度","三十度是六分之派","不能直接除"],"concepts":["弧度制","角速度"]},{"title":"角速度定义求ω","type":"关系建立","judge":"用哪段时间和哪个角度求角速度","why":"匀速圆周运动角速度等于转过的角度除以所用时间，这里的角度和时间必须来自同一段轨迹","do":"用圆弧圆心角除以曝光时间求角速度","expr":"$\\omega=\\frac{\\theta}{\\Delta t}=\\frac{\\pi/6}{1/30}=5\\pi\\ \\mathrm{rad/s}$","cues":["角度除以时间","用曝光时间","匀速所以直接除"],"concepts":["角速度","匀速圆周运动"]},{"title":"角速度转每分钟圈数","type":"关系建立","judge":"求每分钟圈数时用角速度乘时间再除以一圈的角度","why":"一圈对应 2π 弧度，一分钟 60 秒，圈数等于总转角除以 2π","do":"把角速度乘 60 秒得到每分钟总转角，再除以 2π","expr":"$n=\\frac{\\omega\\times60}{2\\pi}$","cues":["一圈是二派","先算一分钟转多少","除以一圈的角度"],"concepts":["周期","转速"]}],"359":[{"title":"发射点势能零点","type":"前提判断","judge":"发射点（星球表面 r=R0）处引力势能取何值，才能与题给势能式配套使用","why":"题给势能式在 r=R0 时为零，机械能守恒必须用同一零点，否则初末势能差算错","do":"把 r=R0 代入题给势能表达式，确认表面处势能为零，从而初态机械能只有动能","expr":"E_{p0}=mg_0R_0^2\\left(\\frac{1}{R_0}-\\frac{1}{R_0}\\right)=0","cues":["表面势能为零","用题给的式子"],"concepts":["引力势能","零势能面"]},{"title":"轨道半径取2R0","type":"几何关系","judge":"圆轨道半径是 R0 还是 2R0","why":"题说距表面高度为 R0，轨道半径应为星球半径加高度，误取 R0 会使速度和动能全错","do":"由高度 R0 加星球半径 R0 得轨道半径，代入势能式和向心力式","expr":"r=R_0+R_0=2R_0","cues":["高度加半径","离地心两个半径"],"concepts":["轨道半径","中心天体"]},{"title":"用表面重力替换GM","type":"关系建立","judge":"轨道处向心力方程中的 GM 如何用题给的 g0、R0 消去","why":"题目只给 g0 和 R0 而未给 M，必须借星球表面重力加速度关系把 GM 换掉才能求速度","do":"写出表面处重力等于万有引力的关系，再写出轨道处万有引力提供向心力的方程，联立消去 GM","expr":"\\frac{GMm}{R_0^2}=mg_0,\\quad \\frac{GMm}{(2R_0)^2}=m\\frac{v^2}{2R_0}","cues":["黄金代换","表面重力等于引力"],"concepts":["万有引力定律","向心力","黄金代换"]},{"title":"机械能守恒定初速","type":"模型选择","judge":"从表面发射到进入圆轨道的过程能否用机械能守恒，初态机械能由什么构成","why":"飞行中只受星球引力，引力为保守力，机械能守恒；初态在表面势能为零，末态机械能为动能加势能","do":"令初态动能等于末态动能与末态势能之和，解出初速度","expr":"\\frac12 mv_0^2=\\frac12 mv^2+mg_0R_0^2\\left(\\frac{1}{R_0}-\\frac{1}{2R_0}\\right)","cues":["只有引力做功","初态只有动能"],"concepts":["机械能守恒","引力势能","动能"]}],"360":[{"title":"电荷均分规律","type":"前提判断","judge":"两球接触后各自带电量是否等于接触前总电荷量的一半","why":"A、B、C 是相同的金属球，接触时电荷在两者间重新分配，只有相同金属球才保证均分；若球不同则不能取平均","do":"对 C 与 A 接触、C 再与 B 接触各写一次均分式","expr":"q_1=\\frac{Q+q}{2},\\quad q_2=\\frac{q+q_1}{2}=\\frac{Q+3q}{4}","cues":["相同球才均分","先碰谁后碰谁","电荷量取平均"],"concepts":["电荷守恒","接触起电"]},{"title":"同种电荷带符号","type":"模型选择","judge":"A、B 原来带的是同种电荷，q 应取同号，而 Q 可正可负","why":"题设只说 A、B 带等量同种电荷，未限定 Q 的符号；Q 与 q 异号时接触后电荷可能反号，力的大小关系要用绝对值处理","do":"把 q 视为正的代表 A、B 的电性，令 Q 取正、负两种情形分别代入","expr":"","cues":["Q可能带负电","同种电荷先定号","异号接触会中和"],"concepts":["电荷正负","库仑定律"]},{"title":"力大小只比电量积","type":"关系建立","judge":"间距不变时，比较先后两次静电力大小是否等价于比较两次电荷量乘积的绝对值","why":"库仑定律 F=kq1q2/L²，L 未变，力的大小只由两球电荷量乘积的绝对值决定，与各自符号无关","do":"写出接触前、接触后两个库仑力表达式并令其大小相等","expr":"\\frac{kq^2}{L^2}=\\frac{k|q_1q_2|}{L^2}\\Rightarrow q^2=|q_1q_2|","cues":["距离没变","只看电量乘积","力取绝对值"],"concepts":["库仑定律","控制变量"]},{"title":"去绝对值分两解","type":"数学处理","judge":"由 q²=|q1q2| 解 Q 时，是否保留正负两种可能而不是只取一解","why":"绝对值方程等价于 q1q2=±q²，对应 Q 的两个值；漏掉负号情形会少一个答案，干扰项正是只取一解或算错系数","do":"把 q1、q2 的表达式代入，分别解 q1q2=q² 与 q1q2=-q²","expr":"\\frac{(Q+q)(Q+3q)}{4}=\\pm q^2","cues":["绝对值要拆两种","别只算一个解","正负都要试"],"concepts":["一元二次方程","绝对值方程"]},{"title":"取比值绝对值","type":"结论整理","judge":"题目问的是 |Q:q|，需把解出的 Q 除以 q 后取绝对值","why":"题干明确要求 Q:q 的绝对值，负解也要转成正的比值才能与选项对应","do":"将求得的 Q 值分别除以 q 并取绝对值","expr":"\\left|\\frac{Q}{q}\\right|","cues":["问的是绝对值","负解也变正","比值不是电量"],"concepts":["比值","绝对值"]}],"361":[{"title":"两物块位移与弹簧形变关联","type":"几何关系","judge":"左侧物块沿斜面下移 x 时，右侧物块沿斜面上移多少、两弹簧各自形变多少","why":"细绳不可伸长且跨过定滑轮，两侧沿绳位移大小相等；弹簧一端连物块一端连底端，物块位移即弹簧形变量","do":"设左物块沿斜面向下位移为 x，写出右物块位移和左右弹簧的形变量","expr":"左弹簧伸长 x，右弹簧伸长 x，右物块沿斜面向上移 x","cues":["绳长不变","两边位移一样","弹簧跟着拉长"],"concepts":["不可伸长细绳","弹簧形变","位移约束"]},{"title":"取单物块列牛顿方程","type":"关系建立","judge":"对每个物块沿斜面方向受哪些力、正方向怎么定，才能把绳拉力 T 与弹簧力同时纳入","why":"两物块通过绳相互作用，必须分别对左右物块沿斜面列牛顿第二定律，才能消去未知的 T","do":"对左物块（沿斜面向下为正）和右物块（沿斜面向上为正）分别列方程","expr":"左：$T+kx-mg\\sin\\theta=ma$；右：$mg\\sin\\theta+kx-T=ma$","cues":["分别列方程","沿斜面方向","消掉绳拉力"],"concepts":["牛顿第二定律","受力分析","绳拉力"]},{"title":"消去拉力得回复力","type":"数学处理","judge":"联立两方程后，合外力与位移 x 成什么关系、方向是否总指向平衡位置","why":"简谐运动的判据是合外力与位移成正比且方向相反，即 F=-kx 形式","do":"两式相加消去 T，得到合外力与 x 的关系并判断方向","expr":"$F=ma=kx$，方向与位移 x 相反","cues":["相加消去拉力","合力和位移成正比","方向相反"],"concepts":["简谐运动","回复力","判据"]},{"title":"判断绳拉力是否变化","type":"结论整理","judge":"运动过程中绳拉力 T 是否随位移改变","why":"由两方程相加已得 T 与 x 无关，T 恒等于 mg sinθ，不能凭直觉认为拉力随运动变化","do":"把消元结果回代任一方程，解出 T 并看是否含 x","expr":"$T=mg\\sin\\theta$，与 x 无关","cues":["拉力不变","回代求拉力","和位移无关"],"concepts":["绳拉力","平衡位置","常量判断"]},{"title":"周期与倾角无关","type":"近似条件","judge":"简谐运动的周期由哪些量决定，斜面倾角 θ 是否进入周期表达式","why":"回复力系数为 k、惯性质量为 m，周期只由 m 和 k 决定，重力沿斜面分量只移动平衡位置","do":"写出周期公式，检查其中是否含 θ","expr":"$T_{\\text{周}}=2\\pi\\sqrt{m/k}$","cues":["周期只看质量和劲度","倾角只改平衡位置","和角度无关"],"concepts":["简谐运动周期","等效劲度系数","平衡位置"]}],"362":[{"title":"判断粒子电性","type":"前提判断","judge":"由偏转方向判断粒子带正电还是负电","why":"磁场垂直纸面向里，粒子从 P 向 M 板偏转，用左手定则反推电荷正负，电性决定后续电场力方向","do":"画出 P 到 Q 的圆弧轨迹，确定偏转方向，用左手定则判断电性","expr":"","cues":["看偏转方向","左手定则","先定电性"],"concepts":["洛伦兹力","左手定则"]},{"title":"由弦长定轨迹半径","type":"几何关系","judge":"用 θ=60° 和 OQ=3L 的几何条件确定圆周运动半径 r 及 OP 距离","why":"粒子垂直穿过 M 板，说明 Q 点速度沿板法线，圆心在过 Q 的竖直线上，弦 PQ 与 OP 的夹角关系给出半径","do":"作圆心与弦 PQ，利用直角三角形中 cos60°=(3L−r)/r 解出 r，再求 OP=r sin60°","expr":"\\cos 60^\\circ=\\frac{3L-r}{r},\\quad OP=r\\sin 60^\\circ","cues":["垂直穿过即沿法线","找圆心","弦长关系"],"concepts":["圆周运动","几何关系"]},{"title":"判断最大电场强度","type":"临界条件","judge":"粒子恰好到达 N 板时板间电场强度取最大值，判断 E 与 d 的关系","why":"N 板不断吸收粒子使带电量增加，电场增强，粒子减速；恰能到达 N 板是电场最强的临界状态","do":"对恰好到达 N 板的过程用动能定理或 v²=2ad，解出 E 的表达式","expr":"v^{2}=2\\frac{qE}{m}d\\Rightarrow E=\\frac{mv^{2}}{2qd}","cues":["恰能到达即临界","动能定理","电场随电量增大"],"concepts":["动能定理","匀强电场"]},{"title":"区分两种打板路径","type":"模型选择","judge":"粒子打在 M 板上表面可能来自磁场直接偏转，也可能经板间返回后从 Q 射出再偏转，需比较两种路径的最大距离","why":"N 板带电后粒子从 Q 射入会被减速返回，再从 Q 射出继续圆周运动，路径不同导致落点范围不同","do":"分别求直接偏转的最大水平距离 x_m1 与返回后偏转的 x_m2，取较大者","expr":"x_{m1}=\\sqrt{(2r)^2-OP^2},\\quad x_{m2}=OQ+2r","cues":["两种路径","返回再射出","取较大值"],"concepts":["圆周运动","对称性"]},{"title":"确定返回射入的速度方向","type":"几何关系","judge":"粒子经板间返回后从 Q 射出时，进入板间的速度方向与 M 板夹角 α 由轨迹弦长仍为 PQ 决定","why":"金属板厚度不计，轨迹弦长不变则粒子仍从 Q 进入板间，由几何关系确定入射角 α=30°","do":"由弦长 PQ 不变确定 P 点沿正上方发射，求进入板间速度与板的夹角 α","expr":"\\alpha=30^\\circ","cues":["弦长不变","沿正上方发射","入射角"],"concepts":["圆周运动","几何对称"]},{"title":"求板间运动时间与水平位移","type":"关系建立","judge":"板间为匀减速运动，用竖直分速度求时间，再用水平分速度求水平位移 s","why":"板间只有竖直方向电场力，水平方向匀速，竖直方向匀减速，两方向独立","do":"由 t=2v sinα/a 求时间，再由 s=v cosα·t 求水平位移，代入 a=v²/(2d)","expr":"t=\\frac{2v\\sin\\alpha}{a},\\quad s=v\\cos\\alpha\\,t=2d\\sin 2\\alpha","cues":["分方向处理","竖直减速","水平匀速"],"concepts":["运动的分解","匀变速直线运动"]}],"363":[{"title":"欧姆表测阻须断电","type":"实验操作","judge":"用欧姆表接在热敏电阻 a、b 两端测阻值时，热敏电阻所在的原电路是否还带电","why":"欧姆表内部自带电源，若外电路电源未断开，外加电压会叠加到表头上，读数不准甚至损坏表头","do":"判断开关 S 的状态，使热敏电阻与电源脱离","expr":"","cues":["先断电源","欧姆表自己带电","不能带电测"],"concepts":["欧姆表","闭合电路"]},{"title":"过热保护选正温度系数","type":"前提判断","judge":"要抑制电流异常增大，串联的热敏电阻阻值应随温度升高而增大还是减小","why":"串联电阻越大电流越小，只有阻值随温度升高而增大，才能在元件过热时自动限流","do":"比较曲线Ⅰ、Ⅱ的阻值随温度变化趋势，挑出阻值随温度升高而增大的那条","expr":"","cues":["温度高电阻要大","阻值随温度升","看曲线走向"],"concepts":["热敏电阻","温度特性","限流保护"]},{"title":"验证机械能守恒可约去质量","type":"模型选择","judge":"验证机械能守恒时滑块质量是否必须测量","why":"重力势能减少量与动能增加量都正比于质量，方程两边可约去 m，故质量不是必测量","do":"写出 mgh 与动能变化相等的式子，两边消去 m，看剩下哪些量","expr":"mg\\Delta h=\\tfrac12 m v_B^2-\\tfrac12 m v_A^2","cues":["质量约掉了","两边都有质量","不用测质量"],"concepts":["机械能守恒","动能","重力势能"]},{"title":"竖直高度差不可换成距离","type":"几何关系","judge":"重力做功对应的是两光电门间的竖直高度差还是沿导轨的距离","why":"重力做功只由竖直方向的高度变化决定，沿斜面距离需再乘倾角正弦才等于高度差，题中未给倾角","do":"比较甲、乙、丙三方案所需物理量，找出把高度差替换成距离而无法换算的那个","expr":"W_G=mg\\Delta h","cues":["重力看高度差","距离要乘角度","倾角没给"],"concepts":["重力做功","高度差","斜面"]},{"title":"遮光时间对应遮光条宽度","type":"图像读取","judge":"算通过光电门的速度时，用遮光条宽度 d1 还是光电门宽度 d2 除以遮光时间","why":"挡光的是遮光条，计时器记录的遮光时间正是遮光条通过光路的时间，故位移取 d1","do":"取 d1 与所给遮光时间相除，注意毫米与毫秒的单位换算","expr":"v_A=\\frac{d_1}{\\Delta t}","cues":["用遮光条宽度","不是门宽","单位换米和秒"],"concepts":["平均速度","光电门","瞬时速度近似"]}],"364":[{"title":"压强由高度差决定","type":"前提判断","judge":"集气室内气体压强由哪段水柱的高度差决定，与桶的内径 D 是否有关","why":"封闭气体压强由连通器原理决定，等于大气压加上水面高度差产生的压强，只与高度差有关，与容器粗细无关","do":"写出集气室内压强表达式，比较桶内水位与集气室内进水高度之差，判断 D 是否出现在式中","expr":"p=p_0+\\rho g(H-h)","cues":["看高度差","与粗细无关","连通器原理"],"concepts":["连通器原理","液体压强"]},{"title":"相对误差看测量值大小","type":"误差分析","judge":"同一把刻度尺测 H 和 h，哪个量的相对误差更小","why":"同一刻度尺绝对误差相同，相对误差等于绝对误差除以测量值，测量值越大相对误差越小","do":"比较表中 H 与 h 的数量级，用绝对误差比测量值判断相对误差大小","expr":"\\frac{\\Delta x}{x}","cues":["同一把尺子","绝对误差一样","看谁数值大"],"concepts":["相对误差","刻度尺分度值"]},{"title":"细管气体被忽略致截距","type":"误差分析","judge":"V 与 1/p 的直线不过原点，是哪个被忽略的因素造成的","why":"玻意耳定律要求气体质量不变，若把细管中那部分气体漏算，则记录的 V 比实际气体体积偏小，直线平移不过原点","do":"写出含细管体积的等温方程，对比记录体积与实际体积的差别，判断截距来源","expr":"p(V+V_{\\text{细}})=C","cues":["细管里的气","气体体积记少了","等温变化质量不变"],"concepts":["玻意耳定律","系统误差"]},{"title":"水位升高使自感变大","type":"关系建立","judge":"水位 H 升高时，铁芯进入线圈的长度和自感系数 L 如何变化","why":"铁芯进入越多，线圈磁通量变化越强，自感系数越大；水位越高，集气室压强越大，铁芯被压入越深","do":"按 H 增大、p 增大、铁芯进入长度增大、L 增大的链条推理","expr":"H\\uparrow\\Rightarrow p\\uparrow\\Rightarrow L\\uparrow","cues":["铁芯进得多","自感变大","水位高压强大"],"concepts":["自感系数","铁芯磁化"]},{"title":"频率与周期的反比关系","type":"关系建立","judge":"由 L 变大判断 LC 振荡频率是变大还是变小，再对应到示波器图像","why":"LC 振荡周期随 L 增大而增大，频率与周期互为倒数，故 L 越大频率越小、图像周期越长","do":"由周期公式判断 L 增大时 T 增大 f 减小，在 u-t 图上比较甲、乙的周期长短","expr":"T=2\\pi\\sqrt{LC},\\quad f=\\frac{1}{T}","cues":["先看周期","频率是倒数","周期长的频率低"],"concepts":["LC 振荡电路","周期与频率"]}],"365":[{"title":"全反射临界角对应最小入射角","type":"临界条件","judge":"要求的是全反射刚好发生时的入射角，还是任意入射角都能全反射","why":"全反射条件要求光从光密介质射向光疏介质且入射角大于等于临界角，临界角对应能发生全反射的最小入射角","do":"把'最小入射角'对应到临界角C，令入射角等于临界角","expr":"\\sin C=\\frac{1}{n}","cues":["最小角就是临界角","刚好全反射","入射角取临界值"],"concepts":["全反射","临界角"]},{"title":"真空一侧折射率取1","type":"前提判断","judge":"临界角公式中的分母n是玻璃相对哪种介质的折射率","why":"题设明确光纤为真空中的长玻璃丝，光从玻璃射向真空，光疏介质折射率为1","do":"确认n为玻璃相对真空的折射率，直接代入题给数值","expr":"n=\\frac{2\\sqrt{3}}{3}","cues":["外面是真空","光疏介质是真空","折射率取1"],"concepts":["折射率","光密介质与光疏介质"]},{"title":"截止频率由逸出功决定","type":"关系建立","judge":"截止频率对应光电效应中哪种能量关系","why":"截止频率是恰好能发生光电效应的最低频率，此时光电子最大初动能为零，入射光能量全部用于克服逸出功","do":"令最大初动能为零，写出逸出功与截止频率的关系式","expr":"h\\nu_{0}=W_{0}","cues":["最大初动能为零","刚好能逸出","能量全用来克服逸出功"],"concepts":["光电效应","逸出功","截止频率"]},{"title":"用hν0=W0而非减动能","type":"模型选择","judge":"用爱因斯坦光电方程时是否保留最大初动能项","why":"求的是截止频率而非某频率下的最大初动能，此时初动能为零，方程退化为hν0=W0","do":"在光电方程中令Ek=0，只保留逸出功项","expr":"h\\nu_{0}=W_{0}+0","cues":["不用减动能","初动能为零","直接用逸出功"],"concepts":["爱因斯坦光电方程"]},{"title":"两问单位与量级核对","type":"结论整理","judge":"角度用度还是弧度、频率数量级是否合理","why":"第一问求角度通常以度表示，第二问频率由焦耳除以焦耳秒得到赫兹，需核对10^14量级是否符合可见光附近范围","do":"检查角度值与频率的数量级和单位","expr":"\\nu_{0}=\\frac{W_{0}}{h}","cues":["角度写度","频率量级检查","单位是赫兹"],"concepts":["单位换算","数量级估算"]}],"366":[{"title":"平台段先判是否滑出","type":"前提判断","judge":"物块在平台上做匀减速，能否在到达右端前停下，即离开平台时是否还有水平速度","why":"只有确认物块能滑到平台右端并飞出，才能用平抛模型处理后续运动；若中途停下，题目问的'落到地面'就不存在","do":"用牛顿第二定律求平台上的加速度大小，再用速度位移关系求到达右端时的速度平方，与零比较","expr":"a=\\mu g,\\quad v_x^2-v_0^2=-2ax_0","cues":["先看能不能滑出去","算到右端还有没有速度","别默认一定飞出"],"concepts":["匀减速直线运动","牛顿第二定律","速度位移关系"]},{"title":"平抛初速取离开平台速度","type":"模型选择","judge":"离开平台后水平方向是否匀速、竖直方向是否自由落体，平抛的初速度应取哪一速度","why":"物块离开平台后只受重力，水平速度保持离开平台瞬间的值，不能用初速度 3 m/s 代入平抛","do":"把平台段末速度作为平抛的水平初速度，竖直方向从静止自由下落高度 h","expr":"h=\\tfrac12 gt_1^2,\\quad x=v_x t_1","cues":["平抛用飞出时的速度","不能用开始的速度","竖直方向自由落体"],"concepts":["平抛运动","运动的分解"]},{"title":"分段计时求接触时间","type":"关系建立","judge":"总时间 1 s 由哪几段组成，与地面接触的时间应等于总时间减去哪两段","why":"弹力冲量要用接触时间 Δt，而 Δt 不能直接读出，必须由总时间扣除下落段和反弹上升段得到","do":"由下落高度求下落时间，由反弹最大高度求上升时间，再用总时间相减得接触时间","expr":"t_2=\\sqrt{2h'/g},\\quad \\Delta t=t-t_1-t_2","cues":["总时间要拆成三段","接触时间靠相减","反弹高度求上升时间"],"concepts":["自由落体","竖直上抛","时间关系"]},{"title":"竖直方向动量定理定正方向","type":"关系建立","judge":"碰撞前后竖直速度方向相反，动量定理中初末动量如何带符号，弹力冲量与重力冲量如何共存","why":"弹力冲量是矢量，必须规定正方向并把落地速度取负、反弹速度取正，否则会漏掉重力冲量或符号出错","do":"取竖直向上为正，写出落地竖直速度（负）和反弹初速度（正），对接触过程列竖直方向动量定理","expr":"I_N-mg\\Delta t=mv_{y2}-m(-v_{y1}),\\quad v_{y1}=gt_1,\\ v_{y2}=gt_2","cues":["取向上为正","落地速度带负号","重力冲量不能漏"],"concepts":["动量定理","冲量","矢量方向"]},{"title":"水平方向摩擦冲量判停","type":"临界条件","judge":"水平方向摩擦力冲量是否足以把水平速度减到零，减到零后是否还会反向","why":"地面摩擦是阻力，只能使水平速度减小到零，不会使其反向；若算出的末速度变号，说明物块已提前相对地面静止","do":"对接触过程水平方向列动量定理，求出末水平速度，若结果为负则取零","expr":"-\\mu N\\Delta t=mv_x'-mv_x,\\quad I_N=N\\Delta t","cues":["摩擦只能减速","算出来是负的就取零","不会反向运动"],"concepts":["滑动摩擦力","动量定理","临界判断"]}],"367":[{"title":"恒流源下安培力做功","type":"模型选择","judge":"判断调控系统提供的是恒定电流而非恒定电压，因而安培力大小恒定、可用功的定义直接求加速效果","why":"题设明确给出 1000 A 恒定电流，安培力 F=BIL 与速度无关，才能用 Fx 求功；若误当恒压源，安培力随速度变化，无法用简单功式","do":"写出安培力 F=BI₀L，对 a（或 a+b 整体）用动能定理 BI₀Lx=½mv²","expr":"$BI_0Lx=\\frac12 mv^2$","cues":["恒流源","安培力不变","用动能定理"],"concepts":["安培力","恒定电流","动能定理"]},{"title":"碰撞与分离用动量能量","type":"关系建立","judge":"判断碰撞和分离过程时间极短、可忽略安培力冲量，从而用动量守恒加能量守恒（含弹性势能）处理","why":"碰撞、分离时间极短，外力冲量可忽略；题设说明损失动能全部储存为弹性势能、后又全部释放，故须同时列动量守恒和能量守恒","do":"对正碰列 m_a v_a=(m_a+m_b)v共 与 ½m_a v_a²=½(m_a+m_b)v共²+E_p；对分离列 (m_a+m_b)v共1=m_a v_a1+m_b v_b1 与 ½(m_a+m_b)v共1²+E_p=½m_a v_a1²+½m_b v_b1²","expr":"$m_av_a=(m_a+m_b)v_{\\text{共}},\\quad \\frac12m_av_a^2=\\frac12(m_a+m_b)v_{\\text{共}}^2+E_p$","cues":["时间极短","动量守恒","势能储存再释放"],"concepts":["动量守恒","能量守恒","弹性势能"]},{"title":"分段求位移与时间","type":"关系建立","judge":"判断碰撞前 a 单独加速、碰撞后 a+b 整体加速，两段加速度不同，须分段求位移与时间","why":"碰撞前后质量由 m_a 变为 m_a+m_b，加速度不同；题给初始间距 1.25 m 和 MM′到 NN′ 的 5 m，必须分清哪段对应哪个位移","do":"碰撞前用 x_ab 求 v_a，碰撞后用 x_MN−x_ab 求 v共1，再分别用平均速度求 t₁、t₂","expr":"$x_{ab}=\\frac{v_a}{2}t_1,\\quad x_{MN}-x_{ab}=\\frac{v_{\\text{共}}+v_{\\text{共}1}}{2}t_2$","cues":["分两段","质量变了","平均速度求时间"],"concepts":["匀变速直线运动","平均速度"]},{"title":"电荷量求电压降","type":"关系建立","judge":"判断电容器电压减小量应由流出的总电荷量 Δq=I₀(t₁+t₂) 除以电容求得，而非用某时刻电流","why":"恒流源放电，电压降由 ΔU=Δq/C 决定；总电荷量等于恒定电流乘总时间，需把两段时间都算上","do":"求 t₁+t₂，算 Δq=I₀(t₁+t₂)，再算 ΔU=Δq/C","expr":"$\\Delta U=\\frac{I_0(t_1+t_2)}{C}$","cues":["总电荷量","两段时间都要","除以电容"],"concepts":["电容","电荷量","电压"]},{"title":"变阻力用动能定理积分","type":"数学处理","judge":"判断阻力 f=kv² 随速度变化，不能直接用匀变速公式，须用 a=v dv/dx 或动能定理对位移积分","why":"阻力是速度的函数，加速度不恒定；只有把 kv² 对位移积分才能求末速度","do":"对整体列 (BI₀L−kv²)=(m_a+m_b)v dv/dx，分离变量积分求 v共2","expr":"$(BI_0L-kv^2)=(m_a+m_b)v\\frac{dv}{dx}$","cues":["阻力随速度变","不能匀变速","对位移积分"],"concepts":["变力做功","动能定理","分离变量"]},{"title":"比较比值下结论","type":"结论整理","judge":"判断是否达到 99% 需用 v共2/v共1 与 0.99 比较，而非直接比较速度差","why":"题目问的是相对（2）问分离前速度的百分比，须作比值判断","do":"算 v共2=√392.64，求 v共2/v共1 与 0.99 比较","expr":"$\\frac{v_{\\text{共}2}}{v_{\\text{共}1}}\\approx 99.05\\%$","cues":["算比值","和99%比","看百分比"],"concepts":["比值","百分数"]}],"368":[{"title":"绳偏方向定加速度方向","type":"模型选择","judge":"由轻绳向左偏还是向右偏，判断零件加速度的水平方向","why":"忽略空气阻力时零件只受重力和绳拉力，合力必沿绳偏斜的水平方向，绳的偏斜方向就是加速度方向","do":"对零件画受力图，看绳与竖直方向的夹角偏向哪一侧，确定合力水平指向哪边","expr":"","cues":["看绳往哪偏","合力沿绳的水平分量"],"concepts":["受力分析","牛顿第二定律","合力方向"]},{"title":"水平直线运动判竖直平衡","type":"关系建立","judge":"零件沿水平方向做直线运动时，竖直方向是否处于平衡","why":"零件相对无人机静止且无人机水平飞行，零件无竖直分运动也无竖直加速度，竖直方向合力为零","do":"把合力分解到竖直方向，令竖直合力为零，得拉力竖直分量等于重力","expr":"$T\\cos\\theta=mg$","cues":["竖直方向没动","竖直合力为零"],"concepts":["运动的分解","平衡条件"]},{"title":"由偏角推水平加速度","type":"关系建立","judge":"用绳偏角把水平合力与重力联系起来，判断加速度大小和方向","why":"水平方向只有拉力的水平分量提供加速度，与竖直平衡式联立才能定量确定加速度","do":"写水平方向牛顿第二定律，与竖直平衡式相除消去拉力","expr":"$ma=T\\sin\\theta,\\ a=g\\tan\\theta$","cues":["水平分量提供加速度","两式相除消拉力"],"concepts":["牛顿第二定律","加速度分解"]},{"title":"区分速度方向与加速度方向","type":"前提判断","judge":"绳偏斜只说明加速度方向，能否据此断定速度方向或速度在增大","why":"加速度与速度无必然同向关系，题设只说向左飞行，未给速度变化信息，不能由加速度方向推出速度方向或速率变化","do":"比较加速度方向与已知运动方向（向左），判断是加速还是减速需知速度方向与加速度是否同向，题中信息不足","expr":"","cues":["可能加速也可能减速","加速度与速度","匀变速直线运动"],"concepts":["加速度与速度","匀变速直线运动"]},{"title":"惯性只由质量决定","type":"结论整理","judge":"零件惯性大小是否随运动状态或速度改变","why":"惯性是物体保持原有运动状态的性质，量度只有质量，与速度、加速度无关","do":"比较运动前后质量是否变化，质量不变则惯性不变","expr":"","cues":["惯性只看质量","速度变了惯性不变"],"concepts":["惯性","质量"]}],"369":[{"title":"入射点法线方向","type":"几何关系","judge":"顶点处的法线是沿半径方向（竖直方向），还是沿切面方向","why":"圆柱表面法线过圆心，顶点处法线竖直；入射角是光线与法线的夹角，不是与表面的夹角","do":"在顶点画过圆心的竖直法线，量出光线与它的夹角作为入射角","expr":"i_1=45^\\circ","cues":["法线竖直","过圆心","与竖直夹角"],"concepts":["法线","入射角"]},{"title":"界面折射定律","type":"关系建立","judge":"用折射定律联系入射角、折射角与折射率，判断光进入玻璃后偏折方向","why":"光从空气进入折射率更大的介质，折射角小于入射角，须用 n=sin i/sin r 求折射角","do":"对顶点入射面列折射定律，由 n=√2、入射角 45° 求折射角","expr":"n=\\frac{\\sin 45^\\circ}{\\sin\\theta}","cues":["折射定律","空气进玻璃","折射角变小"],"concepts":["折射定律","折射率"]},{"title":"内部光路与出射点","type":"几何关系","judge":"光在圆柱内沿直线传播，出射点处的法线方向及出射入射角与入射折射角的关系","why":"圆柱内光线为直线，出射点法线仍沿半径；由等腰三角形（两半径相等）可得出射入射角等于入射折射角","do":"画出射点法线，利用三角形两半径相等，判断出射入射角 i=θ","expr":"i=\\theta=30^\\circ","cues":["半径相等","等腰三角形","出射入射角"],"concepts":["光路可逆","等腰三角形"]},{"title":"出射折射与方向合成","type":"数学处理","judge":"出射折射角相对法线的偏折，以及法线与竖直方向的夹角，如何合成得到与竖直的夹角","why":"出射时从玻璃到空气折射角大于入射角；所求角是出射光线与竖直方向的夹角，须由法线倾角减去折射角","do":"对出射面列折射定律求 r，再求法线与竖直夹角 α=θ+i，最后作差 β=α−r","expr":"n=\\frac{\\sin r}{\\sin i},\\ \\alpha=\\theta+i,\\ \\beta=\\alpha-r","cues":["玻璃出空气","法线倾斜","角度相减"],"concepts":["折射定律","角度几何关系"]}],"370":[{"title":"选定中心天体与环绕天体","type":"模型选择","judge":"判断引力来源是母恒星对行星，而不是行星对恒星或太阳对地球","why":"行星做匀速圆周运动的向心力由母恒星的万有引力提供，中心天体质量必须取母恒星质量","do":"把母恒星放在圆心，行星为环绕体，写出万有引力等于向心力的方程","expr":"\\frac{GMm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["恒星在圆心","引力来自母恒星"],"concepts":["万有引力","匀速圆周运动"]},{"title":"用地球作比较基准","type":"前提判断","judge":"判断需要借助地球绕太阳的已知周期和轨道半径来消去常量","why":"题目只给比值，没有给G和绝对质量，必须用地球—太阳系统作参照才能求出绝对周期","do":"对地球绕太阳写同一形式的方程，与行星方程相除","expr":"\\frac{GM_0m}{r_0^{2}}=m\\frac{4\\pi^{2}}{T_0^{2}}r_0","cues":["拿地球比","用365天"],"concepts":["参考系","周期"]},{"title":"导出周期与半径质量关系","type":"关系建立","judge":"判断周期平方与轨道半径三次方成正比、与中心天体质量成反比","why":"由万有引力提供向心力整理可得T²∝r³/M，这是开普勒第三定律的推广形式","do":"将两式相除，消去G和4π²，得到T与T₀的比值表达式","expr":"\\frac{T^{2}}{T_{0}^{2}}=\\frac{r^{3}M_{0}}{r_{0}^{3}M}","cues":["半径三次方","质量反比"],"concepts":["开普勒第三定律","万有引力定律"]},{"title":"代入比值开方求周期","type":"数学处理","judge":"判断半径比取1/14、质量比取2/7，并正确开平方","why":"比值代入后T²/T₀²=(1/14)³·(7/2)，开方得1/28，才能得到天数","do":"把r/r₀=1/14、M/M₀=2/7代入比值式，开方后乘365天","expr":"T=\\sqrt{\\frac{(1/14)^{3}}{2/7}}\\,T_0=\\frac{T_0}{28}\\approx13\\ \\text{天}","cues":["先算比值","再开根号"],"concepts":["比值运算","开平方"]}],"371":[{"title":"判断哪种核素可视为不衰变","type":"近似条件","judge":"106 天这段时间里，两种核素各自能否用半衰期公式算出明显变化，哪一种的衰变可以忽略","why":"铍10 半衰期约 139 万年，106 天只占其半衰期的极小比例，衰变个数可忽略；铍7 半衰期 53 天，106 天正好是两个半衰期，必须计入","do":"把 106 天分别与 53 天、139 万年比较，判断铍7 经历两个半衰期、铍10 几乎不变","expr":"","cues":["铍10几乎不衰变","铍7过了两个半衰期","先比半衰期"],"concepts":["半衰期","放射性衰变"]},{"title":"写出剩余原子数表达式","type":"关系建立","judge":"经过 106 天后，铍7 和铍10 各自的剩余原子数分别怎样用初始个数表示","why":"半衰期公式 N=N0(1/2)^(t/T) 对铍7 取 t/T=2，对铍10 取 t/T≈0 即近似不变","do":"设初始铍7 为 x、铍10 为 y，分别写出 106 天后的剩余个数","expr":"$x\\left(\\frac12\\right)^{2}+y$","cues":["设两个未知数","铍7剩四分之一","铍10原样保留"],"concepts":["半衰期公式","衰变规律"]},{"title":"用总量比建立方程","type":"关系建立","judge":"题目给的“总原子个数变为原来的 3/4”对应的是衰变后总数与初始总数的比，如何把这个条件写成方程","why":"总量比同时含 x 和 y，是唯一能把两个未知数联系起来的条件，只算铍7 的剩余量无法定出比值","do":"用衰变后总数除以初始总数 x+y，令其等于 3/4","expr":"$\\frac{x/4+y}{x+y}=\\frac34$","cues":["总数比是四分之三","分子是剩余总数","分母是初始总数"],"concepts":["总量守恒","比例关系"]},{"title":"解比值并核对选项","type":"数学处理","judge":"由方程解出的 x/y 是否与某个选项吻合，且数值是否合理（铍7 应少于铍10）","why":"铍7 衰变快、剩余少，初始量必须比铍10 少才能让总量只降到 3/4，解出的比值应小于 1","do":"化简方程求出 x 与 y 的比，与四个选项对照","expr":"$\\frac{x}{y}=\\frac12$","cues":["解出是一比二","铍7应该更少","对照选项"],"concepts":["方程求解","比值"]}],"372":[{"title":"碰撞瞬间动量守恒","type":"模型选择","judge":"碰撞时间极短、无外力冲量，能否对每次碰撞单独用动量守恒","why":"碰撞极短时外力冲量可忽略，系统动量守恒，这是比较质量大小的唯一依据","do":"对 P 与 N、Q 与 N 两次碰撞分别列动量守恒方程","expr":"m v + m_N v_N = m v' + m_N v_N'","cues":["碰撞极短","用动量守恒","外力冲量忽略"],"concepts":["动量守恒定律","碰撞"]},{"title":"把守恒式化为速度变化量","type":"关系建立","judge":"如何把守恒式整理成只含两车速度变化量的乘积关系","why":"质量比等于速度变化量之反比，只有化成变化量形式才能从图上直接读出大小","do":"移项整理成 m(Δv) = m_N(Δv_N) 的形式","expr":"m(v-v') = m_N(v_N'-v_N)","cues":["移项","看速度变化量","质量乘变化量"],"concepts":["动量守恒","速度变化量"]},{"title":"从 v-t 图读速度变化量","type":"图像读取","judge":"在 v-t 图上碰撞前后两段水平线的高度差，分别对应哪辆车的速度变化量","why":"v-t 图中碰撞前后速度是两段水平线，其纵坐标差即速度变化量的大小","do":"分别读出 P、Q 与 N 碰撞前后的速度值，比较各自变化量的大小","expr":"","cues":["看纵坐标差","前后两段水平线","读初末速度"],"concepts":["v-t 图像","速度变化量"]},{"title":"由变化量大小反推质量","type":"结论整理","judge":"速度变化量大的那辆车质量小还是大","why":"动量守恒要求 mΔv 相等，故 Δv 越大对应质量越小","do":"比较 P 与 N 的变化量得 m_P 与 m_N 的大小，再比较 Q 与 N 的变化量得 m_Q 与 m_N 的大小，最后排序","expr":"m_N > m_P,\\ m_Q > m_N","cues":["变化大的质量小","反比关系","排个序"],"concepts":["动量守恒","质量比较"]}],"373":[{"title":"波速由介质决定","type":"前提判断","judge":"同一介质中不同频率的声波，传播速度是否相同","why":"声速只由介质（及温度等）决定，与频率无关，这是比较波长和跨介质波长变化的前提","do":"确认 A5 与 D6 都在空气中传播，取相同的 v 作为比较基准","expr":"v_{A_5}=v_{D_6}=v","cues":["速度都一样","声速看介质","跟频率无关"],"concepts":["声速","介质"]},{"title":"波长与频率反比","type":"关系建立","judge":"频率不同的两个音，波长大小关系如何","why":"由波速公式 v=λf，v 相同时 λ 与 f 成反比，频率低的波长大","do":"比较 880 Hz 与 1175 Hz，用 λ=v/f 判断哪个波长更长","expr":"\\lambda=\\frac{v}{f}","cues":["频率低波长长","用波速公式","反比关系"],"concepts":["波长","频率","波速公式"]},{"title":"跨介质频率不变","type":"前提判断","judge":"声波从空气进入水中，频率是否改变","why":"频率由声源振动决定，与介质无关；只有波速和波长随介质改变","do":"确定进入水中后仍用原频率 f 计算新波长","expr":"f'=f","cues":["频率不变","频率看声源","只变速度"],"concepts":["频率","介质"]},{"title":"波长改变量比较","type":"关系建立","judge":"两种介质中波长之差与频率是什么关系","why":"Δλ=(v'-v)/f，速度差相同，故 Δλ 与 f 成反比，频率越小改变量越大","do":"写出 Δλ 表达式，比较 880 Hz 与 1175 Hz 对应的 Δλ 大小","expr":"\\Delta\\lambda=\\frac{v'-v}{f}","cues":["改变量看频率","低频改变大","速度差一样"],"concepts":["波长变化","频率"]}],"374":[{"title":"零加速度的受力含义","type":"前提判断","judge":"镜头处于零加速度状态时，是合力为零还是只需线圈安培力抵消某个力","why":"镜头随手机框架一起运动，框架有加速度 a 时，镜头要相对框架静止就必须获得与框架相同的加速度，因此线圈安培力要补上 ma 这一项，等效为安培力与框架对镜头的弹力等大反向","do":"把镜头隔离，写出合力等于 ma 的方程，明确安培力要抵消的是框架通过弹簧传给镜头的作用力","expr":"\\vec F_{\\text{安}}+\\vec F_{\\text{弹}}=m\\vec a,\\quad \\vec F_{\\text{安}}=-\\vec F_{\\text{弹}}","cues":["合力为零","跟着手机一起加速","安培力抵消弹力"],"concepts":["牛顿第二定律","受力分析","惯性"]},{"title":"安培力方向由电流定","type":"关系建立","judge":"已知线圈中电流的绕向和磁场方向，判断该线圈所受安培力指向哪一侧","why":"磁场垂直纸面向里，线圈处在磁场中的一段导线电流方向决定安培力方向，用左手定则判断，且 c、d 两线圈所在磁场相同、绕向相同则受力方向规律相同","do":"对 c、d 分别取处在磁场中的那段导线，用左手定则定出受力方向，再与框架加速度方向对应","expr":"\\vec F=BI\\vec l\\times\\vec B","cues":["左手定则","看磁场里那段导线","顺时针还是逆时针"],"concepts":["安培力","左手定则","磁场方向"]},{"title":"两线圈受力正交分解","type":"几何关系","judge":"a 斜向时，c 只提供水平力、d 只提供竖直力，如何把 a 的两个分量分配给两个线圈","why":"c 固定在右侧、d 固定在上侧，两线圈安培力方向互相垂直，因此水平分量只能由 c 承担、竖直分量只能由 d 承担，再由分量大小比较两电流大小","do":"把 a 分解为水平和竖直分量，令 c 的安培力对应水平分量、d 的安培力对应竖直分量，比较两分量大小","expr":"F_c=ma_x,\\quad F_d=ma_y,\\quad F=BIl\\Rightarrow I\\propto F","cues":["水平靠c竖直靠d","分解加速度","谁的分量大谁电流大"],"concepts":["正交分解","安培力","分力与合力"]},{"title":"斜向加速度的偏向定大小","type":"临界条件","judge":"a 偏上 30° 时，是水平分量大还是竖直分量大，从而判断两电流的大小关系","why":"30° 的偏向决定 a 在两坐标轴上的投影谁大谁小，投影大的那个线圈必须提供更大的安培力，也就需要更大的电流","do":"比较 a 的水平分量与竖直分量（或与 45° 比较），得出对应线圈电流的大小关系","expr":"a_x=a\\cos30^\\circ>a_y=a\\sin30^\\circ","cues":["偏上三十度","水平分量更大","和四十五度比"],"concepts":["矢量分解","三角函数","安培力大小"]},{"title":"由受力方向反推电流绕向","type":"结论整理","judge":"由所需安培力方向反推每个线圈的电流绕向，并核对两线圈绕向是否一致","why":"同一磁场下，安培力方向相反意味着电流绕向相反；安培力方向相同则绕向相同，这是判断选项电流方向说法的依据","do":"先定所需安培力方向，再用左手定则反推顺时针或逆时针，逐项核对电流方向与大小关系","expr":"","cues":["反推电流方向","一个顺一个逆","绕向相同还是相反"],"concepts":["左手定则","安培力方向","电流方向"]}],"375":[{"title":"两侧初始压强相等","type":"前提判断","judge":"能否由活塞 P 无摩擦且平衡，判定左右两部分气体压强始终相等","why":"P 是自由活塞且无摩擦，水平方向只受两侧气体压力，平衡即要求两侧压强相等；这是后续所有比较的基准","do":"对活塞 P 列水平方向受力平衡，得出 p1=p2=p","expr":"p_1=p_2=p","cues":["活塞无摩擦","两边压强一样","先定压强相等"],"concepts":["活塞平衡","压强","无摩擦"]},{"title":"等容假设定移动方向","type":"模型选择","judge":"升温时先假设 P 不动，比较两侧压强增量大小，从而判断 P 向哪侧移动","why":"直接判断移动方向困难，用等容假设把问题化为比较 Δp；Δp 大的一侧膨胀推动活塞","do":"设 P 不动，对两侧分别用等容过程 p/T=Δp/ΔT，比较 Δp1 与 Δp2","expr":"\\Delta p=\\frac{p}{T}\\Delta T","cues":["先假设不动","比压强增量","谁增得多往哪走"],"concepts":["等容过程","查理定律","压强增量"]},{"title":"温度低者压强增量大","type":"关系建立","judge":"在 p 相同、ΔT 相同的条件下，判断 T 小的一侧 Δp 更大","why":"Δp=pΔT/T，p、ΔT 相同时 Δp 与 T 成反比，T1<T2 故左侧增量大","do":"比较 Δp1=pΔT/T1 与 Δp2=pΔT/T2 的大小","expr":"\\Delta p_1=\\frac{p\\Delta T}{T_1}>\\Delta p_2=\\frac{p\\Delta T}{T_2}","cues":["温度低的涨得快","分母小增量大","左边压强涨得多"],"concepts":["正比反比关系","等容变化"]},{"title":"等温移动比较压强","type":"关系建立","judge":"保持温度不变、让 P 向某侧移动相同距离时，判断哪侧压强变得更大","why":"需用 pV/T=C 把压强写成体积的函数，再比较相同体积改变量下两侧压强的大小，才能判断活塞受力方向","do":"由 pV/T=C 写出 p=CT/V，对两侧取相同 ΔV，比较 p1 与 p2","expr":"p=\\frac{CT}{V},\\quad \\frac{V_1}{C_1T_1}=\\frac{V_2}{C_2T_2}","cues":["等温看体积","压强写成体积函数","比相同体积变化"],"concepts":["等温过程","玻意耳定律","状态方程"]},{"title":"体积小者压强变化敏感","type":"数学处理","judge":"判断相同 ΔV 下，初始体积小的一侧压强变化更剧烈","why":"p∝1/V，V 越小同样的 ΔV 引起的相对变化越大，故左侧压强升得更多，把 P 推向右","do":"比较 CT/(V1-ΔV) 与 CT/(V2-ΔV)，结合 V1<V2 定出大小","expr":"\\frac{C_1T_1}{V_1-\\Delta V}>\\frac{C_2T_2}{V_2-\\Delta V}","cues":["体积小的更敏感","分母小压强大","左边压强更大"],"concepts":["反比关系","体积变化率"]}],"376":[{"title":"判断曲线是否线性","type":"图像读取","judge":"图(a)中阻值随温度变化的图线是不是一条直线","why":"线性要求阻值与温度成正比，图线必须是直线；曲线说明变化率随温度改变","do":"观察图(a)中图线的弯曲情况，看它是否偏离直线","expr":"","cues":["看是不是直线","图线弯的","不成正比"],"concepts":["线性关系","图像法"]},{"title":"温度升高阻值变小","type":"前提判断","judge":"热敏电阻是正温度系数还是负温度系数","why":"只有先确定阻值随温度升高而减小，才能推出控制电路电流随温度的变化方向","do":"从图(a)读出温度升高时阻值的变化趋势","expr":"","cues":["温度高阻值小","负温度系数","先看阻值怎么变"],"concepts":["热敏电阻","温度系数"]},{"title":"电流大小决定衔铁位置","type":"关系建立","judge":"温度升高使电流增大后，衔铁吸向哪一侧触头","why":"电磁铁磁力随线圈电流增大而增强，电流超过 I0 时吸下衔铁与 b 接触","do":"由欧姆定律把阻值减小转化为电流增大，再对应题干给出的 I0 分界","expr":"I=\\frac{E}{R_{\\text{总}}}","cues":["电流大吸下来","超过I0接b","先看电流方向"],"concepts":["欧姆定律","电磁铁"]},{"title":"加热丝接常闭触头","type":"临界条件","judge":"温度达到设定值、衔铁吸向 b 时，加热电路应断开还是接通","why":"温度已达设定值需停止加热，故加热丝必须接在衔铁离开时闭合的触头 a 上","do":"比较衔铁在上、下两个位置时 c 端与 a、b 的通断状态，选出“高温断开”的接法","expr":"","cues":["高温要断电","接常闭那个","衔铁抬起才加热"],"concepts":["继电器","自动控制"]},{"title":"电阻箱读数","type":"数据处理","judge":"图(c)旋钮示数对应各挡位的倍率与数字","why":"电阻箱示数等于各旋钮示数乘以对应倍率之和","do":"读出各旋钮所指数字，按百、十、个位倍率相加","expr":"R=100\\times1+10\\times3+1\\times0","cues":["看旋钮倍率","百位十位相加","别漏了零"],"concepts":["电阻箱读数"]},{"title":"控制电流不变定总电阻","type":"模型选择","judge":"改变设定温度时，控制电路在动作瞬间的哪个量保持不变","why":"衔铁动作由同一电流 I0 触发，故动作时控制电路总电阻恒定，温度改变只能靠调节电阻箱补偿热敏电阻的变化","do":"由 50 ℃ 时的热敏电阻值与电阻箱值求总电阻，再减去 100 ℃ 时的热敏电阻值","expr":"R_{\\text{箱}}'=R_T(50)+R_{\\text{箱}}-R_T(100)","cues":["动作电流不变","总电阻不变","用差值补"],"concepts":["闭合电路欧姆定律","等效替代"]}],"377":[{"title":"步骤筛选与排序","type":"实验操作","judge":"哪些步骤是必需的、哪些可省（称质量），以及接通电源与释放纸带的先后顺序","why":"验证 mgh=½mv² 中质量 m 两边约去，无需测质量；先放纸带后通电会漏掉起始点、点迹稀疏，必须先打点后放纸带","do":"逐条核对每个步骤是否服务于原理且操作规范，剔除称质量一步，把剩余四步按'固定纸带—通电打点—断电取带—测量数据'排序","expr":"mgh=\\frac{1}{2}mv^{2}\\Rightarrow m\\text{可约去}","cues":["质量能约掉","先通电再放纸带","不用天平"],"concepts":["机械能守恒","实验步骤","打点计时器"]},{"title":"用平均速度求瞬时速度","type":"关系建立","judge":"B 点速度该用哪段位移和哪个时间间隔来算","why":"匀变速直线运动中某段时间内的平均速度等于中间时刻的瞬时速度，B 是 AC 的中间时刻","do":"从纸带读出 A、C 两点到起点的距离，取差值作为 AC 段位移，除以 2T（T=0.02 s）","expr":"v_{B}=\\frac{h_{AC}}{2T},\\quad T=\\frac{1}{f}=0.02\\,\\mathrm{s}","cues":["中间时刻速度","取前后两点","相邻间隔0.02秒"],"concepts":["匀变速直线运动","中间时刻瞬时速度","打点周期"]},{"title":"化曲为直看图像","type":"关系建立","judge":"v²-h 图理论上是否过原点、斜率对应什么物理量","why":"由 mgh=½mv² 得 v²=2gh，v² 与 h 成正比，h=0 时 v=0，故过原点，斜率即 2g","do":"把机械能守恒式改写为 v² 关于 h 的一次函数，对照 y=kx 形式读出截距与斜率","expr":"v^{2}=2gh,\\quad k=2g","cues":["化成一次函数","过原点","斜率是2g"],"concepts":["机械能守恒","图像斜率","线性化"]},{"title":"图像斜率读数","type":"图像读取","judge":"在 v²-h 图上取哪两点算斜率，取点是否落在直线（而非数据点）上","why":"斜率应由拟合直线的两个较远点求得以减小读数误差，取点太近会放大相对误差","do":"在直线上选相距较远的两点，读其坐标，用纵坐标差除以横坐标差","expr":"k=\\frac{\\Delta v^{2}}{\\Delta h}","cues":["取直线上的点","两点隔远些","纵差比横差"],"concepts":["图像斜率","有效数字","误差"]},{"title":"误差用斜率表达","type":"关系建立","judge":"相对误差 η 如何由实测斜率 k 与理论值 2g 表示","why":"Ep=mgh，Ek=½mv²=½m·kh，代入 η 定义后 m、h 约去，只剩 k 与 g","do":"把 v²=kh 代入 η 定义式，化简成只含 k、g 的式子，再代入 g=9.80 与实测 k 求百分数","expr":"\\eta=\\left|\\frac{mgh-\\frac{1}{2}mv^{2}}{mgh}\\right|=\\frac{2g-k}{2g}\\times100\\%","cues":["把动能换成斜率","质量和高度约掉","用2g减k"],"concepts":["相对误差","重力势能","动能"]}],"378":[{"title":"电场中运动模型","type":"模型选择","judge":"液滴进入极板间后，沿初速度方向和垂直初速度方向分别做什么运动","why":"初速度竖直、电场力水平且恒定，重力不计，两个方向互不影响，符合类平抛运动的成立条件","do":"把运动分解为竖直方向的匀速直线运动和水平方向的初速为零的匀加速直线运动","expr":"l=vt_1,\\quad x_1=\\frac12 at_1^2","cues":["类平抛","分两个方向","竖直匀速"],"concepts":["运动的分解","类平抛运动"]},{"title":"加速度由电场力定","type":"关系建立","judge":"水平方向的加速度由哪个力产生、用哪个定律求","why":"液滴只受水平电场力，重力不计，牛顿第二定律直接给出加速度","do":"写出电场力表达式并除以质量求加速度","expr":"qE=ma\\Rightarrow a=\\frac{qE}{m}","cues":["电场力提供加速度","不计重力","用牛二"],"concepts":["牛顿第二定律","电场力"]},{"title":"出电场后匀速","type":"前提判断","judge":"液滴离开极板区域后水平方向是否还继续加速","why":"极板外无电场，水平方向不再受力，水平分速度保持为出射时的值","do":"确认出电场后两方向均为匀速，水平位移用出射水平速度乘以下落时间","expr":"x_2=v_x t_2=at_1t_2","cues":["出电场不再加速","水平速度不变","匀速直线"],"concepts":["匀速直线运动","速度的分解"]},{"title":"竖直下落时间","type":"关系建立","judge":"极板下方这段竖直距离对应的时间用哪个速度算","why":"竖直方向始终匀速，速度恒为入射速度 v，与水平偏转无关","do":"用竖直距离除以入射速度求下落时间","expr":"h=vt_2","cues":["竖直速度不变","用入射速度","下落时间"],"concepts":["匀速直线运动","分运动的独立性"]},{"title":"正负电荷反向偏转","type":"结论整理","judge":"A、B 两液滴电荷符号相反，偏转方向如何、间距怎么合成","why":"电场方向水平向右，正电荷受力向右、负电荷受力向左，两者关于中轴线对称偏转","do":"先求单个液滴的总水平偏移，再由对称性把两侧偏移相加得间距","expr":"\\Delta x=2(x_1+x_2)","cues":["正负反向偏","关于中线对称","间距是两倍"],"concepts":["对称性","电荷受力方向"]}],"379":[{"title":"碰撞后P速度方向","type":"前提判断","judge":"碰撞后 P 的速度方向是向右还是向左，即取 +7 还是 -7 代入动量守恒","why":"P 原来静止，被向右运动的 Q 撞击，冲量向右，P 只能向右运动；若误取负号会得到完全不同的 Q 速度与损失能量","do":"由碰撞的冲量方向判定 P 碰后速度沿 Q 初速方向，取 v=+7 m/s 代入","expr":"v_P=+7\\ \\mathrm{m/s}","cues":["P被撞向右","取正号","方向跟Q一样"],"concepts":["动量守恒","冲量方向"]},{"title":"碰撞过程用动量守恒","type":"模型选择","judge":"碰撞时间极短、水平方向不受外力（防滑带摩擦在碰撞瞬间冲量可忽略），能否对 P、Q 系统用动量守恒","why":"碰撞极短时摩擦冲量趋于零，系统水平动量守恒；若把摩擦冲量算进去就无法求解","do":"对 P、Q 组成的系统沿水平方向列动量守恒式，求出碰后 Q 的速度","expr":"m_2v_0=m_2v_Q+m_1v","cues":["碰撞极短","摩擦来不及作用","取PQ系统"],"concepts":["动量守恒定律","碰撞"]},{"title":"损失机械能算差值","type":"关系建立","judge":"损失的机械能是碰前总动能减碰后总动能，而不是某一个物体的动能变化","why":"非弹性碰撞中系统动能减少量即损失机械能，必须用系统前后动能之差","do":"用碰前 Q 的动能减去碰后 P、Q 动能之和","expr":"\\Delta E=\\tfrac12m_2v_0^2-\\tfrac12m_2v_Q^2-\\tfrac12m_1v^2","cues":["前后动能差","系统总动能","别只看一个物块"],"concepts":["能量守恒","机械能损失"]},{"title":"分段判断P的运动","type":"模型选择","judge":"P 在防滑带上做匀减速、在光滑段做匀速，需逐段判断每段末速度是否减到零","why":"防滑带有摩擦、光滑段无摩擦，运动性质不同，不能整体用一个匀减速公式","do":"对每个防滑带用速度位移关系求末速度，对光滑段用匀速公式求时间，逐段推进直到速度为零","expr":"v_{k-1}^2-v_k^2=2\\mu g l_2,\\quad l_1=v_k t","cues":["防滑带减速","光滑段匀速","一段一段算"],"concepts":["牛顿第二定律","匀变速运动","分段处理"]},{"title":"判定停止所在防滑带","type":"临界条件","judge":"P 最终停在第几个防滑带上，需比较剩余动能能走的最大距离与各段长度","why":"只有先确定停止位置，才能知道最后一段减速时间算到哪，否则会多算或漏算一段","do":"依次算出经过第一、第二防滑带后的速度，用 v²/(2a) 与 l₂ 比较判断能否穿过下一个防滑带","expr":"s=\\frac{v_{P2}^2}{2\\mu g}<l_2","cues":["看能不能穿过","比一比滑行距离","停在第几块"],"concepts":["临界条件","匀减速停止"]},{"title":"总时间为各段之和","type":"结论整理","judge":"总时间是否等于各减速段与各匀速段时间之和，且最后一段只算到速度为零","why":"各段运动性质不同，时间必须分段累加；最后一段不能按整段防滑带长度算","do":"把各防滑带减速时间与各光滑段匀速时间相加","expr":"t=\\sum t_{\\text{减速}}+\\sum t_{\\text{匀速}}","cues":["分段加时间","最后只算到停下","别按整段算"],"concepts":["运动学公式","时间累加"]}],"380":[{"title":"磁场中半径的几何求法","type":"几何关系","judge":"由 a 点出射速度水平、进入电场时速度与虚线成 60°，能否用圆心到虚线的距离关系定出轨迹半径","why":"粒子在磁场中做匀速圆周运动，a 点速度水平说明 a 是轨迹上速度水平的位置，圆心必在 a 的正下方或正上方；进入电场点距虚线 h、速度方向 60°，这两个条件共同约束半径","do":"画出圆弧轨迹，找出圆心位置，把圆心到虚线的距离用 r 与 r cos60° 表示，与 h 建立方程","expr":"r = r\\cos 60^\\circ + h","cues":["画轨迹找圆心","速度水平说明切线水平","半径投影加高度"],"concepts":["洛伦兹力","匀速圆周运动","几何关系"]},{"title":"电场中运动的对称性","type":"前提判断","judge":"粒子在匀强电场中做类抛体运动，出电场时速度大小和方向是否与入射时对称","why":"电场竖直、粒子只受竖直恒力，水平分速度不变；竖直方向先减速到零再反向加速，回到同一虚线高度时竖直分速度大小不变、方向相反，故速度大小仍为 v0、与虚线夹角仍为 60°","do":"比较入射与出射的竖直分速度，确认速率不变、夹角大小不变，只是方向由右下变为右上","expr":"v_x=v_0\\cos60^\\circ,\\quad v_y\\to -v_y","cues":["水平分速度不变","竖直先减后加","出射角对称"],"concepts":["类平抛运动","运动的独立性","对称性"]},{"title":"水平位移拆分定电场时间","type":"关系建立","judge":"电场中水平位移应等于总距离 s 减去两段磁场中的水平偏移，而不是直接用 s","why":"s 是 a、b 两点间总水平距离，其中包含粒子在磁场中两段圆弧造成的水平位移 2r sin60°，只有剩余部分才是电场中的水平位移","do":"先算两段圆弧的水平投影 2r sin60°，从 s 中扣除得电场中水平位移，再除以水平分速度得时间","expr":"AB=s-2r\\sin60^\\circ,\\quad t=\\frac{AB}{v_0\\cos60^\\circ}","cues":["总距离要扣掉磁场段","水平分速度不变","先算圆弧水平投影"],"concepts":["位移分解","匀速直线运动"]},{"title":"竖直方向定电场强度","type":"关系建立","judge":"用电场中竖直分速度的变化（由 +v0 sin60° 变为 -v0 sin60°）配合时间求加速度，而不是用位移公式","why":"竖直方向只受电场力，加速度恒定；已知初末竖直分速度和时间，可直接由加速度定义式求 a，再由牛顿第二定律得 E，避免引入未知位移","do":"写出竖直方向速度关系 -v0 sin60° = v0 sin60° - at，解出 a，再由 qE = ma 求 E","expr":"-v_0\\sin60^\\circ=v_0\\sin60^\\circ-at,\\quad qE=ma","cues":["竖直方向用速度公式","加速度恒定","别用位移公式绕远"],"concepts":["匀变速直线运动","牛顿第二定律","电场力"]},{"title":"竖直下射时入射角的重判","type":"几何关系","judge":"改为竖直向下发射后，进入电场时速度与虚线的夹角是否仍为 60°","why":"速度大小仍为 v0，半径仍为 2h，但入射方向变了，圆弧对应的圆心角改变，进入电场点的位置和速度方向都要重新由几何关系确定，不能沿用第一问的角度","do":"以 a 点为切点、速度竖直向下定圆心，画圆弧到虚线，由半径与竖直方向夹角推出进入电场时速度与虚线的夹角","expr":"r=2h,\\quad \\alpha=60^\\circ","cues":["半径不变角度变","重新画圆","竖直向下是切线"],"concepts":["匀速圆周运动","几何关系"]},{"title":"一个周期的位移与时间","type":"结论整理","judge":"漂移速度要用一个完整周期内的净水平位移除以周期总时间，而不是只看电场段或只看磁场段","why":"粒子在磁场中走大圆弧、在电场中走类抛体，两者交替构成周期；净位移是各段水平位移的代数和，时间也是各段之和","do":"分别算出电场段时间与水平位移、磁场段圆弧时间与水平位移，求净位移与总时间之比","expr":"v'=\\frac{\\Delta x}{t_1+t_2},\\quad t_2=\\frac{360^\\circ-2\\alpha}{360^\\circ}\\cdot\\frac{2\\pi r}{v_0}","cues":["按一个周期算","磁场段走大圆弧","位移和时间都要累加"],"concepts":["周期性运动","漂移速度","圆周运动周期"]}],"381":[{"title":"确定反应前后核子数","type":"前提判断","judge":"反应方程中除 X 外各核的质量数是否已知、能否直接相加","why":"质量数守恒是求 X 质量数的唯一依据，必须先确认方程两边除 X 外各项的质量数","do":"列出 U-235、Ba-144、Kr-89 和 3 个中子的质量数","expr":"235 + A_X = 144 + 89 + 3\\times 1","cues":["先数质量数","看方程两边","中子算三个"],"concepts":["质量数守恒","核反应方程"]},{"title":"确定反应前后电荷数","type":"前提判断","judge":"反应方程中除 X 外各核的电荷数（原子序数）是否已知、能否直接相加","why":"电荷数守恒是求 X 电荷数的唯一依据，与质量数守恒并列使用","do":"列出 U 的 92、Ba 的 56、Kr 的 36 和中子的 0","expr":"92 + Z_X = 56 + 36 + 3\\times 0","cues":["再数电荷数","看原子序数","中子不带电"],"concepts":["电荷数守恒","原子序数"]},{"title":"联立两守恒定 X","type":"关系建立","judge":"由两个守恒式解出的质量数与电荷数组合对应哪种粒子","why":"只有同时满足质量数守恒和电荷数守恒的粒子才是方程中缺失的 X","do":"分别解出 A_X 与 Z_X，再对照粒子符号确定 X","expr":"A_X = 1,\\quad Z_X = 0 \\Rightarrow {}^{1}_{0}\\mathrm{n}","cues":["两个守恒一起用","解出质量数和电荷数","对照粒子表"],"concepts":["质量数守恒","电荷数守恒","中子"]},{"title":"排除只守一个守恒的项","type":"结论整理","judge":"干扰项是否只满足其中一个守恒式（如只对质量数或只对电荷数）","why":"核反应必须两个守恒同时成立，只满足其一的粒子不能使方程配平","do":"把各候选粒子的 A、Z 代入两式检验是否同时成立","expr":"","cues":["只对一半不行","两个都要对","配平才算数"],"concepts":["核反应配平","守恒定律"]}],"382":[{"title":"近球端感应异种电荷","type":"前提判断","judge":"带正电的球靠近时，靠近端的金属球 a 应带何种电荷","why":"静电感应中异种电荷相互吸引，自由电子被正球吸引向近端聚集，故近端显负电","do":"确定 a 球靠近正电球的一侧聚集电子，判断 a 球带负电","expr":"","cues":["近端异种","电子被吸过来","a球带负电"],"concepts":["静电感应","电荷间相互作用"]},{"title":"远端的电荷由守恒定","type":"关系建立","judge":"a 球带负电后，金属箔 b 与金属杆上的电荷正负如何确定","why":"验电器整体原本不带电，导体内部电荷守恒，近端多余负电荷必对应远端等量正电荷","do":"由电荷守恒推出 b 与金属杆带正电，与 a 的负电符号相反","expr":"q_a+q_b=0","cues":["原来不带电","电荷守恒","远端带正电"],"concepts":["电荷守恒定律","导体"]},{"title":"金属箔张开的判断","type":"结论整理","judge":"b 与金属杆带同种电荷后金属箔是否张开","why":"两片金属箔带同种电荷相互排斥，才会张开，这是验电器显示带电的机制","do":"比较两片箔片所带电荷符号，同号则判断为张开","expr":"","cues":["同种相斥","箔片张开","验电器原理"],"concepts":["同种电荷相斥","验电器"]}],"383":[{"title":"读图定运动性质","type":"图像读取","judge":"v-t 图线的斜率正负与是否为零分别对应什么运动状态","why":"v-t 图像斜率表示加速度，斜率为零即加速度为零，速度不变","do":"把整段图线按 t1、t2、t3 分成三段，逐段看斜率是否为零、正负如何","expr":"a=\\dfrac{\\Delta v}{\\Delta t}","cues":["看斜率","斜率是加速度","平的那段匀速"],"concepts":["v-t 图像","加速度"]},{"title":"速度正负定方向","type":"前提判断","judge":"图线在时间轴上方还是下方，决定速度方向是否改变","why":"v-t 图中速度的正负直接表示运动方向，纵坐标始终为正说明一直同向行驶","do":"观察三段图线的纵坐标是否都在 t 轴同侧","expr":"","cues":["都在横轴上方","速度一直为正","方向没变"],"concepts":["速度方向","正方向约定"]},{"title":"加速度方向比较","type":"关系建立","judge":"减速段与加速段的加速度方向是否相同","why":"加速度方向由斜率正负决定，与速度正负无关，减速时 a 与 v 反向、加速时同向","do":"比较 0~t1 段斜率符号与 t2~t3 段斜率符号","expr":"a_{0\\sim t_1}<0,\\quad a_{t_2\\sim t_3}>0","cues":["减速加速度为负","加速加速度为正","两段方向相反"],"concepts":["加速度方向","匀变速直线运动"]}],"384":[{"title":"加速升空的方向判断","type":"前提判断","judge":"火箭加速上升时加速度方向朝哪，据此判断超重还是失重","why":"加速度向上则支持力大于重力，为超重；加速度向下才是失重","do":"看火箭速度增大且向上运动，确定加速度竖直向上，与重力方向相反","expr":"","cues":["加速向上","看加速度方向","向上就是超重"],"concepts":["超重与失重","加速度方向"]},{"title":"引力随高度变小","type":"关系建立","judge":"宇航员在轨道上受到的万有引力与在地表相比是变大还是变小","why":"万有引力与到地心距离的平方成反比，轨道高度使距离大于地球半径","do":"写出万有引力定律，比较轨道半径与地球半径的大小","expr":"F=\\frac{GMm}{r^{2}}","cues":["离地越远引力越小","比半径大小","平方反比"],"concepts":["万有引力定律","轨道半径"]},{"title":"轨道参量随半径变化","type":"关系建立","judge":"由引力提供向心力推出的角速度、加速度随轨道半径如何变化","why":"匀速圆周运动由万有引力提供向心力，半径越小角速度和向心加速度越大","do":"联立万有引力与向心力公式，消去质量得到角速度和加速度的表达式，再比较空间站与同步卫星的半径","expr":"\\frac{GMm}{r^{2}}=m\\omega^{2}r,\\quad \\frac{GMm}{r^{2}}=ma","cues":["引力提供向心力","半径小转得快","先写表达式再比"],"concepts":["万有引力提供向心力","角速度","向心加速度"]},{"title":"与同步卫星比半径","type":"临界条件","judge":"空间站轨道高度低于同步卫星，对应轨道半径谁大谁小","why":"题目给出的高度关系是判断各参量大小关系的唯一依据，半径大小决定结论方向","do":"把空间站高度与同步卫星高度比较，得出空间站轨道半径更小，再代入上一步的单调关系","expr":"r_{空间站}<r_{同步}","cues":["高度低半径小","跟同步卫星比","半径小的转得快"],"concepts":["同步卫星","轨道半径"]}],"385":[{"title":"读波长","type":"图像读取","judge":"从波形图上读出相邻同相点（波峰到波峰或平衡点同向过零点）的水平距离，判断波长是多少","why":"波长由波形图直接给出，是后续求波速的必要量，读错则波速全错","do":"在实线（或虚线）上找相邻两个波峰（或相邻两个同向过平衡位置的点），量出横坐标差","expr":"\\lambda = 10\\,\\mathrm{cm}","cues":["看波峰间距","相邻同相点","横轴一格多少"],"concepts":["波长","波形图"]},{"title":"定平移量与周期关系","type":"关系建立","judge":"判断 0.5 s 内波形沿 +x 方向平移了多少个波长，从而把 Δt 写成 nT 加一个分数周期","why":"波沿 +x 传播，实线到虚线是波形整体右移，平移量必须用周期性写成 nT+分数T 的通式，否则无法与 T>0.5 s 联立","do":"比较实线与虚线同一相位点（如波峰）右移的距离，看它占几个波长，写成 Δt 与 T 的通式","expr":"\\Delta t = nT + \\tfrac{3}{4}T,\\ n=0,1,2\\ldots","cues":["波形右移了多少","平移四分之三波长","加整周期"],"concepts":["波的传播","周期性","波形平移"]},{"title":"用周期条件定 n","type":"临界条件","judge":"由 T>0.5 s 判断通式中 n 能取哪些值","why":"T>0.5 s 意味着 0.5 s 内波传播不足一个完整周期还多，只有 n=0 时解出的 T 才满足该不等式","do":"把通式解成 T 关于 n 的表达式，代入 n=0,1,… 检验哪个满足 T>0.5 s","expr":"T=\\frac{0.5}{n+3/4}>0.5\\ \\Rightarrow\\ n=0,\\ T=\\tfrac{2}{3}\\,\\mathrm{s}","cues":["周期大于半秒","只能取零","多解要筛"],"concepts":["周期","多解性","不等式约束"]},{"title":"算波速","type":"数学处理","judge":"用波长和已定出的周期求波速","why":"波速由介质决定，数值上等于波长除以周期，周期定错则波速必错","do":"把 λ=10 cm 与 T=2/3 s 代入 v=λ/T","expr":"v=\\frac{\\lambda}{T}=\\frac{10}{2/3}=15\\,\\mathrm{cm/s}","cues":["波长除周期","单位用厘米每秒"],"concepts":["波速","波长","周期"]},{"title":"判质点振动方向","type":"模型选择","judge":"对 +x 传播的波，判断某质点此刻是向上还是向下振动","why":"质点振动方向由波传播方向和该点处波形斜率共同决定，需用同侧法（或上下坡法）而不是凭感觉","do":"在 t=0 的实线上找质点 M 的位置，看其左侧波形高低，用同侧法确定 M 的速度方向","expr":"","cues":["同侧法","看波形斜率","波向右传"],"concepts":["质点振动方向","同侧法","波的传播方向"]}],"386":[{"title":"斜率读场强","type":"图像读取","judge":"φ-x 图线的斜率对应什么物理量、正负号代表什么","why":"由 E=-dφ/dx，φ-x 图线斜率的绝对值等于场强大小，斜率正负决定场强沿 x 轴哪一侧","do":"比较 M、N 两点处图线斜率的绝对值与正负，判断两点场强大小是否相等、方向是否相同","expr":"E_x=-\\dfrac{\\Delta\\varphi}{\\Delta x}","cues":["看斜率","斜率就是场强","斜率的正负"],"concepts":["电势梯度","电场强度"]},{"title":"由电势定场强方向","type":"关系建立","judge":"正半轴上电势随 x 降低时，电场方向指向哪一侧","why":"电场线由高电势指向低电势，电势降低的方向就是场强方向","do":"观察 x>0 段 φ 随 x 增大而减小，据此定出该区域场强沿 +x 方向","expr":"","cues":["高电势指向低电势","顺着电势降","场强朝右"],"concepts":["电场线方向","电势高低"]},{"title":"电子受力与运动","type":"前提判断","judge":"电子带负电，在沿 +x 的场强中受到的电场力指向哪一侧，从 M 释放后向哪边运动","why":"负电荷受力方向与场强方向相反，初速度为零时沿受力方向加速","do":"由 M 点场强方向反推电子受力方向，确定电子向 P 一侧运动","expr":"\\vec F=q\\vec E,\\ q=-e","cues":["电子带负电","受力跟场强反向","往左走"],"concepts":["负电荷受力","电场力方向"]},{"title":"电势能比高低","type":"关系建立","judge":"电子在电势较高处还是较低处电势能更大","why":"E_p=qφ，电子 q<0，电势越低电势能越大","do":"比较 M 与 P、P 与 N 的电势高低，换算成电子电势能的大小关系","expr":"E_p=q\\varphi=-e\\varphi","cues":["负电荷反着来","电势低势能大","电子势能"],"concepts":["电势能","电荷正负"]},{"title":"能量守恒定动能","type":"关系建立","judge":"只有电场力做功时，动能变化与电势能变化如何互补","why":"仅受电场力，动能与电势能之和守恒，电势能减小则动能增大","do":"由 P、N 两点电势能大小关系推出两点动能大小关系","expr":"E_k+E_p=\\text{常量}","cues":["只有电场力做功","动能加势能不变","势能降动能升"],"concepts":["能量守恒","电场力做功"]}],"387":[{"title":"判断哪个是光敏电阻","type":"前提判断","judge":"R1 与 R2 中哪一个接在 1、2 之间、哪一个才是光敏电阻","why":"光敏电阻阻值随照度降低而增大，只有把它接在 1、2 之间，照度降低时 1、2 电压才会升高到 2 V 触发开关；若光敏电阻接在另一端，照度降低时 1、2 电压反而下降，与题设矛盾","do":"分别假设 R1 或 R2 为光敏电阻，看照度降低时 1、2 间电压的变化方向，取与“升至 2 V”一致的那种","expr":"","cues":["先看电压怎么变","光敏电阻放哪边","照度低阻值大"],"concepts":["光敏电阻","串联分压"]},{"title":"用分压比定阻值","type":"关系建立","judge":"照度 1.0 lx 时 1、2 电压为 2 V，如何由总电压 3 V 求出两电阻的比值","why":"两电阻串联，电压按阻值正比分配，1、2 两端电压 2 V 对应光敏电阻 20 kΩ，剩余 1 V 对应另一个电阻","do":"由 U1:U2 = R1:R2 列比例，代入 2 V 与 1 V 及 20 kΩ 求另一电阻","expr":"\\frac{R_1}{R_2}=\\frac{U_1}{U_2}=\\frac{2}{3-2}","cues":["串联分压","电压比等于电阻比","剩下1伏"],"concepts":["串联电路","分压原理"]},{"title":"核对阻值随照度单调性","type":"结论整理","judge":"所得定值电阻的阻值是否与表格中光敏电阻随照度变化的趋势自洽","why":"定值电阻阻值不随照度改变，而光敏电阻在照度低于 1.0 lx 时阻值应大于 20 kΩ，才能保证电压继续升高触发开关","do":"把求出的定值电阻与表格中 0.6、0.8 lx 对应的 28、23 kΩ 比较，确认照度更低时光敏电阻更大、分压更高","expr":"","cues":["定值的不变","照度低阻值更大","电压还会升"],"concepts":["定值电阻","照度与阻值关系"]}],"388":[{"title":"选整体为研究对象","type":"模型选择","judge":"是取 P、Q 加轻绳作为整体，还是分别对单个球受力分析","why":"两球都套在光滑圆环上，环对球的支持力沿半径方向、通过圆心，对圆心不产生力矩；绳的拉力是内力，取整体后自动消去，只剩两个重力的力矩","do":"把 P、Q 和轻绳看成一个系统，以圆弧圆心为支点考察力矩平衡","expr":"","cues":["取整体","支点选圆心","绳力是内力"],"concepts":["整体法","力矩平衡","内力"]},{"title":"支持力过心无力矩","type":"前提判断","judge":"环对球的支持力方向是否沿半径、其力矩是否为零","why":"光滑圆环只能提供沿半径方向的支持力，作用线通过圆心，对圆心的力臂为零，因此整体力矩方程中不出现支持力","do":"确认支持力沿半径指向或背离圆心，力臂为零，从力矩方程中剔除","expr":"","cues":["支持力沿半径","力臂为零","光滑无摩擦"],"concepts":["弹力方向","力臂"]},{"title":"重力力臂取余弦","type":"几何关系","judge":"两球重力对圆心的力臂应取 R cos30° 还是 R sin30°","why":"力臂是圆心到重力作用线（竖直直线）的垂直距离，角度是半径与竖直方向的夹角，故力臂为 R 乘该角的余弦","do":"过圆心作竖直线，量出半径与竖直方向夹角，写出力臂 R cos30° 与 R cos60°","expr":"L_P=R\\cos30^\\circ,\\quad L_Q=R\\cos60^\\circ","cues":["力臂是水平距离","角度从竖直量起","取余弦"],"concepts":["力臂","几何关系"]},{"title":"力矩平衡列方程","type":"关系建立","judge":"两球重力对圆心的力矩应相等（同向转动趋势相互抵消）","why":"整体处于平衡，两重力对圆心一个顺时针、一个逆时针，力矩大小相等；半径 R 相同可约去","do":"令 m_P g R cos30° = m_Q g R cos60°，约去 gR 后求质量比","expr":"m_P gR\\cos30^\\circ=m_Q gR\\cos60^\\circ","cues":["力矩相等","半径约掉","一顺一逆"],"concepts":["力矩平衡","重力矩"]},{"title":"绳与半径夹角判断","type":"几何关系","judge":"若改用隔离法，绳与半径的夹角是否为 45°","why":"两球所在半径夹角为 30°+60°=90°，弦与两半径构成等腰直角三角形，弦与每条半径的夹角均为 45°，这是隔离法分解拉力时的关键角","do":"连接 P、Q 得弦，由等腰直角三角形得出绳与半径夹角 45°，再沿垂直半径方向分解","expr":"\\theta=\\frac{180^\\circ-90^\\circ}{2}=45^\\circ","cues":["弦是等腰直角边","夹角四十五度","垂直半径分解"],"concepts":["等腰直角三角形","拉力分解"]}],"389":[{"title":"区分折射与全反射","type":"前提判断","judge":"海市蜃楼是光在不均匀大气中折射形成的虚像，还是全反射形成的","why":"蜃楼由不同高度空气密度不同导致光线连续折射，属于折射现象而非全反射，误判为全反射就会错选","do":"比较海市蜃楼与全反射的成因，确认是密度不均匀引起的连续折射","expr":"","cues":["密度不均匀","连续折射","不是全反射"],"concepts":["折射","全反射","不均匀介质"]},{"title":"光电效应判粒子性","type":"结论整理","judge":"光电效应说明光具有粒子性还是波动性","why":"光电效应中光子把能量交给电子，体现光的粒子性，这是判断该项正误的唯一依据","do":"由光电效应的物理本质直接对应光的粒子性","expr":"","cues":["光子打出电子","体现粒子性","不是波动性"],"concepts":["光电效应","粒子性","光子"]},{"title":"薄膜干涉的成因","type":"模型选择","judge":"油膜彩色条纹是上下表面反射光叠加的干涉，还是色散或衍射","why":"油膜上下表面反射的两列光相干叠加形成干涉条纹，不同色光波长不同使条纹间距不同而呈彩色，选错模型就会误判","do":"确认彩色来自薄膜上下表面反射光的干涉，而非棱镜色散","expr":"","cues":["上下表面反射","两列光叠加","薄膜干涉"],"concepts":["薄膜干涉","相干叠加","波长"]},{"title":"折断筷子判折射","type":"前提判断","judge":"斜插水中的筷子看起来折断是折射还是反射","why":"光从水射入空气时在界面发生折射，视深变化使筷子看起来错位，属于折射现象","do":"追踪筷子反射光经水—空气界面折射进入眼睛的路径","expr":"","cues":["水面处偏折","视深变化","光从水到空气"],"concepts":["折射","视深","光路"]}],"390":[{"title":"交流电表读有效值","type":"前提判断","judge":"电压表、电流表的读数对应交流电的哪个值","why":"交流电表测量的是有效值，不是瞬时值也不是最大值；题干给的表达式是瞬时值形式","do":"从 u=220√2 sin100πt 中读出最大值，再除以 √2 得有效值，作为原线圈输入电压","expr":"U_1=\\frac{U_m}{\\sqrt{2}}=\\frac{220\\sqrt{2}}{\\sqrt{2}}=220\\,\\mathrm{V}","cues":["电表读有效值","先求最大值","除以根号二"],"concepts":["有效值","最大值","交流电"]},{"title":"理想变压器电压比","type":"关系建立","judge":"原、副线圈电压之比由什么决定","why":"理想变压器电压比等于匝数比，与负载无关","do":"用 U1/U2=n1/n2 把已知的 U1=220V、U2=10V 与匝数比联系起来","expr":"\\frac{U_1}{U_2}=\\frac{n_1}{n_2}","cues":["电压比等于匝数比","先定匝数比"],"concepts":["理想变压器","匝数比"]},{"title":"电流比取匝数反比","type":"关系建立","judge":"原、副线圈电流之比与匝数比是正比还是反比","why":"理想变压器只有一个副线圈时，输入功率等于输出功率，故电流与匝数成反比","do":"由 n1/n2=22 得 I1/I2=n2/n1，代入 I2=4A 求原线圈电流","expr":"\\frac{I_1}{I_2}=\\frac{n_2}{n_1}=\\frac{1}{22}","cues":["电流比是反的","功率相等推出来","别和电压比搞混"],"concepts":["电流比","功率相等"]},{"title":"副线圈电压不变","type":"前提判断","judge":"滑动变阻器移动时，副线圈电压是否改变","why":"原线圈电压有效值和匝数比都不变，由 U1/U2=n1/n2 知 U2 恒定，与负载阻值无关","do":"比较滑片移动前后的 U1 与 n1/n2，确认 U2 保持 10V","expr":"U_2=\\frac{n_2}{n_1}U_1=\\text{常量}","cues":["电压由匝数比定","负载不影响电压","电压表读数不变"],"concepts":["副线圈电压","匝数比"]},{"title":"滑片移动判电流","type":"关系建立","judge":"滑片上移时接入电阻如何变，副线圈电流随之如何变","why":"U2 不变时，由欧姆定律 I2=U2/R，电阻减小则电流增大","do":"判断滑片上移使接入阻值减小，再据 I2=U2/R 判断电流表读数增大","expr":"I_2=\\frac{U_2}{R}","cues":["电压不变看电阻","电阻小电流大","电流表读数变大"],"concepts":["欧姆定律","滑动变阻器"]}],"391":[{"title":"匀加速末速度","type":"关系建立","judge":"匀加速阶段结束时速度是否达到最大值，以及能否用初速为零的匀加速公式求它","why":"集装箱由静止开始做匀加速直线运动，加速度恒为 a、持续时间为 t，故末速度就是整个提升过程的最大速度","do":"用速度公式写出匀加速末速度，作为后续求动能和功率的速度依据","expr":"v_m=at","cues":["从静止开始","加速度不变","末速度最大"],"concepts":["匀变速直线运动","速度公式"]},{"title":"提升高度的求法","type":"关系建立","judge":"求重力势能增量时，上升高度该用哪段运动的位移公式","why":"重力势能增量只由竖直高度决定，而高度由初速为零的匀加速位移公式给出，不能误用匀速或平均速度以外的公式","do":"写出匀加速阶段的位移，作为高度 h 代入重力势能增量","expr":"h=\\frac{1}{2}at^{2}","cues":["先求上升高度","用位移公式","高度决定势能"],"concepts":["匀变速直线运动","位移公式","重力势能"]},{"title":"机械能增量的组成","type":"前提判断","judge":"机械能增量是否等于动能增量与重力势能增量之和，两项是否都要算","why":"机械能包括动能和重力势能，提升过程中两者同时增加，只算其中一项会漏掉另一半","do":"分别算出动能增量和重力势能增量后相加，得到机械能总增量","expr":"\\Delta E=\\frac{1}{2}mv_m^{2}+mgh=\\frac{1}{2}m(a+g)at^{2}","cues":["动能势能都要算","机械能是两者之和","别只算动能"],"concepts":["机械能","动能","重力势能"]},{"title":"拉力由牛顿第二定律定","type":"模型选择","judge":"起重机拉力是否等于重力，还是必须由合力等于 ma 反求","why":"集装箱有向上加速度，合力不为零，拉力大于重力，直接用 F=mg 会算错功率","do":"对集装箱受力分析，取竖直向上为正，由合力等于 ma 解出拉力","expr":"F-mg=ma\\Rightarrow F=m(g+a)","cues":["有加速度","拉力大于重力","先受力分析"],"concepts":["牛顿第二定律","受力分析"]},{"title":"最大功率的取法","type":"临界条件","judge":"起重机的最大输出功率应取哪一时刻的力与速度乘积","why":"功率 P=Fv，拉力在匀加速阶段恒定，速度在阶段末最大，故功率在匀加速末达到最大","do":"把已求出的恒定拉力和匀加速末速度相乘，得到最大输出功率","expr":"P_m=Fv_m=m(g+a)at","cues":["速度最大时功率最大","力不变看速度","取末时刻"],"concepts":["功率","瞬时功率"]}],"392":[{"title":"释放瞬间弹簧力不突变","type":"前提判断","judge":"释放瞬间能否认为弹簧弹力仍等于初始压缩量对应的值","why":"弹簧形变需要时间，瞬间形变量不变，弹力不突变；而绳中拉力可以突变","do":"先用初始静止条件对 N 求弹簧压缩量，再把该弹力代入释放瞬间 M、N 整体的受力","expr":"kx_1=mg","cues":["弹簧力不突变","先求压缩量","绳拉力会突变"],"concepts":["弹簧弹力","突变与不突变","平衡条件"]},{"title":"取 M、N 整体避开绳力","type":"模型选择","judge":"求加速度和速度时是否把 M、N 及绳看成一个整体","why":"绳中拉力是内力，取整体可消去未知拉力，只需一个方程","do":"沿斜面方向对整体列牛顿第二定律，把电场力、重力分量、弹簧力一起计入","expr":"Eq+mg\\sin30^\\circ-mg+kx=2ma","cues":["取整体","避开绳的拉力","沿斜面列方程"],"concepts":["整体法","牛顿第二定律"]},{"title":"速度最大对应合力为零","type":"临界条件","judge":"M 速度最大出现在加速度为零处，而不是最低点","why":"加速度为零前速度增大、之后减小，速度极大值对应合力为零","do":"令整体合力为零求此时弹簧伸长量，再与初始压缩量比较判断弹性势能是否变化","expr":"Eq+mg\\sin30^\\circ=kx_2+mg","cues":["合力为零速度最大","不是最低点","先找平衡位置"],"concepts":["平衡位置","速度极值","弹性势能"]},{"title":"识别简谐运动并用对称性","type":"模型选择","judge":"合外力是否随位移线性变化、能否按简谐运动处理","why":"合力与位移成正比且指向平衡位置，故为简谐运动，可用关于平衡位置的对称性","do":"以速度最大处为原点写出合力随位移的表达式，利用释放点与最低点加速度等大反向求最大位移","expr":"F_合=kx-mg","cues":["合力与位移成正比","是简谐运动","用对称性"],"concepts":["简谐运动","回复力","对称性"]},{"title":"周期与时间对应关系","type":"关系建立","judge":"从释放到第一次最低点对应半个周期，还是四分之一周期","why":"释放点为端点、最低点为另一端点，两点间为半个周期，故 T=2t","do":"写出位移随时间变化的余弦式，代入指定下滑距离解出对应时刻","expr":"x=\\frac{2mg}{k}\\cos\\frac{\\pi}{t}t'","cues":["端点到端点","半个周期","用余弦式代入"],"concepts":["简谐运动周期","振动方程"]}],"393":[{"title":"分解两区域运动","type":"模型选择","judge":"进入 Ⅰ 区后，粒子在 x 方向与 yOz 平面上的运动各是什么性质，能否拆成两个独立分运动","why":"电场沿 x 轴、磁场沿 x 轴，洛伦兹力只在 yOz 平面内，故 x 方向只受电场力做匀加速，yOz 平面只受洛伦兹力做匀速圆周","do":"把初速度按 x 轴和 yOz 平面分解，分别写出 x 方向匀加速方程与 yOz 平面圆周运动方程","expr":"v_x=v_0\\cos\\theta,\\quad v_{\\perp}=v_0\\sin\\theta,\\quad qv_\\perp B_1=\\frac{mv_\\perp^2}{r}","cues":["拆成两个方向","x方向匀加速","平面内转圈"],"concepts":["运动的分解","洛伦兹力","匀强电场"]},{"title":"由共速定乙的速度","type":"关系建立","judge":"甲、乙沿 x 轴的分速度相等这一条件，能否用来由甲的速度反推乙的初速度大小和方向","why":"两粒子同种、同源、同一区域，x 方向加速度相同，初 x 分量相等则任意时刻 x 分量相等，这是后面时间相等的前提","do":"用甲的速度和 30° 角算出共同的 x 分量，再由乙的 60° 角关系求出乙的 z 分量与合速度","expr":"v_x=v_0\\cos30^\\circ,\\quad v_{\\text{乙}z}=v_x\\tan60^\\circ","cues":["x分量相同","先算共同分量","用角度反推"],"concepts":["速度分解","分速度相等"]},{"title":"最短时间定半径","type":"临界条件","judge":"乙“以最短时间”从 O 到 O₁，对应 yOz 平面内圆弧的哪种几何情形，半径与 d 是什么关系","why":"x 方向位移固定为 d，时间由 x 方向运动决定；而 yOz 平面内要从原点回到 z=0 的 O₁，最短对应半圆，弦长即直径等于 d","do":"画出 yOz 平面内乙的圆弧轨迹，判断 O 与 O₁ 为直径两端，取 r₁=d/2，并用半圆时间与 x 方向位移联立","expr":"r_1=\\frac{d}{2},\\quad t_1=\\frac{\\pi r_1}{v_{\\text{乙}z}},\\quad d=\\frac{v_x+v_x'}{2}t_1","cues":["最短就是半圆","直径是d","先定半径"],"concepts":["圆周运动","最短时间","几何关系"]},{"title":"屏处半径定 B₂","type":"几何关系","judge":"乙进入 Ⅱ 区后“恰好到达接收屏”，在 xOy 平面内圆周半径与 d 的关系是什么","why":"Ⅱ 区磁场沿 z 轴，粒子在 xOy 平面做圆周、z 方向匀速；从 x=d 出发要恰好打到 x=2d 的屏，圆轨道直径或半径必须与区域宽度 d 匹配","do":"在 xOy 平面画乙进入 Ⅱ 区后的圆轨迹，由入射速度方向与屏位置确定半径 r₂=d，再用向心力公式求 B₂","expr":"r_2=d,\\quad qv_x'B_2=\\frac{mv_x'^2}{r_2}","cues":["恰好打到屏","半径等于d","看xOy平面"],"concepts":["圆周运动","边界条件","洛伦兹力"]},{"title":"两粒子时间相同","type":"前提判断","judge":"甲、乙在 Ⅰ 区和 Ⅱ 区的运动时间是否分别相等，从而能否同时到达屏","why":"两粒子 x 方向初速度相同、加速度相同，Ⅰ 区位移同为 d，故 Ⅰ 区时间相等；同一磁场中周期相同，进入 Ⅱ 区时 z 坐标与速度情形相同，故 Ⅱ 区时间也相等","do":"比较两粒子在 Ⅰ 区的 x 方向运动，再比较 Ⅱ 区圆周运动的周期与所转角度，判断总时间是否相等","expr":"t_1=\\frac{2d}{v_x+v_x'},\\quad T=\\frac{2\\pi m}{qB}","cues":["x方向完全一样","时间应该相等","同时到屏"],"concepts":["运动时间","周期","分运动独立性"]},{"title":"z 坐标差用匀速段","type":"关系建立","judge":"两粒子到达屏时 z 坐标之差由哪一段运动贡献，能否只用 Ⅱ 区的 z 方向匀速运动计算","why":"两粒子在 Ⅰ 区结束时 z 坐标都回到零，Ⅱ 区 z 方向不受力做匀速直线运动，故 z 坐标差只由 Ⅱ 区时间和 z 方向速度差决定","do":"写出 Ⅱ 区运动时间（四分之一周期），用乙、甲 z 方向速度差乘该时间求 Δz","expr":"\\Delta z=(v_{\\text{乙}z}-v_{\\text{甲}z})\\cdot\\frac{T_2}{4}","cues":["只看Ⅱ区","z方向匀速","速度差乘时间"],"concepts":["匀速直线运动","分运动独立性","坐标差"]}],"394":[{"title":"摆长要加球半径","type":"关系建立","judge":"摆长 L 是摆线长加小球半径，还是只取摆线长","why":"单摆摆长定义为悬点到球心的距离，题给的是线长和直径，直径需换算单位后取一半","do":"把 d=20 mm 换成 2.00 cm，取半径 1.00 cm 加到线长 79 cm 上","expr":"L=l+\\frac{d}{2}","cues":["摆长就是线长","直径要除以二","单位先换成厘米"],"concepts":["单摆摆长","球心到悬点"]},{"title":"最低点开始计时","type":"实验操作","judge":"在最高点还是最低点开始计时、数全振动次数","why":"最低点处摆球速度最大，经过该位置的时间误差最小，最高点速度为零计时误差大","do":"选最低点作为计时起点，用 30 次全振动总时间除以 30 得周期","expr":"T=\\frac{t}{30}","cues":["最低点速度最快","最高点不好卡时间","总时间除以次数"],"concepts":["计时误差","全振动"]},{"title":"周期公式反解 g","type":"关系建立","judge":"用哪个公式把 L、T 与 g 联系起来，L 用米还是厘米","why":"单摆小角摆动周期公式给出 g 与 L、T 的定量关系，代入时长度须用国际单位","do":"由周期公式反解出 g，把 L 换成 0.8000 m、T=1.80 s、π²=10 代入","expr":"T=2\\pi\\sqrt{\\frac{L}{g}}\\Rightarrow g=\\frac{4\\pi^{2}L}{T^{2}}","cues":["用单摆周期公式","长度换成米","π方取10"],"concepts":["单摆周期公式","重力加速度"]},{"title":"光屏消失判全反射","type":"模型选择","judge":"光屏上光线消失对应哪种光学现象","why":"光从玻璃射向空气、入射角增大到临界角时折射光消失，只剩反射光，这是全反射的特征而非色散或衍射","do":"把激光沿半径射向圆心，在 AB 界面处入射角随 D 移动而增大，消失即达到临界角","expr":"","cues":["光从玻璃射向空气","折射光没了","入射角到临界角"],"concepts":["全反射","临界角"]},{"title":"临界角对应几何角","type":"几何关系","judge":"临界角是三角形里的哪个角，用哪两条边算正弦","why":"光线沿半径射到 O，在 AB 面入射角等于临界角，该角与三角形 DOE 中 O 处的角相等，可用对边比斜边求正弦","do":"在直角三角形 DOE 中取 DE 为对边、OD=OB 为斜边，写出正弦并代入 2.50 cm 与 4.00 cm","expr":"\\sin C=\\frac{DE}{OD}=\\frac{DE}{OB}","cues":["角在圆心O处","斜边是半径","对边是DE"],"concepts":["临界角","直角三角形"]},{"title":"临界角求折射率","type":"关系建立","judge":"用 sinC 与 n 的哪个关系求折射率","why":"全反射临界角满足正弦等于折射率倒数，这是由折射定律在折射角为 90° 时得到的","do":"把算出的正弦值取倒数得折射率","expr":"\\sin C=\\frac{1}{n}\\Rightarrow n=\\frac{1}{\\sin C}","cues":["临界角正弦是倒数","取倒数就行"],"concepts":["折射率","全反射临界角"]}],"395":[{"title":"滑动变阻器量程匹配","type":"前提判断","judge":"选最大阻值 50 Ω 还是 500 Ω 的变阻器，才能让电流在 0.6 A 量程内连续可调且调节灵敏","why":"电源约 3 V、总电阻约几欧到几十欧，若用 500 Ω 变阻器，大部分行程电流变化极小，读数集中在表盘一端，精度差","do":"估算回路总电阻范围，比较两个变阻器最大阻值与电流表量程的匹配程度","expr":"I=\\frac{E}{R_0+r+R}","cues":["选小的那个","大电阻调不动","电流变化太小"],"concepts":["滑动变阻器","量程匹配","调节精度"]},{"title":"明确 U-I 图线的函数关系","type":"关系建立","judge":"电压表读数 U 与电流 I 满足什么线性关系，截距和斜率各对应什么物理量","why":"闭合电路欧姆定律中，电压表测的是路端电压，但回路里还串有定值电阻 R0，斜率对应的是 R0+r 而不是单独的 r","do":"对含 R0 的闭合回路列欧姆定律，把 U 写成 I 的一次函数，确定纵截距为 E、斜率绝对值为 R0+r","expr":"U=E-I(R_0+r)","cues":["斜率是内阻加定值电阻","截距是电动势","别把定值电阻漏了"],"concepts":["闭合电路欧姆定律","路端电压","U-I 图像"]},{"title":"描点连线并延长取截距","type":"图像读取","judge":"如何描点、连线，以及把直线延长到 I=0 处读电动势、取斜率算内阻","why":"表格数据点有限，直接读某一点误差大；只有用拟合直线延长到纵轴才能得到电动势，斜率要用相距较远的两点计算","do":"在坐标纸上补齐五个点，用直尺拟合直线并延长与纵轴相交读 E，再在直线上取相距较远的两点求斜率","expr":"E=U|_{I=0},\\quad k=\\frac{\\Delta U}{\\Delta I}=R_0+r","cues":["延长到纵轴","取远的两点算斜率","直线要过大多数点"],"concepts":["图像法","线性拟合","斜率与截距"]},{"title":"区分测量值与真实值","type":"误差分析","judge":"电压表分流使测得的 E、r 偏大还是偏小，等效电源的电动势和内阻如何写","why":"电压表并非理想表，它与电源并联分流，实际流入电流表的电流小于总电流，图像反映的是电压表与电源（含 R0）组成的等效电源的参数","do":"把电压表与电源、R0 看成等效新电源，求等效电动势（分压）和等效内阻（并联），再与真实值比较","expr":"E_{\\text{测}}=\\frac{R_V}{R_V+R_0+r_{\\text{真}}}E_{\\text{真}},\\quad r_{\\text{测}}=\\frac{(R_0+r_{\\text{真}})R_V}{R_0+r_{\\text{真}}+R_V}","cues":["电压表在分流","等效成一个新电源","测量值偏小"],"concepts":["电压表分流","等效电源","系统误差"]},{"title":"由等效内阻反解真实内阻","type":"数学处理","judge":"已知 r测、R0、RV，如何反解出 r真 的表达式","why":"等效内阻是 R0+r真 与 RV 的并联值，需把 r真 从并联式中解出，而不是直接把 r测 当作内阻","do":"将并联关系式变形，解出 r真 用 r测、R0、RV 表示","expr":"r_{\\text{真}}=\\frac{r_{\\text{测}}R_V}{R_V-r_{\\text{测}}}-R_0","cues":["并联公式反解","先减掉定值电阻","别把测量值当真实值"],"concepts":["并联电阻","等效内阻","表达式变形"]}],"396":[{"title":"判断升温过程压强不变","type":"前提判断","judge":"活塞缓慢上升时，封闭气体压强是否保持不变","why":"活塞质量不计且无摩擦，竖直放置时活塞只受内外气体压力，任一时刻都满足 pS=p0S，故 p 恒等于大气压","do":"对活塞列受力平衡，确认 p=p0 与体积无关，从而认定过程为等压过程","expr":"pS=p_0S\\Rightarrow p=p_0","cues":["活塞没质量","无摩擦","压强等于大气压"],"concepts":["等压过程","受力平衡"]},{"title":"选盖-吕萨克定律","type":"模型选择","judge":"等压升温过程该用哪条气体定律联系 V 与 T","why":"一定质量理想气体在压强不变时，体积与热力学温度成正比","do":"写出 V0/T0=V1/T1，代入 V0、V1、T0 求 T1","expr":"\\frac{V_0}{T_0}=\\frac{V_1}{T_1}","cues":["压强不变","体积温度成正比","用盖-吕萨克"],"concepts":["盖-吕萨克定律","理想气体状态方程"]},{"title":"确定初态压强","type":"前提判断","judge":"放重物前封闭气体的压强是多少","why":"活塞质量忽略、无摩擦，初态活塞平衡给出 p1=p0，这是玻意耳定律的初态压强","do":"由初态活塞受力平衡得 p1=p0=1×10^5 Pa，作为后续等温过程的起始压强","expr":"p_1=p_0","cues":["初始压强就是大气压","活塞质量不计","先定初态压强"],"concepts":["压强平衡","初态压强"]},{"title":"重物平衡定末态压强","type":"关系建立","judge":"放上重物稳定后，气体压强由哪些力平衡决定","why":"稳定后活塞静止，向下受大气压力 p0S 和重物重力 mg，向上受气体压力 p2S","do":"对放重物后的活塞列竖直方向力平衡，解出 p2","expr":"p_2S=p_0S+mg","cues":["取活塞为对象","加上重物重力","向上气体压力"],"concepts":["受力平衡","压强定义"]},{"title":"选玻意耳定律","type":"模型选择","judge":"放重物下降且温度恒定时，用哪条定律联系初末状态","why":"温度不变、气体质量不变，压强与体积成反比","do":"写出 p1V0=p2V2，与压强平衡式联立求 V2","expr":"p_1V_0=p_2V_2","cues":["温度恒定","等温过程","压强体积反比"],"concepts":["玻意耳定律","等温过程"]}],"397":[{"title":"圆弧段用机械能守恒","type":"模型选择","judge":"A 在圆弧上下滑时，能否用机械能守恒求最低点速度，还是必须用牛顿定律加运动学","why":"轨道光滑、只有重力做功，支持力始终垂直于速度不做功，机械能守恒成立；用牛顿定律则需处理变力变加速，无法直接求速度","do":"取最低点为零势能面，写出初末机械能相等的方程，解出最低点速度","expr":"m_A g(R-R\\cos 53^\\circ)=\\frac{1}{2}m_A v_0^2","cues":["轨道光滑","只有重力做功","取最低点为零势能"],"concepts":["机械能守恒","重力势能","圆周运动"]},{"title":"最低点向心力来源","type":"关系建立","judge":"最低点指向圆心的合力由哪些力提供，支持力与重力谁大","why":"最低点圆心在正上方，支持力向上、重力向下，二者合力提供向心力，故支持力大于重力","do":"沿半径方向列牛顿第二定律方程，代入速度解出支持力","expr":"F_N-m_A g=m_A\\frac{v_0^2}{R}","cues":["圆心在上方","支持力减重力","合力指向圆心"],"concepts":["向心力","牛顿第二定律","圆周运动"]},{"title":"碰撞瞬间动量守恒","type":"前提判断","judge":"A 与 B 碰撞粘连的极短时间内，能否认为动量守恒","why":"碰撞时间极短，水平方向外力（摩擦）冲量可忽略，系统水平动量守恒；但机械能不守恒，需另算损失","do":"以 A、B 为系统沿水平方向列动量守恒方程，求出碰后共同速度","expr":"m_A v_0=(m_A+m_B)v_{\\text{共}}","cues":["碰撞时间极短","水平方向动量守恒","粘连成整体"],"concepts":["动量守恒","完全非弹性碰撞"]},{"title":"损失机械能算法","type":"关系建立","judge":"碰撞损失的机械能是碰前总动能减碰后总动能，还是只算 A 的动能变化","why":"损失机械能指系统初末动能之差，B 初动能为零但碰后获得动能，必须用系统总动能作差","do":"分别写出碰前、碰后系统总动能并相减","expr":"\\Delta E=\\frac{1}{2}m_A v_0^2-\\frac{1}{2}(m_A+m_B)v_{\\text{共}}^2","cues":["系统总动能","碰前减碰后","B初速为零"],"concepts":["动能","能量损失","完全非弹性碰撞"]},{"title":"传送带速度方向分情形","type":"临界条件","judge":"传送带速度比碰后共同速度大还是小，整体在带上先加速还是先减速","why":"整体与带共速前相对滑动方向由两者速度大小决定，摩擦生热对应相对位移大小，两种情形方程不同，必须分类讨论","do":"以 v 与 v共 的大小关系分两种情形，分别写出相对滑动阶段的速度关系与相对位移，代入热量表达式求解并检验解是否落在该情形范围内","expr":"Q=\\mu(m_A+m_B)g\\,|x_{\\text{带}}-x_{\\text{物}}|","cues":["先减速后匀速","先加速后匀速","分两种情况","舍去不合条件的解"],"concepts":["相对位移","摩擦生热","匀变速直线运动"]}],"398":[{"title":"倾斜棒静止的安培力方向","type":"前提判断","judge":"ab 棒静止时，安培力必须沿斜面向上且大小等于重力沿斜面的分力，据此判断电流方向与大小关系","why":"ab 棒受重力、支持力、安培力三力平衡，斜面光滑无摩擦，安培力只能沿斜面方向","do":"对 ab 棒沿斜面方向列平衡方程，用左手定则配合磁场垂直斜面向上确定电流方向","expr":"BIL=mg\\sin\\theta","cues":["沿斜面平衡","安培力向上","只有三个力"],"concepts":["安培力","平衡条件","左手定则"]},{"title":"cd 棒启动的临界电流","type":"临界条件","judge":"cd 棒刚要运动时，安培力恰好等于最大静摩擦力，由此反推此时回路电流和 ab 棒速度","why":"最大静摩擦力等于滑动摩擦力，cd 棒从静止到运动的分界点就是安培力等于 μmg","do":"对 cd 棒列临界方程，再用感应电动势与总电阻表示电流，解出临界速度","expr":"BI_{1}L=\\mu mg,\\quad I_{1}=\\frac{BLv_{0}}{2R}","cues":["刚好要动","安培力等于摩擦力","临界速度"],"concepts":["最大静摩擦力","临界状态","感应电动势"]},{"title":"两棒串联焦耳热均分","type":"关系建立","judge":"两棒电阻相同且串联，电流时刻相同，判断两棒产生的焦耳热相等，总热量为单棒的两倍","why":"串联电路电流相同、电阻相同，由焦耳定律 Q=I²Rt 得两棒发热相等","do":"用能量守恒把重力势能减少量减去 ab 棒动能，得到回路总焦耳热，再除以 2 得 cd 棒的热量","expr":"mgx_{0}\\sin\\theta-\\frac{1}{2}mv_{0}^{2}=2Q_{cd}","cues":["电阻相同","热量平分","总热量除以二"],"concepts":["焦耳定律","能量守恒","串联电路"]},{"title":"稳定时两棒加速度相等","type":"模型选择","judge":"电流稳定意味着速度差恒定，判断此时两棒加速度相同，从而可把两棒方程联立消去加速度","why":"速度差恒定则相对速度不变，两棒加速度必然相等；两棒所受安培力大小相等方向相反","do":"分别对 ab、cd 沿运动方向列牛顿第二定律，令加速度相同，联立解出速度差","expr":"mg\\sin\\theta-BIL=ma,\\quad BIL-\\mu mg=ma,\\quad I=\\frac{BL\\Delta v}{2R}","cues":["速度差恒定","加速度相等","安培力等大反向"],"concepts":["牛顿第二定律","安培力","相对速度"]},{"title":"t1 前系统动量守恒","type":"模型选择","judge":"从 ab 到达水平导轨到 t1 时刻，判断两棒整体所受合外力为零，可用动量守恒求 t1 时刻 ab 的速度","why":"两棒所受安培力等大反向相互抵消，两棒所受摩擦力均为 μmg 但方向相反，整体合外力为零","do":"对两棒整体列动量守恒，结合 t1 时 cd 速度为零，求出 t1 时刻 ab 棒速度","expr":"m\\Delta v=mv_{1}'","cues":["整体合外力为零","安培力抵消","动量守恒"],"concepts":["动量守恒","整体法","合外力"]},{"title":"用冲量与电量求路程差","type":"数学处理","judge":"对两棒分别列动量定理，把安培力冲量转化为 BLq，再把 q 与路程差通过磁通量变化联系起来","why":"安培力随时间变化，只能用冲量形式；电量 q 与磁通量变化成正比，磁通量变化又正比于两棒路程差","do":"对 ab、cd 分别写动量定理并相加消去时间项，用 q=BLΔs/2R 代入，结合加速度为零时安培力等于 μmg 解出 Δs","expr":"2BLq=mv_{1}'-m(v_{1}''-v_{cd}),\\quad q=\\frac{BL\\Delta s}{2R}","cues":["动量定理","电量等于磁通量变化","路程差转磁通量"],"concepts":["动量定理","电荷量","磁通量变化"]}],"399":[{"title":"衰变产物核的确定","type":"前提判断","judge":"由衰变方程中质量数和电荷数守恒，判断新核 X 的质量数与电荷数各是多少","why":"核反应方程必须同时满足质量数守恒和电荷数守恒，这是确定未知核的唯一依据","do":"对 ^18_9F → X + ^0_1e + ^0_0ν 分别列质量数方程和电荷数方程，解出 X 的 A 与 Z","expr":"18=A+0+0,\\quad 9=Z+1+0","cues":["数质量数","电荷数守恒","看上下标"],"concepts":["质量数守恒","电荷数守恒","衰变方程"]},{"title":"衰变类型的判别","type":"模型选择","judge":"判断该过程是核聚变还是放射性衰变（β+ 衰变）","why":"核聚变是轻核结合成较重核，而本题是单个原子核自发转变为另一种核并放出正电子，属于衰变","do":"比较反应前后核的个数：一变二（放出正电子和中微子）为衰变，两轻核合一为重核才是聚变","expr":"","cues":["一个核变另一个","放出正电子","不是两个核合并"],"concepts":["核聚变","β+衰变","放射性衰变"]},{"title":"半衰期的统计含义","type":"关系建立","judge":"判断经过一个半衰期后，发生衰变的核与剩余核各占多少","why":"半衰期是大量原子核有半数发生衰变所需的时间，经过 n 个半衰期剩余质量为原来的 (1/2)^n","do":"把 110 min 与半衰期 110 min 比较，得出经过 1 个半衰期，剩余质量取原来的一半","expr":"m=m_0\\left(\\tfrac12\\right)^{t/T}","cues":["一个半衰期","剩一半","衰变了一半"],"concepts":["半衰期","剩余质量"]},{"title":"中微子的电性判断","type":"结论整理","judge":"判断不带电粒子在磁场中是否受力偏转","why":"磁场对运动电荷的洛伦兹力与电荷量成正比，不带电粒子不受洛伦兹力","do":"由中微子不带电，判断其在磁场中沿直线运动、不偏转","expr":"F=qvB","cues":["不带电","磁场不偏转","没有洛伦兹力"],"concepts":["洛伦兹力","电中性粒子"]}],"400":[{"title":"确定向心力来源","type":"模型选择","judge":"行星做圆周运动的向心力由谁提供，能否忽略行星间引力","why":"题设明确忽略两行星间万有引力，只有恒星对行星的引力充当向心力，才能把问题化为单一中心天体的圆轨道模型","do":"对任一行星受力分析，只保留恒星引力，令其等于所需向心力","expr":"G\\frac{Mm}{r^{2}}=m\\frac{v^{2}}{r}=m\\omega^{2}r=m\\frac{4\\pi^{2}}{T^{2}}r=ma","cues":["只有恒星引力","忽略行星间引力","万有引力当向心力"],"concepts":["万有引力定律","向心力","中心天体模型"]},{"title":"导出各量与半径关系","type":"关系建立","judge":"由同一条引力=向心力方程，能否解出 T、v、ω、a 各自随 r 变化的单调方向","why":"四个物理量都由同一个 GM 与 r 决定，必须分别解出表达式才能比较，不能凭直觉猜","do":"从向心力方程分别解出 T、v、ω、a 关于 r 的表达式","expr":"T=2\\pi\\sqrt{\\frac{r^{3}}{GM}},\\ v=\\sqrt{\\frac{GM}{r}},\\ \\omega=\\sqrt{\\frac{GM}{r^{3}}},\\ a=\\frac{GM}{r^{2}}","cues":["分别解出四个量","看谁在分子谁在分母","周期带根号三次方"],"concepts":["圆周运动参量","开普勒第三定律"]},{"title":"比较半径定大小","type":"数学处理","judge":"r 甲小于 r 乙时，各量是随 r 增大而增大还是减小","why":"T 与 r 的 3/2 次方成正比，v、ω、a 分别与 r 的 1/2、3/2、2 次方成反比，单调方向不同，必须逐量判断","do":"把 r甲<r乙 代入四个表达式，比较 T、v、ω、a 的大小","expr":"r_\\text{甲}<r_\\text{乙}\\Rightarrow T_\\text{甲}<T_\\text{乙},\\ v_\\text{甲}>v_\\text{乙},\\ \\omega_\\text{甲}>\\omega_\\text{乙},\\ a_\\text{甲}>a_\\text{乙}","cues":["半径小的转得快","半径小的周期短","向心加速度也变大"],"concepts":["反比关系","正比关系"]},{"title":"排除向心加速度反向错项","type":"结论整理","judge":"向心加速度 a 与 r 是正相关还是负相关，干扰项是否把它当成随 r 增大而增大","why":"a=GM/r² 是反比平方关系，半径越小加速度越大，若误记成 a=ω²r 随 r 增大就会选错","do":"用 a=GM/r² 核对含向心加速度的选项，确认其方向与其余三个量一致","expr":"a=\\frac{GM}{r^{2}}","cues":["别用角速度乘半径","半径小加速度大"],"concepts":["向心加速度","平方反比"]}],"401":[{"title":"绝热+电热丝的能量归属","type":"前提判断","judge":"判断气体吸热还是放热、内能变化由谁决定","why":"汽缸和活塞均绝热，气体与外界无热交换，但电热丝在内部加热，热量直接输入气体，故 Q>0；理想气体内能只由温度决定","do":"明确电热丝加热使气体吸热，温度升高则内能增大","expr":"Q>0,\\ \\Delta U>0","cues":["绝热就不吸热吗","电热丝在里面","温度升内能增"],"concepts":["热力学第一定律","理想气体内能","绝热过程"]},{"title":"体积减小对应外界做功","type":"关系建立","judge":"判断体积减小时是外界对气体做功还是气体对外做功","why":"做功正负由体积变化方向决定，体积减小即外界压缩气体","do":"由体积缓慢减小判断 W>0（外界对气体做功）","expr":"W>0\\ (\\Delta V<0)","cues":["体积小了被压缩","外界对气体做功","压缩就做功"],"concepts":["体积功","热力学第一定律"]},{"title":"用状态方程定压强变化","type":"关系建立","judge":"判断 T 升为 2 倍、V 减小时压强如何变化","why":"一定量理想气体满足 pV/T=C，T 增大而 V 减小，两者同向推高压强","do":"由 pV/T=C 比较初末态，得 p 大于原来的 2 倍","expr":"\\frac{pV}{T}=C\\Rightarrow p=\\frac{CT}{V}","cues":["先看状态方程","温度升体积减","压强肯定变大"],"concepts":["理想气体状态方程"]},{"title":"外力 F 随压强变化","type":"模型选择","judge":"判断活塞受力平衡中外力 F 应随压强怎样变化","why":"活塞缓慢移动处于平衡，F 与气体压力、外界大气压力需满足平衡关系，压强增大则所需外力增大","do":"对活塞列力平衡，比较初末态压强得出 F 增大","expr":"pS+F=p_0S\\ (示意)","cues":["活塞受力平衡","压强大了要更用力","外力跟着变大"],"concepts":["受力平衡","压强"]}],"402":[{"title":"环形电流磁场方向","type":"模型选择","judge":"要判断环形电流在轴线上 M、N 两点产生的磁场方向是否相同","why":"环形电流的磁场由右手螺旋定则决定，轴线上同侧各点的磁场方向都沿轴线同一方向","do":"用右手螺旋定则判断环形电流在轴线上产生的磁场方向，确认 M、N 两点磁场同向","expr":"","cues":["右手定则","沿轴线同向","同侧同向"],"concepts":["右手螺旋定则","环形电流磁场"]},{"title":"对称点磁场等大","type":"关系建立","judge":"要判断 M、N 两点到圆心等距时，环形电流在这两点产生的磁感应强度大小是否相等","why":"环形电流轴线上的磁场关于线圈平面对称，到圆心距离相等的两点磁感应强度大小相等","do":"比较 M、N 到 O 的距离，得出环形电流在两点产生的磁感应强度大小相等、方向相同","expr":"B_M'=B_N'","cues":["等距等大","对称性","关于圆心对称"],"concepts":["磁场的对称性","磁感应强度叠加"]},{"title":"M 点合磁场为零的含义","type":"前提判断","judge":"要判断 M 点合磁感应强度为零说明匀强磁场与环形电流在 M 点的磁场是什么关系","why":"总磁感应强度是匀强磁场与环形电流磁场的矢量和，合矢量为零意味着两者等大反向","do":"把 M 点的合磁场写成匀强磁场与环形电流磁场的矢量和，令其为零，得出两者等大反向","expr":"\\vec{B}_0+\\vec{B}_M'=0","cues":["矢量和为零","等大反向","抵消"],"concepts":["磁场的叠加","矢量合成"]},{"title":"N 点合磁场合成","type":"结论整理","judge":"要判断 N 点处匀强磁场与环形电流磁场叠加后的合磁感应强度大小","why":"N 点环形电流磁场与 M 点等大同向，而匀强磁场与 M 点环形电流磁场等大反向，故在 N 点两者也等大反向","do":"把 N 点的两个分磁场按矢量合成，得出合磁感应强度大小","expr":"B_N=B_0-B_N'=0","cues":["同样抵消","等大反向","合成为零"],"concepts":["磁场的叠加","矢量合成"]}],"403":[{"title":"回路面积取初始面积","type":"前提判断","judge":"计算磁通量变化时，回路面积该取哪一段——是两棒初始间距围成的面积，还是随时间变化的面积","why":"两棒都在运动，若把面积当成随时间变化，就必须先求两棒各自的运动，而题中并未给出速度大小，无法求解；只有认定磁通量变化只由 B 的变化引起、面积取 t=0 时的 B₀Lx₀，才能用 ΔΦ=B₀Lx₀ 直接算出","do":"确定 0~T 内磁通量从 B₀Lx₀ 变到 0，写出 ΔΦ=B₀Lx₀","expr":"\\Delta\\Phi=B_{0}Lx_{0}","cues":["面积用初始的","两棒间距会变","只看磁场变"],"concepts":["磁通量","有效面积"]},{"title":"平均电动势代替瞬时值","type":"模型选择","judge":"求电荷量时该用平均感应电动势还是某一时刻的瞬时电动势","why":"电荷量 q=ĪΔt 只与平均电流有关，而平均电流由平均电动势决定，用瞬时电动势积分虽等价但题中 B(t) 的具体形状未给出，只能用平均值","do":"对 0~T 全过程用 Ē=ΔΦ/Δt，再与 q=ĪΔt 联立","expr":"\\bar{E}=\\frac{\\Delta\\Phi}{\\Delta t},\\quad q=\\bar{I}\\Delta t","cues":["用平均电动势","不用瞬时值","电荷量看平均电流"],"concepts":["法拉第电磁感应定律","平均感应电动势"]},{"title":"回路总电阻取 2R","type":"关系建立","judge":"回路总电阻是 R 还是 2R——两棒是串联在回路中还是并联","why":"两棒跨在平行导轨上，与导轨构成单一闭合回路，两棒首尾相接串联，电流处处相同，总电阻为两棒电阻之和，导轨电阻忽略","do":"写出 Ī=Ē/(2R)，把两棒电阻相加","expr":"\\bar{I}=\\frac{\\bar{E}}{2R}","cues":["两棒串联","总电阻是两倍","导轨没电阻"],"concepts":["串联电路","闭合回路欧姆定律"]},{"title":"末态磁通量为零","type":"临界条件","judge":"t=T 时刻回路磁通量是否为零，即 ΔΦ 的末值取什么","why":"图(b) 给出 t=T 时 B=0，磁场消失则穿过回路的磁通量必为零，故 ΔΦ 就是从 B₀Lx₀ 减到 0 的整个量","do":"读出图(b) 中 t=T 处 B=0，取 Φ末=0","expr":"\\Phi_{末}=0,\\quad \\Delta\\Phi=B_{0}Lx_{0}","cues":["T时刻磁场为零","末磁通量为零","图上看B归零"],"concepts":["磁通量","图像读取"]},{"title":"两棒运动不影响电荷量","type":"结论整理","judge":"cd 棒有初速度、ab 棒静止这一运动信息，对求电荷量是否必需","why":"电荷量只由磁通量总变化和总电阻决定，与两棒如何运动无关；把运动信息当作必需条件会误入求速度、求加速度的歧路","do":"确认 q 的表达式中不含速度、时间以外的运动量，直接得 q=B₀Lx₀/(2R)","expr":"q=\\frac{B_{0}Lx_{0}}{2R}","cues":["速度用不上","只算磁通量变化","别去求加速度"],"concepts":["电荷量公式","感应电荷量"]}],"404":[{"title":"两球竖直位移的符号约定","type":"前提判断","judge":"斜向上与斜向下抛出的球，从击球点到过网点的竖直位移方向如何取","why":"两球击球点高度不同（L/2 与 L），但过网点都在网顶，竖直位移一个向下、一个也向下，必须统一以向下为正才能把初速度竖直分量写成 +v₀sinθ 与 −v₀sinθ","do":"设网高为 h，写出两球竖直位移：第一球 L−h，第二球 L/2−h，均取向下为正","expr":"y_1=L-h,\\quad y_2=\\frac{L}{2}-h","cues":["都往下落","取向下为正","位移是末减初"],"concepts":["竖直位移","正方向约定","匀变速直线运动"]},{"title":"水平方向定飞行时间","type":"关系建立","judge":"两球水平距离相同、水平分速度是否相同，从而飞行时间是否相同","why":"水平方向匀速，水平距离均为 L，水平分速度均为 v₀cosθ，故两球飞行时间相等，这是把两个方程联立的前提","do":"对两球分别写水平方向方程，确认 t 相同","expr":"t=\\frac{L}{v_0\\cos\\theta}","cues":["水平匀速","时间一样","水平速度相同"],"concepts":["平抛运动","匀速直线运动","分运动独立性"]},{"title":"竖直方向建两方程","type":"关系建立","judge":"竖直方向是匀变速，初速度竖直分量对两球分别为 +v₀sinθ 与 −v₀sinθ","why":"竖直方向只受重力，加速度为 g，斜向上抛竖直分量向上、斜向下抛竖直分量向下，符号相反是两式能相减消元的关键","do":"分别写竖直位移方程，注意第二球竖直初速度为负","expr":"L-h=v_0\\sin\\theta\\,t+\\frac12gt^2,\\quad \\frac{L}{2}-h=-v_0\\sin\\theta\\,t+\\frac12gt^2","cues":["一个向上一个向下","竖直初速度反号","加速度都是g"],"concepts":["匀变速直线运动","竖直分速度","重力加速度"]},{"title":"消去网高与速度","type":"数学处理","judge":"两式中 h、v₀、t 均为未知，如何通过相减消去 h 和 gt² 项","why":"两式右边 gt²/2 相同，相减可同时消去 h 与 gt²，只剩 v₀sinθ·t 与 L/2 的关系，再代入 t 的表达式即可解出 tanθ","do":"两式相减得 L/2=2v₀sinθ·t，代入 t=L/(v₀cosθ) 化简","expr":"\\frac{L}{2}=2v_0\\sin\\theta\\cdot\\frac{L}{v_0\\cos\\theta}\\Rightarrow\\tan\\theta=\\frac14","cues":["两式相减","消掉网高","代掉时间"],"concepts":["方程联立","消元","正切函数"]}],"405":[{"title":"确定门板实际位移","type":"几何关系","judge":"门板从完全关闭到完全打开，其质心（或参考点）沿轨道移动的距离是 L 还是 L/2","why":"图(a)到图(b)是两扇各宽 L/2 的门板错开到另一侧，单扇门板相对门框的位移等于门板宽度 L/2，不是门总宽 L","do":"对照图(a)(b)中同一门板的左右边缘位置，量出它相对门框移动的距离","expr":"s=\\frac{L}{2}","cues":["位移是半个门宽","不是整个门宽","看门板边缘移动"],"concepts":["位移","参考系"]},{"title":"选全过程用动量定理","type":"模型选择","judge":"求最短总时间时，是分加速、减速两段分别列式，还是对全过程用动量定理消去拉力","why":"拉力大小未知且可调，分两段会引入 F 与 t1 两个未知量；全过程初末速度均为零，冲量关系只含 F、t1 与总时间 t，能把 F 用 t、t1 表示","do":"对全过程列冲量等于动量变化，把 F 解成 μmg t/t1","expr":"Ft_1=\\mu mg t","cues":["取全过程","初末速度都是零","消掉拉力"],"concepts":["动量定理","冲量"]},{"title":"用平均速度联系位移","type":"关系建立","judge":"匀加速接匀减速、初末速度均为零的过程，总位移能否用最大速度与总时间的一半表示","why":"v-t 图是等腰三角形，面积即位移，等于 vm·t/2，与两段时间如何分配无关","do":"写出位移与 vm、t 的关系，把 vm 用 L 和 t 表示","expr":"\\frac{L}{2}=\\frac{v_m t}{2}","cues":["画速度时间图","三角形面积","最大速度乘总时间"],"concepts":["平均速度","v-t 图像"]},{"title":"把总时间化为单变量","type":"数学处理","judge":"总时间 t 最终应写成只含减速段时间 t2（或只含 t1）的函数，判断它随哪个量单调变化","why":"只有化成单变量函数才能求极值；由动量定理与位移关系可消去 vm 和 F，得到 t 与 t2 的反比关系","do":"联立三段关系消去 vm、F、t1，得到 t 关于 t2 的表达式","expr":"t=\\frac{L}{\\mu g\\, t_2}","cues":["消到只剩一个变量","看反比关系","t2越大t越小"],"concepts":["函数关系","控制变量"]},{"title":"取极限求最短时间","type":"临界条件","judge":"t2 增大到极限时对应什么物理情形，最短时间在哪个端点取到","why":"t2 是撤去拉力后的减速时间，它不能超过总时间 t；t 随 t2 增大而减小，故最小值在 t2 趋近于 t（即加速段时间趋近于零、拉力极大）时取到","do":"令 t2→t，代入反比式解出 t 的极限值","expr":"t_{\\min}=\\sqrt{\\frac{L}{\\mu g}}","cues":["减速段占满全程","加速时间趋近零","拉力趋于无穷大"],"concepts":["极限法","临界条件"]}],"406":[{"title":"把用户端折算到输电线","type":"模型选择","judge":"判断输电线回路中除 r 外的负载应如何等效，才能用一个回路欧姆定律处理","why":"降压变压器是理想变压器，副线圈负载 R用户 可按匝数比平方折算到原线圈，功率不变","do":"对降压器用 I3n3=I4n4 和 I3²Rx=I4²R用户，求出折算电阻 Rx","expr":"R_x=\\left(\\frac{n_3}{n_4}\\right)^2 R_\\text{用户}","cues":["折算到原线圈","按匝数比平方","把用户等效成电阻"],"concepts":["理想变压器","等效电阻","功率不变"]},{"title":"升压副线圈电压由匝数定","type":"前提判断","judge":"判断 U2 是否随用户数变化，还是只由 U1 和 n2/n1 决定","why":"发电机输出电压 U1 一定，理想变压器电压比只由匝数比决定，与负载无关","do":"写出 U2 与 U1、n1、n2 的关系，确认 U2 在改变用户数时不变","expr":"U_2=\\frac{n_2}{n_1}U_1","cues":["电压由匝数比定","U2不变","先看升压比"],"concepts":["理想变压器电压比","输出电压一定"]},{"title":"输电线电流随负载变化","type":"关系建立","judge":"判断用户数增加（R用户 减小）时输电线电流 I2 如何变化","why":"U2 不变，回路总电阻 r+Rx 随 R用户 减小而减小，故 I2 增大","do":"把 Rx 代入回路欧姆定律，比较 R用户 减小时 I2 的变化方向","expr":"I_2=\\frac{U_2}{r+\\left(\\frac{n_3}{n_4}\\right)^2R_\\text{用户}}","cues":["用户越多电阻越小","电流变大","看总电阻"],"concepts":["闭合电路欧姆定律","等效电阻"]},{"title":"线损与降压输入电压的联动","type":"关系建立","judge":"判断 I2 增大后，线损功率和降压器输入电压 U3 各自怎么变","why":"线路上 r 与降压器原线圈串联，U3=U2−I2r，线损为 I2²r","do":"由 I2 增大分别判断 I2²r 增大、U3 减小，再由 U4=(n4/n3)U3 判断用户电压","expr":"\\Delta P=I_2^2r,\\quad U_3=U_2-I_2r,\\quad U_4=\\frac{n_4}{n_3}U_3","cues":["线损看电流平方","U3被线路吃掉一部分","用户电压跟着降"],"concepts":["线路损耗","串联分压","理想变压器电压比"]},{"title":"调匝数比后的功率走向","type":"关系建立","judge":"判断仅增大 n2 时，U2、I2 及总功率 P=U2I2 如何变化","why":"U2 随 n2 增大而增大，回路电阻不变故 I2 也增大，两者同向增大使总功率增大","do":"先由 U2=n2U1/n1 判断 U2 增大，再由回路式判断 I2 增大，最后看乘积 U2I2","expr":"P_1=P_2=U_2I_2","cues":["升压比变大","电压电流同增","总功率变大"],"concepts":["理想变压器","电功率","闭合电路欧姆定律"]}],"407":[{"title":"判断A球是否被拉起","type":"临界条件","judge":"弹簧对A球向上的弹力能否超过A球重力，即A球是否会离开静止位置","why":"A球受细线约束，只有弹簧向上的拉力大于mg时细线才松弛、A球才可能运动；这是全题分情况讨论的分界","do":"对A球列竖直方向受力，找弹簧弹力等于mg时的形变量作为临界形变量","expr":"kx_0=mg","cues":["看弹簧能不能顶起A球","细线会不会松","弹力要大于重力"],"concepts":["临界条件","弹力","受力平衡"]},{"title":"用简谐振动对称性定振幅","type":"关系建立","judge":"B球单独振动时，平衡位置在哪、振幅等于多少","why":"B球在平衡位置合力为零，释放点相对平衡位置的位移就是振幅；只有确定振幅才能把最低点加速度与形变量联系起来","do":"先找B球合力为零的平衡位置，再量出释放点相对它的位移作为振幅","expr":"A=l","cues":["平衡位置合力为零","振幅就是拉开的距离","对称性用起来"],"concepts":["简谐振动","平衡位置","振幅"]},{"title":"最低点加速度与临界形变挂钩","type":"关系建立","judge":"B球在最低点的加速度与弹簧达到临界形变量时的加速度是否相等","why":"简谐振动关于平衡位置对称，最低点与最高点加速度大小相等；把临界形变量对应的加速度与释放点加速度比较，才能解出临界下拉长度","do":"对B球在弹簧形变为临界值时列牛顿第二定律，再令其等于最低点加速度","expr":"kx_0+mg=ma,\\quad kl=ma","cues":["最低点加速度最大","对称点加速度一样","拿加速度作桥梁"],"concepts":["牛顿第二定律","简谐振动对称性","加速度"]},{"title":"解出临界下拉长度并分情况","type":"数学处理","judge":"下拉长度l与2mg/k的大小关系对应A球动或不动","why":"l超过临界值时弹簧形变足以让弹力超过A球重力，A球被拉起，前面的单振模型失效，必须分情况","do":"联立两式消去加速度，解出l的临界值，再按l与该值的大小关系讨论","expr":"l=\\frac{2mg}{k}","cues":["临界长度是多少","超过就会动","分两种情况说"],"concepts":["临界值","分情况讨论","胡克定律"]}],"408":[{"title":"叠加原理与矢量分解","type":"模型选择","judge":"五个点电荷在 O 点的场强能否直接代数相加，还是必须先分解到坐标轴再合成","why":"电场强度是矢量，五个场强方向各不相同（沿各自到 O 的连线），直接相加大小是错的，必须用矢量叠加","do":"以 O 为原点建立 xOy 坐标，把每个电荷在 O 点产生的场强写成矢量，再按 x、y 分量分别求和","expr":"\\vec E_O=\\sum_i \\frac{k q_i}{R^2}\\hat r_i","cues":["场强是矢量","先分解再合成","不能直接加大小"],"concepts":["电场叠加原理","矢量合成","点电荷场强"]},{"title":"确定各电荷的方位角","type":"几何关系","judge":"3q 在 y 轴正半轴、其余顺时针排列时，每个电荷相对 O 的方位角各是多少","why":"正五边形相邻顶点对中心张角为 72°，题目给出 3q 在 y 轴正半轴且顺时针依次为 q、2q、3q、4q、5q，方位角必须由这一顺序唯一确定，否则分量符号会错","do":"从 3q 的 90° 出发，按顺时针每隔 72° 依次写出 4q、5q、q、2q 的方位角","expr":"\\theta_{3q}=90^\\circ,\\ \\theta_{4q}=18^\\circ,\\ \\theta_{5q}=-54^\\circ,\\ \\theta_{q}=-126^\\circ,\\ \\theta_{2q}=162^\\circ","cues":["相邻差七十二度","3q在正上方","顺时针排下去"],"concepts":["正五边形几何","方位角","对称性"]},{"title":"对称抵消判断","type":"前提判断","judge":"五个场强中哪些分量成对抵消、哪些分量同向叠加","why":"正五边形顶点关于 y 轴对称分布，但电荷量 1q 与 4q、2q 与 5q 并不相等，不能简单说对称抵消，必须按分量逐对检查","do":"把五个场强分解为 x、y 分量，检查 y 分量是否两两抵消、x 分量是否全部同向","expr":"E_y=\\sum_i \\frac{k q_i}{R^2}\\sin\\theta_i,\\quad E_x=\\sum_i \\frac{k q_i}{R^2}\\cos\\theta_i","cues":["看y方向抵消","x方向同向","分量分别求和"],"concepts":["矢量分解","对称性分析"]},{"title":"提取公因子化简","type":"数学处理","judge":"求和结果能否提出 kq/R² 并化成含 cos18°、cos54° 的紧凑形式","why":"五个电荷量是 q 到 5q 的等差排列，只有把 kq/R² 提出、把系数按 18°、54° 的余弦归并，才能与选项形式对上","do":"令 E0=kq/R²，把各分量系数合并，利用 cos18°、cos54° 表示结果","expr":"E=\\frac{kq}{R^2}\\left(2\\cos18^\\circ+4\\cos54^\\circ\\right)","cues":["提出kq比R方","凑成余弦","合并同类项"],"concepts":["三角函数化简","公因子提取"]},{"title":"方向与大小定选项","type":"结论整理","judge":"合成后场强指向哪个方向、大小对应哪个表达式","why":"分量求和后 x 分量为负、y 分量为零，方向沿 x 轴负方向；大小由余弦组合给出，方向或系数写错都会选错项","do":"由 E_x<0、E_y=0 定方向，再核对大小表达式与选项是否一致","expr":"E=\\frac{2kq}{R^2}\\left(2\\cos54^\\circ+\\cos18^\\circ\\right),\\ \\text{方向沿}x\\text{轴负向}","cues":["沿x轴负方向","大小看余弦组合","方向和大小都要对"],"concepts":["合场强方向","结果核对"]}],"409":[{"title":"定值电阻的作用","type":"前提判断","judge":"判断 R0 是串在主干路上限流保护，还是与某支路并联分流","why":"由图(a)电路，R0 与电阻箱、电池串联在同一回路中，改变 R 时若 R 调到很小，回路电流会过大，可能损坏电流传感器或电池","do":"沿电路图追踪电流路径，确认 R0 与电阻箱串联而非并联，再判断其作用是限制最小阻值时的电流","expr":"","cues":["串联限流","防止电流过大","不是并联"],"concepts":["串联电路","限流保护"]},{"title":"闭合电路欧姆定律建模","type":"关系建立","judge":"判断把 R0 与 r 合并为同一串联电阻项，写出 I 与 R 的闭合回路方程","why":"电流传感器与手机无线连接，其内阻在后续问题中单独讨论；本问只按理想电流表处理，回路总电阻为 R+R0+r","do":"对闭合回路列 E=I(R+R0+r)，再取倒数化为 1/I 关于 R 的一次函数","expr":"\\frac{1}{I}=\\frac{R}{E}+\\frac{R_0+r}{E}","cues":["总电阻是三者相加","取倒数化直线","截距含内阻"],"concepts":["闭合电路欧姆定律","一次函数化"]},{"title":"图像斜率截距的物理含义","type":"图像读取","judge":"判断 1/I–R 图的斜率对应 1/E、纵轴截距对应 (R0+r)/E","why":"由关系式 1/I=(1/E)R+(R0+r)/E，与 y=kx+b 对照，斜率和截距分别对应电动势与内阻的组合","do":"从图(b)读出两点坐标，算斜率 k 和截距 b，再令 k=1/E、b=(R0+r)/E","expr":"k=\\frac{1}{E},\\quad b=\\frac{R_0+r}{E}","cues":["斜率是电动势倒数","截距含内阻","先读两点"],"concepts":["图像斜率","纵轴截距","等效电源"]},{"title":"截距求内阻要减 R0","type":"数学处理","judge":"判断由截距求 r 时必须先乘 E 再减去 R0，不能把截距直接当内阻","why":"截距 b=(R0+r)/E 是 R0 与 r 之和除以 E，R0=9.0 Ω 已知且不可忽略","do":"用 r=bE−R0 计算，并注意有效数字要求（E 三位、r 两位）","expr":"r=bE-R_0","cues":["截距不是内阻","要减掉定值电阻","注意有效数字"],"concepts":["截距换算","有效数字"]},{"title":"传感器内阻归属判断","type":"误差分析","judge":"判断电流传感器内阻在等效电源中算进 r 还是算进 E，从而确定对 r 测量值的影响","why":"传感器与电池串联，其内阻与电池内阻在方程中处于同一位置，被一起并入等效内阻","do":"把传感器内阻 r传 加入回路方程，与 r 合并成 r真+r传，比较测量值与真实值","expr":"r_\\text{测}=r_\\text{真}+r_\\text{传}","cues":["串在回路里","并进内阻","测量值偏大"],"concepts":["等效内阻","系统误差"]}],"410":[{"title":"游标卡尺读数规则","type":"实验操作","judge":"读数时判断主尺读数取整毫米部分、游标对齐格数乘精度后相加，且不估读","why":"游标卡尺精度由游标格数决定，本题游标为20分度，精度0.05 mm，读数=主尺整毫米数+对齐格数×精度","do":"读主尺整毫米刻度，找游标上与主尺刻线对齐的格数，相乘后相加并换算成厘米","expr":"L=L_0+n\\times 0.05\\,\\mathrm{mm}","cues":["看对齐格数","精度是0.05毫米","不用估读"],"concepts":["游标卡尺","精度","读数"]},{"title":"光电门测瞬时速度","type":"模型选择","judge":"判断用遮光片宽度除以挡光时间作为重锤经过光电门时的瞬时速度","why":"遮光片宽度足够小、挡光时间足够短，平均速度近似等于瞬时速度","do":"写出速度表达式，把d和t代入后续方程","expr":"v=\\frac{d}{t}","cues":["平均速度代替瞬时速度","挡光时间很短","用d除以t"],"concepts":["光电门","瞬时速度","平均速度"]},{"title":"选系统列机械能守恒","type":"模型选择","judge":"判断把两重锤和绳取作一个系统，用系统重力势能减少量等于系统动能增加量，避开绳的拉力","why":"绳两端拉力是内力，取整体后不做功，只有两重锤重力做功，可直接联系H与v","do":"列系统机械能守恒方程，把v=d/t代入解出g","expr":"(M-m)gH=\\frac{1}{2}(M+m)v^{2},\\quad g=\\frac{(M+m)d^{2}}{2(M-m)Ht^{2}}","cues":["取整体","避开绳的拉力","只看重力做功"],"concepts":["系统机械能守恒","整体法","重力势能"]},{"title":"识别a与β的线性关系","type":"关系建立","judge":"判断表格中a随β线性变化，斜率就是待求的g，截距含γg","why":"题给a=(β-γ)g说明a是β的一次函数，逐差法正是利用等间隔自变量下函数值的二阶差求斜率","do":"把四组数据按β等间隔0.02分组，用后两组之和减前两组之和求斜率","expr":"a_4+a_3-a_2-a_1=(\\beta_4+\\beta_3-\\beta_2-\\beta_1)g","cues":["a和β成一次函数","斜率就是g","逐差法求斜率"],"concepts":["一次函数","逐差法","斜率"]},{"title":"逐差法处理等间隔数据","type":"数据处理","judge":"判断逐差法要跨组相减（第3、4组减第1、2组），而不是相邻两项相减","why":"相邻相减会把每个数据误差放大且只用到局部信息，跨组相减能保留全部数据并消去截距","do":"计算(a4+a3)-(a2+a1)与(β4+β3)-(β2+β1)，相除得g并保留三位有效数字","expr":"g=\\frac{(a_4+a_3)-(a_2+a_1)}{(\\beta_4+\\beta_3)-(\\beta_2+\\beta_1)}","cues":["隔项相减","四组一起用","消掉截距"],"concepts":["逐差法","有效数字","误差"]},{"title":"判断M/m趋1时误差来源","type":"误差分析","judge":"判断M与m接近时系统加速度很小，绳两端拉力差占比变大，摩擦导致的偏差被放大","why":"加速度a=(β-γ)g，β很小时γg的相对影响显著，圆柱体不光滑使两端拉力不等，不能忽略","do":"比较β与γ的大小关系，说明β趋零时a偏离真实值的方向","expr":"a=(\\beta-\\gamma)g","cues":["加速度太小","摩擦影响变大","两端拉力不等"],"concepts":["动摩擦因数","系统误差","拉力差"]}],"411":[{"title":"镜面反射后进入AB边","type":"几何关系","judge":"光线经平面镜反射后，是射向AB边还是先射向AC/BC边，需由反射角与顶角关系确定","why":"AC紧贴镜面，反射光线从O点出发，O靠近A，反射角等于入射角α，反射光线与AC的夹角为90°−α，只有它与AB边相交才能从AB边射入棱镜","do":"画出反射光线，比较反射光线与AB边的夹角，求出光线射到AB边时的入射角","expr":"\\angle 1=\\angle BAC-(90^\\circ-\\alpha)","cues":["先画反射光线","看反射线打到哪条边","O靠近A"],"concepts":["反射定律","光路图","几何关系"]},{"title":"入射角与法线换算","type":"几何关系","judge":"光线射到AB边时，入射角是光线与AB边法线的夹角，而不是与AB边的夹角","why":"折射定律中的入射角、折射角都是相对法线定义的，必须把几何夹角换算成与法线的夹角","do":"由光线与AB边的夹角∠1，取其余角得到入射角∠2","expr":"\\angle 2=90^\\circ-\\angle 1","cues":["入射角对法线","别拿边夹角当入射角","取余角"],"concepts":["入射角","法线","折射定律"]},{"title":"等腰三角形顶角求底角","type":"几何关系","judge":"由AC=BC和∠C=30°判断出∠BAC=∠ABC=75°，作为后续所有角度计算的基准","why":"三角形内角和为180°，等腰三角形两底角相等，这是确定AB边方向和法线方向的依据","do":"用内角和与等腰条件算出底角","expr":"\\angle BAC=\\frac{180^\\circ-30^\\circ}{2}=75^\\circ","cues":["等腰三角形","两底角相等","内角和一百八"],"concepts":["等腰三角形","内角和","几何关系"]},{"title":"全反射临界角定折射角","type":"临界条件","judge":"在BC边刚好发生全反射时，BC边上的入射角等于临界角C′，由此反推AB边的折射角","why":"刚好全反射的临界条件是入射角等于临界角，sinC′=1/n，这是第（2）问的出发点","do":"先由折射率求临界角，再结合三角形内角和几何关系求AB边折射角∠3′","expr":"\\sin C'=\\frac{1}{n}=\\frac{\\sqrt{2}}{2},\\quad \\angle 3'=30^\\circ","cues":["刚好全反射","临界角","折射率定临界角"],"concepts":["全反射","临界角","折射率"]},{"title":"折射定律反推入射角","type":"关系建立","judge":"已知棱镜内折射角，用折射定律n=sin i/sin r反推AB边入射角，而不是直接由α求","why":"光从空气进入棱镜，空气侧为入射角、棱镜侧为折射角，n=sin∠2′/sin∠3′，只有先得∠3′才能求∠2′","do":"把∠3′=30°和n=√2代入折射定律求∠2′","expr":"n=\\frac{\\sin\\angle 2'}{\\sin\\angle 3'}","cues":["折射定律","空气到玻璃","由内角反推外角"],"concepts":["折射定律","入射角","折射角"]},{"title":"由AB入射角回推α","type":"关系建立","judge":"把AB边入射角∠2′与镜面入射角α通过几何链联系起来，解出α","why":"α经反射、经几何关系决定AB边入射角，第（1）问已建立∠1=∠BAC−(90°−α)与∠2=90°−∠1的链条，需反向使用","do":"由∠2′反解∠1′，再由∠1′=∠BAC−(90°−α′)解出α′","expr":"\\alpha'=90^\\circ-[\\angle BAC-(90^\\circ-\\angle 2')]","cues":["反推回去","几何链倒着用","从AB边回到镜面"],"concepts":["反射定律","几何关系","光路可逆"]}],"412":[{"title":"定圆心与半径公式","type":"模型选择","judge":"粒子在左侧磁场中只受洛伦兹力，需判断轨迹是匀速圆周运动并确定半径由哪个公式给出","why":"洛伦兹力始终垂直于速度，提供向心力，故轨迹为圆，半径由 qvB=mv²/R 决定","do":"对左侧磁场中的粒子列洛伦兹力等于向心力的方程，解出 R","expr":"qv_{0}B=\\frac{mv_{0}^{2}}{R}\\Rightarrow R=\\frac{mv_{0}}{qB}","cues":["洛伦兹力当向心力","轨迹是圆","半径看速度"],"concepts":["洛伦兹力","匀速圆周运动","向心力"]},{"title":"由弦长定出射角","type":"几何关系","judge":"O 到 MN 的距离与半径之比决定粒子从 MN 射出时速度与 MN 的夹角","why":"粒子从 O 出发沿平行 MN 方向射入，O 到 MN 的距离是轨迹圆的一条弦长的一半关系，需用几何关系把 d 与 R 联系起来求偏转角","do":"画出左侧轨迹圆，找出 O 到 MN 的垂距 d 与半径 R 构成的直角三角形，用 cos 或 sin 关系求夹角 θ","expr":"d=\\frac{3mv_{0}}{2qB},\\ R=\\frac{mv_{0}}{qB}\\Rightarrow \\cos\\theta=\\frac{d-R}{R}\\ \\text{类关系}\\Rightarrow\\theta=60^\\circ","cues":["先画圆找弦","距离比半径","出射角靠几何"],"concepts":["弦长","圆心角","几何关系"]},{"title":"无场区速度不变","type":"前提判断","judge":"MN 与 PQ 之间无磁场，粒子在此区域是否做匀速直线运动、速度方向与大小是否保持","why":"无磁场则无洛伦兹力，粒子不受力（不计重力），做匀速直线运动，速度大小和方向都不变","do":"判断粒子从 MN 到 PQ 沿直线匀速运动，进入 PQ 时速度与 PQ 的夹角等于从 MN 射出时的夹角 θ","expr":"v=v_{0},\\ \\theta_{PQ}=\\theta_{MN}=60^\\circ","cues":["中间没磁场","走直线","速度不变"],"concepts":["匀速直线运动","无磁场区域"]},{"title":"右侧半径与偏转方向","type":"关系建立","judge":"右侧磁场为 2B，需判断半径变为原来的一半，并判断粒子在右侧磁场中偏转的方向与圆心位置","why":"半径 R=mv/(qB) 与 B 成反比，B 加倍则半径减半；由左手定则（正电荷、磁场向外）确定偏转方向，才能画出第一次与第二次经过 PQ 的位置","do":"用 2B 代入半径公式求 R'，再由洛伦兹力方向定圆心，画出粒子在右侧磁场中从 PQ 进、再回到 PQ 的圆弧","expr":"R'=\\frac{mv_{0}}{q(2B)}=\\frac{mv_{0}}{2qB}","cues":["磁场加倍半径减半","先定偏转方向","画右侧圆弧"],"concepts":["左手定则","圆周运动"]},{"title":"两交点间距的几何计算","type":"几何关系","judge":"第一次与第二次经过 PQ 的两点间距由右侧圆弧的弦长决定，需判断弦长与 R'、偏转角的关系","why":"粒子在右侧磁场中偏转一段圆弧后再次穿过 PQ，两点连线是圆弧的弦，弦长由半径和圆心角（或入射角）决定","do":"在右侧圆弧中找出弦与半径构成的等腰三角形，用 θ=60° 及 R' 求弦长 x","expr":"x=2R'\\sin\\theta=\\sqrt{3}R'=\\frac{\\sqrt{3}mv_{0}}{2qB}","cues":["两点连线是弦","用等腰三角形","弦长看半径和角"],"concepts":["弦长","圆心角","几何关系"]},{"title":"周期分段与对称性","type":"结论整理","judge":"完整周期由左侧圆弧时间、右侧圆弧时间、两段无场区直线时间组成，需判断各段圆心角及无场区路程如何由对称性确定","why":"粒子回到 O 点做周期性运动，轨迹具有对称性；各段时间为弧长对应圆心角占整圆的比例乘周期，直线段路程由进出点间距与夹角决定","do":"分别求左侧圆弧圆心角（240°）、右侧圆弧圆心角（120°）对应的时间，再由对称性求 MN 到 PQ 的直线路程 l 并求 t3，最后相加","expr":"t_{1}=\\frac{2}{3}\\frac{2\\pi m}{qB},\\ t_{2}=\\frac{1}{3}\\frac{2\\pi m}{2qB},\\ l=\\frac{\\sqrt{3}R-\\sqrt{3}R'}{2\\cos\\theta},\\ t_{3}=\\frac{2l}{v_{0}}","cues":["分段算时间","看圆心角占比","对称定直线路程"],"concepts":["周期","圆心角","对称性","匀速直线运动"]}],"413":[{"title":"判断木板是否先静止","type":"前提判断","judge":"滑块1滑动时，木板受到的滑块摩擦力与地面最大静摩擦力谁大，木板动不动","why":"木板若一开始就动，滑块相对木板的位移不再是L，第(1)问的动能定理和后续碰撞间距全部失效","do":"比较滑块对木板的摩擦力 2μmg 与地面对木板的最大静摩擦力 μ(nm+3nm)g=4μnmg","expr":"2\\mu mg < 4\\mu n mg","cues":["先看木板动不动","地面摩擦更大","木板被压住"],"concepts":["最大静摩擦力","相对滑动","受力分析"]},{"title":"碰撞前用动能定理","type":"关系建立","judge":"滑块1碰前速度由哪段位移上的摩擦力做功决定","why":"木板不动，滑块1相对木板滑行L，只受木板给的滑动摩擦力2μmg做负功","do":"对滑块1从初速到碰前写动能定理，位移取L","expr":"-2\\mu mgL=\\frac12 m v_1^2-\\frac12 m v_0^2","cues":["只滑一个间距","摩擦力做负功","木板不动位移就是L"],"concepts":["动能定理","滑动摩擦力做功"]},{"title":"碰后粘合动量守恒","type":"模型选择","judge":"第j个滑块与第j+1个滑块极短碰撞中用什么规律联系碰前碰后速度","why":"碰撞时间极短，木板给的外摩擦冲量可忽略，系统动量守恒；碰后粘在一起用完全非弹性碰撞","do":"对j个滑块与第j+1个滑块写动量守恒，碰后共同质量(j+1)m","expr":"j m v_j'=(j+1)m v_{j+1}","cues":["碰撞极短用动量守恒","粘在一起是完全非弹性","质量变成j+1份"],"concepts":["动量守恒","完全非弹性碰撞"]},{"title":"递推式累积求和","type":"数学处理","judge":"如何把逐次碰撞的递推关系化成含β的单一方程","why":"每次碰撞都带一个j²因子，直接逐项代入无法得到闭式，必须把(j+1)²v_{j+1}²=j²v_j²-4j²μgL从j=2累加到k并套用平方和公式","do":"将递推式两边乘(j+1)²后逐项相加，用1²+…+k²公式合并","expr":"(k+1)^2v_{k+1}^2=\\beta\\mu gL-4\\mu gL\\sum_{j=1}^{k}j^2","cues":["把递推式乘开","一项一项累加","用平方和公式"],"concepts":["递推数列","平方和公式"]},{"title":"找木板起滑的临界块数","type":"临界条件","judge":"第几个滑块开始滑动时滑块总摩擦力恰好等于地面最大静摩擦力，木板从此起滑","why":"木板起滑前后滑块相对木板的加速度规律不同，必须先定出起滑发生在第k+1块，才能分段处理","do":"令2μkmg=μ(nm+3nm)g，解出k并与3n比较","expr":"2\\mu k mg=\\mu(nm+3nm)g\\Rightarrow k=2n","cues":["摩擦力刚好顶住地面","数到第几块起滑","k等于2n"],"concepts":["临界状态","最大静摩擦力"]},{"title":"恰好不再碰的共速条件","type":"临界条件","judge":"木板起滑后'恰好不再相碰'对应怎样的运动学临界","why":"不再相碰的极限是前面滑块与下一块恰好在相对位移为L时达到共速，此时两者速度相等且相对位移取满L","do":"对起滑后前k+1块与木板分别写速度-位移关系，令相对位移等于L且末速相同，联立求v_{k+1}","expr":"\\frac{v_{k+1}^2-v_共^2}{2a_{k+1}}-\\frac{v_共^2}{2a}=L,\\quad v_共=\\frac{v_{k+1}}{2n}","cues":["刚好追上就共速","相对位移正好一个间距","末速度相等"],"concepts":["追及相遇","相对位移","匀变速直线运动"]}],"414":[{"title":"衰变中的质量变化","type":"前提判断","judge":"衰变释放能量时，反应前后总质量是否守恒","why":"质能方程说明释放能量必然伴随质量亏损，衰变后总静质量小于衰变前","do":"比较衰变前后系统的总静质量，判断是否出现质量亏损","expr":"\\Delta E=\\Delta m c^2","cues":["释放能量","质量亏损","总质量变小"],"concepts":["质能方程","质量亏损","衰变"]},{"title":"半衰期的统计含义","type":"前提判断","judge":"半衰期描述的是单个核还是大量核的统计规律","why":"半衰期是大量放射性原子核有半数发生衰变所需的时间，对少数或单个核无意义","do":"看题干是否强调“大量”，确认半衰期定义适用的对象","expr":"","cues":["大量核","统计规律","单个核不行"],"concepts":["半衰期","统计规律"]},{"title":"半衰期的决定因素","type":"关系建立","judge":"半衰期由核内部结构决定，还是由温度、压强等外部条件决定","why":"半衰期是原子核自身的性质，由核内部结构决定，与外界物理条件无关","do":"把温度、压强等外部因素与核内部结构作对比，判断哪个能改变半衰期","expr":"","cues":["内部结构决定","与温度无关","外界条件没用"],"concepts":["半衰期","原子核结构"]},{"title":"化学变化的影响范围","type":"前提判断","judge":"化学方法能否改变原子核的衰变快慢","why":"化学反应只涉及核外电子，不改变原子核内部结构，因此不影响半衰期","do":"判断化学变化作用于核外电子还是原子核，据此确定是否影响半衰期","expr":"","cues":["化学只动电子","不碰原子核","半衰期不变"],"concepts":["半衰期","化学变化","核外电子"]}],"415":[{"title":"确定折射光线的几何位置","type":"几何关系","judge":"由 A 点入射、B 点出射，判断 AB 弦与 AC 直径的夹角，从而确定折射角","why":"B 是半圆中点，圆周角关系给出 ∠BAC=45°，折射光线沿 AB 方向，故折射角为 45°","do":"连接 AB，利用 B 为弧中点得 ∠BAC=45°，即折射角 r=45°","expr":"r=45^\\circ","cues":["连AB","B是中点","折射角看AB"],"concepts":["圆周角","折射角","光路图"]},{"title":"用折射定律反推入射角范围","type":"关系建立","judge":"由 n=sinθ/sin45° 且 n>1，判断入射角 θ 必须大于 45°","why":"光从真空进入介质，n>1，故 sinθ>sin45°，入射角必大于折射角","do":"写出 n=sinθ/sin45°，由 n>1 得 sinθ>√2/2","expr":"n=\\frac{\\sin\\theta}{\\sin45^\\circ}>1\\Rightarrow\\theta>45^\\circ","cues":["n大于1","入射角大于折射角","光密介质"],"concepts":["折射定律","折射率"]},{"title":"由折射角定临界角大小","type":"临界条件","judge":"由 sinC=1/n 与 n<√2，判断临界角 C 大于 45°","why":"n=√2 sinθ 且 sinθ<1，故 n<√2，从而 sinC>√2/2，临界角大于 45°","do":"将 n=√2 sinθ 代入 sinC=1/n，比较 C 与 45°","expr":"\\sin C=\\frac{1}{n}>\\frac{\\sqrt2}{2}\\Rightarrow C>45^\\circ","cues":["先求临界角","n小于根号二","临界角比45大"],"concepts":["全反射","临界角"]},{"title":"判断两界面入射角与临界角","type":"临界条件","judge":"比较光在 AB、BC 面上的入射角与临界角 C 的大小，判断哪一面可能全反射","why":"全反射条件是光从光密到光疏且入射角大于临界角；AB 面入射角大于 45°，BC 面入射角小于 45°","do":"改变入射角后重画光路，分别量出 AB、BC 面上的入射角，与 C>45° 比较","expr":"i_{AB}>45^\\circ,\\quad i_{BC}<45^\\circ","cues":["看AB面入射角","BC面入射角小","和临界角比"],"concepts":["全反射条件","入射角"]}],"416":[{"title":"同步轨道半径的确定","type":"前提判断","judge":"同步轨道的高度 h 是相对小行星表面量出的，轨道半径该取 R+h 还是 h","why":"万有引力定律和开普勒定律中的距离都是到中心天体的距离，题目给的是离表面高度，必须加上天体半径","do":"把同步轨道半径写成 R+h，表面附近轨道半径写成 R","expr":"r_同=R+h,\\quad r_近=R","cues":["高度不是半径","要加星球半径","轨道半径是到球心"],"concepts":["轨道半径","中心天体"]},{"title":"两轨道周期与半径配对","type":"关系建立","judge":"T0 与 R+h 配对、T1 与 R 配对，还是反过来","why":"同步轨道周期等于自转周期 T0，表面附近圆周运动周期为 T1，周期与半径必须一一对应，配错则比值颠倒","do":"对同步轨道用 T0、半径 R+h，对表面附近轨道用 T1、半径 R，列开普勒第三定律等式","expr":"\\frac{(R+h)^3}{T_0^2}=\\frac{R^3}{T_1^2}","cues":["同步轨道对应自转周期","近地轨道对应T1","别把周期配反"],"concepts":["开普勒第三定律","同步轨道"]},{"title":"解出半径的代数形式","type":"数学处理","judge":"由比值式解 R 时，是开三次方后整理成 T1、T0 的 2/3 次幂之比，还是直接线性相减","why":"(R+h)^3/R^3=(T0/T1)^2，两边开三次方才能得到 R 与 h 的关系，指数必须是 2/3","do":"两边开三次方得 (R+h)/R=(T0/T1)^{2/3}，再解出 R","expr":"R=\\frac{T_1^{2/3}}{T_0^{2/3}-T_1^{2/3}}h","cues":["先开三次方","指数是三分之二","分母是两者之差"],"concepts":["开普勒第三定律","幂运算"]},{"title":"质量表达式的来源","type":"模型选择","judge":"求 M 时用表面附近轨道的万有引力提供向心力，还是用同步轨道数据","why":"表面附近轨道半径恰为 R，与质量式中的 R 直接对应，一步消去卫星质量即可；用同步轨道会多出 R+h","do":"对表面附近轨道写引力等于向心力，消去卫星质量 m","expr":"\\frac{GMm}{R^2}=m\\frac{4\\pi^2}{T_1^2}R\\ \\Rightarrow\\ M=\\frac{4\\pi^2R^3}{GT_1^2}","cues":["用近表面轨道","引力提供向心力","卫星质量约掉"],"concepts":["万有引力提供向心力","黄金代换"]},{"title":"对照字母 a、b、c","type":"结论整理","judge":"把得到的 R、M 表达式与题干含 a、b、c 的形式逐位比对，确定各字母对应哪个周期","why":"题干用 a、b、c 代替具体量，只有指数和位置完全吻合才能确定对应关系","do":"比较 R 式中分子指数 2/3 对应 T1、分母减数对应 T0，M 式中 c^2 对应 T1^2","expr":"a=T_1,\\quad b=T_0,\\quad c=T_1","cues":["分子是a","减数是b","c跟T1一样"],"concepts":["量纲与形式对应","周期"]}],"417":[{"title":"A球三力平衡的几何","type":"几何关系","judge":"绳与竖直成60°、AB连线与绳成30°，能否定出库仑力方向与竖直的夹角","why":"A球只受重力、绳拉力、库仑力三力平衡，库仑力沿AB连线，必须由这两个角度推出它与竖直的夹角才能作平行四边形","do":"画A球受力图，由绳与竖直60°、连线与绳30°得库仑力与竖直方向夹角为30°","expr":"","cues":["先画受力图","连线与绳夹30度","库仑力沿连线"],"concepts":["三力平衡","平行四边形定则","库仑力方向"]},{"title":"用平行四边形定则求两力","type":"关系建立","judge":"三力平衡时，绳拉力与库仑力的合力是否与重力等大反向，从而解出T和F","why":"A球静止即合力为零，重力已知为mg，另两力的合力必须竖直向上、大小等于mg","do":"以重力为对角线的反向边作平行四边形，由30°几何关系解出T与F","expr":"T=mg,\\quad F=2mg\\cos30^{\\circ}=\\sqrt{3}mg","cues":["合力与重力反向","合成两力等于重力","解三角形"],"concepts":["三力平衡","力的合成"]},{"title":"剪断瞬间的突变判断","type":"临界条件","judge":"剪断轻绳瞬间，哪些力突变消失、哪些力保持不变","why":"绳的拉力由平衡需要决定，剪断即消失；重力与库仑力由位置和电荷决定，瞬间不变","do":"去掉绳拉力，把剩余的重力与库仑力按原方向合成，求合力","expr":"F_{\\text{合}}=mg","cues":["绳拉力瞬间消失","库仑力来不及变","重力不变"],"concepts":["力的突变","牛顿第二定律"]},{"title":"B球受力是否改变","type":"前提判断","judge":"剪断A的绳后，B球所受库仑力、重力、杆的作用力是否发生变化","why":"B球由固定轻杆支撑，剪断的是A的绳，B的位置和A的电荷分布瞬间未变，故B受力不变、仍静止","do":"比较剪断前后B球所受三个力，确认库仑力与重力不变，杆的作用力也不变","expr":"","cues":["B球位置没动","杆是固定的","B仍然静止"],"concepts":["平衡状态","固定杆约束"]}],"418":[{"title":"副边负载折算到原边","type":"模型选择","judge":"能否把副线圈所接的灯泡折算成原线圈回路中的一个等效电阻，从而把含变压器的电路化为纯电阻串联电路","why":"理想变压器两侧电压、电流成比例，副边电阻 R 在原边看进去等效为 k²R，只有折算后原边回路才能直接用串联分压求电流","do":"写出原、副边电压比与电流比，用原边电压除以原边电流定义等效电阻，联立消去副边量","expr":"R_{\\text{等}}=\\frac{U_1}{I_1}=k^{2}R","cues":["折算到原边","等效成一个电阻","副边折过来"],"concepts":["理想变压器","等效电阻","匝数比"]},{"title":"触点决定串联电阻个数","type":"前提判断","judge":"开关接 a、b、c 时，原线圈回路中分别串入几个阻值为 R 的电阻","why":"原边回路总电阻不同，分到原线圈上的电压就不同，灯泡亮度才可调；数错个数后面全错","do":"沿原线圈回路从电源出发数经过的固定电阻：接 a 时三个全接入，接 b 时两个，接 c 时一个","expr":"R_{\\text{总}}=k^{2}R+nR,\\quad n=3,2,1","cues":["接a串三个","接b少一个","接c只串一个"],"concepts":["串联电路","原线圈回路"]},{"title":"分压求原线圈电压","type":"关系建立","judge":"原线圈两端电压是否等于电源电压按等效电阻与串联电阻之比分得的那一部分","why":"原边回路是等效电阻 k²R 与若干 R 串联接在恒压源 U 上，原线圈只分到其中一部分，不能把 U 直接当原线圈电压","do":"用串联分压写出原线圈电压，再除以 k 得灯泡电压","expr":"U_1=\\frac{k^{2}R}{k^{2}R+nR}U,\\quad U_2=\\frac{U_1}{k}=\\frac{kU}{k^{2}+n}","cues":["先分压","原线圈不是全压","再除以匝数比"],"concepts":["串联分压","理想变压器电压比"]},{"title":"最大功率的匹配条件","type":"临界条件","judge":"灯泡功率最大时是否要求等效电阻等于外串电阻，而题中 k 未知能否断定满足","why":"把原边看成等效电源，外接等效电阻 k²R 与内阻 nR 相等时输出功率最大；k 未给定，k²R=3R 不一定成立，故不能断言功率最大","do":"写出灯泡功率随 k 的表达式，比较 k²R 与 3R 是否相等，判断能否取到极值","expr":"P=\\frac{k^{2}U^{2}}{(k^{2}+n)^{2}R}","cues":["看k是多少","不一定匹配","等效电源内阻"],"concepts":["等效电源","输出功率最大条件"]},{"title":"逐项核验电流与功率","type":"结论整理","judge":"每个选项给出的电压、电流、功率表达式是否与对应触点下的 n 值一致","why":"不同触点对应不同 n，代入同一通式即可一次性检验各项，避免逐项重算","do":"把 n=3、2、1 分别代入 U₂ 与 I₂ 的通式，与选项给出的式子比对","expr":"I_2=\\frac{kU}{(k^{2}+n)R}","cues":["代n检验","看分母对不对","通式比对"],"concepts":["变压器电流比","电功率"]}],"419":[{"title":"波长由波速频率定","type":"关系建立","judge":"是否用 λ=v/f 由波速和频率求波长，而不是凭几何长度猜","why":"波速、频率是波源和介质给定的，波长是派生量，必须由 λ=v/f 得出","do":"代入 v=10 m/s、f=2.5 Hz 算出波长，作为后面判断路程差与半波长关系的基准","expr":"\\lambda=\\frac{v}{f}","cues":["先算波长","波速除频率"],"concepts":["波长","波速","频率"]},{"title":"沿直线传播定路程","type":"几何关系","judge":"判断两列波各自沿哪条直线传到 C，从而确定传播路程","why":"题设明确波分别沿 AC、BC 方向传播，路程就是对应线段长，不是任意路径","do":"由 A(0,0)、C(0,3) 得 AC=3 m；由 B(4,0)、C(0,3) 用勾股定理得 BC=5 m","expr":"AC=3\\,\\mathrm{m},\\quad BC=\\sqrt{3^2+4^2}=5\\,\\mathrm{m}","cues":["沿直线走","勾股定理算斜边"],"concepts":["直线传播","几何距离"]},{"title":"到达时刻与已振动时间","type":"前提判断","judge":"判断某时刻某列波是否已到达 C，以及到达后 C 已振动了多长时间","why":"波的传播需要时间 t=s/v，叠加效果取决于两列波是否都已到达以及各自的振动相位","do":"分别算 t1=3/10 s、t2=5/10 s，并与所给时刻比较，得出各波在 C 处已振动的时间","expr":"t_1=\\frac{3}{10}\\,\\mathrm{s},\\quad t_2=\\frac{5}{10}\\,\\mathrm{s}","cues":["先看波到没到","算传播时间"],"concepts":["波的传播","振动时间"]},{"title":"半波长判减弱点","type":"临界条件","judge":"判断 C 点到两波源的路程差是波长的整数倍还是半波长奇数倍","why":"同相波源干涉时，路程差为半波长奇数倍处振动减弱，为波长整数倍处振动加强","do":"求 Δx=BC−AC，与 λ/2 比较，判断 C 是加强点还是减弱点","expr":"\\Delta x=5-3=2\\,\\mathrm{m}=\\frac{\\lambda}{2}","cues":["算路程差","看差几个半波长"],"concepts":["干涉","路程差","振动减弱"]},{"title":"等幅减弱点恒静止","type":"结论整理","judge":"判断两列振幅相同的波在减弱点叠加后 C 的位移和速度是否恒为零","why":"振幅相同、反相叠加完全抵消，合振幅为零，质点始终停在平衡位置","do":"由减弱点且振幅相同，得出 C 处合位移始终为零、速度为零","expr":"A_{\\text{合}}=A-A=0","cues":["振幅相同抵消","一直不动"],"concepts":["波的叠加","振幅","减弱点"]}],"420":[{"title":"电势能与电势的换算","type":"前提判断","judge":"由同一电势能 Ep 和各自电荷量（含正负）反推 O、A、B 三点电势的正负与大小","why":"电势能 Ep=qφ，电荷正负决定电势符号，电荷量大小决定电势数值，不先定出三点电势就无法谈等势线和场强","do":"对三个试探电荷分别写 Ep=qφ，解出 φO、φA、φB 并比较大小","expr":"\\varphi_O=\\frac{E_p}{q},\\ \\varphi_A=-\\frac{E_p}{q},\\ \\varphi_B=\\frac{E_p}{2q}","cues":["先算电势","带正负号","电荷量不同"],"concepts":["电势能","电势","试探电荷"]},{"title":"找等势点定等势线","type":"关系建立","judge":"在 OA、AB 边上找电势为零的点，判断这些点是否共线构成等势线","why":"匀强电场中等势线是直线，只有先找到两个电势相同的点才能确定等势线方向，进而定场强方向","do":"取 OA 中点 M 和 AB 上合适的分点 N，用线性插值求其电势，验证均为零后连线 MN","expr":"\\varphi_M=\\frac{\\varphi_O+\\varphi_A}{2}=0","cues":["取中点","找零电势点","连成等势线"],"concepts":["等势线","匀强电场","电势的线性分布"]},{"title":"场强垂直于等势线","type":"几何关系","judge":"由等势线 MN 的方向确定电场线方向，并判断其与 x 轴正方向的夹角","why":"电场线与等势线垂直且由高电势指向低电势，方向判断错则夹角和场强分量全错","do":"过 A 作 MN 的垂线，由高电势指向低电势定出指向，再用 AM=AN 得等腰直角三角形求夹角","expr":"\\angle NMA=45^{\\circ}","cues":["垂直等势线","由高到低","看等腰直角"],"concepts":["电场线","等势面","电场方向"]},{"title":"沿场强方向取距离求场强","type":"数学处理","judge":"用 E=U/d 时，d 必须取沿场强方向（即垂直等势线）的两点间距离，而不是任意两点间距","why":"E=U/d 中的 d 是沿场强方向的距离，若误用 OA 或 AM 的实际长度会算错场强大小","do":"取 A 到零等势线的垂直距离作为 d，代入 A 与零等势点的电势差求 E","expr":"E=\\frac{0-\\varphi_A}{\\frac{1}{2}d\\cos45^{\\circ}}=\\frac{2\\sqrt{2}E_p}{qd}","cues":["取垂直距离","不能直接用斜边","投影到场强方向"],"concepts":["匀强电场","电势差与场强的关系"]}],"421":[{"title":"切割长度随位置变化","type":"模型选择","judge":"要判断金属杆接入回路的有效长度 L 是否随 x 变化，能否当作定值处理","why":"导轨是抛物线，杆始终平行 y 轴，杆与两导轨交点间距随 x 增大而增大，L 是 x 的函数，不能当常量","do":"把杆所在横坐标 x 处的两交点纵坐标之差取为 L(x)，明确 L 随前进而增大","expr":"L=L(x)","cues":["长度在变","越走越长","不能当定值"],"concepts":["有效切割长度","抛物线导轨"]},{"title":"感应电动势与电流","type":"关系建立","judge":"要判断动生电动势用哪个速度、回路电阻如何随 L 变化，从而写出电流","why":"杆垂直切割磁感线，电动势由杆的有效长度和速度决定；回路电阻只由杆接入部分贡献（导轨电阻不计），电阻正比于 L","do":"写 E=BLv，总电阻 R=Lr0，相除得电流，注意 L 在分子分母中约去","expr":"I=\\frac{BLv}{Lr_{0}}=\\frac{Bv}{r_{0}}","cues":["电阻正比于长度","长度约掉","电流只看速度"],"concepts":["动生电动势","电阻定律","闭合电路欧姆定律"]},{"title":"安培力随长度变化","type":"前提判断","judge":"要判断维持匀速所需的恒力 F 是否真的恒定，即安培力是否与 L 无关","why":"安培力 F=BIL，电流虽与 L 无关，但力中仍含 L，L 变化则安培力变化，匀速所需的力也必须变化，与“恒力”矛盾","do":"把已求电流代入 F=BIL，检查 F 中是否残留 L 因子","expr":"F_{\\text{安}}=BIL=\\frac{B^{2}Lv}{r_{0}}","cues":["力里还有长度","恒力做不到","安培力在变"],"concepts":["安培力","匀速直线运动条件"]},{"title":"冲量累积求面积","type":"数学处理","judge":"要判断变力作用下求位移/面积该用动量定理对时间累积，还是用牛顿定律直接积分","why":"安培力随 L 变化，加速度不恒定，但安培力冲量可写成 B L q 形式，而 L·Δx 恰为扫过的面积增量，能把过程量转化为面积","do":"对微元时间列动量定理，把 BILΔt 中的 LΔt 换成面积元 ΔS，再对全过程求和","expr":"-\\frac{B^{2}}{r_{0}}\\Delta S=m\\Delta v\\ \\Rightarrow\\ S=\\frac{mv_{0}r_{0}}{B^{2}}","cues":["用动量定理","变力用冲量","面积元代替长度乘位移"],"concepts":["动量定理","安培力冲量","电磁感应中的面积"]},{"title":"面积与位移非线性","type":"几何关系","judge":"要判断面积减半时杆前进的距离是否也减半","why":"抛物线围成的面积随 x 按三次方增长（S∝x³），面积与位移不成正比，面积减半对应位移大于原来的一半","do":"由抛物线方程写出 S 与 x 的关系，比较 S/2 对应的 x 与原 x 的大小","expr":"S\\propto x^{3}","cues":["面积不是线性","抛物线越走越宽","减半位置偏后"],"concepts":["抛物线面积","非线性关系"]}],"422":[{"title":"爆炸后速度反向关系","type":"模型选择","judge":"爆炸瞬间 A、B 组成的系统动量是否守恒，能否用动量守恒把 A、B 的速度联系起来","why":"爆炸内力远大于外力，极短时间内动量守恒；若误用能量守恒或漏掉 A 的反向速度，后面所有速度关系都错","do":"对 A、B 取系统，沿水平方向列动量守恒方程，用质量 3m 与 m 表示两速度大小之比","expr":"3mv_1=mv_2","cues":["爆炸瞬间动量守恒","A和B反向","取AB系统"],"concepts":["动量守恒","爆炸模型"]},{"title":"完全非弹性碰撞合并","type":"模型选择","judge":"B 嵌入 C 属于哪类碰撞，碰后 D 的质量和速度如何确定","why":"B 嵌入 C 后共同运动，是完全非弹性碰撞，动量守恒但动能不守恒；若按弹性碰撞处理会算错 D 的初动能","do":"对 B、C 列动量守恒，求出组合体 D 的质量 6m 与速度 v","expr":"mv_2=6mv","cues":["嵌入就是完全非弹性","碰后一起运动","质量变成6m"],"concepts":["完全非弹性碰撞","动量守恒"]},{"title":"摩擦与重力做功抵消","type":"关系建立","judge":"D 从滑行到落地全过程合外力做功是否为零，初动能与落地动能是否相等","why":"滑行段摩擦力做负功 -μ·6mg·s_1，平抛段只有重力做正功 6mgh，而 s_1=h/μ 使两者大小恰好相等，这是题设给的特殊条件","do":"分别写出摩擦力做功与重力做功，代入 s_1=h/μ 比较两者大小","expr":"W_f=-\\mu\\cdot6mg\\cdot\\frac{h}{\\mu}=-6mgh,\\quad W_G=6mgh","cues":["摩擦力做功和重力做功","s1等于h比μ","合功为零"],"concepts":["动能定理"]},{"title":"平抛求抛出速度","type":"关系建立","judge":"由水平射程 s_2 和高度 h 如何反推 D 离开滑轨时的速度","why":"平抛竖直方向自由落体定时间，水平方向匀速定速度，这是把 s_2 与能量联系起来的唯一桥梁","do":"由 h 求飞行时间，再由 s_2 求抛出速度 v_0","expr":"h=\\frac12gt^2,\\quad s_2=v_0t\\Rightarrow v_0=s_2\\sqrt{\\frac{g}{2h}}","cues":["平抛分两个方向","先求时间","射程除以时间"],"concepts":["平抛运动","运动的分解"]},{"title":"能量反推与量纲核对","type":"数学处理","judge":"如何由 D 的初速度 v 反推爆炸总能量，并判断各选项表达式是否成立","why":"爆炸能量全部转化为 A、B 动能，需先用动能定理把 v 与 v_0 联系，再用动量关系把 v_1、v_2 换成 v，最后代入 v 的表达式","do":"用动能定理求 v，写出总能量 E 关于 v 的式子，再把 v 用 s_2、h 表示并化简","expr":"E=\\frac12\\cdot3mv_1^2+\\frac12mv_2^2=24mv^2=48mgh\\left(1+\\frac{s_2^2}{4h^2}\\right)","cues":["能量全给A和B","先换成同一个速度","看括号里是不是加号"],"concepts":["动能定理","能量守恒"]}],"423":[{"title":"螺旋测微器读数","type":"实验操作","judge":"判断固定刻度是否已露出半毫米刻线，以及可动刻度对齐的是哪一条","why":"螺旋测微器精度为 0.01 mm，需估读到 0.001 mm；半毫米刻线是否露出直接决定整数部分","do":"读主尺整毫米与半毫米刻线，再读可动刻度对齐格数并乘 0.01 mm，最后估读一位","expr":"D=D_0+n\\times0.01\\,\\mathrm{mm}","cues":["看半刻度露没露","估读到千分之一","对齐第几格"],"concepts":["螺旋测微器","估读"]},{"title":"匀速段取点与时间间隔","type":"图像读取","judge":"判断 A 到 E 之间跨了几个闪光间隔，以及位移该用哪两个位置读数相减","why":"频闪照片中相邻记录点时间间隔等于闪光周期，A、E 之间是 4 个间隔而非 5 个","do":"数清 A 到 E 的间隔数，用两端位置坐标之差求位移，再除以总时间","expr":"t=4T,\\quad v=\\frac{x_E-x_A}{4T}","cues":["数间隔不数点","四段不是五段","两端坐标相减"],"concepts":["频闪摄影","匀速直线运动","平均速度"]},{"title":"有效数字与单位换算","type":"数据处理","judge":"判断距离读数换算成米后的有效位数，结果应保留几位","why":"题目要求保留 2 位有效数字，且照片数据单位为 cm，需先换算再取舍","do":"把 cm 换算为 m，算出速度后按 2 位有效数字取舍","expr":"v=\\frac{\\Delta x}{t}\\;(2\\text{ 位有效数字})","cues":["先换成米","保留两位有效数字","厘米别忘除一百"],"concepts":["有效数字","单位换算"]},{"title":"匀速时三力平衡建模","type":"模型选择","judge":"判断匀速阶段小球受重力、浮力、黏滞阻力三力平衡，而非二力平衡","why":"小球浸没在液体中，排开液体产生浮力，忽略浮力会使 k 的表达式错误","do":"对匀速小球列竖直方向平衡方程，浮力用液体密度和球体积表示","expr":"\\rho gV=\\rho_0 gV+kDv","cues":["别忘了浮力","三力平衡","浸没排开液体"],"concepts":["受力平衡","浮力","黏滞阻力"]},{"title":"球体积用直径表示","type":"关系建立","judge":"判断体积应写成直径 D 的函数而不是半径，以便与阻力式中的 D 配套","why":"阻力 f=kDv 中给的是直径，体积若用半径表示会多出未知量 R，无法只用题给量表达 k","do":"把 V 用 D 表示后代入平衡式，解出 k 并化简","expr":"V=\\frac{\\pi D^3}{6},\\quad k=\\frac{(\\rho-\\rho_0)g\\pi D^2}{6v}","cues":["统一用直径","体积换成直径","消掉半径"],"concepts":["球体积公式","代数化简"]},{"title":"由表达式判断速度随直径变化","type":"结论整理","judge":"判断 k 为常量时匀速速度与直径的单调关系，而不是凭直觉猜","why":"同种材质、同种液体意味着 ρ、ρ₀、k 不变，v 与 D 的关系只能由第（4）问的表达式给出","do":"把 k 表达式变形为 v 关于 D 的式子，看 D 减小时 v 如何变化","expr":"v=\\frac{(\\rho-\\rho_0)g\\pi D^2}{6k}\\propto D^2","cues":["看表达式不看感觉","直径越小速度越小","同种材质k不变"],"concepts":["控制变量","正比关系"]}],"424":[{"title":"欧姆挡读数与倍率","type":"数据处理","judge":"指针落在表盘哪条刻度线、读数要不要乘倍率","why":"欧姆挡刻度不均匀且右端为零、左端为无穷，读数必须按欧姆刻度线读再乘选择开关的倍率","do":"读指针在欧姆刻度上的示数，再乘以“×1 k”的倍率","expr":"R=示数\\times 10^{3}\\ \\Omega","cues":["看最上面那条刻度","乘一千","指针在中间偏左"],"concepts":["欧姆表","倍率","刻度不均匀"]},{"title":"电流表内外接的取舍","type":"模型选择","judge":"待测电阻与√(R_A R_V)谁大，从而决定电流表内接还是外接","why":"电压表内阻约10 kΩ、电流表内阻约100 Ω，待测电阻达千欧量级，电压表分流不可忽略而电流表分压可忽略，只有内接才能把测量误差压小","do":"估算待测电阻数量级，与√(R_A R_V)比较后选定内接法，并据此连线","expr":"R_x\\gtrless\\sqrt{R_A R_V}","cues":["电阻挺大的","电压表会分流","用内接法"],"concepts":["伏安法","电流表内接","系统误差"]},{"title":"分压接法的实物连线","type":"实验操作","judge":"滑动变阻器分压接法要接哪三个接线柱、测量回路与分压回路如何分开","why":"题目明确要求分压接法，分压必须把变阻器整个电阻丝并在电源上，再从滑片和另一端引出电压","do":"把变阻器下两接线柱接电源、滑片与上接线柱引出作为分压输出，再串入电流表与水泥块的内接回路","expr":"","cues":["下面两个接线柱都接","滑片要引出一根","分压不是限流"],"concepts":["分压接法","滑动变阻器","实物连线"]},{"title":"电阻率公式中长度与截面的对应","type":"关系建立","judge":"电流沿哪个方向流过水泥块，电阻定律中的L和S分别对应a、b、c中的哪两个","why":"电阻定律R=ρL/S中L是电流方向上的长度、S是垂直于电流的横截面积，图(b)中电流沿高c方向，故L=c、S=ab","do":"先确定电流流向，再写出L与S，反解ρ","expr":"R=\\rho\\frac{c}{ab}\\Rightarrow\\rho=\\frac{Rab}{c}","cues":["电流是竖着流的","长度取高","截面积是长乘宽"],"concepts":["电阻定律","电阻率","横截面积"]},{"title":"报警器并联位置的判断","type":"关系建立","judge":"压力增大时R₁是变大还是变小，从而判断哪个电阻两端电压随压力增大而升高","why":"由图(c)压力越大电阻率越小、R₁越小，串联回路中R₁分压减小而R₂分压增大；报警器要在压力达到阈值时启动，就必须接在电压随压力增大而升高的元件上","do":"由ρ-F图判断R₁随F的变化趋势，再用串联分压判断U₁、U₂各自随F的变化方向","expr":"U_2=\\frac{R_2}{R_1+R_2}E","cues":["压力大电阻小","R₁电压反而降","接在电压升高的那个上"],"concepts":["串联分压","传感器","阈值"]},{"title":"电动势衰减对报警压力的影响","type":"临界条件","judge":"E减小时，要保持报警器两端仍为3 V，R₁需要变大还是变小，进而判断触发压力是升还是降","why":"报警阈值是固定电压3 V，由分压式U₂=R₂E/(R₁+R₂)可知E减小必须靠R₁减小来补偿，而R₁越小对应压力越大","do":"把U₂=3 V作为临界条件，分析E减小时R₁的补偿方向，再结合ρ-F图换算成压力的变化","expr":"\\frac{R_2}{R_1+R_2}E=3\\ \\mathrm{V}","cues":["电压不够要靠电阻补","R₁得再小一点","压力要更大才报警"],"concepts":["串联分压","临界条件","电源老化"]}],"425":[{"title":"液柱压强来源","type":"模型选择","judge":"竖直放置时被封闭气体的压强由大气压和液柱自身重力共同决定，需判断液柱重力产生的压强如何计入","why":"液柱静止，竖直方向受力平衡，液柱下表面压强等于上表面大气压加上液柱重力产生的压强","do":"对竖直管中的液柱列竖直方向力平衡，写出封闭气体压强","expr":"p_1=p_0+\\rho g h","cues":["液柱压气体","加上液柱重力","上下压强差"],"concepts":["液体压强","力平衡","封闭气体压强"]},{"title":"水平时压强判断","type":"前提判断","judge":"细管转为水平后，液柱不再沿管方向产生重力压强，需判断此时封闭气体压强是否等于大气压","why":"水平放置时液柱重力方向垂直于管轴，不沿管方向压气体，液柱两端气压相等","do":"比较水平管中液柱两端受力，确定封闭气体压强","expr":"p_2=p_0","cues":["水平后只剩大气压","重力不压气体","两端压强相等"],"concepts":["液体压强","力平衡"]},{"title":"等温过程选律","type":"关系建立","judge":"第（1）问温度不变，需判断用玻意耳定律联系两个状态的压强与体积","why":"质量一定、温度不变的气体，压强与体积成反比","do":"对竖直和水平两状态列等温方程，体积用气柱长度乘横截面积表示","expr":"p_1L_1S=p_2L_2S","cues":["温度不变","等温变化","压强乘体积不变"],"concepts":["玻意耳定律","等温过程"]},{"title":"等容过程选律","type":"关系建立","judge":"第（2）问中水平放置时气柱长度与竖直时相同，需判断体积不变而用查理定律联系压强与温度","why":"气柱长度相同、管粗细均匀，则气体体积相同，质量一定时压强与热力学温度成正比","do":"对竖直状态和调温后的水平状态列等容方程","expr":"\\frac{p_1}{T_1}=\\frac{p_2}{T_2}","cues":["长度相同体积相同","等容变化","压强比温度"],"concepts":["查理定律","等容过程"]},{"title":"联立消元求g","type":"数学处理","judge":"第（2）问中p_1含未知g、p_2已知，需判断由等容关系直接解出g而不引入L_1、L_2","why":"等容方程中体积已约去，只剩p_1、p_2与温度，p_1中唯一未知量是g","do":"将p_1=p_0+ρgh与p_2=p_0代入等容方程，解出g","expr":"g=\\frac{p_0(T_1-T_2)}{\\rho h T_2}","cues":["体积约掉","只剩重力加速度","直接解出"],"concepts":["查理定律","数学消元"]}],"426":[{"title":"滑片在中点时的分压","type":"前提判断","judge":"滑动变阻器滑片在中点时，接入电路的是哪一部分电阻、电容器两端电压取的是哪段电压","why":"滑片在中点说明接入电阻为最大值的一半，即 r0；电容器与接入的那一半并联，电压等于该部分的分压，而不是电源电动势","do":"画出等效电路，确认接入电阻为 r0，用串联分压求电容器两端电压","expr":"U=\\frac{r_0}{r_0+r_0}E_0=\\frac{E_0}{2}","cues":["滑片在中点","接入一半电阻","电压不是电动势"],"concepts":["闭合电路欧姆定律","串联分压","电容器电压"]},{"title":"类平抛的分解与出射速度","type":"模型选择","judge":"粒子在电容器内受恒定电场力、初速度水平，应把运动分解为水平匀速和竖直匀加速两段处理","why":"电场力竖直向下且恒定，初速度与力垂直，符合类平抛模型；水平位移和竖直位移分别由板长和偏转量给出","do":"水平方向用板长除以初速度求时间，竖直方向用平均速度公式求末竖直分速度","expr":"\\sqrt{3}d=v_0t,\\quad \\frac{d}{2}=\\frac{0+v_y}{2}t","cues":["类平抛","水平匀速","竖直匀加速"],"concepts":["类平抛运动","运动的分解"]},{"title":"由偏转量反求电荷量","type":"关系建立","judge":"把竖直加速度与电场力、板间电压联系起来，才能由已知偏转量解出 q","why":"竖直方向加速度由电场力提供，而电场力由板间电压和板间距决定，电压又由电路分压给出，三者必须串成一条链","do":"写出竖直加速度表达式，代入时间消去 t，再代入电压 U 解出 q","expr":"a=\\frac{qU}{md},\\quad v_y=at,\\quad q=\\frac{mv_0^2}{E_0}","cues":["电场力提供加速度","电压用分压","消去时间"],"concepts":["牛顿第二定律","匀强电场"]},{"title":"磁场中圆周运动的几何定半径","type":"几何关系","judge":"粒子从下极板右边缘 b 进入、从上极板右边缘 c 射出，圆心位置和半径要由入射速度方向与边界几何共同确定","why":"粒子在磁场中只受洛伦兹力做匀速圆周运动，轨迹半径不能直接由题给长度读出，必须用速度方向角与板间距的几何关系求出","do":"先由速度分量求入射方向角，再由弦长与圆心角关系求半径","expr":"\\tan\\theta=\\frac{v_x}{v_y}=\\sqrt{3},\\quad R=\\frac{d/2}{\\cos30^\\circ}=\\frac{\\sqrt{3}d}{3}","cues":["先定入射方向","弦长定半径","画圆心"],"concepts":["洛伦兹力","匀速圆周运动","几何关系"]},{"title":"速度分解法处理复合场","type":"模型选择","judge":"同时存在磁场和水平电场时，不能直接当圆周运动，要把速度分解出一个使洛伦兹力与电场力平衡的竖直分量","why":"电场力水平向右恒定，只有让洛伦兹力与之等大反向，剩余速度才做匀速圆周运动，这是速度选择器式的分解思路","do":"设竖直向上分速度使 qvB=qE，求出该分速度，剩余分速度做圆周运动","expr":"qv_{y1}B=qE,\\quad v_{y1}=\\frac{2\\sqrt{3}}{3}v_0","cues":["速度分解","洛伦兹力平衡电场力","剩余速度做圆周"],"concepts":["速度选择器","洛伦兹力","运动的合成与分解"]},{"title":"最远水平距离的临界位置","type":"临界条件","judge":"粒子相对电容器右侧的最远水平距离出现在圆周运动轨迹的最右端，需用半径与偏角合成","why":"匀速直线运动只改变竖直位置不改变水平距离，水平距离的极值完全由圆周分运动的轨迹决定，最右点对应半径方向水平","do":"求合速度大小与方向角，算圆周半径，再用半径加水平投影求最远距离","expr":"v'=2v_0,\\quad r=\\frac{mv'}{Bq}=d,\\quad x_m=r+r\\cos\\alpha","cues":["最右端在圆周上","直线运动不改水平距离","半径加投影"],"concepts":["圆周运动极值","临界位置"]}],"427":[{"title":"绳长不变的圆周约束","type":"模型选择","judge":"滑杆固定时，机器人绕悬点做半径恒为 L 的圆周运动，还是做一般曲线运动","why":"轻绳不可伸长且始终绷紧，机器人到滑杆的距离恒为 L，轨迹被约束在圆周上","do":"以滑杆为圆心、L 为半径确定机器人各位置的几何关系，把速度方向取为圆周切线方向","expr":"r=L","cues":["绳长不变","绕悬点转圈","半径就是绳长"],"concepts":["圆周运动","绳约束"]},{"title":"最低点向心力求拉力","type":"关系建立","judge":"在最低点求绳拉力时，用牛顿第二定律的径向分量，而不是只做受力平衡","why":"最低点机器人有向心加速度，拉力与重力的合力提供向心力，不能令 F=mg","do":"先由 B 到最低点的动能定理求最低点速度，再在最低点沿径向列牛顿第二定律","expr":"F-mg=m\\frac{v_0^2}{L}","cues":["最低点有向心加速度","不能受力平衡","合力指向圆心"],"concepts":["向心力","牛顿第二定律","动能定理"]},{"title":"松绳后做斜抛运动","type":"模型选择","judge":"松绳瞬间速度沿绳的切线方向，松绳后只受重力，应作为斜抛（或平抛类）处理","why":"绳松开后约束消失，机器人只受重力，初速度方向由松绳位置的切线决定","do":"把松绳点速度分解为水平、竖直分量，分别列匀速与匀变速方程，并注意抛点与 A 点的水平、竖直位移","expr":"x=L\\cos37^\\circ+L,\\quad y=1.2L-L\\sin37^\\circ","cues":["松绳后只受重力","速度沿切线","分解成水平和竖直"],"concepts":["斜抛运动","运动的分解"]},{"title":"滑杆可动时水平动量守恒","type":"前提判断","judge":"滑杆可自由滑动时，机器人与滑杆组成的系统在水平方向是否动量守恒","why":"轨道光滑、水平方向无外力，系统水平动量守恒；竖直方向有重力与支持力，不守恒","do":"取机器人和滑杆为系统，只沿水平方向列动量守恒，并配合人船模型确定水平位移关系","expr":"mv_x=kmv_2,\\quad mx_1=kmx_2","cues":["水平方向没外力","取人和杆整体","竖直方向不守恒"],"concepts":["动量守恒","人船模型","系统"]},{"title":"相对速度沿绳方向","type":"几何关系","judge":"机器人相对滑杆的速度方向沿绳（垂直于绳的径向分量为零），据此建立两速度分量间的关系","why":"绳不可伸长，机器人相对悬点的速度只能垂直于绳，即相对速度沿绳方向的分量满足约束","do":"把机器人速度与滑杆速度都分解到沿绳和垂直绳方向，令相对速度沿绳方向，得到分量关系","expr":"\\tan37^\\circ=\\frac{v_x+v_2}{v_y}","cues":["相对速度沿绳","绳不能伸长","分解到沿绳方向"],"concepts":["相对速度","速度分解","绳约束"]},{"title":"能量守恒含滑杆动能","type":"关系建立","judge":"滑杆可动时，机器人减少的重力势能转化为机器人与滑杆两者的动能，不能只算机器人","why":"绳的拉力对机器人和滑杆都做功，系统机械能守恒，滑杆获得动能必须计入","do":"从 B 点到松绳点对系统列机械能守恒，把机器人速度按水平、竖直分量展开，再与动量、速度约束联立消元","expr":"\\frac12mv^2=mgL\\sin37^\\circ+\\frac12m(v_x^2+v_y^2)+\\frac12kmv_2^2","cues":["杆也动起来了","能量分给两个物体","不能只算机器人动能"],"concepts":["机械能守恒","系统动能","速度分解"]}],"428":[{"title":"激发上限的判定","type":"临界条件","judge":"50 eV 的电子最多能把 He⁺ 激发到哪一能级","why":"电子碰撞激发时，电子把能量交给离子，离子吸收的能量不能超过入射电子的动能，因此只能跃迁到能级差不超过 50 eV 的激发态","do":"在能级图上读出各激发态相对基态的能量，与 50 eV 逐一比较，取不超过 50 eV 的最高能级","expr":"E_n - E_1 \\le 50\\,\\mathrm{eV}","cues":["看能级差","不能超过50","最高到哪一级"],"concepts":["能级跃迁","能量守恒"]},{"title":"可及能级的范围","type":"前提判断","judge":"被激发后离子可能处在哪些能级上","why":"只要某个激发态的能量低于 50 eV，电子碰撞就可能把离子送到该态，因此可及能级不止最高那一级，还包括所有更低的激发态","do":"列出所有能量低于 50 eV 的激发态，作为后续可能发出谱线的初态","expr":"","cues":["不止最高能级","低能级也能到","所有可能的态"],"concepts":["激发态","能级结构"]},{"title":"波长最长对应最小能差","type":"关系建立","judge":"波长最长对应哪一种跃迁","why":"由 ΔE = hc/λ 可知波长与跃迁能级差成反比，波长最长即能级差最小","do":"把“找最长波长”转化为“在所有可及跃迁中找最小能级差”","expr":"\\lambda = \\frac{hc}{\\Delta E}","cues":["波长最长能差最小","反比关系","先找最小能差"],"concepts":["光子能量","波长与能差关系"]},{"title":"相邻能级差最小","type":"数学处理","judge":"在可及跃迁中哪一对能级的差最小","why":"能级越高越密集，相邻高能级之间的间隔小于低能级之间的间隔，故最小能差出现在可及的最高两个相邻能级之间","do":"比较各相邻能级差，取可及范围内最高两相邻能级之差","expr":"\\Delta E_{\\min} = E_{n_{\\max}} - E_{n_{\\max}-1}","cues":["能级越高越密","相邻能级差最小","取最高两级"],"concepts":["能级间隔","跃迁"]}],"429":[{"title":"速度决定轨道类型","type":"前提判断","judge":"要判断小星球在给定速度下做哪种轨道运动，取决于速度与两个临界速度的大小关系","why":"万有引力提供向心力时做圆周运动；速度偏大则做离心运动，偏小则做近心运动，轨道类型由速度与临界值比较决定","do":"先算出圆周运动所需速度与逃逸速度两个临界值，再把题给速度与它们比较","expr":"v_c=\\sqrt{\\frac{GM}{R}},\\quad v_e=\\sqrt{\\frac{2GM}{R}}","cues":["先算临界速度","看速度够不够大","比一比两个临界值"],"concepts":["万有引力","向心力","临界速度"]},{"title":"圆周运动条件","type":"关系建立","judge":"要判断速度恰好等于圆轨道速度时，万有引力是否刚好提供所需向心力","why":"只有引力恰好等于所需向心力时，半径才保持不变，轨道才是圆","do":"令万有引力等于向心力，解出对应的圆轨道速度","expr":"\\frac{GMm}{R^2}=m\\frac{v^2}{R}\\Rightarrow v=\\sqrt{\\frac{GM}{R}}","cues":["引力刚好够用","半径不变","列向心力方程"],"concepts":["向心力","匀速圆周运动"]},{"title":"逃逸速度临界","type":"临界条件","judge":"要判断速度达到多大时小星球才能脱离恒星引力束缚","why":"引力束缚的临界对应总机械能为零，此时轨道为抛物线，速度再大则做双曲线运动","do":"由动能与引力势能之和为零解出逃逸速度，作为椭圆与抛物线、双曲线的分界","expr":"\\frac{1}{2}mv^2-\\frac{GMm}{R}=0\\Rightarrow v=\\sqrt{\\frac{2GM}{R}}","cues":["能不能跑掉","机械能为零","抛物线是分界"],"concepts":["引力势能","机械能","逃逸速度"]},{"title":"区间对应轨道形状","type":"结论整理","judge":"要判断速度落在两个临界值之间的区间时轨道是椭圆而非抛物线","why":"速度介于圆轨道速度与逃逸速度之间时引力不足做圆周但足以束缚，轨道为椭圆；等于逃逸速度为抛物线；超过则为双曲线","do":"把速度区间与轨道形状一一对应，排除把椭圆说成抛物线、把双曲线说成相撞的选项","expr":"\\sqrt{\\frac{GM}{R}}<v<\\sqrt{\\frac{2GM}{R}}\\Rightarrow \\text{椭圆}","cues":["中间那段是椭圆","抛物线要刚好逃逸","再大就飞走了"],"concepts":["椭圆轨道","抛物线轨道","双曲线轨道"]}],"430":[{"title":"受力方向与合力","type":"模型选择","judge":"火箭受到的推力和重力方向相反，合力是两者之差而不是之和","why":"推力竖直向上、重力竖直向下，牛顿第二定律中的 F 必须是合外力","do":"画火箭受力图，取竖直向上为正，写出合力表达式","expr":"F_{合}=F-mg","cues":["推力减重力","方向相反","取向上为正"],"concepts":["合外力","受力分析","牛顿第二定律"]},{"title":"质量单位换算","type":"前提判断","judge":"把火箭质量的吨换算成千克后再代入","why":"牛顿、米每二次方秒都是国际单位制，质量必须用千克","do":"将 500 t 乘以 1000 化为千克","expr":"m=500\\,\\mathrm{t}=5\\times10^{5}\\,\\mathrm{kg}","cues":["吨要换千克","乘一千","统一单位"],"concepts":["国际单位制","单位换算"]},{"title":"重力不可忽略","type":"近似条件","judge":"判断发射初期重力 mg 是否远小于推力、能否略去","why":"mg 约为 5×10⁶ N，与推力 6×10⁶ N 同量级，略去重力会使结果偏大数倍","do":"算出 mg 并与推力比较，确认必须保留重力项","expr":"mg=5\\times10^{6}\\,\\mathrm{N}\\approx F","cues":["重力不能丢","和推力差不多大","不能只算推力"],"concepts":["重力","量级比较"]},{"title":"由合力求加速度","type":"关系建立","judge":"用合外力除以质量得到加速度，而不是用推力除以质量","why":"牛顿第二定律 F_合=ma 中 F 是合外力","do":"把合力表达式代入第二定律解出 a","expr":"a=\\frac{F-mg}{m}","cues":["合力除以质量","先求合力","用第二定律"],"concepts":["牛顿第二定律","加速度"]}],"431":[{"title":"碰撞方向分离","type":"模型选择","judge":"碰撞只改变水平方向速度，竖直方向运动不受影响","why":"B 从左侧水平击中小球 A，冲量沿水平方向，竖直方向无冲量，A 的竖直分速度在碰撞前后不变","do":"把 A 的运动拆成竖直自由落体和水平匀速两段，碰撞只作用在水平段","expr":"","cues":["水平碰竖直不管","竖直速度不变","分开看两个方向"],"concepts":["运动的独立性","动量守恒"]},{"title":"等质量弹性碰交换速度","type":"关系建立","judge":"两球质量相等且完全弹性正碰时，碰后 A 获得 B 原来的水平速度，B 水平速度变为零","why":"水平动量守恒与动能守恒联立，等质量弹性碰撞的解就是速度交换，不必再设两个未知数硬解","do":"直接写出碰后 A 的水平速度等于碰前 B 的速度 v，B 碰后水平速度为零","expr":"$v_1=v,\\quad v_2=0$","cues":["等质量交换速度","碰后B停下","不用解方程"],"concepts":["弹性碰撞","速度交换"]},{"title":"求落地总时间","type":"前提判断","judge":"A 从 20 m 处自由下落，落地总时间为 2 s，碰后到落地只剩 1 s","why":"竖直方向始终是自由落体，与水平碰撞无关，由高度定总时间；1 s 末碰撞，剩余时间才是水平位移所用的时间","do":"用自由落体位移公式由 h=20 m 求总时间，再减去已过的 1 s","expr":"$h=\\frac12gt^2\\Rightarrow t=2\\,\\mathrm{s},\\quad t'=1\\,\\mathrm{s}$","cues":["先算总时间","碰后只剩一秒","竖直定时间"],"concepts":["自由落体","运动时间"]},{"title":"水平位移反推速度","type":"关系建立","judge":"碰后 A 的水平位移 3 m 是在剩余 1 s 内以速度 v 匀速走完的","why":"水平方向碰后不受力，做匀速直线运动，位移等于速度乘剩余时间","do":"用剩余时间去除水平位移，得到碰前 B 的速度","expr":"$x=vt'\\Rightarrow v=\\frac{3}{1}=3.0\\,\\mathrm{m/s}$","cues":["水平匀速","位移除以时间","用剩下的一秒"],"concepts":["匀速直线运动","水平位移"]}],"432":[{"title":"电场线方向定电势高低","type":"前提判断","judge":"沿电场线方向电势是降低还是升高","why":"电场线由高电势指向低电势，这是判断任意两点电势高低的基本依据","do":"从图中读出电场线由上方极板指向下方极板，沿电场线从 N 到 P 走一遍","expr":"","cues":["顺着电场线走","电势往下掉"],"concepts":["电场线","电势"]},{"title":"等势面联系两点电势","type":"关系建立","judge":"M 与 N 在同一等势面上意味着什么，能否把 M 的电势换成 N 的电势来比较","why":"同一等势面上各点电势相等，可把 M、P 的电势比较转化为同一电场线上 N、P 的比较","do":"先写 M、N 等势，再沿同一电场线比较 N 与 P 的电势","expr":"\\varphi_M=\\varphi_N>\\varphi_P","cues":["同一等势面","换成同一条线比"],"concepts":["等势面","电势差"]},{"title":"电场线疏密定场强大小","type":"图像读取","judge":"M 处与 N 处哪里的电场线更密，从而判断场强大小","why":"电场线越密处电场强度越大，这是非匀强电场中比较场强的唯一图像依据","do":"比较 M、N 附近电场线的疏密程度","expr":"","cues":["看疏密","密的地方场强大"],"concepts":["电场线","电场强度"]},{"title":"电势能变化定做功正负","type":"关系建立","judge":"负电荷从高电势移到低电势时电势能是增大还是减小，电场力做正功还是负功","why":"电势能变化与电场力做功满足 W=-ΔEp，负电荷在高电势处电势能反而小","do":"先由电势高低定电势能增减，再由功能关系定电场力做功正负","expr":"W_{MP}=-\\Delta E_p=q(\\varphi_M-\\varphi_P)","cues":["负电荷反着来","高电势处电势能小"],"concepts":["电势能","电场力做功"]},{"title":"动能随做功变化","type":"结论整理","judge":"只有电场力做功时动能如何随电场力做功变化","why":"由动能定理，电场力做负功则动能减小、速率减小","do":"把上一步做功正负接到动能增减上，得出速度变化","expr":"W_{MP}=\\Delta E_k","cues":["做负功就减速","动能定理接上"],"concepts":["动能定理","动能"]}],"433":[{"title":"磁通量由B与S共同决定","type":"关系建立","judge":"判断磁通量Φ随B的变化规律，即Φ与B是否同相位、同增减","why":"题设金属框平面始终与磁感线垂直且面积S不变，由Φ=BS知Φ与B成正比，Φ-t图与B-t图同形，故Φ的极值点、零点位置与B完全相同","do":"写出Φ=BS，确认S恒定，把B-t图直接当作Φ-t图（只差常数倍S）来读极值和零点","expr":"$\\Phi=BS$","cues":["面积不变","Φ跟着B走","同增同减"],"concepts":["磁通量","有效面积"]},{"title":"电动势看磁通变化率","type":"前提判断","judge":"判断感应电动势E由Φ本身的大小还是由Φ的变化快慢（即B-t图斜率）决定","why":"法拉第电磁感应定律E=nΔΦ/Δt，E只与磁通量的变化率成正比，与Φ的瞬时值大小无关；这是全题的核心，混淆Φ大与E大就会选错","do":"明确E∝ΔΦ/Δt=S·ΔB/Δt，把问题转化为读B-t曲线各点的切线斜率","expr":"$E=\\dfrac{\\Delta\\Phi}{\\Delta t}=S\\dfrac{\\Delta B}{\\Delta t}$","cues":["看斜率","不看高度","变化率才是电动势"],"concepts":["法拉第电磁感应定律","磁通量变化率"]},{"title":"正弦曲线斜率的变化","type":"图像读取","judge":"判断正弦形B-t曲线在四分之一周期内斜率如何变化、在哪些点斜率为零或最大","why":"B按正弦规律变化，其斜率按余弦规律变化：峰值处斜率为零，过零点处斜率最大；不读出这一图像特征就无法比较各时刻E的大小","do":"在B-t图上找出t=T/4（峰值，斜率0）与t=T/2（过零，斜率最大），并比较0~T/4内切线由陡变缓","expr":"$B=B_m\\sin\\dfrac{2\\pi}{T}t,\\quad \\dfrac{\\Delta B}{\\Delta t}\\propto\\cos\\dfrac{2\\pi}{T}t$","cues":["峰值处最平","过零处最陡","斜率越来越小"],"concepts":["正弦图像斜率","变化率"]},{"title":"对称时刻斜率等大反向","type":"数学处理","judge":"判断t=T/8与t=3T/8两时刻斜率的大小关系与正负关系","why":"余弦函数关于t=T/4对称，两时刻到峰值的距离相等，故斜率绝对值相等而符号相反，对应E大小相等、方向相反，这正是干扰项设错之处","do":"比较两时刻在B-t图上切线的陡峭程度与倾斜方向，得出|E|相等、方向相反","expr":"$\\left|\\dfrac{\\Delta B}{\\Delta t}\\right|_{T/8}=\\left|\\dfrac{\\Delta B}{\\Delta t}\\right|_{3T/8}$","cues":["对称位置","陡度一样","一升一降"],"concepts":["对称性","感应电动势方向"]}],"434":[{"title":"加速与偏转的衔接","type":"关系建立","judge":"偏转电场的入射速度由哪段电场决定、用什么方程求出","why":"离子初速为零，只在加速电场中获得动能，进入偏转场后速度大小不变，这是把两段电场联系起来的唯一桥梁","do":"对加速段写动能定理，解出 v0，作为偏转段类平抛的初速度","expr":"qU_1=\\frac{1}{2}mv_0^2","cues":["先求进入偏转场的速度","加速电场给动能"],"concepts":["动能定理","加速电场"]},{"title":"类平抛分解与边缘条件","type":"模型选择","judge":"偏转段按什么模型处理，以及“恰好从极板边缘射出”对应哪个位移","why":"电场竖直、初速水平，是类平抛；恰好从边缘射出意味着出板时竖直位移恰为板间距的一半","do":"沿板方向写匀速、垂直板方向写初速为零的匀加速，竖直位移取 d/2，联立消去飞行时间","expr":"l=v_0t,\\quad \\frac{d}{2}=\\frac{1}{2}\\frac{qU_m}{dm}t^2","cues":["类平抛","竖直位移取一半板距","水平方向匀速"],"concepts":["类平抛运动","运动的分解"]},{"title":"出板后直线外推","type":"几何关系","judge":"离子离开偏转场后做什么运动，样品上的落点由出板时的速度方向决定","why":"出板后无电场，离子做匀速直线运动，其轨迹是出板点处速度方向的延长线","do":"用出板点的竖直位移与水平位移之比表示速度方向，再按相似三角形把这条直线延长到样品平面","expr":"\\frac{d/2}{a/2}=\\frac{l/2}{l/2+L}","cues":["用相似三角形延长","看速度方向不看位移"],"concepts":["匀速直线运动","相似三角形"]},{"title":"辐照范围与偏转量的关系","type":"前提判断","judge":"样品上辐照范围的大小由哪个偏转量决定，从而判断该调大还是调小加速电压","why":"样品范围由离子出板时的偏转位移（即速度偏角）决定，偏转位移越大范围越大，而偏转位移与加速电压成反比","do":"写出偏转位移随 U1 变化的表达式，判断增大范围需减小 U1","expr":"y=\\frac{U_ml^2}{4dU_1}","cues":["偏转越大范围越大","偏转位移","控制变量"],"concepts":["偏转位移","控制变量"]},{"title":"交变电压下的偏转方向","type":"图像读取","judge":"从 U2-t 图读出 t1、t2 时刻电压的大小和极性，判断两时刻离子偏转方向和偏转量","why":"离子通过极板时间极短，可视为在该时刻的恒定电压下偏转，偏转方向由电压极性决定、偏转量由电压大小决定","do":"比较 t1 与 t2 时刻电压的极性和绝对值，确定偏转方向相反、偏转量大小关系","expr":"","cues":["看电压正负定方向","看电压大小定偏转多少","短时间视为恒定"],"concepts":["交变电场","电压极性"]}],"435":[{"title":"剪断瞬间弹力不变","type":"前提判断","judge":"剪断细线的瞬间，弹簧弹力是否发生突变","why":"弹簧形变不能瞬间改变，弹力由形变量决定，剪断细线只撤去绳的拉力，弹力仍等于剪断前托住 A、B 整体的 3mg；若误认为弹力瞬间变为 2mg，加速度就算错","do":"先对剪断前的 A、B 整体受力平衡求弹簧弹力，再把这个值直接用于剪断瞬间对 A 列牛顿第二定律","expr":"F_{\\text{弹}}=3mg,\\quad F_{\\text{弹}}-2mg=2ma","cues":["弹簧来不及变","弹力先不变","剪断前整体平衡"],"concepts":["弹簧弹力","牛顿第二定律","瞬时加速度"]},{"title":"A 做简谐运动","type":"模型选择","judge":"剪断后 A 的运动是单调上升还是围绕新平衡位置的简谐振动","why":"A 只受重力和弹簧弹力，合力与位移成正比，是简谐振动；只有认定这一点才能用平衡位置和对称性求最高点、最低点，否则只能靠能量硬算","do":"找出合力为零的新平衡位置，把初始位置到平衡位置的距离作为振幅","expr":"kx_2=2mg","cues":["围绕平衡位置振动","合力为零处是平衡位置","用对称性"],"concepts":["简谐运动","平衡位置","回复力"]},{"title":"速度最大在平衡位置","type":"临界条件","judge":"A 向上运动过程中速度最大出现在哪个位置","why":"加速度为零时速度才达到极值，此时弹力等于 A 的重力，弹簧仍处于拉伸状态；若误以为最高点速度最大或弹簧原长处速度最大，就会错判 A 项","do":"令合力为零求该位置的弹簧伸长量，与零比较判断弹簧是拉伸还是压缩","expr":"kx=2mg","cues":["加速度为零速度最大","弹力等于重力","还在拉伸"],"concepts":["速度极值","加速度与速度关系","弹簧伸长"]},{"title":"用振幅对称定最高最低","type":"关系建立","judge":"最高点和最低点的弹簧伸长量如何由振幅对称得到","why":"简谐振动关于平衡位置对称，最高点与最低点到平衡位置的距离都等于振幅，由初位置与平衡位置之差得振幅，才能同时判断最高点和最低点的形变","do":"用剪断前伸长量减平衡位置伸长量得振幅，再对平衡位置加减振幅求两端位置","expr":"A=\\frac{3mg}{k}-\\frac{2mg}{k}=\\frac{mg}{k}","cues":["振幅等于初末位置差","上下对称","平衡位置加减振幅"],"concepts":["振幅","简谐运动对称性","弹簧形变"]}],"436":[{"title":"判断两过程的体积与温度变化","type":"图像读取","judge":"从 p-V 图上读出 A→B 是等容、B→C 是等温，并判断各过程体积、温度如何变化","why":"过程性质决定 W 和 ΔU 是否为零，是使用热力学第一定律的前提","do":"在图上确认 A、B 在同一条竖直线上（体积相同），B、C 在同一条等温线上；比较 A、B、C 三点的温度高低","expr":"V_A=V_B,\\quad T_B=T_C,\\quad T_A<T_B","cues":["看横坐标","竖直线是等容","同一温度"],"concepts":["等容过程","等温过程","p-V 图"]},{"title":"用温度定内能变化","type":"前提判断","judge":"判断各过程内能变化 ΔU 的正负，依据是题给“内能只由温度决定”","why":"题设明确内能只与温度有关且随温度升高而增大，因此 ΔU 的符号完全由温度变化决定","do":"比较初末状态温度：A→B 温度升高取 ΔU>0，B→C 温度不变取 ΔU=0","expr":"\\Delta U_{AB}>0,\\quad \\Delta U_{BC}=0","cues":["温度升高内能增大","等温内能不变"],"concepts":["理想气体内能","温度"]},{"title":"由体积变化定做功正负","type":"关系建立","judge":"判断气体对外做功 W 的正负（或外界对气体做功），看体积是膨胀还是压缩","why":"体积不变不做功，体积减小则外界对气体做正功，这是热力学第一定律中 W 项的来源","do":"A→B 体积不变取 W=0；B→C 体积减小，外界对气体做正功","expr":"W_{AB}=0,\\quad W_{BC}>0","cues":["体积不变不做功","压缩外界做功"],"concepts":["气体做功","体积变化"]},{"title":"用第一定律定吸放热","type":"关系建立","judge":"由 ΔU 与 W 联立判断 Q 的正负，即过程吸热还是放热","why":"热力学第一定律 ΔU=W+Q 把内能变化、做功、热传递三者联系起来，Q 的符号即吸放热","do":"对 A→B：ΔU>0、W=0 得 Q>0 吸热；对 B→C：ΔU=0、W>0 得 Q<0 放热","expr":"\\Delta U=W+Q","cues":["代第一定律","吸热还是放热"],"concepts":["热力学第一定律","吸热与放热"]},{"title":"等容过程比压强","type":"关系建立","judge":"等容升温时压强如何变化，从而比较 A、B 两状态压强大小","why":"一定质量理想气体体积不变时压强与热力学温度成正比（查理定律）","do":"由 A→B 温度升高，按 p/T=常量 推出 p_B>p_A","expr":"\\frac{p_A}{T_A}=\\frac{p_B}{T_B}","cues":["等容升压","查理定律"],"concepts":["查理定律","等容变化"]},{"title":"跨过程比较温度与内能","type":"结论整理","judge":"比较 A 与 C 的温度高低，进而比较两状态内能大小","why":"内能只由温度决定，跨过程比较内能必须先借中间状态 B 把温度串起来","do":"由 T_A<T_B 且 T_B=T_C 得 T_A<T_C，故 A 的内能小于 C 的内能","expr":"T_A<T_B=T_C\\Rightarrow U_A<U_C","cues":["借中间状态比","温度串起来"],"concepts":["状态参量","内能比较"]}],"437":[{"title":"确定粒子圆周半径","type":"关系建立","judge":"由比荷和速度判断粒子在磁场中做圆周运动的半径与内圆半径的关系","why":"洛伦兹力提供向心力，半径由速度与比荷共同决定，是后续所有几何关系的基础","do":"写出半径公式，代入 a 粒子速度，得到半径与内圆半径的倍数关系","expr":"R=\\frac{mv}{qB},\\quad R_a=\\frac{m}{qB}\\cdot\\frac{qBR_0}{m}=R_0","cues":["先算半径","半径等于内圆半径","用比荷求半径"],"concepts":["洛伦兹力","圆周运动半径"]},{"title":"判断轨迹与外边界相切","type":"临界条件","judge":"判断“恰好到达外边界后返回”对应轨迹圆与外圆相切这一临界几何条件","why":"恰好到达意味着粒子速度方向在边界处与边界相切，轨迹圆与外圆相切，这是求外圆半径的唯一依据","do":"画出 a 粒子轨迹圆，令其与外圆相切，用内圆半径和轨迹半径表示外圆半径","expr":"R'=R_0+\\sqrt{2}R_0","cues":["恰好到达就是相切","轨迹圆和外圆相切","用几何找外圆半径"],"concepts":["临界条件","几何相切"]},{"title":"判断返回路径与时间","type":"模型选择","judge":"判断 a 粒子返回 A 点需经历“磁场中圆弧+无场区直线+磁场中圆弧”的分段过程，并取最短时间","why":"粒子只在环形磁场区内偏转，出磁场后做匀速直线运动，再次进入磁场继续偏转，必须分段累加时间","do":"分别算出磁场中两段圆弧的圆心角之和与无场区直线段长度，再除以速度求总时间","expr":"t_{\\min}=\\frac{540^\\circ}{360^\\circ}T+\\frac{2R_0}{v_a}=\\frac{(3\\pi+2)m}{qB}","cues":["出磁场走直线","分两段算时间"],"concepts":["分段运动","周期"]},{"title":"判断 b、c 方向与轨迹","type":"几何关系","judge":"由 b、c 速度方向与 a 垂直且彼此相反，判断两粒子轨迹圆的圆心位置及返回 A 点的路径","why":"速度方向决定圆心所在垂线，b、c 方向相反使两轨迹关于某轴对称，返回 A 点均对应一个完整圆周","do":"以 A 点为起点作垂直于速度方向的半径线定圆心，比较两轨迹圆半径与内圆半径的几何关系","expr":"2R_c=\\sqrt{2}R_0","cues":["速度垂直定圆心","两粒子轨迹对称","转一圈回到A"],"concepts":["圆心定位","对称性"]},{"title":"比较 b、c 最短时间","type":"结论整理","judge":"判断 b、c 返回 A 点的最短时间是否相同，取决于两者周期与转过角度是否一致","why":"周期只由比荷和磁感应强度决定，与速度无关；两粒子比荷相同则周期相同，转过的总角度相同则时间相同","do":"比较 b、c 的周期表达式和各自轨迹转过的总圆心角，得出时间比","expr":"T=\\frac{2\\pi m}{qB},\\quad t_b:t_c=1:1","cues":["周期只跟比荷有关","比荷相同周期相同","转的角度一样"],"concepts":["周期与速度无关","比荷"]},{"title":"由几何求 c 的速度","type":"数学处理","judge":"由 c 轨迹圆半径与内圆半径的几何关系求出 c 的轨道半径，再反推速度","why":"半径由几何确定后，速度由半径与比荷共同决定，需联立半径公式求解","do":"由几何关系得 c 的半径，代入半径公式并与 a 的速度比较","expr":"v_c=\\frac{qBR_c}{m}=\\frac{\\sqrt{2}}{2}v_a","cues":["先求c的半径","再用半径反推速度","和a的速度比大小"],"concepts":["半径公式","速度比较"]}],"438":[{"title":"挡光时间求速度","type":"模型选择","judge":"小球过光电门时，能否用直径除以挡光时间代表球心经过平衡位置的瞬时速度","why":"光电门测的是球体遮光过程的平均速度，只有小球直径足够小、挡光时间足够短，平均速度才近似等于球心经过光电门时的瞬时速度","do":"写出速度与挡光时间的关系式，明确用 d/Δt 代替瞬时速度","expr":"v=\\frac{d}{\\Delta t}","cues":["直径除以时间","挡光很短","近似瞬时速度"],"concepts":["瞬时速度","平均速度","光电门"]},{"title":"守恒式化到可测量","type":"关系建立","judge":"把机械能守恒写成只含 h、Δt、d、g 的关系式，判断哪个量作纵坐标才能得到过原点的直线","why":"题中直接测量的是 h 和 Δt，需由 mgh=½mv² 消去 v，看纵坐标与 h 是否成线性关系","do":"将 v=d/Δt 代入 mgh=½mv²，整理成纵坐标关于 h 的一次函数形式","expr":"\\frac{1}{(\\Delta t)^{2}}=\\frac{2g}{d^{2}}h","cues":["先消去速度","看谁和高度成正比","化曲为直"],"concepts":["机械能守恒","线性化","图像法"]},{"title":"斜率对应表达式","type":"数学处理","judge":"图像斜率与 d、g 的对应关系，判断斜率等于什么才能作为验证依据","why":"由线性关系式直接读出斜率，斜率只由 g 和 d 决定，与 h 无关，这是图像过原点且斜率为定值的物理含义","do":"把整理后的式子与 y=kx 对比，写出斜率表达式","expr":"k=\\frac{2g}{d^{2}}","cues":["对比直线方程","斜率是常数","和直径平方有关"],"concepts":["斜率","机械能守恒"]},{"title":"由读数判分度","type":"实验操作","judge":"由测得直径 20.48 mm 末位数字判断游标卡尺的分度值","why":"不同分度游标卡尺的精确度不同，读数末位只能出现在精确度的整数倍上，末位 0.08 mm 只能是 0.02 mm 的整数倍","do":"比较 0.1、0.05、0.02 mm 三种精确度，看哪个能整除 0.08 mm","expr":"0.48\\,\\mathrm{mm}=24\\times0.02\\,\\mathrm{mm}","cues":["看末位小数","精确度要对得上","零点零八"],"concepts":["游标卡尺","精确度","读数规则"]},{"title":"25分度对齐刻度","type":"数据处理","judge":"25 分度卡尺测同一小球时，游标尺上第几条刻度线与主尺对齐","why":"25 分度精确度为 0.04 mm，游标读数部分 0.48 mm 必须等于对齐格数乘以精确度","do":"用小数部分除以精确度，求出对齐的刻度线条数","expr":"n=\\frac{0.48}{0.04}=12","cues":["小数部分除以精确度","零点四八","算格数"],"concepts":["游标卡尺","精确度","对齐刻度线"]}],"439":[{"title":"双掷开关接法","type":"实验操作","judge":"S₂ 的 c、d 两端应分别接到待测电阻的哪一侧，才能实现内接与外接的切换","why":"S₂ 是单刀双掷开关，公共端接电流表，两个掷端分别接电压表节点和待测电阻外侧节点，才能通过切换改变电压表测量位置","do":"把 c 端接到待测电阻与电压表相连的节点，d 端接到待测电阻另一端（电流表侧），使 S₂ 在两个位置分别构成电流表内接与外接","expr":"","cues":["公共端接电流表","两个掷端跨接待测电阻","切换电压表接点"],"concepts":["单刀双掷开关","内接法","外接法"]},{"title":"限流接法滑片位置","type":"前提判断","judge":"滑动变阻器是限流式接法时，闭合开关前滑片应放在使接入阻值最大的一端","why":"限流接法中滑片置于阻值最大处可限制电流、保护电表和电源，这是闭合开关前的安全操作规范","do":"观察变阻器接入电路的是哪一段，找出使接入阻值最大的端点（b 端）","expr":"","cues":["保护电路","阻值最大","限流式"],"concepts":["限流接法","滑动变阻器"]},{"title":"内外接法选择依据","type":"关系建立","judge":"电压表示数变化明显而电流表示数基本不变，说明哪只电表的分压/分流影响更大，应选内接还是外接","why":"电压表读数变化大说明电流表分压显著，即电流表内阻与待测电阻相比不可忽略，若用内接法会带来大的串联分压误差；电流表读数几乎不变说明电压表分流可忽略，故应让电压表直接并联在待测电阻两端","do":"比较两种接法下电压表与电流表示数的变化幅度，判断电流表分压是主要误差来源，选择电流表外接（接 c 端）","expr":"","cues":["电压表变化大","电流表几乎不变","电流表分压明显","选外接"],"concepts":["电流表内接外接","分压分流","实验误差"]},{"title":"电压表接入位置","type":"模型选择","judge":"图(b)中电压表应并联在哪两点之间，才能配合双掷开关实现两次测量并消去电表内阻","why":"要消除电表内阻误差，需让电压表分别测量含电流表与不含电流表的两段电压，通过两次比值作差消去电流表内阻和变阻器电阻","do":"把电压表一端接 S₂ 的公共节点（电流表与待测电阻之间），另一端接待测电阻外侧节点，使 S₂ 切换时电压表分别测“R_x+R_A+R_滑”与“R_A+R_滑”上的电压","expr":"","cues":["电压表跨接待测电阻","两次测量作差","消去电流表内阻"],"concepts":["电压表并联","双掷开关","消除系统误差"]},{"title":"两次读数作差求阻值","type":"数学处理","judge":"两次测量的电压与电流之比分别对应哪段电阻，如何作差得到 R_x","why":"S₂ 接 c 时电压表测的是待测电阻、电流表与变阻器串联的总电压，接 d 时测的是电流表与变阻器串联的总电压，两式相减即消去 R_A 与 R_滑","do":"写出 U_c/I_c = R_x+R_A+R_滑 与 U_d/I_d = R_A+R_滑，两式相减得 R_x","expr":"R_x=\\frac{U_c}{I_c}-\\frac{U_d}{I_d}","cues":["两次比值相减","消去电流表内阻","消去变阻器电阻"],"concepts":["欧姆定律","等效替代","系统误差消除"]}],"440":[{"title":"确定恰好看到的光路","type":"临界条件","judge":"要判断“恰好可以看到”对应哪一条特殊光线，即从底部质点发出、经液面折射后恰好擦过容器上边缘射入人眼的那条光线","why":"未装液体时边缘挡住视线，装液后恰好可见，说明折射光线刚好经过容器口边缘，这是几何光学的临界光线，只有取这条光线才能把容器尺寸与折射角联系起来","do":"画出光路图，标出底部质点、液面折射点、容器上边缘点，令折射光线过容器口边缘","expr":"","cues":["恰好看到","擦边缘","临界光线"],"concepts":["光路图","临界光线","折射定律"]},{"title":"由观测角定入射角","type":"几何关系","judge":"要判断人眼观测角 α 是入射光线与法线的夹角（入射角），还是与界面的夹角","why":"折射定律中的角是光线与法线的夹角，题给的 sinα=3/5 若直接当入射角正弦会与几何图形矛盾，需由光路图确认 α 与入射角互余","do":"在入射点作法线，比较 α 与法线的位置关系，得入射角 i 满足 sin i = cos α","expr":"\\sin i=\\cos\\alpha=\\frac{4}{5}","cues":["与法线夹角","互余","先定入射角"],"concepts":["入射角","法线","折射定律"]},{"title":"用几何求折射角正弦","type":"几何关系","judge":"要判断折射角 r 的正弦应由液面下三角形（深度 h 与水平偏移）算出，而不是由空气侧三角形算出","why":"折射角是液体中光线与法线的夹角，其正弦等于水平偏移与斜边之比，必须用液体内的几何尺寸 h 和 R−O'A 来算","do":"先由 H−h 与观测角关系求出 O'A，再在液面下直角三角形中求水平偏移 R−O'A 与斜边 OB，取比值","expr":"\\sin r=\\frac{R-O'A}{\\sqrt{h^{2}+(R-O'A)^{2}}}","cues":["用液体里的三角形","水平偏移比斜边","先求O'A"],"concepts":["折射角","几何关系","直角三角形"]},{"title":"分清两段传播路程","type":"模型选择","judge":"要判断全过程分为空气中一段和液体中一段，两段速度不同，不能把总路程除以同一速度","why":"光在液体中速度 v=c/n 小于真空光速，两段介质不同必须分段计时再相加","do":"空气中路程取入射点到人眼的距离，液体中路程取质点经液面到入射点的斜距 OB，分别求时间后相加","expr":"t=\\frac{s_1}{c}+\\frac{s_2}{v},\\quad v=\\frac{c}{n}","cues":["分两段算","液体里变慢","先求速度"],"concepts":["光速与介质","折射率","分段计时"]},{"title":"统一单位再代入","type":"数学处理","judge":"要判断所有长度须统一换算成米后再与光速运算，避免厘米与米混用","why":"光速单位为 m/s，题给尺寸为 cm，单位不统一会使结果差两个数量级","do":"把 H、h、R、人眼距离等全部化为米，再代入时间公式","expr":"1\\,\\mathrm{cm}=10^{-2}\\,\\mathrm{m}","cues":["化成米","单位统一","别混厘米"],"concepts":["单位换算","国际单位制"]}],"441":[{"title":"由静止条件定动摩擦因数","type":"前提判断","judge":"能否由“初始刚好静止”判断出最大静摩擦力与重力沿杆分量恰好平衡，从而求出 μ","why":"题设“刚好能静止”意味着静摩擦力达到最大值，且此时 F=0，法向压力只由重力垂直杆分量提供","do":"沿杆方向列平衡式，垂直杆方向写正压力，联立求 μ","expr":"mg\\sin\\theta=\\mu mg\\cos\\theta,\\ \\mu=\\tan\\theta","cues":["刚好静止就是临界","F还没开始作用","沿杆方向平衡"],"concepts":["最大静摩擦力","平衡条件","动摩擦因数"]},{"title":"判断正压力方向反转时刻","type":"临界条件","judge":"要判断 F 的垂直杆分量何时等于重力垂直杆分量，即杆对物块的支持力何时反向","why":"正压力 N 的表达式在 F sinθ 与 mg cosθ 大小关系改变时换号，摩擦力大小随之改变，不找这个临界点就写不对 f(t)","do":"令垂直杆方向合力为零，解出 F sinθ=mg cosθ 对应的时刻","expr":"F\\sin\\theta=mg\\cos\\theta\\Rightarrow t=4\\,\\mathrm{s}","cues":["支持力会反向","垂直杆方向先平衡","四秒是分界"],"concepts":["正压力","临界状态","力的分解"]},{"title":"分段写摩擦力关系式","type":"关系建立","judge":"要判断 0~4 s 与 4~6 s 两段中 N 分别等于重力分量减、加 F 分量，从而分段写出 f=μN","why":"摩擦力由正压力决定，而正压力在两段中表达式不同，必须分段才能得到正确的 f-t 关系","do":"分别对两段写垂直杆方向方程，代入 μ 得 f(t)，并画出折线图","expr":"0\\le t\\le4:f=(\\tfrac12-\\tfrac18 t)mg;\\ 4\\le t\\le6:f=(\\tfrac18 t-\\tfrac12)mg","cues":["分两段写","先算支持力","摩擦力跟着压力变"],"concepts":["滑动摩擦力","正压力","分段函数"]},{"title":"冲量用面积而非平均值","type":"图像读取","judge":"要判断 F 的冲量与摩擦力冲量都等于各自图线与时间轴围成的面积，而不是简单用末值乘时间","why":"F 与 f 都随时间线性变化，冲量定义 I=∫Fdt 在图上就是面积，用平均值只对匀变速线性情形成立但必须按面积算","do":"对 F-t 图取三角形面积；对 f-t 图取两段三角形面积相加","expr":"I_F=\\tfrac12 F(6)\\cdot6,\\ I_f=\\tfrac12\\cdot\\tfrac12 mg\\cdot4+\\tfrac12\\cdot\\tfrac14 mg\\cdot2","cues":["冲量看面积","线性变化取平均","两段面积相加"],"concepts":["冲量","F-t 图像面积","变力冲量"]},{"title":"沿杆方向用动量定理","type":"模型选择","judge":"要判断求速度应沿杆方向对整个过程用动量定理，把 F 冲量的沿杆分量、重力冲量、摩擦力冲量一起计入","why":"力随时间变化且方向固定，动量定理对全过程成立，可避开求加速度和运动细节","do":"把各冲量投影到沿杆方向，注意摩擦力方向与运动方向相反取负号，列动量定理方程求 v","expr":"I_F\\cos\\theta-mg\\sin\\theta\\cdot t-I_f=mv","cues":["全过程动量定理","冲量要投影","摩擦力冲量取负"],"concepts":["动量定理","冲量的分量","方向正负"]}],"442":[{"title":"双棒回路电动势叠加","type":"模型选择","judge":"两棒都在磁场中运动时，回路总电动势该由哪几个电动势合成、按什么方向相加","why":"两棒切割磁感线各自产生电动势，回路电流由两棒电动势之差（或和）决定，不能只看棒1","do":"画出回路，标出棒1、棒2各自电动势方向，判断二者在回路中相互抵消还是叠加","expr":"\\varepsilon_1=BLv_1,\\ \\varepsilon_2=BLv_2","cues":["两棒都有电动势","方向相反要相减","先定回路绕向"],"concepts":["动生电动势","右手定则","闭合回路"]},{"title":"电容电压与电流关系","type":"关系建立","judge":"电容器电压与两棒电动势、电阻压降之间满足什么回路方程","why":"电容器并联在导轨左端，其电压等于回路中沿路径的电动势与电阻压降的代数和，这是把U与I1、I2联系起来的唯一桥梁","do":"沿回路写基尔霍夫电压方程，把U用棒1、棒2的电动势和两段电阻压降表示","expr":"U=BLv_1-I_1R=BLv_2+I_2R","cues":["电容电压等于路端电压","沿回路走一圈","电阻上有压降"],"concepts":["基尔霍夫电压定律","电容电压","电阻压降"]},{"title":"稳定态电流为零","type":"临界条件","judge":"系统达到稳定时回路电流是否为零、两棒速度是否相等","why":"题设明确稳定后电流为零、速度相同；电流为零意味着两棒电动势相等且等于电容电压，这是求末速度的临界条件","do":"令I1=I2=0，得BLv1=BLv2=U，结合动量与电荷守恒求v","expr":"I=0,\\ BLv=U","cues":["稳定时没电流","两棒速度一样","电动势等于电容电压"],"concepts":["稳定状态","临界条件","电磁感应"]},{"title":"动量定理求电荷量","type":"关系建立","judge":"安培力冲量如何转化为通过回路的电荷量，从而联系速度变化","why":"安培力F=BIL，冲量∫BILdt=BLq，把难以直接求的速度变化与可求的电荷量挂钩","do":"对棒1、棒2分别写动量定理，把∫I dt记为通过棒的电荷量","expr":"-BLq_1=mv-mv_0,\\ BLq_2=mv","cues":["安培力冲量","冲量等于电荷量乘BL","分别对两棒用动量定理"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"相对位移与电荷量关联","type":"几何关系","judge":"两棒间距的最小值由什么决定，如何用相对位移把间距与电荷量联系起来","why":"不相撞的临界是间距恰好减为零，间距变化等于两棒位移之差，而位移差可通过回路方程对时间累积与电荷量挂钩","do":"对回路电压方程两边乘Δt求和，把(v1-v2)Δt识别为间距变化，把IΔt识别为电荷量","expr":"BLd_{\\min}=(q_1+q_2)R","cues":["间距变化是位移差","对时间累积","电流累积就是电荷量"],"concepts":["相对位移","电荷量累积","临界间距"]},{"title":"全过程电荷守恒联立","type":"数学处理","judge":"如何把动量定理得到的两个电荷量与回路累积方程联立消去电荷量","why":"动量定理给出q1、q2与v的关系，回路累积给出q1+q2与d的关系，只有联立才能解出d_min","do":"由动量定理得BL(q1+q2)=mv0，代入累积式解d_min","expr":"BL(q_1+q_2)=mv_0\\Rightarrow d_{\\min}=\\frac{mv_0R}{B^2L^2}","cues":["两式联立消电荷量","先求电荷量之和","再代回间距式"],"concepts":["联立方程","动量定理","电磁感应综合"]}],"443":[{"title":"底部作用力方向","type":"前提判断","judge":"无风静止时，底部巨石对风动石的作用力方向是否沿接触面法线（竖直）","why":"风动石只受重力和底部作用力两个力而静止，二力平衡要求两力等大反向，故底部作用力必竖直向上、大小等于重力","do":"对无风状态取风动石为对象，由二力平衡确定 F1 的方向与大小","expr":"F_1=mg,\\ \\text{方向竖直向上}","cues":["二力平衡","方向竖直向上","等于重力"],"concepts":["二力平衡","重力"]},{"title":"三力平衡求合力","type":"关系建立","judge":"有水平风力时，底部作用力是否等于重力与风力的合力","why":"风动石仍静止，三力（重力、风力、底部作用力）平衡，底部作用力必须与重力、风力的合力等大反向，而不是单独与重力平衡","do":"把重力和风力先合成，再由平衡条件令 F2 与该合力等大反向","expr":"\\vec F_2=-(m\\vec g+\\vec F)","cues":["三力平衡","先合成两个力","与合力反向"],"concepts":["三力平衡","力的合成"]},{"title":"比较大小关系","type":"数学处理","judge":"重力与水平风力互相垂直时，合力大小与重力大小谁大","why":"重力竖直、风力水平，两分力垂直，合力为斜边，斜边必大于任一直角边，故 F2 大于 F1","do":"用勾股定理写出 F2 并和 mg 比较","expr":"F_2=\\sqrt{(mg)^2+F^2}>mg=F_1","cues":["勾股定理","斜边大于直角边","风力越大越大"],"concepts":["勾股定理","合力与分力"]}],"444":[{"title":"读图取峰值与周期","type":"图像读取","judge":"从图(b)的横纵坐标读出输入电压的最大值和交流电周期","why":"有效值由峰值除以根号二得到，周期决定频率，二者都只能从图像坐标轴上读取，读错则后续全错","do":"看图像峰值对应的纵坐标和相邻两个零点（或峰峰）之间的横坐标差","expr":"U_m=48\\sqrt{2}\\ \\mathrm{V},\\quad T=0.02\\ \\mathrm{s}","cues":["看峰值","数格子","横轴是秒"],"concepts":["交流电最大值","周期","有效值"]},{"title":"峰值转有效值","type":"前提判断","judge":"判断电压表读数、功率计算该用有效值还是最大值","why":"变压器变压比和欧姆定律适用于有效值，电压表显示的是有效值，直接用峰值代入会偏大根号二倍","do":"把峰值除以根号二得到原线圈电压有效值","expr":"U_1=\\frac{U_m}{\\sqrt{2}}=48\\ \\mathrm{V}","cues":["先转有效值","电压表读有效值"],"concepts":["有效值","正弦交流电"]},{"title":"理想变压器变压比","type":"关系建立","judge":"判断副线圈电压应由匝数比与原线圈电压共同决定，与负载电阻无关","why":"理想变压器铁芯无漏磁，每匝电压相同，故电压比等于匝数比，副线圈电压只由原线圈电压和匝数比决定","do":"用匝数比把原线圈有效值折算到副线圈，得到电压表读数","expr":"U_2=\\frac{n_2}{n_1}U_1=12\\ \\mathrm{V}","cues":["电压比等于匝数比","副线圈电压先定"],"concepts":["理想变压器","变压比"]},{"title":"副线圈两电阻并联","type":"模型选择","judge":"判断副线圈两端两个电阻是并联（电压相同）还是串联","why":"两电阻接在副线圈同一对端点之间，电压相同，电流按电阻反比分配；若误当串联则电流关系全错","do":"确认并联后，用电压相同、电阻成二倍关系推出两支路电流比","expr":"I_1:I_2=R_2:R_1=1:2","cues":["两端接同一线圈","电压一样","电流反比"],"concepts":["并联电路","欧姆定律"]},{"title":"原副线圈功率相等","type":"结论整理","judge":"判断理想变压器原副线圈的功率关系及电流比该由功率还是匝数比决定","why":"理想变压器无能量损耗，输入功率等于输出功率，原副线圈电流比等于匝数反比而非匝数比","do":"用P入=P出核对功率选项，用电流比等于匝数反比核对电流选项","expr":"P_1=P_2,\\quad I_1:I_2=n_2:n_1","cues":["理想无损耗","功率相等","电流反比"],"concepts":["理想变压器功率","电流比"]}],"445":[{"title":"两导线在O点叠加","type":"关系建立","judge":"两导线在O点产生的磁感应强度方向是相同还是相反","why":"O位于两导线中垂线上，由安培定则判断两电流在O点的磁场方向，方向相同才能直接相加得 B2","do":"用安培定则分别画出 L1、L2 在 O 点的磁场方向，比较是否同向","expr":"B_2=2B_0","cues":["方向相同","叠加相加","先定方向"],"concepts":["安培定则","磁感应强度叠加"]},{"title":"单根导线在O点的贡献","type":"数学处理","judge":"能否由合磁场 B2 反推出单根导线在 O 点的磁感应强度","why":"两导线电流大小相等、到 O 点距离相等，各自在 O 点产生的磁感应强度大小相等，合成为 B2","do":"把 B2 对半分，得到单根导线在 O 点的磁感应强度","expr":"B_0=\\frac{B_2}{2}","cues":["对半分","大小相等","一半"],"concepts":["对称性","磁场叠加"]},{"title":"M、N两点磁场对称","type":"前提判断","judge":"两导线同时存在时，N 点合磁场大小是否等于 M 点的 B1","why":"M、N 关于 O 对称，两导线位置也关于 O 对称，整体图形具有中心对称性，故两点合磁场大小相等","do":"由对称性把 M 点的已知量 B1 搬到 N 点","expr":"B_N=B_1","cues":["对称","跟M一样","搬过去"],"concepts":["对称性"]},{"title":"N点两导线磁场反向","type":"关系建立","judge":"L1、L2 在 N 点产生的磁场方向是相同还是相反，谁大","why":"N 点位于 L2 附近、远离 L1，L2 在 N 点的磁感应强度大于 L1 的，且由安培定则知两者方向相反，故合磁场是两者之差","do":"分别判断两导线在 N 点的磁场方向与大小，写出合磁场为两者之差","expr":"B_1=B_{2N}-B_{1N}","cues":["方向相反","离得近的强","相减"],"concepts":["安培定则","磁场叠加"]},{"title":"撤去L2后取L1的贡献","type":"结论整理","judge":"撤去 L2 后 N 点只剩 L1 的磁场，应如何由已知量表示","why":"撤去一根导线即从合磁场中扣除它的贡献，剩下的就是另一根导线单独产生的磁场","do":"用 L2 在 N 点的贡献减去合磁场 B1，得到 L1 单独在 N 点的磁感应强度","expr":"B=\\frac{B_2}{2}-B_1","cues":["扣掉一根","只剩L1","相减得结果"],"concepts":["磁场叠加","等效替代"]}],"446":[{"title":"a 做圆周运动的向心力来源","type":"模型选择","judge":"电子 a 沿半圆轨迹运动时，向心力是否完全由径向电场力提供","why":"轨迹是以 O 为圆心的半圆，速度始终垂直于半径，电场力沿半径指向 O，恰好充当向心力，不需要分解或引入其他力","do":"对电子 a 写牛顿第二定律的向心力形式，与初动能表达式联立","expr":"eE=\\frac{mv_a^2}{r},\\quad E_k=\\frac12 mv_a^2","cues":["电场力当向心力","沿半径指向圆心","匀速圆周"],"concepts":["向心力","电场力","动能"]},{"title":"等势线与电势高低的判定","type":"前提判断","judge":"H、N 是否在同一等势线上，P、Q 两点电势谁高谁低","why":"等势线是以 O 为圆心的半圆，H 与 N 半径相同故等势；电场沿径向向外、沿电场方向电势降低，半径越大电势越低","do":"比较 H 与 N 的半径、P 与 Q 的半径，确定各点电势高低及电子电势能大小","expr":"\\varphi_H=\\varphi_N,\\quad \\varphi_P>\\varphi_Q","cues":["同一条等势线","半径大电势低","电子在低电势处势能大"],"concepts":["等势线","电势","电势能"]},{"title":"由轨迹弯曲判断电场力方向","type":"关系建立","judge":"电子 b 从 M 到 Q 的过程中电场力做正功还是负功，动能如何变化","why":"电子带负电，受力方向与电场方向相反；轨迹向 O 侧弯曲说明电场力大致指向 O，即与位移方向夹角为钝角，电场力做负功","do":"由轨迹凹向判断 b 所受合力指向，结合电子负电性确定电场力做功的正负","expr":"W_b=eU_{MQ}<0","cues":["轨迹向里弯","电场力指向圆心","电场力做负功"],"concepts":["曲线运动条件","电场力做功","动能定理"]},{"title":"径向电场强度随半径减小","type":"前提判断","judge":"HP 段与 NQ 段的平均电场强度哪个大","why":"等势线为同心半圆，越靠近 O 等势线越密，电场线也越密，故半径越小处场强越大","do":"比较 HP 与 NQ 所在区域的等势线疏密，得出平均场强的大小关系","expr":"\\bar E_{HP}>\\bar E_{NQ}","cues":["等势线越密场强越大","靠近球心场强大","半径小的地方电场强"],"concepts":["电场强度","等势面疏密"]},{"title":"用电势差比较做功大小","type":"关系建立","judge":"已知 NQ=2HP，能否直接得出 U_NQ=2U_HP","why":"U=Ēd 只在匀强电场中严格成立；此处场强沿径向变化，两段平均场强不同，不能按长度正比推电势差","do":"用 U=Ēd 分别写出两段电势差，代入平均场强的大小关系比较","expr":"U_{NQ}=\\bar E_{NQ}\\cdot NQ<\\bar E_{HP}\\cdot 2HP=2U","cues":["不能按长度正比","平均场强不一样","分段算电势差"],"concepts":["电势差","平均电场强度","非匀强电场"]}],"447":[{"title":"识别同轴转动模型","type":"模型选择","judge":"P、Q 两点是否绕同一根固定轴、以相同角速度转动","why":"两点固定在同一块绕 O 点转动的手绢上，属于同轴传动，角速度必须相等；若误判为皮带或齿轮传动，就会得出角速度与半径成反比的错误结论","do":"确认 P、Q 与 O 的相对位置固定、手绢整体绕 O 匀速转动，从而判定两点角速度相同","expr":"\\omega_P=\\omega_Q","cues":["同轴转动","角速度一样","绕同一点转"],"concepts":["同轴转动","角速度"]},{"title":"线速度与半径成正比","type":"关系建立","judge":"在角速度相同的条件下，线速度大小由哪个量决定","why":"由 v=ωr，ω 相同时 v 与轨道半径成正比，半径之比为 d:√3d","do":"写出 v=ωr，用 r_OP:r_OQ=1:√3 比较两点线速度","expr":"v=\\omega r,\\quad v_P:v_Q=1:\\sqrt{3}","cues":["半径大的线速度大","用v等于欧米伽乘r"],"concepts":["线速度","圆周运动"]},{"title":"向心加速度与半径成正比","type":"关系建立","judge":"角速度相同时向心加速度随半径如何变化","why":"由 a=ω²r，ω 相同则 a 与 r 成正比，不能误用 a=v²/r 而得出与半径成反比的结论","do":"写出 a=ω²r，代入半径比得到加速度比","expr":"a=\\omega^{2}r,\\quad a_P:a_Q=1:\\sqrt{3}","cues":["用欧米伽平方乘半径","别用v平方除以r"],"concepts":["向心加速度"]},{"title":"合力指向圆心","type":"结论整理","judge":"匀速圆周运动中合外力是否沿半径指向圆心、大小是否恒定","why":"匀速圆周运动速度大小不变，切向合力为零，合外力全部充当向心力，方向始终指向圆心，只有方向变而大小不变","do":"由合力等于向心力判断合力方向指向 O，并说明其大小不随时间改变","expr":"F_{\\text{合}}=F_n=m\\omega^{2}r","cues":["合力就是向心力","指向圆心","大小不变方向变"],"concepts":["向心力","合外力"]}],"448":[{"title":"反应类型与守恒量","type":"前提判断","judge":"该反应属于裂变还是轻核聚变，反应前后质量数与电荷数是否守恒","why":"氘核与氚核结合成氦核并放出中子，是轻核聚变；核反应方程中质量数、电荷数守恒，但反应前后总质量不守恒（存在质量亏损），亏损质量对应释放的能量","do":"核对反应式两边质量数（2+3=4+1）与电荷数（1+1=2+0），并区分“质量数守恒”与“质量守恒”","expr":"\\Delta E=\\Delta m c^{2}","cues":["轻核聚变","质量数守恒","有质量亏损"],"concepts":["核聚变","质量数守恒","质量亏损"]},{"title":"碰撞前后动量守恒","type":"模型选择","judge":"能否把氘核与氚核的正碰及后续反应当作一个动量守恒过程处理","why":"核反应时间极短，内力远大于外力，系统动量守恒；题设两核动量等大反向，系统总动量为零","do":"写出反应前后总动量式，由初态总动量为零推出末态氦核与中子动量等大反向","expr":"\\vec p_{\\mathrm{D}}+\\vec p_{\\mathrm{T}}=0\\Rightarrow \\vec p_{\\mathrm{He}}+\\vec p_{\\mathrm{n}}=0","cues":["取系统","动量守恒","总动量为零"],"concepts":["动量守恒定律","正碰"]},{"title":"动能按质量反比分配","type":"关系建立","judge":"动量大小相等时，动能与质量成什么比例","why":"由 E_k=p²/(2m)，p 大小相同则动能与质量成反比，质量大的氦核分得动能少","do":"用同一 p 分别写出氦核与中子的动能，作比得 E_kHe:E_kn=m_n:m_He","expr":"E_{\\mathrm{k}}=\\frac{p^{2}}{2m},\\quad E_{\\mathrm{k,He}}:E_{\\mathrm{k,n}}=m_{\\mathrm{n}}:m_{\\mathrm{He}}=1:4","cues":["动能看质量","反比关系","动量一样大"],"concepts":["动能与动量的关系","反比分配"]},{"title":"总动能按比例拆分","type":"数学处理","judge":"把 17.5 MeV 的总动能按 1:4 分给氦核和中子时，谁取大份","why":"题设反应后两粒子总动能近似等于释放的全部能量，且中子质量约为氦核的 1/4，故中子分得 4/5","do":"用总动能乘以 4/5 与 1/5，分别得到中子与氦核的动能","expr":"E_{\\mathrm{k,n}}=\\frac{4}{5}\\times17.5\\ \\mathrm{MeV}=14\\ \\mathrm{MeV},\\quad E_{\\mathrm{k,He}}=3.5\\ \\mathrm{MeV}","cues":["中子拿大头","按四比一","总能量分完"],"concepts":["能量分配","核能释放"]}],"449":[{"title":"匀速直线判受力平衡","type":"前提判断","judge":"MN 段做匀速直线运动说明合力为零，需判断电场力、洛伦兹力、重力三力如何平衡","why":"匀速直线运动是平衡态，合力必为零；这是求 E、B 的唯一依据","do":"对微粒在 MN 段受力分析，画三力矢量三角形，列水平与竖直两个平衡方程","expr":"qE=mg,\\quad qvB=\\sqrt{2}mg","cues":["三力平衡","合力为零","画受力图"],"concepts":["受力平衡","洛伦兹力","电场力"]},{"title":"洛伦兹力方向定偏转","type":"模型选择","judge":"由速度沿 MN 斜向、B 垂直纸面向里，判断洛伦兹力垂直于 MN 指向哪一侧，从而确定三力闭合方式","why":"洛伦兹力方向由左手定则决定且垂直于速度，方向判错则平衡方程符号全错","do":"用左手定则定 f 方向，与重力、电场力构成闭合三角形，读出 f 与 mg 的夹角关系","expr":"qvB=\\sqrt{2}mg","cues":["左手定则","垂直速度","斜向右上"],"concepts":["左手定则","洛伦兹力方向"]},{"title":"撤磁场后判类平抛","type":"模型选择","judge":"撤去磁场后只剩重力和电场力，判断其合力方向与 N 点速度方向是否垂直，从而确定是类平抛还是别的运动","why":"合力恒定时，只有合力与初速度垂直才是类平抛，才能用平抛规律处理","do":"求重力与电场力的合力大小和方向，与 MN 方向比较夹角","expr":"F_{\\text{合}}=\\sqrt{2}mg,\\quad a=\\sqrt{2}g","cues":["合力恒定","与速度垂直","类平抛"],"concepts":["类平抛运动","合力与初速度"]},{"title":"位移偏转角定速度角","type":"几何关系","judge":"N、P 等高且 MN 与水平成 45°，判断 NP 位移方向与水平方向的夹角，再用偏转角关系求 P 点速度方向","why":"类平抛中速度偏转角与位移偏转角满足 tanθ=2tanα，α 取错则速度算错","do":"由 N、P 等高及 45° 几何关系定出位移偏转角 α，代入 tanθ=2tanα 求 P 点速度","expr":"\\tan\\theta=2\\tan45^\\circ=2,\\quad v_P=\\sqrt{5}v","cues":["等高","位移偏角","速度偏角"],"concepts":["类平抛偏转角关系","速度分解"]},{"title":"竖直分运动求最大高度","type":"关系建立","judge":"判断竖直方向分运动是竖直上抛，用竖直分速度独立求上升最大高度，而非用合运动求","why":"竖直方向只受重力分量的效果，竖直分速度决定上升高度，与水平分运动无关","do":"把 N 点速度分解，取竖直分量，用竖直上抛公式求最大上升高度","expr":"h=\\frac{(v\\cos45^\\circ)^2}{2g}=\\frac{v^2}{4g}","cues":["分解速度","竖直上抛","竖直分量"],"concepts":["运动的分解","竖直上抛"]},{"title":"动能定理求电势差","type":"关系建立","judge":"判断 N 到 P 电场力做功对应哪段电势差，用动能定理把速度变化与 U 联系起来","why":"电场力做功 qU 等于动能增量（重力做功为零，因等高），这是求电势差的直接途径","do":"对 N→P 列动能定理，代入 v_P 与 v 求 U","expr":"qU=\\frac12mv_P^2-\\frac12mv^2","cues":["等高重力不做功","动能定理","电场力做功"],"concepts":["动能定理","电势差"]}],"450":[{"title":"判断两摩擦力等大反向","type":"前提判断","judge":"A、B 各自受到的滑动摩擦力大小是否相等、方向是否相反","why":"A 相对带向右滑、B 相对带向左滑，两摩擦力方向相反；只有大小相等（μ_A m_A g = μ_B m_B g）时整体合外力才为零，才能用动量守恒","do":"分别算 f_A = μ_A m_A g 与 f_B = μ_B m_B g 并比较","expr":"f=\\mu_A m_A g=\\mu_B m_B g=5\\,\\mathrm{N}","cues":["两摩擦力一样大","方向相反","先算摩擦力"],"concepts":["滑动摩擦力","整体法"]},{"title":"共速前用动量守恒","type":"模型选择","judge":"t₁ 之前能否把 A、B 当整体、用动量守恒求 B 的速度","why":"两摩擦力等大反向抵消，弹簧力是内力，整体合外力为零，故系统动量守恒；不取整体就要多解弹簧力","do":"对 A、B 系统列初末动量相等的方程，代入 v_A=1 m/s 求 v_B","expr":"m_A v_0 = m_A v + m_B v_B","cues":["取整体","合外力为零","动量守恒"],"concepts":["动量守恒定律","内力与外力"]},{"title":"比较加速度判断速度大小","type":"关系建立","judge":"共速前 A、B 加速度谁大，从而判断 t₁ 时两者速度的大小关系","why":"同一弹簧力下 a=f/m，质量小的 A 加速度大，故 A 减速更快、末速度小于 B","do":"由 f+F弹=ma 写出 a_A、a_B 并比较","expr":"a_A=\\frac{f+F_{\\text{弹}}}{m_A},\\quad a_B=\\frac{f+F_{\\text{弹}}}{m_B}","cues":["质量小的加速度大","A减得快","比加速度"],"concepts":["牛顿第二定律","弹簧弹力"]},{"title":"用功能关系求形变量","type":"关系建立","judge":"如何由能量关系求弹簧压缩量（即 A、B 位移差）","why":"摩擦力对 A 做负功、对 B 做正功，初动能转化为末动能、弹性势能与摩擦功，只有把位移差与弹性势能挂钩才能解出形变量","do":"对 0~t₁ 列动能定理，代入 E_p=0.75 J 解出 x_A−x_B","expr":"-fx_A+fx_B+\\tfrac12 m_A v_0^2=\\tfrac12 m_A v^2+\\tfrac12 m_B v_B^2+E_p","cues":["列动能定理","摩擦一正一负","位移差就是形变量"],"concepts":["动能定理","弹性势能"]},{"title":"相对位移与划痕长度","type":"临界条件","judge":"A 相对传送带的划痕长度对应哪段相对位移，与 B 的相对位移如何比较","why":"划痕只由 A 相对带的位移决定，而 A、B 相对带位移之和等于两者位移差；需借 v-t 图面积比较两者大小才能定出划痕范围","do":"画 0~t₁ 的 v-t 图，比较 A 与带、B 与带所夹面积，结合两者之和为 0.1 m 判断","expr":"x_{\\text{相}A}+x_{\\text{相}B}=x_A-x_B=0.1\\,\\mathrm{m}","cues":["看v-t图面积","划痕只看A","面积谁大谁小"],"concepts":["相对位移","v-t 图像面积","划痕"]}],"451":[{"title":"识别等温过程","type":"前提判断","judge":"管中封闭空气在排水过程中温度是否可视为不变，从而能否用玻意耳定律","why":"题干明确说明进排水过程管中空气为理想气体且温度不变，只有等温才能把 p 与 V 的乘积视为定值","do":"从题干中提取“温度不变”这一条件，确认 pV=常量适用","expr":"p_1V_1=p_2V_2","cues":["温度不变","等温变化","用玻意耳定律"],"concepts":["理想气体","等温变化","玻意耳定律"]},{"title":"体积与气柱长度挂钩","type":"关系建立","judge":"细管中空气体积能否用气柱长度与截面积的乘积表示，截面积在前后两状态是否相同","why":"细管粗细均匀，截面积 S 不变，体积之比才等于长度之比，否则无法由压强比直接求长度","do":"写出 V_1=L_1S、V_2=L_2S 并代入等温方程消去 S","expr":"p_1L_1S=p_2L_2S","cues":["粗细均匀","截面积相同","体积正比于长度"],"concepts":["体积","截面积","正比关系"]},{"title":"判断排水时气柱变长","type":"关系建立","judge":"排水使水位下降时，封闭空气柱长度是变长还是变短","why":"水位下降使管内被水封住的空气空间扩大，气体体积增大，这是判断做功正负的前提","do":"比较排水前后气柱所占空间，确定体积增大","expr":"","cues":["水位下降","气柱变长","体积变大"],"concepts":["体积变化","水位"]},{"title":"判断气体做功正负","type":"结论整理","judge":"气体体积增大时，气体对外界做正功还是负功","why":"气体对外做功的符号由体积变化方向决定，膨胀时对外做正功","do":"由体积增大得出气体对外做正功","expr":"W>0","cues":["膨胀对外做功","体积变大做正功","排水气体做功"],"concepts":["气体做功","体积膨胀"]}],"452":[{"title":"同频率下波速与波长关系","type":"关系建立","judge":"频率相同时，波速大小与波长大小是否同向变化","why":"由 v=λf，同一振动源产生的纵波与横波频率相同，波长与波速成正比，故速度大的波长也大","do":"写出 v=λf，比较 v1 与 v2 的大小，直接得出两波长的大小关系","expr":"v=\\lambda f","cues":["频率相同","速度大的波长长","用波速公式"],"concepts":["波速","波长","频率"]},{"title":"两波到达时间差的来源","type":"前提判断","judge":"时间差 Δt 是两列波传播同一段距离所用时间之差，还是别的什么","why":"纵波和横波由同一次振动同时产生、沿同一直线传向沙蝎，起点相同、终点相同，只是速度不同导致到达时刻不同","do":"确认两波传播的路程相同（都等于波源到沙蝎的距离 s），把 Δt 写成两段传播时间之差","expr":"\\Delta t = t_2 - t_1","cues":["同时产生","路程一样","速度不同才有时差"],"concepts":["波的传播","时间差"]},{"title":"快波先到定时间差符号","type":"临界条件","judge":"Δt 应写成慢波时间减快波时间，还是反过来","why":"v1>v2，纵波先到达，横波后到达，时间差为正量必须是后到时间减先到时间","do":"用 s/v2 减 s/v1 表示 Δt，保证 Δt>0","expr":"\\frac{s}{v_2}-\\frac{s}{v_1}=\\Delta t","cues":["纵波先到","慢的用时长","大减小"],"concepts":["传播时间","先后到达"]},{"title":"解出距离的代数处理","type":"数学处理","judge":"如何从含 s 的分式方程中把 s 单独解出","why":"方程两边都含未知量 s，需通分提取公因子 s 后再除系数","do":"提取 s，通分合并分母，把系数除到等号另一边","expr":"s=\\frac{v_1v_2\\Delta t}{v_1-v_2}","cues":["先提公因式","通分","分母是速度差"],"concepts":["分式方程","代数变形"]}],"453":[{"title":"三力平衡的矢量闭合","type":"模型选择","judge":"P 点小球受重力、两个库仑力共三力，是否可用三力平衡（矢量三角形）处理","why":"题设小球在 P 点受力平衡，三力合力为零，必构成封闭三角形，这是后续所有比例关系的前提","do":"对 P 点小球画受力图，把重力竖直向下、两个库仑力沿 PM 与 PN 方向画出，判断三力能否首尾相接闭合","expr":"\\vec{G}+\\vec{F}_{1}+\\vec{F}_{2}=0","cues":["三力平衡","画矢量三角形","先受力分析"],"concepts":["共点力平衡","库仑力","矢量三角形"]},{"title":"库仑力方向沿连线","type":"前提判断","judge":"两个正电荷对带电小球的库仑力方向是沿 MP、NP 连线向外还是向内，取决于小球电性","why":"库仑力沿两点电荷连线，同种电荷相斥、异种电荷相吸；方向定错则矢量三角形画反，比例关系全错","do":"由平衡时重力向下，判断两库仑力必须斜向上，从而确定小球带负电、两力分别沿 PM、PN 指向 M、N","expr":"\\vec{F}_{1}\\parallel \\overrightarrow{PM},\\quad \\vec{F}_{2}\\parallel \\overrightarrow{PN}","cues":["先判电性","力沿连线","指向电荷"],"concepts":["库仑定律","电荷相互作用"]},{"title":"由几何角定力方向夹角","type":"几何关系","judge":"两个库仑力方向之间的夹角由三角形内角决定，需用 ∠PMN=30° 与直角顶点位置求出","why":"矢量三角形中力与力之间的夹角只能由几何角度给出，角度取错则正切关系取错","do":"由 M、N 水平、∠PMN=30° 定出 P 处两连线 PM 与 PN 的夹角，进而得两库仑力夹角","expr":"\\angle MPN=60^\\circ","cues":["看三角形内角","P处夹角","直角在P"],"concepts":["几何关系","直角三角形"]},{"title":"力三角形与几何三角形相似","type":"关系建立","judge":"三力矢量三角形与 P、M、N 几何三角形是否相似，从而把力之比换成边长之比","why":"重力竖直、MN 水平，两库仑力沿 PM、PN，力三角形与几何三角形对应边平行，故相似，力之比等于对应距离之比","do":"写出 F1/F2 与 PM、PN（或对应边）之比的关系，再结合 30° 得具体比值","expr":"\\frac{F_{1}}{F_{2}}=\\frac{PN}{PM}=\\tan 30^\\circ","cues":["力三角形相似","换成边长比","用正切"],"concepts":["相似三角形","力的分解"]},{"title":"库仑定律反平方代入","type":"关系建立","judge":"把力之比写成 Q 与距离平方之比，才能解出 Q1:Q2","why":"库仑力 F=kQq/r²，同一小球 q 相同，力之比只由 Q 与 r² 决定","do":"将 F1、F2 用 kQ1q/PM²、kQ2q/PN² 表示后代入上一步的比值式，解出 Q1/Q2","expr":"\\frac{Q_{1}/PM^{2}}{Q_{2}/PN^{2}}=\\frac{PN}{PM}","cues":["用平方反比","q约掉","代库仑定律"],"concepts":["库仑定律"]},{"title":"沿 MP 移动的单调性判断","type":"临界条件","judge":"小球沿 MP 移动时，两库仑力大小与方向同时变化，需判断能否再次三力平衡","why":"平衡要求两库仑力的合力始终竖直向上且等于重力；移动后 F1 增大而 F2 因距离增大而减小，无法同时满足","do":"设小球沿 MP 偏离 P，比较 F1 与 F2 的变化趋势，用矢量三角形说明合力无法再竖直且等于重力，得出不存在其他平衡点","expr":"F_{1}\\uparrow,\\ F_{2}\\downarrow\\ \\Rightarrow\\ \\text{合力无法保持竖直且等于 }G","cues":["看力怎么变","一个变大一个变小","合力对不上重力"],"concepts":["平衡条件","库仑力变化","反证法"]}],"454":[{"title":"入射角折射角的几何转化","type":"几何关系","judge":"要判断入射角 i 与折射角 r 分别由哪组 L、h 构成，且两角是否都以同一法线（液面法线）为基准","why":"折射定律中的 i、r 是光线与法线的夹角，而题给 L、h 是相对法线和液面的距离，必须通过直角三角形把长度换算成正弦","do":"在入射侧用 L1、h1 构成直角三角形求 sin i，在折射侧用 L2、h2 构成直角三角形求 sin r","expr":"\\sin i=\\frac{L_1}{\\sqrt{L_1^2+h_1^2}},\\quad \\sin r=\\frac{L_2}{\\sqrt{L_2^2+h_2^2}}","cues":["看直角三角形","斜边用勾股","对边比斜边"],"concepts":["折射定律","入射角","折射角"]},{"title":"判断哪一侧是空气哪一侧是糖水","type":"前提判断","judge":"要判断光从空气射入糖水时，入射角对应的是 L1、h1 一侧还是 L2、h2 一侧，从而确定 n 写成 sin i 比 sin r 还是反过来","why":"折射定律 n=sin i/sin r 中 i 必须在空气（真空）一侧，糖水折射率大于 1，若把两侧颠倒会得到小于 1 的结果","do":"对照图(b)确认 A 点在空气中、B 点在糖水中，把 L1、h1 归入分子侧，L2、h2 归入分母侧","expr":"n=\\frac{\\sin i}{\\sin r}","cues":["空气那边是入射","糖水那边是折射","n要大于1"],"concepts":["折射定律","光疏介质","光密介质"]},{"title":"补点并作拟合直线","type":"图像读取","judge":"要判断 32% 对应的点应补在坐标纸哪个位置，以及五个点应连成直线还是折线","why":"题设已说明 n 随浓度近似线性变化，作图应使各点均匀分布在一条直线两侧，而不是逐点折线连接","do":"在横轴 32%、纵轴 1.38 处描点，用直尺作一条穿过尽量多点、两侧偏差均衡的直线","expr":"","cues":["描点要对应坐标","连成一条直线","让点均匀分布"],"concepts":["描点作图","线性拟合"]},{"title":"由斜率换算每 10% 的增量","type":"数据处理","judge":"要判断所求量是图线斜率本身，还是斜率乘以 10.0% 后的折射率增量","why":"图线横轴单位是百分浓度，斜率对应每 1% 的折射率变化，题目问的是每增加 10.0% 的增量","do":"在拟合直线上取两个相距较远的点求斜率，再乘以 10.0 并保留 2 位有效数字","expr":"\\Delta n=\\frac{\\Delta n}{\\Delta \\eta}\\times 10.0\\%","cues":["先求斜率","再乘十","注意有效数字"],"concepts":["图线斜率","有效数字"]}],"455":[{"title":"等效替代的落地方式","type":"前提判断","judge":"要判断“等效替代”在这里替代的是什么量——是保持电流不变时用 R6 的减小量替代 Rx，还是直接读某个电阻值","why":"实验只保证两次电流表示数相同，说明两次总电阻相同，因此 Rx 等于原电路中被减掉的那部分电阻，而不是 R6 的读数本身","do":"对照 S1 接 1（a、b 短接）与接 2（接入 Rx）两种接法，写出两次总电阻相等的等式，找出被替代的电阻量","expr":"R_x=R_{1}+(R_{6初}-R_{6末})","cues":["电流相同总电阻相同","替代的是减小的电阻","不是直接读滑变"],"concepts":["等效替代法","串联电路总电阻"]},{"title":"定标电流的估读","type":"图像读取","judge":"要判断电流表该读到哪一位、最小分度是多少","why":"30 mA 量程对应 30 个小格，每小格 1 mA，指针落在整刻度上仍需按仪器规则估读到下一位","do":"读图(c)指针所指刻度，按 1 mA 分度写出带一位小数的读数","expr":"I=16.0\\ \\mathrm{mA}","cues":["一小格一毫安","要估读一位","读十六"],"concepts":["电流表读数","估读规则"]},{"title":"三种接法的电阻比较","type":"关系建立","judge":"要判断 S1 接 1、2、3 时电路总电阻各由哪些电阻串联组成，并据此把电流大小关系转成电阻大小关系","why":"电源电动势不变，电流小于定标值说明总电阻大于定标时的总电阻，大于定标值说明总电阻更小","do":"分别写出接 1、2、3 时的串联电阻表达式，与接 1 短接时的 400 Ω 比较，解出 Rx 的上下界","expr":"R_1+R_2+R_3+R_6<R_x+R_2+R_3+R_6,\\quad R_x+R_3+R_6<R_1+R_2+R_3+R_6","cues":["电流小电阻大","接2比接1多一个Rx","接3少了一个电阻"],"concepts":["闭合电路欧姆定律","串联电阻"]},{"title":"选对替代档位","type":"模型选择","judge":"要判断第(4)步应把 S1 打在哪一档，才能让 R6 的调节量恰好等于 Rx","why":"只有接入 Rx 的那一档（位置 2）才把 Rx 串入电路，此时减小 R6 才能等效替代 Rx；选 1 或 3 电路结构不同，替代关系不成立","do":"由第(3)问得到的 Rx 范围确认 Rx 与 R1 同量级，选定位置 2，再列 R6 减小量与 Rx 的关系","expr":"R_x=R_1+(100-55)\\ \\Omega","cues":["选接入待测电阻那档","接2才串进Rx","滑变减小量补上"],"concepts":["等效替代法","电路结构分析"]},{"title":"误差来源的甄别","type":"误差分析","judge":"要判断哪些因素会破坏“两次电流相同即总电阻相同”这一等效条件，哪些因素在两次测量中同时存在而抵消","why":"电源内阻、电流表内阻在定标和测量两次中都串在同一回路，电流相同则它们的影响相同，不改变等效关系；而 R6 读数偏差、指针未回定标值会直接破坏等效","do":"逐项检查该因素是否在两次测量中保持不变，只把会改变等效关系的因素选为影响结果","expr":"","cues":["两次都有内阻就抵消","读数偏差直接影响","没回定标值就不等效"],"concepts":["系统误差","等效替代法"]}],"456":[{"title":"读图取各段端点速率","type":"图像读取","judge":"要从 v-t 图上读出 t0、t1、t2、t3 四个时刻对应的速率值，判断每段是直线还是折线","why":"v-t 图上的纵坐标就是瞬时速率，各段端点速率是后续所有计算的输入数据，读错一个值整题全错","do":"在图上对准四个时刻的横坐标，读出纵坐标：t0 处 2.8、t1 处 2.0、t2 处 2.0、t3 处 2.2（单位 m/s）","expr":"","cues":["看纵轴刻度","读出四个速度","端点值","图线拐点"],"concepts":["v-t 图像","瞬时速度"]},{"title":"匀变速段用平均速度公式","type":"模型选择","judge":"t0~t1 段是匀减速直线运动，判断能否用初末速率算术平均求平均速度","why":"只有匀变速直线运动，平均速度才等于初末速度的算术平均值；若误用总位移除以总时间或别的段数据就错","do":"确认该段图线为直线（匀减速），取该段初速率 2.8 与末速率 2.0 求算术平均","expr":"\\bar{v}=\\frac{v_0+v_1}{2}","cues":["匀减速才能取平均","初末速度相加除二","别用总时间","图线是直线"],"concepts":["匀变速直线运动","平均速度"]},{"title":"加速度取速率变化率","type":"关系建立","judge":"t2~t3 段加速度大小由速率变化量与时间间隔之比给出，判断用哪两个时刻的速率差和哪段时间","why":"加速度定义是速度变化率，v-t 图斜率即加速度；时间段必须取 t3-t2 而非整段或 t1~t2","do":"取 t3 与 t2 时刻的速率之差，除以 t3 与 t2 的时间间隔","expr":"a=\\frac{v_3-v_2}{t_3-t_2}","cues":["斜率就是加速度","用冲刺段两端","时间取差值","速度变化除以时间"],"concepts":["加速度","v-t 图斜率"]},{"title":"冲刺段位移用梯形面积","type":"模型选择","judge":"t2~t3 段位移判断用 v-t 图线下面积（梯形）还是用平均速度乘时间","why":"v-t 图线与时间轴围成的面积等于位移，匀加速段为梯形；直接读面积或等价地用平均速度乘时间都得同一结果","do":"取该段初末速率 2.0、2.2 与时间间隔 2 s，按梯形面积（上底加下底乘高除二）计算","expr":"x=\\frac{(v_2+v_3)(t_3-t_2)}{2}","cues":["面积就是位移","梯形面积","平均速度乘时间","冲刺段两秒"],"concepts":["v-t 图面积","位移"]}],"457":[{"title":"F-x图面积求功","type":"图像读取","judge":"求F做的功时，是取F-x图线与x轴围成的面积，还是直接用某个F值乘位移","why":"F随x变化，不是恒力，功只能由F-x图线下面积给出；第(1)问x从0到1 m对应图线是水平段","do":"读图(b)中x=0到1 m段对应的F值，用矩形面积算功","expr":"W=Fx","cues":["看面积","图线下方面积","恒力段"],"concepts":["F-x图像"]},{"title":"整体法求加速度","type":"模型选择","judge":"求A、B间作用力时，先取A、B整体求加速度，还是分别对A、B列方程","why":"A、B一起运动、加速度相同，取整体可避开未知的相互作用力，只出现外力F和摩擦力","do":"对A、B整体沿水平方向列牛顿第二定律，求出共同加速度","expr":"F-\\mu m g=2ma","cues":["取整体","先求加速度","避开内力"],"concepts":["整体法","牛顿第二定律"]},{"title":"隔离B求相互作用力","type":"模型选择","judge":"求A、B间作用力时选哪个物体隔离，B受哪些水平力","why":"B与水平面间无摩擦，隔离B后水平方向只有A对B的弹力，方程最简","do":"隔离B，沿水平方向列牛顿第二定律，代入整体求得的加速度","expr":"F_{AB}=ma","cues":["隔离B","B不受摩擦","只剩弹力"],"concepts":["隔离法","弹力"]},{"title":"分离临界条件","type":"临界条件","judge":"A、B何时分离，分离时两者间弹力满足什么条件","why":"靠在一起的两物体分离瞬间相互作用力恰好减为零，此后加速度不再相同","do":"令A、B间弹力为零，结合第(2)问的受力关系反推此时F的大小，再由F-x图读出对应位移","expr":"F_{AB}=0 \\Rightarrow F'=0.5\\,\\mathrm{N}","cues":["弹力为零","分离瞬间","加速度刚要不同"],"concepts":["临界状态","分离条件"]},{"title":"分段求F的总功","type":"数学处理","judge":"从开始到分离，F做的总功如何由图(b)分段累加","why":"F先恒为1.5 N后线性增大，图线不是单一形状，必须分段求面积再相加","do":"恒力段取矩形面积，倾斜段取梯形面积，两段相加得总功","expr":"W_F=1.5+\\frac{0.5+1.5}{2}\\times 2","cues":["分两段","梯形面积","恒力加变力"],"concepts":["图像面积"]},{"title":"M点最小速度与半径上限","type":"临界条件","judge":"B能到达M点的临界条件是什么，对应半径取最大还是最小","why":"半圆轨道内侧过最高点的临界是重力恰好提供向心力；半径越大越难通过，故临界给出半径上限","do":"对P到M用动能定理，在M点列重力提供向心力的临界式，联立解出最大半径","expr":"mg=m\\frac{v_{\\min}^2}{r},\\ -mg\\cdot 2r=\\frac12 mv_{\\min}^2-\\frac12 mv^2","cues":["最高点临界","重力提供向心力","半径取上限"],"concepts":["圆周运动临界","动能定理"]}],"458":[{"title":"匀速段反推线框边长","type":"临界条件","judge":"要判断线框边长与区域Ⅰ宽度 l1 的大小关系，才能确定匀速段覆盖的位移","why":"cd 边进入Ⅰ到 ab 边离开Ⅰ全程速度恒为 v，说明穿过Ⅰ的整个过程中安培力与重力沿斜面分量始终平衡，只有边长等于 l1 时进出过程才连续匀速","do":"比较线框边长 L 与 l1，由匀速条件 mg sinθ = BIl1 与 E = Bl1v 反解出 L = l1","expr":"L=l_{1},\\quad mg\\sin\\theta=BIl_{1}","cues":["速度一直不变","边长等于宽度","进出都匀速"],"concepts":["安培力平衡","法拉第电磁感应"]},{"title":"区分感应电动势与路端电压","type":"关系建立","judge":"要判断 cd 两端电势差是电源电动势还是外电路电压，即 cd 边是电源、其余三边是外电阻","why":"cd 边切割磁感线产生电动势，线框自身其余部分构成闭合回路并有电阻，电势差只等于外电路分压","do":"把 cd 边看作电源、内阻为 R/4，其余三边为外电阻 3R/4，按分压求 U","expr":"U=\\frac{3}{4}E=\\frac{3}{4}Bl_{1}v","cues":["cd是电源","要分内外电阻","不是整个电动势"],"concepts":["电源内阻","闭合电路欧姆定律"]},{"title":"判定区域Ⅱ宽度与 l1 关系","type":"前提判断","judge":"要判断 l2 与 l1 谁大，因为进入Ⅱ和离开Ⅱ速度相同这一条件对两种宽度给出不同结论","why":"若 l2 = l1，线框在Ⅱ中只减速或先减速后匀速，离开时速度无法恢复到进入时速度，与题设矛盾；只有 l2 ≠ l1 才可能速度先减后增回到原值","do":"先排除 l2 = l1，再分 l2 > l1 与 l2 < l1 两种情形分别讨论","expr":"l_{2}\\neq l_{1}","cues":["先排除相等","要分两种情况","速度能恢复"],"concepts":["安培力做功","动能定理"]},{"title":"用动量定理求磁场中运动时间","type":"模型选择","judge":"要判断求时间应选动量定理而非牛顿第二定律，因为安培力随速度变化、加速度不恒定","why":"安培力 F = B²l1²v/R 与速度成正比，是变力，但冲量可用电荷量 q = ∫I dt 整体替换，动量定理把变力冲量化为电量","do":"对进入Ⅱ到离开Ⅱ的过程列动量定理，用 mg sinθ·t 与 2B l1 q 的冲量差等于动量变化（初末速度相同故动量为零）","expr":"mg\\sin\\theta\\, t-2B\\bar{I}l_{1}t=0,\\quad q=\\bar{I}t","cues":["力随速度变","用动量定理","冲量换成电量"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"由电荷量桥接两种宽度","type":"关系建立","judge":"要判断穿过磁场时通过回路的电荷量只由磁通量变化决定，与速度、时间无关","why":"q = ΔΦ/R = BΔS/R，进入Ⅱ时磁通量变化对应面积 l1·min(l1,l2)，据此把 q 与 l1、l2 联系起来","do":"分别写出 l2 > l1 时 q = Bl1²/R 与 l2 < l1 时 q' = Bl1l2/R，再与动量定理联立消去 B","expr":"q=\\frac{Bl_{1}^{2}}{R}\\ (l_{2}>l_{1}),\\quad q'=\\frac{Bl_{1}l_{2}}{R}\\ (l_{2}<l_{1})","cues":["电量只看面积","与速度无关","用磁通量算电量"],"concepts":["磁通量变化","感应电荷量"]},{"title":"能量守恒求克服安培力做功","type":"关系建立","judge":"要判断初末速度相同则动能变化为零，重力势能减少量全部转化为克服安培力做的功","why":"线框进入Ⅱ与离开Ⅱ速度相同，动能不变，只有重力做正功与安培力做负功，故 W安 = mg sinθ·(l1+l2)","do":"对进入Ⅱ到离开Ⅱ全过程列能量方程，再用平均功率 P = W安/t 求值","expr":"W_{\\text{安}}=mg\\sin\\theta(l_{1}+l_{2}),\\quad P=\\frac{W_{\\text{安}}}{t}","cues":["动能没变","重力做功全给安培力","平均功率用总功除时间"],"concepts":["能量守恒","克服安培力做功","平均功率"]}],"459":[{"title":"识别图像类型","type":"图像读取","judge":"要判断图(b)的纵轴是位置还是速度，即这是 x-t 图还是 v-t 图","why":"x-t 图的斜率表示速度、纵坐标差表示位移；若误当 v-t 图，就会把面积当位移、把纵坐标当速度，全盘皆错","do":"看纵轴标注与单位，确认纵轴为位置 x、横轴为时间 t","expr":"","cues":["看纵轴标的是位置","这是位置时间图","斜率才是速度"],"concepts":["位置-时间图像","斜率"]},{"title":"位移看纵坐标差","type":"关系建立","judge":"要判断位移应取区间两端纵坐标之差，而不是图像上走过的路程或曲线长度","why":"位移是矢量，x-t 图中 Δx=x末−x初，与路径无关；机器人中途可能折返，读成路程就会出错","do":"在图上读出 0 s、10 s、20 s、30 s 四个时刻对应的位置坐标，分别作差","expr":"\\Delta x=x(t_2)-x(t_1)","cues":["位移看首末位置","不能读路程","两端纵坐标相减"],"concepts":["位移","位置坐标"]},{"title":"速度取图像斜率","type":"关系建立","judge":"要判断区间速度等于该段图线的斜率（纵坐标变化量除以时间间隔），而不是纵坐标本身","why":"x-t 图斜率即速度，匀速段斜率恒定；把某个时刻的纵坐标当速度是常见错误","do":"对 0~10 s 和 20~30 s 两段分别取 Δx/Δt 求斜率","expr":"v=\\frac{\\Delta x}{\\Delta t}","cues":["速度是斜率","纵坐标不是速度","用变化量除以时间"],"concepts":["速度","斜率"]},{"title":"分段比较两段结果","type":"结论整理","judge":"要判断两段位移的大小关系和两段速度的大小关系，并注意两段图线倾斜程度不同","why":"题目要求比较 Δx1 与 Δx2、v1 与 v2，需分别由纵坐标差和斜率得出，不能由一段的结论推另一段","do":"比较两段 Δx 的数值，再比较两段斜率的数值（斜率大者速度大）","expr":"","cues":["先比位移再比速度","看哪段更陡","两段分开算"],"concepts":["位移比较","速度比较"]}],"460":[{"title":"选系统与守恒条件","type":"模型选择","judge":"把甲、乙取为一个系统，判断推的过程系统动量是否守恒","why":"冰面光滑、水平方向无外力，推力是系统内力，故系统总动量守恒；不取整体就要多引入推力冲量这个未知量","do":"把甲、乙视为一个系统，只考察水平方向，确认合外力为零","expr":"","cues":["取整体","冰面光滑","水平方向没外力"],"concepts":["动量守恒定律","系统","内力"]},{"title":"动量变化量对应关系","type":"关系建立","judge":"判断甲、乙各自的动量变化量大小是否相等、方向是否相反","why":"系统总动量守恒意味着两物体动量变化量等大反向，这是把甲的动量变化转移到乙身上的桥梁","do":"写出甲的初、末动量，求其动量变化量，再令乙的动量变化量大小与之相等","expr":"\\Delta p_甲=-\\Delta p_乙,\\quad |\\Delta p_甲|=|\\Delta p_乙|","cues":["变化量等大反向","乙的增量等于甲的减量","总动量不变"],"concepts":["动量变化量","动量守恒"]},{"title":"乙初动量为零","type":"前提判断","judge":"判断乙被推前是静止的，初动量为零","why":"题设明确乙原来静止，所以乙分开时的动量就等于它获得的动量变化量，无需再减初动量","do":"确认乙初速度为零，把乙的末动量直接取为动量变化量","expr":"p_{乙0}=0,\\quad p_{乙}=|\\Delta p_乙|","cues":["乙原来静止","初动量为零","直接就是增量"],"concepts":["动量","静止"]},{"title":"同向速度定正负","type":"前提判断","judge":"判断甲、乙分开后速度都与 v0 同向，动量方向相同","why":"题目说明两者运动方向与 v0 相同，所以动量大小之比就是动量数值之比，不必考虑方向带来的符号","do":"以 v0 方向为正，确认甲、乙末动量均为正值，再取大小作比","expr":"p_甲=\\frac{1}{3}p_0>0,\\quad p_乙>0","cues":["都朝前","方向相同","取正方向"],"concepts":["动量矢量性","正方向"]},{"title":"比值化简","type":"数学处理","judge":"判断用甲的初动量 p0 作中间量，把两者末动量都表示成 p0 的倍数再约去","why":"甲的质量和初速度未知，只有用同一个 p0 表示两者动量，未知量才能约掉得到纯比值","do":"写出甲末动量与乙末动量的 p0 表达式，作比并约去 p0","expr":"\\frac{p_甲}{p_乙}=\\frac{\\frac{1}{3}p_0}{\\frac{2}{3}p_0}","cues":["用同一个量表示","约掉初动量","只看系数比"],"concepts":["动量","比例"]}],"461":[{"title":"判断白炽灯发光性质","type":"前提判断","judge":"白炽灯直接发出的光是否为自然光","why":"白炽灯是普通热光源，各方向振动均匀分布，属于自然光；这是判断第一次观察现象的前提","do":"确认白炽灯发光为自然光，振动方向各向均匀","expr":"","cues":["白炽灯是自然光","各方向都有振动"],"concepts":["自然光","偏振"]},{"title":"判断水面反射光的偏振性","type":"模型选择","judge":"自然光经水面反射后变成什么性质的光","why":"自然光斜射到水面反射时，反射光中垂直于入射面的振动占优，成为部分偏振光，这是第二次观察现象的依据","do":"把水面反射当作起偏过程，判断反射光为部分偏振光","expr":"","cues":["反射后是部分偏振光","水面反射会起偏"],"concepts":["部分偏振光","反射起偏"]},{"title":"区分两次旋转的亮度变化","type":"关系建立","judge":"旋转偏振片时，自然光与部分偏振光透射强度随角度如何变化","why":"自然光通过偏振片后强度恒为一半，与透振方向无关；部分偏振光透射强度随透振方向与主要振动方向夹角变化","do":"比较两种光透射强度对旋转角的依赖关系，得出一次不变、一次变化","expr":"I自然=I0/2；I部分随夹角变化","cues":["自然光亮度不变","倒影亮度会变"],"concepts":["马吕斯定律","偏振片透振方向"]}],"462":[{"title":"绳中张力是否等于mg","type":"前提判断","judge":"缓慢下拉过程中配重物是否被拉离地面，从而判断绳中张力是否始终等于配重重力","why":"配重物静止在地面上且绳恰好伸直，缓慢下拉时若配重未被提起，则绳张力由配重平衡决定，恒等于mg；若被提起则张力不再是mg，需另列方程","do":"比较吊环下拉后两侧绳长变化与配重可上升的空间，确认配重仍在地面、绳张力等于mg","expr":"T=mg","cues":["配重没离地","张力等于重力","缓慢拉"],"concepts":["平衡条件","绳的张力"]},{"title":"绳与竖直方向夹角","type":"几何关系","judge":"由两定滑轮间距d和吊环下拉d/2，判断吊环两侧绳与竖直方向的夹角","why":"拉力F与两侧绳张力的合力平衡，合力方向沿竖直，需用几何关系确定张力沿竖直方向的分量","do":"画出吊环位置与两滑轮的几何图，用水平半间距d/2与竖直下拉量d/2构成等腰直角三角形，读出夹角","expr":"\\tan\\theta=\\frac{d/2}{d/2}=1\\Rightarrow\\theta=45^\\circ","cues":["水平竖直都是d/2","等腰直角","夹角45度"],"concepts":["几何关系","角度"]},{"title":"吊环受力平衡方程","type":"关系建立","judge":"把吊环视为受力平衡的结点，判断拉力与两侧绳张力的合力关系","why":"吊环静止，所受合力为零，向下的拉力F与两侧绳张力T的竖直分量之和平衡","do":"对吊环列竖直方向平衡方程，两侧张力竖直分量相加等于F","expr":"F=2T\\cos\\theta","cues":["取吊环为对象","两侧绳对称","竖直方向平衡"],"concepts":["共点力平衡","力的合成与分解"]},{"title":"代入角度与张力求拉力","type":"数学处理","judge":"将θ=45°与T=mg代入平衡方程，判断拉力大小","why":"已确定张力等于mg且夹角为45°，代入即得唯一结果","do":"把T=mg、cos45°=√2/2代入F=2Tcosθ计算","expr":"F=2mg\\cdot\\frac{\\sqrt2}{2}=\\sqrt2 mg","cues":["代入45度","两倍张力乘余弦","根号二倍mg"],"concepts":["三角函数","力的合成"]}],"463":[{"title":"判断A点场强是否为零","type":"模型选择","judge":"两个等量正电荷在中点A产生的场强是否等大反向、合场强是否为零","why":"点电荷场强大小只由电荷量和距离决定，A到两电荷距离相等、电荷等量同号，两个场强矢量沿MN方向反向，必然抵消","do":"分别写出两个电荷在A点的场强方向，比较大小后矢量合成","expr":"E_A = k\\frac{q}{(L/2)^2} - k\\frac{q}{(L/2)^2} = 0","cues":["等大反向","合场强为零","中点抵消"],"concepts":["点电荷场强","矢量合成"]},{"title":"比较A、B两点场强大小","type":"关系建立","judge":"B点合场强是否一定大于A点的零场强","why":"A点合场强为零是特殊对称位置的结果，B点不在中垂线对称抵消的位置，两场强有夹角，合场强不为零","do":"画出B点到M、N的距离和两个分场强方向，判断合场强是否为零","expr":"E_B \\ne 0 \\Rightarrow E_A < E_B","cues":["B点不抵消","有夹角","合场强不为零"],"concepts":["场强叠加","对称性"]},{"title":"判断A、B电势高低","type":"关系建立","judge":"沿电场线方向电势降低，A与B谁的电势更高","why":"无穷远为零电势，两个正电荷周围电势为正；电场线从正电荷出发指向无穷远，A在中点、B在直线外，需比较两点到两电荷的距离之和","do":"比较A、B到M、N的距离之和，距离之和越小电势越高","expr":"\\varphi = k\\frac{q}{r_M}+k\\frac{q}{r_N}","cues":["距离之和","越近电势越高","沿电场线降低"],"concepts":["电势叠加","电势与距离"]},{"title":"排除干扰项的错误判断","type":"结论整理","judge":"各干扰项是把场强关系还是电势关系判断反了","why":"等量同种电荷中垂线上中点场强为零但电势最高，容易误认为场强为零处电势也为零或最低","do":"对照主链结论，检查每项中场强大小和电势高低的方向是否与判断一致","expr":"","cues":["场强为零电势也零","中点电势最低","大小关系弄反"],"concepts":["场强与电势的区别"]}],"464":[{"title":"合力做功对应什么","type":"模型选择","judge":"求合力做的功，是直接算引力做功，还是走动能定理绕开变力做功","why":"卫星沿椭圆式螺旋下降时引力是变力、空气阻力也做功，直接积分不可行；动能定理只关联初末动能，与过程细节无关","do":"确定用 W合=ΔEk，把问题转化为求初、末两个圆轨道上的动能","expr":"W_{\\text{合}}=\\Delta E_k=E_{k2}-E_{k1}","cues":["用动能定理","别算引力做功","只看初末动能"],"concepts":["动能定理","合力做功"]},{"title":"圆轨道动能与半径关系","type":"关系建立","judge":"如何由万有引力提供向心力推出 Ek 与 r 的反比关系","why":"卫星在圆轨道上唯一受力是万有引力，它充当向心力，由此把 v 消去得到只含 r 的动能表达式","do":"联立万有引力定律与向心力公式，解出 v² 再代入 Ek=mv²/2","expr":"G\\frac{Mm}{r^{2}}=m\\frac{v^{2}}{r}\\Rightarrow E_k=\\frac{GMm}{2r}","cues":["万有引力当向心力","动能写成半径的函数","消掉速度"],"concepts":["万有引力定律","向心力","动能"]},{"title":"半径变小动能变大","type":"结论整理","judge":"轨道半径由 R 变为 kR 时，动能是增是减、合外力做正功还是负功","why":"Ek 与 r 成反比，半径减小动能增大，故合力做正功；这决定了结果中分子应为 1−k 的符号方向","do":"比较 kR 与 R 的大小关系，判断 ΔEk 的正负，据此确定表达式符号","expr":"E_k\\propto\\frac{1}{r}","cues":["半径小了动能大","合力做正功","符号别弄反"],"concepts":["动能定理","功能关系"]},{"title":"初末动能作差","type":"数学处理","judge":"把 r=R 与 r=kR 两个动能值代入动能定理并合并成单一分式","why":"题目问的是该段时间内的功，必须用末动能减初动能，且结果要化成与选项同形的分式","do":"写出 Ek1=GMm/(2R)、Ek2=GMm/(2kR)，作差后通分","expr":"W_{\\text{合}}=\\frac{GMm}{2kR}-\\frac{GMm}{2R}=\\frac{GMm(1-k)}{2kR}","cues":["末减初","通分合并","分母带k"],"concepts":["动能定理","分式运算"]}],"465":[{"title":"切割磁感线的有效长度","type":"模型选择","judge":"金属棒转动时哪一段在切割磁感线、有效长度取 r 还是 L","why":"棒平行于轴线放置，棒上各点绕轴做圆周运动，速度方向垂直于半径，只有沿半径方向的投影才与 B 垂直并产生电动势，故有效切割长度是半径 r 而非棒长 L","do":"把棒看成沿半径方向展开的线段，取棒到轴的距离 r 作为切割长度，写出最大电动势","expr":"E_m=BLr\\omega","cues":["取半径方向","棒长不切割","有效长度是r"],"concepts":["动生电动势","有效切割长度"]},{"title":"电动势按正弦规律变化","type":"关系建立","judge":"转动过程中电动势是恒定值还是随时间按正弦规律变化","why":"棒绕轴匀速转动，速度方向与磁场方向的夹角随时间匀速变化，故电动势 e=E_m sin(ωt)，是正弦式交变电","do":"写出瞬时电动势表达式，确认其最大值与周期","expr":"e=BLr\\omega\\sin\\omega t","cues":["是交流电","按正弦变","有最大值"],"concepts":["正弦式交流电","交变电流"]},{"title":"用有效值算电热","type":"前提判断","judge":"求一圈内灯泡消耗的电能时该用最大值、平均值还是有效值","why":"电阻发热功率由电流有效值决定，只有正弦式交流电才满足最大值与有效值的根号二关系，不能直接用最大值或平均值算电热","do":"先由最大值求有效值，再用有效值算功率","expr":"U=\\frac{E_m}{\\sqrt2}","cues":["用有效值","不能拿最大值","除以根号二"],"concepts":["有效值","焦耳热"]},{"title":"一圈时间与能量累积","type":"关系建立","judge":"一圈的时间如何由角速度得到，能量是功率乘整圈时间","why":"匀速转动一圈对应相位变化 2π，周期 T=2π/ω，电功率恒定，故一圈电能等于功率乘周期","do":"写出周期，再乘恒定功率求总电能","expr":"T=\\frac{2\\pi}{\\omega},\\quad E=\\frac{U^{2}}{R}T","cues":["一圈是2π","功率乘时间","先求周期"],"concepts":["周期","电功率"]}],"466":[{"title":"同位素质子数守恒","type":"前提判断","judge":"分子总质子数是否只由各原子的质子数相加决定，与中子数、质量数无关","why":"质子数即原子序数，同位素之间质子数相同，只有中子数不同；判断总质子数不能看质量数","do":"分别写出 C 和 O 的质子数，把两种分子的质子数相加比较","expr":"Z_{\\text{总}}=Z_C+Z_O","cues":["看质子数","质量数不是质子数","同位素质子数一样"],"concepts":["质子数","同位素","原子序数"]},{"title":"中子数由质量数减质子数","type":"关系建立","judge":"比较两种 CO 分子总中子数时，要判断中子数应由质量数减质子数得到，并逐原子计算","why":"中子数 N=A−Z，同位素差异正体现在中子数上，不能直接用质量数代替中子数","do":"对 ^{13}C 与 ^{12}C 分别算中子数，O 相同可抵消，只比较碳的中子数差","expr":"N=A-Z","cues":["质量数减质子数","碳多一个中子","氧相同抵消"],"concepts":["中子数","质量数","同位素"]},{"title":"频率与光子能量成正比","type":"关系建立","judge":"比较辐射光子能量大小时，要判断能量只由频率决定，频率越大能量越大","why":"光子能量 E=hν，h 为常量，能量与频率成正比，与波长成反比","do":"从表格读出三种分子的频率，找出最大频率对应的分子","expr":"E=h\\nu","cues":["频率越大能量越大","看表格频率","能量正比频率"],"concepts":["光子能量","普朗克常量","频率"]},{"title":"波长与频率成反比","type":"关系建立","judge":"比较电磁波波长时，要判断波长与频率成反比，频率最大者波长最短","why":"真空中 c=λν，波速相同，波长与频率成反比","do":"由最大频率直接推出最短波长，与能量最大的分子对应","expr":"\\lambda=\\frac{c}{\\nu}","cues":["频率大波长短","波速相同","反比关系"],"concepts":["电磁波波长","波速","频率"]}],"467":[{"title":"取气体为系统判绝热","type":"前提判断","judge":"把哪部分物质取作研究对象，并判断它与外界有无热交换","why":"气缸和两侧活塞都绝热，气体在迁移过程中不与外界交换热量，这是用热力学第一定律的前提","do":"把全部气体作为系统，确认气缸壁与活塞均绝热，得 Q=0","expr":"Q=0","cues":["取全部气体","气缸绝热","没有热交换"],"concepts":["热力学系统","绝热过程","热力学第一定律"]},{"title":"两侧做功的符号与大小","type":"关系建立","judge":"左侧活塞对气体做正功、气体对右侧活塞做正功，两者方向相反，净功是两者之差","why":"左侧压强 p1 推动气体进入，外界对气体做功 p1V1；右侧气体顶住 p2 膨胀，气体对外做功 p2V2，故净功为 p1V1-p2V2","do":"分别写出左侧活塞做功 p1V1 和右侧气体对外做功 p2V2，再取代数和","expr":"W_{\\text{净}}=p_1V_1-p_2V_2","cues":["左边压进去","右边顶出来","一正一负"],"concepts":["等压过程","体积功"]},{"title":"内能增量与净功相等","type":"关系建立","judge":"把 Q=0 与净功代入热力学第一定律，得到内能变化与 pV 的关系","why":"绝热条件下内能增量等于外界对气体做的净功，这是能量守恒的直接体现","do":"列 ΔU=W净，即 U2-U1=p1V1-p2V2，移项整理","expr":"U_1+p_1V_1=U_2+p_2V_2","cues":["能量守恒","内能变化等于净功","移项配成焓"],"concepts":["热力学第一定律","内能"]},{"title":"内能与温度成正比","type":"前提判断","judge":"由 U1/T1=U2/T2 判断内能与温度成正比，比例系数对同一气体相同","why":"理想气体内能只由温度决定，题设给出 U/T 相等，说明 U=kT 且 k 相同","do":"设 U1=kT1、U2=kT2，k 为同一常数","expr":"U=kT","cues":["内能只看温度","比例系数一样","同一份气体"],"concepts":["理想气体内能","温度"]},{"title":"联立状态方程比较温度","type":"数学处理","judge":"把 pV=CT 与 U=kT 代入守恒式，判断 T1 与 T2 是否相等","why":"理想气体状态方程给出 pV 与 T 成正比，代入后两边同含 (k+C)，只能推出 T1=T2","do":"将 p1V1=CT1、p2V2=CT2 代入 U1+p1V1=U2+p2V2，约去公因子比较 T1、T2","expr":"kT_1+CT_1=kT_2+CT_2\\Rightarrow T_1=T_2","cues":["代入状态方程","两边同除","温度不变"],"concepts":["理想气体状态方程","等焓过程"]}],"468":[{"title":"磁铁极性排布","type":"前提判断","judge":"相邻磁铁同极相对时，管外各段的磁场方向（向上还是向下）如何随位置变化","why":"金属环中的磁通量方向由管内磁铁的磁场方向决定，不先确定各段磁场方向就无法用楞次定律判断感应电流方向","do":"根据图(a)中相邻磁铁 N 极对 N 极、S 极对 S 极的排布，画出管外磁感线，标出各段（尤其 0.11~0.15 m 与 0.35~0.39 m）磁场方向","expr":"","cues":["看磁铁极性","同极相对","磁感线往外冒"],"concepts":["磁场方向","磁感线","磁铁极性"]},{"title":"磁通量增减判断","type":"关系建立","judge":"金属环下落经过某段时，穿过环面的磁通量是增大还是减小、方向朝哪","why":"楞次定律的结论取决于磁通量的方向及其增减，只判断方向不判断增减会得出相反的感应电流方向","do":"比较环到达该段前后所围面积内磁感线的条数与方向，确定磁通量方向及增减趋势","expr":"","cues":["磁通量变大还是变小","穿过环的磁感线","先定方向再定增减"],"concepts":["磁通量","楞次定律"]},{"title":"感应电流与安培力方向","type":"关系建立","judge":"由磁通量变化推得感应电流方向后，环所受安培力是向上还是向下","why":"安培力方向由感应电流方向与所在处磁场方向共同决定，也可直接用楞次定律“来拒去留”判断，两者必须一致","do":"先用楞次定律定感应电流方向（从上往下看），再用左手定则或“来拒去留”定安培力方向，两法互相校验","expr":"","cues":["来拒去留","从上往下看","左手定则验一下"],"concepts":["楞次定律","安培定则","安培力"]},{"title":"v-y 图像读匀速段","type":"图像读取","judge":"图(b)中哪一段速度不随位置变化，即合力为零","why":"只有合力为零（重力与安培力平衡）时速度才恒定，此段才能用动能定理把克服安培力做的功与重力做功相等","do":"在图(b)上找出速度平台段对应的 y 区间（0.24~0.26 m），读出该段速度不变这一特征","expr":"","cues":["找速度不变那段","图线水平","匀速说明合力为零"],"concepts":["速度-位置图像","平衡状态"]},{"title":"动能定理求克服安培力功","type":"关系建立","judge":"匀速段内重力做的功与克服安培力做的功是否相等","why":"该段动能变化为零，由动能定理合力做功为零，故重力做功全部用来克服安培力做功","do":"对 0.24~0.26 m 段列动能定理，用 mgh 算出克服安培力做的功","expr":"mgh-W=0,\\quad W=mg\\,(y_2-y_1)","cues":["动能没变","用高度差算"],"concepts":["动能定理","克服安培力做功"]}],"469":[{"title":"斜槽末端调水平","type":"实验操作","judge":"斜槽末端是否必须调成水平，才能保证小球离开轨道时初速度沿水平方向","why":"平抛运动的定义要求初速度水平，若末端倾斜，小球离轨后做斜抛，水平方向不再匀速、竖直方向也不再是自由落体","do":"调节斜槽末端，用水平仪或让小球在末端附近静止不滚动来检验末端水平","expr":"","cues":["末端要水平","初速度水平","不然成斜抛"],"concepts":["平抛运动","初速度水平"]},{"title":"水平方向取平均间距","type":"数据处理","judge":"求水平速度时，是用四个水平间距逐一算再平均，还是先求平均间距再除以周期","why":"水平方向做匀速直线运动，各段间距理论上相等，取平均值可减小测量偶然误差；逐段算再平均与先平均再除在数学上等价，但用总平均更简洁","do":"把四个水平间距相加除以 4 得平均间距，再除以时间间隔 0.05 s","expr":"v_0=\\frac{\\bar{\\Delta x}}{T}=\\frac{(0.0517+0.0514+0.0505+0.0504)/4}{0.05}","cues":["先求平均值","四段加起来除四","再除以零点零五"],"concepts":["匀速直线运动","平均速度","偶然误差"]},{"title":"竖直方向用逐差法","type":"数学处理","judge":"竖直方向加速度是用相邻两段差一次，还是用逐差法把四段全部用上","why":"匀变速直线运动中相邻相等时间间隔的位移差为恒量 aT²，但单次相减误差大；逐差法把四段数据分成两组相减，充分利用全部数据并减小误差","do":"把后两段之和减前两段之和，再除以 4T²","expr":"a=\\frac{(\\Delta y_4+\\Delta y_3)-(\\Delta y_2+\\Delta y_1)}{4T^2}","cues":["用逐差法","后两段减前两段","四段都要用上"],"concepts":["匀变速直线运动","逐差法","位移差公式"]},{"title":"分清间距与位移差","type":"前提判断","judge":"表中 Δy 是相邻两位置间的竖直间距，还是相邻两段间距之差","why":"逐差公式中的 Δy′ 指相邻相等时间内的位移之差，而表中给出的是每段的位移本身，两者不能混用","do":"明确表中每列是一个时间间隔内的竖直位移，作差时是段与段相减，不是直接代入 Δy","expr":"\\Delta y'=\\Delta y_{n+1}-\\Delta y_n","cues":["表里是每段位移","不是位移差","要先作差"],"concepts":["位移","位移差","时间间隔"]},{"title":"结果保留两位小数","type":"结论整理","judge":"计算结果按几位小数报告，是否在中间步骤提前取整","why":"题目要求结果保留 2 位小数，中间过程若提前取整会引入额外误差，影响末位","do":"中间运算保留足够位数，最后一步再四舍五入到两位小数","expr":"","cues":["最后再取两位","中间别急着约","按题目要求保留"],"concepts":["有效数字","误差"]}],"470":[{"title":"限流接法滑片位置","type":"实验操作","judge":"闭合开关前滑片应置于使变阻器接入电阻最大的一端，需判断哪一端对应最大阻值","why":"限流电路中只有接入电阻最大时回路电流才最小，才能保护毫安表和电源","do":"沿电路图追踪电流从电源经变阻器到铅笔芯的路径，看滑片在 A、B 哪端时变阻器接入长度最长","expr":"","cues":["滑到阻值最大端","看电流从哪进","保护电表"],"concepts":["限流电路","滑动变阻器","安全操作"]},{"title":"电压表分流模型","type":"模型选择","judge":"铅笔芯与电压表并联，毫安表读数是否为流过铅笔芯的电流，还是总电流","why":"电压表内阻只有几百欧，与铅笔芯电阻可比，分流不可忽略，毫安表测的是并联部分总电流","do":"把铅笔芯电流写成总电流减去电压表电流，建立 U 与 I0、RV、Rx 的关系","expr":"I_x=I_0-\\frac{U}{R_V}","cues":["电压表会分流","毫安表测总电流","不能直接用I0"],"concepts":["并联分流","欧姆定律","电表内阻"]},{"title":"数据有效数字比对","type":"数据处理","judge":"表中哪个电压读数与其余数据的有效数字位数不一致","why":"同一电压表量程下读数应保留相同的小数位数，位数异常者即为记录错误","do":"逐个比较五个电压值的小数位数，找出只保留一位小数的那一个","expr":"","cues":["看小数位数","都是两位小数","有一个少一位"],"concepts":["有效数字","仪器读数"]},{"title":"化曲为直建线性关系","type":"关系建立","judge":"如何把 U 与 x 的非线性关系变形为 1/U 与 1/x 的线性关系","why":"U 同时出现在等式两边，直接作 U-x 图不是直线，需解出 U 后取倒数才能与给定斜率截距对应","do":"由并联关系解出 U 的表达式，两边取倒数，整理成 1/U 关于 1/x 的一次函数","expr":"\\frac{1}{U}=\\frac{1}{I_0R_0}\\cdot\\frac{1}{x}+\\frac{1}{I_0R_V}","cues":["先解出U","取倒数","凑成一次函数"],"concepts":["线性化","并联电路","函数拟合"]},{"title":"斜率截距对应物理量","type":"数学处理","judge":"拟合直线的斜率与截距分别对应 R0 和 RV 的哪种组合","why":"只有把整理后的表达式与 y=kx+b 逐项对照，才能从 k、b 反解出两个待测电阻","do":"将斜率等于 1/(I0R0)、截距等于 1/(I0RV)，代入 I0=50.0 mA 分别解出 R0 与 RV","expr":"k=\\frac{1}{I_0R_0},\\quad b=\\frac{1}{I_0R_V}","cues":["斜率含R0","截距含RV","代入50毫安"],"concepts":["图象斜率","图象截距","单位换算"]}],"471":[{"title":"由振动图定P初态","type":"图像读取","judge":"t=0 时刻质点 P 位于平衡位置且向哪个方向运动","why":"振动图像给出的是单个质点位移随时间的变化，t=0 处的斜率符号就是该时刻的速度方向","do":"在图(c)中找 t=0 对应的点，看它之后位移是向正方向还是负方向变化","expr":"","cues":["看t等于零那点","斜率为负","往下走"],"concepts":["振动图像","速度方向"]},{"title":"波形图与振动方向定传播方向","type":"关系建立","judge":"已知 P 点的振动方向和它在波形图上的位置，判断波沿 x 轴正方向还是负方向传播","why":"横波中质点振动方向与波传播方向有确定的对应关系（同侧法/上下坡法），不能凭感觉选","do":"在图(b)中标出 P 点位置，按 P 此刻向下振动，用同侧法判断波前方向","expr":"","cues":["同侧法","上下坡法","波往哪边跑"],"concepts":["横波传播方向","质点振动方向"]},{"title":"从两图分别读波长和周期","type":"图像读取","judge":"波长从波形图上读、周期从振动图上读，两者不能混用","why":"波形图横轴是空间坐标 x，振动图横轴是时间 t，物理意义不同","do":"在图(b)上量相邻同相点间距得波长，在图(c)上量一个完整循环的时间得周期","expr":"\\lambda=8\\times10^{-4}\\,\\mathrm{m},\\quad T=1\\times10^{-6}\\,\\mathrm{s}","cues":["波形图读波长","振动图读周期","别把横轴搞混"],"concepts":["波长","周期"]},{"title":"用波长周期求波速","type":"关系建立","judge":"波速该用波长除以周期，而不是用质点速度","why":"波速是波形整体平移的速度，由介质决定，与质点振动速度无关","do":"把读出的波长和周期代入波速公式","expr":"v=\\frac{\\lambda}{T}","cues":["波速不等于质点速度","用波长除周期"],"concepts":["波速","波长","周期"]},{"title":"时间折合成周期数","type":"数学处理","judge":"3×10⁻⁶ s 是周期的整数倍还是非整数倍","why":"只有整数个周期才能直接用每个周期路程 4A 累加，非整数倍要分段算","do":"用给定时间除以周期，看商是否为整数","expr":"\\frac{3\\times10^{-6}}{1\\times10^{-6}}=3","cues":["先算几个周期","正好三倍","整数倍好办"],"concepts":["周期","全振动"]},{"title":"一个周期路程为四倍振幅","type":"前提判断","judge":"质点做简谐运动时，一个完整周期内通过的路程是否恒为 4A","why":"简谐运动一个周期内从平衡位置出发回到原状态，路程恰为四个振幅，与初相位无关","do":"确认 P 做简谐运动，用 4A 乘周期数求总路程","expr":"s=n\\cdot 4A","cues":["一个周期走四倍振幅","从平衡位置出发","直接乘周期数"],"concepts":["简谐运动","振幅","路程"]}],"472":[{"title":"分段处理上升过程","type":"模型选择","judge":"上升过程要判断是否分成受恒力上升和松手后竖直上抛两段分别处理","why":"F1只作用t1时间，松手后只受重力，两段加速度不同，不能用同一匀变速公式贯穿","do":"把上升过程拆成受F1加速段和松手后减速段，分别列运动学方程再相加","expr":"a=\\frac{F_1-mg}{m},\\quad v_1=at_1,\\quad h_2=\\frac{v_1^2}{2g}","cues":["分两段","松手后只受重力","先加速后减速"],"concepts":["匀变速直线运动","牛顿第二定律"]},{"title":"最高点速度为零","type":"临界条件","judge":"求最大高度时要以松手后速度减为零作为上升终止的临界条件","why":"最高点竖直速度为零，是减速段结束的标志，也是下落段的初态","do":"令减速段末速度为零，用速度位移关系求h2，用速度时间关系求t2","expr":"0=v_1-gt_2,\\quad h_2=\\frac{v_1^2}{2g}","cues":["最高点速度为零","减速到零","到顶就停"],"concepts":["竖直上抛","临界条件"]},{"title":"图像面积求功","type":"图像读取","judge":"要判断图(b)中F2-x图线与x轴围成的面积表示F2做的功","why":"力随位移变化时，F-x图线下的面积等于该力做的功，这是变力做功的通用读图方法","do":"识别图线为过原点的直线，取三角形面积计算F2做的功","expr":"W=\\frac{1}{2}F_m h_0","cues":["面积就是功","三角形面积","看F-x图"],"concepts":["变力做功","F-x图像"]},{"title":"下落全程用动能定理","type":"关系建立","judge":"要判断把重力和F2的功合并，对从最高点到接触谷物的整段下落列动能定理","why":"下落段同时有重力和变力F2做功，用动能定理可避开中间加速度变化，直接求接触谷物时的速度","do":"以最高点到接触谷物为过程，列重力做功加F2做功等于动能增量，解出v2","expr":"W+mgh_0=\\frac{1}{2}mv_2^2","cues":["整段用动能定理","重力也做功","直接求末速度"],"concepts":["动能定理"]},{"title":"碰撞段取向上为正","type":"关系建立","judge":"要判断石杵与谷物作用时受谷物向上的平均力F和向下的重力，并规定正方向后列动量定理","why":"Δt极短，重力冲量不能忽略但可算，动量从向下v2变为零，方向变化必须由正负号体现","do":"取向上为正，列合外力冲量等于动量变化，注意初动量为负、末动量为零","expr":"(F-mg)\\Delta t=0-(-mv_2)","cues":["取向上为正","初速度向下","动量变化带符号"],"concepts":["动量定理","冲量","正方向规定"]},{"title":"牛顿第三定律转换","type":"结论整理","judge":"要判断求出的是谷物对石杵的力，题目问的是石杵对谷物的力，需用牛顿第三定律转换","why":"动量定理研究对象是石杵，得到的是谷物给石杵的支持力，作用力与反作用力等大反向","do":"将求得的F作为石杵对谷物的平均作用力大小作答","expr":"F'=F","cues":["问的是对谷物","作用力反作用力","大小相等"],"concepts":["牛顿第三定律"]}],"473":[{"title":"电场力与重力平衡","type":"前提判断","judge":"粒子在竖直方向受重力和电场力，要判断二者是否必须等大反向","why":"粒子在区域Ⅰ、Ⅱ中都做匀速圆周运动，速率不变且轨迹为圆，合力只能是洛伦兹力，竖直方向合力必须为零","do":"对粒子竖直方向受力分析，令电场力等于重力","expr":"qE=mg","cues":["匀速圆周","合力只当向心力","竖直方向抵消"],"concepts":["匀速圆周运动","电场力","重力平衡"]},{"title":"由弦长定进入点","type":"几何关系","judge":"粒子第一次到达 z=z0 平面时，水平位移与半径、z0 构成什么几何关系","why":"粒子在区域Ⅰ内做半径 R1 的圆弧，从 O 出发到 z=z0 平面，弦长与半径、竖直高度满足勾股关系","do":"先由洛伦兹力提供向心力求 R1，再用弦、半径、z0 的直角三角形求 x","expr":"R1=\\frac{v^2}{g},\\quad x^2+(R1-z_0)^2=R1^2","cues":["先求半径","画圆弧","弦长关系"],"concepts":["洛伦兹力提供向心力","几何关系"]},{"title":"跨区轨迹的周期性","type":"关系建立","judge":"粒子在两区之间来回穿越时，每完成一个周期的水平净位移由什么决定","why":"两区磁场方向相同但大小不同，粒子在两区各走一段圆弧，每次从区域Ⅰ进入区域Ⅱ再返回，水平位移由两段弦长之差决定","do":"设进入区域Ⅱ时速度与分界面夹角 θ，用 R1、x 求 θ，写出单周期水平位移表达式","expr":"\\cos(90^\\circ-\\theta)=\\frac{x}{R_1},\\quad \\Delta x=2R_1\\sin\\theta-2R_2\\sin\\theta","cues":["两段圆弧","弦长之差","来回穿越"],"concepts":["圆周运动","弦长","分界面"]},{"title":"最短时间取最小圈数","type":"临界条件","judge":"到达 P 点所需总水平位移固定时，圈数 n 取何值对应时间最短","why":"每多绕一圈就多花时间，在满足总位移等于 OP 的前提下，圈数越少用时越短，且 n 必须为整数","do":"令 nΔx=OP，从 n=1 起检验能否使 R2 为正且轨迹合理，取满足条件的最小整数 n","expr":"n(2R_1\\sin\\theta-2R_2\\sin\\theta)=\\frac{16v^2}{5g}","cues":["圈数越少越快","取最小整数","检验半径为正"],"concepts":["周期性","最短时间","整数约束"]},{"title":"电场转向后的分运动","type":"模型选择","judge":"电场改为沿 y 轴后，洛伦兹力是否仍与重力平衡，粒子在三个方向各做什么运动","why":"速度沿 x 轴，磁场沿 y 轴，洛伦兹力沿 z 轴且大小 qvB1=mg，恰好抵消重力；y 方向只受电场力","do":"分别对 x、y、z 三方向列受力与运动方程，确认 z 方向合力为零、x 方向匀速、y 方向匀加速","expr":"qvB_1=mg,\\quad x=vt,\\quad y=\\frac12at^2,\\quad a=\\frac{qE}{m}=g","cues":["洛伦兹力沿z轴","重力被抵消","y方向匀加速"],"concepts":["洛伦兹力方向","分运动独立性","匀加速直线运动"]},{"title":"消去时间得轨迹","type":"数学处理","judge":"如何把 x、y 的参数方程合成不含 t 的轨迹方程","why":"题目要求轨迹方程，需消去中间变量 t，得到 y 与 x 的直接关系","do":"由 x=vt 解出 t 代入 y 的表达式","expr":"y=\\frac{gx^2}{2v^2}","cues":["消去时间","参数方程","写成y关于x"],"concepts":["轨迹方程","参数消元"]}],"474":[{"title":"选钢管为研究对象","type":"模型选择","judge":"以钢管还是以结点 O 为研究对象","why":"钢管受重力与两绳拉力三力平衡，直接可求绳的弹力；若取结点 O，会引入缆绳拉力这个未知量，多一个未知数","do":"隔离钢管，画它受的重力和 MO、NO 两段绳的拉力","expr":"","cues":["取钢管","别取结点","隔离钢管"],"concepts":["受力分析","隔离法"]},{"title":"两绳拉力对称相等","type":"前提判断","judge":"MO、NO 两段绳的拉力大小是否相等","why":"两绳与竖直方向夹角均为 60°，钢管水平且匀质，结构左右对称，由水平方向合力为零可判定两拉力大小相等","do":"对钢管列水平方向平衡方程，比较两拉力的水平分量","expr":"T_{MO}\\sin60^\\circ=T_{NO}\\sin60^\\circ","cues":["对称","两边一样","水平方向抵消"],"concepts":["对称性","平衡条件"]},{"title":"竖直方向合成求拉力","type":"关系建立","judge":"两绳拉力的竖直分量之和与钢管重力如何平衡","why":"钢管悬停，竖直方向合力为零，两绳拉力的竖直分量共同承担重力","do":"把两拉力沿竖直方向分解，列竖直方向平衡方程","expr":"2T\\cos60^\\circ=mg","cues":["竖直方向平衡","两个分力抬重力","悬停合力为零"],"concepts":["力的分解","共点力平衡"]},{"title":"夹角取竖直方向","type":"几何关系","judge":"60° 是与竖直方向还是与水平方向的夹角，分解时用余弦还是正弦","why":"题设明确 MO、NO 与竖直方向夹角为 60°，竖直分量对应余弦；若误按与水平方向夹角处理，会得到错误结果","do":"确认 60° 的参考方向，竖直分量取 Tcos60°","expr":"T_y=T\\cos60^\\circ","cues":["跟竖直比","用余弦","别用正弦"],"concepts":["角度定义","力的分解"]}],"475":[{"title":"绝热压缩的判定","type":"前提判断","judge":"气袋被压缩且不计与外界热交换，能否按绝热过程处理","why":"题干明确说明无热交换，即 Q=0，这是后续用热力学第一定律的前提","do":"确认 Q=0，并确认体积减小、外界对气体做正功","expr":"Q=0","cues":["无热交换","绝热压缩","Q等于零"],"concepts":["绝热过程","热力学第一定律"]},{"title":"内能与温度的关系","type":"关系建立","judge":"由外界对气体做功且 Q=0，判断内能如何变化、温度如何变化","why":"理想气体内能只由温度决定，绝热压缩时 W>0、Q=0，由 ΔU=W+Q 得 ΔU>0","do":"用热力学第一定律写出 ΔU=W，判断 ΔU 的正负，再由内能变化推出温度变化","expr":"ΔU=W+Q=W>0","cues":["外界做正功","内能增加","温度升高"],"concepts":["热力学第一定律","理想气体内能"]},{"title":"平均动能由温度决定","type":"关系建立","judge":"分子热运动平均动能的变化该由哪个量决定","why":"理想气体分子平均动能只与温度有关，与体积、压强无直接关系","do":"把温度升高这一结论对应到分子平均动能增大，排除“体积减小使平均动能减小”的干扰","expr":"\\bar{E}_k\\propto T","cues":["平均动能看温度","温度升高动能增大","与体积无关"],"concepts":["分子平均动能","温度的微观意义"]},{"title":"压强变化的合成判断","type":"关系建立","judge":"体积减小与温度升高同时发生时，压强是增大还是减小","why":"由理想气体状态方程 pV/T=C，V 减小使 p 趋于增大，T 升高也使 p 趋于增大，两者同向叠加","do":"用状态方程分别分析 V 减小和 T 升高对 p 的影响，判断两者是否同向","expr":"\\frac{pV}{T}=C","cues":["两个因素同向","体积小温度高","压强一定增大"],"concepts":["理想气体状态方程"]},{"title":"做功正负的界定","type":"结论整理","judge":"气体对外界做功的正负该按哪个主体来表述","why":"体积减小是外界对气体做功，若表述为“气体对外界做功”则应为负值，不能据此说气体对外界做正功","do":"先定做功主体，再判断体积变化方向，最后确定“气体对外界做功”的符号","expr":"W_{\\text{气体对外}}<0","cues":["体积减小","外界对气体做功","气体对外做负功"],"concepts":["体积功","做功的正负"]}],"476":[{"title":"两车运动阶段划分","type":"模型选择","judge":"汽车在 NO 段做匀减速、在 OP 段做匀速圆周，两段需分别用不同规律处理，不能混用","why":"匀减速直线运动用速度位移关系，圆周运动用向心加速度公式，规律不同","do":"把汽车全程拆成 NO 直线减速段和 OP 圆弧匀速段，分别列式","expr":"","cues":["分段处理","先减速后转弯"],"concepts":["匀变速直线运动","匀速圆周运动"]},{"title":"减速段加速度与时间","type":"关系建立","judge":"由初末速度和位移求加速度，再由速度变化求减速时间","why":"NO 段已知初速 2v0、末速 v0、位移 s，速度位移关系可直接定加速度","do":"用 v0²-(2v0)²=-2as 求 a，再用 t=(2v0-v0)/a 求时间","expr":"a=\\frac{3v_0^2}{2s},\\quad t=\\frac{2s}{3v_0}","cues":["先求加速度","再算时间"],"concepts":["速度位移关系","加速度"]},{"title":"列车同步位移比较","type":"关系建立","judge":"列车与汽车同时出发、同时经历这段减速时间，列车位移用 2v0 乘同一时间","why":"列车匀速，且两车运动时间相同，才能比较位移","do":"用 s'=2v0·t 代入汽车减速时间，与 s 比较","expr":"s'=2v_0\\cdot\\frac{2s}{3v_0}=\\frac{4}{3}s","cues":["时间相同","匀速乘时间"],"concepts":["匀速直线运动","同时性"]},{"title":"圆弧段向心加速度","type":"关系建立","judge":"OP 段速率恒为 v0，向心加速度只由 v0 和半径 R 决定","why":"匀速圆周运动向心加速度 a=v²/r，与减速段加速度无关","do":"把 v0、R 代入 a_n=v0²/R","expr":"a_n=\\frac{v_0^2}{R}","cues":["用向心加速度公式","速率不变"],"concepts":["向心加速度","匀速圆周运动"]}],"477":[{"title":"数出标记间隔含几个条纹间距","type":"图像读取","judge":"标记的两条亮纹中心之间隔了几个相邻亮纹间距","why":"条纹间距公式只对应相邻两条亮纹中心的距离，必须先从图样上数清标记两点跨过的间隔数","do":"在干涉图样上数两条被标记亮纹之间夹的亮纹间距个数","expr":"a=4\\Delta x","cues":["数间隔","隔了四条","看条纹数"],"concepts":["干涉条纹间距","亮纹中心"]},{"title":"选用双缝干涉条纹间距公式","type":"模型选择","judge":"该用哪个关系把条纹间距、波长、缝屏距和双缝间距联系起来","why":"杨氏双缝干涉的条纹间距由光程差决定，满足间距与波长、屏距成正比、与缝距成反比","do":"写出条纹间距与 l、λ、d 的关系式","expr":"\\Delta x=\\frac{l}{d}\\lambda","cues":["用条纹间距公式","间距和波长成正比","缝越宽条纹越密"],"concepts":["杨氏双缝干涉","条纹间距公式"]},{"title":"把 a 换算成条纹间距再反解 d","type":"关系建立","judge":"用 a 表示条纹间距后，如何反解出双缝间距 d","why":"题目给的是标记间距 a 而非条纹间距，须先代换再解出 d，否则会差一个倍数","do":"将 Δx=a/4 代入公式，解出 d 的表达式","expr":"d=\\frac{\\lambda l}{\\Delta x}=\\frac{4\\lambda l}{a}","cues":["先换成四分之一","再解缝距","别漏倍数"],"concepts":["条纹间距","双缝间距"]}],"478":[{"title":"识别类平抛模型","type":"模型选择","judge":"两粒子在匀强电场中是否做类平抛运动（初速度垂直于电场、只受恒定电场力）","why":"初速度垂直于 OQ 而电场平行于 OQ，电场力恒定且与初速垂直，忽略重力，故为类平抛；不识别此模型就无法把运动分解到两个方向","do":"把运动分解为沿初速方向的匀速直线运动和沿电场方向的初速为零的匀加速直线运动","expr":"","cues":["分解成两个方向","沿电场方向加速","垂直方向匀速"],"concepts":["类平抛运动","运动的分解"]},{"title":"同时到达定时间相等","type":"前提判断","judge":"两粒子从进入电场到到达 M、N 所用时间是否相等","why":"题设明确两粒子同时进入、同时到达，这是比较两粒子各量的时间基准；不先定下时间相等，就无法由位移比推出速度比","do":"由同时进入、同时到达，判定两粒子运动时间相同","expr":"t_a=t_b","cues":["同时进入同时到达","时间一样","用同一个时间"],"concepts":["运动时间","同时性"]},{"title":"由水平位移比求初速比","type":"关系建立","judge":"沿初速方向的位移之比对应什么，能否由此得到初速度之比","why":"沿初速方向匀速，位移等于初速乘时间，时间相等时位移比即初速比；这是后续比较速度、时间的基础","do":"从图中读出 a、b 沿初速方向的位移之比，结合时间相等写出初速之比","expr":"x_a:x_b=v_{0a}:v_{0b}=2:1","cues":["水平位移比就是速度比","时间相同","读图量位移"],"concepts":["匀速直线运动","位移与速度"]},{"title":"由电场方向位移定加速度","type":"关系建立","judge":"两粒子沿电场方向的位移相等时，加速度是否相等，进而比荷是否相同","why":"沿电场方向初速为零，位移由 y=½at² 决定，时间相等且位移相等则加速度相等；再结合 qE=ma 得比荷相同，这是判断比荷类选项的依据","do":"比较两粒子沿电场方向的位移，用 y=½at² 求加速度关系，再用牛顿第二定律联系比荷","expr":"y=\\frac12at^2,\\quad qE=ma","cues":["电场方向位移相等","加速度一样","比荷相同"],"concepts":["匀加速直线运动","牛顿第二定律","比荷"]},{"title":"交点处水平位移相同","type":"几何关系","judge":"轨迹交点 K 对两粒子意味着沿初速方向的位移相同，能否据此比较到达 K 的时间","why":"K 是两轨迹的公共点，到各自起点的水平距离相等，而水平方向匀速，位移相同、初速不同则时间不同，这是判断时间比选项的关键","do":"找出 K 到 Q、O 的水平距离相等，用 x=v₀t 分别写出两粒子到 K 的时间并求比","expr":"x=v_{0a}t_a'=v_{0b}t_b'\\Rightarrow t_a':t_b'=1:2","cues":["交点水平距离一样","速度大的用时短","时间比是速度比倒数"],"concepts":["轨迹交点","匀速直线运动"]},{"title":"电场力做功判电势能","type":"结论整理","judge":"电场力对两粒子做正功还是负功，电势能如何变化","why":"粒子沿电场力方向发生位移，电场力做正功，电势能减小；这是排除电势能变化类干扰项的依据","do":"判断电场力方向与位移方向同向，得出电场力做正功、电势能减小","expr":"W=qEy>0,\\ \\Delta E_p<0","cues":["电场力做正功","电势能减小","顺着电场力走"],"concepts":["电场力做功","电势能"]}],"479":[{"title":"光子能量与波长关系","type":"关系建立","judge":"由光子能量 E 求其波长，应使用哪个关系式","why":"光子能量与波长由 E=hc/λ 联系，这是能量与波长的基本换算关系","do":"写出 E=hc/λ 并解出 λ","expr":"E=\\frac{hc}{\\lambda}\\Rightarrow\\lambda=\\frac{hc}{E}","cues":["能量换波长","用普朗克关系"],"concepts":["光子能量","波长"]},{"title":"吸收光子后能量与质量","type":"前提判断","judge":"原子吸收光子后总能量增加，其质量应增大还是减小","why":"由质能关系 E=Δmc²，能量增加对应质量增加，吸收过程不可能使质量减少","do":"比较吸收前后原子（含光子能量）的总能量，判断质量变化方向","expr":"\\Delta E=\\Delta m c^{2}","cues":["吸收能量质量变大","质能对应"],"concepts":["质能方程","能量守恒"]},{"title":"德布罗意波长用动量","type":"模型选择","judge":"求原子吸收光子后的物质波波长，应选动量 p 还是速度等其他量","why":"德布罗意关系 λ=h/p 直接以动量为自变量，题目已给出吸收后的动量 p","do":"直接代入 λ=h/p，不再引入速度或质量","expr":"\\lambda=\\frac{h}{p}","cues":["物质波用动量","德布罗意关系"],"concepts":["德布罗意波","动量"]},{"title":"跃迁需能量严格匹配","type":"临界条件","judge":"波长更长的光子能否仍使原子发生同样的跃迁","why":"能级差固定，只有能量恰等于能级差的光子才能被吸收；波长更长则能量更小，不满足跃迁条件","do":"比较 E'=hc/λ' 与能级差 E 的大小","expr":"E'=\\frac{hc}{\\lambda'}<E","cues":["能量要正好等于能级差","波长长能量小"],"concepts":["能级跃迁","光子能量"]}],"480":[{"title":"凌日几何的相似关系","type":"几何关系","judge":"金星小黑点的位移 L 与地球两点间距 d 之比，对应的是哪两个距离之比","why":"太阳直径远小于金星轨道半径，可把太阳当点处理，地球两点、金星两点与太阳构成两个相似三角形，底边之比等于到太阳的距离之比","do":"画出地球两点、金星两点与太阳的连线，用相似三角形把 d、L 与地球轨道半径、金星轨道半径联系起来","expr":"\\frac{r_{\\text{地}}}{r_{\\text{金}}}=\\frac{d+L}{L}","cues":["画相似三角形","太阳当点看","底边比等于距离比"],"concepts":["相似三角形","光沿直线传播"]},{"title":"轨道半径比的分子是d+L","type":"前提判断","judge":"地球轨道半径对应的是 L 还是 d+L","why":"地球上的观测点比金星更远，地球两点张开的底边对应的是金星到太阳距离加上地球到金星距离，即 d+L 而非 d","do":"比较地球、金星到太阳的距离大小，确定相似比中地球一侧取 d+L","expr":"r_{\\text{地}}:r_{\\text{金}}=(d+L):L","cues":["地球在外侧","别把d当半径","金星在内侧"],"concepts":["轨道半径","相似比"]},{"title":"万有引力提供向心力","type":"模型选择","judge":"用哪个力、对哪个量建立圆周运动方程","why":"行星绕太阳做匀速圆周运动，唯一提供向心力的是太阳对行星的万有引力","do":"对地球和金星分别写万有引力等于向心力的方程，消去行星质量","expr":"\\frac{GMm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r=m\\frac{v^{2}}{r}=ma","cues":["万有引力当向心力","消掉小m","同一个中心天体"],"concepts":["万有引力定律","向心力"]},{"title":"各量随半径的幂次关系","type":"关系建立","judge":"周期、线速度、向心加速度分别与轨道半径的几次方成比例","why":"由同一组方程解出 T、v、a 的表达式，指数不同导致比值方向不同，选错指数就会选错项","do":"分别解出 T∝r^{3/2}、v∝r^{-1/2}、a∝r^{-2}，再代入半径比","expr":"T\\propto r^{3/2},\\quad v\\propto r^{-1/2},\\quad a\\propto r^{-2}","cues":["周期是二分之三次","速度是负二分之一次","加速度是平方反比"],"concepts":["开普勒第三定律","圆周运动参量"]},{"title":"比值方向与大小核对","type":"结论整理","judge":"半径较大的地球，其周期应更大、线速度和向心加速度应更小","why":"r 越大，T 越大而 v、a 越小，可据此排除把比值取反的干扰项","do":"用 r地>r金 核对三个比值的正反，选出与幂次关系一致的一项","expr":"\\frac{T_{\\text{地}}}{T_{\\text{金}}}=\\sqrt{\\left(\\frac{d+L}{L}\\right)^{3}},\\quad \\frac{v_{\\text{地}}}{v_{\\text{金}}}=\\sqrt{\\frac{L}{d+L}},\\quad \\frac{a_{\\text{地}}}{a_{\\text{金}}}=\\left(\\frac{L}{d+L}\\right)^{2}","cues":["地球周期更长","地球速度更小","比值别取反"],"concepts":["比例关系","定性核对"]}],"481":[{"title":"相邻实线间距定波长","type":"关系建立","judge":"第1圈与第3圈实线之间隔了几个完整波长","why":"实线表示波峰，相邻两条实线（波峰）之间的距离才是一个波长，第1圈到第3圈跨过2个波长","do":"用第3圈半径减第1圈半径，再除以间隔的波长数","expr":"2\\lambda = 9r - r \\Rightarrow \\lambda = 4r","cues":["相邻实线差一个波长","隔了两圈","半径差除以二"],"concepts":["波长","波峰","简谐波"]},{"title":"波速由波长频率定","type":"关系建立","judge":"波速该用波长和频率的哪个关系求","why":"波速由介质和波源频率共同决定，简谐波满足 v=λf，波长已由几何关系求出","do":"把 λ=4r 与频率 f 代入波速公式","expr":"v = \\lambda f = 4fr","cues":["波速等于波长乘频率","先求波长再求速度"],"concepts":["波速","波长","频率"]},{"title":"由首圈半径定浮筒相位","type":"前提判断","judge":"第1圈波峰半径 r 与波长 4r 的比值说明浮筒此刻在什么位置","why":"波峰从浮筒处向外传播，最近一个波峰到波源的距离等于波源到平衡位置的距离对应的相位差，r=λ/4 说明浮筒此刻正处在平衡位置","do":"比较 r 与 λ 的大小关系，判断浮筒偏离平衡位置的位移","expr":"r = \\frac{\\lambda}{4}","cues":["浮筒在平衡位置","波峰刚离开波源"],"concepts":["相位","平衡位置","波源"]},{"title":"由传播方向定振动方向","type":"模型选择","judge":"波向外传播时，平衡位置处的浮筒下一时刻向哪个方向运动","why":"波向外传播，波源处质点的振动方向与波前传播方向满足同侧法（或由波形平移判断），不能只看波峰向外扩就认为浮筒向上","do":"画出波峰向外移动一小段后的波形，看浮筒处质点位移的正负变化","expr":"","cues":["波向外传","用同侧法","看波形平移"],"concepts":["波的传播方向","质点振动方向","同侧法"]},{"title":"四分之一周期后的位置","type":"临界条件","judge":"从平衡位置向下振动，经过 T/4 后到达哪个极端位置","why":"简谐振动从平衡位置到最大位移恰好用四分之一周期，方向由振动方向决定","do":"由 T=1/f 取四分之一周期，结合已判定的向下振动确定到达最低点","expr":"t = \\frac{1}{4f} = \\frac{T}{4}","cues":["四分之一周期到端点","向下振动到最低点","周期是频率倒数"],"concepts":["周期","简谐振动","最大位移"]}],"482":[{"title":"直流段电流的求法","type":"关系建立","judge":"求直流输电线上的电流时，应判断用输送功率除以哪一个电压","why":"输送功率 P 是输电线路首端的总功率，必须除以输电线路两端的电压（1.6×10⁶ V），而不是除以用户端电压；若错用 1.0×10⁴ V 或 220 V，电流就会算错，后续导线电阻的判断也全错","do":"用 I=P/U 代入 P=8.0×10⁹ W、U=1.6×10⁶ V 求直流电流","expr":"I=\\frac{P}{U}","cues":["用输送电压","别用用户电压","先算电流"],"concepts":["电功率","输电电压"]},{"title":"损耗上限转电阻上限","type":"临界条件","judge":"把“损耗不超过输送功率 5%”这一条件转化为导线总电阻的上限","why":"损耗功率由 P损=I²R 决定，5% 是允许的最大损耗，对应的是允许的最大电阻；只有取这个临界值才能得到电阻的上限，而不是某个确定值","do":"先算 P损=5%P，再由 R=P损/I² 求导线总电阻的最大值","expr":"P_{\\text{损}}=0.05P=I^{2}R","cues":["取最大损耗","损耗对应电阻上限","用电流平方"],"concepts":["焦耳定律","功率损耗"]},{"title":"交流电有效值与峰值","type":"图像读取","judge":"从瞬时值表达式 220√2 sin(100πt) V 中读出峰值和有效值，并判断家用电压该用哪一个","why":"表达式前的系数是峰值 220√2 V，有效值才是 220 V；变压器匝数比按有效值计算，若把峰值当有效值代入，匝数比就会算错","do":"由表达式读出峰值 Um=220√2 V，取有效值 U=Um/√2=220 V 作为副线圈电压","expr":"U=\\frac{U_m}{\\sqrt{2}}","cues":["系数是峰值","家用是有效值","除以根号二"],"concepts":["交流电有效值","峰值"]},{"title":"由角频率求频率","type":"关系建立","judge":"由表达式中的角频率 100π 判断交流电频率是否为 50 Hz","why":"角频率 ω 与频率 f 的关系是 ω=2πf，100π 对应 50 Hz；若直接把 100π 当作频率或忘记除以 2π，就会误判频率项","do":"用 f=ω/2π 代入 ω=100π 计算频率","expr":"f=\\frac{\\omega}{2\\pi}","cues":["角频率除以二派","一百派对应五十","别把角频率当频率"],"concepts":["角频率","频率"]},{"title":"理想变压器匝数比","type":"关系建立","judge":"判断配电变压器原、副线圈的电压比与匝数比、电流比的关系","why":"理想变压器电压比等于匝数比，电流比等于匝数比的反比；原线圈电压应取 1.0×10⁴ V 的有效值，副线圈取 220 V，若电压取错或把电流比当成正比就会出错","do":"用 n₁/n₂=U₁/U₂ 求匝数比，再由 I₁/I₂=n₂/n₁ 求电流比","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2},\\quad \\frac{I_1}{I_2}=\\frac{n_2}{n_1}","cues":["电压比等于匝数比","电流比反过来","原线圈用一万伏"],"concepts":["理想变压器","匝数比"]}],"483":[{"title":"电压均匀增加的含义","type":"前提判断","judge":"由 gh 两端电压随时间均匀增加，能否判定 gh 在磁场中做匀变速直线运动","why":"电压 U=Bdv，U 随时间均匀变化即 v 随时间均匀变化，这正是匀变速直线运动的定义；不抓住这一点就无法把动力学方程与运动学方程联立","do":"写出 U=Bdv，把“U 随 t 均匀增加”翻译成“v 随 t 均匀变化”，从而确定加速度 a 为常量","expr":"U=Bdv,\\quad U\\propto t\\Rightarrow v=v_0+at","cues":["电压正比速度","速度均匀变","就是匀变速"],"concepts":["动生电动势","匀变速直线运动"]},{"title":"分离恒力与速度项","type":"关系建立","judge":"把牛顿第二定律写成 kv+b-B²d²v/R=ma 后，如何让加速度与速度无关","why":"只有 v 的系数整体为零，a 才与 v 无关、才是匀变速；否则 a 随 v 变化，与“匀变速”前提矛盾","do":"令 v 的系数 k-B²d²/R=0，剩下的常数项 b 提供恒定加速度","expr":"k-\\frac{B^2d^2}{R}=0,\\quad ma=b","cues":["速度项要抵消","加速度得恒定","系数配平"],"concepts":["安培力","牛顿第二定律"]},{"title":"无磁场段用动量定理","type":"模型选择","judge":"gh 在无磁场区域时 F=0，但有感应电流和安培力，该用动量定理还是牛顿定律逐点积分","why":"安培力随速度变化，是变力，直接积分加速度困难；安培力的冲量可写成 Bdq=B²d³/R，与速度细节无关","do":"对无磁场段列动量定理，把安培力冲量化为电量与 B d 的乘积","expr":"-\\frac{B^2d^3}{R}=mv_0-mv_{\\max}","cues":["变力用冲量","电量乘磁感应强度","别硬积加速度"],"concepts":["动量定理","安培力冲量","电荷量"]},{"title":"两段速度衔接","type":"关系建立","judge":"v₀ 与 v_max 分别对应磁场段的哪一端，两段运动如何用同一组 v₀、v_max 衔接","why":"v₀ 是每次进入磁场左边界的速度（磁场段初速），v_max 是磁场段末速，也是无磁场段初速；不明确衔接点就无法联立两个方程","do":"对磁场段用 v_max²-v₀²=2ad（位移为 d），对无磁场段用动量定理，两式共用 v₀、v_max","expr":"v_{\\max}^2-v_0^2=2ad,\\quad a=\\frac{b}{m}","cues":["进磁场是v₀","出磁场最快","两段接同一个速度"],"concepts":["运动学公式","速度衔接"]},{"title":"解出质量与最大速度","type":"数学处理","judge":"联立动量定理式与速度位移式时，如何消元得到 m 和 v_max 的表达式","why":"两个方程含 m、v_max 两个未知量，必须先用 a=b/m 把运动学式化为含 m 的形式再与动量式联立，否则无法定解","do":"由 v_max²-v₀²=2bd/m 与动量式消去 v_max，先解 m 再回代求 v_max","expr":"m=\\frac{k^2d}{2(b-kv_0)},\\quad v_{\\max}=\\frac{2b}{k}-v_0","cues":["先消最大速度","两个方程两个未知","回代求另一个"],"concepts":["联立方程","消元"]},{"title":"磁场段的时间","type":"关系建立","judge":"求 gh 穿过一个磁场区域所用时间，应使用哪段速度变化","why":"磁场段是匀变速，时间由速度增量除以加速度决定，而速度增量是 v_max-v₀，不是整个过程的平均速度","do":"用 t=(v_max-v₀)/a 并结合 a=b/m、v_max-v₀ 的表达式化简","expr":"t=\\frac{v_{\\max}-v_0}{a}=\\frac{kd}{b}","cues":["用速度增量","除以加速度","别用平均速度"],"concepts":["匀变速运动","加速度"]}],"484":[{"title":"螺旋测微器读数规则","type":"实验操作","judge":"读数时主尺整毫米数与可动刻度示数如何组合、是否要估读","why":"螺旋测微器精度为 0.01 mm，可动刻度需估读到 0.1 分度，固定刻度半毫米线是否露出决定主尺读数","do":"先读固定刻度整毫米（及半毫米）数，再读可动刻度与主尺横线对齐的格数并估读一位，相加","expr":"d=d_0+n\\times0.01\\,\\mathrm{mm}","cues":["看半毫米线露没露","可动刻度要估读一位","主尺加可动刻度"],"concepts":["螺旋测微器","估读","精度"]},{"title":"F-l 图纵轴截距含义","type":"图像读取","judge":"弹力为零时对应的横坐标是否为弹簧原长","why":"弹簧处于原长时弹力为零，F-l 图线与横轴交点即原长；图线不过原点是因为横轴是弹簧长度而非伸长量","do":"在 F-l 图上找 F=0 对应的 l 值，读横轴截距","expr":"F=0\\Rightarrow l=l_0","cues":["弹力为零就是原长","看横轴交点","横轴是长度不是伸长量"],"concepts":["胡克定律","原长","图像截距"]},{"title":"斜率与劲度系数的对应","type":"关系建立","judge":"F-l 图线斜率的绝对值是否等于劲度系数","why":"由胡克定律 F=k(l-l_0)，F 随 l 线性增大，斜率大小即 k，与截距无关","do":"在直线上取相距较远的两点，用纵坐标差除以横坐标差求斜率大小","expr":"k=\\left|\\dfrac{\\Delta F}{\\Delta l}\\right|","cues":["斜率就是劲度系数","取两点算斜率","别用截距算"],"concepts":["胡克定律","斜率","劲度系数"]},{"title":"反向延长线取截距","type":"数学处理","judge":"实验数据只覆盖部分区间时，如何由延长线得到纵轴截距","why":"题给图线未画到 l=0 附近，需按线性规律反向延长才能读出 F 轴截距，用于求原长或校核","do":"沿直线趋势反向延长至横轴或纵轴，读出交点坐标","expr":"F=k(l-l_0)","cues":["把直线延长","看纵轴交点","按趋势外推"],"concepts":["线性外推","截距","胡克定律"]},{"title":"有效数字与单位换算","type":"结论整理","judge":"结果保留几位有效数字、长度单位是否统一为米","why":"题目要求保留 3 位有效数字，而图中长度以 mm 给出，代入斜率公式前须换算成 m 才能得到 N/m","do":"把 mm 换算为 m 后计算斜率，结果按 3 位有效数字书写","expr":"1\\,\\mathrm{mm}=10^{-3}\\,\\mathrm{m}","cues":["毫米换成米","保留三位有效数字","单位要统一"],"concepts":["有效数字","单位换算"]}],"485":[{"title":"电流表内外接选择","type":"模型选择","judge":"测约 0.05 Ω 的小电阻时，电流表应内接还是外接","why":"待测电阻远小于电压表内阻（10 MΩ）而接近电流表内阻（1 Ω），电压表分流可忽略、电流表分压不可忽略，须用电流表外接以减小系统误差","do":"比较待测电阻与两表内阻的数量级，判断电流表该接在电压表并联节点之内还是之外，据此确定 Q 端接 b 还是 c","expr":"R_x \\ll R_V \\Rightarrow \\text{外接}","cues":["小电阻","外接法","电压表内阻很大"],"concepts":["电流表外接法","系统误差","伏安法测电阻"]},{"title":"分压接法的安全位置","type":"实验操作","judge":"闭合开关前滑片应放在使测量电路电压最小的那一端","why":"滑动变阻器为分压接法，闭合开关瞬间须保证待测部分分得电压为零，防止电表与线圈过流","do":"看分压电路输出端接法，找出使输出电压为零的滑片端，选 d 或 e","expr":"","cues":["分压接法","保护电表","电压从零开始"],"concepts":["分压电路","电学实验安全"]},{"title":"释放电流对应的电动势","type":"关系建立","judge":"衔铁被释放的临界条件对应热电偶电动势多大","why":"线圈与热电偶构成闭合回路，吸合力不足的临界是线圈电流降到 142 mA，此时电动势由欧姆定律唯一确定","do":"用测得的组合体电阻乘临界电流，算出释放瞬间的电动势阈值","expr":"E=Ir=0.020\\times142\\times10^{-3}\\ \\mathrm{V}","cues":["临界电流","欧姆定律","先算阈值"],"concepts":["闭合电路欧姆定律","临界状态"]},{"title":"从图像读释放时刻","type":"图像读取","judge":"在 E'-t 图上取哪一时刻作为衔铁释放的时刻","why":"停止加热后电动势随时间单调下降，降到阈值那一刻即释放时刻，须在曲线上找纵坐标等于阈值的点","do":"在纵轴上定位算出的电动势阈值，作水平线交曲线，读出对应横坐标，再减去停止加热时刻","expr":"\\Delta t=t_2-t_1","cues":["找交点","读横坐标","减去停止时刻"],"concepts":["图像法","电动势随时间变化"]},{"title":"直接连接后的时间等效","type":"前提判断","judge":"A、B 直接连接后，同一冷却过程中释放时间是否仍由同一 E'-t 曲线决定","why":"题设说明加热冷却过程相同且不计温度对电阻的影响，故电动势随时间的变化关系不变，只是回路总电阻改变使阈值电动势改变","do":"确认可直接沿用图(c)曲线，仅用新电阻重算阈值电动势，再重复读图","expr":"E'_{\\text{新}}=Ir_{\\text{新}}","cues":["曲线不变","电阻变了","沿用原图"],"concepts":["等效替代","控制变量"]}],"486":[{"title":"判断气体变化过程","type":"前提判断","judge":"腔内气体从初态到末态经历的是等温过程还是绝热过程","why":"题目明确给出末态腔内气体温度与初始时相同，且气体被密闭在气腔中，质量不变","do":"比较初末两态的温度，确认温度不变，从而选定玻意耳定律而非理想气体状态方程的一般形式","expr":"T_1=T_2","cues":["温度没变","等温变化","用玻意耳定律"],"concepts":["理想气体","等温过程","玻意耳定律"]},{"title":"确定气体体积变化","type":"几何关系","judge":"下极板下移后气腔体积如何用极板间距表示","why":"气腔由平行板与绝缘侧壁围成，体积等于底面积乘极板间距，间距由 d 变为 2d","do":"写出初态体积与末态体积，代入玻意耳定律求末态压强","expr":"V_1=Sd,\\quad V_2=2Sd,\\quad p_2=\\frac{p}{2}","cues":["体积翻倍","间距变两倍","底面积不变"],"concepts":["气腔体积","玻意耳定律"]},{"title":"选下极板为受力对象","type":"模型选择","judge":"求外界压强时该对谁做受力分析","why":"外界压强只通过下极板下表面与腔内气体共同作用于下极板，上极板固定不参与平衡","do":"隔离下极板，列出竖直方向受力平衡方程，把腔内压强、重力、外界压强联系起来","expr":"p_2S+mg=p_0'S","cues":["取极板","隔离下极板","看下极板受力"],"concepts":["受力分析","平衡条件","压强"]},{"title":"判断压强差方向","type":"关系建立","judge":"外界压强与腔内压强谁大，重力项应加在哪一侧","why":"下极板能停在 2d 处，说明外界压力与腔内压力之差恰好平衡极板重力，方向由外界指向腔内","do":"由平衡方程解出外界压强，确认重力项与腔内压强同侧相加","expr":"p_0'=\\frac{p}{2}+\\frac{mg}{S}","cues":["外界压强更大","重力向下","压力差托住极板"],"concepts":["力平衡","压力","重力"]},{"title":"电容只随间距变化","type":"近似条件","judge":"间距改变时，决定电容的介电常数、正对面积是否随之改变","why":"题目说明不计相对介电常数的变化，极板面积 S 不变，只有间距由 d 变为 2d","do":"用平行板电容器决定式比较初末电容，间距加倍则电容减半","expr":"C=\\frac{\\varepsilon S}{4\\pi kd}\\Rightarrow \\frac{C'}{C}=\\frac{d}{2d}=\\frac12","cues":["面积没变","介电常数不变","只看间距"],"concepts":["平行板电容器","电容决定式"]}],"487":[{"title":"定圆心与半径","type":"几何关系","judge":"粒子水平射出后，圆周运动的圆心在入射点正下方还是正上方，半径由 O 点位置如何确定","why":"粒子速度水平，洛伦兹力竖直，圆心必在过 K 的竖直线上；光点在 O 点，说明轨迹过 O，圆心到 O 的距离等于半径","do":"在过 K 的竖直线上取圆心，令圆心到 O 的距离等于圆心到 K 的距离，解出半径","expr":"r=\\frac{OK}{2}=\\frac{3h}{2}","cues":["圆心在竖直线","半径是高度一半","轨迹过O点"],"concepts":["洛伦兹力","匀速圆周运动","几何关系"]},{"title":"正负粒子轨迹拼圆","type":"模型选择","judge":"两端同时发射的正、负粒子轨迹是各自独立的两段圆弧，还是能拼成一个完整圆并在 N 点相切","why":"正负粒子速度方向相反、比荷大小相同，在同一磁场中偏转方向相反，轨迹关于发射管对称，题设说恰都能在 N 点产生光点，意味着两段弧在 N 点相接","do":"画出正、负粒子轨迹，判断两段圆弧在 N 点相切并合成一个整圆，圆心在发射管所在直线上","expr":"","cues":["正负轨迹对称","两段弧拼成整圆","在N点相切"],"concepts":["左手定则","对称性","圆周运动"]},{"title":"由旋转角定圆心角","type":"几何关系","judge":"发射管逆时针转 60° 后，整圆圆心到 N 的连线与发射管方向之间的夹角取多少","why":"整圆圆心在发射管所在直线上，N 在屏上，ON 与发射管方向的夹角由旋转角和屏面水平关系共同决定","do":"用旋转 60° 及 ON 与竖直方向的关系，求出圆心到 N 的半径与屏面法线方向的夹角，再结合 N 点位置解出半径","expr":"r_1=2h","cues":["先找圆心位置","用60°角","半径由ON定"],"concepts":["几何关系","圆周运动半径"]},{"title":"关闭磁场后做匀速直线","type":"临界条件","judge":"关闭磁场瞬间粒子不再受洛伦兹力，之后沿该时刻速度方向做匀速直线运动，要打在 M 点必须满足什么方向条件","why":"撤去磁场后粒子不受力，做匀速直线运动；要经过 M，关闭时刻的速度方向必须沿关闭点到 M 的连线","do":"过 M 作轨迹圆的切线，切点即关闭磁场的位置 P，判断此时速度沿 PM 方向","expr":"","cues":["撤磁场后走直线","速度指向M","切线方向就是速度"],"concepts":["匀速直线运动","切线方向","临界条件"]},{"title":"圆心角对应运动时间","type":"关系建立","judge":"粒子在磁场中走过的圆心角是多少，时间与周期如何对应","why":"粒子在磁场中做匀速圆周运动，转过圆心角 α 所用时间为 α/2π 个周期，周期只由比荷和磁感应强度决定","do":"由几何关系求出从发射到 P 点转过的圆心角，再用周期公式换算成时间","expr":"t=\\frac{\\alpha}{2\\pi}T,\\quad T=\\frac{2\\pi m}{qB}","cues":["先求圆心角","周期看比荷","时间按比例分"],"concepts":["周期公式","圆心角","匀速圆周运动"]}],"488":[{"title":"传送带上是否已共速","type":"前提判断","judge":"要判断 A 在传送带上是否已经加速到与传送带同速，从而决定用匀加速公式还是先加速后匀速","why":"题设明确'A 还未与传送带达到相同速度时就离开'，说明全程滑动摩擦、全程匀加速，若误判为共速则速度被传送带速度限制","do":"比较由 v²=2μg d 得到的离开速度与传送带速度，确认题设条件自洽，直接取全程匀加速","expr":"v_1^2=2\\mu g d","cues":["还没共速","一直加速","不用管传送带速度"],"concepts":["滑动摩擦力","匀加速直线运动"]},{"title":"碰前 B 速度的方向与大小","type":"关系建立","judge":"要判断碰前 B 的速度取 +v1/2 还是 -v1/2，即 B 与 A 同向运动","why":"题设说 B 向右运动，A 从 N 进入水平面也向右，同向碰撞才能用一维同向弹性碰撞公式，若取反向则动量方程符号全错","do":"以向右为正，写碰前动量 mv1+M(v1/2)，并据此列动量与能量方程","expr":"mv_1+M\\frac{v_1}{2}=mv_1'+Mv_2'","cues":["都向右","同向碰撞","取向右为正"],"concepts":["动量守恒","一维碰撞"]},{"title":"弹性碰撞用相对速度式","type":"模型选择","judge":"要判断弹性碰撞除动量、能量守恒外还可直接用'碰前相对速度等于碰后相对速度大小'这一等价关系，避免解二次方程","why":"弹性碰撞恢复系数为 1，相对速度大小不变方向相反，这是动量与动能守恒联立后的等价简化，用它可把二次方程组降为线性","do":"写出 v1-v1/2=v2'-v1'，与动量守恒式联立解出 v1'、v2'","expr":"v_1-\\frac{v_1}{2}=v_2'-v_1'","cues":["弹性碰撞","相对速度不变","别解二次方程"],"concepts":["弹性碰撞","恢复系数"]},{"title":"碰后滑行距离与速度平方","type":"关系建立","judge":"要判断碰后 A、B 在粗糙地面上的滑行距离只由碰后速度决定，且 s=v²/(2μg)，从而把'相距 d'翻译成速度平方差","why":"地面摩擦做负功使动能归零，由动能定理 s=v²/(2μg)，与质量无关，这是把几何距离条件转化为速度条件的桥梁","do":"对 A、B 分别用动能定理得 s_A、s_B，再令 s_B-s_A=d 并与 v1²=2μgd 联立","expr":"s=\\frac{v^2}{2\\mu g},\\quad s_B-s_A=d","cues":["滑行距离","动能定理","距离差"],"concepts":["动能定理","摩擦力做功"]},{"title":"碰后不二次碰撞的临界","type":"临界条件","judge":"要判断碰后 A 不能追上 B（或 B 不能落后于 A）对应 v_A≤v_B，由此给出 n 的上界","why":"碰后两者都在 O 点进入同一粗糙面，若 A 速度大于 B 速度会再次追上发生二次碰撞，与题设'碰后各自停下'矛盾","do":"由动量相同得 v_A=n v_B，代入 v_A≤v_B 得 n≤1","expr":"v_A\\le v_B\\ \\Rightarrow\\ n\\le 1","cues":["不能追上","二次碰撞","速度不能反超"],"concepts":["追及临界","碰撞约束"]},{"title":"碰后动能不增定下界","type":"临界条件","judge":"要判断碰撞过程动能不增（非爆炸、非超弹性）给出 n 的下界，并注意 n=1/3 取不到","why":"真实碰撞中碰后总动能不大于碰前总动能，这是除动量守恒外的第二个物理约束，缺它 n 只有上界没有下界","do":"把 v_A、v_B 表达式代入动能不等式，化简得 n>1/3，再与 n≤1 合并","expr":"\\tfrac12 mv_1^2+\\tfrac12 nmv_{B0}^2\\ge\\tfrac12 mv_A^2+\\tfrac12 nmv_B^2","cues":["动能不增","碰撞不能凭空生能","下界靠能量"],"concepts":["碰撞能量约束","动量守恒"]}],"489":[{"title":"选定环绕模型","type":"模型选择","judge":"把轨道器的匀速圆周运动看成万有引力提供向心力，还是当成别的运动模型","why":"题设明确轨道器绕火星做匀速圆周运动，只有万有引力充当向心力才能把 r、T 与火星质量联系起来","do":"写出万有引力等于向心力的等式，并把向心力用周期形式表示","expr":"G\\frac{Mm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["万有引力提供向心力","匀速圆周运动","用周期形式"],"concepts":["万有引力定律","向心力","匀速圆周运动"]},{"title":"分清已知与未知量","type":"前提判断","judge":"题给的 r、T、G 中，哪个是中心天体半径、哪个是轨道半径，能否直接得到火星自身尺寸","why":"r 是轨道器到火星中心的距离，不是火星半径；火星体积、逃逸速度都要用火星自身半径，而题中未给","do":"列出已知量 r、T、G，标出火星半径 R 为未知，比较 R 与 r 是否可互推","expr":"","cues":["轨道半径不是火星半径","火星半径未知","还差一个半径"],"concepts":["轨道半径","天体半径"]},{"title":"反解中心天体质量","type":"关系建立","judge":"由含 M、r、T 的向心力方程能否唯一解出火星质量","why":"方程中除 M 外其余量 r、T、G 均已知，M 是唯一未知，可解","do":"把向心力方程变形，将 M 移到等号一边","expr":"M=\\frac{4\\pi^{2}r^{3}}{GT^{2}}","cues":["只有质量能求","把M解出来","r和T都已知"],"concepts":["中心天体质量","万有引力提供向心力"]},{"title":"判断体积逃逸速度可否求","type":"结论整理","judge":"求火星体积和逃逸速度是否还需要题中未给的量","why":"体积需火星半径 R，逃逸速度 v=√(2GM/R) 也需 R，仅知 M 和轨道半径 r 不够","do":"写出体积与逃逸速度表达式，检查其中是否出现未给的 R","expr":"V=\\frac{4}{3}\\pi R^{3},\\quad v=\\sqrt{\\frac{2GM}{R}}","cues":["体积要火星半径","逃逸速度也要半径","缺R求不出"],"concepts":["球体体积","逃逸速度"]},{"title":"排除自转周期","type":"前提判断","judge":"环绕体的公转周期能否给出中心天体的自转周期","why":"自转周期取决于火星自身转动，与轨道器的环绕周期无任何动力学联系，题给数据中不含自转信息","do":"确认方程中只出现环绕周期 T，不出现自转周期，判定其不可求","expr":"","cues":["公转不是自转","自转周期没给信息","两者无关"],"concepts":["自转周期","公转周期"]}],"490":[{"title":"钢管受力全图","type":"模型选择","judge":"钢管受哪几个力、各沿什么方向","why":"钢管静止，必须先明确重力（竖直向下）、绳拉力（竖直向上）、地面支持力（竖直向上）与可能的地面摩擦力（水平方向）","do":"画出钢管受力图，标出重力、绳拉力、支持力、摩擦力四个力的方向","expr":"","cues":["先画受力图","绳子是竖直的","地面支持力向上"],"concepts":["受力分析","重力","弹力"]},{"title":"水平方向无外力","type":"前提判断","judge":"除地面摩擦力外，钢管在水平方向是否还有别的力","why":"绳拉力竖直、重力竖直、支持力竖直，三者均无水平分量，水平方向只剩摩擦力这一个可能的力","do":"把各力分解到水平方向，检查除摩擦力外是否还有水平分力","expr":"","cues":["绳子竖直没有水平分力","支持力垂直地面","水平方向只剩摩擦力"],"concepts":["力的分解","正交分解"]},{"title":"静止必水平平衡","type":"关系建立","judge":"静止的钢管在水平方向合力必须满足什么","why":"由平衡条件，静止物体所受合力为零，水平方向合力也必须为零","do":"对水平方向列平衡方程，令水平合力等于零","expr":"\\sum F_x = 0","cues":["静止就是合力为零","水平方向也要平衡","合力必须为零"],"concepts":["共点力平衡","平衡条件"]},{"title":"摩擦力只能为零","type":"结论整理","judge":"水平方向唯一可能的力若不为零，合力能否为零","why":"水平方向只有摩擦力一个力，若它不为零则水平合力不为零，与静止矛盾，故摩擦力必为零","do":"由水平合力为零反推摩擦力大小，与动摩擦因数、夹角无关","expr":"f = 0","cues":["只有一个力不可能平衡","摩擦力只能是零","跟动摩擦因数无关"],"concepts":["静摩擦力","平衡条件"]}],"491":[{"title":"加速获得动能的规律","type":"关系建立","judge":"电子经电压加速后，动能与加速电压是什么关系","why":"电场力做功等于动能增量，初速为零，故 eU 等于二分之一 mv 平方，这是把电压与速度连起来的唯一桥梁","do":"对静止电子用动能定理，写出 eU 与 mv²/2 的等式","expr":"eU=\\frac{1}{2}mv^{2}","cues":["用动能定理","初速为零","电场做功"],"concepts":["动能定理","电场力做功"]},{"title":"动量与波长的联系","type":"关系建立","judge":"德布罗意波长该用速度还是动量表示","why":"德布罗意关系是波长等于普朗克常量除以动量，必须先把速度换成动量才能与电压挂钩","do":"写出 p=mv 与 λ=h/p，把 λ 表示成含 p 的式子","expr":"\\lambda=\\frac{h}{p},\\quad p=mv","cues":["用动量表示","波长看动量","先求动量"],"concepts":["德布罗意波长","动量"]},{"title":"消去速度得波长表达式","type":"数学处理","judge":"如何把速度从两个关系式中消掉，得到波长随电压变化的函数","why":"题目只给电压比，必须得到 λ 与 U 的显式依赖关系才能比较两次加速","do":"由 p=√(2meU) 代入波长式，整理出 λ 正比于 1/√U","expr":"\\lambda=\\frac{h}{\\sqrt{2meU}}","cues":["消去速度","合成一个式子","波长随电压变"],"concepts":["德布罗意波长","动能定理"]},{"title":"电压比与波长比","type":"数学处理","judge":"电压变为原来的多少倍，波长应变为原来的多少倍","why":"λ 与 √U 成反比，电压比 100:1 对应波长比 1:10，这是本题唯一需要算的数值关系","do":"取 U' 比 U 等于 100 比 1，代入 λ 正比于 1/√U 求 λ' 与 λ 的比值","expr":"\\frac{\\lambda'}{\\lambda}=\\sqrt{\\frac{U}{U'}}=\\frac{1}{10}","cues":["电压变一百倍","波长变十分之一","开平方反比"],"concepts":["反比关系","平方根"]},{"title":"排除相对论修正","type":"近似条件","judge":"10 kV 加速下电子速度是否已大到必须用相对论动量","why":"题设明确不考虑相对论效应，若擅自引入相对论修正会得到偏离选项的结果","do":"确认题目给定非相对论条件，全程使用经典动量 p=mv","expr":"","cues":["题目说不考虑","用经典公式","别加相对论"],"concepts":["非相对论近似"]}],"492":[{"title":"判定感应电流方向","type":"关系建立","judge":"铜环中感应电流的方向与钢制线圈中电流方向是相同还是相反","why":"线圈电流从零迅速增大，穿过铜环的磁通量急剧增加，由楞次定律，感应电流的磁场要阻碍原磁通量的增加，故感应电流方向与原电流方向相反","do":"先确定线圈电流产生的磁场方向，再看铜环内磁通量是增是减，用楞次定律定出感应电流的磁场方向，反推感应电流方向","expr":"","cues":["磁通量在增大","阻碍增加","方向相反"],"concepts":["楞次定律","磁通量","感应电流方向"]},{"title":"判断感应电流大小","type":"前提判断","judge":"铜环中感应电流是远小于、约等于还是远大于线圈电流","why":"铜环与线圈同轴且紧邻，磁通量变化率由线圈电流的急剧上升决定，铜环电阻很小，感应电动势产生的电流可与线圈电流同量级，解析取二者大小几乎相等","do":"比较铜环回路的感应电动势与电阻，判断感应电流与线圈电流的数量级关系","expr":"","cues":["电阻很小","电流差不多大","不能忽略"],"concepts":["法拉第电磁感应定律","感应电动势","电阻"]},{"title":"由电流相互作用定压缩方向","type":"模型选择","judge":"两股反向电流之间的安培力使铜环向内压缩还是向外扩张","why":"反向电流相互排斥，铜环各处受到的安培力沿径向指向环心，才使铜环向内压缩、磁感线被浓缩","do":"把铜环看成载流回路，取一小段电流元，用左手定则判断它在螺线管磁场中受力的径向指向","expr":"","cues":["反向电流相斥","安培力指向圆心","向内压缩"],"concepts":["安培力","电流元","左手定则"]}],"493":[{"title":"安培力只算一条边","type":"模型选择","judge":"线框进出磁场时，受安培力的有效长度取哪一段","why":"线框上下两边与磁场边界平行、所在处磁场方向与边平行，不受安培力；只有切割磁感线的竖直边受力，长度恰为 L","do":"对甲、乙分别写出刚进入时的感应电动势和电流，再乘 BL 得安培力","expr":"F=BIL,\\quad I=\\frac{BLv}{R}","cues":["只看竖直边","上下边不受力","有效长度是宽"],"concepts":["安培力","动生电动势","有效长度"]},{"title":"两框电阻不同致力不同","type":"关系建立","judge":"同一速度下甲、乙所受安培力之比由什么决定","why":"电动势相同（同 B、同 L、同 v0），电流与电阻成反比，安培力也就与电阻成反比，不能默认两框受力相同","do":"用 R 与 2R 分别算 I 和 F，比较 F甲/F乙","expr":"\\frac{F_甲}{F_乙}=\\frac{R_乙}{R_甲}=2","cues":["电阻大的电流小","力跟电阻反比","别当成一样"],"concepts":["欧姆定律","安培力"]},{"title":"用动量定理求末速度","type":"关系建立","judge":"求线框完全出磁场后的速度，该用哪个守恒/定理","why":"安培力随速度变化，是变力，不能直接用牛顿定律；但安培力的冲量可由通过的总电荷量算出，而总电荷量只由磁通量变化和电阻决定","do":"对甲、乙分别列动量定理，用 q=ΔΦ/R 代入，ΔΦ 取整个线框穿过磁场过程的磁通量变化","expr":"-BqL=mv-mv_0,\\quad q=\\frac{\\Delta\\Phi}{R}=\\frac{B\\cdot 4L^2}{R}","cues":["变力用冲量","电量看磁通量","q只跟电阻有关"],"concepts":["动量定理","电荷量","磁通量变化"]},{"title":"判断甲是否恰好停下","type":"临界条件","judge":"甲完全出磁场时速度是否恰好减为零，还是中途就已停下","why":"由动量定理算出的甲末速度恰为 0，说明它刚好能完全穿出；若算得负值则说明未出磁场就停了，后续热量算法要改","do":"把 v0 的给定值代入甲的动量定理式，解出 v1 并与 0 比较","expr":"v_1=v_0-\\frac{4B^2L^3}{mR}=0","cues":["先算末速度","看是不是刚好为零","为零才算完全出"],"concepts":["临界状态","动量定理"]},{"title":"热量用能量守恒算","type":"关系建立","judge":"焦耳热该用哪个量守恒来求，初末动能各取什么","why":"水平面光滑、无其他力做功，减少的动能全部转化为焦耳热；甲末动能为零，乙末速度为 v0/2，不能想当然认为两者热量相同","do":"分别写 Q=½mv0²−½mv末²，再求比值","expr":"Q_1=\\frac12 mv_0^2,\\quad Q_2=\\frac12 mv_0^2-\\frac12 m\\left(\\frac{v_0}{2}\\right)^2","cues":["热量等于动能损失","甲全损失","乙还剩一部分"],"concepts":["能量守恒","焦耳热"]},{"title":"进出磁场电流方向相反","type":"结论整理","judge":"线框进入与离开磁场时感应电流方向是否相同","why":"进入时磁通量增加、离开时磁通量减少，楞次定律给出两种相反的感应电流方向，同一过程方向不变的说法不成立","do":"分别对进入段和离开段判断磁通量增减，定出电流绕向","expr":"","cues":["进和出方向相反","磁通量一增一减","不能全程一个方向"],"concepts":["楞次定律","感应电流方向"]}],"494":[{"title":"复合光能否干涉","type":"前提判断","judge":"两束不同波长的光各自与自身干涉，还是彼此之间发生干涉","why":"干涉的稳定条件是两列光频率相同、相位差恒定，蓝光和红光频率不同，彼此不能形成稳定干涉，但各自独立成条纹","do":"明确屏上蓝、红两套条纹各自独立叠加，不是两色光互相干涉","expr":"","cues":["两色光频率不同","各自成条纹","不能互相干涉"],"concepts":["相干条件","频率","光的干涉"]},{"title":"条纹间距与波长关系","type":"关系建立","judge":"同一装置下条纹间距由哪个量决定、蓝红谁大谁小","why":"双缝干涉相邻亮纹间距由装置参数和波长决定，波长越短间距越小","do":"写出条纹间距公式，比较蓝光与红光的波长大小得出间距大小关系","expr":"$\\Delta x=\\frac{L}{d}\\lambda$","cues":["间距看波长","蓝光波长小","蓝纹更密"],"concepts":["双缝干涉","条纹间距","波长"]},{"title":"代入装置参数算间距","type":"数学处理","judge":"把 L、d、λ 统一成国际单位后代入公式求两种光的间距","why":"题给 d 为毫米、L 为毫米、λ 为纳米，不统一单位会算错数量级","do":"将 d、L、λ 换算为米，分别代入公式求蓝、红条纹间距","expr":"$\\Delta x_1=\\frac{0.5}{5\\times10^{-4}}\\times4.4\\times10^{-7}$，$\\Delta x_2=\\frac{0.5}{5\\times10^{-4}}\\times6.6\\times10^{-7}$","cues":["先换单位","毫米变米","纳米变米"],"concepts":["单位换算","条纹间距"]},{"title":"亮纹重合条件","type":"关系建立","judge":"两套条纹的亮纹中心在屏上重合需要满足什么整数关系","why":"亮纹位置是间距的整数倍，重合即同一位置同时是两种光的整数级亮纹","do":"令蓝光第 m 级与红光第 n 级亮纹位置相等，建立整数方程","expr":"$m\\Delta x_1=n\\Delta x_2$","cues":["整数级重合","找公倍数","级次配比"],"concepts":["亮纹条件","光程差"]},{"title":"找最小重合位置","type":"数学处理","judge":"满足整数方程的最小非零位置对应哪组最小整数 m、n","why":"间距之比为 2:3，最小整数解为 m=3、n=2，对应位置才是最近的重合亮纹","do":"由间距比化为整数比，取最小整数解，算出重合位置并与选项给出的距离比较","expr":"$\\frac{\\Delta x_1}{\\Delta x_2}=\\frac{2}{3}\\Rightarrow m:n=3:2$，$x=3\\Delta x_1=2\\Delta x_2$","cues":["间距比二比三","最小整数解","三倍蓝纹"],"concepts":["最小公倍数","亮纹重合"]}],"495":[{"title":"绳长与伸长量的几何关系","type":"几何关系","judge":"弹性绳的伸长量是否等于滑轮到滑块的距离（因原长恰为 OQ）","why":"题设明确原长为 OQ，绳跨过 Q 后只有 Q 到滑块这一段被拉长，故伸长量就是 Q 到滑块的距离","do":"设滑块沿杆下滑 x 后与 Q 的距离为 l，写出伸长量 x伸 与 PQ、x 的勾股关系","expr":"x_{伸}=\\sqrt{PQ^{2}+x^{2}}","cues":["原长就是OQ","伸长量是Q到滑块","用勾股定理"],"concepts":["胡克定律","几何关系"]},{"title":"垂直杆方向弹力恒定","type":"关系建立","judge":"杆对滑块的弹力是否随滑块位置变化","why":"绳拉力沿垂直杆方向的分量与伸长量成正比，而伸长量乘以该方向余弦恰为定值 PQ，故垂直杆方向合力恒为零","do":"在垂直杆方向列平衡方程，代入 F=kx伸 与 x伸cosθ=PQ，消去 θ 求 F_N","expr":"F_{N}=k\\cdot PQ-mg\\cos 53^\\circ","cues":["垂直杆方向平衡","拉力分量抵消重力分量","弹力是定值"],"concepts":["受力分析","正交分解","胡克定律"]},{"title":"摩擦力大小恒定","type":"前提判断","judge":"滑动摩擦力是否全程为同一数值","why":"正压力恒定且动摩擦因数不变，故摩擦力大小不变，只方向随运动方向改变","do":"由 f=μF_N 算出摩擦力大小，供后续能量与冲量使用","expr":"f=\\mu F_{N}","cues":["正压力不变","摩擦力大小不变","方向会变"],"concepts":["滑动摩擦力"]},{"title":"判断能否停在最低点","type":"临界条件","judge":"滑块第一次速度为零时，沿杆向上的合力是否超过最大静摩擦力所需条件","why":"最大静摩擦力等于滑动摩擦力，只有沿杆的绳分力与重力分力的差值不超过 f 时滑块才能静止","do":"用能量守恒求第一次停止的位移 x，再比较绳沿杆分力与 mg sin53°±f 的大小","expr":"k\\sqrt{PQ^{2}+x^{2}}\\cdot\\frac{x}{\\sqrt{PQ^{2}+x^{2}}}\\gtrless mg\\sin 53^\\circ\\pm f","cues":["先算第一次停下位置","比较绳分力和重力分力","看会不会回弹"],"concepts":["能量守恒","临界条件","最大静摩擦力"]},{"title":"往返后最终静止位置","type":"数学处理","judge":"滑块上滑到速度再次为零时能否保持静止，从而确定总位移","why":"每次停止都要重新检验静摩擦条件，直到沿杆合力落在摩擦锥内才真正静止","do":"对下滑段与上滑段分别用能量守恒求位移，再检验第二次停止点的受力","expr":"\\tfrac12 k[PQ^{2}+x^{2}]-\\tfrac12 k[PQ^{2}+(x-x_1)^{2}]=mg\\sin 53^\\circ x_1+fx_1","cues":["上滑也要算能量","再检验一次静止","位移是净位移"],"concepts":["动能定理","能量守恒","往复运动"]},{"title":"摩擦生热用总路程","type":"结论整理","judge":"克服摩擦力做的功应按总路程还是净位移计算","why":"摩擦力始终做负功，其功等于 f 乘以实际经过的路程，而非首末位置之差","do":"把下滑路程与上滑路程相加，再乘 f 得克服摩擦力做功","expr":"W_{f}=f\\,(x+x_1)","cues":["摩擦力看路程","不是净位移","来回都要算"],"concepts":["摩擦生热"]}],"496":[{"title":"判断木板是否需垫高","type":"实验操作","judge":"木板应保持水平还是一端垫高，取决于本实验是否需要且能够补偿摩擦阻力","why":"本实验用槽码重力提供合外力，必须让绳的拉力等于小车所受合外力，因此需把木板一端垫高，用重力沿斜面的分量平衡摩擦阻力","do":"分析小车在无绳拉力时能否在倾斜木板上匀速下滑，据此确定木板一端垫高","expr":"","cues":["要平衡摩擦力","垫高木板","无拉力时能匀速"],"concepts":["平衡摩擦力","牛顿第二定律"]},{"title":"化曲为直的判据选择","type":"数学处理","judge":"要判断 a 与 m 是否成反比，应把哪个量作横轴、哪个量作纵轴，使预期图线成为直线","why":"反比关系 a∝1/m 在 a-m 图上为双曲线，难以直观判断；只有把关系式变形为线性形式，才能用直线与否作判据","do":"把 a=k/m 变形为 a=k·(1/m) 或 am=k，检查各选项的坐标组合能否使预期图线为直线","expr":"a=\\frac{k}{m}\\ \\Leftrightarrow\\ a=k\\cdot\\frac{1}{m}\\ \\Leftrightarrow\\ am=k","cues":["化曲为直","看是不是直线","取倒数作横轴"],"concepts":["反比关系","线性化","图像法"]},{"title":"排除非线性坐标组合","type":"前提判断","judge":"a-m²、a²-m 这类组合在 a 与 m 成反比时预期图线是否为直线","why":"若 a=k/m，则 a 与 m² 成反比、a² 与 m² 成反比，画成 a-m² 或 a²-m 仍是曲线，无法直观判断","do":"把 a=k/m 代入各选项的纵轴量，看纵轴量与横轴量是否成正比","expr":"a=\\frac{k}{m}\\Rightarrow a\\propto\\frac{1}{m^2}\\ (\\text{对 }m^2),\\ a^2\\propto\\frac{1}{m^2}\\ (\\text{对 }m)","cues":["还是曲线","看不出直线","不成正比"],"concepts":["反比关系","图像线性化"]},{"title":"恒质量与变质量的操作取舍","type":"模型选择","judge":"改变拉力时，是保持小车质量不变只加槽码，还是把车上槽码移到盘上使系统总质量不变","why":"绳拉力实为 F=Mmg/(M+m)，只有 m≪M 时才近似等于 mg；甲法使 m 不断增大而 M 不变，近似条件逐渐破坏；乙法总质量 M+m 不变，系统误差更小","do":"写出两种操作下绳拉力的表达式，比较随槽码质量增大时 F 与 mg 的偏差变化","expr":"F=\\frac{M}{M+m}mg","cues":["总质量不变","槽码移来移去","m远小于M"],"concepts":["系统误差","隔离法求拉力","近似条件"]},{"title":"绳拉力与槽码重力的偏差","type":"误差分析","judge":"把槽码重力当作绳拉力会带来多大系统误差，哪种操作使偏差更小","why":"小车与槽码一起加速，槽码处于失重状态，绳拉力小于槽码重力；m 相对 M 越大，偏差越大","do":"比较甲、乙两法在改变拉力过程中 m/(M+m) 的变化趋势，判断哪种方法偏差更小","expr":"mg-F=ma>0\\Rightarrow F<mg","cues":["槽码也加速","拉力小于重力","偏差越来越大"],"concepts":["失重","系统误差","牛顿第二定律"]}],"497":[{"title":"换挡后必须重新调零","type":"实验操作","judge":"换到新的欧姆挡倍率后，是否必须重新短接表笔并调零，以及调零与换挡的先后顺序","why":"欧姆表内部电池与表头串联，换挡改变了内部串联电阻，同一指针位置对应的中值电阻变了，不重新调零读数全部作废","do":"先判断待测阻值落在哪一挡，再确定操作顺序：换挡→短接表笔→调零旋钮使指针指欧姆零","expr":"","cues":["换挡要重新调零","先换挡再短接","短接后调零"],"concepts":["欧姆表","欧姆调零","中值电阻"]},{"title":"估测阻值选倍率","type":"前提判断","judge":"约 15 kΩ 的电阻应选哪一挡倍率，使指针落在刻度盘中值附近","why":"欧姆表刻度不均匀，指针偏转过大或过小读数误差都大，应使指针靠近中值附近","do":"比较 15 kΩ 与各挡中值电阻，判断 ×100 挡指针过于偏左、×1k 挡指针落在中部","expr":"","cues":["指针要指中间","×1k才合适","×100偏得太多"],"concepts":["欧姆表倍率","刻度不均匀"]},{"title":"改装电压表串还是并","type":"模型选择","judge":"把满偏电流很小的表头改成大量程电压表，应串联还是并联电阻","why":"表头满偏电压 U_g=I_gR_g 远小于 2 V，需串联大电阻分压，并联只会分流、不能提高量程","do":"由 U_g=I_gR_g 算出表头满偏电压，与 2 V 比较，确定串联分压","expr":"U_g=I_gR_g","cues":["串联分压","并联是改电流表","表头耐压太小"],"concepts":["电表改装","串联分压"]},{"title":"串联电阻的分压关系","type":"关系建立","judge":"串联电阻应满足什么方程，用满偏电流还是量程电流","why":"改装后满偏时表头与串联电阻中电流同为 I_g，总电压为量程 U","do":"列 U=I_g(R_g+R)，解出 R=U/I_g−R_g","expr":"R=\\frac{U}{I_g}-R_g","cues":["满偏时一起满偏","总电压等于量程","用满偏电流算"],"concepts":["欧姆定律","串联电路"]},{"title":"零电压段定位电容器","type":"结论整理","judge":"哪些接线柱间电压为零，说明该段是电阻还是电容器","why":"直流稳态下电容器相当于断路，与之串联的电阻无电流无压降；而纯电阻段有电流必有压降，故零电压段对应电容器所在支路","do":"找出表中 U=0 的两组接线柱，判断它们共同构成含电容器的支路","expr":"","cues":["零电压是电容","电容隔直流","没电流就没压降"],"concepts":["电容器隔直流","稳态电路"]},{"title":"最大电压段定位电源","type":"结论整理","judge":"哪两个接线柱间电压最大，是否就是电源所在位置","why":"外电路各段电压之和等于电源电动势，电源两端（外电路断开处）电压即电动势，为各测量值中最大","do":"比较表中六个电压值，取最大者对应的接线柱作为电源位置","expr":"","cues":["电压最大是电源","电源电压最高","电动势最大"],"concepts":["电动势","闭合电路欧姆定律"]},{"title":"由分压比定电阻大小","type":"关系建立","judge":"剩余两段电阻如何按电压大小与 R_A>R_B 对应","why":"串联电路中电压与电阻成正比，电压大的那段电阻大，结合题设 R_A>R_B 即可定段","do":"比较 1 和 3 与 2 和 4 的电压，电压大者对应 R_A","expr":"U\\propto R","cues":["电压大电阻大","串联分压成正比","比一比电压"],"concepts":["串联分压","电阻大小比较"]}],"498":[{"title":"选理想气体状态方程","type":"模型选择","judge":"两个状态之间用哪个方程把 p、V、T 联系起来","why":"气体视为理想气体且质量不变，三个参量同时变化，只能用理想气体状态方程而非单个气体定律","do":"对状态1和状态2写出状态方程，把 T1、V1、p1、T2、V2 代入求 p2","expr":"\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}","cues":["质量不变","三个量都变","用状态方程"],"concepts":["理想气体","状态方程"]},{"title":"p-V图面积算功","type":"图像读取","judge":"p-V 图线下面积代表什么、该过程气体对外做功还是外界对气体做功","why":"p-V 图线与 V 轴所围面积等于气体对外做的功，体积增大说明气体膨胀对外做功","do":"取图线为直线，用梯形面积公式算图线下面积，得气体对外做功大小","expr":"W_{\\text{对外}}=\\frac{p_1+p_2}{2}(V_2-V_1)","cues":["面积就是功","梯形面积","体积变大"],"concepts":["p-V图像"]},{"title":"功的正负号约定","type":"前提判断","judge":"代入热力学第一定律时 W 取正还是取负","why":"ΔU=Q+W 中 W 是外界对气体做的功，气体膨胀对外做功则 W 为负值","do":"把算出的对外做功取负号作为 W 代入第一定律","expr":"W=-\\frac{p_1+p_2}{2}(V_2-V_1)","cues":["对外做功取负","外界对气体做功","符号别弄反"],"concepts":["热力学第一定律","正负号约定"]},{"title":"吸热Q取正","type":"前提判断","judge":"Q 在 ΔU=Q+W 中取正还是取负","why":"题设明确气体吸收热量，按符号约定吸热为正","do":"把 Q=7.608×10⁴ J 以正值代入第一定律求 ΔU","expr":"\\Delta U=Q+W","cues":["吸热为正","Q直接代正","热量是吸收的"],"concepts":["热力学第一定律","吸放热"]}],"499":[{"title":"最危险电子的方向","type":"临界条件","judge":"要判断在 B0 下哪一类发射方向的电子最先（最容易）打到筒壁，从而由'恰好没有电子落到筒壁'确定临界轨迹","why":"电子速度有平行轴线的分量时，该分量不受洛伦兹力、不改变横截面内的回旋半径，只会让电子沿轴向平移，因此垂直轴线射出的电子在横截面内回旋半径最大、最容易碰壁","do":"把 v0 分解为垂直轴线分量与平行轴线分量，比较不同发射方向对应的横截面回旋半径，取垂直轴线射出者为临界情形","expr":"v_\\perp=v_0\\sin\\theta,\\quad r=\\frac{mv_\\perp}{eB_0}","cues":["垂直射出的最容易碰壁","平行分量不影响半径","取垂直方向"],"concepts":["洛伦兹力","速度分解","回旋半径"]},{"title":"相切定半径几何关系","type":"几何关系","judge":"要判断'恰好不落到筒壁'对应回旋圆与筒壁截面圆的哪种几何位置关系，并由此定出回旋半径与筒半径 R 的关系","why":"电子源在轴线上，回旋圆必过轴线上的 O 点，圆与筒壁截面圆内切时半径最大而不相交，这正是临界条件","do":"画横截面图，令过 O 点的回旋圆与半径 R 的筒壁圆内切，由圆心距关系读出回旋半径","expr":"r_0=\\frac{R}{2}","cues":["轨迹与筒壁相切","半径是筒半径一半","圆心在中间"],"concepts":["几何相切","临界轨迹"]},{"title":"洛伦兹力提供向心力","type":"关系建立","judge":"要判断用哪个动力学方程把临界半径、磁感应强度与比荷联系起来","why":"电子在匀强磁场中只受洛伦兹力，做匀速圆周运动，向心力完全由洛伦兹力提供","do":"对临界电子列牛顿第二定律方程，代入 r0=R/2 解出 e/m","expr":"eB_0v_0=\\frac{mv_0^2}{R/2}\\Rightarrow\\frac{e}{m}=\\frac{2v_0}{B_0R}","cues":["洛伦兹力当向心力","列圆周运动方程","消去v0"],"concepts":["牛顿第二定律","洛伦兹力","比荷"]},{"title":"螺旋运动分解","type":"模型选择","judge":"要判断 B 变为 B0/2 后电子的运动是'横截面内匀速圆周+沿轴匀速直线'的螺旋运动，并明确两方向运动相互独立","why":"速度的平行轴线分量与磁场平行，不受洛伦兹力；垂直分量在横截面内做圆周运动，两分运动独立可分别处理","do":"把任意发射速度分解为 v_x（垂直轴线）与 v_y（平行轴线），分别写圆周运动与匀速直线运动的规律","expr":"r=\\frac{mv_x}{e(B_0/2)},\\quad y=v_yt","cues":["螺旋线运动","两个方向分开算","平行分量不受力"],"concepts":["运动的合成与分解","螺旋运动"]},{"title":"最远落点仍取相切","type":"临界条件","judge":"要判断 B 减半后打到筒壁'最远'的电子，其横截面内轨迹仍须与筒壁相切，从而回旋半径仍为 R/2，反推出该电子的 v_x","why":"落点沿轴向的距离由飞行时间与 v_y 决定，而飞行时间由横截面内从 O 到相切点的半周期决定；相切是电子能到达筒壁的极限横向条件，对应最长飞行时间","do":"令 r=R/2 代入含 B0/2 的向心力方程求 v_x，再由速度合成求 v_y，用半周期求飞行时间 t 与轴向距离 y","expr":"e\\frac{B_0}{2}v_x=\\frac{mv_x^2}{R/2}\\Rightarrow v_x=\\frac{v_0}{2},\\quad v_y=\\frac{\\sqrt3}{2}v_0,\\quad t=\\frac{T}{2}=\\frac{\\pi R}{v_0},\\quad y=\\frac{\\sqrt3\\pi}{2}R","cues":["最远点还是相切","半径不变","半个周期到壁"],"concepts":["临界条件","周期公式","速度合成"]},{"title":"落点区域对称求和","type":"结论整理","judge":"要判断筒壁上被击中区域是绕轴线的一圈带状面还是上下两段，以及面积如何由轴向长度与周长组合","why":"电子可向各方向发射，绕轴线旋转对称，轴向落点分布在 O 点两侧对称的两段，每段是长为 y、周长 2πR 的圆柱侧面","do":"先算单侧一段的侧面积 2πRy，再由上下对称性乘 2 得总面积","expr":"S=2\\times2\\pi Ry=2\\sqrt3\\pi^2R^2","cues":["上下对称","一圈带状","侧面积乘二"],"concepts":["旋转对称","圆柱侧面积"]}],"500":[{"title":"共速瞬间的动量守恒","type":"模型选择","judge":"两粒子共速前系统所受合外力是否为零，能否用动量守恒求共速速度","why":"两粒子间只有相互作用的库仑力，属内力，系统合外力为零，动量守恒成立","do":"对A、B组成的系统列初末动量相等的方程，初态只有A以v0运动，末态两者同速","expr":"mv_{0}=(m+4m)v_{1}","cues":["取两粒子整体","内力不影响总动量","共速时用动量守恒"],"concepts":["动量守恒","内力","共速"]},{"title":"共速时电势能反比求间距","type":"关系建立","judge":"共速时刻的电势能能否由能量守恒求出，再由反比关系定出此时间距","why":"库仑力做功使动能与电势能相互转化，系统总能量守恒；题设电势能与距离成反比","do":"用初态总能量减去共速时总动能得共速时电势能，再按电势能与距离反比换算出共速间距","expr":"E_{p}'=\\frac{1}{2}mv_{0}^{2}+\\frac{1}{25}mv_{0}^{2}-\\frac{1}{2}\\cdot5mv_{1}^{2},\\quad l'=\\frac{E_{p0}}{E_{p}'}l_{0}","cues":["先算共速时的电势能","电势能和距离成反比","能量守恒求间距"],"concepts":["能量守恒","电势能","反比关系"]},{"title":"质心式位移关系","type":"关系建立","judge":"t1内动量守恒能否转化为两粒子位移的线性关系，并与几何间距关系联立","why":"共速前系统动量守恒，对时间累积得mv0t1=mxA+4mxB，把速度关系转成位移关系","do":"对动量守恒式两边乘t1得位移关系，再结合B比A多走的距离等于间距变化量列几何方程，联立解xB","expr":"mv_{0}t_{1}=mx_{A}+4mx_{B},\\quad x_{B}+l_{0}=x_{A}+l'","cues":["动量守恒乘时间","位移和间距挂钩","B多走了间距差"],"concepts":["动量守恒的位移形式","位移几何关系"]},{"title":"恒力做功只看位移","type":"前提判断","judge":"恒力对系统做的功是否只由B的位移决定，能否用全过程动能定理求F","why":"恒力只作用在B上且方向与B运动方向相同，做功为F乘B的位移；题设末态间距恢复l0，B相对A的位移即l0","do":"对全过程列动能定理，初态只有A动能，末态只有B动能，恒力做功等于动能增量","expr":"Fl_{0}=\\frac{1}{2}\\cdot4mv_{0}^{2}-\\frac{1}{2}mv_{0}^{2}","cues":["恒力只作用在B上","做功看B的位移","末态间距回到l0"],"concepts":["动能定理","功的定义"]},{"title":"冲量只来自恒力","type":"模型选择","judge":"求恒力作用时间时，能否对全过程用动量定理并只计恒力冲量","why":"库仑力是内力，全过程冲量为零，系统动量变化只由外恒力冲量决定","do":"对全过程列动量定理，末态B速度v0、A速度为零，初态A速度v0，解出Ft2再与动能定理式联立消F","expr":"Ft_{2}=4mv_{0}-mv_{0}","cues":["内力冲量抵消","只看外恒力冲量","动量定理配动能定理"],"concepts":["动量定理","冲量","内力"]}],"501":[{"title":"位移只看首末位置","type":"前提判断","judge":"位移由初位置和末位置决定，还是由走过的路径决定","why":"位移是矢量，只由初、末位置的有向线段决定，与中间路径无关；题设中笔尖从 a 出发又回到 a","do":"比较起点 a 与终点 a 的位置，判断有向线段长度是否为零","expr":"","cues":["回到原点","首末位置相同","位移为零"],"concepts":["位移","矢量"]},{"title":"路程看轨迹长度","type":"前提判断","judge":"路程是否等于轨迹的实际长度，与位移是否为零无关","why":"路程是标量，等于轨迹的实际长度；笔尖沿实线绕行一圈，轨迹长度不为零","do":"沿图中带箭头的实线累计路径长度，与零比较","expr":"","cues":["轨迹有长度","绕了一圈","路程不为零"],"concepts":["路程","标量"]},{"title":"速度方向沿切线","type":"模型选择","judge":"笔尖在 a 点的速度方向由哪一段轨迹决定","why":"曲线运动中某点的瞬时速度方向沿该点轨迹的切线方向；两次经过 a 点时轨迹的走向不同","do":"分别画出第一次经过 a 点和第二次经过 a 点时轨迹的切线方向，比较两者是否相同","expr":"","cues":["看切线方向","两次过a点","方向不同"],"concepts":["瞬时速度","切线方向","曲线运动"]},{"title":"摩擦力方向随速度反向","type":"关系建立","judge":"笔尖所受摩擦力方向由什么决定，两次经过 a 点时是否相同","why":"滑动摩擦力方向与相对运动（笔尖速度）方向相反，速度方向变了，摩擦力方向也随之改变","do":"由两次经过 a 点的速度方向分别反推摩擦力方向，再比较","expr":"","cues":["摩擦力与速度反向","速度变则摩擦变","方向不同"],"concepts":["滑动摩擦力","相对运动方向"]}],"502":[{"title":"识别瓶内气体变化过程","type":"模型选择","judge":"瓶盖拧紧后瓶内气体质量与体积是否改变，从而判断属于哪种等值变化过程","why":"气密性良好且瓶子刚性，气体无法逸出、容积不变，故为一定质量的等容变化","do":"确认瓶内气体质量不变、体积不变，把过程归为等容过程","expr":"V=\\text{const},\\ m=\\text{const}","cues":["瓶盖拧紧了","体积没变","质量不变"],"concepts":["等容变化","理想气体"]},{"title":"判断温度与内能关系","type":"关系建立","judge":"温度升高时瓶内理想气体的内能如何变化","why":"理想气体忽略分子势能，内能只由温度决定，温度升高则内能增大","do":"比较进入车厢前后温度，由温度升高得出内能增大","expr":"U=U(T),\\ T\\uparrow\\Rightarrow U\\uparrow","cues":["温度升高","内能只跟温度有关","理想气体无势能"],"concepts":["理想气体内能","温度"]},{"title":"用等容定律判压强","type":"关系建立","judge":"体积不变、温度升高时压强如何变化","why":"一定质量气体在等容过程中压强与热力学温度成正比（查理定律）","do":"对初末状态列查理定律，由温度升高推出压强增大","expr":"\\frac{p_1}{T_1}=\\frac{p_2}{T_2},\\ T\\uparrow\\Rightarrow p\\uparrow","cues":["等容变化","查理定律","温度升压强升"],"concepts":["查理定律","压强"]},{"title":"区分分子平均与个体动能","type":"结论整理","judge":"温度升高是使所有分子动能都增大，还是只使平均动能增大","why":"温度是分子平均动能的标志，统计规律只说明平均动能增大，个别分子动能可增可减","do":"把'平均动能增大'与'每个分子动能都增大'区分开，排除绝对化表述","expr":"\\bar{E}_k\\propto T","cues":["平均动能增大","不是每个分子","统计规律"],"concepts":["分子平均动能","统计规律"]}],"503":[{"title":"全反射条件","type":"前提判断","judge":"激光从光密介质射向光疏介质、入射角大于等于临界角时，才发生全反射","why":"全反射只在光从光密介质射向光疏介质时发生，液束流射向气体满足这一条件","do":"确认光从液体射向气体，界面处发生全反射","expr":"","cues":["光密到光疏","射向气体","入射角够大"],"concepts":["全反射","光密介质","光疏介质"]},{"title":"临界角与折射率关系","type":"关系建立","judge":"临界角的正弦与折射率成反比，折射率越大临界角越小","why":"由全反射临界角公式 sinC=1/n 可知，n 越大，sinC 越小，C 越小","do":"写出 sinC=1/n，比较甲、乙折射率对应的临界角大小","expr":"\\sin C=\\frac{1}{n}","cues":["临界角公式","折射率越大临界角越小","反比关系"],"concepts":["临界角","折射率","全反射"]},{"title":"频率不变","type":"前提判断","judge":"光从一种介质进入另一种介质时频率是否改变","why":"频率由光源决定，与介质无关，只改变波速和波长","do":"排除以频率变化为依据的选项","expr":"","cues":["频率不变","频率由光源决定","只变波速波长"],"concepts":["光的频率","介质"]},{"title":"比较甲乙临界角","type":"结论整理","judge":"甲折射率大于乙时，哪个液体的全反射临界角更大","why":"由 sinC=1/n，n甲>n乙，得 C甲<C乙，即乙的临界角大","do":"比较 C甲 与 C乙 的大小，选出与之一致的选项","expr":"n_甲>n_乙\\Rightarrow C_甲<C_乙","cues":["乙的临界角大","甲的临界角小","折射率大的临界角小"],"concepts":["临界角","折射率"]}],"504":[{"title":"绳速与块速的关联","type":"关系建立","judge":"绳端沿绳方向的速度分量与塔块沿绳方向的速度分量是否相等","why":"同一根不可伸长的绳上各点沿绳方向的速度分量必须相同，否则绳会伸长或松弛","do":"把塔块速度沿绳和垂直绳分解，把手的水平速度也沿绳和垂直绳分解，令两者沿绳分量相等","expr":"v_{\\text{块}}\\cos\\theta=v\\sin\\theta","cues":["沿绳分量相等","绳不可伸长","分解速度"],"concepts":["速度分解","绳的约束"]},{"title":"夹角随下落变化","type":"几何关系","judge":"塔块下落时绳与竖直方向的夹角是增大还是减小","why":"两绳上端固定、手相向靠近，绳长不变，塔块下降使绳更趋竖直","do":"画出下落前后的几何图，比较绳与竖直方向的夹角","expr":"","cues":["越落越竖直","夹角变小","手在靠近"],"concepts":["几何约束","绳长不变"]},{"title":"由关系式判单调性","type":"数学处理","judge":"由关联式解出 v 随 θ 减小如何变化","why":"关联式给出 v 与 θ 的函数关系，θ 单调减小时 v 的单调性由函数形式决定","do":"把关联式变形为 v 关于 θ 的表达式，分析 θ 减小时 v 的变化趋势","expr":"v=\\frac{v_{\\text{块}}}{\\tan\\theta}","cues":["解出v","看正切","θ变小v变大"],"concepts":["正切函数","单调性"]},{"title":"匀速下落的隐含条件","type":"前提判断","judge":"塔块匀速下落是否意味着 v 恒定","why":"匀速指塔块速度大小不变，而手的速度 v 由几何关系决定，可以变化","do":"区分塔块速度 v块 为常量与手速 v 为变量，避免把 v 当常量","expr":"v_{\\text{块}}=\\text{常量},\\ v=v(\\theta)","cues":["块匀速","手速可变","别搞混"],"concepts":["匀速运动","变量区分"]}],"505":[{"title":"弹簧长度与形变量","type":"几何关系","judge":"判断物块在 A、B、C 三点时弹簧的长度与形变量是否相同","why":"弹簧原长 2r，O 到 A、B、C 的距离需由几何关系算出，弹性势能只由形变量决定","do":"分别算出 OA、OB、OC 的长度，与 2r 比较，判断三点形变量是否相等","expr":"OA=3r,\\ OB=OC=2r","cues":["算弹簧长度","形变量一样吗","原长是二倍半径"],"concepts":["弹性势能","几何关系"]},{"title":"弹力做功是否为零","type":"前提判断","judge":"判断从 A 到 B、从 B 到 C 过程中弹簧弹力做的总功是否为零","why":"弹性势能只与形变量有关，三点形变量相同则弹性势能相同，弹力做功等于弹性势能减少量","do":"比较 A、B、C 三点的弹性势能，得出各段弹力做功为零","expr":"W_{弹}=E_{pA}-E_{pB}=0","cues":["弹力不做功","势能没变","只看电场和重力"],"concepts":["弹性势能","功与能"]},{"title":"电场力做功的位移","type":"关系建立","judge":"判断电场力在 A 到 B、B 到 C 过程中做功的正负与大小，需用水平位移而非路径长度","why":"电场力水平向右，做功只取决于水平方向位移，B 到 C 水平位移为零","do":"写出 A 到 B 的水平位移 3r，判断 B 到 C 电场力做功为零","expr":"W_{电,AB}=qE\\cdot 3r,\\ W_{电,BC}=0","cues":["看水平位移","电场力向右","B到C不沿电场方向"],"concepts":["电场力做功","匀强电场"]},{"title":"重力做功看高度差","type":"关系建立","judge":"判断 B 到 C 过程中重力做功的正负，需用竖直高度差","why":"重力竖直向下，B 到 C 上升高度 r，重力做负功","do":"写出 B 到 C 高度差为 r，重力做功为 -mgr","expr":"W_{重,BC}=-mgr","cues":["上升了","重力做负功","高度差是半径"],"concepts":["重力做功","动能定理"]},{"title":"用动能定理比较动能","type":"结论整理","judge":"用各段合外力做功的正负判断三点动能的大小顺序","why":"动能定理：合外力做功等于动能变化，弹力做功为零后只剩电场力与重力","do":"对 A→B、B→C、A→C 分别列动能定理，比较做功正负","expr":"qE\\cdot 3r-mgr=E_{kC}-E_{kA}>0","cues":["列动能定理","看合功正负","电场力与重力等大"],"concepts":["动能定理","合外力做功"]}],"506":[{"title":"衰变方程守恒定核","type":"前提判断","judge":"双β衰变方程中质量数和电荷数是否各自守恒，从而定出A和y","why":"核反应方程必须满足质量数守恒和电荷数守恒，这是写方程的唯一依据，不先定出A、y就无法判断涉及核素与电子个数","do":"对反应式两边分别列质量数方程和电荷数方程，解出A与y","expr":"100=A+0,\\quad 42=44-y","cues":["数质量数","数电荷数","电子带负电"],"concepts":["质量数守恒","电荷数守恒","β衰变"]},{"title":"激发态能级差对应光子","type":"关系建立","judge":"第二激发态先后辐射两个光子回到基态，说明两光子能量分别对应哪两级之间的能级差","why":"处于第二激发态先辐射一个光子落到中间态，再辐射一个光子落到基态，光子能量等于对应跃迁的能级差，能量大小关系由此确定","do":"把0.5908 MeV与0.5395 MeV分别对应第一、第二次跃迁的能级差，比较两光子能量大小","expr":"E_\\gamma=h\\nu","cues":["先辐射的能量大","能级差定能量","两次跃迁"],"concepts":["能级跃迁","光子能量"]},{"title":"光子能量定频率波长","type":"关系建立","judge":"由两光子能量大小推出频率大小，再由频率大小推出波长大小","why":"光子能量E=hν，能量越大频率越高；真空中波长λ=c/ν，频率越高波长越短，两条关系串联才能比较两光子的频率与波长","do":"先由E比较ν，再由ν比较λ，得出γ1频率高、波长短","expr":"E=h\\nu,\\quad \\lambda=\\frac{c}{\\nu}","cues":["能量大频率高","频率高波长短","先比频率再比波长"],"concepts":["光子能量","频率与波长关系"]}],"507":[{"title":"确定哪两条边切割磁感线","type":"模型选择","judge":"判断线框转动时哪些边真正切割磁感线、哪些边速度方向与 B 平行而不产生电动势","why":"只有速度方向与磁场不平行且沿垂直于 B 方向有分量的导体棒才产生动生电动势；be 轴与 B 垂直，绕轴转动时与轴平行的边（bc、de）速度方向始终与 B 平行或反平行，不切割","do":"把四条边按与转轴 be 的关系分类：bc、de 平行于轴，ab、ef 垂直于轴；再判断 ab、ef 中哪条在转动中扫过磁感线","expr":"","cues":["看哪条边切割","平行轴的边不切割","只有两条边有效"],"concepts":["动生电动势","切割磁感线"]},{"title":"t=0 时速度与磁场的关系","type":"几何关系","judge":"判断 t=0 时刻各切割边速度方向与磁场方向的夹角，确定此刻哪条边电动势为零","why":"t=0 时线框与水平面平行，ab、ef 边速度竖直，与水平磁场垂直；而 cd 边速度方向与 B 平行，故此刻 cd 不产生电动势","do":"画出 t=0 的俯视/侧视图，标出 B 方向与各边速度方向，比较夹角","expr":"E=Blv_{\\perp}","cues":["先看零时刻","速度与磁场平行","画图看夹角"],"concepts":["速度分解","有效切割速度"]},{"title":"用右手定则定电流方向","type":"关系建立","judge":"由切割边的速度方向和磁场方向判断感应电动势（电流）沿线框的绕行方向","why":"右手定则：磁感线穿入手心，拇指指速度方向，四指指感应电流方向；再沿线框回路统一成绕行方向","do":"对产生电动势的那条边用右手定则定出该边电流方向，再沿闭合回路推出整体绕行方向","expr":"","cues":["右手定则","四指指电流","沿回路绕一圈"],"concepts":["右手定则","感应电流方向"]},{"title":"转动中切割边是否换边","type":"临界条件","judge":"判断转过 180° 后，产生电动势的边是否改变、电动势是否为零","why":"转轴 be 与 B 垂直，转过半圈后原来切割的边速度方向反向但仍有垂直于 B 的分量，另一条边速度方向与 B 平行，故切割边不变、电动势大小不变仅方向反转","do":"取 t=π/ω 时刻重画速度方向，与 t=0 对比，确认哪条边速度仍与 B 垂直","expr":"","cues":["转半圈再看","切割边不变","电动势不为零"],"concepts":["周期性转动","有效切割"]},{"title":"区分磁通量与平均电动势","type":"数学处理","judge":"判断求平均电动势时应取哪个回路的磁通量变化，而不是整个线框的磁通量变化","why":"线框为折面，abef 与 bcde 两面磁通量方向相反；整体磁通量变化为零，但法拉第定律应对确定的回路面积取变化量，需分别计算两面的磁通量变化","do":"分别写出 abef 面和 bcde 面在 0 到 π/ω 内的初末磁通量，求 ΔΦ，再除以 Δt","expr":"\\bar{E}=\\frac{\\Delta\\Phi}{\\Delta t}","cues":["分面算磁通量","整体变化为零","别用总磁通"],"concepts":["磁通量","法拉第电磁感应定律"]}],"508":[{"title":"抛物线读成匀变速","type":"图像读取","judge":"x-t 图是抛物线说明速度随时间线性变化，即加速度恒定，甲、乙各自做匀变速直线运动","why":"x-t 图切线斜率表示速度，抛物线对应速度随时间均匀变化，才能用匀变速公式和牛顿第二定律处理","do":"看(b)图两条曲线形状，确认甲、乙均为抛物线，从而判定二者加速度恒定","expr":"x=At^2+Bt+C","cues":["斜率是速度","抛物线就是匀变速","切线越来越陡"],"concepts":["x-t 图像","匀变速直线运动","加速度"]},{"title":"乙图顶点定速度","type":"临界条件","judge":"乙曲线在 t0 处切线斜率为零，说明 t0 时刻乙的速度为零，t0 前乙沿斜面减速下滑","why":"x-t 图切线斜率即速度，斜率为零对应速度为零，这是乙运动方向与加速度方向的转折点","do":"读出乙在 t0 处斜率为零，确定乙的末速度为零，再结合初速度 v0 判断乙做匀减速运动","expr":"v_乙(t_0)=0","cues":["顶点速度为零","斜率是零","乙在减速"],"concepts":["瞬时速度","x-t 图像斜率","匀减速运动"]},{"title":"平均速度求位移","type":"关系建立","judge":"用匀变速平均速度公式把 t0 内甲、乙的位移与初末速度联系起来，才能由图上位移比反推甲在 t0 的速度","why":"匀变速直线运动平均速度等于初末速度平均值，位移等于平均速度乘时间，图上给出甲位移 3x0、乙位移 x0","do":"对乙用 (v0+0)/2·t0=x0 定出 v0 与 x0、t0 的关系，再对甲用 (v0+v)/2·t0=3x0 求甲在 t0 的速度","expr":"\\frac{v_0+v}{2}t_0=3x_0,\\quad \\frac{v_0}{2}t_0=x_0","cues":["平均速度等于首末平均","位移比是三比一","先定乙再定甲"],"concepts":["平均速度","匀变速位移公式"]},{"title":"加速度方向分别定","type":"模型选择","judge":"甲沿斜面加速下滑、乙沿斜面减速下滑，两者加速度方向相反，列牛顿第二定律时摩擦力和重力分量的符号要分别处理","why":"甲速度增大说明合力沿斜面向下，乙速度减小说明合力沿斜面向上，加速度方向不同导致两物块受力方程形式不同","do":"对甲写 mg sinθ−μ1mg cosθ=ma1，对乙写 μ2mg cosθ−mg sinθ=ma2，再由速度变化求 a1、a2 并消去质量","expr":"a_1=\\frac{v-v_0}{t_0},\\quad a_2=\\frac{v_0}{t_0}","cues":["甲加速乙减速","加速度方向相反","摩擦力方向不同"],"concepts":["牛顿第二定律","滑动摩擦力","沿斜面方向受力分析"]},{"title":"整体法判地面摩擦","type":"模型选择","judge":"求地面对斜面的摩擦力时把物块和斜面取整体，用系统牛顿第二定律看水平方向合外力，避免引入物块与斜面间的内力","why":"斜面静止，其水平方向受力由物块对斜面的压力和摩擦力的水平分量决定，取整体可把这些内力消去，只剩地面摩擦力与物块加速度的水平分量","do":"取水平方向，把两物块的 ma 分解到水平，t0 前比较 ma1cosθ 与 ma2cosθ 的大小，t0 后只看甲的水平分量","expr":"f=ma_1\\cos\\theta-ma_2\\cos\\theta","cues":["取整体","避开内力","看加速度的水平分量"],"concepts":["整体法","系统牛顿第二定律","静摩擦力"]}],"509":[{"title":"红黑表笔接法","type":"实验操作","judge":"测 a、b 间电压时红表笔该接 a 还是 b","why":"多用电表作电压表时电流必须从红表笔流入、黑表笔流出，红笔对应高电位端","do":"沿电流方向判断 a、b 两点电位高低，把红表笔接到电位较高的一端","expr":"","cues":["红笔接高电位","电流从红笔进","看电流方向"],"concepts":["多用电表","红进黑出","电位高低"]},{"title":"电压挡读数与估读","type":"数据处理","judge":"0.5 V 挡下分度值是多少、读到哪一位","why":"量程 0.5 V 对应分度值 0.01 V，读数需估读到分度值的下一位，结果保留三位小数","do":"先由量程确定分度值，再按指针位置在最小格间估读一位","expr":"","cues":["先看量程","分度值多少","估读一位"],"concepts":["电压表读数","分度值","估读"]},{"title":"区分两曲线的测量对象","type":"模型选择","judge":"接 a、c 与接 a、b 时电压表分别测的是谁两端的电压","why":"接 a、b 时电压表只跨接在元件两端，接 a、c 时电压表跨接在元件与电流表串联后的整体上","do":"画出两种接法下电压表并联的位置，比较同一电流下两电压的大小关系","expr":"R_{ac}=\\frac{U_{ac}}{I},\\quad R_{ab}=\\frac{U_{ab}}{I}","cues":["看电压表并在哪","串了电流表","同一电流比电压"],"concepts":["伏安法","串联分压","电压表并联位置"]},{"title":"由大小关系定曲线归属","type":"关系建立","judge":"同一电流下 U_ac 与 U_ab 哪个更大，从而判断乙是哪条曲线","why":"a、c 间多串入电流表内阻，故 R_ac>R_ab，同一 I 下 U_ac>U_ab","do":"在图(b)中取同一电流作水平线，比较甲、乙两曲线的电压值大小","expr":"U_{ac}=U_{ab}+IR_A>U_{ab}","cues":["同一电流比高低","多一个电流表","乙电压更大"],"concepts":["欧姆定律","电流表内阻","图像比较"]},{"title":"补偿电压的物理含义","type":"关系建立","judge":"U_ac−U_bc 对应的是哪部分电压，它消除了什么影响","why":"U_ac 含元件与电流表电压，U_bc 含电流表电压，两者相减恰好把电流表内阻造成的压降扣掉","do":"写出 U_ac 与 U_bc 的组成，作差看剩下哪一段电压","expr":"U_{ac}-U_{bc}=U_{元件}","cues":["相减扣掉电流表","差值就是元件电压","消除内阻影响"],"concepts":["电压补偿","电流表内阻","等效测量"]},{"title":"小阻值下曲线贴近判断","type":"结论整理","judge":"元件阻值较小时，甲、乙哪条曲线更接近补偿后的曲线","why":"阻值小时电流表内阻所占比例大，未补偿的 U_ac 偏差大，而 U_ab 只含元件电压，偏差小","do":"比较小阻值区段甲、乙与 I-(U_ac−U_bc) 曲线的偏离程度","expr":"","cues":["小阻值看偏差","电流表影响变大","甲更贴近"],"concepts":["误差分析","相对误差","伏安特性曲线"]}],"510":[{"title":"确定橡皮筋拉力与重力的关系","type":"关系建立","judge":"要判断橡皮筋拉力与杯中总重力通过哪个几何关系联系起来","why":"结点受绳1拉力、橡皮筋拉力、绳2拉力三力平衡，绳2拉力等于杯与水的总重力，必须用正交分解或矢量三角形把橡皮筋拉力用重力表示","do":"对结点作受力分析，沿橡皮筋方向和垂直橡皮筋方向分解，或画矢量三角形，找出橡皮筋拉力与总重力的关系","expr":"T=mg\\cos30^\\circ","cues":["三力平衡","画矢量三角形","沿橡皮筋方向分解"],"concepts":["共点力平衡","正交分解","矢量三角形"]},{"title":"把拉力关系转成x-m线性关系","type":"模型选择","judge":"要判断橡皮筋弹力是否满足胡克定律，从而把拉力与长度x的关系写成线性形式","why":"图像给出的是x-m直线，只有认定橡皮筋在弹性限度内满足F=k(x-x0)，才能把拉力关系转化为x与m的线性关系","do":"将胡克定律代入拉力表达式，整理出x随m变化的直线方程，明确斜率与截距的物理意义","expr":"k(x-x_0)=mg\\cos30^\\circ","cues":["胡克定律","弹性限度内","找斜率和截距"],"concepts":["胡克定律","弹性限度","线性关系"]},{"title":"由图像读出芒果质量","type":"图像读取","judge":"要判断在x-m图上如何由已知x值反查m，并注意坐标轴单位与刻度","why":"图线是x与m的对应关系，已知x=11.60 cm必须从纵轴定位后水平找图线再竖直读横轴，且横轴单位与题目要求的g要统一","do":"在纵轴找到11.60 cm对应点，水平引到图线，再竖直向下读横轴数值，按刻度估读并保留到个位","expr":"","cues":["先看纵轴","水平找图线","再读横轴"],"concepts":["图像读数","坐标轴单位","有效数字"]},{"title":"判断不垂直时拉力偏大","type":"前提判断","judge":"要判断橡皮筋与绳1不垂直时，维持绳1夹角30°所需的橡皮筋拉力比垂直时大还是小","why":"三力平衡中，橡皮筋拉力方向改变会改变它与重力方向的夹角，由矢量三角形可知垂直时橡皮筋拉力最小，偏离垂直则拉力增大","do":"比较垂直与不垂直两种情形下橡皮筋拉力的大小，判断橡皮筋伸长量及x的变化方向，再判断由图像读出的质量偏大还是偏小","expr":"","cues":["垂直时拉力最小","偏离垂直拉力变大","伸长量偏大"],"concepts":["共点力平衡","矢量三角形","极值条件"]},{"title":"判断图线弯曲的原因","type":"结论整理","judge":"要判断x-m图线后半段弯曲是哪个因素导致非线性","why":"图像弯曲意味着x与m不再成正比，只有橡皮筋弹力与伸长量不成正比（超出弹性限度）才会破坏线性关系，水杯质量、绳套长度只影响截距或平移","do":"逐一分析各选项对x-m关系是改变斜率截距还是破坏线性，排除只影响截距的选项","expr":"","cues":["超出弹性限度","不成正比","只改变截距"],"concepts":["胡克定律","弹性限度","图像非线性"]},{"title":"找扩大测量范围的措施","type":"临界条件","judge":"要判断改变哪个可调量能在橡皮筋达到弹性限度前承受更大质量","why":"测量上限由橡皮筋最大伸长对应的最大拉力决定，减小绳1与竖直方向夹角可使同样质量对应的橡皮筋拉力变小，从而在限度内测更大质量","do":"从拉力表达式出发，分析减小绳1与竖直方向夹角对同一质量所需橡皮筋拉力的影响，得出可增大测量范围的措施","expr":"T=mg\\cos\\theta","cues":["减小夹角","同样质量拉力变小","换更粗橡皮筋"],"concepts":["共点力平衡","弹性限度","测量范围"]}],"511":[{"title":"选规律求A点速度","type":"模型选择","judge":"求屋顶上滑行末速度时，该用牛顿第二定律加运动学，还是直接用动能定理","why":"屋顶上受重力、支持力、摩擦力三个力，其中支持力不做功、摩擦力大小恒定，用动能定理可一步关联位移与速度，不必求加速度和时间","do":"对雪块从O到A的过程列动能定理，把重力沿斜面分力的功与摩擦力做功相加等于动能增量","expr":"mgx\\sin\\theta-\\mu mgx\\cos\\theta=\\frac{1}{2}mv_0^2","cues":["用动能定理","不用求加速度","摩擦力做负功"],"concepts":["动能定理","摩擦力做功","斜面"]},{"title":"离开后按斜下抛处理","type":"模型选择","judge":"雪块离开屋顶后是平抛、斜抛还是斜下抛，初速度方向如何","why":"离开瞬间速度沿屋顶向下，与水平方向成俯角，之后只受重力，属于匀变速曲线运动，可分解为水平匀速和竖直匀加速","do":"把A点速度分解为水平分量与竖直分量，判断竖直分量方向向下，确认是斜下抛而非平抛","expr":"v_{0x}=v_0\\cos\\theta,\\quad v_{0y}=v_0\\sin\\theta","cues":["斜下抛","速度沿屋顶向下","分解成水平和竖直"],"concepts":["斜抛运动","运动的分解","重力"]},{"title":"落地速度用动能定理","type":"关系建立","judge":"求落地速度大小时，是分方向求分速度再合成，还是直接用重力做功等于动能变化","why":"空中只有重力做功，重力做功只取决于竖直下落高度h，与轨迹无关，用动能定理可绕过时间直接得末速率","do":"对A到落地点列动能定理，重力做功取mgh，等于末动能减初动能","expr":"mgh=\\frac{1}{2}mv_1^2-\\frac{1}{2}mv_0^2","cues":["重力做功只看高度","不用求时间","动能定理一步到位"],"concepts":["动能定理","重力做功","末速度"]},{"title":"夹角用水平分速不变","type":"关系建立","judge":"求速度方向与水平方向夹角时，用哪个分速度作比较，水平分速度在空中是否改变","why":"空中水平方向不受力，水平分速度保持v0cosθ不变，故夹角余弦等于水平分速度与合速度之比","do":"写出水平分速度表达式，与落地速度大小作比求余弦，再取反余弦得夹角","expr":"\\cos\\alpha=\\frac{v_0\\cos\\theta}{v_1}","cues":["水平速度不变","用水平比合速度","求余弦再反算角度"],"concepts":["速度分解","水平分速度","夹角"]}],"512":[{"title":"有效面积只算一半","type":"前提判断","judge":"计算磁通量变化时，线框处在磁场中的有效面积取整个正方形还是只取一半","why":"ab 边中点位于磁场边界，只有边界右侧的一半线框处在磁场中，磁通量只穿过这部分面积","do":"确定有效面积 S=½L²，代入法拉第电磁感应定律求 0~1 s 的电动势","expr":"E=\\frac{\\Delta B}{\\Delta t}\\cdot\\frac{1}{2}L^{2}","cues":["面积取一半","只有半框在磁场里"],"concepts":["磁通量","有效面积","法拉第电磁感应定律"]},{"title":"由电流图反推磁场变化率","type":"图像读取","judge":"如何用图(c)中 1~2 s 的电流大小和方向，反推该段磁感应强度的变化率和末值","why":"电流大小由电动势决定，电动势由磁通量变化率决定；电流方向由楞次定律决定，二者共同约束 B-t 图线","do":"读图(c)得 1~2 s 电流大小与方向，先算电动势，再算 ΔB/Δt，结合 t=1 s 的 B 值外推 t=2 s 的 B 值并确定增减","expr":"E_{2}=I_{2}R,\\quad \\frac{\\Delta B}{\\Delta t}=\\frac{E_{2}}{\\frac{1}{2}L^{2}}","cues":["先读电流再算电动势","用楞次定律定方向","从一秒推到两秒"],"concepts":["楞次定律","法拉第电磁感应定律","闭合电路欧姆定律"]},{"title":"区分感生与动生电动势","type":"模型选择","judge":"t=2 s 后线框运动时，感应电动势该用动生公式还是仍用感生公式","why":"题设明确 t=2 s 后磁场不再随时间变化，磁通量变化完全来自线框切割磁感线，属于动生电动势","do":"确认 B 恒定，改用 E=BLv 描述运动过程中的电动势，不再用 ΔB/Δt","expr":"E=BLv","cues":["磁场不变了","靠切割磁感线","换成动生公式"],"concepts":["动生电动势","切割磁感线"]},{"title":"安培力冲量用平均电流","type":"关系建立","judge":"变力安培力作用下求末速度，用牛顿第二定律逐时刻积分还是用动量定理整体处理","why":"线框运动时速度变化，安培力 F=BIL 随速度变化，是变力，无法用匀变速公式，只能对整个过程用动量定理，把安培力冲量写成 BIL·Δt","do":"对线框从初速到 ad 边离开磁场的过程列动量定理，把冲量中的 IΔt 合并为电荷量 q","expr":"-B_{2}\\bar{I}L\\Delta t=mv_{1}-mv_{0}","cues":["力是变的","用动量定理","把电流乘时间合起来"],"concepts":["动量定理","安培力","变力冲量"]},{"title":"电荷量由磁通量变化算","type":"关系建立","judge":"动量定理中的 q 能否直接用平均电流乘时间，还是需转化为磁通量变化量除以电阻","why":"平均电流未知，但 q=ΔΦ/R 只依赖始末磁通量，与运动细节无关，这是消去未知量的关键","do":"写出 q=ΔΦ/R，ΔΦ 取线框从初始位置到 ad 边刚出磁场时扫过的那部分磁通量变化","expr":"q=\\bar{I}\\Delta t=\\frac{\\Delta\\Phi}{R}=\\frac{\\frac{1}{2}B_{2}L^{2}}{R}","cues":["电量只看磁通量变化","和过程快慢无关","用始末磁通量差"],"concepts":["电荷量公式","磁通量变化"]},{"title":"离开瞬间的磁通量变化","type":"临界条件","judge":"ad 边离开磁场时，线框扫过并减少的磁通量对应哪块面积","why":"初始只有一半线框在磁场中，ad 边移出边界时这半个线框的面积全部退出磁场，磁通量减少量由这半个面积决定","do":"确定 ΔΦ=½B₂L²，与动量定理联立解出 v₁","expr":"\\Delta\\Phi=\\frac{1}{2}B_{2}L^{2}","cues":["出界时半框退出","减少的就是那半块面积"],"concepts":["临界状态","磁通量变化"]}],"513":[{"title":"由弦长定轨迹半径","type":"几何关系","judge":"要判断入射速度方向与弦 MN 的夹角，从而用弦长和偏转角表示圆周半径","why":"粒子在匀强磁场中做匀速圆周运动，轨迹圆的弦 MN 沿 y 轴，弦长 2y₀ 已知，入射速度与 y 轴正方向成 30°，弦与入射速度的夹角决定半径","do":"画出轨迹圆，找出弦 MN 与入射速度的夹角 θ=30°，用弦长一半与 sinθ 的关系求半径","expr":"r=\\frac{y_{0}}{\\sin\\theta}=2y_{0}","cues":["画轨迹圆","弦长一半","入射角三十度"],"concepts":["洛伦兹力","圆周运动","几何关系"]},{"title":"偏转角定运动时间","type":"关系建立","judge":"要判断粒子从 M 到 N 转过的圆心角是 2θ 还是 π−2θ，从而确定时间占周期的比例","why":"圆周运动时间由圆心角决定，圆心角等于速度方向偏转角，需由几何关系确定偏转角","do":"由弦与速度夹角推出圆心角为 2θ=60°，用 t=(2θ/2π)T 求时间","expr":"t_{1}=\\frac{2\\theta}{2\\pi}T=\\frac{\\pi m}{3qB}","cues":["圆心角多少","偏转角","占几分之几周期"],"concepts":["周期","圆心角","运动时间"]},{"title":"定负电荷位置在圆心","type":"前提判断","judge":"要判断负点电荷应放在轨迹圆心 O 处，才能使库仑力沿半径方向与洛伦兹力共线","why":"粒子仍沿原轨迹运动，合力必须始终指向圆心且沿半径，只有点电荷位于圆心 O 时库仑力才沿半径","do":"由轨迹圆心在 O 点，确定负电荷固定在 O，库仑力与洛伦兹力同向指向圆心","expr":"","cues":["电荷放圆心","力沿半径","仍走原轨迹"],"concepts":["点电荷电场","向心力","共线"]},{"title":"向心力方程定速度","type":"关系建立","judge":"要判断洛伦兹力与库仑力同向叠加提供向心力，并代入质量关系解出 v₂","why":"正电荷在向里磁场中沿原轨迹运动，洛伦兹力指向圆心，负电荷在圆心对正电荷吸引也指向圆心，两力同向","do":"列向心力方程，代入 m=B²y₀³/k，解关于 v₂ 的二次方程并舍去负根","expr":"qv_{2}B+k\\frac{48q^{2}}{r^{2}}=m\\frac{v_{2}^{2}}{r},\\quad m=\\frac{B^{2}y_{0}^{3}}{k}","cues":["两力同向","代入质量","舍去负根"],"concepts":["牛顿第二定律","库仑力","向心力"]},{"title":"判断出磁场后做椭圆","type":"模型选择","judge":"要判断粒子离开磁场后库仑力不足以提供所需向心力，因而做椭圆运动而非圆周运动","why":"比较所需向心力 mv²/r 与库仑力 k·48q²/r² 的大小，前者大，故轨迹为椭圆，需用能量守恒与开普勒第二定律","do":"在 N 点比较 mv₂²/r₂ 与 k·48q²/r₂²，确认做椭圆运动，改用能量守恒加角动量守恒求解","expr":"m\\frac{v_{2}^{2}}{r_{2}}>k\\frac{48q^{2}}{r_{2}^{2}}","cues":["力不够","不是圆周","椭圆轨道"],"concepts":["椭圆运动","能量守恒","开普勒第二定律"]},{"title":"速度反向对应远心点","type":"临界条件","judge":"要判断速度方向首次与 N 点速度相反的位置是椭圆轨道的另一个顶点（远心点），从而确定 r₃ 与半长轴","why":"椭圆轨道上速度方向与位置矢量垂直，速度反向只能出现在长轴两端，N 点为近心点，另一顶点为远心点","do":"用能量守恒与 v₂r₂=v₃r₃ 联立求 r₃，再以半长轴 (r₂+r₃)/2 用牛顿第二定律求周期，取半个周期为 t₂","expr":"r_{3}=6y_{0},\\quad T=\\frac{4\\sqrt{3}\\pi By_{0}^{3}}{3kq},\\quad t_{2}=\\frac{T}{2}","cues":["远心点","长轴两端","半个周期"],"concepts":["椭圆轨道","开普勒第三定律","能量守恒"]}],"514":[{"title":"识别基本单位范畴","type":"前提判断","judge":"要判断题目问的是国际单位制的“基本单位”而不是导出单位或常用单位","why":"国际单位制中只有七个被选定的基本量对应的单位才叫基本单位，其余（如 N、J、W）都是由此导出的单位","do":"回忆七个基本量：长度、质量、时间、电流、热力学温度、物质的量、发光强度","expr":"","cues":["基本单位只有七个","导出单位不算"],"concepts":["国际单位制","基本单位","导出单位"]},{"title":"核对符号与单位对应","type":"关系建立","judge":"要判断每个符号是否恰好对应七个基本单位之一，而不是某个导出单位的符号","why":"基本单位的符号是固定规定的（m、kg、s、A、K、mol、cd），符号与单位必须一一对应，不能凭字母形似猜测","do":"把选项中的符号逐个与七个基本单位符号比对，排除属于导出单位的符号","expr":"","cues":["看符号对不对","牛顿不是基本单位"],"concepts":["单位符号","基本量"]}],"515":[{"title":"质点判据","type":"前提判断","judge":"判断运动员的形状和体积对所研究的问题是否有影响","why":"质点的定义是物体的形状和大小对所研究问题的影响可以忽略时，把物体简化为有质量的点","do":"对每个场景问一句：研究的是运动员整体的位置变化，还是运动员自身的动作姿态","expr":"","cues":["看形状大小能不能忽略","看研究的是不是动作"],"concepts":["质点","理想化模型"]},{"title":"区分整体运动与自身动作","type":"模型选择","judge":"判断所研究的问题是运动员整体的位移、时间、速度，还是身体各部分的转动、姿态","why":"研究整体平动轨迹时各点运动可视为相同，可当质点；研究转体、入水、攀支点等自身动作时各部分运动不同，不能当质点","do":"把四个场景分成两类：一类问整体跑了多快、用了多久，一类问身体怎么动","expr":"","cues":["整体跑多快","身体怎么转","动作细节"],"concepts":["平动","转动","质点"]},{"title":"平均速度只看整体","type":"关系建立","judge":"判断求百米平均速度时是否需要知道运动员身体各部分的运动","why":"平均速度由总位移和总时间决定，与运动员的形体、姿态无关，形状体积的影响可忽略","do":"写出平均速度的定义式，确认式中只出现位移和时间两个量","expr":"\\bar{v}=\\frac{x}{t}","cues":["位移除以时间","跟姿势无关"],"concepts":["平均速度","位移","时间"]}],"516":[{"title":"判断是否受空气阻力","type":"前提判断","judge":"足球从1到3的轨迹是否对称、能否用无阻力抛体运动描述","why":"若只有重力，轨迹应是关于最高点对称的抛物线，落点3应与1关于最高点竖直投影对称；题图轨迹不对称，说明存在空气阻力","do":"对比1到2与2到3的水平位移和轨迹弯曲程度，判断轨迹是否对称","expr":"","cues":["看轨迹对不对称","有没有空气阻力","不能当平抛斜抛"],"concepts":["抛体运动","空气阻力","轨迹对称性"]},{"title":"上升段动能减少量","type":"关系建立","judge":"从1到2动能减少量应等于重力势能增加量还是大于它","why":"动能定理：合外力做功等于动能变化，上升过程中重力和空气阻力都做负功，阻力做负功使动能损失多于重力势能增加","do":"对1到2段列动能定理，比较阻力做功与重力做功的符号和大小","expr":"-mgh-W_f=E_{k2}-E_{k1}","cues":["阻力也做负功","动能损失比势能多","上升段用动能定理"],"concepts":["动能定理","重力做功","阻力做功"]},{"title":"下降段机械能变化","type":"关系建立","judge":"从2到3重力势能减少mgh时，动能增加量是等于还是小于mgh","why":"下降过程中空气阻力做负功，机械能减少，重力势能的减少量一部分转化为动能，一部分被阻力耗散","do":"对2到3段列动能定理或机械能关系，比较动能增量与mgh","expr":"mgh-W_f'=E_{k3}-E_{k2}","cues":["下降阻力做负功","机械能减少","动能增加不到mgh"],"concepts":["机械能守恒条件","动能定理","阻力做功"]},{"title":"全程机械能判断","type":"结论整理","judge":"整段运动中机械能是否守恒、落回地面时动能与初动能谁大","why":"全程空气阻力始终做负功，机械能单调减少，故落地动能小于初动能","do":"比较位置1与位置3的动能，或比较全程初末机械能","expr":"E_{k3}<E_{k1}","cues":["全程机械能一直减","落地比踢出时慢","阻力一直做负功"],"concepts":["机械能","功能关系","阻力做功"]}],"517":[{"title":"磁场方向沿半径","type":"前提判断","judge":"极靴与软铁圆柱之间各点的磁场方向是否都沿半径方向（即与线圈边垂直）","why":"题设明确给出极靴与圆柱间磁场沿半径方向，这是判断安培力方向与线圈受力是否始终垂直于导线的前提","do":"读题干与示意图，确认 a、b、c、d 各点磁感线均沿半径指向或背离圆心","expr":"","cues":["磁场沿半径","辐向磁场","磁感线与导线垂直"],"concepts":["辐向磁场","磁感线"]},{"title":"安培力方向判定","type":"关系建立","judge":"左侧通电导线所受安培力沿哪个方向","why":"电流方向、磁场方向、安培力方向三者由左手定则确定，方向判断错则整项错","do":"对左侧导线用左手定则：让磁感线穿入掌心，四指指电流方向，拇指指向即安培力方向","expr":"\\vec F=I\\vec L\\times\\vec B","cues":["左手定则","四指指电流","磁感线穿掌心"],"concepts":["安培力","左手定则"]},{"title":"辐向磁场中线圈受力","type":"模型选择","judge":"线圈处于辐向磁场中时，各边所受安培力是否始终与线圈平面垂直、大小是否恒定","why":"辐向磁场使导线处处与磁感线垂直，安培力大小不变且方向始终沿切线，这正是磁电式电表刻度均匀的原因","do":"把线圈四边分别与所在处磁感线方向比较，确认导线与磁场垂直，再判断各边受力方向","expr":"F=BIL","cues":["导线与磁场垂直","受力大小不变","刻度均匀"],"concepts":["辐向磁场","安培力"]},{"title":"磁感应强度大小比较","type":"图像读取","judge":"a 与 b、c 与 d 各点磁感应强度的大小关系及方向关系","why":"磁感应强度是矢量，大小看磁感线疏密，方向看磁感线切线；辐向磁场中同一半径上各点方向不同","do":"比较 a、b 两点磁感线疏密与方向，比较 c、d 两点磁感线疏密","expr":"","cues":["看疏密","方向不同","大小相同"],"concepts":["磁感应强度","磁感线疏密"]},{"title":"圆柱内磁场是否为零","type":"结论整理","judge":"软铁圆柱内部磁感应强度是否为零","why":"磁感线是闭合曲线，在软铁内部仍要连续通过，故内部磁场不为零","do":"由磁感线闭合性判断圆柱内磁感线是否连续存在","expr":"","cues":["磁感线闭合","内部不为零","软铁导磁"],"concepts":["磁感线闭合性","磁感应强度"]}],"518":[{"title":"峰值与有效值换算","type":"前提判断","judge":"给出的 5 V 是交流电压的峰值还是有效值，变压器公式该用哪一个","why":"变压器电压比等于匝数比，针对的是有效值；而打火条件 10 kV 是峰值，两者不能混用","do":"把输入峰值 5 V 除以根号二换成有效值，再对副线圈结果乘根号二换回峰值","expr":"U_1=\\frac{5}{\\sqrt{2}}\\ \\mathrm{V},\\quad U_{2\\max}=\\sqrt{2}U_2","cues":["先换成有效值","峰值不能直接用","乘根号二换回来"],"concepts":["有效值","峰值","理想变压器"]},{"title":"升压匝数比不等式","type":"关系建立","judge":"由副线圈峰值须大于 10 kV 反推匝数比应满足的方向和大小","why":"升压变压器 n2>n1，且点火条件是峰值严格大于 10 kV，取等号只是临界","do":"把 U2max 用 U1 和匝数比表示，代入 10 kV 解出 n2/n1 的下界","expr":"\\frac{n_2}{n_1}=\\frac{U_2}{U_1}>\\frac{10^4/\\sqrt{2}}{5/\\sqrt{2}}=2000","cues":["升压就是副线圈多","临界取等号","比值要大于两千"],"concepts":["匝数比","升压变压器","临界条件"]},{"title":"电压表读有效值","type":"前提判断","judge":"电压表测原线圈电压时显示的是峰值、有效值还是平均值","why":"交流电压表读数恒为有效值，与瞬时值和峰值无关","do":"直接取原线圈电压有效值作为示数，不再乘根号二","expr":"U_1=\\frac{5\\sqrt{2}}{2}\\ \\mathrm{V}","cues":["电压表读有效值","不是峰值","不用再换算"],"concepts":["交流电表读数","有效值"]},{"title":"频率由电源决定","type":"关系建立","judge":"副线圈电压频率是否被变压器改变","why":"理想变压器只改变电压和电流，不改变频率，频率由发电机（电源）决定","do":"从 u 的表达式读出角频率，用角频率与频率的关系求 f","expr":"\\omega=100\\pi\\ \\mathrm{rad/s},\\quad f=\\frac{\\omega}{2\\pi}=50\\ \\mathrm{Hz}","cues":["变压器不改频率","看角频率","一百派除以二派"],"concepts":["角频率","频率","理想变压器"]}],"519":[{"title":"配重拉力等于重力","type":"前提判断","judge":"细线 c、d 中的拉力是否等于配重 P、Q 的重力","why":"配重静止且不计摩擦，绳中张力处处相等，故 T_c=T_d=mg；若误以为绳张力需由角度分解求出，就会多出未知量","do":"对配重 P、Q 分别列平衡，得 T_c=T_d=mg=0.5 N","expr":"T_c=T_d=mg","cues":["绳张力等于配重重力","不计摩擦","两边一样重"],"concepts":["绳中张力","平衡条件"]},{"title":"c、d拉力相互抵消","type":"关系建立","judge":"c 对 A 的拉力与 d 对 B 的拉力是否等大反向","why":"c、d 平行且与水平成同一角度，两配重质量相同，故两拉力大小相等、方向相反，对 A、B 整体而言是一对内力，合冲量为零","do":"比较 T_c 与 T_d 的大小和方向，确认二者沿同一直线反向","expr":"\\vec T_c=-\\vec T_d,\\quad |\\vec T_c|=|\\vec T_d|","cues":["两绳平行","方向相反","大小相等"],"concepts":["内力","整体法"]},{"title":"取整体求a的拉力","type":"模型选择","judge":"求 a 的拉力时是否把 A、B 取作整体","why":"c、d 拉力对整体相互抵消，整体只受重力与 a 的拉力，一步即得；若隔离单个球则需联立 b 绳的未知力，多解一个未知数","do":"对 A、B 整体竖直方向列平衡，a 的拉力等于两球总重力","expr":"T_a=(m_A+m_B)g","cues":["取整体","两绳抵消","只看外绳"],"concepts":["整体法","平衡条件"]},{"title":"隔离A求b的拉力","type":"模型选择","judge":"求 b 的拉力时是否隔离 A（或 B）单独分析","why":"b 是 A、B 之间的内力，整体法无法求出，必须隔离其中一球，把 b 的拉力和已知的 c（或 d）拉力一起分解","do":"对 A 列水平、竖直两个方向的平衡方程，含 T_b 与角度 α","expr":"T_b\\sin\\alpha+T_c\\sin\\theta=m_Ag,\\quad T_b\\cos\\alpha=T_c\\cos\\theta","cues":["隔离A","b是内力","分解两个方向"],"concepts":["隔离法","力的分解"]},{"title":"消去角度求b","type":"数学处理","judge":"如何消去未知的 b 绳倾角 α 得到 T_b","why":"α 未知且题目不要求，需用两方程平方相加（或合成矢量三角形）消去 α，只留 T_b 与已知量","do":"将两式平方相加，利用 sin²+cos²=1 消去 α，再开方求 T_b","expr":"T_b^2=(m_Ag-T_c\\sin\\theta)^2+(T_c\\cos\\theta)^2","cues":["平方相加","消掉角度","合成矢量"],"concepts":["三角函数消元","矢量合成"]}],"520":[{"title":"写对聚变核反应方程","type":"关系建立","judge":"反应物与生成物的核电荷数和质量数是否同时守恒，中子是否必须出现在生成物中","why":"核反应遵循电荷数守恒和质量数守恒，氘氚聚变生成氦的同时必须放出一个中子，否则质量数和电荷数无法配平","do":"用质量数守恒和电荷数守恒配平，写出完整的聚变方程","expr":"^{2}_{1}\\mathrm{H}+^{3}_{1}\\mathrm{H}\\to^{4}_{2}\\mathrm{He}+^{1}_{0}\\mathrm{n}","cues":["配平质量数","要放出中子","电荷数守恒"],"concepts":["核反应方程","质量数守恒","电荷数守恒"]},{"title":"比结合能大小比较","type":"前提判断","judge":"中等质量核与轻核相比，谁的比结合能更大","why":"比结合能随质量数增大先升后降，氦核处于较稳定区域，比结合能大于氘核，因此聚变后比结合能增大才放出能量","do":"比较氘核与氦核的比结合能大小，判断聚变后比结合能是增大还是减小","expr":"","cues":["氦核更稳定","比结合能变大","中等核最稳定"],"concepts":["比结合能","核稳定性"]},{"title":"聚变的临界距离判断","type":"临界条件","judge":"核力起作用要求两核间距达到什么量级，是否远小于原子尺度","why":"核力是短程力，只有两核接近到核力作用范围（约 10 的负 15 次方米）以内才能发生聚变，而不是原子大小或更远","do":"判断聚变所需距离的数量级，与核力作用半径比较","expr":"r\\sim10^{-15}\\,\\mathrm{m}","cues":["要挨得很近","核力是短程力","到原子核尺度"],"concepts":["核力","临界距离"]},{"title":"质量亏损与释放能","type":"关系建立","judge":"用反应前后质量之差求质量亏损，再换算成释放的核能","why":"爱因斯坦质能方程给出质量亏损与释放能量的对应关系，必须先算准反应前后总质量之差","do":"用反应物总质量减生成物总质量得质量亏损，再乘 931.5 MeV/u","expr":"\\Delta m=(2.0141+3.0161-4.0026-1.0087)\\,\\mathrm{u},\\ \\Delta E=\\Delta m\\times931.5\\,\\mathrm{MeV}","cues":["先算质量差","乘九百三十一点五","反应前后质量"],"concepts":["质量亏损","质能方程"]},{"title":"宏观能量与数量级估算","type":"数学处理","judge":"把单个核反应的能量推广到给定质量的氘，判断总能量数量级","why":"宏观样品含大量氘核，总能量等于参与反应的核对数乘以单次释放能量，需用摩尔质量与阿伏加德罗常数换算核数","do":"由氘的摩尔质量求给定质量对应的物质的量，乘阿伏加德罗常数得核数，再乘单次释放能量","expr":"E=\\frac{m}{M}N_{A}\\Delta E","cues":["先求核的个数","再乘单次能量","看数量级"],"concepts":["阿伏加德罗常数","摩尔质量","数量级估算"]}],"521":[{"title":"平抛模型识别","type":"模型选择","judge":"水离开管口后的运动应归为哪类运动","why":"水离开水平细水管时只有水平初速度，之后只受重力，符合平抛运动条件","do":"把出水口到桶底 A 点的轨迹当作平抛处理，水平方向匀速、竖直方向自由落体","expr":"","cues":["平抛","水平射出","只受重力"],"concepts":["平抛运动","运动的分解"]},{"title":"竖直位移取两倍桶高","type":"几何关系","judge":"从出水口到桶底 A 点的竖直下落高度是 h 还是 2h","why":"题设水管到地面距离为桶高的两倍，桶底 A 在地面上，故竖直总落差为 2h；桶口高度处只下落了 h","do":"分别写出落到桶口高度和落到桶底 A 点对应的竖直位移 h 与 2h","expr":"y_1=h,\\quad y_2=2h","cues":["落差是两倍桶高","桶口只降一个桶高","到桶底降两个桶高"],"concepts":["竖直位移","自由落体"]},{"title":"桶口与桶底的水平衔接","type":"关系建立","judge":"水从桶口中心到桶底边沿 A 的水平位移与桶直径是什么关系","why":"水恰好从桶口中心无阻挡进入，再落到桶底边沿 A，桶口中心到 A 的水平距离为半径 D/2","do":"把出水口到桶口中心的水平距离记为 x，则到 A 点的水平距离为 x+D/2","expr":"x+D/2=v_0 t_2","cues":["桶口中心进","落到边沿","水平差半个直径"],"concepts":["水平位移","几何约束"]},{"title":"两段飞行时间由高度定","type":"关系建立","judge":"两段水平位移是否对应同一初速但不同飞行时间","why":"平抛水平速度不变，飞行时间只由竖直下落高度决定","do":"用 h 和 2h 分别求 t1、t2，再与各自水平位移联立消去 x","expr":"t_1=\\sqrt{2h/g},\\quad t_2=\\sqrt{4h/g}","cues":["时间由高度定","初速不变","两段时间不同"],"concepts":["平抛运动","飞行时间"]},{"title":"消去 x 解出初速","type":"数学处理","judge":"如何把两个方程合成只含 v0 的式子","why":"x 是未知中间量，需用两式相减消去，才能解出唯一初速","do":"由 x=v0t1 与 x+D/2=v0t2 相减得 D/2=v0(t2-t1)，再解 v0","expr":"v_0=\\frac{D/2}{\\sqrt{4h/g}-\\sqrt{2h/g}}","cues":["消去x","两式相减","只剩初速"],"concepts":["方程联立","平抛规律"]}],"522":[{"title":"轨道半径的确定","type":"前提判断","judge":"卫星做圆周运动的半径应取地球半径加轨道高度，还是只取轨道高度","why":"万有引力定律中的距离是两质心间距，卫星距地面 500 km，必须加上地球半径","do":"把 500 km 与 6.4×10³ km 相加，得到 r 后代人 GM/r²","expr":"r=R+h=6.9\\times10^{6}\\,\\mathrm{m}","cues":["半径就是高度","要加地球半径","离地五百公里"],"concepts":["万有引力定律","轨道半径"]},{"title":"向心加速度由引力提供","type":"模型选择","judge":"求卫星加速度时，用万有引力提供向心力，还是用地面重力加速度 g 直接代替","why":"卫星在高空，重力加速度已不是 9.8，只能由 GM/r² 求当地引力加速度","do":"写 GMm/r²=ma，约去 m 后代入 GM 与 r 求 a","expr":"a=\\frac{GM}{r^{2}}","cues":["用黄金代换","不能直接用g","引力当向心力"],"concepts":["牛顿第二定律","万有引力"]},{"title":"周期公式与单位换算","type":"关系建立","judge":"求周期时用开普勒第三定律还是由 GMm/r²=m(2π/T)²r 推出，结果如何换成小时","why":"周期由引力提供向心力决定，算出的秒数需除以 3600 才能与选项的小时数比较","do":"由 GMm/r²=m(4π²/T²)r 解出 T，再换算成小时与选项比对","expr":"T=2\\pi\\sqrt{\\frac{r^{3}}{GM}}","cues":["先算秒再换小时","周期看半径","开普勒第三定律"],"concepts":["圆周运动周期","开普勒第三定律"]},{"title":"反冲推力的来源","type":"模型选择","judge":"火箭获得的推力是燃气对火箭的反作用力，还是火箭自己喷气产生的“自力”","why":"动量守恒与牛顿第三定律，喷气与箭体受力是一对作用反作用","do":"把燃气与箭体视为相互作用的两部分，判断推力施力物体是燃气","expr":"","cues":["燃气给的反作用力","作用力与反作用力","不是自己推自己"],"concepts":["反冲","牛顿第三定律"]},{"title":"超重失重的判据","type":"临界条件","judge":"火箭加速上升时，箭上卫星是超重还是失重，取决于加速度方向而非速度方向","why":"超重失重由加速度方向决定：加速度向上即超重，与运动方向无关","do":"判断初始阶段火箭加速度方向向上，得出卫星视重增大","expr":"","cues":["看加速度方向","加速上升就超重","速度向上不算数"],"concepts":["超重与失重","加速度方向"]}],"523":[{"title":"影子与小球同相","type":"关系建立","judge":"屏上影子的振动步调由谁决定，是与光源同相还是与小球同相","why":"影子是光源发出的光被小球遮挡形成的，遮挡体的位置决定影子的位置，光源只提供光线","do":"把影子位置看成小球位置的几何投影，判断影子位移随小球位移同步变化","expr":"","cues":["影子跟着小球走","遮挡物决定影子","光源只提供光"],"concepts":["光的直线传播","遮挡","相位"]},{"title":"两球振动反相","type":"图像读取","judge":"从振动图像判断小球与光源的相位关系及各自在关键时刻的位置","why":"两图线关于时间轴镜像，位移始终等大反向，说明二者步调相反","do":"读图(b)中两条曲线的峰谷对应时刻，确认同一时刻一个在最高点另一个在最低点","expr":"","cues":["两图线反着走","一个最高一个最低","步调相反"],"concepts":["简谐运动图像","相位差"]},{"title":"加速度指向平衡位置","type":"前提判断","judge":"由位移方向判断回复力与加速度的方向","why":"简谐运动中回复力与位移反向，加速度方向总指向平衡位置","do":"看该时刻光源位移的正负，再取反得到加速度方向","expr":"a=-\\frac{k}{m}x","cues":["加速度指向平衡位置","位移向上加速度向下","回复力与位移反向"],"concepts":["简谐运动","回复力","加速度"]},{"title":"速度方向看图像斜率","type":"图像读取","judge":"由振动图像在该时刻的斜率判断小球运动方向","why":"位移-时间图像的斜率正负即速度方向，正方向已规定为竖直向上","do":"看该时刻之后位移是增大还是减小，判断小球向上还是向下运动","expr":"v=\\frac{\\Delta x}{\\Delta t}","cues":["看斜率正负","之后位移变小","向下运动"],"concepts":["位移-时间图像","速度方向"]},{"title":"相似三角形求影长","type":"几何关系","judge":"用光源、小球、影子三点共线建立相似三角形，确定影子位移与两球位移的定量关系","why":"光沿直线传播，光源到小球的水平距离为 l，小球到屏的水平距离为 2l，构成相似三角形","do":"以光源为顶点作过小球的直线交屏于影子点，按水平距离比 l:(l+2l) 列相似比","expr":"\\frac{l}{3l}=\\frac{y_{\\text{源}}-y_{\\text{球}}}{y_{\\text{影}}-y_{\\text{球}}}","cues":["三点共线","相似三角形","水平距离一比三"],"concepts":["光的直线传播","相似三角形"]},{"title":"取极值时刻算最大位移","type":"临界条件","judge":"影子位移最大出现在光源与小球分别处于最低点和最高点的时刻","why":"两球位移反向且同时达到极值，此时分子最大、影子偏离平衡位置最远","do":"把光源位移取 -A、小球位移取 +A 代入相似比，解出影子位移","expr":"x_{\\text{影}}=5A","cues":["取最高最低点","位移反向最大","代极值算"],"concepts":["振幅","极值条件"]}],"524":[{"title":"电子在板间受力方向","type":"模型选择","judge":"判断电子在两板间做匀变速直线还是类平抛运动，即初速度方向与电场力方向是否共线","why":"电子带负电，电场力方向与场强方向相反；只有沿极板方向射出的电子才做类平抛，其余方向初速度与电场力不垂直","do":"取从 M 板逸出的电子为研究对象，画出初速度方向与电场力方向，判断是否垂直","expr":"","cues":["电子带负电","受力与初速不共线","做类平抛"],"concepts":["电场力方向","类平抛运动","负电荷"]},{"title":"到达 N 板动能与方向无关","type":"关系建立","judge":"判断到达 N 板时的动能是否与电子逸出方向有关","why":"电场力做功只由电势差和电荷量决定，与路径及初速度方向无关，动能定理给出动能增量恒为 eU","do":"对任意方向逸出的电子写动能定理，比较末动能表达式","expr":"E_{kN}=\\frac{1}{2}mv_m^2+eU","cues":["电场力做功只看电势差","与方向无关","动能定理"],"concepts":["动能定理","电场力做功","电势差"]},{"title":"最大侧移对应平行射出","type":"临界条件","judge":"判断哪种逸出方向的电子在沿板方向（y 方向）的位移最大","why":"沿板方向初速度分量最大时，在相同渡越时间内 y 方向位移最大，故取平行极板射出的电子","do":"取初速度平行极板、大小为 v_m 的电子，分别写 y 方向匀速和 x 方向匀加速方程","expr":"y=v_m t,\\quad d=\\frac{1}{2}\\frac{eU}{md}t^2","cues":["平行射出侧移最大","y方向匀速","x方向匀加速"],"concepts":["类平抛运动","分运动独立性","最大位移"]},{"title":"反向电压截止条件","type":"临界条件","judge":"判断加反向电压使电流恰好为零时，截止电压与最大初动能的关系","why":"电流为零意味着速度最大的光电子也恰好到不了 N 板，电场力做功恰好抵消最大初动能","do":"对最大初动能的光电子写动能定理并令末动能为零","expr":"eU_c=\\frac{1}{2}mv_m^2","cues":["恰好为零","最大初动能被抵消","截止电压"],"concepts":["遏止电压","动能定理","光电子最大初动能"]}],"525":[{"title":"由公式定波长长短","type":"关系建立","judge":"要判断 Hδ 与 Hγ 哪条谱线对应的 n 更大、波长更长","why":"巴耳末公式中 1/λ 随 n 增大而增大，故 n 越大波长越短；Hδ 对应 n=6、Hγ 对应 n=5，所以 Hγ 波长较长","do":"把 n=6 与 n=5 分别代入巴耳末公式比较 1/λ 的大小，再反推 λ 的大小关系","expr":"\\frac{1}{\\lambda}=R_\\infty\\left(\\frac{1}{2^2}-\\frac{1}{n^2}\\right)","cues":["n越大波长越短","先比波长","Hγ波长长"],"concepts":["巴耳末公式","氢原子光谱"]},{"title":"波长定频率与折射率","type":"前提判断","judge":"要判断由波长长短能否推出频率高低以及介质中折射率的大小","why":"真空中 c=λf，波长越长频率越低；同种介质对频率越低的光折射率越小","do":"由 λγ>λδ 得 fγ<fδ，再由频率高低比较两光在同一玻璃中的折射率","expr":"c=\\lambda f,\\quad n_{\\text{折}}=n(f)","cues":["波长长频率低","频率低折射率小","先定频率"],"concepts":["光速与频率","折射率"]},{"title":"单缝衍射条纹宽窄","type":"关系建立","judge":"要判断波长较长的光在同一单缝衍射装置中中央明纹是更宽还是更窄","why":"波长越长衍射现象越明显，中央明条纹越宽","do":"比较 λγ 与 λδ，直接得出中央明纹宽度的大小关系","expr":"","cues":["波长长衍射明显","中央条纹更宽","看衍射明显程度"],"concepts":["单缝衍射","衍射现象明显条件"]},{"title":"光子数与光强关系","type":"关系建立","judge":"要判断相同功率（相同光强）的细光束中，哪种光单位长度上的平均光子数更多","why":"每个光子能量 E=hf，功率相同时光子数由 E 决定，频率低的光子能量小、光子数多","do":"用 E=hf 比较两光单个光子能量，再由相同功率推光子数多少","expr":"E=hf=\\frac{hc}{\\lambda}","cues":["光子能量看频率","频率低光子多","相同功率比光子数"],"concepts":["光子能量","光强与光子数"]},{"title":"饱和光电流大小判断","type":"结论整理","judge":"要判断相同光强照射同一光电管时，哪种光产生的饱和光电流更大","why":"饱和光电流由单位时间到达阳极的光电子数决定，光子数越多（频率越低）饱和光电流越大","do":"由前面得到的光子数多少，直接比较两光的饱和光电流大小","expr":"I_{\\text{饱}}\\propto N_{\\text{光子}}","cues":["饱和电流看光子数","光子多电流大","频率低饱和电流大"],"concepts":["光电效应","饱和光电流"]}],"526":[{"title":"自感电动势的来源","type":"模型选择","judge":"电流随时间减小是由线圈自身电阻耗能引起的，还是由外加电源或外部磁场变化引起的","why":"超导线圈闭合、无外电源，电流衰减只能由自身电阻 R 与自感 L 共同决定，满足 ε=-L dI/dt=IR，这是全题唯一动力学方程","do":"把线圈看成 RL 回路，写出 ε=-L dI/dt 与 ε=IR 联立，消去 ε 得到 ΔI 与 R、L 的关系","expr":"-L\\frac{\\Delta I}{\\Delta t}=IR","cues":["看成RL回路","没有外电源","电流自己衰减"],"concepts":["自感电动势","欧姆定律","RL 回路"]},{"title":"自感系数用磁通定义","type":"关系建立","judge":"L 能否直接用题给的 B=kI 与线圈面积相乘得到，即 L=Φ/I=kS","why":"题设已把线圈内磁场近似为垂直线圈平面的匀强磁场 B=kI，磁通 Φ=BS 与 I 成正比，故 L=Φ/I=kS，无需另记长直螺线管公式","do":"取线圈所围面积 S=πr₂²，用 Φ=BS=kI·πr₂² 除以 I 得 L","expr":"L=\\frac{\\Phi}{I}=k\\pi r_2^{2}","cues":["用磁通定义自感","B是匀强的","面积取线圈围的面积"],"concepts":["磁通量","自感系数"]},{"title":"电阻用导线长度与截面","type":"几何关系","judge":"电阻 R 中的长度取线圈周长 2πr₂、截面取导线横截面 πr₁²，而不是把 r₁ 当线圈半径","why":"题给两个半径含义不同：r₂=1 cm 是线圈半径决定导线长度，r₁=1 mm 是导线横截面半径决定电阻截面，混用会使 R 差几个数量级","do":"写 R=ρL_wire/S_wire=ρ·2πr₂/(πr₁²)，化简为 2ρr₂/r₁²","expr":"R=\\rho\\frac{2\\pi r_2}{\\pi r_1^{2}}=\\frac{2\\rho r_2}{r_1^{2}}","cues":["两个半径别混","长度是周长","截面是导线截面"],"concepts":["电阻定律","横截面积"]},{"title":"数量级估算与单位换算","type":"数学处理","judge":"一年时间要换成秒，且结果只保留数量级时各量取一位有效数字即可","why":"题目只问数量级，ρ 只给上限、k 只给数量级，精确计算无意义，但时间单位不换算会差 10⁷ 量级","do":"取 Δt=365×24×3600 s，把 ρ、k、r₁、r₂ 都写成 10 的幂代入 ΔI 表达式，再回代 ε=IR 估数量级","expr":"\\Delta I=\\frac{I\\rho\\Delta t}{k\\pi r_2 r_1^{2}},\\quad \\varepsilon=IR","cues":["一年换成秒","只留数量级","都写成10的幂"],"concepts":["数量级估算","单位换算"]}],"527":[{"title":"黑体辐射与吸收的关系","type":"前提判断","judge":"相同温度下，黑体的吸收本领与辐射本领是否同时最强、二者是否由同一规律决定","why":"基尔霍夫辐射定律指出，同一温度下对任一波长，物体的发射率与吸收率之比都等于黑体的发射率，因此吸收越强的物体辐射也越强，黑体两者都最强","do":"把“黑体只善于辐射、不善于吸收”这类说法与基尔霍夫定律对照，判断该说法是否成立","expr":"","cues":["黑体只辐射","吸收和辐射分开看","温度相同就一样"],"concepts":["黑体","基尔霍夫辐射定律","热辐射"]},{"title":"德布罗意波长与质量的关系","type":"关系建立","judge":"动能相同时，德布罗意波长与粒子质量是正相关还是负相关","why":"由德布罗意关系与动能关系联立可得波长与质量平方根成反比，动能相同则质量越小波长越长","do":"写出波长与动量、动量与动能的关系式，比较电子与中子的质量大小，得出波长长短","expr":"$\\lambda=\\frac{h}{p}=\\frac{h}{\\sqrt{2mE_k}}$","cues":["质量大波长短","动能相同波长相同","电子波长更长"],"concepts":["德布罗意波","物质波","动能与动量"]},{"title":"电磁场的物质性","type":"前提判断","judge":"电磁场是真实物质还是仅为了描述方便而引入的数学工具","why":"电磁场具有能量、动量，能与实物相互作用并独立存在，是物质存在的一种形式","do":"判断“电磁场不是物质”这一说法是否与场的物质性相矛盾","expr":"","cues":["场是假想的","场没有质量","场也是物质"],"concepts":["电磁场","场的物质性","电磁波能量"]},{"title":"反射光的偏振性判断","type":"模型选择","judge":"自然光经玻璃、水面反射后，反射光是否成为部分偏振光（可视为偏振光）","why":"自然光在电介质表面反射时，垂直于入射面的振动分量被优先反射，反射光成为部分偏振光，透过偏振片转动时会出现明暗变化","do":"把反射光按部分偏振光处理，判断转动偏振片时透射光强是否变化","expr":"","cues":["反射光仍是自然光","偏振片转也没变化","反射光有偏振"],"concepts":["自然光","偏振光","偏振片"]}],"528":[{"title":"跨介质频率不变","type":"前提判断","judge":"波从介质Ⅰ进入介质Ⅱ时，哪个物理量保持不变","why":"频率由波源决定，与介质无关，只有波速和波长随介质改变","do":"用波源所在介质的波速和波长定出频率，再迁移到介质Ⅱ","expr":"f=\\frac{v}{\\lambda}","cues":["频率不变","波速变了","波长跟着变"],"concepts":["频率","波速","波长"]},{"title":"定介质Ⅱ波长与波峰位置","type":"关系建立","judge":"介质Ⅱ中波长变为多少，S点相对O的位置如何由'仅一个波峰'确定","why":"波速变为√2v而频率不变，波长按同比例放大；图示时刻只有一个波峰且该波峰过S，说明S到波源的距离恰为整数个波长","do":"先由v'=√2v、f不变求λ'，再由波峰条件定出S在y轴上的坐标","expr":"\\lambda'=\\frac{\\sqrt{2}v}{f}=\\sqrt{2}\\lambda","cues":["先求新波长","波峰在S","只有一个波峰"],"concepts":["波长","波速","波峰"]},{"title":"由波峰条件反推R位置","type":"几何关系","judge":"R点也是波峰时，P到R的波程与P到O的波程相差几个波长","why":"R、S同处一个波峰（同一波面），波从P传到R与传到O的相位差由波程差决定，波峰对应波程差为整数个波长","do":"用PR−PO为整数倍λ，结合P、O坐标解出OR长度","expr":"PR=PO+\\lambda=5\\lambda,\\ OR=\\sqrt{PR^{2}-PO^{2}}=3\\lambda","cues":["R也是波峰","波程差整数倍","用勾股定OR"],"concepts":["波程差","波面","几何关系"]},{"title":"判断M点干涉强弱","type":"临界条件","judge":"M点是振动加强点还是减弱点，取决于两列波到M的波程差是半波长的奇数倍还是偶数倍","why":"相干加强/减弱的判据是波程差等于nλ（加强）或(2n+1)λ/2（减弱），不能凭直觉","do":"算出PM与OM的波程差，与半波长整数倍比较","expr":"\\Delta=PM-OM","cues":["算波程差","比半波长","看奇偶倍"],"concepts":["干涉加强","干涉减弱","波程差"]},{"title":"折射定律求入射角","type":"关系建立","judge":"入射角的正弦与折射角的正弦之比等于两介质中波速之比（即折射率）","why":"波在界面折射时满足sin i/sin r=v₁/v₂，折射角可由OR与PR的几何关系给出","do":"由n=λ'/λ=√2，结合sin r=OR/PR求sin i","expr":"n=\\frac{\\sin i}{\\sin r}=\\frac{\\lambda'}{\\lambda}=\\sqrt{2},\\ \\sin r=\\frac{OR}{PR}","cues":["用折射定律","折射率看波速比","折射角由几何定"],"concepts":["折射定律","折射率","入射角"]}],"529":[{"title":"确定三个量关系的研究方法","type":"前提判断","judge":"面对加速度、力、质量三个量同时变化，应判断用哪种实验研究方法","why":"三个变量同时变化无法单独看出任一因素的影响，必须固定其中一个再研究另两个的关系","do":"对照各方法的定义，选出固定一个量、改变另一个量的做法","expr":"","cues":["固定一个量","一个一个来","控制变量"],"concepts":["控制变量法"]},{"title":"判断补偿阻力与打点操作","type":"实验操作","judge":"补偿阻力时纸带是否要连、接通电源与释放小车的先后、细绳应与哪条线平行","why":"纸带阻力也需一并平衡，且要靠纸带点距判断是否匀速；先放小车会丢失起始点；拉力方向须与运动方向一致","do":"逐条对照操作规范，检查纸带连接、电源顺序、细绳与长木板是否平行","expr":"","cues":["纸带要连上","先通电后放车","绳与木板平行"],"concepts":["补偿阻力","打点计时器","操作规范"]},{"title":"拉力近似等于槽码重力的条件","type":"近似条件","judge":"要判断小车质量与槽码质量满足什么大小关系时，绳中拉力才可近似等于槽码重力","why":"对小车和槽码分别列牛顿第二定律，联立得绳拉力随质量比变化，只有小车质量远大于槽码质量时拉力才趋近槽码重力","do":"对小车和槽码分别列方程，解出绳中拉力的表达式，再取质量比极限","expr":"$F=\\frac{Mmg}{M+m}$","cues":["小车质量远大于","取整体看加速度","绳拉力不等于重力"],"concepts":["牛顿第二定律","近似条件","系统误差"]},{"title":"区分误差类型并选改进方案","type":"误差分析","judge":"用槽码重力代替绳拉力带来的误差属于哪一类，以及哪种改进能真正消除它","why":"该误差源于实验原理的近似，不随多次测量减小，属系统误差；只有直接测出绳拉力才能消除","do":"判断误差来源是原理缺陷还是测量偶然，再比较各方案是否直接测量了小车所受拉力","expr":"","cues":["原理不完善","系统误差","加力传感器直接测"],"concepts":["系统误差","力传感器"]},{"title":"确定计数点时间间隔与逐差法","type":"关系建立","judge":"相邻计数点之间隔了几个打点周期，以及用哪几段位移求瞬时速度和加速度","why":"纸带按每 5 个间隔取计数点，故相邻计数点时间间隔为 5T；速度用中间时刻的平均速度，加速度用逐差法消除初速度影响","do":"先数清计数点间的时间间隔，再用计数点 4、6 间的平均速度求点 5 速度，用相隔 3 段的两组位移差求加速度","expr":"$v=\\frac{x_6-x_4}{10T}$，$a=\\frac{x_6-2x_3}{(15T)^2}$","cues":["间隔是五个周期","中间时刻速度","逐差法"],"concepts":["匀变速直线运动","逐差法","瞬时速度"]},{"title":"由充电电流方向判断放电偏转","type":"模型选择","judge":"开关从 1 拨到 2 后，电容器放电电流方向与充电时相反，微安表指针应向哪侧偏转、示数如何变化","why":"充电时电流流入电容器一侧，放电时电荷反向流出，流过微安表的电流反向；且放电电流随电荷减少而衰减","do":"比较充电与放电时流过微安表的电流方向，判断指针偏转方向，再由放电过程电荷减少判断示数变化","expr":"","cues":["放电电流反向","指针向左偏","示数逐渐减小"],"concepts":["电容器充放电","电流方向"]},{"title":"稳定电流下求电压表内阻","type":"关系建立","judge":"微安表示数稳定时电容器相当于断路，此时回路中只剩电阻箱、微安表与电压表串联，应据此求电压表内阻","why":"充电结束电容器中无电流，干电池电压按电阻比例分配在电阻箱和电压表上，由总电流可求总电阻","do":"读电压表读数，用电动势除以稳定电流得总电阻，再按电压比分配求电压表内阻","expr":"$R+R_V=\\frac{E}{I}$，$\\frac{R}{R_V}=\\frac{E-U}{U}$","cues":["电容器相当于断路","串联分压"],"concepts":["闭合电路欧姆定律","串联分压","电压表内阻"]},{"title":"选择温控电路与定值电阻","type":"临界条件","judge":"要判断哪种电路在温度低于设定值时 1、2 两端电压能超过 2 V，以及定值电阻取哪个阻值","why":"热敏电阻温度越低阻值越大，只有让热敏电阻与定值电阻串联且 1、2 取热敏电阻两端电压，低温时电压才升高触发加热","do":"比较三种电路的连接方式，选热敏电阻分压随温度降低而升高的接法，再用 20 ℃ 时的阻值代入分压式求定值电阻","expr":"$\\frac{R_t}{R_t+R}E=2\\,\\mathrm{V}$","cues":["低温阻值大","热敏电阻分压","串联分压式"],"concepts":["热敏电阻","串联分压","临界条件"]}],"530":[{"title":"判断扩散过程是否可逆","type":"前提判断","judge":"气体向真空自由扩散后能否自发回到原状态，即过程是否可逆","why":"热力学第二定律指出，一切与热现象有关的实际宏观过程都是不可逆的，自由扩散没有外界做功补偿就无法逆转","do":"对照可逆过程的定义（无耗散、准静态、能沿原路返回），判断隔板抽去后气体充满两室的过程","expr":"","cues":["向真空扩散","没有外界干预","自发过程"],"concepts":["热力学第二定律","可逆过程"]},{"title":"判断自由扩散的温度变化","type":"关系建立","judge":"气体向真空扩散时是否做功、是否吸放热，从而判断内能和温度如何变化","why":"左侧为真空，气体膨胀时不受阻力，对外不做功；绝热容器又无热交换，由热力学第一定律得内能不变","do":"对状态1到状态2用热力学第一定律，取W=0、Q=0，得ΔU=0，再由理想气体内能只与温度有关推出温度不变","expr":"ΔU=Q+W=0","cues":["真空不做功","绝热无热交换","内能不变"],"concepts":["热力学第一定律","理想气体内能","温度"]},{"title":"用等温规律求状态2压强","type":"关系建立","judge":"状态1到状态2温度不变，能否用玻意耳定律由体积加倍求压强","why":"自由扩散前后温度相同（内能不变），一定质量理想气体等温变化满足pV=常量","do":"对状态1、2列玻意耳定律，体积由V1变为2V1，解出p2","expr":"p_{1}V_{1}=p_{2}\\cdot 2V_{1}","cues":["温度没变","体积变两倍","压强减半"],"concepts":["玻意耳定律","等温变化"]},{"title":"选活塞为对象定受力平衡","type":"模型选择","judge":"求恒力F时应以活塞B为研究对象，判断它受哪几个压力并列出平衡方程","why":"活塞被锁定保持静止，合力为零；活塞两侧分别受气体压强和大气压强作用，外加水平恒力F","do":"对活塞B画受力分析，比较左右两侧压力大小，列水平方向平衡方程解F","expr":"p_{2}S=p_{0}S+F","cues":["取活塞","两侧压强差","静止合力为零"],"concepts":["受力平衡","压强与压力"]},{"title":"判断加热过程为等压","type":"模型选择","judge":"加热时活塞缓慢滑动，气体压强是否保持不变","why":"活塞缓慢移动且无摩擦，任一时刻仍受力平衡，F、p0、S均不变，故气体压强恒为p2","do":"确认滑动过程中活塞始终平衡，压强不变，对状态2到状态3用盖-吕萨克定律","expr":"\\frac{2V_{1}}{T_{1}}=\\frac{V_{3}}{T_{2}}","cues":["缓慢滑动","无摩擦","压强不变"],"concepts":["等压变化","盖-吕萨克定律"]},{"title":"用第一定律求吸收热量","type":"关系建立","judge":"求电阻丝放热需先算气体对外做功，再判断ΔU、W、Q的正负号关系","why":"等压膨胀气体对外做功W=p2ΔV，内能增加ΔU已知，由热力学第一定律ΔU=-W+Q'求吸收热量，电阻丝放热等于气体吸热","do":"先由V3减2V1求体积增量算W，再代入ΔU=-W+Q'解Q'，最后令Q=Q'","expr":"W=p_{2}(V_{3}-2V_{1}),\\quad \\Delta U=-W+Q'","cues":["等压膨胀做功","内能增加","放热等于吸热"],"concepts":["热力学第一定律","等压做功","能量守恒"]}],"531":[{"title":"C点速度的来路","type":"模型选择","judge":"从A到第一次经过C，机械能是否守恒、该用哪段高度差","why":"AB、BCD均光滑，只有重力做功，支持力不做功，机械能守恒；C点比A点低 h 还是低 h 需按几何定出竖直落差","do":"取A到C过程列机械能守恒，写出C点速度平方与下落竖直高度的关系","expr":"mgh=\\frac{1}{2}mv_C^2","cues":["轨道光滑","只有重力做功","用机械能守恒"],"concepts":["机械能守恒","向心加速度"]},{"title":"DE上能否自行下滑","type":"临界条件","judge":"物块在DE最高点速度为零后，重力沿斜面分量与最大静摩擦力谁大","why":"最大静摩擦力等于滑动摩擦力，若下滑分量大于最大静摩擦则必然下滑，否则会停在DE上，后续总路程与时间比全变","do":"比较 mg sinθ 与 μ2 mg cosθ 的大小","expr":"mg\\sin\\theta \\;\\text{vs}\\; \\mu_2 mg\\cos\\theta","cues":["比较下滑力和摩擦力","会不会停在斜面上"],"concepts":["最大静摩擦力","斜面受力分析"]},{"title":"最终往复区间的判定","type":"前提判断","judge":"机械能不断损失后，物块最终在哪个范围内往复运动","why":"每次上下DE都损耗机械能，直到剩余能量不足以再冲上DE，只能在光滑的B、D之间往复，这是用功能关系求总路程的前提","do":"判断能量耗尽后物块能到达的最高点是否低于D点，确定终态在BD段","expr":"","cues":["最后在圆弧里来回","上不去DE了","能量被摩擦耗光"],"concepts":["功能关系","能量耗散"]},{"title":"总路程按上下各半计","type":"关系建立","judge":"DE上每次上滑与下滑的距离是否相等，总路程如何与单程距离挂钩","why":"每次上滑到最高点再滑回同一起点，上升段与下降段路程相等，故总路程等于单程总距离的两倍，摩擦力的功要按两段不同μ分别累加","do":"设DE上单程累计距离为 s/2，对上升段用μ1、下降段用μ2分别写摩擦生热，与重力势能减少量相等","expr":"mg[h-R(1-\\cos\\theta)]=(\\mu_1+\\mu_2)mg\\cos\\theta\\cdot\\frac{s}{2}","cues":["上去下来一样长","摩擦力两段不一样","按单程算再乘二"],"concepts":["功与能","摩擦生热","路程与位移"]},{"title":"上下时间比的等效处理","type":"数学处理","judge":"多次上滑下滑的时间比能否用一次完整上滑下滑等效代替","why":"每段上滑初末速度对应同一高度差，加速度恒定，各次上滑时间之和与一次从静止滑下同样距离的时间满足同一运动学比例","do":"分别求上滑、下滑的加速度大小，用位移相等 ½a上t上²=½a下t下² 建立时间比","expr":"a_{\\text{上}}=g\\sin\\theta+\\mu_1g\\cos\\theta,\\quad a_{\\text{下}}=g\\sin\\theta-\\mu_2g\\cos\\theta","cues":["等效成一次","加速度不同","位移一样"],"concepts":["牛顿第二定律","匀变速直线运动"]},{"title":"不脱离滑块的临界","type":"临界条件","judge":"物块与滑块相对滑动的极限情形是恰好到达挡板前共速，还是滑出右端","why":"滑块足够长时物块在滑块上往返滑动，摩擦生热消耗相对动能，恰好不脱离对应相对速度刚减为零时物块到达滑块边缘，此时二者共速","do":"对a与b系统用动量守恒求共速，再用能量守恒把相对滑动路程与滑块长度联系","expr":"mv_F=2mv,\\quad \\tfrac12 mv_F^2=\\tfrac12(2m)v^2+2\\mu_1 mgl","cues":["恰好不脱离","共速时到边缘","相对滑动生热"],"concepts":["动量守恒","能量守恒","相对位移"]}],"532":[{"title":"静止时线圈是否受力","type":"前提判断","judge":"平台静止时线圈中有无感应电流、是否受安培力","why":"磁通量不变则不产生感应电动势，线圈不受安培力，弹簧只需平衡重力","do":"判断静止时穿过线圈的磁通量不变，安培力为零，再对平台用胡克定律","expr":"k\\Delta x=mg","cues":["静止没电流","磁通量不变","只平衡重力"],"concepts":["电磁感应条件","胡克定律","平衡条件"]},{"title":"辐向磁场切割长度","type":"几何关系","judge":"线圈在辐向磁场中运动时，切割磁感线的有效长度取什么","why":"辐向磁场处处与线圈圆周垂直，整圈导线都在切割，有效长度是圆周长而非直径","do":"写出每个线圈的有效切割长度，再代入动生电动势公式","expr":"L=2\\pi r,\\quad E=BLv_0","cues":["取周长","整圈都在切割","不是直径"],"concepts":["动生电动势","辐向磁场","有效长度"]},{"title":"单线圈安培力与总质量区分","type":"模型选择","judge":"求的是每个线圈的安培力还是三个线圈的总安培力","why":"题问每个线圈受力，而质量 m 是平台加三个线圈的总质量，两者不能混用","do":"先用单线圈电流和单根导线长度算一个线圈的安培力，再乘 3 才得总阻力","expr":"F=BIL=\\frac{B^2L^2v_0}{R}=\\frac{4\\pi^2r^2B^2v_0}{R}","cues":["先算一个线圈","最后乘三","别拿总质量"],"concepts":["安培力","电阻","单对象分析"]},{"title":"用能量守恒求总焦耳热","type":"关系建立","judge":"0到t1内减少的机械能转化为什么，初末动能与势能如何取","why":"阻尼振动中机械能减少量全部转化为焦耳热，初态速度 v0、末态振幅 A1 处速度为零","do":"取平衡位置为势能零点，比较 t=0 与 t1 时刻的总机械能，差值即三线圈总焦耳热","expr":"Q_{\\text{总}}=\\frac12mv_0^2-\\frac12kA_1^2","cues":["机械能减少量","末态速度为零","平衡位置定零势能"],"concepts":["能量守恒","阻尼振动","弹性势能"]},{"title":"安培力冲量化为位移","type":"数学处理","judge":"变力安培力的冲量能否用速度对时间的累积换成位移","why":"安培力正比于速度，对时间求和时 ΣvΔt 就是位移，从而避开对变力直接积分","do":"写出总安培力冲量表达式，把速度对时间的累积替换为 t1 到 t2 的位移大小","expr":"I_A=\\frac{12\\pi^2r^2B^2}{R}\\sum v\\Delta t=\\frac{12\\pi^2r^2B^2}{R}(A_1-A_2)","cues":["力正比速度","求和变位移","用振幅差"],"concepts":["变力冲量","微元求和","安培力"]},{"title":"动量定理定正方向","type":"关系建立","judge":"t1到t2内对平台用动量定理时，各冲量的正负号如何取","why":"初末速度均为零，动量变化为零，弹力冲量、重力冲量、安培力冲量必须按统一正方向代数相加","do":"规定向上为正，列动量定理方程，把重力冲量与安培力冲量移到等号另一侧求弹力冲量","expr":"I_{\\text{弹}}+I_A-mg(t_2-t_1)=0","cues":["向上为正","初末速度都为零","冲量带符号"],"concepts":["动量定理","冲量","正方向规定"]}],"533":[{"title":"反射的临界几何","type":"临界条件","judge":"质子从 Ⅰ 区右侧射出实现反射的临界条件是什么","why":"磁场只改变方向不改变速率，轨迹为半径 r 的圆弧，要从右边界射出必须让圆弧在宽度 d 内完成转向，d 太小时质子会从右侧穿出而不是折返","do":"画出质子从 O 入射到 P 出射的圆弧轨迹，找出圆弧与右边界相切（或恰好到达右边界）的极限情形，把 d 与 r 比较","expr":"r=\\frac{mv_{0}}{eB},\\quad d_{\\min}=r","cues":["轨迹是圆弧","刚好擦着右边界","半径等于宽度"],"concepts":["洛伦兹力","圆周运动半径","临界轨迹"]},{"title":"分解速度定不变量","type":"关系建立","judge":"穿过 Ⅱ 区时哪个速度分量守恒、哪个分量被电场改变","why":"Ⅱ 区宽度很小，电场只沿法线（水平）方向做功，切向（竖直）方向不受力，故切向速度不变；而动能定理给出总速率变化","do":"把速度分解为沿边界方向和垂直边界方向，对垂直分量用动能定理，对平行分量写守恒式","expr":"v_{0}\\sin\\theta=v_{1}\\sin\\theta',\\quad eU=\\frac12 mv_{1}^{2}-\\frac12 mv_{0}^{2}","cues":["沿边界速度不变","电场只改法向","先分解再算"],"concepts":["速度分解","动能定理","电场做功"]},{"title":"折射率由速率比定","type":"结论整理","judge":"折射率是否等于两侧速率之比","why":"由切向速度守恒 v0 sinθ = v1 sinθ' 直接得 sinθ/sinθ' = v1/v0，与光学中 n=c/v 的形式一致","do":"联立动能定理求 v1，再与速度守恒式相除得 n","expr":"n=\\frac{\\sin\\theta}{\\sin\\theta'}=\\frac{v_{1}}{v_{0}}","cues":["正弦比等于速度比","先求末速度","类比光的折射"],"concepts":["折射率","速度分解"]},{"title":"全反射的临界条件","type":"临界条件","judge":"全反射的临界是法向速度恰好减为零还是总速度为零","why":"质子要返回 Ⅰ 区，必须让垂直边界方向的速度被电场减速到零后反向，切向速度始终保留，故临界时法向分量为零而总速率不为零","do":"令末态法向速度为零，用动能定理求对应的电势差，再判断 U 取何范围满足全反射","expr":"eU=0-\\frac12 m(v_{0}\\cos\\theta)^{2}","cues":["法向速度减到零","切向速度还在","临界不是停下"],"concepts":["全反射","动能定理","临界条件"]},{"title":"两束对称粒子的落板判定","type":"几何关系","judge":"两束对称质子中哪些能打到探测板、打在板的哪一段","why":"两束质子关于法线对称，出射后沿直线运动，能否落板取决于出射方向与板端点 C、D 的连线几何关系，需分别对两侧束作射线判断","do":"由 P 点位置和板长、板距算出 PC、PD 与法线的夹角，与各束出射方向比较，确定临界角 30° 与 60°","expr":"\\tan\\angle CPQ=\\frac{CQ}{PQ}","cues":["先算板端点张角","对称两束分开看","临界角三十和六十"],"concepts":["几何关系","直线运动","对称性"]},{"title":"分区间求冲量再化力","type":"数学处理","judge":"不同 U 区间内落板束数与每束的竖直动量如何合成总力","why":"力等于单位时间被吸收的竖直动量，只有落板质子贡献；U 正负决定折射角大小，从而决定是一束还是两束落板，需分段讨论","do":"按 U≥0、临界值之间、更负三个区间分别数落板束数，用 eU 与竖直速度关系求 vy，再乘 N 与束数","expr":"F=2Nmv_{y},\\quad eU=\\frac12 mv_{y}^{2}-\\frac12 m(v_{0}\\cos\\theta)^{2}","cues":["力等于动量变化率","分段讨论","两束都打就乘二"],"concepts":["动量定理","分段讨论","动量流"]}],"534":[{"title":"矢量判据","type":"前提判断","judge":"判断一个物理量是否为矢量，依据是它既有大小又有方向，且相加时遵守平行四边形法则，而不是只看它有没有方向","why":"矢量的本质是方向参与运算，即按平行四边形法则合成；只有方向而不按此法则合成的量仍是标量","do":"对每个待判物理量，先看它有没有方向，再看它的合成法则是否为平行四边形法则，两个条件都满足才判为矢量","expr":"","cues":["看合成法则","有方向还不够","要按平行四边形"],"concepts":["矢量","标量","平行四边形法则"]},{"title":"电流的方向陷阱","type":"模型选择","judge":"判断电流虽有方向，但它的运算是否按平行四边形法则进行","why":"电流的方向只表示电荷定向移动的指向，两路电流汇合时按算术相加，不满足平行四边形法则，所以电流是标量","do":"把电流与位移对比：两者都有方向，但电流合成用算术加法，位移合成用平行四边形法则，据此区分","expr":"","cues":["电流有方向","方向不参与合成","算术相加"],"concepts":["电流","标量","矢量"]},{"title":"无方向即标量","type":"结论整理","judge":"判断时间和热量是否具有方向","why":"标量的判据是只有大小、没有方向，时间和热量都只由数值和单位描述，没有方向","do":"检查时间和热量的定义中是否含方向要素，确认二者均为标量","expr":"","cues":["时间没方向","热量没方向","只有大小"],"concepts":["时间","热量","标量"]}],"535":[{"title":"腾空时受力分析","type":"前提判断","judge":"小猫或蝴蝶在空中是否与其他物体接触、受哪些力","why":"弹力（支持力、压力）的产生条件是物体间直接接触并挤压，腾空后无接触即无弹力；蝴蝶飞行时与空气有相对运动，受空气作用力","do":"对腾空的小猫和飞行的蝴蝶分别做受力分析，检查有无接触物体","expr":"","cues":["空中没接触","只受重力","还有空气"],"concepts":["弹力产生条件","受力分析"]},{"title":"曲线运动合力方向","type":"关系建立","judge":"蝴蝶转弯做曲线运动时，合力方向与速度方向是否共线","why":"物体做曲线运动的条件是合力方向与速度方向不在同一直线上，合力指向轨迹凹侧","do":"比较蝴蝶转弯时合力方向与瞬时速度方向是否在同一直线","expr":"","cues":["转弯是曲线","合力指向凹侧","不在一条线"],"concepts":["曲线运动条件","合力与速度"]},{"title":"蹬地起跳的加速度方向","type":"模型选择","judge":"小猫蹬地跃起的过程中加速度方向朝上还是朝下","why":"起跳时速度由零增大，加速度向上，由牛顿第二定律知合力向上","do":"取小猫为研究对象，判断起跳瞬间速度变化方向，确定加速度方向","expr":"a=\\frac{\\Delta v}{\\Delta t}>0\\ (\\text{向上})","cues":["起跳加速","加速度向上","速度变大"],"concepts":["加速度方向","牛顿第二定律"]},{"title":"弹力与重力大小比较","type":"关系建立","judge":"蹬地时地面对小猫的弹力与小猫重力的大小关系","why":"加速度向上时合力向上，弹力减重力为合力，故弹力大于重力","do":"对小猫列竖直方向牛顿第二定律方程，比较弹力与重力","expr":"N-mg=ma>0\\Rightarrow N>mg","cues":["合力向上","弹力减重力","弹力更大"],"concepts":["牛顿第二定律","超重"]}],"536":[{"title":"水流导光靠全反射","type":"模型选择","judge":"光在水柱中传播到水—空气界面时，是折射出射还是发生全反射","why":"光从光密介质（水）射向光疏介质（空气），入射角大于临界角时发生全反射，光被限制在水柱内传播，这是水流能导光的物理机制","do":"比较光在水—空气界面的入射角与临界角，判断是否满足全反射条件","expr":"\\sin C=\\frac{1}{n}","cues":["光密到光疏","入射角够大","全反射","临界角"],"concepts":["全反射","临界角","光密介质"]},{"title":"介质中光速的比较","type":"关系建立","judge":"光在水中的传播速度与在空气中的传播速度谁大","why":"由折射率定义 n=c/v，水的折射率大于空气，故光在水中速度小于真空中速度","do":"用 v=c/n 比较水与空气（近似真空）中的光速","expr":"v=\\frac{c}{n}","cues":["折射率越大速度越小","水中光速变慢"],"concepts":["折射率","光速"]},{"title":"水流的运动性质","type":"模型选择","judge":"离开出水口后水在空中受什么力、做什么运动","why":"水离开出水口后只受重力（忽略空气阻力），初速度水平，故为平抛运动，是匀变速曲线运动","do":"对水做受力分析，确认只受重力且初速度水平","expr":"","cues":["只受重力","平抛运动","匀变速曲线"],"concepts":["平抛运动","重力","匀变速曲线运动"]},{"title":"平抛速度与水平分运动","type":"关系建立","judge":"水在空中的速度大小如何变化、水平方向做什么运动","why":"平抛运动中水平方向不受力做匀速直线运动，竖直方向自由落体使合速度不断增大","do":"分解速度：水平分速度不变，竖直分速度增大，合速度增大","expr":"v_x=v_0,\\quad v_y=gt,\\quad v=\\sqrt{v_x^2+v_y^2}","cues":["水平匀速","竖直加速","合速度变大"],"concepts":["运动的分解","平抛运动","速度合成"]}],"537":[{"title":"守恒律定未知核","type":"前提判断","judge":"核反应与衰变中应依据哪两条守恒来确定未知粒子","why":"核反应和衰变都满足质量数守恒与电荷数守恒，这是确定未知核组成成分的唯一依据","do":"对两个方程分别列出质量数方程和电荷数方程，解出 X 和 Y 的质量数与电荷数","expr":"4+9=A_X+1,\\quad 2+4=Z_X+0;\\quad 238=A_Y+234,\\quad 94=Z_Y+92","cues":["数质量数","数电荷数","两个都守恒"],"concepts":["质量数守恒","电荷数守恒","核反应方程"]},{"title":"由核子数认元素","type":"结论整理","judge":"由求出的质量数与电荷数能否对应到具体元素符号","why":"电荷数（质子数）决定元素种类，质量数减质子数得中子数，据此才能写出 X、Y 的核符号","do":"把 Z、A 对应到元素周期表中的元素，写出 X 与 Y 的完整核符号","expr":"^{A}_{Z}\\mathrm{X}","cues":["看质子数定元素","碳还是氦","中子数不用管"],"concepts":["质子数","元素符号","核素"]},{"title":"辨明中子与α粒子","type":"模型选择","judge":"方程中的中子与 Y 粒子各是什么、质量数电荷数各为多少","why":"中子质量数为 1、电荷数为 0；α 粒子即氦核，质量数 4、电荷数 2，混淆二者会直接选错","do":"写出中子和 α 粒子的核符号，与求得的 Y 对照","expr":"^{1}_{0}n,\\quad ^{4}_{2}\\mathrm{He}","cues":["中子不带电","α是氦核","别把中子当质子"],"concepts":["中子","α 粒子","氦核"]},{"title":"衰变伴随质量亏损","type":"关系建立","judge":"自发衰变过程是吸能还是放能、质量是否守恒","why":"衰变后总静质量减小，质量亏损按质能方程转化为释放的能量，故质量数守恒但质量不守恒","do":"","expr":"\\Delta E=\\Delta m c^{2}","cues":["衰变放能","质量有亏损","质量数才守恒"],"concepts":["质量亏损","质能方程","衰变放能"]}],"538":[{"title":"功率对应动能增加率","type":"模型选择","judge":"喷水功率该用动能变化率还是重力做功或其他能量来算","why":"喷头把静止的水加速到喷出速度，功率等于单位时间内赋予水的动能，水离开喷口后不再被喷头做功","do":"把喷头做功与喷出水的动能增量对应起来，写出功率等于动能除以时间","expr":"P=\\frac{\\frac{1}{2}mv^{2}}{\\Delta t}","cues":["算动能变化","用动能除以时间","不是算重力势能"],"concepts":["功率","动能定理"]},{"title":"质量流量用密度截面速度","type":"关系建立","judge":"单位时间内喷出的水的质量由哪些量决定","why":"连续流体在时间 Δt 内流出的体积是以截面积为底、vΔt 为长的柱体，质量等于密度乘体积","do":"写出 Δt 内流出水的质量表达式，再除以 Δt 得质量流量","expr":"m=\\rho S v\\Delta t,\\quad \\frac{m}{\\Delta t}=\\rho S v","cues":["质量等于密度乘体积","柱体体积是底乘长","先求每秒出多少水"],"concepts":["质量流量","连续性"]},{"title":"消去时间再代数据","type":"数学处理","judge":"Δt 是否会在功率表达式中消去，能否直接用题给数据算","why":"功率是单位时间的量，与所取时间间隔无关，Δt 在分子分母中约掉","do":"把质量表达式代入功率式约去 Δt，得到只含 ρ、S、v 的式子再代入数值","expr":"P=\\frac{1}{2}\\rho S v^{3}","cues":["时间会约掉","只跟密度截面速度有关","速度要立方"],"concepts":["功率","量纲"]}],"539":[{"title":"确定静电计测什么","type":"前提判断","judge":"静电计指针张角反映的是极板间电势差还是电荷量","why":"静电计与电容器并联，张角随两板间电势差变化，而题设已说明电荷量保持不变","do":"把张角变化直接对应到极板间电势差 U 的变化，不把张角当成电荷量的量度","expr":"","cues":["张角看电压","电荷量不变","张角变大电压大"],"concepts":["静电计","电势差"]},{"title":"电容随间距的变化","type":"关系建立","judge":"极板间距增大时电容是增大还是减小","why":"平行板电容器电容由正对面积、间距和介质决定，间距在分母上","do":"写出电容决定式，看 d 增大时 C 的变化趋势","expr":"C=\\frac{\\varepsilon S}{4\\pi kd}","cues":["间距大电容小","电容反比于间距","先看电容变不变"],"concepts":["平行板电容器","电容决定式"]},{"title":"电荷不变下电压走向","type":"关系建立","judge":"Q 不变而 C 减小时，极板间电势差如何变化","why":"电荷量、电容、电压满足 Q=CU，Q 固定时 U 与 C 成反比","do":"由 Q=CU 联立电容决定式，判断 U 随 d 增大的方向，并与张角增大相互印证","expr":"Q=CU\\Rightarrow U=\\frac{Q}{C}=\\frac{4\\pi kQd}{\\varepsilon S}","cues":["电荷不变电压升","电压反比于电容","跟张角变大对得上"],"concepts":["Q=CU","电荷量守恒"]},{"title":"场强是否随间距改变","type":"关系建立","judge":"d 增大、U 也增大时，板间匀强电场场强是变大、变小还是不变","why":"场强由 U 与 d 的比值决定，而 U 正比于 d，两者之比与 d 无关","do":"把 U 的表达式代入 E=U/d，消去 d 后看 E 由哪些量决定","expr":"E=\\frac{U}{d}=\\frac{4\\pi kQ}{\\varepsilon S}","cues":["电压除间距","场强跟间距无关","只看面电荷密度"],"concepts":["匀强电场","场强与电势差关系"]},{"title":"能量变化的判断","type":"关系建立","judge":"拉开极板过程中电容器储存的电场能是增大还是减小","why":"极板间相互吸引，拉开时外力克服电场力做正功，能量由外界输入","do":"比较拉开前后由 Q 与 C 算出的储能，或用外力做正功判断能量增加","expr":"W=\\frac{Q^2}{2C}","cues":["克服电场力做功","外力做正功","能量变大"],"concepts":["电场能","功能关系"]}],"540":[{"title":"副线圈电压由匝比决定","type":"模型选择","judge":"副线圈两端电压是否随负载支路变化而改变","why":"理想变压器副线圈电压只由原线圈电压和匝数比决定，与副线圈接什么负载无关，所以各支路电压在切换元件时保持不变","do":"写出变压比关系，确认改变电容、频率、光照时副线圈电压不变","expr":"$\\frac{U_1}{U_2}=\\frac{n_1}{n_2}$","cues":["电压不变","看匝数比","副线圈电压固定"],"concepts":["理想变压器","变压比"]},{"title":"区分电容电感频率效应","type":"关系建立","judge":"电容、电感对交流电的阻碍随电容大小和频率如何变化","why":"电容容抗随电容增大、频率升高而减小；电感感抗随频率升高而增大，两者规律相反，混淆就会判断反","do":"分别写出容抗和感抗的表达式，比较电容增大、频率增大时各自的变化方向","expr":"$X_C=\\frac{1}{2\\pi fC},\\quad X_L=2\\pi fL$","cues":["电容通高频","电感阻高频","容抗感抗"],"concepts":["容抗","感抗","交流电频率"]},{"title":"支路独立判断亮度","type":"结论整理","judge":"某支路元件变化时，是只看本支路电流还是受其他支路影响","why":"三个支路并联接在副线圈两端，电压相同且互不影响，所以每条支路的电流只由本支路阻抗决定","do":"对每条支路用欧姆定律算电流，电流增大则灯变亮","expr":"$I=\\frac{U_2}{Z}$","cues":["并联互不影响","各看各的","电压相同"],"concepts":["并联电路","欧姆定律"]},{"title":"光敏电阻阻值方向","type":"前提判断","judge":"光照增强时光敏电阻阻值变大还是变小","why":"光敏电阻受光照增强时阻值减小，若记反方向，L3 亮度变化就判反","do":"由光照增强推出阻值减小，再由电压不变推出该支路电流增大","expr":"","cues":["光照强电阻小","光敏变小","越亮越导通"],"concepts":["光敏电阻","半导体特性"]},{"title":"开关换接改变匝比","type":"临界条件","judge":"S 从 a 接到 b 时原线圈匝数是增是减，副线圈电压如何变","why":"接 b 时接入的原线圈匝数减少，由变压比得副线圈电压升高，三灯同时变亮，这是与前面单支路变化的本质区别","do":"比较 a、b 两位置原线圈匝数，代入变压比判断副线圈电压升降","expr":"$U_2=\\frac{n_2}{n_1}U_1$","cues":["匝数变少","电压升高","三灯一起变"],"concepts":["匝数比","副线圈电压"]}],"541":[{"title":"轨道半长轴由切点定","type":"几何关系","judge":"甲、乙的椭圆轨道半长轴能否用地球轨道半径 R 与 R1、R2 表示","why":"甲轨道与地球轨道外切于近日点、乙轨道与地球轨道内切于远日点，切点处两轨道到太阳距离相等，都是 R","do":"画出日心到切点的连线，把甲轨道的近日点距离取为 R、远日点距离取为 R1，乙轨道远日点距离取为 R、近日点距离取为 R2，再取两端距离的平均值作为半长轴","expr":"a_甲=\\frac{R+R_1}{2},\\quad a_乙=\\frac{R+R_2}{2}","cues":["切点距离等于地球半径","半长轴取两端平均","外切是近日点","内切是远日点"],"concepts":["椭圆轨道","半长轴","相切几何关系"]},{"title":"周期比用开普勒第三定律","type":"关系建立","judge":"比较甲、乙的周期该用哪个量作桥梁","why":"两星都绕同一太阳运行，开普勒第三定律中 k 相同，周期平方比等于半长轴立方比","do":"写出 T²∝a³，把上一步的两个半长轴代入求周期比","expr":"\\frac{T_1}{T_2}=\\sqrt{\\frac{a_甲^3}{a_乙^3}}=\\sqrt{\\frac{(R_1+R)^3}{(R_2+R)^3}}","cues":["同一中心天体k相同","周期看半长轴","开普勒第三定律"],"concepts":["开普勒第三定律","周期","半长轴"]},{"title":"远日点到近日点的时间","type":"前提判断","judge":"从远日点到近日点所经历的时间与周期的比例关系","why":"远日点、近日点把椭圆轨道分成对称的两半，各占半个周期，故该段时间为 T/2","do":"确认甲、乙各自从远日点到近日点都走半个椭圆，时间比等于周期比","expr":"\\frac{t_1}{t_2}=\\frac{T_1/2}{T_2/2}=\\frac{T_1}{T_2}","cues":["走半圈就是半个周期","时间比等于周期比","对称的两段"],"concepts":["椭圆轨道对称性","周期"]},{"title":"近日点远日点速度与加速度","type":"模型选择","judge":"比较速度、加速度时该用开普勒第二定律还是万有引力定律","why":"速度由面积定律判断（近日点快、远日点慢）；加速度只由该处到太阳的距离决定，a=GM/r²","do":"对甲用面积定律比较远日点与近日点速度；对乙用 a=GM/r² 比较其远日点（距离为 R）与地球公转加速度","expr":"a=\\frac{GM}{r^2}","cues":["速度看面积定律","加速度只看距离","同一位置加速度相同"],"concepts":["开普勒第二定律","万有引力定律","加速度"]}],"542":[{"title":"等效摆长的几何定位","type":"几何关系","judge":"要判断等效单摆的悬点位置与摆长如何由杆上 A、B 间距和倾角确定","why":"题设已说明微小摆动等效于悬挂点在重垂线与 AB 交点处的单摆，摆长是该交点到球心的距离，必须用几何关系求出，不能直接取 AB 间距","do":"画出重垂线与 AB 的交点，利用 A 端线与杆垂直、杆倾角 30° 找出摆长与 AB 间距、倾角之间的三角关系","expr":"L=\\frac{d\\tan30^\\circ}{\\cos30^\\circ}","cues":["找重垂线交点","摆长不是绳长","用杆的倾角"],"concepts":["等效单摆","摆长","几何关系"]},{"title":"绳两端拉力相等","type":"前提判断","judge":"要判断同一根光滑细线穿过小球时两端拉力是否相等","why":"细线光滑且不可伸长，线内张力处处相同，这是对小球受力分析时把两端拉力视为等大的前提","do":"对小球受力分析，把 A、B 两端拉力记为同一个大小 F","expr":"F_A=F_B=F","cues":["同一根绳","光滑穿球","张力处处相等"],"concepts":["绳的张力","受力分析"]},{"title":"平衡时拉力方向夹角","type":"关系建立","judge":"要判断平衡时两段线与竖直方向（或彼此）的夹角，才能列平衡方程","why":"A 端线与杆垂直、杆倾角 30°，可推出两段线与竖直方向的夹角均为 30°，合力方向沿角平分线竖直向上","do":"由 A 端垂直杆确定 A 段方向，再由对称性确定 B 段方向，写出竖直方向合力为零的方程","expr":"2F\\cos30^\\circ=mg","cues":["两段对称","夹角三十度","竖直方向平衡"],"concepts":["共点力平衡","力的合成"]},{"title":"周期与摆角无关","type":"近似条件","judge":"要判断微小摆动的周期是否随摆角改变","why":"单摆做微小摆动时周期只由摆长和重力加速度决定，与振幅（摆角）无关，这是排除“摆角越大周期越大”类干扰项的依据","do":"写出单摆周期公式，确认其中不含摆角","expr":"T=2\\pi\\sqrt{\\frac{L}{g}}","cues":["周期与摆角无关","小角度近似","只跟摆长有关"],"concepts":["单摆周期","简谐运动"]},{"title":"代入摆长求周期","type":"数学处理","judge":"要判断求出的摆长代入周期公式后对应的周期值","why":"摆长已由几何关系确定为 1 m，g 取 10 m/s²，代入即得周期，用于与各选项的周期值比较","do":"把 L=1 m、g=10 m/s² 代入周期公式计算","expr":"T=2\\pi\\sqrt{\\frac{1}{10}}\\approx 2\\,\\mathrm{s}","cues":["摆长一米","代公式算周期","大约两秒"],"concepts":["单摆周期","代入计算"]}],"543":[{"title":"跃迁光子能量对应能级差","type":"关系建立","judge":"每种跃迁光子的能量该用哪两个能级之差表示","why":"玻尔跃迁条件 hν=E_m−E_n，光子能量只由初末能级差决定，与路径无关","do":"写出 hν31=E3−E1、hν32=E3−E2、hν21=E2−E1 三式","expr":"h\\nu_{31}=E_3-E_1,\\ h\\nu_{32}=E_3-E_2,\\ h\\nu_{21}=E_2-E_1","cues":["能级差定频率","三种光对应三对能级"],"concepts":["玻尔跃迁条件","能级差"]},{"title":"光子动量用能量除光速","type":"关系建立","judge":"光子动量该由能量还是由频率单独换算","why":"光子 p=h/λ 且 c=λν，故 p=hν/c=E/c，动量与能量成正比","do":"把 hν31 换成 E3−E1 后除以 c 得 p","expr":"p=\\frac{h\\nu}{c}=\\frac{E_3-E_1}{c}","cues":["动量等于能量除光速","先算能量再除c"],"concepts":["光子动量","光速与波长关系"]},{"title":"最大初动能差消去逸出功","type":"关系建立","judge":"两种光打同一金属时逸出功是否相同、差值中能否消去","why":"同一光电效应装置逸出功 W 相同，爱因斯坦光电效应方程中 W 在相减时抵消","do":"写 Ekm=hν−W 两式相减，得 ΔEkm=h(ν31−ν21)","expr":"\\Delta E_{km}=h\\nu_{31}-h\\nu_{21}=h\\nu_{32}","cues":["同一金属逸出功一样","相减把逸出功消掉"],"concepts":["爱因斯坦光电效应方程","逸出功"]},{"title":"条纹间距与频率成反比","type":"关系建立","judge":"干涉条纹间距随频率增大而变宽还是变窄","why":"Δx=Lλ/d 且 λ=c/ν，故 Δx=Lc/(dν)，频率越高条纹越密","do":"写出 Δx 与 ν 的反比式，再判断两间距之差是否等于含 ν32 的式子","expr":"\\Delta x=\\frac{Lc}{d\\nu}","cues":["频率高条纹密","间距和波长成正比"],"concepts":["双缝干涉条纹间距","波长频率关系"]},{"title":"吸收光子须匹配能级差","type":"前提判断","judge":"原子吸收光子跃迁时，入射光频率是否必须恰好等于能级差除以 h","why":"自由原子吸收光子要满足能量守恒，光子能量必须精确等于 E4−E3，不能被部分吸收","do":"写 hν′=E4−E3，得 ν′=(E4−E3)/h，与题给频率比较","expr":"\\nu'=\\frac{E_4-E_3}{h}","cues":["吸收要正好对上能级差","光子吸收条件","能量守恒"],"concepts":["光子吸收条件","能量守恒"]}],"544":[{"title":"读图定两波到达时刻","type":"图像读取","judge":"从 M 点振动图像上判断两列波各自何时传到 M 点","why":"波传到某点前该点静止，图像上位移由零开始变化的那两个时刻就是两列波的到达时刻","do":"在振动图像上找位移开始偏离零的两个时刻，读出 4 s 和 7 s，求时间差","expr":"\\Delta t = 7\\,\\mathrm{s}-4\\,\\mathrm{s}=3\\,\\mathrm{s}","cues":["看起振时刻","两段波形","时间差三秒"],"concepts":["振动图像","波的传播"]},{"title":"由路程差和时间差求波速","type":"关系建立","judge":"判断路程差与到达时间差之比就是波速","why":"两波同速传播，路程差等于速度乘时间差，这是求波速的唯一途径","do":"用 6 m 除以 3 s 得波速，再由波速和周期求波长","expr":"v=\\frac{\\Delta x}{\\Delta t}=2\\,\\mathrm{m/s},\\ \\lambda=vT=4\\,\\mathrm{m}","cues":["路程差比时间差","先求波速","再算波长"],"concepts":["波速","波长"]},{"title":"由起振方向定波源方向","type":"前提判断","judge":"判断两列波刚传到 M 点时使 M 点向哪个方向起振","why":"介质中各质点起振方向与波源起振方向相同，这是判断波源振动方向的依据","do":"看 4 s 和 7 s 之后 M 点位移的正负走向，确定两波起振方向一致","expr":"","cues":["起振方向看第一下","向上起振","和波源一致"],"concepts":["起振方向","波的传播"]},{"title":"由振幅变化判干涉强弱","type":"临界条件","judge":"判断 7 s 后 M 点是振动加强还是减弱","why":"两波频率相同能干涉，某点合振幅变大还是变小取决于两波在该点的相位差，图像上表现为振幅增减","do":"比较 7 s 前后 M 点振幅，看是叠加增大还是减小，据此定加强或减弱","expr":"","cues":["看振幅变大变小","加强还是减弱","两波叠加"],"concepts":["干涉","振幅叠加"]},{"title":"由合位移拆各波振幅","type":"数学处理","judge":"判断如何从合位移反推每列波单独的振幅","why":"加强点合振幅等于两波振幅之和，减弱时等于之差，需用同一时刻两波位移的代数和拆分","do":"取 4.5 s 和 7.5 s 的位移值，结合加强减弱的结论列方程求各自振幅","expr":"A_1+A_2=3\\,\\mathrm{cm},\\ A_1-A_2=1\\,\\mathrm{cm}","cues":["合振幅拆开","加强相加","减弱相减"],"concepts":["振幅","波的叠加"]}],"545":[{"title":"圆环所在平面是等势面","type":"前提判断","judge":"等量异种电荷在圆环所在平面（MN 的中垂面）上产生的电势是否处处相等","why":"等量异种点电荷的中垂面是零势面，环上各点电势相同，所以点电荷电场对小球不做功，只有匀强电场和重力做功；不先判断这一点，就会误以为从 A 到 C 电势能变化由点电荷引起","do":"找出 MN 的中垂面，确认圆环平面与它重合，得出环上点电荷电势贡献恒定","expr":"","cues":["中垂面是等势面","点电荷不做功","只看匀强电场"],"concepts":["等势面","等量异种点电荷","电势能"]},{"title":"竖直方向合力的等效重力","type":"模型选择","judge":"把重力与匀强电场力合成一个竖直方向的恒力，判断它的大小和方向","why":"重力和电场力都竖直且恒定，可合并成一个等效恒力，环上各点只有这个恒力做功，圆周运动的“最高点/最低点”由它决定","do":"写出等效合力 mg−qE（向上为正时取符号），据此判断 A、C 哪端是等效最高点","expr":"F_{\\text{合}}=mg-qE","cues":["等效重力","重力和电场力合并","看合力方向"],"concepts":["等效重力","匀强电场"]},{"title":"匀速圆周的临界条件","type":"临界条件","judge":"qE 与 mg 满足什么关系时，小球沿环做匀速圆周运动","why":"只有等效合力为零，切向加速度才为零，速率才不变；这是判断“能否匀速”的唯一依据，也是干扰项 B 的错因所在","do":"令 mg−qE=0，比较 qE 与 mg 的大小关系","expr":"qE=mg","cues":["合力为零才匀速","切向不能有加速度","qE等于mg"],"concepts":["匀速圆周运动","平衡条件"]},{"title":"B 点速度由动能定理求","type":"关系建立","judge":"从 A 到 B 过程中哪些力做功、初末动能差等于什么","why":"点电荷电场不做功，只有竖直方向恒力做功，位移的竖直分量是 R，故可一步求出 B 点速率","do":"对 A→B 段列动能定理，取竖直位移为 R","expr":"(mg-qE)R=\\frac12 mv_B^2-\\frac12 mv_0^2","cues":["只有竖直力做功","竖直落差是半径","先求速度"],"concepts":["动能定理","功的计算"]},{"title":"向心与切向加速度合成","type":"关系建立","judge":"B 点加速度由哪两个互相垂直的分量组成","why":"B 点在水平直径端点，速度竖直，向心加速度沿半径水平指向 O，切向加速度由等效合力沿切向提供，二者垂直，必须矢量合成而不是直接相加","do":"用 v_B²/R 求向心加速度，用等效合力除以 m 求切向加速度，再勾股合成","expr":"a=\\sqrt{\\left(\\frac{v_B^2}{R}\\right)^2+\\left(\\frac{mg-qE}{m}\\right)^2}","cues":["两个加速度垂直","向心加切向","勾股合成"],"concepts":["向心加速度","切向加速度","矢量合成"]},{"title":"D 点环的作用力方向","type":"结论整理","judge":"D 点圆环对小球的作用力是否沿 MN 方向","why":"D 点在水平直径端点，向心力沿半径指向 O，即沿 MN 方向；但环的支持力还要平衡竖直方向的等效合力，故合力不沿 MN，干扰项 D 就错在只看向心力","do":"在 D 点沿半径和竖直两个方向分解受力，判断支持力的实际方向","expr":"","cues":["向心力沿半径","还要抵消竖直力","支持力不沿MN"],"concepts":["向心力","受力分析","弹力方向"]}],"546":[{"title":"区分两种发热功率来源","type":"模型选择","judge":"要判断两种情形下功率分别由感生电动势还是动生电动势提供","why":"磁场均匀变化时线框不动，只有感生电动势；磁场恒定时线框转动，只有动生电动势，两者不能混用同一公式","do":"对第一种情形用法拉第电磁感应定律求感生电动势，对第二种情形用切割磁感线求动生电动势峰值","expr":"E=\\frac{\\Delta B}{\\Delta t}S,\\quad E_m=BS\\omega","cues":["先看磁场变不变","转动才有动生电动势","两种功率分开算"],"concepts":["法拉第电磁感应定律","动生电动势","感生电动势"]},{"title":"转动功率用有效值","type":"关系建立","judge":"要判断转动产生的正弦交变电动势在算平均发热功率时该用有效值而非最大值","why":"发热功率由电流的有效值决定，正弦交流电有效值等于峰值除以根号二","do":"把转动时的功率写成峰值电动势平方除以二倍电阻，与已知的 2P 联立","expr":"2P=\\frac{(E_m/\\sqrt2)^2}{R}=\\frac{E_m^2}{2R}","cues":["功率用有效值","峰值除以根号二","不能拿最大值算功率"],"concepts":["交流电有效值","焦耳定律"]},{"title":"最大安培力取电流峰值","type":"临界条件","judge":"要判断 ab 边所受安培力最大发生在感应电流最大、即线框平面与磁场平行的时刻","why":"安培力 F=BIL 中 B、L 固定，力随电流变化，电流峰值出现在线框平面平行于磁场的瞬间","do":"取线框平面与磁场平行位置，用峰值电动势求峰值电流，再代入安培力公式","expr":"I_m=\\frac{BS\\omega}{R},\\quad F_m=BI_mL","cues":["转到平行时电流最大","取峰值电流","安培力跟着电流变"],"concepts":["安培力","交变电流峰值"]},{"title":"由功率比反求角速度","type":"数学处理","judge":"要判断需先用第一种情形的 P 定出具体数值，再由 2P 反解出角速度 ω","why":"两种情形的功率通过 P 相联系，只有先算出 P 的数值才能把转动功率方程中的 ω 解出","do":"先由感生电动势算 P，再代入转动功率方程解 ω，最后回代求峰值电流与最大安培力","expr":"P=\\frac{E^2}{R},\\quad \\omega=\\frac{2\\sqrt{PR}}{BS}","cues":["先算P的数值","用2P反解角速度","最后回代求力"],"concepts":["电功率","角速度"]}],"547":[{"title":"中子内部结构的判断","type":"前提判断","judge":"中子是否因整体电中性就等同于没有内部结构","why":"电中性只说明净电荷为零，不能推出内部无结构；中子由夸克通过强相互作用组成，β衰变体现弱相互作用","do":"区分'电中性'与'无内部结构'两个命题，判断二者是否等价","expr":"","cues":["电中性就没结构","中子还能衰变","弱相互作用"],"concepts":["基本粒子结构","弱相互作用"]},{"title":"光速不变原理的适用范围","type":"前提判断","judge":"真空中光速是否随惯性参考系不同而改变","why":"狭义相对论的两条基本假设之一就是光速不变原理，与光源和观察者的运动无关","do":"确认'不同惯性系'这一前提，直接调用光速不变原理","expr":"c=\\text{常量}","cues":["光速不变","换参考系也一样","相对论假设"],"concepts":["狭义相对论","光速不变原理"]},{"title":"LC固有频率与匝数的关系","type":"关系建立","judge":"增加线圈匝数时，是L变还是C变，固有频率随之升高还是降低","why":"f=1/(2π√(LC))，匝数增加使自感L增大，频率f减小，才能接收更低频率信号","do":"先由匝数判断L增大，再由频率公式判断f减小，最后对应到可接收信号的频率高低","expr":"f=\\frac{1}{2\\pi\\sqrt{LC}}","cues":["匝数多电感大","频率变低","接收低频台"],"concepts":["LC振荡电路","自感","固有频率"]},{"title":"分子力做功与势能变化","type":"关系建立","judge":"分子间距从小于r0到大于r0的过程中，分子力先做正功还是先做负功，势能如何变化","why":"r<r0时表现为斥力，r>r0时表现为引力；斥力阶段间距增大做正功，引力阶段间距继续增大做负功，故势能先减后增","do":"以r0为分界，分段判断分子力方向与位移方向是否同向，再累加势能变化","expr":"r<r_0:\\;F\\text{斥},\\;r>r_0:\\;F\\text{引}","cues":["先斥后引","先做正功","势能先降后升"],"concepts":["分子间作用力","分子势能","功与能"]}],"548":[{"title":"洛伦兹力方向判定","type":"前提判断","judge":"由小球带正电、向上运动及磁场垂直纸面向里（或向外），判断洛伦兹力沿垂直杆方向指向哪一侧","why":"洛伦兹力方向由左手定则决定，它决定杆对球的弹力方向，进而影响摩擦力是否为零及弹力冲量的正负","do":"用左手定则定出 v×B 方向，画出垂直杆方向的受力图","expr":"\\vec{F}=q\\vec{v}\\times\\vec{B}","cues":["左手定则","垂直杆方向","先定方向"],"concepts":["洛伦兹力","左手定则"]},{"title":"沿杆方向受力与加速度","type":"模型选择","judge":"判断沿杆方向是否只有重力分量 mg sinθ 提供加速度，即杆光滑、洛伦兹力垂直杆不贡献沿杆分力","why":"杆光滑无摩擦，洛伦兹力始终垂直于速度，沿杆方向合力仅为重力沿杆分量，故为匀减速","do":"沿杆列牛顿第二定律，求出加速度并写出速度随时间关系","expr":"a=g\\sin\\theta,\\quad v=v_0-g\\sin\\theta\\, t","cues":["沿杆分解","光滑无摩擦","匀减速"],"concepts":["牛顿第二定律","匀变速直线运动"]},{"title":"动量定理求合冲量","type":"关系建立","judge":"判断合外力的冲量等于动量变化量，而非某个分力的冲量","why":"动量定理对合外力成立，初末动量已知，合冲量大小直接由 mv0 给出，与重力冲量、洛伦兹力冲量区分开","do":"用末动量减初动量求合冲量大小，并据此排除把重力冲量当作合冲量的选项","expr":"I_{\\text{合}}=\\Delta p=0-mv_0","cues":["合冲量","动量变化","别混分力"],"concepts":["动量定理","冲量"]},{"title":"重力冲量的时间因子","type":"关系建立","judge":"判断上滑时间由 v0 与 g sinθ 决定，重力冲量需乘该时间而非直接用 v0","why":"重力是恒力，冲量 I=mg t，t 由匀减速到零的运动学关系给出，含 1/sinθ 因子","do":"先求上滑时间 t=v0/(g sinθ)，再算 mg t","expr":"I_G=mg\\cdot\\frac{v_0}{g\\sin\\theta}=\\frac{mv_0}{\\sin\\theta}","cues":["先求时间","恒力冲量","带正弦因子"],"concepts":["冲量","匀减速运动"]},{"title":"变力冲量的平均化处理","type":"数学处理","judge":"判断洛伦兹力随速度线性变化，其冲量可用平均力乘时间（等价于 F-t 图面积）计算","why":"洛伦兹力大小 Bqv 与 v 成线性关系，v 随时间线性减小，故力随时间线性变化，平均力等于初末力平均值","do":"写出 F洛=Bq(v0-at)，取初末平均再乘 t，代入 t 化简","expr":"I_{\\text{洛}}=\\frac{Bqv_0+0}{2}\\cdot\\frac{v_0}{g\\sin\\theta}","cues":["线性变化","取平均值","图线面积"],"concepts":["变力冲量","平均力"]},{"title":"弹力反向的临界与净冲量","type":"临界条件","judge":"判断在给定 v0 下弹力何时为零、何时反向，从而其冲量正负抵消为零","why":"垂直杆方向 Bqv 随 v 减小，与 mg cosθ 的大小关系会翻转，弹力先沿一侧后沿另一侧，F_N-t 图线上下面积相等则净冲量为零","do":"比较 Bqv0 与 mg cosθ 定初始弹力方向，找出 F_N=0 的时刻，判断图线对称性","expr":"Bqv=mg\\cos\\theta+F_N","cues":["弹力会反向","找零点","面积抵消"],"concepts":["临界状态","弹力","冲量"]}],"549":[{"title":"纸带瞬时速度的求法","type":"关系建立","judge":"打点13的速度该用哪两个计数点间的平均速度来替代","why":"匀变速直线运动中某段时间内的平均速度等于中间时刻的瞬时速度，点13是点11到点15的中间时刻","do":"取点13前后相邻的对称两点（11和15）的间距，除以对应时间2T","expr":"v_{13}=\\frac{x_{15}-x_{11}}{2T}=\\frac{x_{15}-x_{11}}{2}f","cues":["用相邻两点间距","中间时刻速度","除以两个周期"],"concepts":["匀变速直线运动","中间时刻瞬时速度","打点计时器"]},{"title":"验证守恒该用哪个g","type":"前提判断","judge":"用纸带算出的g去算势能减少量，还能不能用来验证机械能守恒","why":"验证性实验要检验的是重力势能减少量与动能增加量是否相等，两者都应由同一套测量数据独立算出再比较，若用纸带反推的g去算势能，等于把待验证的关系预先代入","do":"比较势能减少量与动能增加量的数值差是否落在误差允许范围内，并判断所用g的来源是否独立于待验证结论","expr":"\\Delta E_p=mgh,\\quad \\Delta E_k=\\frac{1}{2}mv^2","cues":["看两者是否接近","误差允许范围","g是不是测出来的"],"concepts":["机械能守恒","实验误差","重力加速度"]},{"title":"欧姆挡倍率的选择","type":"前提判断","judge":"指针完全不偏转说明电阻太大还是太小，该换哪个倍率","why":"欧姆挡指针不偏转意味着待测电阻远大于该倍率下的中值电阻，应换更大倍率使指针进入可读区","do":"比较×100挡下指针位置与中值附近区域，判断应增大倍率","expr":"","cues":["指针不动说明电阻大","换大倍率","往中值靠"],"concepts":["欧姆挡","倍率选择","二极管单向导电性"]},{"title":"红黑表笔与二极管极性","type":"关系建立","judge":"多用电表红表笔接的是内部电源的正极还是负极，据此判断二极管极性","why":"欧姆挡内部电池的正极接黑表笔、负极接红表笔（红进黑出），二极管正向导通时电流从正极流入","do":"由指针偏转时电流方向反推红表笔所接的二极管电极","expr":"","cues":["红进黑出","黑笔接内部正极","导通时电流从正极进"],"concepts":["欧姆表内部电源","二极管单向导电性","表笔极性"]},{"title":"分压接法与接线柱选择","type":"模型选择","judge":"要实现电压从零开始调节，滑动变阻器该用分压式还是限流式，P、Q各接哪个柱","why":"只有分压式接法才能使负载电压从零连续可调，限流式的最小电压不为零","do":"把滑动变阻器下端两柱接入电源两端，滑片P接a，电压表量程选0~3V故Q接d","expr":"","cues":["从零开始要分压","滑片接a","电压表选小量程"],"concepts":["分压式接法","滑动变阻器","电压表量程"]},{"title":"多用电表电流读数","type":"数据处理","judge":"50mA挡下分度值是多少，读到哪一位","why":"50mA量程对应分度值1mA，需估读到分度值的下一位","do":"按表盘刻度读出整格数并估读一位小数","expr":"I=45.0\\,\\mathrm{mA}","cues":["分度值是一毫安","要估读一位","看中间刻度"],"concepts":["电表读数","估读","分度值"]},{"title":"插针法确定出射光线","type":"实验操作","judge":"P3要挡住谁的像，以及是否需要第四枚大头针","why":"插针法要求各针在同一条光线上，P3应同时挡住P1、P2的像；光垂直入射方向不变，入射点可由ef与cd交点确定，只需再定一点即可确定出射光线","do":"判断P3挡住P1和P2的虚像，并说明出射光线由入射点与P3连线确定，不需第四针","expr":"","cues":["挡住两个像","垂直入射不偏折","不用第四枚针"],"concepts":["插针法","光的折射","光路确定"]},{"title":"折射率的几何角换算","type":"几何关系","judge":"入射角和折射角分别对应图中的哪个角","why":"光垂直ab入射，入射角为顶角θ；出射光线与ef夹角为α，则折射角为90°−α","do":"由几何关系写出入射角θ与折射角π/2−α，代入折射定律","expr":"n=\\frac{\\sin(\\frac{\\pi}{2}-\\alpha)}{\\sin\\theta}=\\frac{\\cos\\alpha}{\\sin\\theta}","cues":["入射角是顶角","折射角与α互余","用折射定律"],"concepts":["折射定律","几何关系","等腰三角形玻璃砖"]}],"550":[{"title":"判断压强是否变化","type":"前提判断","judge":"活塞缓慢移动过程中封闭气体压强是否改变","why":"活塞质量与大气压不变、无摩擦滑动，活塞受力平衡决定气体压强恒定，这是能用等压规律的前提","do":"对活塞列竖直方向受力平衡，比较初末两态的受力组成","expr":"pS=p_0S+mg","cues":["活塞受力平衡","压强不变","缓慢移动"],"concepts":["受力平衡","等压过程"]},{"title":"微观量对应宏观压强","type":"关系建立","judge":"器壁单位面积所受分子平均作用力与哪个宏观量对应","why":"压强定义就是单位面积上的平均作用力，温度升高但压强不变，故该平均作用力不变","do":"把分子平均作用力与压强挂钩，再由压强不变得结论","expr":"p=\\frac{F}{S}","cues":["压强就是单位面积受力","看压强","温度升高但压强不变"],"concepts":["压强微观意义","分子平均作用力"]},{"title":"数密度看体积变化","type":"关系建立","judge":"气体分子数密度随体积如何变化","why":"分子总数一定，数密度等于分子数除以体积，体积变大则数密度变小","do":"由活塞上升判断体积增大，再判断数密度","expr":"n=\\frac{N}{V}","cues":["体积变大","分子数不变","数密度变小"],"concepts":["数密度","体积"]},{"title":"初态体积含固体","type":"模型选择","judge":"封闭气体的实际体积是容器容积加气柱体积再减去固体体积","why":"固体占据容器内空间，气体只能填充剩余部分，漏掉固体体积或漏掉气柱体积都会列错方程","do":"写出初末两态气体体积表达式，再对两态列等压规律","expr":"V_1=V_0-V+l_1S,\\quad V_2=V_0-V+l_2S","cues":["减去固体体积","加上气柱体积","气体只占剩余空间"],"concepts":["气体体积","排开体积"]},{"title":"等压定律求固体体积","type":"关系建立","judge":"用哪条定律联系两态的体积与温度","why":"压强不变，质量一定的理想气体满足盖—吕萨克定律，两态体积比等于温度比","do":"把两态体积表达式代入等压定律，解出固体体积","expr":"\\frac{V_0-V+l_1S}{T_1}=\\frac{V_0-V+l_2S}{T_2}","cues":["等压变化","体积比等于温度比","盖—吕萨克"],"concepts":["盖—吕萨克定律","理想气体"]},{"title":"功的正负与热一律符号","type":"数学处理","judge":"气体对外做功的正负及热力学第一定律中各项符号","why":"气体膨胀对外做功，外界对气体做负功；第一定律中ΔU=Q+W，W取外界对气体做功","do":"用恒定压强乘体积变化算外界对气体做功，再代入第一定律求吸热","expr":"W=-p_1S(l_2-l_1),\\quad \\Delta U=Q+W","cues":["膨胀对外做功","外界做负功","符号别弄反"],"concepts":["热力学第一定律","等压做功"]}],"551":[{"title":"恰好过最高点的临界","type":"临界条件","judge":"滑块恰好通过圆形轨道最高点 C 时，重力与轨道压力满足什么关系","why":"光滑圆轨道内侧最高点，轨道只能提供指向圆心的压力，恰好通过时压力为零，向心力全部由重力提供","do":"对 C 点列牛顿第二定律，取压力为零","expr":"mg=\\frac{mv_C^2}{R}","cues":["压力为零","重力当向心力","恰好过顶"],"concepts":["向心力","临界速度","牛顿第二定律"]},{"title":"弹射点到 C 的动能定理","type":"关系建立","judge":"从离开弹簧到 C 点，用哪段过程、哪些力做功来联系 v0 与 vC","why":"AB、BCD 均光滑，只有重力做功，机械能守恒（或动能定理），高度差为 2R","do":"对 A 到 C 列动能定理，代入 vC 求 v0","expr":"-2mgR=\\frac12 mv_C^2-\\frac12 mv_0^2","cues":["只有重力做功","高度差两个半径","光滑无摩擦"],"concepts":["动能定理","机械能守恒"]},{"title":"共速用动量守恒","type":"模型选择","judge":"滑块滑上平板到共速的过程，能否对滑块与平板组成的系统用动量守恒","why":"μ2=0 时凹槽底面光滑，系统水平方向不受外力，碰撞式相互作用内力远大于外力，动量守恒；用牛顿定律加运动学也能做但多未知数","do":"取滑块加平板为系统，列水平方向动量守恒，再列初末动能差求损耗","expr":"mv_B=(M+m)v_{\\text{共}},\\quad \\Delta E=\\frac12 mv_B^2-\\frac12(M+m)v_{\\text{共}}^2","cues":["取整体","水平不受外力","动量守恒"],"concepts":["动量守恒","系统动能损失","完全非弹性碰撞"]},{"title":"判断是否先共速再同减速","type":"前提判断","judge":"μ2=0.1 时，滑块与平板是先达到共速再一起减速，还是滑块一直相对滑动到 H","why":"两种运动图景对应不同的位移约束和末速度表达式，选错图景方程就错；需先用相对位移等于板长 L 的假设求出 vE，再检验能否到达 H","do":"假设先共速，由相对位移 Δx=L 解出 vE 与共速速度，再算共同减速到 H 的末速度是否为正","expr":"\\Delta x=x_1-x_2=L","cues":["先假设共速","相对位移等于板长","再检验能否到H"],"concepts":["相对位移","运动图景假设","假设检验"]},{"title":"两阶段加速度分别求","type":"关系建立","judge":"相对滑动阶段平板受哪些摩擦力、共同减速阶段整体受哪些摩擦力，各自加速度多大","why":"滑块对板的摩擦向前 μ1mg，地面对板的摩擦向后 μ2(M+m)g，二者方向相反；共速后二者无相对滑动，只能靠地面摩擦共同减速，最大静摩擦等于滑动摩擦保证能一起减速","do":"分别对平板、对整体列牛顿第二定律求 a2、a3，对滑块求 a1","expr":"a_1=\\mu_1 g,\\quad a_2=\\frac{\\mu_1 mg-\\mu_2(M+m)g}{M},\\quad a_3=\\mu_2 g","cues":["板受两个摩擦","共速后一起减速","整体求加速度"],"concepts":["牛顿第二定律","滑动摩擦力","整体法"]},{"title":"最大速度对应板到 H 锁定","type":"结论整理","judge":"v0 增大时，限制滑块到达 H 的是哪个条件——是滑块从板右端滑落，还是板被锁定后滑块继续滑","why":"vE 再大则共速前相对位移超过 L，滑块会从平板右端掉下，无法随板到达 H；故最大速度对应相对位移恰好等于 L 的临界","do":"以 Δx=L 的临界解作为最大初速度对应的 vE，再由光滑段机械能守恒换回 v0","expr":"\\frac12 mv_0^2=\\frac12 mv_E^2+2mgR","cues":["刚好不掉下来","相对位移取板长","临界即最大"],"concepts":["临界条件","相对位移","机械能守恒"]}],"552":[{"title":"辐条并联与电流方向","type":"模型选择","judge":"三根辐条是并联还是串联，总电阻取 R 还是 R/3","why":"三根辐条一端都接转轴 O、另一端都接圆环边缘，两端电势差相同，属并联分流","do":"画出转轴—圆环两端节点，确认三根辐条并联，等效内阻取 R/3","expr":"r_0=\\frac{R}{3}=0.3\\,\\Omega","cues":["三根并联","每根电阻一样","等效内阻三分之一"],"concepts":["并联电路","等效电阻"]},{"title":"电动机的电流与反电动势","type":"关系建立","judge":"电压表读数 U 是路端电压还是反电动势，辐条电动势与电源电动势是相加还是相减","why":"电压表接在电源两端量路端电压；电动机正常工作时反电动势与电源电动势反向，U 与 E1 之差才降在辐条内阻上","do":"对电源回路用闭合电路欧姆定律求 I，再对辐条支路写 U−E1=I·R/3 求 E1","expr":"I=\\frac{E_0-U}{R_1+r},\\quad U-E_1=I\\frac{R}{3}","cues":["电压表量路端","反电动势抵消","先求电流再求电动势"],"concepts":["闭合电路欧姆定律","反电动势","路端电压"]},{"title":"磁场方向判定","type":"前提判断","judge":"由物块上升定转向、由转向定辐条电流方向，再用左手定则反推磁场方向","why":"安培力方向由转向和电流方向共同决定，三者中已知两个才能定第三个","do":"物块上升→轮逆时针转→辐条受安培力沿转向→辐条电流由边缘流向 O→左手定则得磁场垂直纸面向外","expr":"","cues":["先定转向","电流从边缘到轴","左手定则反推"],"concepts":["安培力","左手定则","右手定则"]},{"title":"电动机功率平衡求速度","type":"关系建立","judge":"用 E1I 作机械功率还是用 UI 作总功率，重力功率对应哪一个","why":"匀速提升时电功率转化为重力势能功率，只有反电动势部分 E1I 才是转化为机械能的功率","do":"对匀速过程写 E1I=mgv，代入 E1、I、m 求 v","expr":"E_1I=mgv","cues":["匀速则功率平衡","反电动势乘电流","等于重力功率"],"concepts":["电功率","机械功率","能量守恒"]},{"title":"下落时安培力与电流的对称性","type":"临界条件","judge":"物块匀速下落时辐条安培力大小、方向与提升时是否相同，电流是否仍为 10 A","why":"两次都是匀速，安培力都必须与重力平衡，故安培力大小相同；同一磁场、同一转速下电流大小也相同","do":"由 mg 与安培力平衡判断 I2=I1、E2=E1，再对掷 2 回路写 E2=I2(R2+R/3)","expr":"I_2=I_1,\\quad E_2=I_2\\left(R_2+\\frac{R}{3}\\right)","cues":["两次都匀速","安培力都等于重力","电流大小不变"],"concepts":["安培力平衡","匀速运动","对称性"]},{"title":"旋转切割电动势的等效速度","type":"几何关系","judge":"辐条切割电动势用 E=BLv 时 v 取端点速度还是中点（平均）速度","why":"辐条上各点线速度随半径线性增大，等效切割速度为辐条中点速度 ωa/2","do":"写 E=½Bωa²，并用 v=ωa 化为 E=½Bav，代入 E2 求 B","expr":"E=\\frac{1}{2}B\\omega a^2=\\frac{1}{2}Bav","cues":["取中点速度","线速度随半径变","二分之一系数"],"concepts":["动生电动势","线速度与角速度","平均切割速度"]}],"553":[{"title":"磁场偏转的几何落点","type":"几何关系","judge":"离子沿 y 轴射入上方磁场后，从射入点到再次回到 x 轴的距离与圆周半径是什么关系","why":"离子速度垂直 x 轴射入，圆周运动的弦恰为直径，出射点相对入射点的水平位移等于 2R","do":"画出半圆轨迹，确认出射点在 x 轴上且与入射点相距 2R，写出 x0=2R","expr":"x_0=2R,\\quad R=\\frac{mv}{Bq}","cues":["弦是直径","偏转半圆","水平位移两倍半径"],"concepts":["洛伦兹力","匀速圆周运动","弦长"]},{"title":"加速电压与半径的换算","type":"关系建立","judge":"加速电压 U 与离子在磁场中半径 R 的定量关系，以及用 U0 归一化后半径对应多少 L","why":"动能定理给出速度，洛伦兹力提供向心力给出半径，两者联立才能把可调电压翻译成可调落点","do":"联立 qU=mv²/2 与 R=mv/(Bq)，代入 U0 定义化简出 R 与 U/U0 的关系","expr":"R=\\frac{1}{B}\\sqrt{\\frac{2mU}{q}},\\quad U_0=\\frac{B^2qL^2}{8m}\\Rightarrow x_0=2L\\sqrt{\\frac{U}{U_0}}","cues":["先加速后偏转","电压定半径","用U0归一"],"concepts":["动能定理","向心力","比荷"]},{"title":"落到板面任意处的区间","type":"临界条件","judge":"a 离子要打满 P 板上表面，第一次偏转的落点范围应取哪一段，对应电压上下限","why":"P 板上表面横跨 x=1.5L 两侧各 L/2，即从 L 到 2L；只有第一次偏转直接落在该区间才可能覆盖全部位置","do":"令 L≤x0≤2L，反解出 U 的范围并用 U0 表示","expr":"L\\le 2L\\sqrt{\\frac{U}{U_0}}\\le 2L\\Rightarrow U_0\\le U\\le 4U_0","cues":["板长L两端","只能偏转一次","落点卡在L到2L"],"concepts":["临界条件","落点区间"]},{"title":"b 离子过栅极的筛选","type":"前提判断","judge":"b 离子第一次偏转落在 x 轴上 2L 到 4L 之间时，哪些能穿过栅极板 M、N 进入下方磁场","why":"栅极板只覆盖 2.5L 到 3.5L，落在该区间外的 b 离子被板挡住或无法进入下方区域，只有穿过栅极的才参与后续减速偏转","do":"由 b 的比荷为 a 的 1/4 得 xb=2x0，代入 U 范围得 2L≤xb≤4L，再与栅极坐标 2.5L~3.5L 取交集，反解出有效 U 区间","expr":"x_b=\\frac{2}{B}\\sqrt{\\frac{2m_bU}{q_b}}=2x_0,\\quad \\frac{25}{16}U_0\\le U\\le\\frac{49}{16}U_0","cues":["比荷四分之一","半径翻倍","被栅极挡住"],"concepts":["比荷","几何筛选","栅极板"]},{"title":"减速后半径与落点平移","type":"关系建立","judge":"b 离子经 U_MN 减速后进入下方磁场，其半径由剩余动能决定，落点相对栅极出射点的平移量如何算","why":"电场减速消耗动能，剩余动能决定下方圆周半径，而下方偏转的弦长同样是 2R'，平移量由此确定","do":"对减速过程用动能定理求 v'，再由 R'=m_bv'/(Bq_b) 得平移量 Δx=2R'，分别代入 U 的上下限求两端平移","expr":"q_bU-\\frac34q_bU=\\frac12m_bv'^2,\\quad \\Delta x=2R'=\\frac{2}{B}\\sqrt{\\frac{2m_b(U/4)}{q_b}}","cues":["减速剩四分之一","弦长还是两倍半径","平移量随电压变"],"concepts":["动能定理","剩余动能","弦长"]},{"title":"多级减速的整数约束","type":"临界条件","judge":"b 离子在栅极间可能被多次减速，取几次减速才能恰好落在 P 板下表面中点，且此前不提前打到板上","why":"每次经过栅极都损失一份动能，半径逐次减小，只有第 n 次偏转的弦长恰为 1.5L 且前一次弦长大于板长 L 时才符合题意","do":"写出第 n 次减速后的半径平方表达式，令 2r_n=1.5L 且 2r_{n-1}>L，解出 n 的整数取值","expr":"r_n^2=\\frac{9L^2}{4}-\\frac{8nm}{B^2q}U_{NM},\\quad 2r_n=\\frac32L,\\quad 2r_{n-1}>L","cues":["可能减速多次","半径逐次变小","前一次不能打到板"],"concepts":["多过程","整数取值","临界条件"]}],"554":[{"title":"动能与速度的平方关系","type":"关系建立","judge":"动能变为 4 倍时，初速度变为原来的几倍","why":"动能 Ek=½mv² 与速度平方成正比，质量不变，所以动能变 4 倍对应速度变 2 倍，而不是 4 倍","do":"由 Ek=½mv² 比较调整前后，求出速度之比","expr":"E_k=\\frac{1}{2}mv^2 \\Rightarrow v\\propto\\sqrt{E_k}","cues":["动能四倍速度也四倍","开平方","质量不变"],"concepts":["动能","速度"]},{"title":"平抛竖直方向定时间","type":"模型选择","judge":"水平距离由什么决定，飞行时间是否随初速度改变","why":"离开甲板后只受重力，竖直方向自由落体，下落高度不变则时间不变，与水平初速度无关","do":"对竖直方向列 h=½gt²，确认 t 与 v 无关","expr":"h=\\frac{1}{2}gt^2,\\quad t=\\sqrt{\\frac{2h}{g}}","cues":["平抛运动","时间看高度","竖直方向自由落体"],"concepts":["平抛运动","自由落体"]},{"title":"水平方向匀速定射程","type":"关系建立","judge":"水平射程与初速度成什么比例","why":"水平方向不受力做匀速直线运动，时间不变时射程与初速度成正比","do":"由 x=vt，代入速度变为 2 倍、时间不变，得射程倍数","expr":"x=vt\\propto v","cues":["水平匀速","射程看速度","时间一样"],"concepts":["匀速直线运动","水平射程"]}],"555":[{"title":"选定中心天体模型","type":"模型选择","judge":"行星做圆周运动的向心力由谁提供，该用哪套公式","why":"行星绕红矮星近似做匀速圆周运动，万有引力提供向心力，这是求中心天体质量的唯一依据","do":"对 GJ1002c 绕红矮星、地球绕太阳分别列出引力等于向心力的方程","expr":"G\\frac{Mm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["万有引力当向心力","绕谁转就求谁的质量"],"concepts":["万有引力定律","向心力","中心天体"]},{"title":"消去行星质量求中心质量","type":"关系建立","judge":"方程中行星质量能否约去，从而把中心天体质量单独解出","why":"行星质量 m 在等式两边同时出现，可约去，说明环绕天体的质量不影响结果，只有中心天体质量与 r、T 有关","do":"约去 m，把 M 写成 r 和 T 的表达式","expr":"M=\\frac{4\\pi^{2}r^{3}}{GT^{2}}","cues":["行星质量约掉","只跟半径和周期有关"],"concepts":["中心天体质量","周期"]},{"title":"用比值避开常数","type":"数学处理","judge":"是直接算红矮星质量，还是与太阳做比值","why":"G、π 等常数未知且题目只给相对量（0.07 倍、0.06 年），取比值可让常数全部消去","do":"把红矮星与太阳的 M 表达式相除，整理成半径比三次方乘周期反比平方","expr":"\\frac{M_{1}}{M_{2}}=\\left(\\frac{r_{1}}{r_{2}}\\right)^{3}\\left(\\frac{T_{2}}{T_{1}}\\right)^{2}","cues":["两式相除","常数全消掉"],"concepts":["比值法","开普勒第三定律"]},{"title":"周期单位统一","type":"前提判断","judge":"0.06 年与日地周期 1 年是否同单位，能否直接代入比值","why":"比值中 T 的幂次要求两周期单位一致，地球周期取 1 年才能与 0.06 年直接相比","do":"确认 T2=1 年、T1=0.06 年，单位一致后代入","expr":"\\frac{T_{2}}{T_{1}}=\\frac{1}{0.06}","cues":["地球周期是一年","单位要一样"],"concepts":["周期单位"]},{"title":"估算三次方与平方","type":"数学处理","judge":"0.07 的三次方与 0.06 的平方之比落在哪个数量级","why":"选项间是数量级差别，只需估算到约 0.1 即可定项，不必精确计算","do":"算 0.07³≈3.4×10⁻⁴，0.06²=3.6×10⁻³，两者相除取近似","expr":"\\frac{0.07^{3}}{0.06^{2}}\\approx 0.1","cues":["先估数量级","零点零七的立方"],"concepts":["数量级估算"]}],"556":[{"title":"比较红蓝光频率","type":"前提判断","judge":"要判断红光和蓝光谁的频率高、谁的波长大","why":"可见光中红光波长最长、频率最低，蓝光波长较短、频率较高，这是后续所有比较的出发点","do":"按可见光谱顺序排出红、蓝两色的波长与频率大小关系","expr":"\\nu_{\\text{红}}<\\nu_{\\text{蓝}},\\ \\lambda_{\\text{红}}>\\lambda_{\\text{蓝}}","cues":["红光频率低","红光波长长","蓝光偏紫"],"concepts":["光的频率","光的波长","可见光谱"]},{"title":"光子能量与频率挂钩","type":"关系建立","judge":"要判断光子能量该由频率还是波长决定，并据此比较两色光子能量","why":"光子能量由普朗克关系决定，只与频率成正比，与波长成反比","do":"用光子能量公式把频率大小关系翻译成能量大小关系","expr":"E=h\\nu=\\frac{hc}{\\lambda}","cues":["能量看频率","频率高能量大"],"concepts":["光子能量","普朗克常量"]},{"title":"光子动量与波长挂钩","type":"关系建立","judge":"要判断光子动量该用哪个公式、随波长如何变化","why":"光子动量与波长成反比，波长越长动量越小，与能量公式是两条不同的关系","do":"用动量公式把波长大小关系翻译成动量大小关系","expr":"p=\\frac{h}{\\lambda}","cues":["动量看波长","波长长动量小"],"concepts":["光子动量","德布罗意关系"]},{"title":"介质中速度由折射率定","type":"关系建立","judge":"要判断光在玻璃中的传播速度由什么决定，并比较红蓝光速度","why":"介质中光速由该介质对该色光的折射率决定，而折射率随频率升高而增大","do":"先比较玻璃对红蓝光的折射率，再用速度与折射率的关系比较速度","expr":"v=\\frac{c}{n},\\ n_{\\text{蓝}}>n_{\\text{红}}","cues":["速度看折射率","蓝光偏折大"],"concepts":["折射率","介质中的光速"]},{"title":"折射时频率不变","type":"前提判断","judge":"要判断光从一种介质进入另一种介质时，哪个物理量保持不变","why":"频率由光源决定，与介质无关；改变的是波长和速度","do":"确认跨介质传播时频率守恒，波长和速度随之改变","expr":"\\nu_{\\text{不变}},\\ \\lambda'=\\frac{\\lambda}{n}","cues":["频率不变","波长会变","颜色不变"],"concepts":["频率的决定因素","光的折射"]}],"557":[{"title":"两球受力方向判定","type":"模型选择","judge":"两球所受库仑力是相互排斥还是相互吸引，方向沿两球连线","why":"两球均带正电，同种电荷相互排斥，库仑力沿连线向外，这是后续列水平方向方程的前提","do":"画出 P、Q 各自受力图，标出库仑力沿两球连线背离对方的方向","expr":"","cues":["同种电荷排斥","库仑力沿连线","先画受力图"],"concepts":["库仑定律","受力分析"]},{"title":"绳偏方向与电场力关系","type":"关系建立","judge":"两球绳与竖直方向夹角相等时，各自水平方向电场力与库仑力、绳拉力的水平分量如何组合","why":"平衡条件要求每球水平合力为零，绳偏方向决定绳拉力水平分量指向哪一侧，从而决定电场力与库仑力的大小关系","do":"对 Q、P 分别沿水平方向列平衡方程，把电场力、库仑力、绳拉力水平分量按方向组合","expr":"q_1E+T_1\\sin\\theta=F,\\quad q_2E+F=T_2\\sin\\theta","cues":["水平方向合力为零","绳拉力有水平分量","分两球列方程"],"concepts":["共点力平衡","电场力"]},{"title":"由水平方程比较绳拉力","type":"数学处理","judge":"由两球水平方程能否推出两绳拉力的大小关系","why":"两球电场力均为正，结合库仑力方向可判断 T_2sinθ 与 T_1sinθ 的大小，夹角相同则拉力大小随之确定","do":"将两式相减或比较右边，得出 T_2 与 T_1 的大小关系","expr":"T_2\\sin\\theta-T_1\\sin\\theta=(q_1+q_2)E>0","cues":["两式相减","夹角相同","比较拉力"],"concepts":["共点力平衡","方程联立"]},{"title":"竖直方向联系质量","type":"关系建立","judge":"绳拉力竖直分量与重力平衡，能否把拉力大小关系转化为质量关系","why":"竖直方向无其他力，Tcosθ=mg，夹角相同则拉力大小直接反映质量大小","do":"对两球写竖直方向平衡式，用已得拉力大小关系比较 m_1 与 m_2","expr":"T_1\\cos\\theta=m_1g,\\quad T_2\\cos\\theta=m_2g","cues":["竖直方向平衡","拉力反映质量","夹角相同"],"concepts":["共点力平衡","重力"]},{"title":"电荷量不可判定的判断","type":"结论整理","judge":"仅凭平衡条件能否确定两球电荷量的大小关系","why":"水平方程只给出电场力与库仑力的组合关系，电荷量以乘积形式出现，无法单独比较 q_1 与 q_2","do":"检查方程中 q_1、q_2 是否可分离，确认电荷量关系无法确定","expr":"","cues":["电荷量解不出","只能比质量","别多下结论"],"concepts":["共点力平衡","库仑定律"]}],"558":[{"title":"读振动图得周期振幅","type":"图像读取","judge":"从波源振动图像上读出周期和振幅，并判断它们是否等于波的周期和振幅","why":"介质中各质点都重复波源的振动，波的周期和振幅由波源决定，与传播距离无关","do":"在振动图像上读一个完整循环的时间间隔和最大位移","expr":"T=0.2\\,\\mathrm{s},\\ A=0.2\\,\\mathrm{m}","cues":["看一个完整周期","振幅看峰值","波源决定周期"],"concepts":["振动图像","周期","振幅"]},{"title":"数波源到第二次波谷","type":"关系建立","judge":"从 t=0 起波源第 2 次到达波谷所经历的时间是几个周期加几分之几","why":"波源从平衡位置起振，第一次到波谷需 3/4 周期，之后每过一个周期再到一次波谷","do":"从起振方向出发，数到第一次波谷再累加一个周期","expr":"t=\\tfrac{3}{4}T+T=0.35\\,\\mathrm{s}","cues":["先到第一次波谷","再加一个周期","起振方向向上"],"concepts":["振动步调","波谷","周期计数"]},{"title":"P 起振时刻对应波传时间","type":"前提判断","judge":"P 刚开始振动说明波恰好传到 P，波传播的距离与所用时间的对应关系","why":"波传到某点时该点才开始振动，故波源振动的时间就是波传播到 P 所用的时间","do":"把上一步算出的时间当作波从 O 传到 P 的传播时间","expr":"t_{\\text{传}}=0.35\\,\\mathrm{s}","cues":["刚起振就是波刚到","传播时间等于振动时间"],"concepts":["波的传播","起振时刻"]},{"title":"由距离和时间求波速","type":"关系建立","judge":"用 O 到 P 的距离除以传播时间求波速","why":"波匀速传播，满足 v=x/t","do":"代入 x=3.5 m 与 t=0.35 s 求 v","expr":"v=\\dfrac{3.5}{0.35}=10\\,\\mathrm{m/s}","cues":["距离除以时间","匀速传播"],"concepts":["波速","匀速传播"]},{"title":"P 传到 Q 的时间与相位","type":"关系建立","judge":"波从 P 传到 Q 所需时间是周期的几分之几，据此判断此时 P 的振动状态","why":"相隔半个周期的两点振动步调相反，P 与 Q 相距半个波长时 P 处于平衡位置","do":"用 PQ 距离除以波速得时间，再与周期比较","expr":"t'=\\dfrac{x_{PQ}}{v}=0.1\\,\\mathrm{s}=\\tfrac{T}{2}","cues":["先算传播时间","和周期比","半个周期反相"],"concepts":["波长","振动步调","平衡位置"]}],"559":[{"title":"识别初始位置","type":"前提判断","judge":"磁场方向与线圈平面垂直时，线圈处于什么位置、磁通量是最大还是零","why":"磁通量 Φ=BS⊥ 取决于磁场与线圈平面的夹角，磁场垂直于线圈平面时磁感线全部穿过线圈，磁通量最大，该位置即中性面","do":"由题图判断磁场方向与线圈平面的几何关系，确定此刻磁通量取极大值","expr":"\\Phi=BS","cues":["磁场垂直线圈平面","磁通量最大","中性面"],"concepts":["磁通量","中性面"]},{"title":"转过九十度后的磁通","type":"几何关系","judge":"再转过 90° 后磁场方向与线圈平面是什么关系，磁通量变为多少","why":"线圈转过 90° 后磁场方向与线圈平面平行，磁感线不再穿过线圈，磁通量为零","do":"把线圈平面转动 90°，比较转动前后磁场与线圈平面的夹角，得出磁通量由最大变为零","expr":"\\Phi'=0","cues":["转九十度后平行","磁通量变零","磁感线擦着线圈"],"concepts":["磁通量","线圈平面"]},{"title":"磁通量变化率最大","type":"临界条件","judge":"磁通量为零的时刻，感应电动势（电流）是最大还是零","why":"感应电动势由磁通量的变化率决定而非磁通量本身，中性面处 Φ 最大但变化率为零，与中性面垂直处 Φ=0 而变化率最大","do":"比较中性面与转过 90° 位置处 Φ-t 图像的斜率，判断感应电动势的极值位置","expr":"e=\\left|\\frac{\\Delta\\Phi}{\\Delta t}\\right|","cues":["磁通量为零电流最大","看变化率不看磁通量","斜率最大"],"concepts":["法拉第电磁感应定律","磁通量变化率"]},{"title":"用楞次定律定方向","type":"关系建立","judge":"磁通量减小的过程中，感应电流的磁场要阻碍减小，据此定出线圈中电流的绕行方向","why":"楞次定律：感应电流的磁场总要阻碍原磁通量的变化，原磁通量减小则感应磁场方向与原磁场同向","do":"先判原磁场穿过线圈的方向，再判磁通量增减，由阻碍关系定感应磁场方向，用安培定则得电流由 Q 流向 P","expr":"","cues":["磁通量在减小","感应磁场同向","右手螺旋定则"],"concepts":["楞次定律","安培定则"]}],"560":[{"title":"识别循环各过程的性质","type":"模型选择","judge":"要判断四个过程中哪些是绝热、哪些是等压、哪些是等容，以及各过程体积、压强、温度如何变化","why":"热力学第一定律 ΔU=Q+W 中 Q 与 W 的符号取决于过程性质，不先定性过程就无法判断吸放热与内能变化","do":"对照 p-V 图逐段确认：1→2、3→4 为绝热线，2→3 为水平等压线，4→1 为竖直等容线，并读出各段体积增减","expr":"","cues":["先看是什么过程","绝热没有热交换","等压看体积","等容看压强"],"concepts":["绝热过程","等压过程","等容过程","p-V 图"]},{"title":"绝热段用第一定律定内能","type":"关系建立","judge":"要判断绝热过程中体积变化方向决定外界做功正负，从而决定内能增减","why":"绝热 Q=0，ΔU=W，内能变化完全由外界对气体做功决定；体积压缩则外界做正功、内能增大","do":"对 1→2 看体积减小，对 3→4 看体积增大，分别由 ΔU=W 判断内能增减","expr":"$\\Delta U=W\\ (Q=0)$","cues":["绝热只看做功","体积变小外界做功","体积变大对外做功"],"concepts":["热力学第一定律","绝热过程","内能"]},{"title":"等压段用盖-吕萨克定律","type":"关系建立","judge":"要判断等压过程中体积增大对应温度升高，进而内能增大","why":"等压过程 V/T=常量，体积与温度同向变化；温度升高则理想气体内能增大","do":"对 2→3 由体积增大推出温度升高、内能增大，再结合对外做功判断吸热","expr":"$\\dfrac{V}{T}=\\text{常量},\\ \\Delta U>0,\\ W<0$","cues":["等压体积温度同向","体积变大温度升高","内能跟着温度走"],"concepts":["盖-吕萨克定律","等压过程","内能"]},{"title":"等容段用查理定律","type":"关系建立","judge":"要判断等容过程中压强减小对应温度降低，且不做功","why":"等容过程 p/T=常量，压强与温度同向变化；体积不变则 W=0，内能变化只能来自热交换","do":"对 4→1 由压强减小推出温度降低、内能减小，再由 ΔU=Q 判断放热","expr":"$\\dfrac{p}{T}=\\text{常量},\\ W=0,\\ \\Delta U=Q$","cues":["等容不做功","压强降温度降","内能减小要放热"],"concepts":["查理定律","等容过程","热力学第一定律"]},{"title":"用第一定律统一判吸放热","type":"结论整理","judge":"要判断每段中 Q 的符号，即气体吸热还是放热","why":"由 ΔU=Q+W 移项得 Q=ΔU−W，只有同时确定 ΔU 与 W 的符号才能定 Q 的正负","do":"逐段代入 ΔU 与 W 的符号，比较 Q 的正负，得出吸热或放热结论","expr":"$Q=\\Delta U-W$","cues":["先定内能再定做功","两个符号一起看","吸热放热看Q正负"],"concepts":["热力学第一定律","吸热","放热"]}],"561":[{"title":"选质量大小关系","type":"前提判断","judge":"要判断入射球 a 与被碰球 b 的质量谁大谁小，才能保证碰后 a 不反弹、两球都向前飞出落在同一木板区域","why":"碰后 a 若反弹，落点位置与速度方向关系被破坏，且无法用同一水平位移正比关系处理；由一维弹性/非弹性碰撞规律，入射球质量大于被碰球时碰后入射球仍向前","do":"比较 m_a 与 m_b，写出碰后 a 球速度方向不反向的条件","expr":"m_a > m_b","cues":["碰后不能反弹","入射球要重些","a球质量大"],"concepts":["碰撞","动量守恒","质量条件"]},{"title":"平抛时间相同","type":"模型选择","judge":"要判断两球（及碰撞前后）离开轨道后是否做同一高度的平抛运动，从而下落时间相同","why":"轨道末端水平，各球从同一高度水平飞出，竖直方向自由落体高度相同，故飞行时间 t 相同，这是用水平位移替代速度的前提","do":"确认抛出点高度相同、初速度水平，写出竖直方向位移与时间关系","expr":"h=\\frac{1}{2}gt^{2}","cues":["同一高度飞出","下落时间一样","平抛运动"],"concepts":["平抛运动","运动独立性","飞行时间"]},{"title":"位移替代速度","type":"关系建立","judge":"要判断能否用落点与 O 点的水平距离 x 直接代替水平飞出速度 v 代入动量守恒式","why":"水平方向匀速直线运动，x=vt，t 相同，故 x 与 v 成正比，比例系数 1/t 在动量守恒式两边可约去","do":"对碰前 a、碰后 a、碰后 b 分别写出 x=vt，再代入动量守恒式消去 t","expr":"v=\\frac{x}{t}\\Rightarrow m_a x_P=m_a x_M+m_b x_N","cues":["位移正比于速度","时间相同可约掉","用水平距离代替速度"],"concepts":["平抛运动","动量守恒","正比关系"]},{"title":"对应落点归属","type":"几何关系","judge":"要判断 x_P、x_M、x_N 分别对应碰前 a、碰后 a、碰后 b 的落点，不能把 M、N 与两球对应错","why":"碰后 a 速度小于碰前，b 速度最大，故落点距离满足 x_M<x_P<x_N；对应错则方程中质量与位移配错","do":"按碰前 a→P、碰后 a→M、碰后 b→N 的对应关系列动量守恒方程","expr":"m_a x_P=m_a x_M+m_b x_N","cues":["M是碰后a的落点","N是碰后b的落点","P是碰前a的落点"],"concepts":["动量守恒","落点对应","速度大小比较"]},{"title":"多次测量取平均","type":"实验操作","judge":"要判断为什么每个落点都要重复多次取平均位置，而不能只测一次","why":"落点存在偶然误差，多次落点取平均可减小偶然误差，使平均位置更接近真实落点","do":"说明重复释放、找平均落点（如用最小圆包含多数落点取圆心）的操作目的","expr":"","cues":["减小偶然误差","找平均落点","多测几次"],"concepts":["偶然误差","平均位置","实验规范"]}],"562":[{"title":"欧姆表挡位与调零顺序","type":"实验操作","judge":"选挡、短接、调零这三步的先后顺序能否颠倒","why":"欧姆表每次换挡后内部电路改变，必须重新短接调零，否则读数整体偏移","do":"先选×10挡，再将红黑表笔短接，最后调欧姆调零旋钮使指针指零欧姆","expr":"","cues":["先选挡位","换挡要重新调零","短接再调零"],"concepts":["欧姆表","欧姆调零","倍率选择"]},{"title":"欧姆表笔接电压表极性","type":"前提判断","judge":"红黑表笔应接电压表的正极还是负极","why":"欧姆表测电阻时内部电源供电，电流从黑表笔流出经外部电阻流回红表笔，即红进黑出","do":"判断表内电源方向，确定黑表笔接电压表正极、红表笔接负极","expr":"","cues":["红进黑出","黑笔接正极","表内有电源"],"concepts":["欧姆表内部电源","电流方向"]},{"title":"倍率换挡与读数","type":"数据处理","judge":"指针偏转太小说明倍率偏小还是偏大，应换哪一挡，读数乘多少","why":"欧姆表刻度不均匀，指针偏角过小表示示数过大，应增大倍率使指针落在中值附近","do":"由虚线Ⅰ偏角小判断倍率偏小，改×100挡重新调零，读实线Ⅱ刻度乘以100","expr":"","cues":["偏角小换大倍率","指针靠左要升挡","读数乘倍率"],"concepts":["欧姆表刻度","中值电阻","倍率"]},{"title":"分压接法选小阻值变阻器","type":"模型选择","judge":"滑动变阻器是分压接法还是限流接法，该选最大阻值大的还是小的","why":"分压接法要求变阻器阻值远小于负载电阻，才能均匀调节输出电压；R2阻值与电压表内阻同量级，调节范围过窄","do":"识别电路为分压式，比较50Ω与5kΩ相对负载的大小，选R1","expr":"","cues":["分压选小电阻","阻值小才好调","从零开始调"],"concepts":["分压接法","滑动变阻器选择"]},{"title":"闭合开关前滑片位置","type":"临界条件","judge":"闭合开关前滑片应放在使测量部分电压为零的那一端","why":"保护电表，避免闭合瞬间待测部分承受过大电压，同时保证电压可从零开始调节","do":"判断分压输出端，将滑片置于a端使输出电压为零","expr":"","cues":["保护电表","电压从零开始","滑到a端"],"concepts":["分压电路","电表保护"]},{"title":"用串联分压求内阻","type":"关系建立","judge":"待测电压表与R0是串联还是并联，电流如何由两表示数差求出","why":"两电压表与R0串联，电流相等，R0两端电压为U1与U之差，由此得电流再求RV","do":"写I=(U1−U)/R0，再由RV=U/I联立","expr":"$R_V=\\dfrac{U R_0}{U_1-U}$","cues":["串联电流相等","电压差除以电阻","两表示数相减"],"concepts":["串联电路","欧姆定律","电压表内阻"]}],"563":[{"title":"选重物为受力对象","type":"模型选择","judge":"以重物为研究对象，还是把绳和重物一起取整体","why":"两绳拉力是待求量，取重物为对象时两拉力直接出现在受力图上，取整体则拉力成为内力无法求解","do":"隔离重物，画出重力与两绳拉力的受力示意图","expr":"","cues":["隔离重物","只看重物","画受力图"],"concepts":["隔离法","受力分析"]},{"title":"缓慢下降判平衡","type":"前提判断","judge":"重物缓慢下降过程中能否按合力为零处理","why":"缓慢意味着速度变化可忽略、加速度近似为零，故三力平衡而非用牛顿第二定律列加速方程","do":"由缓慢二字判定加速度为零，对重物列合力为零的平衡方程","expr":"\\vec{T}_1+\\vec{T}_2+m\\vec g=0","cues":["缓慢就是平衡","加速度为零","合力为零"],"concepts":["平衡状态","共点力平衡"]},{"title":"两绳方向定几何","type":"几何关系","judge":"两绳与竖直方向夹角分别为α、β时，各拉力在水平、竖直方向的分量如何写","why":"拉力沿绳方向，题目给的是与竖直方向的夹角，故竖直分量用余弦、水平分量用正弦","do":"把T₁、T₂分别沿竖直和水平方向分解，写出四个分量表达式","expr":"T_1\\cos\\alpha,\\ T_1\\sin\\alpha,\\ T_2\\cos\\beta,\\ T_2\\sin\\beta","cues":["沿绳方向","与竖直夹角","余弦给竖直"],"concepts":["力的分解","正交分解"]},{"title":"竖直方向含重力","type":"关系建立","judge":"竖直方向平衡式中重力与两绳竖直分量如何组合（同向还是反向）","why":"两绳都斜向上拉重物，竖直分量均向上，与向下的重力平衡，故两竖直分量之和等于重力","do":"列竖直方向平衡方程，把两绳竖直分量放在等号同侧相加","expr":"T_1\\cos\\alpha+T_2\\cos\\beta=mg","cues":["两绳都往上拉","竖直分量相加","等于重力"],"concepts":["共点力平衡","正交分解"]},{"title":"水平方向抵消","type":"关系建立","judge":"水平方向两绳分量大小相等方向相反，据此建立第二个方程","why":"重物水平方向不移动、合力为零，两绳水平分量必须互相抵消","do":"列水平方向平衡方程，令两水平分量相等","expr":"T_1\\sin\\alpha=T_2\\sin\\beta","cues":["水平方向抵消","左右相等","水平合力为零"],"concepts":["共点力平衡","正交分解"]},{"title":"全程动能定理求功","type":"模型选择","judge":"求变力（方向变化）的拉力总功时，用功的定义逐段积分还是用动能定理整体处理","why":"下降中两绳方向不断变化，拉力是变力，直接求功困难；而初末速度均为零，动能变化为零，用动能定理可绕开过程细节","do":"对从开始到落地全过程列动能定理，把重力功与拉力总功相加等于零","expr":"W_T+mgh=0-0","cues":["变力不好算","用动能定理","初末都静止"],"concepts":["动能定理","变力做功"]}],"564":[{"title":"两物体加速度分别定","type":"模型选择","judge":"物块与薄板各自受哪种摩擦力、加速度由什么决定","why":"物块相对薄板向右滑，薄板对物块的滑动摩擦力向左使其减速；薄板受物块给的向右滑动摩擦力而加速，两者质量相等故加速度大小相同","do":"分别对物块和薄板沿水平方向列牛顿第二定律，求出两个加速度大小","expr":"a_1=\\mu g,\\quad a_2=\\frac{\\mu mg}{m}=\\mu g","cues":["分别受力","摩擦力方向相反","质量相等"],"concepts":["滑动摩擦力","牛顿第二定律"]},{"title":"相对位移定几何约束","type":"几何关系","judge":"物块从板右端飞出时，物块位移与板位移之间满足什么关系","why":"物块相对薄板滑过整个板长 l，而板同时向前移动 Δl，故物块对地位移为 l+Δl","do":"写出物块对地位移与板位移的几何关系，作为两运动学方程的衔接条件","expr":"s_物=l+\\Delta l,\\quad s_板=\\Delta l","cues":["相对滑过整块板","板也在动","位移要叠加"],"concepts":["相对位移","参考系"]},{"title":"同时间联立两运动方程","type":"关系建立","judge":"物块与薄板从开始到分离经历的时间是否相同，能否用同一 t 联立","why":"两者同时开始运动、同时分离，时间相同，才能把两个位移方程联立消元","do":"对物块写匀减速位移式、对板写初速为零的匀加速位移式，用同一 t 联立解出 v0 与 t","expr":"l+\\Delta l=v_0t-\\tfrac12a_1t^2,\\quad \\Delta l=\\tfrac12a_2t^2","cues":["时间一样","同时开始同时分离","两个方程两个未知数"],"concepts":["匀变速直线运动","联立方程"]},{"title":"分离后板做匀速","type":"前提判断","judge":"物块飞出后薄板是否还受水平力、做什么运动","why":"物块离开后板与物块间无摩擦力，平台光滑，板水平方向不受力，故保持分离时的速度匀速前进","do":"由分离时刻速度公式求板的速度，确认之后匀速","expr":"v_2=a_2t","cues":["没有摩擦力了","光滑平台","匀速直线"],"concepts":["惯性","匀速直线运动"]},{"title":"板中心到 O 的距离","type":"几何关系","judge":"分离时板中心离 O 点多远，落到地面时板中心还要走多远","why":"初始板右端与 O 对齐，板中心在 O 左侧 l/2 处；板已前进 Δl，故剩余距离为 l/2−Δl","do":"用板长一半减去已运动距离，得板中心还需移动的距离，再除以板速得平抛时间","expr":"s=\\frac{l}{2}-\\Delta l=\\frac{l}{3},\\quad t'=\\frac{s}{v_2}","cues":["中心在板中间","右端对齐边缘","还差三分之一板长"],"concepts":["几何关系","匀速运动"]},{"title":"平抛时间等于板运动时间","type":"临界条件","judge":"物块落地时刻与板中心到达 O 的时刻是否同一时刻，平抛时间取哪个","why":"题设“当物块落到地面时薄板中心恰好运动到 O”，两事件同时发生，故平抛下落时间等于板匀速走完剩余距离的时间","do":"把板匀速时间作为平抛时间，代入自由落体高度公式求 h","expr":"h=\\tfrac12g t'^2","cues":["恰好同时","时间相等","用板的时间算下落"],"concepts":["平抛运动","自由落体","同时性"]}],"565":[{"title":"速度图曲线的物理含义","type":"前提判断","judge":"要判断速度坐标图（vx-vy 图）中曲线长度随时间的变化率代表什么物理量","why":"题设给出'任何相等时间内 P 点沿闭合曲线通过的曲线长度相等'，曲线长度元是速度增量的大小，除以时间即为加速度大小","do":"把曲线长度元写成速度增量大小，再除以对应时间，识别出它等于加速度大小","expr":"$\\frac{\\Delta s}{\\Delta t}=\\frac{|\\Delta \\vec v|}{\\Delta t}=a$","cues":["曲线长度是速度变化","长度除以时间","就是加速度"],"concepts":["加速度定义","速度矢量图"]},{"title":"磁场中速率恒定","type":"前提判断","judge":"要判断 P 点在圆弧段运动时粒子的速率是否变化，从而确定圆周运动的速度大小","why":"洛伦兹力始终垂直于速度，只改变方向不改变速率，故圆弧段对应速率恒定","do":"取圆弧上任意一点（如 b 点）求速度分量合成，得到圆周运动速率","expr":"$v=\\sqrt{v_0^2+v_0^2}=\\sqrt2 v_0$","cues":["磁场不做功","速率不变","取b点算速度"],"concepts":["洛伦兹力","匀速圆周运动"]},{"title":"加速度大小处处相等","type":"关系建立","judge":"要判断电场段与磁场段的加速度大小必须相等，才能把电场强度与磁感应强度联系起来","why":"曲线长度通过速率恒定意味着加速度大小恒定，磁场段加速度由洛伦兹力给出，电场段由电场力给出，两者相等","do":"分别写出磁场段加速度 Bqv/m 与电场段加速度 Eq/m，令二者相等","expr":"$\\frac{Bq\\sqrt2 v_0}{m}=\\frac{Eq}{m}$","cues":["加速度一样大","两段加速度相等","用加速度搭桥"],"concepts":["牛顿第二定律","加速度大小恒定"]},{"title":"圆弧段转过的圆心角","type":"几何关系","judge":"要判断 P 点从 b 沿圆弧到 c 转过的角度，以及对应粒子在磁场中实际偏转的角度","why":"圆弧以 O 为圆心，b、c 的坐标决定其位置，圆心角由几何关系确定；粒子速度方向转过的角度等于速度矢量转过的角度","do":"在速度坐标图中由 b(v0,v0)、c(-v0,v0) 与圆心 O 求圆心角，得 270°","expr":"$\\theta=270^\\circ$","cues":["看b到c的弧","转过四分之三圈","速度方向转多少"],"concepts":["速度矢量转向","圆心角"]},{"title":"电场段类平抛的分解","type":"模型选择","judge":"要判断电场中粒子沿电场方向做匀加速、垂直电场方向做匀速，从而分别求两段位移","why":"电场沿水平方向且初速度有垂直分量，属类平抛模型，需分解到两个方向处理","do":"沿电场方向用 v0=at 求时间，垂直方向用 L=v0t 求位移","expr":"$\\frac{Eq}{m}t=v_0,\\quad L=v_0 t$","cues":["类平抛","分两个方向","垂直方向匀速"],"concepts":["类平抛运动","运动的分解"]},{"title":"一周位移的矢量合成","type":"结论整理","judge":"要判断一周后粒子位移应由磁场段位移与两段电场位移矢量叠加得到，而非简单相加路程","why":"位移是矢量，bc 段与两段电场段方向关系由对称性确定，需按矢量差合成","do":"由对称性写出总位移为 bc 段位移减去两段电场段位移之和","expr":"$x_{aa'}=x_{bc}-2L$","cues":["位移是矢量","用对称性","bc减两段L"],"concepts":["矢量合成","对称性"]}],"566":[{"title":"确定守恒定律","type":"前提判断","judge":"判断该核反应方程应依据哪条守恒定律来配平","why":"聚变反应中质量数与电荷数（核电荷数）都守恒，能量项 43.15 MeV 不参与配平，只说明反应放能","do":"写出质量数守恒与电荷数守恒两个方程，不把能量项写进方程","expr":"","cues":["质量数守恒","电荷数守恒","能量不用管"],"concepts":["核反应方程","质量数守恒","电荷数守恒"]},{"title":"数清各粒子核子数","type":"关系建立","judge":"判断氘核、氦核、中子、质子的质量数与电荷数各是多少","why":"配平方程必须用各核素的上下标，氘核质量数为 2、电荷数为 1，氦核为 4 和 2，中子为 1 和 0，质子为 1 和 1","do":"把反应式两边每种粒子的质量数与电荷数分别列出，左边 6 个氘核","expr":"","cues":["氘核是2和1","氦核是4和2","中子不带电"],"concepts":["核素符号","质量数","电荷数"]},{"title":"列两式解出未知数","type":"数学处理","judge":"判断由两个守恒方程能否唯一确定 x、y","why":"两个未知数对应两个独立方程，质量数方程与电荷数方程联立即可解出","do":"质量数方程与电荷数方程联立，先由电荷数方程解出 y，再代入质量数方程解出 x","expr":"6\\times2=2\\times4+x+y,\\quad 6=2\\times2+y","cues":["先解电荷数","再代质量数","两个方程两个未知数"],"concepts":["联立方程","核反应配平"]}],"567":[{"title":"质量与重力区分","type":"前提判断","judge":"样品从月面到地球、从正面到背面，哪个量不变、哪个量随位置改变","why":"质量是物体本身的属性，不随位置改变；重力由万有引力产生，随所在天体的 g 改变，这是判断 C 项和比较重力大小的前提","do":"把样品在各过程中的质量视为同一常量，把重力写成 mg，分别对应月球 g 与地球 g","expr":"G=mg,\\quad m\\text{ 不变}","cues":["质量不变","重力会变","换个地方重量变"],"concepts":["质量","重力","重力加速度"]},{"title":"环月飞行合力不为零","type":"模型选择","judge":"环月飞行时样品是否处于受力平衡状态","why":"环月飞行是圆周运动，需要向心力，由万有引力（合力）提供，合力必须指向月心且不为零，不能按静止平衡处理","do":"对环月飞行的样品列向心力方程，确认合力提供向心力而非为零","expr":"F_{\\text{合}}=F_{\\text{向}}\\neq 0","cues":["做圆周运动","需要向心力","合力不为零"],"concepts":["向心力","圆周运动","万有引力"]},{"title":"压力等于当地重力","type":"关系建立","judge":"样品静止放在月球（或地球）表面时，对表面的压力与自身重力是什么关系","why":"样品在表面静止，竖直方向只受重力与支持力而平衡，支持力与压力是作用力与反作用力，故压力大小等于当地重力大小","do":"对静止在表面的样品列竖直方向平衡方程，把压力替换为当地重力 mg","expr":"N=mg_{\\text{当地}}","cues":["静止放表面","压力等于重力","二力平衡"],"concepts":["压力","平衡条件","作用力与反作用力"]},{"title":"比较两地重力大小","type":"关系建立","judge":"同一块样品在月球表面与地球表面所受重力谁大","why":"月球表面自由落体加速度约为地球的 1/6，同一质量下重力与 g 成正比，故月球上重力更小，压力也更小","do":"用 g月≈g地/6 比较 mg月 与 mg地，得出月球上压力较小的结论","expr":"mg_{\\text{月}}=\\tfrac{1}{6}mg_{\\text{地}}<mg_{\\text{地}}","cues":["月球重力小","六分之一","压力更小"],"concepts":["重力","重力加速度","压力"]}],"568":[{"title":"判断作用力方向随位置变化","type":"前提判断","judge":"小环在不同位置时，大圆环对小环的弹力是背离圆心还是指向圆心","why":"小环套在环上，弹力方向由重力沿半径方向的分力与所需向心力的相对大小决定，方向判断错则力的大小变化趋势必错","do":"比较各位置重力沿半径方向的分力 mgcosθ 与所需向心力 mv²/R 的大小","expr":"mg\\cos\\theta \\gtrless m\\frac{v^2}{R}","cues":["先看谁大谁小","重力分力够不够","弹力朝里还是朝外"],"concepts":["向心力","弹力方向","牛顿第二定律"]},{"title":"用机械能守恒联系速度与位置","type":"关系建立","judge":"能否把某位置的速度用该位置与顶端的竖直高度差表示出来","why":"小环在光滑圆环上只受重力和弹力，弹力不做功，机械能守恒，这是把速度与角度挂钩的唯一途径","do":"从顶端到该点列机械能守恒方程，解出 v² 关于角度 θ 的表达式","expr":"mgR(1-\\cos\\theta)=\\frac{1}{2}mv^2","cues":["只有重力做功","从顶端算高度差","速度平方代进去"],"concepts":["机械能守恒","重力势能","动能"]},{"title":"沿半径方向列牛顿第二定律","type":"关系建立","judge":"把重力沿半径方向的分力、弹力与向心力三者按方向正确组合","why":"向心力是沿半径方向的合力，方向规定错或漏掉重力分力都会得到错误的力—角度关系","do":"沿半径方向列合力等于 mv²/R 的方程，解出弹力 F 关于 θ 的表达式","expr":"F+mg\\cos\\theta=m\\frac{v^2}{R}","cues":["沿半径方向合成","向心力指向圆心","把重力分力算进去"],"concepts":["向心力","牛顿第二定律","力的分解"]},{"title":"求弹力为零的临界位置","type":"临界条件","judge":"弹力由背离圆心变为指向圆心的转折点在哪里","why":"弹力大小先减后增，最小值出现在弹力为零处，找不准这个位置就无法判断变化趋势","do":"令 F=0，联立机械能守恒与向心力方程解出 cosθ","expr":"\\cos\\theta=\\frac{2}{3}","cues":["弹力为零那一点","先减小后增大","找转折位置"],"concepts":["临界状态","向心力","机械能守恒"]},{"title":"由表达式判断力的大小变化","type":"数学处理","judge":"弹力大小的绝对值随角度如何变化，是先减后增还是单调变化","why":"弹力是矢量，其大小取绝对值，需由 |F| 关于 cosθ 的函数判断极值位置","do":"写出 |F| 关于 cosθ 的表达式，分析其在 0 到 π 区间内的增减性","expr":"|F|=|2mg-3mg\\cos\\theta|","cues":["取绝对值再看","先减后增","最小值在转折点"],"concepts":["绝对值函数","极值","牛顿第三定律"]}],"569":[{"title":"由等势线定电荷正负","type":"前提判断","judge":"要判断 Q1、Q2 各自带正电还是负电","why":"点电荷电势 kQ/r 的符号由 Q 的符号决定，图中靠近某电荷处电势为正说明该电荷带正电，为负则带负电","do":"看图中靠近 Q1 一侧的等势线数值符号，再看靠近 Q2 一侧的数值符号","expr":"","cues":["看电势正负","靠近谁电势高","正电荷电势为正"],"concepts":["点电荷电势","电势叠加"]},{"title":"零势线上的叠加方程","type":"关系建立","judge":"要判断用哪条等势线建立两电荷电荷量的关系","why":"零电势线上两电荷电势代数和为零，是唯一能直接给出 Q1 与 Q2 比例关系的条件","do":"在图中标出电势为 0 的等势线，写出该线上任一点的电势叠加式","expr":"k\\frac{Q_1}{r_1}+k\\frac{Q_2}{r_2}=0","cues":["找零势线","电势代数和为零","用零等势线列式"],"concepts":["电势叠加原理","零势面"]},{"title":"零势线到两电荷的距离比","type":"几何关系","judge":"要判断零势线上取哪一点、该点到 Q1 和 Q2 的距离之比是多少","why":"零势线上各点都满足叠加为零，但只有取在图中能读出距离的位置（两电荷连线上的零点）才能得到确定的距离比","do":"在图中读出零势线与两电荷连线的交点到 Q1、Q2 的距离，求比值","expr":"\\frac{r_1}{r_2}=\\frac{6}{3}","cues":["取连线上的零点","读距离","量到两电荷的距离"],"concepts":["等势线分布","距离比"]},{"title":"联立求电荷量之比","type":"数学处理","judge":"要判断由零势方程和距离比如何解出 Q1/Q2 并保留符号","why":"电势叠加式与距离比联立后直接给出 Q1/Q2 的数值和符号，符号体现电性","do":"把距离比代入零势方程，解出 Q1 与 Q2 的比值","expr":"\\frac{Q_1}{Q_2}=-\\frac{r_1}{r_2}=-2","cues":["代入距离比","比值带负号","异号电荷"],"concepts":["电荷量之比","电性判断"]}],"570":[{"title":"副线圈电压由匝数比定","type":"前提判断","judge":"副线圈两端电压是否只由原线圈电压和两线圈匝数比决定，与负载电阻无关","why":"理想变压器无漏磁、无铜损，U1/U2=n1/n2，副线圈电压是'电源电压'，改变 R 只改变电流不改变它","do":"写出电压比关系，明确移动 T 改变的是 n2，从而改变副线圈电压；移动滑片只改变负载电阻","expr":"$\\dfrac{U_0}{U_2}=\\dfrac{n_1}{n_2}$","cues":["电压由匝数比定","T动才变电压","滑片不动电压"],"concepts":["理想变压器","匝数比","副线圈电压"]},{"title":"T 移动方向定电压升降","type":"关系建立","judge":"T 向 a 端或 b 端移动时，副线圈接入匝数是增多还是减少，副线圈电压随之升高还是降低","why":"由 U2 正比于 n2 判断：n2 增大则 U2 增大，n2 减小则 U2 减小","do":"比较 T 在 a、b 两端时副线圈接入的匝数多少，得出向 a 移 n2 增、向 b 移 n2 减","expr":"$U_2=\\dfrac{n_2}{n_1}U_0$","cues":["向a匝数多","向b匝数少","电压跟着匝数走"],"concepts":["匝数比","副线圈电压"]},{"title":"滑片方向定电阻增减","type":"几何关系","judge":"滑片向 e 端或 f 端滑动时，接入电路的 R 阻值是增大还是减小","why":"滑动变阻器接入的是滑片到所接端点之间的那段电阻丝，长度变长则阻值变大","do":"看图上 R 的接线端与 e、f 的相对位置，判断滑向哪端接入长度变短、阻值变小","expr":"","cues":["向f电阻变小","向e电阻变大","看接入那段长度"],"concepts":["滑动变阻器","接入电阻"]},{"title":"热功率随电流的平方变","type":"关系建立","judge":"R1 的热功率由通过它的电流决定，电流增大则功率增大，与 R 的阻值变化方向相反","why":"R1 为定值电阻，P=I²R1，功率只随电流单调变化，故只需判断电流增减","do":"把 R 与 R1 视为串联支路，用 I=U2/(R+R1) 综合电压与电阻两个变化判断电流方向","expr":"$P=I^{2}R_1,\\quad I=\\dfrac{U_2}{R+R_1}$","cues":["看电流就行","功率跟电流平方","电压电阻一起看"],"concepts":["电功率","串联电路","欧姆定律"]}],"571":[{"title":"力最大即最低点","type":"模型选择","judge":"F-t 图上的峰值时刻对应运动员运动到哪个位置","why":"蹦床弹力随形变量单调增大，弹力最大时形变最大，运动员被压到最低点，重力势能最小","do":"在图上找出 F 的最大值对应的时刻，把它与最低点对应起来，再判断该时刻重力势能是否最小","expr":"","cues":["力最大在最低点","形变最大","看峰值时刻"],"concepts":["弹力与形变","重力势能"]},{"title":"离床时刻读图","type":"图像读取","judge":"图上哪一段是运动员与蹦床接触、哪一段是腾空","why":"运动员不与蹦床接触时蹦床水平，作用力为零，F-t 图上 F=0 的区间就是腾空阶段","do":"读出 F 由非零降为零的时刻（离床）和由零升为非零的时刻（再落床），得到腾空时长","expr":"","cues":["力为零就是腾空","找离床时刻","看零力区间"],"concepts":["接触与分离","F-t 图像"]},{"title":"腾空对称求速度","type":"关系建立","judge":"能否用腾空总时长的一半作为上升时间，并据此求离床速度","why":"腾空阶段只受重力，运动是竖直上抛，上升与下落时间对称，上升时间等于腾空总时间的一半","do":"取腾空总时间的一半为上升时间，用速度公式求离床速度，并确定最高点对应的时刻","expr":"$t_{\\text{上}}=\\frac{\\Delta t_{\\text{空}}}{2},\\quad v=g\\,t_{\\text{上}}$","cues":["上升下落时间相等","一半时间","竖直上抛对称"],"concepts":["竖直上抛运动","对称性"]},{"title":"接触段用动量定理","type":"关系建立","judge":"求平均作用力时该对哪一段过程、以哪个方向为正列动量定理","why":"接触段运动员受重力与蹦床弹力共同作用，速度由落床时的向下变为离床时的向上，动量变化需计入重力冲量","do":"取接触段为过程，规定竖直向上为正，写出合外力冲量等于动量变化，解出平均弹力","expr":"$\\bar F\\Delta t-mg\\Delta t=mv-(-mv)$","cues":["取接触段","先定正方向","重力冲量不能漏"],"concepts":["动量定理","冲量"]},{"title":"落床速度由对称得出","type":"前提判断","judge":"落床速度大小是否等于离床速度大小","why":"腾空阶段机械能守恒且高度回到同一水平面，落床速率与离床速率相等","do":"直接用离床速率作为落床速率代入动量定理，不必另设未知量","expr":"$|v_{\\text{落}}|=|v_{\\text{离}}|$","cues":["同一高度速率相同","落床离床一样快","不用另算"],"concepts":["机械能守恒","竖直上抛"]}],"572":[{"title":"测力计读数","type":"图像读取","judge":"弹簧测力计的分度值是多少、指针落在哪一格，读数应读到哪一位","why":"弹簧测力计读数需先确定分度值再估读，分度值决定读数的最小位数，读错则重力 G 全错","do":"观察图中相邻两刻度线代表的牛数，确定分度值，再读指针所指刻度并保留一位小数","expr":"","cues":["先看分度值","一格是半个牛","读到小数点后一位"],"concepts":["弹簧测力计","分度值","读数"]},{"title":"静止时示数等于重力","type":"前提判断","judge":"电梯静止时测力计示数是否等于物体重力","why":"静止时物体受力平衡，弹簧拉力与重力大小相等，这是后面求质量和加速度的基础","do":"把（1）的读数直接作为重力 G，再由 G=mg 求质量 m","expr":"$G=mg$","cues":["静止时拉力等于重力","先求质量","示数就是重力"],"concepts":["二力平衡","重力"]},{"title":"由示数比较判断超失重","type":"关系建立","judge":"示数 4.5 N 与重力 5.0 N 谁大，据此判断超重还是失重","why":"示数小于重力说明支持力（拉力）不足以平衡重力，合力向下、加速度向下，属于失重；与电梯上行还是下行无关","do":"比较拉力 T 与重力 G 的大小，T<G 判为失重","expr":"$T<G\\Rightarrow$ 失重","cues":["示数变小了","拉力小于重力","别被上行骗了"],"concepts":["超重与失重","视重"]},{"title":"加速度方向与牛顿第二定律","type":"模型选择","judge":"加速度方向取向下，合力应写成重力减拉力还是拉力减重力","why":"失重时加速度方向向下，取向下为正，合力为 mg-T，由牛顿第二定律 mg-T=ma 求 a","do":"对物体受力分析，沿竖直方向列 mg-T=ma，代入 G=5.0 N、T=4.5 N、m=G/g 求 a","expr":"$mg-T=ma$","cues":["加速度向下","合力向下","重力减拉力"],"concepts":["牛顿第二定律","受力分析","失重"]}],"573":[{"title":"滑动变阻器接法选择","type":"模型选择","judge":"要判断滑动变阻器用限流式还是分压式接入电路","why":"传感器阻值随氧气含量变化范围大，且要求传感器两端电压能从零开始连续调节，限流式无法把电压调到零且调节范围窄","do":"比较两种接法的电压调节范围，确认需要从零起调，选分压式并据此连线","expr":"","cues":["分压式","电压要从零调","限流调不到零"],"concepts":["分压接法","限流接法","电压调节范围"]},{"title":"电流表内外接判断","type":"前提判断","judge":"要判断毫安表应接在传感器哪一侧、用内接还是外接","why":"毫安表内阻可忽略，其压降不影响传感器两端电压的测量，故电流表串联在干路中即可，电压表直接并联在传感器两端","do":"依据毫安表内阻可忽略这一条件，确定电压表并联在传感器两端、毫安表串联在支路中","expr":"","cues":["毫安表内阻可忽略","电压表并联在传感器上","电流表串在支路"],"concepts":["内接法","外接法","电表内阻"]},{"title":"闭合开关前滑片位置","type":"实验操作","judge":"要判断闭合开关前滑片应置于 a 端还是 b 端","why":"分压式接法中滑片置于使传感器两端电压为零的一端，才能保护传感器和电表，避免闭合瞬间电流过大","do":"找出使传感器两端分压为零的滑片位置，即滑到 a 端","expr":"","cues":["保护电路","电压先调到零","滑到a端"],"concepts":["分压电路","电学实验安全操作"]},{"title":"电压表估读规则","type":"数据处理","judge":"要判断电压表读数应估读到哪一位","why":"电压表分度值为 0.1 V，需估读到分度值的下一位，即读到 0.01 V","do":"观察图(c)指针位置，按 0.1 V 分度值向下估读一位，记录两位小数","expr":"","cues":["分度值0.1伏","估读一位","读到百分位"],"concepts":["电压表读数","估读"]},{"title":"描点连线与曲线外推","type":"图像读取","judge":"要判断如何由已标数据点和 20% 对应点得到完整定标曲线","why":"电压与氧气含量不是线性关系，需用平滑曲线连接各点，才能由 1.50 V 反查氧气含量","do":"在图上补描 20% 对应的点，用平滑曲线连接全部数据点，再由纵轴 1.50 V 对应到横轴读数","expr":"","cues":["描点","平滑曲线","由电压反查含量"],"concepts":["定标曲线","图像法处理数据"]}],"574":[{"title":"加速段末速度","type":"关系建立","judge":"匀加速段结束时速度由加速度和时间决定，是否直接用速度公式求末速度","why":"题设给出初速度为零、加速度恒定、加速时间 10 s，匀变速直线运动速度公式适用","do":"用速度公式求 t1 时刻的速度，作为匀速段速度","expr":"v=at_1","cues":["先算加速末速度","匀加速到十秒"],"concepts":["匀变速直线运动","速度公式"]},{"title":"加速段位移","type":"关系建立","judge":"求匀速段路程前，是否先算出加速阶段走过的位移","why":"总距离由加速段位移与匀速段位移相加，加速段位移不能漏","do":"用位移公式求 0 到 t1 内的位移","expr":"x_1=\\frac{1}{2}at_1^2","cues":["先算加速走多远","位移要加上"],"concepts":["匀变速直线运动","位移公式"]},{"title":"声音传播时间对应路程","type":"模型选择","judge":"最后一声从停止鸣笛处传到出发点所用时间，对应的是哪段路程","why":"声音匀速传播，传播时间等于声音走过的路程除以声速，而该路程正是停止鸣笛时车距出发处的距离","do":"把声音传播时间写成停止鸣笛时车距出发处的距离除以声速","expr":"t_{\\text{声}}=\\frac{x}{v_0}","cues":["声音走的路程就是车距","用声速除路程"],"concepts":["匀速直线运动","声速"]},{"title":"总时间由两段构成","type":"关系建立","judge":"t2 是从出发到人听到最后一声的总时间，它由鸣笛停止时刻与声音传播时间相加构成","why":"声音在 t3 时刻发出，再经传播时间才被听到，两个时间段首尾相接","do":"列出 t3 与声音传播时间之和等于 t2 的时间关系","expr":"t_3+\\frac{x}{v_0}=t_2","cues":["总时间分两段","鸣笛时刻加传播时间"],"concepts":["时间关系","追及与传播"]},{"title":"车距用分段位移表示","type":"关系建立","judge":"停止鸣笛时车距出发处的距离要用加速段位移加匀速段位移表示，而不是只用匀速段","why":"车先加速后匀速，总位移是两段位移之和，匀速段时间为 t3 减 t1","do":"写出总距离关于 t3 的表达式，与时间关系联立消去 t3","expr":"x=x_1+v(t_3-t_1)","cues":["两段位移相加","匀速段时间要减十秒"],"concepts":["分段位移","匀速直线运动"]}],"575":[{"title":"最大速度定外力","type":"临界条件","judge":"开关闭合、恒力拉动时，速度达到最大对应什么受力条件","why":"速度最大时加速度为零，水平方向外力与安培力平衡，这是把已知最大速度 v0 与恒定外力 F 联系起来的唯一桥梁","do":"对金属棒列水平方向平衡方程，用 E=BLv0、I=E/R 把安培力写成含 v0 的表达式，反解出 F","expr":"F=BIL=\\frac{B^{2}L^{2}v_{0}}{R}","cues":["速度最大时受力平衡","安培力等于外力","先求恒定外力"],"concepts":["安培力","平衡条件","法拉第电磁感应定律"]},{"title":"区分两种功率","type":"关系建立","judge":"外力功率与电阻功率分别用哪个速度、哪个电流表达，二者不是同一个量","why":"外力功率是 Fv（F 由 v0 决定），电阻功率是 I²R（I 由瞬时 v 决定），混用同一个速度就会把方程写错","do":"分别写出 P_F=Fv 与 P_R=I²R，代入 I=BLv/R，再令 P_F=2P_R 消去公共因子","expr":"\\frac{B^{2}L^{2}v_{0}}{R}v=2\\frac{B^{2}L^{2}v^{2}}{R}","cues":["外力功率用哪个速度","电阻功率用瞬时电流","两个功率别混"],"concepts":["功率","焦耳定律","感应电动势"]},{"title":"断开后电路重构","type":"模型选择","judge":"断开 S 后，电容与电阻是串联还是并联，回路方程怎么写","why":"S 断开后电阻不再与电源单独成回路，而是与电容器串联，电容器电压不能简单等于 BLv，必须用含 q/C 的回路方程","do":"沿回路写电动势等于电阻压降加电容电压，明确电流由电容器充电产生","expr":"BLv=IR+\\frac{q}{C}","cues":["电容与电阻串联","电压要分给电容","不能只看电阻"],"concepts":["含容电路","基尔霍夫电压定律","电容充电"]},{"title":"匀速下电流衰减","type":"前提判断","judge":"金属棒匀速时，拉力是否恒定、电流是否恒定","why":"匀速只说明合力为零，拉力须随安培力变化而调整；电容器持续充电使电流不断减小，故拉力、功率都是瞬时量，功率条件只能取某一时刻","do":"由匀速得 F'=BIL，写出 P_F=BILv、P_R=I²R，令 P_F=2P_R 解出该时刻的 IR","expr":"BILv=2I^{2}R\\Rightarrow IR=\\frac{BLv}{2}","cues":["匀速但电流在变","拉力跟着安培力变","功率条件取瞬时"],"concepts":["安培力","瞬时功率","匀速运动"]},{"title":"电容电压由分压得","type":"关系建立","judge":"功率条件给出的 IR 如何转成电容器两端电压","why":"回路方程中 BLv=IR+U_C，已知 IR 占电动势的一半，剩余部分才是电容电压，不能把 BLv 直接当电容电压","do":"把 IR=BLv/2 代入回路方程求 U_C，再用第（1）问的 v 与 v0 关系换算","expr":"U_{C}=BLv-IR=\\frac{BLv}{2}","cues":["电容电压是剩余部分","电动势减去电阻压降","用第一问的速度关系"],"concepts":["电容电压","分压关系","感应电动势"]},{"title":"变力求功用电荷量","type":"数学处理","judge":"拉力是变力，求外力功能否直接 F·s，还是要对元功求和","why":"电流随时间减小，拉力是变力，不能乘位移；但每一小段做功 BILvΔt=BLv·IΔt，求和后只剩总电荷量 q","do":"把外力元功写成 BLv·Δq 并对全过程求和，q 由该时刻电容电压乘 C 得到","expr":"W=BLv\\sum I\\Delta t=BLv\\,q,\\quad q=CU_{C}","cues":["变力不能直接乘位移","元功求和","功转成电荷量"],"concepts":["变力做功","电荷量","电容"]}],"576":[{"title":"饱和汽压随温度变化","type":"前提判断","judge":"试管内水面上方封闭气体的饱和汽压由什么决定、随温度怎样变化","why":"饱和汽压只由物质种类和温度决定，与体积、是否另有气体无关；温度越高饱和汽压越大","do":"比较 a、b、c、d 四杯水的温度高低，按温度顺序排出各自饱和汽压的大小","expr":"","cues":["只看温度","温度高汽压大","与体积无关"],"concepts":["饱和汽压","温度"]},{"title":"管内气压的静力学关系","type":"关系建立","judge":"试管内外水面高度差的正负与管内气体压强相对大气压是偏大还是偏小","why":"管内气体被水柱与大气隔开，由连通器静压强平衡，管内气压等于大气压加上（或减去）水柱产生的压强","do":"对管内水面列压强平衡式，按管内水面低于或高于外水面确定水柱压强的正负号","expr":"$p=p_0\\pm\\rho g\\Delta h$","cues":["看水面高低","水柱加还是减","内外压强平衡"],"concepts":["液体静压强","压强平衡"]},{"title":"区分倒立与正立水柱","type":"模型选择","judge":"a、b、c 中管内水面低于外水面、d 中管内水面高于外水面，各自对应加号还是减号","why":"管内水面低时水柱向下压管内气体，管内气压大于大气压；管内水面高时管内气压小于大气压","do":"对 a、b、c 用加号形式，对 d 用减号形式，写出各自的压强表达式","expr":"$p_{a,b,c}=p_0+\\rho g\\Delta h,\\quad p_d=p_0-\\rho g\\Delta h$","cues":["低的加压","高的减压","d是负号"],"concepts":["压强平衡","高度差"]},{"title":"同温差下比较气压","type":"结论整理","judge":"c 与 d 温度相同、饱和汽压相同，能否直接由高度差符号判断两者气压大小","why":"饱和汽压相同不代表管内气压相同，管内气压还取决于水柱方向；d 中水柱使气压低于大气压，c 中高于大气压","do":"先由温度相同得饱和汽压相等，再比较两管气压表达式的大小关系","expr":"$p_d=p_0-\\rho g\\Delta h<p_0<p_c=p_0+\\rho g\\Delta h$","cues":["温度同汽压同","气压还要看水柱","d比c小"],"concepts":["饱和汽压","压强平衡"]}],"577":[{"title":"确定两卡销间体积比","type":"几何关系","judge":"要判断活塞在 a、b 两位置时封闭气体的体积之比，而不是把 ab 当成体积或把 bc 当成总体积","why":"体积由活塞到缸底的距离决定，b 到缸底为 bc=10ab，a 到缸底为 ab+bc=11ab，故 V1:V2=11:10","do":"把 a、b 到缸底的距离分别写成 11ab 和 10ab，再乘面积 S 得两态体积","expr":"V_1=S\\cdot 11ab,\\quad V_2=S\\cdot 10ab","cues":["距离比就是体积比","a到缸底是十一份","b到缸底是十份"],"concepts":["等温变化","体积"]},{"title":"判断 a 到 b 为等温","type":"模型选择","judge":"要判断活塞从 a 缓慢移到 b 的过程中气体经历的是等温过程，可用玻意耳定律","why":"题设明确'过程中气体温度视为不变'，缓慢移动保证气体与外界充分换热","do":"对 a、b 两态列 p1V1=p2V2，求出活塞到 b 时缸内压强","expr":"p_1V_1=p_2V_2","cues":["温度不变用玻意耳","缓慢就是等温","先求到b时的压强"],"concepts":["玻意耳定律","等温过程"]},{"title":"活塞受力平衡定支持力","type":"关系建立","judge":"要判断活塞在 b 处受哪几个力、卡销 b 的支持力方向朝上，并选活塞为对象列平衡式","why":"活塞轻质（重力可忽略）且无摩擦，受外力 F、大气压向下压力、气体向上压力、卡销支持力，四力平衡","do":"沿竖直方向列平衡方程，把已求出的 p2 与 F=200 N、p1、S 代入解 N","expr":"F+p_1S=p_2S+N","cues":["取活塞为对象","轻活塞不算重力","支持力向上"],"concepts":["受力平衡","压强与压力"]},{"title":"判离开 b 的临界压强","type":"临界条件","judge":"要判断'活塞刚好离开卡销 b'的临界条件是卡销支持力恰好为零，此时气体压强由力平衡唯一确定","why":"支持力为零是活塞即将上移的临界点，此时 F 与大气压力仍不变，气体压力须恰好平衡它们","do":"令 N=0，由同一平衡式解出临界压强 p3","expr":"p_3S=F+p_1S\\Rightarrow p_3=1.2\\times10^{5}\\,\\mathrm{Pa}","cues":["支持力刚好为零","刚要离开就是临界","压强由力平衡定"],"concepts":["临界状态","受力平衡"]},{"title":"判断升温段为等容","type":"模型选择","judge":"要判断从 b 处升温到刚离开 b 之前气体体积不变，应使用查理定律而非理想气体状态方程全式","why":"活塞被卡销挡住不能上移，体积保持 V2 不变，只有压强随温度升高","do":"以 p2、T2=300 K 为初态，p3 为末态列等容关系求 T3","expr":"\\frac{p_2}{T_2}=\\frac{p_3}{T_3}","cues":["体积没变用等容","卡着不动体积不变","压强随温度升"],"concepts":["查理定律","等容过程"]}],"578":[{"title":"读图取波长","type":"图像读取","judge":"从波形图上读出相邻同相点（波峰到波峰或平衡点同向过零点）的水平距离，确定波长","why":"波速由 v=λ/T 决定，λ 必须从图上量出，不能凭周期猜","do":"在图上找相邻两个波峰（或相邻两个同向过平衡位置的点），读出横坐标差","expr":"\\lambda=2\\,\\mathrm{m}","cues":["看相邻波峰","横坐标差两米","图上量波长"],"concepts":["波长","波形图"]},{"title":"由振动方向定传播方向","type":"前提判断","judge":"由质点 b 此刻向 y 轴负方向运动，判断波是沿 x 轴正方向还是负方向传播","why":"质点振动方向与波传播方向由波形平移法（或同侧法）唯一对应，方向判反则后面所有时刻的位移、速度全错","do":"画出 b 附近波形微小平移后的形状，看哪种平移能使 b 点下移，据此定传播方向","expr":"","cues":["波形平移法","同侧法","b往下走"],"concepts":["波的传播方向","质点振动方向"]},{"title":"相距半波长的点反相","type":"关系建立","judge":"判断 a、c 两点间距与半波长的关系，从而确定两点振动步调是相同还是相反","why":"相距 nλ 的点同相，相距 (2n+1)λ/2 的点反相，这是判断任意时刻两点运动方向关系的依据","do":"比较 a、c 横坐标差与 λ/2，得出两点反相，再推任意时刻运动方向相反","expr":"\\Delta x_{ac}=\\frac{\\lambda}{2}\\Rightarrow \\text{反相}","cues":["差半个波长","振动完全相反","步调相反"],"concepts":["相位差","反相点"]},{"title":"用周期分数推特定时刻状态","type":"数学处理","judge":"把给定时刻 t 换算成周期的几分之几，判断质点从初态经过该时间后到达哪个位置、向哪个方向运动","why":"简谐振动经 T/4 从波峰到平衡位置、经 3T/4 从平衡位置到波峰，只有把时间折成周期分数才能定位状态","do":"对 a 取 t=0.5s=T/4，对 b 取 t=1.5s=3T/4，分别由初态推末态位置与速度","expr":"t_a=\\frac{T}{4},\\quad t_b=\\frac{3T}{4}","cues":["四分之一周期","四分之三周期","从波峰往下走"],"concepts":["简谐振动周期性","振动状态"]},{"title":"波峰处速度为零","type":"临界条件","judge":"判断质点位于波峰（最大位移处）时速率是否为零","why":"简谐振动在最大位移处速度为零、加速度最大，这是判断 b 在 t=1.5s 速率的关键","do":"确认 b 在 t=1.5s 处于波峰，据最大位移处速度为零判定其速率","expr":"v\\big|_{y=A}=0","cues":["波峰速度为零","最大位移处","速率为零"],"concepts":["简谐振动速度","最大位移"]}],"579":[{"title":"确定入射点几何","type":"几何关系","judge":"要判断平行光线距 AB 为 h 时，在圆弧上的入射点位置与入射角 α 由什么几何量决定","why":"入射角是法线（半径）与光线的夹角，必须把 h 与半径方向联系起来才能用折射定律","do":"过入射点作半径（法线），由光线平行 AB 找出半径与 AB 的夹角，得到入射角 α 与 h、R 的关系","expr":"\\sin\\alpha=\\frac{h}{R}","cues":["法线是半径","光线平行AB","入射角看半径"],"concepts":["法线","入射角","圆的几何"]},{"title":"判断 BC 面入射角","type":"关系建立","judge":"要判断折射光线射到 BC 边时，在 BC 面的入射角与折射角 β 及临界角 C 之间满足什么角度关系","why":"全反射条件取决于光在 BC 面的入射角，而该角需由光路三角形的外角关系从 β 推出","do":"画出折射光线与 BC 的交点，利用三角形内角和外角关系，把 BC 面入射角写成 β+C 的形式","expr":"\\alpha=\\beta+C","cues":["外角等于两内角和","折射光线与BC相交","把β和C拼起来"],"concepts":["光路图","外角关系","全反射入射角"]},{"title":"取恰好全反射临界","type":"临界条件","judge":"要判断“恰好发生全反射”对应 BC 面入射角等于临界角，而不是大于或小于","why":"恰好全反射是临界状态，此时折射角为 90°，入射角取临界角 C","do":"令 BC 面入射角等于临界角，写出临界角正弦与折射率的关系","expr":"\\sin C=\\frac{1}{n}=\\frac{\\sqrt{3}}{3}","cues":["恰好全反射就是临界角","折射角九十度","临界角由折射率定"],"concepts":["全反射","临界角","折射率"]},{"title":"联立折射与临界","type":"数学处理","judge":"要判断如何把折射定律、角度关系、临界角三式联立，消去 α 和 C 只留 β","why":"未知量有三个（α、β、C），必须用三条独立关系消元才能解出 β","do":"将 α=β+C 代入折射定律，用 sinC、cosC 的数值展开 sin(β+C)，整理成只含 tanβ 的方程","expr":"\\frac{\\sin(\\beta+C)}{\\sin\\beta}=\\sqrt{3}","cues":["三式联立","消掉α和C","展开和角公式"],"concepts":["折射定律","消元","和角公式"]},{"title":"由 β 回求 h/R","type":"结论整理","judge":"要判断最终所求 h/R 应通过 sinα 而不是直接由 β 给出","why":"h/R 的几何表达式是 sinα，而 α 与 β 由折射定律相连，需先解出 β 再换算","do":"由 tanβ 求出 sinβ，再用 sinα=√3 sinβ 得到 h/R","expr":"\\frac{h}{R}=\\sin\\alpha=\\sqrt{3}\\sin\\beta","cues":["先解β再换α","h比R就是sinα","最后回代"],"concepts":["折射定律","三角函数换算"]}],"580":[{"title":"确定经历几个半衰期","type":"关系建立","judge":"要判断经过的 48 天相当于几个半衰期","why":"半衰期是每衰变一半所需的时间，剩余质量只由经过的半衰期个数决定，与初始质量无关","do":"用总时间除以半衰期，算出半衰期个数","expr":"n=\\frac{t}{T_{1/2}}=\\frac{48}{24}=2","cues":["先算几个半衰期","48除以24"],"concepts":["半衰期","衰变时间"]},{"title":"剩余质量按半衰期递减","type":"模型选择","judge":"要判断剩余质量随半衰期个数按什么规律减少","why":"每经过一个半衰期，剩余未衰变的原子核数（质量）减为原来的一半，是逐次乘 1/2 而非线性减少","do":"写出剩余质量与初始质量、半衰期个数的关系式","expr":"m=m_0\\left(\\frac{1}{2}\\right)^{n}","cues":["每过一个半衰期剩一半","不是减一半质量"],"concepts":["半衰期","指数衰减"]},{"title":"代入初始质量求剩余","type":"数学处理","judge":"要把半衰期个数和初始质量代入关系式算出剩余质量","why":"题目给出初始质量 1 g，只有把 n=2 代入指数式才能得到具体数值","do":"将 n=2、m0=1 g 代入并计算","expr":"m=1\\times\\left(\\frac{1}{2}\\right)^{2}=0.25\\,\\mathrm{g}","cues":["四分之一克","两次减半"],"concepts":["剩余质量"]}],"581":[{"title":"识别末速度为零","type":"前提判断","judge":"制动停止意味着末速度取零，而不是某个非零值","why":"题设明确'经2s停止'，末速度为零是使用平均速度公式或逆向思维的前提","do":"确认 t=2s 时刻 v=0，把运动看成初速10m/s、末速0的匀减速过程","expr":"v_t=0","cues":["停止就是速度为零","末速取零"],"concepts":["匀减速直线运动","末速度"]},{"title":"选平均速度求位移","type":"模型选择","judge":"已知初速、末速和时间，是否用平均速度公式直接求位移，而不去先求加速度","why":"匀变速直线运动中平均速度等于初末速度的算术平均，位移等于平均速度乘时间，一步到位且避免求加速度的额外运算","do":"写出位移等于初末速度之和的一半乘以时间，代入10、0、2","expr":"x=\\frac{v_0+v_t}{2}t","cues":["用平均速度","不用求加速度","初末速度平均"],"concepts":["平均速度","匀变速直线运动"]},{"title":"排除加速度干扰","type":"结论整理","judge":"是否意识到先求加速度再代位移公式会多绕一步，且容易算错","why":"加速度 a=(0-10)/2=-5m/s² 只是中间量，题目只问位移，不必显式求出","do":"比较两条路径，确认平均速度法只需一次代入","expr":"a=\\frac{v_t-v_0}{t}","cues":["不用算加速度","直接代公式"],"concepts":["加速度","位移公式"]}],"582":[{"title":"气泡压强随深度变化","type":"关系建立","judge":"气泡内压强由外界大气压和上方水柱压强共同决定，上浮时水柱高度减小","why":"气泡与周围水接触，内部压强必须与外部压强平衡，外部压强为大气压加上方水柱产生的压强","do":"写出气泡内压强表达式，判断上浮时 h 减小导致 p 减小","expr":"$p=p_0+\\rho_{\\text{水}}gh$","cues":["看水深","水柱压强","越往上压强越小"],"concepts":["液体压强","压强平衡"]},{"title":"恒温下体积与压强反比","type":"前提判断","judge":"恒温水槽意味着气体温度不变，分子数不变，可对气泡内气体用玻意耳定律","why":"题目明确恒温水槽且分子个数不变，温度不变是使用 pV=常量 的前提","do":"由压强减小推出体积增大","expr":"$pV=C$","cues":["温度不变","等温变化","压强小体积大"],"concepts":["玻意耳定律","理想气体"]},{"title":"体积膨胀对外做功与吸热","type":"关系建立","judge":"体积增大时气体对外做功，结合温度不变内能不变，判断热量传递方向","why":"热力学第一定律 ΔU=Q+W，等温理想气体 ΔU=0，体积增大对外做功使 W 为负","do":"由 ΔU=0 和对外做功推出气体必须吸热","expr":"$\\Delta U=Q+W=0$","cues":["内能不变","对外做功","要吸热"],"concepts":["热力学第一定律","内能","做功"]},{"title":"对接体整体求加速度","type":"模型选择","judge":"飞船与空间站一起运动，加速度相同，可把两者视为一个整体避开内部作用力","why":"两者速度、加速度一致，整体法只需考虑外力 F，避免引入未知的内部作用力","do":"对整体列牛顿第二定律求共同加速度","expr":"$a=\\frac{F}{M+m}$","cues":["取整体","加速度相同","先求加速度"],"concepts":["整体法","牛顿第二定律"]},{"title":"隔离空间站求相互作用力","type":"模型选择","judge":"求两者之间的作用力必须隔离其中一个物体，选受力较简单的空间站","why":"内部作用力在整体法中消去，只有隔离单个物体才能让它出现在方程中","do":"对空间站单独列方程，代入共同加速度求解","expr":"$F'=Ma=\\frac{M}{M+m}F$","cues":["隔离空间站","只看推力","内部力"],"concepts":["隔离法","牛顿第二定律"]}],"583":[{"title":"区分峰值与有效值","type":"前提判断","judge":"图乙给出的 24 V 是交流电压的峰值还是有效值","why":"正弦交流电的有效值等于峰值除以根号二，变压器电压比用的是有效值，把峰值当有效值会算错匝数比","do":"从图乙读出峰值，再换算成原线圈电压有效值","expr":"U_1=\\frac{U_m}{\\sqrt{2}}","cues":["看图读峰值","先换成有效值"],"concepts":["正弦交流电","有效值","峰值"]},{"title":"灯泡额定值定副线圈","type":"关系建立","judge":"灯泡正常发光时副线圈的电压和电流各取多少","why":"额定电压 6 V、额定功率 3 W 就是正常发光时副线圈两端的电压和通过的电流，是联系原副线圈的桥梁","do":"用额定功率除以额定电压求副线圈电流有效值","expr":"I_2=\\frac{P_L}{U_2}=\\frac{3}{6}","cues":["正常发光就是额定","先求副线圈电流"],"concepts":["额定电压","额定功率","理想变压器"]},{"title":"匝数比用有效值之比","type":"关系建立","judge":"原副线圈匝数比由哪两个电压决定","why":"理想变压器电压比等于匝数比，且必须用有效值相比，不能用峰值","do":"把原线圈有效值与副线圈额定电压相比得匝数比","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2}","cues":["电压比等于匝数比","用有效值比"],"concepts":["理想变压器","匝数比"]},{"title":"功率由副线圈决定","type":"结论整理","judge":"原线圈输入功率与副线圈输出功率的关系","why":"理想变压器无能量损失，输入功率等于输出功率，不能把输入电压乘副线圈电流当输入功率","do":"比较输入功率与灯泡额定功率是否相等","expr":"P_1=P_2=P_L","cues":["理想变压器不耗能","功率看副线圈"],"concepts":["理想变压器","功率守恒"]},{"title":"稳定时磁通量不变","type":"临界条件","judge":"开关闭合达到稳定后，穿过线圈 P 的磁通量是否变化","why":"感应电流产生的条件是磁通量变化，稳定后铁芯中磁场恒定，P 中无感应电流","do":"判断稳定后磁通量是否随时间改变，从而确定电流表示数","expr":"\\frac{\\Delta\\Phi}{\\Delta t}=0","cues":["稳定后磁场不变","没有磁通量变化"],"concepts":["电磁感应","磁通量","感应电流产生条件"]},{"title":"断开瞬间用楞次定律定方向","type":"关系建立","judge":"断开开关瞬间 P 中感应电流的磁场方向及电流表电流方向","why":"原磁场向右且磁通量减小，由楞次定律感应磁场要阻碍减小，故感应磁场向右，再由安培定则定电流方向","do":"先判原磁场方向与增减，再定感应磁场方向，最后用右手螺旋定则定电流表电流方向","expr":"","cues":["先看原磁场方向","磁通量在减小","感应磁场要补上"],"concepts":["楞次定律","安培定则","感应磁场"]}],"584":[{"title":"恰好到最高点的临界条件","type":"临界条件","judge":"物体恰好能到达最高点 C 时，在 C 点受哪些力、速度满足什么条件","why":"恰好到达意味着轨道对物体的弹力刚好为零，重力单独提供向心力；若误以为 C 点速度为零，就会把临界速度算错","do":"对 C 点受力分析，只保留重力，列向心力方程","expr":"mg=m\\dfrac{v_C^2}{r}\\Rightarrow v_C=\\sqrt{gr}","cues":["最高点速度为零","只受重力","弹力刚好为零"],"concepts":["向心力","临界条件","牛顿第二定律"]},{"title":"向心加速度的求法","type":"关系建立","judge":"C 点的向心加速度由什么决定，是否等于重力加速度","why":"向心加速度只由该点速度和半径决定，而临界条件下速度与半径的关系恰好使 a=v²/r=g，与质量无关","do":"把临界速度代入向心加速度定义式，与 g 比较","expr":"a=\\dfrac{v_C^2}{r}=g","cues":["向心加速度等于g","用速度平方比半径","和重力加速度比"],"concepts":["向心加速度","圆周运动"]},{"title":"弹性势能的去向","type":"模型选择","judge":"从 A 到 C 全过程中，弹簧的弹性势能转化成了哪些能量","why":"轨道光滑、只有重力和弹簧弹力做功，机械能守恒；弹性势能应等于 C 点的动能与重力势能之和，漏掉动能或重力势能都会出错","do":"以 A 点弹簧原长为零势能参考，对 A 到 C 列能量守恒式","expr":"E_p=mg\\cdot 2r+\\tfrac12 mv_C^2","cues":["取全过程能量守恒","别忘了C点动能","高度差是两倍半径"],"concepts":["机械能守恒","弹性势能","重力势能"]}],"585":[{"title":"阻力方向随运动方向变","type":"前提判断","judge":"上升段和下落段空气阻力分别指向哪一侧","why":"阻力方向总与速度方向相反，上升时向下、下落时向上，这决定了合力是重力加阻力还是重力减阻力","do":"分别对上升段和下落段画受力图，标出重力与阻力的方向","expr":"","cues":["阻力跟速度反向","上升时阻力向下","下落时阻力向上"],"concepts":["空气阻力","受力分析"]},{"title":"同位置上升速度更大","type":"关系建立","judge":"经过同一高度时，上升速度与下落速度哪个大","why":"全程阻力做负功，机械能不断减少，同一高度处上升阶段的机械能（动能）必大于下落阶段","do":"对从抛出到某高度、以及从最高点到该高度两段分别用能量关系比较动能","expr":"","cues":["阻力一直做负功","同一高度上升时更快","机械能一直在减少"],"concepts":["动能定理","机械能"]},{"title":"加速度大小比较","type":"关系建立","judge":"上升段与下落段在同一位置的加速度哪个大","why":"由牛顿第二定律，上升时合力为重力加阻力、下落时为重力减阻力，同一位置速度大则阻力大，故上升段加速度更大","do":"写出两段的牛顿第二定律方程并比较合力大小","expr":"","cues":["上升合力更大","加速度看合力","同一位置阻力不同"],"concepts":["牛顿第二定律","合力"]},{"title":"时间由平均速度定","type":"关系建立","judge":"上升时间与下落时间哪个长","why":"两段路程相同，上升段每个位置速度都更大，平均速度更大，故上升时间更短","do":"比较两段平均速度，再由路程相同比较时间","expr":"","cues":["路程一样","上升平均速度大","上升时间短"],"concepts":["平均速度","运动时间"]},{"title":"冲量用动量定理比较","type":"模型选择","judge":"比较两段合力冲量时选动量定理还是逐段积分","why":"合力的冲量等于动量变化量，只需比较初末动量大小，不必求变力的积分","do":"对上升段和下落段分别写动量定理，比较动量变化量的大小","expr":"","cues":["冲量看动量变化","用动量定理","别去积分变力"],"concepts":["动量定理","冲量"]}],"586":[{"title":"加速度方向定位置","type":"关系建立","judge":"由加速度的正负判断手机相对平衡位置在上方还是下方","why":"简谐振动中加速度方向总指向平衡位置，a>0（向上）说明位移在平衡位置下方，a<0 说明在上方","do":"读图乙中某时刻 a 的正负，结合向上为正的约定，反推手机位于平衡位置哪一侧","expr":"a=-\\omega^2 x","cues":["向上为正","加速度指平衡位置","正就偏下"],"concepts":["简谐振动","回复力","加速度方向"]},{"title":"a=0 处即平衡位置","type":"临界条件","judge":"判断 a=0 的时刻手机是否处于平衡位置、此时弹簧弹力与重力是否平衡","why":"平衡位置处回复力为零，合力为零，弹簧弹力大小等于重力；a=0 不代表弹力为零","do":"在 t=0 处令 a=0，由合力为零得弹簧弹力等于 mg","expr":"F-mg=ma=0\\Rightarrow F=mg","cues":["加速度为零","合力为零","弹力等于重力"],"concepts":["平衡位置","牛顿第二定律","合力"]},{"title":"由 a-t 图读周期","type":"图像读取","judge":"从正弦曲线的一个完整波形读出振动周期 T","why":"a-t 曲线与位移同周期，相邻两个同向零点或相邻峰值间隔即为一个周期","do":"在图上找相邻两个 a=0 且斜率同号的点，读出时间间隔","expr":"T=0.8\\,\\mathrm{s}","cues":["看一个完整波形","相邻零点","周期是0.8秒"],"concepts":["周期","简谐振动图像"]},{"title":"峰值定振幅与初相","type":"数学处理","judge":"由图像峰值和 t=0 时 a=0 确定加速度表达式的振幅和初相","why":"a-t 为正弦曲线，峰值即 \\omega^2 A，t=0 时 a=0 且随后增大，决定用正弦而非余弦形式","do":"取峰值 4 作振幅，由 \\omega=2\\pi/T 求角频率，写出 a=A\\sin\\omega t","expr":"a=4\\sin(2.5\\pi t)\\,\\mathrm{m/s^2}","cues":["峰值是4","先求角频率","从零开始增大用正弦"],"concepts":["角频率","振幅","简谐振动表达式"]},{"title":"加速度增大判速度变化","type":"关系建立","judge":"由加速度大小增大判断手机正远离平衡位置、速度在减小","why":"加速度大小与位移大小成正比，加速度增大说明位移增大，即从平衡位置向最大位移处运动，速度减小、动能减小","do":"比较 t=0 到 t=0.2 s 内加速度大小的变化趋势，判断运动方向和速度增减","expr":"|a|=\\omega^2|x|","cues":["加速度变大","远离平衡位置","速度在减小"],"concepts":["位移与加速度关系","速度变化","动能"]}],"587":[{"title":"相对滑动方向判定","type":"前提判断","judge":"物体刚放上传送带时相对传送带向哪一侧滑动，从而确定摩擦力方向","why":"物体初速度为零而传送带已有速度，物体相对传送带向后运动，滑动摩擦力方向与相对运动方向相反，沿传送带运动方向","do":"比较物体瞬时速度与传送带速度的大小，由相对速度方向定出滑动摩擦力方向","expr":"v_{\\text{物}}<v_{\\text{带}}\\Rightarrow f\\ \\text{沿带运动方向}","cues":["物体比带慢","相对带向后","摩擦力向前"],"concepts":["相对运动","滑动摩擦力方向"]},{"title":"共速后摩擦力消失","type":"临界条件","judge":"物体与传送带速度相同后是否还受摩擦力","why":"共速后二者无相对滑动、也无相对运动趋势（水平方向不需要力维持匀速），静摩擦力为零","do":"对匀速阶段物体做水平方向受力分析，检查是否存在维持匀速所需的水平力","expr":"v_{\\text{物}}=v_{\\text{带}}\\Rightarrow f=0","cues":["一起匀速","没有相对趋势","不受摩擦力"],"concepts":["相对运动趋势","静摩擦力"]},{"title":"摩擦力做功正负","type":"关系建立","judge":"加速阶段摩擦力对物体做正功还是负功","why":"摩擦力方向与物体位移方向相同，故做正功，物体动能增加","do":"比较摩擦力方向与物体位移方向，用动能定理判断功的正负","expr":"W_f=\\Delta E_k>0","cues":["摩擦力向前","位移也向前","动能增加"],"concepts":["功的正负","动能定理"]},{"title":"加速度由动摩擦因数决定","type":"模型选择","judge":"加速阶段加速度与传送带速度是否有关","why":"水平方向只受滑动摩擦力，由牛顿第二定律 a=μg，只取决于动摩擦因数，与带速无关","do":"对加速阶段列牛顿第二定律，消去质量得到加速度表达式","expr":"a=\\frac{\\mu mg}{m}=\\mu g","cues":["只受摩擦力","质量约掉","加速度不变"],"concepts":["牛顿第二定律","滑动摩擦力"]},{"title":"加速时间随带速变化","type":"关系建立","judge":"传送带速度越大，物体加速到共速所需时间如何变化","why":"加速度恒定，末速度等于带速，由 v=at 知带速越大所需加速时间越长","do":"用速度公式把加速时间表示为带速与加速度之比，分析带速增大时时间的变化","expr":"t=\\frac{v_{\\text{带}}}{a}=\\frac{v_{\\text{带}}}{\\mu g}","cues":["加速度不变","末速度更大","时间更长"],"concepts":["匀变速直线运动","速度公式"]}],"588":[{"title":"识别等量异种电荷场分布","type":"模型选择","judge":"要判断这是等量异种点电荷的电场，其连线上的场强和电势分布有何对称特点","why":"等量异种电荷在连线上各点场强方向相同（由正指向负），且关于连线中点对称的两点场强大小相等；这是判断 P、Q 场强关系的依据","do":"画出 MN 连线，标出正负电荷位置，利用关于中点对称性比较 P、Q 到两电荷的距离组合","expr":"","cues":["等量异种","连线对称","场强同向"],"concepts":["等量异种点电荷","电场叠加","对称性"]},{"title":"比较 P、Q 场强大小","type":"关系建立","judge":"要判断 P、Q 两点电场强度大小是否相等","why":"由 MP=QN 知 P、Q 关于 MN 中点对称，各自到两电荷的距离组合互换，叠加后场强大小相等","do":"分别写出 P、Q 处场强的叠加式，比较两式中的距离项","expr":"E_P=\\frac{kQ}{MP^{2}}+\\frac{kQ}{NP^{2}},\\quad E_Q=\\frac{kQ}{MQ^{2}}+\\frac{kQ}{NQ^{2}}","cues":["距离互换","大小相等","叠加比较"],"concepts":["电场叠加","点电荷场强"]},{"title":"判断 P、Q 电势高低","type":"前提判断","judge":"要判断 P、Q 两点电势谁高谁低","why":"电场线由正电荷指向负电荷，沿电场线方向电势降低，P 离正电荷更近，故电势更高","do":"沿 MN 从正电荷到负电荷画出电场方向，比较 P、Q 在电场线上的先后位置","expr":"","cues":["沿场线降低","靠近正电荷","电势更高"],"concepts":["电势","电场线方向"]},{"title":"电荷量加倍后的场强变化","type":"关系建立","judge":"要判断两电荷电荷量均加倍时，P、Q 各自场强如何变化","why":"场强与源电荷电荷量成正比，两个电荷都加倍时每点的叠加场强也加倍，比例关系不变","do":"把 E 表达式中两个 Q 同时换成 2Q，看结果与原来 E 的倍数关系","expr":"E'=2E","cues":["正比于电荷量","同时加倍","场强加倍"],"concepts":["点电荷场强","正比关系"]},{"title":"用电势差定性判断变化","type":"近似条件","judge":"要判断 PQ 间电势差在电荷量加倍后如何变化，能否用 U=Ed 定性比较","why":"PQ 间距不变，而两点场强均加倍，用 U=Ed 定性可知电势差随场强增大而增大","do":"比较加倍前后 P、Q 的场强与间距，代入 U=Ed 定性判断 U 的变化趋势","expr":"U=Ed","cues":["间距不变","场强变大","电势差变大"],"concepts":["电势差","匀强电场定性"]}],"589":[{"title":"确定中点零电势","type":"前提判断","judge":"M 在中点时 P、Q 两端电势差是否为零，指针是否居中","why":"两电源电动势相同、内阻不计，滑动片在中点时两侧电阻对称分压，P、Q 等电势，这是把指针位置与加速度方向对应起来的基准","do":"设 R 中点电势为零，比较 M 在中点及偏离中点时 P、Q 的电势高低","expr":"U_{PQ}=0 \\quad (M\\text{ 在中点})","cues":["先找中点","两边电源一样","指针居中对应零"],"concepts":["电势差","分压","电桥平衡"]},{"title":"位移与电压成正比","type":"关系建立","judge":"P、Q 间电压与滑动片偏离中点距离是线性关系还是其他关系","why":"滑动变阻器上电势随长度均匀变化，两段电阻之差与偏移距离成正比，故电压与偏移量成正比，这是把电压表读数当作加速度大小的依据","do":"写出偏移 x 时两侧电阻差，用欧姆定律求 U_PQ 与 x 的关系","expr":"U_{PQ}\\propto \\Delta R \\propto x","cues":["电阻随长度变","电压跟偏移走","线性关系"],"concepts":["电阻定律","欧姆定律","线性关系"]},{"title":"由电压定加速度方向","type":"关系建立","judge":"指针偏左（P 低于 Q）对应滑块所受合力、加速度指向哪一侧","why":"电压极性由滑动片偏移方向决定，偏移方向又由弹簧形变即合力方向决定，三者一一对应","do":"由指针偏左定出 M 偏向中点哪一侧，再定出哪侧弹簧压缩、哪侧伸长，从而定合力方向","expr":"","cues":["先看指针偏哪边","再看哪根弹簧被压","合力指向伸长侧"],"concepts":["弹簧弹力","合力方向","加速度方向"]},{"title":"加速度与速度区分","type":"结论整理","judge":"由加速度方向能否确定物体速度方向","why":"加速度只由合力决定，与速度方向无必然联系，物体可加速也可减速","do":"比较加速度方向与可能的运动方向，判断速度方向是否唯一确定","expr":"","cues":["加速度不等于速度","可能加速也可能减速","速度方向定不了"],"concepts":["加速度","速度","牛顿第二定律"]}],"590":[{"title":"脉冲周期上限","type":"前提判断","judge":"持续时间内至少含一个完整周期，能否把脉冲持续时间直接当作光波周期的上限","why":"题设'持续时间内至少包含一个完整的光波周期'给出 T ≤ 100 as，取等号时对应频率最低、光子能量最小","do":"把 100 as 换算成秒，作为光波周期的最大值，用于后续求波长和光子能量的极值","expr":"T\\le 100\\ \\mathrm{as}=1.0\\times10^{-16}\\ \\mathrm{s}","cues":["至少一个周期","取等号","周期最大"],"concepts":["周期","频率"]},{"title":"波长与衍射明显程度","type":"关系建立","judge":"由 c=λ/T 求出波长后，判断波长与障碍物尺寸的关系决定衍射是否明显","why":"障碍物尺寸与波长相差不多或比波长小时衍射才明显，波长越长衍射越明显","do":"用 λ=cT 算出该脉冲波长，再与 550 nm 可见光波长比较大小","expr":"\\lambda=cT=3.0\\times10^{8}\\times1.0\\times10^{-16}=3.0\\times10^{-8}\\ \\mathrm{m}","cues":["波长越长越明显","比障碍物小","先算波长"],"concepts":["光的衍射","波长"]},{"title":"光子能量与光子数","type":"关系建立","judge":"总能量相同时，光子能量越大则光子数越少","why":"总能量等于光子数乘单个光子能量，E总=NE，E 越大 N 越小","do":"由 E=hc/λ 判断该脉冲光子能量比可见光大，再反推同等总能量下光子数更少","expr":"E=\\frac{hc}{\\lambda},\\quad N=\\frac{E_{总}}{E}","cues":["能量大个数少","总能量相等","单个光子能量"],"concepts":["光子能量","光子数"]},{"title":"电离条件的能量比较","type":"临界条件","judge":"光子能量是否不小于氢原子基态电离所需能量 13.6 eV","why":"只有光子能量大于等于电离能，才能把基态氢原子中的电子电离出去","do":"用 E=h/T 求光子能量的最小值，与 13.6 eV 对应的焦耳值比较","expr":"E_{\\min}=\\frac{h}{T}=\\frac{6.6\\times10^{-34}}{1.0\\times10^{-16}}=6.6\\times10^{-18}\\ \\mathrm{J}>2.2\\times10^{-18}\\ \\mathrm{J}","cues":["大于电离能","基态氢原子","换算成焦耳"],"concepts":["电离能","光子能量"]},{"title":"探测要求的时间尺度","type":"前提判断","judge":"要分辨电子的动态过程，脉冲持续时间应比电子运动周期长还是短","why":"只有'快门'时间短于被观测过程的特征时间，才能拍下该过程的瞬时状态","do":"把脉冲持续时间与原子内电子运动的特征周期比较，判断应取更短的时间尺度","expr":"","cues":["快门要更快","小于电子周期","分辨动态过程"],"concepts":["时间分辨率","特征周期"]}],"591":[{"title":"用单位制反推忆阻器属性","type":"前提判断","judge":"判断 Φ/Q 的量纲对应哪种电磁学元件的属性","why":"题设把忆阻器定义为 Φ 与 Q 之比，元件的属性只能由该比值的单位确定，而 Φ 的单位 V·s 需由法拉第电磁感应定律 E=ΔΦ/Δt 反推，Q 的单位 A·s 需由 Q=It 反推","do":"先由 E=ΔΦ/Δt 得 Φ 的单位 V·s，再由 Q=It 得 Q 的单位 A·s，把两者相除看得到什么单位","expr":"[\\Phi]=[E][t]=\\mathrm{V\\cdot s},\\quad [Q]=[I][t]=\\mathrm{A\\cdot s},\\quad \\frac{[\\Phi]}{[Q]}=\\frac{\\mathrm{V}}{\\mathrm{A}}=\\Omega","cues":["先看单位","用公式反推单位","相除得欧姆"],"concepts":["单位制","法拉第电磁感应定律","量纲分析"]},{"title":"识别三种元件对应的比值","type":"模型选择","judge":"判断电容器、电阻、电感分别由哪两个量的比值描述，从而确认 Φ/Q 与电阻同类","why":"题图给出的对应关系是元件属性的定义依据：电容对应 Q/U，电阻对应 U/I，电感对应 Φ/I，只有把这三个比值与忆阻器的 Φ/Q 放在同一框架下比较，才能判断忆阻器描述的是哪类属性","do":"把 Q/U、U/I、Φ/I 三个比值与 Φ/Q 并列，看 Φ/Q 与哪个比值量纲一致","expr":"C=\\frac{Q}{U},\\quad R=\\frac{U}{I},\\quad L=\\frac{\\Phi}{I},\\quad M=\\frac{\\Phi}{Q}","cues":["对照题图","比值定义属性","和电阻同类"],"concepts":["比值定义法","电容","电感"]},{"title":"由量纲相同判定能量单位","type":"关系建立","judge":"判断 QU 与 ΦI 是否具有相同的单位，从而判断关于二者单位相同的说法是否成立","why":"QU 与 ΦI 的量纲需分别由 Q=It、Φ 的 V·s 单位展开，只有展开到基本单位后比较才能确认是否同为焦耳，不能凭形式相似下结论","do":"把 QU 展开为 A·s·V，把 ΦI 展开为 V·s·A，比较两者是否都等于 J","expr":"[QU]=\\mathrm{A\\cdot s\\cdot V}=\\mathrm{J},\\quad [\\Phi I]=\\mathrm{V\\cdot s\\cdot A}=\\mathrm{J}","cues":["展开成基本单位","都是焦耳","单位相同"],"concepts":["单位换算","功与能"]},{"title":"由法拉第定律导出电感电压关系","type":"关系建立","judge":"判断能否由 L=Φ/I 与 E=ΔΦ/Δt 推出 E=LΔI/Δt","why":"电感的定义式 L=Φ/I 只在磁通量与电流成正比时才能写成增量形式 L=ΔΦ/ΔI，再与法拉第定律联立消去 ΔΦ，这一步依赖自感中 Φ 与 I 成正比这一前提","do":"把 ΔΦ=LΔI 代入 E=ΔΦ/Δt，消去 ΔΦ 得到 E 与 ΔI/Δt 的关系","expr":"L=\\frac{\\Delta\\Phi}{\\Delta I}\\ \\Rightarrow\\ \\Delta\\Phi=L\\Delta I,\\quad E=\\frac{\\Delta\\Phi}{\\Delta t}=L\\frac{\\Delta I}{\\Delta t}","cues":["磁通和电流成正比","消去磁通量","自感电动势"],"concepts":["自感","法拉第电磁感应定律","增量形式"]}],"592":[{"title":"折射率定义式","type":"前提判断","judge":"判断折射率应由入射角与折射角的正弦之比定义，而不是角度之比","why":"折射定律的物理内容是光在两种介质界面发生偏折时正弦量之比为常数，角度本身不成正比","do":"对光路图找出光在玻璃表面的入射角 i 与折射角 r，写出正弦之比","expr":"n=\\frac{\\sin i}{\\sin r}","cues":["正弦之比","不是角度比","看光路定角"],"concepts":["折射定律","折射率"]},{"title":"明确探究的是方向","type":"前提判断","judge":"判断本实验的探究对象是感应电流的方向而非大小","why":"实验目的决定要记录和观察的物理量，题目明确写的是探究影响感应电流方向的因素","do":"对照实验目的，筛掉要求记录电流大小的选项","expr":"","cues":["只探究方向","大小不用记","看实验目的"],"concepts":["电磁感应","感应电流方向"]},{"title":"用指针偏转定方向","type":"实验操作","judge":"判断感应电流方向通过电流表指针偏转方向来显示","why":"电流方向无法直接观察，只能借助电流表指针偏转方向这一可观测现象间接反映","do":"观察电流表指针向哪一侧偏转，据此标记感应电流方向","expr":"","cues":["看指针偏转","间接显示方向","标记电流方向"],"concepts":["电流表","转换法"]},{"title":"控制变量比甲乙","type":"关系建立","judge":"判断甲、乙两图对比中改变的是插入端极性，从而得出方向与极性有关","why":"对比实验只有在其他条件相同、只改变一个因素时，才能把现象差异归因于该因素","do":"比较甲、乙中磁体插入端是 N 极还是 S 极以及对应的电流方向","expr":"","cues":["只变极性","对比甲乙","控制变量"],"concepts":["控制变量法","磁极"]},{"title":"闭合电路建 U-R 关系","type":"关系建立","judge":"判断电压表读数 U 与电阻箱阻值 R 满足闭合电路欧姆定律给出的关系","why":"电压表为理想电压表，读数即路端电压，电阻箱是唯一外电阻，故 U 与 R 由闭合电路欧姆定律联系","do":"由 E=U+Ir 与 I=U/R 消去电流，整理成 U 关于 1/R 的线性式","expr":"U=E-\\frac{r}{R}U","cues":["路端电压","消去电流","化成直线"],"concepts":["闭合电路欧姆定律","路端电压"]},{"title":"由截距斜率取 E 和 r","type":"图像读取","judge":"判断图像纵轴截距对应电动势、斜率绝对值对应内阻与某量之积","why":"线性关系 U=E-k·(U/R) 中截距即 E，斜率含 r，只有把图像与公式逐项对应才能读出参数","do":"读出纵轴截距得 E，取图线上两点算斜率并结合坐标物理量求出 r","expr":"E=U_{\\text{截}},\\ r=\\frac{E-U_1}{U_1/R_1}","cues":["截距是电动势","斜率求内阻","两点算斜率"],"concepts":["图像法","电动势","内阻"]}],"593":[{"title":"保证平抛以位移代速度","type":"前提判断","judge":"斜槽末端是否必须调水平，以及为什么必须调","why":"只有小球离开槽口后做平抛运动，落地时间才相同，水平位移才与碰前碰后速度成正比，才能用距离代替速度代入动量守恒式","do":"检查斜槽末端切线是否水平，确认两球离开后均做平抛","expr":"h=\\frac{1}{2}gt^{2},\\quad x=v_{0}t","cues":["末端要水平","平抛时间相同","位移代替速度"],"concepts":["平抛运动","动量守恒","等效替代"]},{"title":"对心正碰与碰后同向","type":"模型选择","judge":"两球半径是否必须相同、入射球质量是否必须大于被碰球","why":"半径相同才能发生对心正碰，使速度沿同一直线；入射球质量大才能碰后不反弹、两球均向前飞出并留下落点","do":"比较两球半径与质量，选择半径相同、m1>m2 的组合","expr":"","cues":["半径要一样","大碰小","碰后都往前飞"],"concepts":["对心碰撞","正碰条件"]},{"title":"最小圆定平均落点","type":"实验操作","judge":"多个落点如何确定一个代表位置","why":"落点有分散性，需用多次重复的统计中心代表平均落点，否则单点偶然误差大","do":"用圆规画尽可能小的圆把所有落点圈住，取圆心为平均落点","expr":"","cues":["画最小圆","取圆心","多测几次取平均"],"concepts":["多次测量","偶然误差"]},{"title":"选对位移组合列式","type":"关系建立","judge":"OP、OM、ON 分别对应碰前入射球、碰后入射球、碰后被碰球的速度","why":"P 是 m1 单独下落点对应碰前速度，M 是碰后 m1 的落点，N 是碰后 m2 的落点，代入时必须各归其位","do":"写出 m1·OP 与 m1·OM+m2·ON 的等量关系","expr":"m_{1}OP=m_{1}OM+m_{2}ON","cues":["P是碰前","M是碰后入射球","N是被碰球"],"concepts":["动量守恒","平抛位移与速度成正比"]},{"title":"弦长代速度的几何转换","type":"几何关系","judge":"偏角与弦长、绳长的几何关系如何把弦长换成最低点速度","why":"由动能定理得速度与下降高度有关，而下降高度需用弦长和绳长表示，才能把待测弦长直接代入动量式","do":"由 mgL(1-cosθ)=½mv² 与 sin(θ/2)=l/(2L) 联立消去角度","expr":"v=l\\sqrt{\\frac{g}{L}}","cues":["弦长换速度","用动能定理","消去角度"],"concepts":["动能定理","几何关系","圆周运动"]},{"title":"反弹球速度取负号","type":"关系建立","judge":"碰后小球1向左反弹，其速度在动量式中应取正还是负","why":"动量是矢量，规定向右为正时，碰后小球1速度方向向左，必须带负号，否则关系式符号错误","do":"按向右为正写出 m v1 = -m v2 + M v3，再代入各弦长表达式","expr":"ml_{1}=-ml_{2}+Ml_{3}","cues":["反弹取负","规定正方向","矢量要带符号"],"concepts":["动量矢量性","一维碰撞"]}],"594":[{"title":"水流平抛模型","type":"模型选择","judge":"水离开管口后的运动应归为哪一类运动模型","why":"水只受重力、初速度水平，题设明确假定为平抛运动，这是后续分解方向的依据","do":"确认初速度水平、只受重力，把运动分解为水平匀速和竖直自由落体","expr":"","cues":["平抛运动","水平初速","只受重力"],"concepts":["平抛运动","运动的分解"]},{"title":"竖直方向定时间","type":"关系建立","judge":"求时间应看哪个方向的分运动，用哪个已知量","why":"竖直方向初速度为零、加速度为 g，落高 h 已知，时间只由竖直方向决定，与水平速度无关","do":"对竖直方向列自由落体位移公式，由 h 解出 t","expr":"h=\\frac{1}{2}gt^{2}","cues":["竖直方向算时间","初速为零","只看下落高度"],"concepts":["自由落体","运动时间"]},{"title":"水平方向求初速","type":"关系建立","judge":"水平位移 d 与排出速度、时间之间是什么关系","why":"水平方向不受力做匀速直线运动，水平射程等于初速乘以下落时间","do":"对水平方向列匀速方程，代入已求出的 t 解出 v0","expr":"d=v_{0}t","cues":["水平匀速","射程等于速度乘时间","两方向共用时间"],"concepts":["匀速直线运动","射程"]},{"title":"流量等于截面乘流速","type":"关系建立","judge":"单位时间流出体积与管口截面积、流速之间如何联系","why":"满口排水时，单位时间内流出的水柱长度等于流速，体积等于截面积乘该长度","do":"取单位时间，写出流出的水柱体积，即截面积乘流速","expr":"Q=Sv_{0}","cues":["满口排水","流量等于面积乘速度","单位时间水柱长度"],"concepts":["流量","连续性"]},{"title":"管径远小于落高","type":"近似条件","judge":"能否把管口各点出流视为同一初速、忽略水柱截面变化","why":"h 远大于管口内径，水柱下落过程中截面变化和管口各点速度差异可忽略，平抛模型才成立","do":"比较 h 与管口内径，确认可把出流当作速度均匀的水平抛射","expr":"h\\gg D","cues":["远大于内径","忽略水柱粗细","速度算均匀"],"concepts":["理想化条件","平抛模型适用条件"]}],"595":[{"title":"瞬时电流的求法","type":"前提判断","judge":"开关闭合瞬间电容电压尚未变化，能否用 U=Q/C 与 I=U/R 求瞬时电流","why":"电容器电压由极板电荷量决定，闭合瞬间电荷量来不及改变，故电压仍为 Q/C；此时电路只有电阻 R 限制电流","do":"先由初始电荷量写出电容电压，再用欧姆定律求闭合瞬间电流","expr":"U=\\frac{Q}{C},\\quad I=\\frac{U}{R}=\\frac{Q}{CR}","cues":["电压还是原来的","电荷来不及变","用欧姆定律"],"concepts":["电容电压","欧姆定律","瞬时值"]},{"title":"安培力方向与大小","type":"关系建立","judge":"判断导体棒所受安培力的大小与方向，确认它是棒加速的唯一水平力","why":"磁场竖直向下、棒水平且与导轨垂直，电流沿棒方向，三者两两垂直，故 F=BIL；方向由左手定则确定，沿导轨方向","do":"写出安培力 F=BIL，并用左手定则判断其沿导轨方向，说明棒将沿导轨加速","expr":"F=BIL","cues":["三者互相垂直","左手定则","沿导轨方向"],"concepts":["安培力","左手定则"]},{"title":"选棒为对象用牛二","type":"模型选择","judge":"以导体棒为研究对象，水平方向只受安培力，竖直方向重力与支持力平衡","why":"导轨光滑无摩擦，水平方向合力即安培力，可直接用牛顿第二定律求瞬时加速度","do":"对棒列水平方向牛顿第二定律方程，代入瞬时电流求加速度","expr":"BIL=ma,\\quad a=\\frac{BQL}{CRm}","cues":["取导体棒","水平只受安培力","光滑无摩擦"],"concepts":["牛顿第二定律","受力分析"]},{"title":"速度增大导致电流减小","type":"关系建立","judge":"棒加速后产生动生电动势，判断它如何改变电容电压与回路电流","why":"棒切割磁感线产生与电容电压反向的电动势，回路总电动势减小，放电电流随之减小，安培力减小","do":"写出含动生电动势的回路方程，说明 v 增大时电流 I 减小","expr":"I=\\frac{U-BLv}{R}","cues":["棒切割磁感线","电动势反向","电流越来越小"],"concepts":["动生电动势","回路欧姆定律"]},{"title":"加速度递减的定性判断","type":"结论整理","judge":"由电流减小推出安培力减小，进而判断加速度如何随速度变化","why":"a=BIL/m，I 随 v 增大而减小，故 a 随 v 增大而减小，v-t 图线斜率逐渐变小","do":"比较不同时刻的电流与加速度，确定 v-t 图线为斜率递减的上升曲线","expr":"a=\\frac{BIL}{m},\\quad I\\downarrow\\Rightarrow a\\downarrow","cues":["加速度越来越小","斜率逐渐变小","曲线向上弯"],"concepts":["加速度","v-t 图像斜率"]}],"596":[{"title":"均匀性定球内质量","type":"前提判断","judge":"判断膨胀后半径 2r₀ 的球内包含的质量与原来半径 r₀ 球内质量是否相同","why":"题设说宇宙中所有位置观测结果都一样、质量始终均匀分布，意味着以 O 为心的任一球内物质不会因膨胀而增减，球内质量守恒","do":"把 r₀ 球内质量与 2r₀ 球内质量用密度乘球体积表示并令其相等","expr":"\\rho_{0}\\cdot\\frac{4}{3}\\pi r_{0}^{3}=\\rho\\cdot\\frac{4}{3}\\pi(2r_{0})^{3}","cues":["球内质量不变","密度乘体积","均匀分布"],"concepts":["均匀分布","质量守恒","球体积"]},{"title":"球壳对内部无引力","type":"模型选择","judge":"判断 P 所受引力是否只由半径 r 的球内质量决定、球外物质是否可忽略","why":"题设明确给出 P 受到的万有引力相当于球内质量集中于 O 点，这是球壳定理的结论，球外球壳对内部点合力为零","do":"取球内质量 M 集中于 O 点作为引力源，写出 M 的表达式，不把球外物质计入","expr":"M=\\rho_{0}\\cdot\\frac{4}{3}\\pi r_{0}^{3}","cues":["只看球内","球外抵消","等效质点"],"concepts":["球壳定理","等效引力源","万有引力"]},{"title":"引力势能取负值","type":"关系建立","judge":"判断引力势能变化时用题给的负值公式，且距离增大势能是增大（趋于零）","why":"题给 E_p=-Gm₁m₂/R，R 增大时 E_p 由更负变为较不负，势能增加，符号不能丢","do":"分别写出 r₀ 处与 2r₀ 处的势能，作差得势能变化量","expr":"\\Delta E_{p}=-\\frac{GMm}{2r_{0}}-\\left(-\\frac{GMm}{r_{0}}\\right)=\\frac{GMm}{2r_{0}}","cues":["势能是负的","距离大势能大","别丢负号"],"concepts":["引力势能","势能零点","符号约定"]},{"title":"能量守恒求动能变化","type":"关系建立","judge":"判断只有万有引力做功、无其他能量输入，机械能守恒，动能变化等于势能变化的相反数","why":"题设说明仅考虑万有引力和径向运动，无外力做功，故 E_k+E_p 守恒","do":"令 ΔE_k+ΔE_p=0，把 M 代入化简","expr":"\\Delta E_{k}=-\\Delta E_{p}=-\\frac{GMm}{2r_{0}}=-\\frac{2}{3}G\\pi\\rho_{0}mr_{0}^{2}","cues":["机械能守恒","动能减少","势能增加"],"concepts":["机械能守恒","动能定理","引力做功"]},{"title":"由速度随距离减小判 H","type":"结论整理","judge":"判断哈勃系数 H 随时间的变化方向，需要把 v 随 r 的减小趋势与 r 随时间增大对应起来","why":"由 a 知 r 越大动能越小、速率越小；而星体远离时 r 随时间增大，故同一星体后一时刻 v 更小、r 更大，v=Hr 中 H=v/r 必减小","do":"比较同一星体在两个不同时刻的 v 与 r，用 H=v/r 判断比值变化","expr":"H=\\frac{v}{r}","cues":["速度在变小","距离在变大","比值变小"],"concepts":["哈勃定律","比值判断","膨胀速率"]}],"597":[{"title":"离子受力取舍","type":"前提判断","judge":"氙离子在放电室内要不要考虑磁场力","why":"题干明确说明对氙离子仅考虑电场的作用，且离子初速近似为零、速度沿轴向，轴向磁场对轴向速度不产生洛伦兹力","do":"对氙离子只画电场力 eE，沿轴向，忽略两个方向的磁场","expr":"","cues":["只受电场力","不管磁场","离子初速为零"],"concepts":["电场力","洛伦兹力","受力分析"]},{"title":"电子圆周运动平面","type":"模型选择","judge":"电子做匀速圆周运动的圆面取哪个平面、圆心在哪","why":"题设电子在垂直于轴线的平面内绕轴线做半径为 R 的圆周运动，说明向心力必须指向轴线，只能由轴向磁场提供","do":"把电子的速度分解为绕轴环向速度，确认圆面垂直于轴线、圆心在轴线上","expr":"","cues":["垂直轴线平面","绕轴线转","圆心在轴上"],"concepts":["匀速圆周运动","向心力","洛伦兹力"]},{"title":"两磁场分工","type":"关系建立","judge":"轴向磁场和径向磁场各自对电子起什么作用","why":"电子同时受轴向电场力和两个磁场洛伦兹力，只有把径向磁场的力与电场力平衡、轴向磁场的力充当向心力，才能维持半径不变的圆周运动","do":"沿轴向列电场力与径向磁场洛伦兹力平衡式，沿径向列轴向磁场洛伦兹力提供向心力式","expr":"eE=evB_{2},\\quad evB_{1}=\\frac{mv^{2}}{R}","cues":["径向磁场平衡电场","轴向磁场提供向心力","两个磁场分工"],"concepts":["洛伦兹力","电场力平衡","向心力"]},{"title":"电子数分配","type":"关系建立","judge":"进入放电室的电子数与阴极发射总数 n 是什么关系","why":"阴极发射的电子一部分进入放电室、一部分未进入，而氙离子只与进入的那部分完全中和，比例 k 是对进入数而言的","do":"设单位时间进入放电室的电子数为 n'，写出被电离氙离子数 N=kn' 与 n=n'+N 的联立关系","expr":"N=kn',\\quad n=n'+N\\Rightarrow N=\\frac{nk}{1+k}","cues":["一部分没进","k是对进入的","先设进入数"],"concepts":["电荷中和","比例关系","粒子数守恒"]},{"title":"推力用动量定理","type":"模型选择","judge":"求推进器推力应取什么对象、用什么规律","why":"推力来自喷出离子对推进器的反作用，本质是单位时间内离子动量的改变，用动量定理比逐个体求力更直接","do":"取 Δt 内喷出的 NΔt 个离子为对象，写出动量定理，再由牛顿第三定律得推力","expr":"F'\\Delta t=N\\Delta t\\,Mv_{1},\\quad F=F'","cues":["取喷出的离子","用动量定理","反作用力就是推力"],"concepts":["动量定理","牛顿第三定律","反冲"]},{"title":"喷出速度由加速求","type":"关系建立","judge":"离子喷出速度由哪段过程决定","why":"离子初速近似为零，只在电场中沿轴向加速距离 d，动能定理（或运动学）给出喷出速度，与加速度 a 的结果一致","do":"对单个离子用动能定理，把 eE 与 d 的乘积写成动能的增量","expr":"eEd=\\frac{1}{2}Mv_{1}^{2}\\Rightarrow v_{1}=\\sqrt{\\frac{2eEd}{M}}","cues":["从静止加速","电场做功","用动能定理"],"concepts":["动能定理","匀强电场做功"]}],"598":[{"title":"光电效应的物理意义","type":"前提判断","judge":"光电效应现象说明光具有粒子性还是波动性","why":"光电效应中电子一次性吸收光子能量、存在截止频率，体现能量量子化，是粒子性的证据；波动性由干涉衍射体现","do":"把光电效应与干涉、衍射现象的证据归属区分开","expr":"","cues":["光电效应看粒子性","干涉衍射看波动性"],"concepts":["粒子性","波动性","光子"]},{"title":"介质中频率与波长关系","type":"关系建立","judge":"光从真空进入介质时，频率、波速、波长三者中哪个不变、哪个改变","why":"频率由光源决定，跨介质不变；波速由介质决定而减小，再由 v=λf 推出波长变短","do":"先定频率不变，再用 v=λf 判断波长随波速减小而变短","expr":"v=\\lambda f","cues":["频率由光源定","波速变小","波长跟着变短"],"concepts":["频率","波速","波长"]},{"title":"光纤通信的物理原理","type":"模型选择","judge":"光纤通信依靠的是全反射还是折射或干涉","why":"光在纤芯与包层界面入射角大于临界角时发生全反射，光被限制在纤芯内低损耗传输","do":"把光纤通信与全反射条件对应，排除折射、干涉等机制","expr":"","cues":["光在纤芯里全反射","不是靠折射传"],"concepts":["全反射","临界角","光纤"]},{"title":"油膜彩纹的成因","type":"模型选择","judge":"油膜彩色条纹属于薄膜干涉还是色散或衍射","why":"油膜上下表面反射的两列光叠加，光程差随膜厚变化，不同波长加强位置不同形成彩色条纹","do":"把油膜彩纹归入薄膜干涉，与棱镜色散、单缝衍射区分","expr":"","cues":["上下表面反射叠加","是薄膜干涉","不是色散"],"concepts":["薄膜干涉","光程差","色散"]}],"599":[{"title":"绝热过程的热交换","type":"前提判断","judge":"绝热膨胀时气体与外界是否有热量交换","why":"绝热的定义就是 Q=0，这是用热力学第一定律判断内能变化的前提，若误认为有吸放热则内能变化方向会判错","do":"确认绝热过程 Q=0，再看体积增大对外做功 W<0","expr":"Q=0","cues":["绝热就是不传热","先定热量","体积变大对外做功"],"concepts":["绝热过程","热力学第一定律"]},{"title":"内能变化的判据","type":"关系建立","judge":"由 Q=0 和对外做功判断内能增大还是减小","why":"热力学第一定律 ΔU=W+Q，W<0 且 Q=0 时 ΔU<0，内能减小；理想气体内能只由温度决定，故温度降低","do":"把 W<0、Q=0 代入 ΔU=W+Q，得 ΔU<0","expr":"ΔU=W+Q","cues":["代第一定律","内能看温度","对外做功内能减"],"concepts":["热力学第一定律","内能","理想气体"]},{"title":"等温压缩的压强变化","type":"关系建立","judge":"温度不变、体积减小时压强如何变化","why":"一定质量理想气体等温过程满足玻意耳定律 pV=常量，体积减小则压强增大","do":"由 pV=C，V 减小推出 p 增大","expr":"pV=C","cues":["等温用玻意耳","体积小压强大","温度不变"],"concepts":["玻意耳定律","等温过程"]},{"title":"等温过程内能不变","type":"前提判断","judge":"等温压缩时理想气体的内能是否改变","why":"理想气体内能只与温度有关，温度不变则内能不变，与压强、体积变化无关","do":"由温度不变直接判定内能不变","expr":"","cues":["内能只看温度","等温内能不变","别被压强骗了"],"concepts":["理想气体内能","等温过程"]}],"600":[{"title":"选重物为研究对象","type":"模型选择","judge":"该对谁做受力分析，是重物还是小车整体","why":"题目问的是底板和侧板对重物的弹力，只有隔离重物才能让这两个力出现在方程里；取小车整体会把它们变成内力","do":"隔离重物，画出重力、底板支持力、侧板支持力三个力","expr":"","cues":["隔离重物","只看重物","别取整体"],"concepts":["隔离法","受力分析"]},{"title":"分解方向与角度","type":"几何关系","judge":"两个弹力沿水平和竖直方向的分量各用哪个角的正余弦表示","why":"底板与水平面夹角为 θ，底板弹力垂直于底板、侧板弹力垂直于侧板，二者互相垂直，各自与水平方向的夹角要由几何关系定出","do":"以水平、竖直为轴分解，写出 F底 与 F侧 的水平、竖直分量","expr":"F_{\\text{底}}\\sin\\theta,\\ F_{\\text{侧}}\\cos\\theta","cues":["先定角度","垂直关系","画个角"],"concepts":["力的分解","几何关系"]},{"title":"匀速时竖直平衡","type":"关系建立","judge":"匀速阶段竖直方向是否平衡，能否由此定出两弹力的大小关系","why":"匀速时加速度为零，竖直方向合力为零，这是后面比较加速前后变化的基准状态","do":"对竖直方向列平衡方程，得到 F底 与 F侧 的初始关系","expr":"F_{\\text{底}}\\cos\\theta+F_{\\text{侧}}\\sin\\theta=mg","cues":["匀速合力为零","竖直平衡","先算原来多大"],"concepts":["平衡条件","牛顿第二定律"]},{"title":"加速方向定水平方程","type":"关系建立","judge":"加速度沿水平向右，水平合力应由哪个力减去哪个力，符号如何","why":"加速时水平方向不再平衡，合力方向与加速度同向，必须判断两弹力水平分量谁大谁小","do":"沿水平向右列牛顿第二定律，把 F侧 的水平分量写在被减数位置","expr":"F_{\\text{侧}}\\cos\\theta-F_{\\text{底}}\\sin\\theta=ma","cues":["合力向右","侧板力减底板力","加速度方向"],"concepts":["牛顿第二定律","合力方向"]},{"title":"联立判断两力变化","type":"数学处理","judge":"由匀速到加速，两个方程联立后 F底、F侧 各自增大还是减小","why":"竖直方向平衡关系不变，水平方向多出向右的合力，两个方程共同约束两个未知力，必须联立才能定出各自的变化趋势","do":"用竖直方程消去一个力，结合水平方程中 a>0 判断另一力的增减，再回代判断第一个力","expr":"F_{\\text{底}}\\downarrow,\\quad F_{\\text{侧}}\\uparrow","cues":["联立两式","一个增一个减","代回去看"],"concepts":["方程组求解","控制变量"]}],"601":[{"title":"确定方程①中的粒子","type":"关系建立","judge":"由质量数守恒和电荷数守恒反推未知粒子 X 的质量数与电荷数","why":"核反应方程必须同时满足质量数守恒和电荷数守恒，这是确定未知粒子的唯一依据","do":"对反应①两侧列质量数方程和电荷数方程，解出 X 的质量数与电荷数，再对照常见粒子判断其种类","expr":"232+A=233,\\quad 90+Z=90","cues":["数质量数","电荷数守恒","补一个中子"],"concepts":["质量数守恒","电荷数守恒","中子"]},{"title":"识别方程②的衰变类型","type":"模型选择","judge":"看方程②放出的电子带何种电荷，判断它属于α衰变还是β衰变","why":"放出负电子（电荷数为-1）是β衰变的标志，α衰变放出的是氦核","do":"观察方程②生成物中电子的电荷数与质量数，与β衰变、α衰变的产物特征对照","expr":"{}^{233}_{90}\\mathrm{Th}\\to{}^{233}_{91}\\mathrm{Pa}+{}^{0}_{-1}e","cues":["放出电子","负电子","β衰变"],"concepts":["β衰变","α衰变","衰变方程"]},{"title":"半衰期是否受外界影响","type":"前提判断","judge":"判断半衰期是否随温度、压强、化学状态等外界条件改变","why":"半衰期由原子核内部结构决定，是统计规律，与外界物理化学条件无关","do":"直接调用半衰期由核内部因素决定这一结论，排除“改变外界条件可改变半衰期”的说法","expr":"","cues":["半衰期由核决定","外界条件无关","统计规律"],"concepts":["半衰期","放射性衰变"]},{"title":"β衰变电子的来源","type":"模型选择","judge":"判断β衰变放出的电子是核内中子转变而来，还是核内原本就存在的组成成分","why":"β衰变的实质是核内一个中子转化为质子并放出一个电子，电子是转化产物而非原子核的组成成分","do":"把方程②的电子与“中子→质子+电子”的转化过程对应起来，据此否定“电子是原子核组成部分”的说法","expr":"{}^{1}_{0}n\\to{}^{1}_{1}p+{}^{0}_{-1}e","cues":["中子变质子","电子是产物","核内没有电子"],"concepts":["β衰变实质","中子","质子"]}],"602":[{"title":"两状态角速度相同","type":"前提判断","judge":"未发射时随地球自转的角速度与同步轨道运行的角速度是否相等","why":"同步卫星的周期与地球自转周期相同，两者角速度都等于地球自转角速度","do":"比较两个状态的周期（或直接比较角速度），确认二者相等","expr":"\\omega_1=\\omega_2=\\omega_{\\text{地}}","cues":["同步就是同周期","角速度一样"],"concepts":["同步卫星","角速度","地球自转"]},{"title":"用同一角速度比较运动量","type":"关系建立","judge":"线速度、向心加速度该用哪个公式与半径挂钩","why":"两状态角速度相同，用含 ω 的公式才能把 v、a 直接化为与半径成正比","do":"写出 v=ωr 与 a=ω²r，把两状态的 v、a 之比化为半径之比","expr":"v=\\omega r,\\quad a_n=\\omega^{2}r","cues":["用带角速度的公式","先定角速度再比"],"concepts":["线速度","向心加速度","圆周运动"]},{"title":"区分半径与轨道半径","type":"几何关系","judge":"未发射时的转动半径是地球半径 R 还是同步轨道半径 r","why":"静置在赤道上的卫星绕地心转动的半径是地球半径，运行时的半径是同步轨道半径","do":"分别标出两状态的轨道半径 R 与 r，再代入比值","expr":"r_1=R,\\quad r_2=r","cues":["地面上半径是地球半径","别都当成r"],"concepts":["轨道半径","地球半径"]},{"title":"引力按平方反比","type":"关系建立","judge":"万有引力之比该用半径平方反比还是与向心力相同的比例","why":"万有引力由牛顿万有引力定律决定，只与两物体质量和距离有关，与运动状态无关","do":"写出 F=GMm/r²，比较两状态距离 R 与 r 得引力之比","expr":"F=\\frac{GMm}{r^{2}}\\Rightarrow F_1:F_2=r^{2}:R^{2}","cues":["引力只看距离","别把引力当向心力比"],"concepts":["万有引力定律","平方反比"]}],"603":[{"title":"负电荷电势能符号","type":"前提判断","judge":"负电荷在电势高处电势能大还是小","why":"电势能定义式 Ep=qφ 中 q 为负，φ 越大 Ep 越小，符号判断反了则动能极值点全错","do":"由 Ep=qφ 结合 q<0，把图像上各点 φ 的高低直接翻成 Ep 的高低","expr":"E_p=q\\varphi,\\ q<0","cues":["负电荷反着来","电势高反而能小"],"concepts":["电势能","电势"]},{"title":"动能极值定位","type":"关系建立","judge":"只有静电力时动能最小对应电势能最大还是最小","why":"仅静电力做功，动能与电势能之和守恒，动能最小处必是电势能最大处","do":"在图像上找 φ 最低点，对应 Ep 最大、动能最小、速率最小","expr":"E_k+E_p=\\text{常量}","cues":["能量守恒","动能最小在电势最低"],"concepts":["能量守恒","动能"]},{"title":"由斜率定场强方向","type":"图像读取","judge":"φ–x 图像的升降对应电场沿 x 正方向还是负方向","why":"沿电场线方向电势降低，φ 随 x 增大而升高处场强指向 x 负方向，反之指向正方向","do":"看 c 点两侧 φ–x 曲线的升降，定出 c 左、c 右的场强方向","expr":"E_x=-\\dfrac{\\Delta\\varphi}{\\Delta x}","cues":["看曲线升降","由斜率定场强方向","电场强度","电势梯度"],"concepts":["电场强度","电势梯度"]},{"title":"负电荷受力方向","type":"关系建立","judge":"负电荷所受静电力与场强方向相同还是相反","why":"F=qE 中 q<0，受力方向与场强方向相反，据此才能判断各段做功正负","do":"把 c 两侧场强方向各反一次，得到负电荷在 a 侧、d 侧的受力方向","expr":"\\vec F=q\\vec E,\\ q<0","cues":["负电荷受力反向","受力与场强相反"],"concepts":["电场力","电场强度"]},{"title":"分段判断做功正负","type":"结论整理","judge":"从 d 向 a 运动过程中电场力先做负功还是先做正功","why":"d 到 c 段受力沿 x 正方向而位移沿 x 负方向，做负功；c 到 a 段受力与位移同向，做正功","do":"按 c 点分段，比较各段电场力方向与运动方向，判断动能先减后增","expr":"W=qU_{dc}+qU_{ca}","cues":["先减速后加速","c点是转折"],"concepts":["电场力做功","动能定理"]}],"604":[{"title":"输出功率极值条件","type":"关系建立","judge":"要判断外电阻 R 取何值时电源输出功率 P 达到峰值，即 P 随 R 变化的极大值点在哪里","why":"由闭合电路欧姆定律，P=I²R=E²R/(R+r)²，需对该式关于 R 求极值才能确定峰值位置","do":"写出 P=E²R/(R+r)²，对 R 求导或配方，找出使分母最小的 R 值","expr":"P=\\frac{E^{2}R}{(R+r)^{2}},\\quad \\frac{dP}{dR}=0","cues":["配方求极值","看分母最小","R等于r"],"concepts":["闭合电路欧姆定律","输出功率","极值"]},{"title":"滑动变阻器量程匹配","type":"前提判断","judge":"要判断两个滑动变阻器中哪一个的阻值范围与电源内阻约 1 Ω、电动势约 3 V 的电路相匹配，能有效调节电流","why":"滑动变阻器阻值过大时，绝大部分阻值区间对应的电流变化极小，无法有效改变电路状态、得不到足够多的有效数据点","do":"比较 20 Ω 与 1000 Ω 相对内阻 1 Ω 的比例，判断哪个能在电流表量程内实现明显、均匀的调节","expr":"I=\\frac{E}{R+r}","cues":["选小阻值的","大阻值调不动","和内阻差不多量级"],"concepts":["滑动变阻器","量程匹配","有效调节"]},{"title":"电流表内外接选择","type":"模型选择","judge":"要判断单刀双掷开关接 1 端还是 2 端，即电压表测量的是路端电压还是包含电流表压降的电压，哪种接法使内阻测量更接近真实值","why":"电压表内阻约 3 kΩ 远大于电源内阻约 1 Ω，若把电流表接在电压表测量支路内，电流表内阻会直接叠加到内阻测量值上造成显著误差","do":"比较电流表内阻（约 1 Ω）与电源内阻（约 1 Ω）的量级，判断哪种接法把电流表内阻排除在内阻测量之外","expr":"r_{\\text{测}}=r+R_{A}\\ \\text{或}\\ r_{\\text{测}}=r","cues":["电压表内阻很大","电流表内阻不能忽略","接2端误差小"],"concepts":["电流表外接法","电压表分流","系统误差"]},{"title":"内阻误差来源分析","type":"误差分析","judge":"要判断两种接法下测量值与真实值偏差的方向和大小，从而确定哪种接法误差更小","why":"电压表分流使电流读数偏小、电流表分压使电压读数偏小，两种系统误差对内阻测量结果的影响程度不同，需按器材内阻量级比较","do":"分别写出两种接法下由 U=E-Ir 拟合得到的等效内阻表达式，比较 R_A 与 r、R_V 与 r 的大小关系","expr":"r_{\\text{测}}=r+R_{A}\\quad\\text{或}\\quad r_{\\text{测}}=\\frac{rR_{V}}{R_{V}+r}","cues":["电压表分流影响小","电流表内阻影响大","选误差小的接法"],"concepts":["系统误差","等效内阻","电压表分流"]}],"605":[{"title":"冲量转初速度","type":"关系建立","judge":"瞬时冲量作用后，是用动量定理求 A 的初速度，还是误以为冲量直接等于速度或等于力","why":"冲量是过程量，瞬时冲量只改变动量，不改变位置；A 在最低点获得速度后冲量已消失","do":"对 A 单独用动量定理，把冲量与质量、初速度联系起来","expr":"I=m_A v_0","cues":["冲量等于动量变化","先求初速度","冲量不是力"],"concepts":["动量定理","冲量","动量"]},{"title":"轨道上升用动能定理","type":"模型选择","judge":"从最低点到最高点的过程，该用动能定理还是运动学公式，以及重力做功取正还是取负","why":"轨道光滑、只有重力做功，且速度方向不断变化，用动能定理可避开变力与曲率细节","do":"对 A 从最低点到最高点列动能定理，高度差取 2R，重力做负功","expr":"-m_A g\\cdot 2R=\\frac12 m_A v^2-\\frac12 m_A v_0^2","cues":["光滑轨道只有重力做功","上升两倍半径","重力做负功"],"concepts":["动能定理","重力做功","机械能守恒"]},{"title":"碰前速度取最高点","type":"前提判断","judge":"求碰前 A 的速度，应取 A 到达轨道最高点时的速度，而不是最低点初速度或全程平均速度","why":"题设说明 A 运动到最高点才与 B 正碰，碰撞瞬间的速度就是最高点速度","do":"把动能定理解出的最高点速度作为碰撞前 A 的速度","expr":"v=\\sqrt{v_0^2-4gR}","cues":["碰前在最高点","用最高点速度","不是初速度"],"concepts":["末速度","状态量"]},{"title":"完全非弹性碰撞","type":"模型选择","judge":"A 与 B 正碰后粘在一起，属于哪类碰撞，动量守恒还是机械能守恒","why":"粘在一起意味着碰后同速，是完全非弹性碰撞，机械能不守恒但水平方向动量守恒","do":"对 A、B 组成的系统沿水平方向列动量守恒，求共同速度","expr":"m_A v=(m_A+m_B)v_{\\text{共}}","cues":["粘在一起同速","动量守恒","机械能不守恒"],"concepts":["完全非弹性碰撞","动量守恒","共同速度"]},{"title":"绳拉力用向心力","type":"关系建立","judge":"碰后瞬间绳的拉力，应按最低点圆周运动的向心力方程求，还是误用平衡条件 F=(m_A+m_B)g","why":"碰后瞬间两球在最低点做圆周运动，有向心加速度，绳拉力必须大于重力","do":"对碰后整体在最低点沿绳方向列牛顿第二定律，向心加速度用共同速度与绳长表示","expr":"F-(m_A+m_B)g=(m_A+m_B)\\frac{v_{\\text{共}}^2}{R}","cues":["最低点有向心力","拉力大于重力","用共同速度"],"concepts":["牛顿第二定律","向心力","圆周运动"]}],"606":[{"title":"直线匀速的受力平衡","type":"前提判断","judge":"粒子沿直线匀速穿过磁场区，说明电场力与洛伦兹力必须等大反向，要判断两力方向是否真的相反","why":"匀速直线运动要求合力为零；负电荷受电场力方向与电场方向相反，洛伦兹力方向由左手定则（负电荷反向）确定，只有二者共线反向才能抵消","do":"先由电场方向定出负电荷所受电场力沿 -x，再用速度沿 +y、磁场垂直纸面向里判断洛伦兹力沿 +x，确认两力反向","expr":"qE=qvB","cues":["匀速就是合力为零","电场力和洛伦兹力抵消","负电荷受力反着来"],"concepts":["洛伦兹力","电场力","平衡条件"]},{"title":"仅电场时的运动分解","type":"模型选择","judge":"去掉磁场后，粒子只受沿 -x 的恒力，初速度沿 +y，要判断这是类平抛而不是直线运动","why":"恒力方向与初速度垂直，x 方向匀加速、y 方向匀速，两个分运动独立","do":"把运动分解为 x 方向初速为零的匀加速和 y 方向匀速，用 x 方向位移等于半径 R 列方程","expr":"qE=ma,\\quad R=\\tfrac12 at^2","cues":["类平抛","垂直方向分开算","x方向从静止加速"],"concepts":["运动的分解","匀变速直线运动","牛顿第二定律"]},{"title":"磁场中半径与周期","type":"关系建立","judge":"仅磁场时粒子做匀速圆周运动，要判断周期与入射速度大小无关，只由 q、B、m 决定","why":"洛伦兹力提供向心力，r 与 v0 成正比，T=2πr/v0 中 v0 约掉，故改变入射速度只改变半径不改变周期","do":"由向心力方程求出 r，再写出周期表达式，确认 T 只含 m、q、B，并用第（1）问的 B=E/v 代入","expr":"qv_0B=\\frac{mv_0^2}{r},\\quad T=\\frac{2\\pi m}{qB}=\\frac{2\\pi mv}{qE}","cues":["周期跟速度无关","先求半径再求周期","把B换掉"],"concepts":["匀速圆周运动","洛伦兹力提供向心力","周期"]},{"title":"轨迹圆心与几何角","type":"几何关系","judge":"要判断粒子从 M 出发、经磁场偏转后到达 x 轴上 P 点（MP=√3R）时，轨迹圆弧对应的圆心角是多少","why":"入射速度沿 +y，圆心必在过 M 且垂直于速度的直线上（即 x 轴方向）；出射点 P 在 x 轴上，弦长 MP=√3R 与半径 r 构成等腰三角形，圆心角由弦长与半径之比决定","do":"画出轨迹，利用弦 MP 与半径构成的三角形，由 tanθ=√3R/R 得半圆心角 θ=60°，从而圆心角为 120°","expr":"\\tan\\theta=\\frac{\\sqrt3 R}{R}=\\sqrt3\\Rightarrow\\theta=60^\\circ","cues":["先找圆心","弦长比半径定角度","画图看圆心角"],"concepts":["圆周运动的几何关系","弦与圆心角","轨迹分析"]},{"title":"圆心角折算时间","type":"数学处理","judge":"要判断运动时间等于圆心角占整圆的比例乘以周期，而不是用弧长除以某个速度","why":"周期对应 2π 圆心角，匀速圆周运动时间与转过的圆心角成正比","do":"用 120°/360° 乘周期 T，把第（3）问求得的 T 代入化简","expr":"t_1=\\frac{120^\\circ}{360^\\circ}T=\\frac{2\\pi mv}{3qE}","cues":["按角度比例分周期","三分之一圈","用周期乘比例"],"concepts":["周期与圆心角","匀速圆周运动的时间"]}],"607":[{"title":"判断切割方向与电流方向","type":"前提判断","judge":"图示位置 AB 边是向纸内还是向纸外运动，从而用右手定则定出 AB 中电流由 B 到 A 还是由 A 到 B","why":"感应电流方向由导体切割磁感线的速度方向与磁场方向共同决定，转动方向看错则电流方向必反","do":"先由线框转动方向确定 AB 边的线速度方向，再用右手定则（磁感线穿掌心、四指指速度、拇指指感应电流）判断 AB 中电流方向","expr":"","cues":["看转动方向","右手定则","AB往纸里走"],"concepts":["右手定则","切割磁感线","感应电流方向"]},{"title":"区分中性面与垂直位置","type":"几何关系","judge":"计时起点线框平面与中性面垂直，判断 t 时刻线框转过的角度以及 AB 速度方向与磁场的夹角","why":"中性面是线框平面与磁场垂直的位置，从与中性面垂直处开始计时，转过的角度 θ=ωt 直接决定速度在垂直磁场方向的分量","do":"画出 t 时刻线框位置，把 AB 边中点绕轴的速度 v=ωL/2 分解，取垂直于磁场方向的分量","expr":"v_{\\perp}=\\omega\\frac{L}{2}\\cos\\theta,\\ \\theta=\\omega t","cues":["从中性面垂直处计时","速度要分解","取垂直磁场分量"],"concepts":["中性面","线速度分解","角速度"]},{"title":"单边电动势与整框电动势","type":"关系建立","judge":"求 AB 边电动势时用一条边，求整周电能时判断 AB、CD 两边是否都在切割、总电动势是单边还是两倍","why":"第（2）问只问 AB 边，用 e=BLv⊥；第（3）问算回路电能必须用整个线框的总电动势，漏掉 CD 边会使电能少一半","do":"第（2）问只对 AB 边写 e=BLv⊥；第（3）问确认 AB、CD 同时切割且电动势方向在回路中相加，取 e总=2e","expr":"e=\\frac{1}{2}\\omega BL^{2}\\cos\\omega t,\\quad e_{1}=\\omega BL^{2}\\cos\\omega t","cues":["只算AB边","两边都在切割","总电动势要翻倍"],"concepts":["动生电动势","线框回路","电动势叠加"]},{"title":"用有效值算整周电能","type":"数学处理","judge":"一周内电动势按余弦变化，求电阻消耗电能时用有效值还是最大值，以及一周所用时间","why":"电能是功率对时间的积分，正弦式电动势一周的平均功率等于最大值平方的一半除以电阻，直接用最大值会算大","do":"取 E有效=Em/√2，乘一周时间 T=2π/ω 得该周电能，再对逐周减半的角速度求和","expr":"\\varepsilon_{1}=\\frac{(E_{m1}/\\sqrt{2})^{2}}{R}\\cdot\\frac{2\\pi}{\\omega_{0}}=\\frac{\\pi B^{2}L^{4}\\omega_{0}}{R}","cues":["用有效值","一周时间多少","功率乘时间"],"concepts":["有效值","交流电功率","周期"]},{"title":"逐周减半的等比求和","type":"数学处理","judge":"角速度逐周减半时，每周电能按什么比例递减，无限多周求和收敛到多少","why":"电能正比于 ω，ω 逐周减半则电能也逐周减半，构成公比 1/2 的无穷等比数列，其和为有限值 2 倍首项","do":"写出 εn=ε1·(1/2)^(n-1)，用无穷等比数列求和公式 S=ε1/(1-1/2)","expr":"\\varepsilon=\\frac{\\varepsilon_{1}}{1-1/2}=\\frac{2\\pi B^{2}L^{4}\\omega_{0}}{R}","cues":["公比是一半","无限周求和","收敛到两倍"],"concepts":["等比数列","无穷级数求和"]},{"title":"能量回收与制动距离挂钩","type":"关系建立","judge":"储存电能占初动能 50% 时，初动能与回收电能是什么倍数关系，制动距离由哪个力做功决定","why":"题设储存电能等于初动能的 50%，故初动能是回收电能的两倍；汽车匀减速到停，动能全部被制动力做功消耗，制动力由 ma 给出","do":"由 ε=0.5Ek0 反解 Ek0，再对汽车用动能定理 fx=Ek0，配合 f=ma 求 x","expr":"E_{k0}=2\\varepsilon,\\quad fx=E_{k0},\\quad f=ma","cues":["电能是初动能一半","初动能要翻倍","制动力等于ma"],"concepts":["动能定理","牛顿第二定律","能量守恒"]}],"608":[{"title":"跃迁谱线条数","type":"模型选择","judge":"大量处于 n=3 的氢原子向低能级跃迁时，可能发出几种不同频率的光","why":"大量原子各自独立跃迁，所有可能的能级对（3→1、3→2、2→1）都会出现，不是只走一条路径","do":"列出 n=3 到低能级的所有可能跃迁，用组合数 C(3,2) 计数","expr":"N=C_{3}^{2}=3","cues":["大量原子","所有可能跃迁","不能只算一条路"],"concepts":["能级跃迁","组合计数"]},{"title":"光子能量取能级差","type":"关系建立","judge":"每种频率光子的能量该用哪两个能级之差来算","why":"玻尔理论中辐射光子能量等于两能级能量差的绝对值，能级值为负，须用高能级减低温级","do":"对三种跃迁分别写出 ΔE=E_m−E_n，代入图中 n=1、2、3 的能级值","expr":"hν=E_m-E_n","cues":["能级差","高减低","能量取正值"],"concepts":["玻尔理论","光子能量"]},{"title":"与紫外阈值比较","type":"临界条件","judge":"算出的三种光子能量中哪些超过 3.11 eV 的紫外门槛","why":"题设给出紫外光光子能量大于 3.11 eV，只有跨过该阈值的跃迁才算紫外光","do":"把三个 ΔE 分别与 3.11 eV 比较，数出大于该值的个数","expr":"ΔE>3.11\\,\\mathrm{eV}","cues":["比门槛","大于3.11","数个数"],"concepts":["紫外光阈值","能量比较"]}],"609":[{"title":"确定研究对象与过程","type":"模型选择","judge":"把人和滑板取为一个整体作为研究对象，并明确研究的是从顶端静止到底端速度 v 的整段下滑过程","why":"人和滑板一起运动、加速度相同，取整体后摩擦力做功与重力做功都作用在同一对象上，可直接对整体列动能定理，避免拆开求内力","do":"选定整体为对象，标出初态（静止）和末态（速度 v），确定过程中受重力、支持力、摩擦力","expr":"","cues":["取整体","人和板一起看","从顶到底整段"],"concepts":["整体法","动能定理"]},{"title":"判断支持力不做功","type":"前提判断","judge":"判断斜坡对人和滑板的支持力在整个下滑过程中是否做功","why":"支持力始终垂直于接触面，而速度沿斜面方向，力与位移方向垂直，故支持力做功为零，动能定理中不必出现","do":"比较支持力方向与位移方向，确认二者垂直，将支持力项从动能定理中剔除","expr":"W_N=0","cues":["支持力垂直斜面","垂直不做功","只算重力和摩擦"],"concepts":["支持力"]},{"title":"明确克服摩擦力做功的符号","type":"关系建立","judge":"判断动能定理中摩擦力做功取负号，而题目所求“克服摩擦力做的功”是其绝对值","why":"摩擦力方向与位移方向相反，做负功；克服摩擦力做的功等于摩擦力做功的绝对值，二者差一个负号，混淆会得到相反符号的答案","do":"在动能定理中写 -W_f（W_f 为克服摩擦力做的功），使方程两边符号一致","expr":"mgh-W_f=\\frac12 mv^2","cues":["摩擦做负功","克服摩擦是正值","别把符号弄反"],"concepts":["负功","克服摩擦力做功"]},{"title":"用动能定理建立功与速度关系","type":"关系建立","judge":"判断重力做正功 mgh、初动能为零，合功等于动能变化，从而把 h、v、W_f 联系起来","why":"只有重力和摩擦力做功，重力做功由高度差决定与路径无关，动能变化由初末速度决定，动能定理正好把待求的 W_f 单独解出","do":"对整段过程列动能定理，代入初速度为零，解出 W_f","expr":"mgh-W_f=\\frac12 mv^2-0","cues":["列动能定理","初动能为零","重力做功看高度"],"concepts":["动能定理","重力做功"]},{"title":"排除用运动学求摩擦的歧路","type":"结论整理","judge":"判断本题不需要（也无法）求斜面倾角、摩擦因数或加速度，直接用能量关系即可得到结果","why":"题给条件只有 h、v、m、g，没有斜面倾角与摩擦因数，若试图用牛顿第二定律加运动学公式会引入未知量而无法求解","do":"检查所列方程中未知量个数，确认动能定理一步即可解出 W_f，不再引入倾角或摩擦因数","expr":"W_f=mgh-\\frac12 mv^2","cues":["不用求加速度","条件不够求摩擦因数","能量法一步到位"],"concepts":["动能定理","功能关系"]}],"610":[{"title":"两波传播速度相同","type":"前提判断","judge":"是否认定甲、乙两列波在同一均匀介质中传播速度大小相等","why":"同一种均匀介质决定波速只由介质性质决定，与波源无关，这是后面所有对称推理的前提；若误以为波速随波源或频率变化，就会算错相遇位置","do":"从题干“同一均匀介质”“波速大小相等”提取条件，确认两波速率相同","expr":"v_甲=v_乙=v","cues":["同一介质波速相同","波速由介质决定"],"concepts":["波速","介质"]},{"title":"确定两波初始位置","type":"图像读取","judge":"从波形图上读出甲波右端与乙波左端各自的横坐标，判断两波此刻相距多远","why":"相遇位置由两波前端之间的距离和相向运动共同决定，读错端点坐标后面全错","do":"读图找出甲波最右端坐标和乙波最左端坐标，算出两者间距","expr":"","cues":["看波的前沿","读两端坐标"],"concepts":["波形图","坐标"]},{"title":"相向运动对称相遇","type":"关系建立","judge":"两波相向传播且速率相等时，相遇点是否在两波前端连线的中点","why":"相同时间内两波传播距离相同，故各自走过总间距的一半，相遇点必在中点；这是判断“开始相遇位置”的核心","do":"取两波前端坐标的平均值作为开始相遇的位置","expr":"x_遇=\\frac{x_{甲前}+x_{乙前}}{2}","cues":["各走一半","取中点"],"concepts":["波的传播","对称性"]},{"title":"波峰相遇点判断","type":"关系建立","judge":"两列波的波峰是否也按同样对称方式在中点相遇","why":"波峰随波以相同波速平移，两波峰间距同样被等分，故波峰相遇点也在两波峰坐标的中点；干扰项错在把波峰相遇点与波前相遇点混为一谈","do":"读出甲、乙波峰的横坐标，取二者平均值作为波峰相遇位置","expr":"x'=\\frac{x_1+x_2}{2}","cues":["波峰也对称","峰对峰取中点"],"concepts":["波峰","波的传播"]}],"611":[{"title":"确定中心天体","type":"前提判断","judge":"捕获轨道与冻结轨道绕行的中心天体是月球还是地球","why":"开普勒第三定律的比值只在同一中心天体的不同轨道间成立，中心天体不同则 k 值不同，不能直接比较","do":"由题设“绕月球运行、近月制动”确认两轨道中心天体均为月球，才能对两轨道用同一 k","expr":"\\frac{a_1^3}{T_1^2}=\\frac{a_2^3}{T_2^2}","cues":["绕月球转","同一中心天体","k相同"],"concepts":["开普勒第三定律","中心天体"]},{"title":"半长轴定周期","type":"关系建立","judge":"用半长轴之比和已知周期求捕获轨道周期，应选哪条定律、比值方向如何","why":"开普勒第三定律给出 a³/T² 为常量，周期随半长轴的 3/2 次方变化","do":"把 a₁=51900 km、a₂=9900 km、T₂=24 h 代入，算 T₁=T₂(a₁/a₂)^{3/2}","expr":"T_1=T_2\\left(\\frac{a_1}{a_2}\\right)^{3/2}","cues":["半长轴大的周期长","开普勒第三定律","三次方比二次方"],"concepts":["开普勒第三定律","半长轴"]},{"title":"椭圆轨道快慢","type":"关系建立","judge":"同一椭圆轨道上近月点与远月点的速率谁大","why":"开普勒第二定律：面积速度恒定，离中心天体近处速率大","do":"比较近月点与远月点到月心的距离，距离小处速率大","expr":"v_{\\text{近}}>v_{\\text{远}}","cues":["近的快远的慢","开普勒第二定律","面积相同"],"concepts":["开普勒第二定律","近日点速度"]},{"title":"制动改变近月点速度","type":"模型选择","judge":"从捕获轨道变到冻结轨道，近月点速度是变大还是变小","why":"进入更低（半长轴更小）的轨道需在近月点减速制动，故原轨道近月点速度更大","do":"比较两轨道近月点速度：捕获轨道需制动减速才能进入冻结轨道，故捕获轨道近月点速度更大","expr":"v_{\\text{捕,近}}>v_{\\text{冻,近}}","cues":["制动就是减速","低轨道速度大","近月点减速"],"concepts":["变轨","近月制动"]},{"title":"加速度只看引力","type":"结论整理","judge":"两轨道在近月点（同一点）的加速度是否相同","why":"加速度由万有引力产生，a=GM/r²，只由该点位置决定，与所在轨道无关","do":"比较同一点到月心距离相同，得万有引力相同、加速度相同","expr":"a=\\frac{GM}{r^2}","cues":["同一点引力相同","加速度看位置","与轨道无关"],"concepts":["牛顿第二定律","万有引力"]}],"612":[{"title":"两弹簧合力的方向","type":"模型选择","judge":"两弹簧对小球拉力的合力沿什么方向","why":"两弹簧等长且对称，形变量相同，弹力大小相等，其合力必沿竖直方向（角平分线方向）","do":"以小球为对象，把两弹簧弹力沿竖直和水平分解，水平分量等大反向抵消","expr":"F_合=2k\\Delta x\\cos\\theta","cues":["对称抵消","只看竖直","水平抵消了"],"concepts":["对称性","力的合成","弹力"]},{"title":"P点平衡求弹簧合力","type":"关系建立","judge":"P点静止时两弹簧合力的大小与方向","why":"缓慢拉至P点保持静止，小球处于平衡态，三力（拉力、重力、弹簧合力）平衡","do":"对P点小球列竖直方向平衡方程，由F=2mg、重力mg求出弹簧合力","expr":"F_弹=F-mg=mg","cues":["三力平衡","先求弹簧合力","向上拉"],"concepts":["共点力平衡","受力分析"]},{"title":"撤力后合力方向判断","type":"前提判断","judge":"撤去拉力后，从P到O过程中弹簧合力与重力的合方向是否始终向下","why":"P点弹簧合力向上、大小mg，与重力mg恰好平衡；向O运动时形变量减小，弹簧向上合力小于mg，故总合力向下","do":"比较各位置弹簧向上合力与重力mg的大小，判断合外力方向","expr":"F_合=mg-F_弹>0（向下）","cues":["合力向下","一直加速","形变变小"],"concepts":["合力方向","加速条件","胡克定律"]},{"title":"加速度最大值位置","type":"临界条件","judge":"加速度最大出现在哪一位置","why":"弹簧形变量随上升而减小，向上弹力减小，向下合力从P点的最大值单调减小，故P点加速度最大","do":"取P点刚撤去拉力瞬间列牛顿第二定律，此时弹簧合力仍为mg","expr":"mg+mg=ma_{max}","cues":["P点最大","刚撤力时","形变最大"],"concepts":["牛顿第二定律","临界状态"]},{"title":"速度与加速度变化趋势","type":"结论整理","judge":"从P到O速度如何变化、加速度如何变化","why":"合外力始终向下且与运动同向，速度一直增大；合外力大小不断减小，加速度不断减小","do":"由合力方向判速度增减，由合力大小判加速度增减","expr":"a=\\frac{mg-F_弹}{m}","cues":["一直加速","加速度变小","到O最快"],"concepts":["加速度与速度关系","变加速运动"]}],"613":[{"title":"取微元水柱为对象","type":"模型选择","judge":"研究哪一部分水、以什么为质量来源","why":"功率是能量对时间的比率，必须取一段时间内流出的水作为研究对象，才能把功率与流量、速度联系起来","do":"取 t 时间内从出水口射出的水柱，用流量乘时间求质量","expr":"m=\\rho S v_0 t","cues":["取一段时间的水","用流量算质量","水柱当整体"],"concepts":["微元法","流量","质量守恒"]},{"title":"由平抛反求出口速度","type":"关系建立","judge":"出水口射出的水做什么运动，用哪两个方向的关系消去时间","why":"水离开出水口后只受重力，水平匀速、竖直自由落体，题给的 h 与 l 正是这两个方向的约束","do":"竖直方向写自由落体求飞行时间，水平方向写匀速直线求初速度","expr":"h=\\frac12 gt'^2,\\quad l=v_0 t'\\Rightarrow v_0=l\\sqrt{\\frac{g}{2h}}","cues":["平抛运动","竖直自由落体","水平匀速"],"concepts":["平抛运动","运动的分解"]},{"title":"机械能增量含提升与动能","type":"关系建立","judge":"水从井面到出水口增加的机械能包含哪几部分","why":"水泵做功使水从井中水面升到出水口并具有射出速度，势能增量按 H+h 计，动能增量按出口速度计","do":"写出单位时间（或 t 时间内）水的重力势能增量与动能增量之和","expr":"\\Delta E=mg(H+h)+\\frac12 mv_0^2","cues":["高度差是H加h","还要算动能","从井面算起"],"concepts":["重力势能","动能","功能关系"]},{"title":"效率折算输出功率","type":"前提判断","judge":"η 是输出能量的比例还是输入功率的比例，功率该由谁除谁","why":"题设说输出能量的 η 倍转化为水的机械能，故水泵输出能量乘 η 等于水获得的机械能，输出功率应比水获得功率大","do":"把 η 乘在输出功率一侧，与水获得的机械能功率相等","expr":"P\\eta t=\\Delta E","cues":["效率乘在输出端","输出功率更大","别把η除反"],"concepts":["效率","能量转化"]},{"title":"化简时保留 h 与 H 的组合","type":"数学处理","judge":"代入速度后如何整理，避免把 h 与 H 混淆或漏项","why":"速度含根号与 h，势能项含 H+h，动能项含 l²/h，整理时需通分合并才能与选项形式对应","do":"将 v₀ 代入 ΔE 后提出公因子 ρgSl√(2gh)/(2ηh)，核对括号内各项","expr":"P=\\frac{\\rho gSl\\sqrt{2gh}}{2\\eta h}\\left(H+h+\\frac{l^2}{4h}\\right)","cues":["先代速度再通分","括号里三项","注意根号位置"],"concepts":["代数化简","量纲核对"]}],"614":[{"title":"系统动量是否守恒","type":"前提判断","judge":"三球系统在水平面内所受合外力是否为零，能否用动量守恒","why":"光滑水平面、细线拉力为内力、库仑力成对抵消，合外力为零，动量守恒才成立；若误判为不守恒，就无法建立速度关系","do":"对三球整体受力分析，确认无水平外力，写出动量守恒方程","expr":"m v_{1}+m v_{2}+m v_{3}=0","cues":["取整体","合外力为零","动量守恒"],"concepts":["动量守恒","内力与外力","整体法"]},{"title":"末态速度方向与对称性","type":"几何关系","judge":"三球共线时，球1、球2的速度是否等大反向，球3速度方向如何","why":"初始构型与受力对球1、球2对称，运动过程保持对称，故两者速度大小相等、方向相反；球3沿对称轴运动","do":"画出共线时刻的速度方向，利用对称性令 v1=v2，并确定动量守恒中各项的符号","expr":"v_{1}=v_{2},\\quad 2m v_{1}=m v_{3}","cues":["对称","等大反向","沿对称轴"],"concepts":["对称性","速度方向","动量守恒"]},{"title":"能量转化关系建立","type":"关系建立","judge":"减少的电势能转化为什么，动能如何分配","why":"光滑绝缘面无摩擦、无外力做功，电势能减少量等于系统总动能增加量","do":"把题给的电势能减少量与三球动能之和相等，联立速度关系求解","expr":"\\tfrac12 m v_{1}^{2}+\\tfrac12 m v_{2}^{2}+\\tfrac12 m v_{3}^{2}=\\frac{kq^{2}}{2d}","cues":["能量守恒","电势能变动能","三球动能相加"],"concepts":["能量守恒","电势能","动能"]},{"title":"球3合力是否恒定","type":"结论整理","judge":"球3所受合力在整个过程中是否保持不变","why":"球3从静止启动瞬间合力不为零，而共线时两侧库仑力等大反向、合力为零，合力必然变化，故不是匀加速","do":"比较初态与末态球3所受合力，判断是否为恒力","expr":"","cues":["先看合力","从静止启动","合力在变"],"concepts":["库仑力","合力","变加速运动"]}],"615":[{"title":"分解两方向受力","type":"模型选择","judge":"斜面上物块的运动应沿哪两个方向分解，各方向受哪些力","why":"斜面光滑，重力沿斜面向下的分量 mg sin30° 只作用在 y 方向且恒定，F1、F2 沿 x 方向，两方向互不影响","do":"沿斜面建系：y 方向只受 mg sin30°，x 方向只受 F1、F2 的合力","expr":"","cues":["沿斜面和水平分解","重力分量在y向","两力都在x向"],"concepts":["运动的分解","牛顿第二定律","正交分解"]},{"title":"读图写出力的表达式","type":"图像读取","judge":"由图(b)读出 F1、F2 随时间的变化规律并合成 x 方向合力","why":"F1 从 4 N 线性减到 0，F2 从 0 线性增到 6 N，方向相同应相加而非相减","do":"分别写出两直线的截距与斜率，再相加得 x 方向合力随时间的关系","expr":"F_1=4-t,\\quad F_2=3t,\\quad F_x=4+2t","cues":["两力同向相加","看截距和斜率","F随t线性变"],"concepts":["图像斜率","力的合成"]},{"title":"判断是否匀变速","type":"前提判断","judge":"x 方向合力随时间变化时，物块整体是否做匀变速运动","why":"匀变速要求加速度大小方向都不变，而 x 方向加速度随 t 增大，合加速度方向不断改变","do":"比较 x 方向加速度是否恒定，判断合加速度是否变化","expr":"a_x=\\frac{4+2t}{1.2}","cues":["合力在变","加速度方向在变","不是匀变速"],"concepts":["匀变速运动","加速度"]},{"title":"分方向独立求位移与速度","type":"关系建立","judge":"y 方向匀加速、x 方向变加速，能否分别独立用运动学与动量定理求解","why":"两方向受力互不影响，y 方向可用匀加速公式，x 方向力线性变化可用平均力或动量定理","do":"y 向用 y=½a_y t²、v_y=a_y t；x 向用冲量等于动量变化求 v_x","expr":"y=\\tfrac12 a_y t^2,\\quad v_y=a_y t,\\quad \\bar{F}_x t=m v_x","cues":["两方向分开算","y向匀加速","x向用冲量"],"concepts":["匀变速直线运动","动量定理","运动的独立性"]},{"title":"合成求合速度与合加速度","type":"数学处理","judge":"求出两分速度、分加速度后如何合成总量","why":"速度与加速度都是矢量，需按勾股定理合成，不能直接相加","do":"在 t=2 s 时分别求 v_x、v_y 与 a_x、a_y，再矢量合成","expr":"v=\\sqrt{v_x^2+v_y^2},\\quad a=\\sqrt{a_x^2+a_y^2}","cues":["矢量合成","用勾股定理","先求分量再合成"],"concepts":["速度合成","加速度合成"]}],"616":[{"title":"重力电场力平衡","type":"前提判断","judge":"油滴 a 能做匀速圆周运动，是否必须让重力与电场力等大反向","why":"只有合外力恰好等于洛伦兹力时，速率才不变、轨迹才是圆；若重力与电场力不平衡，速度大小会变，就不是圆周运动","do":"对油滴 a 列竖直方向平衡方程，并由电场方向与电场力方向反推电性","expr":"mg=qE","cues":["重力电场力抵消","匀速圆周","先定电性"],"concepts":["电场力","重力","平衡条件"]},{"title":"洛伦兹力提供向心力","type":"关系建立","judge":"圆周运动的半径由哪个力提供，半径公式中质量、电量、速度如何组合","why":"洛伦兹力始终垂直于速度，是唯一的向心力来源，半径与动量成正比、与电荷量成反比","do":"对 a 写向心力方程，解出 a 的速率，再代入 q=mg/E 化为已知量","expr":"qvB=\\frac{mv^{2}}{R}\\Rightarrow v=\\frac{qBR}{m}=\\frac{gBR}{E}","cues":["洛伦兹力当向心力","半径看动量","消去电量"],"concepts":["洛伦兹力","向心力","圆周运动半径"]},{"title":"分裂后半径比推速度","type":"关系建立","judge":"Ⅰ 的质量、电量都减半后，半径变为 3R 意味着它的速度是 a 的几倍","why":"半径 R=mv/(qB)，质量与电量同比例减半时 m/q 不变，半径之比就等于速度之比","do":"对 Ⅰ 写半径公式，与 a 的半径公式作比，求出 Ⅰ 的速率","expr":"3R=\\frac{(m/2)v_{1}}{(q/2)B}\\Rightarrow v_{1}=3v","cues":["质量电量都减半","半径比就是速度比","比值不变"],"concepts":["半径公式","比荷"]},{"title":"周期与速度无关","type":"结论整理","judge":"Ⅰ 的周期是否随半径和速率同时变化而改变","why":"周期 T=2πm/(qB)，只由比荷和磁感应强度决定，与速率、半径无关；Ⅰ 的比荷与 a 相同，周期应与 a 相同","do":"用 T=2π·3R/v₁ 算出 Ⅰ 的周期，再与 a 的周期 T=2πm/(qB) 比较","expr":"T=\\frac{2\\pi m}{qB}=\\frac{2\\pi E}{gB}","cues":["周期只看比荷","半径大速度也大","周期不变"],"concepts":["圆周运动周期","比荷"]},{"title":"分裂瞬间动量守恒","type":"模型选择","judge":"瞬间分裂过程能否用动量守恒求 Ⅱ 的速度，正方向如何取","why":"分裂时间极短，重力和电场力的冲量可忽略，内力远大于外力，系统动量守恒；取 a 原速度方向为正","do":"对 a 与 Ⅰ、Ⅱ 列动量守恒方程，代入 v 与 v₁ 解出 v₂ 的符号和大小","expr":"mv=\\frac{m}{2}v_{1}+\\frac{m}{2}v_{2}\\Rightarrow v_{2}=-v","cues":["瞬间分裂动量守恒","取原速度为正","看符号定方向"],"concepts":["动量守恒","正方向"]},{"title":"由速度方向定绕行方向","type":"几何关系","judge":"Ⅱ 带负电、速度反向时，洛伦兹力指向圆心哪一侧，从而判断顺逆时针","why":"负电荷用左手定则时四指指向速度反方向；磁场向里，速度与 a 反向，洛伦兹力方向决定圆心在轨迹哪侧","do":"先由 v₂ 为负确定 Ⅱ 的实际速度方向，再用左手定则判断洛伦兹力指向，确定绕行方向","expr":"","cues":["负电荷左手定则","速度反了","看力指圆心"],"concepts":["左手定则","洛伦兹力方向"]}],"617":[{"title":"界面线的画法","type":"实验操作","judge":"画玻璃砖两界面时，是沿玻璃砖边缘直接描线，还是先描一条、再用直尺平移描另一条","why":"玻璃砖边缘与笔尖有宽度差，直接沿边描两条线会使测得的宽度和实际光路界面不符，引入系统误差","do":"比较 A 项做法与规范做法：先画一条界面线 a，放砖对齐，用直尺贴另一长边定位后取出玻璃砖再画 a'","expr":"","cues":["沿边描线","用直尺平移","砖要取下来画"],"concepts":["界面线","作图误差"]},{"title":"插针确定光路","type":"实验操作","judge":"判断 P3、P4 应满足什么遮挡条件，才能唯一确定出射光线和出射点","why":"插针法利用光的直线传播，只有后针挡住前面所有针的像，四针才共线，出射光线才被唯一确定","do":"核对 B 项：P2 挡 P1 定入射光线与 O1，P3 挡 P1、P2，P4 挡 P1、P2、P3，定出射光线与 O2","expr":"","cues":["后针挡前针","四针共线","透过砖看"],"concepts":["插针法","光的直线传播"]},{"title":"入射角大小的取舍","type":"前提判断","judge":"入射角应取小一些还是适当大一些，才能减小相对误差","why":"入射角过小时折射角也小，两角正弦值接近且角度测量绝对误差不变，相对误差被放大","do":"比较 C 项与规范要求：入射角适当大些但不接近 90°，兼顾可观测与相对误差","expr":"","cues":["角大误差小","别接近九十度","角小测不准"],"concepts":["相对误差","入射角"]},{"title":"由偏折判频率关系","type":"关系建立","judge":"相同入射角下，由两束光折射角的大小判断哪种光折射率大，再联系频率","why":"折射定律 n=sinα/sinβ，入射角相同则折射角越小折射率越大；同种介质中频率越大的光折射率越大","do":"在图(b)中比较红光与绿光折射角，绿光偏折更厉害即折射角更小，对应频率更大、折射率更大","expr":"n=\\frac{\\sin\\alpha}{\\sin\\beta}","cues":["看谁偏得多","绿光偏折大","折射角小的n大"],"concepts":["折射定律","光的色散"]},{"title":"同入射角比较折射率","type":"关系建立","judge":"入射角相同时，折射角越小对应的折射率越大还是越小","why":"由 n=sinα1/sinβ，分子相同，分母（折射角正弦）越小则 n 越大","do":"比较 α2 与 α3，α2<α3，故玻璃对应折射率更大","expr":"n=\\frac{\\sin\\alpha_1}{\\sin\\alpha_2}","cues":["折射角小n大","分母小分数大","比折射角就行"],"concepts":["折射定律","折射率"]}],"618":[{"title":"分压接法的安全位置","type":"实验操作","judge":"闭合开关前滑片应放在使输出电压最小的一端，需判断分压电路中哪一端对应输出为零","why":"滑动变阻器为分压式接法，测量电路与滑片到某端的电阻并联，滑片置于该端时并联部分电压为零，保护电表和电源","do":"观察图(a)中滑动变阻器的接法，找出使测量电路分得电压为零的滑片位置","expr":"","cues":["分压接法","滑片放到零电压端","保护电表"],"concepts":["分压电路","滑动变阻器","安全操作"]},{"title":"双量程的串阻分配","type":"模型选择","judge":"接 a 与接 b 分别对应哪个量程，以及两个量程下串联的电阻分别是哪几部分","why":"改装电压表靠串联分压，量程越大串联的电阻越多；接 b 时 R2 被短接，只有 Rg+R1 参与分压，接 a 时 Rg+R1+R2 全部参与","do":"分别对 S2 接 b、接 a 写出满偏时的电压表达式，用两个量程联立求 R2","expr":"U_1=I_g(R_g+R_1),\\quad U_2=I_g(R_g+R_1+R_2)","cues":["接b量程小","接a量程大","串联电阻越多量程越大"],"concepts":["电压表改装","串联分压","满偏电流"]},{"title":"用标准表反推内阻","type":"关系建立","judge":"接 a 时标准电压表读数 U 与电流表读数 I 之比代表哪一段总电阻","why":"标准电压表测的是改装表两端电压，电流表 G 示数是通过该支路的电流，欧姆定律给出整条串联支路的总电阻","do":"对接 a 时的串联支路列欧姆定律，把 Rg 移到等号一边","expr":"R_g=\\frac{U}{I}-R_1-R_2","cues":["总电阻减串联电阻","标准表读数除以电流","整条支路欧姆定律"],"concepts":["欧姆定律","伏安法测电阻","串联电路"]},{"title":"读数偏大的偏差方向","type":"前提判断","judge":"改装表读数偏大说明实际串联总电阻偏大还是偏小，进而判断真实 Rg 比标称值大还是小","why":"同一电流下改装表读数由串联总电阻决定，读数偏大说明实际总电阻大于设计值；而 Rg 真实值偏小才会使按标称值算出的读数偏大","do":"比较实际总电阻与设计总电阻，再判断应增大还是减小电阻箱阻值","expr":"","cues":["真实内阻偏小","要补上差值"],"concepts":["电表校准","误差方向","串联电阻"]},{"title":"读表与量程对应","type":"图像读取","judge":"图(b)读数应取哪个量程刻度，以及该示数对应接 b 时的哪条电压换算关系","why":"S2 接 b 时改装表量程为 1 V，表盘读数需按电流表量程读出微安数，再乘以 Rg+R1 换算成电压","do":"读出图(b)电流表 G 的示数，代入接 b 时的电压表达式计算","expr":"U=I_A(R_g+R_1)","cues":["先读微安数","接b用小的那组电阻","再乘总电阻"],"concepts":["电表读数","电压表改装","有效数字"]}],"619":[{"title":"确定研究对象为封闭气体","type":"模型选择","judge":"把轮胎内原有气体视为质量不变的封闭系统，还是把充气前后混在一起考虑","why":"第（1）问充气前没有气体进出，轮胎容积不变，原有气体质量固定，才能用定质量气体的状态方程","do":"取充气前轮胎内原有气体为研究对象，确认其质量、体积均不变","expr":"","cues":["取轮胎内原来的气","质量不变","体积不变"],"concepts":["封闭气体","理想气体"]},{"title":"温度换算为热力学温度","type":"前提判断","judge":"代入气体定律前，是否把摄氏温度换算成热力学温度","why":"查理定律、理想气体状态方程中的温度必须是热力学温度，直接用摄氏温度会使比值错误","do":"分别把出发时和哈尔滨的温度加上 273 换算成热力学温度","expr":"T_1=273+t_1,\\quad T_2=273+t_2","cues":["先加273","换成开尔文","不能直接用摄氏"],"concepts":["热力学温度","摄氏温度"]},{"title":"等容过程选查理定律","type":"关系建立","judge":"第（1）问中气体体积不变、质量不变，压强随温度变化应选哪个定律","why":"轮胎容积不变且未漏气，是等容变化，压强与热力学温度成正比","do":"对充气前原有气体列等容变化方程，由初态压强温度求末态压强","expr":"\\frac{p_1}{T_1}=\\frac{p_2}{T_2}","cues":["体积不变","等容变化","压强比等于温度比"],"concepts":["查理定律","等容变化"]},{"title":"充气过程选玻意耳定律","type":"关系建立","judge":"第（2）问中温度不变、充入气体与原有气体混合，应把哪部分气体作为对象、用哪个定律","why":"充气前后温度相同，可把原有气体与充入气体合并看成总质量不变的系统，整体经历等温过程","do":"以充气后轮胎内全部气体为对象，把充入的空气在压强为大气压、体积为待求量 V 下的状态与原有气体状态合并列等温方程","expr":"p_2V_0+p_0V=p_1V_0","cues":["温度不变","等温混合","把充入的气也算进去"],"concepts":["玻意耳定律","等温变化","混合气体"]},{"title":"充入气体按大气压计体积","type":"前提判断","judge":"充入空气的体积 V 应在哪个压强下计量","why":"题目说充入压强与大气压相同的空气，所求体积是这些空气在大气压下的体积，而非进入轮胎后被压缩后的体积","do":"把充入部分写成 p_0V 的形式，与轮胎内原有气体的 p_2V_0 相加等于充气后总状态 p_1V_0","expr":"p_0V","cues":["按大气压算体积","充入的是常压空气","不是轮胎里的体积"],"concepts":["大气压强","气体状态参量"]}],"620":[{"title":"最低点拉力用向心力","type":"关系建立","judge":"求最低点绳拉力时，是否判断出拉力不等于重力、必须补上向心加速度项","why":"小球在最低点做圆周运动，绳拉力与重力的合力提供向心力，只由平衡条件会漏掉 mv²/L 这一项","do":"先由摆动过程求最低点速度，再在最低点沿半径方向列牛顿第二定律方程","expr":"F_T-mg=m\\dfrac{v_0^2}{L}","cues":["最低点拉力最大","要加向心力","不能只等于重力"],"concepts":["向心力","牛顿第二定律","机械能守恒"]},{"title":"碰撞用弹性碰撞规律","type":"模型选择","judge":"判断小球与物块的碰撞属于哪类碰撞、该用哪组方程","why":"题设明确为弹性碰撞，动量守恒与机械能守恒同时成立；若按完全非弹性处理会得到错误速度","do":"对小球和物块列水平方向动量守恒式和机械能守恒式，联立解出碰后物块速度","expr":"mv_0=mv_1+Mv_2,\\quad \\tfrac12 mv_0^2=\\tfrac12 mv_1^2+\\tfrac12 Mv_2^2","cues":["弹性碰撞","两个守恒都要用","碰后速度有公式"],"concepts":["弹性碰撞","动量守恒","机械能守恒"]},{"title":"水平段取物块小车整体","type":"模型选择","judge":"物块在粗糙水平轨道上滑动时，是否把物块与小车取为系统、用水平动量守恒处理","why":"水平面光滑，系统水平方向不受外力，动量守恒；摩擦力是内力，只耗散机械能，取整体可避开求摩擦力和加速度","do":"以物块和小车为系统列水平动量守恒式，再用能量守恒把摩擦生热与相对位移 s 联系起来","expr":"Mv_2=2Mv_3,\\quad \\tfrac12 Mv_2^2=\\tfrac12(2M)v_3^2+\\mu Mgs","cues":["取整体","水平方向动量守恒","摩擦生热看相对位移"],"concepts":["动量守恒","能量守恒","相对位移"]},{"title":"进入圆弧的临界判断","type":"临界条件","judge":"判断物块恰好能进入圆弧轨道（到达最低点）时对应的动摩擦因数上限","why":"物块要进入圆弧，必须在到达轨道末端前不与小车共速；恰好到达最低点共速是能否进入的临界","do":"令物块到达圆弧最低点时与小车共速，用动量守恒和能量守恒解出对应的 μ 值，作为取值范围的一端","expr":"\\tfrac12 Mv_2^2=\\tfrac12(2M)v_3^2+\\mu_1 Mgs","cues":["恰好进入圆弧","到最低点共速","这是最大值"],"concepts":["临界状态","动量守恒","能量守恒"]},{"title":"不脱离的等高临界","type":"临界条件","judge":"判断物块在圆弧上升阶段不脱离小车的临界位置是圆心等高处，而非最高点","why":"圆弧轨道只到四分之一圆周，物块若越过圆心等高处继续上升就会脱离轨道，故恰好升到圆心等高是上限","do":"令物块恰好到达与圆心等高处且与小车共速，用能量守恒把重力势能 MgR 计入，解出对应的 μ 值作为另一端","expr":"\\tfrac12 Mv_2^2=\\tfrac12(2M)v_4^2+\\mu_2 Mgs+MgR","cues":["四分之一圆弧","升到圆心等高就脱离","要加势能"],"concepts":["临界条件","重力势能","能量守恒"]},{"title":"两临界值定区间","type":"结论整理","judge":"判断两个临界 μ 值分别对应区间的哪一端、端点是否取等","why":"μ 越大物块在水平段损失越多、越难进入圆弧；μ 越小越容易冲得高而脱离，故区间夹在两值之间，且能进入要求严格小于上限","do":"比较两临界值大小，按物理意义确定开闭，写出 μ 的取值范围","expr":"\\mu_2\\le\\mu<\\mu_1","cues":["夹在中间","大的取不到","小的能取到"],"concepts":["取值范围","临界分析"]}],"621":[{"title":"区分两处磁场的作用","type":"模型选择","judge":"要判断正方形区域磁场与支架上方导轨间磁场各自在电路中扮演什么角色","why":"正方形区域内磁场变化只提供感应电动势，导轨间磁场只对通电的 ab 棒提供安培力，两者互不影响","do":"把 cdef 区域当作电动势源，把 ab 所在处的磁场当作受力场，分别处理","expr":"","cues":["两个磁场分开看","一个生电一个受力"],"concepts":["法拉第电磁感应定律","安培力"]},{"title":"判断感应电流方向","type":"前提判断","judge":"要判断 cdef 区域内磁通量增大时，回路中感应电流沿哪个方向绕行，从而确定 ab 中电流由 a 到 b 还是由 b 到 a","why":"楞次定律要求感应电流的磁场阻碍原磁通量增加，原磁场垂直纸面向外且在增强","do":"先定原磁场方向与增减，再用楞次定律定感应磁场方向，最后用右手螺旋定则定回路绕向并落到 ab 棒上","expr":"","cues":["向外且在增强","增反减同","右手定绕向"],"concepts":["楞次定律","磁通量"]},{"title":"写出回路总电阻","type":"关系建立","judge":"要判断电路总电阻由哪几部分组成，以及随 ab 上移导轨间电阻如何变化","why":"下方导轨电阻 R 固定，上方接入回路的导轨长度随位移增大，单位长度电阻为 r，两边导轨都要计入","do":"用位移表示接入长度，写出上方电阻并加上 R 得总电阻","expr":"R_{总}=R+2xr,\\quad x=\\tfrac12 at^{2}","cues":["两边导轨都算","长度随位移变","总电阻等于两部分相加"],"concepts":["电阻定律","闭合电路欧姆定律"]},{"title":"安培力方向与正压力","type":"关系建立","judge":"要判断 ab 所受安培力是垂直导轨面（水平）还是竖直方向，从而决定它是否影响支持力与摩擦力","why":"导轨间磁场竖直向下，ab 水平放置，由左手定则安培力垂直于纸面，与竖直方向垂直，故不改变正压力","do":"用左手定则定安培力方向，指出正压力恒等于 mg，摩擦力为 μF安","expr":"F_{安}=BIL,\\quad f=\\mu F_{安}","cues":["安培力垂直纸面","正压力不变","摩擦力由安培力决定"],"concepts":["左手定则","滑动摩擦力"]},{"title":"拉力表达式的极值处理","type":"数学处理","judge":"要判断拉力 F 随 t 的变化不是单调的，需把含 t 的项化成可用均值不等式求极值的形式","why":"安培力项为 k²L³t/(R+art²)，分子分母都含 t，直接看会误判为单调，须化为分母除以 t 的形式","do":"把安培力项分子分母同除以 t，令分母中两项相等求极值时刻，再回代求最大值","expr":"F=\\frac{\\mu k^{2}L^{3}}{R/t+art}+m(g+a),\\quad \\frac{R}{t}=art","cues":["分子分母都有t","同除以t","两项相等取极值"],"concepts":["均值不等式","牛顿第二定律"]}],"622":[{"title":"判定衰变类型","type":"前提判断","judge":"由质量数守恒和电荷数守恒判断两种核衰变各放出什么粒子","why":"衰变方程两边质量数、电荷数必须相等，据此可反推放出的粒子种类","do":"对 Sr→Y 和 Pu→U 分别列质量数、电荷数守恒式，比较反应前后差值","expr":"^{90}_{38}\\mathrm{Sr}\\to{}^{90}_{39}\\mathrm{Y}+{}^{0}_{-1}\\mathrm{e}；\\ ^{238}_{94}\\mathrm{Pu}\\to{}^{234}_{92}\\mathrm{U}+{}^{4}_{2}\\mathrm{He}","cues":["看电荷数差","质量数不变","差四是α"],"concepts":["质量数守恒","电荷数守恒","α衰变","β衰变"]},{"title":"半衰期决定剩余量","type":"关系建立","judge":"相同时间内剩余核数与半衰期的关系，判断哪种核剩余多","why":"衰变剩余量由经过的半衰期次数决定，半衰期越短，相同时间内衰变次数越多、剩余越少","do":"比较两核半衰期大小，用剩余量公式比较相同时间后剩余数目","expr":"N=N_0\\left(\\tfrac12\\right)^{t/T}","cues":["半衰期短剩得少","看经过几个半衰期","相同时间比次数"],"concepts":["半衰期","剩余核数"]},{"title":"初始数目相同的前提","type":"前提判断","judge":"比较剩余数目时是否以两者初始数目相同为条件","why":"题目明确用相同数目的两种核各做一块电池，只有初数相同才能直接由剩余比例比较多少","do":"确认 N₀ 相同，把比较剩余量转化为比较 (1/2)^(t/T) 的大小","expr":"N_0\\ \\text{相同}\\Rightarrow \\text{比较}\\left(\\tfrac12\\right)^{t/T}","cues":["初数一样","同数目起步","只比衰减快慢"],"concepts":["初始核数","控制变量"]}],"623":[{"title":"斜面静止的临界条件","type":"临界条件","judge":"要判断机器人能静止在斜面上的临界状态对应哪个力平衡关系","why":"静摩擦随倾角增大而增大，倾角最大时静摩擦恰好达到最大值，此时是能否站稳的临界点","do":"取倾角为最大值的临界情形，沿斜面方向列静摩擦与重力分量的平衡","expr":"mg\\sin\\theta = f_{\\max}","cues":["倾角最大时最危险","刚好不下滑"],"concepts":["静摩擦力","平衡条件"]},{"title":"最大静摩擦的替换","type":"前提判断","judge":"要判断临界时最大静摩擦能否用 μN 表示","why":"题设给出最大静摩擦力等于滑动摩擦力，才可用 μ 乘正压力代替最大静摩擦","do":"把临界静摩擦写成 μ 与正压力的乘积","expr":"f_{\\max}=\\mu N","cues":["用μ代替","最大静摩擦的替换","最大静摩擦力","动摩擦因数"],"concepts":["最大静摩擦力","动摩擦因数"]},{"title":"正压力不等于重力","type":"关系建立","judge":"要判断斜面上正压力与重力的大小关系","why":"重力垂直斜面的分量才是正压力，直接用 mg 会漏掉余弦因子导致结果错误","do":"垂直斜面方向列平衡，求出正压力","expr":"N=mg\\cos\\theta","cues":["正压力要分解","别直接用重力"],"concepts":["正压力","力的分解"]},{"title":"解出摩擦因数下限","type":"数学处理","judge":"要判断不等式化简后 μ 与倾角正切的关系及取等方向","why":"由 mg sinθ ≤ μmg cosθ 约去 mg 后得 μ ≥ tanθ，倾角不超过 30° 意味着 μ 不能小于 tan30°","do":"约去 mg，把正弦余弦之比化为正切，代入 30° 求值","expr":"\\mu \\ge \\tan 30^{\\circ}=\\frac{\\sqrt{3}}{3}","cues":["化成正切","取30度算"],"concepts":["正切","不等式"]}],"624":[{"title":"木板加速度是否恒定","type":"前提判断","judge":"木板沿光滑斜面下滑时加速度是否与木板长度无关、保持同一恒定值","why":"木板整体在光滑斜面上只受重力和支持力，沿斜面分力 mg sinθ 与质量成正比，故 a=g sinθ 与板长无关，这是能用同一 a 比较两次时间的前提","do":"对木板整体沿斜面方向列牛顿第二定律，确认 a 只由斜面倾角决定","expr":"a=g\\sin\\theta","cues":["加速度一样","板长不影响","沿斜面分力"],"concepts":["牛顿第二定律","光滑斜面"]},{"title":"通过A点的起止时刻","type":"模型选择","judge":"把'木板通过 A 点'对应为从木板下端到达 A 到木板上端离开 A 的哪两个时刻","why":"木板有长度，'通过 A 点'不是质点经过一点，必须用下端到 A 作为开始、上端到 A 作为结束，否则时间间隔算错","do":"分别写出下端到 A 与上端到 A 时木板下滑的位移，取两者时间之差为通过时间","expr":"\\Delta t=t_{\\text{上}}-t_{\\text{下}}","cues":["下端到A开始","上端到A结束","板有长度"],"concepts":["质点模型","位移"]},{"title":"两次释放的位移对应","type":"几何关系","judge":"板长 L 与 2L 两种情形下，下端到 A、上端到 A 时木板分别走过的位移是多少","why":"木板下端初始距 A 为 L，板长改变只改变上端位置，下端到 A 的位移始终是 L，上端到 A 的位移随板长变为 2L 或 3L","do":"画出两种板长下木板下端、上端相对 A 点的位置，写出各自的总位移","expr":"L,\\ 2L\\ (\\text{板长}L);\\quad L,\\ 3L\\ (\\text{板长}2L)","cues":["下端都走L","上端走2L","上端走3L"],"concepts":["几何关系","位移"]},{"title":"初速为零的位移时间关系","type":"关系建立","judge":"由静止释放后位移与时间是否满足 s 正比于 t 的平方","why":"木板做初速度为零的匀加速直线运动，才能用 s=½at² 把位移比转化为时间比","do":"对下端到 A、上端到 A 两个过程分别列 s=½at²，解出对应时刻","expr":"s=\\tfrac12 at^2","cues":["从静止释放","初速为零","位移比开方"],"concepts":["匀变速直线运动","运动学公式"]},{"title":"时间间隔作差再求比","type":"数学处理","judge":"所求 Δt 是两时刻之差而非某一时刻，比值需先作差再相除","why":"通过 A 点的时间是上端到 A 与下端到 A 两时刻的间隔，直接比总时间会得到错误结果","do":"分别算出两种板长的通过时间，再求两者之比并化简","expr":"\\Delta t_1=t_1-t_0,\\ \\Delta t_2=t_2-t_0","cues":["要作差","不是总时间","先减后比"],"concepts":["时间间隔","比值化简"]}],"625":[{"title":"判定干涉发生在哪两束光","type":"模型选择","judge":"要判断干涉条纹由哪两个反射面产生的两束光叠加形成","why":"装置是两块平板玻璃夹滚珠形成的空气劈尖，只有空气层上下表面的反射光才能在上玻璃下表面附近叠加，光程差才与空气层厚度挂钩","do":"确认入射光垂直照射，取空气劈尖上表面反射光与下表面反射光作为相干光","expr":"","cues":["空气劈尖","上下表面反射","垂直入射"],"concepts":["薄膜干涉","空气劈尖","反射光"]},{"title":"光程差与空气层厚度挂钩","type":"关系建立","judge":"要判断同一干涉条纹位置对应的空气层厚度是否相同","why":"垂直入射时往返光程差等于空气层厚度的两倍，同一条纹对应同一光程差，也就对应同一空气层厚度","do":"写出光程差与厚度关系，把条纹位置与空气层厚度一一对应","expr":"$\\Delta=2d$","cues":["厚度两倍","同一明纹同厚度","条纹对应厚度"],"concepts":["光程差","等厚干涉"]},{"title":"由条纹形状判断直径关系","type":"几何关系","judge":"要判断条纹是平行等距直条纹还是弯曲/疏密变化，从而判断两滚珠直径是否相等","why":"若两滚珠直径相等，空气劈尖是等厚楔形，条纹为平行等距直条纹；直径不等则劈尖厚度沿横向非线性变化，条纹弯曲或间距改变","do":"读图乙中条纹的走向与间距是否均匀，比较条纹形状与等厚楔形条纹的差异","expr":"","cues":["看条纹直不直","看间距匀不匀","条纹弯了"],"concepts":["等厚干涉","楔形空气层","条纹形状"]},{"title":"区分合格与不合格的判据","type":"结论整理","judge":"要判断哪一颗待测滚珠与标准滚珠直径相等（合格），哪一颗不等（不合格）","why":"只有直径相等时空气劈尖才保持等厚楔形，条纹才与标准情形一致；条纹异常说明该侧滚珠直径与标准值不等","do":"把条纹正常的一侧对应的滚珠判为合格，条纹异常的一侧判为不合格","expr":"","cues":["条纹正常就合格","条纹异常不合格","和标准比"],"concepts":["等厚干涉","直径比较"]}],"626":[{"title":"识别周期相同","type":"前提判断","judge":"鹊桥二号椭圆轨道周期与地球同步卫星周期是否相等","why":"题给 24 小时椭圆轨道，同步卫星周期也是 24 小时，只有两者周期相同才能把 T 约掉","do":"把鹊桥二号的周期 T 与同步卫星周期 T′ 都取为 24 小时并令其相等","expr":"T=T'=24\\ \\text{h}","cues":["都是24小时","周期一样","同步就是24小时"],"concepts":["周期","地球同步卫星"]},{"title":"选开普勒第三定律","type":"模型选择","judge":"用哪条规律把半长轴、周期和中心天体质量联系起来","why":"椭圆轨道与圆轨道都满足开普勒第三定律，且常量只由中心天体决定，这是唯一能沟通 a、r 与两天体质量的规律","do":"对绕月的鹊桥二号和绕地的同步卫星分别写开普勒第三定律","expr":"\\frac{a^{3}}{T^{2}}=k,\\quad \\frac{r^{3}}{T'^{2}}=k'","cues":["用开普勒第三定律","a³比T²是定值","中心天体不同常量不同"],"concepts":["开普勒第三定律","半长轴"]},{"title":"常量正比于中心质量","type":"关系建立","judge":"开普勒常量 k 与中心天体质量是什么关系","why":"由万有引力提供向心力可推出 k=GM/(4π²)，常量与中心天体质量成正比，这是把轨道参数换算成质量比的关键桥梁","do":"写出 k 与中心天体质量的表达式，取两中心天体的 k 之比","expr":"k=\\frac{GM}{4\\pi^{2}}\\ \\Rightarrow\\ \\frac{M_{\\text{月}}}{M_{\\text{地}}}=\\frac{k}{k'}","cues":["常量正比于质量","k等于GM除4π²","质量比就是常量比"],"concepts":["开普勒常量","万有引力定律","中心天体质量"]},{"title":"联立消去周期","type":"数学处理","judge":"把两个开普勒方程相除后周期能否消去","why":"两周期相等，相除时 T² 与 T′² 约掉，质量比只剩半长轴与半径的立方比","do":"将两式相除并代入 T=T′，化简得质量比","expr":"\\frac{M_{\\text{月}}}{M_{\\text{地}}}=\\frac{a^{3}/T^{2}}{r^{3}/T'^{2}}=\\frac{a^{3}}{r^{3}}","cues":["两式相除","周期约掉","只剩立方比"],"concepts":["比例运算","开普勒第三定律"]}],"627":[{"title":"识别三类过程性质","type":"前提判断","judge":"要判断 a→b、b→c、c→a 各是什么热力学过程，以及各过程中体积、温度如何变化","why":"等压、绝热、等温三种过程的约束不同，直接决定用哪个定律和 Q、W 的取值","do":"读图：a→b 体积增大且压强不变；b→c 体积增大且 Q=0；c→a 体积减小且 T 不变","expr":"","cues":["等压膨胀","绝热膨胀","等温压缩"],"concepts":["等压过程","绝热过程","等温过程"]},{"title":"比较各状态温度高低","type":"关系建立","judge":"要判断 T_a、T_b、T_c 三者的相对大小","why":"内能变化只由温度决定，必须先定出温度高低才能判断 ΔU 的正负","do":"a→b 等压膨胀由盖-吕萨克定律得 T_b>T_a；c→a 等温得 T_c=T_a；故 T_b>T_c","expr":"\\frac{V_a}{T_a}=\\frac{V_b}{T_b},\\quad T_c=T_a","cues":["等压膨胀升温","等温温度相同","b点温度最高"],"concepts":["盖-吕萨克定律","理想气体内能"]},{"title":"用第一定律定吸放热","type":"关系建立","judge":"要判断每个过程（或组合过程）中 Q 与 W 的正负及大小关系","why":"热力学第一定律 ΔU=Q+W 是判断吸热、放热、做功关系的唯一依据，符号约定必须统一","do":"对 a→b 写 ΔU_ab=Q_ab+W_ab；对 b→c 取 Q=0 由体积增大得 W<0 推 ΔU<0；对 a→b→c 整体用 ΔU=0 联系 Q 与 W","expr":"\\Delta U=Q+W","cues":["先定符号","体积增大对外做功","绝热没有热交换"],"concepts":["热力学第一定律","做功符号约定"]},{"title":"循环整体净功判断","type":"结论整理","judge":"要判断整个循环的净功方向，以及 a→b 吸热与 c→a 放热是否相等","why":"循环一周 ΔU=0，净热量等于净功；只有净功为零时吸放热才相等，需由体积变化判断净功方向","do":"比较循环中膨胀与压缩的净效果，判断整体对外做功 W≠0，再由 ΔU=0 得 Q_ab≠-Q_ca","expr":"\\Delta U_{\\text{循环}}=0\\Rightarrow Q_{\\text{净}}=W_{\\text{净}}","cues":["循环内能不变","整体对外做功","吸放热不相等"],"concepts":["热力学循环","净功"]}],"628":[{"title":"甲刚要动的临界条件","type":"临界条件","judge":"甲所坐木板刚要离开原位置时，绳的拉力与甲所受最大静摩擦力满足什么关系","why":"甲不动时绳拉力被静摩擦力平衡，刚要滑动时静摩擦力达到最大值，且题设最大静摩擦力等于滑动摩擦力 μmg","do":"对甲及其木板整体沿水平方向列临界方程，求出绳的伸长量","expr":"kx_0=\\mu mg","cues":["刚要动","静摩擦到最大","等于滑动摩擦"],"concepts":["最大静摩擦力","临界状态","胡克定律"]},{"title":"绳伸长与位移的几何关系","type":"几何关系","judge":"乙的位移等于绳的伸长量加上哪一段长度差","why":"绳原长 l 大于连接点间距 d，绳先要伸到原长才开始产生拉力，之后继续伸长 x0，乙的位移是这两部分之和","do":"用原长 l、间距 d 和伸长量 x0 表示乙所坐木板的位移","expr":"x_1=x_0+(l-d)","cues":["先伸到原长","还要多伸一段","位移是两段相加"],"concepts":["绳长变化","几何约束"]},{"title":"F 做功的功能关系","type":"关系建立","judge":"F 做的功转化为哪些能量和克服哪些阻力做功","why":"缓慢拉动，动能不变，F 的功等于弹性绳弹性势能增量与乙木板克服地面摩擦力做功之和","do":"写出总功表达式，代入弹性势能和摩擦力做功","expr":"W=E_0+\\mu mg x_1","cues":["缓慢动能不变","算弹性势能","加上摩擦生热"],"concepts":["功能关系","弹性势能","摩擦力做功"]},{"title":"弹性势能用伸长量表示","type":"数学处理","judge":"弹性势能公式中的 x 应取绳的伸长量而不是乙的位移","why":"题给 E=½kx² 中 x 是绳的伸长量，与乙的位移 x1 不是同一个量，混用会多算 l-d 那一段","do":"把 x0=μmg/k 代入弹性势能公式，再与摩擦力做功项合并","expr":"E_0=\\frac{1}{2}k\\left(\\frac{\\mu mg}{k}\\right)^2=\\frac{(\\mu mg)^2}{2k}","cues":["别把位移当伸长","伸长只有一段","分开算再相加"],"concepts":["弹性势能","伸长量"]}],"629":[{"title":"两波叠加的位移求法","type":"关系建立","judge":"P 点的实际位移要由两列波各自传到 P 的振动位移叠加得到，而不是只看其中一列","why":"两列波在同一介质中相遇，P 同时参与两个振动，依据波的叠加原理，合位移等于两列波单独引起位移的矢量和","do":"分别用波形平移法找出 t=0.5 s 时甲、乙两波在 P 处各自引起的位移，再代数相加","expr":"$y_P=y_{甲}+y_{乙}$","cues":["叠加原理","两列波各算各的","位移相加"],"concepts":["波的叠加原理","简谐横波"]},{"title":"波形平移定传播距离","type":"模型选择","judge":"判断某时刻 P 处对应的是哪一段波形，需用波形整体平移的方法，而不是让质点随波迁移","why":"机械波传播的是振动形式和能量，质点只在平衡位置附近振动，波形以波速整体平移","do":"由 Δx=vΔt 算出两波在给定时间内平移的距离，把原波形沿各自传播方向平移该距离，读出 P 处对应的波形点","expr":"$\\Delta x=v\\Delta t$","cues":["波形平移","质点不随波走","平移一段距离"],"concepts":["波的传播","波形平移法"]},{"title":"由波形斜率定振动方向","type":"几何关系","judge":"要判断 P 在 t=1.0 s 时的振动方向，需由传到 P 的波形在该点的倾斜方向（或波峰波谷位置）确定质点速度方向","why":"质点振动方向与波的传播方向、波形斜率之间有确定关系（同侧法/上下坡法），不能凭直觉","do":"把两波各平移 2 m 后，看 P 处波形是上坡还是下坡，分别定出两波引起 P 的速度方向，再合成","expr":"","cues":["看波形斜率","上坡下坡","同侧法"],"concepts":["质点振动方向","波传播方向"]},{"title":"两波速度方向的合成","type":"结论整理","judge":"P 的合运动方向要由两列波各自引起的速度方向叠加判断，而不是只看一列波","why":"P 同时参与两个简谐振动，合速度是两分振动速度的矢量和，两分速度同向则合速度同向","do":"比较 t=1.0 s 时甲、乙两波在 P 处引起的速度方向是否同向，同向则合速度沿该方向","expr":"$v_P=v_{甲}+v_{乙}$","cues":["速度也叠加","两列波都向上","合速度看合成"],"concepts":["速度合成","叠加原理"]}],"630":[{"title":"B点平衡的受力方向","type":"模型选择","judge":"在B点把库仑力沿斜面方向和垂直斜面方向分解，判断哪个分量与重力沿斜面的分量平衡","why":"B点加速度为零，合力为零；库仑力沿OB连线，而OB与斜面不垂直，必须分解到沿斜面方向才能与 mg sin30° 平衡，垂直方向由支持力平衡","do":"画B点受力图，把库仑力分解为沿斜面向下分量和垂直斜面分量，只对沿斜面方向列平衡方程","expr":"mg\\sin30^{\\circ}=\\frac{kq^{2}}{l^{2}}\\cos30^{\\circ}","cues":["沿斜面分解","库仑力不沿斜面","垂直方向有支持力"],"concepts":["库仑定律","力的分解","平衡条件"]},{"title":"B点到O的距离","type":"几何关系","judge":"判断B点到O的距离 l 与斜面几何量之间的关系，确定 l 就是库仑力表达式中的距离","why":"库仑定律中的距离是滑块与O点的实际间距，B点与O点等高，需由斜面倾角确定OB与斜面的夹角，才能正确写出库仑力沿斜面的分量","do":"由B与O等高、斜面倾角30°，确定OB与斜面的夹角为30°，从而库仑力沿斜面分量含 cos30°","expr":"l=\\sqrt{\\frac{\\sqrt{3}kq^{2}}{mg}}","cues":["等高","OB与斜面夹角","距离就是l"],"concepts":["几何关系","库仑定律"]},{"title":"A到C用动能定理","type":"关系建立","judge":"判断求静电力做功应取A到C整段过程用动能定理，而不是只看B点或分段","why":"A、C两点速度均为零，整段动能变化为零，只有重力和静电力做功，可直接求出静电力做的总功，避开中间变力过程的细节","do":"对A到C列动能定理，重力做功取 mg·s·sin30°，初末动能均为零","expr":"W+mg s\\sin30^{\\circ}=0","cues":["首末都静止","整段动能定理","变力不做功的细节不管"],"concepts":["动能定理","静电力做功"]},{"title":"电势差与功的关系","type":"关系建立","judge":"判断用电场力做功除以电荷量求AC电势差，并注意功的正负号","why":"电势差定义 U=W/q，W 为静电力做的功，已由动能定理求得为负值，符号直接决定电势差正负","do":"把上一步求得的 W 代入 U_AC=W/q，保留负号","expr":"U_{AC}=\\frac{W}{q}=-\\frac{mgs}{2q}","cues":["功除以电荷量","负功","符号别丢"],"concepts":["电势差","电场力做功"]}],"631":[{"title":"切割磁感线的有效速度","type":"模型选择","judge":"判断棒沿圆弧运动时哪一速度分量在切割竖直向下的磁场","why":"只有垂直于磁场且垂直于棒的速度分量才产生感应电动势，沿棒方向的分量不切割","do":"把棒的速度沿水平与竖直方向分解，取水平分量与磁场垂直","expr":"E=BLv_x","cues":["看水平速度","竖直分量不切割","速度要分解"],"concepts":["动生电动势","速度分解","有效切割长度"]},{"title":"感应电流方向判定","type":"关系建立","judge":"判断棒向右、向左运动时回路中电流的流向","why":"右手定则给出四指指向即感应电流方向，方向随速度反向而反向","do":"对向右、向左两种运动分别用右手定则定出 M→N 或 N→M","expr":"","cues":["右手定则","电流随速度反向","从M到N"],"concepts":["右手定则","感应电流方向"]},{"title":"安培力方向与做功","type":"关系建立","judge":"判断安培力沿运动方向还是逆运动方向，从而判断其做功正负","why":"楞次定律的阻碍效果要求安培力总是阻碍相对运动，故恒做负功","do":"用左手定则定安培力方向，与速度方向比较","expr":"W_安<0","cues":["阻碍运动","安培力做负功","左手定则"],"concepts":["左手定则","楞次定律","安培力做功"]},{"title":"机械能持续损耗","type":"结论整理","judge":"判断多次往返后棒最终停在哪里","why":"光滑导轨无摩擦，只有安培力做负功把机械能转化为焦耳热，能量单调减少","do":"由能量守恒看机械能单调下降，最终停在势能最低处","expr":"E_机↓→停在最低点","cues":["机械能一直减少","最终停在最低点","能量变焦耳热"],"concepts":["能量守恒","焦耳热","阻尼振动"]},{"title":"最低点前已开始减速","type":"临界条件","judge":"判断棒到达 OO′ 前速度是否已达最大、之后是否减速","why":"重力沿切向分力随位置减小，安培力随速度增大，二者相等时加速度为零，此后合力反向","do":"比较切向重力分力与安培力的大小变化，找合力为零的位置","expr":"mg sinθ=BIl","cues":["先加速后减速","合力为零处速度最大","到最低点前已减速"],"concepts":["切向分力","牛顿第二定律","临界平衡"]}],"632":[{"title":"选分解方向","type":"模型选择","judge":"沿哪两个互相垂直的方向分解初速度和重力加速度，才能让落点条件最简单","why":"P、Q 连线与水平成 30°，若沿 PQ 和垂直 PQ 分解，则垂直 PQ 方向的位移为零，可直接用对称性求时间；若沿水平竖直分解，则要联立两个方向的位移关系解时间","do":"把初速度分解为沿 PQ 的 v1 和垂直 PQ 的 v2，把重力加速度分解为沿 PQ 的 a1 和垂直 PQ 的 a2","expr":"v_1=v_0\\cos60^\\circ,\\quad v_2=v_0\\sin60^\\circ,\\quad a_1=g\\sin30^\\circ,\\quad a_2=g\\cos30^\\circ","cues":["沿连线分解","垂直连线方向","斜抛分解"],"concepts":["运动的分解","斜抛运动"]},{"title":"垂直连线方向定时间","type":"关系建立","judge":"垂直 PQ 方向的初速度与加速度方向相反、位移为零，能否用对称性直接得到总时间","why":"垂直 PQ 方向做匀变速直线运动，起点和终点都在 PQ 上，位移为零，上升与下落两段对称，故 t 等于速度由 v2 减到零再反向增到 v2 的两倍时间","do":"令垂直 PQ 方向位移为零，用对称性写出总时间 t=2v2/a2","expr":"t=2\\dfrac{v_2}{a_2}","cues":["垂直方向位移为零","上升下落对称","两倍上升时间"],"concepts":["匀变速直线运动","对称性"]},{"title":"最远距离取速度为零","type":"临界条件","judge":"离 PQ 连线最远的时刻对应垂直 PQ 方向速度为零，而不是总时间的一半或落地时刻","why":"垂直 PQ 方向速度为零时该方向位移达到极值，即重物到 PQ 连线的距离最大","do":"用 v2²=2a2·dmax 求最大距离","expr":"d_{\\max}=\\dfrac{v_2^2}{2a_2}","cues":["垂直速度为零","离连线最远","到极值点"],"concepts":["临界条件","匀变速直线运动"]},{"title":"落地速度用竖直分速度","type":"关系建立","judge":"求落地速度方向时，应把总时间代回竖直方向求落地竖直分速度，而不是用初速度的竖直分量","why":"落地速度方向由落地时竖直分速度与水平分速度之比决定，竖直分速度须由 vy=-v0sin30°+gt 重新计算","do":"先由总时间 t 求落地竖直分速度 vy，再与水平分速度 vx=v0cos30° 作比求夹角","expr":"v_y=-v_0\\sin30^\\circ+gt,\\quad \\tan\\theta=\\dfrac{v_y}{v_x}","cues":["落地竖直速度","水平速度不变","求速度夹角"],"concepts":["速度分解","平抛/斜抛落地速度"]},{"title":"最高点与落点高差","type":"关系建立","judge":"最高点到落点的高度差要用从最高点下落到落地的时间 t2 单独计算，而不是用总时间或总高度","why":"最高点竖直分速度为零，此后为自由落体，下落高度只由 t2=t-t1 决定，t1 为上升到最高点的时间","do":"先求上升到最高点时间 t1=v0sin30°/g，再求 t2=t-t1，最后用 h=½gt2² 求高差","expr":"t_1=\\dfrac{v_0\\sin30^\\circ}{g},\\quad t_2=t-t_1,\\quad h=\\dfrac12 g t_2^2","cues":["先求上升时间","最高点速度为零","分段算下落"],"concepts":["竖直上抛","自由落体"]}],"633":[{"title":"位移传感器测距含义","type":"模型选择","judge":"要判断 xA、xB 是滑块到各自传感器的距离，而不是滑块的位置坐标，因此图像斜率对应速度的符号要按各自方向理解","why":"传感器 a 测 A 到 a 的距离、b 测 B 到 b 的距离，两传感器分装导轨两端，同一运动方向在两图中斜率的正负含义相反","do":"明确两图纵轴都是到对应传感器的距离，把斜率绝对值当作速率，斜率的正负只表示靠近还是远离该传感器","expr":"v=\\left|\\dfrac{\\Delta x}{\\Delta t}\\right|","cues":["距离不是坐标","斜率取绝对值","靠近还是远离"],"concepts":["位移传感器","x-t 图像斜率"]},{"title":"碰撞时刻看斜率突变","type":"图像读取","judge":"要判断碰撞发生在哪一时刻，应找两滑块速度（即 x-t 图线斜率）同时发生突变的那个时刻，而不是两图线相交或距离相等的时刻","why":"碰撞瞬间两滑块速度发生突变，x-t 图线出现折点；图线相交只说明到各自传感器距离相等，与碰撞无必然关系","do":"在图乙、图丙上找折点，比较两图折点对应的横坐标，取共同时刻","expr":"","cues":["找折点","斜率突变处","不是交点"],"concepts":["碰撞","x-t 图像折点"]},{"title":"碰撞前取折点前一段","type":"图像读取","judge":"要判断求碰撞前 B 的速度应取折点之前那段图线，而不是碰撞后那段","why":"题目问的是碰撞前瞬间的速度，碰撞后斜率已改变，取错段会得到碰后速度","do":"在图丙上取碰撞时刻之前的一段直线，读出该段两端点的坐标求斜率绝对值","expr":"v_B=\\left|\\dfrac{\\Delta x_B}{\\Delta t}\\right|","cues":["取碰前那段","折点左边","别用碰后斜率"],"concepts":["碰撞前速度","图像斜率"]},{"title":"单位与有效数字换算","type":"数据处理","judge":"要判断图像纵轴单位是 cm、横轴是 s，算出的是 cm/s，需换算成 m/s 并按 2 位有效数字保留","why":"题目要求速度单位为 m/s 且保留 2 位有效数字，直接用 cm/s 作答或保留位数不对都会失分","do":"用 cm 除以 s 得 cm/s，再除以 100 化为 m/s，最后按 2 位有效数字书写","expr":"v\\,(\\mathrm{m/s})=\\dfrac{v\\,(\\mathrm{cm/s})}{100}","cues":["纵轴是厘米","换成米每秒","保留两位"],"concepts":["单位换算","有效数字"]},{"title":"用动量守恒反推质量","type":"关系建立","judge":"要判断哪个滑块是 200 g，必须由碰撞前后各滑块速度配合动量守恒式反解质量比，而不能凭速度大小或质量大小直接猜","why":"两滑块质量未知对应关系，只有动量守恒方程把碰前碰后速度与质量联系起来，才能定出质量归属","do":"从两图分别读出碰前 A、B 速度和碰后 A、B 速度，规定正方向后代入动量守恒式，解出质量比并与 200 g、400 g 比对","expr":"m_Av_A+m_Bv_B=m_Av_A'+m_Bv_B'","cues":["列动量守恒","先读四个速度","解质量比"],"concepts":["动量守恒定律","质量比"]},{"title":"速度方向定正负号","type":"前提判断","judge":"要判断代入动量守恒式时各速度的正负号，需先由两图斜率判断碰前碰后各滑块是靠近还是远离各自传感器，从而确定运动方向","why":"动量是矢量，两滑块运动方向及碰后是否反向直接决定方程中各项的符号，符号取错会导致质量比错误","do":"由两图折点前后斜率的正负判断各段运动方向，统一规定正方向后给四个速度赋值代入","expr":"m_Av_A+m_Bv_B=m_Av_A'+m_Bv_B'","cues":["先定正方向","看斜率正负","碰后是否反向"],"concepts":["动量矢量性","正方向规定"]}],"634":[{"title":"螺旋测微器读数","type":"实验操作","judge":"判断主尺整毫米刻度与可动刻度对齐格数，并确定是否估读","why":"螺旋测微器精度为 0.01 mm，读数需主尺读数加可动刻度乘以精度，末位要估读到 0.001 mm","do":"读主尺露出的整毫米数，再读可动刻度与基准线对齐的格数，两者相加","expr":"d=d_0+0.01\\times n","cues":["看主尺","数可动格","要估读一位"],"concepts":["螺旋测微器","估读","精度"]},{"title":"内外接法选择","type":"模型选择","judge":"由电压表示数变化更明显判断电流表分压显著，从而确定电流表内接还是外接","why":"试触法中哪一表示数变化明显，说明该表所在支路的分压或分流不可忽略，应把该表接到不产生此影响的位置","do":"比较掷 1、2 时电压表与电流表示数变化幅度，电压表变化大说明电流表分压大，应避免电流表与铅笔芯串联分压","expr":"","cues":["电压表变化大","电流表分压","用外接法"],"concepts":["伏安法","内接法","外接法","试触法"]},{"title":"I-U 图线取点求电阻","type":"图像读取","judge":"判断 I-U 图线是否为直线，并选取图线上便于读数的点计算斜率倒数","why":"铅笔芯为金属导体，温度变化不大时近似线性，电阻等于 U 与 I 的比值，取图线上明确经过的格点可减小读数误差","do":"在图丙直线上选一个坐标易读的点，读出对应的 U 和 I，用欧姆定律求比值","expr":"R_Y=\\frac{U}{I}","cues":["图线是直线","选格点","电压除以电流"],"concepts":["欧姆定律","I-U 图像","电阻"]},{"title":"电阻率比较的变量控制","type":"关系建立","judge":"判断比较电阻率时哪些量相同、哪些量不同，把电阻率表示为可测量量的函数","why":"电阻定律给出电阻率与电阻、横截面积、长度的关系，直径近似相等意味着横截面积相同，只需比较电阻与长度的比值","do":"由电阻定律写出电阻率表达式，代入两种型号的电阻和长度，比较 R/l 的大小","expr":"\\rho=\\frac{RS}{l}=\\frac{\\pi d^2 R}{4l}","cues":["直径相同","面积约掉","比电阻比长度"],"concepts":["电阻定律","电阻率","横截面积"]}],"635":[{"title":"折射界面与法线定位","type":"几何关系","judge":"判断EF边入射时法线方向，以及折射角α是折射光线与法线的夹角","why":"折射定律中的角都是与法线的夹角，若误把与EF边的夹角当折射角，角度关系全错","do":"在EF入射点作EF的垂线为法线，标出入射角θ与折射角α","expr":"","cues":["先画法线","角是跟法线量的","别拿边当法线"],"concepts":["折射定律","法线"]},{"title":"由垂直射出定折射角","type":"关系建立","judge":"判断折射光线垂直EG射出时，折射角α与∠FEG=30°之间的几何关系","why":"折射光线垂直EG，而EF与EG成30°角，法线又垂直EF，由平行线与垂线关系才能把α与30°挂钩","do":"利用EF⊥法线、折射光线⊥EG，比较两直线夹角得α=∠FEG","expr":"\\alpha=\\angle FEG=30^{\\circ}","cues":["垂直就转九十度","角跟着三十度走","把角搬到三角形里"],"concepts":["几何关系","折射角"]},{"title":"全反射临界角判据","type":"临界条件","judge":"判断光第一次到达圆弧面能否全反射，取决于入射角是否不小于临界角C","why":"光从玻璃射向空气（圆弧外侧）才可能全反射，临界条件是入射角≥C，且sinC=1/n","do":"写出临界角公式，算出sinC并与圆弧处入射角比较","expr":"\\sin C=\\frac{1}{n}=\\frac{2}{3}","cues":["从玻璃射向空气","入射角够大才全反射","先算临界角"],"concepts":["全反射","临界角"]},{"title":"圆弧入射角转成到O距离","type":"几何关系","judge":"判断圆弧面上入射角等于光线与半径（法线）的夹角，从而把临界入射角转化为光线到O点的垂直距离","why":"圆弧上任一点的法线沿半径方向，入射角就是光线与半径的夹角，临界时该角为C，对应光线到O的垂距为RsinC","do":"作过O到光线的垂线，用直角三角形把临界入射角C换成垂距l","expr":"l=R\\sin C","cues":["半径就是法线","入射角是跟半径的夹角","垂距等于半径乘正弦"],"concepts":["圆的法线","临界角","几何关系"]},{"title":"边界点投影到EF","type":"数学处理","judge":"判断临界光线在EF上的入射点P与E的距离，需把O到光线的垂距l投影到EF方向","why":"l是O到光线的垂距，而EF与EG成30°，需用R−l与cos30°的比值换算成EF上的长度","do":"在含E、O、P的直角三角形中，用(R−l)/cos30°求PE","expr":"x_{PE}=\\frac{R-R\\sin C}{\\cos30^{\\circ}}=\\frac{2\\sqrt{3}}{9}R","cues":["投影到EF上","除以余弦","用R减垂距"],"concepts":["几何投影","三角函数"]},{"title":"全反射区域方向判定","type":"结论整理","judge":"判断满足全反射的入射点是在P靠E一侧还是靠F一侧，从而定出区间端点","why":"入射点越靠近E，光线离O越远、圆弧处入射角越大，越容易全反射；P是临界点，故区间为0到PE","do":"比较P两侧入射点对应的圆弧入射角与C的大小，确定范围并写出含端点的不等式","expr":"0<x\\le\\frac{2\\sqrt{3}}{9}R","cues":["越靠E越容易全反射","P是分界点","范围从E算起"],"concepts":["全反射条件","区间判断"]}],"636":[{"title":"确定封闭气体初态","type":"前提判断","judge":"堵住孔 A 的瞬间，长柄内被封闭气体的压强和体积各取什么值","why":"堵孔前长柄经孔 A 与大气相通，且内外液面相平，故封闭瞬间气体压强等于大气压；此时长柄浸入液面部分长 x，液面以上被封闭的气柱长 H−x","do":"取堵孔瞬间为初态，写出初态压强与气柱长度，体积用 S₁ 乘气柱长度表示","expr":"p_1=p_0,\\quad V_1=(H-x)S_1","cues":["堵孔瞬间与大气相通","初压就是大气压","气柱长是H减x"],"concepts":["封闭气体","等温变化","大气压"]},{"title":"末态压强由液柱差定","type":"关系建立","judge":"提出液面后罐内满液时，长柄顶部封闭气体的压强由哪段液柱决定","why":"罐内液面比长柄内液面高 h，这段液柱产生的压强差使封闭气体压强低于大气压，故不能仍取 p₀","do":"对罐内液面与长柄内液面列压强平衡，用 p₀ 减去高为 h 的液柱压强","expr":"p_2+\\rho gh=p_0","cues":["罐内液面高出一截","要减去液柱压强","不能再用大气压"],"concepts":["压强平衡","液柱压强","连通器"]},{"title":"等温压缩求 x","type":"模型选择","judge":"从堵孔到提出液面，封闭气体经历什么过程、初末态体积如何对应","why":"题设缓慢提出且温度不变，封闭气体质量不变，故为等温过程；末态气柱占满整根长柄，长 H","do":"对封闭气体列玻意耳定律，初态体积用 (H−x)S₁、末态体积用 HS₁，与压强关系联立解 x","expr":"p_1(H-x)S_1=p_2HS_1","cues":["温度不变用玻意耳","气柱最后占满长柄","体积比就是长度比"],"concepts":["玻意耳定律","等温过程","理想气体"]},{"title":"选全部气体为对象","type":"模型选择","judge":"进入空气后，把新进空气与原有气体合并成一体研究，还是分开研究","why":"新进空气与罐内原有气体混合后压强、温度相同，合并后总物质的量守恒，只需一个状态方程即可，避免多设未知分压","do":"以进入的 p₀、V 空气与原有 p₂、HS₁ 气体之和为研究对象，对应末态为罐内半罐液体上方的全部气体","expr":"p_0V+p_2HS_1=p_3\\left(HS_1+\\frac{h}{2}S_2\\right)","cues":["把新进空气并进去","以全部气体为对象","总物质的量不变"],"concepts":["研究对象选取","气体混合","物质的量守恒"]},{"title":"末态压强与体积定准","type":"关系建立","judge":"稳定后半罐液体时，气体压强由剩余液柱高度决定，气体体积包含哪几部分","why":"罐内液面比长柄内液面高 h/2，故压强为 p₀ 减 h/2 液柱压强；气体占据长柄全长加上罐内上半部空间","do":"写出末态压强表达式与末态总体积表达式，再与气体总量方程联立","expr":"p_3+\\rho g\\frac{h}{2}=p_0,\\quad V_3=HS_1+\\frac{h}{2}S_2","cues":["只剩半罐液体","液柱高是h的一半","体积要加罐子上半部"],"concepts":["压强平衡","液柱压强","几何体积"]},{"title":"统一单位后求解","type":"数学处理","judge":"各面积、长度、压强单位不统一时，代入前如何换算才不会差数量级","why":"S₁、S₂ 给的是 cm²，H、h 给的是 cm，而 p₀、ρ、g 用国际单位，必须统一到 m、m²、Pa 才能与 V 的立方米结果匹配","do":"把 S₁、S₂ 换算成 m²，H、h 换算成 m，代入两式消去 p₃ 解出 V，并检查数量级","expr":"S_1=1.0\\times10^{-4}\\,\\mathrm{m^2},\\quad S_2=9.0\\times10^{-3}\\,\\mathrm{m^2}","cues":["面积换成平方米","长度换成米","先统一单位再算"],"concepts":["单位换算","数量级检验"]}],"637":[{"title":"Q点弹力方向判定","type":"前提判断","judge":"Q点轨道对小物块的弹力是向上还是向下","why":"Q点为半圆轨道最高点，弹力沿半径方向只能竖直；需由速度大小判断物块是压轨道还是被轨道拉/托，才能确定向心力方程中弹力与重力的加减关系","do":"比较物块在Q点所需向心力与重力的大小，判断弹力方向后写合力等于向心力的方程","expr":"mg+N=m\\frac{v^2}{R}","cues":["弹力向下","压着轨道","最高点受力","先看向心力"],"concepts":["向心力","竖直平面圆周运动","弹力方向"]},{"title":"整体加速与相对滑动分界","type":"临界条件","judge":"F较小时物块与轨道是否一起加速、F超过何值时发生相对滑动","why":"图乙中a-F图线斜率在F=4N处突变，说明此点由整体共同加速转为轨道与物块间达到最大静摩擦力而相对滑动","do":"以F=4N为分界，分别对整体和单独轨道列牛顿第二定律，与图线两段斜率、截距对应","expr":"F=(M+m)a\\ (F\\le 4\\,\\mathrm{N});\\quad F-\\mu mg=Ma\\ (F>4\\,\\mathrm{N})","cues":["先看有没有一起动","转折点在四牛","最大静摩擦","斜率变了"],"concepts":["整体法","牛顿第二定律","最大静摩擦力"]},{"title":"由图像斜率截距反求参数","type":"图像读取","judge":"图乙两段直线的斜率与截距分别对应哪个物理组合量","why":"a-F关系式a=F/(M+m)与a=F/M-μmg/M中的系数和常数项必须与图上读出的数值一一对应，才能解出M、m、μ","do":"读低段斜率得1/(M+m)，读高段斜率得1/M，读高段纵截距得-μmg/M，联立求解","expr":"k_1=\\frac{1}{M+m}=0.5,\\ k_2=\\frac{1}{M}=1,\\ b=-\\frac{\\mu mg}{M}=-2","cues":["斜率是谁的倒数","截距含摩擦","两段分别读","单位别丢"],"concepts":["图像斜率","图像截距","牛顿第二定律"]},{"title":"撤力后水平动量守恒","type":"模型选择","judge":"撤去F后，物块沿光滑半圆上升过程中系统水平方向动量是否守恒","why":"水平面光滑、撤去外力后系统水平方向合外力为零，故水平动量守恒；但竖直方向受重力与支持力不守恒，机械能才守恒","do":"对物块从P到Q的过程，分别列水平方向动量守恒式和系统机械能守恒式","expr":"Mv_1+mv_2=Mv_3+mv_4;\\quad \\tfrac12Mv_1^2+\\tfrac12mv_2^2=\\tfrac12Mv_3^2+\\tfrac12mv_4^2+2mgR","cues":["水平方向没外力","动量守恒","机械能也守恒","竖直方向不管"],"concepts":["动量守恒","机械能守恒","系统"]},{"title":"两段加速度与相对位移","type":"关系建立","judge":"物块在水平段运动时轨道与物块各自的加速度及相对位移如何算","why":"F=8N时二者已相对滑动，轨道加速度由图线取6m/s²，物块只受滑动摩擦力加速，水平段长度等于二者位移之差","do":"由a=μg求物块加速度，用运动学公式写出两物体位移，作差得L","expr":"a_2=\\mu g=2\\,\\mathrm{m/s^2};\\ L=\\tfrac12a_1t_0^2-\\tfrac12a_2t_0^2","cues":["相对位移","各自加速","位移作差","摩擦力带动"],"concepts":["相对运动","匀变速直线运动","滑动摩擦力"]}],"638":[{"title":"确定粒子入射方向","type":"几何关系","judge":"粒子从 y 轴进入磁场时速度沿 x 轴正方向，需判断轨迹圆心在入射点正上方还是正下方，从而定出半径与弦长的几何关系","why":"粒子无初速经水平加速电场后速度水平向右，进入磁场时洛伦兹力沿 y 方向，圆心必在过入射点且垂直于速度的直线上","do":"画出入射点、圆心与 K 点的位置关系，用挡板倾角 60° 和 K 为中点定出弦长与半径的几何关系","expr":"r=\\frac{L}{2}","cues":["速度水平向右","圆心在入射点正上方","先画轨迹图"],"concepts":["洛伦兹力","圆周运动圆心","几何关系"]},{"title":"最小速度对应最小半径","type":"临界条件","judge":"要判断“速度最小”等价于“轨迹半径最小”，并找出过 K 点且与挡板相切（或与边界相切）的临界轨迹","why":"由 r=mv/(qB) 知 v 与 r 成正比，半径最小时速度最小；过定点 K 的圆弧中半径最小者对应圆心到 K 的连线沿挡板方向","do":"比较过 K 点的各条可能圆弧，取半径最小的那条，用 NK 长度和 60° 角算出半径","expr":"r'=NK\\cos60^{\\circ}=\\frac{L}{4}","cues":["半径最小速度最小","过K点作相切圆","取最短的那条弦"],"concepts":["临界轨迹","轨迹半径","洛伦兹力提供向心力"]},{"title":"匀速直线运动条件","type":"前提判断","judge":"判断粒子穿出 K 后做匀速直线运动要求电场力与洛伦兹力等大反向，并据此定出电场方向","why":"匀速直线运动合力为零，粒子只受洛伦兹力和电场力，二者必须平衡","do":"先用左手定则定出 K 点处洛伦兹力方向，再反推电场力方向，由正电荷定电场方向，列平衡方程求 E","expr":"qv'B=Eq","cues":["合力为零","洛伦兹力与电场力平衡","先定洛伦兹力方向"],"concepts":["力平衡","左手定则","电场力"]},{"title":"穿出后运动分解","type":"模型选择","judge":"判断粒子穿出 K 后进入的是只有电场的区域还是仍有磁场的区域，从而决定用匀速圆周加匀速直线的配速法还是别的模型","why":"题设电场只存在于三角形 OMN 之外的第一象限，穿出后粒子同时受恒定电场与磁场，属正交场中的摆线运动","do":"把速度分解为沿 y 方向的匀速分量和垂直方向的圆周分量，用配速法写出两个分运动","expr":"v''_{y}=v''\\sin\\theta,\\quad v''_{x}=v''\\cos\\theta","cues":["穿出后还有磁场","用配速法","分解成匀速加圆周"],"concepts":["配速法","正交电磁场","运动的合成与分解"]},{"title":"离 y 轴最近的条件","type":"临界条件","judge":"判断“距离 y 轴最近”对应圆周分运动摆到最靠近 y 轴的那一点，即用 K 点横坐标减去圆周半径","why":"粒子沿 y 方向匀速漂移，横向位置由圆周分运动决定，横向最小值为圆心横坐标减半径","do":"先由几何关系求出穿出速度与 y 轴的夹角，再算圆周分速度对应的半径，用 K 点横坐标减该半径","expr":"d_{m}=\\frac{L}{4}-r_{y},\\quad r_{y}=\\frac{mv''_{x}}{qB}","cues":["横向最近点","K点横坐标减半径","先求夹角"],"concepts":["圆周分运动","极值位置","几何关系"]}],"639":[{"title":"读图取周期与峰值","type":"图像读取","judge":"从 u-t 图像上读出周期 T 和电压峰值 Um，而不是把某个时刻的瞬时值当成峰值","why":"正弦交流电的周期由相邻两个同相位点（如相邻峰值）的时间间隔决定，峰值是图像的最大值，二者是后续所有计算的输入","do":"在图上找相邻两个波峰（或波谷）的时间差得 T，读纵轴最大值得 Um","expr":"T=0.02\\,\\mathrm{s},\\quad U_m=10\\sqrt{2}\\,\\mathrm{V}","cues":["看相邻波峰","峰值不是有效值","横轴一格多少"],"concepts":["周期","峰值","正弦交流电"]},{"title":"峰值与有效值换算","type":"关系建立","judge":"判断何时用峰值、何时必须换成有效值：求电流峰值用 Um，求发热、耗能必须用有效值","why":"正弦交流电的有效值等于峰值除以根号二，功率和能量只能用有效值计算，混用会得到错误结果","do":"先用欧姆定律由 Um 求 Im，再除以根号二得有效值 I，用于能量计算","expr":"I_m=\\frac{U_m}{R},\\quad I=\\frac{I_m}{\\sqrt{2}}","cues":["先求峰值电流","耗能要用有效值","除以根号二"],"concepts":["有效值","欧姆定律","峰值与有效值关系"]},{"title":"频率由周期倒数得","type":"关系建立","judge":"判断频率与周期的关系是 f=1/T，而不是由角频率直接读成频率","why":"频率定义为每秒完成的周期数，与周期互为倒数；角频率 ω=2π/T 与频率差一个 2π 因子","do":"用 T=0.02 s 算 f，并与选项中给出的频率比较","expr":"f=\\frac{1}{T}=50\\,\\mathrm{Hz}","cues":["频率是周期倒数","别把角频率当频率","五十赫兹"],"concepts":["频率","周期"]},{"title":"写瞬时值表达式","type":"关系建立","judge":"判断表达式中的角频率应由 ω=2π/T 算出，初相位由 t=0 时电压为零且上升确定","why":"图像从零开始且向正方向增大，对应正弦函数而非余弦，角频率必须用 2π/T 换算","do":"由 T 算 ω，确认初相为零，写出 u=Um sin ωt 并与选项比对","expr":"u=U_m\\sin\\frac{2\\pi}{T}t=10\\sqrt{2}\\sin100\\pi t\\ (\\mathrm{V})","cues":["从零开始是正弦","角频率用二派除周期","初相为零"],"concepts":["角频率","初相位","瞬时值表达式"]},{"title":"能量用有效值算","type":"数学处理","judge":"判断 1 s 内消耗的电能应以有效值电流代入焦耳定律，而不是用峰值或瞬时值","why":"交流电在一个周期内的平均发热等效于有效值直流电的发热，这是有效值的定义","do":"把有效值 I 与 R、t=1 s 代入 W=I²Rt 计算","expr":"W=I^{2}Rt=0.2^{2}\\times50\\times1=2\\,\\mathrm{J}","cues":["用有效值代焦耳定律","一秒内耗能","平方乘电阻乘时间"],"concepts":["焦耳定律","有效值","电功"]}],"640":[{"title":"守恒律的选取","type":"前提判断","judge":"该核反应中应同时用哪两条守恒定律来定未知核","why":"核反应中电荷数（质子数）守恒与质量数守恒是确定未知核组成的基本依据，反应前后总电荷数和总质量数不变","do":"对反应式两端分别列出电荷数守恒式与质量数守恒式","expr":"y+95=119+0,\\quad 54+243=A+2","cues":["用两个守恒","电荷数守恒","质量数守恒"],"concepts":["电荷数守恒","质量数守恒","核反应方程"]},{"title":"确定 Y 的质子数","type":"关系建立","judge":"由电荷数守恒求出 Y 的质子数后，能否据此确定 Y 是哪种核","why":"反应物一侧只有 Y 和 Am 提供质子，生成物一侧 X 的质子数为 119，中子不带电，故 Y 的质子数由差值唯一确定","do":"用 119 减去 Am 的质子数 95，得到 Y 的质子数，再对照元素序数确定元素符号","expr":"y=119-95=24","cues":["先求质子数","119减95","查元素序数"],"concepts":["质子数","原子序数","元素符号"]},{"title":"确定 Y 的质量数","type":"关系建立","judge":"Y 的质量数能否由质子数直接推出，还是必须由质量数守恒式反解","why":"质子数只给出元素种类，不给出该同位素的质量数；Y 的质量数需由质量数守恒式与已知的 Am、中子质量数联立确定","do":"把已求出的 Y 质量数代入质量数守恒式，解出 X 的质量数 A","expr":"54+243=A+2\\ \\Rightarrow\\ A=295","cues":["再代质量数","54加243","减去两个中子"],"concepts":["质量数","同位素","核反应方程"]},{"title":"中子数的扣除","type":"数学处理","judge":"生成物一侧有 2 个中子，其质量数是否要从总质量数中扣除","why":"质量数守恒是对反应前后所有粒子质量数求和，2 个中子各贡献 1 个质量数，漏扣会使 A 偏大 2","do":"在质量数守恒式中把 2 个中子的质量数 2 计入生成物一侧再求解","expr":"A=54+243-2\\times1","cues":["别漏两个中子","中子质量数是1","生成物有两个中子"],"concepts":["质量数守恒","中子"]}],"641":[{"title":"读图取波长","type":"图像读取","judge":"从波形图上读出相邻同相点（或一个完整波形）的水平距离，确定波长","why":"波速已知，只有先得到波长才能求周期，这是整条主链的起点","do":"在图上找相邻两个波峰（或波谷）的横坐标之差，读出波长","expr":"\\lambda = 2\\,\\mathrm{m}","cues":["看相邻波峰","一个完整波形","横坐标差"],"concepts":["波长","波形图"]},{"title":"波速波长求周期","type":"关系建立","judge":"判断用哪个公式把波速、波长、周期联系起来","why":"波在一个周期内沿传播方向前进一个波长，故 v=λ/T","do":"由波速和波长算出周期","expr":"T=\\frac{\\lambda}{v}=2\\,\\mathrm{s}","cues":["一个周期走一个波长","先算周期","波速乘周期"],"concepts":["波速","周期"]},{"title":"时间与周期比对","type":"数学处理","judge":"判断 t=1 s 相当于多少个周期，从而确定质点振动状态的变化量","why":"质点做简谐运动，只有把时间折算成周期份数，才能判断它到达哪个位置","do":"用 t 除以周期，看是否为半周期的整数倍","expr":"\\frac{t}{T}=\\frac{1}{2}","cues":["半个周期","时间除以周期","正好一半"],"concepts":["简谐运动","周期"]},{"title":"半周期位移反向","type":"关系建立","judge":"判断经过半个周期后质点位移与初位移的大小、方向关系","why":"简谐运动中相隔半周期的两个状态位移等大反向，与质点初位置无关","do":"先读 t=0 时 x=1.5 m 处质点的位移，再取相反数得到 t=1 s 时的位移","expr":"y(t+T/2)=-y(t)","cues":["等大反向","位移取相反数","半个周期回到对称点"],"concepts":["简谐运动","位移"]},{"title":"传播方向定初位移","type":"前提判断","judge":"判断 x=1.5 m 处质点在 t=0 时是处于波峰、波谷还是平衡位置","why":"波沿 x 轴正方向传播，需由波形和传播方向确定该点此刻的振动方向与位置，才能给出初位移","do":"在图上定位 x=1.5 m，结合波向右传播判断该点此刻位于波峰（位移为正向最大）","expr":"y(0)=+0.1\\,\\mathrm{m}","cues":["波向右传","该点在波峰","先定初位置"],"concepts":["波的传播方向","质点振动"]}],"642":[{"title":"磁通量是否为零","type":"前提判断","judge":"图乙中磁场分界线恰好与线圈竖直边重合时，穿过线圈的磁通量是否为零","why":"磁通量是穿过线圈的磁感线净条数，左右两半磁场方向相反、面积相等，净磁通量为零，这是判断后续感应电动势与电流方向的前提","do":"看图乙中磁场分界线与线圈的相对位置，比较分界线两侧穿过线圈的磁场方向与面积","expr":"\\Phi=\\Phi_{\\text{左}}+\\Phi_{\\text{右}}=0","cues":["分界线正好在中间","两边方向相反","磁通量抵消"],"concepts":["磁通量","匀强磁场"]},{"title":"电动势由变化率决定","type":"关系建立","judge":"感应电动势大小取决于磁通量的变化快慢，还是取决于此刻磁通量的大小","why":"法拉第电磁感应定律给出电动势正比于磁通量的变化率，与瞬时磁通量大小无关，磁通量为零时电动势可以不为零","do":"把永磁铁相对线圈的振动速度与磁通量变化率挂钩，判断速度越大电动势越大","expr":"E=n\\dfrac{\\Delta\\Phi}{\\Delta t}","cues":["看变化快慢","不是看磁通量大小","振动越快电动势越大"],"concepts":["法拉第电磁感应定律","磁通量变化率"]},{"title":"分界线移动改变磁通量","type":"模型选择","judge":"永磁铁上下振动时，是线圈面积变化还是磁场分界线位置变化导致磁通量改变","why":"线圈固定不动，磁场分界线随永磁铁上下移动，分界线扫过线圈使两侧相反方向的磁场面积此消彼长，从而磁通量变化","do":"把分界线看作移动的边界，分析分界线上移或下移时线圈内左右两部分面积的变化","expr":"\\Delta\\Phi=B\\,\\Delta S_{\\text{净}}","cues":["线圈不动","分界线在移动","两侧面积此消彼长"],"concepts":["有效面积","磁通量变化"]},{"title":"楞次定律定电流方向","type":"关系建立","judge":"永磁铁相对线圈下降时，为阻碍磁通量变化，感应电流应取顺时针还是逆时针","why":"楞次定律要求感应电流的磁场阻碍原磁通量的变化，需先判断分界线移动使哪一侧磁场面积增大、净磁通量向哪个方向变化","do":"先定分界线下降时净磁通量方向的变化趋势，再用右手螺旋定则确定线圈中感应电流的环绕方向","expr":"","cues":["先看磁通量往哪变","阻碍变化","右手定则定方向"],"concepts":["楞次定律","右手螺旋定则"]}],"643":[{"title":"卡进端盖的临界伸长量","type":"临界条件","judge":"插销刚要卡进端盖时，弹簧的伸长量是多少","why":"端盖固定在管口处，插销能到达的最远位置就是管口，此时弹簧总长为 l，原长为 l/2，故伸长量恰为 l/2，这是速度上限对应的临界状态","do":"用管长 l 减去弹簧原长 l/2，得到临界伸长量，再代入胡克定律求弹力","expr":"\\Delta x=l-\\frac{l}{2}=\\frac{l}{2},\\quad F=k\\Delta x=\\frac{kl}{2}","cues":["到管口就卡住","伸长量是半个管长","弹簧拉到最长"],"concepts":["胡克定律","临界状态"]},{"title":"弹力充当向心力","type":"模型选择","judge":"插销做匀速圆周运动时，沿半径方向的合力由谁提供","why":"忽略摩擦，插销只受弹簧沿管方向的弹力，该力沿半径指向圆心，正好提供向心力","do":"对插销沿半径方向列牛顿第二定律，把弹力写成向心力形式","expr":"F=m\\omega^{2}l","cues":["只有弹簧的力","弹力指向圆心","用向心力公式"],"concepts":["向心力","牛顿第二定律"]},{"title":"绳速与角速度的关联","type":"关系建立","judge":"细绳被匀速拉动的速度 v 与卷轴角速度之间是什么关系","why":"绳绕在半径为 r 的卷轴上，绳被拉出的长度等于卷轴边缘转过的弧长，故绳速等于卷轴边缘的线速度","do":"用线速度与角速度的关系把 v 和 ω 联系起来，再与向心力式联立消去 ω","expr":"v=r\\omega","cues":["绳速就是边缘线速度","用v等于r乘角速度","先换成角速度"],"concepts":["线速度与角速度","圆周运动"]},{"title":"向心力半径取管长","type":"几何关系","judge":"插销做圆周运动的半径应取 l 还是取弹簧当前长度","why":"插销位于管口临界位置，其到转轴 O 的距离就是管长 l，半径取错会直接改变结果","do":"在向心力式中把半径写成 l，而不是原长或伸长量","expr":"r_{\\text{向}}=l","cues":["半径是整根管长","不是弹簧原长","插销在管口"],"concepts":["转动半径","圆周运动"]}],"644":[{"title":"两光折射角大小比较","type":"关系建立","judge":"同一入射角下，红光与绿光在 MN 面的折射角谁更小","why":"由折射定律 n=sinθ/sinα，入射角相同，n 越大折射角越小；题设 n红<n绿，故绿光折射角更小、偏折更厉害","do":"写出 n=sinθ/sinα，比较两光的 n 得出折射角大小关系","expr":"$n=\\frac{\\sin\\theta}{\\sin\\alpha}$","cues":["折射率大的偏折多","绿光弯得更狠","入射角一样"],"concepts":["折射定律","折射率"]},{"title":"折射光线落点判断","type":"几何关系","judge":"折射角较小的光在 NP 面上的入射点更靠近哪个端点","why":"折射角小意味着光线更向法线偏折，在矩形截面内传播路径更靠近入射侧，需由几何关系确定交点位置","do":"画出两光在介质中的直线路径，比较它们与 NP 面交点相对 P 点的远近","expr":"","cues":["画个图看看","谁离P近","偏折大的靠哪边"],"concepts":["光路几何","折射角"]},{"title":"临界角与折射率关系","type":"前提判断","judge":"红光与绿光在该介质中全反射临界角谁更大","why":"全反射临界角由 sinC=1/n 决定，n 越小临界角越大；n红<n绿 故红光临界角更大","do":"用 sinC=1/n 比较两光临界角大小","expr":"$\\sin C=\\frac{1}{n}$","cues":["折射率小临界角大","红光更难全反射","临界角看倒数"],"concepts":["全反射","临界角"]},{"title":"入射角随θ增大的变化","type":"关系建立","judge":"θ 增大时，光在 NP 面上的入射角如何变化，哪束光先达到临界角","why":"θ 增大使折射角增大，光线在 NP 面的入射角随之改变；需结合临界角大小判断哪束光先满足全反射消失条件","do":"分析 θ 增大时 NP 面上入射角的增减趋势，与各自临界角比较，判断先后","expr":"","cues":["θ变大折射角变大","谁先到临界角","交点往哪移"],"concepts":["全反射条件","入射角变化"]},{"title":"MN面能否全反射","type":"前提判断","judge":"光从空气射入介质时，在 MN 面是否可能发生全反射","why":"全反射只发生在光从光密介质射向光疏介质时；此处由空气到介质是光疏到光密，任何入射角都不会全反射","do":"判断界面两侧介质的光密光疏关系，对照全反射发生条件","expr":"","cues":["空气到玻璃不会全反射","光疏进光密","只有反过来才行"],"concepts":["全反射条件","光密光疏"]}],"645":[{"title":"沿电场线判电势高低","type":"前提判断","judge":"由电场线的指向判断 M、N 两点电势谁高谁低","why":"沿电场线方向电势逐渐降低，这是判断电势高低的基本依据，不看电场线指向就无法比较 M、N 电势","do":"在图中找出经过 M、N 的那条电场线，看箭头从哪端指向哪端，确定 M 与 N 的电势高低","expr":"\\varphi_M<\\varphi_N","cues":["顺着箭头电势降","看电场线方向"],"concepts":["电场线","电势"]},{"title":"负电荷电势能随电势变化","type":"关系建立","judge":"带负电的污泥絮体在电势高处电势能大还是在电势低处大","why":"电势能 E_p=qφ，电荷 q 为负时电势能随电势升高而减小，符号判断反了结论就全反","do":"把 q<0 代入 E_p=qφ，由已判定的 M、N 电势高低比较两点的电势能大小","expr":"E_p=q\\varphi,\\ q<0","cues":["负电荷反着来","电势高电势能反而小"],"concepts":["电势能","电荷符号"]},{"title":"由电势能变化定电场力做功","type":"关系建立","judge":"絮体从 M 移到 N 时电势能增大还是减小，从而电场力做正功还是负功","why":"电场力做功等于电势能减少量，只有先定出电势能变化方向才能判断做功正负","do":"比较 M、N 两点电势能大小，看从 M 到 N 电势能是升是降，据此定做功正负","expr":"W_{MN}=E_{pM}-E_{pN}","cues":["电势能降就做正功","看能量变化定做功"],"concepts":["电场力做功","电势能"]},{"title":"电场线疏密定场强大小","type":"图像读取","judge":"比较 N 点与 P 点所在处电场线的疏密，判断两点场强大小","why":"电场线越密处场强越大，场强大小只能由疏密判断，不能由电势高低或等势面位置推出","do":"在图中分别看 N 点和 P 点附近电场线的疏密程度，比较两点场强","expr":"","cues":["密的地方场强大","数电场线疏密"],"concepts":["电场强度","电场线疏密"]},{"title":"等势面上电势能相等","type":"关系建立","judge":"M 与 P 在同一等势面上时，絮体在这两点的电势能是否相等，再与 N 点比较","why":"同一等势面上电势相同，同一电荷电势能相同，可把 M 点的电势能搬到 P 点再与 N 点比较","do":"由 M、P 等势得 E_pM=E_pP，再结合 M、N 电势能大小关系排出 P、N 的电势能高低","expr":"\\varphi_M=\\varphi_P\\Rightarrow E_{pM}=E_{pP}","cues":["等势面上电势能一样","把M换成P再比"],"concepts":["等势面","电势能"]}],"646":[{"title":"求行星表面重力加速度","type":"前提判断","judge":"能否由行星与地球的质量、半径之比换算出该行星表面的重力加速度","why":"星球表面万有引力近似等于重力，g=GM/R²，g 与 M 成正比、与 R² 成反比，不能直接套用地球的 10","do":"写出 g=GM/R²，把 M行/M地=1/10、R行/R地=1/2 代入求 g'","expr":"g'=\\frac{GM}{R^2},\\quad g'=g\\cdot\\frac{M_行/M_地}{(R_行/R_地)^2}","cues":["先算重力加速度","质量半径都变了","不能直接用10"],"concepts":["万有引力","重力加速度"]},{"title":"第一宇宙速度的换算","type":"关系建立","judge":"第一宇宙速度随星球质量、半径如何变化，能否由地球的 7.9 km/s 换算","why":"第一宇宙速度由万有引力提供向心力得 v=√(GM/R)，与 √M 成正比、与 √R 成反比，不是与 g 同比例","do":"写出 v=√(GM/R)，代入质量比与半径比求 v行/v地，再乘地球第一宇宙速度","expr":"v=\\sqrt{\\frac{GM}{R}},\\quad \\frac{v_行}{v_地}=\\sqrt{\\frac{M_行/M_地}{R_行/R_地}}","cues":["第一宇宙速度怎么变","开根号换算","和地球比"],"concepts":["第一宇宙速度","万有引力提供向心力"]},{"title":"分离前绳中张力判断","type":"模型选择","judge":"分离前匀速下落时，探测器与背罩之间的绳中张力等于什么","why":"整体匀速下落说明合外力为零，忽略空气阻力，则伞与背罩的阻力、重力与绳张力相互平衡，绳张力只由探测器重力决定","do":"对探测器单独受力分析，由匀速条件得绳张力等于探测器所受重力","expr":"T=m_探 g'","cues":["匀速说明合力为零","取探测器单独看","张力等于重力"],"concepts":["平衡条件","整体法与隔离法"]},{"title":"分离后背罩加速度","type":"关系建立","judge":"分离瞬间背罩受到的合力是哪些力，加速度由谁决定","why":"分离后绳张力消失，背罩只受重力与降落伞的阻力，而阻力大小在瞬间不变，故合力大小等于原绳张力","do":"对背罩用牛顿第二定律，合力取原绳张力大小，除以背罩质量求加速度","expr":"a=\\frac{T}{m_背}=\\frac{m_探 g'}{m_背}","cues":["阻力瞬间不变","合力等于原来张力","背罩质量小加速度大"],"concepts":["牛顿第二定律","瞬时性问题"]},{"title":"重力瞬时功率计算","type":"关系建立","judge":"分离后瞬间重力对探测器做功的功率用哪个速度和哪个力计算","why":"功率 P=Fv 中 v 是瞬时速度、F 是沿速度方向的重力，分离瞬间速度仍为 60 m/s 未突变","do":"用 P=mg'v 代入探测器重力与分离瞬间速度求功率","expr":"P=m_探 g' v","cues":["用瞬时速度","速度还没变","重力乘速度"],"concepts":["瞬时功率","重力做功"]}],"647":[{"title":"斜坡上加速度是否相同","type":"前提判断","judge":"两滑块在光滑斜面上的加速度是否与质量、起始高度无关","why":"光滑斜面上滑块只受重力和支持力，沿斜面合力为 mg sinθ，加速度 a=g sinθ 与滑块质量、高度均无关","do":"对单个滑块沿斜面方向列牛顿第二定律，比较甲、乙的加速度","expr":"a=g\\sin\\theta","cues":["加速度一样","跟高度无关","都从静止下滑"],"concepts":["牛顿第二定律","光滑斜面"]},{"title":"同加速度下相对静止","type":"关系建立","judge":"两滑块同时由静止出发且加速度相同，它们之间的相对速度是否始终为零","why":"初速度相同、加速度相同，则任意时刻速度相同，相对速度恒为零，间距保持不变","do":"写出两者速度随时间的关系并相减，判断相对速度","expr":"v_{\\text{甲}}=v_{\\text{乙}}=at,\\quad v_{\\text{甲}}-v_{\\text{乙}}=0","cues":["速度一直相等","相对静止","间距不变"],"concepts":["相对速度","匀变速直线运动"]},{"title":"等质量弹性碰撞换速度","type":"模型选择","judge":"两相同滑块发生弹性碰撞后，速度如何交换","why":"质量相等的两物体发生弹性正碰，动量守恒与动能守恒联立可得碰后交换速度","do":"用动量守恒和动能守恒联立，解出碰后两滑块速度与碰前速度的关系","expr":"v_1'=v_2,\\quad v_2'=v_1","cues":["交换速度","质量相同","弹性碰撞"],"concepts":["弹性碰撞","动量守恒","动能守恒"]},{"title":"碰撞后等效为不碰轨迹","type":"模型选择","judge":"碰撞后甲的运动能否等效为乙不发生碰撞时的运动","why":"交换速度后，甲获得乙碰前的速度，此后两者在水平面上加速度同为 μg，运动轨迹与不碰撞时互换","do":"把碰后甲的运动与假设不碰撞时乙的运动对比，判断最终停止位置是否相同","expr":"a_{\\text{甲}}=a_{\\text{乙}}=\\mu g","cues":["等效替代","换速度后一样","看成不碰"],"concepts":["匀减速运动","等效法"]},{"title":"水平滑行距离与高度关系","type":"关系建立","judge":"最终停止位置到 O 点的距离由哪个量决定，是否与 μ 和 H 有关","why":"下滑过程机械能守恒给出碰前速度，水平面匀减速到停由动能定理给出滑行距离","do":"联立下滑的机械能守恒式与水平面动能定理式，消去速度求 x","expr":"mgH=\\frac12mv^2,\\quad v^2=2\\mu gx\\ \\Rightarrow\\ x=\\frac{H}{\\mu}","cues":["用动能定理","消去速度","距离看高度和摩擦"],"concepts":["机械能守恒","动能定理","摩擦力做功"]},{"title":"总时间是否只由高度定","type":"结论整理","judge":"乙从开始下滑到最终停止的总时间是否只取决于 H_乙 而与 μ 等无关","why":"总时间由斜面下滑时间、水平面追及时间和碰后减速时间三段叠加，各段均含 μ 或 H 的不同组合，不能化为只含 H 的单一关系","do":"分别写出三段时间的表达式并相加，检查是否只含 H_乙","expr":"t=t_1+t_2+t_3","cues":["时间分三段","跟摩擦也有关","不能只看高度"],"concepts":["匀变速运动时间","分段分析"]}],"648":[{"title":"垫高木板的实验目的","type":"前提判断","judge":"判断木板右端垫高是为了平衡摩擦力还是为了提供下滑分力","why":"本实验要求绳的拉力就是小车所受合外力，必须先用重力沿斜面的分力抵消摩擦阻力，否则牛顿第二定律的验证前提不成立","do":"把垫高目的与'使小车获得初速度''增大小车加速度'等干扰说法区分开，确认是让小车不挂砂桶时能匀速下滑","expr":"","cues":["平衡摩擦力","垫高抵消摩擦","不是给初速度"],"concepts":["平衡摩擦力","牛顿第二定律"]},{"title":"纸带加速度的逐差法","type":"数据处理","judge":"判断用逐差法分段求平均加速度，而不是用首尾两点或单段位移算","why":"匀变速直线运动中相邻相等时间间隔的位移差恒定，用全部六段数据分三组作差可减小偶然误差","do":"把六段位移按时间顺序分成前后两组，用后三段之和减前三段之和，再除以九倍时间间隔平方","expr":"a=\\frac{(s_4+s_5+s_6)-(s_1+s_2+s_3)}{9T^2}","cues":[],"concepts":[]},{"title":"计数点时间间隔的确定","type":"前提判断","judge":"判断相邻计数点间的时间间隔是0.02 s还是0.1 s","why":"每相邻两计数点间有四个点未画出，说明计数点间隔为五个打点周期，电源频率50 Hz对应周期0.02 s","do":"由频率算出打点周期，再乘5得到计数点间隔T，代入逐差法公式","expr":"T=5\\times\\frac{1}{f}=0.1\\,\\mathrm{s}","cues":[],"concepts":[]},{"title":"游标卡尺的读数规则","type":"实验操作","judge":"判断主尺读数取到哪一位、游标对齐格数如何乘精度再相加","why":"50分度游标卡尺精度为0.02 mm，读数以mm为单位时游标部分末位在百分位，换算成cm后应保留到千分位","do":"读主尺整毫米刻度，找出与主尺刻线对齐的游标格数乘以0.02 mm，相加后换算为cm","expr":"L=L_{\\text{主}}+n\\times0.02\\,\\mathrm{mm}","cues":[],"concepts":[]},{"title":"双缝干涉的光路调节顺序","type":"实验操作","judge":"判断先调节光源使光束沿遮光筒轴线照亮光屏，再装单缝双缝并调单缝角度","why":"遮光筒不可调节，只能靠调光源让光轴与筒轴共线；单缝与双缝平行且缝宽合适才能在目镜中形成干涉条纹","do":"打开电源调节光源位置与方向使光斑居中照亮屏，装好单缝双缝后缓慢转动单缝直到目镜中出现清晰的干涉条纹","expr":"","cues":["先调光源","再装单缝双缝","看到干涉条纹"],"concepts":["光的干涉","光路共轴调节"]}],"649":[{"title":"滑动变阻器接成分压","type":"模型选择","judge":"虚线框内滑动变阻器应接成分压式还是限流式","why":"检测电路要求两光敏电阻上的电压能从零开始连续可调，且控制单元要比较两电压大小，需要电压调节范围大","do":"把滑动变阻器全部电阻丝两端接电源，滑片与一端作为电压输出接检测电路，对照图甲判断连线方式","expr":"","cues":["分压接法","电压要从零调","三根线接变阻器"],"concepts":["分压电路","滑动变阻器"]},{"title":"滑片先置阻值最大","type":"实验操作","judge":"闭合开关前滑片应放在哪一端才能保证电路安全","why":"保护光敏电阻和电压表，避免闭合瞬间电压过大","do":"找出使输出给检测电路的电压最小的滑片位置，即图甲中变阻器的 b 端","expr":"","cues":["保护电路","先放到最大","滑到b端"],"concepts":["电路安全","分压电路"]},{"title":"电压表量程与读数","type":"数据处理","judge":"V1 应选 3 V 还是 15 V 量程，读数读到哪一位","why":"电源电动势仅 3 V，各支路电压不会超过 3 V，选大量程读数误差大且无法精确读数","do":"确认量程 3 V、最小分度 0.1 V，按估读到下一位读取图丙指针示数","expr":"","cues":["选小量程","估读一位","看3伏那排刻度"],"concepts":["电压表读数","量程选择"]},{"title":"由电压比推电阻大小","type":"关系建立","judge":"两光敏电阻串联，电压大的那个电阻是大还是小","why":"串联电流相同，由 U=IR 知电压与电阻成正比，电压大则电阻大","do":"比较 U1 与 U2，得出 RG1 与 RG2 的阻值大小关系，再结合题设光照强弱判断阻值与光照强度的关系","expr":"$U=IR,\\quad U_1>U_2\\Rightarrow R_{G1}>R_{G2}$","cues":["串联电流一样","电压大的电阻大","光越弱电阻越大"],"concepts":["串联电路","欧姆定律","光敏电阻特性"]},{"title":"由电压差判光照方向","type":"结论整理","judge":"U1<U2 说明哪侧光照更强，电池板该往哪个方向转","why":"光敏电阻光照越强阻值越小，串联时其分得电压越小；控制单元使电池板转向使两电压相等即正对光源","do":"由 U1<U2 判断 RG1 侧光照较强，确定电池板需向 RG1 一侧偏转的方向，并指出停止条件是两电压相等","expr":"$U_1<U_2\\Rightarrow R_{G1}<R_{G2}\\Rightarrow$ RG1 侧光照更强","cues":["哪边电压小哪边光强","转向光强那边","电压相等就停"],"concepts":["光敏电阻","自动跟踪","平衡条件"]}],"650":[{"title":"判断阀门是否打开","type":"前提判断","judge":"降温过程中 A、B 压强差是否达到 Δp，从而决定 B 是等容还是被充气","why":"阀门只在 pA−pB>Δp 时打开，若未打开则 B 气体体积不变、质量不变，才能用等容规律","do":"先假设阀门不打开，算出 B 的压强，再与 A 的压强作差和 Δp 比较","expr":"p_A-p_B\\le \\Delta p","cues":["先假设没打开","比一比压强差","阀门关着吗"],"concepts":["差压阀","等容变化","临界条件"]},{"title":"A 压强由活塞平衡定","type":"关系建立","judge":"A 内气体压强由轻质活塞受力平衡决定，与温度、体积变化无关","why":"活塞轻质且无摩擦、上方与大气相通，故 A 内压强恒等于大气压，A 做等压变化","do":"对活塞列力平衡，得 A 的压强等于 p0","expr":"p_A=p_0","cues":["活塞轻质","上方通大气","A是等压"],"concepts":["活塞受力平衡","等压变化"]},{"title":"B 取等容、A 取等压","type":"模型选择","judge":"对 B 选等容过程、对 A 选等压过程，分别用哪个气体定律","why":"B 体积不变且阀门未开，质量不变；A 压强恒定，两者各自满足不同的气体实验定律","do":"B 用 p/T 不变，A 用 V/T 不变，分别代入初末态","expr":"\\frac{p_{B1}}{T_1}=\\frac{p_{B2}}{T_2},\\quad \\frac{V_{A1}}{T_1}=\\frac{V_{A2}}{T_2}","cues":["B体积不变","A压强不变","各用各的定律"],"concepts":["查理定律","盖-吕萨克定律","理想气体"]},{"title":"倒砂后 A 的压强重算","type":"关系建立","judge":"倒入铁砂后 A 内压强不再等于 p0，需由活塞、铁砂整体受力平衡重新表示","why":"铁砂压在活塞上，活塞平衡方程多了 mg 一项，A 的压强随之升高","do":"对活塞与铁砂列力平衡，写出 pA 与 m 的关系","expr":"p_A'=p_0+\\frac{mg}{S}","cues":["活塞上多了铁砂","压强要加一项","整体受力平衡"],"concepts":["受力平衡","压强定义"]},{"title":"阀门恰好关闭定临界","type":"临界条件","judge":"B 压强回到 p0 且保持不变，说明阀门恰好关闭，此时压强差恰等于 Δp","why":"阀门在差值大于 Δp 时打开、小于等于 Δp 时关闭，压强保持不变意味着处于开闭临界","do":"令 pA′−pB′=Δp，与活塞平衡式联立解 m","expr":"p_A'-p_B'=\\Delta p,\\quad p_B'=p_0","cues":["恰好关闭","压强差等于Δp","保持不变就是临界"],"concepts":["临界状态","差压阀开闭条件"]}],"651":[{"title":"敏感球受力对象与斜面方向","type":"模型选择","judge":"敏感球受哪几个力、沿哪个方向分解，才能把未知支持力消掉","why":"球与车有共同加速度 a，水平方向是加速度方向；斜面对球的支持力垂直于斜面，沿斜面方向分解时支持力不出现在方程里","do":"隔离敏感球，画重力 mg、敏感臂压力 F_N（竖直向下）、斜面支持力 N，沿斜面方向列牛顿第二定律","expr":"(mg+F_N)\\sin\\theta = ma\\cos\\theta","cues":["隔离小球","沿斜面分解","支持力不用管"],"concepts":["隔离法","牛顿第二定律","正交分解"]},{"title":"压力方向竖直向下","type":"前提判断","judge":"敏感臂对球的压力 F_N 是竖直向下还是垂直斜面","why":"敏感臂处于水平状态，臂对球的压力垂直于臂即竖直向下，与重力同向，二者在沿斜面方向的分量才能相加","do":"由臂水平判断 F_N 方向竖直向下，与 mg 合并为竖直向下的合力再分解","expr":"","cues":["臂是水平的","压力竖直向下","和重力同向"],"concepts":["弹力方向","压力"]},{"title":"冲量取 F-t 图面积","type":"图像读取","judge":"F 的冲量该用图像哪块面积、时间区间取多长","why":"冲量是力对时间的积分，F-t 图线与 t 轴围成的面积即冲量；碰撞过程对应 F 从零升到峰值再降回零的整段","do":"读图得峰值 6600 N、总历时 0.1 s，按三角形面积算冲量，方向随 F 竖直向上","expr":"I_F=\\frac12\\times0.1\\times6600","cues":["求面积","三角形","看0.1秒那段"],"concepts":["冲量","F-t 图像面积"]},{"title":"碰撞中重力冲量不可略","type":"近似条件","judge":"用动量定理时能否忽略碰撞时间内重力的冲量","why":"碰撞历时 0.1 s，mg t = 30 N·s，与 F 的冲量 330 N·s 同数量级，不能像短时碰撞那样忽略","do":"动量定理中同时计入 I_F 与 mgt，取向上为正，注意初动量方向向下为负","expr":"I_F - Mgt = Mv - M(-v_0)","cues":["重力冲量要算","0.1秒不短","别漏mgt"],"concepts":["动量定理","冲量"]},{"title":"碰前速度由自由落体定","type":"关系建立","judge":"头锤接触气囊瞬间的速度由哪段运动决定、方向如何","why":"碰前只受重力做自由落体，下落高度 H 决定接触速度大小，方向竖直向下","do":"由 v_0=√(2gH) 求接触速度，代入动量定理时取负号","expr":"v_0=\\sqrt{2gH}","cues":["自由落体","先求落地速度","方向向下"],"concepts":["自由落体","运动学公式"]},{"title":"反弹速度反推上升高度","type":"结论整理","judge":"碰后头锤做竖直上抛，上升高度由碰后速度还是由冲量直接定","why":"碰后只受重力，机械能守恒或运动学公式给出 h=v²/(2g)，需先用动量定理求出碰后速度 v","do":"由动量定理解出 v，再代入 h=v²/(2g) 求最大高度","expr":"h=\\frac{v^{2}}{2g}","cues":["竖直上抛","用速度求高度","先求碰后速度"],"concepts":["竖直上抛","动量定理"]}],"652":[{"title":"由偏转方向定电性","type":"前提判断","judge":"粒子在右侧磁场中向上偏转（从下板右端进入后回到下板右端上方），要判断粒子所受洛伦兹力方向对应的电荷正负","why":"磁场垂直纸面向外、粒子水平向右进入，由左手定则，只有正电荷所受洛伦兹力才指向轨迹弯曲的一侧","do":"画出粒子在磁场中从下板右端进入、绕行后回到下板右端的圆弧轨迹，确定圆心在上方，用左手定则反推电性","expr":"","cues":["看偏转方向","左手定则","向上弯"],"concepts":["洛伦兹力","左手定则"]},{"title":"磁场时间定回旋周期","type":"关系建立","judge":"要判断粒子在磁场中运动的时间与回旋周期 T 的关系，从而把 t0 与 q、m、B 联系起来","why":"粒子在匀强磁场中做匀速圆周运动，周期 T=2πm/(qB) 只由 q、m、B 决定，与速度无关；题给在磁场中停留 t0 且轨迹为一段圆弧","do":"由进入和离开磁场的位置及速度方向确定圆心角，得出在磁场中时间与 T 的倍数关系，再与 T=2πm/(qB) 联立求 q","expr":"T=\\frac{2\\pi m}{qB},\\quad t_0=\\frac{T}{2}","cues":["周期与速度无关","转半圈","时间等于半个周期"],"concepts":["回旋周期","匀速圆周运动"]},{"title":"板间竖直分运动对称","type":"模型选择","judge":"要判断粒子在板间交变电场中竖直方向如何运动——是否出电场时竖直分速度为零、竖直位移如何累加","why":"粒子水平进入板间电场，水平方向匀速；竖直方向受交变电场力，电压每半个周期反向，加速度大小不变方向交替，故竖直速度先增后减，出电场时竖直分速度恰为零，竖直位移为两段对称加速位移之和","do":"把 t0 分成两个 0.5t0，分别写竖直方向的匀加速位移，再相加得总竖直偏移 y","expr":"y=2\\times\\frac{1}{2}\\cdot\\frac{qU_0}{Dm}\\left(\\frac{t_0}{2}\\right)^2","cues":["竖直先加速后减速","出电场竖直速度为零","两段对称"],"concepts":["交变电场","运动的独立性","匀变速直线运动"]},{"title":"板长与水平速度关联","type":"几何关系","judge":"要判断板长、板间距 D 与水平速度 v 之间的几何约束，把 D 和 v 联系起来","why":"粒子水平方向不受力做匀速运动，穿过板长用时 t0；题给板长为板间距的 π/3 倍，构成 D 与 v 的方程","do":"写出板长 L=πD/3 与 L=v·t0 的等式","expr":"\\frac{\\pi D}{3}=v t_0","cues":["水平匀速","板长等于速度乘时间","板长是间距的π/3"],"concepts":["匀速直线运动","几何约束"]},{"title":"磁场圆弧与板间偏移衔接","type":"几何关系","judge":"要判断粒子在磁场中圆弧的直径与板间竖直偏移 y 的几何关系（y 与半径 r 的倍数）","why":"粒子离开下板边缘进入磁场、又回到下板边缘，轨迹是一段圆弧，其弦长与板间偏移由进出位置决定；由轨迹对称性可得 y 与 r 的关系","do":"由进出磁场的位置和速度方向定圆心、求半径 r，写出 y 与 r 的关系式，并与 qvB=mv²/r 联立","expr":"qvB=m\\frac{v^2}{r},\\quad y=2r=\\frac{2mv}{qB}","cues":["圆弧弦长","半径由洛伦兹力提供","进出同一边缘"],"concepts":["洛伦兹力提供向心力","圆周运动几何关系"]},{"title":"全程电场力做功的筛选","type":"结论整理","judge":"要判断从 t=0 到最终碰板上板的全过程中，哪些阶段电场力做功、哪些阶段做功为零，从而只累加有效部分","why":"粒子在板间交变电场中一个完整周期内竖直速度回到零、竖直位移净效果对应电场力做功为零；在左侧恒定电场中往返一次位移为零、做功也为零；只有最初左侧加速段和最后碰板上板的半周期偏转段有净功","do":"分段列出各阶段电场力做功，剔除净功为零的阶段，把初段动能与末段竖直偏转的功相加","expr":"W=\\frac{1}{2}mv^2+qE\\cdot\\frac{D}{3},\\quad E=\\frac{U_0}{D}","cues":["往返做功为零","整周期净功为零","只算首尾两段"],"concepts":["功与路径","动能定理","交变电场"]}],"653":[{"title":"确定引力来源与对象","type":"模型选择","judge":"判断各处海水所受引力由谁提供、比较的是哪个物理量","why":"题设明确是月球对不同位置海水的引力，比较的是单位质量海水所受引力，即引力加速度","do":"锁定施力天体为月球，把比较对象统一为单位质量的海水","expr":"","cues":["只看月球引力","比单位质量受力"],"concepts":["万有引力","引力加速度"]},{"title":"用距离平方反比定大小","type":"关系建立","judge":"判断引力大小随海水到月球距离如何变化","why":"万有引力与距离的平方成反比，质量取单位质量后引力只由距离决定","do":"写出单位质量海水所受月球引力的表达式，明确其只与到月心距离有关","expr":"$\\frac{F}{m}=G\\frac{M}{r^{2}}$","cues":["距离越近引力越大","平方反比"],"concepts":["万有引力定律","平方反比关系"]},{"title":"比较三处到月心距离","type":"几何关系","judge":"判断 a、b、c 三处海水到月球中心的距离谁最小","why":"图中 a 位于地月连线上朝向月球的一侧，b、c 偏离连线，到月心距离依次增大","do":"在图上比较 a、b、c 到月心的连线长度，找出最短者","expr":"$r_a<r_b,\\ r_a<r_c$","cues":["a正对月球","bc偏到侧面"],"concepts":["地月连线","空间距离"]},{"title":"排除误用地球自转或潮汐力","type":"前提判断","judge":"判断能否用地球自转、离心效应或潮汐力差来解释各处引力大小","why":"题目问的是月球对海水的引力本身，不是引力的差（潮汐力），也不是地球自转的离心效果","do":"确认比较对象是月球引力大小，不引入自转离心项或引力差","expr":"","cues":["别算潮汐力差","与自转无关"],"concepts":["潮汐力","离心效应"]}],"654":[{"title":"判断摩擦类型","type":"模型选择","judge":"货箱沿木板下滑时，摩擦力是滑动摩擦还是静摩擦","why":"货箱相对木板滑动，接触面间发生相对滑动，因此是滑动摩擦，可用 f=μF_N 计算，与下滑速度大小、是否匀速无关","do":"确认货箱与木板之间有相对滑动，锁定滑动摩擦模型","expr":"f=\\mu F_N","cues":["在滑动","用滑动摩擦公式"],"concepts":["滑动摩擦力","相对滑动"]},{"title":"判断压力大小","type":"关系建立","judge":"三个货箱对木板的压力是否相同","why":"压力由货箱重力在垂直木板方向的分量决定，三个货箱完全相同、放在同一均匀木板上，倾角相同，故压力相同","do":"把重力沿垂直木板方向分解，比较三个货箱的垂直分量","expr":"F_N=mg\\cos\\theta","cues":["压力看垂直分量","三个箱子一样重"],"concepts":["力的分解","压力"]},{"title":"判断接触面粗糙程度","type":"前提判断","judge":"三个货箱与木板间的动摩擦因数是否相同","why":"题设说明货箱各表面材质和粗糙程度均相同、木板表面均匀，动摩擦因数由接触面材料决定，与接触面积、放置方式无关","do":"由题设条件确认三个接触面的 μ 相同","expr":"","cues":["材质相同","粗糙程度一样"],"concepts":["动摩擦因数","接触面性质"]},{"title":"排除接触面积干扰","type":"结论整理","judge":"货箱以不同侧面接触木板（接触面积不同）是否影响摩擦力大小","why":"滑动摩擦力公式中不含接触面积，面积变化不改变 μ 和 F_N，故不能据面积大小判断摩擦力大小","do":"比较三个货箱的接触面积差异，确认它不进入摩擦力表达式","expr":"f=\\mu F_N\\ (\\text{与 }S\\text{ 无关})","cues":["面积不影响","别被接触面大小骗了"],"concepts":["滑动摩擦力"]}],"655":[{"title":"识别运动性质","type":"模型选择","judge":"两石块从静止释放、只受重力，应判断为什么运动模型","why":"初速度为零且只受重力（忽略空气阻力），满足自由落体运动的条件，与质量无关","do":"确认 P1 与 P2 均做自由落体运动，不因质量不同而改变运动性质","expr":"","cues":["自由落体","只受重力","初速为零"],"concepts":["自由落体运动","重力"]},{"title":"质量是否影响下落","type":"前提判断","judge":"绑成 2 kg 整体后，下落快慢是否改变","why":"自由落体加速度恒为 g，与物体质量无关，质量只影响重力大小而不影响加速度","do":"比较 P1 与 P2 的加速度，确认二者均为 g","expr":"a=\\frac{mg}{m}=g","cues":["与质量无关","加速度都是g","重的不会更快"],"concepts":["重力加速度","惯性质量"]},{"title":"同高度同时刻比较","type":"关系建立","judge":"两石块从同一高度、同样从静止释放，第 1 s 末的速度由什么决定","why":"初速度相同、加速度相同、时间相同，则同一时刻的速度必相同","do":"对两者分别用速度公式，比较 t=1 s 时的速度","expr":"v=gt","cues":["时间相同","初速都为零","速度一样"],"concepts":["速度公式","匀变速直线运动"]},{"title":"代入时间求速度","type":"数学处理","judge":"取 g=10 m/s²、t=1 s 代入速度公式得数值","why":"题给 g 与时间均为确定值，直接代入即可得第 1 s 末速度","do":"计算 g×t 的数值，得到 v1 与 v2 的大小关系","expr":"v=10\\times1=10\\ \\mathrm{m/s}","cues":["代g和t","一秒末","算数值"],"concepts":["速度公式"]}],"656":[{"title":"α衰变核电荷质量变化","type":"前提判断","judge":"α衰变后子核的质量数和质子数各减少多少","why":"α粒子即氦核，含2个质子和2个中子，故质量数减4、质子数减2","do":"对锇-160写出α衰变方程，算出子核的A和Z","expr":"{}^{160}_{76}\\mathrm{Os}\\to{}^{156}_{74}\\mathrm{X}+{}^{4}_{2}\\mathrm{He}","cues":["α粒子是氦核","质量数减四","质子数减二"],"concepts":["α衰变","质量数","电荷数守恒"]},{"title":"β+衰变核电荷变化","type":"前提判断","judge":"β+衰变后子核的质量数和质子数如何变化","why":"正电子质量数近似为零、电荷数为+1，母核放出一个正电子后质子数减1而质量数不变","do":"对钨-156写出β+衰变方程，算出子核的A和Z","expr":"{}^{156}_{74}\\mathrm{W}\\to{}^{156}_{73}\\mathrm{Y}+{}^{0}_{+1}\\mathrm{e}","cues":["正电子带正电","质子数减一","质量数不变"],"concepts":["β+衰变","正电子","电荷数守恒"]},{"title":"比较两子核的A与Z","type":"结论整理","judge":"两个子核的质量数、质子数、中子数中哪一个相同","why":"衰变方程给出子核的A、Z后，中子数由A−Z得出，需逐量比较才能确定相同量","do":"列出两子核的A、Z，并算中子数A−Z，比较三者","expr":"A_1=156,\\ Z_1=74,\\ N_1=82;\\quad A_2=156,\\ Z_2=73,\\ N_2=83","cues":["质量数都是156","质子数差一","中子数差一"],"concepts":["质量数","质子数","中子数"]}],"657":[{"title":"判断粒子圆周运动方向","type":"前提判断","judge":"由粒子带正电、速度沿 x 轴正向、磁场垂直纸面向里，判断洛伦兹力指向哪一侧，从而确定轨迹圆心在速度方向的哪一侧","why":"洛伦兹力方向由左手定则决定，它指向圆心；方向判反则圆心位置和几何图形全错","do":"用左手定则对 O 点速度方向与磁场方向定出洛伦兹力方向，画出轨迹弯曲方向","expr":"\\vec F=q\\vec v\\times\\vec B","cues":["左手定则","力指向哪边","轨迹往哪弯"],"concepts":["洛伦兹力","左手定则"]},{"title":"洛伦兹力提供向心力","type":"关系建立","judge":"判断粒子在匀强磁场中做匀速圆周运动，且向心力只由洛伦兹力提供（不计重力）","why":"只有洛伦兹力充当向心力，才能把半径与 v、B、q、m 联系起来","do":"列出向心力方程，解出半径表达式","expr":"qvB=m\\frac{v^{2}}{r}\\Rightarrow r=\\frac{mv}{qB}","cues":["洛伦兹力当向心力","匀速圆周","求半径"],"concepts":["向心力","匀速圆周运动"]},{"title":"确定圆心与P点位置","type":"几何关系","judge":"判断圆心在 O 点速度的垂线上，且 P 点速度方向与 y 轴正向成 45° 意味着半径 OP 与某条坐标轴成 45°","why":"速度方向与半径垂直，P 点速度方向已知即可反推半径方向，从而定出圆心和 P 的坐标关系","do":"过 O 作速度垂线定圆心，过 P 作速度垂线，利用速度与 y 轴夹角 45° 得到半径与坐标轴夹角 45°","expr":"","cues":["速度垂直半径","圆心在垂线上","夹角四十五度"],"concepts":["半径与速度垂直","几何作图"]},{"title":"用几何关系求PO距离","type":"几何关系","judge":"判断 PO 距离应由圆心到 O、圆心到 P 两段半径与 45° 角构成的几何图形求出，而不是直接取直径或弧长","why":"P 与 O 不在同一直径两端，PO 是弦长类距离，必须由圆心位置和角度合成","do":"把 PO 分解为沿半径方向与垂直半径方向的两段，用 45° 的余弦关系合成","expr":"L_{PO}=r+\\frac{r}{\\cos45^{\\circ}}=(1+\\sqrt2)\\frac{mv}{qB}","cues":["不是直径","弦长","分解成两段"],"concepts":["几何合成","弦长"]}],"658":[{"title":"电压表测的是哪段","type":"模型选择","judge":"判断理想电压表并联在滑片与哪一端之间的导体上，即 U 对应的是 x 段还是剩余段的电阻","why":"电压表读数反映的是它并联部分的电压，只有明确 U 与哪段导体长度对应，才能把 U-x 图线的斜率与电阻率挂钩","do":"看电路图(a)中电压表的两个接点，确定它跨接在 M 端到滑片 P 之间的导体上","expr":"","cues":["看电压表接哪","跨在滑片和端点","测的是接入段"],"concepts":["理想电压表","并联","部分电路欧姆定律"]},{"title":"U-x 斜率对应电阻率","type":"关系建立","judge":"判断 U-x 图线的斜率 ΔU/Δx 与电阻率 ρ 的定量关系","why":"由 R=ρL/S 与 U=IR 得 U=(Iρ/S)x，斜率正比于 ρ，这是把图线斜率转成电阻率的唯一桥梁","do":"对 U=(Iρ/S)x 求斜率，写出 ρ=(S/I)·(ΔU/Δx)，并注意两段导体电流 I、横截面积 S 相同","expr":"U=\\frac{I\\rho}{S}x,\\quad \\rho=\\frac{S}{I}\\cdot\\frac{\\Delta U}{\\Delta x}","cues":["斜率正比电阻率","电流面积相同","先写电阻定律"],"concepts":["电阻定律","欧姆定律","斜率"]},{"title":"图线分段找拐点","type":"图像读取","judge":"判断图(b)中哪一段折线对应 L1、哪一段对应 L2，以及拐点对应的 x 值","why":"两段材料不同，电阻率不同，U-x 图线必然出现斜率突变，拐点位置就是两种导体的分界","do":"读出折线在 x=0.25 m 处斜率改变，前段 U 从 0 升到 0.2 V，后段从 0.2 V 升到 0.5 V 直到 x=1.00 m","expr":"","cues":["找折点","斜率变了","分界在0.25米"],"concepts":["图像分段","斜率突变","分界面"]},{"title":"两段长度各取多少","type":"几何关系","judge":"判断 L1、L2 各自的长度是 0.25 m 与 0.75 m，而不是总长或滑片坐标本身","why":"电阻率公式中的 L 是该段导体自身长度，必须用拐点坐标差来算，直接用 x 会算错","do":"用拐点 x=0.25 m 把总长 1.00 m 分成 0.25 m 和 0.75 m 两段","expr":"L_1=0.25\\,\\mathrm{m},\\quad L_2=0.75\\,\\mathrm{m}","cues":["前段0.25米","后段0.75米","用长度差"],"concepts":["长度分割","坐标差"]},{"title":"斜率比即电阻率比","type":"数学处理","judge":"判断两段斜率之比等于两段电阻率之比，无需知道 I 和 S 的具体值","why":"ρ=(S/I)·斜率中 S/I 对两段相同，作比时约去，只剩斜率比","do":"分别算两段斜率 0.2/0.25 与 (0.5−0.2)/0.75，再作比","expr":"\\frac{\\rho_1}{\\rho_2}=\\frac{0.2/0.25}{(0.5-0.2)/0.75}","cues":["面积电流约掉","只比斜率","直接作比"],"concepts":["比值消元","斜率比"]}],"659":[{"title":"电势能叠加模型","type":"模型选择","judge":"判断环在任意位置的电势能应由两个固定负电荷的电势能之和给出，而不是只算近处那个电荷","why":"环带负电，处在两个负点电荷的叠加电场中，电势能是各电荷单独作用时的代数和","do":"对弧上任意点 P，分别写出 M、N 两电荷到 P 的距离，再叠加两项电势能","expr":"E_p=\\frac{k(27Q)q}{r_M}+\\frac{k(64Q)q}{r_N}","cues":["两个电荷都要算","电势能叠加","别只看近的那个"],"concepts":["电势叠加","电势能","点电荷电势"]},{"title":"用直径角表示距离","type":"几何关系","judge":"判断如何把 M、N 到 P 的距离用同一个角 α 表示，并确定 α 的取值范围","why":"P 在半圆弧上，直径 MN 所对圆周角为直角，故两距离可由 α 的正弦、余弦统一表达","do":"设 PM 与 MN 夹角为 α，利用直角三角形 PMN 写出 r_M、r_N，并由 P1、P2 位置定出 α 的区间","expr":"r_M=2R\\sin\\alpha,\\quad r_N=2R\\cos\\alpha,\\quad 37^\\circ\\le\\alpha\\le53^\\circ","cues":["直径所对是直角","用一个角表示两边","先定角度范围"],"concepts":["圆周角定理","几何约束"]},{"title":"判断电势能单调性","type":"数学处理","judge":"判断在 α 从 37° 增到 53° 的过程中，叠加后的电势能是单调增还是单调减","why":"电场力做功的符号由电势能变化决定，必须比较区间两端及中间的电势能大小，不能凭感觉","do":"把两项写成 α 的函数，在给定区间内比较 α=37°、45°、53° 等点的值，判断单调性","expr":"E_p(\\alpha)=\\frac{kQq}{2R}\\left(\\frac{27}{\\cos\\alpha}+\\frac{64}{\\sin\\alpha}\\right)","cues":["看两端谁大谁小","取中间点验证","单调性决定做功正负"],"concepts":["函数单调性","电势能变化"]},{"title":"由电势能变化定做功","type":"结论整理","judge":"判断电场力做正功还是负功，以及动能、速度如何随之变化","why":"只有电场力做功（重力和支持力不做功或不做净功），电场力做功等于电势能的减少量","do":"由电势能减小推出电场力做正功，再由动能定理判断动能、速度的增减","expr":"W_{\\text{电}}=-\\Delta E_p>0","cues":["电势能减小做正功","动能增加","速度变大"],"concepts":["电场力做功","动能定理","能量守恒"]}],"660":[{"title":"碰撞性质判定","type":"前提判断","judge":"两球正碰且总机械能守恒，能否判定为弹性碰撞","why":"机械能守恒是弹性碰撞的定义特征，只有先认定弹性碰撞才能用动量与动能同时守恒求解","do":"由题给'碰撞过程中总机械能守恒'直接认定碰撞为弹性碰撞","expr":"","cues":["机械能守恒","弹性碰撞","正碰"],"concepts":["弹性碰撞","机械能守恒"]},{"title":"等质量交换速度","type":"关系建立","judge":"两球质量相等时弹性正碰后各自速度如何分配","why":"等质量弹性正碰联立动量守恒与动能守恒可得两球交换速度，这是后续所有运动描述的出发点","do":"联立动量守恒与动能守恒，取等质量条件解出碰后 M、N 的速度","expr":"$m v = m v_M + m v_N,\\ \\tfrac12 m v^2=\\tfrac12 m v_M^2+\\tfrac12 m v_N^2 \\Rightarrow v_M=0,\\ v_N=v$","cues":["交换速度","质量相同","一个停下"],"concepts":["动量守恒","弹性碰撞","等质量交换速度"]},{"title":"碰后运动模型识别","type":"模型选择","judge":"N 离开平台边缘后受什么力、做什么运动","why":"N 碰后具有水平初速度且只受重力，水平方向无外力、竖直方向初速为零，故为平抛运动","do":"把 N 碰后的运动分解为水平匀速直线运动和竖直自由落体运动","expr":"$x=vt,\\ y=\\tfrac12 g t^2$","cues":["平抛运动","水平匀速","竖直自由落体"],"concepts":["平抛运动","运动的分解"]},{"title":"投影速度的对应","type":"几何关系","judge":"地面上的投影速度对应哪个分速度，墙面上的投影速度对应哪个分速度","why":"地面投影只反映水平位移的变化率，墙面投影只反映竖直位移的变化率，投影方向与分运动方向一一对应","do":"把水平分速度对应到地面投影、竖直分速度对应到墙面投影，再判断各自随时间的变化规律","expr":"$v_{地}=v_x=v,\\quad v_{墙}=v_y=gt$","cues":["地面看水平","墙面看竖直","投影对应分运动"],"concepts":["分运动的独立性","速度投影"]}],"661":[{"title":"双缝间距的确定","type":"几何关系","judge":"判断两个相干光源（S 与其平面镜虚像）之间的距离 d 等于多少","why":"平面镜成像具有对称性，虚像到镜面的距离等于物到镜面的距离，因此 S 与虚像的间距是 S 到镜面距离的两倍，而不是 a 本身","do":"由 S 到镜面距离 a，利用物像关于镜面对称，写出 d=2a","expr":"d=2a","cues":["虚像对称","距离是两倍","不是a"],"concepts":["平面镜成像","对称性","相干光源"]},{"title":"条纹间距公式的套用","type":"关系建立","judge":"判断该装置属于哪类干涉模型、条纹间距该用哪个公式、公式中 l 与 d 分别对应什么","why":"平面镜反射光与直射光叠加等效于杨氏双缝干涉，条纹间距由 Δx=(l/d)λ 决定，其中 l 是光源到屏的距离、d 是两相干源间距","do":"把 d=2a 代入 Δx=(l/d)λ，得到 Δx=(l/2a)λ","expr":"\\Delta x=\\frac{l}{d}\\lambda=\\frac{l}{2a}\\lambda","cues":["等效双缝","用双缝公式","l比d"],"concepts":["杨氏双缝干涉","条纹间距"]},{"title":"介质中波长与频率","type":"前提判断","judge":"判断装置浸入折射率为 n 的溶液后，光的频率和波长各自是否改变","why":"光从真空进入介质时频率由光源决定保持不变，传播速度变为 c/n，由 v=λf 可知波长变为原来的 1/n","do":"写出 v=c/n 与 λ'=λ/n，明确频率不变、波长变短","expr":"\\lambda'=\\frac{\\lambda}{n}","cues":["频率不变","波长变短","速度变小"],"concepts":["折射率","光速与波长频率关系"]},{"title":"由条纹间距反推折射率","type":"数学处理","judge":"判断如何用测得的条纹间距 Δx 反解出溶液折射率 n","why":"介质中条纹间距公式中的波长应换成介质中波长 λ/n，把 Δx=(l/2a)(λ/n) 与已知真空波长联立才能解出 n","do":"由 Δx=(l/2a)(λ/n) 解出 n=λl/(2aΔx)","expr":"n=\\frac{\\lambda l}{2a\\Delta x}","cues":["换成介质波长","联立两式","反解n"],"concepts":["条纹间距公式","折射率"]}],"662":[{"title":"撞击瞬间的动量来源","type":"前提判断","judge":"撞击极短，是否可忽略重力的冲量而只用冲量 I 求木栓初速度","why":"锤击时间极短，重力冲量远小于 I，动量定理退化为 I=mv；若把重力冲量也算进去，初速度就求不出来","do":"对木栓在撞击瞬间用动量定理，取竖直向下为正，只保留锤子的冲量","expr":"I=mv_0","cues":["时间极短","忽略重力冲量","只看锤子冲量"],"concepts":["冲量","动量定理","极短时间近似"]},{"title":"全过程的冲量归属","type":"关系建立","judge":"从撞击到停止的整段过程中，合外力冲量是否为零、木料对木栓的冲量是否等于 -I","why":"整段过程初末动量都为零，合冲量为零，故木料冲量应等于 -(I+mg t)，不等于 -I；漏掉重力的持续冲量就会误判","do":"对撞击到静止的全过程列动量定理，把重力冲量 mgt 与锤子冲量 I 一起计入","expr":"I+mgt+I_木料=0","cues":["全过程动量变化为零","重力一直在冲","木料冲量不是负I"],"concepts":["动量定理","合冲量","重力冲量"]},{"title":"用动能定理求平均阻力","type":"关系建立","judge":"进入过程中重力做正功、侧壁摩擦做负功，能否用平均阻力乘位移代替摩擦力的功","why":"摩擦力随弹力线性变化，其功等于平均摩擦力乘位移；只有把重力功与阻力功一起写进动能定理，才能解出平均阻力","do":"对进入 Δx 的过程列动能定理，初动能用 I²/2m，末动能为零","expr":"(mg-\\bar f)\\Delta x=0-\\frac{I^{2}}{2m}","cues":["用平均力算功","初动能由冲量算","末动能为零"],"concepts":["动能定理","平均力"]},{"title":"能量去向的分配","type":"结论整理","judge":"损失的机械能是全部转化为内能，还是有一部分储存为侧壁弹性势能","why":"侧壁发生弹性形变且弹力线性变化，形变能可回收，故内能 Q 小于总机械能损失；把损失全算成内能就会得出错误等式","do":"比较总机械能损失 I²/2m+mgΔx 与摩擦生热 Q 的大小关系","expr":"\\frac{I^{2}}{2m}+mg\\Delta x>Q","cues":["弹性形变储存能量","损失不全变热","内能小于损失"],"concepts":["能量守恒","弹性势能","摩擦生热"]},{"title":"单侧壁受力的分解","type":"几何关系","judge":"四个侧壁均分总阻力，每个侧壁的弹力与摩擦力如何沿竖直方向合成","why":"木栓受四个完全相同的侧面作用，竖直方向总阻力应为单侧的 4 倍；侧面与上底面夹角 θ 决定弹力、摩擦力的竖直分量","do":"取一个侧面，把弹力与摩擦力沿竖直方向分解，再乘 4 与平均总阻力相等","expr":"4\\cdot\\frac{1}{2}(f\\sin\\theta+F_N\\cos\\theta)=\\bar f","cues":["四个侧面平分","沿竖直方向分解","弹力摩擦都出分量"],"concepts":["受力分析","正交分解","对称性"]},{"title":"线性弹力的平均值","type":"近似条件","judge":"弹力随位移线性增大时，单侧竖直分力的平均值是否等于最大值的一半","why":"弹力从零线性增至最大，其平均值取最大值的一半；不取这个平均就无法把最大弹力与平均阻力联系起来","do":"对线性变化的弹力取平均，再结合 f=μF_N 把平均阻力写成最大弹力的表达式","expr":"\\bar F_N=\\frac{F_{N\\max}}{2},\\quad f=\\mu F_N","cues":["线性变化取一半","从零开始增大","平均等于最大的一半"],"concepts":["线性变化","平均值","滑动摩擦力"]}],"663":[{"title":"悬挂方式保摆长","type":"实验操作","judge":"判断两种悬挂方式中哪一种能保证摆动过程中摆长不发生变化","why":"单摆周期公式中的摆长是悬点到球心的距离，若悬点可动或线在钉上滑动，摆动时摆长改变，周期公式失效","do":"比较图(a)固定悬点与图(b)绕钉摆动的差异，看哪种方式摆线长度与悬点位置在摆动中保持不变","expr":"","cues":["看悬点是否固定","线会不会滑动","摆长要不变"],"concepts":["摆长","单摆周期公式","悬点"]},{"title":"摆长量到球心","type":"模型选择","judge":"判断公式中的摆长应取悬点到球心的距离，而不是悬点到球面顶端的线长","why":"单摆模型把摆球视为质点，等效摆长是悬点到球心的距离，需在测得的线长上加上半径","do":"明确摆长等于线长加摆球半径，为后续用直径求半径做准备","expr":"L=l+\\frac{d}{2}","cues":["摆长到球心","要加半径","不是线长"],"concepts":["等效摆长","质点模型"]},{"title":"游标卡尺读数规则","type":"数据处理","judge":"判断该游标卡尺的精确度，并确定主尺读数与游标对齐格数如何组合","why":"游标卡尺读数等于主尺整毫米数加游标对齐格数乘精确度，精确度由游标总格数决定","do":"读主尺上越过游标零刻线的整毫米数，再找游标上与主尺刻线对齐的格数，相乘后相加","expr":"d=d_{\\text{主}}+n\\times\\text{精确度}","cues":["先看精确度","找对齐的格","主尺加游标"],"concepts":["游标卡尺","精确度","读数"]},{"title":"小角近似判简谐","type":"近似条件","judge":"判断摆角为 5° 时单摆振动能否按简谐运动处理","why":"只有摆角很小时正弦值近似等于弧度值，回复力才与位移成正比，振动才是简谐运动","do":"确认 5° 属于小角范围，从而可用简谐运动规律及周期公式描述该振动","expr":"\\sin\\theta\\approx\\theta","cues":["角度很小","可以当简谐","正弦约等于角"],"concepts":["简谐运动","小角近似","回复力"]},{"title":"振幅用弧长还是弦长","type":"几何关系","judge":"判断释放点偏离平衡位置的振幅应取圆弧弧长还是对应的弦长","why":"简谐运动中位移沿圆弧量度，振幅是平衡位置到最大位移处的弧长，小角下弧长与弦长近似相等","do":"由摆长与释放角求振幅，取弧长近似值","expr":"A=L\\sin5^{\\circ}\\approx L\\cdot\\frac{5\\pi}{180}","cues":["振幅是弧长","小角下差不多","用摆长乘角度"],"concepts":["振幅","弧长","小角近似"]},{"title":"初相由释放位置定","type":"关系建立","judge":"判断从最大位移处释放时振动方程应取余弦形式、初相为零","why":"t=0 时摆球在最大位移处、速度为零，余弦函数在零时刻取最大值，符合该初始条件","do":"写出位移随时间变化的余弦表达式，角频率由周期确定","expr":"x=A\\cos\\left(\\frac{2\\pi}{T}t\\right)","cues":["从最大位移释放","用余弦不用正弦","初相取零"],"concepts":["初相","振动方程","角频率"]}],"664":[{"title":"采样周期与频率关系","type":"前提判断","judge":"采样周期与采样频率是倒数关系还是乘积关系","why":"采样频率定义为单位时间内采样次数，周期是相邻两次采样的时间间隔","do":"用频率的倒数求周期","expr":"T=\\frac{1}{f}","cues":["频率倒过来","五千分之一"],"concepts":["采样频率","周期"]},{"title":"充电瞬间电流的读取","type":"图像读取","judge":"读 I-t 图哪一时刻的电流值作为闭合瞬间电流","why":"S1 闭合瞬间电容器尚未积累电荷、极板电压为零，此时电流只由电源和 R1 决定，是曲线的最大值","do":"读图(b)纵轴在 t=0 处的截距，按纵轴分度值估读到三位有效数字","expr":"I_0=\\frac{E}{R_1}","cues":["读纵轴截距","看最高点","刚闭合那一瞬"],"concepts":["I-t 图像","充电电流"]},{"title":"放电终态电压的判断","type":"模型选择","judge":"放电结束后电容器相当于断路还是与 R2 并联的元件","why":"放电结束时电容器不再有电流，但 S1 仍闭合，电容器两端电压等于 R2 两端电压，由 R1、R2 串联分压决定","do":"把 R1、R2 看作串联回路，用分压求 R2 上的电压","expr":"U_c=\\frac{R_2}{R_1+R_2}E","cues":["放电完看分压","电容和R2并联","串联分压"],"concepts":["闭合电路欧姆定律","串联分压"]},{"title":"用总电荷量求电容","type":"关系建立","judge":"放电释放的总电荷量对应的是哪两个电压之差","why":"充电结束时电容电压为 E，放电结束时降为 R2 分压值，电荷量变化等于电容乘电压变化","do":"写出 ΔQ=C(U_充−U_放)，代入 0.0188 C 解 C","expr":"\\Delta Q=C(U_C'-U_c)","cues":["电荷量对应电压差","不是从零放到零"],"concepts":["电容定义式","电荷量"]},{"title":"用部分面积求瞬时电压","type":"关系建立","judge":"t=1 s 后的面积对应从该时刻电压放到终态电压的电荷量","why":"I-t 图线下面积就是释放的电荷量，剩余面积对应剩余电压差","do":"写出 (U''−U_c)C=0.0038 C，与上一步的 C 联立解 U''","expr":"(U_C''-U_c)C=0.0038\\,\\mathrm{C}","cues":["面积就是电荷量","剩余面积对应剩余电压"],"concepts":["I-t 面积","电荷量"]}],"665":[{"title":"选平均速度求瞬时速度","type":"模型选择","judge":"已知每段的位移和时间，要判断用哪个运动学关系把这两个量转成某时刻的瞬时速度","why":"匀变速直线运动中一段位移内的平均速度等于该段中间时刻的瞬时速度，这是把'段'的信息转成'点'的信息的唯一桥梁","do":"分别对 1→2 段和 2→3 段取平均速度，得到两段各自中间时刻的速度","expr":"v_1=\\frac{d}{t_1},\\quad v_2=\\frac{d}{t_2}","cues":["取平均速度","中间时刻速度","每段位移除以时间"],"concepts":["平均速度","中间时刻瞬时速度","匀变速直线运动"]},{"title":"确定两速度的时间间隔","type":"关系建立","judge":"要判断两个中间时刻速度之间相隔多长时间，而不是直接用 t1 或 t2","why":"加速度由速度变化率定义，分母必须是两个瞬时速度所对应时刻的真实时间差；两个中间时刻分别位于两段的中点","do":"把两段的中点时刻相减，得到时间间隔为两段半时间之和","expr":"\\Delta t=\\frac{t_1}{2}+\\frac{t_2}{2}","cues":["两段中点相隔多久","半段时间相加","不是整段时间"],"concepts":["时间间隔","中间时刻"]},{"title":"由速度变化求加速度","type":"关系建立","judge":"判断加速度方向与速度变化方向的关系，并只取大小","why":"匀减速运动中速度逐渐减小，加速度方向与运动方向相反，题目只问大小，故用速度大小之差除以时间间隔","do":"用两中间时刻速度之差除以时间间隔，取绝对值作为加速度大小","expr":"a=\\frac{v_1-v_2}{\\Delta t}","cues":["速度差除以时间","减速取大小","加速度方向与速度反向"],"concepts":["加速度定义","匀减速直线运动"]},{"title":"反推1号锥筒处速度","type":"前提判断","judge":"要判断求最远距离该从哪个位置、哪个速度起算，需先把 1 号锥筒处的速度求出","why":"最远距离由初速度和加速度决定，而题给信息只能先得到中间时刻速度，必须回推到 1 号锥筒这一明确的起算点","do":"对 1→2 段用位移公式，已知位移 d、时间 t1、加速度 a，解出 1 号锥筒处的速度","expr":"v_0t_1-\\frac{1}{2}at_1^2=d","cues":["先求一号筒速度","从一号筒起算","回推初速度"],"concepts":["位移公式","初速度"]},{"title":"用间距比判断最远锥筒","type":"临界条件","judge":"要判断停止前走过的总位移落在第几个间距之内，即比较总位移与 d 的整数倍","why":"锥筒等间距排列，能经过的锥筒号由总位移能覆盖几个 d 决定，超过某号筒的位移才算'经过'","do":"由初速度和加速度求停止距离，再除以 d 看商落在哪两个整数之间，取不超过该商的最大整数对应的锥筒号","expr":"x=\\frac{v_0^2}{2a},\\quad \\frac{x}{d}","cues":["算总位移","除以间距看商","看能跨过几个筒"],"concepts":["刹车距离","等间距","临界判断"]}],"666":[{"title":"b处压强等于大气压","type":"前提判断","judge":"活塞静止在b处时，封闭气体压强是否等于外界大气压","why":"轻杆光滑、活塞无摩擦且静止，活塞两侧受力必须平衡，外侧只有大气压作用","do":"对b处活塞列水平方向力平衡，得封闭气体压强等于大气压","expr":"p_b=p_0","cues":["活塞静止","无摩擦","两侧压强相等"],"concepts":["力平衡","大气压强"]},{"title":"压力与压强换面积","type":"关系建立","judge":"气体对活塞的压力F与气体压强p之间用什么关系换算","why":"压力是压强在活塞面积上的合力，题目给的是F而气体状态方程用的是p","do":"用F=pS把图线纵坐标F换成压强p，S取500 mm²换算成国际单位","expr":"F=pS,\\quad S=500\\times10^{-6}\\,\\mathrm{m^2}","cues":["压力等于压强乘面积","先换成国际单位"],"concepts":["压强","压力","横截面积"]},{"title":"由直线图线反推pV恒定","type":"关系建立","judge":"F与1/(5+x)成正比这一图线特征，能否推出pV为常量","why":"要证明等温变化，必须证明pV乘积不随x改变，而图线给出F与1/(5+x)的线性关系","do":"设F=k/(5+x)，代入F=pS并把气柱长度写成(x+5)，计算pV看是否消去x","expr":"pV=\\frac{k}{(5+x)S}\\cdot S(x+5)\\times10^{-3}=10^{-3}k","cues":["图线过原点","设个斜率","看乘积消不掉x"],"concepts":["玻意耳定律","正比关系","等温变化"]},{"title":"气柱长度对应体积","type":"几何关系","judge":"a、b两处气柱长度各是多少，体积如何由长度和横截面积算出","why":"a处是活塞离管最右端5 mm，b处气柱长200 mm，体积等于长度乘横截面积","do":"写出V_a=S×5 mm、V_b=S×200 mm，统一用国际单位","expr":"V_a=S\\times5\\times10^{-3},\\quad V_b=S\\times200\\times10^{-3}","cues":["a处长度是5毫米","b处是200毫米","体积等于长度乘面积"],"concepts":["气柱体积","几何长度"]},{"title":"全程等温用玻意耳定律","type":"模型选择","judge":"从b压到a再膨胀回b的整个过程能否统一按等温处理","why":"缓慢移动且图线已证膨胀段pV恒定，压缩段与膨胀段沿同一关系，故全程pV相同","do":"用p_aV_a=p_bV_b求a处压强，再与b处一起作为p-V图上的两个坐标点","expr":"p_aV_a=p_bV_b=p_0Sl_0","cues":["缓慢变化","温度不变","同一团气体"],"concepts":["玻意耳定律","等温过程","理想气体"]}],"667":[{"title":"齿轮传动定转速","type":"关系建立","judge":"由大齿轮角速度求小齿轮（即 K 与线圈）的角速度，判断用线速度相等还是角速度相等","why":"链条传动时两齿轮边缘线速度大小相等，而角速度与半径成反比，半径比为 n 故转速比为 n","do":"写出 v=ω·nr=ω₁·r，解出 ω₁ 与 ω 的关系","expr":"\\omega_1=n\\omega,\\quad T=\\frac{2\\pi}{n\\omega}","cues":["链条线速度相同","半径比是n","小齿轮转得快"],"concepts":["线速度","角速度","链条传动"]},{"title":"转轴在磁场边界","type":"几何关系","judge":"判断线圈各边到转轴的距离，以及磁场只存在于转轴一侧这一几何构型","why":"题设转轴轴线位于磁场边界处，线圈圆心在轴线上，故只有半径在 r 到 4r 之间的那部分扇形区域处于磁场中，且只有跨过边界的边切割磁感线","do":"画出线圈相对磁场边界的位置，标出 ab 边半径 r、cd 边半径 4r，确定哪条边在磁场内、切割长度取 4r−r","expr":"L=4r-r=3r","cues":["轴在边界上","只有一半在磁场里","半径差才是切割长度"],"concepts":["磁场边界","切割长度","扇形线圈"]},{"title":"转动切割取平均速度","type":"模型选择","judge":"判断线圈边切割磁感线时电动势该用哪一点的速度，还是用两端速度的平均值","why":"ab、cd 边是沿半径方向的线段，各点线速度随半径线性变化，故等效切割速度为两端速度的平均值","do":"对 ab 边取 v_a=rω₁、对 cd 边取 v_b=4rω₁，求平均速度后乘 B 与有效长度","expr":"E_1=B\\cdot3r\\cdot\\frac{r\\omega_1+4r\\omega_1}{2}=\\frac{15}{2}nBr^{2}\\omega","cues":["边上速度不一样","取平均速度","用中点速度"],"concepts":["动生电动势","转动切割","平均速度"]},{"title":"分阶段判磁通量变化","type":"临界条件","judge":"判断一个周期内线圈何时有感应电流、何时磁通量不变而无电流，并定出各阶段持续时间","why":"只有线圈边界扫过磁场边界时磁通量才变化；两边都进入磁场后线圈内磁通量恒定，感应电流为零","do":"以 ab 边进入为起点，依次划分：ab 进到 cd 进、两边都在场内、ab 出到 cd 出、两边都在场外，用圆心角占比乘周期求各段时长","expr":"t_1=t_3=\\frac{\\pi-\\beta}{n\\omega},\\quad t_2=t_4=\\frac{\\beta}{n\\omega}","cues":["两边都在场里就没电流","按进出磁场分段","用圆心角算时间"],"concepts":["磁通量变化","感应电流条件","周期性分段"]},{"title":"有效值按发热等效","type":"数学处理","judge":"判断 M₂ 电流有效值不能取平均值，而要用一周期内电阻发热相等来等效","why":"电流是分段方波式变化，有效值定义要求 I²RT 等于各段 I²Rt 之和，平均值会低估发热","do":"对 M₁ 一个周期列发热等式，利用 I₁=I₃、t₁=t₃ 化简求有效值，再由两线圈相同得 M₂ 的有效值","expr":"I_1^2Rt_1+I_3^2Rt_3=I^2RT","cues":["有效值看发热","不能取平均电流","一个周期算总热量"],"concepts":["有效值","焦耳热","交流电"]},{"title":"两线圈功率叠加","type":"结论整理","judge":"判断装置 K 的总功率是两个线圈功率之和，且两线圈电流有效值相同","why":"M₁、M₂ 完全相同的线圈对称安装，各自独立发热，总消耗功率为两者之和","do":"用 P=2I²R 把已求有效值代入，整理成含 (π−β)/π 的形式","expr":"P=2I^{2}R=\\frac{15nBr^{3}\\omega(\\pi-\\beta)}{\\pi}","cues":["两个线圈都要算","有效值一样","功率直接相加"],"concepts":["电功率","有效值","对称性"]}],"668":[{"title":"场强定义式","type":"前提判断","judge":"要判断 F 与 q 之间通过什么物理量联系，即用哪个定义式把图像和场强挂钩","why":"场强的定义是 E=F/q，F-q 图像上每一点的纵坐标与横坐标之比才等于该点场强","do":"写出 E=F/q，明确 F-q 图线是过原点的直线，其斜率即场强","expr":"E=\\frac{F}{q}","cues":["用比值定义","场强等于力比电荷"],"concepts":["电场强度","比值定义法"]},{"title":"斜率即场强","type":"关系建立","judge":"要判断 F-q 图像的斜率对应什么物理量，而不是把纵坐标或横坐标本身当成场强","why":"由 F=Eq 可知 F 与 q 成正比，比例系数就是 E，故图线斜率表示场强大小","do":"把 F=Eq 与直线方程对照，确认斜率 k=E","expr":"F=Eq,\\ k=E","cues":["斜率是场强","看直线的倾斜程度"],"concepts":["电场强度","图像斜率"]},{"title":"读两线斜率比","type":"图像读取","judge":"要判断 a、b 两条直线各自的斜率大小，并取它们的比值","why":"题目只给图像，场强之比只能由两条直线的斜率之比得到","do":"在图上取同一横坐标（或同一纵坐标）比较两线的纵坐标（或横坐标），读出斜率之比","expr":"\\frac{E_a}{E_b}=\\frac{k_a}{k_b}","cues":["取同一横坐标比高度","a线更陡"],"concepts":["图像斜率","正比关系"]},{"title":"排除纵轴截距干扰","type":"结论整理","judge":"要判断图线是否过原点，不能把纵轴截距或某点纵坐标误当成场强","why":"F=Eq 是正比关系，图线必过原点；若误读截距或单点纵坐标，就会得出错误比值","do":"确认两直线均过原点，只用斜率比，不用截距或单点坐标","expr":"","cues":["图线过原点","别用截距算"],"concepts":["正比关系","过原点直线"]}],"669":[{"title":"识别镜片的偏振本质","type":"模型选择","judge":"要判断特殊眼镜镜片起偏/检偏作用的物理机制是什么","why":"只有把镜片认定为偏振片、把液晶屏出射光认定为线偏振光，才能用偏振规律解释一亮一暗","do":"由'左亮右暗'反推：两镜片透振方向互相垂直，屏幕出射的是线偏振光","expr":"","cues":["偏振片","线偏振光","不是普通滤光"],"concepts":["偏振","偏振片","线偏振光"]},{"title":"确定两镜片透振方向关系","type":"前提判断","judge":"要判断左右镜片透振方向是相互平行还是相互垂直","why":"立体眼镜左右镜片分别对应两种互相垂直的偏振态，这是'一明一暗'现象成立的前提","do":"由同一偏振光通过两镜片一亮一暗，判定两透振方向互相垂直","expr":"","cues":["互相垂直","左右不同","立体眼镜"],"concepts":["透振方向","偏振片"]},{"title":"用马吕斯定律定量比较","type":"关系建立","judge":"要判断透射光强随偏振方向夹角如何变化","why":"偏振光通过偏振片后光强按余弦平方规律衰减，夹角决定明暗","do":"写出透射光强与夹角的余弦平方关系，比较旋转前后两镜片的夹角","expr":"$I=I_0\\cos^2\\theta$","cues":["余弦平方","夹角决定亮度","马吕斯定律"],"concepts":["马吕斯定律","光强"]},{"title":"旋转屏幕等价于转偏振方向","type":"几何关系","judge":"要判断旋转屏幕 90 度后，入射偏振方向相对两镜片各转过多大角度","why":"屏幕旋转带动出射偏振方向同步旋转，原夹角与镜片透振方向的关系整体改变 90 度","do":"把旋转前夹角记为 θ，旋转后变为 θ±90°，分别代入两镜片","expr":"$\\theta\\to\\theta+90^\\circ$","cues":["偏振方向跟着转","夹角变九十度","屏幕转光也转"],"concepts":["偏振方向","夹角"]},{"title":"明暗互换的结论","type":"结论整理","judge":"要判断旋转后原来亮的一侧与暗的一侧亮度如何对调","why":"夹角由 θ 变为 θ+90° 时余弦平方值互补，原来取大值的一方变为小值","do":"比较旋转前后两镜片的 cos²θ 值，得出左变暗、右变亮","expr":"$\\cos^2(\\theta+90^\\circ)=\\sin^2\\theta$","cues":["明暗互换","左暗右亮","亮度对调"],"concepts":["马吕斯定律","互补"]}],"670":[{"title":"锁定守恒定律","type":"前提判断","judge":"判断该核反应方程应依据哪条（哪几条）守恒定律来定未知粒子","why":"核反应中质量数守恒与电荷数守恒同时成立，这是确定未知核素身份的唯一依据","do":"对反应前后分别列出质量数总和与电荷数总和相等的两个等式","expr":"A_X+14=1+17,\\quad Z_X+7=1+8","cues":["看质量数","看电荷数","两个都要守恒"],"concepts":["质量数守恒","电荷数守恒","核反应方程"]},{"title":"由守恒定核素身份","type":"关系建立","judge":"判断解出的质量数与电荷数组合对应哪种粒子（质子、中子、α粒子等）","why":"核素由质量数A和电荷数Z共同确定，只知其中一个无法区分粒子种类","do":"把求得的A、Z与常见粒子（氦核、质子、中子、电子）的A、Z对照","expr":"{}^{A}_{Z}\\mathrm{X}={}^{4}_{2}\\mathrm{He}","cues":["质量数四","电荷数二","是氦核"],"concepts":["α粒子","核素符号"]},{"title":"排除干扰项","type":"结论整理","judge":"判断各干扰项在质量数或电荷数上是否与守恒结果矛盾","why":"干扰项通常只满足其中一个守恒或把两种粒子混淆，必须用A、Z双条件同时筛","do":"对每个候选粒子核对它的A、Z是否同时等于4和2","expr":"","cues":["质子不对","中子电荷数零","电子质量数零"],"concepts":["质量数","电荷数"]}],"671":[{"title":"空中水的受力与加速度","type":"前提判断","judge":"喷出的水在空中是否只受重力、加速度是否都等于 g","why":"不计空气阻力，水离开喷口后只受重力，由牛顿第二定律加速度恒为 g，与喷出速度大小方向无关","do":"对空中任一水滴受力分析，确认只受重力，比较 a、b 两喷泉水滴的加速度","expr":"a=g","cues":["只受重力","加速度都是g","跟速度无关"],"concepts":["重力","牛顿第二定律","加速度"]},{"title":"竖直方向定飞行时间","type":"模型选择","judge":"把喷泉水的运动看成竖直上抛与平抛的合成，用竖直分运动决定空中时间","why":"竖直方向只受重力做匀变速运动，上升与下落对称，时间只由最大高度决定，与水平速度无关","do":"由最高点高度 h 写出空中时间，比较两喷泉的最大高度","expr":"t=2\\sqrt{\\frac{2h}{g}}","cues":["看竖直高度","上下对称","时间由高度定"],"concepts":["竖直上抛","运动的独立性","对称性"]},{"title":"水平位移与时间定水平速度","type":"关系建立","judge":"能否由水平射程和飞行时间确定最高点速度（水平分速度）的大小关系","why":"最高点只剩水平分速度，v_x=x/t，必须同时知道水平射程 x 与时间 t 才能比较，题图未给出射程关系","do":"写出最高点速度表达式，检查 x 与 t 是否都已知，判断能否比较","expr":"v_x=\\frac{x}{t}","cues":["水平射程没给","x和t都要","比不出来"],"concepts":["平抛运动","水平分速度","射程"]},{"title":"初速度需合成分量","type":"结论整理","judge":"初速度大小能否由竖直、水平分速度合成后比较","why":"初速度是竖直分速度与水平分速度的矢量和，两个分量的大小关系都不确定时，合速度大小无法比较","do":"写出初速度与分速度的合成关系，指出分量均未知故无法判断","expr":"v_0=\\sqrt{v_x^2+v_y^2}","cues":["要合成","两个分量都不定","没法比大小"],"concepts":["速度合成","分速度","矢量"]}],"672":[{"title":"光电效应的能量门槛","type":"前提判断","judge":"发生光电效应的条件应判断为入射光子能量与金属逸出功的大小关系，还是与光强、频率高低排序的关系","why":"光电效应方程 hν=W₀+E_k 表明只有 hν≥W₀ 才能逸出光电子，能否发生只由单个光子的能量（频率）决定，与光子数目、光强无关","do":"写出光电效应发生条件 hν≥W₀，明确比较对象是各光子的能量而非波长长短或光子数多少","expr":"h\\nu \\ge W_0","cues":["看频率够不够","跟逸出功比","不是看光强"],"concepts":["光电效应","逸出功","光子能量"]},{"title":"只有一种生效的含义","type":"关系建立","judge":"“只有一种光子能发生光电效应”对应的是四种光子能量中恰有一个超过逸出功，还是四个都超过只是强弱不同","why":"若有两种以上光子能量超过 W₀，则它们都能引发光电效应，与“只有一种”矛盾；因此该金属的逸出功必须卡在最大光子能量与次大光子能量之间","do":"把四种光子的能量按大小排序，判断逸出功 W₀ 必须落在最大能量与次大能量之间这一区间","expr":"E_{\\text{次大}} < W_0 \\le E_{\\text{最大}}","cues":["只有最大的那个够","逸出功卡在中间","比第二大的还大"],"concepts":["逸出功","光子能量排序","临界条件"]},{"title":"能级差定光子能量","type":"模型选择","judge":"比较四种光子能量时，应比较跃迁两能级间的能量差，还是比较能级的高低或跃迁路径的长短","why":"原子跃迁辐射的光子能量由初末能级差决定，hν=E_m−E_n，能级差越大光子能量越大、波长越短，与能级绝对高低、跃迁级数无关","do":"对图中每条跃迁箭头读出初末能级，算出能级差，找出能级差最大的那一次跃迁","expr":"h\\nu = E_m - E_n","cues":["算能级差","看箭头跨几级","能级差越大能量越大"],"concepts":["能级跃迁","能级差","光子能量"]},{"title":"能量与波长的反比","type":"数学处理","judge":"题目给出的是波长 λ，应判断能量最大对应波长最长还是最短","why":"由 c=λν 与 E=hν 得 E=hc/λ，能量与波长成反比，能量最大的光子对应波长最短","do":"把能级差最大的跃迁换算成波长，取其中最短者，与选项中波长标注对应","expr":"E=\\frac{hc}{\\lambda}","cues":["波长越短能量越大","反比关系","挑最短的波长"],"concepts":["波长与能量关系","光子能量"]}],"673":[{"title":"确定入射角与折射角","type":"几何关系","judge":"图中光线与法线的夹角，哪个是入射角、哪个是折射角，两杯溶液的折射角大小关系如何","why":"折射定律中的角都是光线与法线的夹角，不是与界面的夹角；题设已给出 β₁<β₂","do":"在图上过入射点作法线，标出空气中的入射角 θ 和两溶液中的折射角 β₁、β₂，比较两者大小","expr":"","cues":["找法线","角从法线量起","乙的折射角更大"],"concepts":["入射角","折射角","法线"]},{"title":"由折射角比较折射率","type":"关系建立","judge":"入射角相同时，折射角越小说明折射率越大还是越小","why":"折射定律 n=sinθ/sinβ，θ 相同，n 与 sinβ 成反比","do":"对两杯溶液分别写折射定律，由 β₁<β₂ 推出 n甲 与 n乙 的大小","expr":"n=\\frac{\\sin\\theta}{\\sin\\beta}","cues":["入射角一样","折射角小的折射率大","比sin值"],"concepts":["折射定律","折射率"]},{"title":"浓度与折射率挂钩","type":"前提判断","judge":"折射率大的那杯对应浓度大还是浓度小","why":"题设明确给出折射率随浓度增大而变大，这是判断浓度大小的唯一依据","do":"把上一步得到的折射率大小关系代入题设的单调关系，定出甲、乙浓度高低","expr":"","cues":["浓度大折射率大","题里给了这个条件","甲折射率大所以浓"],"concepts":["浓度","折射率"]},{"title":"光速与临界角随折射率变化","type":"关系建立","judge":"折射率大的介质中光速更大还是更小，全反射临界角更大还是更小","why":"v=c/n 与 sinC=1/n 都表明光速、临界角随折射率增大而减小","do":"用 n甲>n乙 分别比较 v甲 与 v乙、C甲 与 C乙","expr":"v=\\frac{c}{n},\\quad \\sin C=\\frac{1}{n}","cues":["折射率大光速小","临界角看正弦","甲临界角小"],"concepts":["光速","全反射临界角"]}],"674":[{"title":"波沿水面传播","type":"模型选择","judge":"扰动在水面产生的振动以机械波形式沿水面由 O 向 A、B 传播，波速由介质决定、保持不变","why":"水面扰动激起的是机械波，同一水面上波速恒定，与振幅、距离无关；若误以为离波源越远波速越小或越大，就会得出错误时刻","do":"确认波从 O 依次传到 A、B，传播距离与传播时间成正比","expr":"v=\\frac{s}{t}=\\text{常量}","cues":["波速不变","沿水面传过去","距离越远越慢"],"concepts":["机械波","波速"]},{"title":"由 OA 定波速","type":"关系建立","judge":"用 O 到 A 的距离和 A 开始振动的时刻 t1 表示出波速","why":"t1 是波从 O 传到 A 所用的时间，OA 是这段传播的距离，二者之比即波速，这是后续求 B 时刻的唯一桥梁","do":"设 OA=2AB=2L，写出波速与 t1、L 的关系","expr":"v=\\frac{OA}{t_1}=\\frac{2L}{t_1}","cues":["先求波速","用OA除以t1","设一段为L"],"concepts":["波速","传播时间"]},{"title":"换算 AB 段时间","type":"关系建立","judge":"把 AB 的距离换算成波传播所需的时间，再与 t1 比较","why":"OA=2AB 说明 AB 段距离是 OA 的一半，波速不变则时间也是一半；若直接用 AB 距离而不与 OA 比较，就无法用 t1 表示结果","do":"由 AB=L 与 v=2L/t1 求波从 A 传到 B 的时间","expr":"t_{AB}=\\frac{L}{v}=\\frac{t_1}{2}","cues":["AB是OA一半","时间也是一半","用t1表示"],"concepts":["比例关系","波速"]},{"title":"叠加得 B 时刻","type":"结论整理","judge":"B 开始振动的时刻是波到 A 的时刻再加上 A 到 B 的传播时间，而不是只用 AB 段时间","why":"计时起点是 t=0 在 O 处扰动，波必须先走完 OA 才到 A，再到 B；漏加 t1 就会把答案错写成 t1/2","do":"把 t1 与 tAB 相加得到 B 开始振动的时刻","expr":"t=t_1+t_{AB}=\\frac{3}{2}t_1","cues":["要加上t1","从零时刻算起","别漏了OA段"],"concepts":["传播时间","时刻"]}],"675":[{"title":"陶屑随盘转动的运动模型","type":"模型选择","judge":"陶屑相对台面静止时做什么运动、由什么力提供向心力","why":"陶屑随台面一起绕轴匀速转动，相对台面不动，只能由台面给它的静摩擦力提供向心力，重力与支持力在竖直方向平衡","do":"对与台面相对静止的陶屑受力分析，找出水平方向唯一的外力即静摩擦力，并指向轴心","expr":"f=m\\omega^{2}r","cues":["随盘一起转","静摩擦当向心力","水平方向只有摩擦"],"concepts":["匀速圆周运动","向心力","静摩擦力"]},{"title":"静摩擦不超过最大静摩擦","type":"临界条件","judge":"陶屑能保持相对静止的条件是所需向心力不超过最大静摩擦力","why":"静摩擦力有上限，所需向心力随半径增大而增大，超过上限陶屑就会相对台面滑动","do":"把向心力表达式与最大静摩擦力比较，写出不滑动的临界不等式","expr":"m\\omega^{2}r\\le \\mu mg","cues":["不能超过最大静摩擦","半径越大越容易甩出去","临界时取等号"],"concepts":["最大静摩擦力","临界状态"]},{"title":"质量约去得临界半径","type":"关系建立","judge":"临界半径与陶屑质量是否有关","why":"不等式两边都含质量 m，可约去，说明能否静止只由角速度、摩擦因数和半径决定，与质量无关","do":"由临界等式解出半径，观察式中不含 m","expr":"r_{\\max}=\\frac{\\mu g}{\\omega^{2}}","cues":["质量约掉了","和质量无关","只看半径和转速"],"concepts":["牛顿第二定律","向心加速度"]},{"title":"定值半径决定分布范围","type":"结论整理","judge":"角速度与摩擦因数一定时，能静止的陶屑分布范围如何","why":"μ、ω 一定则临界半径是定值，半径小于它的位置都能静止，大于它的位置不能静止","do":"由临界半径是定值，判断静止陶屑只能分布在某一半径以内，最远处不超过该值","expr":"R=\\frac{\\mu g}{\\omega^{2}}=\\text{定值}","cues":["最远有个上限","不是越远越多","超过就滑走"],"concepts":["圆周运动半径","静摩擦上限"]}],"676":[{"title":"选系统判动量守恒","type":"模型选择","judge":"把 A、B 和弹簧取为一个系统，判断水平方向合外力是否为零","why":"各表面光滑、水平方向无外力，系统水平动量守恒；若只取 A 或只取 B，就要多引入弹簧弹力这个未知量","do":"对 A+B+弹簧整体做水平方向受力分析，确认无水平外力","expr":"","cues":["取整体","水平没外力","动量守恒"],"concepts":["动量守恒","整体法"]},{"title":"判机械能守恒","type":"前提判断","judge":"判断剪断细绳后系统机械能是否守恒","why":"只有弹簧弹力做功，支持力和重力不做功，无摩擦生热，故系统机械能守恒","do":"列出剪断前后能量相等的式子，确认没有其他耗散","expr":"","cues":["只有弹力做功","机械能不变","没有摩擦"],"concepts":["机械能守恒","弹性势能"]},{"title":"定速度最大位置","type":"临界条件","judge":"判断 B 的速度在弹簧处于什么状态时达到最大","why":"弹簧恢复原长前弹力一直对 B 做正功、使其加速，过原长后弹力反向做负功使其减速，故原长时速度最大","do":"比较弹簧原长前后弹力方向与 B 运动方向，找加速转减速的分界点","expr":"","cues":["原长时最快","先加速后减速","弹力反向"],"concepts":["弹力做功","速度极值"]},{"title":"用动量守恒定速度比","type":"关系建立","judge":"由系统总动量为零，判断 A、B 速度大小与质量的关系","why":"初态系统静止、总动量为零，任一时刻两者动量等大反向，速度比由质量反比决定","do":"写出动量守恒式并联立机械能守恒式，把 v_A 用 v_B 表示","expr":"m_Av_A=m_Bv_B","cues":["总动量为零","动量等大反向","质量大的慢"],"concepts":["动量守恒","质量与速度反比"]},{"title":"联立求最大动能","type":"数学处理","judge":"把动量关系和能量关系联立，判断原长时动能（动量）是否为最大值","why":"弹性势能全部转化为动能时总动能最大，再由动量守恒分配到两者，故此时各自动能、动量均最大","do":"将 v_A 代入能量式，得到 E_p 与 v_B 的关系式，判断 v_B 最大即动能最大","expr":"E_p=\\frac{1}{2}\\left(\\frac{m_B^2}{m_A}+m_B\\right)v_B^2","cues":["势能全变动能","联立两式","动能最大"],"concepts":["能量守恒","动能"]}],"677":[{"title":"判断a中磁通量变化","type":"前提判断","judge":"线圈a被拉出磁场时，穿过a的磁通量是增大还是减小","why":"感应电流方向由磁通量变化决定，必须先确定磁通量是增是减，才能用楞次定律","do":"比较拉出前后a在磁场中的有效面积，判断磁通量增减","expr":"\\Phi_a = BS_{\\text{有效}},\\ S_{\\text{有效}}\\downarrow\\Rightarrow\\Phi_a\\downarrow","cues":["面积变小","磁通量减少","拉出磁场"],"concepts":["磁通量","楞次定律"]},{"title":"定a中电流方向","type":"关系建立","judge":"由磁通量减小和原磁场方向，判断a中感应电流的绕行方向","why":"楞次定律：感应电流的磁场要阻碍原磁通量的减小，故感应磁场与原磁场同向","do":"先定原磁场方向，再定感应磁场同向，用右手螺旋定则得a中电流绕向","expr":"","cues":["阻碍减少","感应磁场同向","右手螺旋"],"concepts":["楞次定律","右手螺旋定则"]},{"title":"a的磁场穿过b","type":"模型选择","judge":"把a看作产生磁场的场源，判断a的磁场在b处沿什么方向、随a靠近如何变化","why":"b中电流由a的磁场穿过b的磁通量变化决定，需先确定a在b处产生的磁场方向和强弱变化","do":"用右手螺旋定则判断a中电流在b所在区域产生的磁场方向，并判断a靠近b时该磁场增强","expr":"","cues":["a当磁铁看","靠近变强","穿过b的磁场"],"concepts":["电流的磁场","磁通量"]},{"title":"定b中电流方向","type":"关系建立","judge":"由穿过b的磁通量增大及其方向，判断b中感应电流的绕行方向","why":"楞次定律：感应电流的磁场要阻碍磁通量增大，故与穿过b的原磁场反向","do":"先定穿过b的磁场方向，再取反向得b的感应磁场方向，用右手螺旋定则得b中电流绕向","expr":"","cues":["阻碍增大","感应磁场反向","右手螺旋"],"concepts":["楞次定律","右手螺旋定则"]}],"678":[{"title":"圆锥摆受力模型","type":"模型选择","judge":"小球在水平面内做匀速圆周运动，向心力由哪个力提供","why":"小球受重力与绳拉力，二力合力水平指向圆心，竖直方向无加速度，故合力为 mg·tanθ","do":"对小球画受力图，把绳拉力分解为竖直与水平分量，竖直分量与重力平衡，水平分量作向心力","expr":"mg\\tan\\theta = m\\dfrac{v^2}{r}=m\\omega^2 r=m\\dfrac{4\\pi^2}{T^2}r=ma","cues":["合力水平","重力与拉力","圆锥摆"],"concepts":["圆锥摆","向心力","受力分析"]},{"title":"用高度代替摆长","type":"关系建立","judge":"把半径 r=l·sinθ 与高度 h=l·cosθ 联系起来，使各量只依赖 h 或 θ","why":"缓慢下拉时 l 与 θ 同时变化，直接比较 l、θ 无法定论，必须换成单一变量 h 或 θ 才能判断变化趋势","do":"由几何关系写出 r=l·sinθ、h=l·cosθ，把向心力方程中的 r 与 l 消去，化为含 h 或 θ 的式子","expr":"r=l\\sin\\theta,\\quad h=l\\cos\\theta","cues":["换成高度","消去摆长","只看竖直高度"],"concepts":["几何关系","变量替换"]},{"title":"下拉后高度变小","type":"前提判断","judge":"缓慢下拉绳子后，小球所在平面高度 h 与绳角 θ 各自如何变化","why":"绳被拉短，小球沿绳方向上升，圆周平面降低，同时绳与竖直方向夹角增大","do":"比较 A、B 两位置的 h 与 θ，确定 h 减小、θ 增大","expr":"h_B<h_A,\\quad \\theta_B>\\theta_A","cues":["拉绳变短","高度降低","角度变大"],"concepts":["缓慢下拉","几何约束"]},{"title":"周期角速度随高度","type":"关系建立","judge":"T、ω 随 h 减小是增大还是减小","why":"由向心力方程可导出 T 与 ω 只由 h 决定，与 l、θ 无关，故可直接由 h 的变化定论","do":"将向心力方程整理成 T=2π√(h/g)、ω=√(g/h)，代入 h 变小判断","expr":"T=2\\pi\\sqrt{\\frac{h}{g}},\\quad \\omega=\\sqrt{\\frac{g}{h}}","cues":["只跟高度有关","高度小周期小","角速度变大"],"concepts":["周期","角速度","向心力方程"]},{"title":"线速度不能定论","type":"临界条件","judge":"v 随 l 减小、θ 增大能否确定单调变化","why":"v 的表达式中 l 减小使 v 减小、θ 增大使 v 增大，两个因素反向，无法判定","do":"写出 v=sinθ√(gl/cosθ)，分析 l 与 θ 变化对 v 的影响方向相反，得出无法判断","expr":"v=\\sin\\theta\\sqrt{\\frac{gl}{\\cos\\theta}}","cues":["两个因素反向","一个变大一个变小","无法判断"],"concepts":["线速度","单调性"]},{"title":"向心加速度看角度","type":"关系建立","judge":"向心加速度 a 随 θ 增大如何变化","why":"由 mg·tanθ=ma 得 a=g·tanθ，只由 θ 决定，θ 增大则 a 增大","do":"由向心力方程消去 m 得 a=g·tanθ，比较 A、B 两位置的 θ","expr":"a=g\\tan\\theta","cues":["加速度看角度","角度大加速度大","与高度无关"],"concepts":["向心加速度","牛顿第二定律"]}],"679":[{"title":"欧姆表倍率读数","type":"图像读取","judge":"沿 bc 方向测电阻时，欧姆表选的是哪一挡倍率，表盘读数该乘多少","why":"欧姆表刻度不均匀且标的是倍率乘积，读数必须用表盘示数乘以所选挡位倍率，否则电阻值差一个数量级","do":"看图(b)中指针所指的表盘刻度值，并确认选择开关所置的倍率挡，两者相乘","expr":"R = n \\times \\text{倍率}","cues":["看指针位置","乘倍率","选的是哪一挡"],"concepts":["欧姆表","倍率","表盘读数"]},{"title":"按待测阻值选变阻器","type":"前提判断","judge":"测约几百欧的电阻时，滑动变阻器该按阻值相当还是按限流安全来选","why":"分压/限流接法下变阻器最大阻值应与待测电阻同数量级才能有效调节；阻值过小调节范围窄，过大则电流过小、灵敏度差","do":"比较待测电阻约 300 Ω 与两个变阻器的最大阻值 5 Ω、500 Ω，并核对额定电流是否满足电路电流","expr":"R_{\\text{滑}} \\sim R_x","cues":["阻值要相当","看最大阻值","还要看额定电流"],"concepts":["滑动变阻器","分压限流","量程匹配"]},{"title":"分压接法的连线判断","type":"模型选择","judge":"实物图中变阻器采用的是分压还是限流接法，电压表应并联在待测电阻哪两端","why":"分压接法要求变阻器全部电阻丝接入且滑片分压，电压表必须跨接在待测电阻两端，接错位置则测量对象改变","do":"对照电路图(c)逐段核对实物图丁，重点看电压表接线柱是否跨在待测电阻两端，找出错接区域","expr":"","cues":["先看分压还是限流","电压表跨哪两端","对照电路图找"],"concepts":["分压接法","电压表并联","实物连线"]},{"title":"闭合开关前的滑片位置","type":"实验操作","judge":"闭合开关前滑片应置于使待测部分电压（或电流）最小的那一端","why":"保护电表和元件，避免接通瞬间电压、电流过大；分压接法应使输出电压为零，限流接法应使接入阻值最大","do":"判断本电路为分压接法后，确定滑片移到使待测电阻分压为零的一端（图中最右端）","expr":"","cues":["保护电表","输出电压为零","滑到最右端"],"concepts":["分压接法","安全操作","滑片位置"]},{"title":"电表内阻引起的误差比较","type":"误差分析","judge":"测小电阻与大电阻时，电表内阻相对待测电阻的大小决定误差大小，不能只看电阻绝对值","why":"电表内阻与被测电阻可比时，分流/分压效应显著，相对误差大；内阻远小于待测电阻时影响可忽略","do":"分别比较微安表内阻约 4 Ω 与 10 Ω、电流表内阻约 1 Ω 与 300 Ω 的比值，判断哪种组合相对误差更小","expr":"\\frac{R_A}{R_x} \\ll 1 \\Rightarrow \\text{误差小}","cues":["看内阻占比","相对误差","小电阻反而误差大"],"concepts":["电表内阻","相对误差","分流效应"]}],"680":[{"title":"判断气体做何变化","type":"模型选择","judge":"密闭容器移动前后，气体经历的是等容、等压还是等温过程","why":"容器密闭且题设明确体积不变，只有体积不变才能把 p 与 T 直接挂钩","do":"从题干中提取'密闭''体积不变'两个条件，确定气体质量与体积均不变","expr":"V_1=V_2,\\ m=\\text{const}","cues":["密闭容器","体积不变","质量不变"],"concepts":["等容变化","理想气体"]},{"title":"选定律连压强温度","type":"关系建立","judge":"用哪个气体实验定律把初态压强温度与末态压强温度联系起来","why":"一定质量气体在体积不变时压强与热力学温度成正比，这是查理定律的适用条件","do":"写出初末态压强比等于初末态热力学温度比，温度直接代入开尔文值","expr":"\\frac{p_1}{T_1}=\\frac{p_2}{T_2}","cues":["查理定律","压强比温度","温度用开尔文"],"concepts":["查理定律","热力学温度"]},{"title":"明确压力是气体压强产生","type":"前提判断","judge":"观测台受到的气体压力由容器内气体压强决定，还是由月球外部真空或重力决定","why":"月球表面真空，台面一侧无外部气体；压力来源于容器内气体对台面的压强作用","do":"确认受力分析中只计入容器内气体压强，排除外部大气与月球重力因素","expr":"","cues":["外部是真空","只看内部气体","与重力无关"],"concepts":["气体压强","真空"]},{"title":"用压强定义求压力","type":"关系建立","judge":"由压强和受力面积求压力时，面积应取观测台与气体接触的面积","why":"压强定义式 F=pS 中 S 是垂直于压力方向的受力面积，题给观测台面积即此面积","do":"把第（1）问得到的末态压强乘以观测台面积，得到气体对台面的压力","expr":"F=p_2S","cues":["压强乘面积","用观测台面积","压力垂直台面"],"concepts":["压强定义","压力"]}],"681":[{"title":"分离过程动量守恒","type":"模型选择","judge":"分离瞬间A、B组成的系统能否用动量守恒处理","why":"分离时间极短，A、B之间的推力远大于外力（引力等），系统所受合外力冲量可忽略","do":"把A、B取为一个系统，比较分离前后总动量，列守恒式","expr":"(m+M)v_0 = Mv + mv_1","cues":["取整体","分离瞬间","内力远大于外力"],"concepts":["动量守恒定律","系统","内力与外力"]},{"title":"规定正方向","type":"前提判断","judge":"以哪个方向为正，各速度取正还是取负","why":"动量是矢量，题目给出B与v0同向，需统一符号才能列代数式","do":"取v0方向为正，把v0、v都写成正值代入守恒式","expr":"","cues":["同向取正","先定正方向","速度带符号"],"concepts":["动量矢量性","正方向约定"]},{"title":"求A的速度并说明方向","type":"关系建立","judge":"解出的v1符号说明A与v0同向还是反向","why":"动量守恒式解出的v1是带符号的代数量，符号对应方向","do":"由守恒式解出v1，判断其正负并说明方向","expr":"v_1=\\frac{(m+M)v_0-Mv}{m}","cues":["解出再判方向","看正负","与v0比"],"concepts":["动量守恒","速度方向"]},{"title":"隔离B用动量定理","type":"模型选择","judge":"求推力应选A、B整体还是单独选B为研究对象","why":"推力是A、B间的内力，对整体列式会消去；只有隔离其中一个物体，推力才成为外力出现在冲量式中","do":"单独取B为研究对象，分析分离过程中B受到的冲量","expr":"F\\Delta t = Mv - Mv_0","cues":["隔离B","内力变外力","别取整体"],"concepts":["动量定理","隔离法","冲量"]},{"title":"推力用平均力处理","type":"近似条件","judge":"分离过程中推力是否可视为恒定的平均推力","why":"推力在Δt内可能变化，动量定理给出的是冲量，除以Δt得到的是平均推力","do":"用冲量除以分离时间求平均推力大小","expr":"F=\\frac{M(v-v_0)}{\\Delta t}","cues":["求平均力","冲量除以时间","力会变"],"concepts":["平均冲力","动量定理","冲量"]}],"682":[{"title":"分段识别运动性质","type":"模型选择","judge":"要判断 AB、BC、CD 三段各是什么运动，以及每段该用牛顿第二定律还是平衡条件","why":"题设给出“由静止加速到最大速度 v”“匀速”“恰好到达最高点”，三段加速度不同，规律不同，混用会列错方程","do":"把全过程切成 AB 加速、BC 匀速、CD 减速到零三段，分别标出加速度方向和是否受力平衡","expr":"","cues":["分三段看","匀速段合力为零","最后减速到零"],"concepts":["匀变速直线运动","平衡条件","牛顿第二定律"]},{"title":"CD 段受力与加速度","type":"关系建立","judge":"要判断关闭电动机后物块沿斜面向上运动时，重力沿斜面分量与摩擦力是否同向、加速度由谁提供","why":"CD 段无牵引力，物块上滑，滑动摩擦力沿斜面向下，与重力分量同向，两者共同产生减速加速度","do":"沿斜面方向对 CD 段列牛顿第二定律，取沿斜面向下为正","expr":"mg\\sin\\theta+\\mu mg\\cos\\theta=ma","cues":["摩擦力也向下","两个力同向","上滑时摩擦阻碍"],"concepts":["滑动摩擦力","牛顿第二定律","受力分析"]},{"title":"用速度位移关系求 CD 长","type":"数学处理","judge":"要判断 CD 段已知初速 v、末速零、加速度 a，该选哪个运动学公式直接求位移而不引入时间","why":"题目未给时间，用速度—位移关系可一步消去时间，避免多设未知量","do":"对 CD 段用末速为零的匀减速公式，把上一步的 a 代入解出 x","expr":"0-v^{2}=-2ax\\Rightarrow x=\\frac{v^{2}}{2g(\\sin\\theta+\\mu\\cos\\theta)}","cues":["不含时间","用速度位移公式","末速为零"],"concepts":["匀变速直线运动","速度位移公式"]},{"title":"匀速段牵引力等于阻力","type":"临界条件","judge":"要判断 BC 段“达到最大速度后匀速”意味着牵引力与沿斜面的总阻力大小相等","why":"匀速即合力为零，电动机牵引力必须恰好平衡重力分量与摩擦力之和，这是求功率的前提","do":"对 BC 段沿斜面列平衡方程，求出牵引力 F","expr":"F=mg\\sin\\theta+\\mu mg\\cos\\theta","cues":["匀速合力为零","牵引力等于阻力","最大速度对应平衡"],"concepts":["平衡条件","牵引力","滑动摩擦力"]},{"title":"功率用牵引力乘速度","type":"关系建立","judge":"要判断电动机输出功率对应的是牵引力与速度的乘积，而不是合力或重力做功的功率","why":"输出功率定义式为 P=Fv，F 必须是电动机施加的牵引力，用合力算会漏掉阻力消耗的部分","do":"把匀速段的牵引力 F 与速度 v 相乘得 P","expr":"P=Fv=mgv(\\sin\\theta+\\mu\\cos\\theta)","cues":["功率等于牵引力乘速度","不能用合力","匀速段速度就是v"],"concepts":["功率","牵引力"]},{"title":"全程能量守恒定总电能","type":"结论整理","judge":"要判断电动机消耗的总电能最终转化成了哪些能量，机械能增量该用哪段高度差算","why":"能量守恒要求总电能等于物块机械能增量与全程摩擦生热之和，漏掉摩擦生热会低估 E2","do":"用 A 到 D 的竖直高度差算机械能增量，再用全程路程 L 算摩擦生热，两者相加得 E2 后求比值","expr":"E_{1}=mgL\\sin\\theta,\\quad E_{2}=E_{1}+\\mu mgL\\cos\\theta","cues":["电能变机械能加内能","摩擦生热按全程算","高度差用斜面长投影"],"concepts":["能量守恒","机械能","摩擦生热"]}],"683":[{"title":"插入体前后速度关系","type":"前提判断","judge":"电子每次穿过插入体后速度变为原来的 k 倍，这个衰减发生在哪一侧、对应哪个半径","why":"题设规定插入体使速度减为 k 倍，而半径由 r=mv/(Be) 决定，速度变化直接决定半径变化","do":"明确进入插入体前对应大半径 r1、穿出后对应小半径 r2，写出 r1/r2=v1/v2","expr":"\\frac{r_1}{r_2}=\\frac{v_1}{v_2}=\\frac{1}{k}","cues":["穿过插入体速度变小","半径跟着速度变","先定谁大谁小"],"concepts":["洛伦兹力提供向心力","轨道半径"]},{"title":"稳定速度的能量平衡","type":"关系建立","judge":"把哪两个过程配对成一个循环，使电场做功与插入体损失的能量相等","why":"稳定时每循环一次电场加速获得的动能恰好等于插入体减速损失的动能，否则速度会继续变","do":"取电场加速段与插入体减速段为一个循环，用动能定理列等式","expr":"\\frac{1}{2}mv^{2}-\\frac{1}{2}m(kv)^{2}=eU","cues":["电场补能量","插入体扣能量","一进一出相等"],"concepts":["动能定理","稳定状态"]},{"title":"左右半径的比例关系","type":"关系建立","judge":"稳定后电子在左右两个磁场区中的速度分别是 v 和 kv，对应半径成什么比例","why":"同一电子、同一磁感应强度下半径正比于速度，速度差 k 倍则半径差 k 倍","do":"分别写出右侧半径 r右=mv/(Be) 与左侧半径 r左=kmv/(Be)，比较两者","expr":"r_{\\text{左}}=kr_{\\text{右}}","cues":["左边速度是k倍","半径也差k倍","同一磁场同一电子"],"concepts":["轨道半径","速度比例"]},{"title":"每圈横向位移的几何","type":"几何关系","judge":"电子每完成一个完整循环，沿 cd 方向净前进多少，与两半径之差是什么关系","why":"电子在左右两半圆中偏转方向相反，一圈下来横向净位移等于两直径之差","do":"画出一个循环的轨迹，找出每圈净位移 2r右−2r左","expr":"\\Delta x=2r_{\\text{右}}-2r_{\\text{左}}","cues":["两半圆拼一圈","净走一段","直径相减"],"concepts":["圆周运动轨迹","几何位移"]},{"title":"圈数与边界距离匹配","type":"临界条件","judge":"从 P 到 d 的横向距离与每圈净位移、圈数 n 之间如何对应，n 是否必须为整数","why":"电子必须恰好落在边界 d 上，横向总位移等于 P 到 d 的距离，且由整数个循环组成","do":"用 P 到 d 的距离等于 n 倍每圈净位移列式，解出 n","expr":"n(2r_{\\text{右}}-2r_{\\text{左}})=\\frac{1}{2}(R_2-R_1)","cues":["正好落到d","整数圈","总位移对得上"],"concepts":["边界条件","周期性运动"]},{"title":"周期与总时间","type":"数学处理","judge":"总时间用圈数乘周期，周期是否与速度无关、左右两段是否共用同一周期","why":"回旋周期 T=2πm/(Be) 只由 m、e、B 决定，与速度无关，故每圈时间相同","do":"写出 T=2πm/(Be)，用 t=nT 求总时间并代入 n","expr":"t=nT=\\frac{\\pi(R_2-R_1)}{2v(1-k)}","cues":["周期跟速度无关","一圈时间一样","圈数乘周期"],"concepts":["回旋周期","匀速圆周运动"]}],"684":[{"title":"电压不变的条件","type":"前提判断","judge":"判断距离变化时哪个量保持不变——是电压 U 还是极板电荷量 Q","why":"题设明确“两极板电压保持不变”，若误按孤立电容器电荷量不变处理，就会用 Q 不变去推 E，结论完全不同","do":"从题干中锁定“电压保持不变”，确认 U 为常量、d 为变量","expr":"U=\\text{const}","cues":["电压不变","不是电荷量不变","U固定"],"concepts":["电容器","电压"]},{"title":"场强随间距的变化","type":"关系建立","judge":"判断 d 减小时 E 按什么规律变化","why":"匀强电场中电势差与场强的关系为 E=U/d，U 不变时 E 与 d 成反比","do":"写出 E=U/d，由 d 减小推出 E 增大","expr":"E=\\frac{U}{d}","cues":["距离越小场越强","用电压除以间距","反比关系"],"concepts":["匀强电场","电场强度与电势差"]},{"title":"电场线方向读图","type":"图像读取","judge":"判断图中两极板间电场线的指向（由正极板指向负极板）","why":"电子受力方向由场强方向决定，而场强方向必须从图中极板极性/电场线箭头读出，不能凭感觉","do":"观察图中电场线箭头或极板标注，确定场强水平向左","expr":"","cues":["看箭头","电场线从正极到负极","图里向左"],"concepts":["电场线","极板极性"]},{"title":"负电荷受力反向","type":"结论整理","judge":"判断电子（负电荷）所受电场力与场强方向的关系","why":"负电荷受力方向与场强方向相反，若按正电荷处理就会把方向判反","do":"由场强水平向左，取反得电子受力水平向右","expr":"\\vec F=q\\vec E,\\ q<0","cues":["电子带负电","负电荷受力相反","向左的场向右的力"],"concepts":["电场力","负电荷"]}],"685":[{"title":"能级差对应光子能量","type":"前提判断","judge":"发光时释放的光子能量应取哪两个能级之差","why":"LED 发光是电子从高能级跃迁到低能级，释放的光子能量等于两能级能量差，题给能级差 2.20 eV 就是光子能量","do":"确认发光对应的是能级差而不是某一能级的绝对值，把 2.20 eV 定为光子能量 E","expr":"E=h\\nu=\\Delta E","cues":["能级差就是光子能量","不是取单个能级"],"concepts":["能级跃迁","光子能量"]},{"title":"电子伏换算成焦耳","type":"数学处理","judge":"用 eV 还是 J 代入普朗克常量计算","why":"h 的单位是 J·s，频率单位是 Hz，能量必须先统一为焦耳，否则量级全错","do":"把 2.20 eV 乘以 1.6×10⁻¹⁹ 换成焦耳，或直接采用题给的 3.52×10⁻¹⁹ J","expr":"E=2.20\\times1.6\\times10^{-19}\\ \\mathrm{J}\\approx3.52\\times10^{-19}\\ \\mathrm{J}","cues":["先换成焦耳","单位要统一"],"concepts":["电子伏","单位换算"]},{"title":"光子能量公式求频率","type":"关系建立","judge":"用哪个关系把能量和频率连起来","why":"光子能量与频率由 E=hν 联系，这是唯一把已知能量和待求频率挂钩的规律","do":"由 E=hν 解出 ν=E/h，代入 E 和 h 求值","expr":"\\nu=\\frac{E}{h}=\\frac{3.52\\times10^{-19}}{6.63\\times10^{-34}}\\ \\mathrm{Hz}","cues":["用光子能量公式","能量除以普朗克常量"],"concepts":["普朗克常量","光子能量"]},{"title":"结果量级核对","type":"结论整理","judge":"算出的频率数量级是否落在可见光范围","why":"LED 发光属可见光，频率应在 10¹⁴ Hz 量级，可用来排除量级错误的干扰项","do":"检查结果指数是否为 10¹⁴ 量级，与可见光频率范围比对","expr":"\\nu\\sim10^{14}\\ \\mathrm{Hz}","cues":["看数量级","可见光量级"],"concepts":["可见光","数量级估算"]}],"686":[{"title":"区分速度与位移概念","type":"前提判断","judge":"要判断题目问的'速度'是瞬时速度还是平均速度，'位移'是位置变化量还是路程","why":"位置—时间关系给出的是瞬时信息，速度由位置对时间求导得到；位移是末位置减初位置，与路程不同，混淆则结论全错","do":"明确速度对应位置函数的瞬时变化率，位移对应两时刻位置坐标之差","expr":"v=\\frac{dx}{dt},\\quad \\Delta x=x(t_2)-x(t_1)","cues":["速度是瞬时还是平均","位移不是路程","位置变化量"],"concepts":["瞬时速度","位移","位置坐标"]},{"title":"由位置式求瞬时速度","type":"关系建立","judge":"要判断能否对位置函数求导得到速度随时间的变化关系","why":"匀变速直线运动的位置式为二次函数，其导数是一次函数，对应速度随时间线性变化","do":"对 x=1+2t+3t² 关于 t 求导，得速度表达式","expr":"v=\\frac{dx}{dt}=2+6t","cues":["对时间求导","速度随时间变","二次求导变一次"],"concepts":["导数","瞬时速度","匀变速直线运动"]},{"title":"位移用坐标差而非路程","type":"模型选择","judge":"要判断 1 s 内位移应取末位置减初位置，而不是把各段路程相加","why":"位移是矢量，只由初末位置决定；本题运动方向不变，但概念上仍须用坐标差计算","do":"分别代入 t=0 和 t=1 求位置坐标，再作差","expr":"\\Delta x=x(1)-x(0)","cues":["末位置减初位置","别算路程","只看首尾"],"concepts":["位移","位置坐标","矢量"]},{"title":"代入时刻算位置差","type":"数学处理","judge":"要判断初时刻位置不为零，位移不等于末位置坐标本身","why":"位置式含常数项 1，初位置为 1 m，若直接把 x(1) 当作位移就会多算 1 m","do":"算 x(0)=1 m、x(1)=6 m，作差得位移","expr":"\\Delta x=(1+2+3)-1=5\\ \\mathrm{m}","cues":["初位置不是零","常数项要减掉","末位置减初位置"],"concepts":["位移计算","代入求值"]}],"687":[{"title":"万有引力充当向心力","type":"模型选择","judge":"卫星做匀速圆周运动的向心力由什么力提供","why":"卫星只受月球万有引力，且轨道为圆，引力方向指向月心即向心方向，故必须用万有引力等于向心力建立方程，不能把重力或别的力当向心力","do":"对每个卫星写 G Mm/r² = m v²/r = m(4π²/T²)r","expr":"G\\frac{Mm}{r^{2}}=m\\frac{v^{2}}{r}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["引力当向心力","万有引力提供","指向月心"],"concepts":["万有引力定律","向心力","匀速圆周运动"]},{"title":"质量相同可约去","type":"前提判断","judge":"两卫星质量相同这一条件在求比值时起什么作用","why":"动能 E_k=½mv² 中含 m，周期与 m 无关；两星 m 相同，求动能比时 m 直接约掉，比值只由 v 或 r 决定，不必知道 m 的具体值","do":"在动能比和周期比中把相同的 m 消去，只保留 r 的比值","expr":"\\frac{E_{k1}}{E_{k2}}=\\frac{v_{1}^{2}}{v_{2}^{2}},\\quad \\frac{T_{1}}{T_{2}}=\\text{仅由 }r\\text{ 决定}","cues":["质量约掉","m相同","不用管质量"],"concepts":["动能","比值消元"]},{"title":"由引力式导出速度与半径关系","type":"关系建立","judge":"线速度 v 随轨道半径 r 增大是变大还是变小","why":"由 G Mm/r² = m v²/r 得 v²=GM/r，v 与 √r 成反比，半径越大速度越小，这是判断动能比方向的关键","do":"从向心力方程解出 v²=GM/r，再代入动能比","expr":"v^{2}=\\frac{GM}{r}\\Rightarrow \\frac{E_{k1}}{E_{k2}}=\\frac{r_{2}}{r_{1}}","cues":["半径大速度小","速度平方反比","先解速度"],"concepts":["线速度","黄金代换"]},{"title":"由引力式导出周期与半径关系","type":"关系建立","judge":"周期 T 随轨道半径 r 增大是变大还是变小，是几次方关系","why":"由 G Mm/r² = m(4π²/T²)r 得 T²=4π²r³/(GM)，T 与 r^{3/2} 成正比，开普勒第三定律也给出同样结论，指数写错比值就错","do":"从向心力方程解出 T² 正比于 r³，再开方求周期比","expr":"T^{2}=\\frac{4\\pi^{2}r^{3}}{GM}\\Rightarrow \\frac{T_{1}}{T_{2}}=\\sqrt{\\frac{r_{1}^{3}}{r_{2}^{3}}}","cues":["周期看三次方","开普勒第三定律","开根号别忘"],"concepts":["周期","开普勒第三定律"]},{"title":"比值方向与开方处理","type":"数学处理","judge":"动能比取 r₂/r₁ 还是 r₁/r₂，周期比开方后指数是否正确","why":"动能与 r 成反比、周期与 r^{3/2} 成正比，方向弄反或漏开方都会选到干扰项","do":"把两式写成 r₁、r₂ 的幂次形式，核对分子分母与指数","expr":"\\frac{E_{k1}}{E_{k2}}=\\frac{r_{2}}{r_{1}},\\quad \\frac{T_{1}}{T_{2}}=\\left(\\frac{r_{1}}{r_{2}}\\right)^{3/2}","cues":["别把比倒过来","指数是二分之三","核对分子分母"],"concepts":["比值运算","幂运算"]}],"688":[{"title":"流量转质量流量","type":"关系建立","judge":"要判断每秒流下的水体积如何换算成每秒流下的水的质量","why":"流量 Q 是体积流量，重力势能公式里用的是质量，必须用密度把体积流量换成质量流量","do":"写出每秒落下的水质量 m/Δt = ρQ，代入 ρ=1.0×10³ kg/m³、Q=10 m³/s","expr":"\\frac{m}{\\Delta t}=\\rho Q","cues":["流量是体积","乘密度换质量","每秒十吨水"],"concepts":["体积流量","密度","质量"]},{"title":"取时间微元算势能","type":"模型选择","judge":"要判断用哪一段水、以什么时间基准来算重力势能的减少量","why":"功率是能量对时间的比值，必须取 Δt 时间内落下的那部分水，其下降高度为 h，才能把势能变化与时间对应起来","do":"取 Δt 内落下的水为研究对象，其重力势能减少量为 ΔE_p = ρQΔt·g·h","expr":"\\Delta E_p=\\rho Q\\Delta t\\,g h","cues":["取一段时间的水","整段水下降","用高差算势能"],"concepts":["重力势能","时间微元","功率定义"]},{"title":"效率只取七成","type":"前提判断","judge":"要判断重力势能减少量是否全部变成电能","why":"题设给出能量转化效率 70%，只有这部分势能转化为电能，不乘效率会把功率算大","do":"把势能减少量乘以 70% 得到电能，再除以 Δt 得电功率","expr":"P=\\frac{\\Delta E_p}{\\Delta t}\\times 70\\%","cues":["效率要乘","只有七成变电","不能全算成电"],"concepts":["能量转化效率","电功率"]},{"title":"合成功率表达式","type":"数学处理","judge":"要判断把质量流量、高度、效率组合成单一功率表达式后如何估算数量级","why":"P = ηρQg h 中各项数量级差别大，需先合并再估算，才能与选项的量级对上","do":"合并得 P = ηρQg h，代入 η=0.7、ρ=10³、Q=10、g≈10、h=150 估算","expr":"P=\\eta\\rho Q g h","cues":["先合并再算","估数量级","十的七次方"],"concepts":["功率公式","数量级估算"]}],"689":[{"title":"从波形图读周期","type":"图像读取","judge":"从反射信号的波形图上读出相邻同相点（如两个波峰）之间的时间间隔，确定超声波的周期","why":"周期是求波长的唯一途径，读错横轴标度或把半周期当周期，后面波长、相位差全错","do":"在信号图上取相邻两个波峰（或两个波谷）的横坐标之差，结合横轴单位换算成秒","expr":"T=2\\times10^{-7}\\,\\mathrm{s}","cues":["看相邻波峰","横轴一格多少","别把半波当周期"],"concepts":["周期","波长","波的图像"]},{"title":"波速定波长","type":"关系建立","judge":"判断用哪个波速和哪个周期组合求介质中的波长","why":"波长由介质中波速与波源周期共同决定，λ=vT 是联系时间信息与空间信息的桥梁","do":"用机翼材料中的声速乘以读出的周期，算出波长","expr":"\\lambda=vT=1.26\\times10^{-3}\\,\\mathrm{m}","cues":["先算波长","用材料中的声速"],"concepts":["波长","波速","频率"]},{"title":"时间差对应双程路程","type":"几何关系","judge":"判断两反射信号的时间差对应的是声波往返缺陷的额外路程，即 2d 而非 d","why":"探头接收的是反射波，声波要从表面下行到缺陷再返回，缺陷深度对应单程，路程差是深度的两倍","do":"读出两信号到达探头的时间差，用 Δs=vΔt 求路程差，再除以 2 得缺陷深度","expr":"2d=v\\Delta t,\\quad d=\\frac{v\\Delta t}{2}","cues":["反射是往返","路程差是深度的两倍","别忘除以二"],"concepts":["反射","路程差","回声测距"]},{"title":"路程差折合波长判叠加","type":"临界条件","judge":"判断路程差是波长的整数倍还是半波长的奇数倍，从而确定两反射信号在探头处是加强还是减弱","why":"相干波叠加的加强与减弱由路程差与半波长的倍数关系决定，必须把路程差化成 λ 的倍数再判断奇偶","do":"把 2d 除以波长，写成含半波长的倍数形式，看是半波长的奇数倍还是整数倍","expr":"2d=\\frac{15}{2}\\lambda=(2k+1)\\frac{\\lambda}{2}","cues":["化成波长的倍数","看是半波长的奇数倍","奇数倍就减弱"],"concepts":["波的干涉","振动减弱","半波长"]}],"690":[{"title":"载流子面密度的电流表达","type":"关系建立","judge":"电流 I 与面密度 n、漂移速率 v、宽度 b 之间是什么关系","why":"n 定义为每平方米载流子数，是二维面密度而非体密度，故电流应写成 I=nevb（不含厚度），若误用体密度 nd 就会多出未知厚度","do":"取时间 t 内通过横截面的电荷量 q=nevtb，再由 I=q/t 得 I=nevb","expr":"I=nevb","cues":["面密度不是体密度","宽度乘进去","别带厚度"],"concepts":["电流微观表达式","面密度"]},{"title":"霍尔电场与磁场方向匹配","type":"几何关系","judge":"稳定时洛伦兹力与电场力平衡时，电压 U 对应的是哪一维长度","why":"磁场垂直样品表面，电子沿长度 a 方向漂移，偏转沿宽度 b 方向，故霍尔电场沿 b，U=Eb；若把 U 对应 a 则结果差一个 a/b 因子","do":"写出电场力与洛伦兹力平衡 evB=eU/b，确认 U 是宽度 b 两端的电压","expr":"evB=e\\frac{U}{b}","cues":["电压在宽度两端","沿宽方向偏转","别用长度a"],"concepts":["洛伦兹力","霍尔效应","电场力平衡"]},{"title":"消去速率得 U-B 线性关系","type":"数学处理","judge":"如何把含未知 v 的两个方程化为 U 与 B 的正比式","why":"v 不可测，必须由电流式解出 v=I/(neb) 代入平衡式，才能得到只含可测量 U、B 和待求 n 的关系","do":"将 v=I/(neb) 代入 U=vBb，整理得 U=(I/(ne))B","expr":"U=\\frac{I}{ne}B","cues":["消掉漂移速度","U正比于B","斜率含n"],"concepts":["联立方程","正比关系"]},{"title":"从图像读斜率求面密度","type":"图像读取","judge":"U-B 图线的斜率对应哪个物理量组合，读数取哪两点","why":"由 U=(I/ne)B 知斜率 k=I/(ne)，只有取图线斜率而非某一点坐标才能求出 n","do":"在图(b)直线上取两点算斜率 k=88×10⁻³/320×10⁻³ V/T，再由 n=I/(ke) 求值","expr":"k=\\frac{I}{ne},\\quad n=\\frac{I}{ke}","cues":["取斜率不取单点","两点求斜率","斜率等于I比ne"],"concepts":["图像斜率","数据处理"]}],"691":[{"title":"光路元件顺序","type":"前提判断","judge":"光具座上各元件的排列顺序是否与实验光路一致","why":"双缝干涉需先由光源经透镜会聚、滤光片选单色光、单缝形成线光源，再经双缝分成相干光，顺序错了光路不成立","do":"按光传播方向依次核对光源、透镜、滤光片、单缝、双缝、遮光筒、测量头的排列","expr":"","cues":["按光走的方向排","单缝在双缝前","滤光片放最前"],"concepts":["光路","双缝干涉"]},{"title":"透镜与单缝作用","type":"模型选择","judge":"透镜和单缝各自在光路中起什么作用","why":"透镜只改变光束的会聚程度使光更集中，单缝则把点光源变成线光源，二者功能不能混淆","do":"分别指出透镜的会聚作用和单缝获得线光源的作用","expr":"","cues":["透镜聚光","单缝出线光源","别把作用弄反"],"concepts":["会聚","线光源"]},{"title":"条纹间距与双缝间距","type":"关系建立","judge":"双缝间距变化时条纹间距如何变化、观察到的条纹数目如何变化","why":"由条纹间距公式，间距与双缝间距成反比，间距越大同样视场内条纹越密、数目越多","do":"用条纹间距公式比较双缝间距减小前后的条纹间距，再判断视场内条纹数目","expr":"$\\Delta x=\\frac{L}{d}\\lambda$","cues":["间距反比","缝距小条纹宽","条纹少说明间距大"],"concepts":["条纹间距","双缝间距"]}],"692":[{"title":"杆上受力方向判定","type":"模型选择","judge":"甲沿杆运动时，库仑斥力、重力、摩擦力各自沿杆的方向如何取正负","why":"甲、乙带同种电荷互相排斥，甲在乙上方（x>0），斥力沿杆向上；重力向下；摩擦力总与相对运动方向相反，故上升、下降两段摩擦力方向不同","do":"以沿杆向下为正方向，分别写出甲下降段和上升段的合力表达式","expr":"F_{下}=mg-f-\\frac{kQq}{x^{2}},\\quad F_{上}=mg+f-\\frac{kQq}{x^{2}}","cues":["斥力向上","摩擦力反向","下降和上升不一样"],"concepts":["库仑定律","滑动摩擦力","受力分析"]},{"title":"最大速率位置判据","type":"临界条件","judge":"速率最大对应加速度为零还是合力最大","why":"由牛顿第二定律，加速度为零时速度达到极值；此处合力由向下转为向上，速度由增转减","do":"令下降段合力为零，解出该位置坐标","expr":"mg=f+\\frac{kQq}{x^{2}}\\Rightarrow x=\\sqrt{\\frac{kQq}{mg-f}}","cues":["加速度为零","合力为零","速度最大处"],"concepts":["牛顿第二定律","临界状态"]},{"title":"用动能定理求最低点","type":"关系建立","judge":"从释放到最低点，哪些力做功、电势能变化如何计入","why":"最低点速度为零，动能变化为零；重力做正功、摩擦力做负功、电场力做功等于电势能减少量","do":"对释放点到最低点列动能定理，把电势能差用电势能公式代入","expr":"(mg-f)(x_{0}-x)-\\left(\\frac{kQq}{x}-\\frac{kQq}{x_{0}}\\right)=0","cues":["初末都静止","电场力做负功","电势能变化"],"concepts":["动能定理","电势能"]},{"title":"停留位置的静摩擦范围","type":"临界条件","judge":"甲最终停在某处时，静摩擦力能否平衡重力和库仑斥力的合力","why":"最大静摩擦力等于滑动摩擦力 f，静摩擦可在 ±f 内取值，故要求剩余合力不超过 f","do":"写出平衡条件并取静摩擦的上下限，解出 x 的允许区间","expr":"mg-f\\le\\frac{kQq}{x^{2}}\\le mg+f","cues":["静摩擦有范围","停在哪儿都行吗"],"concepts":["静摩擦力","平衡条件"]},{"title":"返回条件与能量联立","type":"临界条件","judge":"在最低点能否返回，取决于该点合力是否向上且足以克服最大静摩擦","why":"返回要求最低点处库仑斥力大于重力与最大静摩擦之和；再与动能定理联立，把最低点位置消去，化为对初始电势能的限制","do":"先写最低点返回的临界不等式，再与动能定理方程联立消去 x","expr":"\\frac{kQq}{x^{2}}>mg+f,\\quad E_{p0}<(mg-f)\\sqrt{\\frac{kQq}{mg+f}}","cues":["最低点要能弹回","斥力要够大","和动能定理联立"],"concepts":["临界条件","动能定理","电势能"]}],"693":[{"title":"判断线性区间随质量变化","type":"图像读取","judge":"比较甲、乙两条图线，判断小车质量增大后哪一段仍保持直线、哪一段开始弯曲","why":"图线斜率反映 1/(M+m)，质量越大，钩码重力增大时 m 相对 M 的影响越小，直线部分能延伸到更大的 F","do":"在图(b)中沿横轴比较甲、乙两线保持直线的 F 范围，以及开始偏离直线的 F 位置","expr":"","cues":["看直线段长短","质量大的线更直","弯曲点往右移"],"concepts":["a-F 图像","线性区间","系统误差"]},{"title":"明确横轴 F 的真实含义","type":"前提判断","judge":"判断图像横轴用的是钩码重力 mg 还是绳对小车的真实拉力","why":"实验中直接测量并记录的是钩码重力 F=mg，而绳的拉力 T 并不等于 mg，二者之差随 m 增大而增大，这正是图线弯曲的根源","do":"对照题干中 F 的定义，确认作图时横坐标取的是钩码所受重力而非绳的拉力","expr":"F=mg","cues":["横轴是钩码重力","不是绳子拉力","F是钩码的重"],"concepts":["钩码重力","绳的拉力","合外力"]},{"title":"隔离钩码与小车列方程","type":"关系建立","judge":"判断求 a 与 F 关系时必须分别对钩码和小车用牛顿第二定律，而不能直接把 F 当作小车所受合力","why":"钩码本身也在加速下落，重力 mg 要提供自身加速度，绳的拉力小于 mg；只有把两者分开列式才能得到含 m 的准确关系","do":"对钩码写 F−T=ma，对小车写 T=Ma，消去 T 得到 a 与 F、M、m 的关系","expr":"F-T=ma,\\quad T=Ma\\ \\Rightarrow\\ a=\\frac{F}{M+m}","cues":[],"concepts":[]},{"title":"取 m 远小于 M 的近似","type":"近似条件","judge":"判断在什么条件下分母 M+m 可以近似为 M，从而使 a 与 F 成正比","why":"只有钩码质量远小于小车质量时，钩码自身加速所需的那部分重力才可忽略，绳的拉力才近似等于钩码重力","do":"在 a=F/(M+m) 中比较 m 与 M 的大小，说明 m≪M 时 M+m≈M","expr":"m\\ll M\\ \\Rightarrow\\ a\\approx\\frac{F}{M}","cues":["远小于","的近似"],"concepts":[]},{"title":"由数据外推质量趋于无穷","type":"结论整理","judge":"根据甲、乙、丙三组质量递增的图线趋势，推断线性区间随 M 增大而扩展的极限情形","why":"M 越大，满足 m≪M 的钩码质量范围越宽，图线保持直线的 F 区间越长，极限情况下整个区间都线性","do":"对比 M₁、M₂、M₃ 对应的线性区间长度，外推到 M 很大时的情形并给出解释","expr":"","cues":["质量越大越接近正比","小车质量远大于钩码","极限是质量很大"],"concepts":["极限外推","正比关系","近似条件"]},{"title":"描点连线取平滑拟合","type":"数据处理","judge":"判断第 6 至 8 组数据点如何描、图线丙如何连接","why":"实验数据存在偶然误差，应让尽可能多的点落在平滑曲线上，其余点均匀分布在两侧，而不能折线连接或强行过每一点","do":"按表中 F、a 数值在坐标系中描出第 6、7、8 点，用平滑曲线延伸图线丙并使其通过或贴近多数数据点","expr":"","cues":["平滑曲线","点均匀分布两侧","不要折线连"],"concepts":["描点作图","平滑拟合","偶然误差"]}],"694":[{"title":"电流表内接还是外接","type":"模型选择","judge":"电流表内阻已知时，应选内接法还是外接法","why":"电流表内阻已知，内接时可由 R测=Rx+RA 精确扣除，消除系统误差；外接时电压表分流大小未知，无法修正","do":"比较电流表内阻与待测水柱电阻的数量级，判断分压/分流误差能否修正，确定接法","expr":"R_x=R_测-R_A","cues":["内阻已知就内接","外接电压表分流算不清","水电阻很大"],"concepts":["内接法","系统误差","电流表内阻"]},{"title":"电压表量程选择","type":"前提判断","judge":"电压表应选 3 V 还是 15 V 量程","why":"电源电动势只有 3 V，待测电压不会超过 3 V，选大量程会使指针偏转过小、读数误差大","do":"把电源电动势与两个量程比较，选使指针偏转超过满偏三分之一的量程","expr":"","cues":["电源才3伏","选小量程读数准","大量程指针偏太小"],"concepts":["量程选择","电表读数"]},{"title":"电阻定律建立斜率关系","type":"关系建立","judge":"R_x 与 l 图线斜率对应电阻率与截面积的什么组合","why":"水柱电阻满足 R=ρl/S，S 为电流垂直通过的截面，即宽 d 与高 h 的乘积，故 R 与 l 成正比，斜率为 ρ/(dh)","do":"写出 R=ρl/(dh)，与直线 R=kl 对比，解出 ρ 用 k、d、h 表示","expr":"R_x=\\rho\\frac{l}{dh}=kl,\\quad \\rho=kdh","cues":["截面是宽乘高","先写电阻定律"],"concepts":["电阻定律","电阻率","图像斜率"]},{"title":"由图像比较温度影响","type":"图像读取","judge":"同一长度下哪条图线电阻小，从而判断哪种水温更易导电","why":"电阻率越小导电性越好；R-l 图线斜率正比于电阻率，斜率小的对应电阻率小","do":"在相同 l 处比较甲、乙两图线的纵坐标（或比较斜率），找出电阻率较小的温度","expr":"k=\\frac{\\rho}{dh}","cues":["比斜率","同长度比电阻","斜率小电阻率小"],"concepts":["电阻率与温度","导电性"]},{"title":"水管电阻的截面换算","type":"几何关系","judge":"圆柱形水管的电阻该用哪个截面积和长度代入电阻定律","why":"电流沿管轴方向流动，导电截面积是圆管内孔面积 π(d0/2)²，长度即管长，不能沿用容器的 d、h","do":"写出 R=ρl_m/[π(d0/2)²]，与安全电流条件 U/R=I0 联立解 l_m","expr":"R=\\rho\\frac{l_m}{\\pi(d_0/2)^2},\\quad \\frac{U}{R}=I_0","cues":["截面换成圆面积","电流沿管子走","用安全电流定电阻"],"concepts":["电阻定律","圆面积","安全电流"]},{"title":"取高温电阻率并保留有效数字","type":"结论整理","judge":"设计水管长度时应取哪个温度下的电阻率，结果保留几位","why":"出水温度最高 65 ℃ 时水最易导电、漏电电流最大，是最不利工况，必须用 65 ℃ 的电阻率计算；题目要求两位有效数字","do":"从乙线（65 ℃）读出斜率算 ρ，代入求 l_m 后按两位有效数字取舍","expr":"l_m=\\frac{U\\pi d_0^2}{4\\rho I_0}","cues":["取最不利的高温","用乙线斜率","结果留两位"],"concepts":["最不利工况","有效数字","电阻率"]}],"695":[{"title":"识别各过程的热力学性质","type":"前提判断","judge":"要判断 AB、BC、CD、DA 四段各属于等温还是等容过程，以及每段对应哪个温度","why":"题设明确 AB、CD 为等温过程，BC、DA 为等容过程；等温段才能用玻意耳定律，等容段才能用查理定律，选错规律整题失效","do":"对照循环图，把四段过程与 T1、T2 两个恒温源对应起来，标出 A、B 同温还是 A、D 同温","expr":"","cues":["先看哪段等温","等容段压强随温度变","AB和CD是等温"],"concepts":["等温过程","等容过程","理想气体状态方程"]},{"title":"用等容段联系 A 与 D","type":"模型选择","judge":"要判断 A、D 两状态之间用哪条定律建立压强与温度的关系","why":"D→A 是等容过程，体积不变，压强与热力学温度成正比，查理定律适用","do":"对 D→A 段写查理定律，把 pA、T1 与 pD、T2 对应代入","expr":"\\frac{p_A}{T_1}=\\frac{p_D}{T_2}","cues":["体积不变用查理","A和D同体积","压强比等于温度比"],"concepts":["查理定律","等容变化"]},{"title":"用等温段联系 C 与 D","type":"模型选择","judge":"要判断 C、D 两状态之间用哪条定律建立压强与体积的关系","why":"C→D 是等温过程，温度不变，压强与体积成反比，玻意耳定律适用","do":"对 C→D 段写玻意耳定律，注意 C 的体积是 V2、D 的体积是 V1","expr":"p_C V_2=p_D V_1","cues":["温度不变用玻意耳","C和D同温度","压强乘体积不变"],"concepts":["玻意耳定律","等温变化"]},{"title":"分清 V1 与 V2 各属哪个状态","type":"几何关系","judge":"要判断 V1 是 A、D 状态的体积，V2 是 B、C 状态的体积，不能把两者对调","why":"BC、DA 为等容过程，同一等容线上体积相同；题给 V1 是状态 A 的体积，而待求 V2 是状态 B（即状态 C）的体积","do":"在循环图上把 V1 标在 A、D 一侧，把 V2 标在 B、C 一侧，再代入玻意耳定律","expr":"V_A=V_D=V_1,\\quad V_B=V_C=V_2","cues":["V1是A的体积","V2是B的体积","等容线上体积一样"],"concepts":["等容线","循环过程"]},{"title":"先求 pD 再回代求 V2","type":"数学处理","judge":"要判断两问的求解顺序：第二问的玻意耳定律中含未知的 pD，必须先由第一问解出 pD 才能求 V2","why":"C→D 的等温方程里同时出现 pD 和 V2 两个未知量，只有先借 D→A 的等容关系定出 pD，方程才可解","do":"先由查理定律解出 pD，再把 pD 代入玻意耳定律解出 V2","expr":"p_D=\\frac{T_2}{T_1}p_A,\\quad V_2=\\frac{p_D V_1}{p_C}","cues":["先求D的压强","pD是桥梁","两问有先后"],"concepts":["联立方程","状态参量"]}],"696":[{"title":"转椅稳定条件","type":"前提判断","judge":"转椅稳定时绳端 B 与圆盘边缘 A 是否同步绕同一竖直轴转动，从而角速度相同","why":"题设明确转椅稳定后角速度与圆盘角速度相等，这是把圆盘角速度与转椅圆周运动联系起来的唯一桥梁","do":"确认 B 点绕 O（或 O₁）做匀速圆周运动，其角速度等于圆盘角速度，向心加速度由绳拉力分量提供","expr":"","cues":["角速度相同","稳定后同步转","绕同一轴"],"concepts":["角速度","匀速圆周运动"]},{"title":"绳拉力分解方向","type":"模型选择","judge":"把绳拉力分解为沿圆周切向与沿半径（径向）两个分量，而不是沿绳与竖直方向随意分解","why":"转椅做匀速圆周运动，切向合力为零、径向合力提供向心力，只有按切向/径向分解才能同时用上这两个条件","do":"在图(a)中把 T 分解为沿 OB 半径方向的 Tcosα 与垂直 OB 的切向分量 Tsinα","expr":"T\\cos\\alpha=m\\omega_1^2 r_1,\\quad T\\sin\\alpha=f","cues":["沿半径和切线分","径向提供向心力","切向力平衡"],"concepts":["向心力","力的分解","匀速圆周运动"]},{"title":"摩擦力大小判断","type":"前提判断","judge":"转椅在雪地上滑动，摩擦力是滑动摩擦力，大小由正压力决定，与切向拉力大小无关","why":"转椅相对雪地滑动，动摩擦因数给定，故 f=μF_N；图(a)中竖直方向无加速度，F_N=mg","do":"写出 f=μmg，并把它与绳拉力的切向分量平衡","expr":"f=\\mu mg","cues":["滑动摩擦","正压力等于重力","摩擦力恒定"],"concepts":["滑动摩擦力","正压力","平衡条件"]},{"title":"空间投影分解","type":"几何关系","judge":"图(b)中绳拉力在水平面内的投影方向与 O₁B 半径方向的夹角是 β，需先把三维绳拉力投影到水平面再沿径向/切向分解","why":"绳倾斜后拉力有竖直分量，只有水平投影才提供向心力与切向平衡，而投影与半径的夹角由题给的 β 确定","do":"把 T′ 分解为竖直分量 T′cosθ 与水平分量 T′sinθ，再把水平分量沿 O₁B 径向与切向分解为 T′sinθcosβ 与 T′sinθsinβ","expr":"T_1=T'\\sin\\theta,\\quad T_2=T'\\cos\\theta","cues":["先投到水平面","再沿半径分","β是投影夹角"],"concepts":["空间力分解","投影","几何关系"]},{"title":"竖直方向正压力变化","type":"关系建立","judge":"绳拉力有竖直向上分量，使雪地正压力小于重力，摩擦力随之减小","why":"图(b)中绳倾斜，竖直方向无加速度，三力平衡 F_N+T′cosθ=mg，正压力不再等于 mg","do":"对转椅竖直方向列平衡方程，求出 F_N=mg−T′cosθ，再代入 f=μF_N","expr":"F_N+T'\\cos\\theta=mg","cues":["绳子往上提","正压力变小","摩擦力变小"],"concepts":["竖直方向平衡","正压力","滑动摩擦力"]},{"title":"联立消元求角速度","type":"数学处理","judge":"把径向向心力方程与切向摩擦平衡方程联立，消去未知拉力 T′，解出 ω₂","why":"两个方程含 T′ 与 ω₂ 两个未知量，只有消去 T′ 才能得到只含已知量的 ω₂ 表达式","do":"由切向方程得 T′sinθsinβ=μ(mg−T′cosθ)，解出 T′，再代入径向方程 T′sinθcosβ=mω₂²r₂","expr":"\\omega_2=\\sqrt{\\frac{\\mu g\\sin\\theta\\cos\\beta}{(\\sin\\theta\\sin\\beta+\\mu\\cos\\theta)r_2}}","cues":["消去拉力","两式联立","解出角速度"],"concepts":["牛顿第二定律","方程组求解","向心力"]}],"697":[{"title":"斜面下滑求入磁场速度","type":"关系建立","judge":"甲在斜面上受重力、支持力和摩擦力，需判断用动能定理还是牛顿定律加运动学求进入水平导轨的速度","why":"斜面上摩擦力做功与路径有关但位移可由高度和倾角换算，动能定理一步到位；斜面长度由 h/sinθ1 给出","do":"对甲从释放到进入水平导轨列动能定理，摩擦力项用 μ1m1gcosθ1·(h/sinθ1)","expr":"m_1gh-\\mu_1m_1g\\cos\\theta_1\\cdot\\frac{h}{\\sin\\theta_1}=\\frac12 m_1v_0^2","cues":["用动能定理","先求斜面长度","摩擦力做负功"],"concepts":["动能定理","摩擦力做功","斜面几何"]},{"title":"判断安培力方向与加速度","type":"前提判断","judge":"甲刚入磁场时，需判断回路感应电流方向及乙所受安培力方向，才能确定乙加速度方向","why":"由楞次定律定电流方向，再用左手定则判断安培力；安培力方向决定乙加速度方向，题目要求回答方向","do":"由甲向右切割磁感线定感应电流方向，对乙用左手定则判安培力，再用牛顿第二定律求大小","expr":"BI_0l=m_2a_{\\text{乙}0},\\quad I_0=\\frac{Blv_0}{2R}","cues":["先判电流方向","左手定则","安培力向右"],"concepts":["楞次定律","左手定则","安培力"]},{"title":"双杆系统动量守恒","type":"模型选择","judge":"两杆在磁场中运动时，需判断系统所受合外力是否为零，从而决定能否用动量守恒","why":"两杆所受安培力等大反向，系统合外力为零，动量守恒；若逐杆用牛顿定律会因变力无法求解","do":"对甲乙系统列动量守恒，求共速速度，作为后续所有速度计算的基准","expr":"m_1v_0=(m_1+m_2)v_{\\text{共}}","cues":["取整体","安培力是内力","动量守恒"],"concepts":["动量守恒","安培力","系统内力"]},{"title":"电荷量联系相对位移","type":"关系建立","judge":"需判断如何把安培力冲量转化为两杆相对位移，而不是各自位移","why":"安培力冲量 BIlt 中 It=q=BlΔx/2R，Δx 为两杆相对位移；只有相对位移才能与初始间距 d 建立联系","do":"对乙用动量定理，把冲量写成 q 的形式，再用电荷量公式换成相对位移 Δx","expr":"B\\bar Ilt=m_2v_{\\text{共}},\\quad q=\\frac{Bl\\Delta x}{2R}","cues":["冲量变电荷量","用相对位移","安培力冲量"],"concepts":["动量定理","电荷量","相对位移"]},{"title":"斜面上滑下滑分段求速度","type":"模型选择","judge":"乙在右侧斜面往返时，需判断上滑与下滑摩擦力方向不同，加速度不同，不能用一个加速度算全程","why":"上滑时重力分量与摩擦力同向，下滑时反向，加速度不同；但位移大小相等，用位移速度关系联立","do":"分别列上滑、下滑的牛顿第二定律和 2ax=v² 关系，用 x上=x下 联立求返回水平面速度","expr":"2a_{\\text{上}}x=v_{\\text{共}}^2,\\quad 2a_{\\text{下}}x=v_1^2","cues":["上滑下滑分开算","摩擦力反向","位移相同"],"concepts":["牛顿第二定律","匀变速运动","摩擦力方向"]},{"title":"由图b高度比定碰撞后速度","type":"图像读取","judge":"需判断图(b)中两次上升高度之比对应哪两个运动过程，从而反推碰撞后共同速度","why":"图(b)给出乙第一次单独上滑高度与碰后整体上滑高度之比 4.84，结合上滑加速度可反解碰后速度","do":"读出 x上=4.84x共上，对碰后整体列上滑加速度和位移速度关系，解出碰后共同速度 v","expr":"2a_{\\text{共上}}x_{\\text{共上}}=v^2,\\quad x_{\\text{上}}=4.84x_{\\text{共上}}","cues":["读高度比","碰后整体上滑","反推速度"],"concepts":["图像信息","完全非弹性碰撞","匀减速运动"]},{"title":"碰撞前后动量守恒定甲速度","type":"关系建立","judge":"需判断乙返回水平面时与甲碰撞前瞬间，系统动量是否守恒，并确定各速度正负","why":"水平导轨上无外力，碰撞前瞬间系统动量守恒；乙向左、甲向右，速度需带符号代入","do":"对乙返回最低点瞬间的甲乙系统列动量守恒，解出碰前甲的速度 v2","expr":"m_1v_2-m_2v_1=(m_1+m_2)v","cues":["带符号","碰前瞬间","动量守恒"],"concepts":["动量守恒","速度方向","完全非弹性碰撞"]},{"title":"两临界定d上下限","type":"临界条件","judge":"需判断 d 的最小值对应乙返回时恰好与甲相碰，最大值对应两者共速时恰好相碰","why":"d 越小甲越靠左越早被追上，d 越大越晚相碰；两个极端分别对应'刚返回即碰'和'共速才碰'","do":"对甲（或乙）在乙上斜期间用动量定理求相对位移 Δx1，再对返回后到共速过程求 Δx2，用位移关系 d-Δx=Δx1 和 d-Δx-Δx1=Δx2 定上下限","expr":"d_{\\min}'-\\Delta x=\\Delta x_1,\\quad d_{\\max}-\\Delta x-\\Delta x_1=\\Delta x_2","cues":["恰好相碰","共速时碰","两个极端"],"concepts":["临界条件","动量定理","相对位移"]}],"698":[{"title":"识别守恒定律","type":"前提判断","judge":"判断核反应方程中哪些量必须守恒，从而确定未知粒子 X 的质量数和电荷数","why":"核反应遵循质量数守恒和电荷数守恒，这是确定未知粒子的唯一依据","do":"对反应方程两边分别列出质量数之和与电荷数之和相等的等式","expr":"A_{左}=A_{右},\\quad Z_{左}=Z_{右}","cues":["质量数守恒","电荷数守恒","两边相等"],"concepts":["质量数守恒","电荷数守恒","核反应方程"]},{"title":"统计反应物总量","type":"关系建立","judge":"判断反应物一侧（碳-12 与氢-1）的总质量数和总电荷数各是多少","why":"守恒方程右侧包含 X 和两个氢-1，必须先把左侧总量算准才能反推 X","do":"把碳-12 和氢-1 的质量数、电荷数分别相加","expr":"A_{左}=12+1=13,\\quad Z_{左}=6+1=7","cues":["左边加起来","碳十二加氢一","先算反应物"],"concepts":["质量数","电荷数"]},{"title":"扣除已知产物","type":"数学处理","judge":"判断从总量中减去锂-7 和两个氢-1 后剩下的质量数与电荷数","why":"X 是方程中唯一未知的产物，其余产物的质量数和电荷数都已知","do":"用左侧总量减去锂-7 与两个氢-1 的质量数、电荷数之和","expr":"A=13-7-2\\times1=4,\\quad Z=7-3-2\\times1=2","cues":["减去已知产物","两个氢要乘二","剩下的给X"],"concepts":["质量数守恒","电荷数守恒"]},{"title":"对应元素符号","type":"结论整理","judge":"判断质量数为 4、电荷数为 2 的粒子对应哪种元素符号","why":"电荷数决定元素种类，质量数决定同位素，二者共同确定核素符号","do":"由 Z=2 查得元素为氦，写出核素符号","expr":"{}^{4}_{2}\\mathrm{He}","cues":["电荷数二就是氦","质量数四","氦四"],"concepts":["核素符号","元素序数"]}],"699":[{"title":"等势线疏密与场强关系","type":"关系建立","judge":"要判断等势线的疏密程度与电场强度大小的对应关系","why":"由 E=U/d，相邻等势线电势差相等时，间距越小场强越大，即等势线越密处场强越大","do":"把等势线疏密与场强大小建立对应：密则场强大，疏则场强小","expr":"E=\\frac{U}{d}","cues":["越密场强越大","看疏密","间距小场强大"],"concepts":["等势线","电场强度","电势差"]},{"title":"比较四点等势线疏密","type":"图像读取","judge":"要判断 a、b、c、d 四点中哪一处等势线最密集","why":"题目给出的是等势线分布图，只有直接比较各点附近相邻等势线的间距才能确定场强大小","do":"在图上分别观察四点附近相邻等势线的间距，找出间距最小（最密集）的位置","expr":"","cues":["看哪最挤","比间距","找最密处"],"concepts":["等势线分布","电场强度"]},{"title":"排除尖端附近误判","type":"前提判断","judge":"要判断是否因尖端放电而把场强最大点定在塔尖附近而非等势线最密处","why":"场强大小只由该点等势线疏密决定，尖端只是造成等势线密集的原因，不能凭位置直觉代替读图","do":"以图上实际等势线疏密为准，不凭尖端位置猜测","expr":"","cues":["别凭直觉","以图为准","尖端不一定最大"],"concepts":["尖端放电","等势线"]}],"700":[{"title":"定速度正方向","type":"图像读取","judge":"要判断 v-t 图中速度的正负号对应向上还是向下运动","why":"篮球由静止下落，初速度必与重力同向，图中起始段速度为负，故负值代表向下、正值代表向上","do":"看图像起点（t=0 附近）速度的正负，与下落方向对照","expr":"","cues":["先看初速度方向","负值代表下落","向上为正"],"concepts":["速度方向","v-t 图像"]},{"title":"速度为零即最高点","type":"关系建立","judge":"要判断篮球位置最高对应图像上哪一类时刻","why":"位置最高即位移最大处，此时速度由向上变为零再转为向下，v-t 图上表现为速度过零点","do":"在图中找出速度由正变负（或由负变正）穿过横轴的点，比较各点对应的速度符号变化","expr":"v=0 \\Rightarrow h \\text{ 取极值}","cues":["速度为零时最高","过横轴的点","看速度变号"],"concepts":["竖直上抛","速度与位移极值"]},{"title":"区分触地突变与过零点","type":"临界条件","judge":"要判断图中速度突变（折返）处是触地反弹，还是空中运动的普通点","why":"与地面碰撞时速度在极短时间内反向且大小改变，图像出现陡峭折线；空中只受重力，加速度恒为 g，图像为斜率固定的直线段","do":"找出图像中斜率突变、速度由负跳为正的位置，标为触地点，再看此后速度减小到零的点","expr":"a=-g\\ (\\text{空中}),\\quad \\Delta v\\ \\text{突变}\\ (\\text{触地})","cues":["折线处是落地","斜率变了就是撞地","反弹后速度变小"],"concepts":["碰撞","加速度","斜率"]},{"title":"比较反弹高度定最高点","type":"结论整理","judge":"要判断反弹后上升段中哪个速度为零的点对应位置最高","why":"每次反弹后上升的最大高度由该次反弹的初速度决定，初速度越大（v-t 图上升段与横轴围成的面积越大）上升越高","do":"比较各次上升段速度从反弹值减到零所围的面积，面积最大者对应最高位置","expr":"h=\\frac{v_0^2}{2g}","cues":["看上升段面积","反弹速度大升得高","比第一次反弹"],"concepts":["竖直上抛最大高度","v-t 图像面积"]}],"701":[{"title":"热量由有效值决定","type":"模型选择","judge":"求一个周期内的热量，该用电压的峰值还是有效值","why":"焦耳热 Q=U²T/R 中的 U 必须是有效值，峰值只反映瞬时最大值，直接代入峰值会算大","do":"对两个电阻都先求各自电压的有效值，再用 Q=U²T/R 比较","expr":"Q=\\frac{U^{2}}{R}T","cues":["用有效值","不能代峰值","先求有效值"],"concepts":["有效值","焦耳定律"]},{"title":"分段积分求脉冲有效值","type":"关系建立","judge":"三角形脉冲电压的有效值能否直接取峰值除以根号三","why":"峰值除以根号三是整周期都是三角波时的结论，本题前半周期是三角脉冲、后半周期为零，必须按有效值定义分段累加热量","do":"把一个周期分成有电压的 T/2 和电压为零的 T/2 两段，分别写出 U²T/R 再相加，令其等于 U₁²T/R","expr":"\\frac{U_1^{2}}{R}T=\\frac{(U_0/\\sqrt{3})^{2}}{R}\\cdot\\frac{T}{2}+0","cues":["分段算","后半周期是零","不能整体除根号三"],"concepts":["有效值定义","分段求和"]},{"title":"正弦电压有效值取峰值除根号二","type":"前提判断","judge":"图(b)的正弦电压有效值是否等于峰值除以根号二","why":"标准正弦交流电的有效值与峰值之比为 1:√2，这是正弦波特有的结论，不能套到三角脉冲上","do":"直接写出 U₂=U₀/√2，与脉冲电压的有效值区分开","expr":"U_2=\\frac{U_0}{\\sqrt{2}}","cues":["正弦取根号二","峰值比有效值","标准正弦"],"concepts":["正弦交流电","有效值"]},{"title":"同阻值下热量比化为电压平方比","type":"数学处理","judge":"两电阻完全相同、周期相同时，热量之比能否直接写成有效值平方之比","why":"Q=U²T/R 中 R 与 T 对两个电阻相同，可以约去，只剩有效值平方的比","do":"把 Q₁/Q₂ 化为 U₁²/U₂²，再代入两个有效值化简","expr":"\\frac{Q_1}{Q_2}=\\frac{U_1^{2}}{U_2^{2}}","cues":["电阻相同约掉","周期相同约掉","比电压平方"],"concepts":["热量比","控制变量"]}],"702":[{"title":"确定三个力的方向","type":"几何关系","judge":"要判断挡板支持力、弹簧拉力与竖直方向各成多大角度","why":"斜面倾角30°、挡板与斜面夹角60°，挡板法线与竖直方向夹角需由几何关系推出，角度错则分解全错","do":"画侧视图，由挡板与斜面夹角60°及斜面倾角30°推出挡板法线与竖直方向夹角为30°，弹簧拉力沿竖直方向","expr":"","cues":["先画侧视图","挡板法线怎么偏","角度是三十度"],"concepts":["几何关系","受力方向"]},{"title":"光滑球无摩擦","type":"前提判断","judge":"要判断球与斜面、挡板之间是否存在摩擦力","why":"题设明确球体光滑，故斜面与挡板对球只有法向支持力，不能多画摩擦力","do":"受力分析时只画重力、弹簧拉力、挡板支持力（斜面支持力为零或不存在），不添加摩擦力","expr":"","cues":["球是光滑的","不能加摩擦力","只有法向力"],"concepts":["光滑接触","弹力"]},{"title":"三力平衡正交分解","type":"关系建立","judge":"要判断用哪两个平衡方程把未知支持力与已知重力、拉力联系起来","why":"球静止，合力为零，竖直与水平方向分别列平衡方程才能解出挡板支持力","do":"沿水平、竖直方向分解，水平方向两支持力分量相互抵消，竖直方向分量与拉力之和等于重力","expr":"F_N\\sin30^\\circ=F\\sin30^\\circ,\\quad F_N\\cos30^\\circ+F\\cos30^\\circ+T=mg","cues":["列平衡方程","水平竖直分开","合力为零"],"concepts":["共点力平衡","正交分解"]},{"title":"拉力小于重力","type":"结论整理","judge":"要判断弹簧拉力方向向上且其大小1.0 N小于重力2.0 N，剩余由支持力补足","why":"重力mg=2.0 N大于拉力1.0 N，说明支持力的竖直分量必须向上补足差额，据此确定方程符号","do":"计算重力mg并与拉力比较，确认竖直方向支持力分量与拉力同向叠加等于重力","expr":"mg=2.0\\,\\mathrm{N}>T=1.0\\,\\mathrm{N}","cues":["重力是两牛","拉力只有一牛","支持力要补上"],"concepts":["重力","弹簧测力计读数"]}],"703":[{"title":"投影运动性质","type":"模型选择","judge":"光点在感光纸上的运动是简谐振动还是别的运动","why":"轻杆匀速转动，光点竖直投影到水平纸上的位移随转角按正弦规律变化，是简谐振动；不识别这一点就无法用振幅、周期、路程的简谐规律","do":"把光点竖直投影位置写成随转角的正弦函数，确认是简谐振动","expr":"x=A\\sin\\omega t","cues":["投影是简谐","匀速圆周的投影","先看运动性质"],"concepts":["简谐振动","匀速圆周运动"]},{"title":"振幅等于杆长","type":"几何关系","judge":"简谐振动的振幅由什么几何量决定","why":"光点竖直投影的最大偏离量等于轻杆长度，即圆周半径","do":"取振幅为杆长，读出 A=0.1 m","expr":"A=L=0.1\\,\\mathrm{m}","cues":["振幅就是杆长","半径即振幅"],"concepts":["振幅","几何投影"]},{"title":"转速换算圆频率","type":"关系建立","judge":"转速 r/min 如何换算成圆频率","why":"圆频率与转速的关系为 ω=2πn，且需先把 r/min 化为 r/s","do":"把 12 r/min 化为 0.2 r/s，再乘 2π","expr":"\\omega=2\\pi n=2\\pi\\times0.2=0.4\\pi\\,\\mathrm{rad/s}","cues":["先换成每秒","转每分要除六十","乘二派"],"concepts":["圆频率","转速"]},{"title":"周期与路程换算","type":"数学处理","judge":"12.5 s 内走过几个周期、每周期路程是几个振幅","why":"简谐振动一个周期内路程为 4A，需先由周期算出经历的周期数","do":"由 T=1/n=5 s 得 12.5 s 为 2.5 个周期，再乘 4A","expr":"s=\\frac{12.5}{5}\\times4A=1\\,\\mathrm{m}","cues":["一个周期走四个振幅","先算周期","数几个周期"],"concepts":["周期","路程","振幅"]}],"704":[{"title":"确定M到各电荷距离","type":"几何关系","judge":"M是正三角形中心，到顶点B、C的距离应取多少","why":"正三角形中心到顶点的距离是外接圆半径，等于边长的√3/3倍，不是边长的一半也不是高","do":"由边长a求中心到顶点的距离，作为库仑定律中的距离平方","expr":"r=\\frac{\\sqrt{3}}{3}a","cues":["中心到顶点","外接圆半径","三分之根号三"],"concepts":["正三角形几何","外接圆半径"]},{"title":"B、C在M的合场强","type":"关系建立","judge":"两个等量同号电荷在M点的场强如何矢量合成","why":"两电荷到M等距、电量相等，场强大小相等，夹角由几何决定，须按平行四边形定则合成而非直接相加","do":"分别写出单个电荷在M的场强，再按两矢量夹角合成","expr":"E_{BC}=2\\frac{kq}{(\\sqrt{3}a/3)^2}\\cos60^\\circ=\\frac{3kq}{a^2}","cues":["等大同号","矢量合成","夹角六十度"],"concepts":["点电荷场强","场强叠加"]},{"title":"由M点零场反推杆的场","type":"前提判断","judge":"M点合场强为零说明带电细杆在M点的场强与B、C的合场强是什么关系","why":"M点总场强为零，是三个带电体场强叠加的结果，故杆在M的场强必与两电荷合场强等大反向","do":"令杆在M的场强大小等于B、C在M的合场强，方向相反","expr":"E_{\\text{杆},M}=E_{BC}=\\frac{3kq}{a^2}","cues":["合场为零","等大反向","抵消"],"concepts":["场强叠加","平衡条件"]},{"title":"对称性迁移杆的场强","type":"模型选择","judge":"能否由杆在M点的场强直接得到杆在A点的场强","why":"细杆沿AM的中垂线对称放置，A与M关于该中垂线对称，故杆在A、M两点产生的场强大小相等、方向沿对称轴","do":"利用对称性把杆在M的场强大小搬到A点，并确定方向沿AM方向","expr":"E_{\\text{杆},A}=E_{\\text{杆},M}=\\frac{3kq}{a^2}","cues":["对称放置","中垂线对称","大小相等"],"concepts":["对称性","带电细杆场强"]},{"title":"A点三场强矢量合成","type":"关系建立","judge":"A点处杆的场强与B、C两电荷场强的方向关系，如何合成","why":"B、C在A的场强沿边方向、夹角60°，杆的场强沿AM方向，三者方向不同，必须按矢量分解合成","do":"写出B、C在A的场强，与杆的场强按方向合成求总大小","expr":"E_A=\\frac{3kq}{a^2}+2\\frac{kq}{a^2}\\cos30^\\circ=\\frac{kq}{a^2}(3+\\sqrt{3})","cues":["沿边方向","沿对称轴","矢量叠加"],"concepts":["点电荷场强","场强叠加"]}],"705":[{"title":"椭圆轨道快慢分段","type":"关系建立","judge":"从 C 经 B 到 D 这一段与从 D 经 A 到 C 这一段，哪段所用时间更长","why":"开普勒第二定律：近月点附近速度大、远月点附近速度小，故远月点一侧同样弧长耗时更长，C→B→D 的时间大于半个周期","do":"比较 A、B 两点速度大小，判断 C→B→D 与 D→A→C 两段的时间谁大于半周期","expr":"","cues":["近月点快","远月点慢","远月点那段更费时"],"concepts":["开普勒第二定律","椭圆轨道"]},{"title":"加速度只由距离定","type":"前提判断","judge":"比较 A、B 两点加速度时，能否直接用万有引力除以质量，而不必先求该点速度","why":"卫星在轨道上任一点只受万有引力，由牛顿第二定律 GMm/r²=ma 得 a=GM/r²，与速度大小无关","do":"对 A、B 两点分别写牛顿第二定律，把加速度之比化为到月心距离平方的反比","expr":"a=\\frac{GM}{r^{2}},\\quad \\frac{a_A}{a_B}=\\frac{r_B^{2}}{r_A^{2}}","cues":["只看距离","不用管速度","引力提供加速度"],"concepts":["牛顿第二定律","万有引力定律"]},{"title":"短轴端点速度沿切线","type":"几何关系","judge":"C、D 两点的速度方向是否沿椭圆切线，而不是垂直于该点与月心的连线","why":"做曲线运动的物体速度方向沿轨迹切线；椭圆短轴端点处切线并不垂直于该点与焦点的连线","do":"画出 C、D 处椭圆的切线方向，与 C、D 到月心的连线比较是否垂直","expr":"","cues":["速度沿切线","不是沿半径","短轴端点切线斜的"],"concepts":["曲线运动速度方向","椭圆几何"]},{"title":"发射速度的宇宙速度区间","type":"临界条件","judge":"鹊桥二号仍绕月球（随月球绕地球）运行，其发射速度应落在第一与第二宇宙速度之间","why":"发射速度达到第一宇宙速度才能离开地面成为地球卫星，未达到第二宇宙速度则仍被地球束缚，不会脱离地月系统","do":"把鹊桥二号的发射速度与 7.9 km/s、11.2 km/s 两个临界值比较","expr":"7.9\\ \\mathrm{km/s}<v<11.2\\ \\mathrm{km/s}","cues":["没飞出地球","比第一宇宙速度大","不到第二宇宙速度"],"concepts":["第一宇宙速度","第二宇宙速度","发射速度"]}],"706":[{"title":"初始弹簧状态","type":"前提判断","judge":"初始静止时弹簧是被压缩还是被拉伸","why":"活塞只受左侧气体向右的压力和弹簧弹力，二力平衡要求弹力向左，故弹簧压缩","do":"对初始活塞受力分析，比较气体压力方向与弹簧弹力方向","expr":"p_0 S = k\\Delta x","cues":["弹力向左","弹簧压缩","二力平衡"],"concepts":["二力平衡","弹力方向"]},{"title":"漏气后压强趋同","type":"关系建立","judge":"漏气后左右两侧压强如何变化、最终是否相等","why":"气体从高压左侧漏向真空右侧，左侧压强下降、右侧出现气体压强上升，缓慢过程最终两侧压强相等","do":"比较漏气前后左右压强，写出最终活塞平衡条件","expr":"p_L = p_R","cues":["漏气","压强变小","最终相等"],"concepts":["气体压强","平衡条件"]},{"title":"末态弹簧恢复原长","type":"临界条件","judge":"两侧压强相等时弹簧是否仍有形变","why":"活塞两侧压强相等则气体压力抵消，活塞只受弹簧力，重新静止必须弹簧力为零","do":"由末态活塞平衡判断弹簧形变量是否为零","expr":"p_L S - p_R S = k\\Delta x' = 0","cues":["压强相等","弹力为零","恢复原长"],"concepts":["平衡条件","弹簧形变"]},{"title":"体积与质量对应","type":"关系建立","judge":"活塞左移后左右两侧体积大小与质量大小的对应关系","why":"同种气体压强相等时密度相同，体积大的一侧质量大；活塞左移使左侧体积小于右侧","do":"比较末态左右体积，由等压等温下密度相同推出质量关系","expr":"m_L = \\rho V_L,\\ m_R = \\rho V_R,\\ V_L < V_R","cues":["活塞左移","左边体积小","质量小"],"concepts":["密度","气体质量"]},{"title":"绝热与弹性势能转化","type":"模型选择","judge":"汽缸绝热时内能变化由什么决定","why":"绝热无热交换，弹簧弹性势能减少转化为气体内能，故内能增加","do":"对气缸内气体与弹簧系统用热力学第一定律，取 Q=0","expr":"\\Delta U = W + Q = -\\Delta E_p > 0","cues":["绝热","无热交换","弹性势能减少"],"concepts":["热力学第一定律","内能","弹性势能"]},{"title":"分子数密度比较","type":"关系建立","judge":"初始左侧与最终左侧单位体积分子数的倍数关系","why":"气体总量不变，初始全部在左半容积，最终均匀占满整个汽缸，体积变为两倍","do":"用总分子数除以对应体积，比较初始左侧与最终左侧的数密度","expr":"n_0 = \\frac{N}{V_0},\\ n = \\frac{N}{2V_0}","cues":["充满整个汽缸","体积变两倍","数密度减半"],"concepts":["分子数密度","体积"]}],"707":[{"title":"确定粒子在磁场中的偏转方向","type":"前提判断","judge":"粒子从 A 沿 AD 方向进入磁场后，洛伦兹力使它向哪一侧偏转（朝 AB 边还是朝 CD 边）","why":"速度方向与磁场方向决定洛伦兹力方向，偏转方向决定轨迹圆心在哪一侧、能否与 ad 边相交，方向判断错则整条轨迹画反","do":"由速度沿 AD、磁场垂直纸面，用左手定则（或右手螺旋）定出受力指向，画出圆弧弯曲方向","expr":"","cues":["先定偏转方向","往哪边弯","左手定则"],"concepts":["洛伦兹力","左手定则"]},{"title":"无磁场区走直线","type":"模型选择","judge":"粒子进入 abcd 内部无磁场区后做什么运动，以及再次进入磁场时速度方向与穿出时是否相同","why":"无磁场区不受洛伦兹力，粒子做匀速直线运动，所以穿过 ad 边时的速度方向就是再次进入磁场时的入射方向，这是后续所有几何作图的前提","do":"把轨迹分成三段：外磁场圆弧—内部直线—外磁场圆弧，标出直线段与 ad、bc（或 cd）边的交点及方向","expr":"","cues":["中间走直线","速度方向不变","分三段画"],"concepts":["匀速直线运动","磁场边界"]},{"title":"用弦长与半径定几何关系","type":"几何关系","judge":"粒子在磁场中圆弧的弦（入射点与出射点连线）与半径、偏转角之间的几何约束，如何由正方形边长确定轨迹","why":"ABCD 边长固定、abcd 边长可调，粒子能否从 ad 穿出并由 BC 射出，取决于圆弧弦长与两正方形边长的几何匹配，必须由几何关系而非动力学方程求解","do":"设出射方向与 ad 边夹角，作出圆心，用弦长、半径和偏转角的关系列式，并与正方形边长比较","expr":"$L=2R\\sin\\dfrac{\\theta}{2}$","cues":["找圆心","弦长和半径","画几何图"],"concepts":["圆周运动","弦长","几何约束"]},{"title":"判断穿出 ad 后打到哪条边","type":"临界条件","judge":"粒子从 ad 边穿出后，直线段是打到 cd 边还是 bc 边再次进入磁场","why":"打到不同边意味着再次进入磁场的位置和方向不同，出射方向随之改变；这正是解析中分 45° 与 60° 两种情形讨论、并区分 B 与 D 的关键","do":"以穿出点为起点沿速度方向作射线，与 cd、bc 边的位置比较，判断先与哪条边相交","expr":"","cues":["看打到哪条边","先碰哪条边","分情况"],"concepts":["直线传播","边界交点"]},{"title":"判断能否垂直 BC 射出","type":"结论整理","judge":"由再次进入磁场时的位置与方向，判断末段圆弧在 BC 边处的速度方向是否垂直于 BC","why":"题目问的是由 BC 边射出时是否垂直，需把末段圆弧的圆心位置与 BC 边对照，只有特定入射方向才使出射速度沿 BC 法线","do":"对每种情形画出末段圆弧，检查出射点处半径是否平行于 BC 边（速度垂直于半径）","expr":"","cues":["看是否垂直射出","半径要平行BC","对照圆心"],"concepts":["圆周运动","速度方向"]}],"708":[{"title":"条纹间距的归属","type":"前提判断","judge":"表中 x1 与 x6 之间跨了几个条纹间距","why":"相邻亮纹间距 Δx 是双缝干涉公式中的量，x6−x1 是 5 个间距而不是 1 个","do":"用 (x6−x1)/5 分别算出两种光的相邻亮纹间距","expr":"\\Delta x=\\frac{x_6-x_1}{5}","cues":["除以五","第一条到第六条","五个间距"],"concepts":["双缝干涉","条纹间距"]},{"title":"由间距比波长","type":"关系建立","judge":"条纹间距大小与波长大小的对应方向","why":"双缝干涉中 Δx 与波长成正比，装置不变时比例系数相同","do":"比较两光的 Δx，Δx 大的对应波长大的光","expr":"\\Delta x=\\frac{L}{d}\\lambda","cues":["间距大波长大","成正比","装置没变"],"concepts":["双缝干涉","波长"]},{"title":"红绿光波长排序","type":"结论整理","judge":"红光与绿光谁波长更长","why":"可见光中红光波长大于绿光，这是判断单色光类别的唯一依据","do":"把算得的 Δx 大小关系与红绿波长顺序对照，定出单色光 1 的颜色","expr":"","cues":["红光大绿光小","红光波长最长","看颜色排序"],"concepts":["可见光波长"]},{"title":"同一位置释放","type":"实验操作","judge":"多次释放钢球时是否必须从斜槽同一高度静止释放","why":"只有初速度完全相同，各次印迹才落在同一条平抛轨迹上，描出的才是同一条曲线","do":"明确每次由静止在同一位置释放，保证平抛初速度相同","expr":"","cues":["同一高度","初速度要一样","从静止放"],"concepts":["平抛运动","控制变量"]},{"title":"平滑曲线连迹","type":"数据处理","judge":"印迹点应连成折线还是平滑曲线","why":"平抛轨迹是抛物线，是连续光滑曲线，逐点折线不能反映真实轨迹","do":"用平滑曲线描出经过（或贴近）各印迹点的轨迹","expr":"","cues":["连平滑曲线","不要连折线","描迹"],"concepts":["平抛轨迹","描点作图"]},{"title":"远点求初速度","type":"数据处理","judge":"取轨迹上哪一点代入平抛公式算初速度","why":"原点为抛出点，取离原点较远的点可减小坐标读数相对误差","do":"在轨迹上取一个较远点的坐标 (x, y)，联立 x=v0t 与 y=gt²/2 解出 v0","expr":"v_0=x\\sqrt{\\frac{g}{2y}}","cues":["取远一点","离原点远些","读坐标再算"],"concepts":["平抛运动","运动的分解"]}],"709":[{"title":"欧姆表笔极性判断","type":"前提判断","judge":"要判断欧姆挡测电阻时黑表笔接内部电源的正极还是负极，以及指针偏转大小对应二极管正向导通还是反向截止","why":"多用电表欧姆挡内部有电池，电流从黑表笔流出经外部元件回到红表笔，只有明确这一点才能由指针位置反推二极管的导通方向","do":"先明确黑表笔接内部电源正极，再比较两次测量中哪次指针偏转大（电阻小）对应正向导通，从而定出 M 端极性","expr":"","cues":["黑笔接正极","偏转大是导通","电阻小那次是正向"],"concepts":["欧姆表内部电源","二极管单向导电性"]},{"title":"分压接法的接线柱选择","type":"模型选择","judge":"要判断滑动变阻器采用分压式还是限流式接法，以及各导线应接到哪几个接线柱","why":"题目要求电压表和电流表读数从 0 开始，限流式接法电压不能调到零，只有分压式接法才能满足","do":"由“从 0 开始”确定分压式，把变阻器下端的两个固定接线柱与电源构成回路，测量支路一端接滑动触头所在的下接线柱、另一端接金属杆上的接线柱","expr":"","cues":["从零开始","必须分压","下端两柱接电源","另一根接金属杆"],"concepts":["分压式接法","限流式接法"]},{"title":"由伏安曲线判断阻值变化","type":"图像读取","judge":"要判断 I-U 图中哪条曲线对应强光，以及曲线斜率变化说明电阻增大还是减小","why":"光敏电阻阻值随光照增强而减小，在 I-U 图中同一电压下电流越大表示电阻越小，斜率越大电阻越小","do":"比较同一电压下三条曲线的电流大小定出强弱对应关系，再看曲线随光照增强斜率如何变化，由 R=U/I 判断阻值变化趋势","expr":"R=\\frac{U}{I}","cues":["同一电压比电流","斜率大电阻小","光越强电流越大"],"concepts":["伏安特性曲线","光敏电阻","电阻定义"]},{"title":"三极管导通条件的电压分配","type":"关系建立","judge":"要判断报警时三极管 b、e 间电压由哪两部分分压决定，以及光强增大时 R_G 减小会使 b、e 电压如何变化","why":"三极管基极电压取自 R_G 与 R_1 串联的分压，只有 b、e 间电压达到阈值三极管才导通、LED 才发光","do":"写出 R_G 与 R_1 串联的分压关系，分析光强增强时 R_G 减小导致 R_1 分压比例变化，判断 b、e 电压是升高还是降低","expr":"U_{be}=\\frac{R_1}{R_G+R_1}U","cues":["串联分压","光强增大阻值减小","看基极电压够不够"],"concepts":["串联分压","三极管导通条件"]},{"title":"调节可调电阻使报警生效","type":"临界条件","judge":"要判断报警光强下三极管未导通是因为 R_1 分压过小还是过大，从而确定 R_1 应增大还是减小","why":"报警时要求 b、e 电压恰好达到导通阈值，若此时仍未导通说明分到基极的电压不足，需改变 R_1 在串联电路中的分压比例","do":"在光强达到报警值、R_G 已减小的前提下，比较当前 b、e 电压与阈值，判断需提高 R_1 分压，故增大 R_1 阻值","expr":"","cues":["基极电压不够","让R1多分压","增大阻值"],"concepts":["分压比","临界导通"]}],"710":[{"title":"场强与电势差关系","type":"关系建立","judge":"匀强电场中沿电场方向两点间距离与电势差的关系，本题中 A、B 沿场强方向的距离是多少","why":"匀强电场中 U=Ed，d 必须是沿电场方向（竖直方向）的投影距离；A 为最低点、B 与 O 等高，A 到 B 的竖直高度差恰为半径 L","do":"找出 A、B 两点在竖直方向（电场方向）上的距离，代入 U=Ed 求 E","expr":"E=\\frac{U}{L}","cues":["沿电场方向量距离","竖直高度差是半径","不能拿弧长算"],"concepts":["匀强电场","电势差","场强"]},{"title":"A 点向心力方程","type":"关系建立","judge":"在最低点 A，沿半径方向的合力由哪些力提供、方向如何","why":"圆周运动最低点合力指向圆心（向上），电场力 qE 向上、重力 mg 向下，绳拉力为零时二者之差提供向心力","do":"沿竖直方向列 A 点的牛顿第二定律方程，令拉力 T=0","expr":"qE-mg=m\\frac{v_A^{2}}{L}","cues":["指向圆心列方程","电场力向上重力向下","拉力取零"],"concepts":["向心力","牛顿第二定律","电场力"]},{"title":"A 到 B 用动能定理","type":"模型选择","judge":"求两点速度关系时选什么规律：是逐段牛顿定律还是全程动能定理","why":"A 到 B 过程中电场力和重力都是恒力，且只关心速度大小，用动能定理可一步关联两速度，避开变力（绳拉力）做功","do":"写出 A 到 B 过程合外力做功等于动能增量，电场力做正功 qU、重力做负功 mgL","expr":"qU-mgL=\\frac{1}{2}mv_B^{2}-\\frac{1}{2}mv_A^{2}","cues":["恒力做功用动能定理","绳拉力不做功","电场力做正功"],"concepts":["动能定理","电场力做功","重力做功"]},{"title":"联立求两速度","type":"数学处理","judge":"两个方程含 v_A、v_B 两个未知量，如何消元得到各自表达式","why":"第一式给出 v_A 的平方，第二式给出 v_B 与 v_A 的平方差，直接代入即可，无需解二次方程","do":"由向心力式解出 v_A²，代入动能定理式求 v_B²，再开方取正根","expr":"v_A=\\sqrt{\\frac{qU-mgL}{m}},\\quad v_B=\\sqrt{\\frac{3(qU-mgL)}{m}}","cues":["先解出速度平方","再开方取正","两式联立消元"],"concepts":["联立方程","速度平方"]}],"711":[{"title":"切割有效长度的极值","type":"临界条件","judge":"OA 转到什么位置时切割磁感线的有效长度取最大、什么位置取最小","why":"感应电动势 E=Blv 中 l 是棒在磁场中切割的有效长度，OA 绕 O 转动时有效长度随方位变化，只有取到极值位置才能得到安培力的极值","do":"比较 OA 与细框对角线重合、与细框一边平行两种方位下的有效长度，取 l_max=√2L、l_min=L","expr":"l_{\\max}=\\sqrt{2}L,\\quad l_{\\min}=L","cues":["转到对角线","与边平行","有效长度变了"],"concepts":["动生电动势","有效切割长度"]},{"title":"转动棒的平均速度","type":"关系建立","judge":"OA 上各点速度不同，该用哪一点的速度（平均速度）代入 E=Blv","why":"OA 绕端点 O 匀速转动，各点线速度随半径线性变化，等效切割速度取中点速度 v=ωl/2","do":"对有效长度 l 的转动棒取其中点线速度作为平均切割速度，写出 E=Bl·(ωl/2)","expr":"E=Bl\\bar v=\\frac{1}{2}Bl^{2}\\omega","cues":["取中点速度","平均速度","角速度乘半径"],"concepts":["圆周运动线速度","动生电动势"]},{"title":"两棒安培力同电流关联","type":"模型选择","judge":"OA 回路与 CD 回路是否共用同一电流，CD 所受安培力该用哪个电流算","why":"导轨与细框通过导线串联成闭合回路，其余电阻不计，全回路电流处处相同，CD 的安培力由这个共同电流决定","do":"用闭合电路欧姆定律由 E 求 I=E/R，再对 CD 用 F=BIL（L 为导轨间距）","expr":"I=\\frac{E}{R},\\quad F=BIL=\\frac{B^{2}L^{2}\\omega l^{2}}{2R}","cues":["同一电流","串联回路","电阻只有R"],"concepts":["闭合电路欧姆定律","安培力"]},{"title":"最大最小安培力对应静止","type":"前提判断","judge":"CD 在安培力最大和最小时都恰好静止，说明静摩擦在两种情形下各取哪个方向的极限","why":"题设给出两种极端情形均恰好静止，说明两处静摩擦力都达到最大值，且方向相反（一个沿斜面向上、一个沿斜面向下）","do":"对 CD 分别列安培力最小时的平衡式和安培力最大时的平衡式，摩擦项取 ±μmgcosθ","expr":"mg\\sin\\theta-\\mu mg\\cos\\theta-F_{\\min}=0,\\quad F_{\\max}-mg\\sin\\theta-\\mu mg\\cos\\theta=0","cues":["恰好静止","摩擦反向","两个极限"],"concepts":["静摩擦最大值","共点力平衡"]},{"title":"联立求质量再求摩擦因数","type":"数学处理","judge":"两平衡式含 m 与 μ 两个未知量，如何消元得到 μ","why":"两式相加可消去 μ 先解出 m，再把 m 代回含 a 的牛顿第二定律式解 μ","do":"由两平衡式相加得 m，再对撤去推力瞬间列 F_max+μmgcosθ−mgsinθ=ma 解出 μ","expr":"m=\\frac{3B^{2}L^{3}\\omega}{4Rg\\sin\\theta},\\quad \\mu=\\frac{a}{g\\cos\\theta}-\\frac{\\tan\\theta}{3}","cues":["先求质量","两式相加","代回牛二"],"concepts":["牛顿第二定律","消元求解"]}],"712":[{"title":"人板系统水平动量守恒","type":"模型选择","judge":"机器人行走时，能否把机器人与 A 板（或与三块板整体）取作系统，用水平方向动量守恒求位移关系","why":"水平面光滑，系统水平方向不受外力；机器人靠摩擦力行走，摩擦力是内力，不改变系统水平总动量","do":"取机器人与 A 板为系统，初动量为零，写出位移关系 Mx=mx₁ 与 x+x₁=L_A","expr":"Mx=mx_1,\\quad x+x_1=L_A","cues":["取整体","水平没外力","人船模型"],"concepts":["动量守恒","人船模型","内力"]},{"title":"起跳过程水平动量守恒","type":"关系建立","judge":"机器人跳离 A 板瞬间，水平方向动量是否守恒，起跳速度的水平分量与 A 板反冲速度如何关联","why":"起跳时间极短，水平方向无外力冲量，机器人水平动量与 A 板动量等大反向","do":"对机器人跳离 A 板过程写水平动量守恒，把 A 板反冲速度用 vcosθ 表示","expr":"Mv\\cos\\theta=mv_A","cues":["起跳瞬间","水平动量守恒","板会反冲"],"concepts":["动量守恒","反冲","速度分解"]},{"title":"斜抛落点约束定速度","type":"关系建立","judge":"机器人从 A 右端落到 B 左端，水平位移与竖直飞行时间受什么约束，能否把 v 与 θ 的关系唯一确定","why":"斜抛运动水平匀速、竖直上抛，落回同一高度时飞行时间为 2vsinθ/g，水平位移等于两板间距","do":"写水平位移 vcosθ·t=x₁ 与 t=2vsinθ/g，联立消去 t 得 v² 关于 θ 的表达式","expr":"v\\cos\\theta\\cdot t=x_1,\\quad t=\\frac{2v\\sin\\theta}{g}","cues":["斜抛","落回同高度","水平位移定死"],"concepts":["斜抛运动","运动分解","飞行时间"]},{"title":"做功最少转化为求极值","type":"数学处理","judge":"起跳做功 W 随 θ 变化，如何把 W 写成单一变量的函数并找出最小值条件","why":"起跳做功等于机器人动能与 A 板反冲动能之和，v 又由落点条件约束为 θ 的函数，故 W 是 θ 的函数","do":"由能量关系写 W=½Mv²+½mv_A²，代入 v²(θ) 与 v_A，化为 tanθ 的函数，用均值不等式求极小","expr":"W=45\\left(\\frac{1}{2}\\tan\\theta+\\frac{2}{\\tan\\theta}\\right)","cues":["能量守恒","写成单变量","均值不等式"],"concepts":["功能关系","极值","动能"]},{"title":"跳上B后共速的动量守恒","type":"模型选择","judge":"机器人落到 B 上并与 B 相对静止时，应把机器人与 B、C 取整体，还是只与 B 取系统","why":"B、C 并排接触且水平面光滑，机器人落在 B 上时 B 会推 C 一起运动，三者水平方向动量守恒","do":"对机器人与 B、C 整体写水平动量守恒，求共同速度 v共","expr":"Mv\\cos\\theta=(M+2m)v_{\\text{共}}","cues":["B推着C走","取三者为整体","共速"],"concepts":["动量守恒","完全非弹性碰撞","整体法"]},{"title":"多次跳跃的位移关联","type":"关系建立","judge":"连续 3 次等间距跳跃中，每次跳跃的相对位移、B 板速度与总时间如何与“B 追上 A”的位移差挂钩","why":"每次跳跃机器人与 B 的相对位移为 L_B/3，且每次跳跃时间相同；B 追上 A 意味着两者总位移差等于初始间距加 A 的退行距离","do":"对每次跳跃写相对位移与动量守恒式，再对 3 次跳跃写 B 与 A 的位移差条件，联立求 Δt 与 L_B 关系","expr":"\\frac{L_B}{3}=(v_0+v_B)\\Delta t,\\quad (v_B-v_A)\\cdot3\\Delta t=x_1+x_A","cues":["等间距跳","相对位移","追上就是位移差"],"concepts":["相对运动","位移关系","匀速运动"]}],"713":[{"title":"判断加速度方向","type":"前提判断","judge":"减速下降时加速度方向朝上还是朝下","why":"速度向下而速率在减小，由加速度与速度反向可知加速度竖直向上","do":"比较速度方向与速度变化方向，定出加速度方向","expr":"","cues":["速度向下","越来越慢","加速度朝上"],"concepts":["加速度方向","减速运动"]},{"title":"超重失重的判据","type":"关系建立","judge":"由加速度方向判定返回舱处于超重还是失重","why":"加速度向上即超重，加速度向下即失重，这是超失重的唯一判据，与速度方向无关","do":"用加速度方向对照超重失重条件","expr":"","cues":["看加速度","不看速度","向上就超重"],"concepts":["超重","失重"]},{"title":"拉力做功正负","type":"关系建立","judge":"主伞拉力方向与位移方向夹角决定做功正负","why":"拉力沿运动反方向，力与位移夹角为钝角，做功为负","do":"比较拉力方向与返回舱位移方向","expr":"W=Fscos\\theta<0","cues":["伞往上拉","位移往下","做负功"],"concepts":["功的正负","力与位移夹角"]},{"title":"重力做功正负","type":"关系建立","judge":"重力方向与位移方向同向时做功的正负","why":"重力竖直向下，返回舱向下运动，二者同向，重力做正功","do":"比较重力方向与位移方向","expr":"W_G=mgh>0","cues":["往下落","重力也向下","做正功"],"concepts":["重力做功","正功"]}],"714":[{"title":"确定守恒定律","type":"前提判断","judge":"判断该人工核反应应使用哪条守恒定律来确定未知粒子","why":"核反应中质量数（核子数）守恒、电荷数守恒，这是确定未知核的唯一依据","do":"对反应式两端分别列出质量数之和与电荷数之和相等的方程","expr":"30+1=A_X+30,\\quad 14+1=Z_X+15","cues":["用质量数守恒","电荷数也要守恒","两个守恒一起用"],"concepts":["质量数守恒","电荷数守恒","核反应方程"]},{"title":"算出未知核参数","type":"数学处理","judge":"由守恒方程解出 X 的质量数与电荷数各是多少","why":"只有先得到 A 与 Z 的具体数值，才能对照粒子种类","do":"分别对质量数和电荷数作差，求出 A_X 与 Z_X","expr":"A_X=1,\\quad Z_X=0","cues":["质量数相减","电荷数相减","先算出来再对号"],"concepts":["质量数","电荷数"]},{"title":"由参数识别粒子","type":"结论整理","judge":"判断质量数为 1、电荷数为 0 的粒子对应哪种核素符号","why":"电荷数为 0 说明不带电，质量数为 1 说明是核子，二者共同唯一确定中子","do":"把 Z=0、A=1 与质子、中子、电子、α 粒子的参数逐一对照","expr":"{}^{1}_{0}\\mathrm{n}","cues":["电荷数为零","不带电的核子","是中子"],"concepts":["中子","核素符号"]}],"715":[{"title":"识别平抛运动模型","type":"模型选择","judge":"冲出平台后只受重力、初速度水平，应判断为什么运动模型","why":"初速度水平且不计空气阻力，只受重力，符合平抛运动条件","do":"把骑车人视为质点，将运动分解为水平匀速直线运动和竖直自由落体运动","expr":"","cues":["水平抛出","只受重力","分解成两个方向"],"concepts":["平抛运动","运动的分解"]},{"title":"水平方向求飞行时间","type":"关系建立","judge":"跨越河流的水平距离由哪个方向的运动决定，能否由此求出飞行时间","why":"水平方向不受力做匀速直线运动，水平位移等于河宽","do":"用水平位移等于河宽列式，解出飞行时间","expr":"x=v_0 t","cues":["水平方向匀速","河宽就是水平位移","先求时间"],"concepts":["匀速直线运动","水平位移"]},{"title":"竖直方向求高度差","type":"关系建立","judge":"两平台高度差由竖直方向的哪种运动规律决定","why":"竖直方向初速度为零、只受重力，做自由落体运动","do":"把已求出的时间代入自由落体位移公式求高度差","expr":"h=\\frac{1}{2}gt^2","cues":["竖直方向自由落体","初速度为零","用时间求高度"],"concepts":["自由落体运动","竖直位移"]}],"716":[{"title":"确定界面入射角","type":"几何关系","judge":"光线在 PQ 界面的入射角是相对 PQ 的法线量度，需要由正三角形的几何关系求出，而不是直接取 60° 或 30°","why":"入射角定义为入射光线与界面法线的夹角；正三角形内角为 60°，光线垂直 OP 射入后方向不变，与 PQ 的夹角为 60°，故与法线的夹角需由几何关系换算","do":"画出法线，利用正三角形内角 60° 与光线垂直 OP 的方向，求光线与 PQ 法线的夹角","expr":"C=60^\\circ","cues":["画法线","三角形内角六十度"],"concepts":["入射角","法线","正三角形几何"]},{"title":"判定恰好全反射","type":"临界条件","judge":"“恰好发生全反射”意味着入射角正好等于临界角，而不是大于或小于临界角","why":"题设“恰好在 PQ 界面发生全反射”给出临界状态，此时入射角等于临界角 C，才能用临界角公式求折射率","do":"把几何求出的入射角认定为临界角，建立临界角与折射率的关系","expr":"C=\\arcsin\\frac{1}{n}","cues":["恰好就是临界","入射角等于临界角","临界状态"],"concepts":["全反射","临界角"]},{"title":"用临界角公式求折射率","type":"关系建立","judge":"应使用 sinC=1/n 这一临界角与折射率的关系式，而不是用折射定律的 sin i/sin r","why":"光从玻璃射向空气发生全反射，临界角由玻璃相对空气的折射率决定，满足 sinC=1/n","do":"将 C=60° 代入 sinC=1/n，解出 n","expr":"\\sin 60^\\circ=\\frac{1}{n}\\Rightarrow n=\\frac{2\\sqrt{3}}{3}","cues":["用临界角公式","正弦等于折射率倒数","代入六十度"],"concepts":["全反射临界角","折射率"]}],"717":[{"title":"单扇门还是两扇门","type":"前提判断","judge":"位移 2 m 对应的是单扇门的运动，还是两扇门合计的间距","why":"题中明确说两扇门各移动 2 m，加速度描述的是每一扇门自身的运动，若把 2 m 当成两扇门共同走完的距离，位移就会用错","do":"锁定研究对象为一扇门，取其位移为 2 m","expr":"x=2\\,\\mathrm{m}","cues":["只看一扇门","各走两米","别把两米平分"],"concepts":["参考系","位移"]},{"title":"先加速后减速的对称性","type":"模型选择","judge":"加速段与减速段的时间、位移是否相等","why":"初末速度均为零、加速度大小相同，速度—时间图像是等腰三角形，两段必然对称","do":"把全程拆成两段等时等位移的匀变速过程，各占 2 s、各走 1 m","expr":"t_1=t_2=\\frac{4}{2}\\,\\mathrm{s}=2\\,\\mathrm{s}","cues":["两段对称","时间对半分","先加后减一样长"],"concepts":["匀变速直线运动","对称性"]},{"title":"用平均速度搭桥求最大速度","type":"关系建立","judge":"匀变速段的平均速度与最大速度是什么关系","why":"匀变速直线运动的平均速度等于初末速度的平均值，两段初末速度分别为 0 与 v、v 与 0，平均速度都是 v/2","do":"对整段用总位移等于平均速度乘总时间，解出最大速度","expr":"x=\\frac{v}{2}\\,t\\;\\Rightarrow\\;v=\\frac{2x}{t}","cues":["用总时间算","先求最大速度"],"concepts":["平均速度","匀变速直线运动"]},{"title":"由速度变化率求加速度","type":"关系建立","judge":"用哪一段的速度变化和时间求加速度大小","why":"加速度定义是速度变化量与所用时间之比，加速段从 0 到 v 用时 2 s","do":"取加速段，用最大速度除以该段时间","expr":"a=\\frac{v}{t_1}","cues":["用加速段算","速度除以时间","别用总时间4秒"],"concepts":["加速度","速度变化率"]}],"718":[{"title":"轨道半径的换算","type":"几何关系","judge":"万有引力定律中的距离该用月球半径还是轨道半径，轨道半径与 R、k 是什么关系","why":"引力提供向心力时，分母是嫦娥六号到月心的距离，即轨道半径，它等于月球半径加轨道高度，而题给的是高度与半径之比 k","do":"设月球半径为 R，把轨道高度写成 kR，轨道半径写成 (k+1)R，代入引力表达式","expr":"r=(k+1)R","cues":["高度就是半径","直接用k乘R","别忘了加月球半径"],"concepts":["轨道半径","万有引力"]},{"title":"向心力用周期表示","type":"关系建立","judge":"圆周运动向心力该用哪个形式，才能把已知周期 T 用上","why":"题目只给周期 T，不给线速度，只有用含 T 的向心力表达式才能把 T 引入方程","do":"写出向心力等于 m(4π²/T²)r，与引力表达式联立","expr":"G\\frac{Mm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["用周期写向心力","别用速度","把T带进去"],"concepts":["向心力","圆周运动周期"]},{"title":"密度用 M 与 R 表示","type":"关系建立","judge":"平均密度该用哪个体积公式，M 与 R 谁是待消去的中间量","why":"密度定义是质量除以体积，月球按球体处理，体积只由半径 R 决定，而 R 在联立后会被消掉","do":"写出球体体积 V=4πR³/3 和密度 ρ=M/V，把上一步解出的 M 代入","expr":"\\rho=\\frac{M}{\\frac{4}{3}\\pi R^{3}}","cues":["球体体积","质量除以体积","R最后会约掉"],"concepts":["密度","球体体积"]},{"title":"消去 R 得密度","type":"数学处理","judge":"联立后 R 能否完全消去，只剩 G、T、k 这些已知量","why":"题目没有给月球半径的数值，结果必须与 R 无关，否则无法得出确定值","do":"由引力方程解出 M 的表达式，代入密度式，约去 R³，整理成只含 k、T、G 的形式","expr":"\\rho=\\frac{3\\pi(1+k)^{3}}{GT^{2}}","cues":["R能约掉","只剩周期和k","整理成最简"],"concepts":["万有引力定律","密度公式"]}],"719":[{"title":"判断气体做何变化","type":"模型选择","judge":"油柱可自由移动、大气压不变时，罐内气体经历的是等压变化还是等容变化","why":"油柱受力平衡，罐内压强始终等于大气压，故为等压过程，必须用盖-吕萨克定律而非查理定律","do":"对油柱列压强平衡，确认 p 恒定，选定盖-吕萨克定律","expr":"\\frac{V_1}{T_1}=\\frac{V_2}{T_2}","cues":["油柱能滑动","压强不变","等压变化"],"concepts":["盖-吕萨克定律","等压变化","理想气体"]},{"title":"确定气体体积的算法","type":"关系建立","judge":"气体体积应算罐体积加吸管内被封闭的那段气柱体积，还是只算罐体积","why":"吸管与罐连通，油柱内侧到罐之间的气体都属于研究对象，体积随油柱位置改变","do":"写出 V=V罐+S·x，x 为油柱到罐口的距离，并代入初态 x=10 cm 求 V1","expr":"V=V_0+Sx,\\quad V_1=330+0.5\\times10=335\\,\\mathrm{cm^3}","cues":["要加吸管那段","体积会变","罐加管"],"concepts":["气体体积","连通容器"]},{"title":"温度换算为热力学温度","type":"前提判断","judge":"代入气体定律前是否必须把摄氏温度换成开尔文温度","why":"盖-吕萨克定律中的 T 是热力学温度，直接用摄氏度代入比例式会算错","do":"把 27 ℃ 换成 300 K，并在最后把结果换回摄氏度","expr":"T=t+273\\,\\mathrm{K}","cues":["先换成开尔文","不能直接用摄氏度","最后再换回来"],"concepts":["热力学温度","摄氏温度"]},{"title":"判断刻度是否均匀","type":"数学处理","judge":"T 与油柱位置 x 之间是线性关系还是非线性关系，从而判断等温差刻度间距是否相等","why":"由等压定律得 T 是 x 的一次函数，故 x 随 t 线性变化，刻度均匀","do":"把 V=V0+Sx 代入定律解出 T(x)，看 x 的系数是否为常数","expr":"T=\\frac{T_1}{V_1}(V_0+Sx)","cues":["看是不是一次函数","线性就均匀","斜率是常数"],"concepts":["线性关系","刻度均匀"]},{"title":"用管长定测量范围","type":"临界条件","judge":"油柱位置 x 取何值时对应可测温度的最高值和最低值","why":"吸管总长 20 cm，油柱只能在 0≤x≤20 cm 内移动，端点即量程端点","do":"分别令 x=20 cm 和 x=0 代入 T(x) 求上下限温度","expr":"x\\in[0,20]\\,\\mathrm{cm}","cues":["管口是上限","罐口是下限","端点就是量程"],"concepts":["临界条件","量程"]},{"title":"抽动吸管后油柱位置","type":"前提判断","judge":"缓慢抽出吸管时，罐内气体体积和温度是否改变，油柱到罐口的距离是否随之改变","why":"等压且温度不变时气体体积不变，被封闭气体总体积不变，油柱相对罐的位置不变，只是吸管相对油柱移动","do":"比较抽管前后气体体积与温度，判断 x 是否变化","expr":"V=\\text{const}\\Rightarrow x\\ \\text{不变}","cues":["温度没变","体积没变","油柱没动"],"concepts":["等压等温","体积不变"]}],"720":[{"title":"判断电压表读数含义","type":"前提判断","judge":"电流表示数为零时电压表的示数代表什么物理量","why":"光电管两端加的是反向电压，只有反向电压足够大才能把光电子全部拦回阴极使电流为零，此时电压表读数即遏止电压","do":"确认滑动变阻器接法使光电管处于反向偏压状态，把 U1 认定为遏止电压","expr":"eU_1 = E_{k\\max}","cues":["反向电压","遏止电压","电流为零"],"concepts":["遏止电压","反向偏压","光电效应"]},{"title":"建立光电效应方程","type":"关系建立","judge":"把遏止电压、入射光频率、逸出功三者用哪个方程联系起来","why":"爱因斯坦光电效应方程给出最大初动能与入射光子能量、逸出功的关系，再与遏止电压的定义式联立","do":"写出 eU1 = hν1 − W0，并注意 W0 只由阴极材料决定","expr":"eU_1 = h\\nu_1 - W_0","cues":["光电效应方程","最大初动能","逸出功"],"concepts":["爱因斯坦光电效应方程","逸出功","最大初动能"]},{"title":"区分光强与频率的作用","type":"模型选择","judge":"增大光强改变的是光电子数目还是最大初动能","why":"光强只影响单位时间入射光子数即饱和光电流大小，不改变单个光子能量，故遏止电压与光强无关","do":"比较增大光强前后 eU1 是否变化，判断电压表示数是否改变","expr":"eU_1 = h\\nu - W_0 \\ \\text{（与光强无关）}","cues":["光强只改数目","遏止电压不变","饱和电流变大"],"concepts":["光强","饱和光电流","遏止电压"]},{"title":"判断换频率后遏止电压走向","type":"关系建立","judge":"入射光频率增大时遏止电压应增大还是减小","why":"逸出功由材料决定不变，频率越大光子能量越大，最大初动能越大，所需遏止电压越大","do":"由 eU = hν − W0 比较 ν 与 ν1 时对应的 U 与 U1 的大小","expr":"U = \\frac{h\\nu - W_0}{e}","cues":["频率大初动能大","遏止电压变大","逸出功不变"],"concepts":["遏止电压","逸出功","频率"]},{"title":"判断换向后的偏压性质","type":"临界条件","judge":"开关接 2 后光电管两端是正向还是反向电压，能否仍有光电流","why":"接 2 时电源极性反转，光电管变为正向偏压，只要 hν1 > W0 光电子就能到达阳极形成电流，无需遏止","do":"比较 hν1 与 W0 判断是否发生光电效应，再判断正向偏压下电流表示数是否为零","expr":"h\\nu_1 > W_0 \\Rightarrow I \\neq 0","cues":["正向偏压","加速光电子","电流不为零"],"concepts":["正向偏压","光电效应发生条件"]},{"title":"用截止频率改写逸出功","type":"数学处理","judge":"把未知逸出功用截止频率表示后解出 νc","why":"逸出功与截止频率满足 W0 = hνc，代入方程即可把 W0 消去得到只含已知量的 νc","do":"将 W0 = hνc 代入 eU1 = hν1 − W0，解出 νc","expr":"\\nu_c = \\nu_1 - \\frac{eU_1}{h}","cues":["截止频率","逸出功等于hνc","消去逸出功"],"concepts":["截止频率","逸出功","普朗克常量"]}],"721":[{"title":"区分有效值与峰值","type":"前提判断","judge":"题给的 220 V 输出电压是有效值还是最大值","why":"变压器电压比公式和功率公式 P=UI 中的电压、电流都指有效值，而选项里出现 220√2 V 是在问峰值","do":"确认 10 kV、220 V、16 A 均为有效值，峰值需另乘 √2","expr":"U_m=\\sqrt{2}U","cues":["220是有效值","峰值要乘根号二","题目没说最大值"],"concepts":["有效值","峰值","正弦交流电"]},{"title":"周期由频率换算","type":"关系建立","judge":"由 50 Hz 求周期该用哪个关系","why":"频率与周期互为倒数，与电压大小、匝数无关","do":"用 T=1/f 计算周期","expr":"T=\\frac{1}{f}","cues":["周期是频率倒数","五十赫兹对应多少秒","和电压无关"],"concepts":["周期","频率"]},{"title":"匝数比用电压比","type":"模型选择","judge":"理想变压器匝数比由电压比决定还是由电流、功率决定","why":"理想变压器电压比等于匝数比，与负载电流无关；电流比才是匝数反比","do":"用原副线圈电压之比等于匝数之比列式，注意 10 kV 化成 10000 V","expr":"\\frac{n_1}{n_2}=\\frac{U_1}{U_2}","cues":["电压比等于匝数比","先统一单位","别用电流比"],"concepts":["理想变压器","匝数比","电压比"]},{"title":"多桩功率求和","type":"关系建立","judge":"10 台充电桩同时使用时输出总功率如何计算","why":"各桩并联在同一输出电压下，每桩功率为 U₂I₂，总功率为单桩的 10 倍","do":"先算单桩功率 U₂I₂，再乘 10 得输出总功率","expr":"P_{2总}=10U_2I_2","cues":["每台都是二百二十伏","功率直接相加","十台乘十"],"concepts":["电功率","并联负载"]},{"title":"理想变压器功率不变","type":"前提判断","judge":"输入功率与输出功率是否相等","why":"理想变压器无能量损耗，输入功率等于输出功率，这是求输入功率的唯一依据","do":"令 P₁总=P₂总，把输出总功率直接作为输入功率","expr":"P_1=P_2","cues":["理想变压器不耗能","输入等于输出","不用再乘效率"],"concepts":["理想变压器","功率守恒"]}],"722":[{"title":"频率由波源决定","type":"前提判断","judge":"声波从空气进入水中时，频率是否改变","why":"频率只由波源决定，与介质无关，换介质只改变波速和波长","do":"比较空气中和水中声波的频率，判断是否等于波源频率 400 Hz","expr":"f_{\\text{空}}=f_{\\text{水}}=f_{\\text{源}}","cues":["频率不变","只看波源","换介质不改频率"],"concepts":["频率","波源","介质"]},{"title":"波速与波长频率关系","type":"关系建立","judge":"已知波速和频率时，用哪个关系式求波长","why":"波速等于波长与频率的乘积，同一频率下波长随波速成正比变化","do":"分别用空气和水的声速除以频率，算出两种介质中的波长","expr":"\\lambda=\\frac{v}{f}","cues":["先算波长","波速除以频率","两个介质分别算"],"concepts":["波速","波长","频率"]},{"title":"同距离传播时间比较","type":"关系建立","judge":"同一段 2 km 距离在两种介质中传播时间如何求、如何作差","why":"传播时间由距离除以该介质中的波速得到，两介质波速不同故时间不同","do":"分别算空气中和水中的传播时间，再取两者之差","expr":"t=\\frac{s}{v},\\quad \\Delta t=\\frac{s}{v_{\\text{空}}}-\\frac{s}{v_{\\text{水}}}","cues":["距离一样","分别算时间","再相减"],"concepts":["匀速传播","传播时间","声速"]}],"723":[{"title":"图像斜率对应压强","type":"图像读取","judge":"在 V-T 图上，过原点的直线斜率代表什么物理量，斜率大小与压强是什么关系","why":"由理想气体状态方程 pV/T=C 得 V=(C/p)T，V-T 图中过原点直线的斜率 k=C/p，斜率越大压强越小","do":"把 a、b、c 三点分别与原点连线，比较三条直线的斜率，斜率最大的压强最小","expr":"V=\\frac{C}{p}T,\\quad k=\\frac{C}{p}","cues":["斜率越大压强越小","过原点连线","比斜率"],"concepts":["理想气体状态方程","V-T 图像"]},{"title":"bc 过原点的含义","type":"模型选择","judge":"bc 延长线过原点说明 bc 是什么过程，压强是否恒定","why":"V-T 图中过原点的直线是等压线，因为 V/T=C/p 在 p 不变时为常数","do":"确认 bc 段 V 与 T 成正比，判定为等压过程，再结合体积变化判断做功方向","expr":"\\frac{V_b}{T_b}=\\frac{V_c}{T_c}","cues":["等压变化","体积在减小","外界做功"],"concepts":["等压过程","体积功"]},{"title":"ab 垂直 T 轴的判定","type":"前提判断","judge":"ab 垂直于 T 轴意味着温度不变还是体积不变","why":"横轴为 T，垂直于 T 轴即 T 恒定，是等温过程，内能不变","do":"读出 ab 段 T 相同、V 减小，由玻意耳定律得 p 增大，外界对气体做正功","expr":"T_a=T_b,\\quad p_aV_a=p_bV_b","cues":["等温","温度不变","内能不变"],"concepts":["等温过程","玻意耳定律","内能"]},{"title":"热力学第一定律定吸放热","type":"关系建立","judge":"ab 过程内能不变而外界做正功时，气体是吸热还是放热","why":"ΔU=Q+W，ΔU=0 且 W>0 时必有 Q<0，即放热","do":"对 ab 段列 ΔU=Q+W，代入 ΔU=0、W>0，判断 Q 的符号","expr":"\\Delta U=Q+W=0,\\ W>0\\Rightarrow Q<0","cues":["内能不变","外界做正功","所以放热"],"concepts":["热力学第一定律","等温过程"]},{"title":"ca 过程压强与内能变化","type":"关系建立","judge":"ca 过程压强如何变化、温度如何变化，从而内能如何变化","why":"ca 沿过原点直线斜率变化（或由 p=C/(V/T)）判断压强减小；同时 T 升高则内能增大","do":"比较 c、a 两点与原点连线的斜率判断压强变化，比较两点的 T 判断内能变化","expr":"p=\\frac{C}{V/T}","cues":["斜率变小压强变小","温度升高","内能增大"],"concepts":["理想气体状态方程","内能"]}],"724":[{"title":"中垂线上场强叠加","type":"关系建立","judge":"中垂线上任一点合场强由两个等量同种电荷的场强矢量叠加得到，需判断合场强方向沿中垂线向外、大小随位置如何变化","why":"两个点电荷在 M 点产生的场强大小相等、与中垂线夹角相同，垂直中垂线的分量互相抵消，只剩沿中垂线的分量","do":"设该点到 O 距离为 y，写出单个电荷场强并取沿中垂线的分量相加","expr":"E=2k\\frac{q}{r^{2}+y^{2}}\\cdot\\frac{y}{\\sqrt{r^{2}+y^{2}}}","cues":["垂直分量抵消","只留竖直分量","两个场强对称"],"concepts":["场强叠加","点电荷场强","矢量分解"]},{"title":"场强极值位置","type":"数学处理","judge":"要判断中垂线上场强最大值出现在哪个位置，而不是想当然认为在 O 点或 M 点","why":"O 点处两场强反向抵消为零，远处也趋于零，极值必在中间某处，需用均值不等式或求导确定","do":"把 E 写成含 sinθ、cosθ 的表达式，用均值不等式求极大值条件","expr":"E=k\\frac{2q}{r^{2}}\\sin^{2}\\theta\\cos\\theta,\\ \\cos\\theta=\\frac{\\sqrt{3}}{3}","cues":["O点场强为零","极值不在端点","用均值不等式"],"concepts":["极值条件","均值不等式","场强叠加"]},{"title":"极值点与 M 点比较","type":"几何关系","judge":"需判断场强最大处到 O 的距离与 M 点到 O 的距离 r 谁大谁小","why":"电子从 M 释放后加速度如何变化，取决于 M 位于极值点的哪一侧","do":"由极值条件 cosθ=√3/3 反求 y=r·cotθ，再与 r 比较","expr":"y=r\\cot\\theta=\\frac{\\sqrt{2}}{2}r<r","cues":["先求极值点位置","和r比大小","M在极值点外侧"],"concepts":["几何关系","临界位置"]},{"title":"电子加速度变化判断","type":"前提判断","judge":"需判断电子从 M 向 O 运动过程中所受电场力是增大还是减小，从而判断加速度变化","why":"电子带负电，受力方向与场强方向相反，指向 O；而 M 已在场强极值点外侧，向 O 靠近时场强减小","do":"比较 M 点与极值点位置，确定运动过程中场强单调减小，得出电场力、加速度一直减小","expr":"","cues":["负电荷受力指向O","越靠近O场强越小","加速度一直减小"],"concepts":["电场力","牛顿第二定律","负电荷受力"]},{"title":"小位移下回复力线性化","type":"近似条件","judge":"需判断 N 点附近电子所受合力能否写成与位移成正比、方向相反的形式，即是否做简谐运动","why":"只有 x≪r 时才能对合力表达式作一阶近似，保留线性项，否则不是简谐运动","do":"写出 N 点（距 O 为 x）处两电荷合场强，利用 x≪r 作近似，保留 x 的一次项","expr":"F=-\\frac{4keq}{r^{3}}x","cues":["x远小于r才能近似","只留一次项","回复力与位移成正比"],"concepts":["简谐运动","小量近似","回复力"]}],"725":[{"title":"两棒同时到达MN","type":"前提判断","judge":"是否认定 ab、cd 从释放到碰撞所用时间相同（同时到达 MN）","why":"题设'恰好在 M、N 处发生弹性碰撞'且同时由静止释放，说明两棒运动时间相等，这是把 cd 的位移与 ab 的位移、速度联系起来的前提","do":"由'同时释放、恰在 MN 相碰'确定 t_ab = t_cd = t，用同一 t 分别处理两棒","expr":"t_{ab}=t_{cd}=t","cues":["同时释放同时到","时间一样","恰好在MN碰"],"concepts":["运动的同时性","弹性碰撞"]},{"title":"cd棒受安培力来自电容","type":"模型选择","judge":"cd 所在回路中电流由电容器充放电产生，还是由感应电动势经电阻产生","why":"cd 侧导轨接的是电容器而非电阻，cd 运动只改变电容两端电压，回路电流 I=CBL·a，安培力正比于加速度而非速度","do":"对 cd 与电容器回路写 Δq=CBLΔv，得 I=CBL·a，再代入牛顿第二定律","expr":"I=\\frac{\\Delta q}{\\Delta t}=CBL\\,a_2","cues":["电容回路","电流看充放电","安培力跟加速度走"],"concepts":["电容器充电电流","安培力","牛顿第二定律"]},{"title":"cd做匀加速的判定","type":"关系建立","judge":"cd 的加速度是否为常量，能否用匀加速公式求时间和末速度","why":"把 I=CBL·a 代入牛顿第二定律后 a 只由恒力 F、重力分量和质量、CB²L² 决定，与速度无关，故为匀加速","do":"联立 F-BIL-m₂g sin30°=m₂a₂ 与 I=CBL·a₂，解出 a₂ 后用 x₀=½a₂t² 求 t","expr":"a_2=\\frac{F-m_2g\\sin30^\\circ}{m_2+CB^2L^2}","cues":["加速度是常数","可以套匀加速","分母多一项"],"concepts":["匀加速直线运动","等效质量"]},{"title":"ab棒用动量定理求位移","type":"模型选择","judge":"ab 棒受变力安培力，求位移和电荷量该用动量定理还是仅用能量守恒","why":"安培力随速度变化，能量方程里同时含未知的 x 与 Q，无法单独求解；动量定理中 BIL·t 可化为 BqL，而 q 又与位移挂钩，才能解出 x 和 q","do":"对 ab 写 m₁g sin30°·t - BqL = m₁v₁，配合 q=BLx/R总 解出 q、x，再由能量方程求 Q","expr":"m_1g\\sin30^\\circ\\cdot t-BqL=m_1v_1,\\quad q=\\frac{BLx}{R+R_{ab}}","cues":["安培力是变力","用冲量","电量联系位移"],"concepts":["动量定理","电荷量公式","能量守恒"]},{"title":"热量按电阻分配","type":"关系建立","judge":"总焦耳热 Q 是否全部算在 R 上，还是按电阻比例分配","why":"ab 棒自身有 0.08 Ω 电阻，与 R=0.02 Ω 串联，两者发热量与电阻成正比，只有一部分热量消耗在 R 上","do":"先由能量方程求总热量 Q，再按 R/(R+R_ab) 折算 R 上的热量","expr":"Q_R=\\frac{R}{R+R_{ab}}Q","cues":["热量要分给棒","按电阻分","不能全算R"],"concepts":["焦耳定律","串联分热"]},{"title":"弹性碰撞的速度方向","type":"临界条件","judge":"碰前两棒速度方向如何取正，碰后 v₁′ 的符号说明什么","why":"ab 沿斜面向下、cd 沿斜面向上（碰前 F 已撤去但速度向上），取沿斜面向下为正，碰后 v₁′<0 表示 ab 反弹向上，这是判断后续运动方向的关键","do":"取沿斜面向下为正，用动量守恒与机械能守恒联立解 v₁′、v₂′，由符号判断方向","expr":"m_1v_1-m_2v_2=m_1v_1'+m_2v_2',\\quad \\tfrac12m_1v_1^2+\\tfrac12m_2v_2^2=\\tfrac12m_1v_1'^2+\\tfrac12m_2v_2'^2","cues":["先定正方向","碰后符号有意义","反弹了"],"concepts":["弹性碰撞","动量守恒","机械能守恒"]}],"726":[{"title":"周期换算角速度","type":"关系建立","judge":"用总时间除以圈数得到周期，再换算成角速度，而不是把总时间当成周期","why":"角速度由周期决定，10 圈的总时间对应 10 个周期","do":"先算周期，再用角速度与周期的关系求角速度","expr":"T=\\frac{t}{10},\\ \\omega=\\frac{2\\pi}{T}","cues":["先求周期","十圈总时间","除以十"],"concepts":["周期","角速度"]},{"title":"游标卡尺读数","type":"实验操作","judge":"主尺读数取整毫米部分，游标读数按游标精度乘以对齐格数，两者相加","why":"游标卡尺读数等于主尺示数加游标对齐格数乘精度，不能只读主尺或漏掉游标部分","do":"读主尺整刻度，找游标上与主尺对齐的格数，乘精度后相加","expr":"d=d_{\\text{主}}+n\\times\\text{精度}","cues":["主尺加游标","看对齐格","精度是零点一"],"concepts":["游标卡尺","读数规则"]},{"title":"确定圆周半径","type":"几何关系","judge":"小圆柱体紧贴圆盘边缘，其质心到转轴的距离是圆盘半径减去圆柱体半径，而不是圆盘半径","why":"圆柱体有大小，做圆周运动的是它的质心，质心不在盘边缘上","do":"用圆盘直径和圆柱体直径表示质心到转轴的距离","expr":"r=\\frac{D-d}{2}","cues":["减去半径","质心不在边缘","紧贴边缘"],"concepts":["圆周运动半径","质心"]},{"title":"向心力表达式","type":"关系建立","judge":"向心力用质量、角速度、半径表示，半径代入质心到转轴的距离","why":"向心力由质量、角速度和圆周半径共同决定，半径取错则结果必错","do":"把半径表达式代入向心力公式，整理成含 D 和 d 的形式","expr":"F=m\\omega^{2}r=\\frac{1}{2}m\\omega^{2}(D-d)","cues":["用角速度","半径代质心距离","质量乘角速度平方"],"concepts":["向心力","牛顿第二定律"]},{"title":"单位与有效数字","type":"数学处理","judge":"质量换算成千克、长度换算成米后再代入，结果保留 2 位有效数字","why":"向心力单位是牛顿，必须用国际单位制；题目要求保留 2 位有效数字","do":"把克换成千克、厘米换成米，代入后按有效数字规则取两位","expr":"m=30.0\\times10^{-3}\\,\\mathrm{kg},\\ D,d\\ \\text{化为米}","cues":["换成千克","换成米","保留两位"],"concepts":["国际单位制","有效数字"]}],"727":[{"title":"等效替代的结点定位","type":"前提判断","judge":"判断两次拉橡皮条时是否必须把小圆环拉到同一位置 O","why":"合力与分力的作用效果相同，效果相同体现为橡皮条伸长量相同，即结点到达同一位置","do":"确认单独用 F 拉时圆心仍到 O 点，与 F1、F2 共同拉时位置一致","expr":"","cues":["拉到同一点","效果相同","结点位置不变"],"concepts":["等效替代","合力与分力"]},{"title":"选定标度统一作图","type":"模型选择","judge":"判断作图时三个力是否用同一标度、从同一作用点出发","why":"力的图示要按同一比例表示大小，平行四边形才成立；标度不同则边长无法比较","do":"按题目给定标度把 F1、F2、F 换算成线段长度，都从 O 点起画","expr":"","cues":["同一标度","从同一点画","按比例截取"],"concepts":["力的图示","标度"]},{"title":"平行四边形作合力","type":"几何关系","judge":"判断以 F1、F2 为邻边作平行四边形后，对角线才是理论合力 F'","why":"平行四边形定则规定两分力为邻边时对角线表示合力","do":"过 F1、F2 箭头端分别作另一力的平行线，连 O 与交点得 F'","expr":"","cues":["作平行线","连对角线","邻边夹合力"],"concepts":["平行四边形定则","矢量合成"]},{"title":"比较 F 与 F' 的偏差","type":"结论整理","judge":"判断实验结论应比较实测合力 F 与作图所得 F' 是否在误差范围内重合","why":"F 是实际一个测力计的读数，F' 是由分力按定则作出的理论值，二者一致才验证了定则","do":"量出 F' 的长度换算大小，与 5.60 N 比较，并看方向是否沿 OP3","expr":"","cues":["看是否重合","比大小和方向","在误差范围内"],"concepts":["实验验证","误差允许范围"]},{"title":"误差来源定位","type":"误差分析","judge":"判断哪些操作缺陷会使 F 与 F' 不重合","why":"测力计未调零、读数视线不正、细绳与木板不平行、结点位置偏移等都会使记录值偏离真实值","do":"从读数、方向记录、结点定位、器材平行度四方面各举可能原因","expr":"","cues":["读数没正视","没与木板平行","结点没对准","测力计没调零"],"concepts":["系统误差","读数误差"]}],"728":[{"title":"充电电流的变化趋势","type":"模型选择","judge":"判断充电过程中电流表读数随时间如何变化，而不是只看最终稳定值","why":"电容器充电时极板电荷量增大，极板间电压升高，与电源的电压差减小，充电电流随之减小；接通瞬间电流从零跃升到最大值","do":"把电路看成电源、电阻、电容器串联的RC充电回路，分析电流从接通瞬间到充电完毕的整个变化过程","expr":"I=\\frac{E-U_C}{R}","cues":["先增大后减小","充满就断路","电流最后为零"],"concepts":["RC充电","电容器","欧姆定律"]},{"title":"稳定电压即电源电动势","type":"前提判断","judge":"判断充电结束后电压表稳定示数代表什么物理量","why":"充电完毕电路无电流，电阻上无电压降，电容器两端电压等于电源电动势","do":"把稳定示数12.3 V认定为电容器充电完毕时的初始电压，作为后续放电计算的电压起点","expr":"U_0=12.3\\,\\mathrm{V}","cues":["稳定值就是电动势","充满电压不变","电阻上没压降"],"concepts":["电动势","电容器电压","电路稳定"]},{"title":"放电电流方向判定","type":"关系建立","judge":"判断放电时通过定值电阻R的电流方向","why":"充电时上极板接电源正极带正电，放电时正电荷从上极板经外电路流向负极板，故外电路中电流由高电位极板经R流向低电位极板","do":"先由充电接法确定上极板带正电，再沿放电回路追踪正电荷移动方向，定出R中电流由a到b","expr":"","cues":["上板带正电","正电荷往外流","从a流向b"],"concepts":["电容器放电","电流方向","极板电性"]},{"title":"面积对应放电电荷量","type":"图像读取","judge":"判断I-t图像与横轴围成的面积代表什么物理量，以及M、N两区域各对应哪段放电过程","why":"电流对时间积分即通过导体截面的电荷量，放电过程中电荷量等于电容器减少的电荷量","do":"把0到2 s的M区域对应电压从12.3 V降到IR的过程，2 s之后的N区域对应电压从IR降到零的过程","expr":"Q=\\int I\\,\\mathrm{d}t","cues":["面积就是电量","M是前段","N是后段"],"concepts":["I-t图像面积","电荷量","放电过程"]},{"title":"用电压降比例代替电量比","type":"数学处理","judge":"判断两段放电电荷量之比可以转化为两段电压降之比，从而消去未知电容C","why":"同一电容器Q=CΔU，C相同，故电荷量之比等于对应电压降之比，避免引入未知的C","do":"写出M段对应ΔU=12.3−IR、N段对应ΔU'=IR，令两者之比等于8:7，解出R","expr":"\\frac{12.3-IR}{IR}=\\frac{8}{7}","cues":["电容约掉","比电压降","同一电容器"],"concepts":["电容定义式","电压降","比例消元"]}],"729":[{"title":"识别虚接的电路位置","type":"模型选择","judge":"C 处虚接的接触电阻 R_C 是串在干路里，还是只串在 B 支路里","why":"虚接点位于 A、B 并联支路分开之后的 B 支路（或干路）位置，决定了 R_C 与 A、B 是串联还是并联关系，画错等效电路后续全错","do":"对照电路图，从 MN 两端沿导线追踪电流分叉点，确定 R_C 与 R_B 串联后再与 R_A 并联","expr":"","cues":["先画等效电路","看电流在哪分叉","虚接在支路上"],"concepts":["等效电路","并联电路","串联电路"]},{"title":"取极值定电阻范围","type":"临界条件","judge":"R_C 在 0 到 240 Ω 间变化时，总电阻 R 的最小值和最大值分别对应 R_C 的哪个端点","why":"总电阻是 R_C 的单调函数，极值必在 R_C 取端点时出现，取错端点或漏掉一端就得不到完整范围","do":"分别令 R_C=0 和 R_C=240 Ω，代入并联总电阻表达式算出两个端点值","expr":"R=\\frac{R_A(R_B+R_C)}{R_A+R_B+R_C}","cues":["取两个端点","虚接为零时最小","虚接最大时最大"],"concepts":["并联电阻","单调性","极值"]},{"title":"选对求功率的回路","type":"模型选择","judge":"求 B 的功率时，是取 B 与 R_C 串联这条支路，还是取整个并联电路","why":"B 支路两端电压不等于 220 V（干路无其他电阻但支路含 R_C），只有把 B 与 R_C 看成串联支路、用总电压除以支路总电阻才得对电流","do":"对 B 与 R_C 串联支路用欧姆定律求支路电流，再代入功率公式","expr":"I=\\frac{U}{R_B+R_C},\\quad P_B=I^2R_B","cues":["B和虚接串联","电压不是全加在B上","先求支路电流"],"concepts":["欧姆定律","串联分压","电功率"]},{"title":"有效数字与单位处理","type":"数学处理","judge":"功率结果保留 3 位有效数字时，中间量是否提前取整","why":"提前把电流或电阻取整会引入误差，导致末位有效数字不符要求","do":"用未取整的中间值连续计算，最后一步再按 3 位有效数字修约并写单位 W","expr":"P_B=\\left(\\frac{220}{24+240}\\right)^2\\times 24","cues":["最后再修约","别提前取整","保留三位"],"concepts":["有效数字","近似计算"]}],"730":[{"title":"滑梯段机械能守恒","type":"模型选择","judge":"从 a 到 b 下滑过程中，能否用机械能守恒（而非牛顿定律加运动学）求 b 点速度","why":"滑梯光滑、只有重力做功，支持力始终垂直于速度不做功，机械能守恒成立","do":"对游客从 a 到 b 列机械能守恒式，由高度差 h 求 b 点速度","expr":"mgh=\\frac{1}{2}mv_0^2","cues":["光滑滑梯","只有重力做功","用能量守恒"],"concepts":["机械能守恒","重力势能"]},{"title":"b 点向心力求压力","type":"关系建立","judge":"b 点求滑梯对游客的支持力时，向心加速度方向指向圆心、合力为支持力减重力","why":"游客在 b 点做圆周运动，径向合力提供向心力，圆心在 b 点上方","do":"沿径向列牛顿第二定律，用已求得的 v0 和半径 R 解出支持力，再由牛顿第三定律得压力","expr":"F_N-mg=m\\frac{v_0^2}{R}","cues":["指向圆心","支持力减重力","还要用牛三"],"concepts":["向心力","牛顿第二定律","牛顿第三定律"]},{"title":"平台段反推上平台速度","type":"前提判断","judge":"游客在平台上滑行 16 m 停下，能否由此反推出游客刚滑上平台时的速度","why":"平台上只有摩擦力做负功，末速度为零，位移已知，动能定理可直接联系初速度与位移","do":"对平台段列动能定理，由 s 和 μ 求游客滑上平台时的速度 v","expr":"-\\mu mgs=0-\\frac{1}{2}mv^2","cues":["末速度为零","摩擦力做负功","反推初速度"],"concepts":["动能定理","滑动摩擦力"]},{"title":"判定游客全程减速","type":"临界条件","judge":"游客在滑板上相对滑动时，是始终减速还是中途与滑板共速，需判断两者速度大小关系","why":"游客初速远大于滑板初速（滑板初速为零），且题设说游客恰好滑上平台时滑板右端刚到平台边缘，说明滑动持续到末了","do":"比较游客速度 v 与滑板速度 a2t 的大小，确认整个过程中游客速度始终大于滑板速度、相对滑动方向不变","expr":"v_0-a_1t>a_2t","cues":["滑板从静止起步","一直相对滑动","没有共速"],"concepts":["相对滑动","匀变速直线运动"]},{"title":"两物体加速度分别求解","type":"模型选择","judge":"求游客和滑板的加速度时，各自所受摩擦力大小相同但方向相反，需分别对两个物体用牛顿第二定律","why":"游客受滑板给的向后摩擦力，滑板受游客给的向前摩擦力，地面光滑无其他水平力，两物体加速度不同","do":"对游客列 μmg=ma1，对滑板列 μmg=Ma2，分别求出 a1、a2","expr":"a_1=\\mu g,\\quad a_2=\\frac{\\mu mg}{M}","cues":["摩擦力方向相反","地面光滑","分别列方程"],"concepts":["牛顿第二定律","滑动摩擦力"]},{"title":"相对位移求板长","type":"几何关系","judge":"滑板长度等于游客相对滑板的位移，即游客位移与滑板位移之差，而非游客位移本身","why":"游客从滑板左端滑到右端，板长由两者对地位移之差决定","do":"由运动学求游客位移 s1 和滑板位移 s2，作差得板长 L","expr":"L=s_1-s_2=\\frac{v_0+v}{2}t-\\frac{1}{2}a_2t^2","cues":["相对位移","两者位移之差","不是游客位移"],"concepts":["相对位移","匀变速直线运动"]}],"731":[{"title":"轨迹半径等于区域半径","type":"几何关系","judge":"从 P 点射入、Q 点射出的粒子，其轨迹半径与区域 Ⅰ 半径是否相等","why":"粒子从 P 点沿 y 轴正方向射入，出射点 Q 在区域 Ⅰ 边界上，且入射速度方向与边界切线垂直，由几何关系可知轨迹圆心与区域圆心重合，轨迹半径等于区域半径","do":"画出粒子在区域 Ⅰ 中的圆周轨迹，比较轨迹圆心与区域圆心 O₁ 的位置关系，确认两者重合","expr":"r=R=\\frac{mv_0}{qB}","cues":["半径相等","从切线方向射入"],"concepts":["洛伦兹力提供向心力","圆周运动半径"]},{"title":"磁聚焦判断出射点","type":"模型选择","judge":"不同入射位置的粒子在区域 Ⅰ 中是否都从同一点 Q 射出","why":"区域 Ⅰ 的磁场半径与粒子轨迹半径相等，入射点、区域圆心、轨迹圆心、出射点构成菱形，出射点位置与入射点无关","do":"对任意入射点作轨迹圆心，利用菱形性质证明出射点固定为 Q","expr":"","cues":["磁聚焦","都从同一点射出","菱形关系"],"concepts":["磁聚焦","菱形几何关系"]},{"title":"最短时间对应最短弦","type":"临界条件","judge":"在区域 Ⅱ 中运动时间最短对应什么几何条件","why":"粒子在区域 Ⅱ 中做圆周运动，周期固定，时间最短即圆心角最小，对应轨迹弦长最短","do":"在区域 Ⅱ 的磁场圆内找最短弦，即沿半径方向的弦，长度为区域 Ⅱ 半径 2R","expr":"t=\\frac{\\theta}{2\\pi}T","cues":["弦最短","沿半径方向"],"concepts":["圆周运动周期","弦长与圆心角"]},{"title":"两区域圆心角关系","type":"几何关系","judge":"最短弦条件下区域 Ⅰ 和区域 Ⅱ 中轨迹对应的圆心角各是多少","why":"区域 Ⅱ 半径是区域 Ⅰ 的 2 倍，轨迹半径也是 2 倍，最短弦为 2R，由几何关系可得两区域圆心角均为 60°","do":"由弦长 2R 与轨迹半径 2R 的关系求区域 Ⅱ 圆心角，再由几何关系求区域 Ⅰ 圆心角","expr":"\\theta_1=\\theta_2=60^\\circ","cues":["都是六十度","弦长等于半径","等边三角形"],"concepts":["圆心角","几何关系"]},{"title":"速度分解找电场力平衡","type":"模型选择","judge":"区域 Ⅲ 中电场力与哪部分速度对应的洛伦兹力平衡","why":"E=Bv₀，故 Eq=Bqv₀，将速度分解为沿 y 轴方向的 v₀ 和另一分量 v′，v₀ 对应的洛伦兹力与电场力平衡，粒子做旋进运动","do":"将进入区域 Ⅲ 的速度沿 y 轴方向和垂直方向分解，验证 v₀ 分量对应的洛伦兹力与电场力等大反向","expr":"Eq=Bqv_0","cues":["速度分解","电场力和洛伦兹力平衡","旋进运动"],"concepts":["速度分解","洛伦兹力与电场力平衡"]},{"title":"动能最大时速度方向","type":"临界条件","judge":"粒子动能最大时 v′ 的方向应满足什么条件","why":"v₀ 分量恒定，动能最大即 v′ 方向与 v₀ 同向时合速度最大","do":"判断 v′ 旋转到竖直向上时合速度最大，求最大速度及对应位置到 y 轴的距离","expr":"v_m=v_0+v'","cues":["速度同向时最大","v′竖直向上","合速度最大"],"concepts":["速度合成","动能最大条件"]}],"732":[{"title":"区分金属与非金属","type":"前提判断","judge":"要判断金属和非金属在雷击这种强电磁环境下最本质的差别是什么","why":"金属有自由电子、电阻率低，非金属没有自由电子，这是后续所有效应的物理根源","do":"把题中银饰、宝刀归为导体，漆器、刀鞘归为绝缘体，比较两者能否产生感应电流","expr":"","cues":["金属导电","非金属不导电","看有没有自由电子"],"concepts":["导体","绝缘体","自由电荷"]},{"title":"锁定电磁感应机制","type":"模型选择","judge":"要判断雷击瞬间的强变化磁场能在金属内部激起什么，而不是热传导或光照","why":"雷击是瞬时大电流，周围磁场剧烈变化，法拉第电磁感应定律要求导体中产生感应电动势","do":"把雷电流视为快速变化的磁场源，判断金属体内是否形成闭合感应电流","expr":"\\mathcal{E}=-\\frac{d\\Phi}{dt}","cues":["磁场在变","感应电动势","雷电流很大"],"concepts":["电磁感应","变化磁场","感应电动势"]},{"title":"涡流只生于导体","type":"关系建立","judge":"要判断感应出的电流在块状金属中如何分布、为何能把金属自身烧熔","why":"整块金属内感应电流自成闭合回路即涡流，焦耳热集中在金属内部；非金属无自由电荷，无法形成涡流","do":"把涡流与焦耳热联系起来，说明热量产生在金属体内而非外部传入","expr":"Q=I^2Rt","cues":["涡流","自己发热","电流在金属里转"],"concepts":["涡流","焦耳定律","电流热效应"]},{"title":"排除其他致热途径","type":"结论整理","judge":"要判断摩擦生热、声波、光照等能否解释只有金属熔化而非金属完好","why":"摩擦、声波、光照对金属和非金属同样作用，无法解释选择性熔化，只有依赖导电性的涡流能区分二者","do":"把各候选原因对金属/非金属的作用效果作对比，保留只对金属有效的那个","expr":"","cues":["摩擦两者都有","光照都会照到","只有涡流分金属非金属"],"concepts":["控制变量","涡流","能量转化"]}],"733":[{"title":"识别核反应方程","type":"模型选择","judge":"判断该方程属于核反应方程，需用质量数守恒和电荷数守恒处理，而非化学反应或衰变规律","why":"方程左边是入射中子轰击硼靶核生成两种新核，属于人工核转变，反应前后核子总数与总电荷不变","do":"确认箭头两侧各核的质量数（左上角）与电荷数（左下角）分别对应相等","expr":"","cues":["核反应方程","用守恒来列","不是化学式"],"concepts":["核反应方程","质量数","电荷数"]},{"title":"质量数守恒定a","type":"关系建立","judge":"判断反应前后质量数总和相等，从而由已知三项求未知核X的质量数a","why":"核反应中核子数守恒，反应前总质量数等于反应后总质量数","do":"列出反应前后质量数相等的方程，代入10、1、4求a","expr":"10+1=a+4","cues":["质量数守恒","左上角相加","先求a"],"concepts":["质量数守恒","核子数"]},{"title":"电荷数守恒定b","type":"关系建立","judge":"判断反应前后电荷数总和相等，从而由已知三项求未知核Y的电荷数b","why":"核反应中电荷守恒，反应前总电荷数等于反应后总电荷数","do":"列出反应前后电荷数相等的方程，代入5、0、3求b","expr":"5+0=3+b","cues":["电荷数守恒","左下角相加","再求b"],"concepts":["电荷数守恒","原子序数"]},{"title":"核对X的电荷数","type":"结论整理","judge":"判断求出的a、b是否与X、Y的电荷数标注一致，即X的电荷数是否确为3","why":"题目已把X的电荷数标为3，需检验守恒结果与标注是否自洽，防止把a、b对应错核","do":"把求得的a与X对应、b与Y对应，检查X电荷数3是否满足电荷守恒","expr":"5+0=3+b","cues":["a配X","b配Y","别对应反了"],"concepts":["核反应方程","电荷数守恒"]}],"734":[{"title":"识别平抛模型","type":"模型选择","judge":"青蛙离叶后只受重力、初速度水平，是否可按平抛处理","why":"题设明确'将青蛙的跳跃视为平抛运动'，故水平匀速、竖直自由落体","do":"把跳跃分解为水平匀速直线运动和竖直自由落体两个分运动","expr":"","cues":["看成平抛","水平匀速","竖直自由落体"],"concepts":["平抛运动","运动的分解"]},{"title":"写出初速度表达式","type":"关系建立","judge":"用水平位移和下落高度表示初速度，判断v随x、h如何变化","why":"平抛两分运动由同一时间t联系，消去t才能得到v与x、h的关系","do":"由水平方向x=vt与竖直方向h=½gt²消去t，解出v","expr":"v=x\\sqrt{\\frac{g}{2h}}","cues":["消去时间","两个方向联立","高度定时间"],"concepts":["平抛运动","运动学公式"]},{"title":"比较竖直下落高度","type":"几何关系","judge":"四个荷叶中哪个下落高度h最大","why":"a、b与青蛙等高，c、d比a、b低一层，故落到c或d时h更大","do":"比较青蛙起跳点与各荷叶的高度差，选出h最大的那一层","expr":"","cues":["先看高度差","cd更低","下落更多"],"concepts":["竖直位移","高度差"]},{"title":"比较水平位移","type":"几何关系","judge":"在h相同的c、d中，哪个水平位移x更小","why":"a、b分别在c、d正上方，c在a正下方，故c的水平距离小于d","do":"比较青蛙到c、到d的水平距离，取较小者","expr":"","cues":["看水平距离","c更近","正下方"],"concepts":["水平位移","几何位置"]},{"title":"最小初速的取舍","type":"结论整理","judge":"h越大、x越小时v越小，据此在四个荷叶中选最优","why":"v=x√(g/2h)中v随x减小、随h增大而减小，两个因素要同时朝有利方向","do":"先取h最大的c、d，再在其中取x最小的c","expr":"v\\propto x,\\quad v\\propto h^{-1/2}","cues":["高度大水平小","两个都要占","取c"],"concepts":["控制变量","极值判断"]}],"735":[{"title":"反冲速度的方向","type":"模型选择","judge":"喷气沿径向向外，空间站获得的反冲速度沿径向向内还是向外","why":"反冲速度方向与喷气方向相反，且沿径向，与原有的切向速度垂直","do":"由箭头指向确定喷气方向，取反方向作为空间站新增速度的方向","expr":"","cues":["反冲方向与喷气相反","径向速度","和原速度垂直"],"concepts":["反冲","速度的合成"]},{"title":"合速度大小的变化","type":"关系建立","judge":"径向新增速度与原切向速度合成后，合速度比原来大还是小","why":"两速度互相垂直，合速度由勾股定理决定，只要新增分量不为零合速度必增大","do":"把原切向速度与新增径向速度按垂直关系合成，比较合速度与原速度","expr":"v'=\\sqrt{v_0^2+v_r^2}>v_0","cues":["垂直合成","勾股定理","合速度变大"],"concepts":["速度合成","矢量"]},{"title":"半长轴定周期","type":"关系建立","judge":"变轨后周期变大还是变小","why":"开普勒第三定律：半长轴越大周期越大，题设已给半长轴大于原半径","do":"比较变轨后椭圆半长轴与原圆轨道半径，用开普勒第三定律得周期关系","expr":"\\frac{a^3}{T^2}=k","cues":["开普勒第三定律","半长轴大周期大","比半径"],"concepts":["开普勒第三定律","半长轴"]},{"title":"P 点加速度只看引力","type":"前提判断","judge":"变轨前后 P 点的加速度是否改变","why":"加速度由该点所受万有引力决定，与速度大小方向无关，P 点位置未变则引力不变","do":"比较变轨前后 P 点到地心距离，确认引力相同，再由牛顿第二定律得加速度相同","expr":"a=\\frac{GM}{r^2}","cues":["加速度只看引力","位置没变","与速度无关"],"concepts":["万有引力定律","牛顿第二定律"]},{"title":"椭圆轨道速度比较","type":"临界条件","judge":"变轨后 P 点速度与近地点速度谁大","why":"椭圆轨道上近地点速度最大、远地点最小，P 点不是近地点","do":"由开普勒第二定律判断 P 点与近地点的速度大小关系，再与变轨前圆轨道速度比较","expr":"v_P r_P=v_{\\text{近}}r_{\\text{近}}","cues":["近地点速度最大","面积速度不变","P不是近地点"],"concepts":["开普勒第二定律","椭圆轨道"]}],"736":[{"title":"二极管导通方向判断","type":"模型选择","judge":"每个半周期内哪个二极管正向导通、哪个反向截止","why":"二极管正向电阻为零、反向电阻无穷大，只有正向偏置的那一路才有电流，反向那一路相当于断路","do":"对正、负半周分别画出电流通路，标出被短路的是哪只灯泡","expr":"","cues":["看正半周","反向就当断路","谁被短路"],"concepts":["二极管的单向导电性","正向导通","反向截止"]},{"title":"短路关系识别","type":"关系建立","judge":"导通的二极管与它并联的灯泡是短路关系还是串联关系","why":"二极管正向电阻为零，与它并联的灯泡两端电压被钳为零，该灯泡无电流、不消耗功率","do":"把导通二极管所在支路看成导线，判断被它短接的是哪只灯泡","expr":"","cues":["并联被短接","那只灯不亮","电压为零"],"concepts":["短路","并联电路"]},{"title":"半周期内串接对象","type":"关系建立","judge":"每个半周期里，有电流的灯泡是与电源单独串联，还是与另一只灯泡串联","why":"一只灯泡被短路后，剩下的那只灯泡直接接在电源两端，承受全部电源电压","do":"分别写出正半周和负半周中通电灯泡与电源的连接方式","expr":"","cues":["另一只单独接电源","各亮半个周期","轮流工作"],"concepts":["串联电路","电源电压"]},{"title":"两灯通电时间相等","type":"前提判断","judge":"一个完整周期内两只灯泡各自通电的时间是否相等","why":"正弦交流电正、负半周对称，各占半个周期，两个二极管分别在半个周期内导通","do":"","expr":"","cues":["各半个周期","时间一样","对称的"],"concepts":["交流电的周期性","正弦交流电"]},{"title":"有效值相同再比功率","type":"结论整理","judge":"两灯承受的电压有效值是否相同，功率比是否只由电阻比决定","why":"两灯都在半个周期内承受完整的正弦电压、另半个周期电压为零，故有效值相等，由 P=U²/R 知功率与电阻成反比","do":"先确认两灯电压有效值相等，再用功率与电阻成反比求比值","expr":"P=\\frac{U^2}{R},\\quad P_1:P_2=R_2:R_1","cues":["有效值一样","功率反比于电阻","电阻是两倍"],"concepts":["有效值","电功率","电阻比"]}],"737":[{"title":"选货船S为受力对象","type":"模型选择","judge":"求绳张力时应先隔离哪艘船，还是把三船整体作为对象","why":"整体法只能给出三船总动力与总阻力的关系，无法解出单根绳的张力；S 只受两绳拉力和水的阻力，未知量最少","do":"隔离货船 S，画水平面内受力图：两绳拉力 T 沿绳方向、夹角各 30°，阻力 f 沿运动反方向","expr":"","cues":["先隔离货船","整体法解不出张力","只看S"],"concepts":["隔离法","受力分析"]},{"title":"沿垂直运动方向平衡","type":"关系建立","judge":"S 匀速前进时，两绳拉力在垂直于运动方向的分量应满足什么关系","why":"S 做匀速直线运动，垂直运动方向合力为零，两绳对称布置使该方向分量互相抵消，从而两绳张力大小相等","do":"把两绳拉力沿运动方向和垂直运动方向正交分解，对垂直方向列平衡式","expr":"T\\sin30^\\circ=T\\sin30^\\circ","cues":["垂直方向抵消","两绳对称","张力一样大"],"concepts":["正交分解","平衡条件"]},{"title":"沿运动方向平衡求张力","type":"关系建立","judge":"S 沿运动方向的合力方程中，两绳拉力的分量与阻力 f 如何配平","why":"S 匀速前进，沿运动方向合力为零，两绳拉力沿运动方向的分量之和等于水的阻力 f","do":"对 S 沿运动方向列平衡方程，解出单根绳的张力 T","expr":"2T\\cos30^\\circ=f","cues":["沿运动方向列方程","两个分力加一起","等于阻力"],"concepts":["平衡条件","正交分解"]},{"title":"拖船P受绳的反作用","type":"前提判断","judge":"拖船 P 受到的绳力方向是沿绳指向 S 还是背离 S，与运动方向成什么角","why":"绳对 P 的拉力是 P 拉绳的反作用力，方向沿绳指向货船，其沿运动方向的分量与阻力同向，会增大所需动力","do":"在 P 的受力图上标出绳拉力 T 的方向，分解为沿运动方向和垂直运动方向两个分量","expr":"T\\cos30^\\circ,\\ T\\sin30^\\circ","cues":["绳拉P指向S","沿运动方向是阻力","别把方向弄反"],"concepts":["作用力与反作用力","绳的拉力"]},{"title":"P的动力与合力正交合成","type":"数学处理","judge":"P 匀速时发动机动力 F 应与哪些力的合力等大反向","why":"P 匀速前进，所受合外力为零，动力 F 必须与绳拉力、水阻力两者的合力大小相等方向相反，两力互相垂直才能用勾股定理","do":"把沿运动方向的力（f 与 T 的分量）和垂直运动方向的力（T 的另一分量）分别求和，再用勾股定理求合力大小","expr":"F=\\sqrt{(T\\sin30^\\circ)^2+(f+T\\cos30^\\circ)^2}","cues":["两方向互相垂直","用勾股定理","动力等于合力"],"concepts":["力的合成","平衡条件"]}],"738":[{"title":"径向射入必径向射出","type":"前提判断","judge":"粒子从 A 沿直径方向（径向）射入圆形磁场区后，出射速度方向是否仍沿半径方向","why":"圆形有界磁场中沿半径方向入射的粒子，由几何对称性（入射点、出射点与圆心构成等腰三角形，轨迹圆心在垂直速度的直线上）可证出射速度必沿半径方向，这是判断轨迹能否过 O、能否回到 A 的前提","do":"画出 A 点速度沿 AO 方向，由洛伦兹力定圆心，验证出射点速度沿该点半径方向","expr":"","cues":["沿半径进就沿半径出","对称性"],"concepts":["有界磁场","对称性","洛伦兹力方向"]},{"title":"轨迹不过圆心","type":"几何关系","judge":"粒子在圆内做圆周运动的轨迹能否经过圆心 O","why":"粒子轨迹是圆弧，入射速度沿 AO，轨迹圆心在过 A 且垂直 AO 的直线上，该圆弧与 AO 只在 A 点相交（相切于 A 的垂线方向），故不可能再经过 O","do":"以 A 为切点、速度沿 AO 作圆弧，检查它与直线 AO 的交点只有 A","expr":"","cues":["轨迹和直径只交于A","圆弧弯不到圆心","过O就要沿直径走"],"concepts":["圆周运动轨迹","几何相切"]},{"title":"区分内外磁场方向","type":"模型选择","judge":"粒子穿出圆形区域进入外部反向磁场后，轨迹向哪一侧偏、曲率半径是否改变","why":"外部磁场方向相反、大小相同，洛伦兹力反向但半径 r=mv/qB 不变，轨迹变成反向弯曲的等半径圆弧，这是分析粒子能否回到 A、能否到 C 的模型基础","do":"在圆外区域把轨迹画成与圆内圆弧半径相同、弯曲方向相反的圆弧，拼接成连续轨迹","expr":"r=\\frac{mv}{qB}","cues":["外面磁场反了","两段圆弧拼起来"],"concepts":["洛伦兹力","回旋半径","磁场反向"]},{"title":"最短时间对应整周期数","type":"临界条件","judge":"粒子连续两次从 A 沿 AC 方向射入，最短时间对应轨迹转过的总角度是多少","why":"要再次以相同方向从 A 射入，轨迹必须闭合回到原状态，转过的总圆心角必须是 2π 的整数倍；取最小倍数即得最短时间","do":"由对称性画出从 A 出发经外场返回 A 且速度方向复原的最短闭合轨迹，数出包含几个完整圆周运动周期","expr":"t_{\\min}=nT,\\ n=1,2,\\dots","cues":["要回到原状态","转过的角是整圈","取最小整圈数"],"concepts":["周期","轨迹闭合","对称性"]},{"title":"A到C最短路径的几何","type":"几何关系","judge":"从 A 射入到从 C 射出用时最短，轨迹在圆内对应的弦与半径构成什么几何关系，由此定出轨迹半径 r","why":"A、C 为直径两端，圆内轨迹是过 A、C 的圆弧，其弦长 AC=2R；结合出射沿径向的对称性，轨迹圆心与 O 的相对位置给出 r 与 R 的定比关系，这是求速度的唯一几何依据","do":"连接 AC，作出过 A、C 的圆弧及其圆心，用等腰/等边三角形的边角关系解出 r 与 R 的比值","expr":"r=\\frac{\\sqrt{3}}{3}R","cues":["弦是直径","画等腰三角形","半径和R成比例"],"concepts":["弦与半径","几何作图","圆周运动半径"]},{"title":"由半径反求速度","type":"关系建立","judge":"把几何得到的轨迹半径代入洛伦兹力提供向心力的方程，求出入射速度","why":"粒子在磁场中做匀速圆周运动，向心力完全由洛伦兹力提供，r 确定后 v 唯一确定","do":"联立 qvB=mv²/r 与 r=√3R/3，解出 v","expr":"qvB=m\\frac{v^{2}}{r}\\Rightarrow v=\\frac{qBr}{m}","cues":["洛伦兹力当向心力","半径定了速度就定了","代入约掉一个根号三"],"concepts":["牛顿第二定律","洛伦兹力","回旋半径"]}],"739":[{"title":"电荷守恒的适用条件","type":"前提判断","judge":"判断电荷守恒定律是否只适用于与外界无电荷交换的孤立系统","why":"电荷守恒定律的内容是孤立系统总电荷量保持不变，若系统与外界有电荷交换则总量可变","do":"确认选项描述的系统是否与外界无电荷交换，再判断总量是否守恒","expr":"","cues":["孤立系统","没有电荷交换","总量不变"],"concepts":["电荷守恒定律","孤立系统"]},{"title":"电场线与等势面关系","type":"关系建立","judge":"判断电场线与等势面是否垂直，以及电场线指向电势升高还是降低的方向","why":"电场强度方向沿电场线切线，且指向电势降低最快的方向，等势面上各点电势相等，故电场线必垂直于等势面并由高电势指向低电势","do":"由电场线方向与电势降落方向的一致性，判断选项中电场线指向与等势面高低的关系是否说反","expr":"","cues":["垂直","由高到低","顺着电场线电势降低"],"concepts":["电场线","等势面","电势"]},{"title":"静止释放后的运动方向","type":"关系建立","judge":"判断点电荷仅在电场力作用下由静止释放后，是沿电场线方向还是逆电场线方向运动，正负电荷是否相同","why":"电场力方向由场强方向和电荷正负共同决定，静止释放后电荷沿受力方向加速，正电荷受力沿场强方向，负电荷受力逆场强方向","do":"先定场强方向，再按电荷正负定受力方向，即得运动方向","expr":"\\vec F=q\\vec E","cues":["看电荷正负","正电荷顺电场线","负电荷逆电场线"],"concepts":["电场力","场强方向","正负电荷"]},{"title":"电势能与电势的对应","type":"关系建立","judge":"判断电场力做正功时电势能如何变化，以及电势能高低与电势高低如何对应","why":"电场力做正功电势能减小，由电势定义式可知电势能与电势的关系还取决于电荷正负，正电荷在高电势处电势能大，负电荷相反","do":"先由电场力做功定电势能变化，再用定义式换算成电势高低，注意电荷正负号","expr":"\\varphi=\\frac{E_p}{q},\\quad W_{电}=-\\Delta E_p","cues":["电场力做正功","电势能减小","负电荷反过来"],"concepts":["电势能","电势","电场力做功"]}],"740":[{"title":"判断洛伦兹力方向","type":"前提判断","judge":"正、负粒子分别向哪块极板偏转，哪块极板积累正电荷","why":"磁场垂直纸面向里、粒子水平向右运动，由左手定则判定正电荷受力向上、负电荷受力向下，这是确定电源正负极的唯一依据","do":"对正离子用左手定则：四指指向速度方向，磁感线穿入手心，拇指指向洛伦兹力方向","expr":"\\vec F=q\\vec v\\times\\vec B","cues":["左手定则","正离子往上偏","磁场向里"],"concepts":["洛伦兹力","左手定则","电源正负极"]},{"title":"建立力平衡求电压","type":"关系建立","judge":"稳定时洛伦兹力与电场力大小相等，据此把极板电压与磁感应强度、间距、速度联系起来","why":"粒子持续偏转使极板电荷积累、板间电场增强，电场力增大到与洛伦兹力平衡后粒子不再偏转，电压达到稳定值","do":"对稳定偏转的粒子列洛伦兹力等于电场力的方程，电场用电压除以板间距表示","expr":"qvB=q\\frac{U}{d}\\Rightarrow U=Bdv","cues":["电场力和洛伦兹力平衡","稳定后不再偏转","电压等于场强乘间距"],"concepts":["洛伦兹力","匀强电场","二力平衡"]},{"title":"判断电压与各量关系","type":"结论整理","judge":"电压随板间距、喷入速度如何变化，是否与粒子数密度有关","why":"由 U=Bdv 可知电压只由 B、d、v 决定，与带电粒子数密度无关；数密度只影响可提供的电流大小","do":"在 U=Bdv 中分别看 d 增大、v 增大时 U 的变化，并确认式中不含数密度","expr":"U=Bdv","cues":["只看间距和速度","数密度不影响电压","间距大电压大"],"concepts":["电动势","磁流体发电机"]}],"741":[{"title":"阻力随初速变化","type":"前提判断","judge":"要判断阻力 f 不是恒量，而是随所考察的初速度 v0 一起变化（f=kv0），因此不同 v0 对应不同的相互作用过程","why":"题设明确 f=kv0，若把 f 当成固定值，加速度、时间、位移全部算错，也无法讨论“木块速度最大”这一极值问题","do":"在列牛顿第二定律和运动学方程时，把 f 写成 kv0 代入，而不是当常数","expr":"f=kv_{0}","cues":["阻力是变的","跟初速有关","不能当常数"],"concepts":["变力","正比关系","牛顿第二定律"]},{"title":"穿出条件定位移差","type":"几何关系","judge":"要判断子弹恰好穿出木块时，子弹相对木块的位移等于木块长度 L，即 x1-x2=L","why":"子弹在木块内运动、阻力作用距离由相对位移决定，只有用相对位移等于 L 才能把两个物体的位移和速度联系起来","do":"分别写出子弹位移 x1 与木块位移 x2 的运动学表达式，令二者之差等于 L","expr":"x_{1}-x_{2}=L","cues":["相对位移是L","看穿出条件","两个位移相减"],"concepts":["相对位移","运动学公式","追及相遇"]},{"title":"动量守恒求末速","type":"关系建立","judge":"要判断子弹与木块组成的系统在水平方向不受外力，相互作用前后动量守恒，从而用 v0 和 v2 表示子弹穿出后的速度 v1","why":"水平面光滑、阻力是系统内力，动量守恒成立；不先用它消去 v1，就无法得到只含 v0 和 v2 的方程","do":"列 mv0=mv1+Mv2，把 v1 用 v0、v2 表示后代入位移关系","expr":"mv_{0}=mv_{1}+Mv_{2}","cues":["取整体","水平方向没外力","先消掉子弹末速"],"concepts":["动量守恒","系统内力","整体法"]},{"title":"消元得速度函数","type":"数学处理","judge":"要判断应把 v2 写成仅关于 v0 的函数，再对 v0 求极值，而不是对某个固定过程求极值","why":"题目问的是“改变 v0 使木块获得速度最大”，v0 是自变量，必须先得到 v2(v0) 的显式函数才能求最大值","do":"联立动量守恒与位移关系，解出 v2 关于 v0 的表达式，把根号部分作为求极值对象","expr":"v_{2}=\\frac{m\\left[v_{0}-\\sqrt{v_{0}^{2}-2\\left(\\frac{kv_{0}}{m}+\\frac{kv_{0}}{M}\\right)L}\\right]}{M+m}","cues":["写成关于初速的函数","对初速求极值","先消元再求导"],"concepts":["函数关系","极值","联立方程"]},{"title":"根号内非负定范围","type":"临界条件","judge":"要判断根号内表达式必须非负，这给出 v0 的取值下限，极值点恰好落在该临界值上","why":"子弹能穿出木块要求相对位移能达到 L，根号内为负则物理上不可能穿出；极值只能在允许区间端点取得","do":"令根号内表达式等于零，解出临界初速度，并判断 v2 在该点取最大","expr":"v_{0}^{2}-2\\left(\\frac{kv_{0}}{m}+\\frac{kv_{0}}{M}\\right)L\\ge 0","cues":["根号不能为负","刚好穿出","临界初速"],"concepts":["临界条件","定义域","恰好穿出"]},{"title":"生热用相对位移","type":"结论整理","judge":"要判断摩擦生热 Q=fL 中的 L 是相对位移，且 f 要代入临界情形下的 kv0，而不是用某个固定力乘位移","why":"热量等于摩擦力乘相对路程，本题相对路程恰为木块长度；同时 f 随 v0 变化，必须用极值点的 v0 代入","do":"用 Q=fL 计算生热，并用平均速度公式求木块位移 x2，与选项比对","expr":"Q=fL=\\frac{2k^{2}L^{2}(m+M)}{mM},\\quad x_{2}=\\frac{mL}{m+M}","cues":["热量看相对位移","力要代临界值","木块位移用平均速度"],"concepts":["摩擦生热","相对路程","平均速度"]}],"742":[{"title":"入射角与折射角的几何转化","type":"几何关系","judge":"要判断入射角和折射角分别对应圆弧上哪一段垂线长度与半径之比","why":"光沿 CO 射向圆心 O，入射点在半圆弧上，法线为过 O 的半径方向；折射光线沿 OM 射出，两角都是弦与半径的夹角，需用垂线长比半径表示其正弦","do":"对 P、M 分别作 BB' 的垂线，把 sin i 写成 PP' 与半径之比、sin r 写成 MM' 与半径之比","expr":"\\sin i=\\frac{y}{R},\\ \\sin r=\\frac{x}{R}","cues":["垂线比半径","入射角看P点","折射角看M点"],"concepts":["折射定律","几何关系","法线"]},{"title":"折射率化为图像斜率","type":"关系建立","judge":"要判断 y-x 图像的斜率与折射率是什么关系，而不是把某个坐标点当结果","why":"由折射定律 n=sin i/sin r，代入几何表达式后半径 R 约去，n 只由 y 与 x 的比值决定，多组数据应通过斜率统一求出","do":"把折射定律与正弦表达式联立，消去 R，写出 y 与 x 的正比关系，指出斜率即折射率","expr":"n=\\frac{\\sin i}{\\sin r}=\\frac{y}{x}","cues":["半径约掉了","斜率就是折射率","取图线不要取单点"],"concepts":["折射定律","图像法","斜率"]},{"title":"图像取点算斜率","type":"图像读取","judge":"要判断从图线上取哪两点算斜率（取图线上相距较远的整点，而非某一组原始数据点）","why":"图线是多次测量拟合的结果，取线上远距离两点可减小读数误差，得到三位有效数字","do":"在 y-x 图线上选取两个便于读数的点，用纵坐标差比横坐标差求斜率","expr":"n=\\frac{\\Delta y}{\\Delta x}","cues":["取图线上的点","两点隔远些","别用原数据点"],"concepts":["图像斜率","有效数字"]},{"title":"入射角不能过小的判断","type":"前提判断","judge":"要判断入射角很小时折射角也很小，角度的相对测量误差会被放大","why":"正弦值小时同样的长度测量误差对应的角度误差更大，折射角测量不准会直接放大 n 的误差","do":"比较入射角很小与适中两种情形下折射角测量的相对误差，说明入射角应适当大些","expr":"","cues":["角太小误差大","入射角要适当","别贴着法线射"],"concepts":["实验误差","角度测量"]},{"title":"轮廓半径偏差的影响","type":"误差分析","judge":"要判断画出的半圆弧半径偏大时，x、y 是否同比例变化、比值是否改变","why":"x、y 都是同一圆弧上的垂线长，半径画大只改变 R 的取值，sin i 与 sin r 中的 R 同时变化并在比值中约去","do":"把半径偏差代入 sin i、sin r 的表达式，检查 n=y/x 中是否还含 R","expr":"n=\\frac{y/R}{x/R}=\\frac{y}{x}","cues":["半径同时约去","比值不变","只影响R不影响n"],"concepts":["误差分析","折射率"]}],"743":[{"title":"周期由总时间折算","type":"前提判断","judge":"30 次全振动的时间 t 是总时间还是单次周期，周期该用 t 除以多少次","why":"周期定义为一个完整振动所需时间，计时器记录的是 30 个完整周期的总时长","do":"把总时间 t 平均分到 30 个全振动上","expr":"T=\\frac{t}{30}","cues":["除以三十","总时间摊开","一次全振动"],"concepts":["周期","全振动"]},{"title":"振子质量与平衡伸长挂钩","type":"关系建立","judge":"振子质量 M 与弹簧平衡时的伸长量之间靠什么规律联系，能否用平衡条件把 M 换成伸长量","why":"周期公式中的 M 是振子总质量，而平衡时重力与弹力平衡给出 M g = k Δl，两式联立才能消去未知的 k 和 M","do":"由周期公式解出 M=kT²/(4π²)，再代入平衡条件 Mg=kΔl 求伸长量","expr":"M=\\frac{kT^{2}}{4\\pi^{2}},\\quad Mg=k\\Delta l\\Rightarrow \\Delta l=\\frac{gT^{2}}{4\\pi^{2}}","cues":["用平衡条件","消掉劲度系数","伸长量换成周期"],"concepts":["弹簧振子周期","平衡条件","劲度系数"]},{"title":"弹簧长度含原长","type":"几何关系","judge":"米尺量出的 l 是弹簧总长还是伸长量，关系式里要不要加原长 l₀","why":"题设明确 l 为平衡时弹簧的长度，而平衡条件给出的是伸长量 Δl，两者相差原长","do":"把总长写成原长加伸长量，得到 l 与 T² 的线性关系","expr":"l=l_{0}+\\frac{g}{4\\pi^{2}}T^{2}","cues":["总长等于原长加伸长","别漏原长","截距是原长"],"concepts":["弹簧原长","伸长量"]},{"title":"斜率反解重力加速度","type":"图像读取","judge":"l-T² 图线的斜率对应 g/(4π²) 还是别的组合，取哪两点算斜率","why":"关系式 l=l₀+gT²/(4π²) 是线性函数，斜率只由 g 和 π 决定，截距为原长","do":"在图上取相距较远的两点读 (T², l)，用斜率等于 g/(4π²) 反解 g","expr":"k_{\\text{斜}}=\\frac{g}{4\\pi^{2}}=\\frac{0.542-0.474}{0.58-0.30}","cues":["斜率是g比四派方","取两点求斜率","截距不用管"],"concepts":["化曲为直","图像斜率","有效数字"]},{"title":"误差来源的甄别","type":"误差分析","judge":"哪些因素真正改变周期测量或斜率，哪些只平移图线而不影响 g","why":"g 只由斜率决定，凡是只改变截距（如弹簧自重、原长偏差）的因素不引入 g 的误差；改变周期或计时起止位置的因素才会","do":"逐项判断该因素作用于斜率还是截距，只保留影响周期测量的项","expr":"","cues":["看影响斜率还是截距","阻力改变周期","光电门位置要准"],"concepts":["系统误差","图像斜率","空气阻力"]}],"744":[{"title":"判断气体压强不变","type":"前提判断","judge":"活塞缓慢移动过程中封闭气体压强是否保持不变","why":"活塞质量、面积不变且无摩擦，缓慢移动时始终处于受力平衡，故封闭气体压强恒等于外界压强加活塞重力压强","do":"对活塞列竖直方向受力平衡，比较初末两态的压强表达式","expr":"p=p_0+\\dfrac{mg}{S}","cues":["活塞缓慢移动","受力平衡","压强不变"],"concepts":["受力平衡","封闭气体压强"]},{"title":"选等压过程定律","type":"模型选择","judge":"用哪个气体实验定律联系初末两态的体积与温度","why":"气体压强恒定、质量不变，属于等压变化，应选盖-吕萨克定律而非玻意耳或查理定律","do":"写出初末两态体积与温度之比相等的关系式","expr":"\\dfrac{V_0}{T_0}=\\dfrac{V_1}{T_1}","cues":["等压变化","用盖-吕萨克","体积比等于温度比"],"concepts":["盖-吕萨克定律","等压变化"]},{"title":"体积用气柱高表示","type":"几何关系","judge":"如何把气柱高度变化换算成体积变化","why":"容器为圆柱形，体积等于横截面积乘气柱高度，高度增加五分之一即体积增加五分之一","do":"用底面积乘高度写出初末体积，并代入高度增量","expr":"V_0=hS,\\quad V_1=\\left(h+\\dfrac{h}{5}\\right)S","cues":["体积等于底面积乘高","高度增加五分之一","面积不变"],"concepts":["圆柱体积","气柱高度"]},{"title":"判断做功的正负与大小","type":"关系建立","judge":"气体对外做功取正还是取负，大小由哪个压强决定","why":"气体膨胀对外做功，且过程等压，做功等于恒定压强乘体积增量，压强须用封闭气体压强而非大气压强","do":"用封闭气体压强乘以体积增量计算对外做功","expr":"W=p\\Delta V=\\left(p_0+\\dfrac{mg}{S}\\right)\\cdot\\dfrac{hS}{5}","cues":["膨胀对外做功","用封闭气体压强","压强乘体积增量"],"concepts":["等压膨胀"]},{"title":"用热力学第一定律求吸热","type":"关系建立","judge":"吸收的热量等于内能增量与对外做功之和还是之差","why":"热力学第一定律中吸热为正、对外做功为正，故吸收热量等于内能增加量加对外做功","do":"先由内能公式算内能增量，再与做功相加得吸收热量","expr":"Q=\\Delta U+W=C\\Delta T+\\dfrac{1}{5}(p_0S+mg)h","cues":["先算内能增量","符号取正"],"concepts":["热力学第一定律","内能"]}],"745":[{"title":"判断物块是否先共速","type":"临界条件","judge":"物块在传送带上先加速，需判断它在到达右端前是否已经与传送带共速","why":"只有加速段长度小于带长，物块到右端时才已达到带速，之后匀速；否则到右端仍在加速，速度要另算","do":"由 μmg=ma 求加速度，再用 x=v带²/(2a) 求加速到带速所需位移，与带长 3.6 m 比较","expr":"a=\\mu g,\\quad x=\\frac{v_{\\text{带}}^2}{2a}","cues":["先算加速度","看能不能追上带速","比较加速距离和带长"],"concepts":["匀变速直线运动","摩擦力","共速"]},{"title":"碰撞前速度取值","type":"结论整理","judge":"共速判断成立后，碰前物块速度取传送带速度还是继续用运动学公式算末速","why":"物块与带共速后不再受摩擦力，做匀速运动，到右端速度保持带速不变","do":"由上一判断得出加速距离小于带长，直接取碰前速度等于带速","expr":"v=v_{\\text{带}}","cues":["后面匀速了","速度就是带速","不用再加速"],"concepts":["匀速直线运动","共速"]},{"title":"碰撞瞬间选系统用动量守恒","type":"模型选择","judge":"碰撞时间极短、水平方向不受外力冲量，应把物块与小球取为系统用动量守恒，而不是用能量守恒","why":"极短碰撞中绳的拉力、重力冲量可忽略，水平方向系统动量守恒；碰撞有能量损失，机械能不守恒","do":"取向右为正，列碰前物块动量等于碰后物块与小球动量之和，代入碰后物块速度 -1 m/s 求小球速度","expr":"m_{\\text{物}}v=m_{\\text{物}}v_1+m_{\\text{球}}v_2","cues":["取整体","碰撞用动量","别用能量守恒"],"concepts":["动量守恒定律","正碰","正方向"]},{"title":"速度方向定正负","type":"前提判断","judge":"碰后物块速度 1 m/s 水平向左，代入动量式时须取负号","why":"动量是矢量，一维问题须先规定正方向，方向相反的速度带负号，否则小球速度算错","do":"规定向右为正，物块碰后速度取 -1 m/s 代入动量守恒式","expr":"v_1=-1\\ \\mathrm{m/s}","cues":["向左取负","先定正方向","别丢负号"],"concepts":["动量矢量性","符号约定"]},{"title":"动能损失用初末动能差","type":"关系建立","judge":"系统损失的动能应等于碰前总动能减碰后总动能，而不是只算某一个物体的动能变化","why":"非弹性碰撞中部分动能转化为内能，损失量由系统初末动能差给出","do":"分别写出碰前物块动能与碰后物块、小球动能，作差求损失","expr":"\\Delta E_k=\\frac12 m_{\\text{物}}v^2-\\frac12 m_{\\text{物}}v_1^2-\\frac12 m_{\\text{球}}v_2^2","cues":["算总动能差","两个物体都要算","损失是初减末"],"concepts":["动能","非弹性碰撞","能量损失"]},{"title":"绕钉后绳不松弛的临界","type":"临界条件","judge":"小球绕 P 点转到 P 正上方时绳恰好不松弛，须由重力单独提供向心力确定该点最小速度","why":"绳只能拉不能推，恰好不松弛即绳张力为零，重力充当向心力，这是求 P 点最小距离的临界条件","do":"在 P 正上方对小球列牛顿第二定律，圆周半径取绳长减 O、P 间距，再与 O 正下方到 P 正上方的机械能守恒式联立求间距","expr":"m_{\\text{球}}g=m_{\\text{球}}\\frac{v_3^2}{L-d},\\quad \\frac12 m_{\\text{球}}v_2^2=\\frac12 m_{\\text{球}}v_3^2+m_{\\text{球}}g(2L-d)","cues":["绳刚好不松弛","重力当向心力","半径是绳长减间距"],"concepts":["向心力","机械能守恒","临界速度","圆周运动半径"]}],"746":[{"title":"棒下滑的机械能守恒","type":"模型选择","judge":"棒从圆弧最高点滑到 MP 的过程中，能否用机械能守恒求速度","why":"圆弧导轨光滑、无摩擦，只有重力做功，磁场在 MP 右侧，下滑过程无感应电流","do":"对棒从最高点到 MP 用动能定理或机械能守恒，求出越过 MP 时的速度","expr":"mgL=\\frac{1}{2}mv_0^2","cues":["光滑无摩擦","只有重力做功","用动能定理"],"concepts":["机械能守恒","动能定理"]},{"title":"环接入电路的等效电阻","type":"模型选择","judge":"金属环放在两导轨上时，哪几段圆弧接入回路、如何连接","why":"导轨与环接触的两点把环分成两段，导轨外侧部分被导轨短路，只有导轨间两段圆弧有电流","do":"由几何关系确定每段圆弧占环的比例，算出每段电阻，再判断两段并联","expr":"R_0=\\frac{1}{2}\\times\\frac{6R}{3}=R,\\quad R_{\\text{总}}=R+\\frac{R}{2}","cues":["两段圆弧并联","外侧被短路","按弧长分电阻"],"concepts":["并联电路","电阻定律"]},{"title":"环所受安培力的有效长度","type":"关系建立","judge":"环在导轨间两段圆弧上受到的安培力如何合成，有效长度取多少","why":"两段圆弧电流方向相反，安培力沿导轨方向叠加，有效长度等于导轨间距 L 的两倍关系需按两段分别算","do":"对每段圆弧用 F=BIL 求安培力，再对环整体列牛顿第二定律","expr":"2BL\\cdot\\frac{I}{2}=2ma","cues":["两段各受安培力","有效长度是L","对环整体列方程"],"concepts":["安培力","牛顿第二定律"]},{"title":"棒与环系统动量守恒","type":"前提判断","judge":"棒和环组成的系统在水平方向合外力是否为零，能否用动量守恒","why":"棒与环所受安培力等大反向，是系统内力，水平方向无外力","do":"把棒和环取整体，判断安培力为内力，列动量守恒","expr":"mv_0=(m+2m)v","cues":["安培力等大反向","取整体","水平方向不受外力"],"concepts":["动量守恒","内力与外力"]},{"title":"恰好不接触的临界条件","type":"临界条件","judge":"棒与环刚好不接触对应什么运动状态","why":"环加速、棒减速，若两者速度相等时仍未追上，之后间距只会增大","do":"令棒追上环的瞬间两者速度相等，作为临界情形","expr":"v_{\\text{棒}}=v_{\\text{环}}=\\frac{v_0}{3}","cues":["速度相等时追上","共速是临界","之后间距变大"],"concepts":["临界状态","追及问题"]},{"title":"用冲量与电荷量求相对位移","type":"数学处理","judge":"如何把棒与环的相对位移与通过回路的电荷量联系起来","why":"安培力冲量 BILt=BLq 可由动量定理求 q，而 q 又等于磁通量变化除以总电阻，磁通量变化正比于相对位移","do":"对棒列动量定理求 BLq，再由 q=BLΔx/R总 解出相对位移","expr":"BLq=\\frac{2}{3}mv_0,\\quad q=\\frac{BL(x_1-x_2)}{R_{\\text{总}}}","cues":["安培力冲量","相对位移"],"concepts":["动量定理","电荷量公式","磁通量变化"]}],"747":[{"title":"光电效应的频率条件","type":"前提判断","judge":"要判断能否发生光电效应取决于入射光频率与金属极限频率的大小关系，而不是光强或照射时间","why":"光电效应方程 hν=W₀+Eₖ 表明只有 ν 超过极限频率 ν₀ 才有光电子逸出，与光强无关","do":"比较红光与紫光的频率高低，再与同一金属的极限频率比较，判断紫光能否使该金属发生光电效应","expr":"h\\nu \\ge W_0","cues":["看频率高低","和极限频率比","紫光频率更大"],"concepts":["光电效应","极限频率","光子能量"]},{"title":"能量量子化的提出者","type":"前提判断","judge":"要判断能量一份一份（量子化）这一思想由谁提出，不能与光电效应、物质波等其他量子论内容混淆","why":"普朗克为解释黑体辐射提出能量子假设，是量子论的起点；爱因斯坦提出光量子解释光电效应，德布罗意提出物质波","do":"把“能量量子化”这一说法对应到普朗克的黑体辐射能量子假设上","expr":"","cues":["普朗克提能量子","黑体辐射量子化","别记成爱因斯坦"],"concepts":["能量量子化","黑体辐射","普朗克"]},{"title":"康普顿散射的守恒与波长","type":"关系建立","judge":"要判断光子与电子碰撞后光子动量如何变化，并由动量与波长的关系推出波长变化方向","why":"康普顿散射中光子与电子系统动量守恒、能量守恒，电子获得动量则光子动量减小，由 λ=h/p 得波长变长","do":"写出光子动量减小的事实，再用 λ=h/p 判断散射后 X 射线波长变长而非变短","expr":"\\lambda=\\frac{h}{p}","cues":["动量守恒","光子动量变小","波长变长"],"concepts":["康普顿散射","动量守恒","德布罗意关系"]},{"title":"物质波的适用范围","type":"结论整理","judge":"要判断德布罗意物质波只适用于电子还是适用于所有实物粒子","why":"德布罗意假设任何运动的实物粒子都对应一列物质波，质子、电子等均具有波动性","do":"确认“物质都具有波动性”这一表述覆盖质子与电子，不把它局限为电子特有","expr":"\\lambda=\\frac{h}{p}","cues":["所有粒子都有波","不只在电子","质子也有"],"concepts":["物质波","德布罗意波"]}],"748":[{"title":"由抖动频率求周期","type":"前提判断","judge":"每分钟抖动 60 次对应波的频率与周期各是多少","why":"波源抖动一次形成一个完整波形，频率由抖动快慢直接决定，是后续算波速和判断质点运动的基准","do":"把每分钟次数换算成每秒次数，取倒数得周期","expr":"f=\\frac{60}{60}\\,\\mathrm{Hz}=1\\,\\mathrm{Hz},\\quad T=\\frac{1}{f}=1\\,\\mathrm{s}","cues":["每分钟六十次","一秒抖一次","周期就是一秒"],"concepts":["频率","周期","波源振动"]},{"title":"由波峰波谷间距定波长","type":"几何关系","judge":"A 在波谷、B 在波峰且中间还夹一个波谷，两点平衡位置间距对应几个波长","why":"相邻波谷与波峰相差半个波长，中间再有一个波谷说明两者之间跨过完整的半个波长再加一个整波长，间距与波长的倍数关系必须数准","do":"从 A 的波谷数到 B 的波峰，数出中间隔的波谷个数，确定间距是波长的几分之几倍","expr":"x_{AB}=1.5\\lambda=6\\,\\mathrm{m}\\Rightarrow\\lambda=4\\,\\mathrm{m}","cues":["中间还有一个波谷","一个半波长","数波峰波谷"],"concepts":["波长","波峰波谷","空间周期性"]},{"title":"波速由波长频率相乘","type":"关系建立","judge":"用波长和频率怎样得到波速","why":"简谐横波波速等于一个周期内波形平移的距离，即波长与频率之积，这是波速与波源振动联系的桥梁","do":"把已求出的波长与频率相乘","expr":"v=\\lambda f=4\\times1\\,\\mathrm{m/s}=4\\,\\mathrm{m/s}","cues":["波长乘频率","一个周期传一个波长"],"concepts":["波速","波长","频率"]},{"title":"按时间占周期比例推质点位置","type":"关系建立","judge":"经过 0.25 s 或 0.50 s 后，处于波峰或波谷的质点运动到哪个位置、速度多大","why":"质点做简谐运动，四分之一周期恰好从波峰（谷）走到平衡位置，半个周期恰好走到相反的波峰（谷），位置决定速度大小","do":"把给定时间除以周期，看是四分之一还是二分之一，再从初始波峰或波谷出发推末位置与速度","expr":"0.25\\,\\mathrm{s}=\\frac{T}{4},\\quad 0.50\\,\\mathrm{s}=\\frac{T}{2}","cues":["半个周期到对面","波峰处速度为零"],"concepts":["简谐运动","周期","位移与速度"]}],"749":[{"title":"区分绳与弹簧的瞬时性","type":"前提判断","judge":"剪断瞬间，哪些连接件的弹力可以突变、哪些不能突变","why":"细线（绳）的张力由约束决定，剪断后立即消失；轻弹簧的弹力由形变决定，形变来不及改变，瞬间弹力保持原值","do":"对 B、C 之间的细线判定为瞬间消失，对 C、D 之间的弹簧判定为瞬间保持剪断前的拉力","expr":"","cues":["弹簧来不及变","绳的力立刻没","剪断瞬间看形变"],"concepts":["弹力突变","弹簧的瞬时性"]},{"title":"剪断前求弹簧拉力","type":"关系建立","judge":"剪断前 C、D 间弹簧的拉力由哪部分的重力平衡决定","why":"系统静止，弹簧下端只挂 D，弹簧拉力只平衡 D 的重力，与上方各球无关","do":"对 D 单独受力平衡，求弹簧对 D 的拉力","expr":"F_{CD}=mg","cues":["只看D","弹簧只吊着D","别把上面的算进去"],"concepts":["受力平衡","隔离法"]},{"title":"剪断瞬间 B 的受力","type":"模型选择","judge":"剪断瞬间 B 受哪些力，上方绳的拉力是否也突变","why":"B 上方的绳未剪断，但绳的张力会随 B 的运动状态瞬间调整，不能沿用剪断前的值；剪断后 B 只受上方绳拉力和自身重力","do":"对 B 列牛顿第二定律，上方绳拉力取剪断后重新确定的值，不能直接代入剪断前求得的 AB 段张力","expr":"F_{AB}'-3mg=3ma_B","cues":["上面的绳也会变","不能沿用旧拉力","绳力可突变"],"concepts":["牛顿第二定律","绳的张力突变"]},{"title":"剪断瞬间 C 的合力方向","type":"临界条件","judge":"剪断瞬间 C 受到的弹簧拉力与自身重力谁大，合力方向朝哪","why":"弹簧拉力保持 mg 不变，而 C 的重力为 2mg，重力大于弹簧拉力，合力竖直向下","do":"比较弹簧拉力 mg 与 C 的重力 2mg，确定合力方向向下","expr":"2mg-F_{CD}=2ma_C","cues":["弹簧力还是mg","重力更大","合力向下"],"concepts":["合力方向","牛顿第二定律"]}],"750":[{"title":"等效为转动导体棒","type":"模型选择","judge":"能否把弯曲导线看成 O 到各点的直棒各自切割磁感线","why":"弯曲导线上每段的速度方向不同，直接积分困难；但绕 O 转动时，O 到任一点连线上各点速度都垂直于连线，等效电动势只由端点位置决定","do":"把 Oa、Ob、Oc 三条连线分别当作绕 O 转动的导体棒，比较它们产生的电动势","expr":"E=\\tfrac12 B\\omega l^2","cues":["等效成直棒","看两端连线","弯曲部分不用管"],"concepts":["动生电动势","等效切割长度"]},{"title":"判断电势高低方向","type":"前提判断","judge":"用右手定则判断 O 与 a、b、c 哪端电势高","why":"磁场垂直纸面向里、导线逆时针转动，由右手定则确定正电荷受力方向，从而定出高电势端","do":"对 Oa 棒用右手定则：四指指向速度方向，磁感线穿掌心，拇指指向高电势端","expr":"","cues":["右手定则","O点电势最高","正电荷往哪走"],"concepts":["右手定则","洛伦兹力"]},{"title":"比较各棒长度","type":"几何关系","judge":"Ob、Oc 与 Oa 的长度关系","why":"电动势与棒长平方成正比，必须先由几何求出各连线长度才能比较电势差","do":"由 Oa=R 且垂直直径 ac、半圆半径 R，算出 O 到 b、c 的距离","expr":"l_{Oa}=R,\\quad l_{Ob}=l_{Oc}=\\sqrt{R^2+(2R)^2}=\\sqrt5 R","cues":["勾股定理","半径加直径","b是中点"],"concepts":["几何关系","半圆弧"]},{"title":"由长度平方比电势差","type":"关系建立","judge":"电动势大小随棒长如何变化，进而定 a、b、c 电势顺序","why":"同一角速度下 E∝l²，长度越大电动势越大，沿电流方向电势降落越多","do":"比较 R² 与 5R²，得 U_Oa<U_Ob=U_Oc，再结合 O 最高排出顺序","expr":"U_{Oa}:U_{Ob}:U_{Oc}=1:5:5","cues":["长度平方成正比","b和c一样长","a最短"],"concepts":["动生电动势","电势差"]}],"751":[{"title":"把用户电阻折算到输电线侧","type":"模型选择","judge":"判断输电线回路中除 R0 外还应串入什么等效电阻，才能把降压变压器和用户端一并纳入一个串联回路","why":"理想变压器只变电压电流不变功率，副线圈接 R 等效到原线圈侧为 k²R（k 为降压比），这样才能用闭合电路欧姆定律求输电线电流","do":"设降压变压器原副线圈匝数比为 k:1，把用户电阻 R 按阻抗折算到降压变压器原线圈侧，画出含 R0 与 k²R 的等效串联回路","expr":"I_{2}=\\frac{U_{2}}{R_{0}+k^{2}R}","cues":["折算到高压侧","等效成一个电阻","先求输电线电流"],"concepts":["理想变压器","等效电阻","闭合电路欧姆定律"]},{"title":"电源电动势随角速度变化","type":"关系建立","judge":"判断转子角速度改变时，升压变压器原线圈电压（即发电机电动势有效值）按什么规律变","why":"转子在匀强磁场中匀速转动产生正弦交流电，峰值 Em=NBSω，有效值与 ω 成正比，ω 加倍则原线圈电压加倍","do":"写出 e=NBSω sinωt，取有效值 E=NBSω/√2，比较 ω 加倍前后 E 与升压变压器原线圈电压的关系","expr":"E=\\frac{NBS\\omega}{\\sqrt{2}}","cues":["电动势跟转速成正比","角速度加倍电压加倍","先看发电机电压"],"concepts":["交变电流","电动势峰值","有效值"]},{"title":"理想变压器电压按匝数比传递","type":"关系建立","judge":"判断升压变压器副线圈电压 U2 由原线圈电压和匝数比共同决定，而不是只由其中一个决定","why":"理想变压器 U1/U2=n1/n2，U2 同时正比于 U1 和副线圈匝数 n2，ω 加倍或 n2 加倍都会使 U2 加倍","do":"写出 U2=U1·n2/n1，分别讨论 ω 加倍、n2 加倍时 U2 的变化倍数","expr":"\\frac{U_{1}}{U_{2}}=\\frac{n_{1}}{n_{2}}","cues":["电压比等于匝数比","两个因素都影响"],"concepts":["理想变压器","电压比"]},{"title":"功率随电流平方变化","type":"关系建立","judge":"判断 R0 上消耗的功率由输电线电流决定，电流变几倍功率就变几倍的平方","why":"定值电阻功率 P=I²R0，与电流平方成正比，不能按电流倍数线性外推","do":"由 I2=U2/(R0+k²R) 判断 U2 加倍时 I2 加倍，再算 P'=I2'²R0 与原 P 的倍数关系","expr":"P=I_{2}^{2}R_{0}","cues":["功率看电流平方","电流翻倍功率四倍","别按线性算"],"concepts":["电功率","焦耳定律"]},{"title":"改电阻时电流不按比例变","type":"临界条件","judge":"判断改变 R0 或用户电阻时，回路总电阻中还有 k²R 或 R0 另一项，电流不会简单反比变化","why":"I2=U2/(R0+k²R)，分母是两项之和，只把其中一项加倍或减半，总电阻并不加倍或减半，功率更不等于 4P 或 6P","do":"分别把 R0 换成 2R0、把 R 换成 R/2 代入 I2 表达式，比较新电流与原电流，再算 R0 上功率","expr":"I_{2}''=\\frac{U_{2}}{2R_{0}+k^{2}R},\\quad I_{2}'''=\\frac{2U_{2}}{2R_{0}+k^{2}R}","cues":["分母是两项和","不能直接反比","代进去比一比"],"concepts":["串联电路","等效电阻","电功率"]}],"752":[{"title":"贴月飞行的向心力来源","type":"模型选择","judge":"返回舱在半径近似等于月球半径的圆轨道上，向心力由什么提供、用哪个半径","why":"轨道半径近似为月球半径，万有引力全部充当向心力，此时引力大小又等于月面重力，两个关系必须同时用上才能把 GM 消掉","do":"对返回舱列万有引力提供向心力的方程，再对月面物体列重力等于引力的方程，联立消去 GM月","expr":"G\\frac{M_月 m}{r_月^2}=m\\frac{v_月^2}{r_月},\\quad G\\frac{M_月 m}{r_月^2}=mg_月","cues":["引力当向心力","半径就是月半径","两个式子联立"],"concepts":["万有引力定律","向心力","黄金代换"]},{"title":"用表面重力表示环绕速度","type":"关系建立","judge":"能否把环绕速度写成只含表面重力加速度和星球半径的形式，以便与地球比较","why":"题目只给了 g 和 R 的比例，没有给月球质量，必须把 GM 换成 gR² 才能代入数据","do":"由两式消去 GM月，解出 v月 的表达式，再对地球近地卫星写出同形式 v地","expr":"v=\\sqrt{gR}","cues":["换成重力加速度","根号下重力乘半径","和地球比"],"concepts":["第一宇宙速度","黄金代换"]},{"title":"第一宇宙速度作比较基准","type":"前提判断","judge":"判断“近地环绕速度”与地球第一宇宙速度是不是同一个量，能否直接拿来作比值","why":"地球近地卫星同样是引力提供向心力且轨道半径近似等于地球半径，形式完全一致，才能用同一公式做比值","do":"确认 v地=√(g地R地) 就是地球第一宇宙速度，再代入 g月/g地=1/6、R月/R地=1/4","expr":"\\frac{v_月}{v_地}=\\sqrt{\\frac{g_月 R_月}{g_地 R_地}}=\\sqrt{\\frac{1}{6}\\cdot\\frac{1}{4}}","cues":["近地卫星同款","比值代进去","六分之一乘四分之一"],"concepts":["第一宇宙速度","比值法"]},{"title":"周期随半径与速度换算","type":"关系建立","judge":"比较周期时用 T=2πr/v 还是只比 v，半径不同不能直接反比","why":"月、地轨道半径不同，周期同时依赖 r 和 v，必须把半径比一并代入，否则会误判为周期与速度成反比","do":"写出 T=2πr/v，代入 r月/r地=1/4 与已得的 v月/v地，求 T月/T地","expr":"T=\\frac{2\\pi r}{v},\\quad \\frac{T_月}{T_地}=\\frac{r_月}{r_地}\\cdot\\frac{v_地}{v_月}","cues":["周期还要乘半径","不能只看速度","半径比四分之一"],"concepts":["圆周运动周期","线速度与周期关系"]}],"753":[{"title":"安培力冲量化为位移","type":"关系建立","judge":"能否把安培力的冲量用滑行位移表示，而不去求速度随时间的变化","why":"安培力 F=B²L²v/(2R) 与速度成正比，对时间累积时 ΣvΔt 恰好等于位移，这是本题唯一能绕过变力做功的通道","do":"对微元过程写动量定理，把 BILΔt 中的 vΔt 换成 Δx，再对整段求和","expr":"-\\frac{B^{2}L^{2}}{2R}\\sum v_t\\Delta t=-\\frac{B^{2}L^{2}x}{2R}","cues":["冲量换成位移","速度乘时间就是路程","不用求末速度"],"concepts":["安培力冲量","动量定理","微元求和"]},{"title":"两段磁场冲量相同","type":"前提判断","judge":"判断杆在光滑段和粗糙段各滑行 d 时，安培力冲量是否相等","why":"冲量只由 B²L²x/(2R) 决定，与接触面是否粗糙、运动快慢无关，两段位移都是 d 故冲量相同","do":"分别写出两段的安培力冲量表达式，比较其中的 x 是否都为 d","expr":"I_{A1}=I_{A2}=\\frac{B^{2}L^{2}d}{2R}","cues":["两段位移一样","冲量只看走了多远","粗糙不影响安培冲量"],"concepts":["安培力冲量","位移"]},{"title":"粗糙段引入摩擦冲量","type":"模型选择","judge":"在 BC 段是否必须把摩擦力作为独立冲量计入动量方程","why":"粗糙段有摩擦，动量变化由安培力冲量与摩擦冲量共同决定，漏掉摩擦就无法把 v_B 与 v_0 联系起来","do":"对 BC 段写动量定理，安培冲量项加 μmg t₀ 项，与 AB 段方程联立消去 B²L²d/(2R)","expr":"-\\frac{B^{2}L^{2}d}{2R}-\\mu mgt_0=-mv_B","cues":["粗糙段要加摩擦","摩擦力也有冲量","两段方程联立"],"concepts":["摩擦冲量","动量定理"]},{"title":"比较过B点速度与半初速","type":"数学处理","judge":"由联立结果判断 v_B 与 v₀/2 的大小关系","why":"联立两段方程消去磁场项后得 v_B=v₀/2+μgt₀/2，摩擦项恒正，故 v_B 必大于 v₀/2","do":"把 AB 段与 BC 段动量方程相加消去 B²L²d/(2R)，解出 v_B 的表达式再与 v₀/2 比较","expr":"v_B=\\frac{v_0}{2}+\\frac{\\mu gt_0}{2}>\\frac{v_0}{2}","cues":["消掉磁场那项","摩擦让速度更大","比一半要大"],"concepts":["动量定理","速度比较"]},{"title":"热量按电阻分配","type":"结论整理","judge":"总焦耳热中定值电阻 R 分得的份额是多少","why":"杆电阻也为 R，与定值电阻串联，两者发热功率相同，故定值电阻只占总热量的一半","do":"先用能量守恒求总热量 Q=½mv₀²-μmgd，再取一半作为 R 上的热量","expr":"Q_R=\\frac{1}{2}Q=\\frac{1}{4}mv_0^{2}-\\frac{1}{2}\\mu mgd","cues":["两个电阻平分热量","先算总热量","串联电流相同"],"concepts":["能量守恒","焦耳热分配","串联电路"]},{"title":"初速加倍后距离比较","type":"临界条件","judge":"初速度加倍后，磁场中滑行距离是否恰好变为原来的两倍","why":"磁场中总冲量含摩擦项 μmg t，速度加倍后运动时间变短，摩擦冲量占比减小，安培冲量（正比于距离）占比增大，故距离超过 2 倍","do":"对加倍初速重写全程动量方程，比较摩擦冲量项与原来 t₀ 时的大小，得出 x 与 2d 的关系","expr":"x=\\frac{2mv_0-\\mu mgt_1}{mv_0-\\mu mgt_0}\\cdot 2d>4d","cues":["时间变短摩擦冲量小","距离不止两倍","摩擦占比变了"],"concepts":["动量定理","冲量分配","非线性关系"]}],"754":[{"title":"确定相干光源来源","type":"模型选择","judge":"判断参与干涉的两束相干光分别来自哪里，能否等效为双缝","why":"洛埃镜中直射光与平面镜反射光是同一光源分出的两束，反射光可等效为虚像 S' 发出，S 与 S' 构成一对相干光源","do":"画出 S 经平面镜成的虚像 S'，把 S 与 S' 当作双缝的两个缝","expr":"","cues":["反射光等效虚像","直射加反射","看成双缝"],"concepts":["相干光","虚像","洛埃镜"]},{"title":"镜面水平时的缝距与屏距","type":"关系建立","judge":"判断 θ=0 时双缝间距 d 和光源到屏距离 l 各由什么几何量决定","why":"双缝干涉条纹间距由 Δx=lλ/d 决定，必须先把 d、l 与题给几何量（S 到镜面距离 a、S 到屏距离 l）对应起来","do":"由 S 与 S' 关于镜面对称，得 d=2a；l 取 S 到光屏的距离","expr":"$d=2a,\\quad \\Delta x=\\frac{l}{2a}\\lambda$","cues":["缝距是两倍距离","用双缝公式","对称得虚像"],"concepts":["双缝干涉","条纹间距"]},{"title":"平移镜面是否改变 d 和 l","type":"前提判断","judge":"判断 θ=0 时沿 OA 方向平移平面镜，d 与 l 是否变化","why":"d 只由 S 到镜面的垂直距离决定，l 只由 S 到屏的距离决定，沿镜面方向平移不改变这两个量","do":"比较平移前后 S 到镜面的垂距和 S 到屏的距离，确认均不变","expr":"","cues":["沿镜面平移","垂距没变","屏距没变"],"concepts":["对称","条纹间距不变"]},{"title":"倾斜后虚像位置变化","type":"几何关系","judge":"判断镜面倾斜微小角度 θ 后，虚像 S' 相对 S 的位置如何改变，从而 d 和条纹位置如何变","why":"镜面倾斜使 S 的对称点 S' 绕镜面转动方向偏移，S 与 S' 的连线方向及间距都改变，双缝间距和条纹中心位置随之改变","do":"以镜面为对称轴重新作 S'，比较倾斜前后 S' 的横向偏移与 S、S' 间距","expr":"","cues":["虚像跟着转","缝距变大","条纹移动"],"concepts":["平面镜成像","对称性","条纹间距"]}],"755":[{"title":"碰后速度方向由反射定律定","type":"前提判断","judge":"碰后 B 球速度方向与挡板法线的夹角是否等于碰前夹角、且分居法线两侧，从而确定碰后速度方向","why":"题设明确给出碰撞前后速度与挡板法线夹角相同且位于法线两侧，等价于速度方向关于法线对称，这是画出碰后轨迹的唯一依据","do":"以挡板法线为对称轴，把碰前速度方向反射，得到碰后速度方向与 x 轴的夹角","expr":"","cues":["关于法线对称","反射定律","碰后方向怎么定"],"concepts":["速度方向","对称性","碰撞"]},{"title":"两球均做匀速直线运动","type":"模型选择","judge":"碰前碰后 A、B 是否都做匀速直线运动，从而位移可用速度乘时间表示","why":"水平面光滑、不计碰撞时间和空气阻力，两球各自不受合外力，速度大小方向均不变","do":"对 A 球和 B 球的两段运动分别写位移等于速度乘时间","expr":"s_1=v_2t_1,\\ s_2=v_2't_2,\\ s_A=v_1(t_1+t_2)","cues":["光滑所以匀速","分段算位移","速度不变"],"concepts":["匀速直线运动","位移"]},{"title":"相遇构成闭合三角形","type":"几何关系","judge":"把 A 的位移、B 的两段位移首尾相接，能否构成一个闭合三角形，并确定各内角","why":"两球同时从 O 出发、最终相遇于同一点，A 的位移与 B 的两段位移首尾相连必闭合；各边方向由速度方向决定，内角由 θ、α 组合得到","do":"画出 O→碰点→相遇点的折线与 O→相遇点的直线，标出三角形三个内角","expr":"","cues":["首尾相接闭合","画轨迹三角形","内角用θ和α表示"],"concepts":["位移矢量","矢量三角形","几何关系"]},{"title":"正弦定理联系速度与角","type":"关系建立","judge":"用正弦定理把三条边（含 t1、t2、v1）与三个内角联系起来，消去时间求 v1","why":"三角形中已知各角、边与速度成正比，正弦定理是唯一能同时含 t1、t2、v1 的等式，可解出 v1 关于 α 的表达式","do":"对闭合三角形列正弦定理，把 t1、t2 用 v1 和角表示后合并","expr":"\\frac{v_2t_1}{\\sin(2\\alpha+\\theta)}=\\frac{v_2't_2}{\\sin\\theta}=\\frac{v_1(t_1+t_2)}{\\sin(2\\alpha+2\\theta)}","cues":["用正弦定理","边角对应","消去时间"],"concepts":["正弦定理","矢量三角形"]},{"title":"对 α 求 v1 的极值","type":"数学处理","judge":"在 θ 固定时，v1 随 α 变化，需判断 α 取何值时 v1 最大以及最大值是多少","why":"选项问的是 v1 的最大值及对应 α，必须把 v1 写成 α 的函数再求极值，而不是任取一个 α","do":"把 θ=15° 或 30°、v2=2、v2'=1 代入 v1 表达式，对 α 求最大","expr":"v_1(\\alpha)=\\frac{v_2\\sin(2\\alpha+2\\theta)}{\\sin(2\\alpha+\\theta)}\\cdot\\frac{\\sin\\theta}{\\sin\\theta+\\sin(2\\alpha+\\theta)}","cues":["求最大值","α取多少","代入θ再算"],"concepts":["极值","三角函数"]}],"756":[{"title":"电压表读数规则","type":"实验操作","judge":"电压表量程 3 V 时，读数应估读到分度值的哪一位","why":"量程 0~3 V 对应分度值 0.1 V，电表读数须在最小分度下一位估读","do":"看表盘 0~3 V 刻度，确认分度值，读出整格数并估读一位小数","expr":"U=1.23\\,\\mathrm{V}","cues":["看量程","分度值多少","估读一位"],"concepts":["电压表读数","估读","量程与分度值"]},{"title":"伏安法测电阻的接线方式","type":"模型选择","judge":"由图(b)判断电流表是内接还是外接，从而确定 R=U/I 测的是哪部分","why":"外接时电压表与金属丝并联，电流表测的是总电流，R=U/I 是金属丝与电压表并联的等效电阻","do":"观察图(b)中电压表并联在金属丝两端、电流表在干路，确认是外接法","expr":"R_{\\text{测}}=\\frac{U}{I}","cues":["电压表并联","外接法","测的是总电流"],"concepts":["伏安法","外接法","并联分流"]},{"title":"由图像判断电阻随压强变化","type":"图像读取","judge":"从 R-p 图线判断压强减小时电阻是增大还是减小","why":"图(d)给出 R 随 p 的变化趋势，是判断电压如何变化的唯一依据","do":"读图(d)：p 越小对应的 R 越大，取 p=0.5 标准大气压与 1 标准大气压比较 R 的大小","expr":"p\\downarrow \\Rightarrow R\\uparrow","cues":["看图线走向","压强小电阻大","比较两点"],"concepts":["R-p 图像","控制变量","电阻与气压"]},{"title":"电流不变时电压随电阻变化","type":"关系建立","judge":"保持 I=100 mA 不变时，电压变化方向由 R 的变化方向决定","why":"欧姆定律 U=IR，I 不变则 U 与 R 成正比","do":"由 R 增大推出 U 增大，再与图(c)原指针位置比较，判断指针偏向哪侧","expr":"U=IR,\\quad I\\text{ 不变}","cues":["电流不变","电压跟电阻走","比原来大"],"concepts":["欧姆定律","正比关系"]},{"title":"电压表分流造成测量偏差","type":"误差分析","judge":"非理想电压表分流使电流表读数偏大还是偏小，从而判断测量值与真实值的大小关系","why":"外接法中电流表读数为 I_真+U/R_V，分母偏大导致 R_测=U/I_测 偏小","do":"写出 I_测=I_真+U/R_V，比较 R_测=U/I_测 与 R_真=U/I_真 的大小","expr":"I_{\\text{测}}=I_{\\text{真}}+\\frac{U}{R_V}\\Rightarrow R_{\\text{测}}<R_{\\text{真}}","cues":["电压表分流","电流表读数偏大","测量值偏小"],"concepts":["电压表分流","系统误差","外接法误差"]}],"757":[{"title":"周期由计时次数换算","type":"关系建立","judge":"第1次到第21次经过平衡位置之间包含多少个完整周期","why":"相邻两次经过平衡位置的时间间隔是半个周期，从第1次到第21次共20个半周期","do":"数出经过平衡位置的次数间隔，用总时间除以完整周期个数得到T","expr":"T=\\frac{t}{20/2}=\\frac{t}{10}","cues":["数间隔不数次数","二十次经过是十个周期","半周期要乘二"],"concepts":["简谐运动周期","平衡位置"]},{"title":"判据用T²而非T","type":"模型选择","judge":"验证周期与质量关系时该作T-m图还是T²-m图","why":"弹簧振子周期与总质量是平方根关系，平方后才与质量成线性，表格已给出T²列","do":"选T²为纵轴、m为横轴描点，判断是否为直线","expr":"T^{2}=\\frac{4\\pi^{2}}{k}(M_0+m)","cues":["先平方再画图","化曲为直","开方关系不好判断"],"concepts":["化曲为直","线性关系"]},{"title":"图线截距对应滑块质量","type":"关系建立","judge":"T²-m图线的斜率与纵轴截距各由什么决定","why":"总质量等于滑块质量加砝码质量，m=0时T²不为零，截距反映滑块自身质量","do":"写出T²与m的线性表达式，指出截距b=4π²M₀/k、斜率k_s=4π²/k","expr":"T^{2}=\\frac{4\\pi^{2}}{k}m+\\frac{4\\pi^{2}}{k}M_0","cues":["截距不是零","截距是滑块的质量","斜率跟劲度系数有关"],"concepts":["弹簧振子周期","等效质量"]},{"title":"待测质量由同一图线读出","type":"数据处理","judge":"待测物体质量应通过图线上T²=0.880对应的横坐标读取，而不是重新拟合","why":"待测物体与砝码等效，都加在滑块上，同一图线对任何附加质量都适用","do":"在已画直的图线上找纵坐标0.880的点，读横坐标即为待测质量","expr":"m_x=\\frac{T^{2}-b}{k_s}","cues":["在图线上找对应点","横坐标就是质量","不用另算斜率"],"concepts":["图像法测质量","等效替代"]},{"title":"换滑块后截距变化方向","type":"前提判断","judge":"滑块质量变小而弹簧不变时，图线是平移还是转动，沿哪个方向移动","why":"斜率只由劲度系数决定不变，截距正比于滑块质量，滑块变轻则同一m下T²变小","do":"比较新旧截距大小，判断整条直线沿纵轴平移的方向","expr":"b=\\frac{4\\pi^{2}}{k}M_0","cues":["斜率不变只平移","滑块轻了周期短","截距变小往下走"],"concepts":["图像截距","弹簧振子周期"]}],"758":[{"title":"等温膨胀的适用判断","type":"前提判断","judge":"第（1）问中气体从压强 p 膨胀到 p0 的过程能否按温度不变处理","why":"题设明确说'等温膨胀'，且气球内空气视为理想气体，只有温度不变才能用玻意耳定律联系两个状态的 p、V","do":"确认初态 (p, V)、末态 (p0, V0) 温度相同，对两态列 pV = p0V0","expr":"pV=p_{0}V_{0}","cues":["等温","温度不变","用玻意耳"],"concepts":["玻意耳定律","理想气体"]},{"title":"把气球内气体折算成同压体积","type":"关系建立","judge":"气球内气体在压强 p 下的体积 V，要换算成在大气压 p0 下占的体积 V0 才能算浮力","why":"阿基米德原理中的浮力用排开外界空气的体积，而外界空气压强为 p0，故必须用第（1）问的 V0 而不是 V","do":"由第（1）问结果写出 V0 = pV/p0，再用 m气 = ρ0 V0 表示球内气体质量","expr":"m_{\\text{气}}=\\rho_{0}V_{0}=\\rho_{0}\\frac{pV}{p_{0}}","cues":["换成大气压下的体积","浮力看排开体积","用V0不用V"],"concepts":["阿基米德原理","密度与质量"]},{"title":"选气球为对象做受力平衡","type":"模型选择","judge":"把气球（含内部气体）作为整体研究对象，还是把球壳与内部气体分开","why":"天平示数对应球壳对秤盘的压力，取气球整体可让内部气体与球壳间的作用力成为内力，只出现重力、浮力和支持力","do":"对气球整体列竖直方向平衡方程，把示数 m 与球壳质量 m0、气体质量 m气、浮力 ρ0gV 联系起来","expr":"mg+\\rho_{0}gV=m_{\\text{气}}g+m_{0}g","cues":["取气球整体","内力不出现","竖直方向平衡"],"concepts":["整体法","共点力平衡","浮力"]},{"title":"浮力用外界空气密度和排开体积","type":"关系建立","judge":"浮力式中的密度取外界空气密度 ρ0 还是球内气体密度，体积取 V 还是 V0","why":"浮力由气球排开的外部空气产生，排开体积就是气球外观体积 V，密度是外界空气密度 ρ0","do":"写出 F浮 = ρ0 g V，并注意它与气体质量式中的 ρ0V0 不是同一个体积","expr":"F_{\\text{浮}}=\\rho_{0}gV","cues":["浮力用外界密度","排开的是V","别和V0混"],"concepts":["阿基米德原理","浮力"]},{"title":"联立状态方程与平衡方程消元","type":"数学处理","judge":"如何把含 p、V 两个未知量的两个方程化成只含 V 的方程","why":"平衡方程给出 p 与 V 的一次关系，状态方程 (p−p0)(V−VB0)=C 给出 p 与 V 的另一关系，两式联立才能定出 V","do":"由平衡方程解出 p 的表达式，代入 (p−p0)(V−VB0)=C，整理成关于 V 的方程并求解","expr":"p=p_{0}+\\frac{m_{0}+\\rho_{0}\\frac{pV}{p_{0}}-m}{V}g","cues":["两式联立","先解出p","消去p求V"],"concepts":["方程联立","气体状态方程"]},{"title":"舍去不合理的体积根","type":"结论整理","judge":"解出的 V 是否满足 V > VB0 且压强 p > p0 的物理约束","why":"气球被撑大才有张力，p 必须大于 p0，故 V 必须大于无张力容积 VB0，否则状态方程左端为负与 C > 0 矛盾","do":"把求得的 V 代回检查 V 与 VB0 的大小关系及 p 与 p0 的大小关系，舍去不合物理意义的根","expr":"V>V_{B0},\\quad p>p_{0}","cues":["压强要大于大气压","舍去不合理的根"],"concepts":["物理意义检验","张力"]}],"759":[{"title":"磁场中运动分解","type":"模型选择","judge":"电子在匀强磁场中的运动应如何分解处理","why":"磁场沿 x 轴，电子初速度有 x 分量和 yOz 平面内分量；洛伦兹力只作用于垂直于 B 的速度分量，x 方向不受力","do":"把速度分解为沿 x 轴的 v0 和垂直于 x 轴的 vy，分别看两方向的运动性质","expr":"v_x=v_0,\\quad v_\\perp=v_y","cues":["沿磁场方向不受力","拆成两个方向","x方向匀速"],"concepts":["运动的分解","洛伦兹力","匀速圆周运动"]},{"title":"螺旋运动周期与螺距","type":"关系建立","judge":"电子从 O' 到 O 沿 x 走 L 的时间与圆周运动周期满足什么关系","why":"电子要恰好从 O 孔穿出，必须在 x 方向走完 L 的同时回到轴线上，即完成整数个圆周","do":"写出 x 方向匀速的时间 t=L/v0，圆周运动周期 T=2πm/(eB)，令 t=nT","expr":"t=\\frac{L}{v_0}=nT=\\frac{2\\pi n m}{eB}","cues":["回到轴线","整数个周期","螺距"],"concepts":["周期","螺旋线","回旋"]},{"title":"取最小磁场的整数条件","type":"临界条件","judge":"n 取何值时 B 最小，且是否满足所有电子都能过 O","why":"B 与 n 成正比，n 越小 B 越小；n=1 时 B 最小，此时所有不同 vy 的电子都恰在一个周期内到达 O","do":"由 t=nT 解出 B 的表达式，取 n=1 得最小值","expr":"B_{\\min}=\\frac{2\\pi m v_0}{eL}","cues":["n取1","周期数最少","B正比于n"],"concepts":["临界条件","磁感应强度"]},{"title":"最大夹角对应最大半径","type":"几何关系","judge":"速度方向与 x 轴夹角最大时，圆周运动半径受什么几何限制","why":"tanθ=vy/v0，vy 越大 θ 越大、半径 R=mvy/(eB) 越大；电子不能碰壁，R 最大只能等于筒半径 r","do":"令 R=r，结合 B 最小值反解 vy 的最大值","expr":"R=\\frac{mv_y}{eB}=r,\\quad \\tan\\theta=\\frac{v_y}{v_0}","cues":["半径最大到筒壁","不碰壁的极限","夹角看速度比"],"concepts":["几何约束","轨迹半径","速度分解"]},{"title":"电场中最大纵向位移","type":"关系建立","judge":"进入电场后 y 方向最大位移由哪个初速度分量和哪个加速度决定","why":"电场沿 y 正向，电子带负电受 y 负向恒力，做匀减速；y 向位移只由进入时的 vy 和加速度决定，与 x 向匀速无关","do":"用匀变速公式 ym=vy²/(2a)，加速度 a=Ee/m，代入最大 vy","expr":"y_m=\\frac{v_{ym}^2}{2a},\\quad a=\\frac{Ee}{m}","cues":["只看y方向","匀减速到零","最大位移用速度平方"],"concepts":["匀变速直线运动","牛顿第二定律","电场力"]}],"760":[{"title":"碰撞瞬间动量守恒","type":"模型选择","judge":"碰撞极短时间内判断圆环对球的法向作用是否可忽略，从而决定能否对A、B系统用动量守恒","why":"碰撞时间极短，环的弹力沿半径方向、在切向无冲量，切向合外力为零，故切向动量守恒","do":"取A、B为系统，沿圆环切线方向列碰撞前后动量守恒式，不引入环的弹力","expr":"m_A v_0=(m_A+m_B)v","cues":["沿切线方向","环的力不管","取两球系统"],"concepts":["动量守恒","切向冲量"]},{"title":"向心力由环弹力提供","type":"关系建立","judge":"判断结合体做圆周运动的向心力来源是圆环的弹力，而非重力或摩擦力","why":"圆环水平放置，重力竖直向下与运动平面垂直，无摩擦，径向只有环的弹力","do":"对结合体沿半径方向用牛顿第二定律，向心力等于环的弹力","expr":"F=(m_A+m_B)\\frac{v^2}{R}","cues":["向心力谁给","环的弹力","沿半径方向"],"concepts":["向心力","牛顿第二定律"]},{"title":"弹性碰撞速度公式","type":"关系建立","judge":"判断弹性碰撞需同时列动量守恒与动能守恒，并解出碰后A、B各自速度","why":"弹性碰撞动能不损失，两球质量不同，碰后速度不能共用，必须分别求出","do":"联立动量守恒与动能守恒，消元解出v_A、v_B关于v_0的表达式","expr":"v_A=\\frac{m_A-m_B}{m_A+m_B}v_0,\\quad v_B=\\frac{2m_A}{m_A+m_B}v_0","cues":["动能也守恒","两球速度分开","解出速度比"],"concepts":["弹性碰撞","动量守恒","动能守恒"]},{"title":"等边三角形顶点路程比","type":"几何关系","judge":"判断两次碰撞间A、B沿圆环走过的弧长之比如何由碰撞点落在等边三角形顶点这一条件确定","why":"碰撞点只能落在三个等分点上，两球从同一碰点出发再次相遇，路程差必为整数圈，路程和受顶点位置约束","do":"按第二次碰撞落在相邻顶点或隔一个顶点两种情形，写出含整数圈数k的路程比通式","expr":"\\frac{x_A}{x_B}=\\frac{1+3k_1}{4+3k_1}\\ \\text{或}\\ \\frac{2+3k_2}{5+3k_2}","cues":["差整数圈","分两种顶点","带个整数k"],"concepts":["圆周运动","弧长与圈数"]},{"title":"质量比取正筛选","type":"数学处理","judge":"判断由路程比等于速度比解出的质量比表达式中，整数k只能取使两质量均为正的那个值","why":"质量必须为正，含k的分式在k增大时会变号或使分母为零，只有有限个k物理上可行","do":"把路程比与速度比联立解出m_A/m_B关于k的表达式，逐一检验正性，舍去非正解","expr":"\\frac{m_A}{m_B}=\\frac{4+3k_1}{2-3k_1}\\ \\text{或}\\ \\frac{5+3k_2}{1-3k_2}","cues":["质量得为正","k只能取零","舍掉负的"],"concepts":["物理约束筛选","参数取值"]},{"title":"相对速度与追及圈数","type":"临界条件","judge":"判断相邻两次碰撞之间B相对A多跑整整一圈，且相对速度按e逐次衰减","why":"两球同向绕环，后一次相碰要求快的球相对慢的球恰好多走一圈；每次碰撞后相对速度乘e","do":"用相对速度写相邻碰撞时间间隔t=2πR/v相，再乘B的速度得每段路程，按等比数列求和到第2n段","expr":"t_i=\\frac{2\\pi R}{e^i v_0},\\quad s=\\sum_{i=1}^{2n}v_{Bi}t_i","cues":["相对多跑一圈","相对速度乘e","等比数列求和"],"concepts":["相对运动","等比数列","恢复系数"]}],"761":[{"title":"识别核反应方程","type":"模型选择","judge":"判断该方程属于哪种核反应类型，从而确定守恒定律的适用范围","why":"核反应方程遵循质量数守恒和电荷数守恒，与化学反应中原子个数守恒不同，不能按化学配平思路处理","do":"确认方程左右两侧是原子核（含质量数上标和电荷数下标），按核反应处理","expr":"","cues":["核反应方程","看上下标","不是化学反应"],"concepts":["核反应","质量数","电荷数"]},{"title":"用守恒定律求X","type":"关系建立","judge":"判断X的质量数和电荷数应分别等于反应前后对应量的差值","why":"反应前后质量数总和与电荷数总和分别守恒，X的粒子数由方程中X的系数4决定","do":"分别对质量数和电荷数列出守恒式，先求单个X的质量数与电荷数","expr":"106+58=160+4A_X,\\quad 48+28=76+4Z_X","cues":["列守恒式","先算总数","除以四"],"concepts":["质量数守恒","电荷数守恒"]},{"title":"由A、Z定粒子","type":"结论整理","judge":"判断质量数为1、电荷数为0的粒子对应哪种微观粒子","why":"电荷数为0说明不带电，质量数为1说明质量与质子相近，符合中子的特征","do":"将求得的A、Z与常见粒子（质子、中子、电子、α粒子）的符号对应","expr":"A_X=1,\\ Z_X=0\\Rightarrow{}^{1}_{0}\\mathrm{n}","cues":["不带电","质量数是1","是中子"],"concepts":["中子","粒子符号"]}],"762":[{"title":"识别面积即位移","type":"模型选择","judge":"要判断 v-t 图像中哪块几何量与两站距离对应","why":"v-t 图线下的面积等于位移，这是由 v=dx/dt 积分得来的，不是图线的斜率或某点纵坐标","do":"把图线与横轴围成的区域圈出来，确认求的是这块面积而不是斜率","expr":"x=\\int v\\,dt","cues":["看面积","图线下方","不是看斜率"],"concepts":["v-t 图像","位移","面积"]},{"title":"确定时间轴区间","type":"图像读取","judge":"要判断横轴上哪一段对应两站之间的运动过程","why":"图像只画了部分时间段，两站间位移只对应从进站前到出站后的那一段，取错区间面积就错","do":"读出图线起点、终点及与横轴交点对应的时刻，确定积分上下限","expr":"t_1=25\\,\\mathrm{s},\\ t_2=94\\,\\mathrm{s}","cues":["从二十五秒开始","到九十四秒结束","中间那段"],"concepts":["时间轴","运动过程"]},{"title":"分块求面积","type":"几何关系","judge":"要判断这块面积由哪几个简单图形拼成、各自如何算","why":"图线是折线，面积可拆成三角形与矩形（或梯形）之和，拆法不同但总面积唯一","do":"把区域分成加速段三角形、匀速段矩形、减速段三角形，分别算面积再相加","expr":"x=\\tfrac12(74-25)\\times20+20\\times(94-74)+\\tfrac12(94-74)\\times20","cues":["拆成三块","三角形加矩形","梯形也行"],"concepts":["三角形面积","矩形面积","分段求和"]},{"title":"峰值速度与单位","type":"图像读取","judge":"要判断纵轴最大速度的读数及单位换算","why":"纵轴单位是 m/s，峰值约 20 m/s，若误读成 km/h 或读错刻度，面积会差几个量级","do":"读出图线最高点对应的速度值，确认纵轴单位后代入面积计算","expr":"v_{\\max}\\approx20\\,\\mathrm{m/s}","cues":["最高点二十","纵轴是米每秒","别当成千米每时"],"concepts":["速度读数","单位换算"]}],"763":[{"title":"判断实验舱内是否失重","type":"前提判断","judge":"要判断天宫实验室内物体是否处于完全失重、视重是否为零","why":"舱内一切物体随舱绕地球做圆周运动，重力全部提供向心力，因此一切靠重力产生效果（测力计称重、单摆计时、天平称质量）的实验都失效","do":"分析舱内物体的受力与运动状态，确认重力只充当向心力、物体间无支持力","expr":"","cues":["完全失重","重力全当向心力","视重为零"],"concepts":["完全失重","向心力"]},{"title":"排除依赖重力的测量","type":"模型选择","judge":"要判断哪些测量方案依赖'重力产生视重或回复力'这一前提","why":"弹簧测力计、天平、单摆测 g 都以物体受重力产生视重或回复力为基础，失重环境下这些效应消失，测不出轨道处的 g","do":"逐一检查各方案是否用到视重、杠杆平衡或单摆周期，凡依赖者一律排除","expr":"","cues":["测力计称重不行","天平不行","单摆不行"],"concepts":["视重","单摆周期","杠杆平衡"]},{"title":"用圆周运动反求重力加速度","type":"关系建立","judge":"要判断能否把'轨道处的重力加速度'转化为舱做圆周运动的向心加速度","why":"轨道处重力全部提供向心力，故 g 等于舱的向心加速度，可由圆周运动的周期与半径求出","do":"对天宫实验室绕地球的匀速圆周运动列牛顿第二定律，把 g 写成周期和轨道半径的函数","expr":"mg=G\\frac{Mm}{r^{2}}=m\\frac{4\\pi^{2}}{T^{2}}r","cues":["重力等于向心力","用周期和半径","绕地球圆周运动"],"concepts":["万有引力定律","向心加速度"]},{"title":"确定可测的轨道参量","type":"结论整理","judge":"要判断舱上能直接测到的是周期和轨道半径，而不是地球质量或引力常量","why":"舱内可测自身绕地运行的周期，轨道半径可由运行周期与已知地球参数间接确定，而 M、G 无法在舱内测得","do":"比较各方案所需物理量能否在舱内测得，选出测周期与轨道半径的方案","expr":"g=\\frac{4\\pi^{2}}{T^{2}}r","cues":["测周期和半径","地球质量测不了","引力常量测不了"],"concepts":["轨道半径","运行周期"]}],"764":[{"title":"切割有效长度取d","type":"模型选择","judge":"导体棒切割磁感线的有效长度应取导轨间距 d 还是棒长 L","why":"感应电动势只由棒在导轨间实际接入回路的那段切割磁感线产生，伸出导轨的部分不构成回路、不贡献电动势","do":"比较棒长 L 与导轨间距 d，确认回路中参与切割的线段长度为 d","expr":"E=Bdv","cues":["用棒长算","有效长度是间距","伸出部分不算"],"concepts":["动生电动势","有效切割长度"]},{"title":"电动势与电流关系","type":"关系建立","judge":"回路总电阻是否只有 R，从而用 E/R 求电流","why":"导轨与棒光滑且题设只给出电阻 R，其余部分电阻不计，故闭合回路欧姆定律直接适用","do":"对由棒、导轨、电阻构成的闭合回路列欧姆定律","expr":"I=\\frac{Bdv}{R}","cues":["只有电阻R","回路欧姆定律","导轨没电阻"],"concepts":["闭合电路欧姆定律","感应电流"]},{"title":"电流方向判定","type":"前提判断","judge":"用右手定则判断棒中感应电流由 b 流向 a 还是由 a 流向 b","why":"安培力方向由电流方向与磁场方向共同决定，电流方向判错则安培力方向必错","do":"对向右运动的棒用右手定则，四指指向感应电流方向，确定电流沿 b→a","expr":"","cues":["右手定则","电流从b到a","先定电流方向"],"concepts":["右手定则","感应电流方向"]},{"title":"安培力用d不用L","type":"模型选择","judge":"计算安培力时受力长度取 d 还是 L","why":"安培力只作用于处在磁场中且载流的那段导体，即导轨间的有效长度 d，伸出部分虽在磁场中但不载流","do":"将电流 I 与有效长度 d、磁感应强度 B 代入安培力公式","expr":"F=BId=\\frac{B^{2}d^{2}v}{R}","cues":["受力长度用间距","不是整根棒","载流部分才受力"],"concepts":["安培力","有效长度"]},{"title":"安培力方向判断","type":"前提判断","judge":"用左手定则判断安培力指向左还是右","why":"磁场垂直纸面向里、电流由 b 到 a，由左手定则确定安培力方向，且该方向必与棒运动方向相反（阻碍相对运动）","do":"对电流 b→a、磁场向里用左手定则，并用楞次定律的阻碍作用交叉验证","expr":"","cues":["左手定则","阻碍运动","方向向左"],"concepts":["左手定则","楞次定律"]}],"765":[{"title":"从图像读周期","type":"图像读取","judge":"横轴相邻两个同相点（如两个波峰或两个过零点同向）之间的间隔对应一个完整周期，需判断读哪一段","why":"单摆周期公式中的 T 必须由图像完整一个循环读出，读半周期或相邻峰间距读错会使摆长算错","do":"在 x-t 图上找相邻两个波峰（或相邻同向过零点），读出其横坐标之差作为周期","expr":"T=0.8\\pi\\ \\mathrm{s}","cues":["看两个波峰间距","一个完整来回","别读半个周期"],"concepts":["振动图像","周期"]},{"title":"用周期公式反求摆长","type":"关系建立","judge":"判断用单摆周期公式把 T 与摆长 l 联系起来，而不是用图像振幅或速度求 l","why":"单摆周期只由摆长和重力加速度决定，T=2π√(l/g) 是唯一把图像读出的 T 与待求摆长挂钩的规律","do":"将读出的 T 和 g=10 代入周期公式，解出 l","expr":"T=2\\pi\\sqrt{\\frac{l}{g}}\\Rightarrow l=\\frac{gT^{2}}{4\\pi^{2}}","cues":["用周期公式","摆长只跟周期有关","代g等于10"],"concepts":["单摆周期公式","摆长"]},{"title":"斜率即速度的判断","type":"模型选择","judge":"判断 x-t 图像的斜率表示速度，从而由斜率正负、大小判断各时刻速度","why":"位移—时间图像的切线斜率就是速度，起始时刻斜率为零说明速度为零，这是判断速度有无及方向的依据","do":"观察 t=0 处切线是否水平，并比较 A、B、C 各点切线斜率的正负与大小","expr":"v=\\frac{\\mathrm{d}x}{\\mathrm{d}t}","cues":["斜率就是速度","起点切线是平的","看斜率正负"],"concepts":["位移时间图像","速度"]},{"title":"区分速度相同与大小相同","type":"结论整理","judge":"判断哪些点速度矢量完全相同（同大小同方向），哪些只是速率相同而方向相反","why":"速度是矢量，斜率的绝对值相同只说明速率相同，方向由斜率正负决定，混淆二者会选错项","do":"比较 A、C 两点斜率是否同号同值，比较 A、B 两点斜率是否等值反号","expr":"","cues":["速度是矢量","大小同方向不一定同","看斜率符号"],"concepts":["矢量","速率与速度"]}],"766":[{"title":"交变磁场来源","type":"前提判断","judge":"线圈中通交变电流时，金属内磁通量是否随时间变化","why":"感应电炉的加热原理是电磁感应，只有穿过金属的磁通量变化才可能在金属中激发感应电流","do":"由交变电流产生的磁场方向与大小周期性变化，判断穿过炉内金属的磁通量是否变化","expr":"","cues":["电流在变","磁场在变","磁通量变化"],"concepts":["交变电流","磁通量","电磁感应"]},{"title":"涡流而非恒定电流","type":"模型选择","judge":"金属中产生的是交变感应电流（涡流）还是恒定电流","why":"磁通量周期性变化，由法拉第电磁感应定律，感应电动势方向也周期性变化，故金属内形成涡流","do":"把金属块看作整块导体，判断其中感应电流的方向和大小随时间周期性变化","expr":"\\mathcal{E}=-\\frac{\\Delta\\Phi}{\\Delta t}","cues":["是涡流","方向会变","整块金属导电"],"concepts":["涡流","法拉第电磁感应定律"]},{"title":"匝数与电动势关系","type":"关系建立","judge":"线圈匝数增加时金属中感应电动势、感应电流如何变化","why":"法拉第电磁感应定律给出电动势与匝数成正比，匝数越多感应电动势越大，金属中涡流越强","do":"写出电动势与匝数的正比关系，再结合金属电阻不变比较感应电流大小","expr":"\\mathcal{E}=n\\frac{\\Delta\\Phi}{\\Delta t},\\quad I=\\frac{\\mathcal{E}}{R}","cues":["匝数越多电动势越大","电流跟着变大","电阻不变"],"concepts":["感应电动势","匝数","涡流"]}],"767":[{"title":"充放电电流的变化趋势","type":"关系建立","judge":"充放电过程中电流随电荷量变化是增大还是减小","why":"电容器电压 U=Q/C，回路电流由电源电压与电容器电压之差（充电）或电容器自身电压（放电）驱动，Q 变化时驱动电压随之变化","do":"写出充电时 i=(E-U)/R、放电时 i=U/R，结合 U=Q/C 判断 i 随 Q 增大（充电）或减小（放电）而如何变化","expr":"i=\\frac{E-U}{R}=\\frac{E-Q/C}{R}","cues":["电压差变小","电流越来越小","电荷越多电压越高"],"concepts":["电容定义式","欧姆定律","闭合电路"]},{"title":"极板带电正负的判断","type":"前提判断","judge":"充电后电容器上极板带正电还是负电","why":"开关接 1 时上极板与电源正极相连，电源正极把正电荷推向所连极板","do":"沿导线从上极板追到电源正极，确定上极板带正电、下极板带负电","expr":"","cues":["上极板接正极","上板带正电","看电源符号长短"],"concepts":["电源极性","电容器带电"]},{"title":"电阻中电流方向的判断","type":"模型选择","judge":"充电和放电时流过电阻 R 的电流分别由哪端流向哪端","why":"充电时正电荷经电阻流向电容器上极板，放电时正电荷从上极板经电阻流出，两个过程电流方向相反","do":"分别画出充电、放电两条回路，标出正电荷在电阻中的流动方向，对应到 M、N 两点","expr":"","cues":["充电流向电容","放电流出电容","两个方向相反"],"concepts":["电流方向","电容器充放电"]}],"768":[{"title":"速度方向时刻改变","type":"前提判断","judge":"匀速圆周运动中速度的大小不变但方向是否改变","why":"速度是矢量，方向沿轨迹切线，圆周运动切线方向逐点不同，故速度在变","do":"把速度看成矢量，比较不同位置的切线方向","expr":"","cues":["速度大小不变","方向一直在变","速率不变"],"concepts":["线速度","矢量性"]},{"title":"动能与动量区分","type":"关系建立","judge":"动能和动量分别由速度的哪个方面决定","why":"动能是标量只依赖速率，动量是矢量依赖速度方向，二者对速度变化的敏感程度不同","do":"由速率不变判断动能不变，由速度方向改变判断动量改变","expr":"$E_k=\\frac12mv^2,\\quad \\vec p=m\\vec v$","cues":["动能是标量","动量有方向","看速率还是看速度"],"concepts":["动能","动量","标量与矢量"]},{"title":"加速度指向圆心","type":"模型选择","judge":"匀速圆周运动的加速度方向如何确定","why":"匀速圆周运动合外力提供向心力，方向始终指向圆心，加速度方向随之改变","do":"画出向心力方向，判断加速度大小不变而方向时刻改变","expr":"$a=\\frac{v^2}{r}$","cues":["向心加速度","指向圆心","方向在转"],"concepts":["向心加速度","向心力"]},{"title":"合外力指向圆心","type":"结论整理","judge":"匀速圆周运动合外力是否一定指向圆心","why":"速率不变说明切向无合力，合外力全部充当向心力，必指向圆心","do":"由速率不变推出切向合力为零，再判断合外力方向","expr":"$\\vec F_{\\text{合}}=m\\vec a$","cues":["合外力提供向心力","切向没有力","指向圆心"],"concepts":["合外力","向心力"]}],"769":[{"title":"由轨迹凹侧定受力方向","type":"模型选择","judge":"粒子所受电场力指向轨迹的哪一侧，从而确定力的方向","why":"做曲线运动的物体所受合外力必指向轨迹凹侧，这是判断电场力方向的唯一依据","do":"在轨迹上取一点，画出切线，找出轨迹弯曲的内侧，即电场力方向","expr":"","cues":["看凹侧","力指向内侧","沿切线不可能"],"concepts":["曲线运动条件","电场力方向"]},{"title":"由受力方向定电性","type":"前提判断","judge":"电场力方向与等势面处电场方向同向还是反向，从而确定粒子带何种电荷","why":"正电荷受力沿电场方向，负电荷受力逆电场方向；电场方向由高电势指向低电势","do":"比较力方向与电场线（由高等势面指向低等势面）方向是否一致","expr":"","cues":["同向带正电","反向带负电","看电势高低"],"concepts":["电场线方向","电荷正负"]},{"title":"等势面疏密定场强","type":"关系建立","judge":"M、N 两点所在处等势面的疏密程度，比较两点场强大小","why":"等差等势面越密集处电场线越密，场强越大","do":"比较 M 点与 N 点附近相邻等势面的间距","expr":"","cues":["密处场强大","疏处场强小","看间距"],"concepts":["等势面疏密","电场强度"]},{"title":"沿电场线方向比电势","type":"关系建立","judge":"M、N 两点电势的高低关系","why":"沿电场线方向电势逐渐降低，等势面数值直接反映电势高低","do":"读出 M、N 所在等势面的电势值并比较","expr":"","cues":["顺着电场线降低","看等势面标值","高电势在左"],"concepts":["电势","等势面"]},{"title":"电势能随电势变化","type":"关系建立","judge":"粒子在 M、N 两点电势能的大小关系","why":"电势能由电荷量与电势共同决定，正电荷在高电势处电势能大","do":"用电荷正负结合两点电势高低判断电势能大小","expr":"E_p=q\\varphi","cues":["正电荷高电势能大","带符号算","先定电性"],"concepts":["电势能","电势"]},{"title":"能量守恒定动能极值","type":"临界条件","judge":"轨迹上动能最小的位置对应电势能最大处","why":"粒子仅受电场力，动能与电势能之和守恒，电势能最大时动能最小","do":"在轨迹上找电势最高的点，即为动能最小处","expr":"E_k+E_p=\\text{常量}","cues":["能量守恒","电势能最大动能最小","找最高电势点"],"concepts":["能量守恒","动能与电势能转化"]}],"770":[{"title":"反射光与折射光垂直的几何关系","type":"几何关系","judge":"由反射光 b 与折射光 c 垂直，判断材料内折射角与入射角 θ 的关系","why":"反射光与界面法线夹角等于 θ，折射光与法线夹角为 r，两线垂直即 θ+r=90°，这是求折射率的前提","do":"画出法线，标出反射角 θ 与折射角 r，利用两线垂直列角度关系","expr":"\\theta + r = 90^{\\circ}","cues":["两线垂直","反射角等于入射角","折射角是余角"],"concepts":["反射定律","折射角","几何关系"]},{"title":"由空气射入介质定折射率","type":"关系建立","judge":"判断哪一侧是空气、哪一侧是介质，从而确定折射率公式中角度的对应","why":"光从空气沿半径方向射入半圆柱材料，入射角在空气中为 θ，折射角在材料中为 r，折射率应为空气角正弦比材料角正弦","do":"把 θ=30°、r=60° 代入折射定律求 n","expr":"n=\\frac{\\sin\\theta}{\\sin r}=\\frac{\\sin30^{\\circ}}{\\sin60^{\\circ}}","cues":["从空气进材料","入射角在空气里","别把角度弄反"],"concepts":["折射定律","折射率"]},{"title":"全反射临界角比较","type":"临界条件","judge":"判断 θ 增大到 45° 时折射光是否消失，需比较临界角 C 与 45° 的大小","why":"全反射条件是光从光密介质射向光疏介质且入射角不小于临界角，临界角由 sinC=1/n 决定","do":"由 n 求 sinC，与 sin45° 比较，判断 45° 是否达到临界角","expr":"\\sin C=\\frac{1}{n}","cues":["算临界角","和四十五度比","会不会全反射"],"concepts":["全反射","临界角"]},{"title":"反射光颜色与折射率色散","type":"前提判断","judge":"判断白光入射时反射光 b 的成分，以及换成紫光后折射角如何变化","why":"反射不改变光的频率成分，故反射光仍为白光；同种介质对紫光折射率大于红光，折射角随折射率增大而增大","do":"由反射定律说明 b 为白光；由 n紫>n红 判断紫光折射角变大，θ+r 不再等于 90°","expr":"n_{\\text{紫}}>n_{\\text{红}}","cues":["反射不改变颜色","紫光折射率大","折射角会变大"],"concepts":["光的色散","反射定律","折射率"]}],"771":[{"title":"小车质量与槽码质量关系","type":"前提判断","judge":"要判断本实验中应让小车质量远大于还是远小于槽码质量","why":"细线拉力近似等于槽码重力这一近似成立的条件是小车质量远大于槽码质量，否则需用整体法联立求解，拉力不再等于槽码重力","do":"比较小车质量与槽码质量的大小关系，确定近似成立的方向","expr":"m\\ll M","cues":["小车要远大于槽码","拉力才近似等于重力","反了就错"],"concepts":["近似条件","牛顿第二定律","细线拉力"]},{"title":"补偿阻力的操作要点","type":"实验操作","judge":"要判断补偿阻力时垫块怎么调、哪些器材必须保留、细线方向如何","why":"只有重力沿板方向的分力恰好抵消摩擦力，细线拉力才等于小车所受合力；纸带上的点迹是否均匀是判断匀速的唯一依据","do":"调垫块使小车不挂槽码时拖动纸带打出均匀点迹，保留打点计时器和纸带，细线与板平行","expr":"","cues":["垫块垫高","纸带不能撤","点迹要均匀","先接通电源"],"concepts":["平衡摩擦力","匀速运动","打点计时器"]},{"title":"逐差法公式的选取","type":"数据处理","judge":"要判断哪种加速度算式对偶然误差的抑制最好","why":"逐差法把全部数据都用上且相邻项相减消去初速度，跨的间隔越大、参与平均的项越多，误差越小","do":"比较各选项中每组数据跨越的间隔数与平均的组数，选跨度最大且数据全用的那一个","expr":"S_{i+4}-S_i=4aT^{2}","cues":["逐差法","跨四段","数据全用上","误差最小"],"concepts":["逐差法","匀变速直线运动","偶然误差"]},{"title":"图像斜率的物理含义","type":"关系建立","judge":"要判断1/a–M图线的斜率由哪个物理量决定、斜率大小与槽码质量的关系","why":"由mg=(m+M)a得1/a=M/(mg)+1/g，斜率1/(mg)只由槽码质量决定，与小车和砝码的总质量无关","do":"写出1/a关于M的表达式，指出斜率为1/(mg)，再比较甲、乙两图斜率大小","expr":"\\frac{1}{a}=\\frac{1}{mg}M+\\frac{1}{g}","cues":["化曲为直","斜率是1/mg","斜率小则槽码大"],"concepts":["牛顿第二定律","图像斜率","反比关系"]},{"title":"由图像判断反比关系","type":"图像读取","judge":"要判断1/a与M成正比能否说明a与M成反比","why":"1/a与M成正比即1/a=kM，变形得a=1/(kM)，说明外力一定时a与M成反比","do":"观察图线是否为过原点的直线，再对关系式作倒数变形","expr":"\\frac{1}{a}\\propto M\\Rightarrow a\\propto\\frac{1}{M}","cues":["过原点的直线","取倒数就是反比","横坐标是总质量"],"concepts":["反比关系","线性化","图像分析"]}],"772":[{"title":"电流表内阻的测量原理","type":"模型选择","judge":"图1中电流表与电压表并联，能否直接用电压表示数除以电流表示数求电流表内阻","why":"电压表与电流表并联，两者电压相同，电压表读数即电流表两端电压；电流表读数即通过电流表自身的电流，故欧姆定律直接适用","do":"读出图2中电压表与电流表的示数，用电压除以电流求电流表内阻","expr":"R_A=\\frac{U}{I}","cues":["并联电压相同","电压除以电流","直接读表"],"concepts":["欧姆定律","并联电路","电表读数"]},{"title":"把电流表内阻计入回路","type":"关系建立","judge":"写闭合电路方程时，电流表内阻是否与电池内阻一起计入内阻项","why":"图3中电流表与电池串联，电流通过电流表时同样产生压降，闭合电路欧姆定律中内阻项应为 r+R_A","do":"沿回路列电动势等于各段电压之和的方程，把电流表内阻并入内阻项","expr":"E=U+I(r+R_A)","cues":["电流表串在干路","内阻要加上","别漏电流表"],"concepts":["闭合电路欧姆定律","串联电路"]},{"title":"图像截距斜率对应什么","type":"图像读取","judge":"U-I 图像的纵截距和斜率绝对值分别对应电动势和内阻之和，还是仅对应内阻","why":"由 E=U+I(r+R_A) 变形得 U=E-(r+R_A)I，截距为 E，斜率绝对值为 r+R_A，需再减去已测的 R_A 才得 r","do":"读纵截距得电动势，取图线上两点求斜率绝对值，再减去电流表内阻得电池内阻","expr":"U=E-(r+R_A)I,\\quad |k|=r+R_A","cues":["截距是电动势","斜率是总内阻","还要减电流表"],"concepts":["U-I 图像","斜率与截距","等效内阻"]},{"title":"电压表串联时电流过小","type":"临界条件","judge":"图5把电压表串入电路后，电路电流是否小到电流表无法读数","why":"电压表内阻约千欧量级，与电池内阻、滑动变阻器相比极大，回路总电阻很大，电流远小于电流表量程下限，指针几乎不动","do":"估算电压表串入后的回路电流量级，与电流表可读的最小电流比较","expr":"I=\\frac{E}{R_V+r+R_{\\text{滑}}}\\ll 0.02\\,\\mathrm{A}","cues":["电压表内阻很大","电流太小","指针不动"],"concepts":["电压表内阻","串联电路","电表量程"]}],"773":[{"title":"抽气后A体积的确定","type":"几何关系","judge":"抽气后隔板右移，A的体积是增大还是减小，增大多少","why":"容器总长固定为2l、横截面积S，A与B体积之和恒为2Sl，B变为原来的3/4即(3/4)Sl，A只能占剩余部分","do":"用总体积2Sl减去抽气后B的体积(3/4)Sl，得到A的新体积","expr":"V_A=2Sl-\\frac{3}{4}Sl=\\frac{5}{4}Sl","cues":["总体积不变","B占四分之三","A是剩下的"],"concepts":["体积守恒","几何约束"]},{"title":"抽气后B的等效初态","type":"前提判断","judge":"抽出一半气体后，若体积不变，B的压强变为多少","why":"温度不变时一定量理想气体的pV乘积与物质的量成正比，气体减半则同体积下压强减半，这是对剩余气体用玻意耳定律前的等效初态","do":"先求剩余气体在原体积V下的压强p0/2，再以此作为初态与末态(3/4)V比较","expr":"p'=\\frac{1}{2}p_0,\\quad \\frac{1}{2}p_0 V=p_B\\cdot\\frac{3}{4}V","cues":["抽走一半气体","同体积压强减半","先折合成一半"],"concepts":["理想气体状态方程","玻意耳定律","物质的量"]},{"title":"A、B各自独立用玻意耳定律","type":"模型选择","judge":"A、B两部分气体是否各自满足等温过程，能否分别对它们列玻意耳定律","why":"题目说明整个过程温度不变，A、B被隔板隔开互不交换气体，各自是固定质量理想气体的等温过程","do":"对A用p0V=pA(5/4)V，对B用(p0/2)V=pB(3/4)V，分别解出压强","expr":"p_0V=p_A\\frac{5}{4}V,\\quad \\frac{1}{2}p_0V=p_B\\frac{3}{4}V","cues":["温度不变","两部分分开算","各自质量不变"],"concepts":["玻意耳定律","等温过程","隔离法"]},{"title":"隔板平衡的受力分析","type":"关系建立","judge":"隔板静止时，A、B气体压力和弹簧弹力三者的方向与平衡关系如何","why":"隔板内壁光滑、处于平衡态，水平方向合力为零；A在左、B在右，弹簧被压缩后对隔板产生向左的推力","do":"对隔板列水平方向力平衡方程，把两侧气体压力与弹簧弹力联系起来","expr":"p_AS=p_BS+F","cues":["隔板受力平衡","两边压强不等","弹簧顶着隔板"],"concepts":["受力平衡","压强与压力","胡克定律"]},{"title":"弹簧压缩量的确定","type":"几何关系","judge":"弹簧被压缩了多少，与隔板移动距离是什么关系","why":"弹簧原长时对应初始平衡位置，隔板移动的距离就是弹簧的形变量，由A、B体积变化量可读出","do":"用A体积的增量(1/4)Sl除以S，得到隔板位移即弹簧压缩量","expr":"\\Delta x=\\frac{V_A-V}{S}=\\frac{l}{4}","cues":["隔板移了多少","弹簧压缩量","体积变化除以面积"],"concepts":["形变量","几何关系"]},{"title":"联立求劲度系数","type":"数学处理","judge":"把压强结果与力平衡、胡克定律联立，消去弹力F求k","why":"力平衡方程中F未知，需用胡克定律F=kΔx替换，再代入已求得的pA、pB","do":"将pA、pB和Δx代入pAS=pBS+kΔx，解出k","expr":"k=\\frac{(p_A-p_B)S}{l/4}","cues":["代入压强","消去弹力","解出劲度系数"],"concepts":["胡克定律","力平衡","联立方程"]}],"774":[{"title":"剪断后A的摆模型","type":"模型选择","judge":"剪断 O'P 后，A 是绕悬点 O 做圆周运动，还是做别的运动","why":"OP 绳不可伸长且始终绷直，A 只能沿以 O 为圆心、OP 为半径的圆弧运动，最低点速度由机械能守恒给出","do":"确认圆心为 O、半径为 OP，取最低点为势能零点列机械能守恒","expr":"mgl(1-\\cos\\theta)=\\tfrac12 mv_0^2","cues":["绕O点摆动","绳长就是半径","从静止放开"],"concepts":["圆周运动","机械能守恒"]},{"title":"最低点绳拉力的方程","type":"关系建立","judge":"最低点沿绳方向的合力指向圆心，拉力与重力的合力提供向心力","why":"最低点速度水平、加速度竖直向上，牛顿第二定律沿半径方向成立","do":"在最低点沿竖直方向列向心力方程，代入刚求出的速度","expr":"F-mg=\\frac{mv_0^2}{l}","cues":["指向圆心","拉力减重力","向心力"],"concepts":["向心力","牛顿第二定律"]},{"title":"碰撞瞬间水平动量守恒","type":"前提判断","judge":"A 与 C 碰撞时间极短，水平方向是否可视为动量守恒","why":"碰撞时间极短，水平方向外力（摩擦等）冲量可忽略，A、C 系统水平动量守恒","do":"对 A、C 系统沿水平方向列碰撞前后动量守恒式","expr":"mv_0=mv_A'+mv_C'","cues":["时间极短","水平方向不受外力","取A和C"],"concepts":["动量守恒","碰撞"]},{"title":"碰后A竖直下落的含义","type":"临界条件","judge":"碰后 A 竖直下落说明碰后 A 的水平速度为零","why":"A 只受重力时竖直下落要求其水平分速度为零，据此确定碰后 A 的水平速度","do":"令碰后 A 的水平速度为零，代入动量守恒式解出 C 的速度","expr":"mv_0=0+mv_C'","cues":["竖直下落","水平速度为零","只剩C在动"],"concepts":["速度分解","动量守恒"]},{"title":"C在B上滑动的对象选择","type":"模型选择","judge":"求摩擦因数时，取 C 与 B 组成的系统还是单独分析 C","why":"B 在光滑水平面上，C、B 系统水平方向不受外力，动量守恒；相对滑动生热用能量守恒最省未知数","do":"对 C、B 系统列水平动量守恒，再列初末动能差等于摩擦生热","expr":"mv_C'=(M+m)v,\\ \\mu mgL_{\\text{相对}}=\\tfrac12 mv_C'^2-\\tfrac12(M+m)v^2","cues":["取C和B整体","水平不受外力","摩擦生热等于动能损失"],"concepts":["动量守恒","能量守恒","相对位移"]}],"775":[{"title":"判断粒子电性","type":"前提判断","judge":"由粒子在分离器中向上偏转的轨迹方向，判断洛伦兹力方向，进而确定电荷正负","why":"洛伦兹力方向由左手定则与电荷正负共同决定，电性未知时无法确定受力方向，后续比荷正负号与配速方向都依赖它","do":"在偏转分离器Ⅲ中看轨迹向上弯曲，磁场垂直纸面向里，用左手定则反推电荷正负","expr":"","cues":["看偏转方向","左手定则","磁场向里"],"concepts":["左手定则","洛伦兹力方向"]},{"title":"速度选择器平衡条件","type":"关系建立","judge":"判断粒子在速度选择器中做直线运动时电场力与洛伦兹力等大反向，从而定出通过速度","why":"只有两力平衡粒子才做匀速直线运动，这是速度选择器筛选速度的原理，也是求比荷的桥梁","do":"对速度选择器中的粒子列电场力与洛伦兹力平衡方程，解出进入速度","expr":"qv_0B_1=qE_1","cues":["两力平衡","匀速直线","速度选择"],"concepts":["速度选择器","电场力","洛伦兹力"]},{"title":"加速电压与速度关联","type":"关系建立","judge":"判断粒子在加速器中初速为零、只受电场力做功，用动能定理把加速电压与进入速度联系起来","why":"比荷是未知量，速度选择器只给出速度，必须再用加速过程给出第二个含 q/m 的方程才能联立求解","do":"对加速过程列动能定理，与速度选择器的速度式联立消去速度，解出比荷","expr":"qU=\\frac12 mv_0^2","cues":["初速为零","动能定理","联立消速度"],"concepts":["动能定理","加速电场","比荷"]},{"title":"分离器半径与距离","type":"几何关系","judge":"判断粒子在分离器中做匀速圆周运动、洛伦兹力提供向心力，且 O 到 P 的距离等于轨迹直径","why":"题目求的是弦长而非半径，若把半径当作 OP 会差一个因子 2","do":"由向心力公式求半径，再取 OP 等于两倍半径，代入已求比荷与速度","expr":"qv_0B_2=m\\frac{v_0^2}{r},\\quad OP=2r","cues":["直径不是半径","向心力","圆周运动"],"concepts":["洛伦兹力提供向心力","轨迹半径"]},{"title":"电场变大后的配速分解","type":"模型选择","judge":"判断 E₂ 略大于 E₁ 后电场力大于原洛伦兹力，粒子不再做直线运动，需把速度分解为匀速平动加匀速圆周运动的叠加","why":"电场力与洛伦兹力不再平衡，直接列牛顿方程难以求解；配速法把合运动拆成水平匀速与圆周运动，才能利用垂直打板的临界条件","do":"设附加速度 v₁ 使 qE₂=q(v₀+v₁)B₁，把运动看成水平匀速 v₀+v₁ 与半径对应 v₁ 的圆周运动的叠加","expr":"qE_2=q(v_0+v_1)B_1","cues":["配速法","速度分解","叠加"],"concepts":["配速法","运动的合成与分解"]},{"title":"垂直打板的临界条件","type":"临界条件","judge":"判断粒子恰好垂直打在右挡板上时，其合速度方向必须水平向右，即圆周分速度转到水平方向","why":"垂直打板意味着速度垂直于板面，只有圆周分速度与平动速度同向时合速度才水平，这是确定打板时刻速度的临界条件","do":"令圆周分速度转到水平向右，将平动速度与圆周速度同向相加得打板速度","expr":"v'=v_0+v_1+v_1=\\frac{2E_2-E_1}{B_1}","cues":["垂直打板","速度同向","转到水平"],"concepts":["临界条件","速度合成"]}],"776":[{"title":"确定守恒定律","type":"前提判断","judge":"判断该核衰变方程应依据哪条守恒律来配平未知粒子","why":"核反应方程必须同时满足质量数守恒和电荷数守恒，这是确定未知粒子身份的唯一依据","do":"对衰变方程左右两边分别列出质量数总和与电荷数总和，建立两个守恒等式","expr":"A_{左}=A_{右},\\quad Z_{左}=Z_{右}","cues":["用质量数守恒","电荷数也要守恒","两边配平"],"concepts":["质量数守恒","电荷数守恒","核反应方程"]},{"title":"读出母核与子核数据","type":"图像读取","judge":"判断方程中已知核的质量数和电荷数各取多少","why":"守恒方程中的已知量必须从核符号左上角和左下角的数字直接读出，读错则未知量全错","do":"从 ${}^{63}_{28}\\mathrm{Ni}$ 读出质量数 63、电荷数 28，从 ${}^{63}_{29}\\mathrm{Cu}$ 读出质量数 63、电荷数 29","expr":"A_{\\mathrm{Ni}}=63,\\ Z_{\\mathrm{Ni}}=28;\\quad A_{\\mathrm{Cu}}=63,\\ Z_{\\mathrm{Cu}}=29","cues":["左上角是质量数","左下角是电荷数","镍是二十八"],"concepts":["核符号表示","质量数","电荷数"]},{"title":"处理中性粒子贡献","type":"前提判断","judge":"判断反中微子对质量数和电荷数的贡献是否为零","why":"题设说明该粒子质量可忽略且为中性，故它在守恒方程中不提供质量数和电荷数","do":"在守恒等式右侧把反中微子的质量数与电荷数均按 0 计入","expr":"A_{\\bar\\nu}=0,\\ Z_{\\bar\\nu}=0","cues":["中微子不带电","质量忽略不计","它对配平没贡献"],"concepts":["中性粒子","反中微子"]},{"title":"解出未知粒子电荷数","type":"关系建立","judge":"判断 X 的质量数和电荷数分别等于多少","why":"由两守恒式相减即可唯一确定 X 的 A 与 Z，电荷数为负说明带负电","do":"用左侧总和减去右侧已知核与中微子的贡献，分别得到 X 的质量数和电荷数","expr":"A_X=63-63-0=0,\\quad Z_X=28-29-0=-1","cues":["质量数相减得零","电荷数差一个","结果是负一"],"concepts":["质量数守恒","电荷数守恒"]},{"title":"由电荷数定粒子种类","type":"结论整理","judge":"判断质量数为 0、电荷数为 -1 的粒子对应哪种符号","why":"质量数为零且电荷数为负一的只能是电子，核衰变中放出的电子记为 β 粒子","do":"把 A=0、Z=-1 与电子符号对应，确认 X 为电子而非正电子或中子","expr":"^{0}_{-1}\\mathrm{e}","cues":["负电荷的电子","就是贝塔粒子","不是正电子"],"concepts":["β 衰变","电子","粒子符号"]}],"777":[{"title":"读图定振幅周期","type":"图像读取","judge":"从振动图像纵轴峰值和相邻同向过零点间距读出振幅与周期","why":"简谐运动图像中纵坐标最大值即振幅，两相邻同向过平衡位置的时间间隔为一个周期","do":"读纵轴峰值得振幅，读相邻两个同向过零点（或相邻两峰）横坐标之差得周期","expr":"A=1.0\\,\\mathrm{cm},\\quad T=0.4\\,\\mathrm{s}","cues":["看纵轴峰值","相邻峰间距","一个完整波形"],"concepts":["振幅","周期","简谐运动图像"]},{"title":"频率由周期换算","type":"关系建立","judge":"判断频率与周期是倒数关系而非正比或等于周期","why":"频率定义为单位时间内完成的全振动次数，与周期互为倒数","do":"用周期倒数求频率并与选项给出的数值比较","expr":"f=\\frac{1}{T}=2.5\\,\\mathrm{Hz}","cues":["周期取倒数","频率和周期反比"],"concepts":["频率","周期"]},{"title":"平衡位置速度最大","type":"前提判断","judge":"判断图像中位移为零的时刻对应速度最大而非速度为零","why":"简谐运动在平衡位置回复力为零、加速度为零，速度达到最大值","do":"在图上找位移为零的横坐标，对照该时刻的速度状态","expr":"x=0\\Rightarrow |v|=v_{\\max}","cues":["位移为零速度最大","平衡位置最快"],"concepts":["平衡位置","速度最大值"]},{"title":"由位移定加速度方向","type":"关系建立","judge":"判断某时刻位移的正负，并由加速度与位移反向确定加速度方向","why":"简谐运动回复力指向平衡位置，加速度方向总与位移方向相反","do":"读出该时刻位移的正负号，取反得到加速度方向，再对照竖直向上为正的规定","expr":"a=-\\omega^{2}x","cues":["加速度指向平衡位置","位移负则加速度正"],"concepts":["回复力","加速度方向","简谐运动动力学"]}],"778":[{"title":"图像斜率读加速度","type":"图像读取","judge":"v-t 图线的斜率绝对值代表加速度大小，需比较两段直线斜率的陡缓","why":"v-t 图像斜率即加速度，比较加速度大小就是比较图线倾斜程度","do":"分别读出 0~3.0 s 段和 3.5~6.0 s 段直线的斜率绝对值并比较","expr":"a=\\left|\\frac{\\Delta v}{\\Delta t}\\right|","cues":["看斜率","比陡缓","斜率就是加速度"],"concepts":["v-t 图像斜率","加速度"]},{"title":"曲线段非匀变速","type":"前提判断","judge":"3.0~3.5 s 图线为曲线，说明该段加速度是否恒定","why":"v-t 图线为曲线则斜率变化，加速度变化，不能当作匀变速处理","do":"观察 3.0~3.5 s 段图线形状，确认斜率是否随时间改变","expr":"","cues":["曲线斜率在变","不是匀变速","加速度不恒定"],"concepts":["匀变速直线运动","非匀变速运动"]},{"title":"面积表示位移","type":"关系建立","judge":"v-t 图线与时间轴围成的面积表示该段位移大小","why":"由 v-t 图像面积等于位移的物理意义，比较两段位移需比较面积","do":"分别估算 0~3.0 s 与 3.0~6.0 s 图线下的面积并比较大小","expr":"x=\\int v\\,dt","cues":["面积就是位移","比面积","数格子"],"concepts":["v-t 图像面积","位移"]},{"title":"曲线段面积估算","type":"数学处理","judge":"3.0~3.5 s 曲线段面积与三角形面积的大小关系","why":"曲线位于连接端点的直线之上或之下，决定面积比三角形大还是小","do":"作辅助直线连接 3.0 s 与 6.0 s 端点，比较曲线与直线所围面积","expr":"x_{2}>\\frac{1}{2}\\times30\\times3.0","cues":["作辅助线","曲线鼓出来","比三角形大"],"concepts":["面积估算","辅助线"]},{"title":"匀加速段平均速度","type":"关系建立","judge":"0~3.0 s 匀加速直线运动的平均速度是否等于初末速度平均值","why":"只有匀变速直线运动才满足平均速度等于初末速度算术平均","do":"用初速度 0 与末速度 30 求平均，与 15 m/s 比较","expr":"\\bar{v}=\\frac{v_0+v}{2}","cues":["匀加速才能取平均","初末速度平均","中间时刻速度"],"concepts":["匀变速直线运动","平均速度"]}],"779":[{"title":"识别铜丝绕行匝数","type":"模型选择","judge":"扭转180°后首尾相接的铜丝沿磁场方向绕了几圈（几匝）","why":"莫比乌斯环只有一条边，铜丝沿这条边绕行一周回到起点时已绕圆柱轴线转了两圈，故等效为两匝串联线圈，匝数因子不能漏","do":"沿铜丝从一端追踪到另一端，数它绕磁场轴线转过的圈数","expr":"n=2","cues":["沿边走一圈","绕了两圈","只有一条边"],"concepts":["莫比乌斯环","匝数","串联"]},{"title":"确定磁场有效面积","type":"几何关系","judge":"穿过回路的磁通量应对应磁场区域面积还是整个纸环围合面积","why":"磁场只存在于半径 r 的圆内，r 以外无磁场，磁通量只计有磁场的部分","do":"比较 r 与 R，取磁场边界圆面积作为有效面积","expr":"S=\\pi r^{2}","cues":["只看有磁场的区域","半径取小的那个","外面没有磁场"],"concepts":["磁通量","有效面积"]},{"title":"区分磁通量变化率","type":"关系建立","judge":"磁通量变化由 B 随时间变化引起还是由面积变化引起","why":"回路静止、面积不变，只有 B=kt 在变，故 ΔΦ/Δt=S·ΔB/Δt","do":"对 Φ=BS 求时间导数，代入 ΔB/Δt=k","expr":"\\frac{\\Delta\\Phi}{\\Delta t}=S\\frac{\\Delta B}{\\Delta t}=k\\pi r^{2}","cues":["面积不变","只有磁场在变","对时间求导"],"concepts":["法拉第电磁感应定律","磁通量变化率"]},{"title":"匝数与变化率相乘","type":"数学处理","judge":"总电动势是单匝电动势乘以匝数还是直接取单匝值","why":"两匝铜丝串联，每匝磁通量变化率相同，电动势相加","do":"将单匝电动势乘以 n=2","expr":"E=n\\frac{\\Delta\\Phi}{\\Delta t}=2k\\pi r^{2}","cues":["两匝要相加","乘匝数","串联叠加"],"concepts":["串联电动势","法拉第电磁感应定律"]}],"780":[{"title":"确定轨道半径大小关系","type":"前提判断","judge":"两望远镜的轨道半径应取地心到卫星的距离，还是题给的离地高度？","why":"万有引力定律中的 r 是到地心的距离，须用地球半径加上离地高度；若直接拿 400 km 与 550 km 比较，结论方向虽同但物理依据错误，且容易在涉及地球半径的选项上出错","do":"写出 r巡=R地+400 km、r哈=R地+550 km，比较得巡天号轨道半径更小","expr":"r=R+h","cues":["离地高度不是半径","要加地球半径","比高度就行"],"concepts":["轨道半径","万有引力"]},{"title":"建立引力提供向心力模型","type":"模型选择","judge":"把两望远镜的运动当作什么模型处理，向心力由谁提供？","why":"题设说明绕地球近似做匀速圆周运动，只有万有引力提供向心力，才能把 G、M、r 与 v、ω、T、a 联系起来","do":"对任一望远镜列万有引力等于向心力的等式，并分别写成含 v、ω、T、a 的四种形式","expr":"\\frac{GMm}{r^{2}}=m\\frac{v^{2}}{r}=m\\omega^{2}r=m\\frac{4\\pi^{2}}{T^{2}}r=ma","cues":["万有引力当向心力","匀速圆周运动","同一个中心天体"],"concepts":["向心力","牛顿第二定律","匀速圆周运动"]},{"title":"判断各量随半径的单调性","type":"关系建立","judge":"v、ω、T、a 各自随轨道半径增大而增大还是减小？","why":"由同一组等式解出的表达式中，v、ω、a 都随 r 增大而减小，只有 T 随 r 增大而增大，方向记反就会把正确项判错","do":"从四个表达式分别看 r 在分子还是分母、在根号内还是外，逐一定出增减性，再代入 r巡<r哈","expr":"v=\\sqrt{\\frac{GM}{r}},\\ \\omega=\\sqrt{\\frac{GM}{r^{3}}},\\ T=\\sqrt{\\frac{4\\pi^{2}r^{3}}{GM}},\\ a=\\frac{GM}{r^{2}}","cues":["半径小转得快","周期看半径三次方","加速度看平方反比"],"concepts":["线速度","角速度","周期","向心加速度"]},{"title":"区分第一宇宙速度","type":"临界条件","judge":"近地轨道环绕速度与第一宇宙速度是什么关系，能否用 7.9 km/s 直接比较？","why":"第一宇宙速度是轨道半径等于地球半径时的最大环绕速度，任何实际卫星轨道半径都大于地球半径，故环绕速度必小于 7.9 km/s；误以为高度小就可以超过它，是这类题的典型陷阱","do":"把 r=R地 代入 v 的表达式得最大环绕速度，再说明 r>R地 时 v 更小","expr":"v_{\\max}=\\sqrt{\\frac{GM}{R_{\\text{地}}}}=7.9\\ \\mathrm{km/s}","cues":["第一宇宙速度是最大值","半径越大速度越小","不可能超过7.9"],"concepts":["第一宇宙速度","近地卫星"]}],"781":[{"title":"安培力方向判定","type":"前提判断","judge":"通电半圆环整体所受安培力的方向是竖直向下还是向上","why":"安培力方向由左手定则决定，需先明确磁场垂直纸面向外、电流沿环从 a 流向 b，逐段判断后由对称性合成","do":"取环上一小段电流元，用左手定则定其安培力方向，再对左右对称的电流元作矢量合成，看水平分量是否抵消、竖直分量指向哪边","expr":"\\Delta\\vec F = I\\Delta\\vec l\\times\\vec B","cues":["左手定则","对称抵消","竖直向下"],"concepts":["安培力","左手定则","对称性"]},{"title":"等效长度取直径","type":"模型选择","judge":"求整个半圆环所受安培力大小时，有效长度取弧长还是取两端连线 ab","why":"匀强磁场中弯曲导线所受安培力只由起点到终点的等效直导线长度决定，与路径形状无关","do":"把半圆环等效为连接 a、b 的直导线，取等效长度等于直径 2r，电流方向由 a 指向 b","expr":"L_{\\text{等效}}=2r","cues":["等效长度","取直径","与弧长无关"],"concepts":["等效长度","安培力"]},{"title":"拉力变化的比较","type":"关系建立","judge":"通电后绳的拉力比通电前变大还是变小","why":"环受重力、两绳拉力和竖直向下的安培力，竖直方向平衡决定拉力随安培力方向改变","do":"对环作竖直方向受力分析，比较通电前后平衡方程中拉力项的变化","expr":"2T=mg+F_{\\text{安}}","cues":["竖直方向平衡","拉力变大","重力加安培力"],"concepts":["共点力平衡","安培力"]},{"title":"安培力大小的计算","type":"数学处理","judge":"把等效长度和磁感应强度、电流代入后得到的安培力是 2rBI 还是别的值","why":"等效长度取直径 2r，安培力大小等于 B、I 与等效长度的乘积","do":"将等效长度 2r 代入安培力公式，得到总安培力大小","expr":"F_{\\text{安}}=BI\\cdot 2r=2rBI","cues":["代入直径","乘电流和磁场","两倍半径"],"concepts":["安培力大小"]}],"782":[{"title":"沿斜面正方向的受力符号","type":"前提判断","judge":"判断沿斜面方向列牛顿第二定律时，重力分量与拉力 F 各自取正还是取负","why":"题设规定沿斜面向下为正，重力沿斜面的分量恒为 +mg sinθ，而 F 的正负由图像(b)读出，符号取错则加速度全错","do":"写出沿斜面方向的合外力表达式，把 mg sinθ 与图像给出的 F 按正方向代数相加","expr":"ma = mg\\sin\\theta + F","cues":["向下为正","重力分量取正","F带符号"],"concepts":["牛顿第二定律","正方向约定","力的分解"]},{"title":"由F-t图读分段恒力","type":"图像读取","judge":"判断 0~4t0 内 F 分成哪几段、每段 F 的大小和正负","why":"F 只在各时间段内为恒值，加速度才分段恒定，才能用匀变速规律或 v-t 图处理","do":"把图(b)按 t0、2t0、3t0、4t0 分段，读出每段 F 的取值（含正负）","expr":"","cues":["分四段","每段恒力","看正负号"],"concepts":["F-t 图像","分段恒定"]},{"title":"算各段加速度","type":"关系建立","judge":"判断每段恒力对应的加速度大小和方向","why":"加速度是画 v-t 图和比较速度、位移的前提，必须逐段由牛顿第二定律算出","do":"把每段的 F 代入 ma=mg sinθ+F，得到各段 a 的大小与方向","expr":"a=\\frac{mg\\sin\\theta+F}{m}","cues":["先求加速度","逐段代入","看方向"],"concepts":["牛顿第二定律","加速度"]},{"title":"画v-t图判运动方向","type":"模型选择","judge":"判断用 v-t 图像的面积和纵坐标来处理速度、位移、动量问题，而不是逐段套运动学公式","why":"加速度分段恒定且方向有正有负，v-t 图能一次看清速度正负（运动方向）与面积（位移）","do":"以初速为零起，按各段加速度斜率画出 0~4t0 的 v-t 折线，检查纵坐标是否始终为正","expr":"","cues":["画速度图","看纵坐标正负","面积是位移"],"concepts":["v-t 图像","速度方向","位移面积"]},{"title":"比较速度与位移","type":"结论整理","judge":"判断 t0 与 2t0 的速度关系、2t0~3t0 与 3t0~4t0 的位移关系","why":"动量正比于速度、位移等于图线面积，只有从 v-t 图上比较纵坐标和面积才能判断这两项","do":"在 v-t 图上读出 t0、2t0 的纵坐标并比较，比较两段图线与横轴围成的面积","expr":"","cues":["比纵坐标","比面积","动量看速度"],"concepts":["动量","v-t 图像面积","位移"]}],"783":[{"title":"斜抛拆成上下两段","type":"模型选择","judge":"把从 H 到落地的斜抛运动拆成上升段和下降段，分别按竖直方向自由落体（逆运动）处理","why":"竖直方向只受重力，上升段可视为从最高点下落的逆过程，两段竖直位移不同、时间不同，不能整体套一个平抛公式","do":"分别写出上升高度 h1=3.2−1.4 与下降高度 h0=3.2，用 h=gt²/2 求两段时间","expr":"h_1=3.2-1.4,\\quad t_{\\text{上}}=\\sqrt{2h_1/g},\\quad t_{\\text{下}}=\\sqrt{2h_0/g}","cues":["拆成上升下降","逆运动","最高点开始算"],"concepts":["斜抛运动","运动的分解","自由落体"]},{"title":"两次飞行时间相同","type":"前提判断","judge":"判断两次抛出的飞行时间是否相等，从而能否用同一时间 t 去除水平位移","why":"两次最高点等高且抛出点相同，竖直方向初速度与总竖直位移都相同，故上升、下降时间均相同","do":"比较两次的竖直初速度 v_y=gt上 与总时间 t=t上+t下，确认二者一致","expr":"t=t_{\\text{上}}+t_{\\text{下}},\\quad v_y=gt_{\\text{上}}","cues":["时间一样","最高点等高","竖直初速度相同"],"concepts":["竖直上抛","运动的独立性"]},{"title":"水平分速度由射程定","type":"关系建立","judge":"用水平方向匀速直线运动，由射程和总时间求两次的水平分速度","why":"水平方向不受力做匀速运动，射程等于水平分速度乘总飞行时间","do":"分别用 OQ1、OQ2 除以同一总时间 t 得 vx1、vx2","expr":"v_{x1}=\\frac{OQ_1}{t},\\quad v_{x2}=\\frac{OQ_2}{t}","cues":["水平匀速","射程除时间","水平速度"],"concepts":["匀速直线运动","分速度"]},{"title":"机械能差只来自水平速度","type":"关系建立","judge":"判断两次在 P 点（同一高度）机械能之差由哪一部分速度决定","why":"同一高度重力势能相同，竖直分速度相同，机械能差只由水平分速度不同引起","do":"用抛出点机械能（或 P 点机械能）作差，只对水平动能项求差","expr":"\\Delta E=\\frac12 m(v_{x2}^2-v_{x1}^2)","cues":["同一高度","势能相同","只差水平动能"],"concepts":["机械能守恒","动能"]},{"title":"落地动能用动能定理","type":"关系建立","judge":"判断落地动能应由抛出动能加上重力做功得到，而不是只算水平动能","why":"从抛出到落地重力做正功 mg·OH，动能定理给出落地动能与抛出动能的关系","do":"对两次分别列 Ek=½m(vx²+vy²)+mg·OH，再求比值","expr":"E_k=\\frac12 m(v_x^2+v_y^2)+mg\\,OH","cues":["动能定理","重力做功","加上下落高度"],"concepts":["动能定理","重力做功"]},{"title":"速度方向夹角比较","type":"结论整理","judge":"判断两次抛出速度方向与落地速度方向的夹角大小关系","why":"竖直分速度两次相同，水平分速度小者速度与水平方向夹角大，抛出与落地两角同时偏大，其夹角也更大","do":"比较 vx1<vx2 时抛出角与落地角的正切值，得出夹角大小","expr":"\\tan\\theta=\\frac{v_y}{v_x}","cues":["看夹角","水平速度小的角大","竖直速度相同"],"concepts":["速度方向","夹角"]}],"784":[{"title":"温度换算为热力学温度","type":"前提判断","judge":"计算气体定律前，是否必须把摄氏温度换算成热力学温度再代入","why":"查理定律等气体定律中的 T 是热力学温度，直接用摄氏温度代入会使比值错误","do":"把 17 ℃ 和 27 ℃ 分别加上 273 得到两个热力学温度","expr":"T_1=17+273=290\\,\\mathrm{K},\\quad T_2=27+273=300\\,\\mathrm{K}","cues":["先加273","换成开尔文","不能直接用摄氏度"],"concepts":["热力学温度","摄氏温度"]},{"title":"判断气体做等容变化","type":"模型选择","judge":"胎内气体升温过程中，压强与温度满足什么关系，能否用等容规律","why":"题设明确体积和质量都不变，一定质量理想气体在体积不变时压强与热力学温度成正比","do":"确认 V 不变、m 不变，选定查理定律作为关系式","expr":"\\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\ (V\\text{ 不变})","cues":["体积不变","质量不变","用查理定律"],"concepts":["等容变化","查理定律","理想气体"]},{"title":"内能只看温度","type":"关系建立","judge":"一定质量理想气体的内能由哪个状态量决定，升温后内能如何变","why":"理想气体分子势能忽略，内能只由温度决定，温度升高内能增大","do":"比较两个状态的温度高低，判断内能大小关系","expr":"U=U(T),\\quad T_2>T_1\\Rightarrow U_2>U_1","cues":["内能只看温度","温度高内能大","与压强无关"],"concepts":["理想气体内能","温度"]}],"785":[{"title":"同入射角比较折射角","type":"关系建立","judge":"入射角相同时，折射率大的光在棱镜中的折射角是更大还是更小","why":"由折射定律 n=sin i/sin r，i 相同则 sin r 与 n 成反比，n 越大 r 越小","do":"对蓝、绿光写出同一入射角下的折射定律，比较两光的折射角","expr":"n=\\frac{\\sin i}{\\sin r}","cues":["入射角一样","折射率大的偏折多","看折射角大小"],"concepts":["折射定律","折射率","折射角"]},{"title":"垂直反射膜的几何条件","type":"几何关系","judge":"光线要垂直射到反射膜，折射光线方向与膜面法线应满足什么几何关系","why":"只有垂直入射到反射膜的光才能原路返回形成激光输出，这是题设给出的出光条件","do":"把折射光线与反射膜法线重合（即折射光线垂直于膜面）作为蓝光、绿光各自满足的条件","expr":"","cues":["垂直膜面","原路返回","折射光线沿法线"],"concepts":["光的反射","法线","原路返回"]},{"title":"换光需改变入射角","type":"前提判断","judge":"入射光线不动时，要让垂直膜面的光由蓝光变为绿光，应增大还是减小入射角","why":"同一棱镜中绿光折射率小，在相同入射角下偏折更小，要使绿光折射光线转到膜面法线方向，必须改变入射角","do":"比较蓝、绿光在同一入射角下的折射方向，判断绿光需把入射角调大还是调小","expr":"","cues":["绿光偏折小","入射角要变","光线不动转棱镜"],"concepts":["折射定律","折射率"]},{"title":"转棱镜方向判断","type":"临界条件","judge":"入射光线方向不变时，转动棱镜使入射角按要求变化，应顺时针还是逆时针转","why":"转动棱镜会同时改变法线方向和入射角，需由入射角应增大还是减小反推棱镜的转向","do":"画出原法线与转动后法线，判断哪种转向使入射角朝所需方向变化","expr":"","cues":["法线跟着转","入射角变大","逆着光转"],"concepts":["入射角","法线","转动方向"]}],"786":[{"title":"对称点场强抵消","type":"模型选择","judge":"判断哪些等分点上的电荷在 O 点产生的场强两两抵消、只需保留哪两个点","why":"八个等分点关于圆心成对分布，等量同号电荷在 O 点的场强沿相反方向、大小相等，矢量和为零；只有 C 与 G 一正一负不能配对抵消","do":"把 A 与 E、B 与 F、D 与 H 分别配对，验证它们在 O 点的场强等大反向，剩下 C、G 两点","expr":"\\vec E_O=\\vec E_C+\\vec E_G","cues":["两两抵消","只看C和G","对称点配对"],"concepts":["电场叠加","对称性","点电荷场强"]},{"title":"C、G 场强同向叠加","type":"关系建立","judge":"判断 C 点正电荷与 G 点负电荷在 O 点产生的场强方向是否相同","why":"C 点 +Q 在 O 点的场强背离 C，G 点 −Q 在 O 点的场强指向 G，而 C、G 在一条直径的两端，两个方向都指向 G 一侧，故同向相加","do":"分别写出两点电荷在 O 点的场强大小，方向相同则直接相加","expr":"E_O=\\frac{kQ}{R^2}+\\frac{kQ}{R^2}","cues":["方向相同","直接相加","都指向G"],"concepts":["场强方向","矢量合成"]},{"title":"电势按距离逐点比较","type":"关系建立","judge":"判断 M、N 两点电势高低时，能否只看 C、G 两个电荷而把其余六个电荷的贡献整体消去","why":"电势是标量，其余六个等量正电荷到 M、N 的距离按对称性成对相等，贡献相同可整体约去，只剩 C（正）与 G（负）两点的贡献之差决定高低","do":"写出 M、N 电势的叠加式，把对称点电荷的贡献配对约去，只比较 C、G 两项","expr":"\\varphi_M-\\varphi_N=(\\varphi_{CM}-\\varphi_{CN})+(\\varphi_{GM}-\\varphi_{GN})","cues":["电势是标量","对称的约掉","只比C和G"],"concepts":["电势叠加","标量叠加","对称性"]},{"title":"正负电荷距离远近定高低","type":"临界条件","judge":"判断 M 比 N 离 C 点正电荷更近、离 G 点负电荷更远，从而确定两项贡献的符号","why":"点电荷电势随距离增大而减小，正电荷近处电势高、负电荷近处电势低；M 在 OC 上靠近 C，N 在 OG 上靠近 G","do":"比较 MC 与 NC、MG 与 NG 的长度，判断 C 项与 G 项各自使 φ_M−φ_N 取正还是取负","expr":"\\varphi_{CM}>\\varphi_{CN}>0,\\quad 0>\\varphi_{GM}>\\varphi_{GN}","cues":["离正电荷近","离负电荷远","两项都为正"],"concepts":["点电荷电势","电势高低"]},{"title":"电场力做功看电势能","type":"结论整理","judge":"判断沿 MN 移动正电荷时电场力做正功还是负功，应比较电势能而非只看路径形状","why":"电场力做功等于电势能的减少量，与路径无关；正电荷在高电势处电势能大，从高电势移到低电势电势能减小","do":"由 φ_M 与 φ_N 的高低判断 +q 的电势能变化，再由 W=−ΔE_p 定做功正负","expr":"W=q(\\varphi_M-\\varphi_N)","cues":["与路径无关","看电势能","正电荷顺电势降"],"concepts":["电场力做功","电势能","电势差"]}],"787":[{"title":"游标卡尺读数规则","type":"实验操作","judge":"十分度游标卡尺的主尺读数与游标对齐格数应如何组合、以什么单位记录","why":"游标卡尺读数=主尺整毫米数+游标对齐格数×分度值(0.1 mm)，且题目要求以 cm 为单位，需换算","do":"读图(b)：主尺读整厘米刻度，找出游标上与主尺刻线对齐的格数，按 0.1 mm 分度值算出小数部分，再换算成 cm","expr":"d=d_{\\text{主}}+n\\times 0.1\\,\\mathrm{mm}","cues":["看游标第几格对齐","分度值是零点一毫米","结果要换成厘米"],"concepts":["游标卡尺","分度值","有效数字"]},{"title":"由挡光时间判断倾斜方向","type":"关系建立","judge":"A、B 两处挡光时间不等说明小车在减速还是加速，从而判断应抬高哪一端","why":"平衡阻力要求小车不受合力沿轨道方向的分量、做匀速直线运动；挡光时间越长说明该处速度越小","do":"比较 13.56 ms 与 17.90 ms，由 v=d/Δt 判断 A、B 哪端速度大，速度小的一侧说明轨道偏低，需抬高该侧","expr":"v=\\frac{d}{\\Delta t}","cues":["时间长的速度小","速度变小说明在减速","哪边低抬哪边"],"concepts":["匀速直线运动","平衡摩擦力","平均速度"]},{"title":"挡光片宽度近似瞬时速度","type":"近似条件","judge":"能否用 d/Δt 代表小车（含子弹）经过光电门时的速度","why":"挡光片宽度很小、挡光时间极短，这段时间内的平均速度可近似为该位置的瞬时速度","do":"写出碰后小车速度 v车=d/Δt，作为动量守恒方程中碰后共同速度","expr":"v_{\\text{车}}=\\frac{d}{\\Delta t}","cues":["用平均速度代替","时间很短误差小"],"concepts":["瞬时速度","平均速度","极限思想"]},{"title":"选子弹与小车为系统","type":"模型选择","judge":"动量守恒应对哪个系统、哪个过程列式，碰前碰后各是什么状态","why":"子弹射入并粘在小车上的极短时间内，系统水平方向不受外力（阻力已平衡），动量守恒；碰前只有子弹运动，碰后二者共同运动","do":"对子弹+小车系统，取子弹初速方向为正，列碰前 mv 等于碰后 (M+m)v车，再解出 v","expr":"mv=(M+m)\\frac{d}{\\Delta t}","cues":["取子弹和小车整体","碰撞时间极短","碰后一起运动"],"concepts":["动量守恒定律","完全非弹性碰撞","系统"]},{"title":"多次测量取平均","type":"数据处理","judge":"五次速度值应如何汇总为一个结果、保留几位有效数字","why":"多次测量取算术平均可减小偶然误差；题目要求保留 3 位有效数字","do":"将五个 v 值相加除以 5，按 3 位有效数字写出平均值","expr":"\\bar v=\\frac{v_1+v_2+v_3+v_4+v_5}{5}","cues":["五次取平均","减小偶然误差","保留三位有效数字"],"concepts":["算术平均","偶然误差","有效数字"]}],"788":[{"title":"分压接法的安全位置","type":"实验操作","judge":"闭合开关前滑片应放在哪一端，才能让测量部分电压从零开始","why":"电路为分压式接法，滑片在a端时测量支路分得电压为零，元件不会被大电流冲击","do":"对照图(a)看滑动变阻器的接线方式，判断哪一端使并联输出为零","expr":"","cues":["分压接法","从零开始调","保护元件"],"concepts":["分压式接法","滑动变阻器"]},{"title":"电压表估读规则","type":"数据处理","judge":"3 V量程、0.1 V分度值下应估读到哪一位","why":"分度值为0.1 V，需估读到下一位即0.01 V，读数才符合有效数字要求","do":"读图(b)指针位置，按0.1 V分度估读到百分位","expr":"","cues":["估读一位","分度值是0.1","看指针位置"],"concepts":["电压表读数","估读"]},{"title":"非线性元件的电阻求法","type":"关系建立","judge":"发光元件电阻随电压变化，某工作点电阻该用哪组量求","why":"伏安特性曲线弯曲，电阻只能由该状态下的U与I之比定义，不能取斜率","do":"用该次测量的U和I代入R=U/I，并换算mA为A","expr":"$R=\\frac{U}{I}$","cues":["用这一点的电压电流","不是斜率","换算成安培"],"concepts":["欧姆定律","伏安特性曲线"]},{"title":"由曲线判断电阻趋势","type":"图像读取","judge":"1.0~18.0 mA范围内U/I比值随电压如何变化","why":"曲线斜率与U/I不同，需比较各点U与I的比值而非曲线斜率","do":"在曲线上取若干点算U/I，比较随电压增大比值的变化","expr":"$R=\\frac{U}{I}$","cues":["看比值不看斜率","电压越大电阻越小","两条曲线都这样"],"concepts":["伏安特性曲线","电阻定义"]},{"title":"同电流下电压差异","type":"图像读取","judge":"10.0 mA时红光与蓝光元件各自需要多大电压","why":"两元件要同时工作在10 mA，但所需电压不同，必须靠串并联分配电压","do":"在图(c)中作I=10 mA水平线，读出两曲线对应的电压并比较大小","expr":"","cues":["作水平线读电压","蓝光电压大","电压不一样"],"concepts":["伏安特性曲线","串并联电压关系"]},{"title":"串并联组合设计","type":"模型选择","judge":"电压较小的元件该串电阻还是并电阻，才能与另一元件同时达到10 mA","why":"并联支路电压相等，电压不足的支路需串联电阻分压补足，才能与高电压元件并联","do":"把需分压的元件与滑动变阻器串联，再与另一元件并联接在电源两端","expr":"","cues":["串联分压","再并联","电压补齐"],"concepts":["串联分压","并联等压"]}],"789":[{"title":"选研究对象","type":"模型选择","judge":"把木板（含人）作为整体受力对象，还是分别分析人和木板","why":"人与木板一起匀速前进，加速度为零，二者之间作用力属于内力，取整体可避开","do":"把人和木板看成一个整体，只画整体受到的外力：两条绳的拉力、重力、地面支持力与阻力","expr":"","cues":["取整体","人和板一起看","别管内力"],"concepts":["整体法","受力分析"]},{"title":"拉力分解与合力","type":"关系建立","judge":"两条绳的拉力在水平方向如何合成，竖直分量是否参与水平平衡","why":"两绳平行且与地面成 θ 角，水平分量同向相加，竖直分量向上，只影响支持力不影响水平平衡","do":"把每条拉力分解为水平分量 Fcosθ 与竖直分量 Fsinθ，水平方向取两绳之和 2Fcosθ","expr":"F_x=2F\\cos\\theta","cues":["分解拉力","水平分量相加","两条绳"],"concepts":["力的分解","合力"]},{"title":"匀速定平衡","type":"前提判断","judge":"能否用水平方向合力为零求阻力，而不是用牛顿第二定律求加速度","why":"题目明确'匀速前进'，加速度为零，水平方向拉力合力与阻力等大反向","do":"对整体在水平方向列平衡方程，令 2Fcosθ 等于阻力 f","expr":"2F\\cos\\theta=f","cues":["匀速就是合力为零","先看加速度","平衡方程"],"concepts":["平衡条件","匀速直线运动"]},{"title":"功只算位移方向","type":"关系建立","judge":"求总功时用哪个位移、哪个力分量，竖直分量是否做功","why":"功等于力在位移方向的分量与位移的乘积，竖直分量与水平位移垂直不做功","do":"用两绳水平合力乘水平位移，或每条绳水平分量乘位移再乘 2","expr":"W=2F\\,l\\cos\\theta","cues":["只看水平分量","竖直不做功","位移方向"],"concepts":["功的定义","力的分解"]},{"title":"功率用总功除时间","type":"关系建立","judge":"求总功率时用总功除以总时间，还是用单个力乘速度","why":"功率定义是功与完成该功所用时间之比，两绳总功对应同一段时间","do":"用第（2）问的总功除以 15 s，或等价地用水平合力乘匀速速度","expr":"P=\\frac{W}{t}=2Fv\\cos\\theta","cues":["总功除时间","先求速度也行","平均功率"],"concepts":["功率","平均功率"]}],"790":[{"title":"选加速段规律","type":"模型选择","judge":"M 到 N 只受电场力、初速为零，该用动能定理还是牛顿定律加运动学","why":"C1 板间为匀强电场，粒子沿极板方向直线加速，只有电场力做功 qU，且不涉及时间","do":"对 M→N 段列动能定理，直接由 qU 求 N 点速度","expr":"qU=\\frac{1}{2}mv_N^2","cues":["用动能定理","只受电场力","初速为零"],"concepts":["动能定理","匀强电场"]},{"title":"分解 C2 中运动","type":"关系建立","judge":"粒子进入 C2 后做类平抛还是匀变速直线，初速度方向与电场方向各是什么","why":"粒子紧贴下极板水平进入，初速度沿 x 方向，而 C2 板间电场沿 y 方向，故水平匀速、竖直匀加速","do":"把 C2 内运动分解为水平方向匀速 v_N 和竖直方向初速为零的匀加速，竖直位移为板间距 d","expr":"d=\\frac{1}{2}at^2,\\quad v_y=at","cues":["类平抛","水平匀速","竖直加速"],"concepts":["运动的合成与分解","类平抛运动"]},{"title":"竖直位移取板间距","type":"几何关系","judge":"粒子在 C2 中竖直方向走过的距离是否等于 O、P 间距离 d","why":"粒子从紧贴下极板处进入、从上极板右端 P 点射出，竖直方向恰好跨越整个板间距，而板间距由 O、P 距离 d 给出","do":"把竖直方向位移取为 d，与水平方向速度 v_N 联立求 v_y","expr":"\\frac{qU}{d}=ma,\\quad d=\\frac{1}{2}at^2","cues":["竖直走满板间距","位移就是d","从下板到上板"],"concepts":["匀强电场","匀变速直线运动"]},{"title":"夹角用速度分量比","type":"关系建立","judge":"P 点速度与 y 轴正向的夹角应由哪两个速度分量之比确定","why":"P 点速度是水平分量 v_N 与竖直分量 v_y 的合速度，夹角是相对 y 轴而非 x 轴量度","do":"写出 tanθ=v_N/v_y，代入已求出的 v_N、v_y 求角","expr":"\\tan\\theta=\\frac{v_N}{v_y}","cues":["相对y轴量","用两分量比","别取错邻边"],"concepts":["速度的合成","正切函数"]},{"title":"磁场半径由几何定","type":"几何关系","judge":"粒子在磁场中做圆周运动的半径与 d 是什么关系，圆心在哪","why":"粒子从 P 垂直 y 轴方向进入磁场、又恰好垂直 x 轴离开，速度方向各转 90°，轨迹为四分之一圆弧，圆心在 O 点，半径即 OP","do":"由入射、出射速度方向均与边界垂直，定出圆心在 O，得 R=OP=d 的两倍关系需按图核对，取 R=2d","expr":"R=2d","cues":["四分之一圆弧","圆心在O","半径看OP"],"concepts":["洛伦兹力","圆周运动几何关系"]},{"title":"磁场用合速度","type":"前提判断","judge":"列洛伦兹力方程时用 P 点合速度还是只用水平分量","why":"粒子进入磁场时的速度是经两次电场加速后的合速度 v_P，洛伦兹力大小与合速度成正比","do":"先由分量合成 v_P，再对磁场中圆周运动列牛顿第二定律求 B","expr":"v_P=\\sqrt{v_N^2+v_y^2},\\quad qv_PB=\\frac{mv_P^2}{R}","cues":["用合速度","先合成再代入","不能只用水平分量"],"concepts":["洛伦兹力","牛顿第二定律"]}],"791":[{"title":"静止时绳拉力为零","type":"前提判断","judge":"撤去电场前 A、B、C 均静止且弹簧处于原长，绳中拉力是否为零","why":"A、B 整体在光滑桌面上只受弹簧弹力和绳拉力，弹簧原长时弹力为零，若绳有拉力则 A、B 不能静止，故拉力必为零","do":"对 A、B 整体列水平方向平衡，得绳拉力为零，再单独对 C 列竖直平衡","expr":"T=0,\\quad qE=m_C g","cues":["弹簧原长","绳没拉力","只看小球C"],"concepts":["共点力平衡","整体法"]},{"title":"匀速时摩擦达最大静摩擦","type":"临界条件","judge":"C 开始匀速运动瞬间，B 与 A 之间是静摩擦还是滑动摩擦、摩擦力取何值","why":"C 匀速说明绳拉力等于 m_C g，B 匀速说明 B 受摩擦力等于绳拉力；此时 A、B 恰好要相对滑动，摩擦力达到最大静摩擦即滑动摩擦","do":"对 C 和 B 分别列平衡，联立求 μ","expr":"T_1=m_C g,\\quad T_1=\\mu m_B g","cues":["匀速就是平衡","刚好要滑动","摩擦力取最大值"],"concepts":["最大静摩擦力","滑动摩擦力"]},{"title":"两弹簧同形变同势能","type":"关系建立","judge":"C 下降 0.2 m 时两根弹簧的弹性势能是否相等、总势能是多少","why":"A 通过两根相同弹簧与固定挡板相连，A 平移时两弹簧形变量相同，故弹性势能相同，系统总弹性势能为 2E_p","do":"写出能量守恒方程时弹性势能项取 2E_p，并注意 A、B、C 三者速度大小相等","expr":"m_C g h=\\tfrac12(m_A+m_B+m_C)v^2+2E_p","cues":["两根弹簧一样","势能要乘二","三者速度相同"],"concepts":["能量守恒","弹性势能"]},{"title":"由临界平衡反求劲度系数","type":"关系建立","judge":"如何用第（2）问的临界状态求出弹簧劲度系数 k","why":"C 匀速瞬间正是 A、B 即将相对滑动的临界，此时 A 受两弹簧拉力与最大静摩擦平衡，形变量就是 C 下降的 0.2 m","do":"对 A 列水平平衡，用 2kx_0=μ m_B g 求 k","expr":"2kx_0=\\mu m_B g,\\quad x_0=0.2\\,\\mathrm{m}","cues":["临界时A也平衡","形变量就是下降高度","两根弹簧一起拉"],"concepts":["胡克定律","临界状态"]},{"title":"电场反向时先整体后隔离","type":"模型选择","judge":"电场竖直向下时，求 B 与 A 即将相对滑动的位置，应选谁为研究对象、用什么规律","why":"滑动前 A、B 加速度相同，需先用整体（B、C 绳连接）求加速度，再隔离 A 用牛顿第二定律把加速度与弹簧形变联系起来","do":"对 A 列 f-2kh'=m_A a，对 B、C 整体列 qE+m_C g-f=(m_B+m_C)a，联立解 h'","expr":"f-2kh'=m_A a,\\quad qE+m_C g-f=(m_B+m_C)a","cues":["先整体求加速度","再隔离A","摩擦力取2牛"],"concepts":["牛顿第二定律","隔离法"]},{"title":"撤电场后速度最大在再次临界","type":"临界条件","judge":"撤去电场后 A 第一次从右向左运动过程中，速度最大出现在哪个位置","why":"A、B 一起运动时系统做简谐运动，速度最大出现在合力为零（即弹簧形变回到 x_0、摩擦力恰好达到最大静摩擦）的平衡位置，此后 A 单独做简谐运动，最大速度即该处速度","do":"对撤电场到形变达 x_0 的过程列能量守恒，求出该处速度即为全过程最大速度","expr":"m_C g(x_0-h')=\\tfrac12(m_A+m_B+m_C)v_{\\max}^2+2\\cdot\\tfrac12kx_0^2-\\left[\\tfrac12(m_A+m_B+m_C)v'^2+2\\cdot\\tfrac12kh'^2\\right]","cues":["速度最大在平衡位置","形变回到0.2米","简谐运动对称"],"concepts":["简谐运动","能量守恒","平衡位置"]}],"792":[{"title":"由间距读加速度方向","type":"图像读取","judge":"相邻等时间间隔位置间距的变化趋势说明速度在增大还是减小","why":"相邻位置时间间隔相等，间距就是各段的平均速度，间距先变大后变小即速度先增后减","do":"比较图中各相邻位置间距，找出间距最大的一段，判断速度先增大后减小","expr":"","cues":["看间距","先疏后密","间距变大再变小"],"concepts":["平均速度","位移"]},{"title":"加速度与速度同向反向","type":"关系建立","judge":"速度增大阶段加速度向下、速度减小阶段加速度向上","why":"加速度方向与速度变化方向一致，速度向下增大则加速度向下，向下减小则加速度向上","do":"把速度先增后减对应到加速度先向下后向上","expr":"","cues":["先加速后减速","加速度先下后上","速度变化方向"],"concepts":["加速度","速度变化"]},{"title":"合力方向定 f 与 G 大小","type":"关系建立","judge":"加速度向下时合力向下，加速度向上时合力向上，据此比较 f 与 G","why":"小圆盘只受重力 G 和向上作用力 f，合力方向由二者大小关系决定，牛顿第二定律给出合力与加速度同向","do":"","expr":"$G-f=ma$","cues":["合力向下","f小于G","f大于G"],"concepts":["牛顿第二定律","合力"]},{"title":"排除匀速与单调情形","type":"结论整理","judge":"图中间距是否恒定或单调变化，以排除匀速、一直加速、一直减速的说法","why":"若间距恒定则匀速，若间距一直增大或一直减小则加速度方向不变，均与图中先疏后密不符","do":"检查间距是否先增大后减小，排除匀速和单向加速/减速的干扰项","expr":"","cues":["不是匀速","一直加速不对","先疏后密"],"concepts":["匀速运动","加速度"]}],"793":[{"title":"卫星做圆周运动的向心力来源","type":"模型选择","judge":"判断卫星做匀速圆周运动的向心力由什么力提供","why":"卫星只受土星引力，且引力方向指向土星中心，恰好充当向心力；若把引力与向心力并列成两个力就会多写一个力","do":"对任一颗卫星画受力图，确认只受万有引力，把它写在向心力位置","expr":"F_{\\text{引}}=F_{\\text{向}}","cues":["引力当向心力","只受万有引力","别再加离心力"],"concepts":["万有引力","向心力","匀速圆周运动"]},{"title":"卫星质量可约去","type":"关系建立","judge":"判断列式后卫星自身质量能否消去，从而加速度只与中心天体质量和轨道半径有关","why":"引力与向心加速度都正比于卫星质量，两边同除卫星质量即消去，所以不同质量的卫星在同一半径处加速度相同","do":"写出引力等于质量乘向心加速度的方程，两边约去卫星质量","expr":"G\\frac{Mm}{r^{2}}=ma\\ \\Rightarrow\\ a=\\frac{GM}{r^{2}}","cues":["质量约掉","与卫星质量无关","只看土星质量"],"concepts":["牛顿第二定律","万有引力定律","中心天体质量"]},{"title":"加速度与半径的平方反比","type":"数学处理","judge":"由加速度表达式判断 a 与 r 是正比、反比还是平方反比，并写成两卫星间的等式","why":"a=GM/r² 中 G、M 对两颗卫星相同，故 a 与 r² 成反比，交叉相乘得 a 与 r² 的乘积相等","do":"对两颗卫星分别写出 a₁r₁²=GM 与 a₂r₂²=GM，令其相等","expr":"a_{1}r_{1}^{2}=a_{2}r_{2}^{2}","cues":["平方反比","乘积相等","半径平方在分母"],"concepts":["平方反比关系","比例式"]},{"title":"排除正比与反比形式","type":"结论整理","judge":"判断选项中 a 与 r 成正比、成反比、或与 r² 成反比这几种形式哪个与推导一致","why":"只有 a∝1/r² 与 GM/r² 相符；写成 a₁r₁=a₂r₂ 相当于 a∝1/r，写成 a₁/r₁=a₂/r₂ 相当于 a∝r，都与平方反比矛盾","do":"把推导出的 a₁r₁²=a₂r₂² 与各选项的比例式对照，只保留平方反比形式","expr":"a\\propto\\frac{1}{r^{2}}","cues":["不是反比","不是正比","平方才对"],"concepts":["比例关系辨析"]}],"794":[{"title":"判断光偏折方向","type":"图像读取","judge":"光从棱镜斜射入液体时，折射光线相对入射光线是靠近还是远离法线","why":"折射定律中入射角与折射角的大小关系直接由两侧介质折射率的相对大小决定，偏折方向是判断 n 与 n0 大小关系的唯一依据","do":"在光路图上找出棱镜与液体分界处的法线，比较入射光线与法线的夹角和折射光线与法线的夹角","expr":"","cues":["看偏折方向","靠近法线还是远离","先画法线"],"concepts":["折射定律","法线","入射角与折射角"]},{"title":"由角度大小定折射率","type":"关系建立","judge":"由入射角小于折射角，判断哪一侧介质折射率更大","why":"光从光密介质射入光疏介质时折射角大于入射角，即折射率大的介质中角小","do":"把入射角、折射角的大小关系代入折射定律，比较 n0 与 n","expr":"n_0\\sin i=n\\sin r","cues":["角小的一边折射率大","光密进光疏","谁大谁小"],"concepts":["折射定律","光密介质与光疏介质"]},{"title":"折射率与波速关系","type":"关系建立","judge":"由 n 与 n0 的大小关系推出 v 与 v0 的大小关系","why":"折射率与介质中光速成反比，折射率越小光速越大","do":"用折射率与速度的反比关系，把 n<n0 换算成 v 与 v0 的不等号","expr":"v=\\frac{c}{n}","cues":["折射率小速度大","速度与折射率反比","换成速度比"],"concepts":["折射率","光速"]}],"795":[{"title":"确定弹力方向","type":"模型选择","judge":"球与横杆、墙面两处接触，各自的支持力沿什么方向","why":"不计摩擦，接触面只能提供垂直于接触面的支持力；横杆是水平杆，支持力垂直于杆（竖直方向），墙面支持力垂直于墙（水平方向）","do":"画出球的三力受力图：重力竖直向下、墙的支持力水平、横杆支持力竖直向上","expr":"","cues":["光滑接触","支持力垂直面","横杆给竖直力"],"concepts":["弹力方向","光滑接触面","受力分析"]},{"title":"把半径关系转成角度","type":"几何关系","judge":"接触点到墙的距离 1.8R 与半径 R 如何确定横杆支持力与竖直方向的夹角","why":"球心到墙的距离等于半径 R，接触点比球心更靠外，二者水平差为 1.8R−R，与半径 R 构成直角三角形，才能把长度条件转成角度","do":"以球心、接触点、球心在横杆上的投影作直角三角形，求该角的余弦或正弦","expr":"\\cos\\alpha=\\frac{R}{1.8R-R}","cues":["球心离墙一个半径","水平差是0.8R","斜边是半径"],"concepts":["几何关系","直角三角形"]},{"title":"选竖直方向列平衡","type":"关系建立","judge":"三力平衡时该沿哪个方向列方程，才能只含一个未知力","why":"墙的支持力水平、重力竖直，只有竖直方向方程不含墙的支持力，可直接解出横杆支持力","do":"对球列竖直方向合力为零的方程，把横杆支持力分解到竖直方向","expr":"F_N\\cos\\alpha=mg","cues":["竖直方向平衡","避开墙的力","只留一个未知数"],"concepts":["共点力平衡","正交分解"]},{"title":"区分球受的力与球施的力","type":"结论整理","judge":"题目问的是球对横杆的压力，还是横杆对球的支持力","why":"作用力与反作用力等大反向，求出的是横杆对球的支持力，需用牛顿第三定律转换后才能作为答案","do":"把求得的支持力大小作为球对横杆压力的大小","expr":"F_N'=F_N","cues":["问的是球压杆","反作用力等大","大小一样"],"concepts":["牛顿第三定律","作用力与反作用力"]}],"796":[{"title":"判断框内合磁场方向","type":"前提判断","judge":"两长直导线在框所在区域产生的磁场叠加后，净磁场指向纸内还是纸外","why":"安培力方向由左手定则决定，必须先确定框所在处的磁场方向；两导线电流反向，需分别用右手螺旋定则判断后叠加","do":"对左导线和右导线分别用右手螺旋定则判断其右侧/左侧区域的磁场方向，再比较两磁场是否同向叠加","expr":"","cues":["右手螺旋定则","两电流反向","磁场叠加"],"concepts":["右手螺旋定则","磁场的叠加"]},{"title":"比较两侧磁场强弱","type":"关系建立","judge":"框的左半部分与右半部分所处磁场哪个更强","why":"两导线到框对称轴距离相等，但 I1>I2，由 B∝I/r 可知靠近 I1 的一侧磁场更强，这是合力方向由谁主导的依据","do":"比较左、右导线在框对应位置产生的磁感应强度大小，得出左半侧磁场更强","expr":"B=\\frac{\\mu_0 I}{2\\pi r}","cues":["电流大的磁场强","离导线越近越强","左边更强"],"concepts":["长直导线磁场","磁感应强度"]},{"title":"水平段安培力抵消","type":"模型选择","judge":"框的上、下两段水平导线所受安培力是否相互抵消，可否不参与合力计算","why":"同一竖直线上磁场相同，上下水平段电流方向相反、长度相同，安培力等大反向，对合力无贡献","do":"对上下水平段分别用左手定则判断受力方向，确认二者等大反向","expr":"F=BIL","cues":["上下抵消","水平段不用算","等大反向"],"concepts":["安培力","左手定则"]},{"title":"竖直段受力方向与大小","type":"关系建立","judge":"左、右两竖直段所受水平安培力各指向哪边、哪边更大","why":"竖直段电流方向相反（顺时针），处于同向磁场中，左手定则给出相反方向的力；再由左侧磁场更强得出左侧力更大","do":"对左、右竖直段分别用左手定则定方向，再用 F=BIL 比较大小","expr":"F=BIL","cues":["左手定则","左边力大","方向相反"],"concepts":["左手定则","安培力"]},{"title":"合成合力方向","type":"结论整理","judge":"左右竖直段水平安培力合成后，合力指向哪一侧","why":"水平段已抵消，只剩两竖直段的水平力，二者反向不等大，合力由较大者决定","do":"把左、右竖直段的水平力按方向合成，取较大力的方向为合力方向","expr":"","cues":["看谁大","合力向左","只剩竖直段"],"concepts":["力的合成"]}],"797":[{"title":"F-x图面积即功","type":"图像读取","judge":"求变力做的功，是逐段算矩形面积还是用别的办法","why":"F 随 x 变化，功的定义 W=∫F dx 在 F-x 图上就是图线与 x 轴围成的面积，只有按面积求才能得到总功","do":"把 0 到 3 m 的图线分成两段，分别算每段矩形面积再相加","expr":"W_F=\\int_0^3 F\\,dx=S_{\\text{图}}","cues":["算面积","分两段","图线下方面积"],"concepts":["功的定义","F-x图像面积"]},{"title":"分段累加而非取平均","type":"数学处理","judge":"两段高度不同的矩形面积是相加还是取平均力乘总位移","why":"F 不是随 x 线性变化，不能用平均力求功，只能分段累加各段恒力做的功","do":"第一段用该段恒力乘该段位移，第二段同理，再求和","expr":"W_F=F_1x_1+F_2x_2","cues":["分段加","不能取平均","各算各的"],"concepts":["变力做功","分段求和"]},{"title":"用动能定理求速度","type":"关系建立","judge":"地面光滑、无摩擦和其他力，求 3 m 处速度该用什么规律","why":"只有 F 做功，合外力功等于动能变化，初速为零，可直接由总功求末速度","do":"令总功等于末动能，解出 x=3 m 处的速度","expr":"W_F=\\tfrac12 mv^2-0","cues":["动能定理","初速为零","只有F做功"],"concepts":["动能定理","动能"]},{"title":"瞬时功率取该点F","type":"前提判断","judge":"算瞬时功率时 F 取 3 m 处的力还是全程的平均力","why":"P=Fv 中的 F 必须是该瞬时位置的力，速度也是该位置的速度，两者要对应同一时刻","do":"从图上读出 x=3 m 处的 F 值，与刚求出的 v 相乘","expr":"P=F(x=3)\\,v","cues":["取该点的力","同一时刻","别用平均力"],"concepts":["瞬时功率","P=Fv"]}],"798":[{"title":"判定两电荷电性","type":"前提判断","judge":"qA 与 qB 是同种还是异种电荷","why":"C 点合场强沿圆的切线方向，而 A、B 在 C 点产生的场强分别沿 AC、BC 连线方向，只有两场强在切线法线方向的分量相互抵消，合场强才可能沿切线；同种电荷时两分量在法线方向同向叠加，无法抵消","do":"画出 C 点处沿 CA、CB 方向的两个分场强，看它们在半径 OC 方向上的分量能否反向抵消","expr":"","cues":["两场强要抵消法向分量","同种电荷抵消不了","异种电荷才行"],"concepts":["电场叠加","点电荷场强方向"]},{"title":"定圆心与半径关系","type":"几何关系","judge":"AC、BC 与圆半径 r 的定量关系","why":"AB 为直径，故 ∠ACB 为直角；再由直径 AB 与弦 BC 夹角 30° 可定出各边与半径的比例，场强按距离平方反比，必须先把距离换成 r 的倍数","do":"利用直径所对圆周角为直角、以及 30° 角，解出 AC=r、BC=√3 r","expr":"r_{AC}=r,\\quad r_{BC}=\\sqrt{3}\\,r","cues":["直径所对是直角","先算边长比例","距离换成半径倍数"],"concepts":["圆的性质","几何关系"]},{"title":"切线方向定分量比","type":"关系建立","judge":"合场强沿切线这一条件给出 EA 与 EB 的什么比例","why":"合场强沿切线等价于两分场强在法线（半径 OC）方向分量等大反向，这一分量平衡条件把 EA、EB 的大小锁定为一个固定比值，而不是任意值","do":"把 EA、EB 分别投影到 OC 方向，令两投影大小相等，解出 EA/EB","expr":"E_A\\sin 30^{\\circ}=E_B\\sin 60^{\\circ}\\ \\Rightarrow\\ \\frac{E_A}{E_B}=\\sqrt{3}","cues":["法向分量相等","投影到半径方向","切线方向合成为零法向"],"concepts":["电场叠加","矢量分解"]},{"title":"场强反推电荷量比","type":"数学处理","judge":"由场强比和距离比反解 qA/qB","why":"点电荷场强 E=kq/r²，距离已由几何确定，场强比与距离平方比共同决定电荷量比；漏掉距离平方会得到错误比值","do":"写出 EA=kqA/rAC²、EB=kqB/rBC²，代入 EA/EB 与距离比求解","expr":"\\frac{q_A}{q_B}=\\frac{E_A}{E_B}\\cdot\\frac{r_{AC}^2}{r_{BC}^2}","cues":["别忘了距离平方","场强比乘距离平方比","代点电荷公式"],"concepts":["库仑定律","点电荷场强"]}],"799":[{"title":"真空中光速不变","type":"前提判断","judge":"两种波长的射电波在真空中传播速度是否相同","why":"真空中所有电磁波传播速度都等于 c，与波长、频率无关；若误以为波长不同速度就不同，后续频率比较全错","do":"确认两辐射同为真空中电磁波，速度都取 c","expr":"c=\\lambda\\nu","cues":["速度都一样","真空光速不变","波长长跑得快"],"concepts":["电磁波谱","光速"]},{"title":"波长与频率反比","type":"关系建立","judge":"波长较长的一方对应频率较大还是较小","why":"由 c=λν，c 相同，波长与频率成反比，这是比较能量、动量的共同前提","do":"比较 21 cm 与 18 cm，写出 ν=c/λ 判断频率大小关系","expr":"\\nu=\\frac{c}{\\lambda}","cues":["波长越长频率越低","先比频率","反比关系"],"concepts":["波长","频率"]},{"title":"光子能量由频率定","type":"关系建立","judge":"光子能量大小该由频率还是波长直接决定","why":"光子能量 E=hν，只由频率决定；波长较长则频率较小，能量较小","do":"用 E=hν 结合上一步频率关系比较两光子能量","expr":"E=h\\nu=\\frac{hc}{\\lambda}","cues":["能量看频率","频率低能量小","用普朗克常量"],"concepts":["光子能量","普朗克常量"]},{"title":"光子动量由波长定","type":"关系建立","judge":"光子动量与波长是正比还是反比","why":"光子动量 p=h/λ，波长越长动量越小，与能量结论方向一致","do":"用 p=h/λ 直接比较 21 cm 与 18 cm 对应的动量","expr":"p=\\frac{h}{\\lambda}","cues":["动量看波长","波长越长动量越小","德布罗意关系"],"concepts":["光子动量","德布罗意波长"]}],"800":[{"title":"确定初始位置","type":"前提判断","judge":"t=0 由静止释放时，小球处于最低点还是最高点","why":"简谐运动中由静止释放的位置就是速度为零的端点，题设对小球施加向下的力使其偏离平衡位置后释放，故释放点是最低点","do":"由“向下施力后静止释放”判断 t=0 时小球在最低点，并据此确定此后各时刻的相位","expr":"","cues":["向下压后释放","最低点","速度为零","端点"],"concepts":["简谐运动","平衡位置","振幅"]},{"title":"由周期定位时刻相位","type":"关系建立","judge":"t=1.5T 对应运动到哪个位置","why":"从最低点起经 1.5 个周期，相位推进 3π，恰好到达另一端点即最高点","do":"以最低点为起点，按每 T/2 换一个端点推算 1.5T 时的位置","expr":"t=1.5T=\\frac{3T}{2}","cues":["一个半周期","到最高点","半个周期换端点"],"concepts":["周期","相位","简谐运动"]},{"title":"判断位移与速度","type":"结论整理","judge":"最高点处位移的方向和速度是否为零","why":"最高点在平衡位置上方，位移沿正方向且取最大值；端点处速度为零","do":"比较该点与平衡位置的高低定位移正负，由端点性质定速度为零","expr":"x=+A,\\quad v=0","cues":["最高点位移最大","向上为正","端点速度为零"],"concepts":["位移","速度","振幅"]},{"title":"判断回复力与加速度","type":"关系建立","judge":"最高点处回复力、加速度的方向和大小","why":"回复力指向平衡位置，与位移反向，大小与位移成正比，故最高点回复力最大且向下，加速度同向向下","do":"由 F=-kx 和牛顿第二定律，由位移方向反推回复力与加速度方向，由位移最大得加速度最大","expr":"F=-kx,\\quad a=-\\frac{k}{m}x","cues":["回复力指向平衡位置","加速度向下","位移最大加速度最大"],"concepts":["回复力","牛顿第二定律","加速度"]}],"801":[{"title":"电荷量只由磁通变化定","type":"关系建立","judge":"求通过棒的电荷量时，要判断它是否只取决于回路磁通量的变化量，而与加速、减速的运动细节无关","why":"由 q=IΔt=E/R·Δt=ΔΦ/R，磁通变化 ΔΦ=BLx 只与位移 x 有关，因此加速段与减速段位移相等就意味着两段电荷量相等","do":"写出 q=ΔΦ/R=BLx/R，比较加速段与减速段的位移 x 是否相等","expr":"q=\\frac{\\Delta\\Phi}{R}=\\frac{BLx}{R}","cues":["电荷量看磁通量","位移相等电荷相等","跟快慢无关"],"concepts":["法拉第电磁感应定律","电荷量公式","磁通量"]},{"title":"减速段用动量定理","type":"模型选择","judge":"求减速段电荷量时，要判断该用动量定理（安培力冲量）而不是牛顿第二定律逐时刻积分","why":"安培力 F=BIL 随时间变化，但冲量 ∫BILdt=BLq 中 q 正是所求量，动量定理把变力冲量直接与电荷量挂钩","do":"对减速段列 -BLq=0-mv，解出 q","expr":"-BLq=0-mv","cues":["取减速段","安培力冲量","变力用动量定理"],"concepts":["动量定理","安培力","冲量"]},{"title":"匀加速段位移公式","type":"关系建立","judge":"要判断加速段位移能否用平均速度乘时间表示，从而由 x 反求加速时间","why":"棒从静止匀加速到最大速度 v，平均速度为 v/2，故 x=vt/2，与前面 q=BLx/R 联立即可解出 t","do":"由 x=vt/2 与 x=mvR/(B²L²) 联立求加速时间 t","expr":"x=\\frac{1}{2}vt=\\frac{mvR}{B^{2}L^{2}}","cues":["匀加速平均速度","先求位移再求时间"],"concepts":["匀变速直线运动","平均速度"]},{"title":"撤去拉力瞬间速度最大","type":"临界条件","judge":"要判断拉力最大、速度最大的时刻是撤去拉力的瞬间，而不是加速过程中的某一中间时刻","why":"加速阶段安培力随速度增大而增大，为维持匀加速，拉力必须同步增大，故撤去瞬间拉力最大；此后只受安培力做减速，速度在撤去瞬间达到最大 v","do":"在撤去瞬间对棒列牛顿第二定律 F_m-BIL=ma，其中 I=BLv/R、v=at","expr":"F_{m}-\\frac{B^{2}L^{2}v}{R}=ma","cues":["撤去瞬间速度最大","拉力随速度增大","临界在撤去时"],"concepts":["牛顿第二定律","安培力","临界状态"]},{"title":"拉力功与动能比较","type":"结论整理","judge":"要判断加速段拉力做的功是否等于 ½mv²，即是否忽略安培力做的负功","why":"加速段合外力功等于动能变化，拉力功与安培力负功之和才等于 ½mv²，故拉力功必大于 ½mv²","do":"对加速段列动能定理 W_F-W_安=½mv²，比较 W_F 与 ½mv²","expr":"W_{F}-W_{安}=\\frac{1}{2}mv^{2}","cues":["拉力还要克服安培力","功大于动能","别漏安培力做功"],"concepts":["动能定理","安培力做功","能量转化"]}],"802":[{"title":"确定计时起点与位移对应","type":"前提判断","judge":"表中每个 h 是否都从最下端磁铁释放位置量起、每个 t 是否都从释放瞬间计起","why":"自由落体公式 h=½gt² 要求 h 与 t 严格同一起点，否则拟合出的系数不是 g/2","do":"核对图(a)中相邻磁铁间距与表中 h 值是否一一对应，确认 h=0 对应 t=0","expr":"h=\\tfrac12 gt^2","cues":["从释放点量起","最下端磁铁对零","同一计时起点"],"concepts":["自由落体","位移起点","计时起点"]},{"title":"描点连线看曲线形状","type":"图像读取","judge":"h-t 图线是直线还是曲线，能否用直线拟合","why":"只有 h 与 t 成正比才是线性；自由落体 h 随 t 二次增长，图线应向上弯曲","do":"把表中七组数据描到图(b)，用平滑曲线连接，观察斜率是否随 t 增大","expr":"","cues":["点越来越陡","不是直线","向上弯"],"concepts":["h-t 图像","非线性关系"]},{"title":"化曲为直用 t² 拟合","type":"数学处理","judge":"应把 h 对 t 还是对 t² 作线性拟合","why":"h=½gt² 中 h 与 t² 成正比，对 t² 作图才是过原点直线，斜率直接给出 g/2","do":"确认拟合式 h=4.916t² 是 h 关于 t² 的一次式，识别其系数含义","expr":"h=\\tfrac12 g\\,t^2","cues":["换成时间的平方","看斜率","过原点的直线"],"concepts":["化曲为直","线性拟合","斜率"]},{"title":"由斜率系数反求 g","type":"关系建立","judge":"拟合系数 4.916 对应的是 g 还是 g/2","why":"对比 h=½gt² 与 h=4.916t²，系数等于 g/2，漏掉 2 倍关系结果会差一倍","do":"令 ½g=4.916，解出 g 并按 3 位有效数字取舍","expr":"\\tfrac12 g=4.916\\ \\Rightarrow\\ g=9.832\\approx 9.83\\ \\mathrm{m/s^2}","cues":["系数是二分之g","要乘二","别忘除以二"],"concepts":["自由落体加速度","系数比较","有效数字"]}],"803":[{"title":"电阻箱初值取最大","type":"实验操作","judge":"闭合开关前电阻箱应调到最大还是最小","why":"电阻箱在电路中串联限流，起保护电流表的作用，接入阻值越大回路电流越小","do":"比较两种极端阻值下回路电流的大小，选使电流最小的一档","expr":"","cues":["保护电表","限流","先调到最大"],"concepts":["限流保护","欧姆定律"]},{"title":"单刀双掷换路的等效","type":"模型选择","judge":"S1 接 1 与接 2 时回路分别包含哪些电阻","why":"接 1 时只有 R0 与 Rg 串联，接 2 时把热敏电阻串入同一回路，电源电动势不变","do":"分别写出两种接法下回路总电阻与电流的关系式，再联立消去 E","expr":"I_g=\\frac{E}{R_0+R_g},\\quad \\frac{I_g}{2}=\\frac{E}{R_0+R_g+R_T}","cues":["接1只有电阻箱","接2多串一个","电源不变"],"concepts":["串联电路","闭合电路欧姆定律"]},{"title":"半偏法读出热敏阻值","type":"关系建立","judge":"电流减半说明回路总电阻如何变化","why":"电动势不变时电流与总电阻成反比，电流变为一半即总电阻变为两倍","do":"由两式相除得 R0+Rg+RT=2(R0+Rg)，解出 RT","expr":"R_T=R_0+R_g","cues":["电流减半","电阻加倍","多出的就是热敏电阻"],"concepts":["半偏法","比例关系"]},{"title":"由图线反查温度","type":"图像读取","judge":"在 R1-t 图上由已知阻值找对应温度","why":"图线给出阻值与温度的一一对应关系，需按阻值定位再读横坐标","do":"在纵轴取 RT 值作水平线交曲线，再竖直向下读温度并取整","expr":"","cues":["先找纵轴","再对到横轴","取整数"],"concepts":["图像法","阻温特性"]},{"title":"并联分流定干路电流","type":"关系建立","judge":"闭合 S2 后电流表满偏时干路电流是 Ig 的几倍","why":"Rg 与 R 并联，两支路电压相同，电流按电阻反比分配","do":"由 Rg=5R 得分流比为 5:1，干路电流为 6Ig，并算出并联部分等效电阻","expr":"I_\\text{干}=6I_g,\\quad R_\\text{并}=\\frac{R_gR}{R_g+R}","cues":["并联分流","电阻比五比一","干路是六倍"],"concepts":["并联电路","分流原理"]},{"title":"两次满偏消去电源","type":"数学处理","judge":"如何用前后两次满偏条件消去未知电动势 E","why":"两次测量中并联部分电阻相同，只有 R0 与 RT 不同，可作比值消去 E","do":"写出含 R0' 与含 RT 的两个欧姆定律式，相除后解出 RT 关于 k 的表达式","expr":"\\frac{6}{k}I_g=\\frac{E}{R_\\text{并}+R_0'+R_T},\\quad 6I_g=\\frac{E}{R_\\text{并}+R_0'}","cues":["两次满偏","电源相同","两式相除"],"concepts":["等效电源","比例消元"]}],"804":[{"title":"充气对象与守恒式","type":"模型选择","judge":"把充入的气体与容器内原有气体合并为同一研究对象，判断初态总物质的量如何用压强和体积表示","why":"温度不变时，原有气体与充入气体最终共同占据容器容积，总 pV 守恒；若只盯容器内气体，会漏掉充入部分","do":"写出初态 p0V0 与充入气体在 p0 下的体积 V 之和，等于末态 4p0 与容器容积 V0 的乘积","expr":"p_{0}V_{0}+p_{0}V=4p_{0}V_{0}","cues":["把充入的也算进去","初态总物质的量","温度不变用玻意耳"],"concepts":["玻意耳定律","理想气体状态方程"]},{"title":"末态容积不变","type":"前提判断","judge":"判断充气后气体占据的体积是否仍为 V0，即容器容积是否变化","why":"题设明确不计容器容积变化，水未喷出前气体空间就是 V0，这是列方程的前提","do":"确认末态体积取 V0，而不是 V0 加充入气体体积","expr":"V_{末}=V_{0}","cues":["容积不变","还是V0","不计形变"],"concepts":["等容","容器容积"]},{"title":"M、N 状态参量对应","type":"关系建立","judge":"判断状态 M 与状态 N 各自的 p、V 取值，并确认两状态气体质量相同","why":"喷水后气体质量不变，才能对 M、N 两态直接用理想气体状态方程求温度比","do":"由题意取 M 态为 4p0、V0，N 态为 p1、V1，列两态状态方程相除","expr":"\\frac{4p_{0}V_{0}}{T_{M}}=\\frac{p_{1}V_{1}}{T_{N}}","cues":["M是充气后","N是喷水后","质量没变"],"concepts":["理想气体状态方程","状态参量"]},{"title":"p-V 图面积比做功","type":"图像读取","judge":"判断实线 MN 与虚线 MN' 哪条线下面积更大，即哪一过程气体对外做功更多","why":"p-V 图线与横轴所围面积表示气体对外做功，这是比较两过程做功大小的依据","do":"比较两条曲线下方到 V 轴围成的面积，确认实线 MN 位于虚线上方、面积更大","expr":"W_{MN}>W_{MN'}","cues":["看线下面积","实线在上方","对外做功更多"],"concepts":["p-V 图像","气体做功"]},{"title":"同起点比较末温","type":"关系建立","judge":"判断 N 与 N' 两末态温度谁高，需借助同一初态 M 的 pV/T 相同来比较","why":"M 到 N 与 M 到 N' 初态相同，pV/T 相同，末态 pV 乘积大者温度高","do":"比较 p1V1 与 N' 态 pV 乘积，得出 TN 与 TN' 的大小关系","expr":"\\frac{pV}{T}=\\text{常量}\\Rightarrow T_{N}>T_{N'}","cues":["同一起点","比pV乘积","末温谁高"],"concepts":["理想气体状态方程","等 pV/T"]},{"title":"绝热基准判吸放热","type":"临界条件","judge":"以绝热过程 MN' 为基准，判断实线 MN 过程内能减少量与做功量的相对大小，从而定吸热还是放热","why":"绝热过程 Q=0，内能减少等于对外做功；MN 做功更多而末温更高、内能减少更少，差额只能由吸热补足","do":"对 MN' 用 ΔU=W（绝热），对 MN 比较 W 与 ΔU 的大小，由 ΔU=Q+W 反推 Q 的符号","expr":"\\Delta U=Q+W,\\quad Q=\\Delta U-W>0","cues":["拿绝热当参照","做功多内能降得少","必须吸热"],"concepts":["热力学第一定律","绝热过程","内能"]}],"805":[{"title":"直线通过区的受力平衡","type":"模型选择","judge":"粒子在 cdef 区域做直线运动时，是匀速直线还是变速直线，能否用合力为零处理","why":"粒子在 cdef 区域同时受竖直向下的电场力和洛伦兹力，若做直线运动则垂直速度方向的合力必须为零，否则轨迹会弯曲","do":"对 cdef 区域内的粒子受力分析，令电场力与洛伦兹力等大反向，列平衡方程","expr":"qE=qv_0B","cues":["直线就是匀速","电场力和洛伦兹力抵消","先定速度大小"],"concepts":["洛伦兹力","电场力","二力平衡"]},{"title":"由偏转方向定电荷正负","type":"前提判断","judge":"粒子从 b 点斜向上射入后向下偏转，结合电场方向判断粒子带何种电荷","why":"电场竖直向下，粒子向下偏转说明电场力向下，与电场方向相同则为正电荷；电荷正负决定后续洛伦兹力方向及圆周偏转方向","do":"比较粒子轨迹弯曲方向与电场方向，确定电场力方向，进而定电荷正负","expr":"","cues":["往下弯说明力向下","电场向下所以带正电","正负不能搞反"],"concepts":["电场力方向","电荷正负"]},{"title":"进入磁场区的速度方向","type":"几何关系","judge":"粒子经 cd 边中点进入 cdef 区域时速度是否水平，从而确定洛伦兹力方向与平衡是否可能","why":"只有速度水平向右时，竖直方向的洛伦兹力才能与竖直电场力共线平衡；速度方向由类平抛末速度方向决定","do":"分析从 b 到 cd 中点的类平抛运动，判断末速度沿水平方向，确认进入 cdef 时速度水平","expr":"","cues":["末速度水平","从中点水平进入","速度方向要定准"],"concepts":["类平抛运动","速度分解"]},{"title":"逆向类平抛求比荷","type":"关系建立","judge":"把从 b 到 cd 中点的曲线运动逆向看成类平抛，用水平匀速和竖直匀加速两个分运动联立求比荷","why":"电场力提供恒定加速度，初速度斜向上，运动可分解为水平匀速与竖直匀变速；逆向处理后初速度水平，竖直位移为 L/2、水平位移为 L","do":"设运动时间 t，列水平方向 v_0 t=L 与竖直方向 (1/2)at^2=L/2，结合 qE=ma 消去 t 和 a，解出 q/m","expr":"v_0t=L,\\ \\frac12at^2=\\frac L2,\\ qE=ma\\Rightarrow\\frac qm=\\frac{v_0^2}{EL}","cues":["逆向看成平抛","水平走一个边长","竖直走半个边长"],"concepts":["类平抛运动","牛顿第二定律","运动的分解"]},{"title":"磁场中圆周半径","type":"关系建立","judge":"粒子进入圆形磁场区后仅受洛伦兹力，做匀速圆周运动，需由洛伦兹力提供向心力求轨迹半径","why":"圆形区域内只有磁场，洛伦兹力始终垂直速度，是匀速圆周运动的向心力来源","do":"用 qv_0B=mv_0^2/R 求半径，并代入第（1）问的 v_0 与第（2）问的 q/m 化简","expr":"qv_0B=m\\frac{v_0^2}{R}\\Rightarrow R=L","cues":["磁场里转圆","洛伦兹力当向心力","半径先算出来"],"concepts":["洛伦兹力","匀速圆周运动","向心力"]},{"title":"偏转角与圆心角关系","type":"几何关系","judge":"粒子沿半径方向射入圆形磁场又沿半径方向射出，速度偏转角等于轨迹圆心角，需由几何关系把偏转角与磁场圆半径、轨迹半径联系起来","why":"粒子进入和射出圆形区域时速度均沿该点半径方向，两速度方向夹角等于两半径夹角，也等于轨迹圆弧对应的圆心角","do":"画轨迹图，用 tanθ=(√3/3 L)/R 求半偏角 θ，再由 α=2θ 得总偏转角","expr":"\\tan\\theta=\\frac{\\frac{\\sqrt3}{3}L}{R},\\ \\alpha=2\\theta","cues":["沿半径进沿半径出","偏转角等于圆心角","画图找直角三角形"],"concepts":["圆周运动几何关系","速度偏转角","圆心角"]}],"806":[{"title":"圆轨道底端求支持力","type":"模型选择","judge":"在 P 点应把支持力与重力的合力当作向心力，而不是把支持力等于重力","why":"P 点做圆周运动，径向合力提供向心力，支持力大于重力","do":"先由机械能守恒求 P 点速度，再在 P 点沿径向列牛顿第二定律","expr":"m_agR=\\frac12 m_a v_P^2,\\quad N-m_ag=m_a\\frac{v_P^2}{R}","cues":["向心力","支持力减重力","先求速度"],"concepts":["机械能守恒","向心力","牛顿第二定律"]},{"title":"碰前速度用动能定理","type":"关系建立","judge":"a 从释放到 M 的过程中，重力做功与地面摩擦力做功之和等于动能变化，需判断摩擦力做负功的路程是 d 而不是 R","why":"圆轨道光滑不做功，只有水平段 PM 有摩擦，摩擦路程为 d","do":"对 a 从顶端到 M 列动能定理，求出碰前速度 v_M","expr":"m_agR-\\mu m_a g d=\\frac12 m_a v_M^2","cues":["光滑轨道不做功","摩擦只在水平段","动能定理"],"concepts":["动能定理","摩擦力做功"]},{"title":"弹性正碰定 b 的速度","type":"关系建立","judge":"弹性正碰要同时用动量守恒和动能守恒，不能只用一个方程；且需注意碰后 a 可能反弹","why":"弹性正碰两个守恒同时成立，质量不等时碰后速度由两式联立唯一确定","do":"联立动量守恒与机械能守恒，解出碰后 b 的速度","expr":"m_av_M=m_av_a+m_bv_b,\\quad \\frac12m_av_M^2=\\frac12m_av_a^2+\\frac12m_bv_b^2","cues":["弹性碰撞","两个守恒","质量不同"],"concepts":["动量守恒","弹性碰撞"]},{"title":"传送带上先减速后匀速","type":"临界条件","judge":"b 滑上传送带后速度大于传送带速率，摩擦力向左使其减速，需判断减速到与传送带同速后是否随带匀速","why":"传送带逆时针转动，带速向左；b 相对带向右滑时受向左摩擦，同速后无相对滑动趋势则匀速","do":"先算减速到 v0 的时间与位移，再判断剩余长度是否匀速通过","expr":"t_1=\\frac{v_b-v_0}{a},\\quad x=\\frac{v_b+v_0}{2}t_1,\\quad t_2=\\frac{L-x}{v_0}","cues":["先减速","同速后匀速","比较位移"],"concepts":["滑动摩擦力","匀变速直线运动"]},{"title":"冲量后速度方向与大小","type":"前提判断","judge":"冲量作用前 b 正以 v0 向左运动，冲量向右，须用动量定理带方向求冲量后的速度，不能把冲量直接当成新速度","why":"动量是矢量，冲量改变动量，需规定正方向并计入初动量","do":"取向右为正，由动量定理求冲量作用后 b 的速度","expr":"I=m_bv-(-m_bv_0)","cues":["有初速度","冲量改动量","规定正方向"],"concepts":["动量定理","矢量性"]},{"title":"周期内往返与相对路程","type":"数学处理","judge":"每个冲量周期内 b 先向右减速到零再向左加速到带速，需判断一个周期净位移与相对传送带的路程，并判断循环次数与最后不足一周期的一段","why":"摩擦生热取决于相对路程而非位移，且每次冲量后运动重复，需按周期累加再补尾段","do":"算单周期净位移与相对路程，用传送带长度判断完整循环次数，再单独处理剩余段","expr":"\\Delta x=\\frac{v}{2}t_3-\\frac{v_0}{2}t_4,\\quad s=\\frac{v}{2}t_3+v_0t_3+v_0t_4-\\frac{v_0}{2}t_4,\\quad Q=\\mu m_b g\\sum s","cues":["相对路程","循环几次","补最后一段"],"concepts":["相对位移","摩擦生热","周期性运动"]}],"807":[{"title":"区分矢量与标量","type":"前提判断","judge":"要判断每个物理量是既有大小又有方向，还是只有大小","why":"矢量的定义是既有大小又有方向、且相加时遵守平行四边形定则的物理量，标量只有大小；这是本题唯一的判断依据","do":"对质量、速率、动能、动量逐个检查是否具有方向性","expr":"","cues":["看有没有方向","矢量要带方向","标量只有大小"],"concepts":["矢量","标量"]},{"title":"识别动量的方向性","type":"关系建立","judge":"要判断动量是否随速度方向而具有方向","why":"动量定义为质量与速度的乘积，速度是矢量，所以动量方向与速度同向，是矢量","do":"由动量的定义式确认它继承了速度的矢量性","expr":"\\vec{p}=m\\vec{v}","cues":["动量跟速度同向","速度是矢量","动量有方向"],"concepts":["动量","速度"]},{"title":"排除无方向的量","type":"结论整理","judge":"要判断质量、速率、动能是否只由大小决定、没有方向","why":"质量是物体惯性的量度，速率是速度的大小，动能是标量式，三者都不含方向信息，不能作为矢量","do":"把这三个量与动量的方向性对比，排除它们","expr":"E_k=\\frac{1}{2}mv^2","cues":["动能没方向","速率就是大小","质量是标量"],"concepts":["质量","速率","动能"]}],"808":[{"title":"识别同轴转动","type":"模型选择","judge":"要判断球面上 P、Q 两点是否绕同一根轴转动、是否属于同轴转动模型","why":"篮球绕指尖所在轴整体转动，球面上各点都绕这根轴做圆周运动，属于同轴转动；若误判成皮带传动或同缘转动，就会把线速度当成相等","do":"找出转轴位置，确认 P、Q 两点都绕同一根轴转动","expr":"","cues":["同轴转动","绕同一根轴","整体一起转"],"concepts":["同轴转动","角速度"]},{"title":"确定半径大小关系","type":"几何关系","judge":"要判断 P、Q 两点到转轴的垂直距离（圆周运动半径）哪个大","why":"圆周运动的半径是点到转轴的垂直距离，不是到球心的距离；由图可见 P 点离转轴更近","do":"从图中比较 P、Q 到转轴的垂直距离","expr":"r_P<r_Q","cues":["看离轴远近","半径不是到球心","P离轴近"],"concepts":["圆周运动半径","转动轴"]},{"title":"由同轴定角速度相等","type":"关系建立","judge":"要判断同轴转动时 P、Q 的角速度是否相等","why":"同轴转动各点角速度相同，这是同轴转动的本质特征，也是后续比较线速度和向心加速度的前提","do":"由同轴转动直接得出角速度相等","expr":"\\omega_P=\\omega_Q","cues":["角速度一样","同轴同角速度"],"concepts":["角速度","同轴转动"]},{"title":"用角速度比较线速度与加速度","type":"关系建立","judge":"要判断在角速度相同的前提下，线速度和向心加速度随半径如何变化","why":"由 v=ωr、a=ω²r，ω 相同时 v 和 a 都与 r 成正比，半径小的 P 点线速度、向心加速度都小","do":"把 ω 相同代入 v=ωr 和 a=ω²r，比较 P、Q 两点的 v 和 a","expr":"v=\\omega r,\\quad a=\\omega^2 r","cues":["半径大线速度大","向心加速度也看半径","同角速度比半径"],"concepts":["线速度","向心加速度"]}],"809":[{"title":"墨条相对砚台滑动方向","type":"前提判断","judge":"要判断墨条相对砚台是向左还是向右滑动，从而确定砚台对墨条摩擦力的方向","why":"滑动摩擦力方向与相对运动方向相反，必须先确定相对运动方向，不能直接看墨条对地的速度方向","do":"以砚台为参考系，比较墨条速度方向与砚台速度（为零），得出墨条相对砚台向左滑动","expr":"","cues":["相对砚台向左","看相对运动","砚台不动"],"concepts":["相对运动","滑动摩擦力方向"]},{"title":"砚台受墨条摩擦力方向","type":"关系建立","judge":"要判断墨条对砚台的摩擦力方向，需由砚台对墨条的摩擦力反推","why":"墨条对砚台的摩擦力与砚台对墨条的摩擦力是一对作用力与反作用力，方向相反","do":"先由相对滑动方向定出砚台对墨条摩擦力向右，再用牛顿第三定律得墨条对砚台摩擦力向左","expr":"","cues":["牛顿第三定律","方向反过来","作用力反作用力"],"concepts":["牛顿第三定律","摩擦力"]},{"title":"砚台水平方向平衡","type":"模型选择","judge":"要判断桌面对砚台的静摩擦力方向，需把砚台作为静止的平衡对象，只看水平方向受力","why":"砚台始终静止，水平方向合力为零，桌面摩擦力必须与墨条对砚台的摩擦力等大反向","do":"对砚台水平方向列平衡方程，由墨条对砚台摩擦力向左推出桌面对砚台摩擦力向右","expr":"f_{桌}=f_{墨→砚}","cues":["砚台静止","水平合力为零","取砚台为对象"],"concepts":["平衡条件","静摩擦力"]},{"title":"支持力与压力的比较","type":"关系建立","judge":"要判断桌面对砚台的支持力与墨条对砚台的压力的大小关系，需对砚台竖直方向整体受力分析","why":"砚台竖直方向平衡，支持力要同时平衡砚台重力和墨条对砚台的压力，故支持力大于压力","do":"对砚台竖直方向列平衡方程，比较支持力与压力两项","expr":"N=G_{砚}+N_{墨→砚}","cues":["竖直方向平衡","支持力托着两个","压力只是其中一项"],"concepts":["平衡条件","弹力"]}],"810":[{"title":"认清双缝间距由什么决定","type":"模型选择","judge":"要判断这个装置的“双缝间距 d”对应的是哪一段几何尺寸","why":"纸板只割一条窄缝，头发丝沿缝方向固定在缝中央，把一条缝分成两条，所以 d 是头发丝的直径，而不是两条割缝的间距","do":"把头发丝直径认定为双缝间距 d，并明确 d 只由头发丝粗细决定","expr":"","cues":["缝被头发丝分成两条","d是头发丝直径","不是缝宽"],"concepts":["双缝干涉","双缝间距"]},{"title":"选对条纹间距公式","type":"关系建立","judge":"要判断条纹间距由哪几个量决定、各自是正比还是反比","why":"双缝干涉的相邻亮纹间距由波长、缝到屏距离、双缝间距三者的比例关系决定","do":"写出条纹间距与波长、屏距、双缝间距的关系式，标出各量的正反比","expr":"$\\Delta x=\\frac{L}{d}\\lambda$","cues":["间距跟波长成正比","跟屏距成正比","跟缝距成反比"],"concepts":["干涉条纹间距","波长"]},{"title":"分清哪个量真的变了","type":"前提判断","judge":"要判断每个做法实际改变的是 d、λ、L 中的哪一个，还是都不改变","why":"只有进入公式的三个量发生变化才会改变条纹间距；光源到纸板的距离不在公式中","do":"把换粗头发丝对应到 d 变大，把换红色激光对应到 λ 变大，把增大纸板与墙面距离对应到 L 变大，把移动光源对应到三个量都不变","expr":"","cues":["粗头发丝是d变","红光是波长变","光源远近不影响"],"concepts":["双缝间距","波长","屏距"]},{"title":"由公式反推间距变小","type":"结论整理","judge":"要判断哪个量的变化方向能使条纹间距变小","why":"按间距公式，d 增大会使 Δx 减小，而 λ 或 L 增大会使 Δx 增大，光源距离变化则无影响","do":"比较各做法引起的量变方向与公式中的正反比关系，挑出使 Δx 减小的那一个","expr":"$\\Delta x\\propto\\frac{\\lambda L}{d}$","cues":["d变大间距变小","波长变大间距变大","屏距变大间距变大"],"concepts":["正比反比关系","干涉条纹间距"]}],"811":[{"title":"溶液是否导电","type":"前提判断","judge":"该溶液在电路中是否形成导电回路、能否让电容器持续放电或漏电","why":"题干明确说溶液不导电，若误认为溶液导电形成回路，就会以为电容器两端电压会改变，从而走错整条主链","do":"读题干中不导电三字，确认电容器两极板间只有电介质、没有闭合导电通路，电源只起维持电压的作用","expr":"","cues":["溶液不导电","没有回路","电压不变"],"concepts":["电介质","电容器充放电","恒压电源"]},{"title":"介电常数随浓度变化","type":"图像读取","judge":"降低浓度时，图（a）中相对介电常数是增大还是减小","why":"电容的决定式里介电常数是唯一随浓度变化的量，读反了曲线趋势，后面电容、电荷量、电流方向全部反向","do":"在图（a）横轴上找到浓度减小的方向，沿曲线读出对应的相对介电常数变化趋势","expr":"","cues":["看横轴往左","曲线在上升","浓度越低介电常数越大"],"concepts":["相对介电常数","图像斜率"]},{"title":"电容随介电常数变化","type":"关系建立","judge":"介电常数增大时，平行板电容器的电容如何变化","why":"由电容决定式，电容正比于介电常数，这是把浓度变化传递到电学量的桥梁","do":"写出电容决定式，保持正对面积和板间距不变，只看介电常数增大对电容的影响","expr":"C=\\frac{\\varepsilon_r S}{4\\pi k d}","cues":["电容决定式","正比于介电常数","面积间距不变"],"concepts":["平行板电容器","电容决定式"]},{"title":"电压不变求电荷量","type":"模型选择","judge":"电容器与恒压电源相连时，应把电压当作不变量还是把电荷量当作不变量","why":"开关闭合且溶液不导电，极板与电源始终相连，电容器两端电压被电源锁定，不能用电荷量不变去推","do":"认定电压不变，用电荷量与电容的关系式，由电容增大推出极板电荷量增大","expr":"Q=CU","cues":["接电源电压不变","用电压算电荷","电荷量变大"],"concepts":["恒压充电","电荷量"]},{"title":"充电电流方向","type":"结论整理","judge":"极板电荷量增大意味着充电还是放电，据此判断电流在导线中的流向","why":"电荷量增大说明电源向电容器输送电荷，电流方向由电源正极经外电路流向正极板，方向判断错就会误选电流方向项","do":"先定哪块极板接电源正极，再由电荷量增大判断充电，沿外电路从电源正极到该极板确定电流方向","expr":"","cues":["电荷量增大是充电","从正极流出","看极板接哪端"],"concepts":["充电电流方向","电源极性"]}],"812":[{"title":"由直线轨迹定合力方向","type":"前提判断","judge":"初速度沿虚线时轨迹为直线，说明合力与初速度共线还是垂直？","why":"物体做直线运动的条件是合外力与速度共线；若合力与速度不共线则轨迹弯曲","do":"把重力与电场力合成，令合力方向沿虚线，从而确定电场力方向","expr":"\\vec F_{合}=\\vec G+\\vec F_e \\parallel \\text{虚线}","cues":["直线运动合力沿速度","合力与虚线共线"],"concepts":["直线运动条件","力的合成"]},{"title":"定电场力水平方向","type":"模型选择","judge":"重力竖直向下、合力沿斜虚线，则电场力必须指向哪一侧？","why":"合力沿虚线方向分解，竖直分量由重力提供，水平分量只能由电场力提供，且方向由合力偏向决定","do":"作平行四边形，由重力竖直向下与合力沿虚线，反推电场力水平指向","expr":"\\vec F_e=\\vec F_{合}-\\vec G","cues":["电场力只能水平","看合力偏哪边"],"concepts":["平行四边形定则","电场力方向"]},{"title":"垂直虚线时做类平抛","type":"模型选择","judge":"初速度垂直于虚线、合力沿虚线，运动是匀变速曲线运动还是圆周运动？","why":"合力恒定且与初速度垂直，符合类平抛（匀变速曲线）模型，加速度沿虚线方向","do":"把运动分解为沿虚线方向的匀加速和垂直虚线方向的匀速","expr":"a=\\frac{F_{合}}{m}\\ \\text{沿虚线}","cues":["类平抛","合力恒定垂直初速"],"concepts":["类平抛运动","运动的分解"]},{"title":"等高过程重力做功为零","type":"关系建立","judge":"从 O 到等高点，重力做功与电场力做功各为多少？","why":"重力做功只由竖直高度差决定，等高则高度差为零；电场力水平，位移的水平分量决定其做功","do":"比较初末位置的高度与水平位移，判断两力做功正负","expr":"W_G=0,\\quad W_e=qE\\,\\Delta x","cues":["等高重力不做功","看水平位移"],"concepts":["功的计算","重力做功特点"]},{"title":"由做功定动能与电势能","type":"结论整理","judge":"电场力做正功还是负功，动能、电势能如何变化？","why":"动能定理：合外力做功等于动能增量；电场力做正功则电势能减小","do":"由电场力方向与水平位移方向是否一致判断做功正负，再推动能与电势能变化","expr":"\\Delta E_k=W_e>0,\\quad \\Delta E_p=-W_e<0","cues":["电场力做正功","动能增大电势能减小"],"concepts":["动能定理","电势能"]}],"813":[{"title":"振幅与释放点关系","type":"几何关系","judge":"要判断图像中给出的振幅 A 与弹簧原长释放点之间的对应关系，即释放点到平衡位置的距离就是振幅","why":"小球从弹簧原长处由静止释放，该处速度为零，是简谐运动的一个端点，端点与平衡位置的距离即振幅","do":"在 x 轴上标出释放点坐标，读出图（b）中地球与天体两条曲线的振幅分别为 4A 和 2A","expr":"x_0=-A","cues":["释放点就是端点","振幅看最高点","从原长释放"],"concepts":["简谐运动","振幅","平衡位置"]},{"title":"用对称性定重力","type":"关系建立","judge":"要判断能否用简谐运动最高点与最低点关于平衡位置对称来求重力加速度，而不是直接用力平衡","why":"简谐运动关于平衡位置对称，端点处速度为零，回复力大小相等方向相反，据此可把弹簧弹力与重力联系起来","do":"对地球情形列最高点与最低点回复力对称式，对天体情形同样列式，解出 g 与 g'","expr":"k\\cdot 4A-mg=mg,\\quad k\\cdot 2A-mg'=mg'","cues":["用对称性定重力"],"concepts":[]},{"title":"重力加速度之比","type":"数学处理","judge":"要判断两式相除后 g 与 g' 的比值，而不是各自的具体值","why":"密度比只依赖 g/g'，无需知道 k、m、A 的具体数值","do":"将两式联立消去 kA/m，得到 g/g'","expr":"\\frac{g}{g'}=2","cues":["比值就行","不用求具体值","消掉k和m"],"concepts":["重力加速度","简谐运动"]},{"title":"星球表面重力与密度","type":"模型选择","judge":"要判断星球表面重力加速度由万有引力提供，且用密度乘体积表示星球质量","why":"不考虑自转，表面物体所受万有引力等于重力；星球质量可用密度与球体体积表示","do":"对地球和天体分别写表面重力加速度表达式，代入半径关系 R1=nR2","expr":"g=\\frac{4}{3}\\pi G\\rho R","cues":["万有引力等于重力","质量用密度乘体积","半径是n倍"],"concepts":["万有引力定律","密度","星球表面重力"]},{"title":"联立求密度比","type":"结论整理","judge":"要判断密度比中半径比的幂次方向，避免把 n 放反","why":"g 正比于 ρR，故 ρ 正比于 g/R，半径越大密度越小","do":"将 g/g'=2 与 R1/R2=n 代入 ρ1/ρ2=(g/g')·(R2/R1)","expr":"\\frac{\\rho_1}{\\rho_2}=\\frac{g}{g'}\\cdot\\frac{R_2}{R_1}=\\frac{2}{n}","cues":["密度和半径成反比","n在分母","别把n乘上去"],"concepts":["密度比","比例关系"]}],"814":[{"title":"区分强度与频率","type":"前提判断","judge":"增加的是光强还是光的频率，两者对单个光子的影响是否相同","why":"光强指单位时间通过单位面积的光子数，改变强度不改变每个光子的能量 hν，只有改变频率才改变光子能量","do":"把题干的'增加强度'翻译成'光子数变多、单个光子能量不变'，据此判断哪些量会变","expr":"E=h\\nu","cues":["强度不是频率","光子数变多","单个光子能量不变"],"concepts":["光子能量","光强","频率"]},{"title":"逸出功由材料决定","type":"前提判断","judge":"逸出功是否随入射光强度改变","why":"逸出功是金属的固有属性，只由金属种类（表面状况）决定，与入射光无关","do":"确认 W₀ 为常量，不随光强变化，排除'强度改变逸出功'的干扰项","expr":"W_0=\\text{常量}","cues":["逸出功是金属自己的","跟光强无关","材料不变就不变"],"concepts":["逸出功","金属属性"]},{"title":"最大初动能只由频率定","type":"关系建立","judge":"光强增大时最大初动能是否改变","why":"爱因斯坦光电效应方程 Ekm=hν−W₀ 中只含频率和逸出功，不含光强","do":"用光电方程比较光强变化前后的 Ekm，得出其不变","expr":"E_{km}=h\\nu-W_0","cues":["看光电方程","只跟频率有关","最大初动能不变"],"concepts":["爱因斯坦光电效应方程","最大初动能"]},{"title":"饱和光电流随光强增大","type":"关系建立","judge":"光强增大时单位时间逸出的光电子数如何变化","why":"光强增大意味着单位时间入射光子数增多，能激发出的光电子数随之增多，光电流增大","do":"把光强与单位时间光子数、单位时间光电子数联系起来比较","expr":"I\\propto n_{\\text{光子}}\\propto N_{\\text{光电子}}","cues":["光子多了电子也多","光电流变大","单位时间数目增多"],"concepts":["光电流","光子数","光电效应"]}],"815":[{"title":"两棒电动势叠加","type":"模型选择","judge":"判断两棒各自产生的感应电动势在回路中是相互叠加还是相互抵消","why":"两棒沿各自斜面下滑，速度方向不同，用右手定则分别判断各棒中电动势方向，才能确定回路总电动势是两者之和","do":"对 ab、cd 分别用右手定则判断感应电动势方向，比较两电动势在回路中的绕行方向","expr":"E=E_{ab}+E_{cd}","cues":["先判方向","右手定则","两棒都切割"],"concepts":["右手定则","动生电动势","闭合回路"]},{"title":"安培力沿斜面分量","type":"几何关系","judge":"判断安培力方向后，确定它在沿导轨方向的分量是 BILcos30° 而不是 BIL","why":"磁场竖直向上，电流沿棒方向，安培力水平，需投影到斜面方向才能与重力沿斜面分量平衡","do":"画出安培力水平方向，分解到沿斜面与垂直斜面两个方向，取沿斜面分量","expr":"F_{\\parallel}=BIL\\cos30^\\circ","cues":["安培力是水平的","要投影","乘余弦"],"concepts":["安培力","力的分解"]},{"title":"两棒加速度相同","type":"关系建立","judge":"判断两棒加速度是否始终相等，从而速度是否始终相等","why":"对两棒分别列牛顿第二定律，比较两式中重力沿斜面分量与安培力沿斜面分量的比值关系","do":"对 ab 列 2mgsin30°−2BILcos30°=2ma_ab，对 cd 列 mgsin30°−BILcos30°=ma_cd，比较两式右边","expr":"a_{ab}=a_{cd}","cues":["列两个牛二","比一下系数","加速度一样"],"concepts":["牛顿第二定律","安培力"]},{"title":"匀速时电流稳定","type":"临界条件","judge":"判断何时电流达到稳定值，即安培力沿斜面分量与重力沿斜面分量平衡","why":"速度增大使电流增大、安培力增大，加速度减小到零时速度与电流不再变化","do":"令 a=0，对 ab 列平衡方程求稳定电流","expr":"2mg\\sin30^\\circ=2BIL\\cos30^\\circ","cues":["加速度为零","受力平衡","电流不再变"],"concepts":["平衡条件","收尾速度"]},{"title":"电动势不等因磁场不同","type":"结论整理","judge":"判断两棒速度相等时产生的感应电动势是否相等","why":"两棒速度大小相等、长度相同，但所在处磁感应强度分别为 2B 和 B，电动势与 B 成正比","do":"比较 E_ab=2BLv 与 E_cd=BLv 的大小","expr":"E_{ab}=2BLv,\\ E_{cd}=BLv","cues":["速度一样","磁场不一样","电动势不同"],"concepts":["动生电动势","磁感应强度"]}],"816":[{"title":"由折点定位滑上时刻","type":"图像读取","judge":"v-t 图线斜率突变处对应木板的加速度突变，要判断物块何时滑上木板","why":"物块滑上木板后，木板额外受到物块对它的摩擦力，合外力改变，加速度必然突变，因此斜率折点就是滑上时刻","do":"观察图像在 0 到 4t₀ 间的斜率变化，找出斜率由正变负的折点，读出对应时刻","expr":"","cues":["看斜率突变","折点就是滑上","加速度变了"],"concepts":["v-t 图像斜率","加速度"]},{"title":"读折点速度定初速","type":"图像读取","judge":"要从图上读出物块滑上瞬间木板的速度，并据此写出物块滑上时的初速度","why":"题设物块速度与木板等大反向，物块初速由木板在该时刻的速度直接决定","do":"读出折点时刻木板速度，取相反数作为物块初速度，再读共速时刻的速度","expr":"v_1=-v_0,\\quad v_共=\\tfrac12\\mu g t_0","cues":["等大反向","读折点速度","共速看末点"],"concepts":["速度图像读数","相对速度"]},{"title":"用共速过程求物块摩擦因数","type":"关系建立","judge":"要判断物块在木板上滑动时加速度由哪个力提供，从而由速度变化求动摩擦因数","why":"物块只受木板给它的滑动摩擦力，加速度为 μ₀g，方向与物块运动方向相反","do":"对物块列速度公式，从滑上初速到共速速度，时间间隔为 t₀，解出 μ₀ 与 μ 的关系","expr":"v_共-v_1=\\mu_0 g t_0","cues":["只受一个摩擦力","加速度是μ₀g","速度变化定摩擦"],"concepts":["牛顿第二定律","滑动摩擦力"]},{"title":"分段列木板方程求质量比","type":"模型选择","judge":"要判断物块滑上前后木板受哪些力，并分别对两个阶段列牛顿第二定律","why":"滑上前后木板所受地面摩擦力和物块摩擦力不同，必须分段，且地面摩擦力与总重 (M+m)g 有关","do":"由图像斜率求滑上前后两段加速度，分别对木板列方程，联立解出 F 与 m/M","expr":"F-\\mu Mg=Ma,\\quad F-\\mu(M+m)g-\\mu_0 mg=Ma'","cues":["分段列方程","地面摩擦按总重","先求两段加速度"],"concepts":["牛顿第二定律","隔离法","滑动摩擦力"]},{"title":"判断共速后能否一起运动","type":"临界条件","judge":"要判断共速后物块与木板是相对滑动还是一起运动，需比较所需静摩擦与最大静摩擦","why":"共速后若整体合外力为零则一起匀速；若所需静摩擦超过最大静摩擦则继续相对滑动","do":"把两者当整体求合外力，检验是否为零，再验证维持共同运动所需静摩擦力是否在最大静摩擦范围内","expr":"F-\\mu(M+m)g=0","cues":["先假设一起动","看整体合外力","验证静摩擦够不够"],"concepts":["整体法","静摩擦力","平衡状态"]}],"817":[{"title":"保护电路选初始位置","type":"实验操作","judge":"闭合开关前金属夹应放在使接入电阻丝阻值最大的一端还是最小的一端","why":"闭合开关瞬间若外电阻过小，电流过大可能损坏电池和电压表，故应使接入电阻最大","do":"比较金属夹在 A、B 两端时接入电路的电阻丝长度，选长度最长（阻值最大）的一端","expr":"","cues":["放阻值最大处","保护电表","看接入长度"],"concepts":["闭合电路欧姆定律","滑动变阻器限流接法"]},{"title":"选反比量作纵轴","type":"模型选择","judge":"U 与 L 的关系是非线性的，应把哪个量作纵轴才能得到直线","why":"由闭合电路欧姆定律与电阻定律联立得 1/U 与 1/L 成线性关系，只有取倒数坐标才能化曲为直","do":"对每组 (U,L) 取倒数，作 1/U–1/L 图线，而不是作 U–L 图线","expr":"\\frac{1}{U}=\\frac{1}{E}+\\frac{Sr}{E\\rho}\\cdot\\frac{1}{L}","cues":["取倒数","化曲为直","作反比图"],"concepts":["闭合电路欧姆定律","电阻定律","线性化"]},{"title":"用截距读电动势","type":"图像读取","judge":"纵轴截距对应关系式中哪一项，能否直接给出电动势","why":"1/L→0 时 1/U→1/E，截距只含 E，与内阻和电阻丝参数无关","do":"令 1/L=0，读出纵轴截距 b，与 1/E 对应","expr":"b=\\frac{1}{E}","cues":["看截距","截距是电动势倒数","外推到头"],"concepts":["图像截距","电动势"]},{"title":"斜率含内阻与电阻丝参数","type":"关系建立","judge":"图线斜率由哪些物理量组成，两次实验斜率差异来自哪里","why":"斜率 Sr/(Eρ) 中含内阻 r 与电阻丝 S、ρ，接入 R0 后等效内阻变为 r+R0，斜率随之改变","do":"分别写出图线 Ⅰ、Ⅱ 的斜率表达式，再取比值消去 S、ρ、E","expr":"k_1=\\frac{Sr}{E\\rho},\\quad k_2=\\frac{S(r+R_0)}{E\\rho}","cues":["斜率比","等效内阻变大","消去电阻丝参数"],"concepts":["图像斜率","等效内阻"]},{"title":"比值消参求内阻","type":"数学处理","judge":"如何用斜率比 n 把未知的 S、ρ、E 全部消去只剩 r 与 R0","why":"两斜率之比只保留 (r+R0)/r，其余参数约去，才能由 n 解出 r","do":"将 k2/k1=n 代入两斜率表达式，解出 r","expr":"\\frac{k_2}{k_1}=\\frac{r+R_0}{r}=n\\ \\Rightarrow\\ r=\\frac{R_0}{n-1}","cues":["两式相除","只剩内阻","解出r"],"concepts":["比值消元","内阻测量"]}],"818":[{"title":"刻度尺估读规则","type":"实验操作","judge":"读数时是否要估读到分度值的下一位，以及估读值取多少","why":"刻度尺分度值为 0.1 cm，测量结果必须保留到 0.01 cm 这一位，末位是估读数字","do":"先确认分度值 0.1 cm，再读主刻度并估读末位，记录到 0.01 cm","expr":"","cues":["估读到下一位","分度值是一毫米","末位要估读"],"concepts":["刻度尺读数","估读","有效数字"]},{"title":"计数次数与周期换算","type":"关系建立","judge":"从第 0 次到第 20 次计数，积木实际摆动了多少个完整周期","why":"积木左端两次与 O 点等高（同侧）之间为半个周期，每计数一次只经历半个周期","do":"把计数间隔数除以 2 得到周期数","expr":"n=\\frac{20}{2}=10","cues":["每次是半个周期","同侧经过才算一个周期","20次除以2"],"concepts":["简谐运动周期","计数法测周期"]},{"title":"双对数图化幂函数","type":"数学处理","judge":"由 lnT-lnD 直线的斜率判断 T 与 D 的幂次关系","why":"若 T=kD^n，则 lnT=lnk+n lnD，双对数图斜率就是指数 n","do":"在图上取两点求斜率，读出 n 的值再对应选项","expr":"n=\\frac{\\Delta\\ln T}{\\Delta\\ln D}","cues":["取两点求斜率","斜率就是指数","双对数变直线"],"concepts":["双对数坐标","幂函数线性化","图像斜率"]},{"title":"斜率取点与符号","type":"图像读取","judge":"取哪两个点算斜率，以及斜率是正还是负","why":"图中 lnT 随 lnD 增大而增大，斜率为正；取点应落在直线上的格点附近以减小读数误差","do":"选直线上相距较远的两点（如 lnD=1.80 与 2.80 处）读纵坐标，作差求斜率","expr":"n=\\frac{-0.5-(-1.0)}{2.80-1.80}=0.5","cues":["取相距远的点","斜率为正","别把符号弄反"],"concepts":["图像斜率","读数误差"]},{"title":"精度改进的针对性","type":"误差分析","judge":"所提措施是否真正减小本实验的主要误差来源（D 的测量、计时起止、摆幅与桌面摩擦）","why":"本实验误差主要来自外径读数、周期计时的反应时间以及摆动是否满足小幅度、无摩擦条件","do":"针对某一误差源提出可操作措施，如换游标卡尺测 D、累计多次全振动计时、减小摆幅、换更光滑桌面","expr":"","cues":["用游标卡尺量外径","多测几十次再算周期","摆幅要小一点"],"concepts":["实验误差","减小偶然误差","小角近似"]}],"819":[{"title":"峰值转有效值","type":"前提判断","judge":"功率计算该用交流电的峰值还是有效值","why":"电阻发热功率由有效值决定，题给的是峰值，必须换算","do":"对正弦交流电取有效值 U1=Um/√2 再进入功率计算","expr":"U_1=\\frac{U_m}{\\sqrt{2}}","cues":["用有效值","峰值除以根号二","功率看有效值"],"concepts":["有效值","正弦交流电"]},{"title":"副线圈电压由匝数比定","type":"关系建立","judge":"用匝数比把原线圈电压传到副线圈时，比值方向不能弄反","why":"理想变压器电压比等于匝数比，n1:n2=5:1 是降压","do":"写出 U1/U2=n1/n2，解出 U2 用 U1 和匝数比表示","expr":"\\frac{U_1}{U_2}=\\frac{n_1}{n_2},\\quad U_2=\\frac{n_2}{n_1}U_1","cues":["降压变压器","副线圈电压小","匝数比别倒"],"concepts":["理想变压器","匝数比"]},{"title":"输出功率即电阻热功率","type":"模型选择","judge":"变压器输出功率该用哪个量算，是否要另设副线圈电流","why":"理想变压器无损耗，输出功率全部消耗在唯一负载 R 上，直接用 U2²/R 最简","do":"对副线圈回路用 P=U2²/R，不引入电流未知量","expr":"P=\\frac{U_2^{2}}{R}","cues":["理想变压器无损耗","功率全给电阻","不用再求电流"],"concepts":["理想变压器","电功率"]},{"title":"等容升温定末温","type":"关系建立","judge":"压强翻倍对应温度怎样变化，体积是否改变","why":"容器封闭且容积不变，气体做等容变化，由查理定律 p/T 为常量","do":"列 p0/T0=2p0/T2，得 T2=2T0，进而 ΔT=T0","expr":"\\frac{p_0}{T_0}=\\frac{2p_0}{T_2}\\Rightarrow T_2=2T_0","cues":["体积不变","等容变化","压强翻倍温度也翻倍"],"concepts":["查理定律","等容过程"]},{"title":"绝热等容的能量转化","type":"模型选择","judge":"电热丝放热与气体内能增加之间如何建立等式","why":"绝热容器无热交换、体积不变不做功，热力学第一定律退化为内能增量等于吸收热量","do":"由 ΔU=Q、W=0，把 Q=Pt 与 Q=CΔT 联立","expr":"\\Delta U=Q=Pt=C\\Delta T","cues":["绝热不散热","等容不做功","电能全变内能"],"concepts":["热力学第一定律","内能","绝热过程"]}],"820":[{"title":"平抛反推A的初速","type":"模型选择","judge":"A 脱离弹簧后到落地这段运动该用哪种运动模型处理","why":"A 从桌面左端沿水平方向飞出，只受重力，竖直方向自由落体、水平方向匀速，两方向时间相同","do":"由竖直高度求飞行时间，再用水平射程除以该时间得水平速度","expr":"h=\\frac12 gt^2,\\ x_A=v_A t","cues":["平抛运动","竖直自由落体","水平匀速","时间相同"],"concepts":["平抛运动","运动的分解"]},{"title":"判断动量是否守恒","type":"前提判断","judge":"弹簧弹开 A、B 的过程中能否对 A、B 用动量守恒","why":"A、B 质量相等，弹簧弹力等大反向，两物块所受摩擦力也等大反向，系统合外力为零，故动量守恒","do":"比较两物块所受弹力与摩擦力的大小方向，确认系统合外力为零后列动量守恒式","expr":"m_A v_A=m_B v_B","cues":["取整体","合外力为零","弹力等大反向","摩擦力也抵消"],"concepts":["动量守恒","系统外力"]},{"title":"B 滑行段用动能定理","type":"关系建立","judge":"求动摩擦因数应取 B 脱离弹簧后的滑行阶段还是弹簧作用阶段","why":"B 脱离弹簧后只受滑动摩擦力做负功，初速为 v_B、末速为零，位移 x_B 已知，可直接解出 μ","do":"对 B 的滑行段列动能定理，摩擦力做功等于动能变化","expr":"-\\mu m_B g x_B=0-\\frac12 m_B v_B^2","cues":["脱离弹簧后","只有摩擦力做功","末速度为零","用滑行距离"],"concepts":["动能定理","滑动摩擦力"]},{"title":"弹簧势能的分配去向","type":"关系建立","judge":"弹簧释放的弹性势能转化成了哪些能量，是否只算两物块动能","why":"弹簧从压缩到恢复原长的过程中，A、B 已在桌面上滑动，克服摩擦力做功也消耗弹性势能，漏掉就偏小","do":"把弹性势能写成两物块动能与两物块各自克服摩擦力做功之和，再用位移之和等于压缩量消去分配细节","expr":"\\Delta E_p=\\frac12 m_Av_A^2+\\frac12 m_Bv_B^2+\\mu m_A g\\Delta x_A+\\mu m_B g\\Delta x_B,\\ \\Delta x_A+\\Delta x_B=\\Delta x","cues":["还要算摩擦生热","位移之和是压缩量","别只算动能","两段位移未知但和已知"],"concepts":["能量守恒","弹性势能","克服摩擦力做功"]}],"821":[{"title":"乙在Ⅰ区偏转的几何关系","type":"几何关系","judge":"乙在Ⅰ区做圆周运动的半径与区域宽度 L、偏转角 30° 之间满足什么几何关系","why":"粒子垂直边界射入匀强磁场后做匀速圆周运动，轨迹圆弧的弦长与区域宽度对应，偏转角决定圆心角","do":"画出乙在Ⅰ区的圆弧轨迹，找出圆心，用偏转角 30° 对应的弦长等于 L 列几何式","expr":"\\sin 30^\\circ = \\frac{L}{r_1}","cues":["画轨迹找圆心","偏转角就是圆心角","弦长等于宽度"],"concepts":["洛伦兹力","圆周运动","几何关系"]},{"title":"两粒子磁场中时间对称性","type":"关系建立","judge":"甲、乙穿过两个反向磁场区所用总时间是否相同，能否用乙的偏转角算出共同时间","why":"两区磁感应强度等大反向，粒子轨迹呈对称的 S 形，进出方向平行于 x 轴，两段圆弧圆心角相同","do":"由乙的偏转角 30° 得每段圆弧圆心角，用周期公式求单段圆弧时间再乘 2","expr":"t_1 = 2\\times\\frac{30^\\circ}{360^\\circ}\\cdot\\frac{2\\pi m}{qB}","cues":["两区磁场反向轨迹对称","进出方向平行","时间用周期算"],"concepts":["磁场偏转","周期","对称性"]},{"title":"甲在Ⅲ区的运动模型","type":"模型选择","judge":"甲进入Ⅲ区时的初速度方向与电场方向的关系，决定甲在Ⅲ区做匀变速直线运动还是类平抛","why":"甲出磁场后速度沿 +x 方向，Ⅲ区电场也沿 +x 方向，二者共线，故为匀加速直线运动","do":"确认甲出磁场速度沿 x 轴，用匀变速直线运动位移公式求Ⅲ区宽度","expr":"d = \\frac{3}{2}v_0 t_1 + \\frac{1}{2}a t_1^2,\\quad a=\\frac{qE_0}{m}","cues":["速度沿x轴","电场也沿x轴","共线所以直线加速"],"concepts":["匀变速直线运动","电场力","牛顿第二定律"]},{"title":"甲匀速直线运动定 k","type":"前提判断","judge":"甲在Ⅳ区始终匀速直线运动，说明Ⅳ区电场对甲的作用有何特点，由此能否确定 k 与 ω 的关系","why":"匀速直线运动要求合力为零，甲只受电场力，故甲所在位置的电场强度必须为零","do":"令甲所在位置 x=3v0 t 处 E=0，代入 E=ωt-kx 解出 k","expr":"\\omega t = k\\cdot 3v_0 t \\Rightarrow k=\\frac{\\omega}{3v_0}","cues":["匀速说明合力为零","甲处场强为零","代入甲的位置"],"concepts":["匀速直线运动","电场强度","平衡条件"]},{"title":"乙的受力与位置联立消时间","type":"数学处理","judge":"乙在Ⅳ区受电场力 F 与其位置 x2、时间的关系中，如何消去时间得到 F 与间距 Δx 的关系","why":"甲、乙在Ⅳ区的时间起点不同，需用同一时刻 t 表示两者位置，再作差消去时间","do":"写出乙的场强表达式，用甲的位置 x1=3v0 t 与乙的位置 x2 作差得 Δx，消去 t","expr":"\\Delta x = x_1-x_2 = \\frac{3v_0 F}{q\\omega}","cues":["同一时刻作差","消去时间","间距等于位置差"],"concepts":["电场力","位置坐标","消元"]}],"822":[{"title":"减速阶段受力判断","type":"前提判断","judge":"减速下降时加速度方向朝哪、合外力是否为零","why":"速度向下而速度在减小，加速度必然向上，由牛顿第二定律合外力不为零且方向向上","do":"比较速度方向与加速度方向，判断合外力是否为零","expr":"","cues":["减速就有加速度","合力向上","合力不为零"],"concepts":["加速度","牛顿第二定律","合外力"]},{"title":"悬停阶段平衡判断","type":"模型选择","judge":"悬停时速度为零是否等于合力为零、是否只受重力","why":"悬停是静止平衡状态，合力为零，但探测器仍受重力与发动机升力，二者平衡","do":"对悬停状态作受力分析，列出重力与升力的平衡关系","expr":"F_{升}=mg","cues":["悬停是平衡","速度为零合力为零","还受升力"],"concepts":["平衡状态","受力分析","合力"]},{"title":"自由下落机械能判断","type":"模型选择","judge":"自由下落阶段除重力外是否还有其他力做功","why":"自由下落指只受重力作用，没有其他力做功，故机械能守恒","do":"确认自由下落阶段只受重力，判断机械能是否守恒","expr":"E_k+E_p=\\text{常量}","cues":["自由下落只受重力","没有其他力做功","机械能守恒"],"concepts":["自由落体","机械能守恒","重力做功"]},{"title":"月球重力加速度判断","type":"结论整理","judge":"月球表面重力加速度是否等于地球的 9.8","why":"月球质量与半径均小于地球，其表面重力加速度约为地球的六分之一，不是 9.8","do":"比较月球与地球表面重力加速度的大小关系","expr":"g_{月}=\\frac{GM_{月}}{R_{月}^2}\\approx\\frac{1}{6}g_{地}","cues":["月球重力小","约为地球六分之一","不是9.8"],"concepts":["重力加速度","万有引力"]}],"823":[{"title":"温度不变定过程","type":"前提判断","judge":"气囊上浮过程中气体温度是否保持不变、质量是否一定","why":"题干明确'气囊密闭''温度不变'，只有等温且质量不变才能用玻意耳定律判断压强随体积的变化","do":"确认气囊密闭不漏气、温度恒定，把过程归为一定质量理想气体的等温膨胀","expr":"T=\\text{const},\\ m=\\text{const}","cues":["温度不变","密闭气囊","质量一定"],"concepts":["理想气体","等温过程","玻意耳定律"]},{"title":"体积增大判压强","type":"关系建立","judge":"体积增大时压强如何变化","why":"一定质量理想气体等温下 pV 为常量，V 增大则 p 必减小","do":"由玻意耳定律比较初末状态的 p 与 V，得出压强变小","expr":"p_1V_1=p_2V_2","cues":["体积变大","压强变小","等温膨胀"],"concepts":["玻意耳定律","压强"]},{"title":"气体对外做功","type":"关系建立","judge":"气体体积增大时对外做正功还是负功","why":"体积膨胀时气体对外界做功，按热力学第一定律符号约定 W<0","do":"由体积增大判断气体对外做功，确定 W 的符号","expr":"W<0\\ (\\text{气体对外做功})","cues":["体积膨胀","对外做功","功取负"],"concepts":["做功","热力学第一定律"]},{"title":"内能不变推吸热","type":"结论整理","judge":"温度不变时内能是否变化，结合做功判断吸放热","why":"理想气体温度不变则内能不变，ΔU=0，而 W<0，由 ΔU=Q+W 得 Q>0，必须吸热","do":"先由等温得 ΔU=0，再代入 ΔU=Q+W 解出 Q 的符号，判断吸热","expr":"\\Delta U=0,\\ \\Delta U=Q+W\\Rightarrow Q=-W>0","cues":["内能不变","从外界吸热","放热不对"],"concepts":["内能","热力学第一定律","吸热"]}],"824":[{"title":"两段阻力做功的符号","type":"前提判断","judge":"两段恒力阻力对针鞘做的功是正还是负，动能定理中如何取号","why":"阻力方向与位移方向相反，两段阻力都做负功，动能减少；若把阻力功写成正，动能定理符号就反了","do":"对针鞘从弹出到停止的全程列动能定理，把 F1、F2 的功都取负号","expr":"-F_{1}d_{1}-F_{2}d_{2}=0-\\frac{1}{2}mv^{2}","cues":["阻力做负功","功取负号","动能减少"],"concepts":["动能定理","功的正负"]},{"title":"全程还是分段列式","type":"模型选择","judge":"求初速度时该对全程列动能定理还是只对某一段列","why":"初速度对应弹出瞬间，末速度为零对应停止，只有全程的初末动能都已知，分段列会多出中间速度这个未知量","do":"把 d1 与 d2 两段合并为一个过程，初动能取 ½mv²、末动能取零","expr":"-F_{1}d_{1}-F_{2}d_{2}=0-\\frac{1}{2}mv^{2}","cues":["取全程","初末动能已知","避开中间速度"],"concepts":["动能定理","过程选择"]},{"title":"进入目标组织时的动能","type":"关系建立","judge":"针鞘到达目标组织表面时的动能由哪段阻力做功决定","why":"该动能是前一段 d1 中阻力消耗后剩下的部分，只由 F1、d1 与初动能决定，不能直接用 F2d2 表示","do":"对 d1 段单独列动能定理，写出到达界面时的动能表达式","expr":"E_{k}=\\frac{1}{2}mv^{2}-F_{1}d_{1}","cues":["界面处动能","前一段剩下","不能只看第二段"],"concepts":["动能定理","分段分析"]},{"title":"第二段动能与动量变化","type":"关系建立","judge":"d2 段中动能减少量与动量变化量分别由什么力做功和什么关系给出","why":"d2 段末速度为零，动能全部被 F2 消耗，动量变化需由动能与动量的关系换算，而不是直接等于力乘距离","do":"对 d2 段写动能定理得 Ek=F2d2，再用 Δp=√(2mEk) 换算动量变化","expr":"F_{2}d_{2}=E_{k},\\quad \\Delta p=\\sqrt{2mE_{k}}","cues":["末速为零","动能全消耗","动量用动能换"],"concepts":["动能定理","动量与动能关系"]}],"825":[{"title":"反射光与折射光垂直","type":"关系建立","judge":"反射光线与折射光线的夹角为 90° 时，入射角与折射角满足什么关系","why":"反射角等于入射角，两光线分居法线两侧，夹角 90° 意味着两角互余","do":"在光路图上标出入射角 θ₁ 与折射角 θ₂，由垂直条件写出两角之和","expr":"\\theta_1+\\theta_2=90^\\circ","cues":["两角互余","加起来九十度","反射角等于入射角"],"concepts":["反射定律","折射角","互余"]},{"title":"折射定律化为正切","type":"数学处理","judge":"把折射定律中的正弦之比换成可直接由几何长度求出的量","why":"θ₁ 与 θ₂ 互余时 sinθ₁=cosθ₂，正弦之比可化为正切","do":"将折射定律中的 sinθ₁ 用 cosθ₂ 替换，化简为正切形式","expr":"n=\\frac{\\sin\\theta_1}{\\sin\\theta_2}=\\frac{\\cos\\theta_2}{\\sin\\theta_2}=\\cot\\theta_2","cues":["正弦比变正切","用余角换掉","化成正切好算"],"concepts":["折射定律","三角函数关系"]},{"title":"用半宽与 h 表示正切","type":"几何关系","judge":"折射角的正切对应光路图中哪两条边之比，水平边取半宽还是全宽","why":"光从液体表面中心入射，反射光打到竖直器壁，水平距离是容器宽度的一半，竖直距离是 h","do":"在直角三角形中找出对边与邻边，写出 tanθ₂ 的表达式","expr":"\\tan\\theta_2=\\frac{8\\,\\mathrm{cm}}{h}","cues":["取半宽八厘米","水平是宽度一半","竖直是h"],"concepts":["光路几何","直角三角形"]},{"title":"合成 n 与 h 的关系式","type":"关系建立","judge":"把折射率 n 与可测量的 h 直接联系成一个式子","why":"正切与余切互为倒数，几何正切代入后 n 只含 h","do":"将几何正切取倒数代入折射率表达式","expr":"n=\\frac{h}{8\\,\\mathrm{cm}}","cues":["n和h成正比","八除以h的倒数","直接代进去"],"concepts":["折射率","函数关系"]},{"title":"由关系式反解判断","type":"结论整理","judge":"给定 h 求 n 或给定 n 求 h 时，是否用同一关系式反解并核对量纲与数量级","why":"方案的可测性要求 h 与 n 一一对应，反解结果须与容器尺寸 16 cm 相容","do":"把各选项的 h 或 n 代入关系式，算出对应量并与题设尺寸比较","expr":"h=8n\\,\\mathrm{cm}","cues":["代进去算","反解h","看是否超过容器尺寸"],"concepts":["折射率","方案可行性"]}],"826":[{"title":"负电荷电势能符号","type":"前提判断","judge":"带负电的试探电荷在某点的电势能应取 qφ 还是 −qφ（即电势越高电势能越大还是越小）","why":"电势能定义 E_p=qφ，q=−e 为负，故 φ 越高电势能越低，符号搞反会导致能量守恒方程整体错位","do":"写出 E_p=−eφ，把 x₂ 处 φ=1 V 代入得 E_p=−1 eV","expr":"E_p=q\\varphi=-e\\varphi","cues":["负电荷反着来","电势高电势能低"],"concepts":["电势能","电势"]},{"title":"总能量守恒定值","type":"关系建立","judge":"能否用动能加电势能之和为常量来确定电荷能到达的区域边界","why":"电荷仅受静电力，电场力做功等于电势能减少量，故 E_k+E_p 守恒，这是判断运动范围的唯一依据","do":"由 x₂ 处 E_k=1.5 eV、E_p=−1 eV 求总能量，再令 E_k=0 求转折点对应的电势","expr":"E_k+E_p=E_k'+q\\varphi'=\\text{const}","cues":["动能加电势能不变","先算总能量"],"concepts":["能量守恒","电势能"]},{"title":"场强方向由斜率定","type":"图像读取","judge":"由 φ–x 图线的斜率正负判断各区间电场方向，进而判断负电荷受力方向","why":"E=−dφ/dx，斜率正负决定场强沿 x 正方向还是负方向，负电荷受力与场强反向，受力方向决定加速还是减速","do":"比较 x₂~x₃ 段与 x₃ 右侧段 φ–x 斜率的正负，得出负电荷在两段的受力方向","expr":"E_x=-\\dfrac{\\Delta\\varphi}{\\Delta x},\\quad F=qE_x","cues":["斜率就是场强","负电荷受力反向"],"concepts":["电势梯度","电场力方向"]},{"title":"转折点与往复范围","type":"临界条件","judge":"速度减为零的位置对应哪个电势值，从而确定电荷运动的两个端点","why":"速度为零处动能为零，由能量守恒该处电势能等于总能量，解出的 φ 值对应图上两个位置，即往复运动的边界","do":"令 E_k=0 解出转折电势，在图上找出该电势对应的左右两个 x 位置，判断能否到达 x₀、x₁","expr":"0+q\\varphi_{\\text{转}}=E_{\\text{总}}","cues":["速度为零是端点","看能不能到左边"],"concepts":["临界条件","能量守恒"]}],"827":[{"title":"三体同角速度的动力学条件","type":"模型选择","judge":"判断三个天体做相对位置不变的圆周运动时，能否各自以 O 为圆心、用同一角速度列向心力方程","why":"相对位置不变意味着三者绕 O 同步转动，角速度相同，每个天体的向心力由其余天体的万有引力合力提供","do":"对 a、b、c 分别取 O 为圆心，写出合力指向 O 的向心力方程，并共用同一个 ω","expr":"F_{\\text{合}}=m_i\\omega^2 R_i","cues":["绕同一点转","角速度一样","相对位置不变"],"concepts":["万有引力","匀速圆周运动","向心力"]},{"title":"忽略 m 对 a、b 的影响","type":"近似条件","judge":"判断求 a、b 的角速度时能否只算 a、b 之间的引力，把 c 对 a 的引力略去","why":"题设 m≪M，c 对 a、b 的引力远小于 a、b 之间的引力，只保留主导项才能得到简洁的 ω","do":"对 a 只列 a、b 间万有引力等于向心力的方程，解出 ω","expr":"G\\frac{M\\cdot M}{(2r)^2}=M\\omega^2 r","cues":["m远小于M","c的引力可忽略","先求角速度"],"concepts":["近似条件","万有引力定律"]},{"title":"由 c 的受力定几何位置","type":"几何关系","judge":"判断 c 必须位于中垂线上哪个位置，即确定 c 与 a、b 连线和中垂线的夹角","why":"c 受到的 a、b 两引力大小相等、关于中垂线对称，其合力沿中垂线指向 O，只有合力方向与向心力方向一致时才能做圆周运动","do":"设 c 与 a 连线跟中垂线夹角为 α，写出两引力沿中垂线的合力，令其等于 mω²R_c，代入已求出的 ω 解 α","expr":"2G\\frac{Mm}{(r/\\sin\\alpha)^2}\\cos\\alpha=m\\omega^2\\frac{r}{\\tan\\alpha}","cues":["合力指向O","对称位置","设个夹角"],"concepts":["力的合成","几何关系","向心力"]},{"title":"由 α 换算轨道半径","type":"数学处理","judge":"判断 c 的轨道半径与 a 的轨道半径 r 之间的比例关系","why":"c 到 O 的距离由 α 和 a 到 O 的距离 r 通过直角三角形关系确定，半径之比直接决定线速度、加速度之比","do":"由 α 求出 R_c=r/tanα，再与 a 的半径 r 相比","expr":"R_c=\\frac{r}{\\tan\\alpha}","cues":["半径差几倍","用直角三角形","比一下r"],"concepts":["轨道半径","三角函数关系"]},{"title":"同 ω 下比较 v 与 a","type":"关系建立","judge":"判断角速度相同时，线速度、向心加速度与轨道半径是成正比还是反比","why":"v=ωR、a=ω²R，ω 相同则 v、a 都随 R 线性增大，倍数关系与半径倍数一致","do":"用 v=ωR、a=ω²R 分别比较 c 与 a、b 的线速度和向心加速度","expr":"v=\\omega R,\\quad a=\\omega^2 R","cues":["角速度相同","正比于半径","倍数一样"],"concepts":["线速度","向心加速度"]},{"title":"路程用整圈周长","type":"结论整理","judge":"判断一个周期内运动路程该用轨道周长还是别的量","why":"匀速圆周运动一个周期恰好走一圈，路程等于 2πR_c","do":"用已求出的 R_c 写出路程表达式","expr":"s=2\\pi R_c","cues":["一圈就是周长","一个周期","算周长"],"concepts":["周期","路程"]}],"828":[{"title":"能级差与谱线波长对应","type":"关系建立","judge":"要判断 Hα 与 Hβ 哪条谱线的光子能量更大，从而确定波长、频率的大小关系","why":"跃迁产生的光子能量等于两能级之差，且能量越大波长越短、频率越高；n=3 到 n=2 的能级差小于 n=4 到 n=2 的能级差","do":"比较 n=3→2 与 n=4→2 的能级差大小，再由 E=hc/λ 推出波长与频率关系","expr":"hν=E_m-E_n,\\quad \\lambda=\\frac{hc}{E_m-E_n}","cues":["能级差大的波长短","先比能级差","频率看能量"],"concepts":["能级跃迁","光子能量","波长频率关系"]},{"title":"用能级公式算光子能量","type":"数学处理","judge":"要判断 Hβ 光子的能量是否等于 2.55 eV，需用氢原子能级公式算出 n=4 与 n=2 的能量值再作差","why":"氢原子能级 E_n=E_1/n²，E_1=-13.6 eV，光子能量等于两能级之差","do":"代入 n=4、n=2 求 E_4、E_2，作差得 Hβ 光子能量","expr":"E_4=\\frac{-13.6}{16}\\approx-0.85\\,\\mathrm{eV},\\quad E_2=-3.40\\,\\mathrm{eV},\\quad \\Delta E=2.55\\,\\mathrm{eV}","cues":["用负十三点六除","能级公式代入","作差得能量"],"concepts":["氢原子能级公式","能级差"]},{"title":"基态电离与激发的最小能量","type":"临界条件","judge":"要判断 Hβ 光子能否使基态氢原子跃迁到激发态，需先确定基态跃迁到第一激发态所需的最小能量","why":"基态到 n=2 的能级差是激发所需的最小能量，光子能量必须恰好等于某两能级差才能被吸收","do":"计算 E_2-E_1，与 Hβ 光子能量 2.55 eV 比较","expr":"\\Delta E_{\\min}=E_2-E_1=10.2\\,\\mathrm{eV}","cues":["基态到第一激发态","最小激发能","比一比够不够"],"concepts":["基态","激发态","能级差吸收条件"]}],"829":[{"title":"最左端定匝数比","type":"前提判断","judge":"P 在最左端时，甲、乙两图中变压器副线圈输出的是不是都恰好等于灯泡额定电压","why":"题设说此时两灯均正常发光，说明副线圈电压就是 6 V，与变阻器接法无关；只有认定这一点才能用 220:6 求匝数比","do":"取 P 在最左端这一特殊位置，读出副线圈电压为 6 V，与原线圈 220 V 相比得匝数比","expr":"\\frac{n_1}{n_2}=\\frac{220}{6}=\\frac{110}{3}","cues":["最左端正常发光","副线圈就是六伏","用额定电压算匝数比"],"concepts":["理想变压器","电压比等于匝数比","额定电压"]},{"title":"辨清两图变阻器接法","type":"模型选择","judge":"甲图中变阻器是串联限流，乙图中变阻器是分压式接法（滑片左侧接电源、右侧与灯并联）","why":"两图电路结构不同，灯泡电压随滑片移动的变化规律完全不同，接法判断错则后面功率、范围全错","do":"沿电流路径追踪：甲图电流经滑片左侧电阻再经灯；乙图滑片把电阻分成两段，右段与灯并联后再与左段串联","expr":"","cues":["甲是串联","乙是并联分压","看滑片把电阻分成两段"],"concepts":["串联限流","分压接法","并联电路"]},{"title":"中点电压大小比较","type":"关系建立","judge":"滑片在中点时，甲图灯泡分得的电压与乙图灯泡分得的电压哪个大","why":"两图副线圈总电压相同，灯泡电压由所在支路的电阻分配决定；乙图中灯与部分电阻并联，并联部分电阻小于灯的电阻，分压更小","do":"比较两种接法下灯泡所在部分的等效电阻：甲为灯电阻本身，乙为灯与右段电阻的并联值，再按串联分压比较","expr":"U_甲=\\frac{R_L}{R_L+R_{左}}U,\\quad U_乙=\\frac{R_并}{R_并+R_{左}}U,\\quad R_并<R_L","cues":["并联电阻更小","分压看电阻比例","乙图灯电压偏低"],"concepts":["串联分压","并联等效电阻","电功率"]},{"title":"最左端输出功率比较","type":"关系建立","judge":"P 在最左端时，甲、乙两图副线圈的总输出功率哪个大（谁更节能）","why":"副线圈电压相同，总功率由副线圈所接负载的总电阻决定，总电阻越小输出功率越大","do":"比较最左端时两图的负载总电阻：甲只有灯，乙是灯与整个变阻器并联，总电阻更小","expr":"P=\\frac{U^2}{R_{总}},\\quad R_{乙总}<R_{甲总}=R_L","cues":["乙图多并联一路","总电阻小功率大","甲更省电"],"concepts":["电功率","并联总电阻","能量损耗"]},{"title":"调压范围下界判断","type":"临界条件","judge":"滑片移到最右端时，甲、乙两图中灯泡电压能否降到零","why":"甲图为串联限流，滑片到最右端时变阻器全接入，灯仍有分压，电压达不到零；乙图为分压接法，滑片到最右端时灯被短路，电压可为零","do":"分别取滑片最右端这一极端位置，写出灯两端电压的极限值，比较两图可调范围","expr":"U_{甲,\\min}=\\frac{R_L}{R_L+R}U>0,\\quad U_{乙,\\min}=0","cues":["甲图降不到零","乙图能短路","看最右端极限"],"concepts":["分压电路","短路","电压调节范围"]}],"830":[{"title":"由振动图定周期和初相","type":"图像读取","judge":"从图乙读出 t=0 时的位移和第一次回到平衡位置的时刻，判断该质点的振动方程中初相与角频率各是多少","why":"图乙是 x=3 m 处质点的振动图像，t=0 的位移为 √3/2 cm 且随后向正方向运动，t=2 s 时位移为零，这两点唯一确定 φ 与 ω，进而定出 T","do":"把 (0, √3/2) 和 (2, 0) 代入 y=Asin(ωt+φ)，结合 t=0 后位移增大定出 φ，再解出 ω 和 T","expr":"y=A\\sin(\\omega t+\\varphi),\\quad \\varphi=\\frac{\\pi}{3},\\ \\omega=\\frac{5\\pi}{6},\\ T=2.4\\,\\mathrm{s}","cues":["看t=0的位移","向正方向运动","两点定周期"],"concepts":["简谐振动方程","振动图像","初相"]},{"title":"波形图与振动图对应同一质点","type":"关系建立","judge":"要判断图甲上哪一点是 x=3 m 处的质点，即该质点在 t=0 时刻的位移与运动方向是否与图甲吻合","why":"图甲是某时刻的波形，图乙是同一质点的振动，两者必须描述同一状态；只有位移为 √3/2 cm 且运动方向一致的点才能对应，这是把两图联系起来的关键","do":"在图甲上找出位移为 √3/2 cm 的点，再结合图乙给出的 t=0 运动方向确定是哪一个","expr":"y(x=3\\,\\mathrm{m},t=0)=\\frac{\\sqrt{3}}{2}\\,\\mathrm{cm}","cues":["两图对应同一质点","位移要相同","方向要一致"],"concepts":["波形图","振动图像","质点振动方向"]},{"title":"双向传播分情况定波长","type":"前提判断","judge":"波沿 x 轴正、负方向传播两种可能下，x=3 m 到该点的距离分别对应波长的几分之几","why":"题设未给传播方向，必须分两种情况；且波长大于 3 m 限制了可取的分数只能是 1/6 或 1/3，否则会多出不符合题意的解","do":"分别按正、负方向在波形图上量出 3 m 对应的波长分数，再用 λ>3 m 筛选","expr":"\\frac{1}{6}\\lambda=3\\,\\mathrm{m}\\ \\text{或}\\ \\frac{1}{3}\\lambda'=3\\,\\mathrm{m}","cues":["方向没给要分两种","波长大于3米","距离是波长的几分之几"],"concepts":["波的传播方向","波长","空间周期性"]},{"title":"波速由波长周期联立","type":"关系建立","judge":"用已定的周期和两种可能的波长分别求波速，判断哪些波速值成立","why":"波速由 v=λ/T 唯一确定，T 已由振动图定出，λ 有两个候选值，因此波速也对应两个值，不能只取一个","do":"把 T=2.4 s 与两个 λ 分别代入 v=λ/T","expr":"v=\\frac{\\lambda}{T}","cues":["用波长比周期","两个波长两个速度"],"concepts":["波速","波长与周期的关系"]},{"title":"非特殊点路程按相位算","type":"数学处理","judge":"2 s 内该质点走过的路程是否等于整数个振幅的简单叠加，需要按实际振动过程分段计算","why":"该质点初始不在平衡位置也不在最大位移处，2 s 不是整周期，路程不能直接用 4A 或 n·4A 估算，必须按振动方程逐段累加","do":"按振动方程算出 2 s 内各段位移变化量并求和，注意起点位移为 √3/2 cm","expr":"s=\\left(4-\\frac{\\sqrt{3}}{2}\\right)\\,\\mathrm{cm}","cues":["不是整周期","起点不在平衡位置","分段累加"],"concepts":["路程","振幅","振动相位"]}],"831":[{"title":"匀速段受力平衡","type":"模型选择","judge":"把上升中某段视为匀速直线运动后，能否用合力为零来关联拉力与夹角","why":"匀速直线运动加速度为零，竖直方向合力为零，这是求拉力变化的前提","do":"对沙桶竖直方向列平衡方程，写出两绳拉力竖直分量之和与重力的关系","expr":"2T\\cos\\theta = Mg","cues":["匀速就平衡","合力为零","看竖直方向"],"concepts":["平衡条件","匀速直线运动","力的分解"]},{"title":"夹角增大拉力变化","type":"关系建立","judge":"由平衡式判断夹角增大时每根绳的拉力如何变化","why":"重力不变，夹角增大使每根绳竖直分量系数减小，必须靠增大拉力补偿","do":"在平衡式中固定重力，分析夹角增大时拉力的单调性","expr":"T=\\dfrac{Mg}{2\\cos\\theta}","cues":["夹角越大拉力越大","分母变小","竖直分量不够"],"concepts":["力的合成与分解","平衡条件"]},{"title":"最高点加速度方向","type":"临界条件","judge":"在最高点 B 速度为零时，判断合力方向而非速度方向","why":"加速度由合力决定，最高点速度为零但合力不为零，不能由运动方向判断加速度","do":"分析 B 点速度为零、随后向下运动，确定合力竖直向下","expr":"","cues":["最高点速度为零","看合力方向","接下来往下掉"],"concepts":["加速度","合力","竖直上抛"]},{"title":"读图取高度差","type":"图像读取","judge":"从 y-t 图中读出初末位置，取竖直方向的位置变化量而非路径长度","why":"机械能增加量只由重力势能增加决定，需用起点与终点的纵坐标差","do":"读 A 点与最终停止点 C 的纵坐标，作差得上升高度","expr":"\\Delta E_p = Mgh","cues":["看起点和终点","取纵坐标差","不是走的路程"],"concepts":["重力势能","y-t 图像"]},{"title":"机械能增量只算势能","type":"结论整理","judge":"判断初末速度均为零，机械能增加量只等于重力势能增加量","why":"沙桶由静止释放并最终停止，动能变化为零，机械能增量即势能增量","do":"确认初末动能均为零后，用质量、重力加速度和高度差算势能增量","expr":"\\Delta E = Mgh = 0.136\\times 9.8\\times 0.084","cues":["初末都静止","动能没变","只算重力势能"],"concepts":["机械能","重力势能","动能"]}],"832":[{"title":"电表接入位置判断","type":"实验操作","judge":"位置②是串在电容器支路里还是与电容器并联，从而决定接电流表还是电压表","why":"电流表必须串联、电压表必须并联，位置②与电容器并联则只能测电压","do":"看图甲中②的接法，判断它与电容器是并联还是串联","expr":"","cues":["看并联还是串联","②和电容并联","串联才测电流"],"concepts":["电流表串联","电压表并联"]},{"title":"充电完毕的电路状态","type":"临界条件","judge":"电压表示数最大时电路处于什么状态，此时电流是否为零","why":"电容器充电完毕后相当于断路，回路中不再有电荷移动，充电电流降为零","do":"由充电完成→电容器电压等于电源电动势→回路电流为零，读出电流表示数","expr":"U_C=E,\\quad I=0","cues":["充满相当于断路","电流降到零","电压最大电流最小"],"concepts":["电容器充电","断路","充电电流"]},{"title":"由U-I图判充放电","type":"图像读取","judge":"图乙中电压与电流是同时增大还是同时减小，对应充电还是放电","why":"充电时电压升高、电流逐渐减小；放电时电压和电流都减小，需按图线走向判断","do":"读图乙中U随I的变化趋势，与充放电的物理过程对照","expr":"","cues":["电压电流都变小","看图像走向","放电是双双减小"],"concepts":["U-I图像","放电过程"]},{"title":"由U-t图取放电电压","type":"图像读取","judge":"0.2 s时电容器两端电压取图丙上哪一点的值","why":"放电时电容器电压随时间按指数衰减，必须从U-t曲线上读对应时刻的纵坐标","do":"在图丙横轴找到0.2 s，读出对应纵坐标电压值","expr":"t=0.2\\,\\mathrm{s}\\Rightarrow U=8\\,\\mathrm{V}","cues":["横轴找0.2秒","读纵坐标","对应电压值"],"concepts":["U-t图像","放电曲线"]},{"title":"同一时刻U与I的对应","type":"关系建立","judge":"放电时电阻R0上的电压与电流是否就是该时刻电容器的电压与图乙中的电流","why":"放电回路中电容器与R0串联成闭合回路，同一时刻二者电压、电流相同，才能把图丙的U与图乙的I配对","do":"用图丙读出的U去图乙中找同一电压对应的电流I，再算功率","expr":"P=UI","cues":["同一时刻电压相同","拿U去图乙找I","串联电流相等"],"concepts":["闭合回路","电功率"]}],"833":[{"title":"P 的受力对象与平衡","type":"模型选择","judge":"求单根导线拉力时，应把 P 单独隔离，还是把 P、Q 整体作为对象","why":"P 匀速下降，加速度为零，P 自身所受合力为零，可直接由 P 的平衡求出导线拉力；若取整体，绳的拉力是内力，无法求出","do":"隔离 P，画 P 的受力：重力 2mg 向下、两根导线各一个拉力 T 向上，列竖直方向平衡方程","expr":"2T=2mg","cues":["先隔离P","匀速就是合力为零","两根线各一个拉力"],"concepts":["隔离法","共点力平衡"]},{"title":"Q 的安培力方向","type":"前提判断","judge":"Q 向上运动时，回路中感应电流方向及 Q 所受安培力是向上还是向下","why":"安培力方向由左手定则结合电流方向决定，只有先定出安培力方向，才能正确写出整体或 Q 的竖直方向受力方程","do":"由 Q 向上切割磁感线判断感应电流方向，再用左手定则判断 Q 所受安培力方向","expr":"","cues":["先判电流方向","左手定则","安培力向上还是向下"],"concepts":["右手定则","左手定则","安培力"]},{"title":"整体法求安培力","type":"关系建立","judge":"求 Q 所受安培力大小时，是否把 P、Q 及导线取整体，以避开导线拉力这个内力","why":"导线拉力对 P、Q 是内力，取整体后竖直方向只剩 P 的重力 2mg、Q 的重力 mg 和 Q 所受安培力，一个方程即可解出安培力","do":"对 P、Q 整体列竖直方向平衡方程，P 的重力向下、Q 的重力向下、安培力按已判方向计入","expr":"mg+F=2mg","cues":["取整体","避开绳的拉力","整体竖直方向平衡"],"concepts":["整体法","共点力平衡"]},{"title":"安培力与电流的桥接","type":"关系建立","judge":"如何把已求出的安培力大小与待求的电流 I 联系起来","why":"安培力公式 F=BIL 中，Q 垂直于磁场放置且长度为 L，B、L 均已知，故可由 F 反解 I","do":"写出 F=BIL，代入上一步得到的 F，解出 I","expr":"F=BIL，I=mg/(BL)","cues":["用安培力公式","BL都已知","反解电流"],"concepts":["安培力公式"]}],"834":[{"title":"磁场中轨迹半径的确定","type":"模型选择","judge":"粒子进入匀强磁场后只受洛伦兹力，应判断其做匀速圆周运动，并由洛伦兹力提供向心力求半径","why":"不计重力、磁场均匀且速度垂直于 B，洛伦兹力大小不变、方向始终垂直速度，是典型的匀速圆周运动","do":"对速率为 v0 的粒子列洛伦兹力等于向心力的方程，解出 r1","expr":"qv_{0}B=m\\dfrac{v_{0}^{2}}{r_{1}}\\Rightarrow r_{1}=\\dfrac{mv_{0}}{qB}","cues":["洛伦兹力当向心力","做圆周运动","先求半径"],"concepts":["洛伦兹力","匀速圆周运动","向心力"]},{"title":"OK 与半径的几何关系","type":"几何关系","judge":"要判断粒子从 O 点进入磁场后经半个圆周到达 K 点，OK 是直径而非半径","why":"粒子在 O 点速度沿 MN，进入磁场后轨迹圆在 O 点与 MN 相切，K 在 MN 上方且 KO⊥MN，故 KO 恰为轨迹直径","do":"画出 O 点速度方向与轨迹圆心的位置，确认圆心在 KO 上，取 OK=2r1","expr":"OK=2r_{1}=\\dfrac{2mv_{0}}{qB}","cues":["OK是直径","两倍半径","圆心在KO上"],"concepts":["轨迹圆","直径","相切"]},{"title":"速率变化后半径成比例","type":"关系建立","judge":"要判断速率变为 4v0 时轨迹半径按同一比例变为 4r1，而不是重新设未知量","why":"r=mv/(qB) 中 m、q、B 均不变，半径与速率成正比","do":"由 r=mv/(qB) 直接写出 r2=4r1，作为后续几何关系的已知量","expr":"r_{2}=\\dfrac{m\\cdot4v_{0}}{qB}=4r_{1}","cues":["半径跟速度成正比","四倍速度四倍半径","直接用r1表示"],"concepts":["半径公式","正比关系"]},{"title":"入射点偏移的几何约束","type":"几何关系","judge":"要判断粒子在磁场外沿 MN 直线运动一段后从某点进入磁场，该点与 O 的距离由轨迹圆必须过 K 点这一条件确定","why":"粒子仍被 K 点收集，说明新轨迹圆过 K；圆心在入射点处垂直于 MN 的直线上，半径已知为 4r1，构成直角三角形","do":"以入射点到 O 的距离为一直角边、圆心到 K 的竖直距离为另一直角边、4r1 为斜边列勾股关系，解出入射点到 O 的距离","expr":"(4r_{1}-2r_{1})^{2}+x^{2}=(4r_{1})^{2}\\Rightarrow x=2\\sqrt{3}r_{1}","cues":["轨迹圆必须过K","画直角三角形","斜边是半径"],"concepts":["勾股定理","轨迹圆过定点","圆心位置"]},{"title":"入射点位于 O 哪一侧","type":"临界条件","judge":"要判断粒子是在到达 O 之前（O 左侧）还是之后（O 右侧）进入磁场，两种情形对应不同的飞行距离","why":"粒子从 M 沿 MN 向 O 运动，若在 O 左侧进入磁场，轨迹圆无法同时满足过 K 与半径 4r1 的几何条件；只有越过 O 后的对称位置才成立","do":"比较入射点到 O 的距离与 MO 的大小，确认入射点在 O 右侧，总飞行路程为 MO 加该距离","expr":"s=MO+ON","cues":["在O右侧","要越过O点","对称位置"],"concepts":["临界位置","对称性","运动路径"]},{"title":"匀速直线段时间的合成","type":"数学处理","judge":"要判断打开磁场前粒子做匀速直线运动，时间等于总路程除以速率 4v0，而不是用某一段路程","why":"磁场打开前无磁场、无重力，粒子保持射出时的速度做匀速直线运动，总时间由总路程决定","do":"把 MO 与入射点到 O 的距离相加得总路程，除以 4v0 求时间","expr":"t=\\dfrac{MO+ON}{4v_{0}}=\\dfrac{\\sqrt{3}m}{qB}","cues":["匀速直线运动","总路程除以速度","两段路程相加"],"concepts":["匀速直线运动","路程与时间"]}],"835":[{"title":"绳绕钉后半径变化","type":"几何关系","judge":"B 绕 M、N 交替做圆周运动时，每绕半圈绳被钉子挡住，转动半径如何变化、绳长如何缩短","why":"绳不可伸长且被钉子阻挡，绕 M 时半径等于 M 到 B 的绳长，绕 N 时半径等于 N 到 B 的绳长，每绕半圈绳在 MN 间缠绕一段，半径和绳长都改变，这决定了后续各位置的半径与下落高度","do":"画出绕 M、绕 N 两种情形的圆心与半径，数清转 n 圈后绳缩短多少、B 到 M 的距离是多少","expr":"r_M=10a-2nh,\\quad r_N=10a-2\\left(n-\\tfrac12\\right)h","cues":["绕M绕N交替","每半圈缩短一段","半径在变"],"concepts":["圆周运动","几何约束","绳长"]},{"title":"最高点临界条件","type":"临界条件","judge":"B 恰能通过圆周最高点时，最高点速度由什么条件决定","why":"绳只能提供拉力不能提供推力，过最高点的临界是绳拉力恰好为零，由重力单独提供向心力","do":"对最高点列牛顿第二定律，取拉力为零，再与最低点到最高点的动能定理联立","expr":"mg=m\\frac{v^2}{10a},\\quad -mg\\cdot 2\\cdot 10a=\\frac12 mv^2-\\frac12 mv_0^2","cues":["最高点拉力为零","重力充当向心力","绳不能推"],"concepts":["向心力","临界速度","机械能守恒"]},{"title":"弹性碰撞定速度关系","type":"关系建立","judge":"A、B 弹性碰撞中动量与动能都守恒，碰后 A、B 速度与碰前 A 速度的关系","why":"碰撞时间极短、无外力冲量，动量守恒；弹性碰撞动能守恒，两式联立才能把 A 的碰前速度与 B 的碰后速度联系起来","do":"对 A、B 列动量守恒和动能守恒两式，消去碰后 A 的速度，得到 B 碰后速度与 A 碰前速度的比例","expr":"2mv_1=2mv_2+mv_3,\\quad \\tfrac12\\cdot2mv_1^2=\\tfrac12\\cdot2mv_2^2+\\tfrac12 mv_3^2","cues":["动量守恒加动能守恒","弹性碰撞","消去A的速度"],"concepts":["动量守恒","弹性碰撞","动能守恒"]},{"title":"A 滑行距离接平抛","type":"关系建立","judge":"碰后 A 在摩擦下减速到停的位移，与 B 断绳后平抛的水平位移如何对应到同一点 P","why":"题设 A、B 都到达 P 点，A 的位移由动能定理给出，B 的位移由平抛水平射程给出，两者相等才能解出 B 的碰后速度","do":"对 A 用动能定理求滑行距离，对 B 用平抛竖直高度求时间再求水平射程，令两者相等","expr":"\\mu\\cdot2mgL=\\tfrac12\\cdot2mv_2^2,\\quad L=v_4 t,\\quad 4a=\\tfrac12 gt^2","cues":["都到P点","位移相等","平抛射程"],"concepts":["动能定理","平抛运动","摩擦力做功"]},{"title":"断绳瞬间的向心力","type":"临界条件","judge":"绳在 M 正下方断开时，绳中拉力达到 12mg，此时速度与半径满足什么关系","why":"断绳条件是拉力达到极限值，而该位置绳的拉力与重力共同提供向心力，半径又随绕 M 或绕 N 不同而不同，必须分别列式","do":"在 M 正下方分别按绕 M、绕 N 两种半径列牛顿第二定律，取拉力为 12mg","expr":"12mg-mg=m\\frac{v_5^2}{r}","cues":["拉力到12mg就断","向心力是拉力减重力","半径分两种"],"concepts":["向心力","临界拉力","牛顿第二定律"]},{"title":"平抛射程的极值分析","type":"数学处理","judge":"水平射程随 nh 变化的函数在给定区间内取最大、最小值的条件","why":"射程是 nh 的二次根式函数，而 nh 受断绳条件限制在一个区间内，极值可能在区间端点或顶点处取得，需比较","do":"写出射程关于 nh 的表达式，配方找顶点，再与区间端点比较取极值","expr":"s=4\\sqrt{20anh-(nh)^2}","cues":["配方找顶点","比较端点","区间内取极值"],"concepts":["平抛运动","二次函数极值","取值范围"]}]};
